import type { Writable } from "node:stream";
import {
  getShellHookApprovalRequirement,
  type ShellStreamExecutor,
} from "@anysphere/agent-exec";
import { type Context, createLogger, createSpan } from "@anysphere/context";
import {
  ForceBackgroundShellResult,
  ForceBackgroundShellStatus,
  ShellAbortReason,
  type ShellArgs,
  ShellBackgroundReason,
  ShellCommandParsingResult,
  ShellPermissionDenied,
  ShellRejected,
  ShellResult,
  ShellSandboxUnsupported,
  ShellStream,
  ShellStreamBackgrounded,
  ShellStreamExit,
  ShellStreamStart,
  ShellStreamStderr,
  ShellStreamStdout,
  ShellSuccess,
  TimeoutBehavior,
} from "@anysphere/proto/agent/v1/shell_exec_pb.js";
import { SandboxUnsupportedError } from "@anysphere/shell-exec";
import { analyzeShellCommand } from "@anysphere/shell-exec/shell-parser";
import type { BackgroundShellManager } from "./background-shell.js";
import { resolvePath } from "./common.js";
import {
  forcedShellSandboxPolicy,
  isForcedShellEgressEnabled,
} from "./forced-egress.js";
import { toOptionalDurationMsInt32 } from "./int32.js";
import {
  convertInternalToProtoPolicy,
  convertProtoToInternalPolicy,
} from "./sandbox-conversion.js";
import { getModelShellAdminCommandDenylistBlockReason } from "./services/admin-command-denylist.js";
import type { IgnoreService } from "./services/ignore-service.js";
import type { PermissionsService } from "./services/permissions-service.js";
import type { ShellCoreExecutor } from "./shell-core.js";
import { resolveShellTimeoutMs } from "./shell-timeout.js";
import { shellBlockReasonMessage } from "./utils/edit-block-handler.js";

const logger = createLogger("local-exec:shell-stream");

/**
 * Wraps an async iterator with timeout support and safe handoff capability.
 * Allows iterating with `for await...of` while supporting clean handoff to
 * background processing when timeout occurs.
 */
type BackgroundableStopReason =
  | {
      kind: "background";
      reason: ShellBackgroundReason;
    }
  | {
      kind: "abort";
    };

class BackgroundableIterator<T> {
  private pendingPromise: Promise<IteratorResult<T>> | null = null;
  private stopReason: BackgroundableStopReason | undefined;
  private timer: NodeJS.Timeout | undefined;
  private stopResolve: (() => void) | undefined;
  private readonly stopPromise: Promise<void>;

  constructor(
    private iterator: AsyncIterator<T>,
    private timeoutMs: number
  ) {
    this.stopPromise = new Promise<void>(resolve => {
      this.stopResolve = resolve;
    });
  }

  private stop(reason: BackgroundableStopReason): boolean {
    if (this.stopReason !== undefined) {
      return false;
    }
    this.stopReason = reason;
    this.stopResolve?.();
    return true;
  }

  get timedOut(): boolean {
    return (
      this.stopReason?.kind === "background" &&
      this.stopReason.reason === ShellBackgroundReason.TIMEOUT
    );
  }

  get backgroundRequested(): boolean {
    return this.stopReason?.kind === "background";
  }

  get backgroundReasonValue(): ShellBackgroundReason | undefined {
    return this.stopReason?.kind === "background"
      ? this.stopReason.reason
      : undefined;
  }

  get stopReasonValue(): BackgroundableStopReason | undefined {
    return this.stopReason;
  }

  /**
   * Iterate with timeout. When timeout occurs, iteration stops and
   * `timedOut` becomes true. Call `getHandoffIterator()` to get an
   * iterator that includes any in-flight event.
   */
  async *iterate(): AsyncGenerator<T> {
    this.timer = setTimeout(() => {
      this.stop({
        kind: "background",
        reason: ShellBackgroundReason.TIMEOUT,
      });
    }, this.timeoutMs);

    try {
      while (true) {
        this.pendingPromise = this.iterator.next();

        const raceResult = await Promise.race([
          this.pendingPromise.then(
            result => ({ kind: "result", result }) as const
          ),
          this.stopPromise.then(() => ({ kind: "stopped" }) as const),
        ]);

        if (raceResult.kind === "stopped") {
          return; // Exit iteration, pendingPromise is preserved for handoff or cleanup
        }

        this.pendingPromise = null;
        if (raceResult.result.done) return;
        yield raceResult.result.value;
      }
    } finally {
      clearTimeout(this.timer);
    }
  }

  /**
   * Trigger background handoff programmatically (e.g. from user action).
   */
  requestBackground(): boolean {
    return this.stop({
      kind: "background",
      reason: ShellBackgroundReason.USER_REQUEST,
    });
  }

  /**
   * Trigger timeout programmatically (e.g., from abort signal).
   */
  abort(): void {
    this.stop({ kind: "abort" });
  }

  /**
   * Get an iterator for handoff that includes any in-flight event.
   * Call this after iteration stops due to timeout.
   */
  getHandoffIterator(): AsyncIterator<T> {
    if (this.pendingPromise) {
      const pending = this.pendingPromise;
      this.pendingPromise = null;
      let consumed = false;
      return {
        next: async () => {
          if (!consumed) {
            consumed = true;
            return pending;
          }
          return this.iterator.next();
        },
      };
    }
    return this.iterator;
  }
}

export class LocalShellStreamExecutor implements ShellStreamExecutor {
  private readonly activeForegroundExecutions: Map<
    string,
    { requestBackground: () => ShellResult | undefined }
  > = new Map();

  constructor(
    private permissionsService: PermissionsService,
    private coreExecutor: ShellCoreExecutor,
    private ignoreService: IgnoreService,
    private backgroundShellManager: BackgroundShellManager
  ) {}

  async forceBackgroundByToolCallId(
    toolCallId: string
  ): Promise<ForceBackgroundShellResult> {
    const execution = this.activeForegroundExecutions.get(toolCallId);
    const shellResult = execution?.requestBackground();
    if (!shellResult) {
      return new ForceBackgroundShellResult({
        status: ForceBackgroundShellStatus.NOT_FOUND,
      });
    }
    return new ForceBackgroundShellResult({
      status: ForceBackgroundShellStatus.ACCEPTED,
      shellResult,
    });
  }

  async *execute(ctx: Context, args: ShellArgs): AsyncIterable<ShellStream> {
    // Fail fast if the context is already cancelled
    ctx.signal?.throwIfAborted();

    using _span = createSpan(ctx.withName("LocalShellStreamExecutor.execute"));
    const command = args.command;
    // Only convert if policy is present - undefined lets permissions service use user's configured policy
    let requestedPolicy = args.requestedSandboxPolicy
      ? convertProtoToInternalPolicy(args.requestedSandboxPolicy)
      : undefined;
    // Add cursorignore mapping to the policy if it's a sandboxed policy
    if (requestedPolicy && requestedPolicy.type !== "insecure_none") {
      const ignoreMapping = await this.ignoreService.getCursorIgnoreMapping();
      requestedPolicy = { ...requestedPolicy, ignoreMapping: ignoreMapping };
    }

    const workingDirectory =
      args.workingDirectory || (await this.coreExecutor.getCwd());
    const timeout = resolveShellTimeoutMs(args);
    const resolvedWorkingDir = resolvePath(workingDirectory);
    const startTime = Date.now();
    const parsingResult = new ShellCommandParsingResult(
      analyzeShellCommand(command).structured
    );

    // Uses the RPC snapshot only. Statsig killswitch is upstream; see helper.
    const modelShellBlockReason = getModelShellAdminCommandDenylistBlockReason({
      command,
      parsingResult,
      blockedCommands: args.adminCommandDenylist,
    });
    if (modelShellBlockReason !== undefined) {
      yield new ShellStream({
        event: {
          case: "rejected",
          value: new ShellRejected({
            command,
            workingDirectory: resolvedWorkingDir,
            reason: modelShellBlockReason,
          }),
        },
      });
      return;
    }

    // Repo blocklist, readonly ceiling, and admin command denylist are
    // non-overridable: they apply even when Smart Mode classifier ALLOW (or
    // any other path) sets `skipApproval=true`.
    // We pass `skipUnsafeWorkingDirectoryBlock: true` because shell commands can
    // chdir anywhere, so failing the spawn solely because realpath errored on the
    // cwd is overzealous — the blocklist lookup still fires when the cwd resolves.
    const invariantBlock =
      await this.permissionsService.shouldEnforceShellInvariantBlocks(
        ctx,
        {
          workingDirectory: resolvedWorkingDir,
          skipUnsafeWorkingDirectoryBlock: true,
          command,
          parsingResult,
          toolCallId: args.toolCallId,
        },
        requestedPolicy
      );
    if (invariantBlock.kind === "block") {
      if (invariantBlock.reason.type === "permissionsConfig") {
        yield new ShellStream({
          event: {
            case: "permissionDenied",
            value: new ShellPermissionDenied({
              command,
              workingDirectory: resolvedWorkingDir,
              error: "Command blocked by permissions configuration",
              isReadonly: invariantBlock.reason.isReadonly ?? false,
            }),
          },
        });
        return;
      }
      yield new ShellStream({
        event: {
          case: "rejected",
          value: new ShellRejected({
            command,
            workingDirectory: resolvedWorkingDir,
            reason: shellBlockReasonMessage(invariantBlock.reason),
          }),
        },
      });
      return;
    }

    // Check if the command should be blocked (skip if skip_approval is true).
    // `shouldBlockShellCommand` re-runs the invariant checks above internally;
    // the duplication is intentional defense-in-depth and idempotent.
    logger.info(ctx, "Shell stream: approval gate reached", {
      toolCallId: args.toolCallId,
      skipApproval: args.skipApproval,
      hasSmartModeApproval: args.smartModeApproval !== undefined,
      hasSmartModeApprovalReason: args.smartModeApproval?.reason !== undefined,
      hasSmartModeApprovalRequestId:
        args.smartModeApproval?.requestId !== undefined,
      requestedPolicyType: requestedPolicy?.type ?? "undefined",
      parserCommandCount: parsingResult.executableCommands.length,
      classifierCommandCount: args.classifierResult?.commands.length ?? 0,
      commandLength: command.length,
    });
    if (!args.skipApproval) {
      const blockResult = await this.permissionsService.shouldBlockShellCommand(
        ctx,
        command,
        {
          workingDirectory: resolvedWorkingDir,
          timeout,
          parsingResult,
          toolCallId: args.toolCallId,
          classifierResult: args.classifierResult,
          smartModeApprovalReason: args.smartModeApproval?.reason,
          smartModeApprovalRequestId: args.smartModeApproval?.requestId,
          hookApprovalRequirement: getShellHookApprovalRequirement(args),
        },
        requestedPolicy
      );
      if (blockResult.kind === "block") {
        logger.info(ctx, "Shell stream: approval gate blocked command", {
          toolCallId: args.toolCallId,
          blockReasonType: blockResult.reason.type,
          hasSmartModeApproval: args.smartModeApproval !== undefined,
          skipApproval: args.skipApproval,
        });
        if (blockResult.reason.type === "permissionsConfig") {
          yield new ShellStream({
            event: {
              case: "permissionDenied",
              value: new ShellPermissionDenied({
                command,
                workingDirectory: resolvedWorkingDir,
                error: "Command blocked by permissions configuration",
                isReadonly: blockResult.reason.isReadonly ?? false,
              }),
            },
          });
          return;
        }

        const reason = shellBlockReasonMessage(blockResult.reason);

        yield new ShellStream({
          event: {
            case: "rejected",
            value: new ShellRejected({
              command,
              workingDirectory: resolvedWorkingDir,
              reason,
            }),
          },
        });
        return;
      }
      // Use the policy returned by permissions service, not the original request.
      // For allowlisted commands, this may be insecure_none (no sandbox) even when
      // the model requested a sandboxed policy.
      requestedPolicy = blockResult.policy;
      logger.info(ctx, "Shell stream: approval gate allowed command", {
        toolCallId: args.toolCallId,
        skipApproval: args.skipApproval,
        effectivePolicyType: requestedPolicy.type,
      });
    } else {
      logger.info(ctx, "Shell stream: skipped local approval", {
        toolCallId: args.toolCallId,
        requestedPolicyType: requestedPolicy?.type ?? "undefined",
      });
    }

    // Eval harness override: force a deny-by-default egress policy that neither
    // unrestricted approval mode nor a model-supplied policy can escalate.
    if (isForcedShellEgressEnabled()) {
      requestedPolicy = forcedShellSandboxPolicy(command, parsingResult);
      if (requestedPolicy.type !== "insecure_none") {
        const ignoreMapping = await this.ignoreService.getCursorIgnoreMapping();
        requestedPolicy = { ...requestedPolicy, ignoreMapping };
      }
    }

    // Yield start event with actual sandbox policy used
    yield new ShellStream({
      event: {
        case: "start",
        value: new ShellStreamStart({
          sandboxPolicy: convertInternalToProtoPolicy(requestedPolicy),
        }),
      },
    });

    const timeoutBehavior = args.timeoutBehavior;
    const shouldBackgroundOnTimeout =
      timeoutBehavior === TimeoutBehavior.BACKGROUND;
    const shouldPipeStdin =
      shouldBackgroundOnTimeout &&
      !args.closeStdin &&
      args.smartModeApproval === undefined;

    // Create an AbortController for background shell management
    const abortController = new AbortController();

    // Background-capable shells have to survive the parent turn abort once the
    // user explicitly backgrounds them. Forward ctx aborts manually until then.
    const executionSignal = shouldBackgroundOnTimeout
      ? abortController.signal
      : ctx.signal
        ? AbortSignal.any([ctx.signal, abortController.signal])
        : abortController.signal;

    // Always show elapsed time in terminal output
    const showElapsedTime = true;

    // Wrap the policy as merge sources for shell-exec
    // The policy has already been merged with admin policies by permissions-service,
    // so we place it in perRepo (closest to execution) for the final hardcoded merge.
    const sandboxPolicyMergeSources = requestedPolicy
      ? { perRepo: requestedPolicy }
      : undefined;

    // Get the async iterator from the core executor
    const iterable = this.coreExecutor.execute(ctx, {
      command,
      workingDirectory,
      signal: executionSignal,
      toolCallId: args.toolCallId,
      conversationId: args.conversationId,
      sandboxPolicy: sandboxPolicyMergeSources,
      fileOutputThresholdBytes: args.fileOutputThresholdBytes,
      pipeStdin: shouldPipeStdin,
      showElapsedTime,
    });

    // For CANCEL behavior, set up a simple timeout that aborts
    // For BACKGROUND behavior, use BackgroundableIterator which handles timeout internally
    let cancelTimer: NodeJS.Timeout | undefined;
    if (!shouldBackgroundOnTimeout) {
      cancelTimer = setTimeout(() => abortController.abort(), timeout);
    }

    const bgIterator = shouldBackgroundOnTimeout
      ? new BackgroundableIterator(iterable[Symbol.asyncIterator](), timeout)
      : null;

    // Track state for potential background adoption
    let collectedOutput = "";
    let stdin: Writable | undefined;
    let pid: number | undefined;
    let backgroundedShellId: number | undefined;
    let killedByHardTimeout = false;

    const foregroundExecution =
      args.toolCallId && bgIterator
        ? {
            requestBackground: () => {
              if (!bgIterator.requestBackground()) {
                return undefined;
              }
              backgroundedShellId =
                backgroundedShellId ??
                this.backgroundShellManager.generateShellId();
              return new ShellResult({
                result: {
                  case: "success",
                  value: new ShellSuccess({
                    shellId: backgroundedShellId,
                    pid,
                    command,
                    workingDirectory: resolvedWorkingDir,
                    msToWait: toOptionalDurationMsInt32(Date.now() - startTime),
                    backgroundReason: ShellBackgroundReason.USER_REQUEST,
                    interleavedOutput: collectedOutput,
                  }),
                },
              });
            },
          }
        : undefined;
    if (args.toolCallId && foregroundExecution) {
      this.activeForegroundExecutions.set(args.toolCallId, foregroundExecution);
    }
    const clearForegroundExecution = () => {
      if (
        args.toolCallId &&
        this.activeForegroundExecutions.get(args.toolCallId) ===
          foregroundExecution
      ) {
        this.activeForegroundExecutions.delete(args.toolCallId);
      }
    };

    // If context is cancelled before handoff, abort immediately. After handoff,
    // the background manager owns the shell's lifetime.
    if (bgIterator && ctx.signal) {
      ctx.signal.addEventListener(
        "abort",
        () => {
          if (!bgIterator.backgroundRequested) {
            abortController.abort();
            bgIterator.abort();
          }
        },
        {
          once: true,
        }
      );
    }

    // Set up hard kill timer at the START if hardTimeout is specified
    // This ensures the command is killed even if hardTimeout < timeout (backgrounding time)
    let hardKillTimer: NodeJS.Timeout | undefined;
    const hardTimeout = args.hardTimeout;
    if (hardTimeout !== undefined && hardTimeout > 0) {
      hardKillTimer = setTimeout(() => {
        if (backgroundedShellId !== undefined) {
          // The shell id can be reserved before adopt() registers it with the
          // background manager. Fall back to the local controller in that gap.
          const aborted =
            this.backgroundShellManager.abort(backgroundedShellId);
          if (!aborted) {
            abortController.abort();
          }
        } else {
          // Not yet backgrounded - kill immediately (don't background a dead process)
          killedByHardTimeout = true;
          abortController.abort();
          bgIterator?.abort();
        }
      }, hardTimeout);
    }

    // Use BackgroundableIterator for background behavior, regular iteration otherwise
    const eventSource = bgIterator?.iterate() ?? iterable;

    try {
      for await (const event of eventSource) {
        if (event.type === "stdout") {
          collectedOutput += event.data;
          yield new ShellStream({
            event: {
              case: "stdout",
              value: new ShellStreamStdout({ data: event.data }),
            },
          });
        } else if (event.type === "stderr") {
          collectedOutput += event.data;
          yield new ShellStream({
            event: {
              case: "stderr",
              value: new ShellStreamStderr({ data: event.data }),
            },
          });
        } else if (event.type === "stdin_ready") {
          stdin = event.stdin;
          pid = event.pid;
        } else if (event.type === "exit") {
          // Determine abort reason if the command was aborted
          let abortReason: ShellAbortReason | undefined;
          if (event.aborted) {
            // Check ctx.signal first - if the context was cancelled by the user,
            // this is a user abort, not a timeout. This must be checked before
            // bgIterator?.timedOut because bgIterator.abort() (called when ctx.signal
            // fires) sets timedOut=true, which would incorrectly classify user aborts
            // as timeouts.
            if (ctx.signal?.aborted) {
              abortReason = ShellAbortReason.USER_ABORT;
            } else if (bgIterator?.timedOut || abortController.signal.aborted) {
              abortReason = ShellAbortReason.TIMEOUT;
            } else {
              abortReason = ShellAbortReason.USER_ABORT;
            }
          }

          yield new ShellStream({
            event: {
              case: "exit",
              value: new ShellStreamExit({
                // Convert to unsigned for uint32 proto field. Negative values
                // (e.g. libuv errors like -4048) are invalid for uint32.
                code: (event.code ?? 0) >>> 0,
                cwd: await this.coreExecutor.getCwd(),
                outputLocation: event.outputLocation,
                aborted: event.aborted,
                abortReason,
                localExecutionTimeMs: toOptionalDurationMsInt32(
                  event.localExecutionTimeMs
                ),
              }),
            },
          });
        }
      }
    } catch (error) {
      // The sandbox helper cannot enforce the policy this command must run under
      // (e.g. a Linux host with no Landlock/bubblewrap backend). Without this the
      // error escapes the stream, which then ends with no `exit` event and the
      // model is told only that the command's result is unknown.
      if (!(error instanceof SandboxUnsupportedError)) {
        throw error;
      }
      const policyType = requestedPolicy?.type ?? "unknown";
      logger.warn(
        ctx,
        "Shell stream: sandbox policy unsupported on this host",
        {
          toolCallId: args.toolCallId,
          policyType,
          reason: error.reason,
        }
      );
      yield new ShellStream({
        event: {
          case: "sandboxUnsupported",
          value: new ShellSandboxUnsupported({
            command,
            workingDirectory: resolvedWorkingDir,
            sandboxPolicyType: policyType,
            reason: error.reason ?? error.message,
            isReadonly: policyType === "workspace_readonly",
          }),
        },
      });
      return;
    } finally {
      clearTimeout(cancelTimer);
      // Clear hardKillTimer if we're NOT going to background (completed/errored without timing out).
      // If we timed out, the timer needs to persist to kill the backgrounded process later.
      if (!bgIterator?.backgroundRequested) {
        clearTimeout(hardKillTimer);
      }
      clearForegroundExecution();
    }

    // Check if the shell was explicitly moved to background. If the timeout
    // fired before the parent context was aborted, we still need to adopt it;
    // executionSignal intentionally keeps that process alive until adoption.
    if (bgIterator?.backgroundRequested && !killedByHardTimeout) {
      const shellId =
        backgroundedShellId ?? this.backgroundShellManager.generateShellId();
      backgroundedShellId = shellId;
      const backgroundReason =
        bgIterator.backgroundReasonValue === ShellBackgroundReason.USER_REQUEST
          ? ShellBackgroundReason.USER_REQUEST
          : ShellBackgroundReason.TIMEOUT;
      const msToWait =
        backgroundReason === ShellBackgroundReason.USER_REQUEST
          ? Date.now() - startTime
          : timeout;

      await this.backgroundShellManager.adopt({
        ctx,
        shellId,
        command,
        workingDirectory: resolvedWorkingDir,
        toolCallId: args.toolCallId,
        // Reuse the already-created merge sources
        sandboxPolicy: sandboxPolicyMergeSources,
        initialOutput: collectedOutput,
        stdin,
        pid,
        abortController,
        eventIterator: bgIterator.getHandoffIterator(),
        startTime,
        showElapsedTime,
        description: args.description,
        outputNotification: args.outputNotification,
      });

      yield new ShellStream({
        event: {
          case: "backgrounded",
          value: new ShellStreamBackgrounded({
            shellId,
            command,
            workingDirectory: resolvedWorkingDir,
            pid,
            // Only include msToWait when feature flag is enabled (hardTimeout is set)
            msToWait: showElapsedTime ? msToWait : undefined,
            reason: backgroundReason,
          }),
        },
      });
    } else if (
      ctx.signal?.aborted &&
      bgIterator?.stopReasonValue !== undefined
    ) {
      // Context was cancelled by the user - yield an exit event so the model knows
      // the command was aborted. When bgIterator.abort() is called (from the ctx.signal
      // abort listener), the iterator exits early without yielding the exit event from
      // the underlying process. We need to explicitly yield one here.
      clearTimeout(hardKillTimer);
      yield new ShellStream({
        event: {
          case: "exit",
          value: new ShellStreamExit({
            // Use unsigned representation of -1 for uint32 proto field
            code: 0xffffffff,
            cwd: await this.coreExecutor.getCwd(),
            aborted: true,
            abortReason: ShellAbortReason.USER_ABORT,
          }),
        },
      });
    } else {
      // Completed normally or was killed by hard timeout - clear the timer
      clearTimeout(hardKillTimer);
    }
  }
}
