/**
 * Path matching utilities for checking "is this a X file?" patterns.
 * All functions handle both Windows and Unix paths by operating on path component arrays.
 *
 * New structure: ~/.cursor/projects/{workspaceId}/terminals|agent-tools|agent-transcripts|agent-notes/
 */

/**
 * Check if a path is absolute on any platform.
 * Handles Windows drive letters even when running on macOS/Linux (e.g., SSH to Windows).
 *
 * @param filePath - Path to check
 * @returns true if the path is absolute on any platform
 *
 * Examples:
 * - `/usr/local` -> true (Unix)
 * - `C:/Users/file.txt` -> true (Windows)
 * - `c:\Windows\System32` -> true (Windows)
 * - `\\server\share` -> true (Windows UNC)
 * - `./relative/path` -> false
 * - `C:` -> false (no slash, not absolute)
 */
export function isAbsolutePath(filePath: string): boolean {
  // Unix absolute paths: start with /
  if (filePath.startsWith("/")) {
    return true;
  }

  // Windows absolute paths: single drive letter + colon + slash
  if (/^[a-zA-Z]:[\\/]/.test(filePath)) {
    return true;
  }

  // Windows UNC paths: \\server\share
  if (filePath.startsWith("\\\\")) {
    return true;
  }

  return false;
}

/**
 * Split a path into components, handling both / and \ separators.
 * Removes empty components (from leading/trailing slashes or double slashes).
 */
function splitPath(path: string): string[] {
  return path.split(/[/\\]/).filter(c => c);
}

/**
 * Result of matching a project subdirectory pattern.
 * Contains the workspace ID and remaining path components after the target directory.
 */
interface ProjectSubdirMatch {
  workspaceId: string;
  /** Path components after the target directory (e.g., ['123.txt'] for a file) */
  remainingPath: string[];
}

/**
 * Check if path contains the pattern: .cursor/projects/{workspaceId}/targetDir
 * Returns match info including workspace ID and remaining path, or null if not found.
 */
function matchProjectSubdir(
  path: string,
  targetDir: string
): ProjectSubdirMatch | null {
  const parts = splitPath(path);

  // Look for .cursor/projects/{workspaceId}/targetDir pattern
  for (let i = 0; i < parts.length - 2; i++) {
    if (
      parts[i] === ".cursor" &&
      parts[i + 1] === "projects" &&
      parts[i + 3] === targetDir
    ) {
      return {
        workspaceId: parts[i + 2],
        remainingPath: parts.slice(i + 4),
      };
    }
  }
  return null;
}

/**
 * Check if a path is anywhere inside a ~/.cursor/projects directory, regardless
 * of workspace id or subdirectory beneath it. Used to keep Cursor's internal
 * app-state tree out of user-facing surfaces (e.g. the native Open dialog default).
 */
export function isCursorProjectsPath(path: string): boolean {
  const parts = splitPath(path);
  for (let i = 0; i < parts.length - 1; i++) {
    if (parts[i] === ".cursor" && parts[i + 1] === "projects") {
      return true;
    }
  }
  return false;
}

/**
 * Check if path is within a Cursor project terminals directory.
 * Path must end with ~/.cursor/projects/{workspaceId}/terminals/
 */
export function isCursorTerminalsDirectory(path: string): boolean {
  const match = matchProjectSubdir(path, "terminals");
  return match !== null && match.remainingPath.length === 0;
}

/**
 * Check if path is within a Cursor project agent transcripts directory.
 * Path must match: ~/.cursor/projects/{workspaceId}/agent-transcripts[/...]
 */
export function isAgentTranscriptPath(path: string): boolean {
  const match: ProjectSubdirMatch | null = matchProjectSubdir(
    path,
    "agent-transcripts"
  );
  return match !== null;
}

/**
 * Check if path is the Cursor project agent transcripts directory itself.
 * Path must end with ~/.cursor/projects/{workspaceId}/agent-transcripts
 */
export function isCursorAgentTranscriptsDirectory(path: string): boolean {
  const match: ProjectSubdirMatch | null = matchProjectSubdir(
    path,
    "agent-transcripts"
  );
  return match !== null && match.remainingPath.length === 0;
}

/**
 * Check if this is an agent tool output file.
 * Must be a .txt file directly in ~/.cursor/projects/{workspaceId}/agent-tools/ directory.
 */
export function isAgentToolOutputFile(filePath: string): boolean {
  const match = matchProjectSubdir(filePath, "agent-tools");
  // Must be direct child (only one component after agent-tools) and end with .txt
  return (
    match !== null &&
    match.remainingPath.length === 1 &&
    match.remainingPath[0].endsWith(".txt")
  );
}

/**
 * Check if path is a terminal file within a Cursor project terminals directory.
 * Path must match: ~/.cursor/projects/{workspaceId}/terminals/{id}.txt
 */
export function isTerminalFilePath(filePath: string): boolean {
  return extractTerminalId(filePath) !== null;
}

/**
 * Extract the terminal ID from a terminal file path.
 * Returns null if the path is not a valid terminal file.
 *
 * Example:
 * - `~/.cursor/projects/{workspaceId}/terminals/123.txt` → { id: 123 }
 * - `other/file.txt` → null
 */
export function extractTerminalId(filePath: string): { id: number } | null {
  const match = matchProjectSubdir(filePath, "terminals");
  // Must be direct child of terminals directory
  if (!match || match.remainingPath.length !== 1) {
    return null;
  }

  const fileName = match.remainingPath[0];

  const fileMatch = /^(\d+)\.txt$/.exec(fileName);
  if (!fileMatch) return null;

  const id = Number.parseInt(fileMatch[1], 10);

  if (Number.isNaN(id)) return null;

  return { id };
}

/**
 * Replace characters that are unsafe in filenames with underscores.
 * Keeps ASCII letters, digits, dots, hyphens, and underscores.
 */
export function sanitizeFilename(name: string): string {
  return name.replace(/[^a-zA-Z0-9._-]/g, "_");
}
