/**
 * X11 executor using xdotool and ffmpeg.
 */

import {
  type ComputerUseAction,
  Coordinate,
  MouseButton,
  ScrollDirection,
} from "@anysphere/proto/agent/v1/computer_use_tool_pb.js";
import type { InputEventLogger } from "./input-event-logger.js";
import { CoordinateScaler } from "./scaling.js";
import { exec, execBuffer, execWithInput, sleep } from "./shell.js";
import {
  DEFAULT_SCREENSHOT_DELAY_MS,
  DEFAULT_TYPING_BATCH_SIZE,
  DEFAULT_TYPING_DELAY_MS,
  type X11Config,
} from "./types.js";

// xdotool button numbers indexed by MouseButton enum value
const BUTTON_MAP: Record<MouseButton, string> = {
  [MouseButton.UNSPECIFIED]: "1", // default to left
  [MouseButton.LEFT]: "1",
  [MouseButton.MIDDLE]: "2",
  [MouseButton.RIGHT]: "3",
  [MouseButton.BACK]: "8",
  [MouseButton.FORWARD]: "9",
};

const SCROLL_BUTTON: Record<ScrollDirection, number> = {
  [ScrollDirection.UNSPECIFIED]: 5, // default to down
  [ScrollDirection.UP]: 4,
  [ScrollDirection.DOWN]: 5,
  [ScrollDirection.LEFT]: 6,
  [ScrollDirection.RIGHT]: 7,
};

function modifiersForXdotool(raw: string | undefined): string[] {
  return (raw?.split("+").filter(Boolean) ?? []).map(modifier =>
    modifier === "meta" ? "super" : modifier
  );
}

function keyForXdotool(key: string): string {
  return key
    .split("+")
    .map(part => (part === "meta" ? "super" : part))
    .join("+");
}

/**
 * How long a keymap change is held before and after the keystrokes relying on it.
 *
 * An application translates a key event against its own cached copy of the
 * keymap, and X offers no way to ask whether it has caught up: MappingNotify
 * carries no version and the server keeps no history.
 */
const KEYMAP_SETTLE_MS = 300;

export interface TypingOptions {
  /**
   * Bind a keycode for each character with no key before typing it, rather than
   * letting `xdotool type` remap one per character and lose it (SAND-1271).
   * Off by default, and carried per call so it can be enabled without a restart.
   */
  bindUnmappedCharacters?: boolean;
}

/** Whether every character in `text` has a key on the keymap, so can be typed. */
function isAscii(text: string): boolean {
  for (const char of text) {
    if ((char.codePointAt(0) ?? 0) > 0x7f) return false;
  }
  return true;
}

/** The distinct characters of `text` with no key, in order of appearance. */
function unmappedCharacters(text: string): string[] {
  return [...new Set([...text].filter(char => !isAscii(char)))];
}

/** The `UXXXX` keysym name X uses for a Unicode character. */
function unicodeKeysym(char: string): string {
  return `U${(char.codePointAt(0) ?? 0).toString(16).toUpperCase().padStart(4, "0")}`;
}

/**
 * The longest prefix of `text` needing no more than `capacity` keys bound.
 *
 * Only distinct unmapped characters cost a key, so ASCII is free and a run ends
 * only where the next new character would not fit.
 */
function runThatFits(text: string, capacity: number): string {
  const needed = new Set<string>();
  let length = 0;
  for (const char of text) {
    if (!isAscii(char) && !needed.has(char)) {
      if (needed.size === capacity) break;
      needed.add(char);
    }
    length += char.length;
  }
  return text.slice(0, length);
}

function actionRequiresSettle(action: ComputerUseAction): boolean {
  switch (action.action.case) {
    case "mouseMove":
    case "click":
    case "mouseDown":
    case "mouseUp":
    case "drag":
    case "key":
    case "scroll":
      return true;
    case "type":
      return /[\r\n]/.test(action.action.value.text);
    case "wait":
    case "screenshot":
    case "cursorPosition":
    case undefined:
      return false;
  }
}

/** Internal result for X11 operations */
export interface X11ExecutionResult {
  success: boolean;
  screenshot: string;
  error?: string;
  cursorPosition?: Coordinate;
  actionCount: number;
  durationMs: number;
}

export class X11Executor {
  private readonly config: Required<X11Config>;
  private readonly scaler: CoordinateScaler;
  private readonly env: Record<string, string>;

  /**
   * Optional InputEventLogger for capturing precise event timing.
   * Set this when screen recording is active to enable event-sourced logging.
   */
  private inputEventLogger: InputEventLogger | undefined;

  /**
   * Create an X11 executor.
   * @param config - MUST include displayNum and resolution (use detectDisplay() to get resolution)
   */
  constructor(config: X11Config) {
    if (!config.resolution) {
      throw new Error(
        "X11Executor requires resolution config. Use detectDisplay() to detect from system."
      );
    }
    this.config = {
      displayNum: config.displayNum,
      display: config.display ?? `:${config.displayNum}`,
      resolution: config.resolution,
      screenshotDelayMs:
        config.screenshotDelayMs ?? DEFAULT_SCREENSHOT_DELAY_MS,
      typingDelayMs: config.typingDelayMs ?? DEFAULT_TYPING_DELAY_MS,
      typingBatchSize: config.typingBatchSize ?? DEFAULT_TYPING_BATCH_SIZE,
    };
    this.scaler = new CoordinateScaler(this.config.resolution);
    this.env = { DISPLAY: this.config.display };
  }

  /**
   * Set the InputEventLogger to use for recording.
   * Pass undefined to disable event logging.
   */
  setInputEventLogger(logger: InputEventLogger | undefined): void {
    this.inputEventLogger = logger;
  }

  /**
   * Get the current InputEventLogger (if any).
   */
  getInputEventLogger(): InputEventLogger | undefined {
    return this.inputEventLogger;
  }

  private xdotool(args: string): Promise<string> {
    return exec("xdotool", args.split(" ").filter(Boolean), { env: this.env });
  }

  private scaleCoordinate(coord: Coordinate): { x: number; y: number } {
    return this.scaler.apiToDisplay(coord.x, coord.y);
  }

  async execute(
    actions: ComputerUseAction[],
    options: TypingOptions = {}
  ): Promise<X11ExecutionResult> {
    const start = Date.now();
    let cursorPosition: Coordinate | undefined;
    let lastScreenshot: string | undefined;
    let screenshotTaken = false;
    let settleNeeded = false;

    for (const action of actions) {
      if (action.action.case === "screenshot") {
        // Honor explicit screenshot requests
        if (settleNeeded) {
          await sleep(this.config.screenshotDelayMs);
          settleNeeded = false;
        }
        lastScreenshot = await this.takeScreenshot();
        screenshotTaken = true;
      } else if (action.action.case === "cursorPosition") {
        const result = await this.executeAction(action, options);
        if (result) {
          cursorPosition = result;
        }
      } else {
        // Execute the action with event logging (non-blocking)
        const commandStartTime = Date.now();
        await this.executeAction(action, options);
        const commandEndTime = Date.now();

        if (this.inputEventLogger?.getIsRunning()) {
          this.inputEventLogger.logEvent(
            action,
            commandStartTime,
            commandEndTime
          );
        }
        if (actionRequiresSettle(action)) {
          settleNeeded = true;
        }
      }
    }

    // Take a final screenshot if none were explicitly requested
    if (!screenshotTaken) {
      if (settleNeeded) {
        await sleep(this.config.screenshotDelayMs);
      }
      lastScreenshot = await this.takeScreenshot();
    }

    return {
      success: true,
      screenshot: lastScreenshot ?? "",
      cursorPosition,
      actionCount: actions.length,
      durationMs: Date.now() - start,
    };
  }

  private async executeAction(
    action: ComputerUseAction,
    options: TypingOptions
  ): Promise<Coordinate | undefined> {
    const { action: actionOneof } = action;

    switch (actionOneof.case) {
      case "mouseMove": {
        const coord = actionOneof.value.coordinate;
        if (!coord) {
          throw new Error("MouseMoveAction requires coordinate");
        }
        const { x, y } = this.scaleCoordinate(coord);
        await this.xdotool(`mousemove --sync ${x} ${y}`);
        break;
      }

      case "click": {
        const { coordinate, button, count, modifierKeys } = actionOneof.value;
        const buttonNum = BUTTON_MAP[button] ?? BUTTON_MAP[MouseButton.LEFT];

        // Build click args
        let clickArgs = buttonNum;
        if (count > 1) {
          clickArgs = `--repeat ${count} --delay 50 ${buttonNum}`;
        }

        // Build command parts
        const parts: string[] = [];

        // Hold modifier keys if specified (split combos like "ctrl+shift" into separate keydowns)
        const modifiers = modifiersForXdotool(modifierKeys);
        for (const mod of modifiers) {
          parts.push(`keydown ${mod}`);
        }

        if (coordinate) {
          const { x, y } = this.scaleCoordinate(coordinate);
          parts.push(`mousemove --sync ${x} ${y}`);
        }
        parts.push(`click ${clickArgs}`);

        // Release modifier keys in reverse order
        for (const mod of [...modifiers].reverse()) {
          parts.push(`keyup ${mod}`);
        }

        await this.xdotool(parts.join(" "));
        break;
      }

      case "mouseDown": {
        const buttonNum =
          BUTTON_MAP[actionOneof.value.button] ?? BUTTON_MAP[MouseButton.LEFT];
        await this.xdotool(`mousedown ${buttonNum}`);
        break;
      }

      case "mouseUp": {
        const buttonNum =
          BUTTON_MAP[actionOneof.value.button] ?? BUTTON_MAP[MouseButton.LEFT];
        await this.xdotool(`mouseup ${buttonNum}`);
        break;
      }

      case "drag": {
        const { path, button, modifierKeys } = actionOneof.value;
        const buttonNum = BUTTON_MAP[button] ?? BUTTON_MAP[MouseButton.LEFT];

        if (path.length < 2) {
          throw new Error("Drag path must have at least 2 points");
        }

        const scaledPath = path.map(coord => this.scaleCoordinate(coord));
        const commands: string[] = [];

        const modifiers = modifiersForXdotool(modifierKeys);
        for (const mod of modifiers) {
          commands.push(`keydown ${mod}`);
        }

        // Move to start and press mouse down
        commands.push(`mousemove --sync ${scaledPath[0].x} ${scaledPath[0].y}`);
        commands.push(`mousedown ${buttonNum}`);

        // Move through all remaining points
        for (let i = 1; i < scaledPath.length; i++) {
          commands.push(
            `mousemove --sync ${scaledPath[i].x} ${scaledPath[i].y}`
          );
        }

        // Release mouse
        commands.push(`mouseup ${buttonNum}`);
        for (const mod of [...modifiers].reverse()) {
          commands.push(`keyup ${mod}`);
        }

        await this.xdotool(commands.join(" "));
        break;
      }

      case "scroll": {
        const { coordinate, direction, amount, modifierKeys } =
          actionOneof.value;
        const scrollButton =
          SCROLL_BUTTON[direction] ?? SCROLL_BUTTON[ScrollDirection.DOWN];
        const parts: string[] = [];

        // Hold modifier keys if specified (split combos like "ctrl+shift" into separate keydowns)
        const modifiers = modifiersForXdotool(modifierKeys);
        for (const mod of modifiers) {
          parts.push(`keydown ${mod}`);
        }

        if (coordinate) {
          const { x, y } = this.scaleCoordinate(coordinate);
          parts.push(`mousemove --sync ${x} ${y}`);
        }
        parts.push(`click --repeat ${amount} ${scrollButton}`);

        // Release modifier keys in reverse order
        for (const mod of [...modifiers].reverse()) {
          parts.push(`keyup ${mod}`);
        }

        await this.xdotool(parts.join(" "));
        break;
      }

      case "type":
        await this.typeText(actionOneof.value.text, options);
        break;

      case "key": {
        const { key, holdDurationMs } = actionOneof.value;
        const xdotoolKey = keyForXdotool(key);
        if (holdDurationMs && holdDurationMs > 0) {
          // Hold key for duration
          await this.xdotool(`keydown ${xdotoolKey}`);
          await sleep(holdDurationMs);
          await this.xdotool(`keyup ${xdotoolKey}`);
        } else {
          // Normal key press
          await this.xdotool(`key -- ${xdotoolKey}`);
        }
        break;
      }

      case "wait":
        await sleep(actionOneof.value.durationMs);
        break;

      case "screenshot":
        break;

      case "cursorPosition": {
        const output = await this.xdotool("getmouselocation --shell");
        const xMatch = output.match(/X=(\d+)/);
        const yMatch = output.match(/Y=(\d+)/);
        if (!xMatch || !yMatch) {
          throw new Error(
            `Failed to parse cursor position from xdotool output: ${output}`
          );
        }
        const displayX = parseInt(xMatch[1], 10);
        const displayY = parseInt(yMatch[1], 10);
        const apiCoords = this.scaler.displayToApi(displayX, displayY);
        return new Coordinate({ x: apiCoords.x, y: apiCoords.y });
      }

      case undefined:
        throw new Error("Action case is undefined");

      default: {
        const _: never = actionOneof;
        throw new Error(`Unknown action case: ${JSON.stringify(_)}`);
      }
    }

    return undefined;
  }

  /**
   * Types text, converting newlines to Return presses, because `xdotool type`
   * sends Linefeed for `\n` and most applications expect Return.
   */
  private async typeText(
    text: string,
    { bindUnmappedCharacters = false }: TypingOptions
  ): Promise<void> {
    const lines = text.split(/\r\n|\r|\n/);
    for (const [index, line] of lines.entries()) {
      if (index > 0) await this.xdotool("key Return");
      if (bindUnmappedCharacters && !isAscii(line)) {
        await this.typeWithBorrowedKeys(line);
      } else {
        await this.sendKeystrokes(line);
      }
    }
  }

  /**
   * Types text containing characters that have no key on the keymap.
   *
   * `xdotool type` handles such a character by borrowing a spare keycode,
   * pressing it, and handing it straight back, once per character. The
   * application translates the event against its own lazily-refreshed copy of the
   * keymap, so a keystroke that overtakes the server's MappingNotify resolves
   * against the stale mapping and vanishes, while xdotool still exits 0. That is
   * how `Aprenderás` reached a live page as `Aprenders` (SAND-1271).
   *
   * Borrowing here instead means every character is already on the keymap before
   * a single key is pressed, and stays there until the run has been typed, so
   * nothing is remapped mid-type. The keymap holds only so many spare keycodes,
   * so longer text is typed as several runs that each fit.
   */
  private async typeWithBorrowedKeys(text: string): Promise<void> {
    let remaining = text;
    while (remaining !== "") {
      // Re-read per run rather than reusing a list from before the last release,
      // so a keycode another action has since taken is never handed out twice.
      const spare = await this.spareKeycodes();
      if (spare.length === 0) {
        throw new Error(
          `Cannot type ${JSON.stringify([...unmappedCharacters(remaining)].join(""))}: ` +
            "the X keymap has no spare keycode to bind them to."
        );
      }

      const run = runThatFits(remaining, spare.length);
      remaining = remaining.slice(run.length);
      const bindings = unmappedCharacters(run).map(
        (char, index) => [spare[index], unicodeKeysym(char)] as const
      );

      try {
        // Each keysym twice: X expands a keycode holding one alphabetic keysym
        // into [lowercase, uppercase], so `Á` alone would arrive as `á`.
        await this.changeKeymap(
          bindings.map(
            ([keycode, keysym]) => `keycode ${keycode} = ${keysym} ${keysym}`
          )
        );
        await sleep(KEYMAP_SETTLE_MS);
        await this.sendKeystrokes(run, {
          clearModifiers: true,
          byCodePoint: true,
        });
        await sleep(KEYMAP_SETTLE_MS);
      } finally {
        await this.changeKeymap(
          bindings.map(([keycode]) => `keycode ${keycode} =`)
        ).catch(() => {
          // A keycode left bound produces nothing on any physical key, so a
          // failed release must not mask a typing error.
        });
      }
    }
  }

  private async sendKeystrokes(
    text: string,
    {
      clearModifiers = false,
      byCodePoint = false,
    }: { clearModifiers?: boolean; byCodePoint?: boolean } = {}
  ): Promise<void> {
    const { typingDelayMs, typingBatchSize } = this.config;
    // A batch boundary inside a surrogate pair reaches xdotool as U+FFFD, which
    // has no key. Off by default, so a caller with the gate off keeps splitting
    // on UTF-16 units exactly as before.
    const units = byCodePoint ? [...text] : text.split("");
    for (let i = 0; i < units.length; i += typingBatchSize) {
      const batch = units.slice(i, i + typingBatchSize).join("");
      await exec(
        "xdotool",
        [
          "type",
          ...(clearModifiers ? ["--clearmodifiers"] : []),
          "--delay",
          String(typingDelayMs),
          "--",
          batch,
        ],
        { env: { ...this.env, LC_ALL: "C.UTF-8" } }
      );
    }
  }

  /** Keycodes carrying no keysyms at all, and so free to borrow. */
  private async spareKeycodes(): Promise<number[]> {
    const table = await exec("xmodmap", ["-pke"], { env: this.env });
    return table
      .split("\n")
      .map(line => /^keycode\s+(\d+)\s*=\s*$/.exec(line.trim()))
      .filter((match): match is RegExpExecArray => match !== null)
      .map(match => Number(match[1]));
  }

  private changeKeymap(entries: string[]): Promise<void> {
    return execWithInput("xmodmap", ["-"], {
      input: `${entries.join("\n")}\n`,
      env: this.env,
    });
  }

  private async takeScreenshot(): Promise<string> {
    const { width, height } = this.config.resolution.display;
    const buffer = await execBuffer(
      "ffmpeg",
      [
        "-f",
        "x11grab",
        "-video_size",
        `${width}x${height}`,
        "-i",
        this.config.display,
        "-frames:v",
        "1",
        "-vf",
        `scale=${this.scaler.apiWidth}:${this.scaler.apiHeight}`,
        "-c:v",
        "libwebp",
        "-preset",
        "text", // Optimized for UI screenshots with sharp edges and text
        "-lossless",
        "1",
        "-f",
        "webp",
        "pipe:1",
      ],
      { env: this.env }
    );

    // Fix WebP headers: ffmpeg can't seek in pipes, so RIFF and VP8 chunk sizes are left as 0.
    // This causes browsers/Preview to reject the file even though the image data is valid.
    // We patch the size fields in memory before returning.
    const isSimpleVP8WebP =
      buffer.length > 20 &&
      buffer.subarray(0, 4).toString() === "RIFF" &&
      buffer.subarray(8, 12).toString() === "WEBP" &&
      buffer.subarray(12, 16).toString() === "VP8 ";

    if (isSimpleVP8WebP) {
      buffer.writeUInt32LE(buffer.length - 8, 4); // RIFF size at offset 4
      buffer.writeUInt32LE(buffer.length - 20, 16); // VP8 chunk size at offset 16
    }

    return buffer.toString("base64");
  }
}
