/**
 * Policy merge logic for combining SandboxPolicy from multiple sources.
 *
 * Sources are merged in priority order (lowest to highest):
 * 1. Per-user settings (optional) - User preferences
 * 2. Per-repo settings - Repository-specific configuration
 * 3. Team Admin (optional) - Enterprise controls
 * 4. Hard-coded - Security invariants (cannot be overridden)
 *
 * Merge semantics:
 * - All provided policies must be of the same type (all readwrite, all readonly, or all insecure_none)
 * - Security restrictions are additive (more restrictive wins)
 * - Path permissions are unioned (all sources contribute additively)
 * - Network allowlist: union (all sources contribute)
 *   - teamAdmin allowlist replaces the union (admin is authoritative)
 *   - teamAdmin allowlist naturally grants network access (via isNetworkEnabledByPolicy)
 * - Network denylist: union (all denies accumulated)
 * - Deny takes precedence over allow (for network policies)
 * - ignoreMapping: patterns are unioned per directory across all sources
 *   (restrictions are additive — any source can block paths, none can unblock)
 *
 * Cross-field interactions (enforced by sandbox helper, not at merge time):
 * - A path appearing in both additionalReadwritePaths and additionalReadonlyPaths
 *   gets readwrite access (readwrite is a superset of readonly).
 * - ignoreMapping takes precedence over all path grants at the sandbox level:
 *   a path in additionalReadwritePaths but matched by ignoreMapping is blocked.
 */

import { stat } from "node:fs/promises";
import { dirname, join, resolve } from "node:path";
import { spawnPromise } from "@anysphere/utils";
import type {
  IgnoreMapping,
  InsecureNoneSandboxPolicy,
  NetworkPolicy,
  NetworkPolicyLoggingConfig,
  SandboxPolicy,
  SandboxReadBoundary,
  WorkspaceReadOnlySandboxPolicy,
  WorkspaceReadWriteSandboxPolicy,
} from "../types.js";
import {
  getGitWriteProtectionMapping,
  getHardcodedSandboxPolicy,
  getWorktreeWriteProtectionMapping,
} from "./hardcoded-policy.js";
import { getEffectiveNetworkPolicy } from "./network-policy-utils.js";

// ============================================================================
// Types
// ============================================================================

/**
 * Input sources for policy merge.
 * All fields are optional - undefined means "no opinion" / "use defaults".
 * All provided policies must be of the same type.
 */
export interface SandboxPolicyMergeSources<
  T extends SandboxPolicy = SandboxPolicy,
> {
  /**
   * Per-user settings (lowest priority).
   * User preferences that can be overridden by all other sources.
   */
  perUser?: T;

  /**
   * Per-repo settings.
   * Repository-specific configuration from .cursor/settings or similar.
   */
  perRepo?: T;

  /**
   * Team Admin settings (optional).
   * Enterprise controls managed centrally.
   */
  teamAdmin?: T;

  // Note: Hard-coded policy is always applied internally and cannot be overridden
}

/**
 * Options for controlling merge behavior.
 */
export interface SandboxPolicyMergeOptions {
  /**
   * If true, includes debug information about merge decisions.
   * @default false
   */
  debug?: boolean;
  /**
   * Workspace root directory. Used to key the hardcoded write-protection
   * ignoreMapping so the Rust sandbox knows which directory the patterns
   * are relative to.
   */
  workspaceDir: string;
  /**
   * Parent directory of the resolved git common dir. Used to key `type: "git"`
   * write-protection patterns. For normal repos this equals `workspaceDir`; for
   * worktrees it's the main repo root (where the real .git/ directory lives).
   * When omitted, falls back to `workspaceDir`.
   */
  gitDirParent?: string;
}

/**
 * Result of a policy merge operation with optional debug info.
 */
export interface SandboxPolicyMergeResult<
  T extends SandboxPolicy = SandboxPolicy,
> {
  policy: T;
  debug?: SandboxPolicyMergeDebugInfo;
}

/**
 * Debug information about merge decisions.
 */
export interface SandboxPolicyMergeDebugInfo {
  /** Which source contributed to each field */
  fieldSources: Record<string, string>;
}

// ============================================================================
// Merge Helper Functions
// ============================================================================

export function getSandboxPolicyType(
  policy: SandboxPolicyMergeSources
): SandboxPolicyType {
  // Priority order (highest to lowest): teamAdmin > perRepo > perUser
  return (
    policy.teamAdmin?.type ??
    policy.perRepo?.type ??
    policy.perUser?.type ??
    "insecure_none"
  );
}

/**
 * Merges a boolean field where `true` is more restrictive.
 * Returns `true` if any higher-priority source sets it to `true`.
 *
 * Used for: disableTmpWrite, networkPolicyStrict
 */
export function mergeRestrictiveBoolean(
  ...values: (boolean | undefined)[]
): boolean {
  // If any source explicitly sets true, the result is true
  return values.some(v => v === true);
}

/**
 * Merges path arrays using intersection.
 * Only paths present in ALL sources (that specify paths) are included.
 * Used for: additionalReadwritePaths (grants write access, more restrictive merge)
 *
 * Important: An empty array [] means "allow nothing" (explicit restriction),
 * while undefined means "no opinion" (defer to other sources).
 *
 * @param sources - Array of path arrays from lowest to highest priority
 * @returns Intersection of all non-undefined sources
 */
export function mergePathsIntersection(
  ...sources: (string[] | undefined)[]
): string[] {
  // Filter out undefined sources (but keep empty arrays - they mean "allow nothing")
  const definedSources = sources.filter((s): s is string[] => s !== undefined);

  if (definedSources.length === 0) {
    return [];
  }

  // If any source is an empty array, the intersection is empty
  // (empty array means "allow nothing")
  if (definedSources.some(s => s.length === 0)) {
    return [];
  }

  if (definedSources.length === 1) {
    // Normalize paths for consistency with multi-source case
    return deduplicatePaths(definedSources[0]!).map(normalizePath);
  }

  // Start with the first defined source
  let result = new Set(definedSources[0]!.map(normalizePath));

  // Intersect with each subsequent source
  for (let i = 1; i < definedSources.length; i++) {
    const sourceSet = new Set(definedSources[i]!.map(normalizePath));
    result = new Set([...result].filter(path => sourceSet.has(path)));
  }

  return [...result];
}

/**
 * Merges path arrays using union.
 * All paths from all sources are included (deduplicated).
 * Used for: additionalReadonlyPaths (readonly is safe, accumulate)
 *
 * @param sources - Array of path arrays from lowest to highest priority
 * @returns Union of all sources
 */
export function mergePathsUnion(
  ...sources: (string[] | undefined)[]
): string[] {
  const allPaths = new Set<string>();

  for (const source of sources) {
    if (source) {
      for (const path of source) {
        allPaths.add(normalizePath(path));
      }
    }
  }

  return [...allPaths];
}

type PolicyField<T> = {
  defaultValue: T;
  merge: (...sources: (T | undefined)[]) => T;
};

function rankedPolicyField<T extends string>({
  defaultValue,
  rank,
}: {
  defaultValue: T;
  rank: Record<T, number>;
}): PolicyField<T> {
  return {
    defaultValue,
    merge: (...sources) => {
      const definedSources = sources.filter(
        (source): source is T => source !== undefined
      );
      if (definedSources.length === 0) {
        return defaultValue;
      }
      return definedSources.reduce((strictest, source) =>
        rank[source] < rank[strictest] ? source : strictest
      );
    },
  };
}

function intersectingPathPolicyField(): PolicyField<string[]> {
  return {
    defaultValue: [],
    merge: (...sources) => mergePathsIntersection(...sources),
  };
}

const readBoundaryPolicyField = rankedPolicyField<SandboxReadBoundary>({
  defaultValue: "system",
  rank: {
    workspace: 0,
    system: 1,
  },
});

const additionalReadPathsPolicyField = intersectingPathPolicyField();

export function mergeReadBoundary(
  ...sources: (SandboxReadBoundary | undefined)[]
): SandboxReadBoundary {
  return readBoundaryPolicyField.merge(...sources);
}

export function mergeAdditionalReadPaths(
  ...sources: (string[] | undefined)[]
): string[] {
  return additionalReadPathsPolicyField.merge(...sources);
}

/**
 * Workspace allowlist contribution for a single merge source.
 * Missing paths on a workspace source means "no opinion" (admin may clamp
 * boundary without specifying an allowlist). An explicit empty array means
 * "allow nothing beyond the workspace".
 */
function workspaceReadPathsSource(
  readBoundary: SandboxReadBoundary | undefined,
  additionalReadPaths: string[] | undefined
): string[] | undefined {
  if (readBoundary !== "workspace" || additionalReadPaths === undefined) {
    return undefined;
  }
  return additionalReadPaths;
}

/**
 * Normalizes a path for comparison and deduplication.
 */
function normalizePath(path: string): string {
  // Normalize slashes and remove trailing slashes
  const normalized = path.replace(/\\/g, "/").replace(/\/+$/, "");
  // Preserve root paths: "/" should stay "/", "C:" should stay "C:/"
  if (normalized === "") {
    return "/";
  }
  // Handle Windows drive-only paths (e.g., "C:" after normalization)
  if (/^[a-zA-Z]:$/.test(normalized)) {
    return `${normalized}/`;
  }
  return normalized;
}

/**
 * Deduplicates paths while preserving order.
 */
function deduplicatePaths(paths: string[]): string[] {
  const seen = new Set<string>();
  const result: string[] = [];

  for (const path of paths) {
    const normalized = normalizePath(path);
    if (!seen.has(normalized)) {
      seen.add(normalized);
      result.push(path);
    }
  }

  return result;
}

/**
 * Merges NetworkPolicy objects from multiple sources.
 *
 * Merge rules:
 * - `default`: "deny" wins if any source specifies it
 * - `deny[]`: Union - accumulate all deny patterns (more restrictive)
 * - `allow[]`: Union - accumulate all allow patterns from all sources
 *   Note: teamAdmin "replace" semantics are handled at the caller level
 *   (mergeCommonWorkspaceFields), not here.
 *
 * @param sources - NetworkPolicy objects from lowest to highest priority
 * @returns Merged NetworkPolicy
 */
export function mergeNetworkPolicies(
  ...sources: (NetworkPolicy | undefined)[]
): NetworkPolicy | undefined {
  // Filter out undefined sources
  const definedSources = sources.filter(
    (s): s is NetworkPolicy => s !== undefined
  );

  if (definedSources.length === 0) {
    return undefined;
  }

  // Merge default: "deny" wins
  let mergedDefault: "allow" | "deny" | undefined;
  for (const source of definedSources) {
    if (source.default === "deny") {
      mergedDefault = "deny";
      break;
    } else if (source.default === "allow" && mergedDefault === undefined) {
      mergedDefault = "allow";
    }
  }

  // Merge deny lists: union (accumulate all denies)
  const mergedDeny = new Set<string>();
  for (const source of definedSources) {
    if (source.deny) {
      for (const pattern of source.deny) {
        mergedDeny.add(pattern);
      }
    }
  }

  // Merge allow lists: union (accumulate all allows)
  // Empty arrays (allow: []) are treated as "no opinion", not "deny all".
  const mergedAllowSet = new Set<string>();
  for (const source of definedSources) {
    if (source.allow) {
      for (const pattern of source.allow) {
        mergedAllowSet.add(pattern);
      }
    }
  }
  const mergedAllow: string[] | undefined =
    mergedAllowSet.size > 0 ? [...mergedAllowSet] : undefined;

  // Merge logging: take highest priority defined value
  // Iterate from highest to lowest priority (reverse order of sources)
  let mergedLogging: NetworkPolicyLoggingConfig | undefined;
  for (let i = definedSources.length - 1; i >= 0; i--) {
    if (definedSources[i]!.logging !== undefined) {
      mergedLogging = definedSources[i]!.logging;
      break;
    }
  }

  // Build the merged policy
  const merged: NetworkPolicy = {
    version: 1,
  };

  if (mergedDefault !== undefined) {
    merged.default = mergedDefault;
  }

  if (mergedAllow !== undefined) {
    merged.allow = mergedAllow;
  }

  if (mergedDeny.size > 0) {
    merged.deny = [...mergedDeny];
  }

  if (mergedLogging !== undefined) {
    merged.logging = mergedLogging;
  }

  // If the merged policy is effectively empty, return undefined
  if (
    merged.default === undefined &&
    (merged.allow === undefined || merged.allow.length === 0) &&
    (merged.deny === undefined || merged.deny.length === 0) &&
    merged.logging === undefined
  ) {
    return undefined;
  }

  return merged;
}

/**
 * Merges IgnoreMapping objects from multiple sources.
 *
 * Merge rules:
 * - Directory keys are matched exactly (no normalization — different sources
 *   should use consistent path formats; URI-to-path conversion happens later
 *   at the enforcement layer in sandbox policy serialization).
 * - For each directory, patterns are unioned (deduplicated) across all sources,
 *   preserving latest-source precedence for duplicates.
 * - If a directory appears in multiple sources, all their patterns are combined.
 *
 * This follows the "restrictions are additive" principle: any source can add
 * ignore patterns to block access to files, and no source can remove patterns
 * added by another source.
 *
 * @param sources - IgnoreMapping objects from lowest to highest priority
 * @returns Merged IgnoreMapping, or undefined if no sources have mappings
 */
export function mergeIgnoreMappings(
  ...sources: (IgnoreMapping | undefined)[]
): IgnoreMapping | undefined {
  const definedSources = sources.filter(
    (s): s is IgnoreMapping => s !== undefined
  );

  if (definedSources.length === 0) {
    return undefined;
  }

  const merged: IgnoreMapping = {};

  for (const source of definedSources) {
    for (const [path, patterns] of Object.entries(source)) {
      const existing = merged[path];
      if (existing) {
        // Union patterns, deduplicating while preserving last-source precedence.
        const patternSet = new Set(existing);
        for (const pattern of patterns) {
          // Re-adding an existing pattern must move it to the end so
          // gitignore last-match-wins semantics reflect source priority.
          if (patternSet.has(pattern)) {
            patternSet.delete(pattern);
          }
          patternSet.add(pattern);
        }
        merged[path] = [...patternSet];
      } else {
        merged[path] = [...patterns];
      }
    }
  }

  // Return undefined if empty
  if (Object.keys(merged).length === 0) {
    return undefined;
  }

  return merged;
}

/**
 * Takes the first defined value (highest priority that set a value).
 * Used for non-security fields like debugOutputDir, enableSharedBuildCache.
 *
 * @param sources - Values from lowest to highest priority
 * @returns The highest-priority defined value, or undefined
 */
export function takeHighestPriorityDefined<T>(
  ...sources: (T | undefined)[]
): T | undefined {
  // Iterate from highest to lowest priority (reverse order)
  for (let i = sources.length - 1; i >= 0; i--) {
    if (sources[i] !== undefined) {
      return sources[i];
    }
  }
  return undefined;
}

/**
 * Async variant of mergeSandboxPolicies that resolves git directory location
 * and detects git worktrees.
 *
 * - Resolves `type: "git"` write-protection patterns to the correct directory
 *   (workspace root for normal repos, main repo root for worktrees).
 * - If .git is a file (worktree), also adds the git common dir as a readwrite
 *   path and blocks writes to the .git pointer file via ignoreMapping.
 */
export async function resolveSandboxPolicyForWorkspace(
  workspaceDir: string,
  sources?: SandboxPolicyMergeSources
): Promise<SandboxPolicyMergeResult<SandboxPolicy>> {
  if (!sources) return { policy: { type: "insecure_none" } };

  const dotGitStat = await stat(join(workspaceDir, ".git")).then(
    s => s,
    () => null
  );
  const isWorktree = dotGitStat?.isFile() ?? false;
  const isGitRepo = dotGitStat !== null;

  if (getSandboxPolicyType(sources) === "workspace_readwrite") {
    // Resolve the git common directory for write-protection patterns.
    // For worktrees, this is the main repo's .git/; for normal repos, <workspace>/.git/.
    let gitDirParent: string = workspaceDir;

    if (isWorktree) {
      const commonDir = await spawnPromise(
        "git",
        ["rev-parse", "--git-common-dir"],
        { cwd: workspaceDir }
      ).then(
        x => resolve(workspaceDir, x.trim()),
        () => null
      );

      if (commonDir) {
        gitDirParent = dirname(commonDir);

        const p = sources.perRepo as
          | WorkspaceReadWriteSandboxPolicy
          | undefined;
        const ig = p?.ignoreMapping;

        sources = {
          ...sources,
          perRepo: {
            ...p,
            type: "workspace_readwrite",
            additionalReadwritePaths: [
              ...(p?.additionalReadwritePaths ?? []),
              commonDir,
            ],
            ignoreMapping: ig,
            writeProtectionMapping: mergeIgnoreMappings(
              p?.writeProtectionMapping as IgnoreMapping | undefined,
              getWorktreeWriteProtectionMapping(workspaceDir)
            ),
          },
        };
      }
    }

    // Merge git write-protection patterns keyed to the resolved git dir parent.
    // For normal repos gitDirParent === workspaceDir; for worktrees it's the
    // main repo root so patterns like .git/hooks/** target the real hooks.
    if (isGitRepo) {
      return mergeSandboxPolicies(sources, {
        workspaceDir,
        gitDirParent,
      });
    }
  }

  return mergeSandboxPolicies(sources, { workspaceDir });
}

// ============================================================================
// Main Merge Function
// ============================================================================

type SandboxPolicyType = SandboxPolicy["type"];

/**
 * Determines the policy type from all provided sources.
 * Throws if mixed policy types are provided.
 */
function validateAndGetPolicyType(
  sources: SandboxPolicyMergeSources
): SandboxPolicyType | undefined {
  const { perUser, perRepo, teamAdmin } = sources;
  const definedPolicies = [perUser, perRepo, teamAdmin].filter(
    (p): p is SandboxPolicy => p !== undefined
  );

  if (definedPolicies.length === 0) {
    return undefined;
  }

  const firstType = definedPolicies[0]!.type;
  for (const policy of definedPolicies) {
    if (policy.type !== firstType) {
      throw new Error(
        `Cannot merge policies of different types: found "${firstType}" and "${policy.type}". ` +
          `All policies must be of the same type (all workspace_readwrite, all workspace_readonly, or all insecure_none).`
      );
    }
  }

  return firstType;
}

/**
 * Merges SandboxPolicy from multiple sources with proper precedence.
 * All provided policies must be of the same type.
 *
 * Priority order (lowest to highest):
 * 1. Per-user settings (optional)
 * 2. Per-repo settings
 * 3. Team Admin (optional)
 * 4. Hard-coded (always applied, cannot be overridden) - only for sandboxed policies
 *
 * @param sources - Policy sources to merge (all must be same type)
 * @param options - Merge options
 * @returns Merged policy with optional debug info
 * @throws Error if policies of different types are provided
 */
export function mergeSandboxPolicies<T extends SandboxPolicy>(
  sources: SandboxPolicyMergeSources<T>,
  options?: SandboxPolicyMergeOptions
): SandboxPolicyMergeResult<T> {
  const policyType = validateAndGetPolicyType(sources);

  // If no policies provided, default to workspace_readwrite
  if (policyType === undefined) {
    return mergeWorkspaceReadWritePolicies(
      sources as SandboxPolicyMergeSources<WorkspaceReadWriteSandboxPolicy>,
      options
    ) as SandboxPolicyMergeResult<T>;
  }

  switch (policyType) {
    case "workspace_readwrite":
      return mergeWorkspaceReadWritePolicies(
        sources as SandboxPolicyMergeSources<WorkspaceReadWriteSandboxPolicy>,
        options
      ) as SandboxPolicyMergeResult<T>;
    case "workspace_readonly":
      return mergeWorkspaceReadOnlyPolicies(
        sources as SandboxPolicyMergeSources<WorkspaceReadOnlySandboxPolicy>,
        options
      ) as SandboxPolicyMergeResult<T>;
    case "insecure_none":
      return mergeInsecureNonePolicies(
        sources as SandboxPolicyMergeSources<InsecureNoneSandboxPolicy>,
        options
      ) as SandboxPolicyMergeResult<T>;
    default: {
      const _exhaustive: never = policyType;
      throw new Error(`Unknown policy type: ${policyType}`);
    }
  }
}

// ============================================================================
// Internal Merge Implementations
// ============================================================================

/**
 * Common fields shared between workspace_readwrite and workspace_readonly policies.
 */
interface CommonMergedFields {
  disableTmpWrite: boolean | undefined;
  networkPolicyStrict: boolean;
  readBoundary: SandboxReadBoundary;
  additionalReadPaths: string[] | undefined;
  additionalReadonlyPaths: string[] | undefined;
  networkPolicy: NetworkPolicy;
  debugOutputDir: string | undefined;
  captureDenies: boolean | undefined;
  enableSharedBuildCache: boolean | undefined;
  ignoreMapping: IgnoreMapping | undefined;
  writeProtectionMapping: IgnoreMapping | undefined;
  fieldSources: Record<string, string>;
}

/**
 * Merges common fields shared between workspace_readwrite and workspace_readonly policies.
 * This helper reduces code duplication between the two merge functions.
 */
function mergeCommonWorkspaceFields<
  T extends WorkspaceReadWriteSandboxPolicy | WorkspaceReadOnlySandboxPolicy,
>(
  sources: SandboxPolicyMergeSources<T>,
  options?: SandboxPolicyMergeOptions
): CommonMergedFields {
  const debug = options?.debug;
  const { perUser, perRepo, teamAdmin } = sources;
  // Backward compatibility: callers may omit options entirely.
  const workspaceDir = options?.workspaceDir ?? process.cwd();
  const hardcoded = getHardcodedSandboxPolicy(workspaceDir);

  const fieldSources: Record<string, string> = {};
  const orderedSources = [perUser, perRepo, teamAdmin];
  const sourceNames = ["perUser", "perRepo", "teamAdmin", "hardcoded"];

  const recordSource = (field: string, sourceIndex: number): void => {
    if (debug) {
      fieldSources[field] = sourceNames[sourceIndex] ?? "unknown";
    }
  };

  const disableTmpWrite = mergeRestrictiveBoolean(
    perUser?.disableTmpWrite,
    perRepo?.disableTmpWrite,
    teamAdmin?.disableTmpWrite
  );

  for (let i = orderedSources.length - 1; i >= 0; i--) {
    if (orderedSources[i]?.disableTmpWrite === true) {
      recordSource("disableTmpWrite", i);
      break;
    }
  }

  const networkPolicyStrict = mergeRestrictiveBoolean(
    perUser?.networkPolicyStrict,
    perRepo?.networkPolicyStrict,
    teamAdmin?.networkPolicyStrict,
    hardcoded.networkPolicyStrict
  );

  if (hardcoded.networkPolicyStrict) {
    recordSource("networkPolicyStrict", 3);
  }

  const readBoundary = mergeReadBoundary(
    perUser?.readBoundary,
    perRepo?.readBoundary,
    teamAdmin?.readBoundary
  );
  const additionalReadPaths = mergeAdditionalReadPaths(
    workspaceReadPathsSource(
      perUser?.readBoundary,
      perUser?.additionalReadPaths
    ),
    workspaceReadPathsSource(
      perRepo?.readBoundary,
      perRepo?.additionalReadPaths
    ),
    workspaceReadPathsSource(
      teamAdmin?.readBoundary,
      teamAdmin?.additionalReadPaths
    )
  );
  const mergedReadPaths =
    readBoundary === "workspace" ? additionalReadPaths : undefined;

  const additionalReadonlyPaths: string[] | undefined = mergePathsUnion(
    perUser?.additionalReadonlyPaths,
    perRepo?.additionalReadonlyPaths,
    teamAdmin?.additionalReadonlyPaths,
    hardcoded.additionalReadonlyPaths
  );
  const mergedReadonlyPaths =
    additionalReadonlyPaths.length > 0 ? additionalReadonlyPaths : undefined;

  // Merge network policies from all sources (allowlists are unioned).
  // Then apply teamAdmin replace: if teamAdmin has a non-empty allowlist,
  // it replaces the unioned allowlist entirely (admin is authoritative).
  let mergedNetworkPolicy = mergeNetworkPolicies(
    perUser?.networkPolicy,
    perRepo?.networkPolicy,
    teamAdmin?.networkPolicy,
    hardcoded.networkPolicy
  );

  const teamAdminAllow = teamAdmin?.networkPolicy?.allow;
  if (
    teamAdminAllow !== undefined &&
    teamAdminAllow.length > 0 &&
    mergedNetworkPolicy !== undefined
  ) {
    mergedNetworkPolicy = {
      ...mergedNetworkPolicy,
      allow: [...teamAdminAllow],
    };
    if (debug) {
      fieldSources["networkPolicy.allow"] = "teamAdmin (replace)";
    }
  }

  // Normalize: ensure merged policy is always concrete (never undefined).
  const networkPolicy = getEffectiveNetworkPolicy(mergedNetworkPolicy);

  const debugOutputDir = takeHighestPriorityDefined(
    perUser?.debugOutputDir,
    perRepo?.debugOutputDir,
    teamAdmin?.debugOutputDir
  );

  const captureDenies = mergeRestrictiveBoolean(
    perUser?.captureDenies,
    perRepo?.captureDenies,
    teamAdmin?.captureDenies
  );

  const enableSharedBuildCache = takeHighestPriorityDefined(
    perUser?.enableSharedBuildCache,
    perRepo?.enableSharedBuildCache,
    teamAdmin?.enableSharedBuildCache
  );

  const ignoreMapping: IgnoreMapping | undefined = mergeIgnoreMappings(
    perUser?.ignoreMapping as IgnoreMapping | undefined,
    perRepo?.ignoreMapping as IgnoreMapping | undefined,
    teamAdmin?.ignoreMapping as IgnoreMapping | undefined,
    hardcoded.ignoreMapping as IgnoreMapping | undefined
  );

  // Resolve git write-protection patterns. When gitDirParent is provided
  // (from resolveSandboxPolicyForWorkspace), git patterns are keyed to the
  // resolved git common dir's parent. Otherwise they fall back to workspaceDir.
  const gitDirParent = options?.gitDirParent ?? workspaceDir;
  const gitWriteProtection = getGitWriteProtectionMapping(gitDirParent);

  const writeProtectionMapping: IgnoreMapping | undefined = mergeIgnoreMappings(
    perUser?.writeProtectionMapping as IgnoreMapping | undefined,
    perRepo?.writeProtectionMapping as IgnoreMapping | undefined,
    teamAdmin?.writeProtectionMapping as IgnoreMapping | undefined,
    hardcoded.writeProtectionMapping as IgnoreMapping | undefined,
    gitWriteProtection
  );

  return {
    disableTmpWrite: disableTmpWrite || undefined,
    networkPolicyStrict,
    readBoundary,
    additionalReadPaths: mergedReadPaths,
    additionalReadonlyPaths: mergedReadonlyPaths,
    networkPolicy,
    debugOutputDir,
    captureDenies: captureDenies || undefined,
    enableSharedBuildCache,
    ignoreMapping,
    writeProtectionMapping,
    fieldSources,
  };
}

/**
 * Removes undefined values from a policy object and returns a clean copy.
 */
function cleanPolicy<T extends SandboxPolicy>(policy: T, type: T["type"]): T {
  const clean = Object.fromEntries(
    Object.entries(policy).filter(([_, v]) => v !== undefined)
  ) as T;
  clean.type = type;
  return clean;
}

function mergeWorkspaceReadWritePolicies(
  sources: SandboxPolicyMergeSources<WorkspaceReadWriteSandboxPolicy>,
  options?: SandboxPolicyMergeOptions
): SandboxPolicyMergeResult<WorkspaceReadWriteSandboxPolicy> {
  const { perUser, perRepo, teamAdmin } = sources;
  const debug = options?.debug;

  const common = mergeCommonWorkspaceFields(sources, options);

  // ReadWrite-specific fields
  const orderedSources = [perUser, perRepo, teamAdmin];
  const sourceNames = ["perUser", "perRepo", "teamAdmin", "hardcoded"];

  const additionalReadwritePaths = mergePathsUnion(
    perUser?.additionalReadwritePaths,
    perRepo?.additionalReadwritePaths,
    teamAdmin?.additionalReadwritePaths
  );

  const policy: WorkspaceReadWriteSandboxPolicy = {
    type: "workspace_readwrite",
    disableTmpWrite: common.disableTmpWrite,
    networkPolicyStrict: common.networkPolicyStrict,
    readBoundary: common.readBoundary,
    additionalReadPaths: common.additionalReadPaths,
    additionalReadwritePaths:
      additionalReadwritePaths.length > 0
        ? additionalReadwritePaths
        : undefined,
    additionalReadonlyPaths: common.additionalReadonlyPaths,
    networkPolicy: common.networkPolicy,
    debugOutputDir: common.debugOutputDir,
    captureDenies: common.captureDenies,
    enableSharedBuildCache: common.enableSharedBuildCache,
    ignoreMapping: common.ignoreMapping,
    writeProtectionMapping: common.writeProtectionMapping,
  };

  const result: SandboxPolicyMergeResult<WorkspaceReadWriteSandboxPolicy> = {
    policy: cleanPolicy(policy, "workspace_readwrite"),
  };
  if (debug) {
    result.debug = { fieldSources: common.fieldSources };
  }
  return result;
}

