/**
 * Utility functions for deriving network enablement from NetworkPolicy.
 */

import type { NetworkPolicy } from "../types.js";

/**
 * Returns a concrete NetworkPolicy for cases where the input is undefined.
 * Undefined means "no opinion" → defaults to deny-by-default (network disabled).
 */
export function getEffectiveNetworkPolicy(
  policy?: NetworkPolicy
): NetworkPolicy {
  if (policy !== undefined) {
    return policy;
  }
  return { version: 1, default: "deny" };
}

/**
 * Determines whether network access is enabled by a given NetworkPolicy.
 *
 * Returns true when either:
 *  - `policy.default === "allow"` (allow-all mode), OR
 *  - `policy.allow` has at least one entry (allowlist mode)
 *
 * Returns false otherwise (including deny-by-default with only a denylist,
 * which should not grant network access).
 */
export function isNetworkEnabledByPolicy(policy?: NetworkPolicy): boolean {
  if (policy === undefined) {
    return false;
  }
  if (policy.default === "allow") {
    return true;
  }
  if (policy.allow !== undefined && policy.allow.length > 0) {
    return true;
  }
  return false;
}

/**
 * Determines whether a policy represents "allow all" network access
 * (as opposed to allowlist-filtered access).
 *
 * Used to preserve the existing behavior where Statsig defaults are NOT
 * applied to "allow all" policies (they would introduce restrictions).
 */
export function isAllowAllNetworkByPolicy(policy?: NetworkPolicy): boolean {
  if (policy === undefined) {
    return false;
  }
  return policy.default === "allow";
}

/**
 * Convenience: build a deny-by-default (network disabled) policy.
 */
export function networkDisabledPolicy(): NetworkPolicy {
  return { version: 1, default: "deny" };
}

/**
 * Convenience: build an allow-all (unrestricted network) policy.
 */
export function networkAllowAllPolicy(): NetworkPolicy {
  return { version: 1, default: "allow" };
}
