export class McpSandboxUnavailableError extends Error {
  constructor(
    readonly serverName: string,
    cause?: unknown
  ) {
    super(
      `MCP server "${serverName}" requires sandboxing because MCP Network Controls are enabled, but the sandbox is not supported on this platform or system. The server was not started.`
    );
    this.name = "McpSandboxUnavailableError";
    if (cause !== undefined) {
      (this as Error & { cause?: unknown }).cause = cause;
    }
  }
}
