import { SimpleControlledExecHandler } from "./controlled.js";
import { ExecutorResource } from "./remote.js";
import { createResource } from "./resource-provider.js";
import { createClientDeserializer, createClientSerializer, createServerDeserializer, createServerSerializer, } from "./serialization.js";
export const COMPUTER_USE_SCREENSHOT_SETTLE_DELAY_MS = 2000;
export const computerUseExecutorResource = createResource(execManager => new ExecutorResource(execManager, createServerSerializer("computerUseArgs"), createClientDeserializer("computerUseResult")), (implementation, controlledExecManager) => {
    controlledExecManager.register(new SimpleControlledExecHandler(implementation, createServerDeserializer("computerUseArgs"), createClientSerializer("computerUseResult")));
});
