import { createValidationResult, isObject, isString } from "./base.js";
import { validateBaseHookResponse } from "./baseHookResponse.js";
export const validateSessionStartResponse = (value) => {
    // First validate base response
    const baseValidation = validateBaseHookResponse(value);
    if (!baseValidation.isValid) {
        return baseValidation;
    }
    const errors = [];
    // Validate env field if present
    if (value.env !== undefined) {
        if (!isObject(value.env)) {
            errors.push("env must be an object if provided");
        }
        else {
            for (const [key, val] of Object.entries(value.env)) {
                if (!isString(key)) {
                    errors.push(`env key "${key}" must be a string`);
                }
                if (!isString(val)) {
                    errors.push(`env value for "${key}" must be a string`);
                }
            }
        }
    }
    // Validate additional_context field if present
    if (value.additional_context !== undefined &&
        !isString(value.additional_context)) {
        errors.push("additional_context must be a string if provided");
    }
    // Validate continue field if present
    if (value.continue !== undefined && typeof value.continue !== "boolean") {
        errors.push("continue must be a boolean if provided");
    }
    // Validate user_message field if present
    if (value.user_message !== undefined && !isString(value.user_message)) {
        errors.push("user_message must be a string if provided");
    }
    return createValidationResult(errors.length === 0, errors);
};
