import type { SpawnOptionsWithoutStdio } from "node:child_process";
import { type Context, createSpan, reportEvent } from "@anysphere/context";
import { createWritableIterable } from "@anysphere/utils";
import { spawnWithSignal } from "./core.js";
import {
  attachShellOutputStreams,
  type BufferReadable,
} from "./output-limiter.js";
import { getPowerShellExecutable } from "./powershell.js";
import { resolveSandboxPolicyForWorkspace } from "./sandbox/policy-merge.js";
import { captureSandboxDenies } from "./sandbox/sandbox.js";
import { shouldEnableSudoAskpass, transformSudoCommand } from "./sudo.js";
import {
  type NaiveTerminalExecutorOptions,
  SHELL_ENV_OVERRIDES,
  type TerminalCommandOptions,
  type TerminalEvent,
  type TerminalExecutor,
} from "./types.js";

/**
 * A naive TerminalExecutor implementation that simply executes commands
 * using the default shell without any state preservation between commands.
 */
export class NaiveTerminalExecutor implements TerminalExecutor {
  constructor(
    private readonly cwd: string,
    private readonly options?: NaiveTerminalExecutorOptions | undefined
  ) {}

  async getCwd(): Promise<string> {
    return this.cwd;
  }

  clone(workingDirectory?: string): NaiveTerminalExecutor {
    return new NaiveTerminalExecutor(
      workingDirectory ?? this.cwd,
      this.options
    );
  }

  async *execute(
    ctx: Context,
    command: string,
    options?: TerminalCommandOptions
  ): AsyncIterable<TerminalEvent> {
    using span = createSpan(ctx.withName("NaiveTerminalExecutor.execute"));

    const iterable = createWritableIterable<TerminalEvent>();
    const pipeStdin = options?.pipeStdin ?? false;

    // Set environment variables to disable color output
    const env = {
      ...process.env,
      ...SHELL_ENV_OVERRIDES,
      ...options?.env,
    };

    // Transform sudo commands to use -A flag when askpass is configured
    // The naive runner can't use aliases (each command runs in a fresh shell),
    // so we must transform the command string directly
    const transformedCommand = shouldEnableSudoAskpass(env)
      ? transformSudoCommand(command)
      : command;

    const cwd = options?.workingDirectory ?? this.cwd;
    const sandboxWorkspaceRoot = options?.sandboxWorkspaceRoot ?? cwd;
    const resolvedPolicy = (
      await resolveSandboxPolicyForWorkspace(
        sandboxWorkspaceRoot,
        options?.sandboxPolicy
      )
    ).policy;
    const sandboxPolicy =
      resolvedPolicy.type !== "insecure_none"
        ? { ...resolvedPolicy, sandboxWorkspaceRoot }
        : resolvedPolicy;

    const child = spawnWithSignal(
      this.options?.shell || process.env.SHELL || "/bin/sh",
      [...(this.options?.shellArgs ?? []), "-c", transformedCommand],
      {
        env,
        cwd,
        // Use 'ignore' for stdin unless interactive, to prevent background
        // processes from inheriting an open stdin pipe
        stdio: [pipeStdin ? "pipe" : "ignore", "pipe", "pipe"],
      } as SpawnOptionsWithoutStdio,
      sandboxPolicy,
      options?.signal
    );

    // Pass the stdin stream to the background terminal state if available, for the writeShellStdin tool to use
    child.on("spawn", async () => {
      try {
        await iterable.write({
          type: "stdin_ready",
          stdin: child.stdin ?? undefined,
          pid: child.pid,
        });
      } catch (_error) {
        // Iterable might be closed, ignore write errors
      }
    });

    const outputPump = attachShellOutputStreams({
      stdout: child.stdout as BufferReadable | null,
      stderr: child.stderr as BufferReadable | null,
      writable: iterable,
      bufferOutputEvents: options?.bufferOutputEvents,
      outputLimiterOptions: options?.outputLimiterOptions,
    });

    // Handle process exit and errors
    child.on("error", error => {
      iterable.throw(error);
    });

    // NB: This naive implementation uses 'exit' instead of 'close' for simplicity
    // and speed. It accepts the risk of potentially missing some buffered output
    // in exchange for not hanging on background processes.
    child.on("exit", async code => {
      reportEvent(span.ctx, "exit");
      await outputPump.flush();

      // Attempt to capture sandbox deny events (best-effort)
      if (sandboxPolicy.captureDenies ?? false) {
        try {
          const denyEvents = await captureSandboxDenies(child);
          if (denyEvents && denyEvents.length > 0) {
            await iterable.write({
              type: "sandbox_denies",
              events: denyEvents,
            });
          }
        } catch {}
      }
      try {
        await iterable.write({
          type: "exit",
          code,
          data: "",
          aborted: options?.signal?.aborted ?? false,
        });
        iterable.close();
      } catch (_error) {
        // Iterable might be closed, ignore write errors
        iterable.close();
      }
    });

    yield* iterable;
  }
}

/**
 * Create a new NaiveTerminalExecutor instance.
 * On Windows, uses PowerShell. On other platforms, uses the default shell.
 * @param options - Optional options to use (shell defaults to PowerShell on Windows, process.env.SHELL or /bin/sh otherwise)
 * @returns A new NaiveTerminalExecutor instance
 */
export function createNaiveTerminalExecutor(
  options?: NaiveTerminalExecutorOptions
): NaiveTerminalExecutor {
  const isWindows = process.platform === "win32";
  const shell =
    options?.shell ?? (isWindows ? getPowerShellExecutable() : undefined);
  const cwd = process.cwd();
  return new NaiveTerminalExecutor(cwd, { ...options, shell });
}
