import type { Stats } from "node:fs";
import { realpath, stat } from "node:fs/promises";
import { homedir } from "node:os";
import { isAbsolute, relative, resolve } from "node:path";

import {
	backgroundShellExecutorResource,
	lsExecutorResource,
	readExecutorResource,
	RegistryResourceAccessor,
	shellStreamExecutorResource,
	SimpleControlledExecManager,
} from "@anysphere/agent-exec";
import {
	BaseShellCoreExecutor,
	LocalBackgroundShellExecutor,
	LocalLsExecutor,
	LocalReadExecutor,
	LocalShellStreamExecutor,
	MockIgnoreService,
	MockPermissionsService,
} from "@anysphere/local-exec";
import { ReadError, ReadResult } from "@anysphere/proto/agent/v1/read_exec_pb.js";
import { ShellStream, ShellStreamStderr } from "@anysphere/proto/agent/v1/shell_exec_pb.js";
import { createDefaultTerminalExecutor } from "@anysphere/shell-exec";
import { resolvePath } from "@anysphere/utils";

import { localExecFileTooLargeMessage } from "../../shared/local-exec-gateway.js";
import { realpathNearestExisting } from "../../shared/node/paths.js";

export class SandLocalExecPathError extends Error {}

async function statOrUndefined(path: string): Promise<Stats | undefined> {
	try {
		return await stat(path);
	} catch {
		return undefined;
	}
}

export async function regularFileSizeBytes(path: string): Promise<number | undefined> {
	const stats = await statOrUndefined(path);
	return stats?.isFile() ? stats.size : undefined;
}

export function resolveLocalExecRoot(env: NodeJS.ProcessEnv = process.env): string {
	const configured = env.SAND_LOCAL_EXEC_ROOT?.trim() || env.SAND_AGENT_PROJECT_DIR?.trim();
	return configured != null && configured.length > 0 ? configured : homedir();
}

async function isDirectory(path: string): Promise<boolean> {
	return (await statOrUndefined(path))?.isDirectory() ?? false;
}

export interface ShellWorkingDirectoryResolution {
	readonly workingDirectory: string;
	readonly fellBackToRoot: boolean;
}

export async function resolveShellWorkingDirectory(args: {
	readonly root: string;
	readonly requested: string;
}): Promise<ShellWorkingDirectoryResolution> {
	const requested = args.requested.trim();
	if (requested.length === 0) {
		return { workingDirectory: requested, fellBackToRoot: false };
	}
	const resolved = resolvePath(requested, args.root);
	if (await isDirectory(resolved)) {
		return { workingDirectory: resolved, fellBackToRoot: false };
	}
	return { workingDirectory: args.root, fellBackToRoot: true };
}

function missingWorkingDirectoryNotice(args: {
	readonly requested: string;
	readonly root: string;
}): string {
	return `working directory ${args.requested} does not exist on this machine; running in ${args.root} instead\n`;
}

function escapesRoot(base: string, target: string): boolean {
	const rel = relative(base, target);
	return rel !== "" && (rel.startsWith("..") || isAbsolute(rel));
}

export async function containPath(args: {
	readonly root: string;
	readonly path: string;
}): Promise<string> {
	const { root, path: p } = args;
	const resolved = isAbsolute(p) ? resolve(p) : resolve(root, p);
	if (escapesRoot(root, resolved)) {
		throw new SandLocalExecPathError(
			`Path is outside the allowed local-exec root and was refused: ${p}`,
		);
	}
	let realRoot: string;
	try {
		realRoot = await realpath(root);
	} catch {
		return resolved;
	}
	const realResolved = await realpathNearestExisting(resolved);
	if (escapesRoot(realRoot, realResolved)) {
		throw new SandLocalExecPathError(
			`Path resolves through a symlink to outside the allowed local-exec root and was refused: ${p}`,
		);
	}
	return resolved;
}

export function buildLocalExecManager(
	root: string,
	maxFileBytes: number,
): SimpleControlledExecManager {
	const permissionsService = new MockPermissionsService();
	const ignoreService = new MockIgnoreService();
	const terminalExecutor = createDefaultTerminalExecutor({
		env: { CURSOR_AGENT: "1", SAND_AGENT: "1" },
	}).clone(root);
	const shellCoreExecutor = new BaseShellCoreExecutor(terminalExecutor, root, root);
	const backgroundShellExecutor = new LocalBackgroundShellExecutor(
		permissionsService,
		shellCoreExecutor,
		ignoreService,
		root,
		undefined,
		undefined,
	);
	const shellStreamExecutor = new LocalShellStreamExecutor(
		permissionsService,
		shellCoreExecutor,
		ignoreService,
		backgroundShellExecutor.getManager(),
	);
	const readExecutor = new LocalReadExecutor(permissionsService, root);
	const lsExecutor = new LocalLsExecutor(permissionsService, ignoreService, root);

	const registry = new RegistryResourceAccessor();
	registry.register(shellStreamExecutorResource, {
		execute: (ctx, args) =>
			(async function* () {
				const requested = args.workingDirectory;
				const resolution = await resolveShellWorkingDirectory({
					root,
					requested,
				});
				args.workingDirectory = resolution.workingDirectory;
				if (resolution.fellBackToRoot) {
					yield new ShellStream({
						event: {
							case: "stderr",
							value: new ShellStreamStderr({
								data: missingWorkingDirectoryNotice({ requested, root }),
							}),
						},
					});
				}
				yield* shellStreamExecutor.execute(ctx, args);
			})(),
	});
	registry.register(backgroundShellExecutorResource, {
		execute: async (ctx, args) => {
			const resolution = await resolveShellWorkingDirectory({
				root,
				requested: args.workingDirectory,
			});
			args.workingDirectory = resolution.workingDirectory;
			return await backgroundShellExecutor.execute(ctx, args);
		},
	});
	registry.register(readExecutorResource, {
		execute: async (ctx, args) => {
			const resolved = await containPath({ root, path: args.path });
			// Refuse a file too large to return over the wire BEFORE the executor
			// reads it fully into memory — readText/readFile of a multi-hundred-MB
			// file (a big log, a video/PDF returned as raw bytes) is exactly what
			// OOM-aborts the daemon. Missing/non-file paths fall through so the
			// executor still returns its typed not-found / directory result.
			const sizeBytes = await regularFileSizeBytes(resolved);
			if (sizeBytes !== undefined && sizeBytes > maxFileBytes) {
				return new ReadResult({
					result: {
						case: "error",
						value: new ReadError({
							path: resolved,
							error: localExecFileTooLargeMessage(sizeBytes, maxFileBytes),
						}),
					},
				});
			}
			return await readExecutor.execute(ctx, args);
		},
	});
	registry.register(lsExecutorResource, {
		execute: async (ctx, args) => {
			await containPath({ root, path: args.path });
			return await lsExecutor.execute(ctx, args);
		},
	});
	return SimpleControlledExecManager.fromResources(registry);
}
