import { authTransition } from './auth-fsm.js';
import { connectionTransition } from './connection-fsm.js';
import { project } from './projection.js';
import type {
	AuthEvent,
	AuthState,
	BackoffConfig,
	ConnectionCommand,
	ConnectionEvent,
	ConnectionState,
	CoordinatorResult,
	FSMEvent,
} from './types.js';

export interface CoordinatorConfig {
	backoff: BackoffConfig;
}

/**
 * Routes events to the correct FSM, applies cross-cutting rules,
 * and returns the composed result with projected status.
 */
export function coordinatorTransition(
	connectionState: ConnectionState,
	authState: AuthState,
	event: FSMEvent,
	config: CoordinatorConfig,
): CoordinatorResult {
	let newConnState = connectionState;
	let newAuthState = authState;
	let commands: ConnectionCommand[] = [];

	switch (event.target) {
		case 'connection': {
			// Cross-cutting rule: suppress timer-driven reconnects when auth requires user action.
			// needsUserAuth: user must complete OAuth flow.
			// expired: credentials are invalid; retrying with the same creds is pointless.
			// Applies to both fast-retry backoff and slow periodic retry timers.
			const authBlocksRetry = authState.type === 'needsUserAuth' || authState.type === 'expired';
			if ((event.kind === 'backoff_timer_expired' || event.kind === 'periodic_retry_expired') && authBlocksRetry) {
				// No-op — swallow the event
			} else {
				// Strip `target` to build a proper ConnectionEvent
				const { target: _, ...connFields } = event;
				const connEvent = connFields as ConnectionEvent;
				const result = connectionTransition(connectionState, connEvent, config.backoff);
				if (result.state !== null) {
					newConnState = result.state;
				}
				commands = result.commands;

				// Cross-cutting rule: successful reconnect heals expired auth.
				// If auth was `expired` (an operation got 401/403) but we just
				// successfully reconnected, the new connection likely has fresh
				// credentials (OAuth token refresh happens during transport creation).
				// Without this rule, expired auth stays stuck until the next
				// successful tool call / list operation dispatches operation_succeeded.
				if (event.kind === 'connect_success' && authState.type === 'expired') {
					const healResult = authTransition(authState, { kind: 'operation_succeeded' });
					if (healResult !== null) {
						newAuthState = healResult;
					}
				}
			}
			break;
		}
		case 'auth': {
			const prevAuthState = authState;
			const { target: _, ...authFields } = event;
			const authEvent = authFields as AuthEvent;
			const result = authTransition(authState, authEvent);
			if (result !== null) {
				newAuthState = result;
			}

			// Cross-cutting rule: when auth leaves a blocking state, kick the
			// connection FSM if it stalled while timer events were suppressed.
			// Both needsUserAuth and expired block timer-driven reconnects
			// (see the suppression guard above), so recovering from either
			// must restart the connection.
			const authWasBlocking = prevAuthState.type === 'needsUserAuth' || prevAuthState.type === 'expired';
			const authNowClear = newAuthState.type !== 'needsUserAuth' && newAuthState.type !== 'expired';
			const connStalled = newConnState.type === 'transient_failure' ||
				newConnState.type === 'failed' ||
				newConnState.type === 'closed';

			if (authWasBlocking && authNowClear && connStalled) {
				const kickResult = connectionTransition(newConnState, { kind: 'connect_start' }, config.backoff);
				if (kickResult.state !== null) {
					newConnState = kickResult.state;
				}
				commands.push(...kickResult.commands);
				// connect_start from transient_failure only cancels the timer,
				// we also need to actually initiate the connection
				commands.push({ type: 'initiate_connection' });
			}
			break;
		}
		default: {
			const _exhaustive: never = event;
			return _exhaustive;
		}
	}

	const projectedStatus = project(newConnState, newAuthState);

	return {
		connectionState: newConnState,
		authState: newAuthState,
		commands,
		projectedStatus,
	};
}
