import {
  type ChildProcess,
  type SpawnOptionsWithoutStdio,
  spawn,
} from "node:child_process";
import { accessSync, constants as fsConstants } from "node:fs";
import type { Context } from "@anysphere/context";
import { filterElectronEnv } from "../env-filter.js";
import type { SandboxPolicy } from "../types.js";
import { getSandboxCacheEnv } from "./cache-env.js";
import {
  type ConfigureSandboxPrereqsOptions,
  configureSandboxPrereqs as configureSandboxPrereqsInternal,
  getLastSandboxFailureReason as getLastSandboxFailureReasonInternal,
  getSandboxBinaryPath as getSandboxBinaryPathInternal,
  isSandboxHelperSupported,
  primeSandboxHelperSupport,
  spawnWithSandboxHelper,
} from "./helper.js";

// Re-export for external debugging
export {
  getLastSandboxFailureReasonInternal as getLastSandboxFailureReason,
  getSandboxBinaryPathInternal as getSandboxBinaryPath,
};

/**
 * Thrown by {@link spawnInSandbox} when a sandboxed policy is requested but the
 * sandbox helper/platform cannot enforce it. Fail-closed callers can
 * `instanceof`-check this to surface a clear reason instead of pattern-matching
 * the error message.
 */
export class SandboxUnsupportedError extends Error {
  constructor(
    message: string,
    readonly reason?: string
  ) {
    super(message);
    this.name = "SandboxUnsupportedError";
  }
}

import { captureSandboxDenies as macOSCaptureSandboxDenies } from "./macos/seatbelt.js";

// Platform detection
const isMacOS = process.platform === "darwin";

export interface SandboxDenyEvent {
  timestamp?: string;
  processName?: string;
  pid?: number;
  decision?: string;
  decisionCode?: number;
  operation?: string;
  target?: string;
  duplicateCount?: number; // defaults to 1 when omitted
  raw: string;
  /** Relationship to the sandboxed process: 'related', 'maybe_related', or 'probably_unrelated' */
  relationship?: "related" | "maybe_related" | "probably_unrelated";
}

// Re-export the options type for consumers
export type { ConfigureSandboxPrereqsOptions };

/**
 * Configure sandbox prerequisites: sandbox binary path.
 * Requires the global ripgrep path to already be configured.
 * This is the ONLY way to initialize the sandbox system - call this at startup.
 */
export function configureSandboxPrereqs(
  options: ConfigureSandboxPrereqsOptions
): void {
  configureSandboxPrereqsInternal(options);
}

/**
 * Spawns a child process with sandboxing based on the provided policy.
 * This is the main entry point that delegates to platform-specific implementations.
 * Linux and macOS use OS-level filesystem sandboxes via the helper; Windows uses
 * the same helper for network proxy / no-network policy only (no filesystem sandbox).
 *
 * @param command - The command to execute
 * @param args - Command arguments
 * @param options - Spawn options
 * @param sandboxPolicy - The sandbox policy to apply
 * @returns ChildProcess instance
 */
export function spawnInSandbox(
  command: string,
  args: string[] = [],
  options: SpawnOptionsWithoutStdio | undefined = {},
  sandboxPolicy: SandboxPolicy
): ChildProcess {
  options.env = filterElectronEnv(options.env);

  // Apply shared build cache env vars if enabled
  if (sandboxPolicy.enableSharedBuildCache) {
    options = {
      ...options,
      env: {
        ...filterElectronEnv(process.env),
        ...getSandboxCacheEnv(),
        ...options.env,
      },
    };
  }

  // Use a lightweight capability check to avoid expensive policy-aware preflight
  if (sandboxPolicy.type !== "insecure_none") {
    if (isSandboxHelperSupported()) {
      return spawnWithSandboxHelper(command, args, options, sandboxPolicy);
    }

    const failureReason = getLastSandboxFailureReasonInternal();
    throw new SandboxUnsupportedError(
      `Sandbox policy '${sandboxPolicy.type}' is not supported on this system. ` +
        `Ensure the sandbox helper binary is available, or use 'insecure_none'. ` +
        `Reason: ${failureReason || "unknown"}`,
      failureReason ?? undefined
    );
  }

  return spawnUnsafe(command, args, options);
}

function spawnUnsafe(
  command: string,
  args: string[],
  options: SpawnOptionsWithoutStdio
): ChildProcess {
  return spawn(command, args, options); // nosemgrep: detect-child-process
}

/**
 * Captures sandbox denial logs for a sandboxed process.
 * Call this function after a sandboxed process exits to see any sandbox violations.
 * Only works on macOS with seatbelt sandboxing.
 *
 * @param child - The ChildProcess returned from spawnInSandbox
 * @returns Promise that resolves with an array of deny events
 */
export function captureSandboxDenies(
  child: ChildProcess
): Promise<SandboxDenyEvent[]> {
  if (isMacOS) {
    return macOSCaptureSandboxDenies(child);
  } else {
    return Promise.resolve([]);
  }
}

/**
 * Returns true if sandboxing is supported on this platform/runtime.
 * All platforms (Linux, Windows, macOS) require the sandbox helper binary.
 * - macOS: also requires the system sandbox-exec to be available
 * - Linux: requires kernel >= 5.13 with Landlock, unprivileged user/mount namespaces
 * - Windows: requires the sandbox helper binary (network filtering / env only)
 */
export function isSandboxSupported(
  _policy?: SandboxPolicy,
  _options?: { cwd?: string; ctx?: Context }
): boolean {
  if (isMacOS) {
    // macOS needs both the helper binary and sandbox-exec
    try {
      accessSync("/usr/bin/sandbox-exec", fsConstants.X_OK);
    } catch {
      return false;
    }
  }
  // All platforms: check for the sandbox helper binary
  return isSandboxHelperSupported(_options?.ctx);
}

/**
 * Async counterpart to {@link isSandboxSupported} that probes from the given
 * workspace directory under a time budget, and caches the verdict for later
 * synchronous callers.
 *
 * Prefer this at startup. {@link isSandboxSupported} probes from the host
 * process's own cwd, which on Linux decides how much of the filesystem the
 * helper walks — so it can report "supported" in milliseconds on a host where
 * every sandboxed command in the real workspace times out during setup.
 */
export async function primeSandboxSupport(options: {
  workspaceCwd: string;
  timeoutMs?: number;
  ctx?: Context;
}): Promise<boolean> {
  if (isMacOS) {
    // macOS needs both the helper binary and sandbox-exec
    try {
      accessSync("/usr/bin/sandbox-exec", fsConstants.X_OK);
    } catch {
      return false;
    }
  }
  return primeSandboxHelperSupport(options);
}
