// The shared settings.json document implementation. Electron main and the
// settings host extension each own one process-local instance over their own Sand
// data root. Keeping the versioned schema and atomic read-modify-write behavior
// here lets both copies round-trip every mirrored field without either process
// importing the other's owner.

import { existsSync, mkdirSync, readFileSync, renameSync, writeFileSync } from "node:fs";
import { dirname } from "node:path";

import { z } from "zod";

import {
	type SandAgentDefaultModel,
	type SandComputerUseModel,
	sandAgentDefaultModelSchema,
	sandComputerUseModelSchema,
} from "../../agents/sand-agent-model.js";
import {
	DEFAULT_SAND_THEME_PREFERENCE,
	SAND_THEME_PREFERENCES,
	type SandThemePreference,
} from "../../desktop.js";
import {
	SAND_DISABLED_NOTIFICATION_CONFIG,
	type SandNotificationConfig,
	type SandNotificationConfigInput,
} from "../../host-settings.js";
import {
	resolveSandLocalToolPermission,
	SAND_DEFAULT_LOCAL_TOOL_PERMISSION,
	SAND_LOCAL_TOOL_PERMISSIONS,
	type SandLocalToolPermission,
} from "../../local-tool-permission.js";
import {
	clampMcpCustomInstruction,
	getDefaultMcpCustomInstruction,
} from "../../mcp-custom-instructions.js";
import {
	DEFAULT_SAND_AUTO_REVIEW_INSTRUCTIONS,
	normalizeSandAutoReviewInstructions,
	type SandAutoReviewInstructions,
} from "../../sand-auto-review-instructions.js";
import {
	SidebarSections,
	type SidebarSectionUpdate,
	type StoredSidebarSection,
} from "../../sidebar-sections.js";
import {
	coerceToEnabledTrack,
	SAND_UPDATE_TRACKS,
	type SandUpdateTrack,
} from "../../update-track.js";

const SETTINGS_VERSION = 1;

const autoReviewInstructionsSchema = z.object({
	isEnabled: z.boolean().default(true),
	allowInstructions: z.array(z.string()).default([]),
	blockInstructions: z.array(z.string()).default([]),
});

const CONCIERGE_CONSENTS = ["unset", "allowed", "denied"] as const;

// Historical id retained for settings files that already applied this migration.
export const SAND_DOWNGRADE_MAX_FAST_MIGRATION_ID = "downgrade-persisted-max-fast";

// Every one-time migration id, in application order. A fresh install pre-marks
// them all (emptySettings): there is no legacy persisted state to rewrite, so a
// brand-new user's later explicit choices must stick from the start.
const SAND_SETTINGS_MIGRATION_IDS: readonly string[] = [SAND_DOWNGRADE_MAX_FAST_MIGRATION_ID];

const notificationConfigSchema = z
	.object({
		isEnabled: z.boolean(),
		allowedApps: z.array(z.string()),
		minIntervalMs: z.number(),
		maxPerWindow: z.number(),
		windowMs: z.number(),
	})
	.partial();

const settingsSchema = z.object({
	version: z.literal(SETTINGS_VERSION),
	/** Names of user MCP servers configured to run inside the box. */
	mcpBoxServers: z.array(z.string().min(1)).default([]),
	hasSeenOnboarding: z.boolean().optional(),
	hasSeenOnboardingAccountScope: z.string().min(1).optional(),
	autoUpdateWhenIdleOptIn: z.boolean().default(false),
	/**
	 * The user's release-track choice for auto-updates; absent means follow
	 * the track the build was published to (see update/update-track.ts).
	 */
	updateTrackOverride: z.enum(SAND_UPDATE_TRACKS).optional(),
	/**
	 * Per-tool/connector custom instructions, keyed by MCP server name. Each value
	 * is a short prompt the agent must follow when using that connector's tools.
	 */
	mcpCustomInstructions: z.record(z.string(), z.string()).default({}),
	mcpCustomInstructionsByServerId: z.record(z.string(), z.string()).default({}),
	mcpCustomInstructionsAccountScope: z.string().min(1).optional(),
	/**
	 * Per-server disabled MCP tools, keyed by server row id to bare tool names.
	 * An absent server or tool name means enabled, so a server's new tools
	 * default to enabled. The `mcpCustomInstructionsAccountScope` field governs
	 * all account-scoped settings, including the permission and ceiling.
	 */
	mcpDisabledToolsByServerId: z.record(z.string(), z.array(z.string())).default({}),
	/**
	 * The user's appearance choice; absent means follow the default
	 * (`system`, i.e. track the OS color scheme).
	 */
	themePreference: z.enum(SAND_THEME_PREFERENCES).optional(),
	egressTunnelEnabled: z.boolean().default(false),
	webauthnProxyEnabled: z.boolean().default(true),
	/**
	 * The desktop mirror of the host-owned default model selection.
	 * It is account-scoped and resets when the signed-in account changes.
	 */
	agentDefaultModel: sandAgentDefaultModelSchema.optional(),
	/**
	 * The user's chosen model for computer-use subagents.
	 * It is account-scoped and resets when the signed-in account changes. Absent
	 * means use the dedicated baked-in CUA request profile.
	 */
	computerUseModel: sandComputerUseModelSchema.optional().catch(undefined),
	notifications: notificationConfigSchema.optional(),
	/**
	 * The user's IANA timezone (e.g. "America/Los_Angeles") as AUTO-DETECTED by
	 * the desktop and reported to the in-box host. The box runs in UTC, so the
	 * host reads this to interpret cron automation schedules and the agent's
	 * "now" on the user's wall clock. Absent until the desktop first reports it.
	 * Refreshed on every desktop (re)connect, so it tracks the machine the user
	 * actually runs on; a deliberate choice lives in `userTimeZoneOverride`.
	 */
	userTimeZone: z.string().min(1).optional(),
	/**
	 * The user's EXPLICIT timezone choice (Settings → Agent → Timezone). Wins
	 * over the auto-detected `userTimeZone` whenever present, and is never
	 * touched by the desktop's detection refresh — so a deliberate choice
	 * survives reconnects, box recreates, and OS timezone changes. Absent means
	 * follow auto-detection.
	 */
	userTimeZoneOverride: z.string().min(1).optional(),
	/**
	 * Retired connector-concierge consent. Keep round-tripping this tombstone
	 * while downgrades can reopen an older build, so a prior denial does not
	 * become `unset` and prompt the user again.
	 */
	conciergeConsent: z.enum(CONCIERGE_CONSENTS).default("unset"),
	/**
	 * Ids of one-time settings migrations already applied to this file. Each id's
	 * rewrite runs exactly once (guarded in applyPendingMigrations), so a
	 * migration never re-fights a choice the user makes AFTER it ran. Absent in
	 * pre-migration files (defaults to `[]`, so pending migrations run); a fresh
	 * install starts with the current ids pre-marked.
	 */
	settingsMigrations: z.array(z.string()).default([]),
	/**
	 * The user's Auto-review toggle and personal natural-language rules.
	 * They are account-scoped and reset when the signed-in account changes.
	 * They come only from this file, never model output, web/MCP tools, or
	 * workspace permission files.
	 */
	autoReviewInstructions: autoReviewInstructionsSchema.optional(),
	/**
	 * The user's account-scoped permission for LOCAL tools on their own computer
	 * (Shell / Read / AwaitShell / CopyToBox / CopyFromBox). It resets when the
	 * signed-in account changes; absent means the safe "ask" default.
	 */
	localToolPermission: z.enum(SAND_LOCAL_TOOL_PERMISSIONS).optional(),
	/**
	 * The team admin's ceiling on the above, mirrored here by the desktop after
	 * it reads the team's admin settings. Absent means the team states no policy.
	 *
	 * Cached on disk rather than fetched on demand for two reasons: the
	 * local-exec daemon — a separate process, and the authority on what may
	 * touch this machine — reads this file directly and has no backend
	 * credentials of its own; and the cache holds across a same-account restart,
	 * so a returning member is held from the first moment. An account change
	 * drops it and the sign-in ceiling fetch re-establishes it.
	 */
	localToolPermissionCeiling: z.enum(SAND_LOCAL_TOOL_PERMISSIONS).optional(),
	/**
	 * The user's pinned agents (ordered id list; index is pin position). The box
	 * owns this so pins sync across the user's devices. OPTIONAL on purpose:
	 * absent means never-written, so a client keeps its local pins and seeds them
	 * on the first pin/unpin, while a stored `[]` is an intentional clear that
	 * must persist as an empty list rather than re-reading as never-written.
	 */
	pinnedAgentIds: z.array(z.string().min(1)).optional(),
	sidebarSections: z
		.array(
			z.object({
				id: z.string().min(1),
				name: z.string(),
				agentIds: z.array(z.string().min(1)),
				isCollapsed: z.boolean(),
			}),
		)
		.optional(),
});

export type SandSettingsV1 = z.infer<typeof settingsSchema>;

function emptySettings(): SandSettingsV1 {
	return {
		version: SETTINGS_VERSION,
		mcpBoxServers: [],
		autoUpdateWhenIdleOptIn: false,
		egressTunnelEnabled: false,
		webauthnProxyEnabled: true,
		mcpCustomInstructions: {},
		mcpCustomInstructionsByServerId: {},
		mcpDisabledToolsByServerId: {},
		conciergeConsent: "unset",
		settingsMigrations: [...SAND_SETTINGS_MIGRATION_IDS],
	};
}

function downgradePersistedFast(
	model: SandAgentDefaultModel,
): NonNullable<SandSettingsV1["agentDefaultModel"]> {
	return {
		modelId: model.modelId,
		maxMode: true,
		parameters: model.parameters.map((parameter) => ({
			id: parameter.id,
			value: parameter.id === "fast" ? "false" : parameter.value,
		})),
	};
}

// Clamps each stored instruction to the max length and drops empty values, so a
// hand-edited settings file can never feed an over-length or blank instruction
// into the prompt. One exception: an empty value is *kept* for a connector that
// has a built-in default, because there it is the "user cleared the default"
// sentinel — dropping it would let the default resurrect on the next load. A
// connector with no default has nothing to suppress, so its empty is still
// dropped (absent == no instruction).
function normalizeCustomInstructions(
	raw: Readonly<Record<string, string>>,
): Record<string, string> {
	const normalized: Record<string, string> = {};
	for (const [name, value] of Object.entries(raw)) {
		const clamped = clampMcpCustomInstruction(value);
		if (clamped.trim().length > 0) {
			normalized[name] = clamped;
		} else if (getDefaultMcpCustomInstruction(name).length > 0) {
			normalized[name] = "";
		}
	}
	return normalized;
}

function normalizeCustomInstructionsByServerId(
	raw: Readonly<Record<string, string>>,
): Record<string, string> {
	const normalized: Record<string, string> = {};
	for (const [serverId, value] of Object.entries(raw)) {
		if (!/^[1-9]\d*$/.test(serverId)) continue;
		normalized[serverId] = clampMcpCustomInstruction(value);
	}
	return normalized;
}

// Same key rule as the custom-instructions map; tool names are deduped and a
// server with no disabled tools drops its entry entirely (absent = enabled).
function normalizeDisabledToolsByServerId(
	raw: Readonly<Record<string, readonly string[]>>,
): Record<string, string[]> {
	const normalized: Record<string, string[]> = {};
	for (const [serverId, toolNames] of Object.entries(raw)) {
		if (!/^[1-9]\d*$/.test(serverId)) continue;
		const deduped = [...new Set(toolNames.filter((name) => name.length > 0))];
		if (deduped.length === 0) continue;
		normalized[serverId] = deduped;
	}
	return normalized;
}

type SeenRecordFields = Pick<SandSettingsV1, "hasSeenOnboarding" | "hasSeenOnboardingAccountScope">;

function scopeSeenRecord(settings: SandSettingsV1, accountScope: string): SeenRecordFields {
	if (settings.hasSeenOnboarding === undefined) return {};
	const owner = settings.hasSeenOnboardingAccountScope;
	if (owner !== undefined && owner !== accountScope) return {};
	return {
		hasSeenOnboarding: settings.hasSeenOnboarding,
		hasSeenOnboardingAccountScope: accountScope,
	};
}

function withoutSeenRecord(settings: SandSettingsV1): Omit<SandSettingsV1, keyof SeenRecordFields> {
	const { hasSeenOnboarding: _seen, hasSeenOnboardingAccountScope: _owner, ...rest } = settings;
	return rest;
}

interface StorableSectionsArgs {
	readonly sections: readonly SidebarSectionUpdate[];
	readonly stored?: readonly StoredSidebarSection[];
}

/**
 * Small atomic JSON store for Sand app-level settings, mirroring
 * `BrowserStateStore`; the versioned schema absorbs new fields without a
 * migration dance.
 */
export class SandSettingsStore {
	constructor(private readonly settingsPath: string) {}

	load(): SandSettingsV1 {
		if (!existsSync(this.settingsPath)) {
			return emptySettings();
		}
		try {
			const parsed = settingsSchema.safeParse(JSON.parse(readFileSync(this.settingsPath, "utf-8")));
			if (parsed.success) {
				const loaded: SandSettingsV1 = {
					version: SETTINGS_VERSION,
					mcpBoxServers: [...new Set(parsed.data.mcpBoxServers)],
					...(parsed.data.hasSeenOnboarding !== undefined
						? { hasSeenOnboarding: parsed.data.hasSeenOnboarding }
						: {}),
					...(parsed.data.hasSeenOnboardingAccountScope !== undefined
						? { hasSeenOnboardingAccountScope: parsed.data.hasSeenOnboardingAccountScope }
						: {}),
					autoUpdateWhenIdleOptIn: parsed.data.autoUpdateWhenIdleOptIn,
					egressTunnelEnabled: parsed.data.egressTunnelEnabled,
					webauthnProxyEnabled: parsed.data.webauthnProxyEnabled,
					mcpCustomInstructions: normalizeCustomInstructions(parsed.data.mcpCustomInstructions),
					mcpCustomInstructionsByServerId: normalizeCustomInstructionsByServerId(
						parsed.data.mcpCustomInstructionsByServerId,
					),
					mcpDisabledToolsByServerId: normalizeDisabledToolsByServerId(
						parsed.data.mcpDisabledToolsByServerId,
					),
					...(parsed.data.mcpCustomInstructionsAccountScope !== undefined
						? {
								mcpCustomInstructionsAccountScope: parsed.data.mcpCustomInstructionsAccountScope,
							}
						: {}),
					conciergeConsent: parsed.data.conciergeConsent,
					settingsMigrations: parsed.data.settingsMigrations,
					...(parsed.data.updateTrackOverride !== undefined
						? { updateTrackOverride: parsed.data.updateTrackOverride }
						: {}),
					...(parsed.data.themePreference !== undefined
						? { themePreference: parsed.data.themePreference }
						: {}),
					...(parsed.data.agentDefaultModel !== undefined
						? { agentDefaultModel: parsed.data.agentDefaultModel }
						: {}),
					...(parsed.data.computerUseModel !== undefined
						? { computerUseModel: parsed.data.computerUseModel }
						: {}),
					...(parsed.data.notifications !== undefined
						? { notifications: parsed.data.notifications }
						: {}),
					...(parsed.data.userTimeZone !== undefined
						? { userTimeZone: parsed.data.userTimeZone }
						: {}),
					...(parsed.data.userTimeZoneOverride !== undefined
						? { userTimeZoneOverride: parsed.data.userTimeZoneOverride }
						: {}),
					...(parsed.data.autoReviewInstructions !== undefined
						? {
								autoReviewInstructions: (() => {
									const normalized = normalizeSandAutoReviewInstructions(
										parsed.data.autoReviewInstructions,
									);
									return {
										isEnabled: normalized.isEnabled,
										allowInstructions: [...normalized.allowInstructions],
										blockInstructions: [...normalized.blockInstructions],
									};
								})(),
							}
						: {}),
					...(parsed.data.localToolPermission !== undefined
						? { localToolPermission: parsed.data.localToolPermission }
						: {}),
					...(parsed.data.localToolPermissionCeiling !== undefined
						? {
								localToolPermissionCeiling: parsed.data.localToolPermissionCeiling,
							}
						: {}),
					// Preserve the absent/`[]` distinction: only spread the field when
					// it was actually written, so a never-written box stays absent
					// (clients keep local pins) while a stored clear round-trips as `[]`.
					...(parsed.data.pinnedAgentIds !== undefined
						? { pinnedAgentIds: [...new Set(parsed.data.pinnedAgentIds)] }
						: {}),
					...(parsed.data.sidebarSections !== undefined
						? {
								sidebarSections: SandSettingsStore.storable({
									sections: parsed.data.sidebarSections,
								}),
							}
						: {}),
				};
				return this.applyPendingMigrations(loaded);
			}
		} catch {}
		return emptySettings();
	}

	// Runs any not-yet-applied one-time migration on freshly loaded settings.
	private applyPendingMigrations(settings: SandSettingsV1): SandSettingsV1 {
		if (settings.settingsMigrations.includes(SAND_DOWNGRADE_MAX_FAST_MIGRATION_ID)) {
			return settings;
		}
		const migrated: SandSettingsV1 = {
			...settings,
			settingsMigrations: [...settings.settingsMigrations, SAND_DOWNGRADE_MAX_FAST_MIGRATION_ID],
			...(settings.agentDefaultModel !== undefined
				? {
						agentDefaultModel: downgradePersistedFast(settings.agentDefaultModel),
					}
				: {}),
		};
		try {
			this.persist(migrated);
		} catch {}
		return migrated;
	}

	persist(settings: SandSettingsV1): void {
		mkdirSync(dirname(this.settingsPath), { recursive: true });
		const tempPath = `${this.settingsPath}.${process.pid}.tmp`;
		writeFileSync(tempPath, JSON.stringify(settings, null, 2), "utf-8");
		renameSync(tempPath, this.settingsPath);
	}

	getHasSeenOnboarding(): boolean | undefined {
		return this.load().hasSeenOnboarding;
	}

	setHasSeenOnboarding(value: boolean): void {
		const { hasSeenOnboardingAccountScope: _previous, ...rest } = this.load();
		this.persist({
			...rest,
			hasSeenOnboarding: value,
			...(rest.mcpCustomInstructionsAccountScope !== undefined
				? { hasSeenOnboardingAccountScope: rest.mcpCustomInstructionsAccountScope }
				: {}),
		});
	}

	clearHasSeenOnboarding(): void {
		const settings = this.load();
		if (
			settings.hasSeenOnboarding === undefined &&
			settings.hasSeenOnboardingAccountScope === undefined
		) {
			return;
		}
		const {
			hasSeenOnboarding: _seen,
			hasSeenOnboardingAccountScope: _owner,
			...cleared
		} = settings;
		this.persist(cleared);
	}

	getAutoUpdateWhenIdleOptIn(): boolean {
		return this.load().autoUpdateWhenIdleOptIn;
	}

	setAutoUpdateWhenIdleOptIn(value: boolean): void {
		this.persist({ ...this.load(), autoUpdateWhenIdleOptIn: value });
	}

	getThemePreference(): SandThemePreference {
		return this.load().themePreference ?? DEFAULT_SAND_THEME_PREFERENCE;
	}

	setThemePreference(preference: SandThemePreference): void {
		this.persist({ ...this.load(), themePreference: preference });
	}

	getEgressTunnelEnabled(): boolean {
		return this.load().egressTunnelEnabled;
	}

	setEgressTunnelEnabled(value: boolean): void {
		this.persist({ ...this.load(), egressTunnelEnabled: value });
	}

	getWebauthnProxyEnabled(): boolean {
		return this.load().webauthnProxyEnabled;
	}

	setWebauthnProxyEnabled(value: boolean): void {
		this.persist({ ...this.load(), webauthnProxyEnabled: value });
	}

	// The host-owned default model last observed by desktop.
	getAgentDefaultModel(): SandAgentDefaultModel | undefined {
		const model = this.load().agentDefaultModel;
		return model === undefined ? undefined : { ...model, maxMode: true };
	}

	// Parameters are copied into a fresh mutable array for callers.
	setAgentDefaultModel(model: SandAgentDefaultModel | undefined): void {
		const { agentDefaultModel: _previous, ...rest } = this.load();
		this.persist(
			model === undefined
				? rest
				: {
						...rest,
						agentDefaultModel: {
							modelId: model.modelId,
							maxMode: true,
							parameters: model.parameters.map((p) => ({ id: p.id, value: p.value })),
						},
					},
		);
	}

	// The user's chosen computer-use model, or undefined when never set. The
	// inference port then falls back to SAND_COMPUTER_USE_SUBAGENT_MODEL_ID.
	getComputerUseModel(): SandComputerUseModel | undefined {
		return this.load().computerUseModel;
	}

	// Read-modify-write so unrelated settings survive. Undefined clears the
	// selection back to the dedicated fallback. Otherwise preserve the shared
	// picker's complete selection, matching setAgentDefaultModel.
	setComputerUseModel(model: SandComputerUseModel | undefined): void {
		const { computerUseModel: _previous, ...rest } = this.load();
		this.persist(
			model === undefined
				? rest
				: {
						...rest,
						computerUseModel: {
							modelId: model.modelId,
							maxMode: model.maxMode,
							parameters: model.parameters.map((p) => ({
								id: p.id,
								value: p.value,
							})),
						},
					},
		);
	}

	getUpdateTrackOverride(): SandUpdateTrack | null {
		const stored = this.load().updateTrackOverride ?? null;
		if (stored == null) {
			return null;
		}
		// TEMPORARY (beta-period disable): migrate anyone persisted on the
		// disabled Nightly track back to Stable and rewrite the stored value, so
		// they aren't re-read onto a track that no longer publishes. Remove this
		// coercion (it becomes a no-op) when Nightly is re-enabled — see
		// NIGHTLY_UPDATE_TRACK_DISABLED in update/update-track.ts.
		const coerced = coerceToEnabledTrack(stored);
		if (coerced !== stored) {
			// Best-effort correction (like applyPendingMigrations): if the rewrite
			// fails, still return the coerced value so update checks aren't blocked;
			// the coercion is idempotent and retries on the next read.
			try {
				this.setUpdateTrackOverride(coerced);
			} catch {
				// Persistence is best-effort; swallow so a bad write never strands the
				// reader on the disabled track.
			}
		}
		return coerced;
	}

	setUpdateTrackOverride(track: SandUpdateTrack | null): void {
		const { updateTrackOverride: _previous, ...rest } = this.load();
		this.persist(track == null ? rest : { ...rest, updateTrackOverride: track });
	}

	getMcpCustomInstructions(): Readonly<Record<string, string>> {
		return this.load().mcpCustomInstructions;
	}

	// Replace the whole custom-instructions map (normalized: over-length values
	// clamped, blanks dropped). Read-modify-write so unrelated fields survive.
	// Used by the in-box settings sync; per-server edits use
	// setMcpCustomInstruction.
	setMcpCustomInstructions(map: Readonly<Record<string, string>>): void {
		this.persist({
			...this.load(),
			mcpCustomInstructions: normalizeCustomInstructions(map),
		});
	}

	getMcpCustomInstructionsByServerId(): Readonly<Record<string, string>> {
		return this.load().mcpCustomInstructionsByServerId;
	}

	getMcpCustomInstructionsAccountScope(): string | undefined {
		return this.load().mcpCustomInstructionsAccountScope;
	}

	scopeToAccount(accountScope: string): void {
		const current = this.load();
		const seenRecord = scopeSeenRecord(current, accountScope);
		if (current.mcpCustomInstructionsAccountScope === accountScope) {
			if (current.hasSeenOnboardingAccountScope !== seenRecord.hasSeenOnboardingAccountScope) {
				this.persist({ ...withoutSeenRecord(current), ...seenRecord });
			}
			return;
		}
		if (current.mcpCustomInstructionsAccountScope === undefined) {
			this.persist({
				...withoutSeenRecord(current),
				...seenRecord,
				mcpCustomInstructionsAccountScope: accountScope,
			});
			return;
		}
		const {
			autoReviewInstructions: _autoReviewInstructions,
			agentDefaultModel: _agentDefaultModel,
			computerUseModel: _computerUseModel,
			localToolPermission: _localToolPermission,
			localToolPermissionCeiling: _localToolPermissionCeiling,
			...settings
		} = withoutSeenRecord(current);
		this.persist({
			...settings,
			...seenRecord,
			mcpCustomInstructionsAccountScope: accountScope,
			mcpCustomInstructions: {},
			mcpCustomInstructionsByServerId: {},
			mcpDisabledToolsByServerId: {},
		});
	}

	clearAccountScope(): void {
		const {
			mcpCustomInstructionsAccountScope: _accountScope,
			autoReviewInstructions: _autoReviewInstructions,
			agentDefaultModel: _agentDefaultModel,
			computerUseModel: _computerUseModel,
			localToolPermission: _localToolPermission,
			localToolPermissionCeiling: _localToolPermissionCeiling,
			...settings
		} = this.load();
		this.persist({
			...settings,
			mcpCustomInstructions: {},
			mcpCustomInstructionsByServerId: {},
			mcpDisabledToolsByServerId: {},
		});
	}

	setMcpCustomInstructionsByServerId(map: Readonly<Record<string, string>>): void {
		this.persist({
			...this.load(),
			mcpCustomInstructionsByServerId: normalizeCustomInstructionsByServerId(map),
		});
	}

	getMcpDisabledToolsByServerId(): Readonly<Record<string, readonly string[]>> {
		return this.load().mcpDisabledToolsByServerId;
	}

	// Replace the whole disabled-tools map (normalized). Read-modify-write so
	// unrelated fields survive. Used by the in-box settings sync and the
	// reconcile merge; per-tool edits use setMcpToolDisabled.
	setMcpDisabledToolsByServerId(map: Readonly<Record<string, readonly string[]>>): void {
		this.persist({
			...this.load(),
			mcpDisabledToolsByServerId: normalizeDisabledToolsByServerId(map),
		});
	}

	// The EFFECTIVE user timezone every consumer (system prompt, cron
	// scheduling, wake-prompt formatting) reads: the explicit override when the
	// user has set one, else the desktop-detected zone, else undefined (the host
	// then falls back to its own box-local clock). This is the one precedence
	// seam — detection fills the value when the user never chose, and a manual
	// choice always wins.
	getUserTimeZone(): string | undefined {
		const settings = this.load();
		return settings.userTimeZoneOverride ?? settings.userTimeZone;
	}

	// The raw auto-detected zone (no override applied), for surfaces that show
	// detection and choice side by side.
	getDetectedUserTimeZone(): string | undefined {
		return this.load().userTimeZone;
	}

	// The raw explicit choice, or undefined when the user follows auto-detection.
	getUserTimeZoneOverride(): string | undefined {
		return this.load().userTimeZoneOverride;
	}

	// Writes the DETECTED zone only — never the override, so a detection refresh
	// (every desktop reconnect) can never clobber an explicit user choice.
	// Read-modify-write so unrelated fields survive. A blank value clears it so a
	// stale timezone never lingers once the desktop stops reporting one.
	setUserTimeZone(timeZone: string | undefined): void {
		const { userTimeZone: _previous, ...rest } = this.load();
		const trimmed = timeZone?.trim();
		this.persist(trimmed != null && trimmed.length > 0 ? { ...rest, userTimeZone: trimmed } : rest);
	}

	// Writes the user's explicit choice. A blank/undefined value clears it, which
	// returns the user to auto-detection (never to a frozen copy of a detected
	// zone). Read-modify-write so unrelated fields survive.
	setUserTimeZoneOverride(timeZone: string | undefined): void {
		const { userTimeZoneOverride: _previous, ...rest } = this.load();
		const trimmed = timeZone?.trim();
		this.persist(
			trimmed != null && trimmed.length > 0 ? { ...rest, userTimeZoneOverride: trimmed } : rest,
		);
	}

	getMcpBoxServers(): readonly string[] {
		return this.load().mcpBoxServers;
	}

	// Replace the set of MCP servers that run in the box (deduped). Read-modify-
	// write so unrelated fields survive. Mirrors how mcp-manager persists it.
	setMcpBoxServers(names: readonly string[]): void {
		this.persist({
			...this.load(),
			mcpBoxServers: [...new Set(names)],
		});
	}

	// The raw stored value for a connector, or `undefined` when the user has
	// never set one. Callers resolve it through `resolveMcpCustomInstruction`,
	// which turns `undefined` into the built-in default (the seed) and treats any
	// string (including "" the user cleared it to) as authoritative. The
	// `undefined` vs "" distinction is what keeps a cleared default from
	// resurrecting, so it must not be collapsed to "".
	getRawMcpCustomInstruction(name: string): string | undefined {
		return this.load().mcpCustomInstructions[name];
	}

	getRawMcpCustomInstructionByServerId(serverId: string): string | undefined {
		return this.load().mcpCustomInstructionsByServerId[serverId];
	}

	setMcpCustomInstructionByServerId(args: {
		serverId: string;
		displayName: string;
		value: string;
		mirrorLegacyName: boolean;
	}): void {
		const { serverId, displayName, value, mirrorLegacyName } = args;
		const current = this.load();
		const byServerId = { ...current.mcpCustomInstructionsByServerId };
		byServerId[serverId] = clampMcpCustomInstruction(value);
		const legacy = { ...current.mcpCustomInstructions };
		if (mirrorLegacyName) {
			const clamped = clampMcpCustomInstruction(value);
			if (clamped.trim().length > 0 || getDefaultMcpCustomInstruction(displayName).length > 0) {
				legacy[displayName] = clamped;
			} else {
				delete legacy[displayName];
			}
		} else {
			delete legacy[displayName];
		}
		this.persist({
			...current,
			mcpCustomInstructionsByServerId: byServerId,
			mcpCustomInstructions: legacy,
		});
	}

	migrateMcpCustomInstructionToServerId(args: { serverId: string; displayName: string }): void {
		const { serverId, displayName } = args;
		const current = this.load();
		if (current.mcpCustomInstructionsByServerId[serverId] !== undefined) return;
		const legacy = current.mcpCustomInstructions[displayName];
		if (legacy === undefined) return;
		this.persist({
			...current,
			mcpCustomInstructionsByServerId: {
				...current.mcpCustomInstructionsByServerId,
				[serverId]: legacy,
			},
		});
	}

	deleteMcpCustomInstructionByServerId(args: {
		serverId: string;
		displayName: string;
		deleteLegacyName: boolean;
	}): void {
		const { serverId, displayName, deleteLegacyName } = args;
		const current = this.load();
		const byServerId = { ...current.mcpCustomInstructionsByServerId };
		delete byServerId[serverId];
		const legacy = { ...current.mcpCustomInstructions };
		if (deleteLegacyName) {
			delete legacy[displayName];
		}
		this.persist({
			...current,
			mcpCustomInstructionsByServerId: byServerId,
			mcpCustomInstructions: legacy,
		});
	}

	// Read-modify-write so unrelated fields (box servers, onboarding) survive.
	// A non-empty value is stored as-is. An empty/whitespace-only value means the
	// user cleared the field: for a connector with a built-in default we store ""
	// (the "cleared" sentinel) so the default does not seed back in; for a
	// connector with no default there is nothing to suppress, so the entry is
	// removed entirely.
	setMcpCustomInstruction(name: string, value: string): void {
		const current = this.load();
		const next = { ...current.mcpCustomInstructions };
		const clamped = clampMcpCustomInstruction(value);
		if (clamped.trim().length === 0) {
			if (getDefaultMcpCustomInstruction(name).length > 0) {
				next[name] = "";
			} else {
				delete next[name];
			}
		} else {
			next[name] = clamped;
		}
		this.persist({ ...current, mcpCustomInstructions: next });
	}

	getNotificationConfig(): SandNotificationConfig {
		const current = this.load();
		if (
			current.notifications?.isEnabled !== false ||
			Object.keys(current.notifications).length !== 1
		) {
			this.persist({ ...current, notifications: { isEnabled: false } });
		}
		return SAND_DISABLED_NOTIFICATION_CONFIG;
	}

	setNotificationConfig(_input: SandNotificationConfigInput): void {
		this.persist({
			...this.load(),
			notifications: { isEnabled: false },
		});
	}

	// Forget a connector's custom instruction entirely (removes the key, including
	// any "cleared" sentinel). Used on uninstall so a later reinstall with the
	// same name starts fresh — seeded again with the built-in default rather than
	// inheriting a stale value or a stuck "cleared" state.
	deleteMcpCustomInstruction(name: string): void {
		const current = this.load();
		if (!(name in current.mcpCustomInstructions)) return;
		const next = { ...current.mcpCustomInstructions };
		delete next[name];
		this.persist({ ...current, mcpCustomInstructions: next });
	}

	getAutoReviewInstructions(): SandAutoReviewInstructions {
		return this.load().autoReviewInstructions ?? DEFAULT_SAND_AUTO_REVIEW_INSTRUCTIONS;
	}

	setAutoReviewInstructions(instructions: SandAutoReviewInstructions): void {
		const normalized = normalizeSandAutoReviewInstructions(instructions);
		const { autoReviewInstructions: _previous, ...rest } = this.load();
		// Absent reads back as the default (enabled, no rules), so drop the key
		// only when that is exactly what the user chose. Auto-review turned off is
		// a real choice and must persist even with no rules.
		if (
			normalized.isEnabled &&
			normalized.allowInstructions.length === 0 &&
			normalized.blockInstructions.length === 0
		) {
			this.persist(rest);
			return;
		}
		this.persist({
			...rest,
			autoReviewInstructions: {
				isEnabled: normalized.isEnabled,
				allowInstructions: [...normalized.allowInstructions],
				blockInstructions: [...normalized.blockInstructions],
			},
		});
	}

	/**
	 * The permission actually in force: the member's own choice narrowed by their
	 * team admin's ceiling. THE accessor every enforcement path reads — the
	 * local-exec daemon on this machine, the mirror pushed to the in-box host,
	 * and the renderer — so the ceiling applies everywhere without each of them
	 * having to know an admin policy exists.
	 */
	getLocalToolPermission(): SandLocalToolPermission {
		const settings = this.load();
		return resolveSandLocalToolPermission(
			settings.localToolPermission ?? SAND_DEFAULT_LOCAL_TOOL_PERMISSION,
			settings.localToolPermissionCeiling,
		);
	}

	/**
	 * What the member themselves picked, before any ceiling. Only Settings wants
	 * this: it shows their choice and says separately that an admin is holding
	 * it, rather than silently rewriting the picker under them.
	 */
	getLocalToolPermissionChoice(): SandLocalToolPermission {
		return this.load().localToolPermission ?? SAND_DEFAULT_LOCAL_TOOL_PERMISSION;
	}

	/** The team admin's ceiling, or undefined when the team states no policy. */
	getLocalToolPermissionCeiling(): SandLocalToolPermission | undefined {
		return this.load().localToolPermissionCeiling;
	}

	setLocalToolPermission(permission: SandLocalToolPermission): void {
		this.persist({ ...this.load(), localToolPermission: permission });
	}

	/**
	 * Mirrors the team's ceiling after a backend read. Undefined clears it, so a
	 * member whose team drops the policy (or who leaves the team) gets their own
	 * choice back rather than staying held by a stale one.
	 */
	setLocalToolPermissionCeiling(ceiling: SandLocalToolPermission | undefined): void {
		const { localToolPermissionCeiling: _dropped, ...rest } = this.load();
		this.persist(ceiling === undefined ? rest : { ...rest, localToolPermissionCeiling: ceiling });
	}

	/**
	 * The stored pinned-agent list, or `undefined` when never written. A returned
	 * `[]` is an intentional clear, NOT never-written — callers must keep the two
	 * apart.
	 */
	getPinnedAgentIds(): readonly string[] | undefined {
		return this.load().pinnedAgentIds;
	}

	// Read-modify-write so unrelated fields survive. Stores the list verbatim
	// (deduped, order preserved) — INCLUDING `[]`, so an intentional clear
	// persists as a written empty list rather than reverting to never-written.
	setPinnedAgentIds(ids: readonly string[]): void {
		this.persist({ ...this.load(), pinnedAgentIds: [...new Set(ids)] });
	}

	private static storable({ sections, stored }: StorableSectionsArgs): {
		id: string;
		name: string;
		agentIds: string[];
		isCollapsed: boolean;
	}[] {
		return SidebarSections.carryFolds({ sections, stored }).map((section) => ({
			id: section.id,
			name: section.name,
			agentIds: [...section.agentIds],
			isCollapsed: section.isCollapsed,
		}));
	}

	getSidebarSections(): readonly StoredSidebarSection[] | undefined {
		const stored = this.load().sidebarSections;
		return stored === undefined ? undefined : SidebarSections.carryFolds({ sections: stored });
	}

	setSidebarSections(sections: readonly SidebarSectionUpdate[]): void {
		const current = this.load();
		this.persist({
			...current,
			sidebarSections: SandSettingsStore.storable({
				sections,
				stored: current.sidebarSections,
			}),
		});
	}
}
