import { SimpleControlledExecHandler } from "./controlled.js";
import { ExecutorResource } from "./remote.js";
import { createResource } from "./resource-provider.js";
import { createClientDeserializer, createClientSerializer, createServerDeserializer, createServerSerializer, } from "./serialization.js";
export { ShellAllowlistPrecheckArgs, ShellAllowlistPrecheckResult, } from "@anysphere/proto/agent/v1/shell_allowlist_precheck_exec_pb.js";
export const shellAllowlistPrecheckExecutorResource = createResource(execManager => new ExecutorResource(execManager, createServerSerializer("shellAllowlistPrecheckArgs"), createClientDeserializer("shellAllowlistPrecheckResult")), (implementation, controlledExecManager) => {
    controlledExecManager.register(new SimpleControlledExecHandler(implementation, createServerDeserializer("shellAllowlistPrecheckArgs"), createClientSerializer("shellAllowlistPrecheckResult")));
});
