import type { Stats } from "node:fs";
import { stat } from "node:fs/promises";
import { basename, dirname, extname, resolve } from "node:path";
import type { LsExecutor } from "@anysphere/agent-exec";
import { type Context, createSpan } from "@anysphere/context";
import {
  type LsArgs,
  LsDirectoryTreeNode,
  LsDirectoryTreeNode_File,
  LsError,
  LsResult,
  LsSuccess,
  LsTimeout,
} from "@anysphere/proto/agent/v1/ls_exec_pb.js";
import type { SandboxPolicy } from "@anysphere/shell-exec";
import { isCursorTerminalsDirectory } from "@anysphere/utils";
import { resolvePath } from "./common.js";
import { clampInt32 } from "./int32.js";
import { ripwalk } from "./ripgrep-stream.js";
import { convertProtoToInternalPolicy } from "./sandbox-conversion.js";
import {
  type IgnoreService,
  resolvePathForIgnoreService,
} from "./services/ignore-service.js";
import type { PermissionsService } from "./services/permissions-service.js";

const DEFAULT_CHARACTER_BUDGET = 2_500;
const DEFAULT_TIMEOUT_MS = 5_000;

export class LocalLsExecutor implements LsExecutor {
  constructor(
    private readonly permissionsService: PermissionsService,
    private readonly ignoreService: IgnoreService,
    private readonly workspacePath?: string
  ) {}

  async execute(parentCtx: Context, args: LsArgs): Promise<LsResult> {
    using span = createSpan(parentCtx.withName("LocalLsExecutor.execute"));
    const ctx = span.ctx;
    const resolvedPath = resolvePath(args.path, this.workspacePath);

    try {
      // Check if path exists and is a directory
      let pathStats: Stats;
      try {
        pathStats = await stat(resolvedPath);
      } catch (error) {
        if ((error as NodeJS.ErrnoException).code === "ENOENT") {
          // Check if this is a terminals directory that doesn't exist yet
          // (terminals directory is created on-demand when the first shell is started)
          if (isCursorTerminalsDirectory(resolvedPath)) {
            return new LsResult({
              result: {
                case: "error",
                value: new LsError({
                  path: resolvedPath,
                  error: `No active terminals.`,
                }),
              },
            });
          }

          return new LsResult({
            result: {
              case: "error",
              value: new LsError({
                path: resolvedPath,
                error: `Path does not exist: ${resolvedPath}`,
              }),
            },
          });
        }

        return new LsResult({
          result: {
            case: "error",
            value: new LsError({
              path: resolvedPath,
              error: (error as Error).message,
            }),
          },
        });
      }

      if (!pathStats.isDirectory()) {
        return new LsResult({
          result: {
            case: "error",
            value: new LsError({
              path: resolvedPath,
              error: `Path is not a directory: ${resolvedPath}`,
            }),
          },
        });
      }

      const sandboxPolicy = convertProtoToInternalPolicy(args.sandboxPolicy);

      const timeoutMs = args.timeoutMs ?? DEFAULT_TIMEOUT_MS;

      const ctx = parentCtx.withTimeout(timeoutMs);

      const { tree, didTimeout } = await this.getDirectoryTree(
        ctx,
        resolvedPath,
        args.ignore,
        sandboxPolicy
      );

      if (didTimeout) {
        return new LsResult({
          result: {
            case: "timeout",
            value: new LsTimeout({
              directoryTreeRoot: tree,
            }),
          },
        });
      }

      return new LsResult({
        result: {
          case: "success",
          value: new LsSuccess({
            directoryTreeRoot: tree,
          }),
        },
      });
    } catch (error) {
      return new LsResult({
        result: {
          case: "error",
          value: new LsError({
            path: resolvedPath,
            error:
              error instanceof Error ? error.message : "Unknown error occurred",
          }),
        },
      });
    }
  }

  private async getDirectoryTree(
    parentCtx: Context,
    directoryPath: string,
    ignoreGlobs: readonly string[],
    sandboxPolicy: SandboxPolicy
  ): Promise<{ tree: LsDirectoryTreeNode; didTimeout: boolean }> {
    using _span = createSpan(
      parentCtx.withName("LocalLsExecutor.getDirectoryTree")
    );

    // Build tree by streaming file paths from ripgrep
    // Terminal metadata promises are set during streaming, awaited at end
    return await this.buildTreeFromRipgrepStream(
      parentCtx,
      directoryPath,
      ignoreGlobs,
      sandboxPolicy,
      DEFAULT_CHARACTER_BUDGET
    );
  }

  /**
   * Build directory tree by streaming paths from ripgrep.
   * Process lines as they arrive - no buffering entire output.
   */
  private async buildTreeFromRipgrepStream(
    ctx: Context,
    directoryPath: string,
    ignoreGlobs: readonly string[],
    sandboxPolicy: SandboxPolicy,
    characterBudget: number
  ): Promise<{ tree: LsDirectoryTreeNode; didTimeout: boolean }> {
    using _span = createSpan(
      ctx.withName("LocalLsExecutor.buildTreeFromRipgrepStream")
    );

    const normalizedRoot = resolve(directoryPath);

    // Initialize tree structure
    const rootNode = new LsDirectoryTreeNode({
      absPath: normalizedRoot,
      childrenDirs: [],
      childrenFiles: [],
      childrenWereProcessed: true,
      fullSubtreeExtensionCounts: {},
    });

    const dirNodes = new Map<string, LsDirectoryTreeNode>();
    dirNodes.set(normalizedRoot, rootNode);

    // Mutable state for tracking budget
    const state = {
      charactersUsed: normalizedRoot.length,
      budgetExceeded: false,
    };

    // Get cursor ignore files and repo block exclude globs in parallel
    const [cursorIgnoreFiles, repoBlockExcludeGlobs] = await Promise.all([
      this.ignoreService.listCursorIgnoreFilesByRoot(directoryPath),
      this.ignoreService.getRepoBlockExcludeGlobs(directoryPath),
    ]);

    // Combine user-provided ignore globs with repo block globs
    const allExcludeGlobs = [...ignoreGlobs, ...repoBlockExcludeGlobs];

    // Stream files from ripgrep (auto-handles abort, exit codes, stderr)
    const { lines, didTimeout } = ripwalk(ctx, {
      root: directoryPath,
      excludeGlobs: allExcludeGlobs,
      caseSensitive: true,
      cursorIgnoreFiles,
      sandboxPolicy,
      source: "ls",
    });

    for await (const line of lines) {
      if (!line) continue;

      const filePath = resolve(directoryPath, line);

      // Filter out files blocked by admin repo rules (OAL parity)
      // This handles the fallback case when git info is unavailable
      const resolvedForIgnore = await resolvePathForIgnoreService(filePath);
      if (
        resolvedForIgnore === null ||
        (await this.ignoreService.isRepoBlocked(resolvedForIgnore))
      ) {
        continue;
      }

      // Process this file path into tree
      this.addPathToTree(
        filePath,
        normalizedRoot,
        dirNodes,
        state,
        characterBudget
      );
    }

    // Sort tree children for consistent output
    this.sortTreeChildren(rootNode);

    return { tree: rootNode, didTimeout: await didTimeout };
  }

  /**
   * Add a single file path to the tree structure.
   * Called for each line streamed from ripgrep.
   */
  private addPathToTree(
    filePath: string,
    normalizedRoot: string,
    dirNodes: Map<string, LsDirectoryTreeNode>,
    state: { charactersUsed: number; budgetExceeded: boolean },
    characterBudget: number
  ): void {
    const fileName = basename(filePath);
    const dirPath = dirname(filePath);

    // Ensure all ancestor directories exist
    this.ensureDirectoryPath(
      dirPath,
      normalizedRoot,
      dirNodes,
      state.budgetExceeded
    );

    const parentNode = dirNodes.get(dirPath);
    if (!parentNode) return;

    // Check character budget
    const fileCharCost = fileName.length;
    if (
      !state.budgetExceeded &&
      state.charactersUsed + fileCharCost <= characterBudget
    ) {
      const fileNode = new LsDirectoryTreeNode_File({
        name: fileName,
      });
      parentNode.childrenFiles.push(fileNode);
      state.charactersUsed += fileCharCost;
    } else {
      // Budget exceeded - first time, mark all ancestors as incomplete
      if (!state.budgetExceeded) {
        state.budgetExceeded = true;
        // Mark all ancestor directories as incomplete since we won't process all their files
        let currentDir = dirPath;
        while (currentDir.startsWith(normalizedRoot)) {
          const node = dirNodes.get(currentDir);
          if (node) {
            node.childrenWereProcessed = false;
          }
          const parentDir = dirname(currentDir);
          if (parentDir === currentDir) break;
          currentDir = parentDir;
        }
      }

      // Track extension counts for this file in all ancestors
      const extension = extname(filePath);
      let currentDir = dirPath;
      while (currentDir.startsWith(normalizedRoot)) {
        const node = dirNodes.get(currentDir);
        if (node) {
          node.fullSubtreeExtensionCounts[extension] ??= 0;
          node.fullSubtreeExtensionCounts[extension] = clampInt32(
            node.fullSubtreeExtensionCounts[extension] + 1
          );
          node.numFiles ??= 0;
          node.numFiles = clampInt32(node.numFiles + 1);
        }
        const parentDir = dirname(currentDir);
        if (parentDir === currentDir) break;
        currentDir = parentDir;
      }
    }
  }

  /**
   * Ensure directory path exists in tree, creating intermediate nodes as needed.
   */
  private ensureDirectoryPath(
    dirPath: string,
    rootPath: string,
    dirNodes: Map<string, LsDirectoryTreeNode>,
    budgetExceeded: boolean
  ): void {
    if (dirNodes.has(dirPath) || dirPath === rootPath) {
      return; // Already exists or is root
    }

    // Ensure parent exists first
    const parentPath = dirname(dirPath);
    if (parentPath !== dirPath && parentPath.startsWith(rootPath)) {
      this.ensureDirectoryPath(parentPath, rootPath, dirNodes, budgetExceeded);
    }

    // Create this directory node
    const dirNode = new LsDirectoryTreeNode({
      absPath: dirPath,
      childrenDirs: [],
      childrenFiles: [],
      childrenWereProcessed: !budgetExceeded,
      fullSubtreeExtensionCounts: {},
    });
    dirNodes.set(dirPath, dirNode);

    // Add to parent's children
    const parentNode = dirNodes.get(parentPath);
    if (parentNode) {
      parentNode.childrenDirs.push(dirNode);
    }
  }

  /**
   * Recursively sort children directories and files by name.
   */
  private sortTreeChildren(node: LsDirectoryTreeNode): void {
    node.childrenDirs.sort((a, b) =>
      basename(a.absPath).localeCompare(basename(b.absPath))
    );

    node.childrenFiles.sort((a, b) => a.name.localeCompare(b.name));

    // Recurse into child directories
    for (const childDir of node.childrenDirs) {
      this.sortTreeChildren(childDir);
    }
  }
}
