/** Maximum stored length of one connector instruction. */
export const MCP_CUSTOM_INSTRUCTIONS_MAX_LENGTH = 500;

export interface McpCustomInstructionEntry {
	readonly name: string;
	readonly instructions: string;
}

// Clamps a raw value to the max length. The UI also clamps on input; persistence
// clamps again as the authoritative guard against hand-edited settings files.
export function clampMcpCustomInstruction(raw: string): string {
	return raw.length > MCP_CUSTOM_INSTRUCTIONS_MAX_LENGTH
		? raw.slice(0, MCP_CUSTOM_INSTRUCTIONS_MAX_LENGTH)
		: raw;
}

const DEFAULT_MCP_CONNECTOR_INSTRUCTIONS: ReadonlyMap<string, string> = new Map([
	[
		"hex",
		"When using Hex, get the underlying numbers as data: download/export the results as CSV or use the data the connector returns, and analyze those raw values directly. Don't read rendered charts or graphs from screenshots (computer-use chart reading is unreliable) — work from the actual data.",
	],
]);

/** Returns the case-insensitive built-in seed for a connector, or an empty string. */
export function getDefaultMcpCustomInstruction(serverName: string): string {
	return DEFAULT_MCP_CONNECTOR_INSTRUCTIONS.get(serverName.trim().toLowerCase()) ?? "";
}

/**
 * Resolves an unset value to the built-in seed. An explicit empty string
 * suppresses the seed.
 */
export function resolveMcpCustomInstruction(
	serverName: string,
	storedInstruction: string | undefined,
): string {
	if (storedInstruction === undefined) {
		return getDefaultMcpCustomInstruction(serverName);
	}
	return storedInstruction.trim();
}

// The preamble prepended to a connector's tool result so the agent sees its
// custom instructions at use time, even on the very first call to that tool.
export function formatMcpCustomInstructionToolNote(
	serverName: string,
	instructions: string,
): string {
	return `Custom instructions for the "${serverName}" connector (always follow them when using this tool):\n${instructions.trim()}`;
}

/** Returns connected connectors with effective instructions in alphabetical order. */
export function selectConnectedMcpCustomInstructions(
	connectedServerNames: Iterable<string>,
	instructionsByServer: ReadonlyMap<string, string>,
): readonly McpCustomInstructionEntry[] {
	const entries: McpCustomInstructionEntry[] = [];
	for (const name of new Set(connectedServerNames)) {
		const instructions = resolveMcpCustomInstruction(name, instructionsByServer.get(name));
		if (instructions.length > 0) {
			entries.push({ name, instructions });
		}
	}
	return entries.sort((a, b) => a.name.localeCompare(b.name));
}

/** Returns the connector-instructions prompt section, or null when none apply. */
export function buildMcpCustomInstructionsSystemPromptSection(
	connectedServerNames: Iterable<string>,
	instructionsByServer: ReadonlyMap<string, string>,
): string | null {
	const entries = selectConnectedMcpCustomInstructions(connectedServerNames, instructionsByServer);
	if (entries.length === 0) return null;
	return [
		"## Connector custom instructions",
		"Custom instructions are configured for some connected tools (MCP connectors). Always follow the matching instruction whenever you use that connector's tools, even before your first call to it:",
		...entries.map((entry) => `- ${entry.name}: ${entry.instructions}`),
	].join("\n");
}
