import { normalizeMcpServerUrl } from "../transport/mcp-url-utils.js";

export {
  accountMcpServerIdentifier,
  dashboardAccountMcpServerIdentifier,
} from "./account-mcp-identifier.js";

export type McpConfigServerSourceKind =
  | "user"
  | "project"
  | "extension"
  | "team"
  | "plugin"
  | "default"
  | "provider";

export interface McpConfigServerInput {
  identifier: string;
  name: string;
  type: "streamableHttp" | "stdio";
  url?: string;
  userManaged?: boolean;
  projectManaged?: boolean;
  projectPath?: string;
  extensionId?: string;
  pluginManaged?: boolean;
  pluginId?: string;
  dashboardManaged?: boolean;
  teamId?: number;
}

export interface MCPConfigServiceInput<TServer extends McpConfigServerInput> {
  servers: readonly TServer[];
  disabledServerIdentifiers?: ReadonlySet<string> | readonly string[];
}

export interface MCPSelectionPreferenceStore {
  getSelection(groupId: string): readonly string[] | undefined;
  setSelection(selection: MCPServerSelection): void;
  deleteSelection?(groupId: string): void;
}

export interface MCPServerSelection {
  groupId: string;
  serverIdentifiers: readonly string[];
}

export interface MCPConfigServiceOptions {
  preferenceStore: MCPSelectionPreferenceStore;
}

export const MCP_GROUP_SELECTION_SETTINGS_KEY = "mcpServerGroupSelections";

export type MCPGroupSelectionPreferences = Record<string, readonly string[]>;

export interface MCPGroupSelectionPreferenceStoreOptions {
  getPreferences: () => MCPGroupSelectionPreferences;
  setPreferences: (preferences: MCPGroupSelectionPreferences) => void;
}

export interface MCPConfigGroup<TServer extends McpConfigServerInput> {
  groupId: string;
  sourceKind: McpConfigServerSourceKind;
  normalizedUrl?: string;
  servers: readonly TServer[];
  selectedServers: readonly TServer[];
  selectedServerIdentifiers: readonly string[];
  isGrouped: boolean;
}

export interface MCPConfigServiceSnapshot<
  TServer extends McpConfigServerInput,
> {
  groups: readonly MCPConfigGroup<TServer>[];
  effectiveServers: readonly TServer[];
}

export interface IMCPConfigService<TServer extends McpConfigServerInput> {
  updateServers(
    input: MCPConfigServiceInput<TServer>
  ): MCPConfigServiceSnapshot<TServer>;
  getEffectiveServers(): readonly TServer[];
  getFullMCPServerState(): readonly MCPConfigGroup<TServer>[];
  setMCPSelection(selection: MCPServerSelection): void;
  getGroupedServerIdentifiers(serverIdentifier: string): readonly string[];
}

export function sanitizeMcpGroupSelectionPreferences(
  rawPreferences: unknown
): MCPGroupSelectionPreferences {
  if (!isRecord(rawPreferences)) {
    return {};
  }
  const preferences: MCPGroupSelectionPreferences = {};
  for (const [groupId, serverIdentifiers] of Object.entries(rawPreferences)) {
    if (
      typeof groupId === "string" &&
      Array.isArray(serverIdentifiers) &&
      serverIdentifiers.every(identifier => typeof identifier === "string")
    ) {
      preferences[groupId] = uniqueIdentifiers(serverIdentifiers);
    }
  }
  return preferences;
}

export function createMcpGroupSelectionPreferenceStore({
  getPreferences,
  setPreferences,
}: MCPGroupSelectionPreferenceStoreOptions): MCPSelectionPreferenceStore {
  return {
    getSelection: groupId => getPreferences()[groupId],
    setSelection: ({ groupId, serverIdentifiers }) => {
      setPreferences({
        ...getPreferences(),
        [groupId]: uniqueIdentifiers(serverIdentifiers),
      });
    },
    deleteSelection: groupId => {
      const preferences = getPreferences();
      if (preferences[groupId] === undefined) {
        return;
      }
      const nextPreferences = { ...preferences };
      delete nextPreferences[groupId];
      setPreferences(nextPreferences);
    },
  };
}

const SOURCE_PRECEDENCE: readonly McpConfigServerSourceKind[] = [
  "user",
  "project",
  "extension",
  "team",
  "plugin",
  "default",
  "provider",
];

export class MCPConfigService<TServer extends McpConfigServerInput>
  implements IMCPConfigService<TServer>
{
  private snapshot: MCPConfigServiceSnapshot<TServer> = {
    groups: [],
    effectiveServers: [],
  };
  private lastInput: MCPConfigServiceInput<TServer> = { servers: [] };
  private readonly preferenceStore: MCPSelectionPreferenceStore;

  constructor(options: MCPConfigServiceOptions) {
    this.preferenceStore = options.preferenceStore;
  }

  updateServers(
    input: MCPConfigServiceInput<TServer>
  ): MCPConfigServiceSnapshot<TServer> {
    this.lastInput = {
      servers: input.servers,
      disabledServerIdentifiers: input.disabledServerIdentifiers,
    };
    this.snapshot = this.computeSnapshot(input);
    return this.snapshot;
  }

  getEffectiveServers(): readonly TServer[] {
    return this.snapshot.effectiveServers;
  }

  getFullMCPServerState(): readonly MCPConfigGroup<TServer>[] {
    return this.snapshot.groups;
  }

  setMCPSelection({
    groupId,
    serverIdentifiers,
  }: MCPServerSelection): void {
    const group = this.snapshot.groups.find(
      candidate => candidate.groupId === groupId
    );
    if (!group) {
      throw new Error(`Unknown MCP server group: ${groupId}`);
    }
    const groupServerIdentifiers = new Set(
      group.servers.map(server => server.identifier)
    );
    const selectedIdentifiers = uniqueIdentifiers(
      serverIdentifiers.filter(identifier => groupServerIdentifiers.has(identifier))
    );
    if (selectedIdentifiers.length === 0) {
      throw new Error(
        `Selection for MCP server group ${groupId} must include at least one group member`
      );
    }

    this.preferenceStore.setSelection({
      groupId,
      serverIdentifiers: selectedIdentifiers,
    });
    this.snapshot = this.computeSnapshot(this.lastInput);
  }

  getGroupedServerIdentifiers(serverIdentifier: string): readonly string[] {
    for (const group of this.snapshot.groups) {
      if (
        group.servers.some(server => server.identifier === serverIdentifier)
      ) {
        return group.servers.map(server => server.identifier);
      }
    }
    return [serverIdentifier];
  }

  private computeSnapshot(
    input: MCPConfigServiceInput<TServer>
  ): MCPConfigServiceSnapshot<TServer> {
    const disabledServerIdentifiers = toIdentifierSet(
      input.disabledServerIdentifiers
    );
    const groups = buildGroups(input.servers).map(group => {
      const selectedServers = chooseSelectedServers(
        group,
        disabledServerIdentifiers,
        this.preferenceStore
      );
      const sourceServer = selectedServers[0] ?? group.servers[0]!;
      return {
        ...group,
        sourceKind: inferMcpConfigServerSourceKind(sourceServer),
        selectedServers,
        selectedServerIdentifiers: selectedServers.map(server => server.identifier),
      };
    });

    const groupByServerIdentifier = new Map<string, MCPConfigGroup<TServer>>();
    for (const group of groups) {
      for (const server of group.servers) {
        if (!groupByServerIdentifier.has(server.identifier)) {
          groupByServerIdentifier.set(server.identifier, group);
        }
      }
    }

    const emittedGroupIds = new Set<string>();
    const effectiveServers: TServer[] = [];
    for (const server of input.servers) {
      const group = groupByServerIdentifier.get(server.identifier);
      if (!group || emittedGroupIds.has(group.groupId)) {
        continue;
      }
      emittedGroupIds.add(group.groupId);
      effectiveServers.push(...group.selectedServers);
    }

    return { groups, effectiveServers };
  }
}

function buildGroups<TServer extends McpConfigServerInput>(
  servers: readonly TServer[]
): Array<
  Omit<MCPConfigGroup<TServer>, "selectedServers" | "selectedServerIdentifiers">
> {
  const remoteGroups = new Map<
    string,
    Omit<MCPConfigGroup<TServer>, "selectedServers" | "selectedServerIdentifiers">
  >();
  const groups: Array<
    Omit<MCPConfigGroup<TServer>, "selectedServers" | "selectedServerIdentifiers">
  > = [];

  for (const server of servers) {
    const groupId = getGroupId(server);
    const sourceKind = inferMcpConfigServerSourceKind(server);
    if (groupId === undefined) {
      groups.push({
        groupId: `singleton:${server.identifier}`,
        sourceKind,
        servers: [server],
        isGrouped: false,
      });
      continue;
    }

    const existing = remoteGroups.get(groupId);
    if (existing) {
      existing.servers = [...existing.servers, server];
      existing.isGrouped = existing.servers.length > 1;
      continue;
    }

    const group = {
      groupId,
      sourceKind,
      normalizedUrl: groupId.slice("streamableHttp:".length),
      servers: [server],
      isGrouped: false,
    };
    remoteGroups.set(groupId, group);
    groups.push(group);
  }

  return groups;
}

function getGroupId(server: McpConfigServerInput): string | undefined {
  if (server.projectManaged || server.type !== "streamableHttp" || !server.url) {
    return undefined;
  }
  if (server.url.startsWith("mcp-provider://")) {
    return undefined;
  }
  return `streamableHttp:${normalizeMcpServerUrl(server.url)}`;
}

function chooseSelectedServers<TServer extends McpConfigServerInput>(
  group: Pick<MCPConfigGroup<TServer>, "groupId" | "servers">,
  disabledServerIdentifiers: ReadonlySet<string>,
  preferenceStore: MCPSelectionPreferenceStore
): readonly TServer[] {
  const storedSelection = preferenceStore.getSelection(group.groupId);
  if (storedSelection) {
    const storedSelectedServers = uniqueIdentifiers(storedSelection)
      .map(identifier =>
        group.servers.find(server => server.identifier === identifier)
      )
      .filter((server): server is TServer => server !== undefined);
    const selectedServers = storedSelectedServers.filter(
      server => !disabledServerIdentifiers.has(server.identifier)
    );
    if (selectedServers.length > 0) {
      return selectedServers;
    }
    const fallback = storedSelectedServers[0];
    if (fallback) {
      return [fallback];
    }
  }

  const fallback = chooseBySourcePrecedence(group.servers) ?? group.servers[0];
  return fallback ? [fallback] : [];
}

function uniqueIdentifiers(identifiers: readonly string[]): string[] {
  const seen = new Set<string>();
  const unique: string[] = [];
  for (const identifier of identifiers) {
    if (seen.has(identifier)) {
      continue;
    }
    seen.add(identifier);
    unique.push(identifier);
  }
  return unique;
}

function chooseBySourcePrecedence<TServer extends McpConfigServerInput>(
  servers: readonly TServer[],
  predicate: (server: TServer) => boolean = () => true
): TServer | undefined {
  for (const sourceKind of SOURCE_PRECEDENCE) {
    const candidate = servers.find(
      server =>
        inferMcpConfigServerSourceKind(server) === sourceKind &&
        predicate(server)
    );
    if (candidate) {
      return candidate;
    }
  }
  return undefined;
}

export function inferMcpConfigServerSourceKind(
  server: McpConfigServerInput
): McpConfigServerSourceKind {
  if (server.url?.startsWith("mcp-provider://")) {
    return "provider";
  }
  if (server.userManaged) {
    return "user";
  }
  if (server.projectManaged) {
    return "project";
  }
  if (server.extensionId) {
    return "extension";
  }
  if (server.dashboardManaged) {
    return "team";
  }
  if (server.pluginManaged) {
    return "plugin";
  }
  if (server.identifier.startsWith("user-")) {
    return "user";
  }
  return "default";
}

function toIdentifierSet(
  identifiers: ReadonlySet<string> | readonly string[] | undefined
): ReadonlySet<string> {
  if (!identifiers) {
    return new Set();
  }
  return identifiers instanceof Set ? identifiers : new Set(identifiers);
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}
