// GitError carries gitErrorCode/exitCode/stderr as object fields, but both the
// exec throw boundary (ExecClientThrow) and the ext-host -> renderer RPC
// (transformErrorForSerialization) only forward error.message. These helpers
// smuggle the diagnostics through that message and recover them server-side.
import { redactHttpUrlUserinfo } from "./redaction.js";
const GIT_DIAGNOSTICS_PREFIX = " [git: ";
const GIT_DIAGNOSTICS_RE = / \[git: ([^\]]*)\]/;
export const GIT_STDERR_LOG_CAP = 2048;
function capStderr(stderr) {
    if (stderr.length <= GIT_STDERR_LOG_CAP) {
        return stderr;
    }
    return `${stderr.slice(0, GIT_STDERR_LOG_CAP)}… [truncated to ${GIT_STDERR_LOG_CAP} chars]`;
}
