import { SimpleControlledExecHandler } from "./controlled.js";
import { ExecutorResource } from "./remote.js";
import { createResource } from "./resource-provider.js";
import { createClientDeserializer, createClientSerializer, createServerDeserializer, createServerSerializer, } from "./serialization.js";
export const forceBackgroundSubagentExecutorResource = createResource(execManager => new ExecutorResource(execManager, createServerSerializer("forceBackgroundSubagentArgs"), createClientDeserializer("forceBackgroundSubagentResult")), (implementation, controlledExecManager) => {
    controlledExecManager.register(new SimpleControlledExecHandler(implementation, createServerDeserializer("forceBackgroundSubagentArgs"), createClientSerializer("forceBackgroundSubagentResult")));
});
