import {
  acquireEventLoopPressureTracker,
  type IEventLoopPressureTracker,
} from "./event-loop-pressure.js";
import type { IDisposable } from "./lifecycle.js";

export const SHELL_OUTPUT_SUPPRESSION_DEFAULTS: {
  readonly windowMs: 60000;
  readonly minimumThresholdCharsPerSecond: number;
  readonly thresholdCharsPerSecondWithoutPressure: number;
  readonly minChars: number;
} = {
  windowMs: 60_000,
  minimumThresholdCharsPerSecond: 64 * 1024,
  thresholdCharsPerSecondWithoutPressure: 2 * 1024 * 1024,
  minChars: 256 * 1024,
} as const;

/** Duration of each output-volume bucket in milliseconds. */
const BUCKET_MS = 1_000;

/** Notice appended to agent/UI streams when shell output forwarding is suppressed. */
export const SHELL_OUTPUT_SUPPRESSED_NOTICE =
  "\n[This shell is producing too much output to stream. The command will still run.]\n";

export interface OutputSuppressionDecision {
  shouldForward: boolean;
  noticeJustTriggered: boolean;
  charsPerSecond: number;
  thresholdCharsPerSecond: number;
}

export interface OutputSuppressionControllerOptions {
  windowMs?: number;
  minimumThresholdCharsPerSecond?: number;
  thresholdCharsPerSecondWithoutPressure?: number;
  minChars?: number;
}

/**
 * Tracks recent shell output volume and decides when UI-facing streams should
 * stop forwarding noisy output while the underlying command keeps running.
 */
export class OutputSuppressionController implements IDisposable {
  private readonly bucketChars: Uint32Array;
  private readonly bucketStarts: Float64Array;
  private totalChars = 0;
  private outputSuppressed = false;
  private noticeSent = false;

  private readonly windowMs: number;
  private readonly minimumThresholdCharsPerSecond: number;
  private readonly thresholdCharsPerSecondWithoutPressure: number;
  private readonly minChars: number;
  private eventLoopPressureTracker: IEventLoopPressureTracker | undefined;
  private disposed = false;

  constructor(options?: OutputSuppressionControllerOptions) {
    this.windowMs =
      options?.windowMs ?? SHELL_OUTPUT_SUPPRESSION_DEFAULTS.windowMs;
    this.minimumThresholdCharsPerSecond =
      options?.minimumThresholdCharsPerSecond ??
      SHELL_OUTPUT_SUPPRESSION_DEFAULTS.minimumThresholdCharsPerSecond;
    this.thresholdCharsPerSecondWithoutPressure =
      options?.thresholdCharsPerSecondWithoutPressure ??
      SHELL_OUTPUT_SUPPRESSION_DEFAULTS.thresholdCharsPerSecondWithoutPressure;
    this.minChars =
      options?.minChars ?? SHELL_OUTPUT_SUPPRESSION_DEFAULTS.minChars;

    const bucketCount = Math.ceil(this.windowMs / BUCKET_MS) + 1;
    this.bucketChars = new Uint32Array(bucketCount);
    this.bucketStarts = new Float64Array(bucketCount);
  }

  // This function uses byteLength but everything outside is measured in chars.
  // This is because of the experiment config and when we're happy with the
  // values we should standardize everything on bytes.
  record(
    byteLength: number,
    now: number = Date.now()
  ): OutputSuppressionDecision {
    if (this.disposed) {
      return {
        shouldForward: !this.outputSuppressed,
        noticeJustTriggered: false,
        charsPerSecond: 0,
        thresholdCharsPerSecond: this.minimumThresholdCharsPerSecond,
      };
    }

    this.recordChars(byteLength, now);

    const eventLoopUnderPressure =
      this.getEventLoopPressureTracker().isUnderPressure();
    const charsInWindow = this.getCharsInWindow(now);
    const charsPerSecond = this.getAverageCharsPerSecond(now);
    const peakBucketCharsPerSecond = this.getPeakBucketCharsPerSecond(now);
    const withoutPressureRate = Math.max(
      charsPerSecond,
      peakBucketCharsPerSecond
    );
    const meetsMinVolume = charsInWindow >= this.minChars;
    const suppressWithoutPressure =
      meetsMinVolume &&
      withoutPressureRate >= this.thresholdCharsPerSecondWithoutPressure;
    const suppressWithPressure =
      meetsMinVolume &&
      eventLoopUnderPressure &&
      charsPerSecond >= this.minimumThresholdCharsPerSecond;
    const triggeredThresholdCharsPerSecond = suppressWithoutPressure
      ? this.thresholdCharsPerSecondWithoutPressure
      : eventLoopUnderPressure
        ? this.minimumThresholdCharsPerSecond
        : this.thresholdCharsPerSecondWithoutPressure;
    const reportedCharsPerSecond = suppressWithoutPressure
      ? withoutPressureRate
      : charsPerSecond;

    if (
      !this.outputSuppressed &&
      (suppressWithoutPressure || suppressWithPressure)
    ) {
      this.outputSuppressed = true;
    }

    const noticeJustTriggered = this.outputSuppressed && !this.noticeSent;
    if (noticeJustTriggered) {
      this.noticeSent = true;
      console.warn(
        "[OutputSuppressionController] Suppressing shell output:",
        formatSuppressionReason({
          charsInWindow,
          charsPerSecond: reportedCharsPerSecond,
          minChars: this.minChars,
          triggeredThresholdCharsPerSecond,
          suppressWithoutPressure,
          eventLoopPressureTracker: this.getEventLoopPressureTracker(),
        })
      );
    }

    return {
      shouldForward: !this.outputSuppressed,
      noticeJustTriggered,
      charsPerSecond: reportedCharsPerSecond,
      thresholdCharsPerSecond: triggeredThresholdCharsPerSecond,
    };
  }

  reset(): void {
    if (this.disposed) {
      return;
    }
    this.bucketChars.fill(0);
    this.bucketStarts.fill(0);
    this.totalChars = 0;
    this.outputSuppressed = false;
    this.noticeSent = false;
  }

  dispose(): void {
    if (this.disposed) {
      return;
    }
    this.disposed = true;
    // Preserve outputSuppressed / noticeSent so post-dispose record() stays latched.
    this.eventLoopPressureTracker?.dispose();
    this.eventLoopPressureTracker = undefined;
  }

  private getEventLoopPressureTracker(): IEventLoopPressureTracker {
    if (this.eventLoopPressureTracker === undefined) {
      this.eventLoopPressureTracker = acquireEventLoopPressureTracker();
    }
    return this.eventLoopPressureTracker;
  }

  private recordChars(chars: number, now: number): void {
    this.prune(now);
    if (chars <= 0) return;

    const bucketStart = Math.floor(now / BUCKET_MS) * BUCKET_MS;
    const bucketIndex =
      Math.floor(bucketStart / BUCKET_MS) % this.bucketChars.length;
    if (this.bucketStarts[bucketIndex] !== bucketStart) {
      this.totalChars -= this.bucketChars[bucketIndex];
      this.bucketStarts[bucketIndex] = bucketStart;
      this.bucketChars[bucketIndex] = 0;
    }

    this.bucketChars[bucketIndex] += chars;
    this.totalChars += chars;
  }

  private getAverageCharsPerSecond(now: number): number {
    this.prune(now);
    if (this.totalChars === 0) return 0;

    const cutoff = now - this.windowMs;
    let oldestBucketStart = now;
    for (let i = 0; i < this.bucketStarts.length; i++) {
      if (this.bucketChars[i] > 0 && this.bucketStarts[i] >= cutoff) {
        oldestBucketStart = Math.min(oldestBucketStart, this.bucketStarts[i]);
      }
    }

    const elapsedMs = Math.max(
      BUCKET_MS,
      Math.min(this.windowMs, now - oldestBucketStart + BUCKET_MS)
    );
    return this.totalChars / (elapsedMs / 1_000);
  }

  private getPeakBucketCharsPerSecond(now: number): number {
    this.prune(now);
    const cutoff = now - this.windowMs;
    let peak = 0;
    for (let i = 0; i < this.bucketChars.length; i++) {
      if (this.bucketStarts[i] >= cutoff) {
        peak = Math.max(peak, this.bucketChars[i]);
      }
    }
    return peak / (BUCKET_MS / 1_000);
  }

  private getCharsInWindow(now: number): number {
    this.prune(now);
    return this.totalChars;
  }

  private prune(now: number): void {
    const cutoff = now - this.windowMs;
    for (let i = 0; i < this.bucketStarts.length; i++) {
      if (this.bucketStarts[i] !== 0 && this.bucketStarts[i] < cutoff) {
        this.totalChars -= this.bucketChars[i];
        this.bucketStarts[i] = 0;
        this.bucketChars[i] = 0;
      }
    }
  }
}

function formatSuppressionReason(args: {
  charsInWindow: number;
  charsPerSecond: number;
  minChars: number;
  triggeredThresholdCharsPerSecond: number;
  suppressWithoutPressure: boolean;
  eventLoopPressureTracker: IEventLoopPressureTracker;
}): string {
  const volumeReasons = [
    `output volume ${args.charsInWindow} chars in window >= min ${args.minChars}`,
    `output rate ${Math.round(args.charsPerSecond)} chars/s >= threshold ${args.triggeredThresholdCharsPerSecond} chars/s`,
  ];
  const volumeSection = `volume thresholds met (${volumeReasons.join("; ")})`;
  const eventLoopSection = args.suppressWithoutPressure
    ? "event loop pressure gate bypassed due to extreme output rate"
    : args.eventLoopPressureTracker.formatSuppressionSection();

  return `${volumeSection}; ${eventLoopSection}`;
}
