import type { ShellCommandParsingResult } from "@anysphere/proto/agent/v1/shell_exec_pb.js";
import type { SandboxPolicy } from "@anysphere/shell-exec";

/**
 * Opt-in, non-overridable shell hardening for sandboxed eval harnesses
 * (e.g. Harbor SWE-Bench runs). {@link FORCED_SHELL_EGRESS_ENV} is the master
 * gate; when set it activates the full eval shell/network posture:
 *
 *  1. Shell egress (this module): every shell tool call is forced onto a
 *     deny-by-default network policy that the model cannot escalate — not via
 *     `--force`/unrestricted approval mode, and not via a model-supplied
 *     `requestedSandboxPolicy`.
 *  2. Web tools (agent-cli `interaction-responses`): WebSearch/WebFetch are
 *     rejected, since they are another arbitrary-egress channel.
 *  3. Sandbox startup (agent-cli `run-agent`): the headless startup
 *     "sandbox unsupported" preflight no longer hard-aborts; per-command
 *     enforcement still applies (and fails closed at exec time if the sandbox
 *     helper genuinely cannot run).
 *
 * This is the typed, version-stable replacement for the runtime bundle patch
 * Harbor applies today (string-rewriting the minified CLI). Behavior is gated
 * entirely behind {@link FORCED_SHELL_EGRESS_ENV} so normal users are
 * unaffected.
 *
 * This module ships mechanism, not policy: every dimension of the forced
 * policies is supplied by the harness operator via env vars, and the built-in
 * defaults are intentionally empty. With only the master gate set, every shell
 * command gets the fail-closed loopback policy (workspace-only writes, network
 * limited to loopback) and web tools are rejected. The harness layers its
 * posture on top per run, without ever needing a new CLI build:
 *
 * - {@link FORCED_SHELL_EGRESS_DEPENDENCY_REGEX_ENV} — pattern for dependency
 *   commands (package installers, build/test runners) that are granted the
 *   direct-egress dependency policy. Unset (default): no command qualifies.
 * - {@link FORCED_SHELL_EGRESS_EXTRA_DEPENDENCY_REGEX_ENV} — extra terms OR'd
 *   onto the dependency pattern.
 * - {@link FORCED_SHELL_EGRESS_SOURCE_REGEX_ENV} — pattern for upstream-source
 *   lookups (e.g. `git clone`, `gh`, `curl github.com`) that are always forced
 *   onto the loopback policy, even when they would otherwise qualify as
 *   dependency commands. Unset (default): no command-level source blocking.
 * - {@link FORCED_SHELL_EGRESS_EXTRA_SOURCE_REGEX_ENV} — extra terms OR'd onto
 *   the source-lookup pattern.
 * - {@link FORCED_SHELL_EGRESS_NETWORK_DEFAULT_ENV} — default network action
 *   (`deny`, the default, or `allow`) for commands that are NOT recognized
 *   dependency installers. With `allow`, pair with a deny-domain list so the
 *   hosts that actually leak answers stay blocked at the network layer.
 * - {@link FORCED_SHELL_EGRESS_DENY_DOMAINS_ENV} — comma-separated
 *   domains/wildcards/CIDRs always denied, on BOTH the non-dependency and the
 *   dependency policies (deny has highest priority in the network policy).
 * - {@link FORCED_SHELL_EGRESS_DEPENDENCY_DENY_DOMAINS_ENV} — deny list for
 *   the dependency policy specifically. Unset: inherit the main deny list
 *   (fail-safe). The literal value `none`: dependency commands get no deny
 *   list (e.g. so build tools like go/bazel/cargo can fetch GitHub-hosted
 *   artifacts while raw curl/python fetches stay blocked). Any other value:
 *   used as the dependency policy's deny list.
 * - {@link FORCED_SHELL_EGRESS_ALLOW_DOMAINS_ENV} — comma-separated extra
 *   allow entries for the non-dependency policy (e.g. package registries when
 *   keeping the default-deny model).
 * - {@link FORCED_SHELL_EGRESS_WRITABLE_PATHS_ENV} — colon-separated absolute
 *   paths added to both policies' `additionalReadwritePaths` (e.g.
 *   `/root:/usr:/go`, or `/` to lift the workspace write restriction
 *   entirely). Default empty: the workspace-only filesystem sandbox is kept.
 *
 * Regex values are regex source strings (matched case-insensitively). All
 * values come from the trusted harness operator, not the model. An invalid
 * regex value throws — failing every gated shell command loudly — because
 * silently dropping a pattern would either disable the source blocklist
 * (fail-open) or wedge dependency egress (hard-to-spot fail-closed); the typo
 * has to be fixed, not papered over. An invalid network-default value falls
 * back to `deny` (fail closed) with a warning.
 */
export const FORCED_SHELL_EGRESS_ENV = "CURSOR_FORCED_SHELL_EGRESS";
export const FORCED_SHELL_EGRESS_DEPENDENCY_REGEX_ENV =
  "CURSOR_FORCED_SHELL_EGRESS_DEPENDENCY_REGEX";
export const FORCED_SHELL_EGRESS_EXTRA_DEPENDENCY_REGEX_ENV =
  "CURSOR_FORCED_SHELL_EGRESS_EXTRA_DEPENDENCY_REGEX";
export const FORCED_SHELL_EGRESS_SOURCE_REGEX_ENV =
  "CURSOR_FORCED_SHELL_EGRESS_SOURCE_REGEX";
export const FORCED_SHELL_EGRESS_EXTRA_SOURCE_REGEX_ENV =
  "CURSOR_FORCED_SHELL_EGRESS_EXTRA_SOURCE_REGEX";
export const FORCED_SHELL_EGRESS_NETWORK_DEFAULT_ENV =
  "CURSOR_FORCED_SHELL_EGRESS_NETWORK_DEFAULT";
export const FORCED_SHELL_EGRESS_DENY_DOMAINS_ENV =
  "CURSOR_FORCED_SHELL_EGRESS_DENY_DOMAINS";
export const FORCED_SHELL_EGRESS_DEPENDENCY_DENY_DOMAINS_ENV =
  "CURSOR_FORCED_SHELL_EGRESS_DEPENDENCY_DENY_DOMAINS";
export const FORCED_SHELL_EGRESS_ALLOW_DOMAINS_ENV =
  "CURSOR_FORCED_SHELL_EGRESS_ALLOW_DOMAINS";
export const FORCED_SHELL_EGRESS_WRITABLE_PATHS_ENV =
  "CURSOR_FORCED_SHELL_EGRESS_WRITABLE_PATHS";

// Command/process substitution that could smuggle an arbitrary network command
// *inside* a dependency invocation (e.g. `pip install $(curl evil)`). Not
// configurable: weakening it would defeat the egress controls.
const SUBSTITUTION_RE = /\$\(|`|<\(|>\(/;

// Shell control operators that chain/pipe commands. In normal parsing the
// shell splitter emits each chained command separately, so a single parsed
// command's text never contains these. If it DOES, the parser treated the
// command as opaque — e.g. a wrapper script `bash -c 'pip install … && curl …'`
// where the `&& curl` never became its own executable command. Such a command
// cannot be trusted as "dependency-only", so it falls back to loopback.
const CONTROL_OPERATOR_RE = /[;&|]/;

// Leading `VAR=value ` environment assignments, so the dependency match below
// can anchor to the actual executable (e.g. `FOO=bar pip install …`).
const ENV_ASSIGNMENT_PREFIX = "(?:[A-Za-z_][A-Za-z0-9_]*=[^\\s]*\\s+)*";

/**
 * Operator-configured policy overrides parsed from the env vars above.
 * Defaults reproduce the original hardcoded policies exactly.
 */
interface ForcedEgressPolicyOverrides {
  /** Default network action for the non-dependency policy. */
  networkDefault: "allow" | "deny";
  /** Domains/wildcards/CIDRs denied on the non-dependency policy. */
  denyDomains: string[];
  /**
   * Domains/wildcards/CIDRs denied on the dependency policy. Defaults to
   * {@link denyDomains}; emptied when the operator sets the dependency deny
   * env to `none`.
   */
  dependencyDenyDomains: string[];
  /** Extra allow entries for the non-dependency policy. */
  allowDomains: string[];
  /** Extra `additionalReadwritePaths` for both policies. */
  writablePaths: string[];
}

let cachedEnabled: boolean | undefined;
// `null` means "computed: no pattern configured" (vs `undefined` = not yet computed).
let cachedDependencyRe: RegExp | null | undefined;
let cachedSourceLookupRe: RegExp | null | undefined;
let cachedPolicyOverrides: ForcedEgressPolicyOverrides | undefined;

/** Reads the gate env var once. Truthy unless empty/`0`/`false`/`off`. */
export function isForcedShellEgressEnabled(): boolean {
  if (cachedEnabled === undefined) {
    const raw = (process.env[FORCED_SHELL_EGRESS_ENV] ?? "")
      .trim()
      .toLowerCase();
    cachedEnabled =
      raw !== "" && raw !== "0" && raw !== "false" && raw !== "off";
  }
  return cachedEnabled;
}

/** Test-only: clear all memoized env reads / compiled patterns. */
export function resetForcedShellEgressCacheForTests(): void {
  cachedEnabled = undefined;
  cachedDependencyRe = undefined;
  cachedSourceLookupRe = undefined;
  cachedPolicyOverrides = undefined;
}

function requiredRegexSource(envVar: string): string | undefined {
  const raw = (process.env[envVar] ?? "").trim();
  if (!raw) {
    return undefined;
  }
  try {
    // Validate compilability; operator-controlled input, not model input.
    new RegExp(raw, "i");
    return raw;
  } catch (error) {
    // Fail loudly: silently dropping the pattern would either disable the
    // source blocklist (fail-open) or quietly wedge dependency egress. The
    // throw surfaces on every gated shell command until the harness fixes
    // the value.
    throw new Error(
      `[forced-egress] invalid regex in ${envVar}: ${String(error)}`
    );
  }
}

/** Comma-separated network-policy entries (domains, wildcards, CIDRs). */
function parseDomainListEnv(envVar: string): string[] {
  return (process.env[envVar] ?? "")
    .split(",")
    .map(entry => entry.trim())
    .filter(entry => entry.length > 0);
}

/**
 * Colon-separated extra writable roots. Only absolute paths are honored — a
 * relative entry is ignored (with a warning) so a typo cannot silently widen
 * filesystem access in an unexpected way.
 */
function parseWritablePathsEnv(envVar: string): string[] {
  const entries = (process.env[envVar] ?? "")
    .split(":")
    .map(entry => entry.trim())
    .filter(entry => entry.length > 0);
  const absolute = entries.filter(entry => entry.startsWith("/"));
  const dropped = entries.length - absolute.length;
  if (dropped > 0) {
    console.error(
      `[forced-egress] ignoring ${dropped} non-absolute path(s) in ${envVar}.`
    );
  }
  return absolute;
}

function policyOverrides(): ForcedEgressPolicyOverrides {
  if (cachedPolicyOverrides === undefined) {
    const rawDefault = (
      process.env[FORCED_SHELL_EGRESS_NETWORK_DEFAULT_ENV] ?? ""
    )
      .trim()
      .toLowerCase();
    let networkDefault: "allow" | "deny" = "deny";
    if (rawDefault === "allow" || rawDefault === "deny") {
      networkDefault = rawDefault;
    } else if (rawDefault !== "") {
      console.error(
        `[forced-egress] ignoring invalid value in ${FORCED_SHELL_EGRESS_NETWORK_DEFAULT_ENV} (expected "allow" or "deny"); using "deny".`
      );
    }
    const denyDomains = parseDomainListEnv(
      FORCED_SHELL_EGRESS_DENY_DOMAINS_ENV
    );
    // Dependency-policy deny list: inherit the main list unless the operator
    // explicitly sets it ("none" = no deny for dependency commands).
    const rawDependencyDeny = (
      process.env[FORCED_SHELL_EGRESS_DEPENDENCY_DENY_DOMAINS_ENV] ?? ""
    ).trim();
    let dependencyDenyDomains = denyDomains;
    if (rawDependencyDeny.toLowerCase() === "none") {
      dependencyDenyDomains = [];
    } else if (rawDependencyDeny !== "") {
      dependencyDenyDomains = parseDomainListEnv(
        FORCED_SHELL_EGRESS_DEPENDENCY_DENY_DOMAINS_ENV
      );
    }
    cachedPolicyOverrides = {
      networkDefault,
      denyDomains,
      dependencyDenyDomains,
      allowDomains: parseDomainListEnv(FORCED_SHELL_EGRESS_ALLOW_DOMAINS_ENV),
      writablePaths: parseWritablePathsEnv(
        FORCED_SHELL_EGRESS_WRITABLE_PATHS_ENV
      ),
    };
  }
  return cachedPolicyOverrides;
}

/**
 * Compiles an operator-supplied pattern from a base env var plus an extra env
 * var (OR'd together). Returns `null` when neither is set: there is no
 * built-in default, so an unconfigured classifier matches nothing and the
 * policy choice fails closed. A set-but-invalid value throws (see
 * {@link requiredRegexSource}).
 */
function compileConfigurablePattern(
  overrideEnv: string,
  extraEnv: string,
  options: { anchorToExecutable?: boolean } = {}
): RegExp | null {
  const parts = [
    requiredRegexSource(overrideEnv),
    requiredRegexSource(extraEnv),
  ]
    .filter((part): part is string => part !== undefined)
    .map(part => `(?:${part})`);
  if (parts.length === 0) {
    return null;
  }
  const body = parts.join("|");
  // The dependency classifier must match the command's actual executable, not
  // a token buried in its arguments — otherwise a wrapper like
  // `bash -c '… pip install …'` would be misread as a dependency command.
  const pattern = options.anchorToExecutable
    ? `^\\s*${ENV_ASSIGNMENT_PREFIX}(?:${body})`
    : body;
  return new RegExp(pattern, "i");
}

function dependencyRegex(): RegExp | null {
  if (cachedDependencyRe === undefined) {
    cachedDependencyRe = compileConfigurablePattern(
      FORCED_SHELL_EGRESS_DEPENDENCY_REGEX_ENV,
      FORCED_SHELL_EGRESS_EXTRA_DEPENDENCY_REGEX_ENV,
      { anchorToExecutable: true }
    );
  }
  return cachedDependencyRe;
}

function sourceLookupRegex(): RegExp | null {
  if (cachedSourceLookupRe === undefined) {
    cachedSourceLookupRe = compileConfigurablePattern(
      FORCED_SHELL_EGRESS_SOURCE_REGEX_ENV,
      FORCED_SHELL_EGRESS_EXTRA_SOURCE_REGEX_ENV
    );
  }
  return cachedSourceLookupRe;
}

/**
 * Policy for commands that are NOT recognized dependency installers.
 *
 * Default (no overrides): workspace read/write with the filesystem sandbox
 * intact, network restricted to loopback only. With
 * {@link FORCED_SHELL_EGRESS_NETWORK_DEFAULT_ENV}=allow the network opens up
 * except for {@link FORCED_SHELL_EGRESS_DENY_DOMAINS_ENV} (domain-deny model);
 * {@link FORCED_SHELL_EGRESS_ALLOW_DOMAINS_ENV} and
 * {@link FORCED_SHELL_EGRESS_WRITABLE_PATHS_ENV} widen the allow list and the
 * writable filesystem respectively.
 */
export function forcedLoopbackEgressPolicy(): SandboxPolicy {
  const overrides = policyOverrides();
  return {
    type: "workspace_readwrite",
    ...(overrides.writablePaths.length > 0
      ? { additionalReadwritePaths: overrides.writablePaths }
      : {}),
    networkPolicy: {
      version: 1,
      default: overrides.networkDefault,
      allow: ["127.0.0.0/8", "::1/128", "localhost", ...overrides.allowDomains],
      ...(overrides.denyDomains.length > 0
        ? { deny: overrides.denyDomains }
        : {}),
    },
    networkPolicyStrict: true,
    skipStatsigDefaults: true,
    enableSharedBuildCache: true,
  };
}

/**
 * Dependency policy: unrestricted *direct* egress (no proxy, so package
 * managers that ignore proxy env vars such as Maven/Cargo still work) while
 * keeping the filesystem sandbox (write-protection of `.git/hooks`, `.cursor`
 * configs, etc.) intact. The dependency deny list (which inherits the main
 * deny list unless overridden via
 * {@link FORCED_SHELL_EGRESS_DEPENDENCY_DENY_DOMAINS_ENV}) and extra writable
 * paths still apply.
 *
 * Note: deliberately NOT `insecure_none`. `insecure_none` would also drop the
 * filesystem protections and re-open link-local targets — the regression this
 * module exists to avoid. Operators that need installs to write outside the
 * workspace widen writes via {@link FORCED_SHELL_EGRESS_WRITABLE_PATHS_ENV}
 * (keeping the network controls), rather than dropping to `insecure_none`.
 */
function forcedDependencyEgressPolicy(): SandboxPolicy {
  const overrides = policyOverrides();
  return {
    type: "workspace_readwrite",
    ...(overrides.writablePaths.length > 0
      ? { additionalReadwritePaths: overrides.writablePaths }
      : {}),
    networkPolicy: {
      version: 1,
      default: "allow",
      ...(overrides.dependencyDenyDomains.length > 0
        ? { deny: overrides.dependencyDenyDomains }
        : {}),
    },
    skipStatsigDefaults: true,
    enableSharedBuildCache: true,
  };
}

/**
 * Choose the forced sandbox policy for a shell command. Returns the dependency
 * (direct-egress) policy only when an operator-supplied dependency pattern is
 * configured, EVERY parsed executable command matches it, none performs an
 * upstream-source lookup, and the raw command contains no command/process
 * substitution. Otherwise returns the loopback policy.
 *
 * Dependency egress is granted only when EVERY parsed command:
 *  - matches the operator-supplied dependency pattern at the command's
 *    executable (so a wrapper like `bash -c '… pip install …'` — whose
 *    executable is `bash`, not `pip` — does not qualify),
 *  - performs no upstream-source lookup, and
 *  - contains no unsplit control operator (`;`, `&`, `|`). A single parsed
 *    command holding one of those means the parser treated it as opaque (e.g.
 *    a `-c` wrapper script), so `&& curl evil` could ride along unseen.
 * The raw command must also be free of command/process substitution.
 * Anything else — including the default state where no dependency pattern is
 * configured at all — falls back to the loopback policy.
 */
export function forcedShellSandboxPolicy(
  command: string,
  parsingResult: ShellCommandParsingResult | undefined
): SandboxPolicy {
  const loopback = forcedLoopbackEgressPolicy();

  const dependencyRe = dependencyRegex();
  if (dependencyRe === null) {
    // No dependency classifier configured → nothing qualifies for the
    // dependency policy; every command gets the loopback policy.
    return loopback;
  }

  const commands = parsingResult?.executableCommands ?? [];
  if (parsingResult?.parsingFailed || commands.length === 0) {
    // No trustworthy command extraction → fail closed to loopback.
    return loopback;
  }

  if (SUBSTITUTION_RE.test(command)) {
    return loopback;
  }

  const sourceLookupRe = sourceLookupRegex();
  for (const cmd of commands) {
    const text = cmd.fullText?.trim() || cmd.name?.trim() || "";
    if (!text || sourceLookupRe?.test(text) || CONTROL_OPERATOR_RE.test(text)) {
      // Empty, source-lookup, or opaque wrapper command → fail closed.
      return loopback;
    }
  }

  const allDependency = commands.every(cmd =>
    dependencyRe.test(cmd.fullText?.trim() || cmd.name?.trim() || "")
  );
  return allDependency ? forcedDependencyEgressPolicy() : loopback;
}
