/**
 * Thrown from `invalidateCredentials('tokens')` when the stored refresh_token
 * differs from the one this provider last handed to the SDK. This means a
 * sibling client sharing the same server URL already rotated the token
 * successfully — our `InvalidGrantError` was a stale-token race, not a
 * genuine auth failure.
 *
 * Propagating this error out of the SDK's `auth()` retry aborts the retry
 * and lets the FSM reconnect the client from scratch. On reconnect the
 * transport reads the sibling's fresh access token from shared storage and
 * uses it directly — no additional refresh, no secondary race.
 */
export class SiblingAlreadyRefreshedError extends Error {
	constructor(identifier: string) {
		super(`OAuth refresh race detected for ${identifier}: sibling already rotated tokens; reconnecting to use fresh credentials`);
		this.name = 'SiblingAlreadyRefreshedError';
	}
}

/** Matches the `name` set by the patched MCP SDK on transient refresh failures. */
export const OAUTH_REFRESH_TRANSIENT_ERROR_NAME = 'OAuthRefreshTransientError';

export function isOAuthRefreshTransientError(error: unknown): error is Error {
	return error instanceof Error && error.name === OAUTH_REFRESH_TRANSIENT_ERROR_NAME;
}

// One definition of "the auth server rejected the credentials", shared by the
// operation classifier (isAuthRelatedError) and the refresh classifier so they
// cannot drift. Names/codes are the SDK's OAuth credential errors; kept here
// (no SDK import) so the refresh path stays off the SDK's bare specifier.
export const OAUTH_CREDENTIAL_ERROR_NAMES: ReadonlySet<string> = new Set([
	'UnauthorizedError',
	'InvalidGrantError',
	'InvalidTokenError',
	'InvalidClientError',
	'UnauthorizedClientError',
]);

export const OAUTH_CREDENTIAL_ERROR_CODES: ReadonlySet<string> = new Set([
	'invalid_grant',
	'invalid_token',
	'invalid_client',
	'unauthorized_client',
]);

/**
 * RFC 6749 §5.2 requires `invalid_grant` for an expired refresh token, but
 * some OAuth servers respond with `invalid_request` instead — e.g. Spacelift's
 * token endpoint returns
 * `400 {"error":"invalid_request","error_description":"token has expired"}`.
 * The SDK surfaces that as `InvalidRequestError`, which the credential sets
 * above deliberately exclude because a generic `invalid_request` can be a
 * malformed request that re-authentication cannot fix.
 */
export const OAUTH_EXPIRED_TOKEN_MESSAGE_PATTERN: RegExp = /\btoken (?:has |is )?expired\b/i;

/**
 * Matches the narrow "expired token reported as invalid_request" shape so it
 * classifies as a credential failure (projecting needsAuth with a Login CTA)
 * instead of a dead-end generic connection error. Keyed on serialized
 * `name` / `errorCode` (not instanceof) so errors that crossed the
 * MCP-process IPC boundary are still recognized.
 */
export function isExpiredTokenInvalidRequestOAuthError(error: unknown): boolean {
	if (error === null || typeof error !== 'object') {
		return false;
	}
	const name = (error as { name?: unknown }).name;
	const errorCode = (error as { errorCode?: unknown }).errorCode;
	const isInvalidRequest =
		name === 'InvalidRequestError' ||
		(typeof errorCode === 'string' && errorCode.toLowerCase() === 'invalid_request');
	if (!isInvalidRequest) {
		return false;
	}
	const message = (error as { message?: unknown }).message;
	return typeof message === 'string' && OAUTH_EXPIRED_TOKEN_MESSAGE_PATTERN.test(message);
}
