import { mkdir, readFile, writeFile } from "node:fs/promises";
import * as path from "node:path";
import type {
  OAuthClientInformationFull,
  OAuthTokens,
} from "@modelcontextprotocol/sdk/shared/auth.js";
import type { McpTokenStorage } from "./loader.js";

interface McpAuthData {
  tokens?: OAuthTokens;
  clientInfo?: OAuthClientInformationFull;
}

export class FileBasedTokenStore implements McpTokenStorage {
  private static readonly mcpAuthPromises = new Map<
    string,
    Promise<Record<string, McpAuthData>>
  >();
  private static readonly saveLocks = new Map<string, Promise<void>>();
  private readonly mcpAuthPromise: Promise<Record<string, McpAuthData>>;

  constructor(private readonly mcpAuthPath: string) {
    const cachedPromise = FileBasedTokenStore.mcpAuthPromises.get(mcpAuthPath);
    if (cachedPromise) {
      this.mcpAuthPromise = cachedPromise;
    } else {
      const mcpAuthPromise = this.loadMcpAuth();
      this.mcpAuthPromise = mcpAuthPromise;
      FileBasedTokenStore.mcpAuthPromises.set(mcpAuthPath, mcpAuthPromise);
      void mcpAuthPromise.catch(() => {
        if (
          FileBasedTokenStore.mcpAuthPromises.get(mcpAuthPath) ===
          mcpAuthPromise
        ) {
          FileBasedTokenStore.mcpAuthPromises.delete(mcpAuthPath);
        }
      });
    }
    if (!FileBasedTokenStore.saveLocks.has(mcpAuthPath)) {
      FileBasedTokenStore.saveLocks.set(mcpAuthPath, Promise.resolve());
    }
  }

  private async loadMcpAuth(): Promise<Record<string, McpAuthData>> {
    try {
      const mcpAuth = await readFile(this.mcpAuthPath, "utf8");
      const data = JSON.parse(mcpAuth);

      // Handle legacy format (direct token storage at root level)
      if (data && typeof data === "object") {
        // Check if it's the old format with direct token storage
        const hasDirectTokens = Object.values(data).some(
          (value: unknown) =>
            value &&
            typeof value === "object" &&
            value !== null &&
            ("access_token" in value || "refresh_token" in value) &&
            !("tokens" in value) &&
            !("clientInfo" in value)
        );

        if (hasDirectTokens) {
          // Convert legacy format: { identifier: OAuthTokens } -> { identifier: { tokens: OAuthTokens } }
          const converted: Record<string, McpAuthData> = {};
          for (const [key, value] of Object.entries(data)) {
            converted[key] = { tokens: value as OAuthTokens };
          }
          return converted;
        }

        // Handle new format or mixed format
        const result: Record<string, McpAuthData> = {};
        for (const [key, value] of Object.entries(data)) {
          if (value && typeof value === "object" && value !== null) {
            result[key] = {
              tokens:
                "tokens" in value ? (value.tokens as OAuthTokens) : undefined,
              clientInfo:
                "clientInfo" in value
                  ? (value.clientInfo as OAuthClientInformationFull)
                  : undefined,
            };
          }
        }
        return result;
      }

      return {};
    } catch (e) {
      if (e instanceof Error && e.message.includes("ENOENT")) {
        return {};
      }
      throw e;
    }
  }

  async loadTokens(identifier: string): Promise<OAuthTokens | undefined> {
    const mcpAuth = await this.mcpAuthPromise;
    return mcpAuth[identifier]?.tokens;
  }

  async saveTokens(identifier: string, tokens: OAuthTokens): Promise<void> {
    await this.withSaveLock(async () => {
      const mcpAuth = await this.mcpAuthPromise;
      if (!mcpAuth[identifier]) {
        mcpAuth[identifier] = {};
      }
      mcpAuth[identifier].tokens = tokens;
      await this.saveMcpAuth(mcpAuth);
    });
  }

  async loadClientInformation(
    identifier: string
  ): Promise<OAuthClientInformationFull | undefined> {
    const mcpAuth = await this.mcpAuthPromise;
    return mcpAuth[identifier]?.clientInfo;
  }

  private async withSaveLock<T>(fn: () => Promise<T>): Promise<T> {
    const previousLock =
      FileBasedTokenStore.saveLocks.get(this.mcpAuthPath) ?? Promise.resolve();
    let releaseLock: () => void;

    FileBasedTokenStore.saveLocks.set(
      this.mcpAuthPath,
      new Promise<void>(resolve => {
        releaseLock = resolve;
      })
    );

    try {
      await previousLock;
      return await fn();
    } finally {
      releaseLock!();
    }
  }

  async saveClientInformation(
    identifier: string,
    clientInfo: OAuthClientInformationFull
  ): Promise<void> {
    await this.withSaveLock(async () => {
      const mcpAuth = await this.mcpAuthPromise;
      if (!mcpAuth[identifier]) {
        mcpAuth[identifier] = {};
      }
      mcpAuth[identifier].clientInfo = clientInfo;
      await this.saveMcpAuth(mcpAuth);
    });
  }

  async deleteCredentials(identifier: string): Promise<void> {
    await this.withSaveLock(async () => {
      const mcpAuth = await this.mcpAuthPromise;
      if (identifier in mcpAuth) {
        delete mcpAuth[identifier];
        await this.saveMcpAuth(mcpAuth);
      }
    });
  }

  private async saveMcpAuth(data: Record<string, McpAuthData>): Promise<void> {
    await mkdir(path.dirname(this.mcpAuthPath), { recursive: true });
    await writeFile(this.mcpAuthPath, JSON.stringify(data, null, 2));
  }
}
