/**
 * V2-specific types for the mcpCommandsV2 wiring layer.
 *
 * The V2 interpreter reuses the existing pure FSMs and coordinator
 * unchanged.  The coordinator still returns ConnectionCommand[] which
 * may include timer commands (start_backoff_timer, etc.).  The V2
 * interpreter filters those out and derives timer lifecycle from the
 * activity model (activeActivities.ts) instead.
 *
 * This file defines the result-returning transport factory contract
 * and the V2 action type.
 */

export type McpIdeOAuthNeedsAuthReason =
	| 'oauth_provider_callback'
	| 'connect_auth_error'
	| 'oauth_config_error'
	| 'sse_fallback_auth_error'
	// A server known to need OAuth (static client credentials, or an
	// allowlisted lazy-auth host) accepted an unauthenticated connect with no
	// stored tokens, so the connect phase started the interactive OAuth flow.
	// Name kept for continuity with existing telemetry.
	| 'connect_unauthenticated_static_client';

// ── ConnectResult ───────────────────────────────────────────────────
// The transport factory returns this instead of dispatching FSM events.
// The caller (ServerLifecycle) owns event dispatch, making I1
// structurally impossible to violate.

export interface Transport {
	readonly sessionId?: string;
	readonly protocolVersion?: string;
	close(): Promise<void>;
	setProtocolVersion?(protocolVersion: string): void;
}

export interface Client {
	onerror?: (error: Error) => void;
	onclose?: () => void;
	connect(transport: Transport): Promise<void>;
	close(): void;
}

export interface ReconnectSessionInfo {
	readonly sessionId: string;
	readonly protocolVersion?: string;
}

export type ConnectResult =
	| ConnectSuccess
	| ConnectFailureSessionReuseContext
	| ConnectFailure
	| ConnectNeedsAuth;

export interface ConnectSuccess {
	readonly ok: true;
	readonly client: Client;
	readonly transport: Transport;
	/** The transport type that was actually used (may differ from requested if SSE fallback occurred) */
	readonly actualType: 'stdio' | 'sse' | 'streamableHttp';
}

export interface ConnectFailure {
	readonly ok: false;
	readonly needsAuth?: false;
	readonly error: string;
	readonly isRetryable: boolean;
	readonly reconnectSession?: ReconnectSessionInfo;
	readonly sessionReuseRequired?: boolean;
}

export interface ConnectFailureSessionReuseContext extends ConnectFailure {
	readonly sessionReuseRequired: true;
	readonly reconnectSession: ReconnectSessionInfo;
}

/** Narrowing guard for connect failures that require a fresh initialize without the cached session id. */
export function isConnectFailureSessionReuseContext(
	result: ConnectResult,
): result is ConnectFailureSessionReuseContext {
	return (
		!result.ok
		&& result.needsAuth !== true
		&& result.sessionReuseRequired === true
	);
}

export interface ConnectNeedsAuth {
	readonly ok: false;
	readonly needsAuth: true;
	readonly authorizationUrl: string;
	/** Transport may still have been created (for OAuth redirect flow) */
	readonly transport?: Transport;
	/** Present when transport factory captured a token snapshot at the needsAuth transition (not the hot `tokens()` read path). */
	readonly refreshTokenPresent?: boolean;
	readonly hadAuthRequiredEvent?: boolean;
	readonly needsAuthReason?: McpIdeOAuthNeedsAuthReason;
	/** Sanitized OAuth refresh diagnostics from the provider (process path). */
	readonly oauthRefreshDiagnostics?: Record<string, unknown>;
}

// ── ConnectionAction ────────────────────────────────────────────────
// Under the activity model, the only "fire-and-forget" action the FSM
// produces is initiate_connection.  Timer lifecycle is derived from
// state, not commanded.
//
// The V2 interpreter extracts these from the coordinator's
// ConnectionCommand[] by filtering to only 'initiate_connection'.

export type ConnectionAction = { readonly type: 'initiate_connection' };

/**
 * Filter coordinator commands to only V2-relevant actions.
 * Timer commands are ignored because the ActivityReconciler handles them.
 */
export function extractV2Actions(
	commands: ReadonlyArray<{ type: string }>,
): ConnectionAction[] {
	const actions: ConnectionAction[] = [];
	for (const cmd of commands) {
		if (cmd.type === 'initiate_connection') {
			actions.push({ type: 'initiate_connection' });
		}
		// Timer commands (start_backoff_timer, cancel_backoff_timer,
		// start_stability_timer, cancel_stability_timer) are deliberately
		// ignored — the ActivityReconciler derives timer lifecycle from
		// state transitions.
	}
	return actions;
}
