import type { Context, StructuredLoggerHandle } from "@anysphere/context";
import {
  buildOAuthClientInformationSnapshotForLog,
  buildOAuthTokensSnapshotForLog,
  emitMcpOAuthLifecycleLog,
  getMcpOAuthErrorLogMetadata,
  type McpOAuthCredentialInvalidationScope,
  type McpOAuthLifecycleLogger,
  sanitizeErrorMessageForLog,
  snapshotServerUrlForLog,
} from "@anysphere/mcp-core";
import type {
  OAuthClientInformationFull,
  OAuthTokens,
} from "@modelcontextprotocol/sdk/shared/auth.js";
import type { McpTokenStorage } from "./loader.js";
import type { ScopedMcpTokenStorage } from "./mcp.js";

export function structuredLoggerToMcpOAuthLifecycleLogger(args: {
  logger: StructuredLoggerHandle;
  ctx: Context;
}): McpOAuthLifecycleLogger {
  const { logger, ctx } = args;
  return {
    debug: (message, metadata) => logger.debug(ctx, message, metadata),
    info: (message, metadata) => logger.info(ctx, message, metadata),
    warn: (message, metadata) => logger.warn(ctx, message, metadata),
    error: (message, error, metadata) =>
      logger.error(ctx, message, error, metadata),
  };
}

export function unrestrictedContextLoggerToMcpOAuthLifecycleLogger(args: {
  ctx: {
    infoUnrestricted: (obj: Record<string, unknown>, msg: string) => void;
    warnUnrestricted: (obj: Record<string, unknown>, msg: string) => void;
  };
}): McpOAuthLifecycleLogger {
  const { ctx } = args;
  return {
    debug: (message, metadata) => ctx.infoUnrestricted(metadata ?? {}, message),
    info: (message, metadata) => ctx.infoUnrestricted(metadata ?? {}, message),
    warn: (message, metadata) => ctx.warnUnrestricted(metadata ?? {}, message),
    error: (message, error, metadata) =>
      ctx.warnUnrestricted(
        {
          ...metadata,
          ...(error instanceof Error
            ? {
                errorName: error.name,
                errorMessage: sanitizeErrorMessageForLog(error.message),
              }
            : error !== undefined
              ? { error: sanitizeErrorMessageForLog(String(error)) }
              : {}),
        },
        message
      ),
  };
}

export type McpOAuthLifecycleLogAdapter = McpOAuthLifecycleLogger;

export function createStructuredLifecycleLogger(args: {
  logger: StructuredLoggerHandle;
  ctx: Context;
}): McpOAuthLifecycleLogger {
  return structuredLoggerToMcpOAuthLifecycleLogger(args);
}

export function createContextStructuredLifecycleLogger(
  ctx: Context,
  logger: StructuredLoggerHandle
): McpOAuthLifecycleLogger {
  return structuredLoggerToMcpOAuthLifecycleLogger({ ctx, logger });
}

export function createRequestContextLifecycleLogger(ctx: {
  infoUnrestricted: (obj: Record<string, unknown>, msg: string) => void;
  warnUnrestricted: (obj: Record<string, unknown>, msg: string) => void;
}): McpOAuthLifecycleLogger {
  return unrestrictedContextLoggerToMcpOAuthLifecycleLogger({ ctx });
}

export interface LoggedScopedMcpTokenStorageOptions {
  readonly identifier: string;
  readonly serverUrl?: string;
  readonly logger: McpOAuthLifecycleLogger;
  readonly inner: ScopedMcpTokenStorage;
}

export class LoggedScopedMcpTokenStorage implements ScopedMcpTokenStorage {
  constructor(private readonly options: LoggedScopedMcpTokenStorageOptions) {
    emitMcpOAuthLifecycleLog({
      logger: options.logger,
      event: "mcp_oauth_provider_initialized",
      metadata: this.baseMetadata,
    });
  }

  private get baseMetadata(): Record<string, unknown> {
    return {
      identifier: this.options.identifier,
      ...(this.options.serverUrl
        ? { serverUrl: snapshotServerUrlForLog(this.options.serverUrl) }
        : {}),
    };
  }

  async loadTokens(): Promise<OAuthTokens | undefined> {
    const tokens = await this.options.inner.loadTokens();
    emitMcpOAuthLifecycleLog({
      logger: this.options.logger,
      event: "mcp_oauth_tokens_loaded",
      level: "debug",
      metadata: {
        ...this.baseMetadata,
        ...buildOAuthTokensSnapshotForLog(tokens),
      },
    });
    return tokens;
  }

  async saveTokens(tokens: OAuthTokens): Promise<void> {
    await this.options.inner.saveTokens(tokens);
    emitMcpOAuthLifecycleLog({
      logger: this.options.logger,
      event: "mcp_oauth_tokens_saved",
      metadata: {
        ...this.baseMetadata,
        ...buildOAuthTokensSnapshotForLog(tokens, {
          expiresInIsFresh: true,
        }),
      },
    });
  }

  async prepareForRefresh(): Promise<void> {
    emitMcpOAuthLifecycleLog({
      logger: this.options.logger,
      event: "mcp_oauth_refresh_prepare",
      metadata: this.baseMetadata,
    });
    await this.options.inner.prepareForRefresh?.();
  }

  async releaseRefreshLeaseOnError(underlyingError?: unknown): Promise<void> {
    emitMcpOAuthLifecycleLog({
      logger: this.options.logger,
      event: "mcp_oauth_refresh_error_release",
      level: "warn",
      error: underlyingError,
      metadata: {
        ...this.baseMetadata,
        ...getMcpOAuthErrorLogMetadata(underlyingError),
      },
    });
    await this.options.inner.releaseRefreshLeaseOnError?.(underlyingError);
  }

  async loadClientInformation(): Promise<
    OAuthClientInformationFull | undefined
  > {
    const clientInformation = await this.options.inner.loadClientInformation();
    emitMcpOAuthLifecycleLog({
      logger: this.options.logger,
      event: "mcp_oauth_client_info_loaded",
      level: "debug",
      metadata: {
        ...this.baseMetadata,
        ...buildOAuthClientInformationSnapshotForLog(clientInformation),
      },
    });
    return clientInformation;
  }

  async saveClientInformation(
    clientInfo: OAuthClientInformationFull
  ): Promise<void> {
    await this.options.inner.saveClientInformation(clientInfo);
    emitMcpOAuthLifecycleLog({
      logger: this.options.logger,
      event: "mcp_oauth_client_info_saved",
      metadata: {
        ...this.baseMetadata,
        ...buildOAuthClientInformationSnapshotForLog(clientInfo),
      },
    });
  }

  async invalidateCredentials(
    scope: McpOAuthCredentialInvalidationScope
  ): Promise<void> {
    if (this.options.inner.invalidateCredentials === undefined) {
      return;
    }
    emitMcpOAuthLifecycleLog({
      logger: this.options.logger,
      event: "mcp_oauth_credentials_invalidated",
      level: "warn",
      metadata: {
        ...this.baseMetadata,
        scope,
      },
    });
    await this.options.inner.invalidateCredentials(scope);
  }
}

export class IdentifierScopedTokenStorage implements ScopedMcpTokenStorage {
  constructor(
    private readonly storage: McpTokenStorage,
    private readonly identifier: string
  ) {}

  async loadTokens(): Promise<OAuthTokens | undefined> {
    return this.storage.loadTokens(this.identifier);
  }

  async saveTokens(tokens: OAuthTokens): Promise<void> {
    return this.storage.saveTokens(this.identifier, tokens);
  }

  async loadClientInformation(): Promise<
    OAuthClientInformationFull | undefined
  > {
    return this.storage.loadClientInformation(this.identifier);
  }

  async saveClientInformation(
    clientInfo: OAuthClientInformationFull
  ): Promise<void> {
    return this.storage.saveClientInformation(this.identifier, clientInfo);
  }
}

export class NoOpScopedTokenStorage implements ScopedMcpTokenStorage {
  constructor(private readonly inner: ScopedMcpTokenStorage) {}

  async loadTokens(): Promise<OAuthTokens | undefined> {
    return undefined;
  }

  async loadClientInformation(): Promise<
    OAuthClientInformationFull | undefined
  > {
    return undefined;
  }

  async saveTokens(tokens: OAuthTokens): Promise<void> {
    return this.inner.saveTokens(tokens);
  }

  async saveClientInformation(
    clientInfo: OAuthClientInformationFull
  ): Promise<void> {
    return this.inner.saveClientInformation(clientInfo);
  }

  async invalidateCredentials(
    scope: McpOAuthCredentialInvalidationScope
  ): Promise<void> {
    await this.inner.invalidateCredentials?.(scope);
  }
}
