import { writeFileSync } from "node:fs";

/**
 * Best-effort reset of a spawned child's OOM badness adjustment back to the
 * kernel default (0).
 *
 * The exec-daemon launchers (sand/box/start-sand-box.sh for Sand boxes, the
 * cloud pod start command built in packages/agent-controller/src/podConfig.ts
 * for Cloud Agent VMs) boot the exec-daemon with oom_score_adj=-1000 so the
 * guest OOM killer never SIGKILLs the machine's only shell/exec surface.
 * Children inherit that on fork, so without this reset every PTY/exec/MCP
 * child would be unkillable too and the kernel would reap unrelated processes
 * instead of the agent's runaway command. Raising a same-uid child's score
 * needs no privilege (only lowering does).
 *
 * No-op on non-Linux (and on daemons booted at 0, where writing 0 changes
 * nothing); best-effort everywhere — the child may already have exited, and
 * protecting the daemon must never break spawning.
 */
export function resetChildOomScoreAdj(pid: number | undefined): void {
  if (process.platform !== "linux" || pid === undefined || pid <= 0) {
    return;
  }
  try {
    writeFileSync(`/proc/${pid}/oom_score_adj`, "0");
  } catch {
    // Best-effort by design; see the doc comment.
  }
}
