const CACHE_EXPIRY_MS = 5 * 60 * 1000; // 5 minutes
const BIGINT_ZERO = BigInt(0);
const BIGINT_EIGHT = BigInt(8);
const BIGINT_SIXTEEN = BigInt(16);
const IPV4_LOW_HEXTET_MASK = BigInt(0xffff);

type AllowedMcpConfiguration = NonNullable<
  GetTeamAdminSettingsResponse["allowedMcpConfiguration"]
>;

type AllowedMcpServerEntry = NonNullable<
  AllowedMcpConfiguration["allowedMcpServers"]
>[number];

type ParsedIpAddress =
  | { version: 4; value: bigint }
  | { version: 6; value: bigint };

function tryParseUrl(value: string): URL | undefined {
  const trimmed = value.trim();
  if (trimmed.length === 0) {
    return undefined;
  }

  const urlToParse = trimmed.includes("://") ? trimmed : `https://${trimmed}`;
  try {
    return new URL(urlToParse);
  } catch {
    return undefined;
  }
}

function stripMarkdownLink(value: string): string {
  const trimmed = value.trim();
  const startBracket = trimmed.indexOf("[");
  const endBracket = trimmed.indexOf("]");
  if (startBracket !== -1 && endBracket > startBracket) {
    const label = trimmed.slice(startBracket + 1, endBracket);
    if (trimmed.slice(endBracket + 1).startsWith("(")) {
      return `${trimmed.slice(0, startBracket)}${label}`;
    }
  }
  return trimmed;
}

function stripPort(value: string): string {
  if (value.startsWith("[")) {
    const endBracket = value.indexOf("]");
    if (endBracket !== -1) {
      return value.slice(1, endBracket);
    }
    return value;
  }

  const parts = value.split(":");
  if (parts.length === 2 && [...parts[1]].every(char => /\d/.test(char))) {
    return parts[0];
  }

  return value;
}

function normalizeHost(value: string): string {
  let normalized = value.trim().replace(/\.+$/, "").toLowerCase();
  if (normalized.startsWith("[")) {
    const endBracket = normalized.indexOf("]");
    if (endBracket !== -1) {
      normalized = normalized.slice(1, endBracket);
    }
  } else if (normalized.split(":").length - 1 === 1) {
    const lastColonIndex = normalized.lastIndexOf(":");
    const port = normalized.slice(lastColonIndex + 1);
    if ([...port].every(char => /\d/.test(char))) {
      normalized = normalized.slice(0, lastColonIndex);
    }
  }
  return normalized;
}

function tryParseIpv4(input: string): ParsedIpAddress | undefined {
  const parts = input.split(".");
  if (parts.length !== 4) {
    return undefined;
  }

  let value = BIGINT_ZERO;
  for (const part of parts) {
    if (!/^\d{1,3}$/.test(part)) {
      return undefined;
    }

    const octet = Number(part);
    if (!Number.isInteger(octet) || octet < 0 || octet > 255) {
      return undefined;
    }

    value = (value << BIGINT_EIGHT) | BigInt(octet);
  }

  return { version: 4, value };
}

function parseIpv6Groups(part: string): number[] | undefined {
  if (part.length === 0) {
    return [];
  }

  const groups: number[] = [];
  const segments = part.split(":");
  for (let index = 0; index < segments.length; index++) {
    const segment = segments[index];
    if (segment.length === 0) {
      return undefined;
    }

    if (segment.includes(".")) {
      if (index !== segments.length - 1) {
        return undefined;
      }

      const ipv4 = tryParseIpv4(segment);
      if (!ipv4) {
        return undefined;
      }

      groups.push(
        Number((ipv4.value >> BIGINT_SIXTEEN) & IPV4_LOW_HEXTET_MASK)
      );
      groups.push(Number(ipv4.value & IPV4_LOW_HEXTET_MASK));
      continue;
    }

    if (!/^[0-9a-f]{1,4}$/i.test(segment)) {
      return undefined;
    }

    groups.push(Number.parseInt(segment, 16));
  }

  return groups;
}

function tryParseIpv6(input: string): ParsedIpAddress | undefined {
  const normalized = normalizeHost(input);
  if (normalized.length === 0 || normalized.includes(":::")) {
    return undefined;
  }

  const doubleColonIndex = normalized.indexOf("::");
  if (doubleColonIndex === -1) {
    const groups = parseIpv6Groups(normalized);
    if (!groups || groups.length !== 8) {
      return undefined;
    }

    return {
      version: 6,
      value: groups.reduce(
        (acc, group) => (acc << BIGINT_SIXTEEN) | BigInt(group),
        BIGINT_ZERO
      ),
    };
  }

  if (normalized.indexOf("::", doubleColonIndex + 1) !== -1) {
    return undefined;
  }

  const leftGroups = parseIpv6Groups(normalized.slice(0, doubleColonIndex));
  const rightGroups = parseIpv6Groups(normalized.slice(doubleColonIndex + 2));
  if (!leftGroups || !rightGroups) {
    return undefined;
  }

  const totalGroups = leftGroups.length + rightGroups.length;
  if (totalGroups > 7) {
    return undefined;
  }

  const groups = [
    ...leftGroups,
    ...new Array(8 - totalGroups).fill(0),
    ...rightGroups,
  ];

  return {
    version: 6,
    value: groups.reduce(
      (acc, group) => (acc << BIGINT_SIXTEEN) | BigInt(group),
      BIGINT_ZERO
    ),
  };
}

function tryParseIpAddress(input: string): ParsedIpAddress | undefined {
  return tryParseIpv4(input) ?? tryParseIpv6(input);
}

function matchesCidrPattern(host: string, pattern: string): boolean {
  const slashIndex = pattern.lastIndexOf("/");
  if (slashIndex <= 0 || slashIndex === pattern.length - 1) {
    return false;
  }

  const network = tryParseIpAddress(pattern.slice(0, slashIndex));
  const hostIp = tryParseIpAddress(host);
  if (!network || !hostIp || network.version !== hostIp.version) {
    return false;
  }

  const prefixLength = Number(pattern.slice(slashIndex + 1));
  const totalBits = network.version === 4 ? 32 : 128;
  if (
    !Number.isInteger(prefixLength) ||
    prefixLength < 0 ||
    prefixLength > totalBits
  ) {
    return false;
  }

  const shift = BigInt(totalBits - prefixLength);
  return hostIp.value >> shift === network.value >> shift;
}

function matchesDomainPattern(domain: string, pattern: string): boolean {
  const normalizedDomain = normalizeHost(domain);
  const normalizedPattern = normalizeHost(pattern);

  if (normalizedPattern === "*") {
    return true;
  }

  if (normalizedPattern.includes("/")) {
    return matchesCidrPattern(normalizedDomain, normalizedPattern);
  }

  if (normalizedPattern.startsWith("*.")) {
    const suffix = normalizedPattern.slice(2);
    return (
      normalizedDomain === suffix || normalizedDomain.endsWith(`.${suffix}`)
    );
  }

  return normalizedDomain === normalizedPattern;
}

function normalizeServerUrlPattern(rawPattern: string): string | undefined {
  const rawValue = stripMarkdownLink(rawPattern).trim();
  if (rawValue.length === 0) {
    return undefined;
  }

  const cidrSlashIndex = rawValue.lastIndexOf("/");
  if (
    !rawValue.includes("://") &&
    cidrSlashIndex > 0 &&
    /^\d+$/.test(rawValue.slice(cidrSlashIndex + 1).trim())
  ) {
    const normalizedIp = normalizeHost(rawValue.slice(0, cidrSlashIndex));
    if (normalizedIp.length > 0) {
      return `${normalizedIp}/${rawValue.slice(cidrSlashIndex + 1).trim()}`;
    }
  }

  const parsed = tryParseUrl(rawValue);
  if (parsed) {
    return normalizeHost(parsed.hostname);
  }

  let value = rawValue;
  const schemeIndex = value.indexOf("://");
  if (schemeIndex !== -1) {
    value = value.slice(schemeIndex + 3);
  }

  const slashIndex = value.indexOf("/");
  if (slashIndex !== -1) {
    value = value.slice(0, slashIndex);
  }

  const normalized = normalizeHost(stripPort(value));
  if (normalized.length === 0) {
    return undefined;
  }

  if (normalized.startsWith("*.")) {
    const suffix = normalized.slice(2);
    if (suffix.length === 0 || suffix.includes("*") || suffix.includes("?")) {
      return undefined;
    }
    return normalized;
  }

  if (normalized.includes("*") || normalized.includes("?")) {
    return undefined;
  }

  return normalized;
}

function normalizeServerUrlHost(rawServerUrl: string): string | undefined {
  const parsed = tryParseUrl(rawServerUrl);
  if (parsed) {
    return normalizeHost(parsed.hostname);
  }

  const normalized = normalizeHost(rawServerUrl);
  return normalized.length > 0 ? normalized : undefined;
}

function matchesWildcardPattern(
  pattern: string,
  stringToMatch: string
): boolean {
  if (!pattern.includes("*")) {
    return pattern === stringToMatch;
  }

  const escapedPattern = pattern.replace(/[.+?^${}()|[\]\\]/g, "\\$&");
  const regexPattern = escapedPattern.replace(/\*/g, ".*");
  const regex = new RegExp(`^${regexPattern}$`);
  return regex.test(stringToMatch);
}

function matchesServerUrlPattern(pattern: string, serverUrl: string): boolean {
  if (matchesWildcardPattern(pattern, serverUrl)) {
    return true;
  }

  if (pattern.includes("://")) {
    let parsedPattern: URL;
    let parsedServerUrl: URL;
    try {
      parsedPattern = new URL(pattern);
      parsedServerUrl = new URL(serverUrl);
    } catch {
      return false;
    }

    if (
      parsedPattern.username !== "" ||
      parsedPattern.password !== "" ||
      parsedServerUrl.username !== "" ||
      parsedServerUrl.password !== "" ||
      parsedPattern.protocol !== parsedServerUrl.protocol ||
      parsedPattern.port !== parsedServerUrl.port
    ) {
      return false;
    }

    const normalizedPatternHost = normalizeHost(parsedPattern.hostname);
    const normalizedServerHost = normalizeHost(parsedServerUrl.hostname);
    if (!matchesDomainPattern(normalizedServerHost, normalizedPatternHost)) {
      return false;
    }

    return matchesWildcardPattern(
      `${parsedPattern.pathname}${parsedPattern.search}`,
      `${parsedServerUrl.pathname}${parsedServerUrl.search}`
    );
  }

  const normalizedPattern = normalizeServerUrlPattern(pattern);
  const normalizedServerHost = normalizeServerUrlHost(serverUrl);
  if (!normalizedPattern || !normalizedServerHost) {
    return false;
  }

  return matchesDomainPattern(normalizedServerHost, normalizedPattern);
}

export interface AutoRunControls {
  enabled: boolean;
  allowed: string[];
  blocked: string[];
  /**
   * When true (and enabled is true), allows "Allowlist" mode.
   * Defaults to enabled unless explicitly disabled by team policy.
   */
  enableAllowlistMode: boolean;
  /**
   * When true (and enabled is true), allows "Run Everything" mode where all
   * commands auto-run without approval. When false, admin has disabled this
   * option - used to enforce parity with IDE's "Enable Run Everything" team setting.
   */
  enableRunEverything: boolean;
  /**
   * When true (and enabled is true), allows "Auto-review" / smart_auto mode.
   * Defaults to enabled unless explicitly disabled by team policy.
   */
  enableSmartAuto: boolean;
  /** Admin-controlled MCP tool allowlist (server:tool format, e.g. "github:issue_write"). */
  mcpToolAllowlist: string[];
}

export interface McpToolControls {
  enabled: boolean;
  /**
   * Admin-controlled MCP tool allowlist normalized to the runtime matcher shape.
   * Per-server admin rows become `server:tool`, and a configured server with
   * an empty tool list becomes `server:*`.
   */
  mcpToolAllowlist: string[];
  /**
   * Mirrors the admin MCP server-extension setting for the existing wire shape.
   * Tool approval unioning is not currently implemented by permissions-service.
   */
  allowUserOverride: boolean;
}

export interface NetworkAccessControls {
  allowlist: string[];
  denylist: string[];
  /** False when the fetch threw → fail-closed. */
  available: boolean;
}

export interface DefaultNetworkAllowlist {
  allowlist: string[];
  /** False when fetch failed → use empty list (fail-closed). */
  available: boolean;
}

type FeatureGateCheckOptions = { disableExposureLog?: boolean };

export interface TeamSettingsServiceOptions {
  isMcpAccessNetworkAllowlistEnabled?: () =>
    | boolean
    | Promise<boolean>
    | PromiseLike<boolean>;
  isMcpSettingsOverhaulEnabled?: (
    options?: FeatureGateCheckOptions
  ) => boolean | Promise<boolean> | PromiseLike<boolean>;
  /**
   * Remote recovery lever (`admin_command_denylist_enforcement_killswitch`).
   * When it reports true, the distributed denylist carries no rules,
   * suspending enforcement everywhere downstream.
   */
  isAdminCommandDenylistEnforcementKilled?: () =>
    | boolean
    | Promise<boolean>
    | PromiseLike<boolean>;
}

export type McpServerBlockReason = "teamPolicy" | "teamNetworkAllowlist";

export interface McpServerBlockInfo {
  blocked: boolean;
  reason?: McpServerBlockReason;
  message?: string;
}

function getLegacyMcpServerNetworkAllowlistBlockInfo({
  isMcpAccessNetworkAllowlistEnabled,
  server,
  settings,
}: {
  isMcpAccessNetworkAllowlistEnabled: boolean;
  server: { command?: string; url?: string };
  settings: GetTeamAdminSettingsResponse | undefined;
}): McpServerBlockInfo {
  if (
    !isMcpAccessNetworkAllowlistEnabled ||
    settings?.allowedMcpConfiguration
      ?.requireMcpServersInTeamNetworkAllowlist !== true
  ) {
    return { blocked: false };
  }

  return getMcpServerTeamNetworkAllowlistBlockInfo({
    failOpenWhenEmpty: true,
    server,
    settings,
  });
}

function getMcpServerTeamNetworkAllowlistBlockInfo({
  failOpenWhenEmpty,
  server,
  settings,
}: {
  failOpenWhenEmpty: boolean;
  server: { command?: string; url?: string };
  settings: GetTeamAdminSettingsResponse | undefined;
}): McpServerBlockInfo {
  if (
    settings?.allowedMcpConfiguration
      ?.requireMcpServersInTeamNetworkAllowlist !== true ||
    server.url === undefined
  ) {
    return { blocked: false };
  }

  const networkAllowlist = (settings.networkAllowlist ?? [])
    .map(entry => entry.trim())
    .filter(entry => entry.length > 0);
  if (networkAllowlist.length === 0 && failOpenWhenEmpty) {
    return { blocked: false };
  }

  if (isUrlAllowedByPatterns(server.url, networkAllowlist)) {
    return { blocked: false };
  }
  return {
    blocked: true,
    reason: "teamNetworkAllowlist",
    message: "Not on the team network allowlist",
  };
}

function matchesWildcard(pattern: string, stringToMatch: string): boolean {
  if (!pattern.includes("*")) {
    return pattern === stringToMatch;
  }

  // Escape special regex characters except *
  const escapedPattern = pattern.replace(/[.+?^${}()|[\]\\]/g, "\\$&");
  const regexPattern = escapedPattern.replace(/\*/g, ".*");
  const regex = new RegExp(`^${regexPattern}$`);
  return regex.test(stringToMatch);
}

function getConfiguredMcpAllowlistField(
  value: string | undefined
): string | undefined {
  const trimmedValue = value?.trim();
  return trimmedValue && trimmedValue.length > 0 ? trimmedValue : undefined;
}

function matchesAllowedMcpServerEntry(
  serverEntry: AllowedMcpServerEntry,
  server: { command?: string; url?: string }
): boolean {
  const commandPattern = getConfiguredMcpAllowlistField(serverEntry.command);
  const serverUrlPattern = getConfiguredMcpAllowlistField(
    serverEntry.serverUrl
  );
  const hasCommandPattern = commandPattern !== undefined;
  const hasServerUrlPattern = serverUrlPattern !== undefined;

  if (!hasCommandPattern && !hasServerUrlPattern) {
    return false;
  }

  const passesCommandPolicy =
    commandPattern === undefined ||
    (server.command !== undefined &&
      matchesWildcard(commandPattern, server.command));
  const passesServerUrlPolicy =
    serverUrlPattern === undefined ||
    (server.url !== undefined &&
      matchesServerUrlPattern(serverUrlPattern, server.url));

  return passesCommandPolicy && passesServerUrlPolicy;
}

function isMcpServerBlockedByAdminPolicy(
  server: { command?: string; url?: string },
  allowedMCPConfig: AllowedMcpConfiguration | undefined,
  options?: { useCorePolicy?: boolean }
): boolean {
  if (options?.useCorePolicy === true) {
    return !isMcpServerAllowedByAdminPolicy(server, allowedMCPConfig);
  }
  if (allowedMCPConfig === undefined) {
    return false;
  }

  if (allowedMCPConfig.disableAll === true) {
    return true;
  }

  const allowedMcpServers = allowedMCPConfig.allowedMcpServers;
  if (allowedMcpServers.length === 0) {
    return false;
  }

  return !allowedMcpServers.some(serverEntry =>
    matchesAllowedMcpServerEntry(serverEntry, server)
  );
}

export interface TeamAdminSettingsProvider {
  getTeamAdminSettings(): Promise<GetTeamAdminSettingsResponse | undefined>;
  getTeamRepos(): Promise<GetTeamReposResponse | undefined>;
}

/**
 * Provides the server-controlled default network allowlist.
 * This is intentionally separate from TeamAdminSettingsProvider because
 * the data comes from a platform-specific config source (e.g. Statsig),
 * not from the dashboard RPC.
 */
export interface DefaultNetworkAllowlistProvider {
  getDefaultNetworkAllowlist(): Promise<string[]>;
}

export class ConnectTeamAdminSettingsProvider
  implements TeamAdminSettingsProvider
{
  constructor(
    private readonly dashboardClient: Client<typeof DashboardService>
  ) {}

  getTeamAdminSettings(): Promise<GetTeamAdminSettingsResponse | undefined> {
    return this.dashboardClient.getTeamAdminSettingsOrEmptyIfNotInTeam(
      new GetTeamAdminSettingsRequest({})
    );
  }

  getTeamRepos(): Promise<GetTeamReposResponse | undefined> {
    return this.dashboardClient.getTeamReposOrEmptyIfNotInTeam(
      new GetTeamReposRequest({})
    );
  }
}

/**
 * Admin "Agent Read Access" setting. The dashboard exposes System and
 * Workspace only, and the server already forces System when the feature gate
 * is off, so the client can take this value at face value.
 */
export type AdminSandboxReadBoundary = "system" | "workspace";

export interface SandboxingControls {
  /** True when admin has set sandboxing to DISABLED */
  sandboxingDisabled: boolean;
  /** True when admin has set sandboxNetworking to ALWAYS_DISABLED */
  networkingDisabled: boolean;
  /** True when admin has set sandboxGit to ALWAYS_DISABLED */
  gitDisabled: boolean;
  /**
   * Filesystem read boundary the admin requires. Absent means the settings
   * fetch produced no opinion, which is treated as System.
   */
  readBoundary?: AdminSandboxReadBoundary;
}

/**
 * Maps the dashboard read-boundary enum onto the two modes the client
 * enforces. CUSTOM is a legacy stored value that the portal no longer offers;
 * it fails closed to Workspace, matching the server's own normalization.
 */
export function adminSandboxReadBoundaryFromProto(
  mode: SandboxReadBoundaryMode | undefined
): AdminSandboxReadBoundary {
  return mode === SandboxReadBoundaryMode.WORKSPACE ||
    mode === SandboxReadBoundaryMode.CUSTOM
    ? "workspace"
    : "system";
}

/**
 * Hard admin command denylist loaded from
 * `GetTeamAdminSettingsResponse.autoRunControls.adminCommandDenylist`.
 *
 * Enforced in every approval mode (allowlist, unrestricted, Smart Mode ALLOW /
 * skipApproval); deliberately NOT gated on Auto-run being enabled.
 */
export interface AdminCommandDenylist {
  rules: string[];
}

export interface TeamSettingsService {
  getDotCursorProtection(): Promise<boolean>;
  getShouldBlockMcp(): Promise<boolean>;
  getDeleteFileProtection(): Promise<boolean>;
  getIsHeadlessDisabled(): Promise<boolean>;
  isServerBlocked(server: { command?: string; url?: string }): Promise<boolean>;
  getMcpServerBlockInfo?(server: {
    command?: string;
    url?: string;
  }): Promise<McpServerBlockInfo>;
  getAutoRunControls(): Promise<AutoRunControls | undefined>;
  /**
   * Loads the hard admin command denylist. See {@link AdminCommandDenylist}:
   * enforcement is not limited to Auto-review / Auto-run modes.
   */
  getAdminCommandDenylist(): Promise<AdminCommandDenylist>;
  getMcpToolControls(): Promise<McpToolControls | undefined>;
  getNetworkAccessControls(): Promise<NetworkAccessControls>;
  getMcpNetworkControlsConfig?(server?: {
    command?: string;
    url?: string;
  }): Promise<McpNetworkControlsConfig>;
  getDefaultNetworkAllowlist(): Promise<DefaultNetworkAllowlist>;
  getSandboxingControls(): Promise<SandboxingControls>;
  getTeamRepos(): Promise<GetTeamReposResponse | undefined>;
  isAttributionDisabledByAdmin(): Promise<boolean>;
  /**
   * Invalidates the cached settings, forcing the next call to getTeamAdminSettings()
   * to re-fetch from the server. Useful for tests that need to update settings
   * on a mock backend server.
   */
  invalidateCache(): void;
}

export type HeadlessCliPolicy =
  | { kind: "disabled" }
  | { kind: "enabled" }
  | { kind: "unavailable" };

export class CachedTeamSettingsService implements TeamSettingsService {
  private settingsPromise: Promise<GetTeamAdminSettingsResponse | undefined>;
  private teamReposPromise:
    | Promise<GetTeamReposResponse | undefined>
    | undefined;
  private defaultAllowlistPromise: Promise<DefaultNetworkAllowlist> | undefined;
  private lastFetchTime: number = 0;
  private lastReposFetchTime: number = 0;
  private lastDefaultAllowlistFetchTime: number = 0;
  private lastFetchSucceeded: boolean = true;

  constructor(
    private readonly teamAdminSettingsProvider: TeamAdminSettingsProvider,
    private readonly defaultAllowlistProvider?:
      | DefaultNetworkAllowlistProvider
      | undefined,
    private readonly options: TeamSettingsServiceOptions = {}
  ) {
    this.settingsPromise = this.fetchSettings();
  }

  /**
   * Invalidates the cached settings, forcing the next call to getTeamAdminSettings()
   * to re-fetch from the server. Useful for tests that need to update settings
   * on a mock backend server.
   */
  invalidateCache(): void {
    this.lastFetchTime = 0;
    this.lastDefaultAllowlistFetchTime = 0;
    this.defaultAllowlistPromise = undefined;
  }

  private async fetchSettings(): Promise<
    GetTeamAdminSettingsResponse | undefined
  > {
    this.lastFetchTime = Date.now();
    try {
      const settings =
        await this.teamAdminSettingsProvider.getTeamAdminSettings();
      this.lastFetchSucceeded = true;
      return settings;
    } catch (_error) {
      this.lastFetchSucceeded = false;
      return undefined;
    }
  }

  async getTeamAdminSettings(): Promise<
    GetTeamAdminSettingsResponse | undefined
  > {
    const now = Date.now();
    const isExpired = now - this.lastFetchTime > CACHE_EXPIRY_MS;

    if (isExpired || (await this.settingsPromise) === undefined) {
      this.settingsPromise = this.fetchSettings();
    }

    return this.settingsPromise;
  }

  async getDotCursorProtection(): Promise<boolean> {
    const settings = await this.getTeamAdminSettings();
    return settings?.dotCursorProtection ?? true;
  }

  async getShouldBlockMcp(): Promise<boolean> {
    const settings = await this.getTeamAdminSettings();
    if (
      settings?.autoRunControls?.enabled &&
      settings?.autoRunControls?.disableMcpAutoRun
    ) {
      return true;
    }
    return false;
  }

  async getDeleteFileProtection(): Promise<boolean> {
    const settings = await this.getTeamAdminSettings();
    if (
      settings?.autoRunControls?.enabled &&
      settings?.autoRunControls?.deleteFileProtection
    ) {
      return true;
    }
    return false;
  }

  // Fail-open when settings are unavailable (returns false). CLI-only gate in
  // agent-cli print mode; not server-side enforcement.
  async getIsHeadlessDisabled(): Promise<boolean> {
    return (await this.getHeadlessCliPolicy()).kind === "disabled";
  }

  async getHeadlessCliPolicy(): Promise<HeadlessCliPolicy> {
    const settings = await this.getTeamAdminSettings();
    if (settings === undefined && !this.lastFetchSucceeded) {
      return { kind: "unavailable" };
    }
    return settings?.cliSettings?.disableHeadless === true
      ? { kind: "disabled" }
      : { kind: "enabled" };
  }

  async getMcpServerBlockInfo(server: {
    command?: string;
    url?: string;
  }): Promise<McpServerBlockInfo> {
    const settings = await this.getTeamAdminSettings();
    const allowedMCPConfig: AllowedMcpConfiguration | undefined =
      settings?.allowedMcpConfiguration;
    const overhaulEnabled = await this.isMcpSettingsOverhaulEnabled({
      disableExposureLog: true,
    });

    if (allowedMCPConfig?.disableAll === true) {
      return {
        blocked: true,
        reason: "teamPolicy",
        message: "Blocked by team policy",
      };
    }

    if (overhaulEnabled) {
      if (
        isMcpServerBlockedByAdminPolicy(server, allowedMCPConfig, {
          useCorePolicy: true,
        })
      ) {
        return {
          blocked: true,
          reason: "teamPolicy",
          message: "Blocked by team policy",
        };
      }

      // MCP network-controls preflight: intercepts outbound fetches and
      // sandboxes local MCP subprocesses against the per-MCP Network Allowlist.
      const config = await this.getMcpNetworkControlsConfig(server);
      const result =
        server.url === undefined
          ? { allowed: true as const }
          : checkMcpNetworkUrl(server.url, config);
      if (!result.allowed) {
        return {
          blocked: true,
          reason: "teamNetworkAllowlist",
          message: result.message,
        };
      }
      const teamNetworkAllowlistBlockInfo =
        getMcpServerTeamNetworkAllowlistBlockInfo({
          failOpenWhenEmpty: false,
          server,
          settings,
        });
      if (teamNetworkAllowlistBlockInfo.blocked) {
        return teamNetworkAllowlistBlockInfo;
      }
    } else {
      // Pre-overhaul behavior only: the legacy Statsig gate can enforce the team
      // network allowlist, and admin MCP controls are ignored.
    }

    if (!overhaulEnabled) {
      const legacyNetworkAllowlistBlockInfo =
        getLegacyMcpServerNetworkAllowlistBlockInfo({
          isMcpAccessNetworkAllowlistEnabled:
            await this.isMcpAccessNetworkAllowlistEnabled(),
          server,
          settings,
        });
      if (legacyNetworkAllowlistBlockInfo.blocked) {
        return legacyNetworkAllowlistBlockInfo;
      }
    }

    return { blocked: false };
  }

  async getMcpNetworkControlsConfig(server?: {
    command?: string;
    url?: string;
  }): Promise<McpNetworkControlsConfig> {
    const settings = await this.getTeamAdminSettings();
    const allowedMCPConfig: AllowedMcpConfiguration | undefined =
      settings?.allowedMcpConfiguration;
    // Adapter boundary: local-exec knows how to read team settings, while
    // mcp-agent-exec owns matching and runtime enforcement.
    const overhaulEnabled = await this.isMcpSettingsOverhaulEnabled();
    if (overhaulEnabled) {
      return resolveMcpNetworkControlsConfigFromAdminPolicy({
        allowedMcpConfiguration: allowedMCPConfig,
        server,
        localAgentNetworkAllowlist: settings?.networkAllowlist,
        blockMessage: "Not on the team network allowlist",
        aggregateManagedServerNetworkAllowlists: false,
      });
    }

    // Pre-overhaul behavior: no admin MCP network controls.
    return {
      enabled: false,
      localAgentNetworkAllowlist: settings?.networkAllowlist,
      blockMessage: "Not on the team network allowlist",
    };
  }

  async isServerBlocked(server: {
    command?: string;
    url?: string;
  }): Promise<boolean> {
    return (await this.getMcpServerBlockInfo(server)).blocked;
  }

  async getAutoRunControls(): Promise<AutoRunControls | undefined> {
    const settings = await this.getTeamAdminSettings();
    // Only return controls if explicitly enabled.
    // The autoRunControls object may exist with stale data (e.g., allowed: ["pwd"])
    // from when it was previously enabled, but if enabled is not true, we should
    // treat it as if there are no admin controls (return undefined).
    if (!settings?.autoRunControls?.enabled) {
      return undefined;
    }

    return {
      enabled: settings.autoRunControls.enabled,
      allowed: settings.autoRunControls.allowed ?? [],
      blocked: settings.autoRunControls.blocked ?? [],
      enableAllowlistMode: settings.autoRunControls.enableAllowlistMode ?? true,
      enableRunEverything:
        settings.autoRunControls.enableRunEverything ?? false,
      enableSmartAuto: settings.autoRunControls.enableSmartAuto ?? true,
      mcpToolAllowlist: settings.autoRunControls.mcpToolAllowlist ?? [],
    };
  }

  private async isDenylistEnforcementKilled(): Promise<boolean> {
    try {
      return (
        (await this.options.isAdminCommandDenylistEnforcementKilled?.()) ===
        true
      );
    } catch {
      // A failing gate read must not suspend enforcement.
      return false;
    }
  }

  async getAdminCommandDenylist(): Promise<AdminCommandDenylist> {
    // Checked before the settings await so the recovery lever works even
    // when the settings fetch itself is stalling shell commands.
    if (await this.isDenylistEnforcementKilled()) {
      return { rules: [] };
    }
    const settings = await this.getTeamAdminSettings();
    // Reads the same TTL-cached settings as every other admin control. A
    // fetch failure yields no rules until a later read succeeds (accepted
    // fail-open, consistent with the cold-start behavior); the fetch is
    // retried on every read while the cached result is undefined.
    return {
      rules: settings?.autoRunControls?.adminCommandDenylist?.rules ?? [],
    };
  }

  private async isMcpSettingsOverhaulEnabled(
    options?: FeatureGateCheckOptions
  ): Promise<boolean> {
    const enabled = this.options.isMcpSettingsOverhaulEnabled?.(options);
    if (enabled === undefined) {
      return false;
    }
    return await enabled;
  }

  async getMcpToolControls(): Promise<McpToolControls | undefined> {
    const settings = await this.getTeamAdminSettings();
    const allowedMCPConfig: AllowedMcpConfiguration | undefined =
      settings?.allowedMcpConfiguration;

    if (allowedMCPConfig === undefined) {
      return undefined;
    }

    const mcpToolAllowlist = resolveAdminMcpToolAllowlist({
      // The resolver flattens per-server policy into the `server:tool` matcher
      // input used by permissions-service. A configured server with an empty
      // tool list becomes `server:*`; an unconfigured/blank team policy stays
      // empty, which means there is no admin tool owner and personal approvals
      // apply.
      autoRunControls: settings?.autoRunControls,
      allowedMcpServers: allowedMCPConfig?.allowedMcpServers,
      isMcpSettingsOverhaulEnabled: true,
    });
    if (mcpToolAllowlist.length === 0) {
      return undefined;
    }

    return {
      enabled: true,
      mcpToolAllowlist,
      allowUserOverride: allowedMCPConfig?.allowUserOverrideMcpServers ?? false,
    };
  }

  async getNetworkAccessControls(): Promise<NetworkAccessControls> {
    const settings = await this.getTeamAdminSettings();
    if (settings === undefined && !this.lastFetchSucceeded) {
      return { allowlist: [], denylist: [], available: false };
    }
    return {
      allowlist: settings?.networkAllowlist ?? [],
      denylist: settings?.networkDenylist ?? [],
      available: true,
    };
  }

  async getSandboxingControls(): Promise<SandboxingControls> {
    const settings = await this.getTeamAdminSettings();
    const controls = settings?.autoRunControls?.sandboxingControls;
    return {
      sandboxingDisabled: controls?.sandboxing === SandboxingMode.DISABLED,
      networkingDisabled:
        controls?.sandboxNetworking === NetworkingMode.ALWAYS_DISABLED,
      gitDisabled: controls?.sandboxGit === GitMode.ALWAYS_DISABLED,
      readBoundary: adminSandboxReadBoundaryFromProto(
        controls?.sandboxReadBoundary
      ),
    };
  }

  async isAttributionDisabledByAdmin(): Promise<boolean> {
    const settings = await this.getTeamAdminSettings();
    if (settings === undefined && !this.lastFetchSucceeded) {
      return true;
    }
    return (
      (
        settings as
          | {
              attributionControls?: { disableAttribution?: boolean };
            }
          | undefined
      )?.attributionControls?.disableAttribution ?? false
    );
  }

  async getDefaultNetworkAllowlist(): Promise<DefaultNetworkAllowlist> {
    const now = Date.now();
    if (
      !this.defaultAllowlistPromise ||
      now - this.lastDefaultAllowlistFetchTime > CACHE_EXPIRY_MS
    ) {
      this.lastDefaultAllowlistFetchTime = now;
      this.defaultAllowlistPromise = this.fetchDefaultAllowlist();
    }
    return this.defaultAllowlistPromise;
  }

  private async fetchDefaultAllowlist(): Promise<DefaultNetworkAllowlist> {
    if (!this.defaultAllowlistProvider) {
      return { allowlist: [], available: true };
    }
    try {
      const allowlist =
        await this.defaultAllowlistProvider.getDefaultNetworkAllowlist();
      return { allowlist, available: true };
    } catch {
      // Fail-closed: return empty list, commands run without default domains
      return { allowlist: [], available: false };
    }
  }

  getTeamRepos(): Promise<GetTeamReposResponse | undefined> {
    const now = Date.now();
    if (
      !this.teamReposPromise ||
      now - this.lastReposFetchTime > CACHE_EXPIRY_MS
    ) {
      this.teamReposPromise = this.teamAdminSettingsProvider.getTeamRepos();
      this.lastReposFetchTime = now;
    }

    const teamReposPromise = this.teamReposPromise;
    return teamReposPromise.catch(error => {
      if (this.teamReposPromise === teamReposPromise) {
        this.teamReposPromise = undefined;
      }
      throw error;
    });
  }

  private async isMcpAccessNetworkAllowlistEnabled(): Promise<boolean> {
    return (await this.options.isMcpAccessNetworkAllowlistEnabled?.()) ?? false;
  }
}
