import {
  catchError,
  defer,
  filter,
  firstValueFrom,
  from,
  lastValueFrom,
  map,
  materialize,
  mergeAll,
  mergeMap,
  type Observable,
  of,
  reduce,
  retry,
  Subject,
  type Subscription,
  share,
  throwError,
  timeout,
} from "rxjs";

/**
 * Map over an array with a promise-returning function, and return a map of the results.
 *
 * @param array - The array to map over
 * @param selector - The function to map over the array
 * @param options - Options for the operation
 * @param options.max - The maximum number of concurrent operations
 * @returns A map of the array with the results of the selector
 */
export function asyncMap<T, TRet>(
  array: T[],
  selector: (x: T) => Promise<TRet>,
  options?: { max?: number }
): Promise<Map<T, TRet>> {
  const { max = 4 } = options ?? {};
  const promiseSelToObs = (k: T) =>
    defer(() => from(selector(k)).pipe(map(v => ({ k, v }))));

  const ret = from(array).pipe(
    map(promiseSelToObs),
    mergeAll(max),
    reduce<{ k: T; v: TRet }, Map<T, TRet>>((acc, kvp) => {
      acc.set(kvp.k, kvp.v);
      return acc;
    }, new Map())
  );

  return firstValueFrom(ret);
}

/**
 * Map over an array with a promise-returning function, and return an array of the values,
 * maintaining the order of the original array. This is most useful when replacing Promise.all,
 * since it guarantees the order of the results.
 *
 * @param array - The array to map over
 * @param selector - The function to map over the array
 * @param options - Options for the operation
 * @param options.max - The maximum number of concurrent operations
 * @returns An array of the results of the selector
 */
export async function asyncMapValues<T, TRet>(
  array: T[],
  selector: (x: T) => Promise<TRet>,
  options?: { max?: number }
): Promise<TRet[]> {
  const { max = 4 } = options ?? {};

  const promiseSelToObs = (idx: number) =>
    defer(() => from(selector(array[idx])).pipe(map(v => ({ idx, v }))));

  const ret = from(array.map((_, idx) => idx)).pipe(
    map(promiseSelToObs),
    mergeAll(max),
    reduce<{ idx: number; v: TRet }, TRet[]>((acc, kvp) => {
      acc[kvp.idx] = kvp.v;
      return acc;
    }, [])
  );

  return firstValueFrom(ret);
}

/**
 * Map over an array with a promise-returning function, and return a map of settled results.
 * Similar to Promise.allSettled, but with concurrency control and returns a Map.
 *
 * @param array - The array to map over
 * @param selector - The function to map over the array
 * @param options - Options for the operation
 * @param options.max - The maximum number of concurrent operations
 * @returns A map of the array with settled results (fulfilled or rejected)
 */
export function asyncMapSettled<T, TRet>(
  array: T[],
  selector: (x: T) => Promise<TRet>,
  options?: { max?: number }
): Promise<Map<T, PromiseSettledResult<TRet>>> {
  const { max = 4 } = options ?? {};
  const promiseSelToObs = (k: T) =>
    defer(() =>
      from(selector(k)).pipe(
        map((v): { k: T; result: PromiseSettledResult<TRet> } => ({
          k,
          result: { status: "fulfilled" as const, value: v },
        })),
        catchError(
          (reason): Observable<{ k: T; result: PromiseSettledResult<TRet> }> =>
            of({
              k,
              result: { status: "rejected" as const, reason },
            })
        )
      )
    );

  const ret = from(array).pipe(
    map(promiseSelToObs),
    mergeAll(max),
    reduce<
      { k: T; result: PromiseSettledResult<TRet> },
      Map<T, PromiseSettledResult<TRet>>
    >((acc, kvp) => {
      acc.set(kvp.k, kvp.result);
      return acc;
    }, new Map())
  );

  return firstValueFrom(ret);
}

/**
 * Map over an array with a promise-returning function, and return an array of settled results.
 * Similar to Promise.allSettled, but with concurrency control
 *
 * @param array - The array to map over
 * @param selector - The function to map over the array
 * @param options - Options for the operation
 * @param options.max - The maximum number of concurrent operations
 * @returns An array of settled results (fulfilled or rejected)
 */
export function asyncMapSettledValues<T, TRet>(
  array: T[],
  selector: (x: T) => Promise<TRet>,
  options?: { max?: number }
): Promise<PromiseSettledResult<TRet>[]> {
  const { max = 4 } = options ?? {};

  const promiseSelToObs = (idx: number) =>
    defer(() =>
      from(selector(array[idx])).pipe(
        map((v): { idx: number; result: PromiseSettledResult<TRet> } => ({
          idx,
          result: { status: "fulfilled" as const, value: v },
        })),
        catchError(
          (
            reason
          ): Observable<{ idx: number; result: PromiseSettledResult<TRet> }> =>
            of({
              idx,
              result: { status: "rejected" as const, reason },
            })
        )
      )
    );

  const ret = from(array.map((_, idx) => idx)).pipe(
    map(promiseSelToObs),
    mergeAll(max),
    reduce<
      { idx: number; result: PromiseSettledResult<TRet> },
      PromiseSettledResult<TRet>[]
    >((acc, kvp) => {
      acc[kvp.idx] = kvp.result;
      return acc;
    }, [])
  );

  return firstValueFrom(ret);
}

/**
 * Reduce over an array with a promise-returning function, and return the reduced value.
 *
 * @param array - The array to reduce over
 * @param selector - The function to reduce over the array
 * @param seed - The initial value of the reduction
 * @returns The reduced value
 */
export async function asyncReduce<T, TAcc>(
  array: T[],
  selector: (acc: TAcc, x: T) => Promise<TAcc>,
  seed: TAcc
): Promise<TAcc> {
  let acc = seed;
  for (const x of array) {
    acc = await selector(acc, x);
  }

  return acc;
}

/**
 * Delay for a given number of milliseconds.
 *
 * @param ms - The number of milliseconds to delay
 * @returns A promise that resolves after the given number of milliseconds
 */
export function delay(ms: number): Promise<void> {
  return new Promise<void>(resolve => {
    setTimeout(resolve, ms);
  });
}

/**
 * Wraps a promise with a timeout. If the promise doesn't resolve within the specified timeout,
 * the returned promise will reject with a TimeoutError.
 *
 * @param promise The promise to wrap with a timeout
 * @param timeoutMs The timeout duration in milliseconds
 * @param errorMessage Optional custom error message
 * @returns A new promise that will resolve with the original promise's result or reject with a TimeoutError
 */
export class TimeoutError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "TimeoutError";
  }
}

/**
 * Wraps a promise with a timeout. If the promise doesn't resolve within the specified timeout,
 * the returned promise will reject with a TimeoutError.
 *
 * @param promise The promise to wrap with a timeout
 * @param timeoutMs The timeout duration in milliseconds
 * @param errorMessage Optional custom error message
 * @returns A new promise that will resolve with the original promise's result or reject with a TimeoutError
 */
export function withTimeout<T>(
  promise: Promise<T>,
  timeoutMs: number,
  message?: string
): Promise<T> {
  return firstValueFrom(
    from(promise).pipe(
      timeout({
        first: timeoutMs,
        with: () =>
          throwError(
            () =>
              new TimeoutError(
                message ?? `Promise timed out after ${timeoutMs}ms`
              )
          ),
      })
    )
  );
}

/**
 * Runs an operation with a timeout signal. When the timeout elapses, aborts and
 * waits for the operation to settle before rejecting so callers can safely
 * clean up resources the operation was using. The operation must propagate the
 * signal; one that ignores cancellation can keep this helper pending.
 */
export async function withAbortableTimeout<T>(
  operation: (signal: AbortSignal) => Promise<T>,
  timeoutMs: number,
  message?: string
): Promise<T> {
  const controller = new AbortController();
  const timeoutError = new TimeoutError(
    message ?? `Operation timed out after ${timeoutMs}ms`
  );
  const operationPromise = Promise.resolve().then(() =>
    operation(controller.signal)
  );
  let timeoutId: ReturnType<typeof setTimeout> | undefined;
  const timeoutPromise = new Promise<never>((_, reject) => {
    timeoutId = setTimeout(() => {
      controller.abort(timeoutError);
      reject(timeoutError);
    }, timeoutMs);
    timeoutId.unref?.();
  });

  try {
    return await Promise.race([operationPromise, timeoutPromise]);
  } catch (error) {
    if (controller.signal.reason !== timeoutError) {
      throw error;
    }
    await operationPromise.catch(() => undefined);
    throw timeoutError;
  } finally {
    if (timeoutId !== undefined) {
      clearTimeout(timeoutId);
    }
  }
}

/**
 * Retry a promise-returning function a given number of times.
 *
 * @param func The function to retry
 * @param retries The number of times to retry
 * @returns A promise that will resolve with the result of the function
 */
export function retryPromise<T>(
  func: () => Promise<T>,
  retries = 3
): Promise<T> {
  const ret = defer(() => from(func())).pipe(retry(retries));

  return firstValueFrom(ret);
}

type Operation<T> = {
  id: number;
  result?: T;
  error?: unknown;
};

/**
 * A queue that limits the number of concurrent operations.
 *
 * @param T - The type of the result of the operations
 */
export class PromiseQueue {
  private readonly opQueue: Subject<Observable<Operation<unknown>>> =
    new Subject();
  private readonly opResultStream: Observable<Operation<unknown>>;
  private nextOperation: number = 1;
  private dispose: Subscription;

  /**
   * Creates a new PromiseQueue.
   *
   * @param options - Options for the operation
   * @param options.max - The maximum number of concurrent operations
   */
  constructor(options?: { max?: number }) {
    const { max = 4 } = options ?? {};

    this.opResultStream = this.opQueue.pipe(
      mergeAll(max) /* NB: Debugging this? uncomment: , tap({
      next: (op) => {
        console.log("next", op);
      },
      error: (e) => {
        console.error("error", e);
      },
      complete: () => {
        console.log("complete");
      },
    })*/,
      share()
    );

    this.dispose = this.opResultStream.subscribe();
  }

  /**
   * Enqueue a new operation.
   *
   * @param block - The function to enqueue
   * @returns A promise that will resolve with the result of the operation
   */
  public enqueue<T>(block: () => Promise<T>): Promise<T> {
    const id = this.nextOperation++;
    const op = defer(() =>
      from(block()).pipe(
        map(v => ({ id, result: v })),
        catchError(e => of({ id, error: e }))
      )
    );

    const ret = firstValueFrom(
      this.opResultStream.pipe(filter(op => op.id === id))
    ).then(e => {
      if (e.error) {
        return Promise.reject<T>(e.error);
      } else {
        return Promise.resolve<T>(e.result! as T);
      }
    });

    this.opQueue.next(op);
    return ret;
  }

  /**
   * Enqueue a list of operations.
   *
   * @param list - The list of items to enqueue
   * @param block - The function to enqueue
   * @returns A promise that will resolve with the result of the operation
   */
  public enqueueList<TList, TRet>(
    list: TList[],
    block: (item: TList) => Promise<TRet>
  ): Promise<Map<TList, TRet>> {
    if (list.length === 0) {
      return Promise.resolve(new Map());
    }

    return firstValueFrom(
      from(list).pipe(
        mergeMap(x =>
          this.enqueue(() => block(x)).then(v => ({ key: x, value: v }))
        ),
        reduce(
          (acc, kvp) => {
            acc.set(kvp.key, kvp.value);
            return acc;
          },
          new Map() as Map<TList, TRet>
        )
      )
    );
  }

  /**
   * Close the queue and wait for all operations to complete. Once this is called,
   * the object is no longer usable.
   *
   * @returns A promise that will resolve when the queue is closed
   */
  public close(): Promise<void> {
    this.opQueue.complete();

    const ret = lastValueFrom(
      this.opResultStream.pipe(
        materialize(),
        map(() => undefined)
      )
    );
    this.dispose.unsubscribe();

    return ret;
  }
}
