import { SimpleControlledExecHandler } from "./controlled.js";
import { ExecutorResource } from "./remote.js";
import { createResource, } from "./resource-provider.js";
import { createClientDeserializer, createClientSerializer, createServerDeserializer, createServerSerializer, } from "./serialization.js";
export const adoptExecutorResource = createResource(execManager => new ExecutorResource(execManager, createServerSerializer("adoptArgs"), createClientDeserializer("adoptResult")), (implementation, controlledExecManager) => {
    controlledExecManager.register(new SimpleControlledExecHandler(implementation, createServerDeserializer("adoptArgs"), createClientSerializer("adoptResult")));
});
