import { SimpleControlledExecHandler } from "./controlled.js";
import { ExecutorResource } from "./remote.js";
import { createResource } from "./resource-provider.js";
import { createClientDeserializer, createClientSerializer, createServerDeserializer, createServerSerializer, } from "./serialization.js";
export const piEditExecutorResource = createResource(execManager => new ExecutorResource(execManager, createServerSerializer("piEditArgs"), createClientDeserializer("piEditResult")), (implementation, controlledExecManager) => {
    controlledExecManager.register(new SimpleControlledExecHandler(implementation, createServerDeserializer("piEditArgs"), createClientSerializer("piEditResult")));
});
