import { normalizeMcpServerUrl } from '../transport/mcp-url-utils.js';

export const MCP_OAUTH_SESSION_KEYS = {
	CODE_VERIFIER: 'mcp_code_verifier',
	SERVER_URL: 'mcp_server_url',
	TOKENS: 'mcp_tokens',
	CLIENT_INFORMATION: 'mcp_client_information',
	OAUTH_RETENTION: 'mcp_oauth_retention',
	OAUTH_ATTEMPT: 'mcp_oauth_attempt',
	OAUTH_ATTEMPT_CLIENT_SECRET: 'mcp_oauth_attempt_client_secret',
	UPDATED_AT: 'mcp_oauth_updated_at_ms',
};

export function base64UrlEncode(value: string): string {
	const bytes = new TextEncoder().encode(value);
	let binary = '';
	for (const byte of bytes) {
		binary += String.fromCharCode(byte);
	}
	const base64 = typeof btoa === 'function'
		? btoa(binary)
		: Buffer.from(bytes).toString('base64');
	return base64.replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/u, '');
}

export function base64UrlDecode(value: string): string {
	const paddedValue = value.padEnd(Math.ceil(value.length / 4) * 4, '=').replace(/-/g, '+').replace(/_/g, '/');
	const binary = typeof atob === 'function'
		? atob(paddedValue)
		: Buffer.from(paddedValue, 'base64').toString('binary');
	const bytes = Uint8Array.from(binary, char => char.charCodeAt(0));
	return new TextDecoder().decode(bytes);
}

export function getMcpOAuthServerSpecificKey({ baseKey, identifier }: { baseKey: string; identifier: string }): string {
	return `[${identifier}] ${baseKey}`;
}

export function getMcpOAuthCanonicalServerUrlKey({ baseKey, serverUrl }: { baseKey: string; serverUrl: string }): string {
	const canonicalServerUrl = normalizeMcpServerUrl(serverUrl);
	return `[url:${base64UrlEncode(canonicalServerUrl)}] ${baseKey}`;
}

export function getMcpOAuthAttemptKey(attemptId: string): string {
	return `[oauth-attempt:${attemptId}] ${MCP_OAUTH_SESSION_KEYS.OAUTH_ATTEMPT}`;
}

export function getMcpOAuthAttemptClientSecretKey(attemptId: string): string {
	return `[oauth-attempt:${attemptId}] ${MCP_OAUTH_SESSION_KEYS.OAUTH_ATTEMPT_CLIENT_SECRET}`;
}

export function getMcpOAuthAttemptCodeVerifierKey(attemptId: string): string {
	return `[oauth-attempt:${attemptId}] ${MCP_OAUTH_SESSION_KEYS.CODE_VERIFIER}`;
}
