import * as sfs from "node:fs";
import * as path from "node:path";
import { LRUCache } from "./lru-cache.js";

const isWindows =
  typeof process !== "undefined" && process.platform === "win32";

const runDownPathCache = new LRUCache<string, string>({ max: 512 });

/**
 * stat a file but don't throw if it doesn't exist
 *
 * @param  {string} file The path to a file
 * @return {Stats}       The stats structure
 *
 * @private
 */
function statSyncNoException(file: string): sfs.Stats | null {
  try {
    // turbopackIgnore: this is a runtime PATH lookup over arbitrary executable
    // names. Without the ignore, Turbopack's NFT can't resolve the dynamic path
    // and conservatively traces the entire project into any serverless function
    // that transitively imports this module (via the @anysphere/utils barrel),
    // blowing past Vercel's 250 MB limit. See vercel/next.js#78460.
    return sfs.statSync(/* turbopackIgnore: true */ file);
  } catch {
    return null;
  }
}

/**
 * Search PATH to see if a file exists in any of the path folders.
 *
 * @param  {string} exe The file to search for
 * @return {string}     A fully qualified path, or the original path if nothing
 *                      is found
 *
 * @private
 */
function runDownPath(exe: string, pathMustMatch?: RegExp): string {
  // NB: Windows won't search PATH looking for executables in spawn like
  // Posix does

  // Files with any directory path don't get this applied
  if (exe.match(/[\\/]/)) {
    return exe;
  }

  const cacheKey = pathMustMatch
    ? `${exe}\0${pathMustMatch.source}\0${pathMustMatch.flags}`
    : exe;
  const cached = runDownPathCache.get(cacheKey);
  if (cached !== undefined) {
    return cached;
  }

  const target = path.join(/* turbopackIgnore: true */ ".", exe);
  if (statSyncNoException(target)) {
    // XXX: Some very Odd programs decide to use args[0] as a parameter
    // to determine what to do, and also symlink themselves, so we can't
    // use realpathSync here like we used to
    runDownPathCache.set(cacheKey, target);
    return target;
  }

  const haystack = process.env.PATH!.split(isWindows ? ";" : ":");
  for (const p of haystack) {
    const needle = path.join(/* turbopackIgnore: true */ p, exe);
    if (
      statSyncNoException(needle) &&
      (!pathMustMatch || pathMustMatch.test(needle))
    ) {
      // NB: Same deal as above
      runDownPathCache.set(cacheKey, needle);
      return needle;
    }
  }

  runDownPathCache.set(cacheKey, exe);
  return exe;
}

/**
 * Finds the actual executable and parameters to run on Windows. This method
 * mimics the POSIX behavior of being able to run scripts as executables by
 * replacing the passed-in executable with the script runner, for PowerShell,
 * CMD, and node scripts.
 *
 * This method also does the work of running down PATH, which spawn on Windows
 * also doesn't do, unlike on POSIX.
 *
 * @param  {string} exe           The executable to run
 * @param  {string[]} args   The arguments to run
 *
 * @return {Object}               The cmd and args to run
 * @property {string} cmd         The command to pass to spawn
 * @property {string[]} args The arguments to pass to spawn
 */
export function findActualExecutable(
  exe: string,
  args: string[],
  pathMustMatch?: RegExp
): {
  cmd: string;
  args: string[];
} {
  // POSIX can just execute scripts directly, no need for silly goosery
  if (process.platform !== "win32") {
    return { cmd: runDownPath(exe), args: args };
  }

  if (!sfs.existsSync(/* turbopackIgnore: true */ exe)) {
    // NB: When you write something like `surf-client ... -- surf-build` on Windows,
    // a shell would normally convert that to surf-build.cmd, but since it's passed
    // in as an argument, it doesn't happen
    const possibleExts = [".exe", ".bat", ".cmd", ".ps1"];

    // If the exe already has a known extension, try to find it in PATH first
    // before attempting to append additional extensions
    const exeLower = exe.toLowerCase();
    if (possibleExts.some(ext => exeLower.endsWith(ext))) {
      const resolvedPath = runDownPath(exe, pathMustMatch);
      if (sfs.existsSync(/* turbopackIgnore: true */ resolvedPath)) {
        return findActualExecutable(resolvedPath, args, pathMustMatch);
      }
    }

    // Try appending extensions to find the executable
    for (const ext of possibleExts) {
      const possibleFullPath = runDownPath(`${exe}${ext}`, pathMustMatch);

      if (sfs.existsSync(/* turbopackIgnore: true */ possibleFullPath)) {
        return findActualExecutable(possibleFullPath, args, pathMustMatch);
      }
    }
  }

  if (exe.match(/\.ps1$/i)) {
    const cmd = path.join(
      /* turbopackIgnore: true */ process.env.SYSTEMROOT!,
      "System32",
      "WindowsPowerShell",
      "v1.0",
      "PowerShell.exe"
    );
    const psargs = [
      "-ExecutionPolicy",
      "Unrestricted",
      "-NoLogo",
      "-NonInteractive",
      "-File",
      exe,
    ];

    return { cmd: cmd, args: psargs.concat(args) };
  }

  if (exe.match(/\.(bat|cmd)$/i)) {
    const cmd = path.join(
      /* turbopackIgnore: true */ process.env.SYSTEMROOT!,
      "System32",
      "cmd.exe"
    );
    const cmdArgs = ["/C", exe, ...args];

    return { cmd: cmd, args: cmdArgs };
  }

  if (exe.match(/\.(js)$/i)) {
    const cmd = process.execPath;
    const nodeArgs = [exe];

    return { cmd: cmd, args: nodeArgs.concat(args) };
  }

  // Dunno lol
  return { cmd: exe, args: args };
}
