import type { ChildProcess } from "node:child_process";
import { execFile, spawn } from "node:child_process";
import * as fs from "node:fs/promises";
import * as path from "node:path";
import { promisify } from "node:util";
import type { RecordScreenExecutor } from "@anysphere/agent-exec";
import { type Context, createSpan } from "@anysphere/context";
import {
  RecordingMode,
  type RecordScreenArgs,
  RecordScreenDiscardSuccess,
  RecordScreenFailure,
  RecordScreenResult,
  RecordScreenSaveSuccess,
  RecordScreenStartSuccess,
  RequestedFilePathRejectedReason,
} from "@anysphere/proto/agent/v1/record_screen_exec_pb.js";
import { resetChildOomScoreAdj } from "@anysphere/utils";
import { protoInt64 } from "@bufbuild/protobuf";
import {
  detectDisplay,
  type InputEvent,
  InputEventLogger,
  parseDisplayNum,
  type ResolutionConfig,
} from "./computer-use/index.js";

const execFileAsync = promisify(execFile);

export interface PolishedRecordingRenderer {
  assertAvailable(): void;
  renderRecordingSession(options: {
    stagingSessionDir: string;
    outputVideoPath: string;
    fps: number;
    includeBrandTag?: boolean;
  }): Promise<void>;
}

interface RecordingState {
  childProcess: ChildProcess;
  sessionDir: string;
  startTime: number;
  inputEventLogger: InputEventLogger;
  /** Actual display/API resolution for this recording */
  resolution: ResolutionConfig;
  /** Epoch ms when ffmpeg first wrote video data (for timestamp sync) */
  ffmpegStartedEpochMs: number | null;
  ffmpegDiedEarly: boolean;
  ffmpegDiedTime: number | null;
  ffmpegExitCode: number | null;
  ffmpegExitSignal: string | null;
}

type RenderProxyName = "render_proxy_1080p" | "render_proxy_full";

interface RenderProxyArtifact {
  name: RenderProxyName;
  path: string;
  width: number;
  height: number;
  fps: number;
  codec: string;
  profile: string;
  keyint: number;
  status: "success" | "failed";
  elapsedMs: number;
  error?: string;
}

interface RenderProxiesMetadata {
  profileVersion: string;
  generatedAtEpochMs: number;
  source: {
    width: number;
    height: number;
    durationMs: number;
    fps: number;
  };
  artifacts: RenderProxyArtifact[];
}

/** Standard artifacts directory path for cloud VMs (used in prompts) */
export const ARTIFACTS_DIR = "/opt/cursor/artifacts/";

/** Standard logs directory path for cloud VMs (used for debug subagent logs) */
export const LOGS_DIR = "/opt/cursor/logs/";

/** Staging directory for in-progress recordings (before polished render) */
export const RECORDING_STAGING_DIR = "/opt/cursor/recording-staging/";

export interface LocalRecordScreenExecutorOptions {
  /** Directory for final polished video artifacts (visible to backend) */
  artifactsDir: string;
  /** Directory for staging in-progress recordings (hidden from backend) */
  stagingDir?: string;
  /** X11 display to record (e.g. ":0", ":1.0") */
  display: string;
  /**
   * Disable polished post-processing render and use the ffmpeg proxy output
   * directly. Useful for test/dev paths where polished renderer deps are absent.
   */
  disablePolishedRendering?: boolean;
  /** Optional polished renderer injected by exec-daemon. */
  polishedRenderer?: PolishedRecordingRenderer;
}

export class LocalRecordScreenExecutor implements RecordScreenExecutor {
  private activeRecording: RecordingState | null = null;
  private readonly artifactsDir: string;
  private readonly stagingDir: string;
  private readonly display: string;
  private readonly disablePolishedRendering: boolean;
  private readonly polishedRenderer?: PolishedRecordingRenderer;
  private onRecordingStartedCallback:
    | ((logger: InputEventLogger) => void)
    | null = null;
  private onRecordingStoppedCallback: (() => void) | null = null;
  private recordingStoppedCallbackInvoked = false;

  constructor(options: LocalRecordScreenExecutorOptions) {
    this.artifactsDir = options.artifactsDir;
    this.stagingDir = options.stagingDir ?? RECORDING_STAGING_DIR;
    this.display = options.display;
    this.disablePolishedRendering = options.disablePolishedRendering ?? false;
    this.polishedRenderer = options.polishedRenderer;
    // Validate renderer dependencies at executor construction time so
    // record-screen availability is known before any tool call starts.
    if (!this.disablePolishedRendering) {
      if (!this.polishedRenderer) {
        throw new Error(
          "record_screen requires a polished recording renderer when polished rendering is enabled. " +
            "This tool should run via exec-daemon where that dependency is bundled."
        );
      }
      this.polishedRenderer.assertAvailable();
    }
  }

  /**
   * Set callback for when recording starts.
   * Used to wire the InputEventLogger to the X11Executor.
   */
  setOnRecordingStarted(callback: (logger: InputEventLogger) => void): void {
    this.onRecordingStartedCallback = callback;
  }

  /**
   * Set callback for when recording stops.
   */
  setOnRecordingStopped(callback: () => void): void {
    this.onRecordingStoppedCallback = callback;
  }

  /**
   * Invoke the stopped callback exactly once per recording session.
   */
  private invokeStoppedCallbackOnce(): void {
    if (
      !this.recordingStoppedCallbackInvoked &&
      this.onRecordingStoppedCallback
    ) {
      this.recordingStoppedCallbackInvoked = true;
      this.onRecordingStoppedCallback();
    }
  }

  /**
   * Clean up recording resources (ffmpeg process, event logger).
   * Safe to call multiple times.
   */
  private async cleanupRecording(state: RecordingState): Promise<void> {
    // Stop event logger
    try {
      await state.inputEventLogger.stop();
    } catch {
      // Already stopped or failed to stop
    }

    // Stop ffmpeg
    if (!state.childProcess.killed && state.childProcess.pid) {
      try {
        await this.stopFfmpegRecording(state);
      } catch {
        // Best effort - process may already be dead
        try {
          process.kill(state.childProcess.pid, "SIGKILL");
        } catch {
          // Already dead
        }
      }
    }
  }

  /**
   * Get the active InputEventLogger (if recording is in progress).
   */
  getActiveInputEventLogger(): InputEventLogger | null {
    return this.activeRecording?.inputEventLogger ?? null;
  }

  /**
   * Dispose the executor, cleaning up any active recording.
   * Discards recording data - use SAVE_RECORDING first if you want to keep it.
   */
  async dispose(): Promise<void> {
    if (this.activeRecording) {
      await this.cleanupRecording(this.activeRecording);
      this.invokeStoppedCallbackOnce();
      // Best effort cleanup of session directory
      try {
        await fs.rm(this.activeRecording.sessionDir, {
          force: true,
          recursive: true,
        });
      } catch {
        // Ignore cleanup errors
      }
      this.activeRecording = null;
    }
  }

  /**
   * Sanitize tool_call_id for use in file paths
   */
  private sanitizeToolCallId(toolCallId: string): string {
    // Replace non-alphanumeric and non-underscore/non-hyphen characters with underscore
    return toolCallId.replace(/[^a-zA-Z0-9_-]/g, "_");
  }

  /**
   * Ensure the recordings directory exists
   */
  private async ensureRecordingDirectoryExists(): Promise<void> {
    await fs.mkdir(this.stagingDir, { recursive: true });
    await fs.mkdir(this.artifactsDir, { recursive: true });
  }

  /**
   * Build a unique session directory for a recording.
   * Each recording gets its own directory containing all artifacts.
   */
  private buildSessionDir(toolCallId: string): string {
    const sanitized = this.sanitizeToolCallId(toolCallId);
    const timestamp = new Date().toISOString().replace(/[:.]/g, "-");
    const dirname = `session-${timestamp}-${sanitized}`;
    return path.join(this.stagingDir, dirname);
  }

  /**
   * Validate and normalize save_as_filename.
   * Returns a result object with either:
   * - success: true with the normalized filename
   * - success: false with a rejection reason
   */
  private validateAndNormalizeSaveAsFilename(saveAsFilename: string):
    | {
        success: true;
        filename: string;
      }
    | {
        success: false;
        reason: RequestedFilePathRejectedReason;
      } {
    let filename = saveAsFilename.trim();

    // Handle special case: filename begins with absolute path to recordings directory
    // Model is told not to do this but if it does, we strip the prefix
    if (filename.startsWith(this.artifactsDir)) {
      filename = filename.slice(this.artifactsDir.length);
      // Remove leading slash if present
      if (filename.startsWith("/")) {
        filename = filename.slice(1);
      }
    }

    filename = filename.trim();
    if (filename.length === 0) {
      return {
        success: false,
        reason: RequestedFilePathRejectedReason.UNSPECIFIED,
      };
    }

    if (filename.includes("/") || filename.includes("\\")) {
      // Reject any slashes in non-absolute paths
      return {
        success: false,
        reason: RequestedFilePathRejectedReason.SLASHES_NOT_ALLOWED,
      };
    }

    // Replace characters that are commonly invalid/unfriendly in filenames.
    // Keep spaces, dots, underscores, and hyphens for readability.
    filename = filename.replace(/[^a-zA-Z0-9 ._-]/g, "_");
    filename = filename.trim();
    if (filename.length === 0) {
      return {
        success: false,
        reason: RequestedFilePathRejectedReason.UNSPECIFIED,
      };
    }

    // Cap filename length to avoid filesystem/path issues.
    // (mp4 extension added below if missing)
    if (filename.length > 128) {
      filename = filename.slice(0, 128).trim();
    }

    // Always ensure .mp4 extension
    if (!filename.toLowerCase().endsWith(".mp4")) {
      filename = `${filename}.mp4`;
    }

    return { success: true, filename };
  }

  private async pathExists(targetPath: string): Promise<boolean> {
    try {
      await fs.access(targetPath);
      return true;
    } catch {
      return false;
    }
  }

  private async movePolishedVideo(
    sourcePath: string,
    destinationPath: string
  ): Promise<void> {
    try {
      await fs.rename(sourcePath, destinationPath);
      return;
    } catch (error) {
      if (
        !(error instanceof Error) ||
        !("code" in error) ||
        error.code !== "EXDEV"
      ) {
        throw error;
      }
    }

    try {
      await fs.copyFile(
        sourcePath,
        destinationPath,
        fs.constants.COPYFILE_EXCL
      );
    } catch (error) {
      if (
        !(error instanceof Error) ||
        !("code" in error) ||
        error.code !== "EEXIST"
      ) {
        await fs.rm(destinationPath, { force: true }).catch(() => undefined);
      }
      throw error;
    }

    try {
      await fs.unlink(sourcePath);
    } catch (error) {
      await fs.rm(destinationPath, { force: true }).catch(() => undefined);
      throw error;
    }
  }

  /**
   * Resolve a unique path in artifactsDir for a preferred filename.
   * If the name is already taken, append "-2", "-3", etc. before extension.
   */
  private async getUniqueArtifactVideoPath(
    preferredFilename: string
  ): Promise<string> {
    const parsed = path.parse(preferredFilename);
    const baseName = parsed.name || "recording";
    const extension = parsed.ext || ".mp4";

    let candidateFilename = `${baseName}${extension}`;
    let suffix = 2;

    while (
      await this.pathExists(path.join(this.artifactsDir, candidateFilename))
    ) {
      candidateFilename = `${baseName}-${suffix}${extension}`;
      suffix++;
    }

    return path.join(this.artifactsDir, candidateFilename);
  }

  /**
   * Resolve final output video path and any save_as_filename rejection reason.
   */
  private async resolveArtifactVideoPath(options: {
    saveAsFilename?: string;
    stagingSessionDir: string;
  }): Promise<{
    finalVideoPath: string;
    requestedFilePathRejectedReason?: RequestedFilePathRejectedReason;
  }> {
    const { saveAsFilename, stagingSessionDir } = options;

    let requestedFilePathRejectedReason:
      | RequestedFilePathRejectedReason
      | undefined;
    let preferredFilename: string;

    if (saveAsFilename) {
      const validationResult =
        this.validateAndNormalizeSaveAsFilename(saveAsFilename);
      if (validationResult.success) {
        preferredFilename = validationResult.filename;
      } else {
        requestedFilePathRejectedReason = validationResult.reason;
        preferredFilename = `${path.basename(stagingSessionDir)}.mp4`;
      }
    } else {
      preferredFilename = `${path.basename(stagingSessionDir)}.mp4`;
    }

    const finalVideoPath =
      await this.getUniqueArtifactVideoPath(preferredFilename);

    return { finalVideoPath, requestedFilePathRejectedReason };
  }

  private static readonly PROXY_TARGET_WIDTH = 1920;
  private static readonly PROXY_TARGET_FPS = 60;
  private static readonly PROXY_CRF = 17;
  private static readonly PROXY_PRESET = "veryfast";
  private static readonly PROXY_PROFILE_VERSION = "render-proxy-h264-all-i-v1";

  /**
   * Get video duration in milliseconds using ffprobe.
   */
  private async getVideoDurationMs(videoPath: string): Promise<number> {
    const { stdout } = await execFileAsync("ffprobe", [
      "-v",
      "error",
      "-show_entries",
      "format=duration",
      "-of",
      "default=noprint_wrappers=1:nokey=1",
      videoPath,
    ]);
    const durationSec = parseFloat(stdout.trim());
    if (!Number.isFinite(durationSec) || durationSec < 0) {
      throw new Error(`Invalid video duration from ffprobe: ${stdout.trim()}`);
    }
    return Math.floor(durationSec * 1000);
  }

  /**
   * Get video dimensions using ffprobe.
   */
  private async getVideoDimensions(videoPath: string): Promise<{
    width: number;
    height: number;
  }> {
    const { stdout } = await execFileAsync("ffprobe", [
      "-v",
      "error",
      "-select_streams",
      "v:0",
      "-show_entries",
      "stream=width,height",
      "-of",
      "csv=p=0:s=x",
      videoPath,
    ]);

    const [widthStr, heightStr] = stdout.trim().split("x");
    const width = Number.parseInt(widthStr, 10);
    const height = Number.parseInt(heightStr, 10);

    if (!Number.isFinite(width) || !Number.isFinite(height)) {
      throw new Error(
        `Invalid video dimensions from ffprobe: ${stdout.trim()}`
      );
    }

    if (width <= 0 || height <= 0) {
      throw new Error(
        `Invalid non-positive video dimensions from ffprobe: ${stdout.trim()}`
      );
    }

    return { width, height };
  }

  private async renderPolished(stagingSessionDir: string): Promise<string> {
    const recordingDir = path.join(stagingSessionDir, "recording");
    const polishedVideoPath = path.join(recordingDir, "recording_full.mp4");
    await this.polishedRenderer!.renderRecordingSession({
      stagingSessionDir,
      outputVideoPath: polishedVideoPath,
      fps: LocalRecordScreenExecutor.PROXY_TARGET_FPS,
      includeBrandTag: true,
    });

    await fs.access(polishedVideoPath, fs.constants.R_OK);
    return polishedVideoPath;
  }

  /**
   * Get video framerate using ffprobe.
   * Returns a rounded fps value, defaults to PROXY_TARGET_FPS on failure.
   */
  private async getVideoFramerate(videoPath: string): Promise<number> {
    try {
      const { stdout } = await execFileAsync("ffprobe", [
        "-v",
        "error",
        "-select_streams",
        "v:0",
        "-show_entries",
        "stream=r_frame_rate",
        "-of",
        "default=noprint_wrappers=1:nokey=1",
        videoPath,
      ]);

      const rate = stdout.trim();
      if (rate.includes("/")) {
        const [numStr, denStr] = rate.split("/");
        const num = Number.parseFloat(numStr);
        const den = Number.parseFloat(denStr);
        if (Number.isFinite(num) && Number.isFinite(den) && den !== 0) {
          const fps = num / den;
          if (fps > 0 && fps < 500) {
            return Math.round(fps);
          }
        }
      } else {
        const fps = Number.parseFloat(rate);
        if (Number.isFinite(fps) && fps > 0 && fps < 500) {
          return Math.round(fps);
        }
      }
      console.warn(
        `[record-screen] Unexpected ffprobe r_frame_rate output "${rate}", defaulting to ${LocalRecordScreenExecutor.PROXY_TARGET_FPS}fps`
      );
    } catch (error) {
      console.warn(
        `[record-screen] Failed to read video framerate: ${error instanceof Error ? error.message : String(error)}, defaulting to ${LocalRecordScreenExecutor.PROXY_TARGET_FPS}fps`
      );
    }
    return LocalRecordScreenExecutor.PROXY_TARGET_FPS;
  }

  private static readonly DEFAULT_REFRESH_RATE = 60;

  /**
   * Start ffmpeg recording to a single MP4 file.
   *
   * Records with crash-resistant settings (movflags +faststart written at end).
   * Returns both the process and a promise that resolves when ffmpeg has started
   * writing frames (for accurate timestamp synchronization).
   */
  private async startFfmpegRecording(
    resolution: string,
    sessionDir: string
  ): Promise<{ process: ChildProcess; videoStartedPromise: Promise<number> }> {
    // Recording files go in sessionDir/recording/ subdirectory
    const recordingDir = path.join(sessionDir, "recording");
    await fs.mkdir(recordingDir, { recursive: true });

    const proxyPath = path.join(
      recordingDir,
      "recording_render_proxy_1080p.mp4"
    );
    let refreshRate: number;
    try {
      const displayResult = await detectDisplay(this.display);
      refreshRate = displayResult.display.refreshRate;
    } catch (error) {
      console.warn(
        `[record-screen] Failed to detect refresh rate: ${error instanceof Error ? error.message : String(error)}, using default ${LocalRecordScreenExecutor.DEFAULT_REFRESH_RATE}Hz`
      );
      refreshRate = LocalRecordScreenExecutor.DEFAULT_REFRESH_RATE;
    }

    // Record directly to render-optimized proxy (all-I, 60fps, 1080p)
    // This is our ONLY recording output - no separate raw file needed
    const args = [
      "-video_size",
      resolution,
      "-framerate",
      String(refreshRate),
      "-draw_mouse",
      "0",
      "-f",
      "x11grab",
      "-i",
      this.display,
      "-vf",
      `scale=${LocalRecordScreenExecutor.PROXY_TARGET_WIDTH}:-2:flags=lanczos,fps=${LocalRecordScreenExecutor.PROXY_TARGET_FPS}`,
      "-c:v",
      "libx264",
      "-preset",
      LocalRecordScreenExecutor.PROXY_PRESET,
      "-crf",
      String(LocalRecordScreenExecutor.PROXY_CRF),
      "-pix_fmt",
      "yuv420p",
      "-profile:v",
      "high",
      "-x264-params",
      "keyint=1:min-keyint=1:scenecut=0:bframes=0",
      "-movflags",
      "+faststart",
      "-tune",
      "fastdecode",
      "-y",
      proxyPath,
    ];

    const child = spawn("ffmpeg", args, {
      stdio: ["ignore", "pipe", "pipe"],
      detached: true,
    });
    resetChildOomScoreAdj(child.pid);

    // Promise that resolves when ffmpeg starts writing frames
    const videoStartedPromise = new Promise<number>((resolve, reject) => {
      let stderrBuffer = "";
      let hasStarted = false;

      const onStderr = (data: Buffer): void => {
        stderrBuffer += data.toString();
        // Look for "frame=" which indicates actual encoding has started
        if (!hasStarted && stderrBuffer.includes("frame=")) {
          hasStarted = true;
          resolve(Date.now());
        }
      };

      child.stderr?.on("data", onStderr);

      // Timeout if ffmpeg doesn't start producing frames within 5s
      const timeout = setTimeout(() => {
        if (!hasStarted) {
          reject(new Error("ffmpeg did not start encoding within 5 seconds"));
        }
      }, 5000);

      child.once("exit", (code, signal) => {
        clearTimeout(timeout);
        if (!hasStarted) {
          reject(
            new Error(
              `ffmpeg exited before starting: code=${code} signal=${signal}`
            )
          );
        }
      });

      child.once("error", err => {
        clearTimeout(timeout);
        if (!hasStarted) {
          reject(new Error(`ffmpeg failed to start: ${err.message}`));
        }
      });
    });

    // Wait briefly to catch immediate startup failures
    await new Promise<void>((resolve, reject) => {
      const timeout = setTimeout(resolve, 300);
      child.once("error", err => {
        clearTimeout(timeout);
        reject(new Error(`Failed to start ffmpeg: ${err.message}`));
      });
      child.once("exit", (code, signal) => {
        clearTimeout(timeout);
        if (code !== null && code !== 0) {
          reject(new Error(`ffmpeg exited with code ${code}`));
        } else if (signal !== null) {
          reject(new Error(`ffmpeg killed by signal ${signal}`));
        } else {
          // code === 0 or code === null with no signal - treat as early exit
          reject(new Error("ffmpeg exited unexpectedly during startup"));
        }
      });
    });

    return { process: child, videoStartedPromise };
  }

  /**
   * Run an ffmpeg command to completion, capturing stderr for diagnostics.
   */
  private async runFfmpegCommand(label: string, args: string[]): Promise<void> {
    return await new Promise((resolve, reject) => {
      const child = spawn("ffmpeg", args, {
        stdio: ["ignore", "ignore", "pipe"],
      });
      resetChildOomScoreAdj(child.pid);

      let stderr = "";

      child.stderr?.on("data", data => {
        if (stderr.length < 20000) {
          stderr += data.toString();
        }
      });

      child.once("error", error => {
        reject(
          new Error(
            `ffmpeg ${label} failed to start: ${error instanceof Error ? error.message : String(error)}`
          )
        );
      });

      child.once("close", code => {
        if (code === 0) {
          resolve();
        } else {
          reject(
            new Error(
              `ffmpeg ${label} exited with code ${code}: ${stderr.trim()}`
            )
          );
        }
      });
    });
  }

  /**
   * Save recording data package to the session directory.
   * Contains input events for preprocessing/rendering.
   */
  private async saveRecordingDataPackage(options: {
    sessionDir: string;
    durationMs: number;
    recordingStartEpochMs: number;
    ffmpegStartedEpochMs: number;
    inputEvents: InputEvent[];
    resolution: ResolutionConfig;
    renderProxies?: RenderProxiesMetadata | null;
  }): Promise<void> {
    const {
      sessionDir,
      durationMs,
      recordingStartEpochMs,
      ffmpegStartedEpochMs,
      inputEvents,
      resolution,
      renderProxies,
    } = options;
    // Recording files go in sessionDir/recording/ subdirectory
    const recordingDir = path.join(sessionDir, "recording");
    const dataPath = path.join(recordingDir, "recording-data.json");

    // Calculate offset between event timestamps and video timestamps
    // Events are timed from recordingStartEpochMs, video starts at ffmpegStartedEpochMs
    const eventToVideoOffsetMs = ffmpegStartedEpochMs - recordingStartEpochMs;

    const serializedEvents = inputEvents.map(event => ({
      executionTimestampMs: event.executionTimestampMs,
      commandDurationMs: event.commandDurationMs,
      positionBefore: event.positionBefore,
      positionAfter: event.positionAfter,
      cursorTypeAfter: event.cursorTypeAfter,
      action: {
        action: this.serializeAction(event.action),
      },
    }));

    const dataPackage = {
      version: 3,
      durationMs,
      recordingStartEpochMs,
      ffmpegStartedEpochMs,
      eventToVideoOffsetMs,
      displayWidth: resolution.display.width,
      displayHeight: resolution.display.height,
      apiWidth: resolution.api.width,
      apiHeight: resolution.api.height,
      inputEvents: serializedEvents,
      renderProxies: renderProxies ?? null,
    };

    await fs.writeFile(dataPath, JSON.stringify(dataPackage, null, 2));
  }

  /**
   * Serialize a ComputerUseAction to a JSON-safe format.
   */
  private serializeAction(
    action: InputEvent["action"]
  ): Record<string, unknown> {
    const { action: actionOneof } = action;

    const result: Record<string, unknown> = {
      case: actionOneof.case,
    };

    switch (actionOneof.case) {
      case "click":
        result.value = {
          coordinate: actionOneof.value.coordinate
            ? {
                x: actionOneof.value.coordinate.x,
                y: actionOneof.value.coordinate.y,
              }
            : null,
          button: actionOneof.value.button,
          count: actionOneof.value.count,
          modifierKeys: actionOneof.value.modifierKeys,
        };
        break;
      case "mouseMove":
        result.value = {
          coordinate: actionOneof.value.coordinate
            ? {
                x: actionOneof.value.coordinate.x,
                y: actionOneof.value.coordinate.y,
              }
            : null,
        };
        break;
      case "type":
        result.value = { text: actionOneof.value.text };
        break;
      case "key":
        result.value = {
          key: actionOneof.value.key,
          holdDurationMs: actionOneof.value.holdDurationMs,
        };
        break;
      case "scroll":
        result.value = {
          coordinate: actionOneof.value.coordinate
            ? {
                x: actionOneof.value.coordinate.x,
                y: actionOneof.value.coordinate.y,
              }
            : null,
          direction: actionOneof.value.direction,
          amount: actionOneof.value.amount,
          modifierKeys: actionOneof.value.modifierKeys,
        };
        break;
      case "drag":
        result.value = {
          path: actionOneof.value.path.map((p: { x: number; y: number }) => ({
            x: p.x,
            y: p.y,
          })),
          button: actionOneof.value.button,
        };
        break;
      case "wait":
        result.value = { durationMs: actionOneof.value.durationMs };
        break;
      case "screenshot":
      case "cursorPosition":
      case "mouseDown":
      case "mouseUp":
        result.value = actionOneof.value;
        break;
      default:
        result.value = {};
    }

    return result;
  }

  /**
   * Stop ffmpeg gracefully, allowing it to finalize the MP4 file.
   */
  private async stopFfmpegRecording(state: RecordingState): Promise<void> {
    const { childProcess } = state;

    if (childProcess.killed || !childProcess.pid) {
      return;
    }

    const pid = childProcess.pid;

    return new Promise((resolve, reject) => {
      const timeout = setTimeout(() => {
        try {
          // Best effort: kill the whole process group if possible.
          // ffmpeg is started with detached: true.
          try {
            process.kill(-pid, "SIGKILL");
          } catch {
            process.kill(pid, "SIGKILL");
          }
        } catch {
          // Process may already be dead
        }
        reject(new Error("Timeout waiting for ffmpeg to stop"));
      }, 20000);

      childProcess.once("exit", () => {
        clearTimeout(timeout);
        resolve();
      });

      childProcess.once("error", error => {
        clearTimeout(timeout);
        reject(new Error(`Error stopping ffmpeg: ${error.message}`));
      });

      try {
        // SIGTERM allows ffmpeg to finalize the MP4 moov atom
        try {
          process.kill(-pid, "SIGTERM");
        } catch {
          process.kill(pid, "SIGTERM");
        }
      } catch (error) {
        clearTimeout(timeout);
        reject(
          new Error(
            `Failed to send SIGTERM: ${error instanceof Error ? error.message : String(error)}`
          )
        );
      }
    });
  }

  async execute(
    parentCtx: Context,
    args: RecordScreenArgs
  ): Promise<RecordScreenResult> {
    using _span = createSpan(
      parentCtx.withName("LocalRecordScreenExecutor.execute")
    );

    // Ensure recordings directory exists
    try {
      await this.ensureRecordingDirectoryExists();
    } catch (error) {
      return new RecordScreenResult({
        result: {
          case: "failure",
          value: new RecordScreenFailure({
            error: `Failed to create recording directory: ${error instanceof Error ? error.message : String(error)}. Ensure the parent directory exists and has write permissions, or run: sudo mkdir -p ${this.stagingDir} ${this.artifactsDir} && sudo chmod 777 ${this.stagingDir} ${this.artifactsDir}`,
          }),
        },
      });
    }

    // Handle UNSPECIFIED mode
    if (args.mode === RecordingMode.UNSPECIFIED) {
      return new RecordScreenResult({
        result: {
          case: "failure",
          value: new RecordScreenFailure({
            error:
              "Mode must be one of START_RECORDING, SAVE_RECORDING, DISCARD_RECORDING",
          }),
        },
      });
    }

    switch (args.mode) {
      case RecordingMode.START_RECORDING: {
        // Reset callback tracking for new recording
        this.recordingStoppedCallbackInvoked = false;

        let wasPriorRecordingCancelled = false;
        if (this.activeRecording) {
          wasPriorRecordingCancelled = true;
          try {
            await this.cleanupRecording(this.activeRecording);
            await fs
              .rm(this.activeRecording.sessionDir, {
                force: true,
                recursive: true,
              })
              .catch(() => {});
          } catch {
            // Best effort cleanup
          }
          this.activeRecording = null;
        }

        // Track resources for cleanup on error
        let childProcess: ChildProcess | null = null;
        let inputEventLogger: InputEventLogger | null = null;
        let sessionDir: string | null = null;

        try {
          sessionDir = this.buildSessionDir(args.toolCallId || "recording");
          await fs.mkdir(sessionDir, { recursive: true });

          const { resolutionString, resolution: resolutionConfig } =
            await detectDisplay(this.display);
          const { process: ffmpegProcess, videoStartedPromise } =
            await this.startFfmpegRecording(resolutionString, sessionDir);
          childProcess = ffmpegProcess;

          const displayNum = parseDisplayNum(this.display);

          inputEventLogger = new InputEventLogger({
            displayNum,
            resolution: resolutionConfig,
          });
          await inputEventLogger.start();
          const startTime = inputEventLogger.getRecordingStartTime();

          // Ensure ffmpeg is actually encoding frames; otherwise timing sync will be garbage
          // and the recording may be unusable for polished rendering.
          let ffmpegStartedEpochMs: number;
          try {
            ffmpegStartedEpochMs = await videoStartedPromise;
          } catch (error) {
            throw new Error(
              `ffmpeg failed to start encoding: ${error instanceof Error ? error.message : String(error)}`
            );
          }

          this.activeRecording = {
            childProcess,
            sessionDir,
            startTime,
            inputEventLogger,
            resolution: resolutionConfig,
            ffmpegStartedEpochMs,
            ffmpegDiedEarly: false,
            ffmpegDiedTime: null,
            ffmpegExitCode: null,
            ffmpegExitSignal: null,
          };

          if (this.onRecordingStartedCallback) {
            this.onRecordingStartedCallback(inputEventLogger);
          }

          childProcess.once("exit", (code, signal) => {
            if (this.activeRecording) {
              this.activeRecording.ffmpegDiedEarly = true;
              this.activeRecording.ffmpegDiedTime = Date.now();
              this.activeRecording.ffmpegExitCode = code;
              this.activeRecording.ffmpegExitSignal = signal;
            }
          });

          const wasSaveAsFilenameIgnored = !!args.saveAsFilename;
          return new RecordScreenResult({
            result: {
              case: "startSuccess",
              value: new RecordScreenStartSuccess({
                wasPriorRecordingCancelled,
                wasSaveAsFilenameIgnored,
              }),
            },
          });
        } catch (error) {
          // Clean up any resources that were allocated
          if (inputEventLogger) {
            try {
              await inputEventLogger.stop();
            } catch {
              // Best effort
            }
          }
          if (childProcess && !childProcess.killed && childProcess.pid) {
            try {
              process.kill(childProcess.pid, "SIGKILL");
            } catch {
              // Best effort
            }
          }
          if (sessionDir) {
            await fs
              .rm(sessionDir, { force: true, recursive: true })
              .catch(() => {});
          }
          this.activeRecording = null;

          return new RecordScreenResult({
            result: {
              case: "failure",
              value: new RecordScreenFailure({
                error: error instanceof Error ? error.message : String(error),
              }),
            },
          });
        }
      }

      case RecordingMode.SAVE_RECORDING: {
        if (!this.activeRecording) {
          return new RecordScreenResult({
            result: {
              case: "failure",
              value: new RecordScreenFailure({
                error: "No active recording to save",
              }),
            },
          });
        }

        const state = this.activeRecording;

        try {
          const inputEvents = await state.inputEventLogger.stop();
          const recordingStartEpochMs =
            state.inputEventLogger.getRecordingStartTime();

          this.invokeStoppedCallbackOnce();

          if (!state.childProcess.killed && state.childProcess.pid) {
            await this.stopFfmpegRecording(state);
          }

          const ffmpegStartedEpochMs =
            state.ffmpegStartedEpochMs ?? recordingStartEpochMs;

          const stagingSessionDir = state.sessionDir;
          const { finalVideoPath, requestedFilePathRejectedReason } =
            await this.resolveArtifactVideoPath({
              saveAsFilename: args.saveAsFilename,
              stagingSessionDir,
            });

          const stagingRecordingDir = path.join(stagingSessionDir, "recording");
          const proxyPath = path.join(
            stagingRecordingDir,
            "recording_render_proxy_1080p.mp4"
          );

          try {
            await fs.access(proxyPath, fs.constants.R_OK);
          } catch {
            this.activeRecording = null;
            return new RecordScreenResult({
              result: {
                case: "failure",
                value: new RecordScreenFailure({
                  error: `Recording proxy not found at ${proxyPath}`,
                }),
              },
            });
          }

          const [actualVideoDurationMs, videoDimensions, sourceFps] =
            await Promise.all([
              this.getVideoDurationMs(proxyPath),
              this.getVideoDimensions(proxyPath),
              this.getVideoFramerate(proxyPath),
            ]);

          const renderProxies: RenderProxiesMetadata = {
            profileVersion: LocalRecordScreenExecutor.PROXY_PROFILE_VERSION,
            generatedAtEpochMs: Date.now(),
            source: {
              width: videoDimensions.width,
              height: videoDimensions.height,
              durationMs: actualVideoDurationMs,
              fps: sourceFps,
            },
            artifacts: [
              {
                name: "render_proxy_1080p",
                path: "recording_render_proxy_1080p.mp4",
                width: videoDimensions.width,
                height: videoDimensions.height,
                fps: LocalRecordScreenExecutor.PROXY_TARGET_FPS,
                codec: "h264",
                profile: LocalRecordScreenExecutor.PROXY_PROFILE_VERSION,
                keyint: 1,
                status: "success",
                elapsedMs: 0,
              },
            ],
          };

          await this.saveRecordingDataPackage({
            sessionDir: stagingSessionDir,
            durationMs: actualVideoDurationMs,
            recordingStartEpochMs,
            ffmpegStartedEpochMs,
            inputEvents,
            resolution: state.resolution,
            renderProxies,
          });

          if (this.disablePolishedRendering) {
            // In test/dev flows we can skip polished rendering and keep the
            // captured proxy as the final artifact.
            await fs.copyFile(proxyPath, finalVideoPath);
          } else {
            const polishedVideoPath =
              await this.renderPolished(stagingSessionDir);
            await this.movePolishedVideo(polishedVideoPath, finalVideoPath);
          }

          // Staging directory stays for debugging but is invisible to backend
          this.activeRecording = null;

          return new RecordScreenResult({
            result: {
              case: "saveSuccess",
              value: new RecordScreenSaveSuccess({
                path: finalVideoPath,
                recordingDurationMs: protoInt64.parse(
                  actualVideoDurationMs.toString()
                ),
                requestedFilePathRejectedReason,
              }),
            },
          });
        } catch (error) {
          // Clean up resources that might still be running
          await this.cleanupRecording(state);
          this.invokeStoppedCallbackOnce();
          this.activeRecording = null;
          return new RecordScreenResult({
            result: {
              case: "failure",
              value: new RecordScreenFailure({
                error: error instanceof Error ? error.message : String(error),
              }),
            },
          });
        }
      }

      case RecordingMode.DISCARD_RECORDING: {
        if (!this.activeRecording) {
          return new RecordScreenResult({
            result: {
              case: "failure",
              value: new RecordScreenFailure({
                error: "No active recording to discard",
              }),
            },
          });
        }

        const state = this.activeRecording;

        try {
          await state.inputEventLogger.stop();

          this.invokeStoppedCallbackOnce();

          if (!state.childProcess.killed && state.childProcess.pid) {
            await this.stopFfmpegRecording(state);
          }

          await fs.rm(state.sessionDir, { force: true, recursive: true });

          this.activeRecording = null;

          return new RecordScreenResult({
            result: {
              case: "discardSuccess",
              value: new RecordScreenDiscardSuccess(),
            },
          });
        } catch (error) {
          // Clean up resources that might still be running
          await this.cleanupRecording(state);
          this.invokeStoppedCallbackOnce();
          const sessionDir = state.sessionDir;
          this.activeRecording = null;
          return new RecordScreenResult({
            result: {
              case: "failure",
              value: new RecordScreenFailure({
                error: `Failed to discard recording: ${error instanceof Error ? error.message : String(error)}. Session may remain at: ${sessionDir}`,
              }),
            },
          });
        }
      }

      default: {
        // Exhaustive check for TypeScript
        const _exhaustiveCheck: never = args.mode;
        return new RecordScreenResult({
          result: {
            case: "failure",
            value: new RecordScreenFailure({
              error: `Unhandled recording mode: ${_exhaustiveCheck}`,
            }),
          },
        });
      }
    }
  }
}
