/**
 * ComputerUseExecutor implementation for OS-level control via X11.
 */

import * as crypto from "node:crypto";
import * as fs from "node:fs/promises";
import * as os from "node:os";
import * as path from "node:path";
import type { Context } from "@anysphere/context";
import { createLogger } from "@anysphere/context";
import { createCounter, createHistogram } from "@anysphere/metrics";
import {
  ComputerUseAction,
  type ComputerUseArgs,
  ComputerUseError,
  ComputerUseResult,
  ComputerUseSuccess,
  Coordinate,
  ScreenshotAction,
  WaitAction,
} from "@anysphere/proto/agent/v1/computer_use_tool_pb.js";
import type { InputEventLogger } from "./input-event-logger.js";
import { DEFAULT_SCREENSHOT_DELAY_MS, type X11Config } from "./types.js";
import { X11Executor } from "./x11-executor.js";

// Metrics
const sessionDuration = createHistogram("computer_use.session.duration_ms", {
  description: "Duration of computer-use session in milliseconds",
});

const sessionActionCount = createHistogram(
  "computer_use.session.action_count",
  {
    description: "Number of actions executed in a computer-use session",
  }
);

const sessionResult = createCounter("computer_use.session.result", {
  description: "Result status of computer-use session",
  labelNames: ["outcome"] as const,
});

export interface ComputerUseExecutor {
  execute(ctx: Context, args: ComputerUseArgs): Promise<ComputerUseResult>;
}

const logger = createLogger("computer-use");

export class X11ComputerUseExecutor implements ComputerUseExecutor {
  private readonly executor: X11Executor;
  private readonly screenshotDirectory: string;
  private readonly errorScreenshotSettleMs: number;

  /**
   * Create an X11 computer use executor.
   * @param config - MUST include displayNum and resolution (use detectDisplay() to get resolution)
   */
  constructor(
    config: X11Config,
    screenshotDirectory: string = path.join(os.tmpdir(), "computer-use")
  ) {
    this.executor = new X11Executor(config);
    this.screenshotDirectory = screenshotDirectory;
    this.errorScreenshotSettleMs =
      config.screenshotDelayMs ?? DEFAULT_SCREENSHOT_DELAY_MS;
  }

  /**
   * Set the InputEventLogger on the underlying X11Executor.
   * Used for recording polished video preprocessing data.
   */
  setInputEventLogger(logger: InputEventLogger | undefined): void {
    this.executor.setInputEventLogger(logger);
  }

  private generateScreenshotFilename(): string {
    // Generate 5-character UUID using random bytes
    const randomBytes = crypto.randomBytes(3);
    const uuid = randomBytes.toString("hex").substring(0, 5);
    return `${uuid}.webp`;
  }

  private async saveScreenshotToTemp(
    ctx: Context,
    screenshotBase64: string
  ): Promise<string | undefined> {
    try {
      const tempDir = this.screenshotDirectory;
      await fs.mkdir(tempDir, { recursive: true });

      const filename = this.generateScreenshotFilename();
      const filepath = path.join(tempDir, filename);

      const buffer = Buffer.from(screenshotBase64, "base64");
      await fs.writeFile(filepath, buffer);

      logger.info(ctx, "Screenshot saved to temp", {
        filepath,
        sizeBytes: buffer.length,
      });

      return filepath;
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : String(error);
      logger.error(ctx, "Failed to save screenshot to temp", error, {
        error: errorMessage,
      });
      return undefined;
    }
  }

  async execute(
    ctx: Context,
    args: ComputerUseArgs
  ): Promise<ComputerUseResult> {
    const startTime = Date.now();

    logger.info(ctx, "Executing computer use actions", {
      toolCallId: args.toolCallId,
      actionCount: args.actions.length,
    });

    try {
      const result = await this.executor.execute(args.actions, {
        bindUnmappedCharacters: args.bindUnmappedCharacters ?? false,
      });
      const durationMs = Date.now() - startTime;

      let screenshotPath: string | undefined;
      if (result.screenshot) {
        screenshotPath = await this.saveScreenshotToTemp(
          ctx,
          result.screenshot
        );
      }

      logger.info(ctx, "Computer use execution completed", {
        success: result.success,
        actionCount: result.actionCount,
        durationMs,
        screenshotPath,
      });

      sessionDuration.histogram(ctx, durationMs);
      sessionActionCount.histogram(ctx, result.actionCount);

      if (result.success) {
        sessionResult.increment(ctx, 1, { outcome: "success" });

        const cursorPosition = result.cursorPosition
          ? new Coordinate({
              x: result.cursorPosition.x,
              y: result.cursorPosition.y,
            })
          : undefined;

        return new ComputerUseResult({
          result: {
            case: "success",
            value: new ComputerUseSuccess({
              actionCount: result.actionCount,
              durationMs: result.durationMs,
              screenshot: result.screenshot,
              screenshotPath,
              log: `Executed ${result.actionCount} actions`,
              cursorPosition,
            }),
          },
        });
      }

      sessionResult.increment(ctx, 1, { outcome: "error" });
      return new ComputerUseResult({
        result: {
          case: "error",
          value: new ComputerUseError({
            error: result.error ?? "Unknown error",
            actionCount: result.actionCount,
            durationMs: result.durationMs,
          }),
        },
      });
    } catch (error) {
      const durationMs = Date.now() - startTime;
      const errorMessage =
        error instanceof Error ? error.message : String(error);

      logger.error(ctx, "Computer use execution failed", error, {
        toolCallId: args.toolCallId,
        durationMs,
      });

      let errorScreenshotBase64: string | undefined;
      let errorScreenshotPath: string | undefined;
      try {
        const screenshotResult = await this.executor.execute([
          new ComputerUseAction({
            action: {
              case: "wait",
              value: new WaitAction({
                durationMs: this.errorScreenshotSettleMs,
              }),
            },
          }),
          new ComputerUseAction({
            action: { case: "screenshot", value: new ScreenshotAction() },
          }),
        ]);
        if (screenshotResult.screenshot) {
          errorScreenshotBase64 = screenshotResult.screenshot;
          errorScreenshotPath = await this.saveScreenshotToTemp(
            ctx,
            screenshotResult.screenshot
          );
        }
      } catch (screenshotError) {
        logger.warn(ctx, "Failed to take error screenshot", {
          error:
            screenshotError instanceof Error
              ? screenshotError.message
              : String(screenshotError),
        });
      }

      sessionDuration.histogram(ctx, durationMs);
      sessionActionCount.histogram(ctx, args.actions.length);
      sessionResult.increment(ctx, 1, { outcome: "error" });

      return new ComputerUseResult({
        result: {
          case: "error",
          value: new ComputerUseError({
            error: errorMessage,
            actionCount: args.actions.length,
            durationMs,
            log: errorScreenshotPath
              ? `Error screenshot saved to ${errorScreenshotPath}`
              : undefined,
            screenshot: errorScreenshotBase64,
            screenshotPath: errorScreenshotPath,
          }),
        },
      });
    }
  }
}
