import { join } from "node:path";

export type ExtensibilitySkillScope = "project" | "user" | "builtin";
export type ExtensibilitySkillSource = "workspace" | "user" | "builtin";

export interface ExtensibilitySkillRoot {
  dirPath: string;
  scope: ExtensibilitySkillScope;
  source: ExtensibilitySkillSource;
}

const EXCLUDED_CODEX_SKILL_NAMES = new Set([
  "imagegen",
  "openai-docs",
  "opneai-docs",
  "plugin-creator",
  "skill-creator",
  "skill-installer",
]);

function getNormalizedSegments(path: string): string[] {
  return path.replace(/\\/g, "/").split("/").filter(Boolean);
}

export function shouldIgnoreExtensibilitySkillPath(skillPath: string): boolean {
  const segments = getNormalizedSegments(skillPath);
  const codexIndex = segments.lastIndexOf(".codex");
  if (codexIndex === -1 || segments[codexIndex + 1] !== "skills") {
    return false;
  }

  const lastSegment = segments.at(-1);
  const skillName = lastSegment === "SKILL.md" ? segments.at(-2) : lastSegment;
  return skillName !== undefined && EXCLUDED_CODEX_SKILL_NAMES.has(skillName);
}

export function getBuiltinExtensibilitySkillRoot(
  userHomeDirectory: string
): ExtensibilitySkillRoot {
  return {
    dirPath: join(userHomeDirectory, ".cursor", "skills-cursor"),
    scope: "builtin",
    source: "builtin",
  };
}

export function getProjectExtensibilitySkillRoots(
  projectRoot: string,
  thirdPartyExtensibilityEnabled: boolean
): ExtensibilitySkillRoot[] {
  const roots: ExtensibilitySkillRoot[] = [];

  if (thirdPartyExtensibilityEnabled) {
    roots.push(
      {
        dirPath: join(projectRoot, ".claude", "skills"),
        scope: "project",
        source: "workspace",
      },
      {
        dirPath: join(projectRoot, ".codex", "skills"),
        scope: "project",
        source: "workspace",
      }
    );
  }

  roots.push(
    {
      dirPath: join(projectRoot, ".agents", "skills"),
      scope: "project",
      source: "workspace",
    },
    {
      dirPath: join(projectRoot, ".cursor", "skills"),
      scope: "project",
      source: "workspace",
    }
  );

  return roots;
}

export function getUserExtensibilitySkillRoots(
  userHomeDirectory: string,
  thirdPartyExtensibilityEnabled: boolean
): ExtensibilitySkillRoot[] {
  const roots: ExtensibilitySkillRoot[] = [];

  if (thirdPartyExtensibilityEnabled) {
    roots.push(
      {
        dirPath: join(userHomeDirectory, ".claude", "skills"),
        scope: "user",
        source: "user",
      },
      {
        dirPath: join(userHomeDirectory, ".codex", "skills"),
        scope: "user",
        source: "user",
      }
    );
  }

  roots.push(
    {
      dirPath: join(userHomeDirectory, ".agents", "skills"),
      scope: "user",
      source: "user",
    },
    {
      dirPath: join(userHomeDirectory, ".cursor", "skills"),
      scope: "user",
      source: "user",
    }
  );

  return roots;
}
