import type { Context } from "@anysphere/context";
import type { GitExecutor } from "../git-executor.js";

export { isOriginBackedRemoteUrl } from "@anysphere/utils";

/**
 * Finds the root directory of the git repository containing the given path.
 * Returns null if not in a git repository.
 *
 * @param gitExecutor - GitExecutor to use for running git commands
 * @param startPath - The path to start searching from
 */
export async function findGitRoot(
  ctx: Context,
  gitExecutor: GitExecutor,
  startPath: string
): Promise<string | null> {
  try {
    const result = await gitExecutor.exec(
      ctx,
      startPath,
      ["rev-parse", "--show-toplevel"],
      { caller: "findGitRoot" }
    );
    return result.stdout.trim();
  } catch {
    // Not in a git repository or git command failed
    return null;
  }
}

/**
 * Gets the remote origin URL for a git repository.
 * Returns undefined if no remote origin is configured.
 *
 * @param gitExecutor - GitExecutor to use for running git commands
 * @param gitRoot - The path to the git repository root
 */
export async function getGitRemoteUrl(
  ctx: Context,
  gitExecutor: GitExecutor,
  gitRoot: string
): Promise<string | undefined> {
  try {
    const result = await gitExecutor.exec(
      ctx,
      gitRoot,
      ["config", "--get", "remote.origin.url"],
      { caller: "getGitRemoteUrl" }
    );
    return result.stdout.trim();
  } catch {
    // No remote origin configured or git command failed
    return undefined;
  }
}

/**
 * Sanitizes git remote URLs for safe display/logging by stripping credentials.
 * Preserves host/path/query/fragment and leaves non-URL formats unchanged.
 */
export function sanitizeGitRemoteUrl(remoteUrl: string): string {
  const trimmedRemoteUrl = remoteUrl.trim();
  if (trimmedRemoteUrl === "") {
    return trimmedRemoteUrl;
  }

  try {
    const parsedRemoteUrl = new URL(trimmedRemoteUrl);
    parsedRemoteUrl.username = "";
    parsedRemoteUrl.password = "";
    return parsedRemoteUrl.toString();
  } catch {
    return trimmedRemoteUrl;
  }
}

/**
 * Normalize a remote URL into a stable host/path form for comparison,
 * e.g. "github.com/org/repo". Handles URL-style, SCP-style, and SSH
 * git remotes. Uses the URL constructor for robust parsing of ports,
 * userinfo, encoding, and query/fragment stripping. Falls back to regex
 * stripping for unparseable URLs (e.g. glob patterns with wildcards in
 * the hostname).
 *
 * Case-preserving — callers that need case-insensitive comparison
 * should apply .toLowerCase() themselves.
 *
 * Mirrors normalizeRepoUrl in vscode cursorIgnoreService.ts — keep in sync.
 */
export function toHostPath(rawUrl: string): string {
  let url = rawUrl.trim();

  // Convert git@ SCP-style to HTTPS for URL parsing
  if (url.startsWith("git@")) {
    url = `https://${url.slice("git@".length).replace(":", "/")}`;
  }

  // Replace any non-HTTP(S) scheme with HTTPS so the URL constructor can parse it
  if (/^[a-z][a-z0-9+.-]*:\/\//i.test(url) && !/^https?:\/\//i.test(url)) {
    url = url.replace(/^[a-z][a-z0-9+.-]*:\/\//i, "https://");
  }

  // Ensure a protocol exists so the URL constructor can parse bare hosts
  if (!/^https?:\/\//i.test(url)) {
    url = `https://${url}`;
  }

  try {
    const parsed = new URL(url);
    const pathname = parsed.pathname
      .replace(/\/+$/, "")
      .replace(/\.git$/i, "")
      .replace(/\/+$/, "");
    return parsed.hostname + pathname;
  } catch {
    // Fallback for glob patterns with wildcards in the hostname
    // (e.g. "*.example.com/org/*") or other unparseable URLs
    url = url.replace(/^https?:\/\//i, "");
    url = url.replace(/[?#].*$/, "");
    url = url.replace(/\/+$/, "");
    url = url.replace(/\.git$/i, "");
    url = url.replace(/\/+$/, "");
    return url;
  }
}

// Globs to skip when scanning for .gitignore / .cursorignore files.
// Mirrors common heavy or tool-generated directories similar to DIRS_TO_SKIP in the VS Code service.
