import { debuglog } from "node:util";
import { type Context, createSpan } from "@anysphere/context";
import type { AgentSkill } from "@anysphere/proto/agent/v1/agent_skills_pb.js";

import {
  type AgentSkillsPromptSortContext,
  sortAgentSkillsForPromptOrder,
} from "./agent-skills-prompt-order.js";
import { dedupeKey } from "./cursor-rules-service.js";

const log = debuglog("merged-agent-skills");

export type { AgentSkillsPromptSortContext } from "./agent-skills-prompt-order.js";

/** Supplies workspace/home paths for prompt-order sorting (re-evaluated each merge). */
export type AgentSkillsPromptSortContextProvider =
  () => AgentSkillsPromptSortContext;

/** Kept in sync with `builtin-skills-sync-service` writes. */
export const MANAGED_CANVAS_SKILL_PATH_SUFFIX =
  "/.cursor/skills-cursor/canvas/SKILL.md";

/**
 * Service interface for loading agent skills as the dedicated AgentSkill proto.
 * Parallel to CursorRulesService but outputs AgentSkill[] instead of CursorRule[].
 */
export interface AgentSkillsService {
  getAllAgentSkills(ctx: Context): Promise<AgentSkill[]>;
  reload(ctx: Context): void;
  onDidChangeSkills(callback: () => void): () => void;
  dispose(): void;
}

/** Re-evaluated on every `getAllAgentSkills` call. */
export type GetDisabledManagedSkillPaths = () =>
  | readonly string[]
  | Promise<readonly string[]>;

/**
 * Merges multiple AgentSkillsService instances into one, deduplicating via
 * dedupeKey (normalises across .cursor/, .claude/, .codex/, .agents/).
 */
export class MergedAgentSkillsService implements AgentSkillsService {
  private static readonly CHANGE_COALESCE_MS = 1_500;

  private readonly onChangeCallbacks = new Set<() => void>();
  private disposeChangeListeners: Array<() => void> | undefined;
  private changeTimer: ReturnType<typeof setTimeout> | undefined;

  constructor(
    private readonly services: AgentSkillsService[],
    private readonly getDisabledManagedSkillPaths: GetDisabledManagedSkillPaths = () => [],
    private readonly getPromptSortContext?:
      | AgentSkillsPromptSortContextProvider
      | undefined
  ) {}

  async getAllAgentSkills(ctx: Context): Promise<AgentSkill[]> {
    using span = createSpan(
      ctx.withName("MergedAgentSkillsService.getAllAgentSkills")
    );
    const allPromises = this.services.map(service =>
      service.getAllAgentSkills(span.ctx).catch(err => {
        log(
          "Failed to load agent skills from service: %s",
          err instanceof Error ? err.message : String(err)
        );
        return [];
      })
    );

    const [allArrays, disabledPaths] = await Promise.all([
      Promise.all(allPromises),
      Promise.resolve(this.getDisabledManagedSkillPaths()).catch(err => {
        log(
          "getDisabledManagedSkillPaths rejected; fail-open: %s",
          err instanceof Error ? err.message : String(err)
        );
        return [] as readonly string[];
      }),
    ]);
    const allSkills = allArrays.flat();

    const seenKeys = new Set<string>();
    const deduped: AgentSkill[] = [];
    for (const skill of allSkills) {
      const key = dedupeKey(skill.fullPath);
      if (!seenKeys.has(key)) {
        seenKeys.add(key);
        deduped.push(skill);
      }
    }

    let result = deduped;
    if (disabledPaths.length > 0) {
      result = deduped.filter(
        skill => !isPathSuffixMatch(skill.fullPath, disabledPaths)
      );
    }

    const sortProvider = this.getPromptSortContext;
    if (sortProvider !== undefined) {
      return sortAgentSkillsForPromptOrder(result, sortProvider());
    }
    return result;
  }

  reload(ctx: Context): void {
    for (const service of this.services) {
      service.reload(ctx);
    }
  }

  private scheduleDidChangeSkills(): void {
    if (this.changeTimer !== undefined) {
      return;
    }

    this.changeTimer = setTimeout(() => {
      this.changeTimer = undefined;
      for (const callback of Array.from(this.onChangeCallbacks)) {
        callback();
      }
    }, MergedAgentSkillsService.CHANGE_COALESCE_MS);
  }

  private ensureChangeListenersRegistered(): void {
    if (this.disposeChangeListeners !== undefined) {
      return;
    }

    this.disposeChangeListeners = this.services.map(service =>
      service.onDidChangeSkills(() => this.scheduleDidChangeSkills())
    );
  }

  private disposeChangeListenersIfUnused(): void {
    if (
      this.onChangeCallbacks.size > 0 ||
      this.disposeChangeListeners === undefined
    ) {
      return;
    }

    for (const dispose of this.disposeChangeListeners) {
      dispose();
    }
    this.disposeChangeListeners = undefined;
    if (this.changeTimer !== undefined) {
      clearTimeout(this.changeTimer);
      this.changeTimer = undefined;
    }
  }

  onDidChangeSkills(callback: () => void): () => void {
    this.onChangeCallbacks.add(callback);
    this.ensureChangeListenersRegistered();
    return () => {
      this.onChangeCallbacks.delete(callback);
      this.disposeChangeListenersIfUnused();
    };
  }

  dispose(): void {
    if (this.changeTimer !== undefined) {
      clearTimeout(this.changeTimer);
      this.changeTimer = undefined;
    }
    this.onChangeCallbacks.clear();
    if (this.disposeChangeListeners !== undefined) {
      for (const dispose of this.disposeChangeListeners) {
        dispose();
      }
      this.disposeChangeListeners = undefined;
    }
    for (const service of this.services) {
      service.dispose();
    }
  }
}

function isPathSuffixMatch(
  fullPath: string | undefined,
  suffixes: readonly string[]
): boolean {
  if (!fullPath) {
    return false;
  }
  const normalizedPath = fullPath.replace(/\\/g, "/");
  return suffixes.some(suffix => normalizedPath.endsWith(suffix));
}
