/**
 * MCP network-controls adapter for mcp-agent-exec.
 *
 * This is the runtime enforcement adapter for remote MCP outbound HTTP(S).
 * Pure URL policy lives in mcp-core; this file wires that policy to
 * mcp-agent-exec's request-control shape. Load-time MCP config checks use the
 * separate admin policy helpers because they validate declared server config,
 * not per-request traffic.
 *
 * This file keeps the mcp-agent-exec-specific service boundary and
 * request-control factory used by loaders and transports.
 */
import {
  checkMcpNetworkUrl,
  type McpNetworkControlsConfig,
  type McpNetworkRequestControlResult,
} from "@anysphere/mcp-core";

export {
  checkMcpNetworkUrl,
  getEffectiveMcpNetworkAllowlist,
  getMatchedAllowedMcpServer,
  getMcpNetworkControlsBlockMessage,
  getStdioMcpSandboxConfig,
  isAllowedUserExtensionCommandServer,
  MCP_NETWORK_CONTROLS_BLOCK_MESSAGE,
  type McpNetworkControlsAllowedConfiguration,
  type McpNetworkControlsAllowedServerEntry,
  type McpNetworkControlsConfig,
  type McpNetworkMode,
  type McpNetworkRequestControlResult,
  matchesAllowedMcpServerEntry,
  resolveMcpNetworkAllowlistForMatchedServer,
  resolveMcpNetworkControlsConfigFromAdminPolicy,
  resolveMcpNetworkModeForMatchedCommandServer,
  shouldEnableMcpNetworkControlsConfigForServer,
} from "@anysphere/mcp-core";

export type McpNetworkControlsConfigProvider = () =>
  | McpNetworkControlsConfig
  | Promise<McpNetworkControlsConfig>;

export type McpNetworkControlsServer = {
  command?: string;
  url?: string;
};

export interface McpNetworkControlsConfigService {
  getMcpNetworkControlsConfig?(
    server?: McpNetworkControlsServer
  ): Promise<McpNetworkControlsConfig>;
}

export interface McpNetworkRequestControl {
  isEnabled?(): Promise<boolean>;
  checkUrl(url: string): Promise<McpNetworkRequestControlResult>;
}

export class McpNetworkRequestBlockedError extends Error {
  constructor(
    readonly url: string,
    message = "MCP network request blocked by policy"
  ) {
    super(message);
    this.name = "McpNetworkRequestBlockedError";
  }
}

export function createMcpNetworkRequestControl(
  getConfig: McpNetworkControlsConfigProvider
): McpNetworkRequestControl {
  return {
    isEnabled: async () => (await getConfig()).enabled === true,
    checkUrl: async url => checkMcpNetworkUrl(url, await getConfig()),
  };
}

export function createMcpNetworkRequestControlFromService(
  service: McpNetworkControlsConfigService
): McpNetworkRequestControl {
  return createMcpNetworkRequestControl(
    async () => (await service.getMcpNetworkControlsConfig?.()) ?? {}
  );
}
