import { SimpleControlledExecHandler } from "./controlled.js";
import { ExecutorResource } from "./remote.js";
import { createResource } from "./resource-provider.js";
import { createClientDeserializer, createClientSerializer, createServerDeserializer, createServerSerializer, } from "./serialization.js";
export const piWriteExecutorResource = createResource(execManager => new ExecutorResource(execManager, createServerSerializer("piWriteArgs"), createClientDeserializer("piWriteResult")), (implementation, controlledExecManager) => {
    controlledExecManager.register(new SimpleControlledExecHandler(implementation, createServerDeserializer("piWriteArgs"), createClientSerializer("piWriteResult")));
});
