import type { ActivitySpec, ActivityType, ServiceType } from './active-activities.js';
import { activeActivities, activeServices } from './active-activities.js';
import type { ConnectionState, FSMEvent } from './types.js';

/**
 * Maps activity types to the FSM event they produce when they fire.
 */
function activityEvent(type: ActivityType): FSMEvent {
	switch (type) {
		case 'backoff_timer':
			return { target: 'connection', kind: 'backoff_timer_expired' };
		case 'stability_timer':
			return { target: 'connection', kind: 'connection_stabilized' };
		case 'periodic_retry_timer':
			return { target: 'connection', kind: 'periodic_retry_expired' };
		case 'health_probe_timer':
			return { target: 'connection', kind: 'health_probe_due' };
		default: {
			const _exhaustive: never = type;
			return _exhaustive;
		}
	}
}

function healthProbeMode(state: ConnectionState): 'keepalive' | 'degraded' | undefined {
	if (state.type === 'connected' && state.stabilized && !state.probing) {
		return 'keepalive';
	}
	if (state.type === 'degraded' && !state.probing) {
		return 'degraded';
	}
	return undefined;
}

interface CancellableHandle {
	cancel: () => void;
}

/**
 * Callback that starts a service.  Returns a cancellable handle and
 * a promise that resolves when the service completes.  The service
 * MUST route its result back via `enqueue()` — the promise is
 * exposed for callers that need to wait (e.g., "wait for connection").
 */
export type ServiceStarter = (
	type: ServiceType,
	enqueue: (events: FSMEvent[]) => void,
) => { handle: CancellableHandle; promise: Promise<void> };

/**
 * ActivityReconciler — derives ALL managed effect lifecycles from FSM state.
 *
 * Manages two kinds of effects:
 *
 * 1. **Activities (timers)**: ongoing effects with a delay that fire a
 *    single event.  Derived from `activeActivities(state)`.
 *
 * 2. **Services (one-shot async operations)**: connection attempts that
 *    produce events on completion.  Derived from `activeServices(state)`.
 *
 * Both are started on state entry, cancelled on state exit, and
 * deduplicated (if the effect is already running, no-op).  This makes
 * ALL effect lifecycle management structural — no fire-and-forget,
 * no forgotten cancels.
 */
export class ActivityReconciler {
	private readonly activeTimers = new Map<ActivityType, CancellableHandle>();
	private readonly activeServiceHandles = new Map<ServiceType, CancellableHandle>();
	private readonly activeServicePromises = new Map<ServiceType, Promise<void>>();

	constructor(
		private readonly resolveActivities: (state: ConnectionState) => ReadonlyMap<ActivityType, ActivitySpec> = activeActivities,
	) { }

	/**
	 * Reconcile timer activities after a state transition.
	 */
	reconcile(
		prev: ConnectionState,
		next: ConnectionState,
		enqueue: (events: FSMEvent[]) => void,
	): void {
		const prevActs = this.resolveActivities(prev);
		const nextActs = this.resolveActivities(next);

		// Stop timers that are no longer needed or whose delay changed
		for (const [type, handle] of this.activeTimers) {
			const nextSpec = nextActs.get(type);
			const prevSpec = prevActs.get(type);
			const isHealthProbeModeChange =
				type === 'health_probe_timer'
				&& healthProbeMode(prev) !== healthProbeMode(next);
			const isDelayChange =
				type !== 'health_probe_timer'
				&& nextSpec?.delayMs !== prevSpec?.delayMs;
			if (!nextSpec || isHealthProbeModeChange || isDelayChange) {
				handle.cancel();
				this.activeTimers.delete(type);
			}
		}

		// Start timers that are newly needed
		for (const [type, spec] of nextActs) {
			if (!this.activeTimers.has(type)) {
				const handle = this.startTimer(type, spec, enqueue);
				this.activeTimers.set(type, handle);
			}
		}
	}

	/**
	 * Reconcile services (one-shot async operations) after a state transition.
	 *
	 * Handles three cases:
	 * 1. Service no longer needed (state exited) → cancel
	 * 2. Service newly needed (state entered) → start
	 * 3. Self-transition with generation change → cancel old + start new
	 *
	 * Case 3 matters for `session_invalidated`: the FSM may transition
	 * `connecting(gen=1) → connecting(gen=2)`.  The reconciler must restart
	 * the service even though the service set is unchanged.  We detect this
	 * via the explicit `generation` field on the `connecting` state, which
	 * is a monotonically increasing counter that increments on every entry.
	 *
	 * @param startService - callback to start a service; provided by
	 *   ServerLifecycle so the reconciler stays decoupled from transport logic.
	 */
	reconcileServices(
		prev: ConnectionState,
		next: ConnectionState,
		enqueue: (events: FSMEvent[]) => void,
		startService: ServiceStarter,
	): void {
		const prevSvcs = activeServices(prev);
		const nextSvcs = activeServices(next);

		// Detect generation change: same state type but generation advanced.
		// This replaces the old reference-identity check with an explicit,
		// verifiable mechanism.
		const prevGen = prev.type === 'connecting' ? prev.generation : -1;
		const nextGen = next.type === 'connecting' ? next.generation : -1;
		const isGenerationChange = prev.type === next.type && prevGen !== nextGen && nextGen >= 0;

		// Cancel services that are no longer needed OR need restart due to generation change
		for (const [type, handle] of this.activeServiceHandles) {
			if (!nextSvcs.has(type) || isGenerationChange) {
				handle.cancel();
				this.activeServiceHandles.delete(type);
				this.activeServicePromises.delete(type);
			}
		}

		// Start services that are newly needed (or restarted after generation change)
		for (const type of nextSvcs) {
			if (!this.activeServiceHandles.has(type)) {
				const { handle, promise } = startService(type, enqueue);
				this.activeServiceHandles.set(type, handle);
				// Guard against unhandled rejection — service results are
				// routed back via enqueue(), so a rejection here is already
				// handled by the lifecycle; swallow it to prevent the global
				// unhandledrejection handler (Sentry) from capturing it.
				this.activeServicePromises.set(type, promise.catch(() => { }));
			}
		}
	}

	/**
	 * Get the promise for a running service.
	 * Returns undefined if the service is not currently running.
	 * Used by operations (callTool, listOfferings) to wait for connection.
	 */
	getServicePromise(type: ServiceType): Promise<void> | undefined {
		return this.activeServicePromises.get(type);
	}

	/**
	 * Dispose all active timers and services.
	 */
	dispose(): void {
		for (const [, handle] of this.activeTimers) {
			handle.cancel();
		}
		this.activeTimers.clear();

		for (const [, handle] of this.activeServiceHandles) {
			handle.cancel();
		}
		this.activeServiceHandles.clear();
		this.activeServicePromises.clear();
	}

	/** Number of currently active timer activities (for testing). */
	get activeCount(): number {
		return this.activeTimers.size;
	}

	/** Number of currently active services (for testing). */
	get activeServiceCount(): number {
		return this.activeServiceHandles.size;
	}

	/** Check if a specific timer activity is currently running (for testing). */
	has(type: ActivityType): boolean {
		return this.activeTimers.has(type);
	}

	/** Check if a specific service is currently running (for testing). */
	hasService(type: ServiceType): boolean {
		return this.activeServiceHandles.has(type);
	}

	private startTimer(
		type: ActivityType,
		spec: ActivitySpec,
		enqueue: (events: FSMEvent[]) => void,
	): CancellableHandle {
		const event = activityEvent(type);
		let cancelled = false;

		const timer = setTimeout(() => {
			if (cancelled) {
				return;
			}
			this.activeTimers.delete(type);
			enqueue([event]);
		}, spec.delayMs);

		return {
			cancel: () => {
				cancelled = true;
				clearTimeout(timer);
			},
		};
	}
}
