import { getSandVariant } from "./sand-variant.js";

export const SAND_CLIENT_TYPE = "sand";

const SAND_CLIENT_FALLBACK_BASE_VERSION = "0.1.0";
const SAND_CLIENT_VERSION_DEV_SUFFIX = "-dev";
const SAND_CLIENT_VERSION_LAB_SUFFIX = "-lab";

const STAMPED_VERSION_BASE = /^(\d+\.\d+\.\d+)(?:-.+)?$/;

function getSandClientBaseVersion(): string {
	const stamped = process.env.SAND_CLIENT_APP_VERSION?.trim() ?? "";
	return STAMPED_VERSION_BASE.exec(stamped)?.[1] ?? SAND_CLIENT_FALLBACK_BASE_VERSION;
}

export type SandBoxNamespace = "prod" | "dev" | "lab";

/** Header name consumed by backend box-tenant routing. */
export const SAND_BOX_NAMESPACE_HEADER = "x-sand-box-namespace";

/** Resolves box namespace lazily from the current process stamps. */
export function getSandBoxNamespace(): SandBoxNamespace {
	const ownerNamespace = process.env.SAND_BOX_OWNER_NAMESPACE?.trim();
	if (ownerNamespace === "dev" || ownerNamespace === "lab") {
		return ownerNamespace;
	}
	switch (getSandVariant()) {
		case "sand-dev":
			return "dev";
		case "sand-lab":
			return "lab";
		default:
			return "prod";
	}
}

// The flavor suffix derives from the same namespace as the header, so suffix-parse and header backends resolve the same tenant; the stamped prerelease flavor is stripped above so it can never read as a tenant fork.
export function getSandClientVersion(): string {
	const baseVersion = getSandClientBaseVersion();
	switch (getSandBoxNamespace()) {
		case "dev":
			return `${baseVersion}${SAND_CLIENT_VERSION_DEV_SUFFIX}`;
		case "lab":
			return `${baseVersion}${SAND_CLIENT_VERSION_LAB_SUFFIX}`;
		case "prod":
			return baseVersion;
	}
}

/** Attribution headers for raw backend HTTP requests outside Connect. */
export function getSandBackendClientHeaders(): {
	readonly "x-cursor-client-type": typeof SAND_CLIENT_TYPE;
	readonly "x-cursor-client-version": string;
	readonly "x-sand-box-namespace": SandBoxNamespace;
} {
	return {
		"x-cursor-client-type": SAND_CLIENT_TYPE,
		"x-cursor-client-version": getSandClientVersion(),
		"x-sand-box-namespace": getSandBoxNamespace(),
	};
}
