import { SAND_UPDATE_TRACKS, type SandUpdateTrack } from "./update.js";

export { SAND_UPDATE_TRACKS, type SandUpdateTrack };

/**
 * Disables the nightly update track: Settings hides it, a persisted nightly
 * override is coerced to stable, and the updater never targets the nightly feed.
 */
export const NIGHTLY_UPDATE_TRACK_DISABLED = true;

const INTERNAL_UPDATE_TRACKS: readonly SandUpdateTrack[] = ["dogfood"];

/**
 * The tracks a user may select in the Settings → Updates UI: never nightly while
 * `NIGHTLY_UPDATE_TRACK_DISABLED` is set, internal tracks only when unlocked.
 */
export function selectableUpdateTracks(unlockInternalTracks: boolean): readonly SandUpdateTrack[] {
	return SAND_UPDATE_TRACKS.filter((track) => {
		if (NIGHTLY_UPDATE_TRACK_DISABLED && track === "nightly") {
			return false;
		}
		if (INTERNAL_UPDATE_TRACKS.includes(track)) {
			return unlockInternalTracks;
		}
		return true;
	});
}

/**
 * The tracks the Settings UI offers: the selectable set plus the effective
 * track, so the control never misses its own value (managed lock, bootstrap window).
 */
export function availableUpdateTracks(input: {
	readonly unlockInternalTracks: boolean;
	readonly effectiveTrack: SandUpdateTrack;
}): readonly SandUpdateTrack[] {
	const selectable = selectableUpdateTracks(input.unlockInternalTracks);
	return SAND_UPDATE_TRACKS.filter(
		(track) => selectable.includes(track) || track === input.effectiveTrack,
	);
}

export function isSandUpdateTrack(value: unknown): value is SandUpdateTrack {
	return typeof value === "string" && (SAND_UPDATE_TRACKS as readonly string[]).includes(value);
}

/**
 * Coerce a stored or derived track to one that currently publishes builds.
 * While Nightly is disabled (see `NIGHTLY_UPDATE_TRACK_DISABLED`) a "nightly"
 * value becomes "stable" so nobody is stranded on a track that no longer
 * ships. When Nightly is re-enabled this is the identity function.
 */
export function coerceToEnabledTrack(track: SandUpdateTrack): SandUpdateTrack {
	if (NIGHTLY_UPDATE_TRACK_DISABLED && track === "nightly") {
		return "stable";
	}
	return track;
}

/**
 * The `sand_internal_release_track_override` policy, validated: `managedTrack`
 * locks the Settings picker; `unlockInternalTracks` reveals internal tracks.
 */
export interface SandReleaseTrackGate {
	readonly managedTrack: SandUpdateTrack | undefined;
	readonly unlockInternalTracks: boolean;
}

// Statsig values arrive through an unvalidated merge, so every field is checked:
// a wrong-typed, unknown, empty, or disabled-track value reads as unset.
export function resolveReleaseTrackGate(config: {
	readonly releaseTrack?: unknown;
	readonly unlockInternalTracks?: unknown;
}): SandReleaseTrackGate {
	return {
		managedTrack: toManagedUpdateTrack(config.releaseTrack),
		unlockInternalTracks: config.unlockInternalTracks === true,
	};
}

function toManagedUpdateTrack(value: unknown): SandUpdateTrack | undefined {
	if (typeof value !== "string") {
		return undefined;
	}
	const track = value.trim();
	if (!isSandUpdateTrack(track)) {
		return undefined;
	}
	return coerceToEnabledTrack(track) === track ? track : undefined;
}

/**
 * The track a running app updates from: managed policy ?? user choice ?? the
 * build's published track (package.json `sandTrack`) ?? stable, coerced to enabled.
 */
export function resolveEffectiveTrack(input: {
	readonly managedTrack?: SandUpdateTrack;
	readonly userOverride: SandUpdateTrack | null;
	readonly buildDefault: SandUpdateTrack | null;
}): SandUpdateTrack {
	return coerceToEnabledTrack(
		input.managedTrack ?? input.userOverride ?? input.buildDefault ?? "stable",
	);
}
