/**
 * Bounded capture of a stdio MCP child's stderr, and the plumbing that attaches
 * it to a connect failure.
 *
 * Without this, a stdio server that dies before `initialize` surfaces only the
 * SDK's generic "Connection closed", and the child's own diagnostics
 * (unreachable host, missing credential, bad interpreter) are discarded — the
 * VM-side logs that would explain a cloud-agent MCP failure never leave the pod.
 *
 * Mirrors the IDE's capture in `@anysphere/mcp-core`'s transport factory, and
 * shares its byte cap so the two surfaces truncate identically.
 */
import type { Stream } from "node:stream";
import {
  STDIO_CONNECT_STDERR_CAPTURE_MAX_BYTES,
  sanitizeErrorMessageForLog,
} from "@anysphere/mcp-core";

/**
 * How long a failed connect waits for the child's stderr to drain before
 * reading the tail. The SDK's `close()` already waits for the child's `close`
 * event, so this only covers the stream ticks between the last write and our
 * `data` handler.
 */
const STDERR_FLUSH_TIMEOUT_MS = 250;

const STDERR_TAIL_PROPERTY = "mcpStdioStderrTail";

export interface StdioStderrCapture {
  /**
   * The captured tail as a single normalized line with credential-shaped
   * values redacted, or `""` when the child wrote nothing.
   */
  read(): string;
  /** Resolves once stderr ends, or after {@link STDERR_FLUSH_TIMEOUT_MS}. */
  waitForFlush(): Promise<void>;
}

/**
 * Starts consuming `stderr` immediately. Call this before `connect()`: the MCP
 * SDK builds the stderr `PassThrough` in the transport constructor precisely so
 * listeners can attach ahead of the spawn and catch the child's earliest
 * output.
 */
export function captureStdioStderr(stderr: Stream | null): StdioStderrCapture {
  let captured = "";
  let ended = stderr === null;

  if (stderr !== null) {
    // Never detached, including after a successful connect. The SDK pipes the
    // child's stderr into a PassThrough; with no consumer, a chatty server's
    // writes block once the high-water mark fills.
    stderr.on("data", (chunk: Buffer | string) => {
      const remaining =
        STDIO_CONNECT_STDERR_CAPTURE_MAX_BYTES - captured.length;
      if (remaining <= 0) {
        return;
      }
      captured += chunk.toString().slice(0, remaining);
    });
    stderr.once("end", () => {
      ended = true;
    });
  }

  return {
    // The child's stderr is outside our control and can carry tokens or other
    // credentials, so redact before it reaches a log line or an error message.
    read: () =>
      sanitizeErrorMessageForLog(captured.replace(/\s+/g, " ").trim(), {
        maxLength: STDIO_CONNECT_STDERR_CAPTURE_MAX_BYTES,
      }),
    waitForFlush: async () => {
      if (ended || stderr === null) {
        return;
      }
      await new Promise<void>(resolve => {
        let timer: NodeJS.Timeout | undefined;
        const finish = (): void => {
          if (timer !== undefined) {
            clearTimeout(timer);
          }
          stderr.off("end", finish);
          resolve();
        };
        timer = setTimeout(finish, STDERR_FLUSH_TIMEOUT_MS);
        timer.unref();
        stderr.once("end", finish);
      });
    },
  };
}

/**
 * Folds `stderrTail` into `error` and returns it for rethrow.
 *
 * The error is annotated in place rather than wrapped: callers branch on the
 * concrete type (`loadCommandBasedServerWithElicitation` maps
 * `SandboxUnsupportedError` to `McpSandboxUnavailableError`), and a wrapper
 * would silently drop those failures into the generic path.
 */
export function annotateMcpStdioConnectError(
  error: unknown,
  stderrTail: string
): unknown {
  if (stderrTail === "") {
    return error;
  }
  const annotated = error instanceof Error ? error : new Error(String(error));
  annotated.message = `${annotated.message}; stderr: ${stderrTail}`;
  Object.defineProperty(annotated, STDERR_TAIL_PROPERTY, {
    value: stderrTail,
    enumerable: false,
    configurable: true,
    writable: true,
  });
  return annotated;
}

/**
 * The stderr tail recorded by {@link annotateMcpStdioConnectError}, for log
 * sites that want it as a structured field rather than inside the message.
 */
export function getMcpStdioStderrTail(error: unknown): string | undefined {
  if (!(error instanceof Error)) {
    return undefined;
  }
  const tail = (error as { [STDERR_TAIL_PROPERTY]?: unknown })[
    STDERR_TAIL_PROPERTY
  ];
  return typeof tail === "string" ? tail : undefined;
}
