import { type Context, createSpan } from "@anysphere/context";
import type {
  TerminalCommandOptions,
  TerminalEvent,
  TerminalExecutor,
} from "./types.js";

export class LazyTerminalExecutor implements TerminalExecutor {
  private promise: Promise<TerminalExecutor> | undefined;

  constructor(private readonly initializer: () => Promise<TerminalExecutor>) {}

  private getExecutor(): Promise<TerminalExecutor> {
    if (this.promise === undefined) {
      this.promise = this.initializer();
    }
    return this.promise;
  }

  async getCwd(): Promise<string> {
    const executor = await this.getExecutor();
    return executor.getCwd();
  }

  clone(workingDirectory?: string): TerminalExecutor {
    return new LazyTerminalExecutor(async () => {
      const executor = await this.getExecutor();
      return executor.clone(workingDirectory);
    });
  }

  async *execute(
    ctx: Context,
    command: string,
    options?: TerminalCommandOptions
  ): AsyncIterable<TerminalEvent> {
    using _span = createSpan(ctx.withName("LazyTerminalExecutor.execute"));

    const executor = await this.getExecutor();
    for await (const event of executor.execute(ctx, command, options)) {
      yield event;
    }
  }
}
