import { z } from "zod";

export {
	SAND_DEFAULT_MODEL_ID,
	SAND_DEFAULT_MODEL_SELECTION,
	type SandAgentDefaultModel,
	type SandAgentModelParameter,
	type SandBrowserUseModel,
	type SandComputerUseModel,
	type SandReasoningEffort,
} from "./agent-model.js";
import type { SandComputerUseModel } from "./agent-model.js";

// The external fallback compactor, matching the glass/IDE agent's control
// choice. Models with verified same-model compaction use that route first;
// unsupported models and forced-external recovery keep this large-window path.
export const SAND_SUMMARIZATION_MODEL_ID = "gemini-2.5-flash";

// The fallback model computer-use subagents run on when the user has not chosen
// one, intentionally decoupled from the parent's selected/default model.
export const SAND_COMPUTER_USE_SUBAGENT_MODEL_ID = "claude-opus-4-8";

const sandAgentModelParameterSchema = z.object({
	id: z.string().min(1),
	value: z.string(),
});

export const sandAgentDefaultModelSchema = z.object({
	modelId: z.string().min(1),
	maxMode: z.boolean(),
	parameters: z.array(sandAgentModelParameterSchema),
});

export const sandComputerUseModelSchema = sandAgentDefaultModelSchema.refine(
	(model) => model.modelId.trim().length > 0,
	{ path: ["modelId"] },
);

export const sandBrowserUseModelSchema = sandAgentDefaultModelSchema.refine(
	(model) => model.modelId.trim().length > 0,
	{ path: ["modelId"] },
);

// Seeds the future computer-use picker when no selection is stored and defines
// the byte-identical fallback request used today. Explicit selections may
// replace every field through the shared picker.
export const SAND_COMPUTER_USE_MODEL_SELECTION: SandComputerUseModel = {
	modelId: SAND_COMPUTER_USE_SUBAGENT_MODEL_ID,
	maxMode: false,
	parameters: [
		{ id: "thinking", value: "false" },
		{ id: "effort", value: "low" },
	],
};

export interface ResolveComputerUseModelSelectionArgs {
	readonly storedModel: SandComputerUseModel | undefined;
	readonly overrideModel: SandComputerUseModel | undefined;
}

export function resolveComputerUseModelSelection({
	storedModel,
	overrideModel,
}: ResolveComputerUseModelSelectionArgs) {
	return overrideModel ?? storedModel;
}
