import {
  type ChildProcess,
  execFileSync,
  type SpawnOptionsWithoutStdio,
  spawn,
} from "node:child_process";
import * as fs from "node:fs";
import { realpathSync } from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { type Context, createContext, createLogger } from "@anysphere/context";
import { filterElectronEnv, scrubSocketEnvVars } from "../env-filter.js";
import { getRipgrepBinaryPath, withConfiguredRipgrepEnv } from "../ripgrep.js";
import type {
  IgnoreMapping,
  NetworkPolicy,
  SandboxPolicy,
  SandboxReadBoundary,
} from "../types.js";
import {
  convertPathsToIgnoreMapping,
  getHardcodedAllowedReadPaths,
} from "./hardcoded-policy.js";
import { registerSandboxMetadata } from "./macos/seatbelt.js";
import { isNetworkEnabledByPolicy } from "./network-policy-utils.js";
import {
  ensureSandboxPolicyDirectory,
  writeSandboxPolicyFile,
} from "./policy-file.js";

const isMacOS = process.platform === "darwin";
const isLinux = process.platform === "linux";

/**
 * Module-level logger for sandbox operations
 */
const logger = createLogger("shell-exec:sandbox");

/**
 * Append the private policy directory to additionalReadonlyPaths so Linux
 * emits one RO bind (via whole-tree `["**"]` planner fast-path) and macOS
 * seatbelt denies writes. Covers CURSOR_SANDBOX_POLICY_DIR overrides.
 */
function withPolicyDirectoryReadonly(
  additionalReadonlyPaths: string[] | undefined
): string[] {
  const dir = ensureSandboxPolicyDirectory();
  if (!additionalReadonlyPaths || additionalReadonlyPaths.length === 0) {
    return [dir];
  }
  if (additionalReadonlyPaths.includes(dir)) {
    return additionalReadonlyPaths;
  }
  return [...additionalReadonlyPaths, dir];
}

// Module-scoped configured path for the sandbox binary.
// Must be set by the host process at startup via configureSandboxPrereqs().
let configuredSandboxBinaryPath: string | undefined;

/**
 * Options for configuring sandbox prerequisites.
 */
export interface ConfigureSandboxPrereqsOptions {
  /** Path to the cursorsandbox binary (required) */
  sandboxBinaryPath: string;
}

/**
 * Configure sandbox prerequisites: sandbox binary path.
 * Requires the global ripgrep path to already be configured.
 * This is the ONLY way to initialize the sandbox system - call this at startup.
 */
export function configureSandboxPrereqs(
  options: ConfigureSandboxPrereqsOptions
): void {
  getRipgrepBinaryPath();
  const { sandboxBinaryPath } = options;
  if (!configuredSandboxBinaryPath) {
    configuredSandboxBinaryPath = sandboxBinaryPath;
  }
}

function getSandboxBinary(): string | undefined {
  return configuredSandboxBinaryPath;
}

/**
 * Returns the configured sandbox binary path, or undefined if not configured.
 * Use this to pass the binary path to MCP sandbox wrapping or other callers
 * that need the path without spawning through shell-exec.
 */
export function getSandboxBinaryPath(): string | undefined {
  return configuredSandboxBinaryPath;
}

function applyConfiguredRipgrepToSandboxEnv(env: NodeJS.ProcessEnv): void {
  if (process.platform !== "linux") {
    return;
  }

  Object.assign(env, withConfiguredRipgrepEnv(env));
}

let binaryAvailable: boolean | null = null;
let binaryCheckError: Error | null = null;
let lastSandboxFailureReason: string | null = null;
let cachedSandboxHelperSupported: boolean | null = null;
/**
 * Whether {@link cachedSandboxHelperSupported} came from a workspace-rooted
 * probe rather than the synchronous one.
 *
 * The two probes share a cache but do not ask the same question: the sync probe
 * roots at the calling process's cwd, which on Linux decides how much of the
 * filesystem the helper walks. Any sandboxed spawn — an MCP server, an early
 * terminal command — reaches the sync probe and can cache a cheap verdict before
 * the workspace-rooted probe has run. Without this flag that verdict would be
 * final, and the slow-workspace case this exists to catch would go undetected.
 */
let cachedVerdictIsWorkspaceRooted = false;
/** In-flight workspace-rooted probe, so concurrent callers share one walk. */
let inFlightWorkspaceProbe: Promise<boolean> | null = null;

interface Capabilities {
  landlock: boolean;
  bubblewrap: boolean;
  seccomp: boolean;
  userns: boolean;
  mountns: boolean;
}

function isBubblewrapAvailable(): boolean {
  const resolvedPath = resolveBubblewrapBinary();
  if (!resolvedPath) {
    return false;
  }

  try {
    execFileSync(resolvedPath, ["--version"], {
      stdio: "ignore",
      timeout: 5000,
      shell: false,
    });
    return true;
  } catch {
    return false;
  }
}

function resolveBubblewrapBinary(): string | null {
  const pathValue = process.env.PATH;
  if (!pathValue) {
    return null;
  }

  for (const dir of pathValue.split(path.delimiter)) {
    if (!dir) {
      continue;
    }

    const candidate = path.join(dir, "bwrap");
    try {
      const resolved = realpathSync(candidate);
      const stats = fs.statSync(resolved);
      if (!stats.isFile()) {
        continue;
      }
      if ((stats.mode & 0o111) === 0) {
        continue;
      }
      if (stats.uid !== 0) {
        continue;
      }
      return resolved;
    } catch {}
  }

  return null;
}

/**
 * Build the network policy object for the unified policy file, if applicable.
 * Returns undefined when no network proxy is needed (no policy, network
 * disabled, or allow-all with no deny list).
 */
function resolveNetworkPolicyForFile(
  sandboxPolicy: SandboxPolicy
): NetworkPolicy | undefined {
  if (sandboxPolicy.type === "insecure_none") {
    return undefined;
  }
  const policy: NetworkPolicy | undefined = sandboxPolicy.networkPolicy;
  if (policy === undefined) {
    return undefined;
  }
  if (!isNetworkEnabledByPolicy(policy)) {
    return undefined;
  }

  // When default is "allow" with no deny list (true full network access),
  // skip the proxy. The proxy routes all traffic through HTTP_PROXY/HTTPS_PROXY
  // env vars, which breaks programs that don't respect proxy settings (e.g.
  // ping, nslookup, raw sockets). With default "allow" and no deny list, the
  // sandbox binary falls back to direct network access (NetworkAccessMode::Allow)
  // which works for all programs.
  //
  // However, if a deny list is specified, we must use the proxy to enforce it.
  const hasDenyList = policy.deny !== undefined && policy.deny.length > 0;
  if (policy.default === "allow" && !hasDenyList) {
    return undefined;
  }

  return { version: 1, ...policy };
}

type SandboxedPolicy = Exclude<SandboxPolicy, { type: "insecure_none" }>;

type NativeSandboxPolicyCommon = {
  cwd: string;
  readBoundary: SandboxReadBoundary;
  hardcodedReadPaths: string[];
  additionalReadonlyPaths: Record<string, string[]> | undefined;
  networkAccess: boolean;
  ignoreMapping: Record<string, string[]> | undefined;
};

type NativeSandboxPolicy =
  | (NativeSandboxPolicyCommon & {
      type: "workspace_readonly";
    })
  | (NativeSandboxPolicyCommon & {
      type: "workspace_readwrite";
      additionalReadwritePaths: string[];
      disableTmpWrite: boolean;
    });

/**
 * Resolve trusted platform runtime paths for the native helper.
 * Canonicalize when present; keep lexical paths otherwise so the native
 * helper can treat missing entries as optional (`IfPresent`).
 * Kept separate from caller-controlled `additionalReadPaths`.
 */
export function resolveHardcodedAllowedReadPaths(
  platform: NodeJS.Platform = process.platform
): string[] {
  const resolved: string[] = [];
  const seen = new Set<string>();
  const bundledPaths: Record<string, string | undefined> = {};
  try {
    bundledPaths.ripgrep = getRipgrepBinaryPath();
  } catch {
    // The declarative bundled-path table simply omits unavailable artifacts.
  }
  for (const entry of getHardcodedAllowedReadPaths(
    platform,
    os.homedir(),
    bundledPaths
  )) {
    let pathToUse = entry;
    try {
      if (fs.existsSync(entry)) {
        pathToUse = realpathSync(entry);
      }
    } catch {
      // Keep the lexical path; native enforcement skips missing optional roots.
    }
    if (seen.has(pathToUse)) {
      continue;
    }
    seen.add(pathToUse);
    resolved.push(pathToUse);
  }
  return resolved;
}

function withSandboxPolicyDirectoryReadonly(
  sandboxPolicy: SandboxedPolicy
): SandboxedPolicy {
  return {
    ...sandboxPolicy,
    additionalReadonlyPaths: withPolicyDirectoryReadonly(
      sandboxPolicy.additionalReadonlyPaths
    ),
  };
}

/**
 * Turn UI/config allowlist entries into directory roots the native helper can
 * grant via subpath readonly rules. Trailing globs (`/*`, `/**`) and
 * basename globs (`*.md`) are reduced to their parent directory.
 */
export function normalizeAdditionalReadPathRoots(
  paths: readonly string[]
): string[] {
  const roots: string[] = [];
  const seen = new Set<string>();
  for (const raw of paths) {
    let entry = raw.trim();
    if (!entry) {
      continue;
    }
    if (entry === "~") {
      entry = os.homedir();
    } else if (entry.startsWith("~/") || entry.startsWith("~\\")) {
      entry = path.join(os.homedir(), entry.slice(2));
    }
    entry = entry.replace(/\/\*\*$/, "").replace(/\/\*$/, "");
    entry = entry.replace(/\\\*\*$/, "").replace(/\\\*$/, "");
    const base = path.basename(entry);
    if (base.includes("*") || base.includes("?")) {
      entry = path.dirname(entry);
    }
    if (!entry || entry === ".") {
      continue;
    }
    const normalized = path.normalize(entry);
    if (seen.has(normalized)) {
      continue;
    }
    seen.add(normalized);
    roots.push(normalized);
  }
  return roots;
}

export function buildNativeSandboxPolicy(
  sandboxPolicy: SandboxedPolicy,
  cwd: string
): NativeSandboxPolicy {
  let ignoreMapping: Record<string, string[]> | undefined;
  if (sandboxPolicy.ignoreMapping) {
    ignoreMapping = buildIgnoreMapping(
      sandboxPolicy.ignoreMapping,
      cwd,
      [],
      []
    );
  }

  const additionalReadonlyPaths = buildReadOnlyJson(
    sandboxPolicy.additionalReadonlyPaths,
    sandboxPolicy.writeProtectionMapping,
    cwd
  );
  const readBoundary = sandboxPolicy.readBoundary ?? "system";
  const trustedReadPaths = resolveHardcodedAllowedReadPaths();
  const allowlistRoots =
    readBoundary === "workspace"
      ? normalizeAdditionalReadPathRoots(
          sandboxPolicy.additionalReadPaths ?? []
        )
      : [];
  const hardcodedReadPaths = [...trustedReadPaths];
  const seen = new Set(trustedReadPaths);
  for (const root of allowlistRoots) {
    if (seen.has(root)) {
      continue;
    }
    seen.add(root);
    hardcodedReadPaths.push(root);
  }
  const common = {
    cwd,
    readBoundary,
    hardcodedReadPaths,
    additionalReadonlyPaths,
    networkAccess: isNetworkEnabledByPolicy(sandboxPolicy.networkPolicy),
    ignoreMapping,
  };

  if (sandboxPolicy.type === "workspace_readonly") {
    return {
      type: sandboxPolicy.type,
      ...common,
    };
  }

  return {
    type: sandboxPolicy.type,
    ...common,
    additionalReadwritePaths: sandboxPolicy.additionalReadwritePaths || [],
    disableTmpWrite: sandboxPolicy.disableTmpWrite || false,
  };
}

/**
 * Check if the sandbox binary is available
 */
function checkBinaryAvailable(ctx: Context): boolean {
  if (binaryAvailable !== null) {
    return !!binaryAvailable;
  }

  try {
    const bin = getSandboxBinary();
    logger.info(ctx, `[checkBinaryAvailable] Resolved binary path: ${bin}`);

    if (!bin) {
      binaryCheckError = new Error("Sandbox binary path was not configured");
      binaryAvailable = false;
      logger.info(
        ctx,
        "[checkBinaryAvailable] Binary path not set, returning false"
      );
      return false;
    }

    binaryAvailable = fs.existsSync(bin);
    if (!binaryAvailable) {
      binaryCheckError = new Error(`Sandbox binary not found at ${bin}`);
      logger.info(ctx, `[checkBinaryAvailable] Binary not found at: ${bin}`);
    } else {
      logger.info(
        ctx,
        `[checkBinaryAvailable] Binary path exists: ${binaryAvailable}`
      );
    }

    return !!binaryAvailable;
  } catch (e) {
    binaryCheckError = e as Error;
    binaryAvailable = false;
    logger.info(ctx, `[checkBinaryAvailable] Exception checking binary: ${e}`);
    return false;
  }
}

/**
 * Clear the cached sandbox-support verdict. Test-only: production code caches
 * for the process lifetime on purpose.
 */
export function resetSandboxSupportCacheForTests(): void {
  cachedSandboxHelperSupported = null;
  cachedVerdictIsWorkspaceRooted = false;
  inFlightWorkspaceProbe = null;
  lastSandboxFailureReason = null;
}

/**
 * Check if sandboxing is supported on this system
 */
export function isSandboxHelperSupported(ctx?: Context): boolean {
  if (cachedSandboxHelperSupported !== null) {
    return cachedSandboxHelperSupported;
  }
  const effectiveCtx = ctx ?? createContext();
  logger.info(
    effectiveCtx,
    "[isSandboxHelperSupported] Starting sandbox support check..."
  );

  if (!checkBinaryAvailable(effectiveCtx)) {
    const reason = binaryCheckError?.message || "Binary check failed";
    lastSandboxFailureReason = reason;
    logger.info(
      effectiveCtx,
      `[isSandboxHelperSupported] Binary not available, returning false. Reason: ${reason}`
    );
    cachedSandboxHelperSupported = false;
    return cachedSandboxHelperSupported;
  }

  // Windows: the native helper only applies network proxy / no-network env (no filesystem sandbox).
  // Return false since we don't provide meaningful filesystem isolation on Windows.
  if (process.platform === "win32") {
    lastSandboxFailureReason =
      "Windows sandbox helper only provides network proxy, not filesystem isolation";
    logger.info(
      effectiveCtx,
      "[isSandboxHelperSupported] win32: returning false (proxy-only, no filesystem sandbox)"
    );
    cachedSandboxHelperSupported = false;
    return cachedSandboxHelperSupported;
  }

  // On macOS, if the binary exists, sandboxing is supported - no preflight needed
  // macOS uses sandbox-exec which is always available on the system
  if (process.platform === "darwin") {
    lastSandboxFailureReason = null; // Clear any previous failure
    logger.info(
      effectiveCtx,
      `[isSandboxHelperSupported] ${process.platform} platform, binary available, sandbox supported!`
    );
    cachedSandboxHelperSupported = true;
    return cachedSandboxHelperSupported;
  }

  // Linux: Preflight to detect issues like mount limit or missing kernel features
  const { binaryPath, args, env } = buildPreflightInvocation(
    effectiveCtx,
    process.cwd()
  );
  try {
    const preflightStart = Date.now();
    execFileSync(binaryPath, args, {
      stdio: ["ignore", "ignore", "pipe"],
      timeout: PREFLIGHT_PROBE_TIMEOUT_MS,
      env,
      shell: false,
    });
    const preflightMs = Date.now() - preflightStart;

    lastSandboxFailureReason = null; // Clear any previous failure
    // Log the duration: this probe runs from the ext-host cwd with an empty
    // policy, so it can pass in milliseconds while a real command from a large
    // git workspace spends minutes in the helper's pre-discovery walk. Without
    // the number there is nothing to compare the two against.
    logger.info(
      effectiveCtx,
      `[isSandboxHelperSupported] Preflight succeeded in ${preflightMs}ms, sandbox supported!`
    );
    cachedSandboxHelperSupported = true;
    return cachedSandboxHelperSupported;
  } catch (e: unknown) {
    const error = e as { message?: string; status?: number; stderr?: Buffer };
    return recordPreflightFailure(effectiveCtx, {
      message: error.message,
      status: error.status,
      stderrText: error.stderr?.toString?.() || "",
    });
  }
}

/** Budget for one capability probe of the sandbox helper. */
const PREFLIGHT_PROBE_TIMEOUT_MS = 15_000;

/**
 * Build the helper invocation used by both capability probes.
 *
 * The policy is deliberately minimal — the probe answers "can this host start a
 * sandbox rooted at `cwd`", not "is this exact policy enforceable". `cwd` still
 * matters and is the caller's choice: the helper's pre-discovery walks the tree
 * beneath it, which is the dominant cost of starting a sandboxed command, so a
 * probe rooted somewhere cheap (a home directory) says nothing about a command
 * rooted in a large git workspace.
 */
function buildPreflightInvocation(
  ctx: Context,
  cwd: string
): { binaryPath: string; args: string[]; env: NodeJS.ProcessEnv } {
  const unifiedPolicy = {
    sandbox: buildNativeSandboxPolicy(
      withSandboxPolicyDirectoryReadonly({ type: "workspace_readwrite" }),
      cwd
    ),
  };

  const binaryPath = String(getSandboxBinary());
  logger.info(
    ctx,
    `[sandboxPreflight] Running preflight with binary: ${binaryPath}`
  );
  logger.info(ctx, `[sandboxPreflight] CWD: ${cwd}`);

  const env: NodeJS.ProcessEnv = { ...process.env };
  applyConfiguredRipgrepToSandboxEnv(env);

  const policyFilePath = writeSandboxPolicyFile(JSON.stringify(unifiedPolicy));

  return {
    binaryPath,
    args: ["--policy", policyFilePath, "--preflight-only", "--", "/bin/true"],
    env,
  };
}

/**
 * Record a failed capability probe: log it, cache "unsupported", and keep the
 * reason for {@link getLastSandboxFailureReason}. Always returns false.
 */
function recordPreflightFailure(
  ctx: Context,
  failure: { message?: string; status?: number | null; stderrText: string }
): boolean {
  const { message, status, stderrText } = failure;
  logger.error(ctx, `[sandboxPreflight] Preflight failed: ${message}`);
  logger.error(ctx, `[sandboxPreflight] Exit status: ${status}`);
  if (stderrText) {
    logger.error(ctx, `[sandboxPreflight] Stderr: ${stderrText}`);
  }

  // If helper returned code 2, treat as unsupported
  if (status === 2) {
    lastSandboxFailureReason = `Linux preflight failed with exit code 2 (unsupported kernel features). stderr: ${stderrText || "none"}`;
  } else {
    lastSandboxFailureReason = `Linux preflight failed: ${message || "unknown error"}. Exit status: ${status}. stderr: ${stderrText || "none"}`;
  }
  cachedSandboxHelperSupported = false;
  return false;
}

/**
 * Populate the cached sandbox-support verdict from a probe rooted at
 * `workspaceCwd`, without blocking the calling thread.
 *
 * {@link isSandboxHelperSupported} probes from the host process's own cwd with
 * `execFileSync`, which is why it has to stay cheap: it blocks. That made it
 * both too optimistic and unable to see the failure it most needs to catch — a
 * host where the sandbox does start, but the pre-discovery walk of the workspace
 * takes longer than the terminal tool will wait, so every sandboxed command
 * times out while the boot probe reports "supported" in milliseconds.
 *
 * Probing from the workspace root with a budget catches that: a workspace too
 * slow to scan is cached as unsupported, and `spawnInSandbox` then throws
 * `SandboxUnsupportedError` so the caller degrades to allowlist/ask instead of
 * issuing commands that cannot finish. Callers that force sandboxing must keep
 * surfacing the reason rather than silently downgrading.
 *
 * Deliberately *overrides* a verdict already cached by the synchronous probe:
 * that verdict was measured from the wrong directory, and treating it as final
 * would let one early sandboxed spawn suppress this probe for the session.
 * Concurrent callers share one walk; a workspace-rooted verdict is reused.
 */
export async function primeSandboxHelperSupport(opts: {
  workspaceCwd: string;
  timeoutMs?: number;
  ctx?: Context;
}): Promise<boolean> {
  if (cachedVerdictIsWorkspaceRooted && cachedSandboxHelperSupported !== null) {
    return cachedSandboxHelperSupported;
  }
  if (inFlightWorkspaceProbe !== null) {
    return inFlightWorkspaceProbe;
  }

  inFlightWorkspaceProbe = probeSandboxSupportFromWorkspace(opts).finally(
    () => {
      inFlightWorkspaceProbe = null;
    }
  );
  return inFlightWorkspaceProbe;
}

async function probeSandboxSupportFromWorkspace(opts: {
  workspaceCwd: string;
  timeoutMs?: number;
  ctx?: Context;
}): Promise<boolean> {
  const ctx = opts.ctx ?? createContext();
  // Only the Linux probe walks the filesystem; every other platform's verdict is
  // a cheap capability check that does not depend on cwd, so the synchronous
  // path is already authoritative.
  if (!isLinux || !checkBinaryAvailable(ctx)) {
    const supported = isSandboxHelperSupported(ctx);
    cachedVerdictIsWorkspaceRooted = true;
    return supported;
  }

  if (cachedSandboxHelperSupported !== null) {
    logger.info(
      ctx,
      `[primeSandboxHelperSupport] Re-probing from ${opts.workspaceCwd}; the cached verdict (${cachedSandboxHelperSupported}) was measured from a different directory`
    );
  }

  const timeoutMs = opts.timeoutMs ?? PREFLIGHT_PROBE_TIMEOUT_MS;
  const { binaryPath, args, env } = buildPreflightInvocation(
    ctx,
    opts.workspaceCwd
  );

  const started = Date.now();
  const outcome = await runPreflightWithTimeout({
    binaryPath,
    args,
    env,
    timeoutMs,
  });
  const elapsedMs = Date.now() - started;

  if (outcome.kind === "timeout") {
    lastSandboxFailureReason =
      `Linux preflight rooted at ${opts.workspaceCwd} did not finish within ${timeoutMs}ms ` +
      `(sandbox setup for this workspace is slower than the terminal tool will wait). ` +
      `stderr: ${outcome.stderrText || "none"}`;
    logger.error(
      ctx,
      `[primeSandboxHelperSupport] Preflight timed out after ${timeoutMs}ms, treating sandbox as unsupported`
    );
    cachedSandboxHelperSupported = false;
    cachedVerdictIsWorkspaceRooted = true;
    return false;
  }

  if (outcome.kind === "failed") {
    const supported = recordPreflightFailure(ctx, {
      message: outcome.message,
      status: outcome.status,
      stderrText: outcome.stderrText,
    });
    cachedVerdictIsWorkspaceRooted = true;
    return supported;
  }

  lastSandboxFailureReason = null;
  logger.info(
    ctx,
    `[primeSandboxHelperSupport] Preflight rooted at ${opts.workspaceCwd} succeeded in ${elapsedMs}ms, sandbox supported!`
  );
  cachedSandboxHelperSupported = true;
  cachedVerdictIsWorkspaceRooted = true;
  return true;
}

type PreflightOutcome =
  | { kind: "ok" }
  | {
      kind: "failed";
      message?: string;
      status?: number | null;
      stderrText: string;
    }
  | { kind: "timeout"; stderrText: string };

/**
 * Run the helper preflight, killing it if it outlives `timeoutMs`.
 *
 * The child is spawned `detached` so it leads its own process group, and the
 * timeout kills the whole group. That matters because the helper's pre-discovery
 * walk is the thing being bounded: it runs in the helper itself and, on Auto, is
 * primed before forking the Bubblewrap preflight child. Signalling only the
 * direct child — which is all `execFileSync`'s own `timeout` does — would leave
 * a multi-minute walk and any forked descendants running after we gave up.
 */
export function runPreflightWithTimeout(opts: {
  binaryPath: string;
  args: string[];
  env: NodeJS.ProcessEnv;
  timeoutMs: number;
}): Promise<PreflightOutcome> {
  return new Promise<PreflightOutcome>(resolve => {
    let child: ChildProcess;
    try {
      child = spawn(opts.binaryPath, opts.args, {
        stdio: ["ignore", "ignore", "pipe"],
        env: opts.env,
        shell: false,
        detached: true,
      });
    } catch (e) {
      resolve({
        kind: "failed",
        message: e instanceof Error ? e.message : String(e),
        stderrText: "",
      });
      return;
    }

    let stderrText = "";
    child.stderr?.on("data", (chunk: Buffer) => {
      stderrText += chunk.toString();
    });

    let settled = false;
    const timer = setTimeout(() => {
      if (settled) {
        return;
      }
      settled = true;
      killProcessGroup(child);
      resolve({ kind: "timeout", stderrText });
    }, opts.timeoutMs);
    // Do not hold the event loop open on the probe's account.
    timer.unref?.();

    const finish = (outcome: PreflightOutcome) => {
      if (settled) {
        return;
      }
      settled = true;
      clearTimeout(timer);
      resolve(outcome);
    };

    child.on("error", e => {
      finish({ kind: "failed", message: e.message, stderrText });
    });
    child.on("close", (code, signal) => {
      if (code === 0) {
        finish({ kind: "ok" });
        return;
      }
      finish({
        kind: "failed",
        message: `preflight exited with code ${code}${signal ? ` (signal ${signal})` : ""}`,
        status: code,
        stderrText,
      });
    });
  });
}

/**
 * SIGKILL the child's whole process group.
 *
 * Requires the child to have been spawned `detached`, which makes it the group
 * leader; `fork()`ed descendants and the bwrap it execs inherit that group, so
 * the negated pid reaches all of them. SIGKILL rather than SIGTERM because the
 * point is to stop a walk that is not checking for signals.
 */
function killProcessGroup(child: ChildProcess): void {
  const pid = child.pid;
  if (pid === undefined) {
    return;
  }
  try {
    process.kill(-pid, "SIGKILL");
  } catch {
    // Group already gone, or we lost the race with normal exit.
    try {
      child.kill("SIGKILL");
    } catch {
      // Nothing left to kill.
    }
  }
}

/**
 * Policy-aware preflight check for sandbox support.
 * Returns false if the helper reports unsupported (e.g., mount limit exceeded for this policy).
 * On Windows, always returns true if binary is available (no preflight needed).
 */
export function isSandboxHelperSupportedForPolicy(
  sandboxPolicy: SandboxPolicy,
  opts?: { cwd?: string }
): boolean {
  const ctx = createContext();
  if (!checkBinaryAvailable(ctx)) {
    return false;
  }

  if (
    sandboxPolicy.type !== "workspace_readwrite" &&
    sandboxPolicy.type !== "workspace_readonly"
  ) {
    // Only workspace_readwrite and workspace_readonly are supported
    return false;
  }

  // On Windows, if the binary exists and policy type is valid, sandboxing is supported
  if (process.platform === "win32") {
    return true;
  }

  // Linux: run preflight to detect issues like mount limit exceeded
  try {
    const cwd = String(opts?.cwd ?? process.cwd());
    const unifiedPolicy = {
      sandbox: buildNativeSandboxPolicy(
        withSandboxPolicyDirectoryReadonly(sandboxPolicy),
        cwd
      ),
    };

    const preflightEnv: NodeJS.ProcessEnv = { ...process.env };
    applyConfiguredRipgrepToSandboxEnv(preflightEnv);

    const policyFilePath = writeSandboxPolicyFile(
      JSON.stringify(unifiedPolicy)
    );

    execFileSync(
      String(getSandboxBinary()),
      ["--policy", policyFilePath, "--preflight-only", "--", "/bin/true"],
      { stdio: "ignore", timeout: 15000, env: preflightEnv, shell: false }
    );

    return true;
  } catch (e: unknown) {
    const error = e as { status?: number };
    if (typeof error?.status === "number" && error.status === 2) {
      return false;
    }
    return false;
  }
}

/**
 * Get detailed capabilities for debugging (Linux only)
 * Returns null on non-Linux platforms.
 */
export function getLinuxCapabilities(): Capabilities | null {
  if (process.platform !== "linux") {
    return null;
  }

  const ctx = createContext();
  if (!checkBinaryAvailable(ctx)) {
    return null;
  }

  try {
    // Check Landlock support
    const landlockSupported = fs.existsSync("/sys/kernel/security/landlock");
    const bubblewrapSupported = isBubblewrapAvailable();

    // Check seccomp support
    const seccompSupported = fs.existsSync("/proc/sys/kernel/seccomp");

    // Check user namespace support
    let usernsSupported = true;
    if (fs.existsSync("/proc/sys/kernel/unprivileged_userns_clone")) {
      const content = fs.readFileSync(
        "/proc/sys/kernel/unprivileged_userns_clone",
        "utf8"
      );
      usernsSupported = content.trim() === "1";
    }

    return {
      landlock: landlockSupported,
      bubblewrap: bubblewrapSupported,
      seccomp: seccompSupported,
      userns: usernsSupported,
      mountns: usernsSupported, // Mount namespaces available with user namespaces
    };
  } catch {
    return null;
  }
}

/**
 * Spawn a process with sandboxing using the native sandbox helper
 */
export function spawnWithSandboxHelper(
  command: string,
  args: string[] = [],
  options: SpawnOptionsWithoutStdio | undefined = {},
  sandboxPolicy: SandboxPolicy
): ChildProcess {
  const ctx = createContext();
  options.env = filterElectronEnv(options.env);

  if (!checkBinaryAvailable(ctx)) {
    throw new Error(
      `Sandbox binary not available: ${binaryCheckError?.message || `binary not configured`}. ` +
        `Please build the binary or use 'insecure_none' policy.`
    );
  }

  if (sandboxPolicy.type === "insecure_none") {
    return spawn(command, args, options); // nosemgrep: detect-child-process
  }

  if (
    sandboxPolicy.type === "workspace_readwrite" ||
    sandboxPolicy.type === "workspace_readonly"
  ) {
    return spawnWithSandboxHelperPolicy(command, args, options, sandboxPolicy);
  }

  throw new Error(`Unsupported sandbox policy: ${String(sandboxPolicy)}`);
}

function spawnWithSandboxHelperPolicy(
  command: string,
  args: string[],
  options: SpawnOptionsWithoutStdio,
  sandboxPolicy: SandboxPolicy
): ChildProcess {
  if (
    sandboxPolicy.type !== "workspace_readwrite" &&
    sandboxPolicy.type !== "workspace_readonly"
  ) {
    throw new Error(
      "Expected workspace_readwrite or workspace_readonly policy"
    );
  }

  const executionCwd = String(options.cwd ?? process.cwd());
  const cwd = sandboxPolicy.sandboxWorkspaceRoot ?? executionCwd;

  // Handle shell option
  let actualCommand = command;
  let actualArgs = args;

  if (options.shell) {
    if (process.platform === "win32") {
      const shellPath =
        typeof options.shell === "string" ? options.shell : "cmd.exe";
      actualCommand = shellPath;
      actualArgs = ["/c", `${command} ${args.join(" ")}`];
    } else {
      const shellPath =
        typeof options.shell === "string" ? options.shell : "/bin/sh";
      actualCommand = shellPath;
      actualArgs = ["-c", `${command} ${args.join(" ")}`];
    }
  }

  const sandbox = buildNativeSandboxPolicy(
    withSandboxPolicyDirectoryReadonly(sandboxPolicy),
    cwd
  );

  // Build the unified policy file object
  const resolvedNetworkPolicy = resolveNetworkPolicyForFile(sandboxPolicy);
  const unifiedPolicy: Record<string, unknown> = { sandbox };
  if (resolvedNetworkPolicy !== undefined) {
    unifiedPolicy.networkPolicy = resolvedNetworkPolicy;
  }
  if (sandboxPolicy.networkPolicyStrict === false) {
    unifiedPolicy.networkPolicyStrict = false;
  }

  const policyFilePath = writeSandboxPolicyFile(JSON.stringify(unifiedPolicy));

  const sandboxArgs = [
    "--policy",
    policyFilePath,
    "--",
    actualCommand,
    ...actualArgs,
  ];

  // Merge environment, including the configured ripgrep binary for Linux file discovery.
  // On Linux, scrub env vars that reference host Unix sockets hidden by mount
  // isolation (/run, /var/run, /tmp replaced with private tmpfs).
  const baseEnv =
    process.platform === "linux"
      ? scrubSocketEnvVars(process.env)
      : process.env;
  const optionsEnv =
    process.platform === "linux" && options.env
      ? scrubSocketEnvVars(options.env)
      : options.env;
  const mergedEnv: NodeJS.ProcessEnv = {
    ...baseEnv,
    ...optionsEnv,
    CURSOR_SANDBOX: "native",
  };

  applyConfiguredRipgrepToSandboxEnv(mergedEnv);

  const spawnOptions: SpawnOptionsWithoutStdio = {
    cwd: options.cwd || executionCwd,
    env: mergedEnv,
    stdio: options.stdio || ["pipe", "pipe", "pipe"],
  };

  try {
    const startTime = new Date();
    const child = spawn(String(getSandboxBinary()), sandboxArgs, spawnOptions);

    if (isMacOS && child.pid) {
      registerSandboxMetadata(child, {
        startTime,
        pid: child.pid,
      });
    }

    return child;
  } catch (e) {
    throw new Error(`Failed to spawn sandboxed process: ${e}`);
  }
}

/**
 * Walk upward from `dir` to check whether the path sits inside a git-backed
 * tree (i.e. some ancestor has a `.git` directory or worktree pointer file).
 *
 * Mirrors the Rust `is_git_backed_path()` in sandbox-helper/native/sandbox/src/types.rs.
 */
function isGitBackedSync(dir: string): boolean {
  let current = path.resolve(dir);
  for (;;) {
    try {
      const dotGit = path.join(current, ".git");
      if (fs.existsSync(dotGit)) {
        return true;
      }
    } catch {
      // permission errors, etc. — keep walking
    }
    const parent = path.dirname(current);
    if (parent === current) {
      return false;
    }
    current = parent;
  }
}

/**
 * Build the combined additionalReadonlyPaths mapping for the Rust sandbox binary.
 * Merges absolute path strings (SSL certs, SSH keys) converted via
 * convertPathsToIgnoreMapping with the workspace write-protection IgnoreMapping
 * from the merged policy.
 *
 * For non-git-backed workspaces on Linux (e.g. $HOME), the workspace
 * write-protection patterns are skipped because they would cause the Rust
 * walker to recursively scan the entire workspace tree — catastrophically
 * expensive for broad roots.
 *
 * We still preserve the explicit readonly path mapping derived from
 * `additionalReadonlyPaths` (for example SSL certs and ~/.ssh), and on macOS we
 * keep the workspace write-protection mapping too because seatbelt converts
 * those patterns directly into regex rules rather than recursively walking the
 * filesystem.
 */
function buildReadOnlyJson(
  additionalReadonlyPaths: string[] | undefined,
  writeProtectionMapping: IgnoreMapping | undefined,
  cwd: string
): Record<string, string[]> | undefined {
  const fromPaths =
    additionalReadonlyPaths && additionalReadonlyPaths.length > 0
      ? convertPathsToIgnoreMapping(...additionalReadonlyPaths)
      : {};

  const cwdIsGitBacked = isGitBackedSync(cwd);
  const fromWorkspace =
    !isLinux || cwdIsGitBacked ? (writeProtectionMapping ?? {}) : {};

  const merged: IgnoreMapping = { ...fromPaths };
  for (const [dir, patterns] of Object.entries(fromWorkspace)) {
    if (merged[dir]) {
      merged[dir] = [...merged[dir], ...patterns];
    } else {
      merged[dir] = patterns;
    }
  }

  if (Object.keys(merged).length === 0) {
    return undefined;
  }
  return normalizeIgnoreMapping(merged, cwd, [], []);
}

/**
 * Convert IgnoreMapping to the normalized object format expected by the
 * Rust sandbox helper.
 * Patterns are stored directly as string arrays, so we just need to
 * convert paths and handle canonical paths.
 */
function buildIgnoreMapping(
  ignoreMapping: IgnoreMapping,
  _cwd: string,
  _additionalReadwrite: string[],
  _additionalReadonly: string[]
): Record<string, string[]> {
  return normalizeIgnoreMapping(
    ignoreMapping,
    _cwd,
    _additionalReadwrite,
    _additionalReadonly
  );
}

function normalizeIgnoreMapping(
  ignoreMapping: IgnoreMapping,
  _cwd: string,
  _additionalReadwrite: string[],
  _additionalReadonly: string[]
): Record<string, string[]> {
  const result: Record<string, string[]> = {};

  for (const [path, patterns] of Object.entries(ignoreMapping)) {
    // Convert file:// URIs to file system paths
    const fsPath = path.startsWith("file://") ? uriToFsPath(path) : path;

    // Patterns are already string[], use directly
    result[fsPath] = patterns;

    // Also add canonical path if different
    const canonicalPath = tryRealpath(fsPath);
    if (canonicalPath !== fsPath) {
      result[canonicalPath] = patterns;
    }
  }

  return result;
}

function uriToFsPath(uri: string): string {
  let path = uri.replace(/^file:\/\//, "");
  path = decodeURIComponent(path);
  if (path.length > 1 && path.endsWith("/")) {
    path = path.slice(0, -1);
  }
  return path;
}

function tryRealpath(p: string): string {
  try {
    return realpathSync(p);
  } catch {
    return p;
  }
}

/**
 * Get the binary check error for debugging
 */
export function getBinaryCheckError(): Error | null {
  return binaryCheckError;
}

/**
 * Get the last sandbox failure reason for debugging.
 * Returns null if sandbox support check passed or hasn't been run.
 */
export function getLastSandboxFailureReason(): string | null {
  return lastSandboxFailureReason;
}
