import { readdir, readFile } from "node:fs/promises";
import { join } from "node:path";
import {
  MCP_DISK_CATALOG_MCPS_DIR,
  MCP_DISK_CATALOG_TOOLS_DIR,
  parseMcpToolNameFromDiskDefinitionJson,
} from "@anysphere/agent-exec";
import { sanitizeServerName } from "./mcp.js";

/** Result of reading one workspace root's on-disk MCP tool catalog. */
export type McpDiskCatalogProjectReadResult = {
  toolNames: string[];
  /** False when the expected tools directory is missing (ENOENT). */
  toolsDirExists: boolean;
};

/**
 * Lists MCP tool names from on-disk definitions for one workspace root, using the same
 * path layout as {@link McpFileSystemWriter}.
 */
export async function readMcpDiskCatalogToolNamesForProjectDir(
  projectDir: string,
  serverIdentifier: string
): Promise<McpDiskCatalogProjectReadResult> {
  const sanitized = sanitizeServerName(serverIdentifier);
  const toolsDir = join(
    projectDir,
    MCP_DISK_CATALOG_MCPS_DIR,
    sanitized,
    MCP_DISK_CATALOG_TOOLS_DIR
  );

  let entries: string[];
  try {
    entries = await readdir(toolsDir);
  } catch (err: unknown) {
    if ((err as NodeJS.ErrnoException)?.code === "ENOENT") {
      return { toolNames: [], toolsDirExists: false };
    }
    throw err;
  }

  const toolNames = await Promise.all(
    entries.map(async (entryName): Promise<string | undefined> => {
      if (!entryName.endsWith(".json")) {
        return undefined;
      }
      try {
        const content = await readFile(join(toolsDir, entryName), "utf8");
        return parseMcpToolNameFromDiskDefinitionJson(content);
      } catch {
        return undefined;
      }
    })
  );

  const unique = new Set<string>();
  for (const name of toolNames) {
    if (name) {
      unique.add(name);
    }
  }
  const sorted = Array.from(unique).sort((a, b) => a.localeCompare(b));
  return { toolNames: sorted, toolsDirExists: true };
}

/**
 * Merges disk catalog tool names across multiple Cursor project directories
 * (same base path as the MCP on-disk writer: ~/.cursor/projects/<slug>/), not workspace folder roots.
 */
export async function readMcpDiskCatalogToolNamesForWorkspaceRoots(
  projectDirs: readonly string[],
  serverIdentifier: string
): Promise<string[] | undefined> {
  if (projectDirs.length === 0) {
    return undefined;
  }
  let anyToolsDirExisted = false;
  const merged = new Set<string>();
  for (const dir of projectDirs) {
    const { toolNames, toolsDirExists } =
      await readMcpDiskCatalogToolNamesForProjectDir(dir, serverIdentifier);
    if (toolsDirExists) {
      anyToolsDirExisted = true;
    }
    for (const n of toolNames) {
      merged.add(n);
    }
  }
  if (!anyToolsDirExisted) {
    return undefined;
  }
  const mergedSorted = Array.from(merged).sort((a, b) => a.localeCompare(b));
  return mergedSorted;
}
