import { type SpawnOptions, spawn as spawnOg } from "node:child_process";

import type { Observer, Subject } from "rxjs";
import { AsyncSubject, merge, Observable, of, Subscription, timer } from "rxjs";
import { map, reduce, retry as rxRetry } from "rxjs/operators";
import { findActualExecutable } from "./find-executable.js";

export type ObservableWithPid<T> = Observable<T> & { pid: number };
export type SpawnOptionsWithExtras = SpawnOptions & SpawnRxExtras;

/**
 * Custom error class for spawn operations with additional metadata
 */
export class SpawnError extends Error {
  public readonly exitCode: number;
  public readonly code: number;
  public readonly stdout?: string;
  public readonly stderr?: string;
  public readonly command: string;
  public readonly args: string[];

  constructor(
    message: string,
    exitCode: number,
    command: string,
    args: string[],
    stdout?: string,
    stderr?: string
  ) {
    super(message);
    this.name = "SpawnError";
    this.exitCode = exitCode;
    this.code = exitCode;
    this.stdout = stdout;
    this.stderr = stderr;
    this.command = command;
    this.args = args;

    // Maintains proper stack trace for where our error was thrown (only available on V8)
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    if ((Error as any).captureStackTrace) {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      (Error as any).captureStackTrace(this, SpawnError);
    }
  }
}

export type SpawnRxExtras = {
  /**
   * Observable that emits strings to write to the spawned process's stdin.
   * If provided, the process will consume input from this observable.
   */
  stdin?: Observable<string>;

  /**
   * If true, echoes process output (stdout and stderr) to the local process's
   * console as it is received.
   */
  echoOutput?: boolean;

  /**
   * If true, outputs are returned separately as stdout and stderr (in Observable or Promise form).
   * If false or omitted, the primary output is the merged process output (only stdout).
   */
  split?: boolean;

  /**
   * The encoding used to decode process output, e.g. 'utf8', 'buffer', etc.
   * Defaults to 'utf8'.
   */
  encoding?: BufferEncoding;

  /**
   * Timeout in milliseconds. If the process doesn't complete within this time,
   * it will be killed and the observable will error with a TimeoutError.
   */
  timeout?: number;

  /**
   * Number of retry attempts if the process fails (non-zero exit code).
   * Defaults to 0 (no retries).
   */
  retries?: number;

  /**
   * Delay in milliseconds between retry attempts. Defaults to 1000ms.
   */
  retryDelay?: number;

  /**
   * Optional process info object. If provided, it will be updated with the process's metadata.
   */
  processInfo?: ProcessInfo;
};

export type OutputLine = {
  source: "stdout" | "stderr";
  text: string;
};

export type ProcessInfo = {
  pid: number;
};

/**
 * Utility type to extract the return type based on split option
 */
export type SpawnResult<T extends SpawnRxExtras> = T extends { split: true }
  ? Observable<OutputLine>
  : Observable<string>;

/**
 * Utility type to extract the promise return type based on split option
 */
export type SpawnPromiseResult<T extends SpawnRxExtras> = T extends {
  split: true;
}
  ? Promise<[string, string]>
  : Promise<string>;

/**
 * Spawns a process attached as a child of the current process.
 *
 * @param  {string} exe               The executable to run
 * @param  {string[]} params     The parameters to pass to the child
 * @param  {SpawnOptions & SpawnRxExtras} opts              Options to pass to spawn.
 *
 * @return {Observable<OutputLine>}       Returns an Observable that when subscribed
 *                                    to, will create a child process. The
 *                                    process output will be streamed to this
 *                                    Observable, and if unsubscribed from, the
 *                                    process will be terminated early. If the
 *                                    process terminates with a non-zero value,
 *                                    the Observable will terminate with onError.
 */
export function spawn(
  exe: string,
  params: string[],
  opts: SpawnOptionsWithExtras & { split: true }
): Observable<OutputLine>;

/**
 * Spawns a process attached as a child of the current process.
 *
 * @param  {string} exe               The executable to run
 * @param  {string[]} params     The parameters to pass to the child
 * @param  {SpawnOptions & SpawnRxExtras} opts              Options to pass to spawn.
 *
 * @return {Observable<string>}       Returns an Observable that when subscribed
 *                                    to, will create a child process. The
 *                                    process output will be streamed to this
 *                                    Observable, and if unsubscribed from, the
 *                                    process will be terminated early. If the
 *                                    process terminates with a non-zero value,
 *                                    the Observable will terminate with onError.
 */
export function spawn(
  exe: string,
  params: string[],
  opts?: SpawnOptionsWithExtras & { split: false | undefined }
): Observable<string>;

/**
 * Spawns a process attached as a child of the current process.
 *
 * @param  {string} exe               The executable to run
 * @param  {string[]} params     The parameters to pass to the child
 * @param  {SpawnOptions & SpawnRxExtras} opts              Options to pass to spawn.
 *
 * @return {Observable<string>}       Returns an Observable that when subscribed
 *                                    to, will create a child process. The
 *                                    process output will be streamed to this
 *                                    Observable, and if unsubscribed from, the
 *                                    process will be terminated early. If the
 *                                    process terminates with a non-zero value,
 *                                    the Observable will terminate with onError.
 */
export function spawn(
  exe: string,
  params: string[],
  opts?: SpawnOptionsWithExtras
): Observable<string> | Observable<OutputLine> {
  opts = opts ?? {};
  const spawnObs: Observable<OutputLine> = new Observable(
    (subj: Observer<OutputLine>) => {
      // eslint-disable-next-line @typescript-eslint/no-unused-vars
      const { encoding, timeout, ...spawnOpts } = opts;
      const { cmd, args } = findActualExecutable(exe, params);

      const stdinObs = spawnOpts.stdin;
      if (stdinObs) {
        delete spawnOpts.stdin;
        spawnOpts.stdio ??= ["pipe", "pipe", "pipe"];
      }

      spawnOpts.stdio ??= ["ignore", "pipe", "pipe"];
      const proc = spawnOg(cmd, args, spawnOpts);

      // Update processInfo if provided, allowing callers to access the PID
      if (opts.processInfo && proc.pid !== undefined) {
        opts.processInfo.pid = proc.pid;
      }

      // Set up timeout if specified
      let timeoutHandle: NodeJS.Timeout | null = null;
      if (timeout && timeout > 0) {
        timeoutHandle = setTimeout(() => {
          if (!proc.killed) {
            proc.kill();
          }
          const error = new SpawnError(
            `Process timed out after ${timeout}ms`,
            -1,
            cmd,
            args
          );
          subj.error(error);
        }, timeout);
      }

      const bufHandler =
        (source: "stdout" | "stderr") => (b: string | Buffer) => {
          if (b.length < 1) {
            return;
          }

          if (opts.echoOutput) {
            (source === "stdout" ? process.stdout : process.stderr).write(b);
          }

          let chunk = "<< String sent back was too long >>";
          try {
            if (typeof b === "string") {
              chunk = b.toString();
            } else {
              chunk = b.toString(encoding || "utf8");
            }
          } catch {
            chunk = `<< Lost chunk of process output for ${exe} - length was ${b.length}>>`;
          }

          subj.next({ source: source, text: chunk });
        };

      const ret = new Subscription();

      if (stdinObs) {
        if (proc.stdin) {
          const stdin = proc.stdin;
          ret.add(
            stdinObs.subscribe({
              next: x => stdin.write(x),
              error: subj.error.bind(subj),
              complete: () => stdin.end(),
            })
          );
        } else {
          subj.error(
            new Error(
              `opts.stdio conflicts with provided spawn opts.stdin observable, 'pipe' is required`
            )
          );
        }
      }

      let stderrCompleted: Subject<boolean> | Observable<boolean> | null = null;
      let stdoutCompleted: Subject<boolean> | Observable<boolean> | null = null;
      let noClose = false;

      if (proc.stdout) {
        stdoutCompleted = new AsyncSubject<boolean>();
        proc.stdout.on("data", bufHandler("stdout"));
        proc.stdout.on("close", () => {
          (stdoutCompleted as Subject<boolean>).next(true);
          (stdoutCompleted as Subject<boolean>).complete();
        });
      } else {
        stdoutCompleted = of(true);
      }

      if (proc.stderr) {
        stderrCompleted = new AsyncSubject<boolean>();
        proc.stderr.on("data", bufHandler("stderr"));
        proc.stderr.on("close", () => {
          (stderrCompleted as Subject<boolean>).next(true);
          (stderrCompleted as Subject<boolean>).complete();
        });
      } else {
        stderrCompleted = of(true);
      }

      proc.on("error", (e: Error) => {
        noClose = true;
        if (timeoutHandle) {
          clearTimeout(timeoutHandle);
        }
        subj.error(e);
      });

      proc.on("close", (code: number) => {
        noClose = true;
        if (timeoutHandle) {
          clearTimeout(timeoutHandle);
        }
        const pipesClosed = merge(stdoutCompleted, stderrCompleted).pipe(
          reduce((_acc: boolean) => true, true)
        );

        if (code === 0) {
          pipesClosed.subscribe(() => subj.complete());
        } else {
          pipesClosed.subscribe(() => {
            const error = new SpawnError(
              `Process failed with exit code: ${code}`,
              code,
              cmd,
              args
            );
            subj.error(error);
          });
        }
      });

      ret.add(
        new Subscription(() => {
          if (noClose) {
            return;
          }

          if (timeoutHandle) {
            clearTimeout(timeoutHandle);
          }

          proc.kill();
        })
      );

      return ret;
    }
  );

  let resultObs: Observable<OutputLine> = spawnObs;

  // Apply retry logic if specified
  if (opts.retries && opts.retries > 0) {
    const retryCount = opts.retries;
    const delay = opts.retryDelay ?? 1000;
    resultObs = resultObs.pipe(
      rxRetry({
        count: retryCount,
        delay: (error: unknown, _retryIndex: number) => {
          // Only retry on SpawnError with non-zero exit codes
          if (error instanceof SpawnError && error.exitCode !== 0) {
            return timer(delay);
          }
          // Don't retry on other errors
          throw error;
        },
      })
    );
  }

  return opts.split
    ? resultObs
    : resultObs.pipe(map((x: OutputLine) => x?.text));
}

export function wrapObservableInPromise(
  obs: Observable<string>
): Promise<string> {
  return new Promise<string>((res, rej) => {
    let out = "";

    obs.subscribe({
      next: (x: string) => {
        out += x;
      },
      error: (e: unknown) => {
        if (e instanceof SpawnError) {
          const err = new SpawnError(
            `${out}\n${e.message}`,
            e.exitCode,
            e.command,
            e.args,
            out,
            e.stderr
          );
          rej(err);
        } else {
          const err = new Error(
            `${out}\n${e instanceof Error ? e.message : String(e)}`
          );
          rej(err);
        }
      },
      complete: () => res(out),
    });
  });
}

export function wrapObservableInSplitPromise(
  obs: Observable<OutputLine>
): Promise<[string, string]> {
  return new Promise<[string, string]>((res, rej) => {
    let out = "";
    let err = "";

    obs.subscribe({
      next: (x: OutputLine) => {
        if (x.source === "stdout") {
          out += x.text;
        } else {
          err += x.text;
        }
      },
      error: (e: unknown) => {
        if (e instanceof SpawnError) {
          const error = new SpawnError(
            `${out}\n${e.message}`,
            e.exitCode,
            e.command,
            e.args,
            out,
            err
          );
          rej(error);
        } else {
          const error = new Error(
            `${out}\n${e instanceof Error ? e.message : String(e)}`
          );
          rej(error);
        }
      },
      complete: () => res([out, err]),
    });
  });
}

/**
 * Spawns a process as a child process.
 *
 * @param  {string} exe               The executable to run
 * @param  {string[]} params     The parameters to pass to the child
 * @param  {SpawnOptions & SpawnRxExtras} opts              Options to pass to spawn.
 *
 * @return {Promise<[string, string]>}       Returns an Promise that represents a child
 *                                 process. The value returned is the process
 *                                 output. If the process terminates with a
 *                                 non-zero value, the Promise will resolve with
 *                                 an Error.
 */
export function spawnPromise(
  exe: string,
  params: string[],
  opts: SpawnOptionsWithExtras & { split: true }
): Promise<[string, string]>;

/**
 * Spawns a process as a child process.
 *
 * @param  {string} exe               The executable to run
 * @param  {string[]} params     The parameters to pass to the child
 * @param  {SpawnOptions & SpawnRxExtras} opts              Options to pass to spawn.
 *
 * @return {Promise<string>}       Returns an Promise that represents a child
 *                                 process. The value returned is the process
 *                                 output. If the process terminates with a
 *                                 non-zero value, the Promise will resolve with
 *                                 an Error.
 */
export function spawnPromise(
  exe: string,
  params: string[],
  opts?: SpawnOptionsWithExtras
): Promise<string>;

/**
 * Spawns a process as a child process.
 *
 * @param  {string} exe               The executable to run
 * @param  {string[]} params     The parameters to pass to the child
 * @param  {Object} opts              Options to pass to spawn.
 *
 * @return {Promise<string>}       Returns an Promise that represents a child
 *                                 process. The value returned is the process
 *                                 output. If the process terminates with a
 *                                 non-zero value, the Promise will resolve with
 *                                 an Error.
 */
export function spawnPromise(
  exe: string,
  params: string[],
  opts?: SpawnOptionsWithExtras
): Promise<string> | Promise<[string, string]> {
  if (opts?.split) {
    return wrapObservableInSplitPromise(
      spawn(exe, params, { ...(opts ?? {}), split: true })
    );
  }
  return wrapObservableInPromise(
    spawn(exe, params, { ...(opts ?? {}), split: false })
  );
}
