import type { Dirent } from "node:fs";
import {
  mkdir,
  mkdtemp,
  readdir,
  readFile,
  rename,
  rm,
  stat,
  writeFile,
} from "node:fs/promises";
import { homedir } from "node:os";
import { dirname, join, posix } from "node:path";
import { type Context, createLogger, createSpan } from "@anysphere/context";
import { isEnvironmentEligible } from "@anysphere/cursor-plugins";
import { grayMatter, grayMatterStringify } from "@anysphere/utils/gray-matter";
import {
  readManifest,
  removeSkill,
  touchSkill,
  writeManifest,
} from "./skill-sync-manifest.js";

const logger = createLogger("builtin-skills-sync");

/** Directory name for built-in skills under ~/.cursor/ */
const BUILTIN_SKILLS_DIR_NAME = "skills-cursor";

/** Throttled via `lastInventoryAt` in the sync manifest, shared across processes. */
const INVENTORY_EMIT_INTERVAL_MS = 24 * 60 * 60 * 1000;

export interface CursorManagedSkill {
  id: string;
  description: string;
  content: string;
  disableModelInvocation?: boolean;
  environments?: string[];
  disabledEnvironments?: string[];
  resources?: Readonly<Record<string, string>>;
  /**
   * Whether the skill is enabled for the current user.
   * When explicitly false, the client should remove any previously synced copy.
   * When undefined (old server), the skill is treated as enabled for backward compat.
   */
  enabled?: boolean;
}

/**
 * Grace period before removing skills that have stopped appearing in the
 * server response. Protects users against transient server issues.
 */
export const SKILL_SYNC_GRACE_MS: number = 3 * 24 * 60 * 60 * 1000; // 3 days

export interface SyncBuiltinSkillsOptions {
  /**
   * Managed skills fetched from the server.
   * Enabled skills are written to disk. Skills with `enabled: false` are
   * removed immediately. Skills absent from the response are kept on disk
   * until the grace window expires (protection against transient server issues).
   */
  managedSkills?: CursorManagedSkill[];
}

interface SerializedSkill {
  id: string;
  fileContent: string;
  resources: Readonly<Record<string, string>>;
}

type SkillFrontmatter = Pick<
  CursorManagedSkill,
  | "id"
  | "description"
  | "disableModelInvocation"
  | "environments"
  | "disabledEnvironments"
>;

/**
 * Get the path to the built-in skills directory.
 * @returns The absolute path to ~/.cursor/skills-cursor/
 */
export function getBuiltinSkillsDir(): string {
  return join(homedir(), ".cursor", BUILTIN_SKILLS_DIR_NAME);
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/**
 * Managed skill ids are used as single path segments under skills-cursor.
 * Reject traversal or separator characters so server-provided ids cannot escape the directory.
 */
function isSafeManagedSkillId(id: string): boolean {
  if (!id || id !== id.trim()) {
    return false;
  }
  if (id.includes("..") || id.includes("/") || id.includes("\\")) {
    return false;
  }
  return true;
}

function validateManagedSkillResources(skill: CursorManagedSkill): void {
  for (const resourcePath of Object.keys(skill.resources ?? {})) {
    if (
      resourcePath.length === 0 ||
      resourcePath.includes("\\") ||
      resourcePath.includes("\0") ||
      posix.isAbsolute(resourcePath) ||
      posix.normalize(resourcePath) !== resourcePath ||
      resourcePath.split("/").includes("..") ||
      posix.basename(resourcePath) === "SKILL.md" ||
      !resourcePath.endsWith(".md")
    ) {
      throw new Error(
        `Unsafe managed skill resource path: ${JSON.stringify(resourcePath)}`
      );
    }
  }
}

function buildSkillFrontmatter(
  skill: SkillFrontmatter,
  extraData?: Record<string, unknown>
): Record<string, unknown> {
  const frontmatter: Record<string, unknown> = {
    ...(extraData ?? {}),
    name: skill.id,
    description: skill.description,
  };
  delete frontmatter.disabledEnvironments;

  if (skill.disableModelInvocation) {
    frontmatter["disable-model-invocation"] = true;
  } else {
    delete frontmatter["disable-model-invocation"];
  }

  if (skill.environments && skill.environments.length > 0) {
    frontmatter.environments = skill.environments;
  } else {
    delete frontmatter.environments;
  }

  if (skill.disabledEnvironments && skill.disabledEnvironments.length > 0) {
    frontmatter["disabled-environments"] = skill.disabledEnvironments;
  } else {
    delete frontmatter["disabled-environments"];
  }

  const existingMetadata = isRecord(frontmatter.metadata)
    ? frontmatter.metadata
    : {};
  const metadata: Record<string, unknown> = { ...existingMetadata };
  delete metadata.environments;
  delete metadata.disabledEnvironments;
  delete metadata["disabled-environments"];

  if (Object.keys(metadata).length > 0) {
    frontmatter.metadata = metadata;
  } else {
    delete frontmatter.metadata;
  }

  return frontmatter;
}

/**
 * Generate normalized SKILL.md content for a server-managed skill.
 * We merge the server-provided content with the proto fields so environment
 * metadata is preserved even when it is not embedded in the markdown body.
 */
function generateManagedSkillFileContent(skill: CursorManagedSkill): string {
  const parsed = grayMatter(skill.content);
  const existingFrontmatter = isRecord(parsed.data) ? parsed.data : {};
  return grayMatterStringify(
    `${parsed.content.trim()}\n`,
    buildSkillFrontmatter(skill, existingFrontmatter)
  );
}

/**
 * Sync a single Cursor-managed skill to disk.
 * Compares file content directly to avoid unnecessary writes.
 * @returns true if the file was written, false if it was already up-to-date
 */
async function syncSkill(
  ctx: Context,
  skillDir: string,
  skill: SerializedSkill
): Promise<boolean> {
  const skillPath = join(skillDir, skill.id);
  const skillFilePath = join(skillPath, "SKILL.md");
  const newContent = skill.fileContent;
  const resourcePaths = Object.keys(skill.resources);
  const existingResourcePaths = await listMarkdownResources(skillPath);

  if (resourcePaths.length > 0 || existingResourcePaths.length > 0) {
    const expectedFiles = new Map<string, string>([
      ["SKILL.md", newContent],
      ...Object.entries(skill.resources),
    ]);
    const existingFiles = new Set(["SKILL.md", ...existingResourcePaths]);
    if (
      existingFiles.size === expectedFiles.size &&
      [...expectedFiles.keys()].every(path => existingFiles.has(path))
    ) {
      let unchanged = true;
      for (const [path, content] of expectedFiles) {
        try {
          const existingContent = await readFile(
            join(skillPath, ...path.split("/")),
            "utf-8"
          );
          if (existingContent !== content) {
            unchanged = false;
            break;
          }
        } catch {
          unchanged = false;
          break;
        }
      }
      if (unchanged) {
        return false;
      }
    }

    await replaceSkillDirectory(skillDir, skill);
    return true;
  }

  try {
    const existingContent = await readFile(skillFilePath, "utf-8");
    if (existingContent === newContent) {
      return false;
    }
  } catch (error) {
    if (
      !(error instanceof Error) ||
      (error as NodeJS.ErrnoException).code !== "ENOENT"
    ) {
      logger.warn(ctx, "Unexpected error reading skill file", {
        skillId: skill.id,
        error: String(error),
      });
    }
  }

  await mkdir(skillPath, { recursive: true });
  await writeFile(skillFilePath, newContent, "utf-8");
  return true;
}

async function listMarkdownResources(
  skillPath: string,
  relativeDir = ""
): Promise<string[]> {
  const absoluteDir = relativeDir
    ? join(skillPath, ...relativeDir.split("/"))
    : skillPath;
  let entries: Dirent[];
  try {
    entries = await readdir(absoluteDir, { withFileTypes: true });
  } catch (error) {
    if (
      error instanceof Error &&
      (error as NodeJS.ErrnoException).code === "ENOENT"
    ) {
      return [];
    }
    throw error;
  }

  const resources: string[] = [];
  for (const entry of entries) {
    const relativePath = relativeDir
      ? `${relativeDir}/${entry.name}`
      : entry.name;
    if (entry.isDirectory()) {
      resources.push(...(await listMarkdownResources(skillPath, relativePath)));
    } else if (entry.isFile() && entry.name.endsWith(".md")) {
      if (relativePath !== "SKILL.md") {
        resources.push(relativePath);
      }
    }
  }
  return resources;
}

async function replaceSkillDirectory(
  skillDir: string,
  skill: SerializedSkill
): Promise<void> {
  const skillPath = join(skillDir, skill.id);
  const stagingPath = await mkdtemp(join(skillDir, `.${skill.id}-staging-`));
  const backupPath = `${stagingPath}-backup`;
  let movedExisting = false;

  try {
    await writeFile(join(stagingPath, "SKILL.md"), skill.fileContent, "utf-8");
    for (const [resourcePath, content] of Object.entries(skill.resources)) {
      const destination = join(stagingPath, ...resourcePath.split("/"));
      await mkdir(dirname(destination), { recursive: true });
      await writeFile(destination, content, "utf-8");
    }

    try {
      await rename(skillPath, backupPath);
      movedExisting = true;
    } catch (error) {
      if (
        !(error instanceof Error) ||
        (error as NodeJS.ErrnoException).code !== "ENOENT"
      ) {
        throw error;
      }
    }

    try {
      await rename(stagingPath, skillPath);
    } catch (error) {
      if (movedExisting) {
        await rename(backupPath, skillPath);
        movedExisting = false;
      }
      throw error;
    }

    if (movedExisting) {
      await rm(backupPath, { recursive: true, force: true });
      movedExisting = false;
    }
  } finally {
    await rm(stagingPath, { recursive: true, force: true });
    // If rollback failed, backupPath is the last valid copy. Leave it in place
    // for manual recovery instead of deleting it during cleanup.
  }
}

async function listSkillDirs(
  ctx: Context,
  skillDir: string
): Promise<string[]> {
  try {
    const entries = await readdir(skillDir, { withFileTypes: true });
    return entries
      .filter(e => e.isDirectory() && !e.name.startsWith("."))
      .map(e => e.name);
  } catch (error) {
    if (
      !(error instanceof Error) ||
      (error as NodeJS.ErrnoException).code !== "ENOENT"
    ) {
      logger.warn(ctx, "Failed to list skills directory, skipping cleanup", {
        skillDir,
        error: String(error),
      });
    }
    return [];
  }
}

/**
 * Sync managed skills to disk in a single pass over the union of server
 * response ids and on-disk skill directories.
 *
 * For each skill we see:
 * - Server lists it as enabled (or undefined) and local-eligible: write
 *   SKILL.md, refresh lastSyncedAt.
 * - Server lists it as `enabled: false` or local-ineligible: remove the
 *   directory immediately.
 * - Server omits it: remove only if it has been absent longer than
 *   {@link SKILL_SYNC_GRACE_MS}. Directories with no manifest entry are
 *   bootstrapped (treated as "just seen") so upgrading clients don't lose
 *   pre-existing skills on first sync.
 */
export async function syncBuiltinSkills(
  ctx: Context,
  options: SyncBuiltinSkillsOptions = {}
): Promise<{
  synced: number;
  upToDate: number;
  removed: string[];
}> {
  using span = createSpan(ctx.withName("syncBuiltinSkills"));
  const spanCtx = span.ctx;
  const nowMs = Date.now();
  const skillDir = getBuiltinSkillsDir();

  await mkdir(skillDir, { recursive: true });

  const [manifest, onDiskIds] = await Promise.all([
    readManifest(skillDir, spanCtx),
    listSkillDirs(spanCtx, skillDir),
  ]);

  const lastInventoryAt = manifest.lastInventoryAt;
  if (
    lastInventoryAt === undefined ||
    nowMs - lastInventoryAt >= INVENTORY_EMIT_INTERVAL_MS
  ) {
    await emitStartupInventory(spanCtx, skillDir, onDiskIds, manifest);
    manifest.lastInventoryAt = nowMs;
  }

  const serverById = new Map<string, CursorManagedSkill>();
  for (const skill of options.managedSkills ?? []) {
    if (!isSafeManagedSkillId(skill.id)) {
      logger.warn(spanCtx, "Skipping managed skill with unsafe id", {
        skillId: skill.id,
      });
      continue;
    }
    serverById.set(skill.id, skill);
  }

  const allIds = new Set<string>([...serverById.keys(), ...onDiskIds]);

  let synced = 0;
  let upToDate = 0;
  const removed: string[] = [];

  for (const id of allIds) {
    try {
      const server = serverById.get(id);
      const entry = manifest.skills[id];
      const ageMs = entry ? nowMs - entry.lastSyncedAt : 0;
      const isStale = entry !== undefined && ageMs > SKILL_SYNC_GRACE_MS;

      const isEligibleForLocalSync =
        server !== undefined && isEnvironmentEligible(server, "local");
      const isEnvironmentIneligible =
        server !== undefined && !isEligibleForLocalSync;
      const hadLocalCopy = entry !== undefined || onDiskIds.includes(id);

      if (server && server.enabled !== false && isEligibleForLocalSync) {
        validateManagedSkillResources(server);
        const wasWritten = await syncSkill(spanCtx, skillDir, {
          id,
          fileContent: generateManagedSkillFileContent(server),
          resources: server.resources ?? {},
        });
        wasWritten ? synced++ : upToDate++;
        touchSkill(manifest, id, nowMs);
      } else if (
        server?.enabled === false ||
        isEnvironmentIneligible ||
        isStale
      ) {
        const reason:
          | "enabled_false"
          | "environment_ineligible"
          | "grace_expired" =
          server?.enabled === false
            ? "enabled_false"
            : isEnvironmentIneligible
              ? "environment_ineligible"
              : "grace_expired";
        await rm(join(skillDir, id), { recursive: true, force: true });
        removeSkill(manifest, id);
        if (hadLocalCopy) {
          removed.push(id);
          logger.info(spanCtx, "managed_skills.removed", {
            skill_id: id,
            reason,
            server_enabled: server?.enabled ?? null,
            had_manifest_entry: entry !== undefined,
            last_synced_ms_ago: entry ? nowMs - entry.lastSyncedAt : null,
          });
        }
      } else if (!entry) {
        touchSkill(manifest, id, nowMs);
      }
    } catch (error) {
      logger.warn(spanCtx, "Failed to apply skill, will retry next sync", {
        skillId: id,
        error: String(error),
      });
    }
  }

  try {
    await writeManifest(skillDir, manifest);
  } catch (error) {
    logger.warn(spanCtx, "Failed to persist sync manifest", {
      skillDir,
      error: String(error),
    });
  }

  return { synced, upToDate, removed };
}

async function pathExists(p: string): Promise<boolean> {
  try {
    await stat(p);
    return true;
  } catch (err) {
    const code = (err as NodeJS.ErrnoException).code;
    if (code === "ENOENT" || code === "ENOTDIR") {
      return false;
    }
    throw err;
  }
}

async function emitStartupInventory(
  ctx: Context,
  skillDir: string,
  skillDirs: readonly string[],
  manifest: Awaited<ReturnType<typeof readManifest>>
): Promise<void> {
  try {
    const skillsOnDisk = await Promise.all(
      skillDirs.map(async id => {
        const idDir = join(skillDir, id);
        const [hasSkillMd, hasSdkDir] = await Promise.all([
          pathExists(join(idDir, "SKILL.md")),
          id === "canvas"
            ? pathExists(join(idDir, "sdk"))
            : Promise.resolve(false),
        ]);
        return {
          skill_id: id,
          has_skill_md: hasSkillMd,
          has_sdk_dir: hasSdkDir,
          last_synced_at: manifest.skills[id]?.lastSyncedAt ?? null,
        };
      })
    );

    logger.info(ctx, "managed_skills.startup_inventory", {
      skills_on_disk: skillsOnDisk,
      manifest_present: Object.keys(manifest.skills).length > 0,
    });
  } catch (error) {
    logger.warn(ctx, "Failed to emit managed skills startup inventory", {
      error: String(error),
    });
  }
}
