import { SimpleControlledExecHandler } from "./controlled.js";
import { ExecutorResource } from "./remote.js";
import { createResource } from "./resource-provider.js";
import { createClientDeserializer, createClientSerializer, createServerDeserializer, createServerSerializer, } from "./serialization.js";
/**
 * Default read executor path.
 */
export const readExecutorResource = createResource(execManager => new ExecutorResource(execManager, createServerSerializer("readArgs"), createClientDeserializer("readResult")), (implementation, controlledExecManager) => {
    controlledExecManager.register(new SimpleControlledExecHandler(implementation, createServerDeserializer("readArgs"), createClientSerializer("readResult")));
});
/**
 * Optional redacted read transport. When secret redaction is enabled,
 * this resource can be wrapped to return redacted file contents.
 */
export const redactedReadExecutorResource = createResource(execManager => new ExecutorResource(execManager, createServerSerializer("redactedReadArgs"), createClientDeserializer("redactedReadResult")), (implementation, controlledExecManager) => {
    controlledExecManager.register(new SimpleControlledExecHandler(implementation, createServerDeserializer("redactedReadArgs"), createClientSerializer("redactedReadResult")));
});
