import { isAbsolute, relative, resolve } from "node:path";
/**
 * Validates that subPath does not escape baseDir (prevents path traversal).
 * Uses the runtime OS path implementation (Node's default path module).
 *
 * @throws Error if subPath resolves outside baseDir
 */
export function validateAndResolveSubpath(baseDir, subPath) {
    const resolvedBase = resolve(baseDir);
    const resolved = resolve(baseDir, subPath);
    const rel = relative(resolvedBase, resolved);
    if (rel.startsWith("..") || isAbsolute(rel)) {
        throw new Error(`Invalid subPath: path traversal not allowed (${JSON.stringify(subPath)})`);
    }
    return resolved;
}
