import { calculateBackoffDelay } from '@anysphere/constants';
import type { MCPServerInfo, MCPServerStatus } from '../fsm/types.js';
import { isTimeoutErrorMessage } from './error-message-utils.js';

function isEmptySseStreamOpenFailure(message: string): boolean {
	// Match bare SDK throws and reconnect/StreamableHTTP wrappers — the SSE
	// failure phrase must be at the end with no status text after it.
	return /Failed to open SSE stream:?\s*$/i.test(message.trim());
}

// ── Reconnect utilities (pure functions) ────────────────────────────────

/** Base delay for exponential backoff (1 second) */
export const BASE_RECONNECT_DELAY_MS = 1000;

/** Maximum delay cap (30 seconds) */
export const MAX_RECONNECT_DELAY_MS = 30_000;

/** Maximum number of fast reconnect attempts before switching to slow periodic retry */
export const MAX_RECONNECT_ATTEMPTS = 15;

/** Base delay for slow periodic retries after fast retries are exhausted (30 seconds) */
export const PERIODIC_RETRY_BASE_DELAY_MS = 30_000;

/** Default maximum delay cap for periodic retries (5 minutes), configurable via Statsig */
export const DEFAULT_PERIODIC_RETRY_MAX_DELAY_MS = 300_000;

/** Error codes that indicate retryable network errors */
export const RETRYABLE_ERROR_CODES: Set<string> = new Set([
	'EAI_AGAIN',
	'ECONNABORTED',
	'ECONNREFUSED',
	'ECONNRESET',
	'EHOSTUNREACH',
	'ENETDOWN',
	'ENETUNREACH',
	'ENOTFOUND',
	'EPIPE',
	'ETIMEDOUT',
	'EADDRNOTAVAIL',
	'UND_ERR_CONNECT_TIMEOUT',
]);

/**
 * Chromium `net::ERR_*` error strings emitted by `electron.net.fetch` (used by
 * the MCP utility process — see `mcpProcessHostEnvironment.ts`). Cert/SSL,
 * policy blocks, and bad-URL/resource errors are handled by
 * {@link CHROMIUM_NON_RETRYABLE_NET_ERROR_PATTERN} below and stay non-retryable.
 */
const CHROMIUM_RETRYABLE_NET_ERROR_PATTERN =
	/net::ERR_(?:NETWORK_CHANGED|NETWORK_IO_SUSPENDED|INTERNET_DISCONNECTED|CONNECTION_(?:RESET|CLOSED|ABORTED|FAILED|REFUSED|TIMED_OUT)|TIMED_OUT|ABORTED|NAME_NOT_RESOLVED|NAME_RESOLUTION_FAILED|DNS_TIMED_OUT|SOCKET_NOT_CONNECTED|ADDRESS_UNREACHABLE|TUNNEL_CONNECTION_FAILED|EMPTY_RESPONSE|HTTP2_(?:PROTOCOL_ERROR|PING_FAILED)|QUIC_PROTOCOL_ERROR)\b/;

/**
 * Chromium errors that must stay non-retryable regardless of the patterns
 * above: cert/SSL, content/policy blocks, bad URLs, denied access, local
 * resource exhaustion. Checked first in {@link isRetryableNetworkError}.
 */
const CHROMIUM_NON_RETRYABLE_NET_ERROR_PATTERN =
	/net::ERR_(?:CERT_[A-Z_]+|SSL_[A-Z_]+|BAD_SSL_[A-Z_]+|BLOCKED_BY_[A-Z_]+|DISALLOWED_URL_SCHEME|UNKNOWN_URL_SCHEME|INVALID_[A-Z_]+|ACCESS_DENIED|NETWORK_ACCESS_DENIED|PROXY_AUTH_[A-Z_]+|INSUFFICIENT_RESOURCES|OUT_OF_MEMORY)\b/;

/** Patterns that indicate retryable network errors in error messages */
export const RETRYABLE_ERROR_PATTERNS: RegExp[] = [
	/fetch failed/i,
	/network error/i,
	/socket hang up/i,
	/client network socket disconnected/i,
	/connection (?:timed out|timeout|closed|terminated)/i,
	/request timed out/i,
	CHROMIUM_RETRYABLE_NET_ERROR_PATTERN,
];

/**
 * A narrower subset of retryable transport failures that strongly suggests the
 * current live stream/socket became unusable and a fresh connection may help.
 *
 * This intentionally excludes broader retryable conditions like DNS failures,
 * connection refused, generic fetch failures, and timeouts. Those are better
 * handled by the FSM's normal backoff/retry policy rather than a synchronous
 * inline reconnect from the operation path.
 */
export const INLINE_RECONNECT_TRANSPORT_BREAKAGE_CODES: Set<string> = new Set([
	'ECONNRESET',
	'EPIPE',
]);

/**
 * Message patterns that indicate the underlying transport likely broke after a
 * connection had already been established. The Chromium subset is narrower
 * than the retryable list: excludes DNS / refused / timeouts (which the FSM
 * backoff path handles better than a synchronous inline reopen).
 */
export const INLINE_RECONNECT_TRANSPORT_BREAKAGE_PATTERNS: RegExp[] = [
	/socket hang up/i,
	/client network socket disconnected/i,
	/connection (?:closed|terminated)/i,
	/ERR_STREAM_PREMATURE_CLOSE/i,
	/premature close/i,
	/net::ERR_(?:NETWORK_CHANGED|NETWORK_IO_SUSPENDED|CONNECTION_(?:RESET|CLOSED|ABORTED)|HTTP2_(?:PROTOCOL_ERROR|PING_FAILED)|QUIC_PROTOCOL_ERROR|EMPTY_RESPONSE)\b/,
];

/**
 * HTTP status codes that indicate retryable server-side failures.
 * These are transient errors where the server (or gateway) is temporarily
 * unable to handle the request but may recover on retry.
 */
export const RETRYABLE_HTTP_STATUS_CODES: Set<number> = new Set([
	429, // Too Many Requests — retryable during connection establishment;
	// suppressed by onerror/eventClassification for established transports
	502, // Bad Gateway
	503, // Service Unavailable — same treatment as 429
	504, // Gateway Timeout
]);

/**
 * Calculate exponential backoff delay with full jitter.
 * Formula: random(0, min(cap, base * 2^attempt))
 *
 * @param attempt - The current attempt number (0-indexed)
 * @param randomFn - Random function for testing (defaults to Math.random)
 * @returns Delay in milliseconds
 */
export function getReconnectDelayMs(attempt: number, randomFn: () => number = Math.random): number {
	return calculateBackoffDelay(
		attempt,
		BASE_RECONNECT_DELAY_MS,
		MAX_RECONNECT_DELAY_MS,
		randomFn
	);
}

/**
 * Extract HTTP status code from an error.
 * Checks both StreamableHTTPError.code and known SDK message formats:
 * - "(HTTP NNN)" from streamable HTTP transport failures
 * - "Non-200 status code (NNN)" from SSE transport failures
 * due to SDK inconsistency (some paths throw plain Error for non-OK responses).
 */
function extractHttpStatusCodeFromObject(error: object): number | undefined {
	const httpCode = (error as { code?: unknown }).code;
	const message = error instanceof Error
		? error.message
		: typeof (error as { message?: unknown }).message === 'string'
			? (error as { message: string }).message
			: '';
	const match = message.match(/\(HTTP (\d+)\)|Non-200 status code \((\d+)\)|\bHTTP\s+(\d{3})\b/i);
	const matchedStatus = match?.[1] ?? match?.[2] ?? match?.[3];
	const messageHttpCode = matchedStatus !== undefined ? parseInt(matchedStatus, 10) : undefined;

	if (typeof httpCode === 'number' && httpCode >= 100) {
		// When .code and message disagree, preserve previous behavior by allowing
		// retryable HTTP statuses from the message (e.g. "(HTTP 503)") to win.
		// This avoids masking rate-limit/overload signals behind a non-retryable .code.
		if (
			messageHttpCode !== undefined &&
			RETRYABLE_HTTP_STATUS_CODES.has(messageHttpCode) &&
			!RETRYABLE_HTTP_STATUS_CODES.has(httpCode)
		) {
			return messageHttpCode;
		}
		return httpCode;
	}
	if (typeof httpCode === 'string' && /^\d{3}$/.test(httpCode)) {
		const parsed = Number.parseInt(httpCode, 10);
		return parsed >= 100 && parsed <= 599 ? parsed : messageHttpCode;
	}
	return messageHttpCode;
}

/**
 * Extract HTTP status code from an error.
 * Checks both StreamableHTTPError.code and known SDK message formats:
 * - "(HTTP NNN)" from streamable HTTP transport failures
 * - "Non-200 status code (NNN)" from SSE transport failures
 * due to SDK inconsistency (some paths throw plain Error for non-OK responses).
 *
 * Also checks `error.cause` once for SDK reconnect wrappers that attach the
 * original transport error (e.g. StreamableHTTPError with `.code`).
 */
export function extractHttpStatusCode(error: unknown): number | undefined {
	if (!error || typeof error !== 'object') {
		return undefined;
	}
	const direct = extractHttpStatusCodeFromObject(error);
	if (direct !== undefined) {
		return direct;
	}
	const cause = (error as { cause?: unknown }).cause;
	if (cause && typeof cause === 'object') {
		return extractHttpStatusCodeFromObject(cause);
	}
	return undefined;
}

/**
 * Check if an error is a retryable network error.
 */
export function isRetryableNetworkError(error: Error): boolean {
	const message = error.message ?? '';
	const httpStatus = extractHttpStatusCode(error);
	if (isEmptySseStreamOpenFailure(message)) {
		// Only retry when we have an explicit transient HTTP status on error/cause.
		// Do not treat status-less empty SSE open failures as retryable network churn.
		return httpStatus !== undefined && RETRYABLE_HTTP_STATUS_CODES.has(httpStatus);
	}
	if (CHROMIUM_NON_RETRYABLE_NET_ERROR_PATTERN.test(message)) {
		return false;
	}

	const errorWithCode = error as NodeJS.ErrnoException;
	const code = errorWithCode.code ?? (error as { cause?: NodeJS.ErrnoException }).cause?.code;
	if (typeof code === 'string' && RETRYABLE_ERROR_CODES.has(code)) {
		return true;
	}

	if (httpStatus !== undefined && RETRYABLE_HTTP_STATUS_CODES.has(httpStatus)) {
		return true;
	}

	return RETRYABLE_ERROR_PATTERNS.some(pattern => pattern.test(message));
}

/** Max bytes of stderr retained for stdio connect-failure classification (bounded buffer). */
export const STDIO_CONNECT_STDERR_CAPTURE_MAX_BYTES = 8192;

/**
 * Errno codes from child_process spawn that indicate local misconfiguration.
 * These reject before a successful spawn (see MCP SDK StdioClientTransport.start).
 */
export const STDIO_HARD_LOCAL_SPAWN_CODES: Set<string> = new Set([
	'ENOENT',
	'EACCES',
	'ENOTDIR',
	'EPERM',
]);

const STDIO_LOCAL_MISCONFIG_STDERR_PATTERNS = [
	/cannot find module/i,
	/module not found/i,
	/syntaxerror/i,
	/command not found/i,
	/is not recognized as an internal or external command/i,
	/no such file or directory/i,
	/err_module_not_found/i,
];

function stderrLooksLikeLocalMisconfig(stderr: string): boolean {
	return STDIO_LOCAL_MISCONFIG_STDERR_PATTERNS.some(p => p.test(stderr));
}

function stderrLooksLikeTransientNetwork(stderr: string): boolean {
	for (const code of RETRYABLE_ERROR_CODES) {
		if (stderr.includes(code)) {
			return true;
		}
	}
	return RETRYABLE_ERROR_PATTERNS.some(pattern => pattern.test(stderr));
}

/**
 * Generic MCP SDK error when the stdio child exits before initialize completes.
 * Must not be classified via {@link isRetryableNetworkError}: that helper's
 * message patterns treat "Connection closed" as retryable.
 */
function isGenericMcpStdioConnectionClosedError(error: Error): boolean {
	return /MCP error -32000:\s*Connection closed/i.test(error.message ?? '');
}

function isKnownRemoteStdioWrapper(command: string, args: readonly string[]): boolean {
	const haystacks = [command, ...args].map(part => part.toLowerCase());
	return haystacks.some(part => part.includes('mcp-remote'));
}

/**
 * Whether a failed stdio MCP connect should be treated as retryable.
 *
 * - Hard local misconfig (spawn errno, obvious stderr): never retry.
 * - Strong network/transient signal on the thrown error or stderr: retry.
 * - Otherwise: use `ambiguousFallbackNonRetryable` (Statsig `stdioConnectFailuresAreNonRetryable`;
 *   when false, ambiguous failures default to retryable).
 */
export function classifyStdioConnectFailureRetryability(
	error: unknown,
	stderrSample: string,
	ambiguousFallbackNonRetryable: boolean,
	command: string,
	args: readonly string[],
): boolean {
	if (error instanceof Error) {
		const errorWithCode = error as NodeJS.ErrnoException;
		const code = errorWithCode.code ?? (error as { cause?: NodeJS.ErrnoException }).cause?.code;
		if (typeof code === 'string' && STDIO_HARD_LOCAL_SPAWN_CODES.has(code)) {
			return false;
		}
		if (
			isKnownRemoteStdioWrapper(command, args) &&
			isTimeoutErrorMessage(error.message ?? '')
		) {
			return true;
		}
		if (!isGenericMcpStdioConnectionClosedError(error) && isRetryableNetworkError(error)) {
			return true;
		}
	}

	const stderr = stderrSample;
	if (stderr.trim().length > 0) {
		if (stderrLooksLikeLocalMisconfig(stderr)) {
			return false;
		}
		if (stderrLooksLikeTransientNetwork(stderr)) {
			return true;
		}
	}

	if (
		error instanceof Error &&
		isGenericMcpStdioConnectionClosedError(error) &&
		stderr.trim().length === 0 &&
		!isKnownRemoteStdioWrapper(command, args)
	) {
		return false;
	}

	return !ambiguousFallbackNonRetryable;
}

/**
 * Check if an error is a transport-breakage failure where one last inline
 * reconnect can be reasonable after the FSM has already exhausted retries.
 */
export function isInlineReconnectEligibleNetworkError(error: Error): boolean {
	const errorWithCode = error as NodeJS.ErrnoException;
	const code = errorWithCode.code ?? (error as { cause?: NodeJS.ErrnoException }).cause?.code;
	if (typeof code === 'string' && INLINE_RECONNECT_TRANSPORT_BREAKAGE_CODES.has(code)) {
		return true;
	}

	const message = error.message ?? '';
	return INLINE_RECONNECT_TRANSPORT_BREAKAGE_PATTERNS.some(pattern => pattern.test(message));
}

// ── Reconnect manager (state machine) ───────────────────────────────────

type ReconnectLogger = {
	debug: (message: string) => void;
	info: (message: string) => void;
	warn: (message: string) => void;
};

const MAX_FAST_RECONNECT_WARN_ERROR_CHARS = 1024;

function truncateForReconnectLog(message: string, maxChars: number): string {
	if (message.length <= maxChars) {
		return message;
	}
	return `${message.slice(0, maxChars)}…`;
}

type ReconnectState = {
	attempt: number;
	periodicAttempt: number;
	/** Message from the most recent failed `reinitializeNetworkConnection` (fast-retry path). */
	lastFastReconnectError?: string;
	timer?: ReturnType<typeof setTimeout>;
	inFlight?: Promise<void>;
};

export type ReconnectManagerDeps = {
	getReconnectDelayMs: (attempt: number) => number;
	maxReconnectAttempts: number;
	getPeriodicRetryMaxDelayMs?: (identifier: string, serverInfo: MCPServerInfo) => number;
	hasServer: (identifier: string) => boolean;
	getStatus: (identifier: string) => MCPServerStatus | undefined;
	updateStatus: (identifier: string, status: MCPServerStatus) => void;
	getLogger: (identifier: string) => ReconnectLogger;
	reinitializeNetworkConnection: (identifier: string, serverInfo: MCPServerInfo) => Promise<void>;
	/** When reconnect fails while status is needsAuth, schedule another attempt (e.g. OAuth refresh was transient). */
	scheduleNeedsAuthReconnectRetry?: (identifier: string, serverInfo: MCPServerInfo, reinitError: unknown) => void;
};

export type ReconnectManager = {
	scheduleReconnect: (identifier: string, serverInfo: MCPServerInfo, reason: string) => void;
	clearReconnectState: (identifier: string) => void;
	withReinitializeLock: (identifier: string, operation: () => Promise<void>) => Promise<void>;
};

export function createReconnectManager(deps: ReconnectManagerDeps): ReconnectManager {
	const reconnectState = new Map<string, ReconnectState>();

	function getReconnectState(identifier: string): ReconnectState {
		const existing = reconnectState.get(identifier);
		if (existing) {
			return existing;
		}
		const initialState: ReconnectState = { attempt: 0, periodicAttempt: 0 };
		reconnectState.set(identifier, initialState);
		return initialState;
	}

	function clearReconnectState(identifier: string): void {
		const state = reconnectState.get(identifier);
		if (state?.timer) {
			clearTimeout(state.timer);
		}
		reconnectState.delete(identifier);
	}

	async function withReinitializeLock(
		identifier: string,
		operation: () => Promise<void>
	): Promise<void> {
		const state = getReconnectState(identifier);
		if (state.inFlight) {
			await state.inFlight;
			return;
		}

		const promise = operation().finally(() => {
			const current = reconnectState.get(identifier);
			if (current?.inFlight === promise) {
				current.inFlight = undefined;
				reconnectState.set(identifier, current);
			}
		});
		state.inFlight = promise;
		reconnectState.set(identifier, state);
		await promise;
	}

	async function executeReconnect(
		identifier: string,
		serverInfo: MCPServerInfo,
		state: ReconnectState
	): Promise<void> {
		try {
			await deps.reinitializeNetworkConnection(identifier, serverInfo);
			clearReconnectState(identifier);
		} catch (reinitError) {
			if (deps.getStatus(identifier)?.type === 'needsAuth') {
				deps.scheduleNeedsAuthReconnectRetry?.(identifier, serverInfo, reinitError);
				clearReconnectState(identifier);
				return;
			}
			const failureMessage = reinitError instanceof Error ? reinitError.message : String(reinitError);
			state.lastFastReconnectError = failureMessage;
			state.attempt += 1;
			reconnectState.set(identifier, state);
			deps.getLogger(identifier).debug(`Reconnect attempt ${state.attempt} failed: ${failureMessage}`);
			scheduleReconnect(identifier, serverInfo, 'reconnect retry');
		}
	}

	function getPeriodicRetryMaxDelayMs(identifier: string, serverInfo: MCPServerInfo): number {
		const raw = deps.getPeriodicRetryMaxDelayMs?.(identifier, serverInfo) ?? DEFAULT_PERIODIC_RETRY_MAX_DELAY_MS;
		// Clamp to [30s, 1h] to guard against misconfigured dynamic config values
		// (0, negative, or extremely large numbers that could cause rapid polling
		// or unreasonably long delays).
		return Math.max(PERIODIC_RETRY_BASE_DELAY_MS, Math.min(raw, 3_600_000));
	}

	function scheduleReconnect(identifier: string, serverInfo: MCPServerInfo, reason: string): void {
		if (serverInfo.type === 'stdio') {
			return;
		}

		if (!deps.hasServer(identifier)) {
			return;
		}

		const state = getReconnectState(identifier);
		if (state.inFlight) {
			deps.getLogger(identifier).debug(`Reconnect already in progress, skipping schedule (${reason})`);
			return;
		}

		if (state.timer) {
			deps.getLogger(identifier).debug(`Reconnect already scheduled, skipping schedule (${reason})`);
			return;
		}

		if (state.attempt >= deps.maxReconnectAttempts) {
			const lastErr = state.lastFastReconnectError?.trim();
			const lastErrSuffix =
				lastErr !== undefined && lastErr.length > 0
					? ` Last error: ${truncateForReconnectLog(lastErr, MAX_FAST_RECONNECT_WARN_ERROR_CHARS)}`
					: '';
			deps.getLogger(identifier).warn(
				`Fast reconnect attempts exhausted (${deps.maxReconnectAttempts}); switching to periodic retry.${lastErrSuffix}`,
			);
			// Switch to slow periodic retry with exponential backoff + jitter.
			// Uses the same calculateBackoffDelay pattern as fast retries but with
			// a higher base (30s) and configurable max cap (default 300s).
			const maxDelayMs = getPeriodicRetryMaxDelayMs(identifier, serverInfo);
			const delayMs = calculateBackoffDelay(
				state.periodicAttempt,
				PERIODIC_RETRY_BASE_DELAY_MS,
				maxDelayMs,
			);

			const periodicRetryErrorMessage = 'Connection failed after multiple retries. Retrying periodically.';
			const currentStatus = deps.getStatus(identifier);
			if (currentStatus?.type !== 'error' || currentStatus.error !== periodicRetryErrorMessage) {
				deps.updateStatus(identifier, { type: 'error', error: periodicRetryErrorMessage });
			}

			deps.getLogger(identifier).debug(
				`Periodic retry in ${Math.round(delayMs / 1000)}s (periodic attempt ${state.periodicAttempt + 1}, max delay ${maxDelayMs / 1000}s)`
			);

			state.timer = setTimeout(() => {
				state.timer = undefined;
				reconnectState.set(identifier, state);

				if (!deps.hasServer(identifier)) {
					deps.getLogger(identifier).debug(`Server removed, canceling periodic retry`);
					return;
				}

				state.periodicAttempt += 1;
				// Reset fast attempt counter so we get a fresh round of fast retries
				// if the periodic attempt partially succeeds or encounters a new
				// transient error.
				state.attempt = 0;
				executeReconnect(identifier, serverInfo, state);
			}, delayMs);
			reconnectState.set(identifier, state);
			return;
		}

		const currentStatus = deps.getStatus(identifier);
		if (currentStatus?.type !== 'needsAuth' && currentStatus?.type !== 'disconnected') {
			deps.updateStatus(identifier, { type: 'disconnected' });
		}

		const delay = deps.getReconnectDelayMs(state.attempt);
		deps.getLogger(identifier).debug(
			`Scheduling reconnect in ${Math.round(delay)}ms (attempt ${state.attempt + 1}/${deps.maxReconnectAttempts})`
		);

		state.timer = setTimeout(() => {
			state.timer = undefined;
			reconnectState.set(identifier, state);

			if (!deps.hasServer(identifier)) {
				deps.getLogger(identifier).debug(`Server removed, canceling reconnect`);
				return;
			}

			executeReconnect(identifier, serverInfo, state);
		}, delay);
		reconnectState.set(identifier, state);
	}

	return {
		scheduleReconnect,
		clearReconnectState,
		withReinitializeLock,
	};
}
