/**
 * Token storage for a single MCP server.
 *
 * This is intentionally "scoped" (no identifier parameter) so callers can
 * capture per-request context safely.
 */
export interface ScopedMcpTokenStorage {
  loadTokens(): Promise<OAuthTokens | undefined>;
  saveTokens(tokens: OAuthTokens): Promise<void>;
  prepareForRefresh?(): Promise<void>;
  releaseRefreshLeaseOnError?(underlyingError?: unknown): Promise<void>;
  invalidateCredentials?(
    scope: McpOAuthCredentialInvalidationScope
  ): Promise<void>;

  loadClientInformation(): Promise<OAuthClientInformationFull | undefined>;
  saveClientInformation(clientInfo: OAuthClientInformationFull): Promise<void>;
}

export type CommandBasedMcpServerConfig = Extract<
  McpServerConfig,
  { command: string }
>;

export type RemoteMcpServerConfig = Extract<McpServerConfig, { url: string }>;

export interface McpHttpExchangeLoggingOptions {
  readonly logger: McpHttpExchangeLogger;
  readonly metadata?: Record<string, unknown>;
}

export interface McpLoader {
  load(ctx: Context, cache?: boolean): Promise<McpManager>;
  loadClient(
    ctx: Context,
    identifier: string,
    ignoreTokens?: boolean
  ): Promise<McpClient>;
  /** Clear a specific client from cache, forcing recreation on next load */
  clearClient?(identifier: string): void;
  /**
   * Drop cached client references after underlying transports were closed
   * (e.g. via `McpManager.closeAllClients()`).
   */
  clearAllMcpCaches?(): void;
}

// OAuth constants and in-memory provider (no auto-open; stores redirect URL)
const OAUTH_GRANT_TYPES = ["authorization_code", "refresh_token"] as const;
const OAUTH_RESPONSE_TYPES = ["code"] as const;
export interface McpOAuthCallbackOwner {
  workspaceId: string;
}

export interface McpOAuthStatePayload {
  id: string;
  owner: McpOAuthCallbackOwner;
  attemptId?: string;
}

function isMcpOAuthCallbackOwner(
  value: unknown
): value is McpOAuthCallbackOwner {
  return (
    value !== null &&
    typeof value === "object" &&
    "workspaceId" in value &&
    typeof value.workspaceId === "string" &&
    value.workspaceId.length > 0
  );
}

function isMcpOAuthStatePayload(value: unknown): value is McpOAuthStatePayload {
  return (
    value !== null &&
    typeof value === "object" &&
    "id" in value &&
    typeof value.id === "string" &&
    value.id.length > 0 &&
    "owner" in value &&
    isMcpOAuthCallbackOwner(value.owner) &&
    (!("attemptId" in value) ||
      value.attemptId === undefined ||
      (typeof value.attemptId === "string" && value.attemptId.length > 0))
  );
}

export function getMcpOAuthCallbackOwner(
  redirectUrl: string
): McpOAuthCallbackOwner {
  return { workspaceId: redirectUrl };
}

export function encodeMcpOAuthState(
  identifier: string,
  owner: McpOAuthCallbackOwner,
  attemptId?: string
): string {
  const payload: McpOAuthStatePayload = {
    id: identifier,
    owner,
    ...(attemptId ? { attemptId } : {}),
  };
  return Buffer.from(JSON.stringify(payload), "utf8").toString("base64url");
}

export function decodeMcpOAuthState(
  state: string
): McpOAuthStatePayload | null {
  try {
    const decoded = Buffer.from(state, "base64url").toString("utf8");
    const parsed = JSON.parse(decoded) as unknown;
    return isMcpOAuthStatePayload(parsed) ? parsed : null;
  } catch {
    return null;
  }
}

function buildStaticClientInformation(
  authConfig: McpAuthConfig | undefined,
  redirectUrl: string
): OAuthClientInformationFull | undefined {
  if (!authConfig) {
    return undefined;
  }

  return {
    client_id: authConfig.CLIENT_ID,
    ...(authConfig.CLIENT_SECRET
      ? { client_secret: authConfig.CLIENT_SECRET }
      : {}),
    redirect_uris: getCanonicalMcpOAuthRedirectUris(redirectUrl),
    grant_types: [...OAUTH_GRANT_TYPES],
    response_types: [...OAUTH_RESPONSE_TYPES],
    token_endpoint_auth_method: "none",
  };
}

function resolveClientInformation({
  storedClientInformation,
  staticClientInformation,
}: {
  storedClientInformation: OAuthClientInformationFull | undefined;
  staticClientInformation: OAuthClientInformationFull | undefined;
}): OAuthClientInformationFull | undefined {
  if (!staticClientInformation) {
    return storedClientInformation;
  }

  if (
    storedClientInformation &&
    storedClientInformation.client_id === staticClientInformation.client_id
  ) {
    return {
      ...staticClientInformation,
      ...storedClientInformation,
      client_secret:
        staticClientInformation.client_secret ??
        storedClientInformation.client_secret,
      redirect_uris: staticClientInformation.redirect_uris,
      grant_types:
        storedClientInformation.grant_types ??
        staticClientInformation.grant_types,
      response_types:
        storedClientInformation.response_types ??
        staticClientInformation.response_types,
      token_endpoint_auth_method:
        storedClientInformation.token_endpoint_auth_method ??
        staticClientInformation.token_endpoint_auth_method,
    };
  }

  return staticClientInformation;
}

type InMemoryOAuthClientProviderOptions = {
  identifier: string;
  redirectUrl: string;
  /** MCP server URL, used to resolve provider-policy authorization params. */
  serverUrl: string | undefined;
  clientMetadata: OAuthClientMetadata;
  scopes: readonly string[] | undefined;
  tokens: OAuthTokens | undefined;
  clientInformation: OAuthClientInformationFull | undefined;
  saveTokens: (tokens: OAuthTokens) => Promise<void>;
  prepareForRefresh?: () => Promise<void>;
  releaseRefreshLeaseOnError?: (underlyingError?: unknown) => Promise<void>;
  invalidateCredentials?: (
    scope: McpOAuthCredentialInvalidationScope
  ) => Promise<void>;
  saveClientInformation: (
    clientInfo: OAuthClientInformationFull
  ) => Promise<void>;
};

class InMemoryOAuthClientProvider implements OAuthClientProvider {
  private _codeVerifier: string | undefined;
  private _lastRedirectUrl: URL | undefined;
  private _oauthState: string | undefined;
  private _oauthAttemptId: string | undefined;

  private readonly _identifier: string;
  private readonly _redirectUrl: string;
  private readonly _serverUrl: string | undefined;
  private readonly _clientMetadata: OAuthClientMetadata;
  private readonly _scopes: readonly string[] | undefined;
  private _tokens: OAuthTokens | undefined;
  private _clientInformation: OAuthClientInformationFull | undefined;
  private readonly _saveTokens: (tokens: OAuthTokens) => Promise<void>;
  private readonly _prepareForRefresh: (() => Promise<void>) | undefined;
  private readonly _releaseRefreshLeaseOnError:
    | ((underlyingError?: unknown) => Promise<void>)
    | undefined;
  private readonly _invalidateCredentials:
    | ((scope: McpOAuthCredentialInvalidationScope) => Promise<void>)
    | undefined;
  private readonly _saveClientInformation: (
    clientInfo: OAuthClientInformationFull
  ) => Promise<void>;

  constructor(options: InMemoryOAuthClientProviderOptions) {
    this._identifier = options.identifier;
    this._redirectUrl = options.redirectUrl;
    this._serverUrl = options.serverUrl;
    this._clientMetadata = options.clientMetadata;
    this._scopes = options.scopes;
    this._tokens = options.tokens;
    this._clientInformation = options.clientInformation;
    this._saveTokens = options.saveTokens;
    this._prepareForRefresh = options.prepareForRefresh;
    this._releaseRefreshLeaseOnError = options.releaseRefreshLeaseOnError;
    this._invalidateCredentials = options.invalidateCredentials;
    this._saveClientInformation = options.saveClientInformation;
  }

  get redirectUrl(): string {
    return this._redirectUrl;
  }

  get clientMetadata(): OAuthClientMetadata {
    return this._clientMetadata;
  }

  state(): string {
    this._oauthAttemptId = randomUUID();
    this._oauthState = encodeMcpOAuthState(
      this._identifier,
      getMcpOAuthCallbackOwner(this._redirectUrl),
      this._oauthAttemptId
    );
    return this._oauthState;
  }

  clientInformation(): OAuthClientInformation | undefined {
    return this._clientInformation;
  }

  hasClientInformation(): boolean {
    return this._clientInformation !== undefined;
  }

  async saveClientInformation(info: OAuthClientInformationFull): Promise<void> {
    this._clientInformation = info;
    await this._saveClientInformation(info);
  }

  tokens(): OAuthTokens | undefined {
    return this._tokens;
  }

  async saveTokens(tokens: OAuthTokens): Promise<void> {
    this._tokens = tokens;
    await this._saveTokens(tokens);
  }

  async prepareForRefresh(): Promise<void> {
    await this._prepareForRefresh?.();
  }

  async releaseRefreshLeaseOnError(underlyingError?: unknown): Promise<void> {
    await this._releaseRefreshLeaseOnError?.(underlyingError);
  }

  async invalidateCredentials(
    scope: McpOAuthCredentialInvalidationScope
  ): Promise<void> {
    switch (scope) {
      case "tokens":
        this._tokens = undefined;
        break;
      case "client":
        this._clientInformation = undefined;
        break;
      case "verifier":
        this._codeVerifier = undefined;
        this._oauthState = undefined;
        this._oauthAttemptId = undefined;
        break;
      case "all":
        this._tokens = undefined;
        this._clientInformation = undefined;
        this._codeVerifier = undefined;
        this._oauthState = undefined;
        this._oauthAttemptId = undefined;
        this._lastRedirectUrl = undefined;
        break;
      default: {
        const _exhaustiveCheck: never = scope;
        return _exhaustiveCheck;
      }
    }
    await this._invalidateCredentials?.(scope);
  }

  redirectToAuthorization(authorizationUrl: URL): void {
    applyConfiguredOAuthScopeOverride(authorizationUrl, this._scopes);
    if (this._serverUrl !== undefined) {
      // Provider-policy params (e.g. Google's access_type=offline +
      // prompt=consent, without which web-client grants carry no refresh
      // token and die un-refreshably at access-token expiry).
      applyMcpOAuthProviderAuthorizationParams(
        authorizationUrl,
        this._serverUrl
      );
    }
    // Do not auto-open. Simply save the redirect URL for later use.
    this._lastRedirectUrl = authorizationUrl;
  }

  get lastRedirectUrl(): URL | undefined {
    return this._lastRedirectUrl;
  }

  async saveCodeVerifier(codeVerifier: string): Promise<void> {
    this._codeVerifier = codeVerifier;
  }

  codeVerifier(): string {
    if (!this._codeVerifier) {
      throw new Error("No code verifier saved");
    }
    return this._codeVerifier;
  }
}

async function createInMemoryOAuthClientProvider(args: {
  serverName: string;
  config: RemoteMcpServerConfig;
  tokenStorage: ScopedMcpTokenStorage;
  authRedirectUrl: string;
}): Promise<InMemoryOAuthClientProvider> {
  const { serverName, config, tokenStorage, authRedirectUrl } = args;
  const staticClientInformation = buildStaticClientInformation(
    config.auth,
    authRedirectUrl
  );
  const clientInformation = resolveClientInformation({
    storedClientInformation: await tokenStorage.loadClientInformation(),
    staticClientInformation,
  });
  return new InMemoryOAuthClientProvider({
    identifier: serverName,
    redirectUrl: authRedirectUrl,
    serverUrl: config.url,
    clientMetadata: {
      redirect_uris: getCanonicalMcpOAuthRedirectUris(authRedirectUrl),
      token_endpoint_auth_method: "none",
      grant_types: [...OAUTH_GRANT_TYPES],
      response_types: [...OAUTH_RESPONSE_TYPES],
      client_name: "Cursor",
      logo_uri: MCP_OAUTH_CLIENT_LOGO_URI,
    },
    scopes: config.auth?.scopes,
    tokens: await tokenStorage.loadTokens(),
    clientInformation,
    saveTokens: newTokens => tokenStorage.saveTokens(newTokens),
    prepareForRefresh: () =>
      tokenStorage.prepareForRefresh?.() ?? Promise.resolve(),
    releaseRefreshLeaseOnError: underlyingError =>
      tokenStorage.releaseRefreshLeaseOnError?.(underlyingError) ??
      Promise.resolve(),
    invalidateCredentials: tokenStorage.invalidateCredentials
      ? scope => tokenStorage.invalidateCredentials!(scope)
      : undefined,
    saveClientInformation: clientInfo =>
      tokenStorage.saveClientInformation(clientInfo),
  });
}

/**
 * Live stdio MCP child pids, SIGKILLed synchronously when this process exits.
 *
 * The SDK's graceful stdio close (stdin EOF wait -> SIGTERM grace -> SIGKILL)
 * can take up to ~4s per stubborn child, so awaiting it on quit made Ctrl-C
 * hang. Children share our process group, so a terminal Ctrl-C also signals
 * them, but `/quit`, SIGTERM-to-us-only, and servers that ignore stdin EOF
 * would otherwise leak the child. Killing tracked pids in a `process.on("exit")`
 * handler makes teardown deterministic and instant without any await.
 *
 * pid-reuse note: we unregister on `close()`, so the set only holds children we
 * believe are still live; a crashed child could leave a stale pid, but SIGKILL
 * to a dead/reused pid is caught and the exit-window race is negligible.
 */
const liveStdioMcpChildPids = new Set<number>();
let stdioMcpKillOnExitInstalled = false;
function killRegisteredStdioMcpChildren(): void {
  for (const childPid of liveStdioMcpChildPids) {
    try {
      process.kill(childPid, "SIGKILL");
    } catch {
      // Already gone; nothing to clean up.
    }
  }
}
function registerStdioMcpChildPid(pid: number): void {
  liveStdioMcpChildPids.add(pid);
  if (stdioMcpKillOnExitInstalled) {
    return;
  }
  stdioMcpKillOnExitInstalled = true;
  process.on("exit", killRegisteredStdioMcpChildren);
}
function unregisterStdioMcpChildPid(pid: number): void {
  liveStdioMcpChildPids.delete(pid);
}

type StdioSpawnFn = (
  command: string,
  args: string[],
  opts: Record<string, unknown>
) => ChildProcess;

/**
 * Wraps the stdio transport's spawn function so the child's OOM badness is
 * reset at fork time. Wrappers like `npx`/`uvx` fork the real MCP server
 * before the connect handshake completes, so resetting only `transport.pid`
 * after connect would leave the already-forked long-lived server with an
 * OOM-exempt daemon's inherited `-1000`; resetting the wrapper before it can
 * fork means every descendant inherits the kernel default instead.
 *
 * Linux-only: the reset is a no-op elsewhere, and the SDK's cross-spawn
 * default must stay in place for its Windows shims (on POSIX cross-spawn is
 * plain `child_process.spawn`, so substituting node's spawn is behavior-
 * preserving).
 */
function wrapStdioSpawnWithOomReset(
  base: StdioSpawnFn | undefined
): StdioSpawnFn | undefined {
  if (process.platform !== "linux") {
    return base;
  }
  const baseSpawn: StdioSpawnFn =
    base ??
    ((command, args, opts) => nodeSpawn(command, args, opts as SpawnOptions));
  return (command, args, opts) => {
    const child = baseSpawn(command, args, opts);
    resetChildOomScoreAdj(child.pid);
    return child;
  };
}

export class McpSdkClient implements McpClient {
  readonly serverName: string;
  readonly config?: McpServerConfig;
  private _stdioChildPid?: number;
  private client: Client;
  private tools: AsyncCache<McpToolDefinition[]>;
  private stateValue: McpClientState;
  private _authProvider?: InMemoryOAuthClientProvider;
  private _sessionId?: string;
  private _currentElicitationProvider?: ScopedMcpElicitationProvider;
  private _currentToolCallId?: string;
  private _currentToolName?: string;
  private _callToolLock: Promise<void> = Promise.resolve();
  private _oauthLifecycleLogger?: McpOAuthLifecycleLogger;
  private _stateEnteredAtMs: number = Date.now();

  constructor(
    serverName: string,
    client: Client,
    options: {
      initialState: McpClientState;
      authProvider?: InMemoryOAuthClientProvider;
      sessionId?: string;
      config?: McpServerConfig;
      oauthLifecycleLogger?: McpOAuthLifecycleLogger;
      /** pid of the stdio child, tracked for SIGKILL-on-exit teardown. */
      stdioChildPid?: number;
    }
  ) {
    this.serverName = serverName;
    this.client = client;
    this.tools = new AsyncCache<McpToolDefinition[]>();
    this.stateValue = options.initialState;
    this._authProvider = options.authProvider;
    this._sessionId = options.sessionId;
    this.config = options.config;
    this._oauthLifecycleLogger = options.oauthLifecycleLogger;
    this._stdioChildPid = options.stdioChildPid;

    // Always set up elicitation handler - it will dispatch to the current provider if available
    this.setupElicitationHandler();
  }

  private _stateKindLabel(state: McpClientState): string {
    return state.kind === "requires_authentication" ? "needsAuth" : state.kind;
  }

  private _logStateTransition(
    from: McpClientState,
    to: McpClientState,
    cause: string,
    errorMeta?: Record<string, unknown>
  ): void {
    if (!this._oauthLifecycleLogger) {
      return;
    }
    const fromKind = this._stateKindLabel(from);
    const toKind = this._stateKindLabel(to);
    if (fromKind === toKind) {
      return;
    }
    const previousStateDurationMs = Date.now() - this._stateEnteredAtMs;
    const serverUrlHost = (() => {
      try {
        const url =
          this.config && "url" in this.config ? this.config.url : undefined;
        return url ? new URL(url).host : undefined;
      } catch {
        return undefined;
      }
    })();
    emitMcpOAuthLifecycleLog({
      logger: this._oauthLifecycleLogger,
      event: "mcp_oauth_state_transition",
      metadata: {
        identifier: this.serverName,
        from: fromKind,
        to: toKind,
        cause,
        serverUrlHost,
        previousStateDurationMs,
        ...errorMeta,
      },
    });
  }

  static createClient(): Client {
    return new Client(
      {
        name: "Cursor",
        version: "1.0.0",
      },
      {
        capabilities: {
          elicitation: { form: {} },
        },
      }
    );
  }

  private setupElicitationHandler(): void {
    this.client.setRequestHandler(ElicitRequestSchema, async request => {
      if (!this._currentElicitationProvider) {
        // No active elicitation provider, decline the request
        return {
          action: "decline" as const,
        };
      }

      if (!("requestedSchema" in request.params)) {
        return {
          action: "decline" as const,
        };
      }

      try {
        // Cast through unknown since MCP SDK schema may not match our strict ElicitationSchema type
        const response = await this._currentElicitationProvider.elicit({
          message: request.params.message,
          requestedSchema: request.params
            .requestedSchema as unknown as ElicitationSchema,
        });

        // Return the response matching the MCP SDK expected type
        return {
          action: response.action,
          content: response.content,
        } as const;
      } catch (_error) {
        return {
          action: "decline" as const,
        };
      }
    });
  }

  static async fromStreamableHttp(
    serverName: string,
    config: RemoteMcpServerConfig,
    tokenStorage: ScopedMcpTokenStorage,
    headers?: Record<string, string>,
    authRedirectUrl?: string,
    fetch?: FetchLike,
    httpExchangeLogging?: McpHttpExchangeLoggingOptions,
    oauthLifecycleLogger?: McpOAuthLifecycleLogger
  ): Promise<McpClient> {
    const url = new URL(config.url);
    authRedirectUrl = authRedirectUrl ?? MCP_OAUTH_LOOPBACK_CALLBACK_URL;
    const tokens = await tokenStorage.loadTokens();
    const oauthProvider = await createInMemoryOAuthClientProvider({
      serverName,
      config,
      tokenStorage,
      authRedirectUrl,
    });

    const baseFetch =
      fetch ??
      (globalThis.fetch
        ? (globalThis.fetch.bind(globalThis) as unknown as FetchLike)
        : undefined);
    const buildLoggedFetch = (
      transportType: "streamableHttp" | "sse"
    ): FetchLike | undefined => {
      if (baseFetch === undefined || httpExchangeLogging === undefined) {
        return baseFetch;
      }
      return createLoggedMcpHttpFetch({
        fetch: baseFetch,
        logger: httpExchangeLogging.logger,
        metadata: {
          ...httpExchangeLogging.metadata,
          transportType,
        },
      });
    };

    const createSseTransport = () =>
      new SSEClientTransport(url, {
        authProvider: oauthProvider,
        requestInit: {
          headers: {
            "User-Agent": "Cursor/1.0.0",
            ...(headers ?? {}),
          },
        },
        fetch: buildLoggedFetch("sse"),
      });
    const client = McpSdkClient.createClient();

    const createRequiresAuthenticationClient = (
      sessionId?: string
    ): McpSdkClient => {
      const authUrl = oauthProvider.lastRedirectUrl?.toString?.() ?? "";
      const mcpClient = new McpSdkClient(serverName, client, {
        oauthLifecycleLogger,
        initialState: {
          kind: "requires_authentication",
          url: authUrl,
          callback: async code => {
            try {
              // Check if client registration has completed
              if (!oauthProvider.hasClientInformation()) {
                throw new Error(
                  "OAuth client registration has not completed. The MCP server may not support dynamic client registration or the registration failed."
                );
              }

              // Exchange the auth code for tokens
              await auth(oauthProvider, {
                serverUrl: url.toString(),
                authorizationCode: code,
                ...(baseFetch !== undefined ? { fetchFn: baseFetch } : {}),
              });
              if (oauthLifecycleLogger) {
                emitMcpOAuthLifecycleLog({
                  logger: oauthLifecycleLogger,
                  event: "mcp_oauth_callback_completion",
                  metadata: {
                    identifier: serverName,
                    ...snapshotServerUrlForLog(url.toString()),
                    ...buildOAuthTokensSnapshotForLog(oauthProvider.tokens(), {
                      expiresInIsFresh: true,
                    }),
                  },
                });
              }

              // Tokens are saved. Don't reconnect in-session (causes hangs/memory issues).
              // Just update state - user needs to reload to use the server.
              mcpClient.updateState({ kind: "ready" });
            } catch (authError: unknown) {
              // If authentication fails, provide a more specific error message
              const errorMessage =
                authError instanceof Error
                  ? authError.message
                  : "Authentication failed";
              throw new Error(
                `Authentication callback failed: ${errorMessage}`
              );
            }
          },
        },
        authProvider: oauthProvider,
        sessionId,
        config,
      });
      return mcpClient;
    };

    const connectSse = async (): Promise<McpClient> => {
      const sseTransport = createSseTransport();
      try {
        await client.connect(sseTransport);
        return new McpSdkClient(serverName, client, {
          initialState: { kind: "ready" },
          authProvider: oauthProvider,
          config,
          oauthLifecycleLogger,
        });
      } catch (sseError: unknown) {
        if (sseError instanceof UnauthorizedError) {
          if (oauthLifecycleLogger) {
            emitMcpOAuthLifecycleLog({
              logger: oauthLifecycleLogger,
              event: "mcp_oauth_state_transition",
              metadata: {
                identifier: serverName,
                from: "connecting",
                to: "needsAuth",
                cause: "connect_auth_error",
                transport: "sse",
                refreshTokenPresent: Boolean(tokens?.refresh_token),
                ...snapshotServerUrlForLog(url.toString()),
                ...getMcpOAuthErrorLogMetadata(sseError),
              },
            });
          }
          return createRequiresAuthenticationClient();
        }
        throw sseError;
      }
    };

    if (config.type === "sse") {
      return connectSse();
    }

    const transport = new StreamableHTTPClientTransport(url, {
      authProvider: oauthProvider,
      requestInit: {
        headers: {
          "User-Agent": "Cursor/1.0.0",
          ...(headers ?? {}),
        },
      },
      fetch: buildLoggedFetch("streamableHttp"),
    });

    try {
      await client.connect(transport);
      return new McpSdkClient(serverName, client, {
        initialState: { kind: "ready" },
        authProvider: oauthProvider,
        sessionId: transport.sessionId,
        config,
        oauthLifecycleLogger,
      });
    } catch (error: unknown) {
      if (error instanceof UnauthorizedError) {
        if (oauthLifecycleLogger) {
          emitMcpOAuthLifecycleLog({
            logger: oauthLifecycleLogger,
            event: "mcp_oauth_state_transition",
            metadata: {
              identifier: serverName,
              from: "connecting",
              to: "needsAuth",
              cause: "connect_auth_error",
              transport: "streamableHttp",
              refreshTokenPresent: Boolean(tokens?.refresh_token),
              ...snapshotServerUrlForLog(url.toString()),
              ...getMcpOAuthErrorLogMetadata(error),
            },
          });
        }
        return createRequiresAuthenticationClient(transport.sessionId);
      }

      if (isSseFallbackAppropriate(error)) {
        return connectSse();
      }

      throw error;
    }
  }

  /**
   * Resume a cached MCP session while keeping the normal OAuth provider wired.
   * On 404 (session expired), caller should fall back to fromStreamableHttp.
   */
  static async fromCachedSession(
    serverName: string,
    config: RemoteMcpServerConfig,
    cachedSession: { sessionId: string },
    tokenStorage: ScopedMcpTokenStorage,
    headers?: Record<string, string>,
    authRedirectUrl: string = MCP_OAUTH_LOOPBACK_CALLBACK_URL,
    fetch?: FetchLike,
    httpExchangeLogging?: McpHttpExchangeLoggingOptions,
    oauthLifecycleLogger?: McpOAuthLifecycleLogger
  ): Promise<McpSdkClient> {
    const url = new URL(config.url);
    const oauthProvider = await createInMemoryOAuthClientProvider({
      serverName,
      config,
      tokenStorage,
      authRedirectUrl,
    });
    const baseFetch =
      fetch ??
      (globalThis.fetch
        ? (globalThis.fetch.bind(globalThis) as unknown as FetchLike)
        : undefined);

    const transport = new StreamableHTTPClientTransport(url, {
      authProvider: oauthProvider,
      sessionId: cachedSession.sessionId,
      requestInit: {
        headers: {
          "User-Agent": "Cursor/1.0.0",
          ...(headers ?? {}),
        },
      },
      fetch:
        baseFetch !== undefined && httpExchangeLogging !== undefined
          ? createLoggedMcpHttpFetch({
              fetch: baseFetch,
              logger: httpExchangeLogging.logger,
              metadata: {
                ...httpExchangeLogging.metadata,
                transportType: "streamableHttp",
              },
            })
          : baseFetch,
    });
    const client = McpSdkClient.createClient();
    await client.connect(transport);

    return new McpSdkClient(serverName, client, {
      initialState: { kind: "ready" },
      authProvider: oauthProvider,
      sessionId: transport.sessionId,
      config,
      oauthLifecycleLogger,
    });
  }

  get sessionId(): string | undefined {
    return this._sessionId;
  }

  static async fromCommand(
    ctx: Context,
    serverName: string,
    config: CommandBasedMcpServerConfig,
    env: Record<string, string>,
    options?: {
      /** Custom spawn function for sandboxed MCP servers. When provided,
       *  StdioClientTransport uses this instead of cross-spawn, enabling
       *  OS-level process isolation via spawnInSandbox. */
      spawn?: (
        command: string,
        args: string[],
        opts: Record<string, unknown>
      ) => import("node:child_process").ChildProcess;
      connectTimeoutMs?: number;
    }
  ): Promise<McpClient> {
    using _span = createSpan(ctx.withName("McpSdkClient.fromCommand"));
    const spawnFn = wrapStdioSpawnWithOomReset(options?.spawn);
    const transport = new StdioClientTransport({
      command: config.command,
      args: config.args ?? [],
      env,
      cwd: config.cwd,
      stderr: "pipe",
      ...(spawnFn && { spawn: spawnFn }),
    } as ConstructorParameters<typeof StdioClientTransport>[0]);
    const stderrCapture = captureStdioStderr(transport.stderr);

    const client = McpSdkClient.createClient();
    const connection = client.connect(transport);
    const connectTimeoutMs =
      options?.connectTimeoutMs ?? COMMAND_MCP_CONNECT_TIMEOUT_MS;
    let timeoutHandle: NodeJS.Timeout | undefined;
    const timeout = new Promise<never>((_resolve, reject) => {
      timeoutHandle = setTimeout(
        () =>
          reject(
            new Error(
              `MCP server connection timed out after ${connectTimeoutMs}ms: ${serverName}`
            )
          ),
        connectTimeoutMs
      );
    });
    try {
      await Promise.race([connection, timeout]);
    } catch (error) {
      connection.catch(() => {});
      await transport.close().catch(() => {});
      await stderrCapture.waitForFlush();
      throw annotateMcpStdioConnectError(error, stderrCapture.read());
    } finally {
      if (timeoutHandle !== undefined) {
        clearTimeout(timeoutHandle);
      }
    }
    const stdioChildPid = transport.pid ?? undefined;
    if (typeof stdioChildPid === "number") {
      registerStdioMcpChildPid(stdioChildPid);
    }
    return new McpSdkClient(serverName, client, {
      initialState: { kind: "ready" },
      config,
      stdioChildPid,
    });
  }

  async close(): Promise<void> {
    if (this._stdioChildPid !== undefined) {
      unregisterStdioMcpChildPid(this._stdioChildPid);
    }
    await this.client.close();
  }

  async getTools(ctx: Context): Promise<McpToolDefinition[]> {
    using _span = createSpan(ctx.withName("McpSdkClient.getTools"));
    if (this.stateValue.kind === "requires_authentication") {
      return [];
    }

    try {
      return await this.tools.get(async () => {
        let cursor: string | undefined;
        const tools: McpToolDefinition[] = [];
        while (true) {
          const response = await this.client.listTools({ cursor });
          tools.push(
            ...response.tools.map(tool => ({
              ...tool,
              inputSchema: tool.inputSchema as JsonValue,
              outputSchema: tool.outputSchema as JsonValue,
            }))
          );
          cursor = response.nextCursor;
          if (cursor === undefined) {
            break;
          }
        }
        return tools;
      });
    } catch (error) {
      if (
        error instanceof UnauthorizedError &&
        this.stateValue.kind === "ready"
      ) {
        const previousState = this.stateValue;
        const redirectUrl =
          this._authProvider?.lastRedirectUrl?.toString() ?? "";
        this.stateValue = {
          kind: "requires_authentication",
          url: redirectUrl,
          callback: async (_code: string) => {},
        };
        this._logStateTransition(
          previousState,
          this.stateValue,
          "runtime_unauthorized",
          { ...getMcpOAuthErrorLogMetadata(error) }
        );
        this._stateEnteredAtMs = Date.now();
      }
      throw error;
    }
  }

  async callTool(
    ctx: Context,
    name: string,
    args: Record<string, JsonValue>,
    toolCallId?: string,
    elicitationProvider?: ScopedMcpElicitationProvider
  ): Promise<McpToolResult> {
    using span = createSpan(ctx.withName("McpSdkClient.callTool"));
    span.span.setAttribute("toolName", name);
    // Acquire lock to ensure exclusive access to elicitation provider context
    const previousLock = this._callToolLock;
    let releaseLock: () => void;
    this._callToolLock = new Promise<void>(resolve => {
      releaseLock = resolve;
    });

    try {
      // Wait for previous tool call to complete
      await previousLock;

      // Store tool call context for elicitation correlation
      this._currentToolCallId = toolCallId;
      this._currentToolName = name;
      this._currentElicitationProvider = elicitationProvider;

      try {
        const response = await this.client.callTool({
          name,
          arguments: args,
        });
        return {
          content: response.content as McpToolResultContent,
          isError: response.error !== undefined,
        };
      } catch (error) {
        if (
          error instanceof UnauthorizedError &&
          this.stateValue.kind === "ready"
        ) {
          const previousState = this.stateValue;
          const redirectUrl =
            this._authProvider?.lastRedirectUrl?.toString() ?? "";
          this.stateValue = {
            kind: "requires_authentication",
            url: redirectUrl,
            callback: async (_code: string) => {},
          };
          this._logStateTransition(
            previousState,
            this.stateValue,
            "runtime_unauthorized",
            { ...getMcpOAuthErrorLogMetadata(error) }
          );
          this._stateEnteredAtMs = Date.now();
        }
        throw error;
      } finally {
        this._currentElicitationProvider = undefined;
        this._currentToolCallId = undefined;
        this._currentToolName = undefined;
      }
    } finally {
      // Release lock for next tool call
      releaseLock!();
    }
  }

  async getInstructions(ctx: Context): Promise<string | undefined> {
    using _span = createSpan(ctx.withName("McpSdkClient.getInstructions"));
    if (this.stateValue.kind === "requires_authentication") {
      return undefined;
    }
    return await this.client.getInstructions();
  }

  async listResources(ctx: Context): Promise<{
    resources: Array<{
      uri: string;
      name?: string;
      description?: string;
      mimeType?: string;
      annotations?: Record<string, unknown>;
    }>;
  }> {
    using _span = createSpan(ctx.withName("McpSdkClient.listResources"));
    if (this.stateValue.kind === "requires_authentication") {
      return { resources: [] };
    }

    // Check if server supports resources capability before attempting to list
    const capabilities = this.client.getServerCapabilities();
    if (!capabilities?.resources) {
      return { resources: [] };
    }

    let cursor: string | undefined;
    const resources: Array<{
      uri: string;
      name?: string;
      description?: string;
      mimeType?: string;
      annotations?: Record<string, unknown>;
    }> = [];

    while (true) {
      const response = await this.client.listResources({ cursor });
      resources.push(...response.resources);
      cursor = response.nextCursor;
      if (cursor === undefined) {
        break;
      }
    }

    return { resources };
  }

  async readResource(
    ctx: Context,
    args: { uri: string }
  ): Promise<{
    contents: Array<{
      uri?: string;
      mimeType?: string;
      text?: string;
      blob?: string;
      name?: string;
      description?: string;
      annotations?: Record<string, unknown>;
    }>;
  }> {
    using _span = createSpan(ctx.withName("McpSdkClient.readResource"));
    if (this.stateValue.kind === "requires_authentication") {
      return { contents: [] };
    }

    const response = await this.client.readResource({ uri: args.uri });
    return { contents: response.contents };
  }

  async listPrompts(ctx: Context): Promise<
    Array<{
      name: string;
      description?: string;
      arguments?: Array<{
        name: string;
        description?: string;
        required?: boolean;
      }>;
    }>
  > {
    using _span = createSpan(ctx.withName("McpSdkClient.listPrompts"));
    if (this.stateValue.kind === "requires_authentication") {
      return [];
    }

    const capabilities = this.client.getServerCapabilities() ?? {
      prompts: false,
    };
    if (!capabilities.prompts) {
      return [];
    }

    const response = await this.client.listPrompts();
    if (!response?.prompts) {
      return [];
    }

    return response.prompts.map(prompt => ({
      name: prompt.name,
      description: prompt.description,
      arguments: prompt.arguments?.map(arg => ({
        name: arg.name,
        description: arg.description,
        required: arg.required,
      })),
    }));
  }

  async getPrompt(
    ctx: Context,
    name: string,
    args?: Record<string, string>
  ): Promise<{
    messages: Array<{
      role: "user" | "assistant" | "system";
      content: Array<
        | {
            type: "text";
            text: string;
          }
        | {
            type: "image";
            data: string;
            mimeType?: string;
          }
      >;
    }>;
  }> {
    using _span = createSpan(ctx.withName("McpSdkClient.getPrompt"));
    if (this.stateValue.kind === "requires_authentication") {
      return { messages: [] };
    }

    const response = await this.client.getPrompt({
      name,
      arguments: args,
    });

    return {
      messages: response.messages.map(msg => ({
        role: msg.role,
        content: Array.isArray(msg.content)
          ? msg.content.map(content => {
              if (content.type === "text") {
                return {
                  type: "text" as const,
                  text: content.text,
                };
              }
              if (content.type === "image") {
                return {
                  type: "image" as const,
                  data: content.data,
                  mimeType: content.mimeType,
                };
              }
              // Fallback for unknown content types
              return {
                type: "text" as const,
                text: JSON.stringify(content),
              };
            })
          : [
              {
                type: "text" as const,
                text:
                  typeof msg.content === "string"
                    ? msg.content
                    : JSON.stringify(msg.content),
              },
            ],
      })),
    };
  }

  /**
   * Get the current tool call context for debugging.
   * This shows which tool is currently being executed and can be used to correlate
   * elicitation requests with their corresponding tool calls.
   * @returns Object with current tool name and toolCallId, or undefined if no tool is executing
   */
  getCurrentToolCallContext():
    | { toolName: string; toolCallId?: string }
    | undefined {
    if (this._currentToolName) {
      return {
        toolName: this._currentToolName,
        toolCallId: this._currentToolCallId,
      };
    }
    return undefined;
  }

  // Observable state API
  async getState(_ctx: Context): Promise<McpClientState> {
    return this.stateValue;
  }

  updateState(newState: McpClientState, cause?: string): void {
    const oldState = this.stateValue;
    this.stateValue = newState;
    this._logStateTransition(oldState, newState, cause ?? "explicit_update");
    this._stateEnteredAtMs = Date.now();
  }
}

/**
 * Error thrown when an MCP tool is not found in the tool set.
 * Contains the requested tool name and list of available tools.
 */
export class McpToolNotFoundError extends Error {
  constructor(
    public readonly toolName: string,
    public readonly availableTools: string[]
  ) {
    super(
      `Tool ${toolName} not found, available tools: ${availableTools.join(", ")}`
    );
    this.name = "McpToolNotFoundError";
  }
}

/**
 * Structural check for {@link McpToolNotFoundError}.
 *
 * The IDE runs cursor-agent-exec and cursor-agent-host as separately
 * webpack-bundled extensions inside one extension host, so this error can be
 * thrown by one bundle's copy of the class and caught by another's —
 * `instanceof` alone fails across bundle copies. Catch sites that may sit on
 * the other side of that boundary (local-exec's MCP executor, the agent
 * loop's tool classification) must use this guard instead.
 */
export function isMcpToolNotFoundError(
  error: unknown
): error is McpToolNotFoundError {
  if (error instanceof McpToolNotFoundError) {
    return true;
  }
  if (!(error instanceof Error) || error.name !== "McpToolNotFoundError") {
    return false;
  }
  const candidate = error as Partial<McpToolNotFoundError>;
  return (
    typeof candidate.toolName === "string" &&
    Array.isArray(candidate.availableTools)
  );
}

/**
 * Error thrown when an MCP server is not found in the lease.
 * Contains the requested server name and list of available servers.
 */
export class McpServerNotFoundError extends Error {
  constructor(
    public readonly serverName: string,
    public readonly availableServers: string[]
  ) {
    super(
      `MCP server ${serverName} not found, available servers: ${availableServers.join(", ")}`
    );
    this.name = "McpServerNotFoundError";
  }
}

/**
 * Thrown when another client sharing the same OAuth credential family already
 * completed a token refresh. Callers should recreate their transport so it
 * rehydrates the winner's fresher stored tokens instead of retrying refresh.
 */
export class SiblingAlreadyRefreshedError extends Error {
  constructor(identifier: string) {
    super(
      `OAuth refresh race detected for ${identifier}: sibling already rotated tokens; reconnecting to use fresh credentials`
    );
    this.name = "SiblingAlreadyRefreshedError";
  }
}

export function isSiblingAlreadyRefreshedError(error: unknown): error is Error {
  return (
    error instanceof Error && error.name === "SiblingAlreadyRefreshedError"
  );
}

export type McpNeedsAuthorizationReason =
  | "no_stored_tokens"
  | "runtime_unauthorized";

/**
 * Thrown when a backend-run MCP server needs the user to complete an OAuth
 * authorization before it is usable.
 *
 * The message is kept byte-identical to the legacy inline string so existing
 * substring classifiers (lazyMcpLease, sandMcpExec) keep working during the
 * migration to `isMcpNeedsAuthorizationError`.
 */
export class McpNeedsAuthorizationError extends Error {
  readonly serverName: string;
  readonly reason: McpNeedsAuthorizationReason;

  constructor(args: {
    serverName: string;
    reason: McpNeedsAuthorizationReason;
  }) {
    super(
      `HTTP MCP server "${args.serverName}" requires authentication. ` +
        `Please authorize this server in cursor.com/agents.`
    );
    this.name = "McpNeedsAuthorizationError";
    this.serverName = args.serverName;
    this.reason = args.reason;
  }
}

export function isMcpNeedsAuthorizationError(error: unknown): error is Error {
  return error instanceof Error && error.name === "McpNeedsAuthorizationError";
}

export interface ExecutableMcpTool {
  definition: NamedMcpToolDefinition;
  execute(
    args: Record<string, JsonValue>,
    toolCallId?: string,
    elicitationFactory?: McpElicitationProviderFactory
  ): Promise<McpToolResult>;
}

export class ExecutableMcpToolSet implements McpToolSet {
  constructor(private readonly tools: Record<string, ExecutableMcpTool>) {}

  async execute(
    name: string,
    args: Record<string, JsonValue>,
    toolCallId?: string,
    elicitationFactory?: McpElicitationProviderFactory
  ): Promise<McpToolResult> {
    const tool = this.tools[name];
    if (!tool) {
      throw new McpToolNotFoundError(name, Object.keys(this.tools));
    }

    return tool.execute(args, toolCallId, elicitationFactory);
  }

  getTools(): NamedMcpToolDefinition[] {
    return Object.entries(this.tools).map(([name, tool]) => ({
      ...tool.definition,
      name,
    }));
  }
}

export class LazyMcpToolSetLease implements McpToolSetLease {
  constructor(private readonly toolSetPromise: Promise<ExecutableMcpToolSet>) {}

  async getToolSet(ctx: Context): Promise<ExecutableMcpToolSet> {
    using _span = createSpan(ctx.withName("LazyMcpToolSetLease.getToolSet"));

    try {
      return await this.toolSetPromise;
    } catch (_error) {
      return new ExecutableMcpToolSet({});
    }
  }

  async getTools(ctx: Context): Promise<NamedMcpToolDefinition[]> {
    try {
      const toolSet = await this.getToolSet(ctx);
      return toolSet.getTools();
    } catch (_error) {
      return [];
    }
  }

  withTimeout(timeout: number): LazyMcpToolSetLease {
    let timeoutId: NodeJS.Timeout;
    const timeoutPromise = new Promise<ExecutableMcpToolSet>(resolve => {
      timeoutId = setTimeout(() => {
        resolve(new ExecutableMcpToolSet({}));
      }, timeout);
    });

    const racedPromise = Promise.race([
      this.toolSetPromise,
      timeoutPromise,
    ]).finally(() => {
      clearTimeout(timeoutId);
    });

    return new LazyMcpToolSetLease(racedPromise);
  }
}

export class NoopMcpLease implements McpLease {
  async getClients(_ctx: Context): Promise<Record<string, McpClient>> {
    return {};
  }

  async getClient(
    _ctx: Context,
    _name: string
  ): Promise<McpClient | undefined> {
    return undefined;
  }

  async getInstructions(_ctx: Context): Promise<McpInstructions[]> {
    return [];
  }

  async getToolSet(_ctx: Context): Promise<ExecutableMcpToolSet> {
    return new ExecutableMcpToolSet({});
  }

  async getTools(_ctx: Context): Promise<NamedMcpToolDefinition[]> {
    return [];
  }

  async getToolsForServers(
    _ctx: Context,
    _serverIdentifiers: readonly string[]
  ): Promise<NamedMcpToolDefinition[]> {
    return [];
  }
}

export class ManagerMcpLease implements ObservableMcpLease {
  constructor(private readonly manager: McpManager) {}

  async getClients(_ctx: Context): Promise<Record<string, McpClient>> {
    return this.manager.getClients();
  }

  async getClient(_ctx: Context, name: string): Promise<McpClient | undefined> {
    return this.manager.getClient(name);
  }

  async getInstructions(ctx: Context): Promise<McpInstructions[]> {
    using span = createSpan(ctx.withName("ManagerMcpLease.getInstructions"));
    return await this.manager.getInstructions(span.ctx);
  }

  async getToolSet(ctx: Context): Promise<ExecutableMcpToolSet> {
    using span = createSpan(ctx.withName("ManagerMcpLease.getToolSet"));
    return await this.manager.getToolSet(span.ctx);
  }

  async getTools(ctx: Context): Promise<NamedMcpToolDefinition[]> {
    using span = createSpan(ctx.withName("ManagerMcpLease.getTools"));
    const toolSet = await this.getToolSet(span.ctx);
    return toolSet.getTools();
  }

  async getToolsForServers(
    ctx: Context,
    serverIdentifiers: readonly string[]
  ): Promise<NamedMcpToolDefinition[]> {
    const requestedServerIds = new Set(serverIdentifiers);
    const allTools = await this.getTools(ctx);
    return allTools.filter(tool => requestedServerIds.has(tool.clientKey));
  }

  onDidChange(listener: McpLeaseChangeListener): Disposable {
    const unsubscribe = this.manager.onDidChange(() => listener(undefined));
    return { dispose: unsubscribe };
  }

  /**
   * Apply a targeted selection change to the live manager: add the newly
   * selected servers and remove the deselected ones, without rebuilding every
   * other client. Mirrors the editor's MCPService transition handling.
   */
  async reconcileSelection(
    ctx: Context,
    changes: { added: readonly string[]; removed: readonly string[] },
    loadClient: (ctx: Context, identifier: string) => Promise<McpClient>
  ): Promise<void> {
    for (const identifier of changes.removed) {
      const existing = this.manager.getClient(identifier);
      this.manager.deleteClient(identifier);
      try {
        await existing?.close?.();
      } catch {
        // Best-effort teardown; do not block the remaining reconcile work.
      }
    }
    for (const identifier of changes.added) {
      if (this.manager.getClient(identifier)) {
        continue;
      }
      const client = await loadClient(ctx, identifier);
      this.manager.setClient(identifier, client);
    }
  }
}

export class McpManager {
  private readonly changeListeners: Set<() => void> = new Set();

  constructor(
    private clients: Record<string, McpClient>,
    private elicitationFactory?: McpElicitationProviderFactory | undefined
  ) {}

  /**
   * Register a listener that will be called when clients are added or removed.
   * Returns a function to unregister the listener.
   */
  onDidChange(listener: () => void): () => void {
    this.changeListeners.add(listener);
    return () => {
      this.changeListeners.delete(listener);
    };
  }

  private fireDidChange(): void {
    for (const listener of this.changeListeners) {
      try {
        listener();
      } catch (e) {
        console.error("Error in McpManager change listener:", e);
      }
    }
  }

  getClients(): Record<string, McpClient> {
    return this.clients;
  }

  getClient(name: string): McpClient | undefined {
    return this.clients[name];
  }

  setClient(name: string, client: McpClient): void {
    this.clients[name] = client;
    this.fireDidChange();
  }

  deleteClient(name: string): void {
    delete this.clients[name];
    this.fireDidChange();
  }

  /**
   * Close every MCP transport (stdio child processes, HTTP sessions, etc.).
   * Safe to call multiple times; failures from individual clients are ignored.
   */
  async closeAllClients(): Promise<void> {
    const clients = Object.values(this.clients);
    await Promise.all(
      clients.map(async client => {
        try {
          await client.close?.();
        } catch {
          // Best-effort shutdown; do not block other clients
        }
      })
    );
  }

  async getToolSet(ctx: Context): Promise<ExecutableMcpToolSet> {
    using span = createSpan(ctx.withName("McpManager.getToolSet"));
    const clientTools = await asyncMapValues(
      Object.entries(this.clients),
      ([key, client]) =>
        client
          .getTools(span.ctx)
          .then(tools =>
            tools.map(tool => ({
              ...tool,
              clientKey: key,
              clientName: client.serverName,
              client: client,
            }))
          )
          // probably should tell the user that the mcp client errored
          .catch(() => []),
      { max: 4 }
    );

    const tools = Array.from(clientTools.values()).flat();

    const toolsMap: Record<string, ExecutableMcpTool> = {};
    for (const tool of tools) {
      toolsMap[`${tool.clientName}-${tool.name}`] = {
        definition: {
          ...tool,
          clientKey: tool.clientKey,
          providerIdentifier: tool.clientName,
          toolName: tool.name,
        },
        execute: async (
          args: Record<string, JsonValue>,
          toolCallId?: string,
          elicitationFactory?: McpElicitationProviderFactory
        ) => {
          // Create elicitation provider for this specific tool call
          const elicitationProvider = elicitationFactory?.createProvider(
            tool.clientName,
            tool.name,
            toolCallId
          );

          const result = await tool.client.callTool(
            span.ctx,
            tool.name,
            args,
            toolCallId,
            elicitationProvider
          );
          return result;
        },
      };
    }
    return new ExecutableMcpToolSet(toolsMap);
  }

  async getInstructions(ctx: Context): Promise<McpInstructions[]> {
    using span = createSpan(ctx.withName("McpManager.getInstructions"));
    const instructionResults = await asyncMapValues(
      Object.entries(this.clients),
      ([_, client]) =>
        client
          .getInstructions(span.ctx)
          .then(instructions => {
            if (!instructions || instructions.trim().length === 0) {
              return null;
            }
            return new McpInstructions({
              serverName: client.serverName,
              instructions: instructions.trim(),
            });
          })
          .catch(() => null),
      { max: 4 }
    );

    return Array.from(instructionResults.values()).filter(
      (result): result is McpInstructions => result !== null
    );
  }
}
