// Result of a manual updateHostNow (admin "Update host"): whether a bundle swap
// was staged for the supervisor, and the target version. `started:false` with a
// reason when already on latest / no bundle source / stage failed.
export interface SandHostUpdateResult {
	readonly started: boolean;
	readonly reason?: string;
	readonly version?: string;
}

// Read-only host-bundle status for the admin "host outdated" badge: the version on
// disk + the latest published version + whether a newer published bundle is
// available, without triggering an update. null fields when unknown (e.g. the
// latest pointer isn't resolved yet).
export interface SandHostStatus {
	readonly hostVersion: string | null;
	readonly latestHostVersion: string | null;
	readonly hostUpdateAvailable: boolean | null;
	// Whether the host is mid-turn (an agent turn or a backgrounded shell job is
	// live) vs idle.
	readonly isBusy: boolean;
	// Additive capability facts from the shared gateway contract
	// (sand/src/shared/rpc/gateway.ts): orderedReplicasV1 means roster and
	// transcript events carry the ordered envelope; sendAcceptanceV1 means
	// sendPrompt resolves at durable acceptance and promptAcceptanceStatus
	// answers nonce queries. Older hosts omit the field; readers treat absence
	// as no capabilities.
	readonly capabilities?: readonly string[];
}

export interface SandBoxSnapshotResult {
	readonly ok: boolean;
	readonly manifestEntries: number;
	// Durable per-agent store.db count in the manifest this flush left behind,
	// so the backend recreate gate can require the conversation DBs are durable
	// before deleting the old box. Optional on the wire so a box on an OLDER
	// host bundle reads as "unknown" and the gate falls back to the
	// manifest-only signal.
	readonly storeDbEntries?: number;
	// Distinct per-agent dirs in the manifest (observability alongside storeDbEntries).
	readonly agentDirEntries?: number;
	// Whether the flush captured every agent store.db it should have — the
	// primary store.db durability signal the backend recreate gate consumes.
	// `undefined` = the sweep did not run (unknown) or an older host bundle
	// that predates the field.
	readonly storeDbComplete?: boolean;
	readonly filesUploaded: number;
	readonly reason?: string;
}

// The box's durable-store status read straight from the manifest it owns — the
// in-box counterpart to the backend's (cross-account-blocked) direct S3 read, so
// durability/status is judged through the box that actually has store access.
export interface SandBoxStoreStatusResult {
	readonly durable: boolean;
	// Persisted manifest hydration stamp. Optional for manifests/hosts predating
	// the field; readers must treat missing as unknown, never complete.
	readonly fullyHydrated?: boolean;
	readonly entryCount: number;
	// Durable per-agent store.db count in the manifest (see SandBoxSnapshotResult).
	// Optional on the wire for the same older-host-bundle back-compat reason.
	readonly storeDbEntries?: number;
	// Distinct per-agent dirs in the manifest (see SandBoxSnapshotResult).
	readonly agentDirEntries?: number;
	readonly totalBytes: number;
	readonly lastSnapshotAtMs: number;
}

// Result of clearing the box's own durable store (reset). The box writes an EMPTY
// manifest via its working presigned PUT (the backend's cross-account direct
// delete is denied) and stops snapshotting so it can't re-seed before teardown.
export interface SandBoxClearStoreResult {
	readonly ok: boolean;
	readonly reason?: string;
}

