	setWindowFocused(args: { readonly isFocused: boolean }): Promise<void>;
	getAgentMemories(args: { readonly id: string }): Promise<readonly SandMemoryRecord[]>;
	deleteAgentMemory(args: {
		readonly id: string;
		readonly memoryId: string;
	}): Promise<readonly SandMemoryRecord[]>;
	clearAgentMemories(args: { readonly id: string }): Promise<readonly SandMemoryRecord[]>;
	getAgentAutomations(args: { readonly id: string }): Promise<readonly SandAutomation[]>;
	// Every agent's automations in one call, each tagged with its owning agent
