export interface SandTrayRecord {
	readonly kind: "error";
	readonly id: string;
	readonly agentId: string;
	readonly title: string;
	readonly detail?: string;
	readonly createdAt: number;
	// Error classification driving the card's recovery affordances. Mirrors
	// SandErrorTrayKind in shared/trays.ts (inlined here so the protocol owns
	// the wire shape); each kind's affordance is documented there.
	readonly errorKind?: "provider_overloaded";
	// Raw/backend error text preserved for debuggability when `detail` holds
	// friendlier copy; kept on the payload, never rendered on the card.
	readonly rawDetail?: string;
	// Recovery affordances projected from the backend's structured error.
	// Mirrors SandErrorTrayAction in shared/trays.ts (inlined for the wire).
	readonly actions?: readonly (
		| { readonly kind: "open-url"; readonly label: string; readonly url: string }
		| { readonly kind: "switch-model" }
		| {
				readonly kind: "dashboard-action";
				readonly label: string;
				readonly action: string;
				readonly args: Readonly<Record<string, string>>;
				readonly successMessage: string | null;
		  }
	)[];
	// Stable identity of a coalescing error (see the trays extension). Carried
	// on the wire so the renderer can recognize semantically-keyed trays (e.g.
	// an introduction failure) without matching on display copy.
	readonly dedupeKey?: string;
	// How many times a coalesced error has occurred; the renderer shows "×N" when
	// it is > 1. Absent for a single occurrence.
	readonly count?: number;
}

