export { type SandGatewayHealth } from "../shared/gateway-wire.js";
// The in-pod supervisor POSTs this to ask the host to gracefully QUIESCE for
// a FORCED host upgrade. Exempt from the bearer like /health (the supervisor
// probes before it has the token; it triggers only a local wind-down and
// exposes no data) and behind the loopback/browser-origin guard. The
// supervisor hand-mirrors this literal (sand/box/supervision/sand-supervisor.mjs).
export const GATEWAY_PREPARE_UPGRADE_PATH = "/prepare-upgrade";

// The pod-proxy routing header: a gateway reached through the anyrun authed
// LB must present the per-pod network token or the LB refuses to route. It
// rides on every gateway request via SandGatewayConnectionInfo.headers,
// alongside the gateway's own bearer; a local loopback host sets none.
export const GATEWAY_NETWORK_TOKEN_HEADER = "x-anyrun-network-token";

export type {
	SandGatewayConnectionInfo,
	SandGatewayVncProxyInfo,
} from "../shared/gateway-connection.js";

const LOOPBACK_HOSTS = new Set(["127.0.0.1", "localhost", "::1", "[::1]"]);

// Whether a bind host is loopback-only. A loopback gateway keeps today's
// no-auth, no-TLS default; binding anywhere else flips on the auth requirement.
export function isLoopbackHost(host: string): boolean {
	return LOOPBACK_HOSTS.has(host.trim().toLowerCase());
}

// The host the desktop should dial, given the gateway's bind host. A wildcard
// bind (0.0.0.0 / ::) is reachable on loopback from the same machine, so the
// co-located desktop connects via 127.0.0.1; any specific host is used as-is.
export function gatewayClientHost(bindHost: string | undefined): string {
	const host = bindHost?.trim() ?? "";
	if (host.length === 0 || host === "0.0.0.0" || host === "::" || host === "[::]") {
		return "127.0.0.1";
	}
	return host;
}

// Builds the base URL the desktop dials from a discovery record. Defaults keep
// older records (no scheme/host) resolving to today's loopback http gateway.
export function buildGatewayBaseUrl(info: {
	readonly scheme?: "http" | "https";
	readonly host?: string;
	readonly port: number;
}): string {
	return `${info.scheme ?? "http"}://${gatewayClientHost(info.host)}:${info.port}`;
}

// The host's egress: the same events the desktop used to receive over Electron
// IPC, now fanned out as Server-Sent Events so any client can attach/detach.
export type SandGatewayEvent =
	| { readonly channel: "transcript"; readonly payload: TranscriptEvent }
	| { readonly channel: "agents"; readonly payload: AgentsEvent }
	| { readonly channel: "agent-upserted"; readonly payload: AgentUpsertedEvent }
	| { readonly channel: "outline"; readonly payload: SandConversationOutlineEvent }
	| { readonly channel: "subagents"; readonly payload: SandSubagentsEvent }
	| { readonly channel: "async-tasks"; readonly payload: SandAsyncTasksEvent }
	| { readonly channel: "memory"; readonly payload: MemoryEvent }
	| { readonly channel: "automations"; readonly payload: AutomationsEvent }
	| { readonly channel: "workflows"; readonly payload: WorkflowsEvent }
	| { readonly channel: "tray"; readonly payload: TrayEvent }
	| { readonly channel: "forever-box"; readonly payload: SandForeverBoxStatus }
	| { readonly channel: "teach-recording"; readonly payload: SandTeachRecordingStatus }
	| {
			readonly channel: "box-disk-pressure";
			readonly payload: SandBoxDiskPressure | null;
	  }
	| {
			readonly channel: "computer-action";
			readonly payload: SandComputerActionEvent;
	  }
	| {
			readonly channel: "mcp-oauth-pending";
			readonly payload: SandMcpOAuthPending;
	  }
	| {
			readonly channel: "mcp-servers";
			readonly payload: SandMcpServersEvent;
	  }
	// The sharing snapshot (room invite joins and room membership), replaced
	// whole on every change like the MCP state.
	| { readonly channel: "sharing"; readonly payload: SandSharingState }
	| {
			readonly channel: "host-settings";
			readonly payload: SandHostSettingsChangedEvent;
	  };

export type SandGatewayEventChannel = SandGatewayEvent["channel"];

// Slim-avatar shaping (GATEWAY_SLIM_AVATARS_HEADER): a client that advertises
// the slim header resolves avatars out-of-band (`getAgentAvatar`, cached by
// the summary's `avatarVersion`), so the gateway serves it summaries with the
// inline bytes nulled. Every shaper is identity-preserving when there is
// nothing to strip.

function stripSummaryInlineAvatar(summary: SandAgentSummary): SandAgentSummary {
	if (summary.avatarDataUrl == null) return summary;
	return { ...summary, avatarDataUrl: null };
}

function stripSummaryRows(rows: readonly SandAgentSummary[]): readonly SandAgentSummary[] {
	let isChanged = false;
	const stripped = rows.map((row) => {
		const slim = stripSummaryInlineAvatar(row);
		if (slim !== row) isChanged = true;
		return slim;
	});
	return isChanged ? stripped : rows;
}

function stripNullableSummary(summary: SandAgentSummary | null): SandAgentSummary | null {
	return summary == null ? null : stripSummaryInlineAvatar(summary);
}

function stripCreateAgentResult(result: SandCreateAgentResult): SandCreateAgentResult {
	const agent = stripSummaryInlineAvatar(result.agent);
	return agent === result.agent ? result : { ...result, agent };
}

/**
 * The slim sibling of SAND_GATEWAY_COMMANDS: identical dispatch, except the
 * summary-carrying replies come back with their inline avatar bytes stripped.
 * The server picks the table off the request's slim header.
 */
export const SAND_GATEWAY_SLIM_COMMANDS: typeof SAND_GATEWAY_COMMANDS = {
	...SAND_GATEWAY_COMMANDS,
	listAgents: async (api, body) =>
		stripSummaryRows(await SAND_GATEWAY_COMMANDS.listAgents(api, body)),
	updateAgent: async (api, body) =>
		stripNullableSummary(await SAND_GATEWAY_COMMANDS.updateAgent(api, body)),
	setGroupMembers: async (api, body) =>
		stripNullableSummary(await SAND_GATEWAY_COMMANDS.setGroupMembers(api, body)),
	setAgentAvatarBytes: async (api, body) =>
		stripNullableSummary(await SAND_GATEWAY_COMMANDS.setAgentAvatarBytes(api, body)),
	createAgent: async (api, body) =>
		stripCreateAgentResult(await SAND_GATEWAY_COMMANDS.createAgent(api, body)),
	createGroup: async (api, body) =>
		stripCreateAgentResult(await SAND_GATEWAY_COMMANDS.createGroup(api, body)),
	duplicateAgent: async (api, body) =>
		stripCreateAgentResult(await SAND_GATEWAY_COMMANDS.duplicateAgent(api, body)),
};

/**
 * Strips inline avatar bytes from one egress event for a slim connection.
 * Only the two roster-carrying channels are touched; every other event passes
 * through by identity.
 */
export function stripInlineAvatarsFromEvent(event: SandGatewayEvent): SandGatewayEvent {
	if (event.channel === "agents") {
		const agents = stripSummaryRows(event.payload.agents);
		if (agents === event.payload.agents) return event;
		return { channel: "agents", payload: { ...event.payload, agents } };
	}
	if (event.channel === "agent-upserted") {
		const agent = stripSummaryInlineAvatar(event.payload.agent);
		if (agent === event.payload.agent) return event;
		return { channel: "agent-upserted", payload: { ...event.payload, agent } };
	}
	return event;
}

// The host's reply to a /prepare-upgrade quiesce request: whether it entered the
// graceful wind-down, and how many turns are still running. The supervisor polls
// until `runningTurns` is 0, then applies the forced upgrade. `quiescing` is
// false when the host declines (e.g. an off-box/laptop host that the forced
// upgrade path never targets).
export interface SandGatewayPrepareUpgradeResult {
	readonly quiescing: boolean;
	readonly runningTurns: number;
}

// The host's reply to a backend `prepareBoxForRecreate` quiesce poke: whether
// the graceful wind-down engaged and how many turns are still running (the
// backend polls until 0), PLUS the ids of the agents marked to resume —
// accurate once `runningTurns` is 0, since a turn writes its resume marker
// before its run count drops. The backend carries these across the pod swap
// because the resume markers are box-private and deliberately do NOT travel
// through the per-box store. `resumePendingWakes` rides the same out-of-band
// channel for the durable pending background-wake markers, denylisted from
// the store sync the same way; the backend round-trips each entry as an
// OPAQUE host-owned object and the receiving host re-coerces it tolerantly.
// Kinds are filtered by the sender (cloud-agent | shell — never subagent) and
// re-filtered by the receiver.
export interface SandGatewayPrepareRecreateResult {
	readonly quiescing: boolean;
	readonly runningTurns: number;
	readonly resumeAgentIds: readonly string[];
	readonly resumePendingWakes: readonly SandPendingWakeMarker[];
}

// The host's reply to `resumeBoxAfterRecreate`: how many of the requested agents
// were actually re-driven (an already-gone / group agent is skipped).
export interface SandGatewayResumeAfterRecreateResult {
	readonly resumed: number;
}
