import {
  getEffectiveMcpNetworkAllowlist,
  type McpNetworkControlsConfig,
  normalizeMcpNetworkAllowlistPattern,
} from "./mcp-url-utils.js";

const PROXY_MEDIATED_ALLOW_ALL = ["0.0.0.0/0", "::/0"] as const;

interface FingerprintNetworkList {
  readonly hasInvalidEntries: boolean;
  readonly entries: string[];
}

function hasConfiguredNetworkAllowlist(config: McpNetworkControlsConfig): boolean {
  return (config.mcpNetworkAllowlist ?? []).some(entry => entry.trim().length > 0);
}

function normalizeNetworkListForFingerprint(
  entries: readonly string[] | undefined
): FingerprintNetworkList {
  const configuredEntries = (entries ?? []).filter(entry => entry.trim().length > 0);
  const normalizedEntries = configuredEntries.flatMap(entry => {
    const normalized = normalizeMcpNetworkAllowlistPattern(entry);
    return normalized === undefined ? [] : [normalized];
  });

  return {
    hasInvalidEntries: normalizedEntries.length !== configuredEntries.length,
    entries: normalizedEntries,
  };
}

function getSandboxAllowlistFingerprintEntries(
  config: McpNetworkControlsConfig
): string[] {
  if (config.mcpNetworkMode === "allow_all") {
    return [...PROXY_MEDIATED_ALLOW_ALL];
  }

  const allowlist = normalizeNetworkListForFingerprint(config.mcpNetworkAllowlist);
  if (config.mcpNetworkMode === "allowlist") {
    return allowlist.entries.includes("*")
      ? [...PROXY_MEDIATED_ALLOW_ALL]
      : allowlist.entries;
  }

  if (!hasConfiguredNetworkAllowlist(config)) {
    return [...PROXY_MEDIATED_ALLOW_ALL];
  }

  const effectiveAllowlist = getEffectiveMcpNetworkAllowlist(config);
  return effectiveAllowlist.includes("*")
    ? [...PROXY_MEDIATED_ALLOW_ALL]
    : effectiveAllowlist;
}

/** Fingerprint sandbox-relevant MCP network-controls config for live revocation. */
export function computeMcpSandboxPolicyFingerprint(
  config: McpNetworkControlsConfig
): string {
  const enabled = config.enabled === true;
  const denylist = normalizeNetworkListForFingerprint(config.mcpNetworkDenylist);
  const denyAll =
    config.mcpNetworkMode === "deny_all" ||
    denylist.entries.includes("*") ||
    denylist.hasInvalidEntries;
  const allow = enabled ? getSandboxAllowlistFingerprintEntries(config) : [];
  const deny = enabled ? (denyAll ? ["*"] : denylist.entries) : [];
  return JSON.stringify({
    enabled,
    mode: config.mcpNetworkMode,
    allow: denyAll ? [] : allow,
    deny,
  });
}
