/**
 * Shared MCP loading boundary for all mcp-agent-exec callers.
 *
 * `loadServer()` is used by DefinitionMcpLoader, ACP session MCPs, plugin MCPs,
 * and direct callers so they share the same local and remote loading paths.
 */
import { createHash } from "node:crypto";
import os from "node:os";
import path from "node:path";
import type { McpClient } from "@anysphere/agent-exec";
import { type Context, createLogger, createSpan } from "@anysphere/context";
import type { McpHttpExchangeLogger } from "@anysphere/mcp-core";
import {
  computeMcpSandboxPolicyFingerprint,
  McpSandboxUnavailableError,
} from "@anysphere/mcp-core";
import { asyncMapValues } from "@anysphere/utils";
import type {
  OAuthClientInformationFull,
  OAuthTokens,
} from "@modelcontextprotocol/sdk/shared/auth.js";
import parseArgsStringToArgv from "string-argv";
import {
  McpServerDisabledError,
  McpServerNotApprovedError,
} from "./approval-store.js";
import type { McpDefinitionLoaderMiddleware } from "./common.js";
import {
  getMcpConfig,
  type McpConfig,
  type McpServerConfig,
} from "./config.js";
import type { McpElicitationProviderFactory } from "./elicitation.js";
import {
  type McpLoader,
  McpManager,
  McpSdkClient,
  type RemoteMcpServerConfig,
  type ScopedMcpTokenStorage,
} from "./mcp.js";
import {
  getStdioMcpSandboxConfig,
  type McpNetworkControlsConfig,
  type McpNetworkControlsConfigService,
} from "./network-controls.js";
import {
  createContextStructuredLifecycleLogger,
  IdentifierScopedTokenStorage,
  LoggedScopedMcpTokenStorage,
  NoOpScopedTokenStorage,
} from "./oauth-logging.js";
import { getMcpStdioStderrTail } from "./stdio-stderr.js";

const logger = createLogger("DefinitionMcpLoader");

/**
 * Expand shell-like path shortcuts that child_process.spawn does not handle:
 * - `~`  or `~/…` → os.homedir() + rest
 * - `./` or `.`    → resolved relative to baseDir (defaults to process.cwd())
 */
function expandPath(args: { filePath: string; baseDir?: string }): string {
  const { filePath, baseDir } = args;
  if (filePath === "~" || filePath.startsWith("~/")) {
    return path.join(os.homedir(), filePath.slice(1));
  }
  if (filePath.startsWith("./") || filePath === ".") {
    return path.resolve(baseDir ?? process.cwd(), filePath);
  }
  return filePath;
}

export { McpSandboxUnavailableError } from "@anysphere/mcp-core";

export interface McpTokenStorage {
  loadTokens(identifier: string): Promise<OAuthTokens | undefined>;
  saveTokens(identifier: string, tokens: OAuthTokens): Promise<void>;
  loadClientInformation(
    identifier: string
  ): Promise<OAuthClientInformationFull | undefined>;
  saveClientInformation(
    identifier: string,
    clientInfo: OAuthClientInformationFull
  ): Promise<void>;
}

export interface McpServerDefinition {
  readonly identifier: string;
  readonly serverConfig: McpServerConfig;
  readonly authStorageKey?: string;
  readonly configPath?: string;
  readonly source?: string;
  readonly metadata?: Record<string, unknown>;
}

export interface McpDefinitionSource {
  getDefinitions(
    ctx: Context,
    cache?: boolean
  ): Promise<readonly McpServerDefinition[]>;
  clearCache?(): void;
}

export interface DefinitionMcpLoaderOptions {
  readonly authRedirectUrlGenerator?: (serverName: string) => string;
  readonly elicitationFactory?: McpElicitationProviderFactory;
  readonly maxConcurrency?: number;
  readonly onDefinitionLoadError?: (
    ctx: Context,
    definition: McpServerDefinition,
    error: unknown
  ) => "handled" | undefined;
}

function isMcpNetworkControlsConfigService(
  middleware: McpDefinitionLoaderMiddleware
): middleware is McpDefinitionLoaderMiddleware &
  McpNetworkControlsConfigService {
  return (
    typeof (middleware as McpNetworkControlsConfigService)
      .getMcpNetworkControlsConfig === "function"
  );
}

function getMcpNetworkControlsServerIdentity(server: McpServerConfig): {
  command?: string;
  url?: string;
} {
  if ("url" in server) {
    return { url: server.url };
  }

  return {
    command: [server.command, ...(server.args ?? [])].join(" "),
  };
}

function countMcpSandboxLogList(values: readonly string[] | undefined): number {
  return values?.length ?? 0;
}

function computeMcpSandboxPolicyHash(
  config: McpNetworkControlsConfig | undefined
): string | undefined {
  if (config === undefined) {
    return undefined;
  }
  return createHash("sha256")
    .update(computeMcpSandboxPolicyFingerprint(config))
    .digest("hex");
}

function getMcpSandboxLogMessage(args: {
  serverName: string;
  networkControlsConfig: McpNetworkControlsConfig | undefined;
  sandboxNetworkControlsConfig: McpNetworkControlsConfig;
}): string {
  return `Sandboxing local MCP server "${args.serverName}" with network controls: networkControlsEnabled=${String(args.networkControlsConfig?.enabled === true)}, mcpNetworkMode=${args.networkControlsConfig?.mcpNetworkMode ?? "unset"}, mcpNetworkAllowlistCount=${countMcpSandboxLogList(args.networkControlsConfig?.mcpNetworkAllowlist)}, mcpNetworkDenylistCount=${countMcpSandboxLogList(args.networkControlsConfig?.mcpNetworkDenylist)}, localAgentNetworkAllowlistCount=${countMcpSandboxLogList(args.networkControlsConfig?.localAgentNetworkAllowlist)}, sandboxPolicyHash=${computeMcpSandboxPolicyHash(args.sandboxNetworkControlsConfig) ?? "none"}`;
}

function getMcpSandboxLogMetadata(args: {
  serverName: string;
  networkControlsConfig: McpNetworkControlsConfig | undefined;
  sandboxNetworkControlsConfig: McpNetworkControlsConfig;
}): Record<string, unknown> {
  return {
    event: "mcp_stdio_sandbox_policy",
    serverName: args.serverName,
    networkControlsEnabled: args.networkControlsConfig?.enabled === true,
    mcpNetworkMode: args.networkControlsConfig?.mcpNetworkMode,
    mcpNetworkAllowlistCount: countMcpSandboxLogList(
      args.networkControlsConfig?.mcpNetworkAllowlist
    ),
    mcpNetworkDenylistCount: countMcpSandboxLogList(
      args.networkControlsConfig?.mcpNetworkDenylist
    ),
    localAgentNetworkAllowlistCount: countMcpSandboxLogList(
      args.networkControlsConfig?.localAgentNetworkAllowlist
    ),
    sandboxPolicyHash: computeMcpSandboxPolicyHash(
      args.sandboxNetworkControlsConfig
    ),
  };
}

async function _loadCommandBasedServer(
  ctx: Context,
  serverName: string,
  commandBasedServer: {
    command: string;
    args?: string[] | undefined;
    env?: Record<string, string> | undefined;
    cwd?: string | undefined;
  }
): Promise<McpClient> {
  // Expand cwd first so it can serve as the base for relative paths in command/args
  const expandedCwd = commandBasedServer.cwd
    ? expandPath({ filePath: commandBasedServer.cwd })
    : undefined;

  // Handle separate args if provided, otherwise parse from command for legacy support
  let command: string;
  let args: string[];

  if (commandBasedServer.args && commandBasedServer.args.length > 0) {
    // New format with separate command and args
    command = expandPath({
      filePath: commandBasedServer.command,
      baseDir: expandedCwd,
    });
    args = commandBasedServer.args.map(arg =>
      expandPath({ filePath: arg, baseDir: expandedCwd })
    );
  } else {
    // Legacy format - parse command string to extract args
    const parts = parseArgsStringToArgv(commandBasedServer.command);
    command = expandPath({ filePath: parts[0], baseDir: expandedCwd });
    args = parts
      .slice(1)
      .map(arg => expandPath({ filePath: arg, baseDir: expandedCwd }));
  }

  return McpSdkClient.fromCommand(
    ctx,
    serverName,
    { command, args, cwd: expandedCwd },
    commandBasedServer.env ?? {}
    // elicitationFactory will be added here
  );
}

async function loadCommandBasedServerWithElicitation(
  ctx: Context,
  serverName: string,
  commandBasedServer: {
    command: string;
    args?: string[] | undefined;
    env?: Record<string, string> | undefined;
    cwd?: string | undefined;
  },
  networkControlsService?: McpNetworkControlsConfigService
): Promise<McpClient> {
  // Expand cwd first so it can serve as the base for relative paths in command/args
  const expandedCwd = commandBasedServer.cwd
    ? expandPath({ filePath: commandBasedServer.cwd })
    : undefined;

  // Handle separate args if provided, otherwise parse from command for legacy support
  let command: string;
  let args: string[];

  if (commandBasedServer.args && commandBasedServer.args.length > 0) {
    // New format with separate command and args
    command = expandPath({
      filePath: commandBasedServer.command,
      baseDir: expandedCwd,
    });
    args = commandBasedServer.args.map(arg =>
      expandPath({ filePath: arg, baseDir: expandedCwd })
    );
  } else {
    // Legacy format - parse command string to extract args
    const parts = parseArgsStringToArgv(commandBasedServer.command);
    command = expandPath({ filePath: parts[0], baseDir: expandedCwd });
    args = parts
      .slice(1)
      .map(arg => expandPath({ filePath: arg, baseDir: expandedCwd }));
  }

  const env = commandBasedServer.env ?? {};

  // When MCP Network Controls are enabled, spawn the MCP server inside a
  // sandbox with OS-level process isolation (Seatbelt on macOS, Landlock/
  // Bubblewrap on Linux). The custom spawn function is passed to
  // StdioClientTransport which uses it instead of cross-spawn.
  //
  // spawnInSandbox is fail-closed: if the sandbox binary is missing or the
  // platform cannot enforce the policy, it throws SandboxUnsupportedError when
  // the transport starts the child. We do not pre-flight the support check or
  // silently drop the server; instead we let that runtime failure surface and
  // re-throw it as a typed McpSandboxUnavailableError so the reason propagates
  // upward to the caller (and the agent) rather than the MCP vanishing without
  // explanation.
  const networkControlsConfig =
    await networkControlsService?.getMcpNetworkControlsConfig?.({
      command: [
        commandBasedServer.command,
        ...(commandBasedServer.args ?? []),
      ].join(" "),
    });
  const sandboxNetworkControlsConfig = getStdioMcpSandboxConfig(
    networkControlsConfig
  );
  if (sandboxNetworkControlsConfig !== undefined) {
    const { buildMcpSandboxPolicy } = await import("./mcp-sandbox-policy.js");
    const { SandboxUnsupportedError, spawnInSandbox } = await import(
      "@anysphere/shell-exec"
    );
    const effectiveCwd = expandedCwd ?? process.cwd();
    const sandboxPolicy = await buildMcpSandboxPolicy(
      sandboxNetworkControlsConfig,
      effectiveCwd
    );
    logger.info(
      ctx,
      getMcpSandboxLogMessage({
        serverName,
        networkControlsConfig,
        sandboxNetworkControlsConfig,
      }),
      getMcpSandboxLogMetadata({
        serverName,
        networkControlsConfig,
        sandboxNetworkControlsConfig,
      })
    );
    try {
      return await McpSdkClient.fromCommand(
        ctx,
        serverName,
        { command, args, cwd: expandedCwd },
        env,
        {
          spawn: (cmd, spawnArgs, opts) =>
            spawnInSandbox(
              cmd,
              spawnArgs as string[],
              opts as import("node:child_process").SpawnOptionsWithoutStdio,
              sandboxPolicy
            ),
        }
      );
    } catch (error) {
      if (error instanceof SandboxUnsupportedError) {
        throw new McpSandboxUnavailableError(serverName, error);
      }
      throw error;
    }
  }

  if (
    networkControlsConfig?.enabled === true &&
    networkControlsConfig.mcpNetworkMode === "no_sandbox"
  ) {
    logger.info(
      ctx,
      `Starting local MCP server "${serverName}" without MCP sandboxing`
    );
  }

  return McpSdkClient.fromCommand(
    ctx,
    serverName,
    { command, args, cwd: expandedCwd },
    env
  );
}

function createHttpExchangeLogging(
  ctx: Context,
  serverName: string
): {
  logger: McpHttpExchangeLogger;
  metadata: { identifier: string; source: string };
} {
  return {
    logger: {
      debug: (message, metadata) => logger.debug(ctx, message, metadata),
      info: (message, metadata) => logger.info(ctx, message, metadata),
      warn: (message, metadata) => logger.warn(ctx, message, metadata),
      error: (message, error, metadata) =>
        logger.error(ctx, message, error, metadata),
    },
    metadata: {
      identifier: serverName,
      source: "mcp-agent-exec",
    },
  };
}

async function loadLegacyHttpServer(
  ctx: Context,
  serverName: string,
  remoteServer: RemoteMcpServerConfig,
  tokenStorage: ScopedMcpTokenStorage,
  authRedirectUrl?: string
): Promise<McpClient> {
  const lifecycleLogger = createContextStructuredLifecycleLogger(ctx, logger);
  const httpExchangeLogging = createHttpExchangeLogging(ctx, serverName);

  return McpSdkClient.fromStreamableHttp(
    serverName,
    remoteServer,
    tokenStorage,
    remoteServer.headers,
    authRedirectUrl,
    undefined,
    httpExchangeLogging,
    lifecycleLogger
  );
}

export async function loadServer(
  ctx: Context,
  serverName: string,
  server: McpServerConfig,
  tokenStorage: ScopedMcpTokenStorage,
  middlewareSettings: {
    middlewares: McpDefinitionLoaderMiddleware[];
    configPath: string;
  } = {
    middlewares: [],
    configPath: "",
  },
  authRedirectUrlGenerator?: (serverName: string) => string
): Promise<McpClient> {
  const { middlewares, configPath } = middlewareSettings;
  using span = createSpan(ctx.withName("mcp-agent-exec.loadServer"));
  span.span.setAttribute("serverName", serverName);
  let next: (
    nextCtx: Context,
    nextServer: McpServerConfig
  ) => Promise<McpClient> = async (
    previousCtx: Context,
    currentServer: McpServerConfig
  ) => {
    using nextSpan = createSpan(previousCtx.withName("loadServer.next"));
    nextSpan.span.setAttribute("serverName", serverName);
    const middlewareCtx = nextSpan.ctx;
    if ("command" in currentServer) {
      nextSpan.span.setAttribute("kind", "command");
      const networkService = middlewares.find(
        isMcpNetworkControlsConfigService
      );
      return await loadCommandBasedServerWithElicitation(
        middlewareCtx,
        serverName,
        currentServer,
        networkService
      );
    }
    if ("url" in currentServer) {
      nextSpan.span.setAttribute("kind", "url");
      const authRedirectUrl = authRedirectUrlGenerator?.(serverName);
      return await loadLegacyHttpServer(
        middlewareCtx,
        serverName,
        currentServer,
        tokenStorage,
        authRedirectUrl
      );
    }
    throw new Error(`Invalid server: ${JSON.stringify(currentServer)}`);
  };
  for (const middleware of middlewares) {
    const previousNext = next;
    next = async (
      middlewareCtx: Context,
      middlewareServer: McpServerConfig
    ) => {
      return await middleware.load(
        middlewareCtx,
        serverName,
        middlewareServer,
        configPath,
        previousNext
      );
    };
  }
  return await next(span.ctx, server);
}

function isExpectedSkippedMcpLoadError(error: unknown): boolean {
  // Note: McpSandboxUnavailableError is intentionally NOT treated as an
  // expected skip. When network controls require sandboxing but the sandbox is
  // unavailable, we want that failure to surface (logged as a load failure and
  // delivered to onDefinitionLoadError) so the agent learns why the MCP server
  // did not start, rather than the server silently disappearing.
  return (
    error instanceof McpServerDisabledError ||
    error instanceof McpServerNotApprovedError ||
    error instanceof McpServerBlockedError
  );
}

function logMcpDefinitionLoadFailure(
  ctx: Context,
  definition: McpServerDefinition,
  error: unknown
): void {
  logger.warn(ctx, "Failed to load MCP server", {
    identifier: definition.identifier,
    source: definition.source,
    configPath: definition.configPath,
    metadata: definition.metadata,
    errorMessage: error instanceof Error ? error.message : String(error),
    stderrTail: getMcpStdioStderrTail(error),
  });
}

export class FileConfigMcpDefinitionSource implements McpDefinitionSource {
  private configPromise: Promise<McpConfig>;

  constructor(private readonly configPath: string) {
    this.configPromise = getMcpConfig(configPath);
  }

  clearCache(): void {
    this.configPromise = getMcpConfig(this.configPath);
  }

  async getDefinitions(
    _ctx: Context,
    _cache: boolean = true
  ): Promise<readonly McpServerDefinition[]> {
    const config = await this.configPromise;
    return Object.entries(config.mcpServers).map(
      ([identifier, serverConfig]) => ({
        identifier,
        serverConfig,
        configPath: this.configPath,
      })
    );
  }
}

export class DefinitionMcpLoader implements McpLoader {
  private readonly clientCache: Map<string, McpClient> = new Map();
  /**
   * Fingerprint of the sandbox-relevant MCP network-controls config captured at
   * the last load. Used to detect mid-session admin policy changes (see
   * {@link evictClientsOnSandboxPolicyChange}).
   */
  private sandboxPolicyFingerprint: string | undefined;

  constructor(
    private readonly source: McpDefinitionSource,
    private readonly tokenStorage: McpTokenStorage,
    private readonly middlewares: McpDefinitionLoaderMiddleware[] = [],
    private readonly options: DefinitionMcpLoaderOptions = {}
  ) {}

  async load(ctx: Context, cache: boolean = true): Promise<McpManager> {
    using _span = createSpan(ctx.withName("DefinitionMcpLoader.load"));
    if (!cache) {
      await this.closeAllCachedClients();
      this.source.clearCache?.();
    }

    const definitions = await this.source.getDefinitions(ctx, cache);
    await this.evictClientsOnSandboxPolicyChange(ctx, definitions);
    const clients: Record<string, McpClient> = {};

    await asyncMapValues(
      [...definitions],
      async definition => {
        try {
          const cachedClient = cache
            ? this.clientCache.get(definition.identifier)
            : undefined;
          const client =
            cachedClient ?? (await this.loadDefinitionClient(ctx, definition));
          if (!cachedClient) {
            this.clientCache.set(definition.identifier, client);
          }
          clients[definition.identifier] = client;
        } catch (error) {
          if (this.handleDefinitionLoadError(ctx, definition, error)) {
            return;
          }

          logMcpDefinitionLoadFailure(ctx, definition, error);
        }
      },
      { max: this.options.maxConcurrency ?? Math.max(definitions.length, 1) }
    );

    return new McpManager(clients, this.options.elicitationFactory);
  }

  clearClient(identifier: string): void {
    this.clientCache.delete(identifier);
  }

  clearAllMcpCaches(): void {
    this.clientCache.clear();
  }

  /**
   * Live policy revocation for cached MCP clients.
   *
   * Sandboxed stdio MCP servers bake their network egress policy in at spawn
   * time (OS-level Seatbelt/Landlock rules), so a team admin tightening the MCP
   * network allowlist mid-session would otherwise leave already-running servers
   * with stale egress rules. On each load we recompute a fingerprint of the
   * sandbox-relevant config (gate state + effective allowlist); when it changes,
   * we close all cached clients so they are re-spawned under the new policy.
   *
   * No-op when no network-controls middleware is present, keeping behavior
   * byte-for-byte identical for setups that do not use MCP network controls.
   */
  private async evictClientsOnSandboxPolicyChange(
    ctx: Context,
    definitions: readonly McpServerDefinition[]
  ): Promise<void> {
    const service = this.middlewares.find(isMcpNetworkControlsConfigService);
    if (!service) {
      return;
    }
    let fingerprint: string;
    try {
      fingerprint = JSON.stringify(
        await Promise.all(
          [...definitions]
            .sort((a, b) => a.identifier.localeCompare(b.identifier))
            .map(async definition => {
              const config =
                (await service.getMcpNetworkControlsConfig?.(
                  getMcpNetworkControlsServerIdentity(definition.serverConfig)
                )) ?? {};
              return [
                definition.identifier,
                computeMcpSandboxPolicyFingerprint(config),
              ] as const;
            })
        )
      );
    } catch {
      // If the policy cannot be read, keep existing clients rather than tearing
      // them down on a transient settings-fetch failure; the next successful
      // read reconciles.
      return;
    }
    const previous = this.sandboxPolicyFingerprint;
    this.sandboxPolicyFingerprint = fingerprint;
    if (previous !== undefined && previous !== fingerprint) {
      logger.info(
        ctx,
        "MCP network-controls policy changed; reloading MCP clients to apply the new egress policy"
      );
      await this.closeAllCachedClients();
    }
  }

  async closeAllCachedClients(): Promise<void> {
    const cachedClients = [...this.clientCache.values()];
    this.clientCache.clear();
    await asyncMapValues(
      cachedClients,
      async client => {
        try {
          await client.close?.();
        } catch {
          // Best-effort shutdown; do not block other cached clients.
        }
      },
      { max: Math.max(cachedClients.length, 1) }
    );
  }

  async loadClient(
    ctx: Context,
    identifier: string,
    ignoreTokens?: boolean
  ): Promise<McpClient> {
    using _span = createSpan(ctx.withName("DefinitionMcpLoader.loadClient"));

    const definitions = await this.source.getDefinitions(ctx);
    await this.evictClientsOnSandboxPolicyChange(ctx, definitions);

    if (!ignoreTokens) {
      const cached = this.clientCache.get(identifier);
      if (cached) {
        return cached;
      }
    }

    const definition = definitions.find(
      candidate => candidate.identifier === identifier
    );

    if (!definition) {
      throw new Error(`MCP server "${identifier}" not found in config`);
    }

    let client: McpClient;
    try {
      client = await this.loadDefinitionClient(ctx, definition, ignoreTokens);
    } catch (error) {
      this.handleDefinitionLoadError(ctx, definition, error);
      throw error;
    }

    if (!ignoreTokens) {
      this.clientCache.set(identifier, client);
    }

    return client;
  }

  private async loadDefinitionClient(
    ctx: Context,
    definition: McpServerDefinition,
    ignoreTokens?: boolean
  ): Promise<McpClient> {
    const identifier = definition.authStorageKey ?? definition.identifier;
    const inner = new IdentifierScopedTokenStorage(
      this.tokenStorage,
      identifier
    );
    const lifecycleLogger = createContextStructuredLifecycleLogger(ctx, logger);
    const loggedScopedTokenStorage = new LoggedScopedMcpTokenStorage({
      inner,
      logger: lifecycleLogger,
      identifier,
      serverUrl:
        "url" in definition.serverConfig
          ? definition.serverConfig.url
          : undefined,
    });
    const scopedTokenStorage: ScopedMcpTokenStorage = ignoreTokens
      ? new NoOpScopedTokenStorage(loggedScopedTokenStorage)
      : loggedScopedTokenStorage;

    return loadServer(
      ctx,
      definition.identifier,
      definition.serverConfig,
      scopedTokenStorage,
      {
        middlewares: this.middlewares,
        configPath: definition.configPath ?? "",
      },
      this.options.authRedirectUrlGenerator
    );
  }

  private handleDefinitionLoadError(
    ctx: Context,
    definition: McpServerDefinition,
    error: unknown
  ): boolean {
    let handled = false;
    try {
      handled =
        this.options.onDefinitionLoadError?.(ctx, definition, error) ===
        "handled";
    } catch (hookError) {
      logger.warn(ctx, "MCP definition load error hook failed", {
        identifier: definition.identifier,
        source: definition.source,
        configPath: definition.configPath,
        metadata: definition.metadata,
        errorMessage:
          hookError instanceof Error ? hookError.message : String(hookError),
      });
    }
    return handled || isExpectedSkippedMcpLoadError(error);
  }
}

export interface ServerBlockingService {
  isServerBlocked(server: { command?: string; url?: string }): Promise<boolean>;
  getMcpNetworkControlsConfig?: McpNetworkControlsConfigService["getMcpNetworkControlsConfig"];
  getMcpServerBlockInfo?(server: { command?: string; url?: string }): Promise<{
    blocked: boolean;
    reason?: "teamPolicy" | "teamNetworkAllowlist";
    message?: string;
  }>;
}

/**
 * Middleware that blocks servers based on a denylist
 */
export type McpServerBlockedReason = "teamPolicy" | "teamNetworkAllowlist";

export class McpServerBlockedError extends Error {
  constructor(
    readonly serverName: string,
    readonly reason: McpServerBlockedReason,
    message?: string
  ) {
    super(
      message ??
        (reason === "teamNetworkAllowlist"
          ? `MCP server "${serverName}" is not on the team network allowlist`
          : `MCP server "${serverName}" is blocked by team policy`)
    );
    this.name = "McpServerBlockedError";
  }
}

export class ServerBlockingMiddleware implements McpDefinitionLoaderMiddleware {
  constructor(private readonly blockingService: ServerBlockingService) {}

  async getMcpNetworkControlsConfig(server?: {
    command?: string;
    url?: string;
  }): Promise<McpNetworkControlsConfig> {
    return (
      (await this.blockingService.getMcpNetworkControlsConfig?.(server)) ?? {}
    );
  }

  async load(
    ctx: Context,
    serverName: string,
    server: McpServerConfig,
    _configPath: string,
    next: (ctx: Context, server: McpServerConfig) => Promise<McpClient>
  ): Promise<McpClient> {
    const commandWithArgs =
      "command" in server
        ? [server.command, ...(server.args ?? [])].join(" ")
        : undefined;

    const serverDefinition = {
      // Admin allowlists should match against the full command invocation.
      // For command-based servers this includes both command and args.
      command: commandWithArgs,
      url: "url" in server ? server.url : undefined,
    };

    const blockInfo: {
      blocked: boolean;
      reason?: McpServerBlockedReason;
      message?: string;
    } = (await this.blockingService.getMcpServerBlockInfo?.(
      serverDefinition
    )) ?? {
      blocked: await this.blockingService.isServerBlocked(serverDefinition),
    };

    if (blockInfo.blocked) {
      throw new McpServerBlockedError(
        serverName,
        blockInfo.reason ?? "teamPolicy",
        blockInfo.message
      );
    }

    return next(ctx, server);
  }
}

export class FileConfigMcpLoader extends DefinitionMcpLoader {
  constructor(
    readonly configPath: string,
    tokenStorage: McpTokenStorage,
    middlewares: McpDefinitionLoaderMiddleware[] = [],
    authRedirectUrlGenerator?: (serverName: string) => string,
    public readonly elicitationFactory?:
      | McpElicitationProviderFactory
      | undefined
  ) {
    super(
      new FileConfigMcpDefinitionSource(configPath),
      tokenStorage,
      middlewares,
      {
        authRedirectUrlGenerator,
        elicitationFactory,
      }
    );
  }

  static init(
    tokenStorage: McpTokenStorage,
    configPath: string,
    middlewares: McpDefinitionLoaderMiddleware[] = []
  ): FileConfigMcpLoader {
    return new FileConfigMcpLoader(configPath, tokenStorage, middlewares);
  }
}
