// Base validator utilities and types
// Basic type validators
export const isString = (value) => typeof value === "string";
export const isObject = (value) => value !== null && typeof value === "object" && !Array.isArray(value);
// Utility function to create validation results
export const createValidationResult = (isValid, errors = []) => ({
    isValid,
    errors,
});
/**
 * Validate that an optional response field is a string when present.
 *
 * Pushes a standardized error into the provided `errors` array if the value
 * is defined and non-string. No-op for undefined.
 *
 * Use for any hook-response field typed `<field>?: string` -- avoids the
 * per-field, per-event boilerplate of inlining the same `typeof !== "string"`
 * check across every validator (additional_context, user_message, agent_message,
 * followup_message, reason, stopReason, etc.).
 */
export function validateOptionalString(value, fieldName, errors) {
    if (value !== undefined && !isString(value)) {
        errors.push(`${fieldName} must be a string if provided`);
    }
}
