import { SimpleControlledExecHandler } from "./controlled.js";
import { ExecutorResource } from "./remote.js";
import { createResource } from "./resource-provider.js";
import { createClientDeserializer, createClientSerializer, createServerDeserializer, createServerSerializer, } from "./serialization.js";
export const grepExecutorResource = createResource(execManager => new ExecutorResource(execManager, createServerSerializer("grepArgs"), createClientDeserializer("grepResult")), (implementation, controlledExecManager) => {
    controlledExecManager.register(new SimpleControlledExecHandler(implementation, createServerDeserializer("grepArgs"), createClientSerializer("grepResult")));
});
