/**
 * Values from `mcp_reconnect_config` that must be read at FSM transition time
 * (so Statsig updates apply without recreating lifecycles).
 */

import type { McpConnectivityChangeSource } from '../connectivity/mcp-connectivity-change.js';
import {
	getMcpReconnectConfigValue,
	type McpReconnectConfigContext,
} from './mcp-reconnect-config.js';

const DEFAULT_FAST_RETRY_MAX_ATTEMPTS = 5;
const DEFAULT_NETWORK_RESUME_RECONNECT_DEBOUNCE_MS = 5_000;

export type ConnectivityRecoveryPolicy = {
	readonly enabled: boolean;
	readonly debounceMs: number;
};

export function getFastRetryMaxAttempts(context?: McpReconnectConfigContext): number {
	const raw = getMcpReconnectConfigValue('fastRetryMaxAttempts', context) ?? DEFAULT_FAST_RETRY_MAX_ATTEMPTS;
	return Math.max(1, Math.min(Math.trunc(raw), 20));
}

/** Undefined = unlimited periodic rounds (V1 compat). */
export function getMaxPeriodicCycles(context?: McpReconnectConfigContext): number | undefined {
	const raw = getMcpReconnectConfigValue('maxPeriodicCycles', context);
	if (raw === undefined) {
		return undefined;
	}
	return Math.max(0, Math.min(Math.trunc(raw), 10_000));
}

/** Opt-in kill switch for OS/network-triggered reconnect fan-out. */
export function getNetworkResumeReconnectEnabled(context?: McpReconnectConfigContext): boolean {
	return getMcpReconnectConfigValue('networkResumeReconnectEnabled', context) ?? false;
}

/** Debounce window before the fan-out runs. Clamped so a bad config can't fire instantly or stall reconnects. */
export function getNetworkResumeReconnectDebounceMs(context?: McpReconnectConfigContext): number {
	const raw = getMcpReconnectConfigValue('networkResumeReconnectDebounceMs', context) ?? DEFAULT_NETWORK_RESUME_RECONNECT_DEBOUNCE_MS;
	return Math.max(0, Math.min(Math.trunc(raw), 1_800_000));
}

/** Debounce window before connectivity recovery runs for any online signal source. */
export function getConnectivityRecoveryDebounceMs(
	_source: McpConnectivityChangeSource,
	context?: McpReconnectConfigContext,
): number {
	return getNetworkResumeReconnectDebounceMs(context);
}

/** Fleet-wide OS recovery stays behind the Statsig kill switch. */
export function getConnectivityRecoveryEnabled(
	source: McpConnectivityChangeSource,
	context?: McpReconnectConfigContext,
): boolean {
	switch (source) {
		case 'power_monitor_resume':
		case 'unlock_screen':
			return getNetworkResumeReconnectEnabled(context);
		default: {
			const _exhaustive: never = source;
			return _exhaustive;
		}
	}
}

export function getConnectivityRecoveryPolicy(
	source: McpConnectivityChangeSource,
	context?: McpReconnectConfigContext,
): ConnectivityRecoveryPolicy {
	return {
		enabled: getConnectivityRecoveryEnabled(source, context),
		debounceMs: getConnectivityRecoveryDebounceMs(source, context),
	};
}
