export type AdminMcpToolAllowlistAutoRunControls = {
  enabled?: boolean;
  mcpToolAllowlist?: readonly string[];
};

export type AdminMcpToolAllowlistServer = {
  name?: string;
  toolAllowlist?: readonly string[];
};

export type ResolveAdminMcpToolAllowlistOptions = {
  autoRunControls?: AdminMcpToolAllowlistAutoRunControls;
  allowedMcpServers?: readonly AdminMcpToolAllowlistServer[];
  isMcpSettingsOverhaulEnabled: boolean;
};

function deduplicateStrings(values: string[]): string[] {
  return [...new Set(values)];
}

function resolvePerMcpToolAllowlist(
  allowedMcpServers: readonly AdminMcpToolAllowlistServer[] | undefined
): string[] {
  return (allowedMcpServers ?? []).flatMap(serverEntry => {
    const serverName = serverEntry.name?.trim();
    if (serverName === undefined || serverName.length === 0) {
      return [];
    }

    const tools = (serverEntry.toolAllowlist ?? [])
      .map(tool => tool.trim())
      .filter(tool => tool.length > 0);
    if (tools.length === 0) {
      return [`${serverName}:*`];
    }

    return tools.map(tool => `${serverName}:${tool}`);
  });
}

export function resolveAdminMcpToolAllowlist({
  autoRunControls,
  allowedMcpServers,
  isMcpSettingsOverhaulEnabled,
}: ResolveAdminMcpToolAllowlistOptions): string[] {
  // The deprecated auto-run MCP allowlist only participates while the broader
  // Auto-Run Controls policy is enabled.
  const legacyAutoRunMcpToolAllowlist =
    autoRunControls?.enabled === true
      ? (autoRunControls.mcpToolAllowlist ?? [])
      : [];

  if (!isMcpSettingsOverhaulEnabled) {
    // Before the MCP settings overhaul, autoRunControls remains the sole source
    // of truth for MCP tool auto-run permissions.
    return deduplicateStrings([...legacyAutoRunMcpToolAllowlist]);
  }

  // Under the overhaul, per-MCP tool allowlists are primary, but non-empty
  // legacy entries are still respected for backwards compatibility.
  return deduplicateStrings([
    ...resolvePerMcpToolAllowlist(allowedMcpServers),
    ...legacyAutoRunMcpToolAllowlist,
  ]);
}
