import type { AuthState, ConnectionState, MCPServerStatus } from './types.js';

export function project(conn: ConnectionState, auth: AuthState): MCPServerStatus {
	// 1. needsUserAuth always wins — user must complete OAuth flow
	if (auth.type === 'needsUserAuth') {
		return { type: 'needsAuth', authorizationUrl: auth.authorizationUrl };
	}

	// 2. Auth expired supersedes connection state — if we know auth is broken,
	//    show it regardless of connection state.  An operation got 401/403,
	//    so the user needs to know even if the transport is technically connected.
	//    This pairs with the classifyToolCallOutcome fix: successful operations
	//    heal expired→valid quickly, so the error clears as soon as auth works again.
	if (auth.type === 'expired') {
		return { type: 'error', error: auth.error };
	}

	// 3. Connection failed (exhausted retries) — periodic retry in progress
	if (conn.type === 'failed') {
		return conn.automaticRetry === false
			? { type: 'error', error: conn.error, isRetryable: false }
			: { type: 'error', error: conn.error };
	}

	// 4. Connection closed with error (stdio)
	if (conn.type === 'closed' && conn.error) {
		return conn.automaticRetry === false
			? { type: 'error', error: conn.error, isRetryable: false }
			: { type: 'error', error: conn.error };
	}

	// 5. Connecting → spinner
	if (conn.type === 'connecting') {
		return { type: 'initializing' };
	}

	// 5.5. Degraded — transport alive but requests failing
	if (conn.type === 'degraded') {
		return { type: 'degraded', reason: conn.reason };
	}

	// 6. Connected (or dormant: idle-released but logically connected) + auth OK → green
	if ((conn.type === 'connected' || conn.type === 'dormant') && (auth.type === 'valid' || auth.type === 'unknown')) {
		return { type: 'connected' };
	}

	// 6.5. Transient failure during fast retries → stay green (V1 parity).
	// The FSM tracks the real state; this only affects user-facing projection
	// and metrics. Matches V1's behavior of silently retrying without updating status.
	if (conn.type === 'transient_failure') {
		return { type: 'connected' };
	}

	// 7. Default (idle, closed without error) → disconnected
	return { type: 'disconnected' };
}
