/** Reverse local-exec routes outside the typed gateway command namespace. */
export const GATEWAY_LOCAL_EXEC_REQUESTS_PATH = "/local-exec/requests";
export const GATEWAY_LOCAL_EXEC_RESPONSES_PATH = "/local-exec/responses";

// Surfaced to the model as a retryable Shell/exec tool error when no desktop is connected.
export const SAND_NO_LOCAL_MACHINE_MESSAGE =
	"Your local machine isn't connected right now (the Grok Bot desktop app must be " +
	"open and online to run commands on it). Try again once it's reachable.";

const COMPUTER_UNAVAILABLE_SUFFIX =
	"is unavailable — it looks disconnected. Reconnect it (or focus the computer " +
	"you want commands to run on) and try again.";
export const SAND_COMPUTER_UNAVAILABLE_MESSAGE = `Your computer ${COMPUTER_UNAVAILABLE_SUFFIX}`;

export function sandComputerUnavailableMessage(label?: string): string {
	if (label === undefined || label.length === 0) {
		return SAND_COMPUTER_UNAVAILABLE_MESSAGE;
	}
	return `Your computer "${label}" ${COMPUTER_UNAVAILABLE_SUFFIX}`;
}

/** Heartbeat cadence and liveness window for a connected desktop. */
export const SAND_LOCAL_EXEC_HEARTBEAT_INTERVAL_MS = 10_000;
export const SAND_LOCAL_EXEC_LIVENESS_WINDOW_MS = 30_000;

/** Resets on every exec response frame; file transfers opt out. */
export const SAND_LOCAL_EXEC_RESPONSE_TIMEOUT_MS = 10_000;

/** Timeout for desktop hello and heartbeat posts. */
export const SAND_LOCAL_EXEC_CONTROL_POST_TIMEOUT_MS = 10_000;

/** Timeout for desktop exec-output and file-data posts. */
export const SAND_LOCAL_EXEC_DATA_POST_TIMEOUT_MS = 120_000;

// Largest single file the local-exec Read / download / upload pulls into memory
// before refusing it. Bytes ship as base64 over the JSON wire, so one file costs
// several times its size (raw + ~1.33x base64 + the JSON copy); a V8 heap
// exhaustion in the long-lived daemon is an UNCATCHABLE abort that strands "work
// on my machine" until restart, so every file path is hard-capped here. Shared
// so the receiver (desktop) and the sender (in-box box) bound the same max.
export const DEFAULT_MAX_LOCAL_EXEC_FILE_BYTES = 100 * 1024 * 1024;

function describeLocalExecBytes(bytes: number): string {
	return `${(bytes / (1024 * 1024)).toFixed(1)} MiB`;
}

// The error surfaced to the model/caller when a single file is refused because
// it exceeds the cap (a Read, download, or upload whose size is known up front).
export function localExecFileTooLargeMessage(actualBytes: number, maxBytes: number): string {
	return (
		`File is ${describeLocalExecBytes(actualBytes)}, which exceeds Grok Bot's ` +
		`${describeLocalExecBytes(maxBytes)} limit for reading or transferring a ` +
		`single file over local-exec. Read a slice with offset/limit, or use a ` +
		`shell command (grep, head, tail) to extract just what you need.`
	);
}

// Surfaced when the receiver refuses an inbound upload frame it bounds BEFORE
// buffering/parsing (the byte count is unknown mid-stream, so it names the
// limit). Shares the "exceeds Grok Bot's ... limit" wording for matchers.
export function localExecUploadFrameTooLargeMessage(maxBytes: number): string {
	return (
		`The upload exceeds Grok Bot's ${describeLocalExecBytes(maxBytes)} limit for ` +
		`transferring a single file over local-exec and was refused before being ` +
		`read into memory. Transfer a smaller file, or split it into parts.`
	);
}

// Largest SSE request frame accumulated before refusal WITHOUT parsing: the
// base64 of a max-size file plus headroom for the SSE prefix + JSON envelope,
// so a real max upload never trips it. Mirrors gateway-server's MAX_BODY_BYTES.
export function maxLocalExecUploadFrameBytes(maxFileBytes: number): number {
	return Math.ceil((maxFileBytes * 4) / 3) + 64 * 1024;
}

/**
 * Host-to-desktop SSE frame. Exec messages use the exec-daemon JSON wire.
 * Local actions carry a renderer-minted `approvalId`; missing ids remain
 * unapproved in ask mode, including frames from older Hosts.
 */
export type SandLocalExecRequestFrame =
	| {
			readonly kind: "exec";
			readonly requestId: string;
			readonly serverMessage: unknown;
			readonly approvalId?: string;
	  }
	| {
			readonly kind: "upload";
			readonly requestId: string;
			readonly path: string;
			readonly bytesBase64: string;
			readonly approvalId?: string;
	  }
	| {
			readonly kind: "download";
			readonly requestId: string;
			readonly path: string;
			readonly approvalId?: string;
	  }
	| {
			readonly kind: "retire-approval";
			readonly requestId: string;
			readonly approvalId: string;
	  }
	| { readonly kind: "cancel"; readonly requestId: string }
	| { readonly kind: "welcome"; readonly providerId: string };

// desktop -> host, batched into a POST body. `message` payloads are
// `ExecClientMessage` / `ExecClientControlMessage` serialized with `.toJson()`.
export type SandLocalExecResponseFrame =
	// Sent once right after the desktop (re)connects so the host can resolve the
	// laptop-side root + terminals folder it advertises to the model (the Shell /
	// Await tools write terminal files there, and they must be paths the desktop's
	// executors can actually reach).
	| {
			readonly kind: "hello";
			readonly localRoot: string;
			readonly terminalsFolder: string;
			// Stable identity of the machine this desktop runs commands on, so the
			// in-box host can address it as a distinct "computer" for file transfer.
			// Older desktops omit it; the bridge then files them under the default
			// single-computer id. `label` is a human name (e.g. the hostname).
			readonly computerId?: string;
			readonly label?: string;
			// Routing-preference signals (see LOCAL_EXEC_SUPERVISOR_HEARTBEAT_FILENAME);
			// daemons predating them omit both and rank lowest.
			readonly supervised?: boolean;
			readonly variant?: string;
	  }
	| { readonly kind: "client"; readonly requestId: string; readonly message: unknown }
	| { readonly kind: "control"; readonly requestId: string; readonly message: unknown }
	| {
			readonly kind: "file";
			readonly requestId: string;
			readonly bytesBase64?: string;
	  }
	| { readonly kind: "file-error"; readonly requestId: string; readonly error: string }
	| { readonly kind: "ping"; readonly supervised?: boolean };

export interface SandLocalExecResponseBatch {
	// The connection id the host handed this desktop in its `welcome` frame, so
	// the host can attribute the batch's hello/heartbeat to the right connection.
	// Omitted by older desktops (the host then falls back to the newest one).
	readonly providerId?: string;
	readonly frames: readonly SandLocalExecResponseFrame[];
}
