/**
 * A computer-use executor that defers X11 initialization until the first action.
 *
 * WHY THIS EXISTS (the bug it fixes): the exec-daemon serves the box's
 * computer-use surface, and it used to build the X11 executor ONCE at startup,
 * gated on a bounded wait for the X11 display. But the box entrypoint starts the
 * exec-daemon BEFORE it brings the desktop up (see sand/box/start-sand-box.sh —
 * `start-exec-daemon &` runs first, `start_desktop` runs later, and a
 * data-preserving recreate can delay the desktop further during boot-time
 * durable-data hydration). When the daemon lost that race the executor was never
 * created, so `computerUseExecutorResource` was never registered on the box's
 * `SimpleControlledExecManager`. For the whole life of that daemon EVERY Computer
 * action then failed with the opaque "No handler found for server message of type
 * computerUseArgs" — even after the desktop came up healthy (box-doctor 5/5,
 * xdotool via the box shell working).
 *
 * THE FIX: always register this executor whenever computer-use is enabled and
 * X11 is installed, and initialize the real X11 executor lazily on first use
 * (with a fresh per-action budget). Once the desktop is up the first action
 * initializes and succeeds; while the desktop is genuinely not ready an action
 * returns a clear, retryable ComputerUseError instead of the opaque dispatch
 * failure. This decouples handler registration from the startup display race.
 */

import type { Context } from "@anysphere/context";
import { createLogger } from "@anysphere/context";
import {
  type ComputerUseArgs,
  ComputerUseError,
  ComputerUseResult,
} from "@anysphere/proto/agent/v1/computer_use_tool_pb.js";
import {
  type ComputerUseExecutor,
  X11ComputerUseExecutor,
} from "./computer-use.js";
import {
  detectDisplaySync,
  parseDisplayNum,
  waitForDisplay,
} from "./display.js";
import type { InputEventLogger } from "./input-event-logger.js";

const logger = createLogger("computer-use-lazy");

/** Default per-action budget spent waiting for the display before failing soft. */
const DEFAULT_READY_TIMEOUT_MS = 30_000;

// The subset of X11ComputerUseExecutor the lazy wrapper drives once the display
// is up: the executor itself plus the record-screen input-event-logger hook.
export interface X11ComputerUseExecutorLike extends ComputerUseExecutor {
  setInputEventLogger(inputEventLogger: InputEventLogger | undefined): void;
}

export interface LazyX11ComputerUseExecutorOptions {
  /** The X11 display the box desktop lives on (e.g. ":1"). */
  readonly display: string;
  /**
   * How long a first-use init waits for the display before giving up with a
   * retryable error. A failed init is not memoized, so each subsequent Computer
   * action gets a fresh budget and can succeed once the desktop is up.
   */
  readonly readyTimeoutMs?: number;
  /**
   * Test seam: build the underlying executor once the display is ready. Defaults
   * to waitForDisplay -> detectDisplaySync -> new X11ComputerUseExecutor.
   */
  readonly initialize?: (
    display: string,
    readyTimeoutMs: number
  ) => Promise<X11ComputerUseExecutorLike>;
}

async function defaultInitialize(
  display: string,
  readyTimeoutMs: number
): Promise<X11ComputerUseExecutorLike> {
  await waitForDisplay(display, readyTimeoutMs);
  const displayInfo = detectDisplaySync(display);
  const displayNum = parseDisplayNum(display);
  return new X11ComputerUseExecutor({
    displayNum,
    resolution: displayInfo.resolution,
  });
}

export class LazyX11ComputerUseExecutor implements ComputerUseExecutor {
  private readonly display: string;
  private readonly readyTimeoutMs: number;
  private readonly initialize: (
    display: string,
    readyTimeoutMs: number
  ) => Promise<X11ComputerUseExecutorLike>;
  private inner: X11ComputerUseExecutorLike | undefined;
  private initInFlight: Promise<X11ComputerUseExecutorLike> | undefined;
  private pendingInputEventLogger: InputEventLogger | undefined;
  private hasPendingInputEventLogger = false;

  constructor(options: LazyX11ComputerUseExecutorOptions) {
    this.display = options.display;
    this.readyTimeoutMs = options.readyTimeoutMs ?? DEFAULT_READY_TIMEOUT_MS;
    this.initialize = options.initialize ?? defaultInitialize;
  }

  // Mirrors X11ComputerUseExecutor.setInputEventLogger so the record-screen
  // wiring can attach the polished-recording logger before the underlying
  // executor exists; it is (re)applied as soon as the executor is created.
  setInputEventLogger(inputEventLogger: InputEventLogger | undefined): void {
    this.pendingInputEventLogger = inputEventLogger;
    this.hasPendingInputEventLogger = true;
    this.inner?.setInputEventLogger(inputEventLogger);
  }

  // Best-effort background warm-up so the common case (desktop up shortly after
  // boot) has the executor ready before the first action, without blocking daemon
  // startup and without turning a slow desktop into a hard failure. A failed
  // prime simply leaves init to the first real action, which retries.
  prime(ctx: Context): void {
    void this.ensureInner(ctx).catch(() => {});
  }

  private async ensureInner(ctx: Context): Promise<X11ComputerUseExecutorLike> {
    if (this.inner !== undefined) return this.inner;
    if (this.initInFlight === undefined) {
      this.initInFlight = (async () => {
        const created = await this.initialize(
          this.display,
          this.readyTimeoutMs
        );
        if (this.hasPendingInputEventLogger) {
          created.setInputEventLogger(this.pendingInputEventLogger);
        }
        this.inner = created;
        logger.info(ctx, "computer-use X11 executor initialized lazily", {
          display: this.display,
        });
        return created;
      })();
    }
    try {
      return await this.initInFlight;
    } catch (error) {
      // Drop the memoized failure so the next Computer action retries once the
      // desktop finishes coming up.
      this.initInFlight = undefined;
      throw error;
    }
  }

  async execute(
    ctx: Context,
    args: ComputerUseArgs
  ): Promise<ComputerUseResult> {
    let inner: X11ComputerUseExecutorLike;
    try {
      inner = await this.ensureInner(ctx);
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      logger.warn(ctx, "computer-use X11 executor not ready", {
        display: this.display,
        error: message,
      });
      return new ComputerUseResult({
        result: {
          case: "error",
          value: new ComputerUseError({
            error:
              `The box desktop (X11 display ${this.display}) is not available yet ` +
              `(${message}). It may still be starting up — try again in a moment.`,
            actionCount: 0,
            durationMs: 0,
          }),
        },
      });
    }
    return await inner.execute(ctx, args);
  }
}
