/**
 * Display detection utilities using xrandr.
 * Provides resolution and refresh rate detection for X11 displays.
 */

import { execFile, execFileSync } from "node:child_process";
import { promisify } from "node:util";
import type { ResolutionConfig } from "./types.js";

const execFileAsync = promisify(execFile);

/** Standard API width - what models see in screenshots */
const API_WIDTH = 1280;

/** Default X11 display when DISPLAY env var is not set */
export const DEFAULT_DISPLAY = ":1";

/**
 * Get the X11 display string from environment or default.
 */
export function getDisplay(override?: string): string {
  return override ?? process.env.DISPLAY ?? DEFAULT_DISPLAY;
}

/**
 * Parse X11 display string to extract the display number.
 * Handles formats like ":1", ":0.0", ":1.0", "localhost:1.0"
 *
 * @param display - X11 display string (e.g., ":1", ":0.0")
 * @returns Display number (e.g., 1 for ":1" or ":1.0")
 */
export function parseDisplayNum(display: string): number {
  // Remove optional hostname prefix (e.g., "localhost:1" -> ":1")
  const colonIndex = display.lastIndexOf(":");
  if (colonIndex === -1) {
    throw new Error(`Invalid X11 display string: ${display} (missing ':')`);
  }
  const afterColon = display.slice(colonIndex + 1);
  // Handle screen suffix (e.g., "1.0" -> "1")
  const numStr = afterColon.split(".")[0];
  const num = parseInt(numStr, 10);
  if (!Number.isFinite(num) || num < 0) {
    throw new Error(
      `Invalid X11 display number in: ${display} (parsed: ${numStr})`
    );
  }
  return num;
}

export interface DisplayInfo {
  /** Display resolution in pixels */
  width: number;
  height: number;
  /** Refresh rate in Hz */
  refreshRate: number;
}

export interface DisplayDetectionResult {
  /** Display info detected from xrandr */
  display: DisplayInfo;
  /** Resolution config for coordinate scaling */
  resolution: ResolutionConfig;
  /** Raw resolution string (e.g., "1920x1200") */
  resolutionString: string;
}

/**
 * Parse xrandr output to extract current resolution and refresh rate.
 * Throws if detection fails - no silent fallbacks.
 *
 * xrandr output format:
 *   Screen 0: minimum 8 x 8, current 1920 x 1200, maximum ...
 *   HDMI-1 connected 1920x1200+0+0 ...
 *      1920x1200    120.00*+  60.00
 *      1280x800      60.00
 *
 * The asterisk (*) marks the active mode.
 */
function parseXrandrOutput(output: string): DisplayInfo {
  let width: number | undefined;
  let height: number | undefined;
  let refreshRate: number | undefined;

  for (const line of output.split("\n")) {
    if (line.includes("*")) {
      // Found active mode line - extract resolution and refresh rate
      const resMatch = line.trim().match(/^(\d+)x(\d+)/);
      if (resMatch) {
        width = parseInt(resMatch[1], 10);
        height = parseInt(resMatch[2], 10);
      }

      // Extract refresh rate (number immediately before asterisk)
      const rateMatch = line.match(/(\d+(?:\.\d+)?)\*(?:\+)?/);
      if (rateMatch) {
        const rate = parseFloat(rateMatch[1]);
        if (rate > 0 && rate <= 500) {
          refreshRate = Math.round(rate);
        }
      }

      if (width && height) {
        break;
      }
    }
  }

  // Fallback: try "current WxH" pattern from Screen line
  if (!width || !height) {
    const currentMatch = output.match(/current\s+(\d+)\s*x\s*(\d+)/i);
    if (currentMatch) {
      width = parseInt(currentMatch[1], 10);
      height = parseInt(currentMatch[2], 10);
    }
  }

  if (!width || !height) {
    throw new Error(
      `Could not detect display resolution from xrandr output.\n` +
        `Expected a line with '*' indicating active mode, or 'current WxH'.\n` +
        `xrandr output:\n${output}`
    );
  }

  // Default refresh rate if not detected (common for VNC/virtual displays)
  if (!refreshRate) {
    refreshRate = 60;
  }

  return { width, height, refreshRate };
}

/**
 * Build ResolutionConfig from display dimensions.
 * API height is calculated to match display aspect ratio.
 */
function buildResolutionConfig(
  displayWidth: number,
  displayHeight: number
): ResolutionConfig {
  const aspectRatio = displayWidth / displayHeight;
  const apiHeight = Math.round(API_WIDTH / aspectRatio);

  return {
    display: { width: displayWidth, height: displayHeight },
    api: { width: API_WIDTH, height: apiHeight },
  };
}

/**
 * Detect display info using xrandr (async version).
 * Throws if detection fails.
 *
 * @param display - X11 display (e.g., ":1" or ":0")
 */
export async function detectDisplay(
  display: string
): Promise<DisplayDetectionResult> {
  const { stdout } = await execFileAsync("xrandr", ["--display", display], {
    timeout: 5000,
  });

  const info = parseXrandrOutput(stdout);
  const resolution = buildResolutionConfig(info.width, info.height);

  return {
    display: info,
    resolution,
    resolutionString: `${info.width}x${info.height}`,
  };
}

/**
 * Detect display info using xrandr (sync version).
 * Throws if detection fails.
 *
 * @param display - X11 display (e.g., ":1" or ":0")
 */
export function detectDisplaySync(display: string): DisplayDetectionResult {
  const stdout = execFileSync("xrandr", ["--display", display], {
    encoding: "utf-8",
    timeout: 5000,
  });

  const info = parseXrandrOutput(stdout);
  const resolution = buildResolutionConfig(info.width, info.height);

  return {
    display: info,
    resolution,
    resolutionString: `${info.width}x${info.height}`,
  };
}

const DEFAULT_WAIT_TIMEOUT_MS = 30_000;
const POLL_INTERVAL_MS = 500;

/**
 * Check if X11 is installed by verifying that xdpyinfo exists and is executable.
 * This is a quick synchronous check that returns immediately.
 */
export function isX11Installed(): boolean {
  try {
    execFileSync("xdpyinfo", ["-version"], { stdio: "ignore", timeout: 500 });
    return true;
  } catch {
    return false;
  }
}

export async function waitForDisplay(
  display: string,
  timeoutMs: number = DEFAULT_WAIT_TIMEOUT_MS
): Promise<void> {
  // First check if X11 is installed at all - if not, skip the wait entirely
  if (!isX11Installed()) {
    throw new Error(
      `X11 is not installed (xdpyinfo not found in PATH). ` +
        `Cannot wait for display ${display}.`
    );
  }

  const startTime = Date.now();

  while (Date.now() - startTime < timeoutMs) {
    try {
      await execFileAsync("xdpyinfo", ["-display", display], {
        timeout: 2000,
      });
      return;
    } catch {
      await new Promise(resolve => setTimeout(resolve, POLL_INTERVAL_MS));
    }
  }

  throw new Error(
    `Timed out waiting for X11 display ${display} after ${timeoutMs}ms`
  );
}

/**
 * Find a working X11 display. Tries DISPLAY env var first, then common values.
 * Throws if no working display found.
 */
export function findDisplay(): string {
  const candidates: string[] = [];

  if (process.env.DISPLAY) {
    candidates.push(process.env.DISPLAY);
  }
  candidates.push(":0", ":1", ":0.0", ":1.0");

  const errors: string[] = [];
  for (const display of candidates) {
    try {
      execFileSync("xdpyinfo", ["-display", display], {
        stdio: "pipe",
        timeout: 5000,
      });
      return display;
    } catch (e) {
      const msg = e instanceof Error ? e.message : String(e);
      errors.push(`  ${display}: ${msg}`);
    }
  }

  throw new Error(
    `Could not find a working X11 display.\n` +
      `Tried:\n${errors.join("\n")}\n\n` +
      `Ensure X server is running and DISPLAY is set correctly.`
  );
}
