import type { EventLogEntry } from './types.js';

const DEFAULT_CAPACITY = 200;

export class EventRingBuffer {
	private buffer: EventLogEntry[];
	private head: number = 0;
	private count: number = 0;
	private readonly capacity: number;

	constructor(capacity: number = DEFAULT_CAPACITY) {
		this.capacity = capacity;
		this.buffer = new Array(capacity);
	}

	push(entry: EventLogEntry): void {
		this.buffer[this.head] = entry;
		this.head = (this.head + 1) % this.capacity;
		if (this.count < this.capacity) {
			this.count++;
		}
	}

	getEntries(): EventLogEntry[] {
		if (this.count === 0) {
			return [];
		}
		if (this.count < this.capacity) {
			return this.buffer.slice(0, this.count);
		}
		// Buffer is full — entries start at head (oldest) and wrap around
		return [
			...this.buffer.slice(this.head),
			...this.buffer.slice(0, this.head),
		];
	}

	clear(): void {
		this.head = 0;
		this.count = 0;
		this.buffer = new Array(this.capacity);
	}

	get size(): number {
		return this.count;
	}
}

/**
 * Per-server event log storage.
 * Each server gets its own ring buffer of EventLogEntries for debugging.
 */
export class ServerEventLog {
	private logs = new Map<string, EventRingBuffer>();
	private readonly capacity: number;

	constructor(capacity: number = DEFAULT_CAPACITY) {
		this.capacity = capacity;
	}

	log(serverId: string, entry: EventLogEntry): void {
		let buffer = this.logs.get(serverId);
		if (!buffer) {
			buffer = new EventRingBuffer(this.capacity);
			this.logs.set(serverId, buffer);
		}
		buffer.push(entry);
	}

	getEntries(serverId: string): EventLogEntry[] {
		return this.logs.get(serverId)?.getEntries() ?? [];
	}

	clear(serverId: string): void {
		this.logs.delete(serverId);
	}

	clearAll(): void {
		this.logs.clear();
	}
}
