export type MCPServerInfo = ({
	type: 'streamableHttp';
	serverUrl: string;
	headers?: Record<string, string>;
	auth?: { CLIENT_ID: string; CLIENT_SECRET?: string; scopes?: string[] };
} | {
	type: 'sse';
	serverUrl: string;
	headers?: Record<string, string>;
	auth?: { CLIENT_ID: string; CLIENT_SECRET?: string; scopes?: string[] };
} | {
	type: 'stdio';
	command: string;
	args?: string[];
	env?: Record<string, string>;
	cwd?: string;
}) & {
	projectPath?: string;
};

export type MCPServerStatus =
	| { type: 'connected' }
	| { type: 'degraded'; reason: string }
	| { type: 'disconnected' }
	| { type: 'error'; error: string; isRetryable?: boolean }
	| { type: 'initializing' }
	| { type: 'needsAuth'; authorizationUrl: string };

// ── Connection FSM ────────────────────────────────────────────────────

export type ConnectionState =
	| { type: 'idle' }
	| { type: 'connecting'; attempt: number; generation: number; periodicCycle: number }
	| { type: 'connected'; attempt: number; stabilized: boolean; probing: boolean }
	| { type: 'dormant' }
	| { type: 'degraded'; consecutiveFailures: number; reason: string; probing: boolean }
	| { type: 'transient_failure'; attempt: number; nextDelayMs: number; periodicCycle: number }
	| {
		type: 'failed';
		error: string;
		periodicRetryDelayMs: number;
		periodicCycle: number;
		exhausted?: boolean;
		automaticRetry?: boolean;
	}
	| {
		type: 'closed';
		error?: string;
		periodicRetryDelayMs: number;
		periodicCycle: number;
		exhausted?: boolean;
		automaticRetry?: boolean;
	};

export type ConnectionEvent =
	| { kind: 'connect_start' }
	| { kind: 'connect_success' }
	| { kind: 'connect_failure'; error: string; isRetryable: boolean }
	| { kind: 'transport_error'; error: string; isRetryable: boolean }
	| { kind: 'transport_closed'; isStdio: boolean }
	| { kind: 'session_invalidated' }
	| { kind: 'idle_suspend' }
	| { kind: 'backoff_timer_expired' }
	| { kind: 'connection_stabilized' }
	| { kind: 'periodic_retry_expired' }
	| { kind: 'request_degraded'; reason: string }
	| { kind: 'health_probe_due' }
	| { kind: 'health_probe_succeeded' }
	| { kind: 'health_probe_failed'; error: string }
	| { kind: 'server_removed' };

export type ConnectionCommand =
	| { type: 'start_backoff_timer'; delayMs: number }
	| { type: 'cancel_backoff_timer' }
	| { type: 'start_stability_timer'; delayMs: number }
	| { type: 'cancel_stability_timer' }
	| { type: 'initiate_connection' };

export interface ConnectionTransitionResult {
	state: ConnectionState | null; // null = no change
	commands: ConnectionCommand[];
}

export interface BackoffConfig {
	/**
	 * Fast retry cap. Omit to use Statsig `mcp_reconnect_config.fastRetryMaxAttempts` (default 5).
	 * Tests may set an explicit value to keep transitions deterministic.
	 */
	maxAttempts?: number;
	getMaxAttempts?: () => number;
	getBackoffDelay: (attempt: number) => number;
	/**
	 * Returns the delay (ms) for the periodic retry timer that fires
	 * when the `failed` state is entered after fast retries are exhausted.
	 * The delay may vary by `periodicCycle` so repeated failed rounds can
	 * back off more aggressively over time.
	 * Should include jitter to decorrelate retries across clients.
	 *
	 * Each periodic kick gives a fresh round of `maxAttempts` fast retries.
	 * Since those fast retries take ~5 minutes (exponential backoff 1s–30s),
	 * even a short periodic delay results in ~5+ minute effective cycle time.
	 */
	getPeriodicRetryDelay: (periodicCycle?: number) => number;
	/**
	 * Maximum number of periodic retry cycles before permanently giving up.
	 * After this many cycles of (fast retries + periodic wait), the server
	 * stays in `failed` with no further automatic retry. The user must
	 * manually reconnect (toggle, reload). Undefined = retry forever (V1 compat).
	 * Omit to use Statsig `mcp_reconnect_config.maxPeriodicCycles`.
	 */
	maxPeriodicCycles?: number;
	getMaxPeriodicCycles?: () => number | undefined;
	getStabilityThresholdMs?: () => number;
	getMaxDegradedProbeFailures?: () => number;
}

// ── Auth FSM ──────────────────────────────────────────────────────────

export type AuthState =
	| { type: 'unknown' }
	| { type: 'valid' }
	| { type: 'expired'; error: string }
	| { type: 'needsUserAuth'; authorizationUrl: string };

export type AuthEvent =
	| { kind: 'auth_required'; authorizationUrl: string }
	| { kind: 'tokens_saved' }
	| { kind: 'auth_completed' }
	| { kind: 'operation_auth_failed'; error: string }
	| { kind: 'operation_succeeded' }
	| { kind: 'server_removed' };

// ── Coordinator ───────────────────────────────────────────────────────

export type FSMEvent =
	| ({ target: 'connection' } & ConnectionEvent)
	| ({ target: 'auth' } & AuthEvent);

export interface ComposedState {
	connection: ConnectionState;
	auth: AuthState;
}

export interface CoordinatorResult {
	connectionState: ConnectionState;
	authState: AuthState;
	commands: ConnectionCommand[];
	projectedStatus: MCPServerStatus;
}

/** Compile-time defaults; live FSM uses getters from `mcpFsmTimingConfig.ts`. */
export {
	DEFAULT_DEGRADED_PROBE_DELAY_MS as DEGRADED_PROBE_DELAY_MS,
	DEFAULT_HEALTH_PROBE_TIMEOUT_MS as HEALTH_PROBE_TIMEOUT_MS,
	DEFAULT_KEEPALIVE_JITTER_MS as KEEPALIVE_JITTER_MS,
	DEFAULT_KEEPALIVE_PROBE_DELAY_MS as KEEPALIVE_PROBE_DELAY_MS,
	DEFAULT_MAX_DEGRADED_PROBE_FAILURES as MAX_DEGRADED_PROBE_FAILURES,
	DEFAULT_STABILITY_THRESHOLD_MS as STABILITY_THRESHOLD_MS,
} from '../config/mcp-fsm-timing-config.js';

// ── Event Log ─────────────────────────────────────────────────────────

export interface EventLogEntry {
	timestamp: number;
	event: string;
	stateBefore: string;
	stateAfter: string;
}
