const GIT_SUFFIX = /\.git$/i;

export interface GitHubRepositoryPathSegments {
  readonly owner: string;
  readonly repo: string;
  readonly hasSubpath: boolean;
}

export interface GitLabRepositoryPathSegments {
  readonly repositorySegments: readonly string[];
  readonly hasSpecialRouteSeparator: boolean;
}

export interface BitbucketRepositoryPathSegments {
  readonly workspace: string;
  readonly repo: string;
  readonly hasSubpath: boolean;
}

export interface AzureDevopsRepositoryPathSegments {
  readonly organization: string;
  readonly project: string;
  readonly repo: string;
  readonly hasSubpath: boolean;
}

const BITBUCKET_NON_REPOSITORY_ROOT_PATHS = new Set(["account", "dashboard"]);

function stripGitSuffix(segment: string): string {
  return segment.replace(GIT_SUFFIX, "");
}

function decodeBitbucketPathSegment(segment: string): string | undefined {
  let decodedSegment: string;
  try {
    decodedSegment = decodeURIComponent(segment);
  } catch {
    return undefined;
  }
  return decodedSegment.length > 0 && !decodedSegment.includes("/")
    ? decodedSegment
    : undefined;
}

export function isGitHubDotComHost(hostname: string): boolean {
  const normalizedHostname = hostname.toLowerCase();
  return (
    normalizedHostname === "github.com" ||
    normalizedHostname.endsWith(".github.com")
  );
}

export function isGitLabHost(hostname: string): boolean {
  return hostname.toLowerCase().split(".").includes("gitlab");
}

export function isBitbucketCloudHost(hostname: string): boolean {
  const normalizedHostname = hostname.toLowerCase();
  return (
    normalizedHostname === "bitbucket.org" ||
    normalizedHostname === "www.bitbucket.org"
  );
}

export function isAzureDevopsServicesHost(hostname: string): boolean {
  const normalizedHostname = hostname.toLowerCase();
  return (
    normalizedHostname === "dev.azure.com" ||
    normalizedHostname === "www.dev.azure.com"
  );
}

export function parseGitHubRepositoryPathSegments(
  segments: readonly string[]
): GitHubRepositoryPathSegments | undefined {
  const owner = segments[0];
  const rawRepo = segments[1];
  if (!owner || !rawRepo) {
    return undefined;
  }

  const repo = stripGitSuffix(rawRepo);
  if (!repo) {
    return undefined;
  }

  return {
    owner,
    repo,
    hasSubpath: segments.length > 2,
  };
}

export function parseGitLabRepositoryPathSegments(
  segments: readonly string[]
): GitLabRepositoryPathSegments | undefined {
  const specialRouteIndex = segments.indexOf("-");
  const hasSpecialRouteSeparator = specialRouteIndex !== -1;
  const repositorySegments = hasSpecialRouteSeparator
    ? segments.slice(0, specialRouteIndex)
    : [...segments];
  if (
    repositorySegments.length < 2 ||
    repositorySegments.some(segment => segment.length === 0)
  ) {
    return undefined;
  }

  const repo = stripGitSuffix(
    repositorySegments[repositorySegments.length - 1]!
  );
  if (!repo) {
    return undefined;
  }
  repositorySegments[repositorySegments.length - 1] = repo;

  return {
    repositorySegments,
    hasSpecialRouteSeparator,
  };
}

export function parseBitbucketRepositoryPathSegments(
  segments: readonly string[]
): BitbucketRepositoryPathSegments | undefined {
  const rawWorkspace = segments[0];
  const rawRepo = segments[1];
  if (rawWorkspace === undefined || rawRepo === undefined) {
    return undefined;
  }

  const workspace = decodeBitbucketPathSegment(rawWorkspace);
  const decodedRepo = decodeBitbucketPathSegment(rawRepo);
  if (
    workspace === undefined ||
    decodedRepo === undefined ||
    BITBUCKET_NON_REPOSITORY_ROOT_PATHS.has(workspace.toLowerCase())
  ) {
    return undefined;
  }

  const repo = stripGitSuffix(decodedRepo);
  if (!repo) {
    return undefined;
  }

  return {
    workspace: encodeURIComponent(workspace),
    repo: encodeURIComponent(repo),
    hasSubpath: segments.length > 2,
  };
}

export function parseAzureDevopsRepositoryPathSegments(
  segments: readonly string[]
): AzureDevopsRepositoryPathSegments | undefined {
  const gitIndex = segments.findIndex(
    segment => segment.toLowerCase() === "_git"
  );
  if (gitIndex < 1 || gitIndex > 2) {
    return undefined;
  }

  const organization = segments[0];
  const rawRepo = segments[gitIndex + 1];
  if (!organization || !rawRepo) {
    return undefined;
  }

  const repo = stripGitSuffix(rawRepo);
  if (!repo) {
    return undefined;
  }

  const project = gitIndex === 2 ? segments[1] : repo;
  if (!project) {
    return undefined;
  }

  return {
    organization,
    project,
    repo,
    hasSubpath: segments.length > gitIndex + 2,
  };
}
