/**
 * FSM probe / stability timing from `mcp_reconnect_config` (Statsig).
 * Defaults match former constants in mcpStateMachine/types.ts.
 */

import {
	getMcpReconnectConfigValue,
	type McpReconnectConfigContext,
} from './mcp-reconnect-config.js';

export const DEFAULT_STABILITY_THRESHOLD_MS = 30_000;
export const DEFAULT_DEGRADED_PROBE_DELAY_MS = 30_000;
export const DEFAULT_HEALTH_PROBE_TIMEOUT_MS = 10_000;
export const DEFAULT_MAX_DEGRADED_PROBE_FAILURES = 3;
export const DEFAULT_KEEPALIVE_PROBE_DELAY_MS: number = 5 * 60_000;
export const DEFAULT_KEEPALIVE_JITTER_MS = 30_000;

export function getStabilityThresholdMs(context?: McpReconnectConfigContext): number {
	const raw = getMcpReconnectConfigValue('stabilityThresholdMs', context) ?? DEFAULT_STABILITY_THRESHOLD_MS;
	return Math.max(5_000, Math.min(Math.trunc(raw), 600_000));
}

export function getDegradedProbeDelayMs(context?: McpReconnectConfigContext): number {
	const raw = getMcpReconnectConfigValue('degradedProbeDelayMs', context) ?? DEFAULT_DEGRADED_PROBE_DELAY_MS;
	return Math.max(1_000, Math.min(Math.trunc(raw), 3_600_000));
}

export function getHealthProbeTimeoutMs(context?: McpReconnectConfigContext): number {
	const raw = getMcpReconnectConfigValue('healthProbeTimeoutMs', context) ?? DEFAULT_HEALTH_PROBE_TIMEOUT_MS;
	return Math.max(1_000, Math.min(Math.trunc(raw), 120_000));
}

export function getMaxDegradedProbeFailures(context?: McpReconnectConfigContext): number {
	const raw = getMcpReconnectConfigValue('maxDegradedProbeFailures', context) ?? DEFAULT_MAX_DEGRADED_PROBE_FAILURES;
	return Math.max(1, Math.min(Math.trunc(raw), 20));
}

export function getKeepaliveProbeDelayMs(context?: McpReconnectConfigContext): number {
	const raw = getMcpReconnectConfigValue('keepaliveProbeDelayMs', context) ?? DEFAULT_KEEPALIVE_PROBE_DELAY_MS;
	return Math.max(10_000, Math.min(Math.trunc(raw), 3_600_000));
}

export function getKeepaliveJitterMs(context?: McpReconnectConfigContext): number {
	const raw = getMcpReconnectConfigValue('keepaliveJitterMs', context) ?? DEFAULT_KEEPALIVE_JITTER_MS;
	return Math.max(0, Math.min(Math.trunc(raw), 3_600_000));
}
