import type { SpawnOptionsWithoutStdio } from "node:child_process";
import { mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import type Stream from "node:stream";
import { type Context, createSpan, reportEvent } from "@anysphere/context";
import { createWritableIterable, findActualExecutable } from "@anysphere/utils";
import {
  attachShellStateOutput,
  parseShellStateOutput,
  spawnWithSignal,
  splitPwdAndState,
  writeShellStatePipe,
} from "./core.js";
import dumpBashState, {
  BASH_STATE_END_MARKER,
  BASH_STATE_START_MARKER,
} from "./dump_bash_state.js";
import {
  attachShellOutputStreams,
  type BufferReadable,
} from "./output-limiter.js";
import { resolveSandboxPolicyForWorkspace } from "./sandbox/policy-merge.js";
import { captureSandboxDenies } from "./sandbox/sandbox.js";
import { getSudoAliasInjection } from "./sudo.js";
import {
  SHELL_ENV_OVERRIDES,
  type TerminalCommandOptions,
  type TerminalEvent,
  type TerminalExecutor,
  type TerminalInitializationOptions,
} from "./types.js";

function getBashPath(userTerminalHint?: string): string | null {
  // NB: On Windows, there is a "bash.exe" that will connect to WSL, and there
  // may be other bash.exe's such as Cygwin, MSYS2, etc, but we *only* support
  // Git Bash, so make sure we find that and if it doesn't exist, we toss it.
  if (process.platform === "win32") {
    const pathMustMatch = /git.*bash/i;

    if (userTerminalHint && pathMustMatch.test(userTerminalHint)) {
      return userTerminalHint;
    }

    const gitBashPath = findActualExecutable("bash", [], pathMustMatch).cmd;

    if (pathMustMatch.test(gitBashPath)) {
      return gitBashPath;
    } else {
      return null;
    }
  }

  const shell = process.env.SHELL;
  if (shell?.includes("bash")) {
    return shell;
  }

  const bashPath = findActualExecutable("bash", []).cmd;
  return bashPath;
}

function windowsPathToGitBash(windowsPath: string): string {
  if (process.platform !== "win32") {
    return windowsPath;
  }

  // Convert Windows path (e.g., C:\Users\...\Temp\...) to Git Bash format
  // Git Bash on Windows can handle Windows paths directly, but we convert to Unix-style
  // for consistency. Try using cygpath if available, otherwise convert manually.
  const normalized = path.normalize(windowsPath);

  // Git Bash typically maps C:\ to /c/, but the exact format can vary
  // Try the standard MSYS2/Git Bash format: /c/Users/...
  const driveLetter = normalized[0]?.toLowerCase();
  if (driveLetter && normalized[1] === ":" && normalized[2] === path.sep) {
    // Convert C:\... to /c/... (MSYS2/Git Bash format)
    const unixPath = `/${driveLetter}${normalized.slice(2).replace(/\\/g, "/")}`;
    return unixPath;
  }
  // Fallback: just replace backslashes with forward slashes
  return normalized.replace(/\\/g, "/");
}

class BashState implements TerminalExecutor {
  constructor(
    private cwd: string,
    private state: string,
    private userTerminalHint?: string,
    private readonly useFileStateTransport: boolean = false
  ) {}

  async getCwd(): Promise<string> {
    return this.cwd;
  }

  clone(workingDirectory?: string): BashState {
    return new BashState(
      workingDirectory ?? this.cwd,
      this.state,
      this.userTerminalHint,
      this.useFileStateTransport
    );
  }

  async *execute(
    ctx: Context,
    command: string,
    options?: TerminalCommandOptions
  ): AsyncIterable<TerminalEvent> {
    using span = createSpan(ctx.withName("BashState.execute"));

    const pipeStdin = options?.pipeStdin ?? false;

    const iterable = createWritableIterable<TerminalEvent>();

    const cwd = options?.workingDirectory ?? this.cwd;

    const env = {
      ...process.env,
      ...SHELL_ENV_OVERRIDES,
      ...options?.env,
    } as NodeJS.ProcessEnv;

    let core = `builtin eval "$1"`;
    if (!pipeStdin) {
      core += " < /dev/null";
    }

    // Inject sudo alias to use -A flag when askpass is configured
    // This makes any sudo invocation in the user's command use the askpass helper
    const sudoAliasInjection = getSudoAliasInjection(env);

    const useFileTransport = this.useFileStateTransport;
    let tempDir: string | undefined;
    let stateInputPath: string | undefined;
    let stateOutputPath: string | undefined;

    if (useFileTransport) {
      tempDir = await mkdtemp(path.join(os.tmpdir(), "cursor-bash-state-"));
      const dirname = path.basename(tempDir);

      stateInputPath = path.join(tempDir, "state-in");
      stateOutputPath = path.join(tempDir, "state-out");

      await writeFile(stateInputPath, this.state, "utf8");

      // Ensure the output file exists (empty) so Git Bash can write to it
      await writeFile(stateOutputPath, "", "utf8").catch(() => {
        // Best effort - if it fails, continue anyway
      });

      // NB: We need to pass this path in Git Bash format, not Windows format
      // Git Bash maps Windows paths: C:\Users\... becomes /c/Users/...
      // Use cygpath if available to ensure correct path conversion, otherwise convert manually
      const gitBashInputPath = windowsPathToGitBash(stateInputPath);
      const gitBashOutputPath = windowsPathToGitBash(stateOutputPath);

      // Set environment variables - Git Bash will use cygpath internally if needed
      env.CURSOR_STATE_INPUT_FILE = gitBashInputPath;
      env.CURSOR_STATE_OUTPUT_FILE = gitBashOutputPath;
    }

    const stateLoader = useFileTransport
      ? 'snap=$(command cat "$CURSOR_STATE_INPUT_FILE")'
      : "snap=$(command cat <&3)";
    // Ensure the output directory exists and file is writable
    const stateWriter = useFileTransport
      ? 'mkdir -p "$(dirname "$CURSOR_STATE_OUTPUT_FILE")" 2>/dev/null; dump_bash_state > "$CURSOR_STATE_OUTPUT_FILE"'
      : "dump_bash_state >&4";

    const c =
      `${stateLoader} && builtin shopt -s extglob && builtin eval -- "$snap" && ` +
      `{ builtin set +u 2>/dev/null || true; ` +
      `builtin eval "\${__CURSOR_SANDBOX_ENV_RESTORE:-}" 2>/dev/null; ` +
      `builtin export PWD="$(builtin pwd)"; builtin shopt -s expand_aliases 2>/dev/null; ${sudoAliasInjection}${core}; }; ` +
      `COMMAND_EXIT_CODE=$?; ${stateWriter}; builtin exit $COMMAND_EXIT_CODE`;

    const args = [
      "-O",
      "extglob",
      "-c",
      c,
      "--", // This separates options from positional arguments
      command,
    ];

    const bashPath = getBashPath(this.userTerminalHint);
    if (!bashPath) {
      throw new Error("Can't find Bash");
    }

    const sandboxWorkspaceRoot = options?.sandboxWorkspaceRoot ?? cwd;
    const resolvedPolicy = (
      await resolveSandboxPolicyForWorkspace(
        sandboxWorkspaceRoot,
        options?.sandboxPolicy
      )
    ).policy;
    const sandboxPolicy =
      resolvedPolicy.type !== "insecure_none"
        ? { ...resolvedPolicy, sandboxWorkspaceRoot }
        : resolvedPolicy;

    let newState = "";

    const readStateFromTransport = async () => {
      if (useFileTransport) {
        if (!stateOutputPath) {
          newState = this.state;
          return;
        }
        try {
          newState = await readFile(stateOutputPath, "utf8");
        } catch (error) {
          console.warn("[shell-exec] Failed to read bash state file", error);
          newState = this.state;
        }
      }
    };

    const cleanupStateFiles = async () => {
      if (tempDir) {
        try {
          await rm(tempDir, { recursive: true, force: true });
        } catch {
          // best effort cleanup
        }
      }
    };

    let child: ReturnType<typeof spawnWithSignal>;
    try {
      child = spawnWithSignal(
        bashPath,
        args,
        {
          env,
          // Use 'ignore' for stdin (unless interactive) to prevent background processes
          // from inheriting an open stdin pipe, which would prevent the 'close' event from firing
          stdio: [
            pipeStdin ? "pipe" : "ignore",
            "pipe",
            "pipe",
            "pipe",
            "pipe",
          ],
          cwd,
          // Use detached to create a new process group. This allows killing all
          // child processes (e.g., python servers) when aborting, not just the shell.
          detached: true,
        } as SpawnOptionsWithoutStdio,
        sandboxPolicy,
        options?.signal
      );
    } catch (error) {
      await cleanupStateFiles();
      throw error;
    }

    // Pass the stdin stream to the background terminal state if available, for the writeShellStdin tool to use
    child.on("spawn", async () => {
      try {
        await iterable.write({
          type: "stdin_ready",
          stdin: child.stdin ?? undefined,
          pid: child.pid,
        });
      } catch (_error) {
        // Iterable might be closed, ignore write errors
      }
    });

    const outputPump = attachShellOutputStreams({
      stdout: child.stdout as BufferReadable | null,
      stderr: child.stderr as BufferReadable | null,
      writable: iterable,
      bufferOutputEvents: options?.bufferOutputEvents,
      outputLimiterOptions: options?.outputLimiterOptions,
    });

    // Handle process exit and errors
    child.on("error", async error => {
      await cleanupStateFiles();
      iterable.throw(error);
    });

    // NB: This is extremely Tricky. Data from stdio can come in after 'exit',
    // so instead of emitting 'exit' immediately, we store off the exit code
    // and emit it once 'close' is called.
    let exitCode: number | null = null;
    let closeTimeoutId: NodeJS.Timeout | null = null;
    let hasEmittedExit = false;

    const emitExitAndClose = async (waitForOutputPumps: boolean) => {
      if (hasEmittedExit) return;
      hasEmittedExit = true;

      if (closeTimeoutId) {
        clearTimeout(closeTimeoutId);
        closeTimeoutId = null;
      }

      reportEvent(span.ctx, "exit");

      if (waitForOutputPumps) {
        try {
          await outputPump.waitForOutput();
        } catch (error) {
          await cleanupStateFiles();
          iterable.throw(
            error instanceof Error ? error : new Error(String(error))
          );
          return;
        }
      }
      await outputPump.flush();

      if (!options?.signal?.aborted) {
        await readStateFromTransport();

        // Only update state if dump_bash_state completed successfully.
        // We require BOTH the start marker (at the beginning) and end marker (at the end).
        // If the bash process was killed (e.g., by pkill -f matching the command line),
        // dump_bash_state won't run or may be killed mid-dump, and we won't have both markers.
        const startMarkerLine = `${BASH_STATE_START_MARKER}\n`;
        const endMarkerLine = `${BASH_STATE_END_MARKER}\n`;
        if (
          newState.startsWith(startMarkerLine) &&
          newState.endsWith(endMarkerLine)
        ) {
          // Strip start marker from beginning and end marker from end
          let stateWithoutMarkers = newState.slice(startMarkerLine.length);
          stateWithoutMarkers = stateWithoutMarkers.slice(
            0,
            -(BASH_STATE_END_MARKER.length + 1)
          );
          const { cwd: nextCwd, rest } = splitPwdAndState(stateWithoutMarkers);
          // On Windows, Git Bash returns Unix-style paths which don't work with Node.js spawn,
          // so we skip updating CWD on Windows
          this.state = rest;
          if (process.platform !== "win32" && nextCwd?.startsWith("/")) {
            this.cwd = nextCwd;
          }
        }
        // If both markers are not present, keep the previous valid state
      }

      // Attempt to capture sandbox deny events (best-effort)
      if (sandboxPolicy.captureDenies) {
        try {
          const denyEvents = await captureSandboxDenies(child);
          if (denyEvents && denyEvents.length > 0) {
            await iterable.write({
              type: "sandbox_denies",
              events: denyEvents,
            });
          }
        } catch {}
      }

      try {
        await iterable.write({
          type: "exit",
          code: exitCode,
          data: "",
          aborted: options?.signal?.aborted ?? false,
        });
        iterable.close();
      } catch {
        // Iterable might be closed, ignore write errors
        iterable.close();
      }

      await cleanupStateFiles();
    };

    child.on("exit", (code, _signal) => {
      exitCode = code;

      // Start timeout to prevent hanging if 'close' never fires
      const timeout = options?.closeTimeout ?? 5000;
      if (timeout > 0) {
        closeTimeoutId = setTimeout(() => {
          console.warn(
            `[shell-exec] Close event did not fire within ${timeout}ms after exit. ` +
              `This may indicate a background process is holding file descriptors open. ` +
              `Proceeding anyway to prevent hang.`
          );
          emitExitAndClose(false);
        }, timeout);
      }
    });

    child.on("close", async () => {
      await emitExitAndClose(true);
    });

    const inFd = child.stdio[3] as Stream.Writable | null;
    const outFd = child.stdio[4] as Stream.Readable | null;

    if (!useFileTransport) {
      writeShellStatePipe(inFd, this.state);
      attachShellStateOutput(outFd, text => {
        newState += text;
      });
    }

    yield* iterable;
  }
}

export async function initBashState(
  options?: TerminalInitializationOptions
): Promise<BashState> {
  const env = {
    ...process.env,
    ...SHELL_ENV_OVERRIDES,
    ...options?.env,
  };

  const STATE_MARKER = "__CURSOR_STATE_MARKER__";
  const args = [
    "-O",
    "extglob",
    "-ilc",
    dumpBashState +
      " " +
      `builtin printf '${STATE_MARKER}\\n'; dump_bash_state`,
  ];

  const bashPath = getBashPath(options?.userTerminalHint);
  if (!bashPath) {
    throw new Error("Can't find Bash");
  }

  const child = spawnWithSignal(
    bashPath,
    args,
    {
      env,
      detached: true,
      // Use 'ignore' for stdin so it's connected to /dev/null from the start
      // This prevents background processes (like ssh-agent) started during
      // initialization from inheriting an open stdin pipe
      stdio: ["ignore", "pipe", "pipe"],
    } as SpawnOptionsWithoutStdio,
    { type: "insecure_none" },
    options?.signal
  );

  let fullOutput = "";
  child.stdout?.on("data", data => {
    fullOutput += data.toString();
  });

  // A failed spawn (e.g. missing binary, or the inherited cwd was deleted)
  // emits 'error' before 'close'. Without a listener, that unhandled 'error'
  // event crashes the whole host process. Log and fall through to the
  // missing-markers fallback below ('close' always follows a spawn 'error').
  child.on("error", error => {
    console.warn(
      `[shell-exec] bash state init spawn failed; falling back to empty state: ${
        error instanceof Error ? error.message : String(error)
      }`
    );
  });

  await new Promise(resolve => {
    child.on("close", () => {
      resolve(undefined);
    });
  });

  const snapshot = parseShellStateOutput(fullOutput, STATE_MARKER);

  // Require BOTH the start marker (at the beginning) and end marker (at the end)
  // to confirm dump_bash_state completed successfully.
  const startMarkerLine = `${BASH_STATE_START_MARKER}\n`;
  const endMarkerLine = `${BASH_STATE_END_MARKER}\n`;
  let stateWithoutMarkers: string;
  if (
    snapshot.startsWith(startMarkerLine) &&
    snapshot.endsWith(endMarkerLine)
  ) {
    // Strip start marker from beginning and end marker from end
    stateWithoutMarkers = snapshot.slice(startMarkerLine.length);
    stateWithoutMarkers = stateWithoutMarkers.slice(
      0,
      -(BASH_STATE_END_MARKER.length + 1)
    );
  } else {
    // Dump failed or was killed mid-run (missing one or both markers).
    // Use process.cwd() and empty state rather than potentially corrupted data.
    stateWithoutMarkers = `${process.cwd()}\n`;
  }
  const { cwd, rest } = splitPwdAndState(stateWithoutMarkers);

  const useFileStateTransport = process.platform === "win32";
  // On Windows, Git Bash returns Unix-style paths which don't work with Node.js spawn,
  // so we use process.cwd() instead
  const initialCwd = process.platform === "win32" ? process.cwd() : cwd;
  return new BashState(
    initialCwd,
    rest,
    options?.userTerminalHint,
    useFileStateTransport
  );
}

export { BashState };
