/**
 * Represents a running background shell process
 */
export interface BackgroundShell {
  readonly id: number;
  readonly signal: AbortSignal;
  stdin: Writable | undefined;
  pid: number | undefined;
  abort(): void;
  dispose(): void;
  isDisposed(): boolean;
  onComplete?(listener: (completion: BackgroundShellCompletion) => void): void;
}

export interface BackgroundShellCompletion {
  code: number | null;
  aborted: boolean;
  outputPath?: string;
}

/**
 * Core implementation of BackgroundShell
 */
class CoreBackgroundShell implements BackgroundShell {
  private disposed: boolean = false;
  private completed: boolean = false;
  private completionListeners: Array<
    (completion: BackgroundShellCompletion) => void
  > = [];
  private completion?: BackgroundShellCompletion;
  stdin: Writable | undefined;
  pid: number | undefined;

  constructor(
    public readonly id: number,
    private readonly abortController: AbortController
  ) {}

  /**
   * Abort this background shell (stops execution)
   */
  abort(): void {
    this.abortController.abort();
  }

  /**
   * Dispose this background shell (cleanup resources)
   * This will also abort the shell if it's still running
   */
  dispose(): void {
    if (this.disposed) {
      return;
    }
    this.disposed = true;

    // Abort if still running
    if (!this.abortController.signal.aborted) {
      this.abortController.abort();
    }
  }

  /**
   * Get the abort signal for this shell
   */
  get signal(): AbortSignal {
    return this.abortController.signal;
  }

  /**
   * Check if this shell has been disposed
   */
  isDisposed(): boolean {
    return this.disposed;
  }

  onComplete(listener: (completion: BackgroundShellCompletion) => void): void {
    if (this.completed && this.completion) {
      listener(this.completion);
      return;
    }
    this.completionListeners.push(listener);
  }

  markCompleted(completion: BackgroundShellCompletion): void {
    if (this.completed) {
      return;
    }
    this.completed = true;
    this.completion = completion;
    const listeners = [...this.completionListeners];
    this.completionListeners = [];
    for (const listener of listeners) {
      listener(completion);
    }
  }
}

export interface ShellExecutionContext {
  ctx: Context;
  command: string;
  workingDirectory: string;
  toolCallId: string | undefined;
  conversationId?: string;
  sandboxPolicy: SandboxPolicyMergeSources | undefined;
  shellId: number;
  enableWriteShellStdinTool?: boolean;
  description?: string;
  outputNotification?: ShellOutputNotificationConfig;
}

/**
 * State for adopting an existing shell execution into the background system
 */
export interface ShellAdoptionState {
  /**
   * The original Context for the shell execution (if available).
   * Used to extract conversationId for UI association when a foreground shell is adopted
   * into the background system.
   */
  ctx?: Context;
  shellId: number;
  command: string;
  workingDirectory: string;
  toolCallId?: string;
  sandboxPolicy?: SandboxPolicyMergeSources;
  /** Output collected so far (for logging purposes) */
  initialOutput: string;
  /** The stdin writable, if available */
  stdin?: Writable;
  description?: string;
  /** The process ID of the shell */
  pid?: number;
  /** AbortController to allow aborting the adopted shell */
  abortController: AbortController;
  /** The async iterator to continue consuming events from */
  eventIterator: AsyncIterator<ShellCoreEvent>;
  /** The original start time of the command (for elapsed time tracking) */
  startTime: number;
  /** When true, include elapsed time in terminal output on exit (feature flag gated) */
  showElapsedTime?: boolean;
  outputNotification?: ShellOutputNotificationConfig;
}

/**
 * Factory interface for creating background shells
 */
export interface BackgroundShellFactory {
  spawn(
    executionContext: ShellExecutionContext,
    coreExecutor: ShellCoreExecutor
  ): Promise<BackgroundShell>;

  /**
   * Adopt an existing shell execution into the background system.
   * This is used when a foreground shell times out with TIMEOUT_BEHAVIOR_BACKGROUND.
   */
  adopt(state: ShellAdoptionState): Promise<BackgroundShell>;
}

/**
 * Consumes events from an async iterator, updating the shell's stdin and pid
 * when stdin_ready events are received. Runs until the iterator is exhausted.
 * Errors are silently swallowed (middleware handles logging).
 */
async function consumeShellEvents(
  shell: CoreBackgroundShell,
  eventIterator: AsyncIterator<ShellCoreEvent>
): Promise<void> {
  let completion: BackgroundShellCompletion | undefined;
  try {
    for (
      let result = await eventIterator.next();
      !result.done;
      result = await eventIterator.next()
    ) {
      if (result.value.type === "stdin_ready") {
        shell.stdin = result.value.stdin;
        shell.pid = result.value.pid;
      } else if (result.value.type === "exit") {
        completion = {
          code: result.value.code,
          aborted: result.value.aborted,
          outputPath: result.value.outputLocation?.filePath,
        };
      }
    }
  } catch (_error: unknown) {
    // Errors silently swallowed - middleware handles logging
  } finally {
    // Mark lifecycle complete on natural exit and error paths.
    shell.markCompleted(
      completion ?? {
        code: null,
        aborted: shell.signal.aborted,
      }
    );
  }
}

/**
 * Runs an async function in the background, suppressing unhandled rejections.
 */
function runInBackground(fn: () => Promise<void>): void {
  fn().catch(() => {});
}

const MIN_SHELL_ID = 1000;
const MAX_SHELL_ID = 999999;
const OUTPUT_NOTIFICATION_LIMIT = 100;

/**
 * Pick a random starting point in [MIN_SHELL_ID, MAX_SHELL_ID] for the
 * per-process shell-id counter. Within a process ids stay monotonic (so a
 * completion can never collide with a live shell — the wakeup-queue invariant),
 * but seeding the counter randomly per process keeps cross-process terminal-file
 * name collisions (`<projectDir>/terminals/<id>.txt` is shared per project) as
 * unlikely as the old fully-random scheme instead of having every process start
 * at MIN_SHELL_ID. Not security-sensitive, so `Math.random` is fine.
 */
function randomInitialShellId(): number {
  return (
    MIN_SHELL_ID + Math.floor(Math.random() * (MAX_SHELL_ID - MIN_SHELL_ID + 1))
  );
}
const OUTPUT_NOTIFICATION_MIN_DEBOUNCE_MS = 5_000;
const OUTPUT_NOTIFICATION_DEBOUNCE_MS = OUTPUT_NOTIFICATION_MIN_DEBOUNCE_MS;
const OUTPUT_NOTIFICATION_CARRYOVER_CHARS = 1_024;
const MAX_NOTIFICATION_TEXT_CHARS = 500;
const MAX_OUTPUT_NOTIFICATION_MATCHED_TEXT_CHARS = 5_000;
const MAX_OUTPUT_NOTIFICATION_PATTERN_CHARS = 500;
const MAX_OUTPUT_NOTIFICATION_SCAN_CHARS = 64 * 1024;

function getConfiguredOutputNotificationDebounceMs(
  config: ShellOutputNotificationConfig
): number | undefined {
  const debounceSeconds = config.debounce;
  if (debounceSeconds === undefined || !Number.isFinite(debounceSeconds)) {
    return undefined;
  }
  return Math.ceil(debounceSeconds * 1000);
}

function truncateNotificationText(value: string): string {
  if (value.length <= MAX_NOTIFICATION_TEXT_CHARS) {
    return value;
  }
  return `${value.slice(0, MAX_NOTIFICATION_TEXT_CHARS)}...`;
}

function formatMatchedTextDetail(
  matchedText: string,
  label: "Matched text" | "Latest match"
): string {
  if (matchedText.length <= MAX_OUTPUT_NOTIFICATION_MATCHED_TEXT_CHARS) {
    return `${label}: ${matchedText}`;
  }
  return `${label} is ${matchedText.length} characters; omitted from notification detail.`;
}

class ShellOutputNotificationObserver {
  private readonly regex: ReturnType<typeof RE2JS.compile>;
  private readonly limit: number;
  private carryover = "";
  private matchedOccurrences = 0;
  private emittedNotifications = 0;
  private pendingBatch:
    | {
        startOccurrence: number;
        endOccurrence: number;
        count: number;
        matchedTextDetail?: string;
      }
    | undefined;
  private flushTimer: ReturnType<typeof setTimeout> | undefined;
  private finished = false;

  constructor(
    private readonly args: {
      shellId: number;
      outputPath: string;
      config: ShellOutputNotificationConfig;
      conversationId: string;
      toolCallId?: string;
      registry: BackgroundWorkRegistry;
      debounceMs?: number;
    }
  ) {
    this.limit = args.config.notificationLimit ?? OUTPUT_NOTIFICATION_LIMIT;
    if (args.config.pattern.length > MAX_OUTPUT_NOTIFICATION_PATTERN_CHARS) {
      throw new Error(
        `Output notification pattern exceeds ${MAX_OUTPUT_NOTIFICATION_PATTERN_CHARS} characters`
      );
    }
    // RE2 guarantees linear-time matching for untrusted patterns. MULTILINE
    // preserves log-style ^/$ behavior from the previous /gm RegExp.
    this.regex = RE2JS.compile(args.config.pattern, RE2JS.MULTILINE);
  }

  observe(data: string): void {
    if (
      this.finished ||
      this.matchedOccurrences >= this.limit ||
      data.length === 0
    ) {
      return;
    }
    if (data.length > MAX_OUTPUT_NOTIFICATION_SCAN_CHARS) {
      for (
        let offset = 0;
        offset < data.length && this.matchedOccurrences < this.limit;
        offset += MAX_OUTPUT_NOTIFICATION_SCAN_CHARS
      ) {
        this.observe(
          data.slice(offset, offset + MAX_OUTPUT_NOTIFICATION_SCAN_CHARS)
        );
      }
      return;
    }

    const previousLength = this.carryover.length;
    const searchable = `${this.carryover}${data}`;
    const matcher = this.regex.matcher(searchable);
    while (this.matchedOccurrences < this.limit && matcher.find()) {
      const matchedText = matcher.group() ?? "";
      const matchEnd = matcher.end();
      if (matchEnd > previousLength) {
        this.queueMatch(matchedText);
      }
    }

    this.carryover = searchable.slice(-OUTPUT_NOTIFICATION_CARRYOVER_CHARS);
  }

  finish(): void {
    if (this.finished) {
      return;
    }
    this.finished = true;
    this.flushPendingBatch("finish");
    this.clearFlushTimer();
  }

  private queueMatch(matchedText: string): void {
    if (this.matchedOccurrences >= this.limit) {
      return;
    }

    this.matchedOccurrences += 1;
    const occurrence = this.matchedOccurrences;
    const matchedTextDetail = formatMatchedTextDetail(
      matchedText,
      occurrence === 1 ? "Matched text" : "Latest match"
    );

    if (occurrence === 1) {
      this.emitNotification({
        startOccurrence: occurrence,
        endOccurrence: occurrence,
        count: 1,
        matchedTextDetail,
      });
      if (occurrence === this.limit) {
        this.emitLimitReachedNotification();
      }
      return;
    }

    if (!this.pendingBatch) {
      this.pendingBatch = {
        startOccurrence: occurrence,
        endOccurrence: occurrence,
        count: 1,
        matchedTextDetail,
      };
    } else {
      this.pendingBatch.endOccurrence = occurrence;
      this.pendingBatch.count += 1;
      this.pendingBatch.matchedTextDetail = matchedTextDetail;
    }

    if (occurrence === this.limit) {
      this.flushPendingBatch("limit");
      this.emitLimitReachedNotification();
      return;
    }

    this.scheduleFlush();
  }

  private scheduleFlush(): void {
    if (this.flushTimer !== undefined) {
      return;
    }
    const debounceMs = this.getDebounceMs();
    this.flushTimer = setTimeout(() => {
      this.flushPendingBatch("debounce");
    }, debounceMs);
  }

  private getDebounceMs(): number {
    const debounceMs =
      this.args.debounceMs ??
      getConfiguredOutputNotificationDebounceMs(this.args.config) ??
      OUTPUT_NOTIFICATION_DEBOUNCE_MS;
    return Math.max(debounceMs, OUTPUT_NOTIFICATION_MIN_DEBOUNCE_MS);
  }

  private clearFlushTimer(): void {
    if (this.flushTimer !== undefined) {
      clearTimeout(this.flushTimer);
      this.flushTimer = undefined;
    }
  }

  private flushPendingBatch(_reason: "debounce" | "finish" | "limit"): void {
    const batch = this.pendingBatch;
    if (!batch) {
      return;
    }

    this.pendingBatch = undefined;
    this.clearFlushTimer();
    this.emitNotification(batch);
  }

  private emitNotification(batch: {
    startOccurrence: number;
    endOccurrence: number;
    count: number;
    matchedTextDetail?: string;
  }): void {
    this.emittedNotifications += 1;
    const title =
      this.args.config.reason.trim() ||
      `Shell output contains /${this.args.config.pattern}/`;
    const pattern = this.args.config.pattern;
    const matchedTextSentence =
      batch.matchedTextDetail !== undefined
        ? ` ${batch.matchedTextDetail}.`
        : "";
    const detail =
      batch.count === 1
        ? `Shell output has pattern /${pattern}/. This is occurrence number ${batch.startOccurrence}.${matchedTextSentence} The title message is being displayed to the user.`
        : `Shell output matched /${pattern}/ ${batch.count} more times since the previous notification. The title message is being displayed to the user.${matchedTextSentence}`;
    const taskId = `${this.args.shellId}:task_progress:${this.emittedNotifications}`;
    this.args.registry.enqueue({
      conversationId: this.args.conversationId,
      id: taskId,
      source: "shell",
      payload: {
        taskId,
        ...(this.args.toolCallId !== undefined
          ? { toolCallId: this.args.toolCallId }
          : {}),
        kind: "shell",
        status: "success",
        title: truncateNotificationText(title),
        detail,
        outputPath: this.args.outputPath,
        reason: "task_progress",
      },
    });
  }

  private emitLimitReachedNotification(): void {
    this.emittedNotifications += 1;
    const pattern = this.args.config.pattern;
    const taskId = `${this.args.shellId}:task_progress:${this.emittedNotifications}`;
    this.args.registry.enqueue({
      conversationId: this.args.conversationId,
      id: taskId,
      source: "shell",
      payload: {
        taskId,
        ...(this.args.toolCallId !== undefined
          ? { toolCallId: this.args.toolCallId }
          : {}),
        kind: "shell",
        status: "success",
        title: `Notification limit reached (${this.limit})`,
        detail: `Shell output matched /${pattern}/ ${this.limit} times and has reached the notification limit. No further notifications will be sent for this pattern. To continue monitoring, read the output file directly at the output path.`,
        outputPath: this.args.outputPath,
        reason: "task_progress",
      },
    });
  }
}

class NotifyingBackgroundShellFactory implements BackgroundShellFactory {
  constructor(
    private readonly innerFactory: BackgroundShellFactory,
    private readonly projectDir: string,
    private readonly backgroundWorkRegistry?: BackgroundWorkRegistry
  ) {}

  async spawn(
    executionContext: ShellExecutionContext,
    coreExecutor: ShellCoreExecutor
  ): Promise<BackgroundShell> {
    const observer = this.createObserver(
      executionContext.ctx,
      executionContext.shellId,
      executionContext.conversationId,
      executionContext.toolCallId,
      executionContext.outputNotification
    );
    if (!observer) {
      return this.innerFactory.spawn(executionContext, coreExecutor);
    }

    try {
      return await this.innerFactory.spawn(
        executionContext,
        this.createObservingExecutor(coreExecutor, observer)
      );
    } catch (error) {
      observer.finish();
      throw error;
    }
  }

  async adopt(state: ShellAdoptionState): Promise<BackgroundShell> {
    const observer = this.createObserver(
      state.ctx,
      state.shellId,
      undefined,
      state.toolCallId,
      state.outputNotification
    );
    if (!observer) {
      return this.innerFactory.adopt(state);
    }

    if (state.initialOutput.length > 0) {
      observer.observe(state.initialOutput);
    }

    try {
      return await this.innerFactory.adopt({
        ...state,
        eventIterator: this.createObservingIterator(
          state.eventIterator,
          observer
        ),
      });
    } catch (error) {
      observer.finish();
      throw error;
    }
  }

  private createObserver(
    ctx: Context | undefined,
    shellId: number,
    conversationId: string | undefined,
    toolCallId: string | undefined,
    config: ShellOutputNotificationConfig | undefined
  ): ShellOutputNotificationObserver | undefined {
    if (!this.backgroundWorkRegistry || !config) {
      return undefined;
    }
    if (config.pattern.trim().length === 0) {
      return undefined;
    }

    const outputPath = path.join(
      this.projectDir,
      "terminals",
      `${shellId}.txt`
    );
    try {
      return new ShellOutputNotificationObserver({
        shellId,
        outputPath,
        config,
        conversationId: conversationId ?? LEGACY_LOCAL_WAKEUP_CONVERSATION_ID,
        toolCallId,
        registry: this.backgroundWorkRegistry,
      });
    } catch (error) {
      if (ctx !== undefined) {
        logger.warn(ctx, "Invalid shell output notification pattern", {
          shellId,
          error: error instanceof Error ? error.message : String(error),
        });
      }
      return undefined;
    }
  }

  private createObservingExecutor(
    coreExecutor: ShellCoreExecutor,
    observer: ShellOutputNotificationObserver
  ): ShellCoreExecutor {
    const originalExecute = coreExecutor.execute.bind(coreExecutor);
    return {
      ...coreExecutor,
      execute: async function* (ctx: Context, args: ShellCoreArgs) {
        try {
          for await (const event of originalExecute(ctx, args)) {
            if (event.type === "stdout" || event.type === "stderr") {
              observer.observe(event.data);
            } else if (event.type === "exit") {
              observer.finish();
            }
            yield event;
          }
        } finally {
          observer.finish();
        }
      },
    };
  }

  private createObservingIterator(
    iterator: AsyncIterator<ShellCoreEvent>,
    observer: ShellOutputNotificationObserver
  ): AsyncIterator<ShellCoreEvent> {
    const returnIterator = iterator.return?.bind(iterator);
    return {
      next: async () => {
        try {
          const result = await iterator.next();
          if (!result.done) {
            const event = result.value;
            if (event.type === "stdout" || event.type === "stderr") {
              observer.observe(event.data);
            } else if (event.type === "exit") {
              observer.finish();
            }
          } else {
            observer.finish();
          }
          return result;
        } catch (error) {
          observer.finish();
          throw error;
        }
      },
      return: async value => {
        observer.finish();
        return returnIterator
          ? returnIterator(value)
          : { done: true, value: undefined };
      },
    };
  }
}

/**
 * Core factory that creates background shells without any additional behavior
 */
export class CoreShellFactory implements BackgroundShellFactory {
  async spawn(
    executionContext: ShellExecutionContext,
    coreExecutor: ShellCoreExecutor
  ): Promise<BackgroundShell> {
    const abortController = new AbortController();
    const shell = new CoreBackgroundShell(
      executionContext.shellId,
      abortController
    );

    const eventIterator = coreExecutor
      .execute(executionContext.ctx, {
        command: executionContext.command,
        workingDirectory: executionContext.workingDirectory,
        signal: abortController.signal,
        toolCallId: executionContext.toolCallId,
        conversationId: executionContext.conversationId,
        sandboxPolicy: executionContext.sandboxPolicy,
        pipeStdin: executionContext.enableWriteShellStdinTool,
        showElapsedTime: true,
      })
      [Symbol.asyncIterator]();

    // Synchronously wait for stdin_ready to capture PID before returning.
    // This ensures spawn() returns with PID available. Remaining events
    // are consumed in the background.
    try {
      for (
        let result = await eventIterator.next();
        !result.done;
        result = await eventIterator.next()
      ) {
        if (result.value.type === "stdin_ready") {
          shell.stdin = result.value.stdin;
          shell.pid = result.value.pid;
          break;
        }
      }
    } catch (error: unknown) {
      // The command never ran: the host cannot enforce the required sandbox
      // policy. Swallowing this would report a successful spawn (just without a
      // PID) for a process that does not exist.
      if (error instanceof SandboxUnsupportedError) {
        throw error;
      }
      // Otherwise continue without PID if an error occurs before stdin_ready.
    }

    runInBackground(() => consumeShellEvents(shell, eventIterator));

    return shell;
  }

  async adopt(state: ShellAdoptionState): Promise<BackgroundShell> {
    const shell = new CoreBackgroundShell(state.shellId, state.abortController);
    shell.stdin = state.stdin;
    shell.pid = state.pid;

    runInBackground(() => consumeShellEvents(shell, state.eventIterator));

    return shell;
  }
}

// Interval for updating running_for_ms (5 seconds)
const RUNNING_TIME_UPDATE_INTERVAL_MS = 5000;

// Width for padding running_for_ms (supports up to 999999999 ms = ~11.5 days)
const RUNNING_MS_WIDTH = 9;

type TerminalTaskStatus = "running" | "succeeded" | "failed" | "aborted";

// All terminal task statuses fit in nine characters. Keeping this field
// fixed-width preserves the in-place frontmatter update invariant.
const TERMINAL_TASK_STATUS_WIDTH = 9;

/**
 * Escapes a string for safe inclusion in YAML as a double-quoted value.
 * Handles special characters like newlines, tabs, backslashes, and double quotes.
 */
function escapeYamlString(value: string): string {
  // Use double-quoted YAML string with proper escaping
  const escaped = value
    .replace(/\\/g, "\\\\") // Backslash must be escaped first
    .replace(/"/g, '\\"') // Escape double quotes
    .replace(/\n/g, "\\n") // Escape newlines
    .replace(/\r/g, "\\r") // Escape carriage returns
    .replace(/\t/g, "\\t"); // Escape tabs
  return `"${escaped}"`;
}

/**
 * Build YAML frontmatter with fixed-width running_for_ms for safe in-place updates
 */
function buildFrontmatter(params: {
  pid?: number;
  cwd: string;
  command: string;
  title?: string;
  status: TerminalTaskStatus;
  startedAt: string;
  runningForMs: number;
}): string {
  const paddedMs = String(params.runningForMs).padEnd(RUNNING_MS_WIDTH, " ");
  const paddedStatus = params.status.padEnd(TERMINAL_TASK_STATUS_WIDTH, " ");

  let content = "---\n";
  if (params.pid !== undefined && params.pid !== 0) {
    content += `pid: ${params.pid}\n`;
  }
  content += `cwd: ${escapeYamlString(params.cwd)}\n`;
  content += `command: ${escapeYamlString(params.command)}\n`;
  if (params.title !== undefined && params.title.trim().length > 0) {
    content += `title: ${escapeYamlString(params.title)}\n`;
  }
  content += `status: ${paddedStatus}\n`;
  content += `started_at: ${params.startedAt}\n`;
  content += `running_for_ms: ${paddedMs}\n`;
  content += "---\n";

  return content;
}

/**
 * Middleware that writes shell output to a file
 */
export class FileLoggingShellFactory implements BackgroundShellFactory {
  constructor(
    private readonly innerFactory: BackgroundShellFactory,
    private readonly projectDir: string
  ) {}

  async spawn(
    executionContext: ShellExecutionContext,
    coreExecutor: ShellCoreExecutor
  ): Promise<BackgroundShell> {
    // Ensure the terminals directory exists
    const terminalsDir = path.join(this.projectDir, "terminals");
    await mkdir(terminalsDir, { recursive: true });

    // Create a custom core executor that intercepts events for logging
    const loggingExecutor = this.createLoggingExecutor(
      coreExecutor,
      executionContext,
      terminalsDir
    );

    // Spawn the shell with the logging executor
    return this.innerFactory.spawn(executionContext, loggingExecutor);
  }

  private createLoggingExecutor(
    coreExecutor: ShellCoreExecutor,
    executionContext: ShellExecutionContext,
    terminalsDir: string
  ): ShellCoreExecutor {
    const originalExecute = coreExecutor.execute.bind(coreExecutor);

    return {
      ...coreExecutor,
      execute: async function* (ctx: Context, args: ShellCoreArgs) {
        let frontmatterHandle: fs.promises.FileHandle | undefined;
        let appendHandle: fs.promises.FileHandle | undefined;
        let stdinPatched: boolean = false;
        let headerWritten: boolean = false;
        let updateInterval: ReturnType<typeof setInterval> | undefined;
        const startTime = Date.now();
        const startedAt = new Date(startTime).toISOString();
        let currentPid: number | undefined;
        let taskStatus: TerminalTaskStatus = "running";
        let terminalFinalized = false;
        let pendingFrontmatterUpdate = Promise.resolve();

        // Safe write that appends output (uses append mode for atomic writes)
        const safeWrite = async (data: string): Promise<void> => {
          if (!appendHandle) {
            return;
          }
          try {
            await appendHandle.write(data);
          } catch (_error: unknown) {}
        };

        // Use the shell ID from the execution context
        const shellId = executionContext.shellId;
        const terminalPath = path.join(terminalsDir, `${shellId}.txt`);

        // Helper to update the frontmatter with current running time
        const updateFrontmatter = async (): Promise<void> => {
          if (!frontmatterHandle) {
            return;
          }
          const runningForMs = Date.now() - startTime;
          const frontmatter = buildFrontmatter({
            pid: currentPid,
            cwd: executionContext.workingDirectory,
            command: executionContext.command,
            title: executionContext.description,
            status: taskStatus,
            startedAt,
            runningForMs,
          });
          try {
            // Write at position 0 for in-place frontmatter update
            await frontmatterHandle.write(frontmatter, 0, "utf8");
          } catch (_error: unknown) {
            // Ignore write errors
          }
        };

        const queueFrontmatterUpdate = (): Promise<void> => {
          pendingFrontmatterUpdate = pendingFrontmatterUpdate
            .then(updateFrontmatter)
            .catch(() => {});
          return pendingFrontmatterUpdate;
        };

        // Helper to clear the update interval
        const clearUpdateInterval = (): void => {
          if (updateInterval !== undefined) {
            clearInterval(updateInterval);
            updateInterval = undefined;
          }
        };

        // Helper to write the header with optional PID
        const writeHeader = async (pid?: number): Promise<void> => {
          if (headerWritten) {
            return;
          }
          headerWritten = true;
          currentPid = pid;

          const runningForMs = Date.now() - startTime;
          const frontmatter = buildFrontmatter({
            pid,
            cwd: executionContext.workingDirectory,
            command: executionContext.command,
            title: executionContext.description,
            status: taskStatus,
            startedAt,
            runningForMs,
          });

          await writeFile(terminalPath, frontmatter, "utf8");

          // Start the interval to update running_for_ms
          updateInterval = setInterval(() => {
            void queueFrontmatterUpdate();
          }, RUNNING_TIME_UPDATE_INTERVAL_MS);
        };

        // Helper to open file handles if not already open
        const ensureHandlesOpen = async (): Promise<void> => {
          if (!frontmatterHandle) {
            frontmatterHandle = await fs.promises.open(terminalPath, "r+");
          }
          if (!appendHandle) {
            appendHandle = await fs.promises.open(terminalPath, "a");
          }
        };

        const finalizeTerminal = async (
          status: Exclude<TerminalTaskStatus, "running">,
          firstFooterLine?: string
        ): Promise<void> => {
          if (terminalFinalized) {
            return;
          }
          terminalFinalized = true;
          clearUpdateInterval();
          if (!headerWritten) {
            await writeHeader();
          }
          await ensureHandlesOpen();
          if (firstFooterLine !== undefined) {
            const elapsedMs = Date.now() - startTime;
            const footer =
              `\n---\n${firstFooterLine}\n` +
              (args.showElapsedTime ? `elapsed_ms: ${elapsedMs}\n` : "") +
              `ended_at: ${new Date().toISOString()}\n---\n`;
            await safeWrite(footer);
          }

          // When a footer exists, write it before the authoritative status
          // transition so pollers never observe a partial terminal record.
          taskStatus = status;
          await queueFrontmatterUpdate();
        };

        try {
          for await (const event of originalExecute(ctx, args)) {
            if (event.type === "stdout") {
              if (!headerWritten) {
                await writeHeader();
                await ensureHandlesOpen();
              }
              await safeWrite(event.data);
            } else if (event.type === "stderr") {
              if (!headerWritten) {
                await writeHeader();
                await ensureHandlesOpen();
              }
              await safeWrite(event.data);
            } else if (event.type === "stdin_ready" && !stdinPatched) {
              stdinPatched = true;
              if (!headerWritten) {
                await writeHeader(event.pid);
                await ensureHandlesOpen();
              }
              const stdin = event.stdin;

              if (stdin) {
                const logInputChunk = (chunk: unknown): void => {
                  if (chunk === undefined || chunk === null) {
                    return;
                  }
                  const chunkStr =
                    typeof chunk === "string"
                      ? chunk
                      : Buffer.isBuffer(chunk)
                        ? chunk.toString()
                        : String(chunk);
                  if (!chunkStr) {
                    return;
                  }
                  const normalizedChunk = chunkStr.endsWith("\n")
                    ? chunkStr
                    : `${chunkStr}\n`;
                  void safeWrite(`[stdin] ${normalizedChunk}`);
                };

                const originalWrite = stdin.write.bind(stdin);
                stdin.write = ((
                  chunk: unknown,
                  encoding?: unknown,
                  callback?: unknown
                ): boolean => {
                  logInputChunk(chunk);
                  return originalWrite(
                    chunk as Parameters<typeof stdin.write>[0],
                    encoding as Parameters<typeof stdin.write>[1],
                    callback as Parameters<typeof stdin.write>[2]
                  );
                }) as typeof stdin.write;

                if (typeof stdin.end === "function") {
                  const originalEnd = stdin.end.bind(stdin);
                  stdin.end = ((
                    chunk?: unknown,
                    encoding?: unknown,
                    callback?: unknown
                  ): ReturnType<typeof stdin.end> => {
                    if (chunk !== undefined) {
                      logInputChunk(chunk);
                    }
                    return originalEnd(
                      chunk as Parameters<typeof stdin.end>[0],
                      encoding as Parameters<typeof stdin.end>[1],
                      callback as Parameters<typeof stdin.end>[2]
                    );
                  }) as typeof stdin.end;
                }
              }
            } else if (event.type === "exit") {
              await finalizeTerminal(
                event.aborted
                  ? "aborted"
                  : event.code === 0
                    ? "succeeded"
                    : "failed",
                `exit_code: ${event.code ?? "unknown"}`
              );
            }

            // Yield the event to the next handler
            yield event;
          }
          if (!terminalFinalized) {
            const isAborted = args.signal?.aborted ?? false;
            await finalizeTerminal(isAborted ? "aborted" : "failed");
          }
        } catch (error: unknown) {
          const isAborted = args.signal?.aborted ?? false;
          const escapedError = escapeYamlString(
            error instanceof Error ? error.message : "Unknown error"
          );
          await finalizeTerminal(
            isAborted ? "aborted" : "failed",
            isAborted ? undefined : `error: ${escapedError}`
          );

          if (!isAborted) {
            throw error;
          }
        } finally {
          clearUpdateInterval();
          await pendingFrontmatterUpdate;
          // Close both file handles
          if (frontmatterHandle) {
            try {
              await frontmatterHandle.close();
            } catch {}
          }
          if (appendHandle) {
            try {
              await appendHandle.close();
            } catch {}
          }
        }
      },
    };
  }

  async adopt(state: ShellAdoptionState): Promise<BackgroundShell> {
    // Ensure the terminals directory exists
    const terminalsDir = path.join(this.projectDir, "terminals");
    await mkdir(terminalsDir, { recursive: true });

    const terminalPath = path.join(terminalsDir, `${state.shellId}.txt`);
    const startTime = state.startTime;
    const startedAt = new Date(startTime).toISOString();
    let taskStatus: TerminalTaskStatus = "running";

    // Create the terminal file with YAML frontmatter and initial output
    const runningForMs = Date.now() - startTime;
    const frontmatter = buildFrontmatter({
      pid: state.pid,
      cwd: state.workingDirectory,
      command: state.command,
      title: state.description,
      status: taskStatus,
      startedAt,
      runningForMs,
    });

    const initialContent = frontmatter + (state.initialOutput ?? "");
    await writeFile(terminalPath, initialContent, "utf8");

    const frontmatterHandle = await fs.promises.open(terminalPath, "r+");
    let appendHandle: fs.promises.FileHandle;
    try {
      appendHandle = await fs.promises.open(terminalPath, "a");
    } catch (error: unknown) {
      // Close frontmatterHandle to avoid file descriptor leak
      await frontmatterHandle.close();
      throw error;
    }

    // Track if cleanup has been performed
    let cleanedUp = false;
    let terminalFinalized = false;
    let pendingFrontmatterUpdate = Promise.resolve();

    const updateFrontmatter = async (): Promise<void> => {
      const currentRunningForMs = Date.now() - startTime;
      const updatedFrontmatter = buildFrontmatter({
        pid: state.pid,
        cwd: state.workingDirectory,
        command: state.command,
        title: state.description,
        status: taskStatus,
        startedAt,
        runningForMs: currentRunningForMs,
      });
      try {
        await frontmatterHandle.write(updatedFrontmatter, 0, "utf8");
      } catch {
        // Ignore write errors
      }
    };

    const queueFrontmatterUpdate = (): Promise<void> => {
      pendingFrontmatterUpdate = pendingFrontmatterUpdate
        .then(updateFrontmatter)
        .catch(() => {});
      return pendingFrontmatterUpdate;
    };

    // Start the interval to update running_for_ms
    let updateInterval: ReturnType<typeof setInterval> | undefined =
      setInterval(() => {
        void queueFrontmatterUpdate();
      }, RUNNING_TIME_UPDATE_INTERVAL_MS);

    const clearUpdateInterval = (): void => {
      if (updateInterval !== undefined) {
        clearInterval(updateInterval);
        updateInterval = undefined;
      }
    };

    // Cleanup function to close handles and clear interval
    const cleanup = async (): Promise<void> => {
      if (cleanedUp) {
        return;
      }
      cleanedUp = true;
      clearUpdateInterval();
      await pendingFrontmatterUpdate;
      try {
        await frontmatterHandle.close();
      } catch {}
      try {
        await appendHandle.close();
      } catch {}
    };

    const safeWrite = async (data: string): Promise<void> => {
      try {
        // Use append mode for atomic writes (no position tracking needed)
        await appendHandle.write(data);
      } catch (_error: unknown) {}
    };

    const finalizeTerminal = async (
      status: Exclude<TerminalTaskStatus, "running">,
      firstFooterLine?: string
    ): Promise<void> => {
      if (terminalFinalized) {
        return;
      }
      terminalFinalized = true;
      clearUpdateInterval();
      if (firstFooterLine !== undefined) {
        const elapsedMs = Date.now() - startTime;
        const footer =
          `\n---\n${firstFooterLine}\n` +
          (state.showElapsedTime ? `elapsed_ms: ${elapsedMs}\n` : "") +
          `ended_at: ${new Date().toISOString()}\n---\n`;
        await safeWrite(footer);
      }
      taskStatus = status;
      await queueFrontmatterUpdate();
    };

    const loggingIterator: AsyncIterator<ShellCoreEvent> = {
      next: async () => {
        try {
          const result = await state.eventIterator.next();
          if (!result.done) {
            const event = result.value;
            if (event.type === "stdout") {
              await safeWrite(event.data);
            } else if (event.type === "stderr") {
              await safeWrite(event.data);
            } else if (event.type === "exit") {
              await finalizeTerminal(
                event.aborted
                  ? "aborted"
                  : event.code === 0
                    ? "succeeded"
                    : "failed",
                `exit_code: ${event.code ?? "unknown"}`
              );
              await cleanup();
            }
          } else if (!terminalFinalized) {
            const isAborted = state.abortController.signal.aborted;
            await finalizeTerminal(isAborted ? "aborted" : "failed");
          }
          if (result.done) {
            await cleanup();
          }
          return result;
        } catch (error: unknown) {
          const isAborted = state.abortController.signal.aborted;
          await finalizeTerminal(isAborted ? "aborted" : "failed");
          await cleanup();
          throw error;
        }
      },
      // Handle early termination (iterator abandoned)
      return: async () => {
        if (!terminalFinalized) {
          const isAborted = state.abortController.signal.aborted;
          await finalizeTerminal(isAborted ? "aborted" : "failed");
        }
        await cleanup();
        // Forward to inner iterator's return if it exists
        if (state.eventIterator.return) {
          return state.eventIterator.return();
        }
        return { done: true, value: undefined };
      },
    };

    // Adopt using the inner factory with the logging wrapper
    return this.innerFactory.adopt({
      ...state,
      eventIterator: loggingIterator,
    });
  }
}

/**
 * Manages the lifecycle of background shells
 */
export class BackgroundShellManager {
  private runningShells: Map<number, BackgroundShell> = new Map();
  private nextShellId = randomInitialShellId();

  constructor(
    private readonly factory: BackgroundShellFactory,
    private readonly backgroundWorkRegistry?: BackgroundWorkRegistry | undefined
  ) {}

  private registerShellWork(
    shell: BackgroundShell,
    metadata: BackgroundWorkMetadata
  ): void {
    const shellId = String(shell.id);
    this.backgroundWorkRegistry?.upsertWork({
      id: shellId,
      kind: "shell",
      state: "running",
      metadata: encodeBackgroundWorkMetadata(metadata),
      abort: () => {
        this.abort(shell.id);
      },
    });
  }

  private clearShellWork(shellId: number): void {
    this.backgroundWorkRegistry?.clearWork(String(shellId));
  }

  private cleanupShell(shellId: number): void {
    if (!this.runningShells.has(shellId)) {
      return;
    }
    this.runningShells.delete(shellId);
    this.clearShellWork(shellId);
  }

  private enqueueShellCompletion(
    shellId: number,
    toolCallId: string | undefined,
    conversationId: string | undefined,
    commandTitle: string,
    completion: BackgroundShellCompletion
  ): void {
    if (!this.backgroundWorkRegistry) {
      return;
    }

    const status = completion.aborted
      ? "aborted"
      : completion.code === 0
        ? "success"
        : "error";
    const detail =
      !completion.aborted && completion.code !== null && completion.code !== 0
        ? `exit_code=${completion.code}`
        : undefined;

    const taskId = String(shellId);
    this.backgroundWorkRegistry.enqueue({
      conversationId: conversationId ?? LEGACY_LOCAL_WAKEUP_CONVERSATION_ID,
      id: taskId,
      source: "shell",
      payload: {
        taskId,
        ...(toolCallId !== undefined ? { toolCallId } : {}),
        kind: "shell",
        status,
        title: commandTitle,
        ...(detail ? { detail } : {}),
        ...(completion.outputPath ? { outputPath: completion.outputPath } : {}),
        reason: "task_finished",
      },
    });
  }

  /**
   * Spawn a background shell and return its ID and PID
   */
  async spawn(
    executionContext: ShellExecutionContext,
    coreExecutor: ShellCoreExecutor
  ): Promise<{ shellId: number; pid: number | undefined }> {
    const shell = await this.factory.spawn(executionContext, coreExecutor);
    this.runningShells.set(shell.id, shell);
    this.registerShellWork(shell, {
      title: executionContext.description || executionContext.command,
      cwd: executionContext.workingDirectory,
      startTimeMs: Date.now(),
    });

    // Clean up when shell completes (signal is aborted)
    shell.signal.addEventListener("abort", () => {
      this.cleanupShell(shell.id);
    });
    shell.onComplete?.(completion => {
      this.enqueueShellCompletion(
        shell.id,
        executionContext.toolCallId,
        executionContext.conversationId,
        executionContext.description || executionContext.command,
        completion
      );
      this.cleanupShell(shell.id);
    });

    return { shellId: shell.id, pid: shell.pid };
  }

  /**
   * Adopt an existing shell execution into the background system.
   * This is used when a foreground shell times out with TIMEOUT_BEHAVIOR_BACKGROUND.
   */
  async adopt(
    state: ShellAdoptionState
  ): Promise<{ shellId: number; pid: number | undefined }> {
    const shell = await this.factory.adopt(state);
    this.runningShells.set(shell.id, shell);
    this.registerShellWork(shell, {
      title: state.description || state.command,
      cwd: state.workingDirectory,
      startTimeMs: state.startTime,
    });

    // Clean up when shell completes (signal is aborted)
    shell.signal.addEventListener("abort", () => {
      this.cleanupShell(shell.id);
    });
    shell.onComplete?.(completion => {
      this.enqueueShellCompletion(
        shell.id,
        state.toolCallId,
        undefined,
        state.description || state.command,
        completion
      );
      this.cleanupShell(shell.id);
    });

    return { shellId: shell.id, pid: state.pid };
  }

  /**
   * Generate a unique shell ID.
   *
   * Monotonic per manager: the wakeup queue keys shell completions by this id,
   * so a fully-random id (the original implementation) could collide between two
   * live shells and silently drop or mis-route a completion. Counting instead
   * makes the id unique for the lifetime of this manager. Ids stay in
   * [MIN_SHELL_ID, MAX_SHELL_ID]; we skip ids still held by a running (or
   * adopted) shell and wrap when we reach the top of the range.
   *
   * The counter is seeded at a random offset per process (see
   * `randomInitialShellId`). This serves two ends: terminal transcripts live at
   * `<projectDir>/terminals/<id>.txt` (shared per project), and the renderer
   * wakeup queue / terminal provider are shared across every manager in a
   * process. The counter only guarantees uniqueness *within* one manager, so two
   * managers (concurrent exec sessions) — or two processes on the same project —
   * could in theory hand out the same id and mis-route a completion or terminal
   * file. Random seeding keeps that as unlikely as the old fully-random scheme;
   * we accept the residual risk rather than coordinating a process-global (or
   * cross-process) allocator, which isn't worth the complexity for odds this low.
   */
  generateShellId(): number {
    for (
      let attempts = 0;
      attempts <= MAX_SHELL_ID - MIN_SHELL_ID;
      attempts++
    ) {
      if (this.nextShellId > MAX_SHELL_ID) {
        this.nextShellId = MIN_SHELL_ID;
      }
      const candidate = this.nextShellId;
      this.nextShellId += 1;
      if (!this.runningShells.has(candidate)) {
        return candidate;
      }
    }
    throw new Error("No available background shell id in range");
  }

  /**
   * Abort a background shell by ID (stops execution but doesn't dispose)
   */
  abort(shellId: number): boolean {
    const shell = this.runningShells.get(shellId);
    if (shell) {
      shell.abort();
      this.runningShells.delete(shellId);
      this.clearShellWork(shellId);
      return true;
    }
    return false;
  }

  /**
   * Check if a shell is still running
   */
  isRunning(shellId: number): boolean {
    return this.runningShells.has(shellId);
  }

  /**
   * Dispose all background shells (cleanup resources)
   * This will abort any running shells and dispose all shells
   */
  dispose(): void {
    for (const [shellId, shell] of this.runningShells) {
      shell.dispose();
      this.clearShellWork(shellId);
    }
    this.runningShells.clear();
  }

  async writeStdin(shellId: number, data: string): Promise<void> {
    const shell = this.runningShells.get(shellId);
    if (!shell) {
      throw new Error("Shell not found");
    }
    if (!shell.stdin) {
      throw new Error("Shell stdin not available");
    }

    // Support both the actual EOT character and the escaped string version
    // (some models send "\\u0004" instead of the actual \u0004 character)
    // Prioritize the real EOT character; only fall back to escaped if real doesn't exist
    const EOT = "\u0004";
    const ESCAPED_EOT = "\\u0004"; // 6-character string

    const eotIndex = data.indexOf(EOT);
    const effectiveEofIndex =
      eotIndex !== -1 ? eotIndex : data.indexOf(ESCAPED_EOT);

    if (effectiveEofIndex !== -1) {
      // Write everything before EOF
      const beforeEof = data.substring(0, effectiveEofIndex);
      if (beforeEof.length > 0) {
        await new Promise<void>((resolve, reject) => {
          shell.stdin!.write(beforeEof, (error: Error | null | undefined) => {
            if (error) {
              reject(error);
            } else {
              resolve(undefined);
            }
          });
        });
      }

      // Send EOF by ending the stream
      shell.stdin.end();
    } else {
      // No EOF, write all data
      await new Promise<void>((resolve, reject) => {
        shell.stdin!.write(data, (error: Error | null | undefined) => {
          if (error) {
            reject(error);
          } else {
            resolve(undefined);
          }
        });
      });
    }
  }
}

/**
 * Event handler interface for background shell events
 * This allows external code to receive shell output events
 */
export interface BackgroundShellEventHandler {
  onStdout(data: string): void | Promise<void>;
  onStderr(data: string): void | Promise<void>;
  onExit(code: number | null): void | Promise<void>;
  onStart?(): void | Promise<void>;
}

/**
 * Callback interface for being notified when a background shell is created
 * External consumers (like VSCode) can use this to create UI elements
 */
export interface BackgroundShellCreationCallback {
  onShellCreated(args: {
    shellId: number;
    command: string;
    cwd: string;
    registerEventHandler: (handler: BackgroundShellEventHandler) => void;
    conversationId: string | undefined;
    abortShell: () => void;
    description: string | undefined;
    toolCallId: string | undefined;
  }): void | Promise<void>;
}

type FanoutEvent =
  | { type: "start" }
  | { type: "stdout"; data: string }
  | { type: "stderr"; data: string }
  | { type: "exit"; code: number | null };

/**
 * Delivers background-shell UI events in order, including events that arrive
 * before any handler is registered.
 *
 * CoreShellFactory returns at `stdin_ready` and drains the rest of the stream
 * in the background. Handlers are registered in `onShellCreated` after that, so
 * a fast command can emit stdout/exit first. We buffer until `openAndFlush`,
 * then run every emit (flush + live) on one promise chain so exit cannot race
 * ahead of an in-flight stdout handler.
 */
export class BackgroundShellEventHandlerFanout {
  private readonly handlers: BackgroundShellEventHandler[] = [];
  private readonly buffer: FanoutEvent[] = [];
  private open = false;
  private chain: Promise<void> = Promise.resolve();

  register(handler: BackgroundShellEventHandler): void {
    this.handlers.push(handler);
  }

  emit(event: FanoutEvent): Promise<void> {
    return this.enqueue(async () => {
      if (!this.open) {
        this.buffer.push(event);
        return;
      }
      await this.dispatch(event);
    });
  }

  openAndFlush(options?: { leading?: readonly FanoutEvent[] }): Promise<void> {
    return this.enqueue(async () => {
      this.open = true;
      const pending = [...(options?.leading ?? []), ...this.buffer.splice(0)];
      for (const event of pending) {
        await this.dispatch(event);
      }
    });
  }

  private enqueue(work: () => Promise<void>): Promise<void> {
    this.chain = this.chain.then(work, work);
    return this.chain;
  }

  private async dispatch(event: FanoutEvent): Promise<void> {
    for (const handler of this.handlers) {
      switch (event.type) {
        case "start":
          await handler.onStart?.();
          break;
        case "stdout":
          await handler.onStdout(event.data);
          break;
        case "stderr":
          await handler.onStderr(event.data);
          break;
        case "exit":
          await handler.onExit(event.code);
          break;
        default: {
          const _exhaustive: never = event;
          void _exhaustive;
        }
      }
    }
  }
}

/**
 * Middleware that notifies an external callback when shells are created
 * and allows event handlers to be registered for streaming output
 */
export class EventStreamingShellFactory implements BackgroundShellFactory {
  constructor(
    private readonly innerFactory: BackgroundShellFactory,
    private readonly creationCallback: BackgroundShellCreationCallback,
    private readonly conversationIdExtractor?: (
      ctx: Context
    ) => string | undefined
  ) {}

  async spawn(
    executionContext: ShellExecutionContext,
    coreExecutor: ShellCoreExecutor
  ): Promise<BackgroundShell> {
    const fanout = new BackgroundShellEventHandlerFanout();

    // Create a custom core executor that intercepts events
    const streamingExecutor = this.createStreamingExecutor(
      coreExecutor,
      fanout
    );

    // Spawn the shell with the streaming executor
    const shell = await this.innerFactory.spawn(
      executionContext,
      streamingExecutor
    );

    // Extract conversationId from context if extractor is provided
    const conversationId = this.conversationIdExtractor?.(executionContext.ctx);

    try {
      await this.creationCallback.onShellCreated({
        shellId: executionContext.shellId,
        command: executionContext.command,
        cwd: executionContext.workingDirectory,
        registerEventHandler: (handler: BackgroundShellEventHandler) => {
          fanout.register(handler);
        },
        conversationId,
        abortShell: () => shell.abort(),
        description: executionContext.description,
        toolCallId: executionContext.toolCallId,
      });
      // Handlers (if any) are registered; release buffered early exit/output.
      await fanout.openAndFlush();
    } catch (error) {
      try {
        shell.dispose();
      } catch (disposeError) {
        logger.warn(
          executionContext.ctx,
          "Failed to dispose background shell after onShellCreated failed",
          {
            shellId: executionContext.shellId,
            disposeError,
          }
        );
      }
      throw error;
    }

    return shell;
  }

  private createStreamingExecutor(
    coreExecutor: ShellCoreExecutor,
    fanout: BackgroundShellEventHandlerFanout
  ): ShellCoreExecutor {
    const originalExecute = coreExecutor.execute.bind(coreExecutor);

    return {
      ...coreExecutor,
      execute: async function* (ctx: Context, args: ShellCoreArgs) {
        await fanout.emit({ type: "start" });

        try {
          for await (const event of originalExecute(ctx, args)) {
            // Yield first so CoreShellFactory can observe stdin_ready without
            // waiting on UI handler registration (avoids deadlock).
            yield event;

            if (event.type === "stdout") {
              await fanout.emit({ type: "stdout", data: event.data });
            } else if (event.type === "stderr") {
              await fanout.emit({ type: "stderr", data: event.data });
            } else if (event.type === "exit") {
              await fanout.emit({ type: "exit", code: event.code });
            }
          }
        } catch (error: unknown) {
          const isAborted = args.signal?.aborted ?? false;

          if (!isAborted) {
            await fanout.emit({ type: "exit", code: -1 });
            throw error;
          }
        }
      },
    };
  }

  async adopt(state: ShellAdoptionState): Promise<BackgroundShell> {
    const fanout = new BackgroundShellEventHandlerFanout();

    const streamingIterator: AsyncIterator<ShellCoreEvent> = {
      next: async () => {
        const result = await state.eventIterator.next();

        if (!result.done) {
          const event = result.value;
          // Buffer/dispatch via fanout. While closed this only pushes to the
          // buffer (no handler await), so adopt cannot deadlock on UI setup.
          if (event.type === "stdout") {
            await fanout.emit({ type: "stdout", data: event.data });
          } else if (event.type === "stderr") {
            await fanout.emit({ type: "stderr", data: event.data });
          } else if (event.type === "exit") {
            await fanout.emit({ type: "exit", code: event.code });
          }
        }
        return result;
      },
    };

    const shell = await this.innerFactory.adopt({
      ...state,
      eventIterator: streamingIterator,
    });

    const conversationId = state.ctx
      ? this.conversationIdExtractor?.(state.ctx)
      : undefined;

    try {
      await this.creationCallback.onShellCreated({
        shellId: state.shellId,
        command: state.command,
        cwd: state.workingDirectory,
        registerEventHandler: (handler: BackgroundShellEventHandler) => {
          fanout.register(handler);
        },
        conversationId,
        abortShell: () => shell.abort(),
        description: state.description,
        toolCallId: state.toolCallId,
      });
      // Pre-adopt output must lead the ordered chain so buffered handoff
      // stdout/exit cannot overtake it (and so we never fire-and-forget
      // onStdout outside the fanout).
      await fanout.openAndFlush({
        leading:
          state.initialOutput !== undefined && state.initialOutput.length > 0
            ? [{ type: "stdout", data: state.initialOutput }]
            : [],
      });
    } catch (error) {
      try {
        shell.dispose();
      } catch (disposeError) {
        if (state.ctx) {
          logger.warn(
            state.ctx,
            "Failed to dispose background shell after onShellCreated failed",
            {
              shellId: state.shellId,
              disposeError,
            }
          );
        }
      }
      throw error;
    }

    return shell;
  }
}

/**
 * Create a factory with file logging middleware
 */
export function createBackgroundShellFactory(
  projectDir: string
): BackgroundShellFactory {
  const coreFactory = new CoreShellFactory();
  return new FileLoggingShellFactory(coreFactory, projectDir);
}

/**
 * Create a factory with file logging and event streaming capabilities
 * @param conversationIdExtractor Optional function to extract conversationId from the context (for UI terminal lookup)
 */
export function createBackgroundShellFactoryWithEventStreaming(
  projectDir: string,
  creationCallback: BackgroundShellCreationCallback,
  conversationIdExtractor?: (ctx: Context) => string | undefined
): BackgroundShellFactory {
  const coreFactory = new CoreShellFactory();
  const fileLoggingFactory = new FileLoggingShellFactory(
    coreFactory,
    projectDir
  );
  return new EventStreamingShellFactory(
    fileLoggingFactory,
    creationCallback,
    conversationIdExtractor
  );
}

/**
 * Wraps a {@link BackgroundWorkRegistry} so every wakeup this producer enqueues
 * is attributed to a fixed "owner" conversation, independent of the per-request
 * (execution) conversation the shell ran under.
 *
 * Background shells started by a CLI subagent execute under the child agent's
 * conversation id, but only the root conversation runs a wakeup-consumer loop
 * (`registry.pull(rootConversationId)`). Without this override a subagent shell's
 * completion (or output notification) would be enqueued under the child id and
 * never delivered. The execution conversation id is still used elsewhere (e.g.
 * terminal association via the creation callback), which is why we override only
 * the registry's `enqueue` and delegate everything else unchanged.
 */
export class ConversationOwnerOverrideRegistry
  implements BackgroundWorkRegistry
{
  constructor(
    private readonly inner: BackgroundWorkRegistry,
    private readonly ownerConversationId: string
  ) {}

  enqueue(wakeup: Wakeup<PendingBackgroundCompletion>): void {
    this.inner.enqueue({ ...wakeup, conversationId: this.ownerConversationId });
  }

  enqueueCompletion(item: PendingBackgroundCompletion): void {
    // Route through enqueue so the owner override applies (mirrors the base
    // registry's completion -> wakeup mapping).
    this.enqueue({
      conversationId: this.ownerConversationId,
      id: item.taskId,
      source: item.kind,
      payload: item,
    });
  }

  pull(conversationId: string): Wakeup<PendingBackgroundCompletion>[] {
    return this.inner.pull(conversationId);
  }

  ack(ids: string[]): Wakeup<PendingBackgroundCompletion>[] {
    return this.inner.ack(ids);
  }

  nack(ids: string[], opts: { requeue: boolean }): void {
    this.inner.nack(ids, opts);
  }

  suppress(conversationId: string, id: string): void {
    this.inner.suppress(conversationId, id);
  }

  upsertWork(record: BackgroundWorkRecord): void {
    this.inner.upsertWork(record);
  }

  clearWork(id: string): boolean {
    return this.inner.clearWork(id);
  }

  abortWork(id: string): boolean {
    return this.inner.abortWork(id);
  }

  hasRunningWork(filter?: BackgroundWorkFilter): boolean {
    return this.inner.hasRunningWork(filter);
  }

  abortAllWork(filter?: BackgroundWorkFilter): number {
    return this.inner.abortAllWork(filter);
  }

  listWork(
    filter?: BackgroundWorkFilter
  ): ReadonlyArray<BackgroundWorkSnapshot> {
    return this.inner.listWork(filter);
  }

  drainCompletions(): PendingBackgroundCompletion[] {
    return this.inner.drainCompletions();
  }

  hasPendingCompletions(conversationId?: string): boolean {
    return this.inner.hasPendingCompletions(conversationId);
  }

  markAwaitedCompletion(taskId: string): void {
    // markAwaitedCompletion is just suppress() under the registry's owning
    // conversation. This wrapper routes wakeups to ownerConversationId, so it
    // must suppress there too — delegating to inner.markAwaitedCompletion would
    // suppress the legacy "local" conversation and miss owner-routed wakeups.
    this.inner.suppress(this.ownerConversationId, taskId);
  }
}

export class LocalBackgroundShellExecutor implements BackgroundShellExecutor {
  private readonly backgroundShellManager: BackgroundShellManager;

  constructor(
    private permissionsService: PermissionsService,
    private coreExecutor: ShellCoreExecutor,
    private ignoreService: IgnoreService,
    projectDir: string,
    factory?: BackgroundShellFactory,
    backgroundWorkRegistry?: BackgroundWorkRegistry,
    /**
     * Conversation that owns wakeups produced by these shells. Defaults to the
     * execution conversation when omitted. Set this to the root conversation for
     * subagent providers so subagent-owned shell completions reach the only
     * consumer loop (see {@link ConversationOwnerOverrideRegistry}).
     */
    wakeupOwnerConversationId?: string
  ) {
    const ownedRegistry =
      backgroundWorkRegistry && wakeupOwnerConversationId !== undefined
        ? new ConversationOwnerOverrideRegistry(
            backgroundWorkRegistry,
            wakeupOwnerConversationId
          )
        : backgroundWorkRegistry;
    const baseShellFactory =
      factory ?? createBackgroundShellFactory(projectDir);
    const shellFactory = new NotifyingBackgroundShellFactory(
      baseShellFactory,
      projectDir,
      ownedRegistry
    );
    this.backgroundShellManager = new BackgroundShellManager(
      shellFactory,
      ownedRegistry
    );
  }

  /**
   * Get the background shell manager instance.
   */
  getManager(): BackgroundShellManager {
    return this.backgroundShellManager;
  }

  /**
   * Dispose all background shells and cleanup resources
   */
  dispose(): void {
    this.backgroundShellManager.dispose();
  }

  async execute(
    ctx: Context,
    args: BackgroundShellSpawnArgs
  ): Promise<BackgroundShellSpawnResult> {
    using _span = createSpan(
      ctx.withName("LocalBackgroundShellExecutor.execute")
    );

    const command = args.command;
    const policy = args.sandboxPolicy
      ? convertProtoToInternalPolicy(args.sandboxPolicy)
      : undefined;

    const workingDirectory =
      args.workingDirectory || (await this.coreExecutor.getCwd());
    const resolvedWorkingDir = resolvePath(workingDirectory);
    const parsingResult = new ShellCommandParsingResult(
      analyzeShellCommand(command).structured
    );

    // Uses the RPC snapshot only. Statsig killswitch is upstream; see helper.
    const modelShellBlockReason = getModelShellAdminCommandDenylistBlockReason({
      command,
      parsingResult,
      blockedCommands: args.adminCommandDenylist,
    });
    if (modelShellBlockReason !== undefined) {
      return new BackgroundShellSpawnResult({
        result: {
          case: "rejected",
          value: new ShellRejected({
            command,
            workingDirectory: resolvedWorkingDir,
            reason: modelShellBlockReason,
          }),
        },
      });
    }

    let effectivePolicy = policy;
    logger.info(ctx, "Background shell: approval gate reached", {
      toolCallId: args.toolCallId,
      skipApproval: args.skipApproval,
      hasSmartModeApproval: args.smartModeApproval !== undefined,
      hasSmartModeApprovalReason: args.smartModeApproval?.reason !== undefined,
      hasSmartModeApprovalRequestId:
        args.smartModeApproval?.requestId !== undefined,
      requestedPolicyType: policy?.type ?? "undefined",
      parserCommandCount: parsingResult.executableCommands.length,
      classifierCommandCount: args.classifierResult?.commands.length ?? 0,
      commandLength: command.length,
    });
    if (args.skipApproval) {
      const invariantBlock =
        await this.permissionsService.shouldEnforceShellInvariantBlocks(
          ctx,
          {
            workingDirectory: resolvedWorkingDir,
            // Matches the sync shell and shell-stream pre-approved paths: an
            // unresolvable cwd alone must not reject a command that shell
            // could chdir into anyway.
            skipUnsafeWorkingDirectoryBlock: true,
            command,
            parsingResult,
            toolCallId: args.toolCallId,
          },
          policy
        );
      if (invariantBlock.kind === "block") {
        logger.info(ctx, "Background shell: invariant blocked command", {
          toolCallId: args.toolCallId,
          blockReasonType: invariantBlock.reason.type,
          skipApproval: args.skipApproval,
        });
        return backgroundShellSpawnBlockResult(
          command,
          resolvedWorkingDir,
          invariantBlock.reason
        );
      }
      logger.info(ctx, "Background shell: skipped local approval", {
        toolCallId: args.toolCallId,
        requestedPolicyType: policy?.type ?? "undefined",
      });
    } else {
      const blockResult = await this.permissionsService.shouldBlockShellCommand(
        ctx,
        command,
        {
          workingDirectory: resolvedWorkingDir,
          timeout: 0, // No timeout for background shells
          parsingResult,
          toolCallId: args.toolCallId,
          classifierResult: args.classifierResult,
          smartModeApprovalReason: args.smartModeApproval?.reason,
          smartModeApprovalRequestId: args.smartModeApproval?.requestId,
          hookApprovalRequirement: getShellHookApprovalRequirement(args),
        },
        policy
      );

      if (blockResult.kind === "block") {
        logger.info(ctx, "Background shell: approval gate blocked command", {
          toolCallId: args.toolCallId,
          blockReasonType: blockResult.reason.type,
          hasSmartModeApproval: args.smartModeApproval !== undefined,
          skipApproval: args.skipApproval,
        });
        return backgroundShellSpawnBlockResult(
          command,
          resolvedWorkingDir,
          blockResult.reason
        );
      }

      effectivePolicy = blockResult.policy;
      logger.info(ctx, "Background shell: approval gate allowed command", {
        toolCallId: args.toolCallId,
        skipApproval: args.skipApproval,
        effectivePolicyType: effectivePolicy.type,
      });
    }

    // Eval harness override: force a deny-by-default egress policy that neither
    // unrestricted approval mode nor a model-supplied policy can escalate.
    // Background shells share the same hardening as foreground shell tools.
    if (isForcedShellEgressEnabled()) {
      effectivePolicy = forcedShellSandboxPolicy(command, parsingResult);
      if (effectivePolicy.type !== "insecure_none") {
        const ignoreMapping = await this.ignoreService.getCursorIgnoreMapping();
        effectivePolicy = { ...effectivePolicy, ignoreMapping };
      }
    }

    try {
      // Generate shell ID upfront
      const shellId = this.backgroundShellManager.generateShellId();

      // Spawn the background shell
      // Wrap the policy as merge sources for shell-exec
      const sandboxPolicyMergeSources = effectivePolicy
        ? { perRepo: effectivePolicy }
        : undefined;

      const executionContext: ShellExecutionContext = {
        ctx,
        command,
        workingDirectory: resolvedWorkingDir,
        toolCallId: args.toolCallId,
        conversationId: args.conversationId,
        sandboxPolicy: sandboxPolicyMergeSources,
        shellId,
        enableWriteShellStdinTool: args.enableWriteShellStdinTool,
        description: args.description,
        outputNotification: args.outputNotification,
      };

      const spawnResult = await this.backgroundShellManager.spawn(
        executionContext,
        this.coreExecutor
      );

      return new BackgroundShellSpawnResult({
        result: {
          case: "success",
          value: new BackgroundShellSpawnSuccess({
            shellId,
            command,
            workingDirectory: resolvedWorkingDir,
            pid: spawnResult.pid,
          }),
        },
      });
    } catch (error: unknown) {
      if (error instanceof SandboxUnsupportedError) {
        const policyType = effectivePolicy?.type ?? "unknown";
        logger.warn(
          ctx,
          "Background shell: sandbox policy unsupported on this host",
          {
            toolCallId: args.toolCallId,
            policyType,
            reason: error.reason,
          }
        );
        return new BackgroundShellSpawnResult({
          result: {
            case: "sandboxUnsupported",
            value: new ShellSandboxUnsupported({
              command,
              workingDirectory: resolvedWorkingDir,
              sandboxPolicyType: policyType,
              reason: error.reason ?? error.message,
              isReadonly: policyType === "workspace_readonly",
            }),
          },
        });
      }
      return new BackgroundShellSpawnResult({
        result: {
          case: "error",
          value: new BackgroundShellSpawnError({
            command,
            workingDirectory: resolvedWorkingDir,
            error: error instanceof Error ? error.message : "Unknown error",
          }),
        },
      });
    }
  }

  writeStdin(shellId: number, data: string): Promise<void> {
    return this.backgroundShellManager.writeStdin(shellId, data);
  }
}
