/**
 * Loader for per-repo sandbox policy configuration.
 *
 * IMPORTANT: This module only loads perRepo config from the workspace.
 * It does NOT load perUser config (~/.cursor/sandbox.json) because:
 *
 * - In Remote SSH, local-exec runs on the REMOTE machine
 * - The ~/.cursor/sandbox.json on the remote is NOT the user's config
 * - perUser must be loaded on the HOST and passed down via RPC/proto
 *
 * For agent-cli (always local), perUser is loaded in agent-cli and passed
 * to LocalResourceProvider via _defaultSandboxPolicySources.perUser.
 */

import { readFileSync } from "node:fs";
import { join } from "node:path";
import {
  type PartialSandboxPolicyJson,
  parseSandboxPolicyJson,
  resolvePolicyPaths,
  type SandboxPolicy,
} from "@anysphere/shell-exec";

/**
 * The path to the per-repo sandbox policy config file, relative to workspace root.
 */
const PER_REPO_SANDBOX_CONFIG_PATH = ".cursor/sandbox.json";

/**
 * Synchronously loads the per-repo sandbox policy from the workspace.
 *
 * This function is safe to call from local-exec on a remote machine,
 * as it only accesses files within the workspace directory.
 *
 * @param workspacePath - The absolute path to the workspace root
 * @returns The loaded policy, or undefined if no config exists or is invalid
 */
export function loadPerRepoSandboxPolicySync(
  workspacePath: string
): SandboxPolicy | undefined {
  const configPath = join(workspacePath, PER_REPO_SANDBOX_CONFIG_PATH);
  try {
    const content = readFileSync(configPath, "utf-8");
    const json: PartialSandboxPolicyJson = JSON.parse(content);
    const policy = parseSandboxPolicyJson(json);
    // Resolve relative paths against the workspace root
    // so ./foo in <workspace>/.cursor/sandbox.json means <workspace>/foo
    return resolvePolicyPaths(policy, workspacePath);
  } catch {
    // File doesn't exist or is invalid - return undefined
    return undefined;
  }
}
