const INT32_MIN = -(2 ** 31);
const INT32_MAX = 2 ** 31 - 1;

/**
 * Clamps a number to the valid int32 range.
 * Returns 0 for NaN to prevent protobuf serialization errors ("invalid int 32: NaN").
 */
export function clampInt32(n: number): number {
  if (Number.isNaN(n)) {
    return 0;
  }
  if (n < INT32_MIN) {
    return INT32_MIN;
  }
  if (n > INT32_MAX) {
    return INT32_MAX;
  }
  return n;
}

/**
 * Parse a duration-like value into a non-negative protobuf int32 in ms.
 * Returns undefined for missing/invalid/negative inputs.
 */
export function toOptionalDurationMsInt32(value: unknown): number | undefined {
  if (typeof value !== "number" || !Number.isFinite(value) || value < 0) {
    return undefined;
  }
  return clampInt32(Math.trunc(value));
}
