/**
 * OAuth structured-log events (browser-safe; no Node crypto).
 */
import {
  authMetaLogEnvelope,
  buildUrlHostMetadataFields,
  emitStructuredCoreLog,
} from "./log-metadata.js";
import { MCP_OAUTH_SESSION_KEYS } from "./oauth/mcp-oauth-keys.js";

type McpOAuthTokensLike = {
  readonly access_token?: string;
  readonly refresh_token?: string;
  readonly expires_in?: number;
  readonly scope?: string;
};

export interface OAuthTokensSnapshotForLog {
  readonly accessTokenLen: number;
  readonly refreshTokenPresent: boolean;
  readonly expiresAtTimestamp: number | null;
  /**
   * The `scope` field of the token response — the scopes the authorization
   * server actually GRANTED, which can be a subset of what was requested
   * (Google's granular consent lets users deselect scopes, and scopes not
   * registered on the OAuth app are dropped). Scope identifiers are public
   * API URLs, not user data, so they are safe to log; this is the primary
   * diagnostic for "consent succeeded but tool calls get PERMISSION_DENIED".
   */
  readonly grantedScope: string | null;
}

export function buildOAuthTokensSnapshotForLog(
  tokens: McpOAuthTokensLike | undefined,
  options?: { readonly expiresInIsFresh?: boolean }
): OAuthTokensSnapshotForLog {
  const accessToken = tokens?.access_token;
  const accessTokenLen =
    typeof accessToken === "string" ? accessToken.length : 0;
  const refreshTokenPresent = Boolean(tokens?.refresh_token);
  const expiresInSec =
    typeof tokens?.expires_in === "number" && Number.isFinite(tokens.expires_in)
      ? tokens.expires_in
      : null;
  const expiresAtTimestamp =
    options?.expiresInIsFresh && expiresInSec !== null
      ? Date.now() + Math.round(expiresInSec * 1000)
      : null;
  const grantedScope =
    typeof tokens?.scope === "string" && tokens.scope.length > 0
      ? tokens.scope
      : null;
  return {
    accessTokenLen,
    refreshTokenPresent,
    expiresAtTimestamp,
    grantedScope,
  };
}

export function buildMcpOAuthAuthMetaServerUrlFields(
  serverUrl: string
): Record<string, string | null> {
  return buildUrlHostMetadataFields(serverUrl, {
    includePath: false,
    duplicateHostAs: ["serverUrlHost"],
  });
}

export function buildMcpOAuthAuthMetaAuthorizationUrlFields(
  authorizationUrl: string
): Record<string, string | null> {
  return buildUrlHostMetadataFields(authorizationUrl, {
    includePath: false,
    duplicateHostAs: ["authUrlHost"],
  });
}

/** Correlates OAuth auth-meta with a specific MCP process registry row (dual cfg siblings). */
export interface McpOAuthProcessRegistryContextForLog {
  readonly processRegistryKey?: string;
  readonly activeIdentifier?: string;
  readonly resolvedConfigHash?: string;
}

export function buildMcpOAuthProcessRegistryContextFields(
  context: McpOAuthProcessRegistryContextForLog
): Record<string, string> {
  const fields: Record<string, string> = {};
  if (context.processRegistryKey) {
    fields.processRegistryKey = context.processRegistryKey;
  }
  if (context.activeIdentifier) {
    fields.activeIdentifier = context.activeIdentifier;
  }
  if (context.resolvedConfigHash) {
    fields.resolvedConfigHash = context.resolvedConfigHash;
  }
  return fields;
}

