export type McpOAuthCredentialsClearReason =
  | "canonical_server_url_mismatch"
  | "retention_expired"
  | "retention_incompatible"
  | "decrypt_failure"
  | "decrypt_failure_set_if_absent"
  | "decrypt_failure_conditional_delete"
  | "logout_clear_identifier"
  | "clear_identifier_scoped_state"
  | "clear_all_tokens"
  | "clear_all_tokens_for_profile"
  | "ext_host_delete_secret"
  | "ext_host_clear_identifier_scoped"
  | "ext_host_clear_all_local_state"
  | "ext_host_provider_clear"
