export function emitMcpOAuthAuthMetaLog(
  args: EmitMcpOAuthAuthMetaLogArgs
): void {
  emitStructuredCoreLog({
    identifier: args.identifier,
    level: args.level ?? "info",
    message: args.message ?? AUTH_META_EVENT_MESSAGES[args.event],
    metadata: authMetaLogEnvelope({
      event: args.event,
      commandsVersion: args.commandsVersion ?? "process",
      mcpOAuthOwner: args.mcpOAuthOwner ?? "mcp_process",
      ...(args.fields ?? {}),
    }),
    error: args.error,
  });
}

export function emitMcpOAuthCredentialsClearedLog(
  args: EmitMcpOAuthCredentialsClearedLogArgs
): void {
  emitMcpOAuthAuthMetaLog({
    identifier: args.identifier,
    event: "mcp_oauth_credentials_cleared",
    level: args.level ?? "warn",
    commandsVersion: args.commandsVersion,
    mcpOAuthOwner: args.mcpOAuthOwner,
    fields: {
      reason: args.reason,
      clearScope: args.clearScope,
      storageKey: args.storageKey,
      hadRefreshToken: args.hadRefreshToken,
      ...(args.fields ?? {}),
    },
  });
}
