// Electron's desktop process can exit mid-task, so local exec runs in a detached daemon.
import { createDeadlinePolicy } from "@sand/dune/scheduling";

import { runLocalExecDaemon } from "../host/local-exec/local-exec-daemon.js";
import {
	flushSandSentry,
	initSandSentryDaemon,
	type SandDaemonCrashReporter,
} from "../host/local-exec/sentry.js";
import { installProcessCrashGuards } from "../host/process-crash-guard.js";
import { installInvariantReporter } from "../shared/invariant.js";
import { writeInvariantViolationLog } from "./invariant-violation-log.js";

// The spawner's terminateProcess exit-wait budget (local-exec-native.ts,
// ~4s) is sized to SIGTERM close plus this 2s force-exit deadline.
const shutdownDeadline = createDeadlinePolicy({
	name: "local-exec-daemon-shutdown",
	timeoutMs: 2_000,
});

let reportCrash: SandDaemonCrashReporter | undefined;

async function main(): Promise<void> {
	installInvariantReporter((report) => writeInvariantViolationLog(report));
	const guards = installProcessCrashGuards({ scope: "sand-local-exec-daemon" });

	reportCrash = initSandSentryDaemon();
	if (reportCrash) guards.setReporter(reportCrash);

	const daemon = await runLocalExecDaemon();
	console.log(
		`[sand-local-exec-daemon] started (pid ${process.pid}); serving local exec over the gateway`,
	);

	let isShuttingDown = false;
	const shutdown = (signal: NodeJS.Signals): void => {
		if (isShuttingDown) return;
		isShuttingDown = true;
		console.log(`[sand-local-exec-daemon] received ${signal}, shutting down`);
		void shutdownDeadline.run(() => daemon.close()).finally(() => process.exit(0));
	};
	process.on("SIGTERM", () => shutdown("SIGTERM"));
	process.on("SIGINT", () => shutdown("SIGINT"));
}

main().catch((error) => {
	void shutdownDeadline
		.run(async () => {
			reportCrash?.(error instanceof Error ? error : new Error(String(error)), "fatal");
			await flushSandSentry(1_500);
		})
		.finally(() => process.exit(1));
});
