export const AGENTS_SECTION_ID = "__agents__";
export const AGENTS_SECTION_NAME = "Unassigned";
export const NEW_SECTION_NAME = "New section";

export const NO_SIDEBAR_SECTIONS: readonly SidebarSection[] = [];

export type SectionDropPosition = "before" | "after";

export interface SidebarSectionRecord {
	readonly id: string;
	readonly name: string;
	readonly agentIds: readonly string[];
}

export interface SidebarSection extends SidebarSectionRecord {
	readonly isCollapsed: boolean;
}

export interface StoredSidebarSection extends SidebarSectionRecord {
	readonly isCollapsed: boolean;
}

export interface SidebarSectionUpdate extends SidebarSectionRecord {
	readonly isCollapsed?: boolean;
}

interface CarryFoldsArgs {
	readonly sections: readonly SidebarSectionUpdate[];
	readonly stored?: readonly StoredSidebarSection[];
}

export class SidebarSections {
	static normalize(sections: readonly SidebarSectionRecord[]): readonly SidebarSectionRecord[] {
		const seenSectionIds = new Set<string>();
		const claimedAgentIds = new Set<string>();
		const normalized: SidebarSectionRecord[] = [];
		let hasSynthetic = false;

		for (const section of sections) {
			const id = section.id.trim();
			if (id.length === 0 || seenSectionIds.has(id)) continue;
			seenSectionIds.add(id);
			if (id === AGENTS_SECTION_ID) {
				hasSynthetic = true;
				normalized.push({ id, name: AGENTS_SECTION_NAME, agentIds: [] });
				continue;
			}
			const agentIds: string[] = [];
			for (const agentId of section.agentIds) {
				if (agentId.length === 0 || claimedAgentIds.has(agentId)) continue;
				claimedAgentIds.add(agentId);
				agentIds.push(agentId);
			}
			normalized.push({ id, name: section.name, agentIds });
		}

		if (normalized.length === (hasSynthetic ? 1 : 0)) return NO_SIDEBAR_SECTIONS;
		if (!hasSynthetic) {
			normalized.push({ id: AGENTS_SECTION_ID, name: AGENTS_SECTION_NAME, agentIds: [] });
		}
		return normalized;
	}

	static parse(value: readonly unknown[]): readonly SidebarSectionRecord[] {
		const records: SidebarSectionRecord[] = [];
		for (const entry of value) {
			if (typeof entry !== "object" || entry == null) continue;
			const record = entry as Record<string, unknown>;
			if (typeof record.id !== "string") continue;
			records.push({
				id: record.id,
				name: typeof record.name === "string" ? record.name : "",
				agentIds: Array.isArray(record.agentIds)
					? record.agentIds.filter((id): id is string => typeof id === "string")
					: [],
			});
		}
		return SidebarSections.normalize(records);
	}

	static withFolds(
		sections: readonly SidebarSectionRecord[],
		collapsedSectionIds: readonly string[],
	): readonly SidebarSection[] {
		const collapsed = new Set(collapsedSectionIds);
		return sections.map((section) => ({ ...section, isCollapsed: collapsed.has(section.id) }));
	}

	static carryFolds({ sections, stored = [] }: CarryFoldsArgs): readonly StoredSidebarSection[] {
		const foldBySectionId = new Map<string, boolean>();
		for (const section of [...stored, ...sections]) {
			if (section.isCollapsed !== undefined) {
				foldBySectionId.set(section.id.trim(), section.isCollapsed);
			}
		}
		return SidebarSections.normalize(sections).map((section) => ({
			...section,
			isCollapsed: foldBySectionId.get(section.id) ?? false,
		}));
	}
}
