import {
  type IntervalHistogram,
  monitorEventLoopDelay,
  performance,
} from "node:perf_hooks";
import type { IDisposable } from "./lifecycle.js";

interface EventLoopPressureSnapshot {
  readonly eventLoopDelayP95Ms: number;
  readonly eventLoopUtilization: number;
}

enum EventLoopPressureThresholdDefault {
  EventLoopDelayP95Ms = 50,
  EventLoopUtilization = 0.7,
}

enum EventLoopPressureTrackerDefault {
  SampleIntervalMs = 250,
  EventLoopResolutionMs = 20,
}

const EMPTY_SNAPSHOT: EventLoopPressureSnapshot = {
  eventLoopDelayP95Ms: 0,
  eventLoopUtilization: 0,
};

export interface IEventLoopPressureTracker extends IDisposable {
  isUnderPressure(): boolean;
  formatSuppressionSection(): string;
}

let sharedEventLoopPressureTracker: EventLoopPressureTracker | undefined;
let acquireCount = 0;

export function acquireEventLoopPressureTracker(): IEventLoopPressureTracker {
  acquireCount++;
  if (sharedEventLoopPressureTracker === undefined) {
    sharedEventLoopPressureTracker = new EventLoopPressureTracker();
  }

  const tracker = sharedEventLoopPressureTracker;
  let disposed = false;

  return {
    isUnderPressure: () => tracker.isUnderPressure(),
    formatSuppressionSection: () => tracker.formatSuppressionSection(),
    dispose: () => {
      if (disposed) {
        return;
      }
      disposed = true;
      acquireCount--;
      if (acquireCount === 0 && sharedEventLoopPressureTracker !== undefined) {
        sharedEventLoopPressureTracker.dispose();
        sharedEventLoopPressureTracker = undefined;
      }
    },
  };
}

/**
 * Samples extension event loop pressure signals at a fixed interval so shell
 * output suppression checks can stay O(1) per chunk.
 */
class EventLoopPressureTracker implements IEventLoopPressureTracker {
  private readonly eventLoopMonitor: IntervalHistogram;

  private sampleTimer: ReturnType<typeof setInterval> | undefined;
  private lastEventLoopUtilization = performance.eventLoopUtilization();
  private latestSnapshot: EventLoopPressureSnapshot = EMPTY_SNAPSHOT;

  constructor() {
    this.eventLoopMonitor = monitorEventLoopDelay({
      resolution: EventLoopPressureTrackerDefault.EventLoopResolutionMs,
    });

    this.lastEventLoopUtilization = performance.eventLoopUtilization();
    this.eventLoopMonitor.enable();
    this.sample();

    this.sampleTimer = setInterval(() => {
      this.sample();
    }, EventLoopPressureTrackerDefault.SampleIntervalMs);
    this.sampleTimer.unref?.();
  }

  dispose(): void {
    if (this.sampleTimer === undefined) {
      return;
    }

    clearInterval(this.sampleTimer);
    this.sampleTimer = undefined;
    this.eventLoopMonitor.disable();
    this.latestSnapshot = EMPTY_SNAPSHOT;
    this.lastEventLoopUtilization = performance.eventLoopUtilization();
  }

  isUnderPressure(): boolean {
    return (
      this.latestSnapshot.eventLoopDelayP95Ms >=
        EventLoopPressureThresholdDefault.EventLoopDelayP95Ms ||
      this.latestSnapshot.eventLoopUtilization >=
        EventLoopPressureThresholdDefault.EventLoopUtilization
    );
  }

  formatSuppressionSection(): string {
    const snapshot = this.latestSnapshot;

    const metrics = [
      `event loop delay p95 ${snapshot.eventLoopDelayP95Ms.toFixed(1)}ms (threshold ${EventLoopPressureThresholdDefault.EventLoopDelayP95Ms}ms)`,
      `event loop utilization ${(snapshot.eventLoopUtilization * 100).toFixed(1)}% (threshold ${(EventLoopPressureThresholdDefault.EventLoopUtilization * 100).toFixed(1)}%)`,
    ].join(", ");

    const pressureReasons = this.getPressureTriggerReasons(snapshot);
    const pressureState =
      pressureReasons.length > 0
        ? `event loop under pressure (${pressureReasons.join(", ")})`
        : "event loop not under pressure";

    return `event loop pressure gate enabled; ${pressureState}; event loop metrics: ${metrics}`;
  }

  private getPressureTriggerReasons(
    snapshot: EventLoopPressureSnapshot
  ): string[] {
    const reasons: string[] = [];
    if (
      snapshot.eventLoopDelayP95Ms >=
      EventLoopPressureThresholdDefault.EventLoopDelayP95Ms
    ) {
      reasons.push(
        `event loop delay p95 ${snapshot.eventLoopDelayP95Ms.toFixed(1)}ms >= ${EventLoopPressureThresholdDefault.EventLoopDelayP95Ms}ms`
      );
    }
    if (
      snapshot.eventLoopUtilization >=
      EventLoopPressureThresholdDefault.EventLoopUtilization
    ) {
      reasons.push(
        `event loop utilization ${(snapshot.eventLoopUtilization * 100).toFixed(1)}% >= ${(EventLoopPressureThresholdDefault.EventLoopUtilization * 100).toFixed(1)}%`
      );
    }
    return reasons;
  }

  private sample(): void {
    this.latestSnapshot = {
      eventLoopDelayP95Ms: this.computeEventLoopDelayP95Ms(),
      eventLoopUtilization: this.computeEventLoopUtilization(),
    };
  }

  private computeEventLoopDelayP95Ms(): number {
    const rawP95Ns = this.eventLoopMonitor.percentile(95);
    this.eventLoopMonitor.reset();

    if (!Number.isFinite(rawP95Ns)) {
      return 0;
    }

    const p95Ms = rawP95Ns / 1e6;
    return Math.max(
      0,
      p95Ms - EventLoopPressureTrackerDefault.EventLoopResolutionMs
    );
  }

  private computeEventLoopUtilization(): number {
    const currentEventLoopUtilization = performance.eventLoopUtilization();
    const active =
      currentEventLoopUtilization.active - this.lastEventLoopUtilization.active;
    const idle =
      currentEventLoopUtilization.idle - this.lastEventLoopUtilization.idle;
    const total = active + idle;

    this.lastEventLoopUtilization = currentEventLoopUtilization;
    if (total <= 0 || !Number.isFinite(total)) {
      return 0;
    }
    return active / total;
  }
}
