import { readFile, rename, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { type Context, createLogger } from "@anysphere/context";

const logger = createLogger("skill-sync-manifest");

const MANIFEST_FILENAME = ".sync-manifest.json";
const MANIFEST_TMP_FILENAME = ".sync-manifest.json.tmp";
const MANIFEST_VERSION = 1;

export interface SkillSyncEntry {
  lastSyncedAt: number;
}

export interface SkillSyncManifest {
  version: number;
  skills: Record<string, SkillSyncEntry>;
  lastInventoryAt?: number;
}

function emptyManifest(): SkillSyncManifest {
  return { version: MANIFEST_VERSION, skills: {} };
}

function isValidManifest(value: unknown): value is SkillSyncManifest {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    return false;
  }
  const obj = value as Record<string, unknown>;
  if (typeof obj.version !== "number" || typeof obj.skills !== "object") {
    return false;
  }
  if (obj.skills === null || Array.isArray(obj.skills)) {
    return false;
  }
  if (
    obj.lastInventoryAt !== undefined &&
    typeof obj.lastInventoryAt !== "number"
  ) {
    return false;
  }
  return true;
}

/**
 * Read the sync manifest from disk.
 * Returns an empty manifest on missing file, parse error, or schema mismatch
 * so callers never need to handle failure — the worst case is that every skill
 * gets bootstrapped with a fresh timestamp (safe: no deletions).
 */
export async function readManifest(
  skillDir: string,
  ctx: Context
): Promise<SkillSyncManifest> {
  try {
    const raw = await readFile(join(skillDir, MANIFEST_FILENAME), "utf-8");
    const parsed: unknown = JSON.parse(raw);
    if (!isValidManifest(parsed)) {
      logger.warn(ctx, "Manifest failed schema validation, resetting", {
        skillDir,
      });
      return emptyManifest();
    }
    return parsed;
  } catch (error) {
    if (
      error instanceof Error &&
      (error as NodeJS.ErrnoException).code === "ENOENT"
    ) {
      return emptyManifest();
    }
    logger.warn(ctx, "Failed to read sync manifest, resetting", {
      skillDir,
      error: String(error),
    });
    return emptyManifest();
  }
}

/**
 * Persist the manifest atomically: write to a tmp file then rename.
 */
export async function writeManifest(
  skillDir: string,
  manifest: SkillSyncManifest
): Promise<void> {
  const tmpPath = join(skillDir, MANIFEST_TMP_FILENAME);
  const finalPath = join(skillDir, MANIFEST_FILENAME);
  await writeFile(tmpPath, JSON.stringify(manifest, null, 2), "utf-8");
  await rename(tmpPath, finalPath);
}

export function touchSkill(
  manifest: SkillSyncManifest,
  id: string,
  nowMs: number
): void {
  manifest.skills[id] = { lastSyncedAt: nowMs };
}

export function removeSkill(manifest: SkillSyncManifest, id: string): void {
  delete manifest.skills[id];
}
