import {
	classifyMcpFailure,
	isAuthRelatedError,
	isBenignSdkError,
	isIgnorableSseError,
} from './error-classification.js';
import type { AuthState, FSMEvent } from './types.js';

// ── Context types for each classifier ────────────────────────────────

export interface OnerrorContext {
	authState: AuthState;
	transportType: string;
}

export interface OncloseContext {
	authState: AuthState;
	transportType: string;
}

export interface ToolCallContext {
	result: {
		content?: ReadonlyArray<{ type: string; text?: string }>;
		isError?: boolean;
	} | undefined;
	error: unknown;
	authState: AuthState;
}

export interface OfferingsContext {
	hasResults: boolean;
	authError: string | undefined;
	authState: AuthState;
}

// ── Classifiers ──────────────────────────────────────────────────────

/**
 * Classify an `onerror` callback from the MCP SDK client.
 * Returns an array of FSMEvents to dispatch, or empty array if the error should be ignored.
 */
export function classifyOnerrorCallback(
	error: Error,
	ctx: OnerrorContext,
): FSMEvent[] {
	const { authState, transportType } = ctx;

	if (isIgnorableSseError(error)) {
		return [];
	}

	// Benign stale response (unknown message ID)
	if (isBenignSdkError(error)) {
		return [];
	}

	// During OAuth, suppress transport errors
	if (authState.type === 'needsUserAuth') {
		return [];
	}

	const classification = classifyMcpFailure(error, transportType);
	if (classification.reason === 'auth') {
		return [{ target: 'auth', kind: 'operation_auth_failed', error: error.message }];
	}

	if (classification.reason === 'session_invalidated') {
		return [{ target: 'connection', kind: 'session_invalidated' }];
	}

	if (transportType !== 'stdio') {
		const httpStatus = classification.httpStatus;
		if (httpStatus === 429 || httpStatus === 503) {
			return [{ target: 'connection', kind: 'request_degraded', reason: `HTTP ${httpStatus}` }];
		}
	}

	if (transportType !== 'stdio' && classification.retryable) {
		return [{ target: 'connection', kind: 'transport_error', error: error.message, isRetryable: true }];
	}

	// Non-retryable error
	return [{ target: 'connection', kind: 'transport_error', error: error.message, isRetryable: false }];
}

/**
 * Classify an `onclose` callback from the MCP SDK client.
 */
export function classifyOncloseCallback(
	ctx: OncloseContext,
): FSMEvent[] {
	const { authState, transportType } = ctx;

	if (authState.type === 'needsUserAuth') {
		return [];
	}
	const isStdio = transportType === 'stdio';
	return [{ target: 'connection', kind: 'transport_closed', isStdio }];
}

/**
 * Extract the combined text from MCP content items.
 */
function extractContentText(content: ReadonlyArray<{ type: string; text?: string }>): string | undefined {
	for (const item of content) {
		if (item.type === 'text' && typeof item.text === 'string') {
			return item.text;
		}
	}
	return undefined;
}

/**
 * Classify the outcome of a callTool operation.
 * Returns events to dispatch based on the result or error.
 *
 * Key principle: if the server responded at all (even with an error result),
 * that proves the connection and auth are working.  Only transport-level
 * thrown errors (where we never reached the server) produce no events.
 */
export function classifyToolCallOutcome(
	ctx: ToolCallContext,
): FSMEvent[] {
	const { result, error: thrownError, authState } = ctx;

	// If an error was thrown (transport-level — we never got a server response)
	if (thrownError !== undefined) {
		if (isAuthRelatedError(thrownError)) {
			if (authState.type !== 'needsUserAuth') {
				const errorMsg = thrownError instanceof Error ? thrownError.message : String(thrownError);
				return [{ target: 'auth', kind: 'operation_auth_failed', error: errorMsg }];
			}
		}
		// Transport failure, no server response — we learned nothing about auth
		return [];
	}

	// Check the result
	if (result === undefined) {
		return [];
	}

	if (!result.isError) {
		// Successful tool call — server responded, auth is working
		return [{ target: 'auth', kind: 'operation_succeeded' }];
	}

	// Tool returned an error result — the server DID respond, so auth is working.
	// Non-auth tool error — the server processed the request, confirming
	// the connection and auth are healthy (e.g., invalid params, rate limit,
	// tool-specific errors).  This heals `expired` auth state.
	return [{ target: 'auth', kind: 'operation_succeeded' }];
}

/**
 * Classify the outcome of a listOfferings operation.
 * Returns events to dispatch based on whether auth errors were seen.
 *
 * A successful offerings call (even with 0 results) proves the server
 * responded and auth is working.  Servers legitimately may expose zero
 * tools/prompts/resources.
 */
export function classifyOfferingsOutcome(
	ctx: OfferingsContext,
): FSMEvent[] {
	const { authError, authState } = ctx;

	if (authError !== undefined) {
		if (authState.type !== 'needsUserAuth') {
			return [{ target: 'auth', kind: 'operation_auth_failed', error: authError }];
		}
		return [];
	}

	// No auth error — the server responded successfully.  This confirms
	// auth is working, even if the server has 0 tools/prompts/resources.
	return [{ target: 'auth', kind: 'operation_succeeded' }];
}
