async function getGitRepoPathForWorkspacePath(
  ctx: Context,
  gitExecutor: GitExecutor,
  path: string
): Promise<string | null> {
  try {
    const result = await gitExecutor.exec(
      ctx,
      path,
      ["rev-parse", "--show-toplevel"],
      { caller: "getGitRepoPathForWorkspacePath" }
    );
    return result.stdout.trim();
  } catch {
    return null;
  }
}

async function getGitStatusForRepoPath(
  ctx: Context,
  gitExecutor: GitExecutor,
  repoPath: string,
  timeoutMs?: number
): Promise<string | undefined> {
  using _span = createSpan(
    ctx.withName("LocalRequestContextExecutor.getGitStatusForRepoPath")
  );
  // Use --short for fast, compact output (agents can read it fine)
  try {
    const result = await gitExecutor.exec(
      ctx,
      repoPath,
      ["--no-optional-locks", "status", "--short", "--branch"],
      { timeout: timeoutMs, caller: "getGitStatusForRepoPath" }
    );
    return result.stdout;
  } catch {
    return undefined;
  }
}

async function getGitBranchForRepoPath(
  ctx: Context,
  gitExecutor: GitExecutor,
  repoPath: string,
  timeoutMs?: number
): Promise<string | undefined> {
  try {
    const result = await gitExecutor.exec(
      ctx,
      repoPath,
      ["rev-parse", "--abbrev-ref", "HEAD"],
      { timeout: timeoutMs, caller: "getGitBranchForRepoPath" }
    );
    const branch = result.stdout.trim();
    if (branch === "HEAD" || branch.length === 0) {
      return undefined;
    }
    return branch;
  } catch {
    return undefined;
  }
}

async function getGitInfoForRepoPathWithinBudget(
  ctx: Context,
  gitExecutor: GitExecutor,
  repoPath: string,
  budgetMs: number
): Promise<{ status?: string; branchName?: string }> {
  const withTimeoutBudget = <T>(
    operation: Promise<T | undefined>
  ): Promise<T | undefined> => {
    let timeoutHandle: NodeJS.Timeout | undefined;
    const timeoutPromise = new Promise<undefined>(resolve => {
      timeoutHandle = setTimeout(() => {
        resolve(undefined);
      }, budgetMs);
    });

    const raced = Promise.race([
      operation.catch(() => undefined),
      timeoutPromise,
    ]);

    return raced.finally(() => {
      if (timeoutHandle !== undefined) {
        clearTimeout(timeoutHandle);
      }
    });
  };

  const [status, branchName] = await Promise.all([
    withTimeoutBudget(
      getGitStatusForRepoPath(ctx, gitExecutor, repoPath, budgetMs)
    ),
    withTimeoutBudget(
      getGitBranchForRepoPath(ctx, gitExecutor, repoPath, budgetMs)
    ),
  ]);

  return { status, branchName };
}

/** Information about the sandbox network allowlist for prompt generation. */
export interface NetworkAllowlistInfo {
  /** Whether the Statsig-controlled defaults (package managers, VCS, etc.) are active and non-empty. */
  hasDefaults: boolean;
  /** Explicit domain entries from sandbox.json and/or admin dashboard settings. */
  explicitEntries: string[];
}

/**
 * Builds a `NetworkAllowlistInfo` from team settings and sandbox.json files.
 * Shared by CLI and IDE to avoid duplicating the collection logic.
 *
 * @param teamSettings - Provider for admin-configured defaults and network controls.
 * @param homeDir - User's home directory (for per-user sandbox.json).
 * @param repoPath - Optional workspace/repo root (for per-repo sandbox.json).
 */
export async function buildNetworkAllowlistInfo(
  teamSettings: {
    getDefaultNetworkAllowlist(): Promise<{
      available: boolean;
      allowlist: string[];
    }>;
    getNetworkAccessControls(): Promise<{ allowlist: string[] }>;
  },
  homeDir: string,
  repoPath?: string
): Promise<NetworkAllowlistInfo> {
  const [defaults, adminControls] = await Promise.all([
    teamSettings.getDefaultNetworkAllowlist(),
    teamSettings.getNetworkAccessControls(),
  ]);

  // Collect explicit entries from admin allowlist and sandbox.json files
  const explicitEntries: string[] = [...adminControls.allowlist];

  // Load per-user sandbox.json network policy entries
  // Pass homeDir as baseDir so relative paths like ./foo resolve to $HOME/foo
  const perUserPath = `${homeDir}/.cursor/sandbox.json`;
  const perUserPolicy = await loadSandboxPolicyFromFileOrUndefined(
    perUserPath,
    homeDir
  );
  if (
    perUserPolicy &&
    perUserPolicy.type !== "insecure_none" &&
    perUserPolicy.networkPolicy?.allow
  ) {
    explicitEntries.push(...perUserPolicy.networkPolicy.allow);
  }

  // Load per-repo sandbox.json network policy entries
  if (repoPath) {
    // Pass repoPath as baseDir so relative paths like ./foo resolve to <workspace>/foo
    const perRepoPath = `${repoPath}/.cursor/sandbox.json`;
    const perRepoPolicy = await loadSandboxPolicyFromFileOrUndefined(
      perRepoPath,
      repoPath
    );
    if (
      perRepoPolicy &&
      perRepoPolicy.type !== "insecure_none" &&
      perRepoPolicy.networkPolicy?.allow
    ) {
      explicitEntries.push(...perRepoPolicy.networkPolicy.allow);
    }
  }

  // Deduplicate entries
  const uniqueEntries = [...new Set(explicitEntries)];

  return {
    hasDefaults: defaults.available && defaults.allowlist.length > 0,
    explicitEntries: uniqueEntries,
  };
}

/**
 * Reads network allow entries from sandbox.json files only (per-user and per-repo).
 * Does NOT include admin/team settings — those live in the workbench.
 * Used by cursor-agent-exec to push file-derived entries to the renderer.
 */
export async function readSandboxNetworkFileEntries(
  homeDir: string,
  repoPath?: string
): Promise<string[]> {
  const entries: string[] = [];

  const perUserPath = `${homeDir}/.cursor/sandbox.json`;
  const perUserPolicy = await loadSandboxPolicyFromFileOrUndefined(
    perUserPath,
    homeDir
  );
  if (
    perUserPolicy &&
    perUserPolicy.type !== "insecure_none" &&
    perUserPolicy.networkPolicy?.allow
  ) {
    entries.push(...perUserPolicy.networkPolicy.allow);
  }

  if (repoPath) {
    const perRepoPath = `${repoPath}/.cursor/sandbox.json`;
    const perRepoPolicy = await loadSandboxPolicyFromFileOrUndefined(
      perRepoPath,
      repoPath
    );
    if (
      perRepoPolicy &&
      perRepoPolicy.type !== "insecure_none" &&
      perRepoPolicy.networkPolicy?.allow
    ) {
      entries.push(...perRepoPolicy.networkPolicy.allow);
    }
  }

  return [...new Set(entries)];
}

export type ArtifactsFolderResolver = (ctx: Context) => string | undefined;

interface ComputeEnvOptions {
  projectDir?: string;
  notesSessionId?: string;
  metaAgentNotesEnabled?: boolean;
  /** Whether this runtime should select the Smart Mode (Auto-review) classifier. */
  getSmartModeClassifierAutoModeEnabled?: () => boolean;
  devForceNextSmartModeClassifierBlockToken?: string;
  isWorkingDirHomeDir?: boolean;
  getSandboxEnabled?: () => boolean;
  /** Whether the environment supports running in a sandbox. */
  getSandboxSupported?: () => boolean;
  /** Network allowlist info for sandbox prompt generation. */
  getNetworkAllowlistInfo?: () => Promise<NetworkAllowlistInfo>;
  userTerminalHint?: string;
  artifactsFolder?: string;
  secretRedactionEnabled?: boolean;
  /** When set, computer-use is supported when this returns true. */
  getComputerUseSupported?: () => boolean;
}

async function computeEnv(
  _ctx: Context,
  workspacePaths: string[],
  options: ComputeEnvOptions = {}
): Promise<RequestContextEnv> {
  const {
    projectDir,
    notesSessionId,
    metaAgentNotesEnabled,
    getSmartModeClassifierAutoModeEnabled,
    devForceNextSmartModeClassifierBlockToken,
    isWorkingDirHomeDir,
    getSandboxEnabled,
    getSandboxSupported,
    getNetworkAllowlistInfo,
    userTerminalHint,
    artifactsFolder,
    secretRedactionEnabled,
    getComputerUseSupported,
  } = options;
  const osVersion: string = `${os.platform()} ${os.release()}`;
  const shell = getSuggestedShell(userTerminalHint);
  const timeZone: string | undefined = (() => {
    try {
      const resolvedOptions: Intl.ResolvedDateTimeFormatOptions =
        new Intl.DateTimeFormat().resolvedOptions();
      return resolvedOptions.timeZone ?? undefined;
    } catch {
      return undefined;
    }
  })();

  // Calculate folder paths if projectDir is available
  const projectFolder = projectDir;
  const terminalsFolder = projectDir ? `${projectDir}/terminals` : undefined;
  const agentSharedNotesFolder =
    projectDir && metaAgentNotesEnabled !== true
      ? `${projectDir}/agent-notes/shared`
      : undefined;
  const agentConversationNotesFolder =
    projectDir && notesSessionId
      ? `${projectDir}/agent-notes/${notesSessionId}`
      : undefined;
  const agentTranscriptsFolder = projectDir
    ? `${projectDir}/agent-transcripts`
    : undefined;

  // Determine if sandbox is enabled: check environment support and user preference
  // If getSandboxEnabled is provided, use it (it should check both environment and user preference)
  // Otherwise, default to false since we don't know the user preference
  const sandboxEnabled = getSandboxEnabled ? getSandboxEnabled() : false;
  const sandboxSupported = getSandboxSupported?.();

  const smartModeClassifierAutoMode = getSmartModeClassifierAutoModeEnabled?.();

  // Fetch network allowlist info for prompt generation (non-blocking, best-effort)
  let networkAllowlistInfo: NetworkAllowlistInfo | undefined;
  if (getNetworkAllowlistInfo) {
    try {
      networkAllowlistInfo = await getNetworkAllowlistInfo();
    } catch {
      // Best-effort: if fetching fails, the model just won't be told about network access
      networkAllowlistInfo = undefined;
    }
  }

  return new RequestContextEnv({
    osVersion,
    workspacePaths,
    shell,
    sandboxEnabled,
    projectFolder,
    terminalsFolder,
    agentSharedNotesFolder,
    agentConversationNotesFolder,
    agentTranscriptsFolder,
    timeZone,
    processWorkingDirectory: process.cwd(),
    artifactsFolder,
    ...(smartModeClassifierAutoMode !== undefined && {
      smartModeClassifierAutoModeEnabled: smartModeClassifierAutoMode,
    }),
    ...(devForceNextSmartModeClassifierBlockToken !== undefined && {
      devForceNextSmartModeClassifierBlockToken,
    }),
    ...(secretRedactionEnabled !== undefined && { secretRedactionEnabled }),
    ...(sandboxSupported !== undefined && { sandboxSupported }),
    ...(networkAllowlistInfo?.hasDefaults !== undefined && {
      sandboxNetworkHasDefaults: networkAllowlistInfo.hasDefaults,
    }),
    ...(networkAllowlistInfo?.explicitEntries &&
      networkAllowlistInfo.explicitEntries.length > 0 && {
        sandboxNetworkExplicitAllowlist: networkAllowlistInfo.explicitEntries,
      }),
    ...(getComputerUseSupported !== undefined && {
      computerUseSupported: getComputerUseSupported(),
    }),
    ...(isWorkingDirHomeDir !== undefined && { isWorkingDirHomeDir }),
  });
}

