const MCP_AUTH_INPUT_SCHEMA = {
  type: "object",
  properties: {},
  additionalProperties: false,
} as const;

export function buildLegacyMcpRequestContextFields(
  mcpState: McpState,
  options?: {
    /**
     * When true, only tools from internal browser providers
     * (BROWSER_MCP_PROVIDER_IDS) are kept in the legacy `tools` field.
     * In MCP meta-tool mode every external server is discovered/invoked via
     * GetMcpTools/CallMcpTool and never reads this field, but the browser and
     * computer-use subagents still materialize direct tools (with schemas)
     * from `props.mcpTools`, which is fed by this field on the IDE path.
     */
    internalBrowserProvidersOnly?: boolean;
    /** Carry schemas as flat `inputSchemaJson` strings. */
    inputSchemaJson?: boolean;
  }
): {
  tools: McpToolDefinition[];
  mcpInstructions: McpInstructions[];
} {
  const servers =
    options?.internalBrowserProvidersOnly === true
      ? mcpState.servers.filter(server =>
          BROWSER_MCP_PROVIDER_IDS.has(server.serverIdentifier)
        )
      : mcpState.servers;
  return {
    tools: servers
      .flatMap(server => server.tools)
      .map(
        tool =>
          new McpToolDefinition({
            name: tool.name,
            providerIdentifier: tool.providerIdentifier,
            toolName: tool.toolName,
            description: tool.description,
            ...(options?.inputSchemaJson === true
              ? {
                  inputSchemaJson:
                    tool.inputSchema === undefined
                      ? undefined
                      : JSON.stringify(tool.inputSchema),
                }
              : {
                  inputSchema: tool.inputSchema
                    ? Value.fromJson(tool.inputSchema)
                    : undefined,
                }),
          })
      ),
    // Instructions stay unfiltered: the prompt renders them via a separate
    // McpInstructionsSection and they are small relative to tool schemas.
    mcpInstructions: mcpState.servers.flatMap(server => server.instructions),
  };
}

export function buildMcpMetaToolOptions(
  mcpState: McpState,
  options?: {
    alwaysExposeVirtualMcpAuthTool?: boolean;
    /**
     * When true, per-tool descriptions and input schemas are omitted from the
     * descriptors. The prompt snapshot and CallMcpTool routing only need
     * server metadata plus tool names; GetMcpTools fetches full definitions
     * live via McpStateExecutor at discovery time. Slimming avoids re-sending
     * every tool schema on each request-context upload.
     */
    slimDescriptors?: boolean;
    /** Carry schemas as flat `inputSchemaJson` strings when not slimmed. */
    inputSchemaJson?: boolean;
  }
): McpMetaToolOptions {
  const slimDescriptors = options?.slimDescriptors === true;
  const mcpDescriptors = mcpState.servers.map(server => {
    const instructions = server.instructions
      .map(i => i.instructions)
      .filter(Boolean)
      .join("\n");

    const toolDescriptors = server.tools.map(
      tool =>
        new McpToolDescriptor({
          toolName: tool.toolName,
          // Annotations are tiny and behavior-relevant (e.g. steer-aware
          // release gates on readOnlyHint), so they are carried even in slim
          // descriptor mode.
          ...toolAnnotationsJsonField(tool.annotations),
          ...(slimDescriptors
            ? {}
            : {
                description: tool.description,
                ...(options?.inputSchemaJson === true
                  ? {
                      inputSchemaJson:
                        tool.inputSchema === undefined
                          ? undefined
                          : JSON.stringify(tool.inputSchema),
                    }
                  : {
                      inputSchema:
                        tool.inputSchema !== undefined
                          ? Value.fromJson(tool.inputSchema)
                          : undefined,
                    }),
              }),
        })
    );

    if (
      supportsInteractiveMcpAuth(server.serverIdentifier) &&
      (options?.alwaysExposeVirtualMcpAuthTool === true ||
        server.status === "needsAuth") &&
      !toolDescriptors.some(tool => tool.toolName === MCP_AUTH_TOOL_NAME)
    ) {
      toolDescriptors.push(
        new McpToolDescriptor({
          toolName: MCP_AUTH_TOOL_NAME,
          ...(slimDescriptors
            ? {}
            : {
                description: DEFAULT_MCP_AUTH_TOOL_DESCRIPTION,
                ...(options?.inputSchemaJson === true
                  ? {
                      inputSchemaJson: JSON.stringify(MCP_AUTH_INPUT_SCHEMA),
                    }
                  : {
                      inputSchema: Value.fromJson(MCP_AUTH_INPUT_SCHEMA),
                    }),
              }),
        })
      );
    }

    return new McpDescriptor({
      serverIdentifier: server.serverIdentifier,
      serverName: server.serverName,
      plugin: server.plugin,
      marketplace: server.marketplace,
      pluginDbId: server.pluginId,
      marketplaceId: server.marketplaceId,
      serverUseInstructions: instructions || undefined,
      tools: toolDescriptors,
    });
  });

  return new McpMetaToolOptions({ enabled: true, mcpDescriptors });
}

function normalizeIdentifier(
  identifier: string | undefined
): string | undefined {
  const trimmed = identifier?.trim();
  return trimmed ? trimmed : undefined;
}

function getInstructionServerIdentifier(
  instruction: McpInstructions
): string | undefined {
  return normalizeIdentifier(instruction.serverIdentifier);
}

function resolveInstructionIdentifier(
  instruction: McpInstructions,
  providerIdentifierToClientKey: Map<string, string>
): string | undefined {
  const explicitIdentifier = getInstructionServerIdentifier(instruction);
  if (explicitIdentifier) {
    return explicitIdentifier;
  }
  const serverName = normalizeIdentifier(instruction.serverName);
  if (!serverName) {
    return undefined;
  }
  return providerIdentifierToClientKey.get(serverName) ?? serverName;
}

/** Max time to wait for an in-flight MCP refresh before returning stale cache. */
const MCP_STATE_STALE_WHILE_REVALIDATE_MS = 150;

interface McpClientStatusInfo {
  status: McpServerStatus;
  errorMessage?: string;
}

function buildMcpState(
  tools: NamedMcpToolDefinition[],
  instructions: McpInstructions[],
  clientStatuses?: Map<string, McpClientStatusInfo>
): McpState {
  const providerIdentifierToClientKey = new Map<string, string>();
  for (const tool of tools) {
    if (!providerIdentifierToClientKey.has(tool.providerIdentifier)) {
      providerIdentifierToClientKey.set(
        tool.providerIdentifier,
        tool.clientKey
      );
    }
  }

  const instructionIdentifiers = instructions
    .map(instruction =>
      resolveInstructionIdentifier(instruction, providerIdentifierToClientKey)
    )
    .filter((identifier): identifier is string => Boolean(identifier));

  const serverIdentifiers = [
    ...new Set([
      ...tools.map(tool => tool.clientKey),
      ...instructionIdentifiers,
      ...Array.from(clientStatuses?.entries() ?? [])
        .filter(([, info]) => info.status !== "connected")
        .map(([identifier]) => identifier),
    ]),
  ];

  const result = {
    servers: serverIdentifiers.map(serverIdentifier => {
      const serverTools = tools.filter(
        tool => tool.clientKey === serverIdentifier
      );
      // Use display name (providerIdentifier) from tools so allowlist and mcp.json match.
      // serverIdentifier is the clientKey (e.g. user-ios_server); providerIdentifier is the display name (e.g. ios_server).
      const serverName = serverTools[0]?.providerIdentifier ?? serverIdentifier;
      return {
        serverName,
        serverIdentifier,
        plugin: serverTools[0]?.plugin,
        marketplace: serverTools[0]?.marketplace,
        tools: serverTools,
        instructions: instructions.filter(
          instruction =>
            resolveInstructionIdentifier(
              instruction,
              providerIdentifierToClientKey
            ) === serverIdentifier
        ),
        status: clientStatuses?.get(serverIdentifier)?.status,
        errorMessage: clientStatuses?.get(serverIdentifier)?.errorMessage,
      };
    }),
  };
  return result;
}

async function computeMcpClientStatuses(
  ctx: Context,
  lease: McpLease
): Promise<Map<string, McpClientStatusInfo>> {
  const clients = await lease.getClients(ctx).catch(error => {
    logger.warn(ctx, "Error fetching MCP clients", { error });
    return {};
  });

  const entries = await Promise.all(
    Object.entries(clients).map(async ([serverIdentifier, client]) => {
      const state = await client.getState(ctx).catch(
        () =>
          ({
            kind: "error",
            message: "Failed to fetch MCP client state",
          }) as McpClientState
      );

      const info: McpClientStatusInfo = {
        status: mcpClientStateToServerStatus(state),
        errorMessage:
          state.kind === "error" && state.message !== undefined
            ? state.message
            : undefined,
      };
      return [serverIdentifier, info] as const;
    })
  );

  return new Map(entries);
}

export class SimpleMcpStateAccessor implements McpStateAccessor {
  constructor(private readonly mcpLease: McpLease) {}

  async getState(ctx: Context): Promise<McpState> {
    const [tools, instructions] = await Promise.all([
      this.mcpLease.getTools(ctx).catch(error => {
        logger.warn(ctx, "Error fetching MCP tools", { error });
        return [];
      }),
      this.mcpLease.getInstructions(ctx).catch(error => {
        logger.warn(ctx, "Error fetching MCP instructions", { error });
        return [];
      }),
    ]);

    const clientStatuses = await computeMcpClientStatuses(ctx, this.mcpLease);

    return buildMcpState(tools, instructions, clientStatuses);
  }
}

/**
 * An McpStateAccessor that listens to ObservableMcpLease changes and
 * caches the MCP state, re-populating it whenever the lease signals a change.
 * Optimistically fetches tools/instructions when the lease changes.
 *
 * Uses stale-while-revalidate: we do **not** clear the cache on every lease
 * signal, so callers usually see the last good snapshot immediately while a
 * refresh runs in the background. (Previously, clearing the cache and
 * returning `{ servers: [] }` while a compute was in flight could strip MCP
 * from the agent prompt.)
 */
export class ObservableMcpStateAccessor implements McpStateAccessor {
  private cachedState: McpState | undefined;
  private currentRefresh:
    | {
        id: number;
        promise: Promise<McpState>;
      }
    | undefined;
  private pendingRefreshRequested = false;
  private nextRefreshId = 0;
  private disposed: boolean = false;
  private readonly disposeSubscription: () => void;
  private readonly listeners = new Set<() => void>();

  constructor(private readonly mcpLease: ObservableMcpLease) {
    const subscription = this.mcpLease.onDidChange(
      (e?: McpLeaseChangeEvent) => {
        this.onLeaseChanged(e);
      }
    );
    this.disposeSubscription = () => subscription.dispose();

    // Eagerly fetch tools/instructions on startup
    this.onLeaseChanged(undefined);
  }

  private startRefresh(ctx: Context): Promise<McpState> {
    const refresh = {
      id: ++this.nextRefreshId,
      promise: this.computeState(ctx),
    };
    this.currentRefresh = refresh;

    refresh.promise.then(
      state => {
        // Only the most recent refresh may update the cache or clear the
        // in-flight marker. This keeps lease-driven and demand-driven refreshes
        // under one ownership model.
        if (!this.disposed && this.currentRefresh?.id === refresh.id) {
          this.cachedState = state;
          this.currentRefresh = undefined;
          this.emitChange();
          if (this.pendingRefreshRequested) {
            this.pendingRefreshRequested = false;
            void this.startRefresh(createContext());
          }
        }
      },
      _error => {
        if (this.currentRefresh?.id === refresh.id) {
          this.currentRefresh = undefined;
          if (!this.disposed && this.pendingRefreshRequested) {
            this.pendingRefreshRequested = false;
            void this.startRefresh(createContext());
          }
        }
        // Error is already logged in computeState, no need to rethrow.
      }
    );

    return refresh.promise;
  }

  onDidChange(listener: () => void): Disposable {
    this.listeners.add(listener);
    return {
      dispose: () => {
        this.listeners.delete(listener);
      },
    };
  }

  private emitChange(): void {
    for (const listener of this.listeners) {
      try {
        listener();
      } catch (error) {
        console.error("Error in MCP state change listener:", error);
      }
    }
  }

  private onLeaseChanged(_e?: McpLeaseChangeEvent): void {
    const ctx = createContext();
    // Optimistically start fetching tools/instructions in the background; keep
    // serving the previous cachedState until this completes (stale-while-revalidate).
    if (this.currentRefresh !== undefined) {
      this.pendingRefreshRequested = true;
      return;
    }
    this.startRefresh(ctx);
  }

  /**
   * Reuse an in-flight refresh if it finishes quickly; otherwise return
   * undefined so callers can continue without blocking indefinitely.
   */
  private async awaitRefreshResultBounded(
    refresh: Promise<McpState>
  ): Promise<McpState | undefined> {
    try {
      return await Promise.race([
        refresh,
        new Promise<undefined>(resolve =>
          setTimeout(
            () => resolve(undefined),
            MCP_STATE_STALE_WHILE_REVALIDATE_MS
          )
        ),
      ]);
    } catch {
      /* computeState already logs */
      return undefined;
    }
  }

  /**
   * Force-refresh the cached state. Use after dynamically loading MCP servers
   * (e.g. loadSessionMcpServers) to ensure the next getState() returns fresh
   * state including the new servers. This is necessary because stale-while-
   * revalidate returns old cachedState immediately, which would cause
   * CallMcpTool to fail with "MCP server does not exist" for servers loaded
   * after the initial cache was populated.
   */
  async refreshNow(ctx: Context): Promise<void> {
    this.pendingRefreshRequested = false;
    try {
      await this.startRefresh(ctx);
    } catch {
      // computeState logs errors internally
    }
  }

  async getState(ctx: Context): Promise<McpState> {
    if (this.disposed) {
      throw new Error("ObservableMcpStateAccessor has been disposed");
    }

    // Stale-while-revalidate: we no longer clear the cache on lease change, so a hit
    // here is the normal case — return immediately while `onLeaseChanged` may still
    // be refreshing in the background.
    if (this.cachedState !== undefined) {
      return this.cachedState;
    }

    // Cold start / first caller: briefly wait for an in-flight lease-driven refresh
    // (e.g. constructor's eager fetch) before starting another compute.
    // Unlike the old empty-cache path, we do not return `{ servers: [] }` here;
    // we either pick up the async refresh result or fall through to computeState.
    const inFlightRefresh = this.currentRefresh;
    if (inFlightRefresh) {
      const reused = await this.awaitRefreshResultBounded(
        inFlightRefresh.promise
      );
      if (reused !== undefined) {
        return reused;
      }
      if (this.cachedState !== undefined) {
        return this.cachedState;
      }
      if (this.currentRefresh?.id === inFlightRefresh.id) {
        return { servers: [] };
      }
    }

    // No cache yet and no refresh in flight — compute now and await (this path
    // may block briefly, but remains bounded to avoid indefinite hangs if
    // MCP providers are stalled.
    const started = this.startRefresh(ctx);
    const startedResult = await this.awaitRefreshResultBounded(started);
    if (startedResult !== undefined) {
      return startedResult;
    }
    if (this.cachedState !== undefined) {
      return this.cachedState;
    }
    return { servers: [] };
  }

  private async computeState(ctx: Context): Promise<McpState> {
    const [tools, instructions] = await Promise.all([
      this.mcpLease.getTools(ctx).catch(error => {
        console.error("Error fetching MCP tools:", error);
        return [];
      }),
      this.mcpLease.getInstructions(ctx).catch(error => {
        console.error("Error fetching MCP instructions:", error);
        return [];
      }),
    ]);

    const clientStatuses = await computeMcpClientStatuses(ctx, this.mcpLease);

    return buildMcpState(tools, instructions, clientStatuses);
  }

  dispose(): void {
    if (this.disposed) {
      return;
    }
    this.disposed = true;
    this.disposeSubscription();
    this.listeners.clear();
    this.cachedState = undefined;
    this.currentRefresh = undefined;
  }
}

function buildMcpStateExecResult(mcpState: McpState): McpStateExecResult {
  return new McpStateExecResult({
    result: {
      case: "success",
      value: new McpStateSuccess({
        servers: mcpState.servers.map(
          server =>
            new McpStateServer({
              serverName: server.serverName,
              serverIdentifier: server.serverIdentifier,
              plugin: server.plugin,
              marketplace: server.marketplace,
              tools: server.tools.map(
                tool =>
                  new McpToolDefinition({
                    name: tool.name,
                    providerIdentifier: tool.providerIdentifier,
                    toolName: tool.toolName,
                    description: tool.description,
                    inputSchema: tool.inputSchema
                      ? Value.fromJson(tool.inputSchema)
                      : undefined,
                  })
              ),
              instructions: server.instructions,
              status: server.status,
              errorMessage: server.errorMessage,
            })
        ),
      }),
    },
  });
}

export class LocalMcpStateExecutor implements McpStateExecutor {
  constructor(
    private readonly mcpStateAccessor: McpStateAccessor,
    private readonly ensureMcpServersLoaded?: (
      ctx: Context,
      serverIdentifiers: readonly string[],
      options?: { wait?: boolean }
    ) => Promise<void>,
    private readonly options?: {
      /**
       * When true (gated by mcp_meta_tool_slim_descriptors), scoped requests
       * return only the requested servers instead of the full MCP state.
       * GetMcpTools single-server lookups only need that server's
       * definitions, so shipping every server's schemas on each exec is pure
       * overhead. When no requested identifier matches, the full state is
       * returned so the caller can render "server not found" errors that
       * list the available servers.
       */
      filterToRequestedServers?: boolean;
    }
  ) {}

  async execute(
    ctx: Context,
    args: McpStateExecArgs
  ): Promise<McpStateExecResult> {
    try {
      await this.ensureMcpServersLoaded?.(ctx, args.serverIdentifiers, {
        wait: !args.kickOnly,
      });
    } catch {}
    const mcpState = await this.mcpStateAccessor.getState(ctx);
    if (
      this.options?.filterToRequestedServers === true &&
      args.serverIdentifiers.length > 0
    ) {
      const requested = new Set(args.serverIdentifiers);
      const servers = mcpState.servers.filter(server =>
        requested.has(server.serverIdentifier)
      );
      if (servers.length > 0) {
        return buildMcpStateExecResult({ ...mcpState, servers });
      }
    }
    return buildMcpStateExecResult(mcpState);
  }
}

export interface LocalRequestContextExecutorOptions {
  /** Optional project directory for storing agent files */
  projectDir?: string;
  /** Whether this runtime should select Smart Mode classifier-backed Auto. */
  getSmartModeClassifierAutoModeEnabled?: () => boolean;
  /**
   * Hard admin command denylist from team settings, snapshotted onto each
   * turn's request context for the model-facing Shell precheck.
   */
  getAdminCommandDenylist?: () => Promise<{ rules: string[] }>;
  /** Development-only one-shot token that forces the next Smart Mode classifier run to block. */
  devForceNextSmartModeClassifierBlockToken?: string;
  /** Whether the current working directory is the user's home directory. */
  isWorkingDirHomeDir?: boolean;
  /** Optional callback to create file watchers for cache invalidation */
  createFileWatcher?: CreateFileWatcherCallback;
  /** Optional callback to check if sandbox is enabled */
  getSandboxEnabled?: () => boolean;
  /** Optional callback to check if the environment supports running in a sandbox. */
  getSandboxSupported?: () => boolean;
  /**
   * Optional callback to get network allowlist info for sandbox prompt generation.
   * When provided, the model is informed about available network access in the sandbox.
   */
  getNetworkAllowlistInfo?: () => Promise<NetworkAllowlistInfo>;
  /** Optional hint for the user's preferred terminal */
  userTerminalHint?: string;
  /**
   * Optional callback to get MCP file system options.
   * If not provided, mcpFileSystemOptions will be undefined in the request context.
   */
  getMcpFileSystemOptions?: (
    ctx: Context,
    options?: { timeoutMs?: number }
  ) => Promise<McpFileSystemOptions | undefined>;
  /** Client-side opt-in for MCP meta-tool discovery mode. */
  mcpMetaToolEnabled?: boolean;
  /** When true, meta-tool descriptors omit per-tool descriptions/schemas (names only). */
  mcpMetaToolSlimDescriptors?: boolean;
  /** When true, remaining MCP schemas use flat `inputSchemaJson` strings. */
  mcpInputSchemaJson?: boolean;
  /** When true, synthetic `mcp_auth` is listed for every MCP server in the meta-tool descriptor. */
  alwaysExposeVirtualMcpAuthTool?: boolean;
  /** Resolve the artifacts folder reported for the current request. */
  getArtifactsFolder?: ArtifactsFolderResolver;
  /** Whether secret redaction is enabled for reads in this environment. */
  secretRedactionEnabled?: boolean;
  /** Config provider for reading CLI attribution settings */
  attributionConfigProvider?: AttributionConfigProvider;
  /**
   * Optional callback used by agent-cli to enforce admin attribution controls.
   * When true, local attribution settings are ignored and attribution is disabled.
   */
  isAttributionDisabledByAdmin?: () => Promise<boolean>;
  getAgentSkills?: (ctx: Context) => Promise<AgentSkill[]>;
  /** Extra rules prepended to the rules list (e.g. glass root workspace guidance). */
  additionalRules?: CursorRule[];
  /** Cloud/exec-daemon: true when X11 computer-use executor is running. */
  getComputerUseSupported?: () => boolean;
}

export class LocalRequestContextExecutor implements RequestContextExecutor {
  private readonly getSandboxEnabled?: () => boolean;
  private readonly getSandboxSupported?: () => boolean;
  private readonly getNetworkAllowlistInfo?: () => Promise<NetworkAllowlistInfo>;
  private readonly getSmartModeClassifierAutoModeEnabled?: () => boolean;
  private readonly getAdminCommandDenylist?: LocalRequestContextExecutorOptions["getAdminCommandDenylist"];
  private readonly devForceNextSmartModeClassifierBlockToken?: string;
  private readonly projectDir?: string;
  private readonly isWorkingDirHomeDir?: boolean;
  private readonly userTerminalHint?: string;
  private readonly getMcpFileSystemOptions?: (
    ctx: Context,
    options?: { timeoutMs?: number }
  ) => Promise<McpFileSystemOptions | undefined>;
  private readonly mcpMetaToolEnabled: boolean;
  private readonly mcpMetaToolSlimDescriptors: boolean;
  private readonly mcpInputSchemaJson: boolean;
  private readonly alwaysExposeVirtualMcpAuthTool: boolean;
  private readonly getArtifactsFolder: ArtifactsFolderResolver | undefined;
  private readonly secretRedactionEnabled?: boolean;
  private readonly attributionConfigProvider?: AttributionConfigProvider;
  private readonly isAttributionDisabledByAdmin?: () => Promise<boolean>;
  private readonly getAgentSkills?: (ctx: Context) => Promise<AgentSkill[]>;
  private readonly additionalRules: CursorRule[];
  private readonly getComputerUseSupported?: () => boolean;

  /** Global cache for non-workspace-specific data */
  private readonly cachedWorkspaces = new Map<string, WorkspaceCache>();
  private readonly inFlightWorkspaceWarms = new Map<string, Promise<void>>();
  private globalCache?: Promise<GlobalCacheData>;
  private globalCacheTraceId?: string;
  private cacheDebounceTimeout?: NodeJS.Timeout;

  private fileWatcher?: RequestContextFileWatcher;

  constructor(
    private readonly cursorRulesService: CursorRulesService,
    private readonly cloudRulesService: CloudRulesService | undefined,
    private readonly subagentsService: SubagentsService | undefined,
    private readonly repositoryProvider: IndexingCodebaseReferenceProvider,
    private readonly grepProvider: GrepProvider,
    private readonly mcpStateAccessor: McpStateAccessor,
    private readonly gitExecutor: GitExecutor,
    private readonly workspacePaths: string[],
    options: LocalRequestContextExecutorOptions = {}
  ) {
    const {
      projectDir,
      getSmartModeClassifierAutoModeEnabled,
      getAdminCommandDenylist,
      devForceNextSmartModeClassifierBlockToken,
      isWorkingDirHomeDir,
      createFileWatcher,
      getSandboxEnabled,
      getSandboxSupported,
      getNetworkAllowlistInfo,
      userTerminalHint,
      getMcpFileSystemOptions,
      mcpMetaToolEnabled,
      mcpMetaToolSlimDescriptors,
      mcpInputSchemaJson,
      alwaysExposeVirtualMcpAuthTool,
      getArtifactsFolder,
      secretRedactionEnabled,
      attributionConfigProvider,
      isAttributionDisabledByAdmin,
      getAgentSkills,
      additionalRules,
      getComputerUseSupported,
    } = options;

    this.projectDir = projectDir;
    this.isWorkingDirHomeDir = isWorkingDirHomeDir;
    this.getSandboxEnabled = getSandboxEnabled;
    this.getSandboxSupported = getSandboxSupported;
    this.getNetworkAllowlistInfo = getNetworkAllowlistInfo;
    this.getSmartModeClassifierAutoModeEnabled =
      getSmartModeClassifierAutoModeEnabled;
    this.getAdminCommandDenylist = getAdminCommandDenylist;
    this.devForceNextSmartModeClassifierBlockToken =
      devForceNextSmartModeClassifierBlockToken;
    this.userTerminalHint = userTerminalHint;
    this.getMcpFileSystemOptions = getMcpFileSystemOptions;
    this.mcpMetaToolEnabled = mcpMetaToolEnabled ?? false;
    this.mcpMetaToolSlimDescriptors = mcpMetaToolSlimDescriptors ?? false;
    this.mcpInputSchemaJson = mcpInputSchemaJson ?? false;
    this.alwaysExposeVirtualMcpAuthTool =
      alwaysExposeVirtualMcpAuthTool ?? false;
    this.getArtifactsFolder = getArtifactsFolder;
    this.secretRedactionEnabled = secretRedactionEnabled;
    this.attributionConfigProvider = attributionConfigProvider;
    this.isAttributionDisabledByAdmin = isAttributionDisabledByAdmin;
    this.getAgentSkills = getAgentSkills;
    this.additionalRules = additionalRules ?? [];
    this.getComputerUseSupported = getComputerUseSupported;
    this.warmWorkspaceCaches();

    // Always warm the global cache at startup so the first turn doesn't pay for
    // it. File-watcher consumers reuse it and re-warm on change below.
    this.rebuildGlobalCache();

    if (createFileWatcher !== undefined) {
      this.fileWatcher = createFileWatcher();
      this.fileWatcher.onDidChange(fsPath => {
        this.onWorkspacePathChanged(fsPath);
      });
      this.fileWatcher.onDidCreate(fsPath => {
        this.onWorkspacePathChanged(fsPath);
      });
      this.fileWatcher.onDidDelete(fsPath => {
        this.onWorkspacePathChanged(fsPath);
      });
    }
  }

  private onWorkspacePathChanged(_fsPath: string): void {
    this.rebuildAllCaches();
  }

  private getWorkspaceCache(workspacePath: string): WorkspaceCache | undefined {
    return this.cachedWorkspaces.get(workspacePath);
  }

  private warmWorkspaceCaches(): void {
    const ctx = createContext();
    void Promise.all(
      this.workspacePaths.map(workspacePath =>
        this.ensureWorkspaceCacheWarm(ctx, workspacePath)
      )
    );
  }

  private ensureWorkspaceCacheWarm(
    ctx: Context,
    workspacePath: string
  ): Promise<void> {
    if (this.cachedWorkspaces.has(workspacePath)) {
      return Promise.resolve();
    }
    const inFlight = this.inFlightWorkspaceWarms.get(workspacePath);
    if (inFlight !== undefined) {
      return inFlight;
    }

    const warming = this.warmWorkspaceCache(ctx, workspacePath).finally(() => {
      this.inFlightWorkspaceWarms.delete(workspacePath);
    });
    this.inFlightWorkspaceWarms.set(workspacePath, warming);
    return warming;
  }

  private async warmWorkspaceCache(
    ctx: Context,
    workspacePath: string
  ): Promise<void> {
    using span = createSpan(
      ctx.withName("LocalRequestContextExecutor.warmWorkspaceCache")
    );

    const repoPath = await getGitRepoPathForWorkspacePath(
      span.ctx,
      this.gitExecutor,
      workspacePath
    );

    const remoteUrl = repoPath
      ? await getGitRemoteUrl(span.ctx, this.gitExecutor, repoPath)
      : undefined;

    const workspaceCache = {
      repoPath: repoPath ?? undefined,
      remoteUrl:
        remoteUrl !== undefined ? sanitizeGitRemoteUrl(remoteUrl) : undefined,
    };
    this.cachedWorkspaces.set(workspacePath, workspaceCache);
  }

  /**
   * Rebuild all caches (both global and per-workspace).
   * Called on initial load or when no specific changed paths are provided.
   */
  rebuildAllCaches(): void {
    if (this.cacheDebounceTimeout) {
      clearTimeout(this.cacheDebounceTimeout);
    }

    this.cacheDebounceTimeout = setTimeout(() => {
      this.cacheDebounceTimeout = undefined;
      this.rebuildGlobalCache();
    }, 5000);
  }

  /**
   * Rebuild the global cache (non-workspace-specific data).
   */
  private rebuildGlobalCache(): void {
    const ctx = createContext();
    using span = createSpan(
      ctx.withName("LocalRequestContextExecutor.rebuildGlobalCache")
    );
    this.globalCacheTraceId = span.span.spanContext().traceId;
    this.globalCache = this.computeGlobalCache(span.ctx);
  }

  /**
   * Compute global cache data (shared across all workspaces).
   */
  private async computeGlobalCache(ctx: Context): Promise<GlobalCacheData> {
    using span = createSpan(
      ctx.withName("LocalRequestContextExecutor.computeGlobalCache")
    );

    const signal = AbortSignal.timeout(1000);
    const startMs = performance.now();
    const timings: Record<string, number> = {};

    const timed = <T>(label: string, p: Promise<T>): Promise<T> => {
      const t0 = performance.now();
      return p.finally(() => {
        timings[label] = Math.round(performance.now() - t0);
      });
    };

    const [rules, cloudRule, codebaseReference, customSubagents] =
      await Promise.all([
        timed(
          "cursorRules",
          this.cursorRulesService.getAllCursorRules(span.ctx)
        ),
        timed(
          "cloudRule",
          this.cloudRulesService
            ? this.cloudRulesService.getCloudRule(span.ctx)
            : Promise.resolve(null)
        ),
        timed(
          "codebaseRef",
          this.repositoryProvider
            .getCodebaseReference(span.ctx, signal)
            .catch(() => undefined)
        ),
        timed(
          "subagents",
          this.subagentsService
            ? this.subagentsService.getAllSubagents().catch(() => [])
            : Promise.resolve([])
        ),
      ]);

    const totalMs = Math.round(performance.now() - startMs);
    if (totalMs > 1000) {
      logger.warn(span.ctx, "computeGlobalCache: slow", {
        totalMs,
        ...timings,
        ruleCount: rules.length,
      });
    }

    const allRules = [...this.additionalRules, ...rules];

    return {
      rules: allRules,
      cloudRule,
      codebaseReference,
      customSubagents,
    };
  }

  dispose(): void {
    // Clear global debounce timeout
    if (this.cacheDebounceTimeout) {
      clearTimeout(this.cacheDebounceTimeout);
      this.cacheDebounceTimeout = undefined;
    }

    // Unsubscribe from file watcher
    if (this.fileWatcher) {
      this.fileWatcher.dispose();
      this.fileWatcher = undefined;
    }

    // Clear all caches
    this.globalCache = undefined;
  }

  /**
   * Collect git repo info from per-workspace caches, computing if necessary.
   * Deduplicates repos that are shared across multiple workspaces.
   */
  private async collectWorkspaceCaches(ctx: Context): Promise<{
    gitRepos: GitRepoInfo[];
    gitRepoInfoComplete: boolean;
  }> {
    using span = createSpan(
      ctx.withName("LocalRequestContextExecutor.collectWorkspaceCaches")
    );

    // Try to get tracked state from the grep provider first
    let trackedState: Record<string, TrackedState> | undefined;
    if (this.grepProvider.getTrackedState) {
      try {
        trackedState = await this.grepProvider.getTrackedState(
          this.workspacePaths
        );
      } catch {
        // Fall back to computing from scratch
        trackedState = undefined;
      }
    }

    // Collect git repo info from each workspace, deduplicating by repo path
    let gitRepoInfoComplete = true;
    const gitRepos = (
      await Promise.all(
        this.workspacePaths.map(async workspacePath => {
          const workspaceCache = this.getWorkspaceCache(workspacePath);
          if (workspaceCache === undefined) {
            gitRepoInfoComplete = false;
            void this.ensureWorkspaceCacheWarm(span.ctx, workspacePath);
            return undefined;
          }

          const tracked = trackedState?.[workspacePath];
          if (tracked !== undefined) {
            return new GitRepoInfo({
              path: workspaceCache.repoPath,
              status: tracked.gitStatus,
              branchName: tracked.gitBranchName,
              remoteUrl: workspaceCache.remoteUrl,
              isOriginBacked: isOriginBackedRemoteUrl(workspaceCache.remoteUrl),
            });
          }

          if (workspaceCache.repoPath === undefined) {
            return undefined;
          }

          // We enforce a maximum latency budget for collecting repo info via git.
          // This code path is latency-sensitive.
          const { status, branchName } =
            await getGitInfoForRepoPathWithinBudget(
              span.ctx,
              this.gitExecutor,
              workspaceCache.repoPath,
              GIT_INFO_BUDGET_TIMEOUT_MS
            );

          return new GitRepoInfo({
            path: workspaceCache.repoPath,
            status,
            branchName,
            remoteUrl: workspaceCache.remoteUrl,
            isOriginBacked: isOriginBackedRemoteUrl(workspaceCache.remoteUrl),
          });
        })
      )
    ).filter((repo): repo is GitRepoInfo => repo !== undefined);

    return { gitRepos, gitRepoInfoComplete };
  }

  private async computeCachedRequestContext(
    ctxt: Context,
    args: RequestContextArgs
  ) {
    using span = createSpan(
      ctxt.withName("LocalRequestContextExecutor.computeCachedRequestContext")
    );

    const projectDir = this.projectDir;

    // Get global cache (or compute if not available)
    const getGlobalData = async () => {
      using cacheSpan = createSpan(
        span.ctx.withName(
          "LocalRequestContextExecutor.computeCachedRequestContext.getGlobalData"
        )
      );
      if (this.globalCacheTraceId) {
        cacheSpan.span.setAttribute("cacheTraceId", this.globalCacheTraceId);
      }
      // Memoize for the process lifetime so we don't recompute every turn.
      // File-watcher consumers still invalidate via rebuildGlobalCache. Don't
      // cache a rejection: clear it so the next turn retries instead of failing
      // forever.
      if (this.globalCache === undefined) {
        const pending = this.computeGlobalCache(span.ctx);
        this.globalCache = pending;
        pending.catch(() => {
          if (this.globalCache === pending) {
            this.globalCache = undefined;
          }
        });
      }
      return this.globalCache;
    };

    // Collect everything in a single parallel fan-out: the global cache, MCP
    // state, workspace/session data, and the formerly-serial tail (MCP
    // filesystem options, attribution, agent skills). All of these are
    // independent of one another, so running the tail after the main batch only
    // added its latency onto the critical path. Per-substep timings are
    // recorded as span attributes so the cold-build breakdown is visible in
    // tracing without extra round trips.
    const startMs = performance.now();
    const timings: Record<string, number> = {};
    const timed = <T>(label: string, p: Promise<T>): Promise<T> => {
      const t0 = performance.now();
      return p.finally(() => {
        timings[label] = Math.round(performance.now() - t0);
      });
    };

    const [
      globalData,
      mcp,
      env,
      { gitRepos, gitRepoInfoComplete },
      conversationNotesListing,
      sharedNotesListing,
      mcpFileSystemOptions,
      attributionDisabledByAdmin,
      agentSkills,
      adminCommandDenylist,
    ] = await Promise.all([
      timed("globalCache", getGlobalData()),
      timed("mcpState", this.mcpStateAccessor.getState(span.ctx)),
      timed(
        "env",
        computeEnv(span.ctx, this.workspacePaths, {
          projectDir,
          notesSessionId: args.notesSessionId,
          metaAgentNotesEnabled: false,
          getSmartModeClassifierAutoModeEnabled:
            this.getSmartModeClassifierAutoModeEnabled,
          devForceNextSmartModeClassifierBlockToken:
            this.devForceNextSmartModeClassifierBlockToken,
          isWorkingDirHomeDir: this.isWorkingDirHomeDir,
          getSandboxEnabled: this.getSandboxEnabled,
          getSandboxSupported: this.getSandboxSupported,
          getNetworkAllowlistInfo: this.getNetworkAllowlistInfo,
          userTerminalHint: this.userTerminalHint,
          artifactsFolder: this.getArtifactsFolder?.(span.ctx),
          secretRedactionEnabled: this.secretRedactionEnabled,
          getComputerUseSupported: this.getComputerUseSupported,
        })
      ),
      timed("git", this.collectWorkspaceCaches(span.ctx)),
      timed(
        "conversationNotes",
        projectDir && args.notesSessionId
          ? generateConversationNotesTreeListing(
              projectDir,
              args.notesSessionId
            )
          : Promise.resolve(undefined)
      ),
      timed(
        "sharedNotes",
        projectDir
          ? generateSharedNotesTreeListing(projectDir)
          : Promise.resolve(undefined)
      ),
      timed(
        "mcpFileSystemOptions",
        this.getMcpFileSystemOptions
          ? this.getMcpFileSystemOptions(span.ctx, { timeoutMs: 3_000 })
          : Promise.resolve(undefined)
      ),
      timed(
        "attribution",
        this.isAttributionDisabledByAdmin
          ? this.isAttributionDisabledByAdmin().catch(() => true)
          : Promise.resolve(false)
      ),
      timed(
        "agentSkills",
        this.getAgentSkills
          ? this.getAgentSkills(span.ctx)
          : Promise.resolve<AgentSkill[]>([])
      ),
      timed(
        "adminCommandDenylist",
        this.getAdminCommandDenylist
          ? this.getAdminCommandDenylist()
          : Promise.resolve(undefined)
      ),
    ]);

    const parallelMs = performance.now() - startMs;
    for (const [label, value] of Object.entries(timings)) {
      span.span.setAttribute(`requestContext.timing.${label}Ms`, value);
    }
    span.span.setAttribute(
      "requestContext.timing.totalMs",
      Math.round(parallelMs)
    );
    if (parallelMs > 1000) {
      logger.warn(
        span.ctx,
        "computeCachedRequestContext: slow parallel data collection",
        {
          durationMs: Math.round(parallelMs),
          ...timings,
        }
      );
    }

    const mcpMetaToolOptions = this.mcpMetaToolEnabled
      ? buildMcpMetaToolOptions(mcp, {
          alwaysExposeVirtualMcpAuthTool: this.alwaysExposeVirtualMcpAuthTool,
          slimDescriptors: this.mcpMetaToolSlimDescriptors,
          inputSchemaJson: this.mcpInputSchemaJson,
        })
      : undefined;

    // Get attribution settings from config if available
    const config = this.attributionConfigProvider?.get();
    const attributeCommitsToAgent = attributionDisabledByAdmin
      ? false
      : (config?.attribution?.attributeCommitsToAgent ?? true);
    const attributePRsToAgent = attributionDisabledByAdmin
      ? false
      : (config?.attribution?.attributePRsToAgent ?? true);
    const requestContext = new RequestContext({
      rules: globalData.rules,
      env,
      gitRepos,
      gitRepoInfoComplete,
      repositoryInfo: globalData.codebaseReference
        ? [
            {
              relativeWorkspacePath:
                globalData.codebaseReference.relativeWorkspacePath,
              repoName: globalData.codebaseReference.repoName,
              repoOwner: globalData.codebaseReference.repoOwner,
              isTracked: globalData.codebaseReference.isTracked,
              isLocal: globalData.codebaseReference.isLocal,
              orthogonalTransformSeed:
                globalData.codebaseReference.orthogonalTransformSeed,
              pathEncryptionKey: globalData.codebaseReference.pathEncryptionKey,
            },
          ]
        : [],
      ...buildLegacyMcpRequestContextFields(mcp, {
        internalBrowserProvidersOnly:
          this.mcpMetaToolEnabled && this.mcpMetaToolSlimDescriptors,
        inputSchemaJson: this.mcpInputSchemaJson,
      }),
      conversationNotesListing,
      sharedNotesListing,
      customSubagents: globalData.customSubagents,
      mcpFileSystemOptions,
      mcpMetaToolOptions,
      supportsMcpAuth: true,
      commitAttributionMessage: attributeCommitsToAgent ? "enabled" : undefined,
      prAttributionMessage: attributePRsToAgent ? "enabled" : undefined,
      agentSkills,
      adminCommandDenylist: adminCommandDenylist?.rules ?? [],
    });

    if (globalData.cloudRule !== null && globalData.cloudRule !== undefined) {
      requestContext.cloudRule = globalData.cloudRule;
    }

    return requestContext;
  }

  async execute(
    ctx: Context,
    args: RequestContextArgs
  ): Promise<RequestContextResult> {
    using span = createSpan(
      ctx.withName("LocalRequestContextExecutor.execute")
    );
    span.span.setAttribute("enableCaching", this.fileWatcher !== undefined);
    span.span.setAttribute("hasGlobalCache", !!this.globalCache);

    try {
      const requestContext: RequestContext =
        await this.computeCachedRequestContext(span.ctx, args);

      return new RequestContextResult({
        result: {
          case: "success",
          value: new RequestContextSuccess({ requestContext }),
        },
      });
    } catch (error) {
      span.span.recordException(error as Error);
      return new RequestContextResult({
        result: {
          case: "error",
          value: new RequestContextError({
            error: error instanceof Error ? error.message : String(error),
          }),
        },
      });
    }
  }
}
