import { SimpleControlledExecHandler } from "./controlled.js";
import { ExecutorResource } from "./remote.js";
import { createResource } from "./resource-provider.js";
import { createClientDeserializer, createClientSerializer, createServerDeserializer, createServerSerializer, } from "./serialization.js";
export const writeExecutorResource = createResource(execManager => new ExecutorResource(execManager, createServerSerializer("writeArgs"), createClientDeserializer("writeResult")), (implementation, controlledExecManager) => {
    controlledExecManager.register(new SimpleControlledExecHandler(implementation, createServerDeserializer("writeArgs"), createClientSerializer("writeResult")));
});
