import * as Sentry from "@sentry/node";

import {
	gateEnvelopeSend,
	SAND_SENTRY_DSN,
	SandSentryPrivacyGate,
} from "../../shared/observability/sentry.js";
import type { SandProcessFatalKind } from "../process-crash-guard.js";

export type SandDaemonCrashReporter = (error: Error, kind: SandProcessFatalKind) => void;

type SentryEnvelope = Parameters<ReturnType<typeof Sentry.makeNodeTransport>["send"]>[0];

export function initSandSentryDaemon(): SandDaemonCrashReporter | undefined {
	const environment = process.env.SAND_SENTRY_ENVIRONMENT;
	const release = process.env.SAND_SENTRY_RELEASE;
	if (environment === undefined || release === undefined) return undefined;

	try {
		const gate = new SandSentryPrivacyGate<SentryEnvelope>();

		Sentry.init({
			dsn: SAND_SENTRY_DSN,
			environment,
			release,
			includeServerName: false,
			defaultIntegrations: false,
			skipOpenTelemetrySetup: true,
			integrations: [
				Sentry.eventFiltersIntegration(),
				Sentry.functionToStringIntegration(),
				Sentry.linkedErrorsIntegration(),
				Sentry.dedupeIntegration(),
			],
			transport: (transportOptions) => {
				const base = Sentry.makeNodeTransport(transportOptions);
				return {
					...base,
					send: gateEnvelopeSend(gate, (envelope) => base.send(envelope)),
				};
			},
		});

		Sentry.setTag("sand.process", "local-exec-daemon");

		return (error, kind) =>
			void Sentry.captureException(error, {
				level: "fatal",
				tags: { "crash.kind": kind },
			});
	} catch (error) {
		console.error("[sand-local-exec-daemon] Sentry init failed:", error);
		return undefined;
	}
}

export function flushSandSentry(timeoutMs: number): Promise<boolean> {
	return Sentry.flush(timeoutMs);
}
