type Mode = "content" | "files_with_matches" | "count";
const SORT_MODES = ["none", "path", "modified", "accessed", "created"] as const;
type SortMode = (typeof SORT_MODES)[number];

export type WorktreeGuardInfo = {
  mainWorktreePath?: string;
};

function splitLines(s: string): string[] {
  return s.replace(/\r\n/g, "\n").replace(/\r/g, "\n").split("\n");
}

function unresolvedTargetPathError(path: string): string {
  return `Path '${path}' could not be verified while resolving symlinks. This can happen when access is denied or the path contains a symlink loop.`;
}

/**
 * Returns the most specific (deepest) workspace root that contains `targetPath`.
 */
function findOwningWorkspaceRoot(
  targetPath: string,
  workspaceRoots: string[]
): string | undefined {
  let owner: string | undefined;
  for (const candidateRoot of workspaceRoots) {
    if (
      isPathWithin({ basePath: candidateRoot, targetPath }) &&
      (owner === undefined || candidateRoot.length > owner.length)
    ) {
      owner = candidateRoot;
    }
  }
  return owner;
}

/**
 * A file should be reported only under the most specific workspace root that
 * contains it. This avoids duplicates in overlapping/nested roots while
 * preserving the canonical owner for each absolute file path.
 */
function fileBelongsToCurrentWorkspace(
  currentRoot: string,
  filePath: string,
  workspaceRoots: string[]
): boolean {
  const absoluteFilePath = resolve(currentRoot, filePath);
  const owner = findOwningWorkspaceRoot(absoluteFilePath, workspaceRoots);
  return owner === undefined || owner === currentRoot;
}

/**
 * Remove files from each workspace result that physically belong to a different
 * workspace root. This prevents the same file from appearing in multiple
 * workspace sections with different relative paths (e.g. `./foo.py` in one
 * workspace and `../other/foo.py` in another).
 */
export function deduplicateCrossWorkspaceResults(
  workspaceResults: Record<string, GrepUnionResult>,
  workspacePaths: string[]
): Record<string, GrepUnionResult> {
  if (workspacePaths.length <= 1) return workspaceResults;

  const resolvedRoots = [...new Set(workspacePaths.map(root => resolve(root)))];
  const deduped: Record<string, GrepUnionResult> = {};

  for (const [root, unionResult] of Object.entries(workspaceResults)) {
    const resolvedRoot = resolve(root);
    const belongsToCurrentWorkspace = (filePath: string): boolean =>
      fileBelongsToCurrentWorkspace(resolvedRoot, filePath, resolvedRoots);
    const result = unionResult.result;

    switch (result.case) {
      case "content": {
        const original = result.value;
        const filteredMatches: typeof original.matches = [];
        let droppedLineCount = 0;
        let droppedMatchedLines = 0;
        for (const m of original.matches) {
          if (belongsToCurrentWorkspace(m.file)) {
            filteredMatches.push(m);
          } else {
            droppedLineCount += m.matches.length;
            droppedMatchedLines += m.matches.filter(
              line => !line.isContextLine
            ).length;
          }
        }
        deduped[root] = new GrepUnionResult({
          result: {
            case: "content",
            value: new GrepContentResult({
              ...original,
              matches: filteredMatches,
              totalLines: Math.max(0, original.totalLines - droppedLineCount),
              totalMatchedLines: Math.max(
                0,
                original.totalMatchedLines - droppedMatchedLines
              ),
            }),
          },
        });
        break;
      }
      case "files": {
        const original = result.value;
        const filteredFiles = original.files.filter(f =>
          belongsToCurrentWorkspace(f)
        );
        deduped[root] = new GrepUnionResult({
          result: {
            case: "files",
            value: new GrepFilesResult({
              ...original,
              files: filteredFiles,
              totalFiles: Math.max(
                0,
                original.totalFiles -
                  (original.files.length - filteredFiles.length)
              ),
            }),
          },
        });
        break;
      }
      case "count": {
        const original = result.value;
        const filteredCounts: typeof original.counts = [];
        let droppedMatchTotal = 0;
        for (const c of original.counts) {
          if (belongsToCurrentWorkspace(c.file)) {
            filteredCounts.push(c);
          } else {
            droppedMatchTotal += c.count;
          }
        }
        deduped[root] = new GrepUnionResult({
          result: {
            case: "count",
            value: new GrepCountResult({
              ...original,
              counts: filteredCounts,
              totalFiles: Math.max(
                0,
                original.totalFiles -
                  (original.counts.length - filteredCounts.length)
              ),
              totalMatches: Math.max(
                0,
                original.totalMatches - droppedMatchTotal
              ),
            }),
          },
        });
        break;
      }
      default:
        deduped[root] = unionResult;
    }
  }

  return deduped;
}

// files_with_matches parser - returns all files up to internal limits
function parseFilesOutput(
  stdout: string,
  clientLimitLines: number,
  ripgrepHardCuttoffLines: number
): {
  files: string[];
  totalFiles: number;
  clientTruncated: boolean;
  ripgrepTruncated: boolean;
} {
  const trimmed = stdout.trim();
  const lines = trimmed !== "" ? splitLines(trimmed) : [];
  const totalFiles = lines.length;

  const sliced = lines.slice(0, clientLimitLines);
  const clientTruncated = lines.length > clientLimitLines;

  return {
    files: sliced,
    totalFiles: clampInt32(totalFiles),
    clientTruncated,
    ripgrepTruncated: totalFiles >= ripgrepHardCuttoffLines,
  };
}

// count parser: expects lines like "path:count"; split from rightmost ':'
// Returns all counts up to internal limits
export function parseCountOutput(
  stdout: string,
  clientLimitLines: number,
  ripgrepHardCuttoffLines: number
): {
  counts: { file: string; count: number }[];
  totalFiles: number;
  totalMatches: number;
  clientTruncated: boolean;
  ripgrepTruncated: boolean;
} {
  const trimmed = stdout.trim();
  const lines = trimmed !== "" ? splitLines(trimmed) : [];
  const allCounts: { file: string; count: number }[] = [];

  for (const line of lines) {
    if (line === "" || line === undefined) {
      continue;
    }
    const colonIndex = line.lastIndexOf(":");
    if (colonIndex <= 0) {
      continue;
    }
    const countString = line.substring(colonIndex + 1).trim();
    const parsedCount = parseInt(countString, 10);
    if (!Number.isFinite(parsedCount)) {
      continue;
    }
    const filePath = line.substring(0, colonIndex);
    allCounts.push({
      file: filePath,
      count: parsedCount,
    });
  }

  const totalFiles = allCounts.length;
  const totalMatches = allCounts.reduce((acc, count) => acc + count.count, 0);

  const sliced = allCounts.slice(0, clientLimitLines);
  const clientTruncated = allCounts.length > clientLimitLines;

  return {
    counts: sliced,
    totalFiles: clampInt32(totalFiles),
    totalMatches: clampInt32(totalMatches),
    clientTruncated,
    ripgrepTruncated: totalFiles >= ripgrepHardCuttoffLines,
  };
}

// content parser (grouped): expects lines like
// file_path\0<number>-<content>
// file_path\0<number>:<content>
// ... and then a "--" between non-contiguous context chunks
// Returns all content up to internal limits
export function parseContentOutput(
  stdout: string,
  clientLimitLines: number,
  ripgrepHardCuttoffLines: number,
  ctx: Context
): {
  byFile: Map<
    string,
    {
      file: string;
      matches: {
        lineNumber: number;
        content: string;
        isContextLine: boolean;
      }[];
    }
  >;
  totalLines: number;
  totalMatchedLines: number;
  totalFiles: number;
  clientTruncated: boolean;
  ripgrepTruncated: boolean;
} {
  using _span = createSpan(ctx.withName("parseContentOutput"));
  // Only trim if stdout is empty or only whitespace to avoid counting as 0 lines
  // Preserve empty lines that are part of ripgrep's --heading format, so we don't miscount the number
  // of lines produced by ripgrep.
  const lines = stdout.trim() === "" ? [] : splitLines(stdout);

  // Remove final empty line that results from ripgrep stdout always ending with newline
  if (lines.length > 0 && lines[lines.length - 1] === "") {
    lines.pop();
  }

  const byFile = new Map<
    string,
    {
      file: string;
      matches: {
        lineNumber: number;
        content: string;
        isContextLine: boolean;
      }[];
    }
  >();

  // Track all unique files for totalFiles count
  const allFiles = new Set<string>();
  let totalMatchedLines = 0;
  let linesProcessed = 0;

  for (const line of lines) {
    if (line === undefined) {
      continue;
    }
    // Ripgrep prints "--" between non-contiguous context chunks; these are not content
    if (line === "--") {
      continue;
    }
    const [filename, lineContent] = line.split("\x00", 2);
    if (filename === undefined || lineContent === undefined) {
      continue;
    }
    const match = /^(\d+)([:-])(.*)$/.exec(lineContent);
    if (!match) {
      // Unexpected format; skip
      continue;
    }
    const lineNumberRaw = match[1];
    const separator = match[2];
    const content = match[3] ?? "";

    const lineNumber = parseInt(lineNumberRaw, 10);
    if (!Number.isFinite(lineNumber)) {
      continue;
    }
    const isContextLine = separator === "-";

    if (isContextLine === false) {
      totalMatchedLines++;
    }

    // Track this file in allFiles for total count
    if (!allFiles.has(filename)) {
      allFiles.add(filename);
    }

    // Don't add to byFile if we've exceeded the client line limit
    if (linesProcessed >= clientLimitLines) {
      continue;
    }

    const fileResults = byFile.get(filename) ?? {
      file: filename,
      matches: [],
    };
    fileResults.matches.push({ lineNumber, content, isContextLine });
    byFile.set(filename, fileResults);
    linesProcessed++;
  }

  const totalFiles = allFiles.size;
  const result = {
    byFile,
    totalLines: clampInt32(lines.length),
    totalMatchedLines: clampInt32(totalMatchedLines),
    totalFiles: clampInt32(totalFiles),
    clientTruncated: linesProcessed >= clientLimitLines,
    ripgrepTruncated: lines.length >= ripgrepHardCuttoffLines,
  };
  return result;
}

