const logger = createLogger("local-exec/grep");

function isEnoentSpawnError(e: unknown): boolean {
  if (!(e instanceof Error)) return false;
  return e.message.includes("ENOENT") && e.message.includes("spawn");
}

type RipgrepErrorLogContext = {
  toolCallId?: string;
  execId?: string;
  outputMode: Mode;
  targetPath?: string;
  workspacePaths: string[];
};

function safeExists(path: string): boolean | "check_failed" {
  try {
    return existsSync(path);
  } catch {
    return "check_failed";
  }
}

function buildRipgrepEnoentMetadata(
  rgPath: string,
  cwd: string,
  error: NodeJS.ErrnoException,
  logContext: RipgrepErrorLogContext
): Record<string, unknown> {
  return {
    ...probeRipgrepPath(rgPath),
    ...logContext,
    cwd,
    cwdExists: safeExists(cwd),
    errorMessage: error.message,
    errorCode: error.code,
    errno: error.errno,
    syscall: error.syscall,
    errorPath: error.path,
  };
}

function createPathDoesNotExistError(path: string): Error {
  return new Error(`Path does not exist: ${path}`);
}

function probeRipgrepPath(rgPath: string): Record<string, unknown> {
  const probe: Record<string, unknown> = {
    rgPath,
    platform: process.platform,
    arch: process.arch,
    pid: process.pid,
    uptimeSeconds: Math.round(process.uptime()),
    execPath: process.execPath,
  };

  try {
    probe.rgPathExists = existsSync(rgPath);
  } catch (e) {
    probe.rgPathExists = false;
    probe.rgPathExistsError = e instanceof Error ? e.message : String(e);
  }

  // Detect broken symlinks: lstat succeeds on broken symlinks, stat/existsSync don't
  try {
    const lst = lstatSync(rgPath);
    probe.rgIsSymlink = lst.isSymbolicLink();
    if (lst.isSymbolicLink() && !probe.rgPathExists) {
      probe.rgBrokenSymlink = true;
    }
  } catch {
    probe.rgLstatFailed = true;
  }

  const MAX_DIR_ENTRIES = 50;

  const parentDir = dirname(rgPath);
  try {
    probe.parentDirExists = existsSync(parentDir);
    if (probe.parentDirExists) {
      probe.parentDirContents = readdirSync(parentDir).slice(
        0,
        MAX_DIR_ENTRIES
      );
    }
  } catch (e) {
    probe.parentDirError = e instanceof Error ? e.message : String(e);
  }

  const grandparentDir = dirname(parentDir);
  try {
    probe.grandparentDirExists = existsSync(grandparentDir);
    if (probe.grandparentDirExists) {
      probe.grandparentDirContents = readdirSync(grandparentDir).slice(
        0,
        MAX_DIR_ENTRIES
      );
    }
  } catch (e) {
    probe.grandparentDirError = e instanceof Error ? e.message : String(e);
  }

  if (probe.rgPathExists) {
    try {
      const st = statSync(rgPath);
      probe.rgFileSize = st.size;
      probe.rgFileMode = st.mode.toString(8);
      probe.rgIsFile = st.isFile();
      probe.rgModifiedMs = st.mtimeMs;
    } catch (e) {
      probe.rgStatError = e instanceof Error ? e.message : String(e);
    }
  }

  const asarUnpackedSegment = "node_modules.asar.unpacked";
  if (rgPath.includes(asarUnpackedSegment)) {
    const prefix = rgPath.split(asarUnpackedSegment)[0];
    if (prefix) {
      const asarPath = prefix.concat("node_modules.asar");
      try {
        probe.asarExists = existsSync(asarPath);
      } catch {
        probe.asarExists = "check_failed";
      }
      const asarUnpackedDir = prefix.concat(asarUnpackedSegment);
      try {
        probe.asarUnpackedDirExists = existsSync(asarUnpackedDir);
        if (probe.asarUnpackedDirExists) {
          // Check if @vscode/ripgrep is in the unpacked dir
          const ripgrepPkgDir = join(asarUnpackedDir, "@vscode", "ripgrep");
          probe.ripgrepPkgDirExists = existsSync(ripgrepPkgDir);
        }
      } catch {
        probe.asarUnpackedDirExists = "check_failed";
      }
    }
  }

  return probe;
}

export class LocalGrepExecutor implements GrepExecutor {
  private static readonly MAIN_TIMEOUT_MS = 25_000;
  private static readonly INDEXED_GREP_TIMEOUT_MS = 25_000;
  private static readonly INDEXED_GREP_CONTEXT_TIMEOUT_MS =
    LocalGrepExecutor.INDEXED_GREP_TIMEOUT_MS + 100;
  private static readonly HARD_MAX_OUTPUT_LINES = 10_000;
  // Maximum number of lines for the client to store on disk and send to the server
  private static readonly CLIENT_LIMIT_LINES = 2_000;
  private singleWorkspacePath: string | undefined;
  private readonly mcpStateAccessor?: McpStateAccessor;

  constructor(
    private ignoreService: IgnoreService,
    private grepProvider: GrepProvider,
    private workspacePath?: string | string[],
    options?: { mcpStateAccessor?: McpStateAccessor }
  ) {
    const firstWorkspacePath = Array.isArray(this.workspacePath)
      ? this.workspacePath[0]
      : this.workspacePath;

    this.singleWorkspacePath =
      Array.isArray(this.workspacePath) && this.workspacePath.length > 1
        ? undefined
        : firstWorkspacePath;
    this.mcpStateAccessor = options?.mcpStateAccessor;
  }

  computeRelativeTarget(path: string, root: string): string {
    const resolvedPath = resolvePath(path, this.singleWorkspacePath);
    if (resolvedPath === root) {
      return ".";
    }
    const result = relative(root, resolvedPath);
    return result;
  }

  private async buildArgs(
    root: string,
    params: GrepArgs,
    mode: Mode
  ): Promise<string[]> {
    const args: string[] = [];
    // Use the custom --cursor-ignore flag from our ripgrep fork
    // This ensures ignore rules cannot be overridden by glob patterns
    const ignoreFiles =
      await this.ignoreService.listCursorIgnoreFilesByRoot(root);
    for (const ignoreFile of ignoreFiles) {
      args.push("--cursor-ignore", ignoreFile);
    }

    if (mode === "content") {
      args.push("--line-number", "--with-filename", "--no-heading", "-0");
      if (params.contextBefore !== undefined) {
        args.push("--before-context", String(params.contextBefore));
      }
      if (params.contextAfter !== undefined) {
        args.push("--after-context", String(params.contextAfter));
      }
      args.push("--max-columns", String(1000), "--max-columns-preview");
      if (
        params.context !== undefined &&
        params.contextBefore === undefined &&
        params.contextAfter === undefined
      ) {
        args.push(
          "--before-context",
          String(params.context),
          "--after-context",
          String(params.context)
        );
      }
    } else if (mode === "files_with_matches") {
      args.push("-l");
    } else if (mode === "count") {
      // Force path:count format even for one file, as otherwise our parser breaks when single file.
      args.push("-c", "--with-filename");
    } else {
      const _exhaustive: never = mode;
      throw new Error(`Unknown output mode: ${mode}`);
    }

    // Default to case sensitive
    if (params.caseInsensitive === true) {
      args.push("--ignore-case");
    } else {
      args.push("--case-sensitive");
    }

    if (params.type) {
      args.push("--type", params.type);
    }
    if (params.glob) {
      // Use --iglob for case-insensitive glob matching
      args.push("--iglob", params.glob);
    }
    if (params.multiline) {
      args.push("--multiline", "--multiline-dotall");
    }

    const sortMode: SortMode = (params.sort as SortMode) ?? "modified";
    if (sortMode !== "none") {
      // Default to sort descending (e.g. last modified)
      const flag = params.sortAscending === true ? "--sort" : "--sortr";
      args.push(flag, sortMode);
    }

    // Don't use ripgrep config files that the user may have set, and ensure color text is disabled
    args.push("--no-config", "--color=never");

    // Include hidden files and folders so that the agent can find files in e.g. `.cursor/rules`
    args.push("--hidden");

    // Follow symlinked directories so agent Grep and Glob match files the Read tool can access.
    args.push("--follow");

    args.push("--regexp", params.pattern);
    args.push("--"); // Separator for pattern and target
    args.push(
      params.path ? this.computeRelativeTarget(params.path, root) : "."
    );

    return args;
  }

  private async filterBlockedFiles<T extends { file: string }>(
    items: T[],
    root: string
  ): Promise<T[]> {
    const filtered: T[] = [];
    for (const item of items) {
      const resolved = await resolvePathForIgnoreService(
        resolvePath(item.file, root)
      );
      if (resolved === null || (await this.isPostRipgrepBlocked(resolved))) {
        continue;
      }
      filtered.push(item);
    }
    return filtered;
  }

  private async isPostRipgrepBlocked(
    filePath: ResolvedIgnorePath
  ): Promise<boolean> {
    const [cursorIgnored, repoBlocked] = await Promise.all([
      this.ignoreService.isCursorIgnored(filePath),
      this.ignoreService.isRepoBlocked(filePath),
    ]);
    return cursorIgnored || repoBlocked;
  }

  private async runFilesMode(
    ctx: Context,
    root: string,
    params: GrepArgs,
    sandboxPolicy: SandboxPolicy,
    logContext: RipgrepErrorLogContext
  ): Promise<GrepUnionResult> {
    using _span = createSpan(ctx.withName("LocalGrepExecutor.runFilesMode"));
    const args = await this.buildArgs(root, params, "files_with_matches");
    const res = await this.executeRg(
      _span.ctx,
      root,
      args,
      undefined,
      sandboxPolicy,
      logContext
    );
    // Ripgrep writes per-file warnings (permission denied, locked files, NUL
    // device) to stderr but still returns valid results for other files. Only
    // throw when there are NO results to return — otherwise we'd discard valid
    // matches because of one inaccessible file.
    if ((res.stderr !== "" || res.exitCode === 2) && res.stdout.trim() === "") {
      throw new Error(res.stderr || `ripgrep exited with code ${res.exitCode}`);
    }

    const { files, totalFiles, clientTruncated, ripgrepTruncated } =
      parseFilesOutput(
        res.stdout,
        LocalGrepExecutor.CLIENT_LIMIT_LINES,
        LocalGrepExecutor.HARD_MAX_OUTPUT_LINES
      );

    // Ripgrep already applied gitignore together with cursorignore negations;
    // only enforce post-resolution cursorignore/admin repo blocks here.
    const filteredFiles: string[] = [];
    for (const file of files) {
      const resolved = await resolvePathForIgnoreService(
        resolvePath(file, root)
      );
      if (resolved !== null && !(await this.isPostRipgrepBlocked(resolved))) {
        filteredFiles.push(file);
      }
    }

    // Adjust totalFiles to exclude blocked files found in this page
    const blockedFileCount = files.length - filteredFiles.length;
    const filesResult = new GrepFilesResult({
      files: filteredFiles,
      totalFiles: clampInt32(totalFiles - blockedFileCount),
      clientTruncated,
      ripgrepTruncated,
    });
    return new GrepUnionResult({
      result: {
        case: "files",
        value: filesResult,
      },
    });
  }

  private async runCountMode(
    ctx: Context,
    root: string,
    params: GrepArgs,
    sandboxPolicy: SandboxPolicy,
    logContext: RipgrepErrorLogContext
  ): Promise<GrepUnionResult> {
    using _span = createSpan(ctx.withName("LocalGrepExecutor.runCountMode"));
    const args = await this.buildArgs(root, params, "count");
    const res = await this.executeRg(
      _span.ctx,
      root,
      args,
      undefined,
      sandboxPolicy,
      logContext
    );
    if ((res.stderr !== "" || res.exitCode === 2) && res.stdout.trim() === "") {
      throw new Error(res.stderr || `ripgrep exited with code ${res.exitCode}`);
    }

    const {
      counts,
      totalFiles,
      totalMatches,
      clientTruncated,
      ripgrepTruncated,
    } = parseCountOutput(
      res.stdout,
      LocalGrepExecutor.CLIENT_LIMIT_LINES,
      LocalGrepExecutor.HARD_MAX_OUTPUT_LINES
    );

    // Ripgrep already applied gitignore together with cursorignore negations;
    // only enforce post-resolution cursorignore/admin repo blocks here.
    const filteredCounts = await this.filterBlockedFiles(counts, root);
    const filteredTotalMatches = filteredCounts.reduce(
      (sum, c) => sum + c.count,
      0
    );

    // Adjust totals to exclude blocked files/matches found in this page
    const blockedFileCount = counts.length - filteredCounts.length;
    const pageMatchTotal = counts.reduce((sum, c) => sum + c.count, 0);
    const blockedMatchTotal = pageMatchTotal - filteredTotalMatches;

    const countResult = new GrepCountResult({
      counts: filteredCounts.map(
        c => new GrepFileCount({ file: c.file, count: clampInt32(c.count) })
      ),
      totalFiles: clampInt32(totalFiles - blockedFileCount),
      totalMatches: clampInt32(totalMatches - blockedMatchTotal),
      clientTruncated,
      ripgrepTruncated,
    });

    return new GrepUnionResult({
      result: {
        case: "count",
        value: countResult,
      },
    });
  }

  private async runContentMode(
    ctx: Context,
    root: string,
    params: GrepArgs,
    sandboxPolicy: SandboxPolicy,
    logContext: RipgrepErrorLogContext
  ): Promise<GrepUnionResult> {
    using _span = createSpan(ctx.withName("LocalGrepExecutor.runContentMode"));
    const args = await this.buildArgs(root, params, "content");
    const res = await this.executeRg(
      _span.ctx,
      root,
      args,
      undefined,
      sandboxPolicy,
      logContext
    );
    if ((res.stderr !== "" || res.exitCode === 2) && res.stdout.trim() === "") {
      throw new Error(res.stderr || `ripgrep exited with code ${res.exitCode}`);
    }

    const {
      byFile,
      totalLines,
      totalMatchedLines,
      clientTruncated,
      ripgrepTruncated,
    } = parseContentOutput(
      res.stdout,
      LocalGrepExecutor.CLIENT_LIMIT_LINES,
      LocalGrepExecutor.HARD_MAX_OUTPUT_LINES,
      _span.ctx
    );

    // Ripgrep already applied gitignore together with cursorignore negations;
    // only enforce post-resolution cursorignore/admin repo blocks here.
    const entries = Array.from(byFile.values());
    const filteredEntries = await this.filterBlockedFiles(entries, root);

    // Adjust totals to exclude lines from blocked files found in this page
    const blockedEntries = entries.filter(e => !filteredEntries.includes(e));
    const blockedLineCount = blockedEntries.reduce(
      (sum, e) => sum + e.matches.length,
      0
    );
    const blockedMatchedLineCount = blockedEntries.reduce(
      (sum, e) => sum + e.matches.filter(m => !m.isContextLine).length,
      0
    );

    const contentRes = new GrepContentResult({
      matches: filteredEntries.map(
        f =>
          new GrepFileMatch({
            file: f.file,
            matches: f.matches.map(
              m =>
                new GrepContentMatch({
                  lineNumber: m.lineNumber,
                  content: m.content,
                  isContextLine: m.isContextLine,
                })
            ),
          })
      ),
      totalLines: clampInt32(totalLines - blockedLineCount),
      totalMatchedLines: clampInt32(
        totalMatchedLines - blockedMatchedLineCount
      ),
      clientTruncated,
      ripgrepTruncated,
    });
    return new GrepUnionResult({
      result: {
        case: "content",
        value: contentRes,
      },
    });
  }

  private async executeIndexedGrepWithTimeout(
    ctx: Context,
    workspacePaths: string[],
    args: GrepArgs,
    logContext: RipgrepErrorLogContext
  ): Promise<Record<string, GrepUnionResult> | undefined> {
    if (this.grepProvider.executeIndexedGrep === undefined) {
      return undefined;
    }

    const [indexedCtx, cancelIndexedCtx] = ctx.withTimeoutAndCancel(
      LocalGrepExecutor.INDEXED_GREP_CONTEXT_TIMEOUT_MS
    );
    const diagnostics: IndexedGrepDiagnostics = { phase: "provider" };
    const startedAt = performance.now();
    try {
      return await withTimeout(
        this.grepProvider.executeIndexedGrep(
          indexedCtx,
          workspacePaths,
          args,
          diagnostics
        ),
        LocalGrepExecutor.INDEXED_GREP_TIMEOUT_MS,
        `Indexed grep timed out after ${LocalGrepExecutor.INDEXED_GREP_TIMEOUT_MS / 1000}s`
      );
    } catch (error) {
      if (error instanceof TimeoutError) {
        logger.warn(ctx, "indexed_grep.timeout_fallback", {
          ...logContext,
          totalMs: Math.round(performance.now() - startedAt),
          ...diagnostics,
        });
        return undefined;
      }
      throw error;
    } finally {
      cancelIndexedCtx();
    }
  }

  private async executeRg(
    ctx: Context,
    cwd: string,
    args: string[],
    lineBudget: number | undefined,
    sandboxPolicy: SandboxPolicy,
    logContext: RipgrepErrorLogContext
  ): Promise<{ stdout: string; stderr: string; exitCode: number }> {
    // Create span without 'using' so it doesn't auto-dispose when function returns
    // We'll manually end it when the Promise resolves/rejects
    const span = createSpan(ctx.withName("LocalGrepExecutor.executeRg"));
    const enc: BufferEncoding = "utf8";
    const maxBytes: number = 8 * 1024 * 1024; // 8MB cap by default
    lineBudget = lineBudget ?? LocalGrepExecutor.HARD_MAX_OUTPUT_LINES;

    return new Promise<{ stdout: string; stderr: string; exitCode: number }>(
      (resolve, reject) => {
        let exited = false;
        let spanEnded = false;
        const endSpan = (): void => {
          if (!spanEnded) {
            spanEnded = true;
            span.span.end();
          }
        };
        let proc: ReturnType<typeof spawnInSandbox>;
        let timeoutId: NodeJS.Timeout;
        try {
          const p = sandboxPolicy;
          proc = spawnInSandbox(getRipgrepBinaryPath(), args, { cwd }, p);
          if (isRipgrepInvocationRecordingEnabled()) {
            const regexpIdx = args.indexOf("--regexp");
            const patternLength =
              regexpIdx >= 0 && regexpIdx + 1 < args.length
                ? args[regexpIdx + 1].length
                : 0;
            let includeGlobCount = 0;
            for (const a of args) {
              if (a === "--iglob") {
                includeGlobCount++;
              }
            }
            recordRipgrepInvocation({
              timestamp: Date.now(),
              source: "agent_grep_tool",
              mode: logContext.outputMode,
              patternLength,
              hasPath: logContext.targetPath !== undefined,
              includeGlobCount,
              excludeGlobCount: 0,
              sandboxPolicyType: p.type,
              toolCallId: logContext.toolCallId,
              execId: logContext.execId,
            });
          }
        } catch (e) {
          endSpan();
          if (isEnoentSpawnError(e)) {
            const errnoErr = e as NodeJS.ErrnoException;
            const rgPath = getRipgrepBinaryPath();
            logger.error(
              ctx,
              "rg_diagnostics.spawn_throw",
              undefined,
              buildRipgrepEnoentMetadata(rgPath, cwd, errnoErr, logContext)
            );
            if (safeExists(cwd) === false) {
              return reject(createPathDoesNotExistError(cwd));
            }
          }
          return reject(e);
        }

        const chunksStdout: Buffer[] = [];
        const chunksStderr: Buffer[] = [];
        let totalStdout = 0;
        let totalStderr = 0;
        let seenLines = 0;
        let lineBudgetExceeded = false;

        timeoutId = setTimeout(() => {
          if (!exited) {
            try {
              endSpan();
              reject(
                new Error(
                  `Timed out after ${LocalGrepExecutor.MAIN_TIMEOUT_MS / 1000}s`
                )
              );
              proc.kill();
            } catch {
              /* ignore */
            }
          }
        }, LocalGrepExecutor.MAIN_TIMEOUT_MS);

        proc.stdout?.on("data", (d: Buffer) => {
          totalStdout += d.length;

          if (lineBudget !== undefined && lineBudgetExceeded !== true) {
            // Count '\n' in this chunk and find where to truncate
            let truncateIndex = -1;
            let linesInChunk = 0;

            for (let i = 0; i < d.length; i++) {
              if (d[i] === 0x0a) {
                // '\n'
                linesInChunk++;
                if (seenLines + linesInChunk >= lineBudget) {
                  // Include this newline and stop
                  truncateIndex = i + 1;
                  lineBudgetExceeded = true;
                  try {
                    proc.kill();
                  } catch {
                    /* ignore */
                  }
                  break;
                }
              }
            }

            seenLines += linesInChunk;

            const bufferToAdd =
              truncateIndex >= 0 ? d.subarray(0, truncateIndex) : d;

            if (totalStdout <= maxBytes) {
              chunksStdout.push(bufferToAdd);
            }
          } else if (lineBudgetExceeded !== true && totalStdout <= maxBytes) {
            chunksStdout.push(d);
          }
        });
        proc.stderr?.on("data", (d: Buffer) => {
          totalStderr += d.length;
          if (totalStderr <= maxBytes) {
            chunksStderr.push(d);
          }
        });
        proc.on("error", (err: Error) => {
          clearTimeout(timeoutId);
          endSpan();
          if (isEnoentSpawnError(err)) {
            const rgPath = getRipgrepBinaryPath();
            const errnoErr = err as NodeJS.ErrnoException;
            logger.error(
              ctx,
              "rg_diagnostics.spawn_enoent",
              undefined,
              buildRipgrepEnoentMetadata(rgPath, cwd, errnoErr, logContext)
            );
            if (safeExists(cwd) === false) {
              reject(createPathDoesNotExistError(cwd));
              return;
            }
          }
          reject(err);
        });
        proc.on("close", (code: number) => {
          exited = true;
          clearTimeout(timeoutId);
          const stdout: string = Buffer.concat(chunksStdout).toString(enc);
          const stderr: string = Buffer.concat(chunksStderr).toString(enc);
          endSpan();
          resolve({ stdout, stderr, exitCode: code ?? 0 });
        });
      }
    );
  }

  async execute(
    ctx: Context,
    args: GrepArgs,
    options?: ExecOptions
  ): Promise<GrepResult> {
    using _span = createSpan(ctx.withName("LocalGrepExecutor.execute"));
    const workspacePaths = Array.isArray(this.workspacePath)
      ? this.workspacePath
      : [this.workspacePath ?? process.cwd()];
    const mode = (args.outputMode ?? "content") as Mode;
    const logContext: RipgrepErrorLogContext = {
      toolCallId: args.toolCallId,
      execId: options?.execId,
      outputMode: mode,
      targetPath: args.path,
      workspacePaths,
    };

    const sandboxPolicy = convertProtoToInternalPolicy(args.sandboxPolicy);

    try {
      const guardInfo: WorktreeGuardInfo | undefined =
        this.grepProvider.getWorktreeGuardInfo?.(workspacePaths);
      const shouldBlock: boolean = shouldBlockWorktreePath({
        targetPath: args.path,
        workspacePaths,
        mainWorktreePath: guardInfo?.mainWorktreePath,
      });
      if (shouldBlock) {
        return new GrepResult({
          result: {
            case: "error",
            value: new GrepError({ error: WORKTREE_GUARD_ERROR }),
          },
        });
      }

      // Block grep on cursorIgnored paths — ripgrep's --cursor-ignore flag
      // does not apply to explicitly specified file/directory targets, so we
      // must check before spawning the process (mirrors the Read tool guard).
      if (args.path) {
        // TODO(pre-existing): singleWorkspacePath picks the first root for
        // multi-root workspaces, which may resolve relative paths against the
        // wrong root. This predates the resolvePathForIgnoreService changes.
        const resolvedTargetPath = await resolvePathForIgnoreService(
          resolvePath(args.path, this.singleWorkspacePath)
        );
        if (resolvedTargetPath === null) {
          return new GrepResult({
            result: {
              case: "error",
              value: new GrepError({
                error: unresolvedTargetPathError(args.path),
              }),
            },
          });
        }
        if (await this.ignoreService.isCursorIgnored(resolvedTargetPath)) {
          return new GrepResult({
            result: {
              case: "error",
              value: new GrepError({
                error: `Path '${args.path}' is filtered out by .cursorignore`,
              }),
            },
          });
        }
        if (this.mcpStateAccessor !== undefined) {
          scheduleDiskMcpDiscoveryFreshnessOnMcpsPathAccess(
            ctx,
            this.mcpStateAccessor,
            resolvedTargetPath
          );
        }
      }

      // Run grep on each workspace path
      let workspaceResults: Record<string, GrepUnionResult> = {};

      const indexedResults = await this.executeIndexedGrepWithTimeout(
        _span.ctx,
        workspacePaths,
        args,
        logContext
      );

      if (indexedResults !== undefined) {
        workspaceResults = indexedResults;
      } else {
        for (const root of workspacePaths) {
          if (safeExists(root) === false) {
            return new GrepResult({
              result: {
                case: "error",
                value: new GrepError({
                  error: `Path does not exist: ${root}`,
                }),
              },
            });
          }
          let results: GrepUnionResult;
          if (mode === "content") {
            results = await this.runContentMode(
              _span.ctx,
              root,
              args,
              sandboxPolicy,
              logContext
            );
          } else if (mode === "files_with_matches") {
            results = await this.runFilesMode(
              _span.ctx,
              root,
              args,
              sandboxPolicy,
              logContext
            );
          } else if (mode === "count") {
            results = await this.runCountMode(
              _span.ctx,
              root,
              args,
              sandboxPolicy,
              logContext
            );
          } else {
            const _exhaustive: never = mode;
            throw new Error(`Unknown output mode: ${mode}`);
          }
          workspaceResults[root] = results;
        }
      }

      const dedupedResults = deduplicateCrossWorkspaceResults(
        workspaceResults,
        workspacePaths
      );

      const success = new GrepSuccess({
        pattern: args.pattern,
        path: args.path,
        outputMode: mode,
        workspaceResults: dedupedResults,
      });
      return new GrepResult({
        result: { case: "success", value: success },
      });
    } catch (e: unknown) {
      // Check if the target path doesn't exist and provide a clearer error message
      if (args.path) {
        const resolvedPath = resolvePath(args.path, this.singleWorkspacePath);
        try {
          await stat(resolvedPath);
        } catch (_e) {
          return new GrepResult({
            result: {
              case: "error",
              value: new GrepError({
                error: `Path does not exist: ${resolvedPath}`,
              }),
            },
          });
        }
      }

      return new GrepResult({
        result: {
          case: "error",
          value: new GrepError({
            error: e instanceof Error ? e.message : String(e),
          }),
        },
      });
    }
  }
}
