import { SimpleControlledExecHandler } from "./controlled.js";
import { ExecutorResource } from "./remote.js";
import { createResource } from "./resource-provider.js";
import { createClientDeserializer, createClientSerializer, createServerDeserializer, createServerSerializer, } from "./serialization.js";
export const subagentAwaitExecutorResource = createResource(execManager => new ExecutorResource(execManager, createServerSerializer("subagentAwaitArgs"), createClientDeserializer("subagentAwaitResult")), (implementation, controlledExecManager) => {
    controlledExecManager.register(new SimpleControlledExecHandler(implementation, createServerDeserializer("subagentAwaitArgs"), createClientSerializer("subagentAwaitResult")));
});
