/** Standing permission for tools that act on the user's machine outside the box. */

// Display order for Settings: Always allow, Ask every time, Never allow.
// Enforcement rank is separate (`SAND_LOCAL_TOOL_PERMISSION_RANK`).
export const SAND_LOCAL_TOOL_PERMISSIONS = ["always", "ask", "never"] as const;

export type SandLocalToolPermission = (typeof SAND_LOCAL_TOOL_PERMISSIONS)[number];

/**
 * Ask before every action that reaches the user's computer. Deliberately the
 * default: a fresh install must not hand an agent the user's machine silently,
 * and the ask card is where most users pick their real answer.
 */
export const SAND_DEFAULT_LOCAL_TOOL_PERMISSION: SandLocalToolPermission = "ask";

export function isSandLocalToolPermission(value: unknown): value is SandLocalToolPermission {
	return (
		typeof value === "string" && (SAND_LOCAL_TOOL_PERMISSIONS as readonly string[]).includes(value)
	);
}

/** Coerces an untrusted/legacy value to a permission, falling back to the default. */
export function normalizeSandLocalToolPermission(value: unknown): SandLocalToolPermission {
	return isSandLocalToolPermission(value) ? value : SAND_DEFAULT_LOCAL_TOOL_PERMISSION;
}

/**
 * What one approved ACTION does on the user's machine. The permission is
 * per action, not per turn, so this is what the card names and what a granted
 * approval is bound to. Named by effect rather than by tool, because several
 * tools land on the same effect (Read and CopyToBox both read a file out).
 */
export const SAND_LOCAL_TOOL_ACTIONS = [
	"run-command",
	"send-input",
	"read-file",
	"list-directory",
	"write-file",
] as const;

export type SandLocalToolAction = (typeof SAND_LOCAL_TOOL_ACTIONS)[number];

export function isSandLocalToolAction(value: unknown): value is SandLocalToolAction {
	return (
		typeof value === "string" && (SAND_LOCAL_TOOL_ACTIONS as readonly string[]).includes(value)
	);
}

/** The card's headline for one action. */
export function sandLocalToolActionLabel(action: SandLocalToolAction): string {
	switch (action) {
		case "run-command":
			return "Run a command on this computer?";
		case "send-input":
			return "Send input to a command on this computer?";
		case "read-file":
			return "Read a file on this computer?";
		case "list-directory":
			return "List a folder on this computer?";
		case "write-file":
			return "Write a file to this computer?";
	}
}

/**
 * Plain-English what the agent is about to do on the user's computer.
 * Prefer a model-authored {@link description} when present.
 */
export function describeSandLocalToolAction(args: {
	readonly action: SandLocalToolAction;
	readonly target: string;
	readonly description?: string;
}): string {
	const description = args.description?.replace(/\s+/g, " ").trim();
	if (description !== undefined && description.length > 0) {
		return description.replace(/[.!?]+$/u, "");
	}
	const target = args.target.replace(/\s+/g, " ").trim();
	switch (args.action) {
		case "run-command":
			return "Run a command on your computer";
		case "send-input":
			return "Send input to a running command on your computer";
		case "read-file":
			return target.length > 0 ? `Read ${target} on your computer` : "Read a file on your computer";
		case "list-directory":
			return target.length > 0
				? `List ${target} on your computer`
				: "List a folder on your computer";
		case "write-file":
			return target.length > 0
				? `Write ${target} on your computer`
				: "Write a file on your computer";
	}
}

/**
 * What the user picked on an ask card. `allow-once` / `deny` answer exactly
 * this action. `always` / `never` also move the standing setting.
 */
export type SandLocalToolPermissionResolution = "allow-once" | "deny" | "always" | "never";

export const SAND_LOCAL_TOOL_PERMISSION_RESOLUTIONS: readonly SandLocalToolPermissionResolution[] =
	["allow-once", "deny", "always", "never"];

export function isSandLocalToolPermissionResolution(
	value: unknown,
): value is SandLocalToolPermissionResolution {
	return (
		typeof value === "string" &&
		(SAND_LOCAL_TOOL_PERMISSION_RESOLUTIONS as readonly string[]).includes(value)
	);
}

/**
 * The lifecycle of one ask card. `always` / `never` record that the user changed
 * their STANDING setting from the card, so the resolved card can say so instead
 * of reading like a one-off answer.
 */
export type SandLocalToolPermissionStatus =
	| "pending"
	| "allowed"
	| "denied"
	| "always"
	| "never"
	| "expired";

const SAND_LOCAL_TOOL_PERMISSION_RANK: Record<SandLocalToolPermission, number> = {
	never: 0,
	ask: 1,
	always: 2,
};

/** Returns the member's choice narrowed only by a stricter team ceiling. */
export function resolveSandLocalToolPermission(
	choice: SandLocalToolPermission,
	adminCeiling: SandLocalToolPermission | undefined,
): SandLocalToolPermission {
	if (adminCeiling === undefined) return choice;
	return SAND_LOCAL_TOOL_PERMISSION_RANK[choice] <= SAND_LOCAL_TOOL_PERMISSION_RANK[adminCeiling]
		? choice
		: adminCeiling;
}

/** Whether the admin ceiling is what is actually holding this member back. */
export function isSandLocalToolPermissionAdminEnforced(
	choice: SandLocalToolPermission,
	adminCeiling: SandLocalToolPermission | undefined,
): boolean {
	return (
		adminCeiling !== undefined &&
		SAND_LOCAL_TOOL_PERMISSION_RANK[choice] > SAND_LOCAL_TOOL_PERMISSION_RANK[adminCeiling]
	);
}

/** The Settings label for each state, shared by the settings page and the ask card. */
export function sandLocalToolPermissionLabel(permission: SandLocalToolPermission): string {
	switch (permission) {
		case "never":
			return "Never allow";
		case "always":
			return "Always allow";
		case "ask":
			return "Ask every time";
	}
}
