import type { Readable } from "node:stream";
import type { TerminalEvent } from "./types.js";

/** Process stdio with no encoding set: chunks are Buffers, not strings. */
export type BufferReadable = Readable & AsyncIterable<Buffer>;

export type ShellOutputEventType = "stdout" | "stderr";
type ShellOutputEvent = Extract<TerminalEvent, { type: ShellOutputEventType }>;

export interface TerminalEventWritable {
  write(event: TerminalEvent): Promise<void>;
}

export interface ShellOutputLimiterOptions {
  /**
   * Maximum time to wait before flushing buffered output chunks.
   */
  flushIntervalMs?: number;

  /**
   * Buffered bytes that force an immediate flush. This bounds memory while still
   * letting quiet commands batch on the timer.
   */
  maxBufferedBytes?: number;
}

export const SHELL_OUTPUT_LIMITER_DEFAULTS: {
  readonly flushIntervalMs: 50;
  readonly maxBufferedBytes: number;
} = {
  flushIntervalMs: 50,
  maxBufferedBytes: 256 * 1024,
} as const;

/**
 * Merges adjacent buffered chunks with the same stream type while preserving
 * stdout/stderr interleaving.
 */
function coalesceAdjacentShellOutputEvents(
  events: readonly ShellOutputEvent[]
): ShellOutputEvent[] {
  if (events.length === 0) {
    return [];
  }

  const coalesced: ShellOutputEvent[] = [];
  let currentType = events[0].type;
  let dataChunks = [events[0].data];

  for (let index = 1; index < events.length; index++) {
    const next = events[index];
    if (next.type === currentType) {
      dataChunks.push(next.data);
      continue;
    }

    coalesced.push({ type: currentType, data: Buffer.concat(dataChunks) });
    currentType = next.type;
    dataChunks = [next.data];
  }

  coalesced.push({ type: currentType, data: Buffer.concat(dataChunks) });
  return coalesced;
}

/**
 * Buffers shell stdout/stderr chunks before they cross the TerminalEvent boundary.
 */
export class ShellOutputLimiter {
  private pending: ShellOutputEvent[] = [];
  private pendingBytes = 0;
  private flushTimeout: ReturnType<typeof setTimeout> | undefined;
  private flushPromise: Promise<void> | undefined;

  private readonly flushIntervalMs: number;
  private readonly maxBufferedBytes: number;

  constructor(
    private readonly writable: TerminalEventWritable,
    options?: ShellOutputLimiterOptions
  ) {
    this.flushIntervalMs =
      options?.flushIntervalMs ?? SHELL_OUTPUT_LIMITER_DEFAULTS.flushIntervalMs;
    this.maxBufferedBytes =
      options?.maxBufferedBytes ??
      SHELL_OUTPUT_LIMITER_DEFAULTS.maxBufferedBytes;
  }

  async push(type: ShellOutputEventType, data: Buffer): Promise<void> {
    if (data.length === 0) return;

    this.pending.push({ type, data });
    this.pendingBytes += data.length;

    if (this.pendingBytes >= this.maxBufferedBytes) {
      await this.flush();
      return;
    }

    this.scheduleFlush();
  }

  async flush(): Promise<void> {
    this.clearFlushTimeout();

    if (this.flushPromise) {
      await this.flushPromise;
      if (this.pendingBytes > 0) {
        await this.flush();
      }
      return;
    }

    if (this.pendingBytes === 0) return;

    const pendingEvents = this.pending;
    this.pending = [];
    this.pendingBytes = 0;

    this.flushPromise = this.writeBufferedOutput(pendingEvents);
    try {
      await this.flushPromise;
    } finally {
      this.flushPromise = undefined;
    }
  }

  async close(): Promise<void> {
    await this.flush();
  }

  private scheduleFlush(): void {
    if (this.flushTimeout !== undefined) return;

    this.flushTimeout = setTimeout(() => {
      this.flushTimeout = undefined;
      void this.flush();
    }, this.flushIntervalMs);
  }

  private clearFlushTimeout(): void {
    if (this.flushTimeout === undefined) return;

    clearTimeout(this.flushTimeout);
    this.flushTimeout = undefined;
  }

  private async writeBufferedOutput(
    events: readonly ShellOutputEvent[]
  ): Promise<void> {
    for (const event of coalesceAdjacentShellOutputEvents(events)) {
      try {
        await this.writable.write(event);
      } catch {
        // Match the existing shell output handlers: output writes after the
        // iterable closes are expected during cancellation and should be ignored.
      }
    }
  }
}

export interface ShellOutputPump {
  /**
   * Waits for buffered stdout/stderr readers to finish and reports pump errors.
   */
  waitForOutput(): Promise<void>;

  /**
   * Flushes any limiter-owned buffered data before control events are emitted.
   */
  flush(): Promise<void>;
}

export interface AttachShellOutputOptions {
  stdout?: BufferReadable | null;
  stderr?: BufferReadable | null;
  writable: TerminalEventWritable;
  bufferOutputEvents?: boolean;
  outputLimiterOptions?: ShellOutputLimiterOptions;
}

function toError(error: unknown): Error {
  return error instanceof Error ? error : new Error(String(error));
}

/**
 * Wires process stdout/stderr to terminal events, optionally with stream
 * backpressure and event coalescing.
 */
export function attachShellOutputStreams(
  options: AttachShellOutputOptions
): ShellOutputPump {
  if (!options.bufferOutputEvents) {
    const writeOutputEvent = (type: ShellOutputEventType, data: Buffer) => {
      void options.writable.write({ type, data }).catch(() => {
        // Iterable might be closed, ignore write errors.
      });
    };

    options.stdout?.on("data", data => {
      writeOutputEvent("stdout", data);
    });
    options.stderr?.on("data", data => {
      writeOutputEvent("stderr", data);
    });

    return {
      async waitForOutput() {},
      async flush() {},
    };
  }

  const limiter = new ShellOutputLimiter(
    options.writable,
    options.outputLimiterOptions
  );
  let outputPumpError: unknown;
  const outputPumpPromise = Promise.all([
    pumpShellOutputStream(options.stdout, "stdout", limiter),
    pumpShellOutputStream(options.stderr, "stderr", limiter),
  ])
    .then(() => undefined)
    .catch(error => {
      outputPumpError = error;
    });

  return {
    async waitForOutput() {
      await outputPumpPromise;
      if (outputPumpError !== undefined) {
        throw toError(outputPumpError);
      }
    },
    async flush() {
      await limiter.flush();
    },
  };
}

/**
 * Consumes a readable shell stream with real async backpressure before buffering.
 */
export async function pumpShellOutputStream(
  stream: BufferReadable | null | undefined,
  type: ShellOutputEventType,
  limiter: ShellOutputLimiter
): Promise<void> {
  if (!stream) return;

  for await (const chunk of stream) {
    await limiter.push(type, chunk);
  }
}
