import { z } from "zod";
/** No-op logger used as the default when the caller does not provide one. */
export const noopPluginLogger = () => { };
export const noopPluginMetricsLogger = {
    log: () => { },
    increment: () => { },
    distribution: () => { },
    captureException: () => { },
};
// ============================================================================
// Plugin Content Types
// ============================================================================
/**
 * MCP server configuration from a plugin.
 */
export const mcpServerConfigSchema = z.object({
    command: z.string().optional(),
    args: z.array(z.string()).optional(),
    env: z.record(z.string(), z.string()).optional(),
    url: z.string().optional(),
    headers: z.record(z.string(), z.string()).optional(),
    cwd: z.string().optional(),
    /** Path to .env file to load environment variables from (stdio servers). */
    envFile: z.string().optional(),
    /** Static OAuth client credentials for remote servers. */
    auth: z
        .object({
        CLIENT_ID: z.string(),
        CLIENT_SECRET: z.string().optional(),
        scopes: z.array(z.string()).optional(),
    })
        .optional(),
    /** Restrict which tools are exposed. If set, unlisted tools are disabled. */
    enabledTools: z.array(z.string()).optional(),
});
/**
 * MCP configuration from a plugin's .mcp.json file.
 */
export const mcpConfigSchema = z.object({
    mcpServers: z.record(z.string(), mcpServerConfigSchema).optional(),
});
