/**
 * SSE fallback helpers — detect connection errors and conditions under which
 * a streamable HTTP transport probe should fall back to deprecated SSE.
 *
 * Pure functions, no transport dependencies. Used by the lifecycle's transport
 * factory and by `mcp-agent-exec`'s legacy `McpSdkClient` connect path.
 */

export function isConnectionRefusedError(error: unknown): boolean {
	if (!(error instanceof Error)) {
		return false;
	}

	const errorWithCode = error as NodeJS.ErrnoException;
	const nestedCode = (error as { cause?: NodeJS.ErrnoException }).cause?.code;
	if (errorWithCode.code === "ECONNREFUSED" || nestedCode === "ECONNREFUSED") {
		return true;
	}

	return error.message.includes("ECONNREFUSED");
}

/**
 * Strict HTTP status extractor used exclusively by {@link isSseFallbackAppropriate}.
 *
 * This intentionally does NOT use mcp-core's general
 * `extractHttpStatusCode` (in `reconnect-manager.ts`) because the two
 * functions have different goals and the general one has wider semantics
 * that would change SSE-fallback behavior in subtle, observable ways:
 *
 *   1. `extractHttpStatusCode` accepts numeric `.code` values >= 100 with
 *      no upper bound — values like `700` would be returned verbatim. That
 *      causes `isSseFallbackAppropriate`'s equality check against 400 /
 *      404 / 405 to fail and silently skip the otherwise-appropriate
 *      fallback. The strict extractor here caps numeric codes at 599.
 *
 *   2. `extractHttpStatusCode` prefers a retryable HTTP status parsed
 *      from the error message over a non-retryable numeric `.code` —
 *      that disagreement-resolution exists for retry classification, not
 *      for transport selection. For SSE fallback we want `.code` to be
 *      authoritative when present so an SDK-reported 404 fallback is not
 *      masked by a `(HTTP 503)` blurb in the message (or vice versa).
 *
 * The accepted message patterns also stay narrow (`HTTP NNN`) so we do
 * not start matching `(HTTP NNN)` / `Non-200 status code (NNN)` shapes
 * that the general extractor handles for SSE-streaming reconnects.
 */
function extractStrictSseFallbackStatusCode(
	error: unknown,
): number | undefined {
	if (!error || typeof error !== "object") {
		return undefined;
	}

	const maybeCode = (error as { code?: unknown }).code;
	if (typeof maybeCode === "number" && maybeCode >= 100 && maybeCode <= 599) {
		return maybeCode;
	}
	if (
		typeof maybeCode === "string" &&
		/^\d{3}$/.test(maybeCode) &&
		Number(maybeCode) >= 100 &&
		Number(maybeCode) <= 599
	) {
		return Number(maybeCode);
	}

	const maybeMessage =
		error instanceof Error
			? error.message
			: typeof (error as { message?: unknown }).message === "string"
				? (error as { message: string }).message
				: undefined;

	if (!maybeMessage) {
		return undefined;
	}

	const match = maybeMessage.match(/\bHTTP\s+(\d{3})\b/i);
	if (!match?.[1]) {
		return undefined;
	}

	const parsed = Number.parseInt(match[1], 10);
	return Number.isNaN(parsed) ? undefined : parsed;
}

export function isSseFallbackAppropriate(error: unknown): boolean {
	const httpStatus = extractStrictSseFallbackStatusCode(error);
	if (httpStatus !== undefined) {
		// Streamable HTTP probes may return compatibility 4xx codes on SSE-only servers.
		return httpStatus === 400 || httpStatus === 404 || httpStatus === 405;
	}

	if (
		error instanceof Error &&
		error.message.toLowerCase().includes("sessionid must be provided")
	) {
		return true;
	}

	return isConnectionRefusedError(error);
}
