import { SimpleControlledExecHandler } from "./controlled.js";
import { ExecutorResource } from "./remote.js";
import { createResource } from "./resource-provider.js";
import { createClientDeserializer, createClientSerializer, createServerDeserializer, createServerSerializer, } from "./serialization.js";
export const piReadExecutorResource = createResource(execManager => new ExecutorResource(execManager, createServerSerializer("piReadArgs"), createClientDeserializer("piReadResult")), (implementation, controlledExecManager) => {
    controlledExecManager.register(new SimpleControlledExecHandler(implementation, createServerDeserializer("piReadArgs"), createClientSerializer("piReadResult")));
});
