import type { makeNodeTransport } from "@sentry/node";

import {
	projectSandSentryEnvelope,
	type SandSentryEnvelope,
	type SandSentryPrivacyTier,
} from "./sentry-scrub.js";

export const SAND_SENTRY_DSN =
	"https://9fb7a1b8cb70c207a28a00476311bd40@metrics.cursor.sh/4511747394240513";

export const SAND_SENTRY_CONVERSATION_TAG = "sand.conversation_id";

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function isUnknownProcessEnvelope(envelope: SandSentryEnvelope): boolean {
	for (const [itemHeader, itemPayload] of envelope[1]) {
		if (itemHeader.type !== "event" || !isRecord(itemPayload)) {
			continue;
		}

		if (isRecord(itemPayload.tags) && itemPayload.tags["event.process"] === "unknown") {
			return true;
		}
	}
	return false;
}

type SandSentryEnvelopeAccount = "match" | "mismatch" | "missing";

function envelopeAccount(
	envelope: SandSentryEnvelope,
	currentUserId: string | undefined,
): SandSentryEnvelopeAccount {
	if (currentUserId === undefined) return "match";
	let matched = false;
	for (const [itemHeader, itemPayload] of envelope[1]) {
		if (!isRecord(itemPayload)) continue;
		let id: unknown;
		if (itemHeader.type === "event" && isRecord(itemPayload.user)) {
			id = itemPayload.user.id;
		} else if (itemHeader.type === "session") {
			id = itemPayload.did;
		}
		if (typeof id === "string" || typeof id === "number") {
			if (String(id) !== currentUserId) return "mismatch";
			matched = true;
		}
	}
	return matched ? "match" : "missing";
}

export class SandSentryPrivacyGate<E extends SandSentryEnvelope> {
	private tier: SandSentryPrivacyTier = "fatal-metadata";
	private userId: string | undefined;

	setTier(tier: SandSentryPrivacyTier): void {
		this.tier = tier;
	}

	setUserId(userId: string | undefined): void {
		this.userId = userId;
	}

	handle(envelope: E): E | undefined {
		if (isUnknownProcessEnvelope(envelope)) return undefined;
		const account = envelopeAccount(envelope, this.userId);
		let tier = this.tier;
		if (account === "mismatch") tier = "fatal-metadata";
		else if (account === "missing" && tier === "full") tier = "scrubbed";
		return projectSandSentryEnvelope(envelope, tier);
	}

	belongsToCurrentAccount(envelope: E): boolean {
		return envelopeAccount(envelope, this.userId) === "match";
	}
}

export interface SandSentryPrivacySyncRequest {
	readonly sequence: number;
	readonly reset: boolean;
	readonly identityChanged: boolean;
}

export class SandSentryAccountPrivacySync {
	private sequence = 0;
	private authId: string | undefined;

	begin(authId: string | undefined): SandSentryPrivacySyncRequest {
		const reset = authId === undefined || authId !== this.authId;
		const identityChanged = this.authId !== undefined && authId !== this.authId;
		this.authId = authId;
		return { sequence: ++this.sequence, reset, identityChanged };
	}

	isCurrent(request: SandSentryPrivacySyncRequest): boolean {
		return request.sequence === this.sequence;
	}

	finish<T>(request: SandSentryPrivacySyncRequest, value: T | undefined): T | undefined {
		return this.isCurrent(request) ? value : undefined;
	}
}

export type SandSentryTransportResponse = Awaited<
	ReturnType<ReturnType<typeof makeNodeTransport>["send"]>
>;

export interface SandSentryTransport<E extends SandSentryEnvelope> {
	send(envelope: E): PromiseLike<SandSentryTransportResponse>;
	flush(timeout?: number): PromiseLike<boolean>;
}

export function gateEnvelopeSend<E extends SandSentryEnvelope>(
	gate: SandSentryPrivacyGate<E>,
	send: (envelope: E) => PromiseLike<SandSentryTransportResponse>,
	onAccepted?: (envelope: E) => void,
): (envelope: E) => PromiseLike<SandSentryTransportResponse> {
	return (envelope) => {
		const projected = gate.handle(envelope);
		if (projected === undefined) return Promise.resolve({});
		if (onAccepted !== undefined && gate.belongsToCurrentAccount(envelope)) {
			onAccepted(projected);
		}
		return send(projected);
	};
}

function gateTransport<E extends SandSentryEnvelope>(
	gate: SandSentryPrivacyGate<E>,
	transport: SandSentryTransport<E>,
	onAccepted?: (envelope: E) => void,
): SandSentryTransport<E> {
	return {
		...transport,
		send: gateEnvelopeSend(gate, (envelope) => transport.send(envelope), onAccepted),
	};
}

const SENTRY_EVENT_ID_PATTERN = /^[0-9a-f]{32}$/;

export class SandSentryEventIdRing {
	private readonly capacity: number;
	private ids: readonly string[] = [];

	constructor(capacity: number) {
		this.capacity = capacity;
	}

	record(envelope: SandSentryEnvelope): void {
		for (const [itemHeader, itemPayload] of envelope[1]) {
			if (itemHeader.type !== "event" || !isRecord(itemPayload)) continue;
			const id = itemPayload.event_id;
			if (typeof id !== "string" || !SENTRY_EVENT_ID_PATTERN.test(id)) continue;
			this.ids = [id, ...this.ids.filter((known) => known !== id)].slice(0, this.capacity);
		}
	}

	list(): readonly string[] {
		return this.ids;
	}

	clear(): void {
		this.ids = [];
	}
}

type SandSentryTransportFactory<O, E extends SandSentryEnvelope> = (
	options: O,
) => SandSentryTransport<E>;

export interface SandSentryOfflineTransport<
	E extends SandSentryEnvelope,
> extends SandSentryTransport<E> {
	purgeSpool(): Promise<number>;
}

interface SandSentryOfflineSpoolStore {
	push(envelope: unknown): PromiseLike<void>;
	unshift(envelope: unknown): PromiseLike<void>;
	shift(): PromiseLike<unknown>;
}

interface SandSentryPurgeableSpoolStore extends SandSentryOfflineSpoolStore {
	purge(): Promise<number>;
}

const MAX_SPOOL_PURGE_SHIFTS = 64;

function purgeableSpoolStore(store: SandSentryOfflineSpoolStore): SandSentryPurgeableSpoolStore {
	let purgeEpoch = 0;
	const shiftedAtEpoch = new WeakMap<object, number>();
	return {
		push: (envelope) => store.push(envelope),
		unshift: (envelope) => {
			const epoch =
				typeof envelope === "object" && envelope !== null
					? shiftedAtEpoch.get(envelope)
					: undefined;
			if (epoch !== undefined && epoch < purgeEpoch) return Promise.resolve();
			return store.unshift(envelope);
		},
		shift: async () => {
			const envelope = await store.shift();
			if (typeof envelope === "object" && envelope !== null) {
				shiftedAtEpoch.set(envelope, purgeEpoch);
			}
			return envelope;
		},
		purge: async () => {
			let purged = 0;
			while (purged < MAX_SPOOL_PURGE_SHIFTS && (await store.shift()) !== undefined) {
				purged += 1;
			}
			purgeEpoch += 1;
			return purged;
		},
	};
}

function captureOfflineSpoolStore(
	transportOptions: unknown,
	capture: (store: SandSentryPurgeableSpoolStore) => void,
): void {
	if (!isRecord(transportOptions)) return;
	const createStore = transportOptions.createStore;
	if (typeof createStore !== "function") return;
	transportOptions.createStore = (...args: unknown[]): unknown => {
		const store = purgeableSpoolStore(
			createStore.apply(transportOptions, args) as SandSentryOfflineSpoolStore,
		);
		capture(store);
		return store;
	};
}

export function makeSandSentryOfflineTransport<O, E extends SandSentryEnvelope>(options: {
	readonly gate: SandSentryPrivacyGate<E>;
	readonly transportOptions: O;
	readonly makeOfflineTransport: (
		makeBaseTransport: SandSentryTransportFactory<O, E>,
	) => SandSentryTransportFactory<O, E>;
	readonly makeNetworkTransport: SandSentryTransportFactory<O, E>;
	readonly onEnvelopeAccepted?: (envelope: E) => void;
}): SandSentryOfflineTransport<E> {
	let spoolStore: SandSentryPurgeableSpoolStore | undefined;
	const offline = options.makeOfflineTransport((transportOptions) => {
		captureOfflineSpoolStore(transportOptions, (store) => {
			spoolStore = store;
		});
		return gateTransport(options.gate, options.makeNetworkTransport(transportOptions));
	})(options.transportOptions);
	return {
		...gateTransport(options.gate, offline, options.onEnvelopeAccepted),
		purgeSpool: async () => (spoolStore === undefined ? 0 : spoolStore.purge()),
	};
}

export type { SandSentryEnvelope, SandSentryPrivacyTier };
