/**
 * Pure logic for the MCP OAuth connect flow status handler.
 *
 * Extracted from settingsFeaturesMCPServerItem.tsx so the
 * status-transition behavior can be unit-tested without SolidJS.
 */

export interface ConnectFlowState {
	isConnecting: boolean;
	authUrlOpened: boolean;
	isExchangingToken: boolean;
	hasOpenedAuthUrlThisAttempt: boolean;
	hasSeenMeaningfulStatus: boolean;
}

export type ConnectFlowAction =
	| { type: 'openAuthUrl'; url: string }
	| { type: 'setExchangingToken' }
	| { type: 'terminate' };

export interface ConnectStatusEvent {
	type: string;
	authorizationUrl?: string;
}

export function initialConnectFlowState(): ConnectFlowState {
	return {
		isConnecting: true,
		authUrlOpened: false,
		isExchangingToken: false,
		hasOpenedAuthUrlThisAttempt: false,
		hasSeenMeaningfulStatus: false,
	};
}

/**
 * Process a single status event in the connect flow.
 *
 * Returns the updated state and any action to perform.
 * This mirrors the onDidChangeServerStatus callback in
 * settingsFeaturesMCPServerItem.tsx.
 *
 * Two guards prevent premature termination:
 * - `disconnected` only terminal after a meaningful status has been
 *   observed (prevents clearServerOAuthState stale events — V1 race)
 * - `error` only terminal after auth URL has been opened (prevents
 *   pre-auth Unauthorized from killing the flow — V2 race)
 */
export function processConnectStatusEvent(
	state: ConnectFlowState,
	status: ConnectStatusEvent,
	oauthUrlSpamGuardEnabled: boolean,
): { state: ConnectFlowState; action?: ConnectFlowAction } {
	if (!state.isConnecting) {
		return { state };
	}

	const shouldOpenAuthUrl = oauthUrlSpamGuardEnabled
		? !state.hasOpenedAuthUrlThisAttempt
		: true;

	if (status.type === 'needsAuth' && shouldOpenAuthUrl) {
		return {
			state: {
				...state,
				hasSeenMeaningfulStatus: true,
				hasOpenedAuthUrlThisAttempt: true,
				authUrlOpened: true,
			},
			action: { type: 'openAuthUrl', url: status.authorizationUrl ?? '' },
		};
	}

	if (status.type === 'initializing') {
		const newState = { ...state, hasSeenMeaningfulStatus: true };
		if (state.authUrlOpened) {
			return {
				state: { ...newState, isExchangingToken: true },
				action: { type: 'setExchangingToken' },
			};
		}
		return { state: newState };
	}

	if (status.type === 'connected') {
		return {
			state: {
				isConnecting: false,
				authUrlOpened: false,
				isExchangingToken: false,
				hasOpenedAuthUrlThisAttempt: false,
				hasSeenMeaningfulStatus: true,
			},
			action: { type: 'terminate' },
		};
	}

	if (status.type === 'error' && state.authUrlOpened) {
		return {
			state: {
				isConnecting: false,
				authUrlOpened: false,
				isExchangingToken: false,
				hasOpenedAuthUrlThisAttempt: false,
				hasSeenMeaningfulStatus: true,
			},
			action: { type: 'terminate' },
		};
	}

	if (status.type === 'disconnected' && state.hasSeenMeaningfulStatus) {
		return {
			state: {
				isConnecting: false,
				authUrlOpened: false,
				isExchangingToken: false,
				hasOpenedAuthUrlThisAttempt: false,
				hasSeenMeaningfulStatus: true,
			},
			action: { type: 'terminate' },
		};
	}

	return { state };
}
