import constants from "node:constants";
import type { FileHandle } from "node:fs/promises";
import { mkdir, open, stat } from "node:fs/promises";
import { dirname, sep } from "node:path";
import type { WriteExecutor } from "@anysphere/agent-exec";
import { type Context, createLogger, createSpan } from "@anysphere/context";
import {
  type WriteArgs,
  WriteError,
  WriteNoSpace,
  WritePermissionDenied,
  WriteRejected,
  WriteResult,
  WriteSuccess,
} from "@anysphere/proto/agent/v1/write_exec_pb.js";
import {
  shouldBlockWorktreePath,
  WORKTREE_GUARD_ERROR,
} from "@anysphere/utils";
import { resolvePath } from "./common.js";
import type {
  FileChangeMetadata,
  FileChangeTrackerInterface,
} from "./file-change-tracker.js";
import { resolvePermissionsPath } from "./permissions-path.js";
import {
  SymlinkRefusedError,
  writeFileNoFollow,
} from "./symlink-safe-write.js";

/** Arguments for the onWriteForAiTracking callback. Object form prevents accidental parameter swap. */
export interface OnWriteForAiTrackingArgs {
  path: string;
  beforeContent: string | undefined;
  afterContent: string;
  metadata: FileChangeMetadata;
}

import { getBufferForWrite, readText } from "@anysphere/utils";
import { MAX_OFS_FILE_SIZE } from "./constants.js";
import { isCursorProjectsInternalPath } from "./internal-paths.js";
import {
  OperationType,
  type PendingDecisionProvider,
} from "./pending-decision-provider.js";
import type {
  BlockReason,
  PermissionsService,
} from "./services/permissions-service.js";
import { handleBlockReason } from "./utils/edit-block-handler.js";

const logger = createLogger("LocalWriteExecutor");

const watchdog = async <R>(
  ctx: Context,
  msg: string,
  ms: number,
  f: () => Promise<R>
): Promise<R> => {
  const timeout = setTimeout(() => {
    logger.warn(
      ctx,
      `[watchdog, LocalWriteExecutor] ${msg} still not completed after ${ms}ms`
    );
  }, ms);
  try {
    return await f();
  } finally {
    clearTimeout(timeout);
  }
};

type LocalWriteExecutorOptions = {
  workspacePaths: string[];
  workspacePath?: string;
  worktreeMainPath?: string;
  /** Optional callback for AI code tracking (cursor-blame). Called after successful text writes. */
  onWriteForAiTracking?: (args: OnWriteForAiTrackingArgs) => Promise<void>;
};

export class LocalWriteExecutor implements WriteExecutor {
  private readonly workspacePaths: string[];
  private readonly workspacePath?: string;
  private readonly worktreeMainPath?: string;

  private readonly onWriteForAiTracking?: (
    args: OnWriteForAiTrackingArgs
  ) => Promise<void>;

  constructor(
    private fileChangeTracker: FileChangeTrackerInterface,
    private permissionsService: PermissionsService,
    private pendingDecisionProvider: PendingDecisionProvider,
    {
      workspacePaths,
      workspacePath,
      worktreeMainPath,
      onWriteForAiTracking,
    }: LocalWriteExecutorOptions
  ) {
    this.workspacePaths = workspacePaths;
    this.workspacePath = workspacePath;
    this.worktreeMainPath = worktreeMainPath;
    this.onWriteForAiTracking = onWriteForAiTracking;
  }

  async execute(parentCtx: Context, args: WriteArgs): Promise<WriteResult> {
    using span = createSpan(parentCtx.withName("LocalWriteExecutor.execute"));
    const ctx = span.ctx;
    const path = args.path;
    const fileText = args.fileText;
    const fileBytes: Uint8Array | undefined =
      args.fileBytes.length > 0 ? args.fileBytes : undefined;
    const resolvedPath: string = resolvePath(path, this.workspacePath);
    const shouldSkipAgentTracking = isCursorProjectsInternalPath(resolvedPath, [
      "assets",
      "agent-tools",
      "swarm-agents",
    ]);

    if (
      shouldBlockWorktreePath({
        targetPath: resolvedPath,
        workspacePaths: this.workspacePaths,
        mainWorktreePath: this.worktreeMainPath,
      })
    ) {
      return new WriteResult({
        result: {
          case: "error",
          value: new WriteError({
            path: resolvedPath,
            error: WORKTREE_GUARD_ERROR,
          }),
        },
      });
    }

    // Read existing contents if the file exists to allow proper change tracking.
    // This needs to happen before shouldBlock check so it's available for approval.
    // Skip reading files larger than MAX_OFS_FILE_SIZE to avoid renderer OOM.
    let beforeContent: string | undefined;
    let existingFileTooLarge = false;
    try {
      const stats = await stat(resolvedPath);
      if (stats.size <= MAX_OFS_FILE_SIZE) {
        beforeContent = await watchdog(
          ctx,
          "readText before write",
          3_000,
          () => readText(resolvedPath, args.encodingHint)
        );
      } else {
        existingFileTooLarge = true;
      }
    } catch {
      // File doesn't exist; we'll create it.
    }

    // Canonicalize (symlink-resolve) the target ONCE and use that exact path
    // for both authorization and the physical write. Resolving separately in
    // the permission check and again at write time is a TOCTOU hole: a symlink
    // flipped in between lets a write that passed the in-workspace check land
    // on an out-of-workspace file (e.g. ~/.zshrc). `writeTargetPath` is the
    // symlink-resolved path the permission check below validates, and the write
    // itself is bound to it via `writeFileNoFollow`.
    const permResolved = await resolvePermissionsPath(resolvedPath);
    const writeTargetPath = permResolved.resolvedPath;

    // Authorization below runs on the symlink-resolved path so the permission
    // decision is bound to the exact inode we write. That still blocks a
    // resolved target named `.cursorignore`, but because the resolved path can
    // differ from what was requested we must independently keep the
    // unbypassable hard block on the *requested* leaf name — a request to write
    // `.cursorignore` (e.g. via a symlink pointing elsewhere) must be refused
    // regardless of where it resolves (CVE-2025-64110 guard).
    const requestedLeafName =
      resolvedPath.split(sep).pop()?.toLowerCase() ?? "";
    const cursorIgnoreNameBlock: BlockReason | undefined =
      requestedLeafName === ".cursorignore"
        ? { type: "permissionsConfig" }
        : undefined;

    const shouldBlock =
      cursorIgnoreNameBlock ??
      (await watchdog(ctx, "permissionsService.shouldBlockWrite", 3_000, () =>
        this.permissionsService.shouldBlockWrite(ctx, writeTargetPath, fileText)
      ));
    if (shouldBlock) {
      const blockResult = await watchdog(ctx, "handleBlockReason", 3_000, () =>
        handleBlockReason(shouldBlock, {
          onNeedsApproval: async (approvalReason, approvalDetails) => {
            const isNewFile =
              approvalDetails?.type === "fileEdit"
                ? approvalDetails.isNewFile
                : true;
            const diffString =
              approvalDetails?.type === "fileEdit"
                ? approvalDetails.diffString
                : fileText;
            const blockReason =
              approvalDetails?.type === "fileEdit"
                ? approvalDetails.blockReason
                : undefined;

            const result = await this.pendingDecisionProvider.requestApproval({
              type: OperationType.Write,
              details: {
                path: resolvedPath,
                reason: approvalReason,
                isNewFile,
                diffString,
                before: beforeContent,
                after: fileText,
                blockReason,
              },
              toolCallId: args.toolCallId,
            });

            if (!result.approved) {
              return new WriteResult({
                result: {
                  case: "rejected",
                  value: new WriteRejected({
                    path: resolvedPath,
                    reason: result.reason || "",
                  }),
                },
              });
            }
            return null;
          },
          onUserRejected: reason =>
            new WriteResult({
              result: {
                case: "rejected",
                value: new WriteRejected({
                  path: resolvedPath,
                  reason: reason || "",
                }),
              },
            }),
          onPermissionDenied: (errorMessage, metadata) =>
            new WriteResult({
              result: {
                case: "permissionDenied",
                value: new WritePermissionDenied({
                  path: resolvedPath,
                  error: errorMessage,
                  isReadonly: metadata?.isReadonly ?? false,
                }),
              },
            }),
        })
      );

      if (blockResult !== null) {
        return blockResult;
      }
    }

    // Ensure the directory exists (use the canonical target so intermediate
    // dirs are created at the resolved location, matching where we write).
    const dir = dirname(writeTargetPath);
    try {
      await watchdog(ctx, "mkdir", 3_000, () =>
        mkdir(dir, { recursive: true })
      );
    } catch (error) {
      const errorCode = (error as NodeJS.ErrnoException).code;
      if (errorCode === "EACCES" || errorCode === "EPERM") {
        return new WriteResult({
          result: {
            case: "permissionDenied",
            value: new WritePermissionDenied({
              path: resolvedPath,
              directory: dir,
              operation: "create_directory",
              error: "Permission denied",
            }),
          },
        });
      }
      return new WriteResult({
        result: {
          case: "error",
          value: new WriteError({
            path: resolvedPath,
            error: (error as Error).message,
          }),
        },
      });
    }

    // Create the file with the specified content
    // If fileBytes is provided, write binary data directly without text processing
    let buffer: Buffer | Uint8Array;
    let lines: number;

    if (fileBytes !== undefined) {
      // Binary mode: write raw bytes directly
      buffer = fileBytes;
      lines = 0; // Line count not meaningful for binary data
    } else {
      // Text mode: apply line ending normalization
      const textResult = await watchdog(ctx, "getBufferForWrite", 3_000, () =>
        getBufferForWrite(
          writeTargetPath,
          fileText,
          this.workspacePath,
          args.encodingHint
        )
      );
      buffer = textResult.buffer;
      lines = textResult.lines;
    }

    try {
      await watchdog(ctx, "writeFile", 3_000, async () => {
        await writeFileNoFollow(writeTargetPath, buffer, { flush: true });
        let dirHandle: FileHandle | undefined;
        try {
          dirHandle = await open(dirname(writeTargetPath), constants.O_RDONLY);
          await dirHandle.sync();
        } catch {
          // Best effort directory sync
        } finally {
          await dirHandle?.close();
        }
      });
    } catch (error) {
      if (error instanceof SymlinkRefusedError) {
        // A symlink was swapped in at (or above) the target between the
        // permission check and the write. Refuse rather than follow it.
        return new WriteResult({
          result: {
            case: "permissionDenied",
            value: new WritePermissionDenied({
              path: resolvedPath,
              directory: "",
              operation: "create_file",
              error: error.message,
            }),
          },
        });
      }
      const errorCode = (error as NodeJS.ErrnoException).code;
      if (errorCode === "EACCES" || errorCode === "EPERM") {
        return new WriteResult({
          result: {
            case: "permissionDenied",
            value: new WritePermissionDenied({
              path: resolvedPath,
              directory: "",
              operation: "create_file",
              error: "Permission denied",
            }),
          },
        });
      }
      if ((error as NodeJS.ErrnoException).code === "ENOSPC") {
        return new WriteResult({
          result: {
            case: "noSpace",
            value: new WriteNoSpace({
              path: resolvedPath,
            }),
          },
        });
      }
      return new WriteResult({
        result: {
          case: "error",
          value: new WriteError({
            path: resolvedPath,
            error: (error as Error).message,
          }),
        },
      });
    }

    // Track the file creation or modification if we have a tracker. Otherwise:
    // - Skip tracking for binary files as change tracking is text-based.
    // - Skip when the file existed but content couldn't be read (e.g. too large),
    //   otherwise the tracker would treat the overwrite as a new-file creation and
    //   undo/reject would delete the original file instead of restoring it.
    if (
      this.fileChangeTracker &&
      fileBytes === undefined &&
      !shouldSkipAgentTracking &&
      !existingFileTooLarge
    ) {
      const metadata = args.toolCallId
        ? { toolCallId: args.toolCallId }
        : undefined;
      await this.fileChangeTracker.trackChange(
        resolvedPath,
        beforeContent,
        fileText,
        metadata
      );
    }

    // Call AI code tracking callback for cursor-blame (text writes only).
    // Best-effort: do not fail the write if tracking throws (e.g. DB, git, storage errors).
    if (
      this.onWriteForAiTracking &&
      fileBytes === undefined &&
      !shouldSkipAgentTracking
    ) {
      const metadata = args.toolCallId ? { toolCallId: args.toolCallId } : {};
      try {
        await this.onWriteForAiTracking({
          path: resolvedPath,
          beforeContent,
          afterContent: fileText,
          metadata,
        });
      } catch (err) {
        logger.warn(ctx, "onWriteForAiTracking failed (write succeeded)", {
          path: resolvedPath,
          error: err instanceof Error ? err.message : String(err),
        });
      }
    }

    const bytes: number = buffer.byteLength;

    // Read the file content after successful write if requested
    let fileContentAfterWrite: string | undefined;
    if (args.returnFileContentAfterWrite) {
      try {
        fileContentAfterWrite = await watchdog(
          ctx,
          "readText after write",
          3_000,
          () => readText(resolvedPath, args.encodingHint)
        );
      } catch {
        // If reading fails, we'll leave it undefined
      }
    }

    return new WriteResult({
      result: {
        case: "success",
        value: new WriteSuccess({
          path: resolvedPath,
          linesCreated: lines,
          fileSize: bytes,
          ...(fileContentAfterWrite !== undefined && {
            fileContentAfterWrite,
          }),
        }),
      },
    });
  }
}
