/**
 * Types for Claude Code hooks configuration.
 * These types represent the structure of settings.json files used by Claude Code.
 *
 * @see https://docs.anthropic.com/en/docs/claude-code/hooks
 */
import { HookStep } from "./hook-step.js";
/**
 * Mapping from Claude Code event names to Cursor hook steps.
 *
 * `null` means the event has no Cursor equivalent (intentionally unsupported).
 */
export const CLAUDE_EVENT_TO_CURSOR_STEP = {
    PreToolUse: HookStep.preToolUse,
    PermissionRequest: null,
    PostToolUse: HookStep.postToolUse,
    UserPromptSubmit: HookStep.beforeSubmitPrompt,
    Stop: HookStep.stop,
    SubagentStop: HookStep.subagentStop,
    SessionStart: HookStep.sessionStart,
    SessionEnd: HookStep.sessionEnd,
    PreCompact: HookStep.preCompact,
    Notification: null,
};
/**
 * Inverse of {@link CLAUDE_EVENT_TO_CURSOR_STEP}. For a Cursor `HookStep` that
 * has a Claude Code equivalent, returns the PascalCase Claude event-name
 * string. Steps with no Claude equivalent (e.g. `beforeShellExecution`,
 * `postToolUseFailure`) return `undefined`.
 *
 * Use this when interoperating with Claude-format payloads (e.g. validating
 * a nested `hookSpecificOutput.hookEventName` in `normalize.ts`). Independent
 * of `HOOK_STEPS_SUPPORTING_ADDITIONAL_CONTEXT` -- callers that want to scope
 * to additional_context-bearing steps gate on that set separately.
 */
export const CURSOR_STEP_TO_CLAUDE_EVENT = Object.fromEntries(Object.entries(CLAUDE_EVENT_TO_CURSOR_STEP)
    .filter((entry) => entry[1] !== null)
    .map(([event, step]) => [step, event]));
/**
 * Mapping from Claude Code tool names to Cursor NAL tool names.
 * null means the tool is not supported.
 */
export const CLAUDE_TOOL_TO_CURSOR_TOOL = {
    Bash: "Shell",
    Read: "Read",
    Write: "Write",
    Edit: "Write", // Edit maps to Write
    Glob: null, // Not exposed in CLI
    Grep: "Grep",
    WebFetch: "WebFetch",
    WebSearch: "WebSearch",
    Task: "Task", // preToolUse/postToolUse supported
};
/**
 * Claude Code tools that are not supported in Cursor.
 * Used for logging warnings.
 */
export const UNSUPPORTED_CLAUDE_TOOLS = ["Glob"];
/**
 * Claude Code events that are not supported in Cursor.
 */
export const UNSUPPORTED_CLAUDE_EVENTS = [
    "Notification",
    "PermissionRequest",
];
