/**
 * Per-server cooldown after focus/wake/network-resume triggered reconnects.
 * Value is pushed from Statsig `mcp_reconnect_config.focusRetryCooldownMs`.
 */

import {
	getMcpReconnectConfigValue,
	type McpReconnectConfigContext,
} from './mcp-reconnect-config.js';

export const FOCUS_RETRY_MINIMUM_COOLDOWN_MS: number = 5 * 60_000;

export function getFocusRetryCooldownMs(context?: McpReconnectConfigContext): number {
	const raw = getMcpReconnectConfigValue('focusRetryCooldownMs', context) ?? FOCUS_RETRY_MINIMUM_COOLDOWN_MS;
	return Math.max(FOCUS_RETRY_MINIMUM_COOLDOWN_MS, Math.min(raw, 3_600_000));
}

export function isWithinFocusRetryCooldown(
	nowMs: number,
	lastRetryAtMs: number | undefined,
	cooldownMs: number,
): boolean {
	return lastRetryAtMs !== undefined && nowMs - lastRetryAtMs < cooldownMs;
}
