/**
 * Per-server inline reconnect cooldown for MCP tool-call retries (V2 adapter).
 * Value is pushed from {@link mcpCommandsV2}'s Statsig fetch; defaults until resolved.
 */

import {
	getMcpReconnectConfigValue,
	type McpReconnectConfigContext,
} from './mcp-reconnect-config.js';

const DEFAULT_INLINE_RECONNECT_COOLDOWN_MS = 5 * 60_000;

export function getInlineReconnectCooldownMs(context?: McpReconnectConfigContext): number {
	const raw = getMcpReconnectConfigValue('inlineReconnectCooldownMs', context) ?? DEFAULT_INLINE_RECONNECT_COOLDOWN_MS;
	return Math.max(1_000, Math.min(raw, 3_600_000));
}
