import { join } from "node:path";

import { errorLogTag } from "../../shared/errors.js";
import { SAND_LOCAL_EXEC_SUPERVISED_WINDOW_MS } from "../../shared/local-exec-daemon.js";
import {
	localToolApprovalCovers,
	SAND_LOCAL_TOOLS_DISABLED_MESSAGE,
	SAND_LOCAL_TOOLS_UNAPPROVED_MESSAGE,
} from "../../shared/local-tool-permission-machinery.js";
import { getSandBackendClientHeaders } from "../../shared/node/sand-client-metadata.js";
import { getSandVariant } from "../../shared/node/sand-variant.js";
import { SandSettingsStore } from "../../shared/node/settings/sand-settings-store.js";
import {
	GATEWAY_NETWORK_TOKEN_HEADER,
	type SandGatewayConnectionInfo,
} from "../gateway-protocol.js";
import { getSandRootDir } from "../host-paths.js";
import {
	clearLocalExecDaemonDiscovery,
	getLocalExecDaemonConnectionPath,
	getLocalExecDaemonCredentialPath,
	getLocalExecSupervisorHeartbeatPath,
	readLocalExecDaemonConnection,
	readLocalExecDaemonCredential,
	readLocalExecSupervisorHeartbeat,
	writeLocalExecDaemonConnection,
	writeLocalExecDaemonDiscovery,
} from "./local-exec-daemon-protocol.js";
import { SandLocalExecProvider } from "./local-exec-provider.js";
import {
	getLocalToolApprovalsPath,
	getLocalToolRetirementsPath,
	readLiveLocalToolApprovals,
	retireLocalToolApproval,
} from "./local-tool-approvals.js";

export class SandLocalExecConnectionError extends Error {}

const NO_CONNECTION_MESSAGE =
	"local-exec daemon has no gateway connection yet (waiting for the desktop to hand one off)";

// The backend endpoint that exchanges the daemon's durable, box-bound credential
// for a fresh connection to the (possibly recreated) box. Mirrors the inference
// renewer's POST /sand-box/inference-credential, but resolves a gateway
// connection instead of an access token (see sandBoxServer.ts +
// handleAuthenticationEndpoints.ts).
const LOCAL_EXEC_CONNECTION_PATH = "/sand-box/local-exec-connection";

// Exchange the daemon's box-bound credential at the backend for a fresh gateway
// connection to its box. Returns null on ANY non-2xx (401 revoked/expired, 503
// no-live-box-yet, transient error) so the caller keeps the existing descriptor
// and retries — the daemon never wedges on a stale credential, it just can't
// self-heal until a live box (or a desktop re-handoff) appears. Injectable for
// tests.
export async function resolveLocalExecConnectionFromBackend(args: {
	readonly backendUrl: string;
	readonly credential: string;
	readonly fetchImpl?: typeof fetch;
}): Promise<SandGatewayConnectionInfo | null> {
	const fetchImpl = args.fetchImpl ?? fetch;
	let response: Response;
	try {
		response = await fetchImpl(new URL(LOCAL_EXEC_CONNECTION_PATH, args.backendUrl).toString(), {
			method: "POST",
			headers: {
				"content-type": "application/json",
				...getSandBackendClientHeaders(),
			},
			body: JSON.stringify({ credential: args.credential }),
		});
	} catch {
		return null;
	}
	if (!response.ok) return null;
	let parsed: { baseUrl?: unknown; token?: unknown; networkToken?: unknown };
	try {
		parsed = (await response.json()) as typeof parsed;
	} catch {
		return null;
	}
	const baseUrl = typeof parsed.baseUrl === "string" ? parsed.baseUrl : "";
	if (baseUrl.length === 0) return null;
	const token =
		typeof parsed.token === "string" && parsed.token.length > 0 ? parsed.token : undefined;
	const networkToken = typeof parsed.networkToken === "string" ? parsed.networkToken : "";
	return {
		baseUrl,
		token,
		headers: networkToken.length > 0 ? { [GATEWAY_NETWORK_TOKEN_HEADER]: networkToken } : undefined,
	};
}

export interface RunLocalExecDaemonOptions {
	readonly connectionPath?: string;
	readonly discoveryPath?: string;
	readonly credentialPath?: string;
	readonly supervisorHeartbeatPath?: string;
	readonly publishDiscovery?: boolean;
	readonly resolveConnectionFromBackend?: (args: {
		readonly backendUrl: string;
		readonly credential: string;
	}) => Promise<SandGatewayConnectionInfo | null>;
	readonly settingsStore?: Pick<SandSettingsStore, "getLocalToolPermission">;
	readonly approvalsPath?: string;
	readonly retirementsPath?: string;
}

export interface RunningLocalExecDaemon {
	close(): Promise<void>;
}

export async function runLocalExecDaemon(
	options: RunLocalExecDaemonOptions = {},
): Promise<RunningLocalExecDaemon> {
	const connectionPath = options.connectionPath ?? getLocalExecDaemonConnectionPath();
	const credentialPath = options.credentialPath ?? getLocalExecDaemonCredentialPath();
	const supervisorHeartbeatPath =
		options.supervisorHeartbeatPath ?? getLocalExecSupervisorHeartbeatPath();
	const publishDiscovery = options.publishDiscovery !== false;
	const resolveConnectionFromBackend =
		options.resolveConnectionFromBackend ?? ((args) => resolveLocalExecConnectionFromBackend(args));

	const startedAt = Date.now();
	let lastInflightCount = 0;
	let isPublishing = false;
	let isPublishPending = false;
	const publishDaemonDiscovery = async (): Promise<void> => {
		isPublishPending = true;
		if (isPublishing) return;
		isPublishing = true;
		try {
			while (isPublishPending) {
				isPublishPending = false;
				await writeLocalExecDaemonDiscovery(
					{ pid: process.pid, startedAt, inflightCount: lastInflightCount },
					options.discoveryPath,
				).catch((error: unknown) => {
					console.error(
						`[local-exec-daemon] discovery publish failed (previous record stands): ${errorLogTag(error)}`,
					);
				});
			}
		} finally {
			isPublishing = false;
		}
	};

	const settingsStore =
		options.settingsStore ?? new SandSettingsStore(join(getSandRootDir(), "settings.json"));
	const approvalsPath = options.approvalsPath ?? getLocalToolApprovalsPath();
	const retirementsPath = options.retirementsPath ?? getLocalToolRetirementsPath();
	const provider = new SandLocalExecProvider({
		resolveConnection: async (): Promise<SandGatewayConnectionInfo> => {
			const connection = await readLocalExecDaemonConnection(connectionPath);
			if (connection == null) throw new SandLocalExecConnectionError(NO_CONNECTION_MESSAGE);
			return connection;
		},
		// Self-heal the box-recreate-while-desktop-quit strand: after repeated
		// connect failures the descriptor likely points at a dead box and — with the
		// desktop closed — nothing is refreshing it. Use the desktop-handed,
		// box-bound credential to re-resolve the recreated box's connection straight
		// from the backend (no desktop), and rewrite the descriptor so the next
		// reconnect dials the live box. A missing credential (e.g. the desktop never
		// handed one off, or a dev env-descriptor box that can't recreate) or a
		// rejected exchange leaves the descriptor as-is and the loop keeps retrying.
		onConnectionStale: async (): Promise<void> => {
			const handoff = await readLocalExecDaemonCredential(credentialPath);
			if (handoff == null) return;
			const fresh = await resolveConnectionFromBackend({
				backendUrl: handoff.backendUrl,
				credential: handoff.credential,
			});
			if (fresh == null) return;
			await writeLocalExecDaemonConnection(fresh, connectionPath);
		},
		isLocalUseBlocked: async ({ approvalId, describes, terminalsFolder }) => {
			const permission = settingsStore.getLocalToolPermission();
			if (permission === "never") return SAND_LOCAL_TOOLS_DISABLED_MESSAGE;
			if (permission === "always") return undefined;
			if (approvalId == null || approvalId.length === 0 || describes == null) {
				return SAND_LOCAL_TOOLS_UNAPPROVED_MESSAGE;
			}
			const approval = (await readLiveLocalToolApprovals(approvalsPath, retirementsPath)).get(
				approvalId,
			);
			if (approval == null) return SAND_LOCAL_TOOLS_UNAPPROVED_MESSAGE;
			return localToolApprovalCovers(
				{
					...approval,
					...(approval.action === "run-command" ? { resourcePath: terminalsFolder } : {}),
				},
				describes,
			)
				? undefined
				: SAND_LOCAL_TOOLS_UNAPPROVED_MESSAGE;
		},
		onApprovalRetired: async (approvalId) => {
			await retireLocalToolApproval(approvalId, approvalsPath, retirementsPath).catch(
				(error: unknown) => {
					console.error(
						`[local-exec-daemon] failed to retire approval ${approvalId}: ${errorLogTag(error)}`,
					);
				},
			);
		},
		onInflightChange: publishDiscovery
			? (count: number): void => {
					lastInflightCount = count;
					void publishDaemonDiscovery();
				}
			: undefined,
		isSupervised: async (): Promise<boolean> => {
			const heartbeat = await readLocalExecSupervisorHeartbeat(supervisorHeartbeatPath);
			return Date.now() - heartbeat.at <= SAND_LOCAL_EXEC_SUPERVISED_WINDOW_MS;
		},
		variant: getSandVariant(),
	});
	provider.start();

	if (publishDiscovery) {
		await publishDaemonDiscovery();
	}

	return {
		close: async (): Promise<void> => {
			provider.close();
			if (publishDiscovery) {
				await clearLocalExecDaemonDiscovery(options.discoveryPath).catch((error: unknown) => {
					console.error(
						`[local-exec-daemon] failed to clear discovery record on close: ${errorLogTag(error)}`,
					);
				});
			}
		},
	};
}
