import type { AuthState, ConnectionState } from '../fsm/types.js';

/**
 * Whether create() should call connect() on an existing lifecycle instead of
 * deduping to the old connect promise.
 *
 * When auth is `expired` but the connection is already in a terminal failure
 * state, we allow reconnect so the user can recover without toggling the
 * server off/on (OAuth can run again on connect).
 */
export function shouldReconnectExistingLifecycle(
	connectionState: ConnectionState,
	authState: AuthState,
): boolean {
	if (authState.type === 'needsUserAuth') {
		return false;
	}

	if (authState.type === 'expired') {
		switch (connectionState.type) {
			case 'idle':
			case 'transient_failure':
			case 'dormant':
				return true;
			case 'failed':
			case 'closed':
				return connectionState.automaticRetry !== false;
			case 'connecting':
			case 'connected':
			case 'degraded':
				return false;
			default: {
				const _exhaustive: never = connectionState;
				return _exhaustive;
			}
		}
	}

	switch (connectionState.type) {
		case 'idle':
		case 'transient_failure':
		case 'dormant':
			return true;
		case 'failed':
		case 'closed':
			return connectionState.automaticRetry !== false;
		case 'connecting':
		case 'connected':
		case 'degraded':
			return false;
		default: {
			const _exhaustive: never = connectionState;
			return _exhaustive;
		}
	}
}
