import fs, { access } from "node:fs/promises";
import os from "node:os";
import {
  basename,
  dirname,
  isAbsolute,
  join,
  parse,
  relative,
} from "node:path";
import { type Context, createContext } from "@anysphere/context";
import type { IgnoreMapping } from "@anysphere/shell-exec";
import {
  asyncMapValues,
  isPathWithin,
  LRUCache,
  normalizeToUnixPath,
  PromiseQueue,
  readText,
} from "@anysphere/utils";
import ignore, { type Ignore } from "ignore";
import picomatch from "picomatch";
import { resolvePath, resolveRealPathStrict } from "../common.js";
import type { GitExecutor } from "../git-executor.js";
import { RipwalkTtlCache } from "../ripwalk-cache.js";
import {
  DEFAULT_GLOB_IGNORE_DIRS,
  findGitRoot,
  getGitRemoteUrl,
  toHostPath,
} from "./common.js";
import type { TeamSettingsService } from "./team-settings-service.js";

/** Ignore files a workspace walk collects; see `findFilesWithRipgrep`. */
const IGNORE_FILE_NAMES = [".gitignore", ".cursorignore"] as const;

// ---------------------------------------------------------------------------
// Branded path type -- exported so callers can mint it via
// resolvePathForIgnoreService() before passing to the IgnoreService interface.
// ---------------------------------------------------------------------------

declare const ResolvedIgnorePathBrand: unique symbol;

/**
 * A path that has been resolved through resolveRealPathStrict: absolute,
 * normalized, and symlinks followed. Produced by resolvePathForIgnoreService()
 * or root resolution at init -- prevents accidentally passing raw caller
 * input into the ignore-checking internals.
 */
export type ResolvedIgnorePath = string & {
  readonly [ResolvedIgnorePathBrand]: never;
};

function makeResolvedIgnorePath(path: string): ResolvedIgnorePath {
  return path as ResolvedIgnorePath;
}

/**
 * Mint a ResolvedIgnorePath without performing any resolution. Use only
 * when the path has already been verified through another mechanism
 * (e.g. resolvePermissionsPath).
 */
export function unsafeMintResolvedIgnorePath(path: string): ResolvedIgnorePath {
  return path as ResolvedIgnorePath;
}

/**
 * Resolve an absolute path for use with IgnoreService methods. Follows
 * symlinks via resolveRealPathStrict. Returns null when the path is
 * unverifiable (EACCES, ELOOP) or not absolute -- callers should treat
 * null as "fail closed" (blocked).
 *
 * Callers are responsible for making the path absolute before calling.
 * For workspace-root-relative paths (e.g. ripgrep output), resolve against
 * the correct workspace root first via `resolvePath(relativePath, root)`.
 * This forces multi-root awareness at the call site.
 */
export async function resolvePathForIgnoreService(
  absolutePath: string
): Promise<ResolvedIgnorePath | null> {
  if (!isAbsolute(absolutePath)) {
    return null;
  }
  const resolved = await resolveRealPathStrict(absolutePath);
  if (resolved === null) return null;
  return makeResolvedIgnorePath(resolved);
}

export interface IgnoreService {
  isIgnoredByAny(filePath: ResolvedIgnorePath): Promise<boolean>;
  isGitIgnored(filePath: ResolvedIgnorePath): Promise<boolean>;
  isCursorIgnored(filePath: ResolvedIgnorePath): Promise<boolean>;
  isRepoBlocked(filePath: ResolvedIgnorePath): Promise<boolean>;
  listCursorIgnoreFilesByRoot(root: string): Promise<string[]>;
  getCursorIgnoreMapping(): Promise<IgnoreMapping>;
  getGitIgnoreMapping(): Promise<IgnoreMapping>;
  /**
   * Get glob patterns that should be excluded for repo blocking.
   * These can be passed directly to ripwalk/ripgrep for native filtering.
   * @param rootDirectory The directory that will be passed as root to ripwalk
   * @returns Glob patterns relative to rootDirectory that should be excluded
   */
  getRepoBlockExcludeGlobs(rootDirectory: string): Promise<string[]>;
}

export class LazyIgnoreService implements IgnoreService {
  private readonly ignoreServicePromise: Promise<LocalIgnoreService>;

  /**
   * @param gitExecutor Git executor instance.
   * @param teamSettingsService Team settings for repo blocking rules.
   * @param rootDirectories Workspace root directories. Callers:
   *   - VSCode extension: passes workspaceFolders.map(f => f.uri.fsPath)
   *   - CLI with explicit root: passes [workspaceRoot]
   *   - CLI/SDK without root: omits this, falling back to [process.cwd()].
   *     This is correct for CLI tools where the user runs from their project
   *     directory, but the path is not guaranteed to be canonical (may be a
   *     symlink). Roots are resolved via resolveRealPathStrict at init time.
   */
  constructor(
    gitExecutor: GitExecutor,
    teamSettingsService: TeamSettingsService | undefined,
    rootDirectories?: string[]
  ) {
    this.ignoreServicePromise = LocalIgnoreService.init(
      createContext(),
      gitExecutor,
      rootDirectories ?? [process.cwd()],
      teamSettingsService
    );
  }

  isIgnoredByAny(filePath: ResolvedIgnorePath): Promise<boolean> {
    return this.ignoreServicePromise.then(x => x.isIgnoredByAny(filePath));
  }

  isGitIgnored(filePath: ResolvedIgnorePath): Promise<boolean> {
    return this.ignoreServicePromise.then(x => x.isGitIgnored(filePath));
  }

  isCursorIgnored(filePath: ResolvedIgnorePath): Promise<boolean> {
    return this.ignoreServicePromise.then(x => x.isCursorIgnored(filePath));
  }

  isRepoBlocked(filePath: ResolvedIgnorePath): Promise<boolean> {
    return this.ignoreServicePromise.then(x => x.isRepoBlocked(filePath));
  }

  listCursorIgnoreFilesByRoot(root: string): Promise<string[]> {
    return this.ignoreServicePromise.then(x =>
      x.listCursorIgnoreFilesByRoot(root)
    );
  }

  getCursorIgnoreMapping(): Promise<IgnoreMapping> {
    return this.ignoreServicePromise.then(x => x.getCursorIgnoreMapping());
  }

  getGitIgnoreMapping(): Promise<IgnoreMapping> {
    return this.ignoreServicePromise.then(x => x.getGitIgnoreMapping());
  }

  getRepoBlockExcludeGlobs(rootDirectory: string): Promise<string[]> {
    return this.ignoreServicePromise.then(x =>
      x.getRepoBlockExcludeGlobs(rootDirectory)
    );
  }

  handleCursorIgnoreCreated(filePath: ResolvedIgnorePath): Promise<void> {
    return this.ignoreServicePromise.then(x =>
      x.handleCursorIgnoreCreated(filePath)
    );
  }

  handleCursorIgnoreChanged(filePath: ResolvedIgnorePath): Promise<void> {
    return this.ignoreServicePromise.then(x =>
      x.handleCursorIgnoreChanged(filePath)
    );
  }

  handleCursorIgnoreDeleted(filePath: ResolvedIgnorePath): Promise<void> {
    return this.ignoreServicePromise.then(x =>
      x.handleCursorIgnoreDeleted(filePath)
    );
  }
}

// NB: Not exactly the best metric but it's a good approximation of
// how beefy their computer is - clamp between [1, NR_CPUS/2, 8]
const maxConcurrentSearches = Math.min(
  8,
  Math.max(1, Math.floor(os.availableParallelism() / 2))
);

export class LocalIgnoreService implements IgnoreService {
  private static ripwalkCache: RipwalkTtlCache | undefined;
  private gitIgnoreCache: LRUCache<string, boolean> = new LRUCache({
    max: 2000,
  });
  private cursorIgnoreCache: LRUCache<string, boolean> = new LRUCache({
    max: 2000,
  });
  private gitRootCache: LRUCache<string, string[]> = new LRUCache({
    max: 1000,
  });
  private gitRemoteUrlCache: LRUCache<string, string> = new LRUCache({
    max: 200,
  });
  private hasGitDirCache: LRUCache<string, boolean> = new LRUCache({
    max: 1000,
  });
  private static readonly promiseQueue = new PromiseQueue({
    max: maxConcurrentSearches,
  });

  // Separate caches for parsed Ignore instances so .cursorignore and .gitignore
  // patterns for the same directory don't collide.
  private gitParsedIgnoreCache: Map<string, Ignore> = new Map();
  private cursorParsedIgnoreCache: Map<string, Ignore> = new Map();

  // Git repo mapping: path → upstream URL (includes submodules)
  // Lazily initialized on first use, then cached
  private gitRepoMappingPromise:
    | Promise<Map<string, string | undefined>>
    | undefined;

  // Canonical ~/.cursor path; lazily resolved on first allowlist check.
  private cursorDataDirPromise: Promise<string> | undefined;

  private constructor(
    private readonly gitExecutor: GitExecutor,
    private readonly gitIgnoreMapping: IgnoreMapping,
    private readonly cursorIgnoreMapping: IgnoreMapping,
    private readonly teamSettingsService: TeamSettingsService | undefined,
    /** Canonical workspace roots -- resolved via resolveRealPathStrict at init. */
    private readonly rootDirectories: ResolvedIgnorePath[]
  ) {}

  private static getRipwalkCache(): RipwalkTtlCache {
    LocalIgnoreService.ripwalkCache ??= new RipwalkTtlCache();
    return LocalIgnoreService.ripwalkCache;
  }

  private getIgnoreInstance(
    path: string,
    patterns: string[],
    cache: Map<string, Ignore>
  ): Ignore {
    let instance = cache.get(path);
    if (!instance) {
      instance = ignore().add(patterns);
      cache.set(path, instance);
    }
    return instance;
  }

  /**
   * Check if there are no workspace folders (indicated by empty ignore mappings).
   * When no workspace folders exist, the ignore mappings remain empty after initialization.
   */
  private hasNoWorkspaceFolders(): boolean {
    return (
      Object.keys(this.gitIgnoreMapping).length === 0 &&
      Object.keys(this.cursorIgnoreMapping).length === 0
    );
  }

  /**
   * Resolve a caller-supplied root directory for helper lookups.
   *
   * We intentionally do not cache this result: unlike init-time workspace roots,
   * a symlinked lookup root can retarget between calls. These helper methods are
   * low-frequency (e.g. once per grep/ls invocation), so a fresh realpath is
   * preferable to a potentially stale cached answer.
   */
  private async resolveLookupRoot(rootDirectory: string): Promise<string> {
    const resolved = await resolveRealPathStrict(rootDirectory);
    return resolved ?? resolvePath(rootDirectory);
  }

  public static async init(
    ctx: Context,
    gitExecutor: GitExecutor,
    rootDirectories: string[],
    teamSettingsService: TeamSettingsService | undefined
  ): Promise<LocalIgnoreService> {
    // Resolve roots to canonical paths by following symlinks.
    //
    // Why: VSCode's folder.uri.fsPath and process.cwd() don't follow symlinks.
    // After file paths are realpath'd (via resolvePathForIgnoreService), isPathWithin
    // comparisons fail if roots aren't also realpath'd. For example, a root of
    // ~/my-project (symlink to /data/repos/actual) would not match a file at
    // /data/repos/actual/foo.ts.
    //
    // If a root can't be resolved (EACCES, ELOOP), we keep it as-is with a
    // warning rather than dropping it, to avoid silently disabling all ignore
    // rules for that workspace.
    const resolvedRoots = await asyncMapValues(
      rootDirectories,
      async (root): Promise<ResolvedIgnorePath> => {
        const resolved = await resolveRealPathStrict(root);
        if (resolved === null) {
          console.warn(
            `[IgnoreService] Cannot resolve workspace root, using as-is: ${root}`
          );
          return makeResolvedIgnorePath(root);
        }
        return makeResolvedIgnorePath(resolved);
      }
    );

    const gitIgnoreMapping: IgnoreMapping = {};
    const cursorIgnoreMapping: IgnoreMapping = {};

    // Only initialize if we're in a git repository (any parent directory has .git folder)
    const reposInGitRoots = (
      await asyncMapValues(resolvedRoots, root =>
        findGitRoot(ctx, gitExecutor, root)
      )
    ).filter(root => root !== null);

    // When both mappings stay empty (no git), both isCursorIgnored and isGitIgnored use
    // handleManualLookupWhenNoWorkspaceDirs() to check .cursorignore and .gitignore.
    if (reposInGitRoots.length > 0) {
      await Promise.all([
        LocalIgnoreService.initializeIgnoreMapping(
          reposInGitRoots,
          ".gitignore",
          gitIgnoreMapping
        ),
        LocalIgnoreService.initializeIgnoreMapping(
          resolvedRoots,
          ".cursorignore",
          cursorIgnoreMapping
        ),
      ]);
    }

    return new LocalIgnoreService(
      gitExecutor,
      gitIgnoreMapping,
      cursorIgnoreMapping,
      teamSettingsService,
      resolvedRoots
    );
  }

  private static async preloadHierarchy(
    startPath: string,
    ignoreFileName: string,
    mapping: IgnoreMapping,
    processedDirs?: Set<string>
  ): Promise<void> {
    let currentPath = resolvePath(startPath);
    const rootPath = parse(currentPath).root;

    // Walk up the directory tree from the workspace root
    while (currentPath !== rootPath) {
      // Skip if we've already processed this directory
      if (processedDirs?.has(currentPath)) {
        const parentPath = dirname(currentPath);
        if (parentPath === currentPath) break; // Reached root
        currentPath = parentPath;
        continue;
      }

      if (mapping[currentPath] === undefined) {
        await LocalIgnoreService.handleHierarchyIgnore(
          currentPath,
          ignoreFileName,
          mapping
        );
      }

      // Mark as processed
      processedDirs?.add(currentPath);

      const parentPath = dirname(currentPath);
      if (parentPath === currentPath) break; // Reached root
      currentPath = parentPath;
    }
  }

  private static async handleHierarchyIgnore(
    dir: string,
    ignoreFileName: string,
    mapping: IgnoreMapping
  ): Promise<void> {
    const ignoreFilePath = join(dir, ignoreFileName);
    try {
      await access(ignoreFilePath, fs.constants.F_OK);
      const content = await readText(ignoreFilePath);

      const ignoreRules = LocalIgnoreService.parseIgnoreRules(content);
      // Store patterns as string array, not Ignore instance
      mapping[dir] = ignoreRules;
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "ENOENT") {
        // File doesn't exist, mark as checked with empty array so we don't check again
        mapping[dir] = [];
      } else {
        console.error(
          `Error reading ${ignoreFileName} file at ${ignoreFilePath}:`,
          error
        );
        mapping[dir] = [];
      }
    }
  }

  private static async initializeIgnoreMapping(
    rootDirectories: string[],
    ignoreFileName: string,
    mapping: IgnoreMapping
  ): Promise<void> {
    try {
      // Dedupe root directories - remove any root that is inside another root
      const deduplicatedRoots =
        LocalIgnoreService.deduplicateRootDirectories(rootDirectories);

      // Find ignore files in all roots
      const ignoreFiles = await LocalIgnoreService.promiseQueue.enqueueList(
        deduplicatedRoots,
        root => LocalIgnoreService.findFilesWithRipgrep(root, ignoreFileName)
      );

      const allIgnoreFiles = Array.from(ignoreFiles.values()).flat();

      // Process all ignore files
      await Promise.all(
        allIgnoreFiles.map(async filePath => {
          try {
            const content = await readText(filePath);
            const ignoreRules = LocalIgnoreService.parseIgnoreRules(content);
            const ignorePath = dirname(filePath);

            // Store patterns as string array, not Ignore instance
            mapping[ignorePath] = ignoreRules;
          } catch (error) {
            console.error(
              `Error processing ${ignoreFileName} file at ${filePath}:`,
              error
            );
          }
        })
      );

      // Preload hierarchy for each root, avoiding duplicate work
      const processedDirs = new Set<string>();
      for (const root of deduplicatedRoots) {
        await LocalIgnoreService.preloadHierarchy(
          root,
          ignoreFileName,
          mapping,
          processedDirs
        );
      }
    } catch (error) {
      console.error(
        `Error initializing ignore mapping for ${ignoreFileName}:`,
        error
      );
    }
  }

  /**
   * Locate every ignore file under `rootDirectory`, bucketed by file name.
   *
   * `.gitignore` and `.cursorignore` are collected by one walk with one set of
   * options, so the two `init` mappings share a single ripgrep process through
   * the walk cache instead of racing two full traversals of the workspace.
   */
  private static async findFilesWithRipgrep(
    rootDirectory: string,
    fileName: string
  ): Promise<string[]> {
    const ctx = createContext();
    const files: string[] = [];
    const ripwalkOptions = {
      root: rootDirectory,
      includeGlobs: IGNORE_FILE_NAMES.map(name => `**/${name}`),
      excludeGlobs: DEFAULT_GLOB_IGNORE_DIRS,
      source: "ignore_scan" as const,
    };
    const ripwalkResult = LocalIgnoreService.getRipwalkCache().walk(
      ctx,
      ripwalkOptions
    );
    for await (const path of ripwalkResult.lines) {
      if (basename(path) === fileName) {
        files.push(join(rootDirectory, path));
      }
    }
    return files;
  }

  private async handleManualLookupWhenNoWorkspaceDirs(
    absolutePath: string,
    ignoreFileName: string
  ): Promise<boolean> {
    const mapping: IgnoreMapping = {};
    let cur = dirname(absolutePath);
    const rootPath = parse(cur).root;

    // Walk from path's directory up to and including filesystem root so
    // root-level ignore files (e.g. /.cursorignore or C:\.cursorignore) are read.
    while (true) {
      const ignoreFilePath = join(cur, ignoreFileName);
      try {
        const content = await readText(ignoreFilePath);
        const patterns = LocalIgnoreService.parseIgnoreRules(content);
        if (patterns.length > 0) {
          mapping[cur] = patterns;
        }
      } catch {}
      if (cur === rootPath) break;
      cur = dirname(cur);
    }

    // without a workspace, the cache is not automatically invalidated when .cursorignore files are edited.
    // the ignore.add(patterns) creates a new IgnoreInstance everytime we execute.
    return this.testIgnored(absolutePath, mapping, (_path, patterns) =>
      ignore().add(patterns)
    );
  }

  // ---------------------------------------------------------------------------
  // Path resolution -- the single gate into the ignore-checking internals
  //
  // All paths are canonicalized via resolveRealPathStrict (realpath) so that
  // symlinks are followed and comparisons against mapping keys are consistent.
  //
  // Failure modes when realpath fails (EACCES, ELOOP):
  //  - Target file path (resolvePathForIgnoreService): returns null -> callers
  //    treat as ignored (fail-closed, conservative for security).
  //  - Watcher event: the caller (cursorIgnoreWatcher) resolves via
  //    resolvePathForIgnoreService and skips unresolvable paths; the init-time
  //    mapping stays intact so rules continue to apply.
  //  - Workspace root at init: kept as-is with a warning rather than dropped,
  //    to avoid silently disabling all ignore rules for that workspace.
  // ---------------------------------------------------------------------------

  // ---------------------------------------------------------------------------
  // Public API -- accepts ResolvedIgnorePath (caller resolves via
  // resolvePathForIgnoreService), delegates to private check methods.
  // ---------------------------------------------------------------------------

  public async isIgnoredByAny(filePath: ResolvedIgnorePath): Promise<boolean> {
    const [gitIgnored, cursorIgnored, repoBlocked] = await Promise.all([
      this.checkGitIgnored(filePath),
      this.checkCursorIgnored(filePath),
      this.checkRepoBlocked(filePath),
    ]);
    return gitIgnored || cursorIgnored || repoBlocked;
  }

  public async isGitIgnored(filePath: ResolvedIgnorePath): Promise<boolean> {
    return this.checkGitIgnored(filePath);
  }

  public async isCursorIgnored(filePath: ResolvedIgnorePath): Promise<boolean> {
    return this.checkCursorIgnored(filePath);
  }

  // ---------------------------------------------------------------------------
  // Private check methods -- accept only ResolvedIgnorePath
  // ---------------------------------------------------------------------------

  private async checkGitIgnored(
    absolutePath: ResolvedIgnorePath
  ): Promise<boolean> {
    if (this.hasNoWorkspaceFolders()) {
      return this.handleManualLookupWhenNoWorkspaceDirs(
        absolutePath,
        ".gitignore"
      );
    }

    // Check cache first
    const cached = this.gitIgnoreCache.get(absolutePath);
    if (cached !== undefined) {
      return cached;
    }

    // Check if we need to populate hierarchy for this path
    await this.populateHierarchyIfNeeded(
      absolutePath,
      ".gitignore",
      this.gitIgnoreMapping
    );

    const result = this.checkIgnored(
      absolutePath,
      this.gitIgnoreMapping,
      this.gitParsedIgnoreCache
    );
    this.gitIgnoreCache.set(absolutePath, result);
    return result;
  }

  private async checkCursorIgnored(
    absolutePath: ResolvedIgnorePath
  ): Promise<boolean> {
    if (this.hasNoWorkspaceFolders()) {
      return this.handleManualLookupWhenNoWorkspaceDirs(
        absolutePath,
        ".cursorignore"
      );
    }

    // Check cache first
    const cached = this.cursorIgnoreCache.get(absolutePath);
    if (cached !== undefined) {
      return cached;
    }

    // Check if we need to populate hierarchy for this path
    await this.populateHierarchyIfNeeded(
      absolutePath,
      ".cursorignore",
      this.cursorIgnoreMapping
    );

    const result = this.checkIgnored(
      absolutePath,
      this.cursorIgnoreMapping,
      this.cursorParsedIgnoreCache
    );
    this.cursorIgnoreCache.set(absolutePath, result);
    return result;
  }

  private async populateHierarchyIfNeeded(
    filePath: string,
    ignoreFileName: string,
    mapping: IgnoreMapping
  ): Promise<void> {
    let currentPath = dirname(resolvePath(filePath));
    const toAdd: string[] = [];
    const rootPath = parse(currentPath).root;

    // Walk up the directory tree
    while (currentPath !== rootPath) {
      // Skip if we're still within the workspace
      if (
        this.rootDirectories.some(root =>
          isPathWithin({ basePath: root, targetPath: currentPath })
        )
      ) {
        currentPath = dirname(currentPath);
        continue;
      }

      // If already processed, we can stop
      if (mapping[currentPath] !== undefined) {
        break;
      }

      toAdd.push(currentPath);
      const parentPath = dirname(currentPath);
      if (parentPath === currentPath) break; // Reached root
      currentPath = parentPath;
    }

    // Process any new directories we found
    if (toAdd.length > 0) {
      await LocalIgnoreService.promiseQueue.enqueueList(toAdd, dir =>
        LocalIgnoreService.handleHierarchyIgnore(dir, ignoreFileName, mapping)
      );

      // Clear the appropriate cache
      if (ignoreFileName === ".gitignore") {
        this.gitIgnoreCache.clear();
      } else {
        this.cursorIgnoreCache.clear();
      }
    }
  }

  /**
   * Test whether a path is ignored by a mapping. The getInstance callback either
   * returns a cached Ignore instance (workspace path) or a fresh one (no-workspace).
   */
  private testIgnored(
    absolutePath: string,
    mapping: IgnoreMapping,
    getInstance: (ignorePath: string, patterns: string[]) => Ignore
  ): boolean {
    // Check each ignore mapping to see if the file should be ignored
    for (const [ignorePath, patterns] of Object.entries(mapping)) {
      if (patterns.length === 0) {
        continue;
      }
      if (!isPathWithin({ basePath: ignorePath, targetPath: absolutePath })) {
        continue;
      }
      const relativePath = relative(ignorePath, absolutePath);

      // Skip if relativePath is empty (checking the directory that contains the ignore file itself)
      if (relativePath === "") {
        continue;
      }

      const ignoreInstance = getInstance(ignorePath, patterns);

      // Normalize separators for the ignore library (expects forward slashes).
      // On Windows, path.relative produces backslash-separated paths.
      const normalizedPath = normalizeToUnixPath(relativePath);

      // The `ignore` library's test method tells us if the path is ignored.
      // We test both with and without trailing slash because:
      // - Patterns like "secret/" only match directories (paths ending with /)
      // - Patterns like "secret-file.txt" match files (paths without /)
      // Testing both forms ensures directory patterns match directory paths.
      const testResult = ignoreInstance.test(normalizedPath);
      if (testResult.ignored && !testResult.unignored) {
        return true;
      }

      // Also test with trailing slash for directory patterns
      const testResultWithSlash = ignoreInstance.test(`${normalizedPath}/`);
      if (testResultWithSlash.ignored && !testResultWithSlash.unignored) {
        return true;
      }
    }
    return false;
  }

  private checkIgnored(
    absolutePath: string,
    mapping: IgnoreMapping,
    cache: Map<string, Ignore>
  ): boolean {
    return this.testIgnored(absolutePath, mapping, (path, patterns) =>
      this.getIgnoreInstance(path, patterns, cache)
    );
  }

  async listCursorIgnoreFilesByRoot(root: string): Promise<string[]> {
    const lookupRoot = await this.resolveLookupRoot(root);
    const ignoreFiles: string[] = [];
    for (const [base, patterns] of Object.entries(this.cursorIgnoreMapping)) {
      if (patterns.length === 0) {
        continue;
      }
      if (!isPathWithin({ basePath: lookupRoot, targetPath: base })) {
        continue;
      }
      const filePath = join(base, ".cursorignore");
      try {
        await access(filePath);
        ignoreFiles.push(filePath);
      } catch {
        // .cursorignore was deleted or never existed in this filesystem
        // context (e.g. worktree). Skip it so ripgrep doesn't get a
        // --cursor-ignore pointing at a missing file.
      }
    }
    return ignoreFiles;
  }

  async getCursorIgnoreMapping(): Promise<IgnoreMapping> {
    // The mapping is already fully populated during initialization
    // since ignoreServicePromise waits for complete init() completion
    // Return a copy of the mapping to prevent external modifications
    return { ...this.cursorIgnoreMapping };
  }

  async getGitIgnoreMapping(): Promise<IgnoreMapping> {
    return { ...this.gitIgnoreMapping };
  }

  private static deduplicateRootDirectories(roots: string[]): string[] {
    // Resolve all paths to absolute paths
    const resolvedRoots = roots.map(root => resolvePath(root));

    // Sort by length (shorter paths first) to efficiently check containment
    const sortedRoots = [...resolvedRoots].sort((a, b) => a.length - b.length);

    const deduplicated: string[] = [];

    for (const root of sortedRoots) {
      // Check if this root is inside any already-added root
      const isContained = deduplicated.some(
        existing =>
          root.startsWith(`${existing}/`) || root.startsWith(`${existing}\\`)
      );

      if (!isContained) {
        deduplicated.push(root);
      }
    }

    return deduplicated;
  }

  private static parseIgnoreRules(raw: string): string[] {
    // Strip Windows line endings, leading whitespace and comment lines (starting with '#').
    return raw
      .split("\n")
      .map(line => line.replace(/\r$/, "").trimStart())
      .filter(line => line !== "" && !line.startsWith("#"));
  }

  // Method to clear caches when files change
  public clearCaches(): void {
    this.gitIgnoreCache.clear();
    this.cursorIgnoreCache.clear();
    this.gitRootCache.clear();
    this.gitRemoteUrlCache.clear();
    this.hasGitDirCache.clear();
    this.gitParsedIgnoreCache.clear();
    this.cursorParsedIgnoreCache.clear();
  }

  public async handleCursorIgnoreCreated(
    filePath: ResolvedIgnorePath
  ): Promise<void> {
    const ignorePath = dirname(filePath);

    const content = await readText(filePath);
    const ignoreRules = LocalIgnoreService.parseIgnoreRules(content);
    this.cursorIgnoreMapping[ignorePath] = ignoreRules;
    this.cursorParsedIgnoreCache.delete(ignorePath);
    this.cursorIgnoreCache.clear();
  }

  public async handleCursorIgnoreChanged(
    filePath: ResolvedIgnorePath
  ): Promise<void> {
    const ignorePath = dirname(filePath);

    const content = await readText(filePath);
    const ignoreRules = LocalIgnoreService.parseIgnoreRules(content);
    this.cursorIgnoreMapping[ignorePath] = ignoreRules;
    this.cursorParsedIgnoreCache.delete(ignorePath);
    this.cursorIgnoreCache.clear();
  }

  public handleCursorIgnoreDeleted(filePath: ResolvedIgnorePath): void {
    const ignorePath = dirname(filePath);

    this.cursorIgnoreMapping[ignorePath] = [];
    this.cursorParsedIgnoreCache.delete(ignorePath);
    this.cursorIgnoreCache.clear();
  }

  private async findGitRootsForFile(filePath: string): Promise<string[]> {
    const absolutePath = resolvePath(filePath);
    // Callers pass both file paths and working directories. Include the input
    // path itself so repo-root working directories still discover their .git.
    const directoryPath = absolutePath;

    const cached = this.gitRootCache.get(directoryPath);
    if (cached !== undefined) {
      return cached;
    }

    const gitRoots: string[] = [];
    const pathsToCheck: string[] = [];
    const uncachedPaths: string[] = [];

    let currentPath = directoryPath;
    const rootPath = parse(currentPath).root;

    while (currentPath !== rootPath) {
      pathsToCheck.push(currentPath);

      if (this.hasGitDirCache.get(currentPath) === undefined) {
        uncachedPaths.push(currentPath);
      }

      const parentPath = dirname(currentPath);
      if (parentPath === currentPath) break;
      currentPath = parentPath;
    }

    if (uncachedPaths.length > 0) {
      const checkPromises: Promise<[string, boolean]>[] = uncachedPaths.map(
        path =>
          access(join(path, ".git"), fs.constants.F_OK)
            .then(() => [path, true] as [string, boolean])
            .catch(() => [path, false] as [string, boolean])
      );

      const results = await Promise.all(checkPromises);

      for (const [path, hasGit] of results) {
        this.hasGitDirCache.set(path, hasGit);
      }
    }

    for (const path of pathsToCheck) {
      const hasGit = this.hasGitDirCache.get(path);
      if (hasGit === true) {
        gitRoots.push(path);
      }
    }

    this.gitRootCache.set(directoryPath, gitRoots);
    return gitRoots;
  }

  public async isRepoBlocked(filePath: ResolvedIgnorePath): Promise<boolean> {
    return this.checkRepoBlocked(filePath);
  }

  private async checkRepoBlocked(
    absolutePath: ResolvedIgnorePath
  ): Promise<boolean> {
    const gitRoots = await this.findGitRootsForFile(absolutePath);

    // Cached for 5 mins
    const teamReposResponse = await this.teamSettingsService?.getTeamRepos();
    if (!teamReposResponse) {
      return false;
    }
    const blockedRepos = teamReposResponse.repos ?? [];
    // Server-controlled kill switch (ENT-3569): when the backend engages it,
    // drop the allowlist so only blocklist enforcement remains. This lets the
    // fail-closed allowlist enforcement be disabled without a client release if
    // it ever over-blocks a legitimately-approved repo. The UI blocked-indicator
    // reads its own data path and is unaffected.
    const allowedRepos = teamReposResponse.disableLocalExecAllowlistEnforcement
      ? []
      : (teamReposResponse.allowedRepos ?? []);
    if (blockedRepos.length === 0 && allowedRepos.length === 0) {
      return false;
    }

    if (gitRoots.length === 0) {
      return this.checkNonRepoPathBlockedByAllowlist(
        absolutePath,
        allowedRepos
      );
    }

    // When the team configured a repo allowlist, a file inside a git repo is
    // blocked unless it matches at least one allowed repo (URL + pattern).
    // Mirrors CursorIgnoreService.isAdminBlocked's allowlist-miss semantics:
    // the allowlist is evaluated against the innermost containing repo with a
    // resolvable remote URL (gitRoots is ordered innermost first), so nesting
    // a non-approved clone inside an approved repo does not grant access, and
    // a repo with no resolvable remote URL fails closed in allowlist mode.
    let matchesAllowlist = allowedRepos.length === 0;
    let allowlistEvaluated = false;

    for (const gitRoot of gitRoots) {
      let repoUrl: string | undefined;

      if (this.gitRemoteUrlCache.has(gitRoot)) {
        repoUrl = this.gitRemoteUrlCache.get(gitRoot)!;
      } else {
        repoUrl = await getGitRemoteUrl(
          createContext(),
          this.gitExecutor,
          gitRoot
        );
        // Only cache if we got a URL (don't cache undefined)
        if (repoUrl !== undefined) {
          this.gitRemoteUrlCache.set(gitRoot, repoUrl);
        }
      }

      if (repoUrl === undefined) {
        continue;
      }
      const resolvedRepoUrl = repoUrl;

      const relativePath = relative(gitRoot, absolutePath) || ".";

      // Find ALL matching blocked repos (exact + glob patterns) and check if
      // the file matches any of their patterns. Blocklist wins over allowlist.
      for (const repo of blockedRepos) {
        if (!this.doesRepoUrlMatch(repo.url, resolvedRepoUrl)) {
          continue;
        }
        for (const pattern of repo.patterns || []) {
          if (this.matchGlob(pattern.pattern, relativePath)) {
            return true;
          }
        }
      }

      if (allowedRepos.length > 0 && !allowlistEvaluated) {
        allowlistEvaluated = true;
        matchesAllowlist = allowedRepos.some(
          repo =>
            this.doesRepoUrlMatch(repo.url, resolvedRepoUrl) &&
            (repo.patterns || []).some(pattern =>
              this.matchGlob(pattern.pattern, relativePath)
            )
        );
      }
    }

    return !matchesAllowlist;
  }

  /**
   * Allowlist enforcement for paths outside any git repo, mirroring
   * CursorIgnoreService.isAdminBlocked's no-repo branch: when the team
   * configured a repo allowlist, non-git content is blocked (so stripping
   * `.git` from an unapproved clone does not bypass the allowlist), except:
   *  - paths under the user's Cursor data directory (~/.cursor/), which hold
   *    internal agent data (terminal transcripts, plans, ...) that must stay
   *    accessible regardless of the repo allowlist, and
   *  - paths matched by allow entries whose URL is the wildcard "*" or a
   *    path pattern (e.g. "data/**") rather than a git URL.
   */
  private async checkNonRepoPathBlockedByAllowlist(
    absolutePath: ResolvedIgnorePath,
    allowedRepos: ReadonlyArray<{
      url: string;
      patterns?: ReadonlyArray<{ pattern: string }>;
    }>
  ): Promise<boolean> {
    if (allowedRepos.length === 0) {
      return false;
    }

    const cursorDataDir = await this.getCursorDataDir();
    if (isPathWithin({ basePath: cursorDataDir, targetPath: absolutePath })) {
      return false;
    }

    const relativePath = this.getWorkspaceRelativePath(absolutePath);
    for (const repo of allowedRepos) {
      if (this.isWildcardUrl(repo.url)) {
        if (
          (repo.patterns || []).some(pattern =>
            this.matchGlob(pattern.pattern, relativePath)
          )
        ) {
          return false;
        }
      } else if (this.isPathPatternUrl(repo.url)) {
        if (this.matchGlob(repo.url, relativePath)) {
          return false;
        }
      }
    }

    return true;
  }

  /** A repo URL entry of "*" applies to all repos/workspaces. */
  private isWildcardUrl(url: string): boolean {
    return url.trim() === "*";
  }

  /**
   * Whether a repo URL entry looks like a path pattern (e.g. "data/**")
   * rather than a git URL. Path patterns don't contain protocols, common git
   * hosts, or @ symbols. Mirrors CursorIgnoreService.isPathPatternUrl.
   */
  private isPathPatternUrl(url: string): boolean {
    return (
      !url.includes("://") &&
      !url.includes("github.com") &&
      !url.includes("gitlab.com") &&
      !url.includes("bitbucket.org") &&
      !url.includes("@")
    );
  }

  /**
   * Relative path from the containing workspace root, or the full path when
   * outside every root. Used to evaluate wildcard/path-pattern entries for
   * paths that are not inside a git repo. Picks the longest matching root so
   * nested workspace roots resolve to the most specific one, mirroring
   * CursorIgnoreService.getRelativePathFromWorkspaceRoot.
   */
  private getWorkspaceRelativePath(absolutePath: string): string {
    let bestRoot: string | undefined;
    for (const root of this.rootDirectories) {
      if (
        isPathWithin({ basePath: root, targetPath: absolutePath }) &&
        (bestRoot === undefined || root.length > bestRoot.length)
      ) {
        bestRoot = root;
      }
    }
    if (bestRoot !== undefined) {
      return normalizeToUnixPath(relative(bestRoot, absolutePath));
    }
    return normalizeToUnixPath(absolutePath);
  }

  /**
   * Canonical path of the user's Cursor data directory (~/.cursor).
   * Resolved through realpath once so comparisons against realpath'd input
   * paths hold when the home directory involves symlinks.
   */
  private getCursorDataDir(): Promise<string> {
    this.cursorDataDirPromise ??= (async () => {
      const raw = join(os.homedir(), ".cursor");
      const resolved = await resolveRealPathStrict(raw);
      return resolved ?? raw;
    })();
    return this.cursorDataDirPromise;
  }

  private doesRepoUrlMatch(repoUrl1: string, repoUrl2: string): boolean {
    const rawPattern = repoUrl1
      .trim()
      .toLowerCase()
      .replace(/\.git$/i, "");
    // Check if repoUrl1 is a glob pattern (contains *)
    const isGlobPattern = repoUrl1.includes("*");

    if (isGlobPattern) {
      // Special case: single "*" matches all repos
      if (repoUrl1.trim() === "*") {
        return true;
      }

      // Use glob matching for pattern-based URLs
      const normalizedPattern = toHostPath(repoUrl1).toLowerCase();
      const normalizedUrl = toHostPath(repoUrl2).toLowerCase();
      return this.matchRepoUrlGlob(normalizedPattern, normalizedUrl);
    } else {
      // Use exact match for non-glob URLs
      return (
        toHostPath(repoUrl1).toLowerCase() ===
        toHostPath(repoUrl2).toLowerCase()
      );
    }
  }

  private matchGlob(pattern: string, value: string): boolean {
    const trimmedPattern = pattern.trim();
    if (
      (value === "." || value === "") &&
      (trimmedPattern === "**" || trimmedPattern === "**/*")
    ) {
      return true;
    }
    try {
      const isMatch = picomatch(trimmedPattern);
      return isMatch(value);
    } catch {
      // Fallback to strict equality on invalid patterns
      return trimmedPattern === value;
    }
  }

  private matchRepoUrlGlob(pattern: string, value: string): boolean {
    const trimmedPattern = pattern.trim();
    if (this.matchGlob(trimmedPattern, value)) {
      return true;
    }

    // Admins commonly enter patterns like "*/repo" to mean "any owner/host
    // with this repo name". Normalized repo URLs include host and owner
    // segments, so allow the leading * to span multiple path segments.
    if (trimmedPattern.startsWith("*/")) {
      return this.matchGlob(`**/${trimmedPattern.slice(2)}`, value);
    }

    return false;
  }

  /**
   * Get glob patterns that should be excluded for repo blocking.
   * These patterns are relative to the rootDirectory and can be passed
   * directly to ripgrep for native filtering.
   */
  public async getRepoBlockExcludeGlobs(
    rootDirectory: string
  ): Promise<string[]> {
    // First check if there are any team repos - early exit if not to save IOPs
    const teamReposResponse = await this.teamSettingsService?.getTeamRepos();

    if (!teamReposResponse?.repos?.length) {
      return [];
    }

    // Only do the expensive git repo mapping if we have team repos to check
    const absoluteRoot = await this.resolveLookupRoot(rootDirectory);
    const gitRepoMapping = await this.getGitRepoMapping();

    if (gitRepoMapping.size === 0) {
      return [];
    }

    const excludeGlobs: string[] = [];

    // For each git root that is under or equal to rootDirectory
    for (const [gitRoot, repoUrl] of gitRepoMapping) {
      if (repoUrl === undefined) continue;

      // Check if this git root is relevant to the rootDirectory
      // Either rootDirectory is under gitRoot, or gitRoot is under rootDirectory
      const normalizedGitRoot = this.normalizePathForComparison(gitRoot);
      const normalizedRoot = this.normalizePathForComparison(absoluteRoot);

      let isRelevant = false;
      let relativeGitRoot = "";

      if (normalizedRoot.startsWith(normalizedGitRoot)) {
        // rootDirectory is under gitRoot (common case)
        isRelevant = true;
        relativeGitRoot = ""; // Patterns apply from root
      } else if (normalizedGitRoot.startsWith(normalizedRoot)) {
        // gitRoot is under rootDirectory (submodule case)
        isRelevant = true;
        relativeGitRoot = relative(absoluteRoot, gitRoot);
      }

      if (!isRelevant) continue;

      // Find all repos whose URL matches this git root's URL
      const matchingRepos = teamReposResponse.repos.filter(repo =>
        this.doesRepoUrlMatch(repo.url, repoUrl)
      );

      if (matchingRepos.length === 0) continue;

      // Collect all patterns from matching repos
      for (const repo of matchingRepos) {
        for (const pattern of repo.patterns || []) {
          const trimmedPattern = pattern.pattern.trim();
          if (!trimmedPattern) continue;

          // Construct the glob relative to rootDirectory
          let glob: string;
          if (relativeGitRoot) {
            // Pattern is for a submodule, prefix with submodule path
            glob = join(relativeGitRoot, trimmedPattern).replace(/\\/g, "/");
          } else {
            // Pattern applies from root
            glob = trimmedPattern;
          }

          // Add both the pattern itself and pattern/** to handle both files and directories
          // (ripgrep requires /** to match directory contents, not just the directory name)
          excludeGlobs.push(glob);
          if (!glob.endsWith("/**")) {
            excludeGlobs.push(`${glob}/**`);
          }
        }
      }
    }

    return excludeGlobs;
  }

  /**
   * Normalize a path for cross-platform comparison.
   * Converts backslashes to forward slashes and lowercases on Windows.
   */
  private normalizePathForComparison(path: string): string {
    let normalized = path.replace(/\\/g, "/");
    // Remove leading slash if present on Windows paths (e.g., /c:/Users -> c:/Users)
    if (
      normalized.startsWith("/") &&
      normalized.length > 2 &&
      normalized[2] === ":"
    ) {
      normalized = normalized.substring(1);
    }
    // On Windows, normalize to lowercase for case-insensitive comparison
    if (process.platform === "win32") {
      normalized = normalized.toLowerCase();
    }
    return normalized;
  }

  /**
   * Get the git repo mapping, initializing it lazily if needed.
   * Returns a Map of git root path → upstream URL.
   */
  private getGitRepoMapping(): Promise<Map<string, string | undefined>> {
    if (!this.gitRepoMappingPromise) {
      this.gitRepoMappingPromise = this.initializeGitRepoMapping();
    }
    return this.gitRepoMappingPromise;
  }

  /**
   * Discover all git repositories in root directories (including submodules)
   * and map them to their upstream URLs.
   */
  private async initializeGitRepoMapping(): Promise<
    Map<string, string | undefined>
  > {
    const result = new Map<string, string | undefined>();
    const gitRepoLocations: string[] = [];

    // Directories to skip when searching for git repos
    const DIRS_TO_SKIP = [
      "**/node_modules/**",
      "**/.turbo/**",
      "**/.next/**",
      "**/.cache/**",
      "**/.pnpm/**",
      "**/.yarn/**",
      "**/dist/**",
      "**/build/**",
      "**/out/**",
      "**/target/**",
      "**/.vscode/**",
      "**/.idea/**",
      "**/venv/**",
      "**/__pycache__/**",
      "**/logs/**",
      "**/tmp/**",
      "**/temp/**",
    ];
    const ctx = createContext();

    // Find all .git directories using ripgrep
    for (const rootDir of this.rootDirectories) {
      const resolvedRoot = resolvePath(rootDir);
      // First add the root itself if it's a git repo
      try {
        await access(join(resolvedRoot, ".git"), fs.constants.F_OK);
        if (!gitRepoLocations.includes(resolvedRoot)) {
          gitRepoLocations.push(resolvedRoot);
        }
      } catch {
        // Not a git repo at root level
      }

      // Also check ancestors of the root (in case we're in a subdirectory of a repo)
      let currentPath = dirname(resolvedRoot);
      const fsRoot = parse(currentPath).root;
      while (currentPath !== fsRoot && currentPath !== "") {
        try {
          await access(join(currentPath, ".git"), fs.constants.F_OK);
          if (!gitRepoLocations.includes(currentPath)) {
            gitRepoLocations.push(currentPath);
          }
        } catch {
          // Not a git repo
        }
        const parentPath = dirname(currentPath);
        if (parentPath === currentPath) break;
        currentPath = parentPath;
      }

      // Search for nested git repos (submodules) using ripgrep
      // We look for .git/config files to identify git repos
      // noIgnoreVcs is required to search inside .git directories
      try {
        const ripwalkOptions = {
          root: resolvedRoot,
          includeGlobs: ["**/.git/config"],
          excludeGlobs: DIRS_TO_SKIP,
          noIgnoreVcs: true,
          source: "ignore_scan" as const,
        };
        const ripwalkResult = LocalIgnoreService.getRipwalkCache().walk(
          ctx,
          ripwalkOptions
        );
        for await (const path of ripwalkResult.lines) {
          // path is relative like "submodule/.git/config"
          const fullPath = join(resolvedRoot, path);
          const gitDir = dirname(fullPath); // .../submodule/.git
          const gitRoot = dirname(gitDir); // .../submodule
          if (!gitRepoLocations.includes(gitRoot)) {
            gitRepoLocations.push(gitRoot);
          }
        }
      } catch {
        // Ripwalk failed, continue with what we have
      }
    }

    // For each discovered git repo, get its upstream URL
    await Promise.all(
      gitRepoLocations.map(async repoPath => {
        try {
          const upstreamUrl = await getGitRemoteUrl(
            ctx,
            this.gitExecutor,
            repoPath
          );
          result.set(repoPath, upstreamUrl);
        } catch {
          // Failed to get upstream URL, still add to map with undefined
          result.set(repoPath, undefined);
        }
      })
    );

    return result;
  }
}
