export interface LocalResourceProviderOptions {
  pendingDecisionStore: PendingDecisionProvider;
  fileChangeTracker: FileChangeTrackerInterface;
  gitExecutor: GitExecutor;
  ignoreService: IgnoreService;
  grepProvider: GrepProvider;
  permissionsService: PermissionsService;
  workspacePaths: string[];
  worktreeMainPath?: string;
  diagnosticsProvider: DiagnosticsProvider;
  /** When set, registers `canvasDiagnosticsExecutorResource` for post-edit TS checks on managed canvases. */
  getCanvasDiagnostics?: GetCanvasDiagnosticsFn;
  mcpLease: McpLease;
  mcpStateAccessor?: McpStateAccessor;
  ensureMcpServersLoaded?: (
    ctx: Context,
    serverIdentifiers: readonly string[],
    options?: { wait?: boolean }
  ) => Promise<void>;
  cursorRulesService: CursorRulesService;
  cloudRulesService?: CloudRulesService;
  subagentsService: SubagentsService;
  repositoryProvider: IndexingCodebaseReferenceProvider;
  projectDir: string;
  shellManager?: ShellManager;
  _sandboxPolicyResolver?: (
    resourceId: string,
    args: unknown,
    options?: ExecOptions
  ) => SandboxPolicy;
  _defaultSandboxPolicy?: SandboxPolicy;
  /**
   * Pre-populated sandbox policy merge sources.
   *
   * In agent-cli (local only), both perUser and perRepo are loaded locally.
   * In IDE with Remote SSH, perUser is loaded on the host and passed here,
   * while perRepo is loaded on the remote in local-exec.
   *
   * This enables the IDE to pass perUser from the host machine's
   * ~/.cursor/sandbox.json without local-exec trying to read it from
   * the remote filesystem.
   */
  _defaultSandboxPolicySources?: SandboxPolicyMergeSources;
  mcpFileOutputThresholdBytes?: number;
  backgroundShellFactory?: BackgroundShellFactory;
  backgroundWorkRegistry?: BackgroundWorkRegistry;
  /**
   * Conversation that owns background-shell wakeups from this provider. Defaults
   * to the execution conversation. Set to the root conversation id for subagent
   * providers so subagent-owned shell completions reach the root consumer loop.
   */
  wakeupOwnerConversationId?: string;
  mcpElicitationFactory?: McpElicitationProviderFactory;
  createFileWatcher?: CreateFileWatcherCallback;
  sharedRequestContextExecutor?: RequestContextExecutor;
  terminalExecutor?: TerminalExecutor;
  /** Extra rules prepended to the rules list (e.g. glass root workspace guidance). */
  additionalRules?: CursorRule[];
  getSandboxEnabled?: () => boolean;
  /** Whether the environment supports running in a sandbox. */
  getSandboxSupported?: () => boolean;
  /**
   * Optional callback to get network allowlist info for sandbox prompt generation.
   * When provided, the model is informed about available network access in the sandbox.
   */
  getNetworkAllowlistInfo?: () => Promise<NetworkAllowlistInfo>;
  /** Whether this runtime should select Smart Mode classifier-backed Auto. */
  getSmartModeClassifierAutoModeEnabled?: () => boolean;
  getAdminCommandDenylist?: LocalRequestContextExecutorOptions["getAdminCommandDenylist"];
  /** Development-only one-shot token that forces the next Smart Mode classifier run to block. */
  devForceNextSmartModeClassifierBlockToken?: string;
  /**
   * Optional callback to get MCP file system options.
   * If not provided, mcpFileSystemOptions will be undefined in the request context.
   */
  getMcpFileSystemOptions?: (
    ctx: Context,
    options?: { timeoutMs?: number }
  ) => Promise<McpFileSystemOptions | undefined>;
  /**
   * Returns the mounted agent stores available to the current request.
   * Applied after request-context caches so one request cannot reuse another
   * request's mount inventory.
   */
  getMountedAgentStores?: (
    ctx: Context
  ) => Promise<readonly MountedAgentStore[]>;
  /** Pre-constructed computer-use executor for browser automation */
  computerUseExecutor?: ComputerUseExecutor;
  userTerminalHint?: string;
  enableRecordScreen?: boolean;
  recordScreenArtifactsDir?: string;
  recordScreenDisplay?: string;
  /**
   * Disable polished recording render and use ffmpeg proxy outputs directly.
   * Intended for test/dev paths where renderer deps may be unavailable.
   */
  disableRecordScreenRendering?: boolean;
  /** Optional polished renderer injected by exec-daemon. */
  polishedRecordingRenderer?: PolishedRecordingRenderer;
  /** Resolve the artifacts folder reported for the current request. */
  getArtifactsFolder?: ArtifactsFolderResolver;
  /** Whether secret redaction is enabled in this environment. */
  secretRedactionEnabled?: boolean;
  /** Config provider for reading CLI attribution settings */
  attributionConfigProvider?: AttributionConfigProvider;
  /** Optional callback for admin attribution overrides in CLI contexts. */
  isAttributionDisabledByAdmin?: () => Promise<boolean>;
  /** Optional callback to get agent skills for the request context. */
  getAgentSkills?: (ctx: Context) => Promise<AgentSkill[]>;
  /** Enables bounded streaming text reads for the read executor. */
  useStreamingRead?: () => boolean | Promise<boolean>;
  /**
   * When true, request context uses MCP meta-tool discovery (GetMcpTools) instead of file-system MCP only.
   * Set by the IDE extension (feature gate), agent-cli (feature gate), or exec-daemon for cloud.
   */
  mcpMetaToolEnabled?: boolean;
  /**
   * When true, meta-tool descriptors carry only server metadata plus tool
   * names (no per-tool descriptions or input schemas). Feature-gated
   * (`mcp_meta_tool_slim_descriptors`); GetMcpTools fetches full definitions
   * live at discovery time.
   */
  mcpMetaToolSlimDescriptors?: boolean;
  /** Carry MCP schemas as flat JSON strings (`mcp_input_schema_json`). */
  mcpInputSchemaJson?: boolean;
  /** When true, synthetic `mcp_auth` is listed for every MCP server in meta-tool descriptors. */
  alwaysExposeVirtualMcpAuthTool?: boolean;
  /** Configuration for sudo askpass support. When set, SUDO_ASKPASS env vars are configured for shell execution. */
  askpassConfig?: AskpassConfig;
  /** Optional output buffering options for high-volume shell streams. */
  shellOutputBackpressureOptions?: ShellOutputBackpressureOptions;
  /** Optional per-execution environment values merged into shell commands. */
  shellExtraEnvProvider?: ShellExtraEnvProvider;
  shellCoreWrapper?: (executor: ShellCoreExecutor) => ShellCoreExecutor;
  /** Optional callback for AI code tracking (cursor-blame). Called after successful text writes. */
  onWriteForAiTracking?: (args: OnWriteForAiTrackingArgs) => Promise<void>;
  /** Optional callback for AI code tracking (cursor-blame). Called after successful file deletions. */
  onDeleteForAiTracking?: (args: OnDeleteForAiTrackingArgs) => Promise<void>;
  /**
   * Registers redactedReadExecutorResource in addition to readExecutorResource.
   * Keep disabled outside environments where secret redaction middleware is active.
   */
  registerRedactedReadExecutor?: boolean;
  /** Optional override for read executor registration. */
  overrideReadExecutor?: ReadExecutor;
  /** Optional override for write executor registration. */
  overrideWriteExecutor?: WriteExecutor;
  /** Optional override for shell executor registration. */
  overrideShellExecutor?: ShellExecutor;
  /**
   * Whether write_shell_stdin requests should be enabled.
   * Disable this when shell lifecycles are managed outside local background shells.
   * Defaults to true.
   */
  enableWriteBackgroundShellStdin?: boolean;
  /**
   * Optional reason surfaced when write_shell_stdin is disabled.
   */
  writeBackgroundShellStdinDisabledReason?: string;
  /** Shared conflict journal drainer for the typed executor. */
  agentStoreConflictDrainer?: AgentStoreConflictJournalDrainer;
}

export class LocalResourceProvider extends RegistryResourceAccessor {
  /** Session-scoped MCP permission gate inputs (shared with LocalMcpToolExecutor). */
  getMcpExecutionPolicyDeps(): {
    permissionsService: PermissionsService;
    pendingDecisionProvider: PendingDecisionProvider;
  } {
    return {
      permissionsService: this.permissionsService,
      pendingDecisionProvider: this.pendingDecisionStore,
    };
  }

  private readonly backgroundShellExecutor: LocalBackgroundShellExecutor;
  private readonly computerUseExecutor?: ComputerUseExecutor;
  private readonly pendingDecisionStore: PendingDecisionProvider;
  private readonly fileChangeTracker: FileChangeTrackerInterface;
  private readonly gitExecutor: GitExecutor;
  private readonly ignoreService: IgnoreService;
  private readonly grepProvider: GrepProvider;
  private readonly permissionsService: PermissionsService;
  private readonly workspacePaths: string[];
  private readonly worktreeMainPath?: string;
  private readonly diagnosticsProvider: DiagnosticsProvider;
  private readonly mcpLease: McpLease;
  private readonly mcpStateAccessor?: McpStateAccessor;
  private readonly cursorRulesService: CursorRulesService;
  private readonly cloudRulesService?: CloudRulesService;
  private readonly subagentsService: SubagentsService;
  private readonly repositoryProvider: IndexingCodebaseReferenceProvider;
  private readonly projectDir: string;
  private readonly shellManager?: ShellManager;
  readonly _sandboxPolicyResolver?: (
    resourceId: string,
    args: unknown,
    options?: ExecOptions
  ) => SandboxPolicy;
  readonly _defaultSandboxPolicy: SandboxPolicy;
  readonly _defaultSandboxPolicySources?: SandboxPolicyMergeSources;
  private readonly mcpFileOutputThresholdBytes?: number;
  private readonly backgroundShellFactory?: BackgroundShellFactory;
  private readonly backgroundWorkRegistry?: BackgroundWorkRegistry;
  private readonly wakeupOwnerConversationId?: string;
  private readonly mcpElicitationFactory?: McpElicitationProviderFactory;
  private readonly createFileWatcher?: CreateFileWatcherCallback;
  private readonly sharedRequestContextExecutor?: RequestContextExecutor;
  private readonly terminalExecutor?: TerminalExecutor;
  private readonly userTerminalHint?: string;
  private readonly enableRecordScreen: boolean;
  private readonly recordScreenArtifactsDir?: string;
  private readonly recordScreenDisplay?: string;
  private readonly disableRecordScreenRendering: boolean;
  private readonly attributionConfigProvider?: AttributionConfigProvider;
  private readonly isAttributionDisabledByAdmin?: () => Promise<boolean>;
  private readonly getAgentSkills?: (ctx: Context) => Promise<AgentSkill[]>;
  private readonly getSmartModeClassifierAutoModeEnabled?: () => boolean;
  private readonly getAdminCommandDenylist?: LocalRequestContextExecutorOptions["getAdminCommandDenylist"];
  private readonly devForceNextSmartModeClassifierBlockToken?: string;
  private readonly mcpMetaToolEnabled: boolean;
  private readonly mcpMetaToolSlimDescriptors: boolean;
  private readonly mcpInputSchemaJson: boolean;
  private readonly alwaysExposeVirtualMcpAuthTool: boolean;
  private readonly additionalRules: CursorRule[];
  private readonly askpassConfig?: AskpassConfig;
  private recordScreenExecutor?: LocalRecordScreenExecutor;

  constructor(options: LocalResourceProviderOptions) {
    super();

    this.pendingDecisionStore = options.pendingDecisionStore;
    this.fileChangeTracker = options.fileChangeTracker;
    this.gitExecutor = options.gitExecutor;
    this.ignoreService = options.ignoreService;
    this.grepProvider = options.grepProvider;
    this.permissionsService = options.permissionsService;
    this.workspacePaths = options.workspacePaths;
    this.worktreeMainPath = options.worktreeMainPath;
    this.diagnosticsProvider = options.diagnosticsProvider;
    this.mcpLease = options.mcpLease;
    this.mcpStateAccessor = options.mcpStateAccessor;
    this.cursorRulesService = options.cursorRulesService;
    this.cloudRulesService = options.cloudRulesService;
    this.subagentsService = options.subagentsService;
    this.repositoryProvider = options.repositoryProvider;
    this.projectDir = options.projectDir;
    this.shellManager = options.shellManager;
    this._sandboxPolicyResolver = options._sandboxPolicyResolver;
    this._defaultSandboxPolicy = options._defaultSandboxPolicy ?? {
      type: "insecure_none",
    };

    // Load perRepo sandbox policy from workspace (if exists)
    // This is safe for Remote SSH since it's reading from the workspace directory
    const firstWorkspacePath = options.workspacePaths[0];
    const perRepoPolicy = firstWorkspacePath
      ? loadPerRepoSandboxPolicySync(firstWorkspacePath)
      : undefined;

    // Merge perRepo with any pre-loaded sources (e.g., perUser from IDE host)
    const inputSources = options._defaultSandboxPolicySources;
    if (perRepoPolicy || inputSources) {
      this._defaultSandboxPolicySources = {
        perUser: inputSources?.perUser,
        perRepo: perRepoPolicy ?? inputSources?.perRepo,
        teamAdmin: inputSources?.teamAdmin,
      };
    } else {
      this._defaultSandboxPolicySources = undefined;
    }

    this.mcpFileOutputThresholdBytes = options.mcpFileOutputThresholdBytes;
    this.backgroundShellFactory = options.backgroundShellFactory;
    this.backgroundWorkRegistry = options.backgroundWorkRegistry;
    this.wakeupOwnerConversationId = options.wakeupOwnerConversationId;
    this.mcpElicitationFactory = options.mcpElicitationFactory;
    this.createFileWatcher = options.createFileWatcher;
    this.sharedRequestContextExecutor = options.sharedRequestContextExecutor;
    this.terminalExecutor = options.terminalExecutor;
    this.mcpMetaToolEnabled = options.mcpMetaToolEnabled ?? false;
    this.mcpMetaToolSlimDescriptors =
      options.mcpMetaToolSlimDescriptors ?? false;
    this.mcpInputSchemaJson = options.mcpInputSchemaJson ?? false;
    this.alwaysExposeVirtualMcpAuthTool =
      options.alwaysExposeVirtualMcpAuthTool ?? false;
    this.enableRecordScreen = options.enableRecordScreen ?? false;
    this.recordScreenArtifactsDir = options.recordScreenArtifactsDir;
    this.recordScreenDisplay = options.recordScreenDisplay;
    this.disableRecordScreenRendering =
      options.disableRecordScreenRendering ?? false;
    this.userTerminalHint = options.userTerminalHint;
    this.attributionConfigProvider = options.attributionConfigProvider;
    this.isAttributionDisabledByAdmin = options.isAttributionDisabledByAdmin;
    this.getAgentSkills = options.getAgentSkills;
    this.getSmartModeClassifierAutoModeEnabled =
      options.getSmartModeClassifierAutoModeEnabled;
    this.getAdminCommandDenylist = options.getAdminCommandDenylist;
    this.devForceNextSmartModeClassifierBlockToken =
      options.devForceNextSmartModeClassifierBlockToken;
    this.additionalRules = options.additionalRules ?? [];
    this.askpassConfig = options.askpassConfig;

    const ex =
      this.terminalExecutor ??
      createDefaultTerminalExecutor({
        env: {
          CURSOR_AGENT: "1",
        },
        userTerminalHint: this.userTerminalHint,
      });

    // For multi-root workspaces, compute the common parent directory of all workspace paths.
    // Multi-root indexed paths use the format `./workspaceFolderName/rest/of/path`, which
    // resolves correctly when the base is the common parent of all workspace roots.
    // For single-root, use the workspace path directly.
    let singleWorkspacePath: string | undefined;
    if (this.workspacePaths.length > 1) {
      const parents = this.workspacePaths.map(p => dirname(p));
      const allSameParent = parents.every(p => p === parents[0]);
      singleWorkspacePath = allSameParent ? parents[0] : undefined;
    } else {
      singleWorkspacePath = firstWorkspacePath;
    }

    // clone to avoid shared mutable state
    const baseShellCoreExecutor = new BaseShellCoreExecutor(
      ex,
      firstWorkspacePath ?? homedir(),
      this.projectDir,
      options.shellOutputBackpressureOptions,
      options.shellExtraEnvProvider
    );

    // Build the shell core executor chain:
    // BaseShellCoreExecutor -> [shellCoreWrapper] -> [AskpassShellCoreExecutor] -> [ManagedShellCoreExecutor]
    let shellCoreExecutor: ShellCoreExecutor = baseShellCoreExecutor;

    if (options.shellCoreWrapper) {
      shellCoreExecutor = options.shellCoreWrapper(shellCoreExecutor);
    }

    if (this.askpassConfig) {
      shellCoreExecutor = new AskpassShellCoreExecutor(
        shellCoreExecutor,
        this.askpassConfig
      );
    }

    // Wrap with shell manager for UI updates if configured
    if (this.shellManager) {
      shellCoreExecutor = new ManagedShellCoreExecutor(
        shellCoreExecutor,
        this.shellManager
      );
    }

    const shellExecutor: ShellExecutor =
      options.overrideShellExecutor ??
      new LocalShellExecutor(
        this.permissionsService,
        shellCoreExecutor,
        this.ignoreService,
        this.pendingDecisionStore
      );
    this.register(shellExecutorResource, createCachedExecutor(shellExecutor));
    this.register(
      miniSweAgentBashExecutorResource,
      createCachedExecutor(
        new LocalMiniSweAgentBashExecutor(
          this.permissionsService,
          this.ignoreService,
          singleWorkspacePath ?? firstWorkspacePath ?? this.projectDir
        )
      )
    );
    const writeExecutor: WriteExecutor =
      options.overrideWriteExecutor ??
      new LocalWriteExecutor(
        this.fileChangeTracker,
        this.permissionsService,
        this.pendingDecisionStore,
        {
          workspacePaths: this.workspacePaths,
          workspacePath: singleWorkspacePath,
          worktreeMainPath: this.worktreeMainPath,
          onWriteForAiTracking: options.onWriteForAiTracking,
        }
      );
    this.register(writeExecutorResource, createCachedExecutor(writeExecutor));
    this.register(
      deleteExecutorResource,
      createCachedExecutor(
        new LocalDeleteExecutor(
          this.pendingDecisionStore,
          this.fileChangeTracker,
          this.permissionsService,
          singleWorkspacePath,
          options.onDeleteForAiTracking
        )
      )
    );
    this.register(
      fetchExecutorResource,
      createCachedExecutor(new LocalFetchExecutor())
    );
    // Not cached: a git diff reflects mutable working-tree state, and the
    // review callers pass a constant `execId`, so caching by `execId` could
    // return a stale diff. Matches how exec-daemon/vscode register theirs.
    this.register(gitDiffExecutorResource, new LocalGitDiffExecutor());
    const mcpStateAccessor: McpStateAccessor =
      this.mcpStateAccessor ?? new SimpleMcpStateAccessor(this.mcpLease);
    this.register(
      grepExecutorResource,
      createCachedExecutor(
        new LocalGrepExecutor(
          this.ignoreService,
          this.grepProvider,
          this.workspacePaths,
          {
            mcpStateAccessor,
          }
        )
      )
    );
    const readExecutor: ReadExecutor =
      options.overrideReadExecutor ??
      new LocalReadExecutor(this.permissionsService, singleWorkspacePath, {
        mcpStateAccessor,
        useStreamingRead: options.useStreamingRead,
      });
    const cachedReadExecutor = createCachedExecutor(readExecutor);
    this.register(readExecutorResource, cachedReadExecutor);
    if (options.registerRedactedReadExecutor) {
      this.register(redactedReadExecutorResource, cachedReadExecutor);
    }
    const lsExecutor = new LocalLsExecutor(
      this.permissionsService,
      this.ignoreService,
      singleWorkspacePath
    );
    this.register(lsExecutorResource, createCachedExecutor(lsExecutor));
    this.register(
      piReadExecutorResource,
      createCachedExecutor(
        new LocalPiReadExecutor(this.permissionsService, singleWorkspacePath)
      )
    );
    this.register(
      piBashExecutorResource,
      createCachedExecutor(new LocalPiBashExecutor(shellExecutor))
    );
    this.register(
      piEditExecutorResource,
      createCachedExecutor(
        new LocalPiEditExecutor(
          this.permissionsService,
          writeExecutor,
          singleWorkspacePath
        )
      )
    );
    this.register(
      piWriteExecutorResource,
      createCachedExecutor(
        new LocalPiWriteExecutor(writeExecutor, singleWorkspacePath)
      )
    );
    this.register(
      piGrepExecutorResource,
      createCachedExecutor(
        new LocalPiGrepExecutor(this.permissionsService, singleWorkspacePath)
      )
    );
    this.register(
      piFindExecutorResource,
      createCachedExecutor(
        new LocalPiFindExecutor(this.permissionsService, singleWorkspacePath)
      )
    );
    this.register(
      piLsExecutorResource,
      createCachedExecutor(
        new LocalPiLsExecutor(this.permissionsService, singleWorkspacePath)
      )
    );
    this.register(
      diagnosticsExecutorResource,
      createCachedExecutor(
        new LocalDiagnosticsExecutor(
          singleWorkspacePath,
          this.diagnosticsProvider
        )
      )
    );
    if (options.getCanvasDiagnostics) {
      this.register(
        canvasDiagnosticsExecutorResource,
        createCachedExecutor(
          new LocalCanvasDiagnosticsExecutor(options.getCanvasDiagnostics)
        )
      );
    }
    this.register(
      mcpExecutorResource,
      createCachedExecutor(
        new LocalMcpToolExecutor(
          this.mcpLease,
          this.permissionsService,
          this.pendingDecisionStore,
          this.projectDir,
          this.mcpFileOutputThresholdBytes,
          this.mcpElicitationFactory,
          options.ensureMcpServersLoaded
        )
      )
    );
    this.register(
      listMcpResourcesExecutorResource,
      createCachedExecutor(
        new LocalListMcpResourcesExecutor(
          this.mcpLease,
          options.ensureMcpServersLoaded
        )
      )
    );
    this.register(
      readMcpResourceExecutorResource,
      createCachedExecutor(
        new LocalReadMcpResourceExecutor(
          this.mcpLease,
          singleWorkspacePath || this.projectDir,
          this.permissionsService,
          this.workspacePaths,
          this.pendingDecisionStore,
          options.ensureMcpServersLoaded
        )
      )
    );
    this.register(
      mcpStateExecutorResource,
      createCachedExecutor(
        new LocalMcpStateExecutor(
          mcpStateAccessor,
          options.ensureMcpServersLoaded,
          {
            filterToRequestedServers:
              this.mcpMetaToolEnabled && this.mcpMetaToolSlimDescriptors,
          }
        )
      )
    );
    const requestContextExecutor =
      this.sharedRequestContextExecutor ??
      new LocalRequestContextExecutor(
        this.cursorRulesService,
        this.cloudRulesService,
        this.subagentsService,
        this.repositoryProvider,
        this.grepProvider,
        mcpStateAccessor,
        this.gitExecutor,
        this.workspacePaths,
        {
          projectDir: this.projectDir,
          isWorkingDirHomeDir: isSameDirectoryPathAsHome(
            firstWorkspacePath,
            homedir()
          ),
          createFileWatcher: this.createFileWatcher,
          getSandboxEnabled: options.getSandboxEnabled,
          getSandboxSupported: options.getSandboxSupported,
          getNetworkAllowlistInfo: options.getNetworkAllowlistInfo,
          getSmartModeClassifierAutoModeEnabled:
            this.getSmartModeClassifierAutoModeEnabled,
          getAdminCommandDenylist: this.getAdminCommandDenylist,
          devForceNextSmartModeClassifierBlockToken:
            this.devForceNextSmartModeClassifierBlockToken,
          userTerminalHint: this.userTerminalHint,
          getMcpFileSystemOptions: options.getMcpFileSystemOptions,
          mcpMetaToolEnabled: this.mcpMetaToolEnabled,
          mcpMetaToolSlimDescriptors: this.mcpMetaToolSlimDescriptors,
          mcpInputSchemaJson: this.mcpInputSchemaJson,
          alwaysExposeVirtualMcpAuthTool: this.alwaysExposeVirtualMcpAuthTool,
          getArtifactsFolder: options.getArtifactsFolder,
          secretRedactionEnabled: options.secretRedactionEnabled,
          attributionConfigProvider: this.attributionConfigProvider,
          isAttributionDisabledByAdmin: this.isAttributionDisabledByAdmin,
          getAgentSkills: this.getAgentSkills,
          additionalRules: this.additionalRules,
          getComputerUseSupported: () => this.computerUseExecutor !== undefined,
        }
      );
    const cachedRequestContextExecutor = createCachedExecutor(
      requestContextExecutor
    );
    this.register(requestContextExecutorResource, {
      execute: async (ctx, args, execOptions) => {
        const result = await cachedRequestContextExecutor.execute(
          ctx,
          args,
          execOptions
        );
        if (
          result.result.case !== "success" ||
          result.result.value.requestContext === undefined
        ) {
          return result;
        }
        const nextResult = result.clone();
        if (nextResult.result.case !== "success") {
          return result;
        }
        const requestContext = nextResult.result.value.requestContext;
        if (requestContext === undefined) {
          return nextResult;
        }
        const mcpState = await mcpStateAccessor.getState(ctx);
        const legacyMcp = buildLegacyMcpRequestContextFields(mcpState, {
          internalBrowserProvidersOnly:
            this.mcpMetaToolEnabled && this.mcpMetaToolSlimDescriptors,
          inputSchemaJson: this.mcpInputSchemaJson,
        });
        requestContext.tools = legacyMcp.tools;
        requestContext.mcpInstructions = legacyMcp.mcpInstructions;
        requestContext.mcpMetaToolOptions = this.mcpMetaToolEnabled
          ? buildMcpMetaToolOptions(mcpState, {
              alwaysExposeVirtualMcpAuthTool:
                this.alwaysExposeVirtualMcpAuthTool,
              slimDescriptors: this.mcpMetaToolSlimDescriptors,
              inputSchemaJson: this.mcpInputSchemaJson,
            })
          : undefined;
        requestContext.mcpFileSystemOptions =
          await options.getMcpFileSystemOptions?.(ctx);
        if (requestContext.env !== undefined) {
          requestContext.env.artifactsFolder =
            options.getArtifactsFolder?.(ctx);
        }
        if (
          options.getMountedAgentStores !== undefined &&
          requestContext.env !== undefined
        ) {
          try {
            const stores = await options.getMountedAgentStores(ctx);
            requestContext.env.mountedAgentStores = stores.map(store =>
              store.clone()
            );
          } catch {
            requestContext.env.mountedAgentStores = [];
            logger.warn(
              ctx,
              "Failed to get mounted agent stores; continuing without prompt inventory"
            );
          }
        }
        return nextResult;
      },
    });

    this.backgroundShellExecutor = new LocalBackgroundShellExecutor(
      this.permissionsService,
      shellCoreExecutor,
      this.ignoreService,
      this.projectDir,
      this.backgroundShellFactory,
      this.backgroundWorkRegistry,
      this.wakeupOwnerConversationId
    );

    this.register(
      backgroundShellExecutorResource,
      createCachedExecutor(this.backgroundShellExecutor)
    );

    const shellStreamExecutor = new LocalShellStreamExecutor(
      this.permissionsService,
      shellCoreExecutor,
      this.ignoreService,
      this.backgroundShellExecutor.getManager()
    );
    this.register(
      shellStreamExecutorResource,
      createCachedStreamExecutor(shellStreamExecutor)
    );

    if (options.agentStoreConflictDrainer !== undefined) {
      this.register(
        agentStoreConflictExecutorResource,
        new LocalAgentStoreConflictExecutor(options.agentStoreConflictDrainer)
      );
    }

    // Allowlist precheck — read-only delegate to PermissionsService used by
    // the agent to short-circuit Smart Mode classifier calls when the user's
    // allowlist already covers the command. No caching: the answer depends
    // on per-call args plus permissions state that PermissionsService owns.
    this.register(
      shellAllowlistPrecheckExecutorResource,
      new LocalShellAllowlistPrecheckExecutor(this.permissionsService)
    );
    // Same pattern for MCP: short-circuits the Smart Mode classifier when
    // the user or team Mcp(server:tool) allowlist already covers the call.
    // No caching for the same reason.
    this.register(
      mcpAllowlistPrecheckExecutorResource,
      new LocalMcpAllowlistPrecheckExecutor(this.permissionsService)
    );
    // Same pattern for WebFetch domains: short-circuits the Smart Mode
    // classifier when the user's WebFetch(domain) allowlist covers the URL.
    this.register(
      webFetchAllowlistPrecheckExecutorResource,
      new LocalWebFetchAllowlistPrecheckExecutor(this.permissionsService)
    );

    const forceBackgroundShellExecutor: ForceBackgroundShellExecutor =
      new LocalForceBackgroundShellExecutor(shellStreamExecutor);
    this.register(
      forceBackgroundShellExecutorResource,
      createCachedExecutor(forceBackgroundShellExecutor)
    );

    const shellWriteStdinExecutor: WriteBackgroundShellStdinExecutor =
      options.enableWriteBackgroundShellStdin === false
        ? new LocalShellWriteStdinExecutor(async () => {
            throw new Error(
              options.writeBackgroundShellStdinDisabledReason ??
                "write_shell_stdin is disabled for this session"
            );
          })
        : new LocalShellWriteStdinExecutor((shellId: number, data: string) =>
            this.backgroundShellExecutor.writeStdin(shellId, data)
          );

    this.register(
      writeBackgroundShellInputExecutorResource,
      createCachedExecutor(shellWriteStdinExecutor)
    );

    // Register computer-use executor if provided
    if (options.computerUseExecutor) {
      this.computerUseExecutor = options.computerUseExecutor;
      this.register(
        computerUseExecutorResource,
        createCachedExecutor(this.computerUseExecutor)
      );
    }

    // Register recordScreen executor only if enabled (exec-daemon only)
    if (this.enableRecordScreen) {
      if (!this.recordScreenArtifactsDir || !this.recordScreenDisplay) {
        throw new Error(
          "recordScreenArtifactsDir and recordScreenDisplay are required when enableRecordScreen is true"
        );
      }
      this.recordScreenExecutor = new LocalRecordScreenExecutor({
        artifactsDir: this.recordScreenArtifactsDir,
        display: this.recordScreenDisplay,
        disablePolishedRendering: this.disableRecordScreenRendering,
        polishedRenderer: options.polishedRecordingRenderer,
      });
      this.register(
        recordScreenExecutorResource,
        createCachedExecutor(this.recordScreenExecutor)
      );
    }
  }

  /**
   * Get the LocalRecordScreenExecutor instance (if enabled).
   * Used to wire up the InputEventLogger with the X11Executor.
   */
  getRecordScreenExecutor(): LocalRecordScreenExecutor | undefined {
    return this.recordScreenExecutor;
  }

  /**
   * Dispose all resources including background shell instances
   * Note: If a computerUseExecutor was passed in, the caller is responsible for disposing it
   */
  async dispose(): Promise<void> {
    this.backgroundShellExecutor.dispose();
    if (this.recordScreenExecutor) {
      await this.recordScreenExecutor.dispose();
    }
  }
}
