import type { AuthEvent, AuthState } from './types.js';

export function authTransition(
	state: AuthState,
	event: AuthEvent,
): AuthState | null {
	switch (event.kind) {
		case 'auth_required':
			return { type: 'needsUserAuth', authorizationUrl: event.authorizationUrl };

		case 'tokens_saved':
			switch (state.type) {
				case 'needsUserAuth':
				case 'expired':
					return { type: 'valid' };
				case 'unknown':
				case 'valid':
					return null;
				default: {
					const _exhaustive: never = state;
					return _exhaustive;
				}
			}

		case 'auth_completed':
			switch (state.type) {
				case 'needsUserAuth':
					return { type: 'valid' };
				case 'unknown':
				case 'valid':
				case 'expired':
					return null;
				default: {
					const _exhaustive: never = state;
					return _exhaustive;
				}
			}

		case 'operation_auth_failed':
			switch (state.type) {
				case 'valid':
				case 'unknown':
					return { type: 'expired', error: event.error };
				case 'needsUserAuth':
				case 'expired':
					// Don't override active auth flow or already-expired state
					return null;
				default: {
					const _exhaustive: never = state;
					return _exhaustive;
				}
			}

		case 'operation_succeeded':
			switch (state.type) {
				case 'expired':
				case 'unknown':
					return { type: 'valid' };
				case 'valid':
				case 'needsUserAuth':
					return null;
				default: {
					const _exhaustive: never = state;
					return _exhaustive;
				}
			}

		case 'server_removed':
			return { type: 'unknown' };

		default: {
			const _exhaustive: never = event;
			return _exhaustive;
		}
	}
}
