import { delimiter, dirname, isAbsolute } from "node:path";
import { findActualExecutable } from "@anysphere/utils";

/**
 * Centralized ripgrep binary path management.
 *
 * Host applications (agent-cli, exec-daemon, vscode extension host, etc.)
 * call `configureRipgrepPath()` once at startup after resolving the binary
 * location. All downstream code uses `getRipgrepBinaryPath()` to retrieve it.
 */

let configuredPath: string | undefined;

/**
 * Resolve ripgrep binary path from current directory and PATH.
 * Uses findActualExecutable which checks ./rg (cwd) first, then PATH, and on
 * Windows handles .exe/.bat/.cmd extensions.
 *
 * @returns Absolute path to rg, or undefined if not found.
 */
export function resolveRipgrepFromPath(): string | undefined {
  const resolved = findActualExecutable("rg", []).cmd;
  return resolved !== "rg" ? resolved : undefined;
}

/**
 * Configure the ripgrep binary path. Must be called once at startup by the
 * host application before any code attempts to use ripgrep.
 *
 * @param path Absolute path to the `rg` binary.
 * @throws If called with an empty string.
 */
export function configureRipgrepPath(path: string): void {
  if (!path) {
    throw new Error("configureRipgrepPath: path must not be empty");
  }
  configuredPath = path;
}

function findPathEnvKey(env: NodeJS.ProcessEnv): string | undefined {
  const pathKeys = Object.keys(env).filter(key => key.toLowerCase() === "path");
  if (pathKeys.length === 0) {
    return undefined;
  }
  if (process.platform === "win32") {
    return pathKeys.find(key => key === "Path") ?? pathKeys[0];
  }
  return pathKeys.find(key => key === "PATH") ?? pathKeys[0];
}

function getPathEnvValue(env: NodeJS.ProcessEnv): string {
  const pathKey = findPathEnvKey(env);
  return pathKey !== undefined ? (env[pathKey] ?? "") : "";
}

function setPathEnvValue(
  env: NodeJS.ProcessEnv,
  pathValue: string
): NodeJS.ProcessEnv {
  const pathKey =
    findPathEnvKey(env) ?? (process.platform === "win32" ? "Path" : "PATH");
  const result: NodeJS.ProcessEnv = { ...env };
  for (const key of Object.keys(result)) {
    if (key !== pathKey && key.toLowerCase() === "path") {
      delete result[key];
    }
  }
  result[pathKey] = pathValue;
  return result;
}

function prependExecutableDirToPath(
  env: NodeJS.ProcessEnv,
  executablePath: string
): NodeJS.ProcessEnv {
  const executableDir = dirname(executablePath);
  if (!executableDir || executableDir === ".") {
    return env;
  }

  const currentPathEntries = getPathEnvValue(env)
    .split(delimiter)
    .filter(Boolean);
  const newPathValue = [
    executableDir,
    ...currentPathEntries.filter(entry => entry !== executableDir),
  ].join(delimiter);

  return setPathEnvValue(env, newPathValue);
}

export function withConfiguredRipgrepEnv(
  env: NodeJS.ProcessEnv
): NodeJS.ProcessEnv {
  if (!configuredPath || !isAbsolute(configuredPath)) {
    return env;
  }

  return {
    ...prependExecutableDirToPath(env, configuredPath),
    CURSOR_RIPGREP_PATH: configuredPath,
  };
}

/**
 * Get the configured ripgrep binary path.
 *
 * @returns The absolute path to `rg`.
 * @throws If `configureRipgrepPath()` has not been called yet.
 */
export function getRipgrepBinaryPath(): string {
  if (!configuredPath) {
    throw new Error(
      "Ripgrep path not configured. Call configureRipgrepPath() at startup."
    );
  }
  return configuredPath;
}

/**
 * Check whether ripgrep has been configured. Useful for optional paths
 * (e.g. the sandbox system, where ripgrep is only needed on Linux).
 */
export function isRipgrepConfigured(): boolean {
  return configuredPath !== undefined;
}
