const rulesLogger = createLogger("local-exec:cursor-rules");
export const MAX_RULE_OR_SKILL_DESCRIPTION_LENGTH = 1_536;

/**
 * When enabled, `.cursor/rules` discovery runs ripgrep from the directory that
 * owns the rules dir (instead of the rules dir itself) and passes workspace
 * `.cursorignore` files via `--cursor-ignore`, so negation patterns like
 * `!.cursor/rules/external/**` can re-include gitignored rules (DESK-9199).
 *
 * Off by default; the client sets it from the
 * `rules_discovery_respect_cursorignore` Statsig gate at activation.
 */
let rulesDiscoveryRespectsCursorIgnore = false;

export function setRulesDiscoveryRespectsCursorIgnore(enabled: boolean): void {
  rulesDiscoveryRespectsCursorIgnore = enabled;
}

interface ParsedRule {
  filename: string;
  path: string;
  frontmatter: Record<string, unknown>;
  body: string;
  /**
   * Frontmatter block parsed from the `.mdc` file, re-emitted with its `---`
   * fences. Undefined for sources with no real frontmatter (e.g. synthesized
   * AGENTS.md/.cursorrules rules).
   */
  rawFrontmatter?: string;
  /** Normalized git remote origin (e.g., "github.com/owner/repo") if available */
  gitRemoteOrigin?: string;
}

// static set of filenames for safe logging
type RuleMarkdownFilename = "CLAUDE.md" | "CLAUDE.local.md" | "AGENTS.md";

// ============================================================================
// Shared utilities for SKILL.md file discovery and parsing
// ============================================================================

/**
 * Recursively find all SKILL.md files in a directory.
 * Includes safeguards against:
 * - Deep recursion (max depth limit)
 * - Symlink cycles (tracks visited real paths)
 * - Problematic directories (skips node_modules, .git, etc.)
 */
async function findSkillMdFilesRecursive(dir: string): Promise<string[]> {
  return await findFilesRecursive({
    rootDir: dir,
    includeFile: filename => filename === "SKILL.md",
  });
}

export function extractEnvironments(parsed: GrayMatterFile<string>): string[] {
  return (
    parseStringListFrontmatter(
      parsed.data?.environments ?? parsed.data?.metadata?.environments
    ) ?? []
  );
}

export function extractDisabledEnvironments(
  parsed: GrayMatterFile<string>
): string[] {
  return (
    parseStringListFrontmatter(
      parsed.data?.["disabled-environments"] ??
        parsed.data?.metadata?.disabledEnvironments
    ) ?? []
  );
}

export function extractScopedTo(parsed: GrayMatterFile<string>): string[] {
  return (
    parseStringListFrontmatter(
      parsed.data?.metadata?.scopedTo ?? parsed.data?.["metadata.scopedTo"]
    ) ?? []
  );
}

function parseStringListFrontmatter(value: unknown): string[] | undefined {
  if (Array.isArray(value)) {
    const normalized = value.filter(
      (entry): entry is string => typeof entry === "string" && entry.length > 0
    );
    return normalized.length === 0 ? undefined : normalized;
  }

  if (typeof value === "string") {
    const normalized = value
      .split(",")
      .map(entry => entry.trim())
      .filter(entry => entry.length > 0);
    return normalized.length === 0 ? undefined : normalized;
  }

  return undefined;
}

function extractSurfaces(parsed: GrayMatterFile<string>): string[] {
  const surfaces = parsed.data?.metadata?.surfaces;
  if (Array.isArray(surfaces)) {
    return surfaces;
  }
  if (typeof surfaces === "string") {
    return surfaces
      .split(",")
      .map(s => s.trim())
      .filter(Boolean);
  }
  return [];
}

/**
 * Returns true if the skill should be excluded from this surface.
 * Skills with no surfaces restriction are included everywhere.
 */
function isExcludedBySurface(
  parsed: GrayMatterFile<string>,
  surface: string
): boolean {
  const surfaces = extractSurfaces(parsed);
  return surfaces.length > 0 && !surfaces.includes(surface);
}

function truncateRuleOrSkillDescription(description: string): string {
  return description.slice(0, MAX_RULE_OR_SKILL_DESCRIPTION_LENGTH);
}

/**
 * Result of reading + parsing a single SKILL.md file.
 * Shared between CursorRule and AgentSkill construction to avoid
 * reading the file and parsing frontmatter twice.
 */
export interface ParsedSkillFile {
  skillFilePath: string;
  content: string;
  parsed: GrayMatterFile<string>;
}

function buildSkillFrontmatter(parsed: GrayMatterFile<string>): string {
  return grayMatterFrontmatter(parsed);
}

async function readAndParseSkillFile(
  skillFilePath: string
): Promise<ParsedSkillFile> {
  const content = await readText(skillFilePath);
  const parsed = grayMatter(content);
  return { skillFilePath, content, parsed };
}

export function isAlwaysApplySkillParsed(
  parsed: GrayMatterFile<string>
): boolean {
  return parsed.data?.alwaysApply === true;
}

export function buildCursorRuleFromParsed({
  skillFilePath,
  content,
  parsed,
}: ParsedSkillFile): CursorRule {
  const frontmatter = buildSkillFrontmatter(parsed);
  if (isAlwaysApplySkillParsed(parsed)) {
    return new CursorRule({
      fullPath: skillFilePath,
      content,
      frontmatter,
      type: new CursorRuleType({
        type: {
          case: "global",
          value: new CursorRuleTypeGlobal(),
        },
      }),
      environments: extractEnvironments(parsed),
      disabledEnvironments: extractDisabledEnvironments(parsed),
      scopedTo: extractScopedTo(parsed),
    });
  }

  const description =
    typeof parsed.data?.description === "string"
      ? truncateRuleOrSkillDescription(parsed.data.description)
      : undefined;

  if (!description) {
    return new CursorRule({
      fullPath: skillFilePath,
      parseError: "Description is required",
      frontmatter,
      scopedTo: extractScopedTo(parsed),
      type: new CursorRuleType({
        type: {
          case: "agentFetched",
          value: new CursorRuleTypeAgentFetched(),
        },
      }),
    });
  }

  return new CursorRule({
    fullPath: skillFilePath,
    content,
    frontmatter,
    type: new CursorRuleType({
      type: {
        case: "agentFetched",
        value: new CursorRuleTypeAgentFetched({
          description,
        }),
      },
    }),
    environments: extractEnvironments(parsed),
    disabledEnvironments: extractDisabledEnvironments(parsed),
    scopedTo: extractScopedTo(parsed),
  });
}

export function buildAgentSkillFromParsed({
  skillFilePath,
  content,
  parsed,
}: ParsedSkillFile): AgentSkill {
  const description =
    typeof parsed.data?.description === "string"
      ? truncateRuleOrSkillDescription(parsed.data.description)
      : "";
  const globs = parseGlobs(parsed.data?.paths ?? parsed.data?.globs);

  return new AgentSkill({
    fullPath: skillFilePath,
    content,
    description,
    globs: globs ?? [],
    parseError: description ? undefined : "Description is required",
    environments: extractEnvironments(parsed),
    disabledEnvironments: extractDisabledEnvironments(parsed),
    scopedTo: extractScopedTo(parsed),
    disableModelInvocation: parsed.data?.["disable-model-invocation"] === true,
  });
}

function buildErrorCursorRule({
  skillFilePath,
  errorMessage,
}: {
  skillFilePath: string;
  errorMessage: string;
}): CursorRule {
  return new CursorRule({
    fullPath: skillFilePath,
    parseError: errorMessage,
    type: new CursorRuleType({
      type: {
        case: "agentFetched",
        value: new CursorRuleTypeAgentFetched(),
      },
    }),
  });
}

function buildErrorAgentSkill({
  skillFilePath,
  errorMessage,
}: {
  skillFilePath: string;
  errorMessage: string;
}): AgentSkill {
  return new AgentSkill({
    fullPath: skillFilePath,
    parseError: errorMessage,
  });
}

function addSkillError({
  rules,
  agentSkills,
  skillFilePath,
  errorMessage,
}: {
  rules: CursorRule[];
  agentSkills: AgentSkill[];
  skillFilePath: string;
  errorMessage: string;
}): void {
  rules.push(
    buildErrorCursorRule({
      skillFilePath,
      errorMessage: `Failed to read skill file: ${errorMessage}`,
    })
  );
  agentSkills.push(
    buildErrorAgentSkill({
      skillFilePath,
      errorMessage: `Failed to read skill file: ${errorMessage}`,
    })
  );
}

/**
 * Optional file watcher interface for cache invalidation.
 * Implementations can use VSCode's file events, @parcel/watcher, or any other mechanism.
 */
export interface CursorRulesFileWatcher {
  /**
   * Subscribe to file change events for specific patterns in a workspace path.
   * @param workspacePath Workspace path to watch
   * @param patterns Glob patterns to watch (relative to the workspace path)
   * @param callback Called when files matching the patterns change
   * @returns Unsubscribe function
   */
  subscribe(
    workspacePath: string,
    patterns: string[],
    callback: (path: string) => void
  ): () => void;
}

export interface CursorRulesService {
  getAllCursorRules(ctx: Context): Promise<CursorRule[]>;
  reload(ctx: Context): void;
  dispose(): void;
  /**
   * Set a callback to be invoked when rules are reloaded.
   * @param callback Called after rules are reloaded
   * @returns A dispose function that removes the listener
   */
  onDidChangeRules(callback: () => void): () => void;
}

/**
 * Deduplication key for CursorRules. Used so that the same logical rule in .cursor vs .claude
 * vs .codex vs .agents is deduped (first wins), while rules at different paths are kept distinct.
 *
 * - Paths under `/.cursor/`, `/.claude/`, `/.codex/`, or `/.agents/`: key = `(config root)::(path under config)`.
 *   Config root = directory containing .cursor or .claude or .codex or .agents. Path under = segment after the config dir.
 *   Example: `/workspace/.cursor/rules/foo.mdc` and `/workspace/.claude/rules/foo.mdc` → same key
 *   `workspace::rules/foo.mdc` (dedupe). `/workspace/sub/.cursor/rules/foo.mdc` → `workspace/sub::rules/foo.mdc`
 *   (distinct).
 * - Paths outside .cursor/.claude/.codex/.agents (e.g. AGENTS.md, CLAUDE.md in hierarchy): key = full path.
 *   Example: `/workspace/AGENTS.md` vs `/workspace/sub/AGENTS.md` remain distinct (no collision).
 */
export function dedupeKey(fullPath: string): string {
  const n = fullPath.replace(/\\/g, "/");
  const lower = n.toLowerCase();
  const cursorIdx = lower.indexOf("/.cursor/");
  const claudeIdx = lower.indexOf("/.claude/");
  const codexIdx = lower.indexOf("/.codex/");
  const agentsIdx = lower.indexOf("/.agents/");

  if (cursorIdx !== -1) {
    const configRoot = n.slice(0, cursorIdx);
    const under = n.slice(cursorIdx + "/.cursor/".length);
    return `${configRoot}::${under}`;
  }
  if (claudeIdx !== -1) {
    const configRoot = n.slice(0, claudeIdx);
    const under = n.slice(claudeIdx + "/.claude/".length);
    return `${configRoot}::${under}`;
  }
  if (codexIdx !== -1) {
    const configRoot = n.slice(0, codexIdx);
    const under = n.slice(codexIdx + "/.codex/".length);
    return `${configRoot}::${under}`;
  }
  if (agentsIdx !== -1) {
    const configRoot = n.slice(0, agentsIdx);
    const under = n.slice(agentsIdx + "/.agents/".length);
    return `${configRoot}::${under}`;
  }
  return fullPath;
}

export type ParsedCursorRulesMdc = {
  frontmatter: Record<string, unknown>;
  /** Raw frontmatter block including the `---` fences, for downstream parsing. */
  rawFrontmatter: string;
  body: string;
};

function parseCursorRulesScalarValue(rawValue: string): string | boolean {
  const value = rawValue.trim();
  if (value === "true") return true;
  if (value === "false") return false;
  if (
    (value.startsWith('"') && value.endsWith('"')) ||
    (value.startsWith("'") && value.endsWith("'"))
  ) {
    return value.slice(1, -1);
  }
  return value;
}

/**
 * Parse .mdc frontmatter using the same line-by-line parser as
 * {@link LocalCursorRulesService}. Avoids gray-matter/js-yaml because unquoted
 * glob patterns like `globs: *.ts` break in YAML (the `*` is interpreted as
 * alias syntax).
 *
 * The agent's `scoped-rule-filtering.ts` (packages/agent) re-derives
 * `metadata.scopedTo` from raw frontmatter with a matching line-by-line parser;
 * keep `scopedTo` semantics in sync when changing this one.
 */
export function parseCursorRulesMdcContent(
  content: string
): ParsedCursorRulesMdc | null {
  // Trim leading whitespace (BOM, newlines, spaces) before parsing.
  const trimmedContent = content.trimStart();
  if (!trimmedContent.startsWith("---")) {
    return null;
  }

  const parts = trimmedContent.split("---").filter(Boolean);
  if (parts.length < 2) return null;
  const frontmatterText = parts[0].trim();
  const body = parts.slice(1).join("---").trim();

  const frontmatter: Record<string, unknown> = {};
  let currentParent: string | null = null;
  let parsingArrayKey: string | null = null;

  for (const rawLine of frontmatterText.split("\n")) {
    const line = rawLine.replace(/\r$/, "");

    const arrayItemMatch = line.match(/^\s+-\s+(.*)$/);
    if (arrayItemMatch && parsingArrayKey) {
      let item = arrayItemMatch[1].trim();
      if (
        (item.startsWith('"') && item.endsWith('"')) ||
        (item.startsWith("'") && item.endsWith("'"))
      ) {
        item = item.slice(1, -1);
      }
      const arr = frontmatter[parsingArrayKey];
      if (Array.isArray(arr)) {
        arr.push(item);
      }
      continue;
    }

    const isIndented = line.startsWith("  ") || line.startsWith("\t");

    if (currentParent && isIndented) {
      const trimmed = line.trim();
      const colonIndex = trimmed.indexOf(":");
      if (colonIndex === -1) continue;
      const childKey = trimmed.slice(0, colonIndex).trim();
      const value = trimmed.slice(colonIndex + 1).trim();
      const parsedValue = parseCursorRulesScalarValue(value);
      const flatKey = `${currentParent}.${childKey}`;

      if (value === "") {
        frontmatter[flatKey] = [];
        parsingArrayKey = flatKey;
      } else if (
        flatKey === "metadata.environments" ||
        flatKey === "metadata.disabledEnvironments" ||
        flatKey === "metadata.scopedTo"
      ) {
        frontmatter[flatKey] = String(parsedValue)
          .split(",")
          .map(s => s.trim())
          .filter(Boolean);
        parsingArrayKey = null;
      } else {
        frontmatter[flatKey] = parsedValue;
        parsingArrayKey = null;
      }
      continue;
    }

    currentParent = null;
    parsingArrayKey = null;

    const i = line.indexOf(":");
    if (i === -1) continue;

    const key = line.slice(0, i).trim();
    const value = line.slice(i + 1).trim();

    if (value === "" && key === "metadata") {
      currentParent = key;
      continue;
    }

    if (key === "globs" && value === "") {
      frontmatter.globs = [];
      parsingArrayKey = "globs";
      continue;
    }

    const parsedValue = parseCursorRulesScalarValue(value);
    if (
      key === "metadata.environments" ||
      key === "metadata.disabledEnvironments" ||
      key === "metadata.scopedTo"
    ) {
      frontmatter[key] = String(parsedValue)
        .split(",")
        .map(s => s.trim())
        .filter(Boolean);
      continue;
    }

    frontmatter[key] = parsedValue;
  }

  const rawFrontmatter = `---\n${frontmatterText}\n---`;

  return { frontmatter, rawFrontmatter, body };
}

/** Build a {@link CursorRule} from parsed .mdc content (same logic as `LocalCursorRulesService`). */
export function cursorRuleFromParsedMdc(rule: {
  path: string;
  body: string;
  frontmatter: Record<string, unknown>;
  /** Raw frontmatter block (with `---` fences); empty for synthesized sources. */
  rawFrontmatter?: string;
}): CursorRule {
  let type: CursorRuleType["type"];
  if (rule.frontmatter.alwaysApply === true) {
    type = { case: "global", value: new CursorRuleTypeGlobal() };
  } else {
    const globs = parseGlobs(rule.frontmatter.globs);
    if (globs && globs.length > 0) {
      type = {
        case: "fileGlobbed",
        value: new CursorRuleTypeFileGlobs({ globs }),
      };
    } else if (
      typeof rule.frontmatter.description === "string" &&
      rule.frontmatter.description.trim().length > 0
    ) {
      type = {
        case: "agentFetched",
        value: new CursorRuleTypeAgentFetched({
          description: truncateRuleOrSkillDescription(
            rule.frontmatter.description
          ),
        }),
      };
    } else {
      type = {
        case: "manuallyAttached",
        value: new CursorRuleTypeManuallyAttached(),
      };
    }
  }

  const envValue = rule.frontmatter["metadata.environments"];
  const environments: string[] = Array.isArray(envValue) ? envValue : [];

  const disabledEnvValue = rule.frontmatter["metadata.disabledEnvironments"];
  const disabledEnvironments: string[] = Array.isArray(disabledEnvValue)
    ? disabledEnvValue
    : [];

  const scopedToValue = rule.frontmatter["metadata.scopedTo"];
  const scopedTo: string[] = Array.isArray(scopedToValue) ? scopedToValue : [];

  return new CursorRule({
    fullPath: rule.path,
    content: rule.body,
    type: new CursorRuleType({ type }),
    environments,
    disabledEnvironments,
    scopedTo,
    frontmatter: rule.rawFrontmatter ?? "",
  });
}

export class MergedCursorRulesService implements CursorRulesService {
  private static readonly CHANGE_COALESCE_MS = 1_000;

  private readonly onChangeCallbacks = new Set<() => void>();
  private disposeChangeListeners: Array<() => void> | undefined;
  private changeTimer: ReturnType<typeof setTimeout> | undefined;

  constructor(private readonly cursorRulesServices: CursorRulesService[]) {}

  async getAllCursorRules(ctx: Context): Promise<CursorRule[]> {
    using span = createSpan(
      ctx.withName("MergedCursorRulesService.getAllCursorRules")
    );
    // Call getAllCursorRules on all services in parallel
    const allRulesPromises = this.cursorRulesServices.map(service =>
      service.getAllCursorRules(span.ctx).catch(err => {
        debuglog("Failed to load cursor rules from service:", err);
        return [];
      })
    );

    const allRulesArrays = await Promise.all(allRulesPromises);

    // Flatten all rules into a single array
    const allRules = allRulesArrays.flat();

    // Dedupe by key - first occurrence wins (Cursor sources are processed first).
    // dedupeKey() uses (config root)::(path under config) for .cursor/.claude, so the same
    // skill/rule in both directories collides and Cursor wins. AGENTS.md/CLAUDE.md/.mdc
    // outside config dirs, or at different directory levels, use full path and never collide.
    const seenKeys = new Set<string>();
    const dedupedRules: CursorRule[] = [];

    for (const rule of allRules) {
      const key = dedupeKey(rule.fullPath);
      if (!seenKeys.has(key)) {
        seenKeys.add(key);
        dedupedRules.push(rule);
      }
    }

    return dedupedRules;
  }

  reload(ctx: Context): void {
    for (const service of this.cursorRulesServices) {
      service.reload(ctx);
    }
  }

  private scheduleDidChangeRules(): void {
    if (this.changeTimer !== undefined) {
      return;
    }

    this.changeTimer = setTimeout(() => {
      this.changeTimer = undefined;
      for (const callback of Array.from(this.onChangeCallbacks)) {
        callback();
      }
    }, MergedCursorRulesService.CHANGE_COALESCE_MS);
  }

  private ensureChangeListenersRegistered(): void {
    if (this.disposeChangeListeners !== undefined) {
      return;
    }

    this.disposeChangeListeners = this.cursorRulesServices.map(service =>
      service.onDidChangeRules(() => this.scheduleDidChangeRules())
    );
  }

  private disposeChangeListenersIfUnused(): void {
    if (
      this.onChangeCallbacks.size > 0 ||
      this.disposeChangeListeners === undefined
    ) {
      return;
    }

    for (const dispose of this.disposeChangeListeners) {
      dispose();
    }
    this.disposeChangeListeners = undefined;
    if (this.changeTimer !== undefined) {
      clearTimeout(this.changeTimer);
      this.changeTimer = undefined;
    }
  }

  onDidChangeRules(callback: () => void): () => void {
    this.onChangeCallbacks.add(callback);
    this.ensureChangeListenersRegistered();
    return () => {
      this.onChangeCallbacks.delete(callback);
      this.disposeChangeListenersIfUnused();
    };
  }

  dispose(): void {
    if (this.changeTimer !== undefined) {
      clearTimeout(this.changeTimer);
      this.changeTimer = undefined;
    }
    this.onChangeCallbacks.clear();
    if (this.disposeChangeListeners !== undefined) {
      for (const dispose of this.disposeChangeListeners) {
        dispose();
      }
      this.disposeChangeListeners = undefined;
    }
    for (const service of this.cursorRulesServices) {
      if (service.dispose) {
        service.dispose();
      }
    }
  }
}

export class LocalCursorRulesService implements CursorRulesService {
  protected static ripwalkCache: RipwalkTtlCache | undefined;
  private _rules: Promise<CursorRule[]>;
  private loadTraceId: string | undefined = undefined;
  private unsubscribeWatcher?: () => void;
  private onChangeCallbacks: Set<() => void> = new Set();
  private readonly ignoreService: IgnoreService;

  private readonly nestedExtensibilityService: NestedExtensibilityService;

  constructor(
    ctx: Context,
    private readonly gitExecutor: GitExecutor,
    private readonly rootDirectory: string,
    private readonly loadNestedRules: boolean,
    private readonly getThirdPartyExtensibilityEnabled: () => boolean,
    fileWatcher: CursorRulesFileWatcher | undefined,
    ignoreService?: IgnoreService,
    initialNestedExtensibilityResult?: Promise<NestedExtensibilityResult>
  ) {
    this.nestedExtensibilityService = new NestedExtensibilityService(
      rootDirectory,
      gitExecutor,
      homedir(),
      getThirdPartyExtensibilityEnabled
    );
    this.ignoreService =
      ignoreService ??
      new LazyIgnoreService(gitExecutor, undefined, [this.rootDirectory]);
    const loadStartMs = performance.now();
    this._rules = this.load(ctx, initialNestedExtensibilityResult)
      .then(rules => {
        try {
          rulesLogger.info(ctx, "LocalCursorRulesService load completed", {
            durationMs: Math.round(performance.now() - loadStartMs),
            ruleCount: rules.length,
          });
        } catch {}
        return rules;
      })
      .catch(err => {
        debuglog("Failed to load cursor rules:", err);
        return [];
      });

    // If file watcher provided, subscribe to reload on file changes
    // NOTE: we don't need to watch for rules changes in subdirectories because we don't provide such rules in the
    // system prompt -- we tell the agent to load them as needed.
    // But also note that we won't be catching new rules files in subdirectories, so the agent might not see them.
    // TODO: add efficient file watching for rules in subdirectories.
    if (fileWatcher) {
      const patterns = [
        ".cursor/rules/**/*.mdc",
        "AGENTS.md",
        "CLAUDE.md",
        "CLAUDE.local.md",
        ".cursorrules",
        ".cursorignore",
      ];
      this.unsubscribeWatcher = fileWatcher.subscribe(
        this.rootDirectory,
        patterns,
        (path: string) => {
          const reloadCtx = createContext();
          using span = createSpan(
            reloadCtx.withName("LocalCursorRulesService.fileWatcher.subscribe")
          );
          if (basename(path) === ".cursorignore") {
            // Ignore-file edits change which rules are visible; recompute the
            // full set and drop cached walks that may predate the edit.
            LocalCursorRulesService.getRipwalkCache().clear();
            this.reload(span.ctx);
            return;
          }
          this.reloadAtPath(span.ctx, path);
        }
      );
    }
  }

  /**
   * Reload rules (e.g., when settings change)
   */
  reload(ctx: Context): void {
    // IMPORTANT: Do not clear the ripwalkCache here because reloads can happen
    // frequently on startup which will end up spawning many processes and slow
    // TTFT down.
    this._rules = this.load(ctx).catch(err => {
      debuglog("Failed to load cursor rules:", err);
      return [];
    });
    // Notify all callbacks that rules have changed
    for (const callback of this.onChangeCallbacks) {
      callback();
    }
  }

  protected static getRipwalkCache(): RipwalkTtlCache {
    LocalCursorRulesService.ripwalkCache ??= new RipwalkTtlCache();
    return LocalCursorRulesService.ripwalkCache;
  }

  private reloadAtPath(ctx: Context, path: string): void {
    using span = createSpan(
      ctx.withName("LocalCursorRulesService.reloadAtPath")
    );
    const previousRules = this._rules;
    this._rules = (async () => {
      const previousRulesAtOtherPaths = (await previousRules).filter(
        r => r.fullPath !== path
      );
      // Discovery excludes cursorignored `.mdc` rules when the flag is on;
      // don't let the per-file fast path re-inject them. Negated (re-included)
      // paths pass: isCursorIgnored is false for negation matches.
      if (
        rulesDiscoveryRespectsCursorIgnore &&
        path.endsWith(".mdc") &&
        (await this.isCursorIgnored(path))
      ) {
        return previousRulesAtOtherPaths;
      }
      const rulesAtPath = (await this.readRulesAtPath(span.ctx, path)).map(r =>
        this.toCursorRule(r)
      );
      return [...previousRulesAtOtherPaths, ...rulesAtPath];
    })().catch(err => {
      debuglog("Failed to load cursor rules at path:", err);
      return [];
    });
    // Notify all callbacks that rules have changed
    for (const callback of this.onChangeCallbacks) {
      callback();
    }
  }

  private isRuleMarkdownFile(
    filename: string
  ): filename is RuleMarkdownFilename {
    return (
      filename === "CLAUDE.md" ||
      filename === "CLAUDE.local.md" ||
      filename === "AGENTS.md"
    );
  }

  private async readRulesAtPath(
    ctx: Context,
    path: string
  ): Promise<ParsedRule[]> {
    using span = createSpan(
      ctx.withName("LocalCursorRulesService.readRulesAtPath")
    );
    const filename = basename(path);
    if (filename === ".cursorrules") {
      // .cursorrules is loaded from workspace root (git root)
      const cwd = resolve(this.rootDirectory);
      const gitRoot = await findGitRoot(span.ctx, this.gitExecutor, cwd);
      const workspaceRoot = gitRoot || cwd;
      const cursorRulesRule = await this.loadCursorRulesRule(
        span.ctx,
        workspaceRoot
      );
      return cursorRulesRule ? [cursorRulesRule] : [];
    } else if (filename.endsWith(".mdc")) {
      try {
        const content = await readText(path);
        const parsed = parseCursorRulesMdcContent(content);
        if (parsed) {
          return [
            {
              filename: basename(path, ".mdc"),
              path: path,
              frontmatter: parsed.frontmatter,
              rawFrontmatter: parsed.rawFrontmatter,
              body: parsed.body,
            },
          ];
        }
      } catch {}
    } else if (this.isRuleMarkdownFile(filename)) {
      try {
        return await this.loadRulesFromMarkdownFile(
          span.ctx,
          dirname(path),
          filename
        );
      } catch {}
    }
    return [];
  }

  onDidChangeRules(callback: () => void): () => void {
    this.onChangeCallbacks.add(callback);
    return () => {
      this.onChangeCallbacks.delete(callback);
    };
  }

  dispose(): void {
    if (this.unsubscribeWatcher) {
      this.unsubscribeWatcher();
      this.unsubscribeWatcher = undefined;
    }
  }

  private async load(
    ctx: Context,
    initialNestedExtensibilityResult?: Promise<NestedExtensibilityResult>
  ): Promise<CursorRule[]> {
    using span = createSpan(ctx.withName("LocalCursorRulesService.load"));
    this.loadTraceId = span.span.spanContext().traceId;

    const cwd = resolve(this.rootDirectory);

    const gitRoot = await findGitRoot(span.ctx, this.gitExecutor, cwd);
    const workspaceRoot = gitRoot || cwd;

    const cursorRulesRule = this.loadCursorRulesRule(
      span.ctx,
      workspaceRoot
    ).then(r => (r ? [r] : []));

    const hierarchical = this.loadRulesFromDirAndAncestors(span.ctx, cwd);

    let fromSubdirectories: Promise<ParsedRule[]> | ParsedRule[];
    let markdownFilesFromSubdirectories: Promise<ParsedRule[]> | ParsedRule[];

    if (this.loadNestedRules) {
      const discovered =
        initialNestedExtensibilityResult ??
        this.nestedExtensibilityService.discover(span.ctx);
      fromSubdirectories = discovered.then(d =>
        this.parseNestedRuleFiles(span.ctx, d.rules)
      );
      markdownFilesFromSubdirectories = discovered.then(d =>
        this.parseNestedMarkdownFiles(span.ctx, d.markdown)
      );
    } else {
      fromSubdirectories = [];
      markdownFilesFromSubdirectories = [];
    }

    const allRules = (
      await Promise.all([
        cursorRulesRule,
        hierarchical,
        fromSubdirectories,
        markdownFilesFromSubdirectories,
      ])
    ).flat();

    const map = new Map<string, ParsedRule>();
    for (const r of allRules) {
      map.set(r.path, r);
    }
    return [...map.values()].map(pr => this.toCursorRule(pr));
  }

  async loadCursorRulesRule(
    ctx: Context,
    workspaceRoot: string
  ): Promise<ParsedRule | null> {
    using _span = createSpan(
      ctx.withName("LocalCursorRulesService.loadCursorrules")
    );
    try {
      const cursorRulesPath = join(workspaceRoot, ".cursorrules");
      const st = await stat(cursorRulesPath);
      if (st.isFile()) {
        const content = await readText(cursorRulesPath);
        return {
          filename: ".cursorrules",
          path: cursorRulesPath,
          frontmatter: { alwaysApply: true },
          body: content,
        };
      }
    } catch {}
    return null;
  }

  async getAllCursorRules(ctx: Context): Promise<CursorRule[]> {
    using span = createSpan(
      ctx.withName("LocalCursorRulesService.getAllCursorRules")
    );
    span.span.setAttribute("cacheTraceId", this.loadTraceId ?? "undefined");
    return await this._rules;
  }

  private toCursorRule(rule: ParsedRule): CursorRule {
    return cursorRuleFromParsedMdc({
      path: rule.path,
      body: rule.body,
      frontmatter: rule.frontmatter,
      rawFrontmatter: rule.rawFrontmatter,
    });
  }

  /**
   * Load rules from .cursor/rules directories and CLAUDE.md/AGENTS.md files,
   * starting at `startPath` and walking up through every ancestor directory.
   */
  private async loadRulesFromDirAndAncestors(
    ctx: Context,
    startPath: string
  ): Promise<ParsedRule[]> {
    using span = createSpan(
      ctx.withName("LocalCursorRulesService.loadRulesFromDirAndAncestors")
    );
    const rulePromises: Promise<ParsedRule[]>[] = [];
    let currentPath = startPath;
    const thirdPartyExtensibilityEnabled =
      this.getThirdPartyExtensibilityEnabled();

    while (true) {
      // Check for .cursor/rules directory
      const rulesDir = join(currentPath, ".cursor", "rules");
      // Capture per iteration: the async closure below resumes after this
      // loop has already walked (and finished at the filesystem root), so
      // reading `currentPath` there would see the final value, not this one.
      const baseDir = currentPath;
      rulePromises.push(
        (async () => {
          if (await this.dirIsDirectory(span.ctx, rulesDir)) {
            return this.loadRulesFromDirectory(span.ctx, baseDir);
          }
          return [];
        })()
      );

      // Optionally check for CLAUDE.md and CLAUDE.local.md if enabled
      const files: RuleMarkdownFilename[] = [];
      if (thirdPartyExtensibilityEnabled) {
        files.push("CLAUDE.md", "CLAUDE.local.md");
      }

      // Check for AGENTS.md
      files.push("AGENTS.md");

      for (const file of files) {
        rulePromises.push(
          this.loadRulesFromMarkdownFile(span.ctx, currentPath, file)
        );
      }

      const parentPath = dirname(currentPath);
      if (parentPath === currentPath) break;
      currentPath = parentPath;
    }
    const rules = (await Promise.all(rulePromises)).flat();
    span.span.setAttribute("rules", rules.length);
    return rules;
  }

  private async loadRulesFromMarkdownFile(
    ctx: Context,
    currentPath: string,
    filename: RuleMarkdownFilename
  ): Promise<ParsedRule[]> {
    using span = createSpan(
      ctx.withName("LocalCursorRulesService.loadRulesFromMarkdownFile")
    );
    span.span.setAttribute("filename", filename);
    try {
      const path = join(currentPath, filename);
      if (await this.isCursorIgnored(path)) {
        return [];
      }
      const st = await stat(path);
      if (st.isFile()) {
        const content = await readText(path);
        return [
          {
            filename: basename(path, ".md"),
            path: path,
            frontmatter: { alwaysApply: true },
            body: content,
          },
        ];
      }
    } catch {}
    return [];
  }

  private async isCursorIgnored(path: string): Promise<boolean> {
    try {
      const resolved = await resolvePathForIgnoreService(
        resolve(this.rootDirectory, path)
      );
      if (resolved === null) {
        return true;
      }
      return await this.ignoreService.isCursorIgnored(resolved);
    } catch {
      return false;
    }
  }

  private async parseNestedRuleFiles(
    ctx: Context,
    paths: string[]
  ): Promise<ParsedRule[]> {
    using span = createSpan(
      ctx.withName("LocalCursorRulesService.parseNestedRuleFiles")
    );

    const results = await Promise.all(
      paths.map(async (path): Promise<ParsedRule | undefined> => {
        try {
          const content = await readText(path);
          const parsed = parseCursorRulesMdcContent(content);
          if (parsed) {
            return {
              filename: basename(path, ".mdc"),
              path,
              frontmatter: parsed.frontmatter,
              rawFrontmatter: parsed.rawFrontmatter,
              body: parsed.body,
            };
          }
        } catch {}
        return undefined;
      })
    );

    const acc = results.filter((r): r is ParsedRule => r !== undefined);
    span.span.setAttribute("ruleFiles", acc.length);
    return acc;
  }

  private async parseNestedMarkdownFiles(
    ctx: Context,
    paths: string[]
  ): Promise<ParsedRule[]> {
    using span = createSpan(
      ctx.withName("LocalCursorRulesService.parseNestedMarkdownFiles")
    );

    const results = await Promise.all(
      paths.map(async (path): Promise<ParsedRule[]> => {
        try {
          const filename = basename(path);
          if (!this.isRuleMarkdownFile(filename)) {
            return [];
          }
          const dirPath = dirname(path);
          return await this.loadRulesFromMarkdownFile(
            span.ctx,
            dirPath,
            filename as RuleMarkdownFilename
          );
        } catch {}
        return [];
      })
    );

    const acc = results.flat();
    span.span.setAttribute("markdownFiles", acc.length);
    return acc;
  }

  // baseDir is a directory containing a .cursor/rules subdirectory to scan
  private async loadRulesFromDirectory(
    ctx: Context,
    baseDir: string
  ): Promise<ParsedRule[]> {
    using span = createSpan(
      ctx.withName("LocalCursorRulesService.loadRulesFromDirectory")
    );
    const rules: ParsedRule[] = [];

    try {
      // Each scan honors exactly the `.cursorignore` at its scan root:
      // ripgrep anchors `--cursor-ignore` patterns to its cwd (baseDir
      // here), so the file and its anchor can't disagree. Workspace config
      // never leaks into ancestor scans (e.g. ~/.cursor/rules), while an
      // ancestor's own negations apply when its tree is scanned. Probing
      // the filesystem directly (not the ignore service's lazily-updated
      // mapping) also means a just-created `.cursorignore` is visible to
      // the reload its own create event triggers.
      const cursorIgnoreFile = join(baseDir, ".cursorignore");
      const cursorIgnoreFiles = rulesDiscoveryRespectsCursorIgnore
        ? await stat(cursorIgnoreFile).then(
            st => (st.isFile() ? [cursorIgnoreFile] : []),
            () => []
          )
        : [];
      // With the flag on, ripgrep runs from baseDir with `.cursor/rules` as a
      // positional path: traversal stays scoped to the rules dir, but
      // `--cursor-ignore` patterns (written relative to the scan root)
      // anchor correctly, letting negations re-include gitignored rules.
      const ripwalkOptions: RipwalkOptions = rulesDiscoveryRespectsCursorIgnore
        ? {
            root: baseDir,
            searchPaths: [join(".cursor", "rules")],
            includeGlobs: ["**/*.mdc"],
            cursorIgnoreFiles,
            followSymlinks: true,
            source: "cursor_rules",
          }
        : {
            root: join(baseDir, ".cursor", "rules"),
            includeGlobs: ["**/*.mdc"],
            followSymlinks: true,
            source: "cursor_rules",
          };
      const ripwalkResult = LocalCursorRulesService.getRipwalkCache().walk(
        span.ctx,
        ripwalkOptions
      );
      for await (const relativePath of ripwalkResult.lines) {
        // Lines are relative to the walk root in both shapes.
        const fullPath = join(ripwalkOptions.root, relativePath);
        rules.push(...(await this.readRulesAtPath(span.ctx, fullPath)));
      }
    } catch {}

    span.span.setAttribute("rules", rules.length);
    return rules;
  }

  private async dirIsDirectory(ctx: Context, path: string): Promise<boolean> {
    using _span = createSpan(
      ctx.withName("LocalCursorRulesService.dirIsDirectory")
    );
    try {
      const st = await stat(path);
      return st.isDirectory();
    } catch {
      return false;
    }
  }
}

/**
 * Service that loads Agent Skills from .cursor/skills, .agents/skills, .claude/skills,
 * and .codex/skills directories and converts them to CursorRule objects.
 */

/**
 * Represents the structure of ~/.claude/settings.json
 */
interface ClaudeSettingsJson {
  enabledPlugins?: Record<string, boolean>;
}

/**
 * Represents a single plugin entry in installed_plugins.json (v2 format)
 */
interface InstalledPluginEntry {
  scope: string;
  installPath: string;
  version: string;
  installedAt: string;
  lastUpdated: string;
  gitCommitSha?: string;
  isLocal?: boolean;
}

/**
 * Represents the structure of ~/.claude/plugins/installed_plugins.json (v2 format)
 * In v2, each plugin has an array of entries for multi-scope support
 */
interface InstalledPluginsJson {
  version: number;
  plugins: Record<string, InstalledPluginEntry[]>;
}

export class AgentSkillsCursorRulesService
  implements CursorRulesService, AgentSkillsService
{
  private _rules: Promise<CursorRule[]>;
  private _agentSkills: Promise<AgentSkill[]>;
  private watchersByFolder: Map<string, () => void> = new Map();
  private onChangeCallbacks: Set<() => void> = new Set();
  private foldersToWatch: string[];
  private fileWatcher: CursorRulesFileWatcher | undefined;
  private readonly getThirdPartyExtensibilityEnabled: () => boolean;
  private readonly surface: string;
  private readonly nestedExtensibilityEntries: ReadonlyArray<NestedExtensibilityService>;

  constructor(
    ctx: Context,
    private readonly workspacePaths: string[],
    private readonly userHomeDirectory: string,
    private readonly gitExecutor: GitExecutor,
    loadNestedSkills: boolean,
    fileWatcher: CursorRulesFileWatcher | undefined,
    getThirdPartyExtensibilityEnabled: () => boolean = () => true,
    private readonly initialBuiltinSkillsSyncPromise: Promise<void> = Promise.resolve(),
    surface: string = "ide",
    initialNestedExtensibilityResults?: ReadonlyArray<
      Promise<NestedExtensibilityResult>
    >
  ) {
    this.surface = surface;
    this.fileWatcher = fileWatcher;
    this.getThirdPartyExtensibilityEnabled = getThirdPartyExtensibilityEnabled;
    if (
      initialNestedExtensibilityResults !== undefined &&
      initialNestedExtensibilityResults.length !== workspacePaths.length
    ) {
      throw new Error(
        `initialNestedExtensibilityResults length (${initialNestedExtensibilityResults.length}) must match workspacePaths length (${workspacePaths.length})`
      );
    }
    this.nestedExtensibilityEntries = loadNestedSkills
      ? workspacePaths.map(
          workspacePath =>
            new NestedExtensibilityService(
              workspacePath,
              gitExecutor,
              userHomeDirectory,
              getThirdPartyExtensibilityEnabled
            )
        )
      : [];
    this.foldersToWatch = this.computeFoldersToWatch();

    const loadStartMs = performance.now();
    const loaded = this.loadAll(ctx, initialNestedExtensibilityResults)
      .then(result => {
        try {
          rulesLogger.info(
            ctx,
            "AgentSkillsCursorRulesService load completed",
            {
              durationMs: Math.round(performance.now() - loadStartMs),
              ruleCount: result.rules.length,
              skillCount: result.agentSkills.length,
            }
          );
        } catch {}
        return result;
      })
      .catch(err => {
        debuglog("Failed to load Agent Skills:", err);
        return { rules: [] as CursorRule[], agentSkills: [] as AgentSkill[] };
      });
    this._rules = loaded.then(r => r.rules);
    this._agentSkills = loaded.then(r => r.agentSkills);

    this.setupWatchers(this.foldersToWatch);
  }

  private computeFoldersToWatch(): string[] {
    const thirdPartyExtensibilityEnabled =
      this.getThirdPartyExtensibilityEnabled();

    const folders = new Set<string>();

    for (const workspacePath of this.workspacePaths) {
      folders.add(join(workspacePath, ".cursor", "rules"));
      for (const root of getProjectExtensibilitySkillRoots(
        workspacePath,
        thirdPartyExtensibilityEnabled
      )) {
        folders.add(root.dirPath);
      }
    }

    for (const root of getUserExtensibilitySkillRoots(
      this.userHomeDirectory,
      thirdPartyExtensibilityEnabled
    )) {
      folders.add(root.dirPath);
    }

    folders.add(
      getBuiltinExtensibilitySkillRoot(this.userHomeDirectory).dirPath
    );

    return Array.from(folders);
  }

  private setupWatchers(folders: string[]): void {
    if (!this.fileWatcher) return;

    const skillsPatterns = ["**"];
    for (const folder of folders) {
      if (this.watchersByFolder.has(folder)) continue;

      const unsubscribe = this.fileWatcher.subscribe(
        folder,
        skillsPatterns,
        (path: string) => {
          const reloadCtx = createContext();
          using span = createSpan(
            reloadCtx.withName(
              "AgentSkillsCursorRulesService.fileWatcher.subscribe"
            )
          );
          this.reloadAtPath(span.ctx, path);
        }
      );
      this.watchersByFolder.set(folder, unsubscribe);
    }
  }

  private removeWatchers(folders: string[]): void {
    for (const folder of folders) {
      const unsubscribe = this.watchersByFolder.get(folder);
      if (unsubscribe) {
        unsubscribe();
        this.watchersByFolder.delete(folder);
      }
    }
  }

  async getAllCursorRules(_ctx: Context): Promise<CursorRule[]> {
    return await this._rules;
  }

  reload(ctx: Context): void {
    const newFoldersToWatch = this.computeFoldersToWatch();
    const oldFoldersSet = new Set(this.foldersToWatch);
    const newFoldersSet = new Set(newFoldersToWatch);

    const foldersToRemove = this.foldersToWatch.filter(
      f => !newFoldersSet.has(f)
    );
    this.removeWatchers(foldersToRemove);

    const foldersToAdd = newFoldersToWatch.filter(f => !oldFoldersSet.has(f));
    this.setupWatchers(foldersToAdd);

    this.foldersToWatch = newFoldersToWatch;

    const loaded = this.loadAll(ctx).catch(err => {
      debuglog("Failed to load Agent Skills:", err);
      return { rules: [] as CursorRule[], agentSkills: [] as AgentSkill[] };
    });
    this._rules = loaded.then(r => r.rules);
    this._agentSkills = loaded.then(r => r.agentSkills);

    for (const callback of this.onChangeCallbacks) {
      callback();
    }
  }

  private reloadAtPath(ctx: Context, path: string): void {
    using span = createSpan(
      ctx.withName("AgentSkillsCursorRulesService.reloadAtPath")
    );

    const pathWithSkillMd = path.endsWith("SKILL.md")
      ? path
      : join(path, "SKILL.md");

    // Shared between both channels; no-op catch prevents unhandled rejection on deletion.
    const parsedFile = readAndParseSkillFile(pathWithSkillMd);
    parsedFile.catch(() => {});

    const reloadChannel = async <T extends { fullPath: string }>(
      previous: Promise<T[]>,
      build: (parsed: ParsedSkillFile) => T | undefined
    ): Promise<T[]> => {
      const prevResolved = await previous;
      const prevAtOtherPaths = prevResolved.filter(
        item => item.fullPath !== pathWithSkillMd
      );
      if (shouldIgnoreExtensibilitySkillPath(pathWithSkillMd)) {
        return prevAtOtherPaths;
      }
      try {
        await stat(pathWithSkillMd);
        const parsed = await parsedFile;
        if (isExcludedBySurface(parsed.parsed, this.surface)) {
          return prevAtOtherPaths;
        }
        const built = build(parsed);
        return built === undefined
          ? prevAtOtherPaths
          : [...prevAtOtherPaths, built];
      } catch {
        return prevAtOtherPaths;
      }
    };

    this._rules = reloadChannel(this._rules, parsed =>
      buildCursorRuleFromParsed(parsed)
    ).catch(err => {
      debuglog("Failed to load Agent Skills at path:", err);
      return [];
    });

    this._agentSkills = reloadChannel(this._agentSkills, parsed =>
      isAlwaysApplySkillParsed(parsed.parsed)
        ? undefined
        : buildAgentSkillFromParsed(parsed)
    ).catch(err => {
      debuglog("Failed to load Agent Skills (proto) at path:", err);
      return [];
    });

    for (const callback of this.onChangeCallbacks) {
      callback();
    }
  }

  async getAllAgentSkills(_ctx: Context): Promise<AgentSkill[]> {
    return await this._agentSkills;
  }

  onDidChangeSkills(callback: () => void): () => void {
    return this.onDidChangeRules(callback);
  }

  onDidChangeRules(callback: () => void): () => void {
    this.onChangeCallbacks.add(callback);
    return () => {
      this.onChangeCallbacks.delete(callback);
    };
  }

  dispose(): void {
    for (const unsubscribe of this.watchersByFolder.values()) {
      unsubscribe();
    }
    this.watchersByFolder.clear();
  }

  private async loadAll(
    ctx: Context,
    initialNestedExtensibilityResults?: ReadonlyArray<
      Promise<NestedExtensibilityResult>
    >
  ): Promise<{ rules: CursorRule[]; agentSkills: AgentSkill[] }> {
    using span = createSpan(
      ctx.withName("AgentSkillsCursorRulesService.loadAll")
    );
    await this.initialBuiltinSkillsSyncPromise;

    const rules: CursorRule[] = [];
    const agentSkills: AgentSkill[] = [];

    const seenPaths = new Set<string>();

    // Kick nested discovery immediately so ripwalk overlaps folder walks/parses.
    // nestedExtensibilityEntries is only populated when loadNestedSkills; discover()
    // skips the ripwalk when the workspace root is not inside a git work tree.
    const nestedResultsPromise = Promise.all(
      this.nestedExtensibilityEntries.map((service, idx) =>
        (
          initialNestedExtensibilityResults?.[idx] ?? service.discover(span.ctx)
        ).catch(error => {
          debuglog("cursor-rules-service")(
            "Failed to discover nested agent skills: %O",
            error
          );
          return undefined;
        })
      )
    );

    // Discover + parse each watched skills root in parallel. Folder order is
    // preserved when merging so catalog order stays deterministic.
    const parsedByFolder = await Promise.all(
      this.foldersToWatch.map(async skillsDir => {
        const skillFiles = (await findSkillMdFilesRecursive(skillsDir)).filter(
          skillFilePath => !shouldIgnoreExtensibilitySkillPath(skillFilePath)
        );
        return Promise.all(
          skillFiles.map(async skillFilePath => {
            try {
              return await readAndParseSkillFile(skillFilePath);
            } catch (error) {
              const errorMessage =
                error instanceof Error ? error.message : String(error);
              return { skillFilePath, error: errorMessage } as const;
            }
          })
        );
      })
    );

    for (const parsedFiles of parsedByFolder) {
      for (const result of parsedFiles) {
        seenPaths.add(result.skillFilePath);
        if ("error" in result) {
          addSkillError({
            rules,
            agentSkills,
            skillFilePath: result.skillFilePath,
            errorMessage: result.error,
          });
        } else {
          if (isExcludedBySurface(result.parsed, this.surface)) {
            continue;
          }
          rules.push(buildCursorRuleFromParsed(result));
          if (!isAlwaysApplySkillParsed(result.parsed)) {
            agentSkills.push(buildAgentSkillFromParsed(result));
          }
        }
      }
    }

    const nestedResults = await nestedResultsPromise;
    const nestedSkillPaths = nestedResults
      .flatMap(nested => nested?.skills ?? [])
      .filter(skillPath => !shouldIgnoreExtensibilitySkillPath(skillPath));
    const dedupedNestedSkillPaths: string[] = [];
    const nestedSeenPaths = new Set<string>();
    for (const skillPath of nestedSkillPaths) {
      if (seenPaths.has(skillPath) || nestedSeenPaths.has(skillPath)) {
        continue;
      }
      nestedSeenPaths.add(skillPath);
      dedupedNestedSkillPaths.push(skillPath);
    }

    const parsedNestedFiles = await Promise.all(
      dedupedNestedSkillPaths.map(async skillFilePath => {
        try {
          return await readAndParseSkillFile(skillFilePath);
        } catch (error) {
          const errorMessage =
            error instanceof Error ? error.message : String(error);
          return { skillFilePath, error: errorMessage } as const;
        }
      })
    );

    for (const result of parsedNestedFiles) {
      seenPaths.add(result.skillFilePath);
      if ("error" in result) {
        addSkillError({
          rules,
          agentSkills,
          skillFilePath: result.skillFilePath,
          errorMessage: result.error,
        });
      } else {
        if (isExcludedBySurface(result.parsed, this.surface)) {
          continue;
        }
        rules.push(buildCursorRuleFromParsed(result));
        if (!isAlwaysApplySkillParsed(result.parsed)) {
          agentSkills.push(buildAgentSkillFromParsed(result));
        }
      }
    }

    span.span.setAttribute("agent_skills.total", rules.length);
    span.span.setAttribute("agent_skills_proto.total", agentSkills.length);
    return { rules, agentSkills };
  }
}

