function mapTranslatedRuleToCursorRule(r: TranslatedCursorRule): CursorRule {
  let ruleType: CursorRuleType;
  switch (r.type) {
    case "global":
      ruleType = new CursorRuleType({
        type: { case: "global", value: new CursorRuleTypeGlobal() },
      });
      break;
    case "fileGlobbed":
      ruleType = new CursorRuleType({
        type: {
          case: "fileGlobbed",
          value: new CursorRuleTypeFileGlobs({ globs: r.globs ?? [] }),
        },
      });
      break;
    case "agentFetched":
      ruleType = new CursorRuleType({
        type: {
          case: "agentFetched",
          value: new CursorRuleTypeAgentFetched({
            description: truncateRuleOrSkillDescription(r.description ?? ""),
          }),
        },
      });
      break;
    case "manuallyAttached":
      ruleType = new CursorRuleType({
        type: {
          case: "manuallyAttached",
          value: new CursorRuleTypeManuallyAttached(),
        },
      });
      break;
    default: {
      const _: never = r.type;
      ruleType = new CursorRuleType({
        type: {
          case: "manuallyAttached",
          value: new CursorRuleTypeManuallyAttached(),
        },
      });
    }
  }
  return new CursorRule({
    fullPath: r.fullPath,
    content: r.content,
    type: ruleType,
    gitRemoteOrigin: r.gitRemoteOrigin,
    plugin: r.plugin,
    marketplace: r.marketplace,
    pluginId: r.pluginId,
    marketplaceId: r.marketplaceId,
    environments: r.environments ?? [],
    disabledEnvironments: r.disabledEnvironments ?? [],
    scopedTo: [],
  });
}

/**
 * Settings for importing Cursor plugins.
 */
export interface CursorPluginsImportSettings {
  /** Whether to import skills from Claude Code and other third-party plugins */
  importThirdPartyPlugins: boolean;
}

/**
 * Service that loads Agent Skills from Claude/Cursor plugins.
 * These are plugins read from Claude's cache in ~/.claude/plugins/.
 * Implements both CursorRulesService (old channel) and AgentSkillsService (new channel).
 */
export class CursorPluginsAgentSkillsService
  implements CursorRulesService, AgentSkillsService
{
  private _rules: Promise<CursorRule[]>;
  private _agentSkills: Promise<AgentSkill[]>;
  private readonly onChangeCallbacks: Set<() => void> = new Set();
  private currentImportSettings: CursorPluginsImportSettings;

  constructor(
    ctx: Context,
    private readonly getImportSettings: () => CursorPluginsImportSettings,
    _fileWatcher: CursorRulesFileWatcher | undefined,
    private readonly pluginsService: PluginsService
  ) {
    this.currentImportSettings = this.getImportSettings();

    const loadStartMs = performance.now();
    const loaded = this.loadAll(ctx)
      .then(result => {
        try {
          rulesLogger.info(
            ctx,
            "CursorPluginsAgentSkillsService load completed",
            {
              durationMs: Math.round(performance.now() - loadStartMs),
              ruleCount: result.rules.length,
              skillCount: result.agentSkills.length,
            }
          );
        } catch {}
        return result;
      })
      .catch(err => {
        const d = debuglog("cursor-plugins-agent-skills");
        d(
          "Failed to load Cursor Plugins Agent Skills: %s",
          err instanceof Error ? err.message : String(err)
        );
        return { rules: [] as CursorRule[], agentSkills: [] as AgentSkill[] };
      });
    this._rules = loaded.then(r => r.rules);
    this._agentSkills = loaded.then(r => r.agentSkills);
  }

  async getAllCursorRules(_ctx: Context): Promise<CursorRule[]> {
    return await this._rules;
  }

  async getAllAgentSkills(_ctx: Context): Promise<AgentSkill[]> {
    return await this._agentSkills;
  }

  reload(ctx: Context): void {
    const newSettings = this.getImportSettings();
    this.currentImportSettings = newSettings;

    const loaded = this.loadAll(ctx, true).catch(err => {
      const d = debuglog("cursor-plugins-agent-skills");
      d(
        "Failed to load Cursor Plugins Agent Skills: %s",
        err instanceof Error ? err.message : String(err)
      );
      return { rules: [] as CursorRule[], agentSkills: [] as AgentSkill[] };
    });
    this._rules = loaded.then(r => r.rules);
    this._agentSkills = loaded.then(r => r.agentSkills);

    for (const callback of this.onChangeCallbacks) {
      callback();
    }
  }

  onDidChangeRules(callback: () => void): () => void {
    this.onChangeCallbacks.add(callback);
    return () => {
      this.onChangeCallbacks.delete(callback);
    };
  }

  onDidChangeSkills(callback: () => void): () => void {
    return this.onDidChangeRules(callback);
  }

  dispose(): void {
    this.onChangeCallbacks.clear();
  }

  private async loadAll(
    ctx: Context,
    reloadPlugins: boolean = false
  ): Promise<{ rules: CursorRule[]; agentSkills: AgentSkill[] }> {
    using span = createSpan(
      ctx.withName("CursorPluginsAgentSkillsService.loadAll")
    );

    const rules: CursorRule[] = [];
    const agentSkills: AgentSkill[] = [];

    try {
      let plugins = reloadPlugins
        ? await this.pluginsService.reload()
        : await this.pluginsService.getAllEnabledPlugins();

      // When importThirdPartyPlugins is off, exclude any primitives from Claude Code plugins.
      if (!this.currentImportSettings.importThirdPartyPlugins) {
        plugins = plugins.filter(p => p.identifier.source !== "claude-plugin");
      }

      span.span.setAttribute("cursor_plugins.loaded", plugins.length);

      const translatedSkills = translatePluginSkillsToCursorRules(plugins);
      const translatedRules = translatePluginRulesToCursorRules(plugins);
      for (const r of [...translatedSkills, ...translatedRules]) {
        rules.push(mapTranslatedRuleToCursorRule(r));
      }

      for (const plugin of plugins) {
        const pluginOrigin = `plugin:${getPluginIdentifierKey(plugin.identifier)}`;
        const pluginName = getPluginName(plugin.identifier);
        const marketplace = getPluginMarketplace(plugin.identifier);
        const pluginId = getPluginDbId(plugin.identifier);
        const marketplaceId = getPluginMarketplaceDbId(plugin.identifier);
        for (const skill of plugin.skills) {
          if (skill.alwaysApply === true) {
            continue;
          }

          let disableModelInvocation = false;
          if (skill.content?.includes("disable-model-invocation")) {
            try {
              disableModelInvocation =
                grayMatter(skill.content).data?.["disable-model-invocation"] ===
                true;
            } catch {
              // parse error — leave as false
            }
          }

          agentSkills.push(
            new AgentSkill({
              fullPath: join(plugin.installPath, skill.path),
              content: skill.content,
              description: truncateRuleOrSkillDescription(
                skill.description ?? ""
              ),
              environments: skill.environments ?? [],
              disabledEnvironments: skill.disabledEnvironments ?? [],
              gitRemoteOrigin: pluginOrigin,
              plugin: pluginName,
              marketplace,
              pluginId,
              marketplaceId,
              disableModelInvocation,
            })
          );
        }
      }
    } catch (err) {
      span.span.setAttribute("cursor_plugins.error", String(err));
    }

    span.span.setAttribute("cursor_plugins.total", rules.length);
    span.span.setAttribute("cursor_plugins_proto.total", agentSkills.length);
    return { rules, agentSkills };
  }
}
