import { readFile } from "node:fs/promises";
import { parse as parseJsonc } from "jsonc-parser";
import { z } from "zod";
import {
  type EnvLookup,
  expandCommandBasedMcpServerWithLayeredLookup,
  expandEnvVarsWithLookup,
} from "./env-expansion.js";

export const commandBasedMcpServer: z.ZodObject<
  {
    type: z.ZodOptional<z.ZodLiteral<"stdio">>;
    command: z.ZodString;
    args: z.ZodOptional<z.ZodArray<z.ZodString, "many">>;
    env: z.ZodOptional<z.ZodRecord<z.ZodString, z.ZodString>>;
    cwd: z.ZodOptional<z.ZodString>;
  },
  "strip"
> = z.object({
  type: z.literal("stdio").optional(),
  command: z.string(),
  args: z.array(z.string()).optional(),
  env: z.record(z.string(), z.string()).optional(),
  cwd: z.string().optional(),
});

export const mcpAuthConfig: z.ZodObject<
  {
    CLIENT_ID: z.ZodString;
    CLIENT_SECRET: z.ZodOptional<z.ZodString>;
    scopes: z.ZodOptional<z.ZodArray<z.ZodString, "many">>;
  },
  "strip"
> = z.object({
  CLIENT_ID: z.string(),
  CLIENT_SECRET: z.string().optional(),
  scopes: z.array(z.string()).optional(),
});

export type McpAuthConfig = z.infer<typeof mcpAuthConfig>;

const MAX_CA_BUNDLE_LENGTH = 128 * 1024;

export const mcpTlsConfig: z.ZodObject<
  {
    caBundle: z.ZodString;
  },
  "strict"
> = z
  .object({
    caBundle: z.string().trim().min(1).max(MAX_CA_BUNDLE_LENGTH),
  })
  .strict();

export type McpTlsConfig = z.infer<typeof mcpTlsConfig>;

export const remoteMcpServer: z.ZodObject<
  {
    type: z.ZodOptional<z.ZodEnum<["http", "sse"]>>;
    url: z.ZodString;
    headers: z.ZodOptional<z.ZodRecord<z.ZodString, z.ZodString>>;
    auth: z.ZodOptional<typeof mcpAuthConfig>;
    tls: z.ZodOptional<typeof mcpTlsConfig>;
  },
  "strip"
> = z.object({
  type: z.enum(["http", "sse"]).optional(),
  url: z.string(),
  headers: z.record(z.string(), z.string()).optional(),
  auth: mcpAuthConfig.optional(),
  tls: mcpTlsConfig.optional(),
});

export const mcpServerSchema: z.ZodUnion<
  [typeof commandBasedMcpServer, typeof remoteMcpServer]
> = z.union([commandBasedMcpServer, remoteMcpServer]);

export type McpServerConfig = z.infer<typeof mcpServerSchema>;

export const mcpConfigSchema: z.ZodObject<
  { mcpServers: z.ZodRecord<z.ZodString, typeof mcpServerSchema> },
  "strip"
> = z.object({
  mcpServers: z.record(z.string(), mcpServerSchema),
});

export type McpConfig = z.infer<typeof mcpConfigSchema>;

/**
 * Combine two MCP configs into one object.
 * - Entries from userConfig are included first
 * - Entries from projectConfig override user entries on name collisions
 */
export function combineMcpConfigs(
  userConfig?: McpConfig,
  projectConfig?: McpConfig
): McpConfig {
  const combinedServers: Record<string, McpServerConfig> = {};

  if (userConfig) {
    for (const [serverName, serverConfig] of Object.entries(
      userConfig.mcpServers
    )) {
      combinedServers[serverName] = serverConfig;
    }
  }

  if (projectConfig) {
    for (const [serverName, serverConfig] of Object.entries(
      projectConfig.mcpServers
    )) {
      combinedServers[serverName] = serverConfig;
    }
  }

  return { mcpServers: combinedServers };
}

/**
 * Convenience helper specifically for our McpServerConfig shape.
 */
export async function getMcpConfig(
  configPath: string,
  envLookup: EnvLookup = (key: string) => process.env[key]
): Promise<McpConfig> {
  try {
    const configString = await readFile(configPath, "utf8");
    const raw = parseJsonc(configString);
    const expanded = expandEnvVarsWithLookup(raw, envLookup);
    return mcpConfigSchema.parse(expanded);
  } catch {
    // Return empty config if file doesn't exist or is invalid
    return { mcpServers: {} };
  }
}

/**
 * Expands `${VAR}` placeholders for MCP config passed into cloud exec-daemon (CLI `--mcp-config`),
 * matching local `getMcpConfig` string expansion where applicable.
 *
 * - **stdio**: `expandCommandBasedMcpServerWithLayeredLookup` (server `env` then `runtimeLookup`, single-pass).
 * - **HTTP (`url`)**: `expandEnvVarsWithLookup` on `url`, `headers`, and `auth` via `runtimeLookup` only.
 */
export function expandMcpConfigForCloudRuntime(
  config: McpConfig,
  runtimeLookup: EnvLookup = (key: string) => process.env[key]
): McpConfig {
  const mcpServers: McpConfig["mcpServers"] = {};
  for (const [name, server] of Object.entries(config.mcpServers)) {
    if ("command" in server) {
      mcpServers[name] = expandCommandBasedMcpServerWithLayeredLookup(
        server,
        runtimeLookup
      );
    } else {
      mcpServers[name] = expandEnvVarsWithLookup(server, runtimeLookup);
    }
  }
  return { mcpServers };
}
