class MockPermissionsService implements PermissionsService {
  private _shouldBlockShellCommandImpl: (
    parentCtx: Context,
    command: string,
    options: {
      workingDirectory: string;
      timeout: number;
      parsingResult: ShellCommandParsingResult;
      hookApprovalRequirement?: ShellHookApprovalRequirement;
    },
    requestedPolicy?: SandboxPolicy
  ) => Promise<
    | { kind: "allow"; policy: SandboxPolicy }
    | { kind: "block"; reason: BlockReason }
  > = async (_ctx, _cmd, _opts, requestedPolicy) => ({
    kind: "allow",
    policy: requestedPolicy ?? { type: "insecure_none" },
  });

  shouldBlockRead(_filePath: string): Promise<false | BlockReason> {
    return Promise.resolve(false);
  }

  shouldBlockWrite(
    _ctx: Context,
    _filePath: string,
    _newContents: string
  ): Promise<false | BlockReason> {
    return Promise.resolve(false);
  }

  shouldBlockShellCommand(
    ctx: Context,
    command: string,
    options: {
      workingDirectory: string;
      timeout: number;
      parsingResult: ShellCommandParsingResult;
      hookApprovalRequirement?: ShellHookApprovalRequirement;
    },
    requestedPolicy?: SandboxPolicy
  ): Promise<
    | { kind: "allow"; policy: SandboxPolicy }
    | { kind: "block"; reason: BlockReason }
  > {
    return this._shouldBlockShellCommandImpl(
      ctx,
      command,
      options,
      requestedPolicy
    );
  }

  private _shouldEnforceShellInvariantBlocksImpl: (
    _ctx: Context,
    _options: {
      workingDirectory: string;
      skipUnsafeWorkingDirectoryBlock?: boolean;
      command: string;
      parsingResult?: ShellCommandParsingResult;
      toolCallId?: string;
    },
    _requestedPolicy?: SandboxPolicy
  ) => Promise<{ kind: "allow" } | { kind: "block"; reason: BlockReason }> =
    async () => ({ kind: "allow" });

  shouldEnforceShellInvariantBlocks(
    ctx: Context,
    options: {
      workingDirectory: string;
      skipUnsafeWorkingDirectoryBlock?: boolean;
      command: string;
      parsingResult?: ShellCommandParsingResult;
      toolCallId?: string;
    },
    requestedPolicy?: SandboxPolicy
  ): Promise<{ kind: "allow" } | { kind: "block"; reason: BlockReason }> {
    return this._shouldEnforceShellInvariantBlocksImpl(
      ctx,
      options,
      requestedPolicy
    );
  }

  setShouldEnforceShellInvariantBlocks(
    impl: (
      ctx: Context,
      options: {
        workingDirectory: string;
        skipUnsafeWorkingDirectoryBlock?: boolean;
      },
      requestedPolicy?: SandboxPolicy
    ) => Promise<{ kind: "allow" } | { kind: "block"; reason: BlockReason }>
  ): void {
    this._shouldEnforceShellInvariantBlocksImpl = impl;
  }

  private _isShellCommandFullyAllowlistedImpl: (
    _ctx: Context,
    _command: string,
    _options: {
      workingDirectory: string;
      parsingResult: ShellCommandParsingResult;
    }
  ) => Promise<boolean> = async () => false;

  isShellCommandFullyAllowlisted(
    ctx: Context,
    command: string,
    options: {
      workingDirectory: string;
      parsingResult: ShellCommandParsingResult;
    }
  ): Promise<boolean> {
    return this._isShellCommandFullyAllowlistedImpl(ctx, command, options);
  }

  setIsShellCommandFullyAllowlisted(
    impl: (
      ctx: Context,
      command: string,
      options: {
        workingDirectory: string;
        parsingResult: ShellCommandParsingResult;
      }
    ) => Promise<boolean>
  ): void {
    this._isShellCommandFullyAllowlistedImpl = impl;
  }

  shouldBlockMcp(_ctx: Context, _args: McpArgs): Promise<false | BlockReason> {
    return Promise.resolve(false);
  }

  private _isMcpFullyAllowlistedImpl: (
    ctx: Context,
    options: { providerIdentifier: string; toolName: string }
  ) => Promise<boolean> = async () => false;

  isMcpFullyAllowlisted(
    ctx: Context,
    options: { providerIdentifier: string; toolName: string }
  ): Promise<boolean> {
    return this._isMcpFullyAllowlistedImpl(ctx, options);
  }

  isWebFetchFullyAllowlisted(
    _ctx: Context,
    _options: { url: string }
  ): Promise<boolean> {
    return Promise.resolve(false);
  }

  setIsMcpFullyAllowlisted(
    impl: (
      ctx: Context,
      options: { providerIdentifier: string; toolName: string }
    ) => Promise<boolean>
  ): void {
    this._isMcpFullyAllowlistedImpl = impl;
  }

  addToAllowList(
    _ctx: Context,
    _kind: "Shell" | "Read" | "Write" | "Mcp" | "WebFetch",
    _value: string
  ): Promise<void> {
    return Promise.resolve();
  }

  addToDenyList(
    _ctx: Context,
    _kind: "Shell" | "Read" | "Write" | "Mcp" | "WebFetch",
    _value: string
  ): Promise<void> {
    return Promise.resolve();
  }

  setShouldBlockShellCommand(
    impl: (
      ctx: Context,
      command: string,
      options: {
        workingDirectory: string;
        timeout: number;
        parsingResult: ShellCommandParsingResult;
        hookApprovalRequirement?: ShellHookApprovalRequirement;
      },
      requestedPolicy?: SandboxPolicy
    ) => Promise<
      | { kind: "allow"; policy: SandboxPolicy }
      | { kind: "block"; reason: BlockReason }
    >
  ): void {
    this._shouldBlockShellCommandImpl = impl;
  }
}

function makeDefaultTeamSettings(
  overrides: Partial<TeamSettingsService> = {}
): TeamSettingsService {
  return {
    getDotCursorProtection: async () => false,
    getShouldBlockMcp: async () => false,
    getDeleteFileProtection: async () => false,
    getIsHeadlessDisabled: async () => false,
    isServerBlocked: async () => false,
    getAutoRunControls: async () => ({
      enabled: false,
      allowed: [],
      blocked: [],
      enableAllowlistMode: true,
      enableRunEverything: false,
      enableSmartAuto: true,
      mcpToolAllowlist: [],
    }),
    getAdminCommandDenylist: async () => ({ rules: [] }),
    getMcpToolControls: async () => undefined,
    getNetworkAccessControls: async () => ({
      allowlist: [],
      denylist: [],
      available: true,
    }),
    getDefaultNetworkAllowlist: async () => ({
      allowlist: [],
      available: true,
    }),
    getSandboxingControls: async () => ({
      sandboxingDisabled: false,
      networkingDisabled: false,
      gitDisabled: false,
    }),
    getTeamRepos: async () => undefined,
    isAttributionDisabledByAdmin: async () => false,
    invalidateCache: () => {},
    ...overrides,
  };
}

export {
  MockIgnoreService,
  MockPendingDecisionProvider,
  MockPermissionsService,
  makeDefaultTeamSettings,
};
