import { randomBytes } from "node:crypto";
import { mkdir, open, rename, unlink } from "node:fs/promises";
import { basename, dirname, join } from "node:path";

export interface AtomicWriteOptions {
	readonly mode?: number;
}

// A reader never observes a half-written file, and a failure leaves the
// previous contents or nothing — never a truncated mix. The single host-side
// durable-write primitive for every place Sand lands box bytes on the user's
// machine, so the partial-transfer-cleanup guarantee cannot drift.
export async function writeFileAtomic(
	targetPath: string,
	data: Uint8Array,
	options: AtomicWriteOptions = {},
): Promise<void> {
	const dir = dirname(targetPath);
	await mkdir(dir, { recursive: true });
	// Hidden so listings never surface a transient .part; randomized so
	// concurrent writers of one target never collide; same-directory so the
	// final rename is same-filesystem and atomic.
	const tempPath = join(dir, `.${basename(targetPath)}.${randomBytes(8).toString("hex")}.part`);
	// `wx` refuses an existing path, so an unrelated file is never truncated.
	const handle = await open(tempPath, "wx", options.mode);
	try {
		await handle.writeFile(data);
		// fsync before rename: a crash just after the rename must not surface a
		// zero-length or partially-flushed file.
		await handle.sync();
	} catch (error) {
		await handle.close();
		await unlink(tempPath).catch(() => {});
		throw error;
	}
	await handle.close();
	try {
		await rename(tempPath, targetPath);
	} catch (error) {
		await unlink(tempPath).catch(() => {});
		throw error;
	}
}
