/** Longest server-supplied annotation title carried on the wire. */
const MAX_TOOL_ANNOTATION_TITLE_LENGTH = 256;

/**
 * Build the JSON-encoded MCP tool annotations field
 * (`McpToolDescriptor.annotations_json`). Only the MCP-spec annotation
 * fields are serialized — the boolean hints plus a length-capped `title` —
 * so a server cannot inflate every request context by stuffing arbitrary
 * payloads into `Tool.annotations`; the serialized field is structurally
 * bounded to ~150 bytes + title. Empty results are omitted so absent and
 * empty look identical to readers, which must fail closed either way.
 */
export function toolAnnotationsJsonField(
  annotations: Record<string, unknown> | undefined
): { annotationsJson?: string } {
  if (annotations === undefined) {
    return {};
  }
  const bounded: Record<string, unknown> = {};
  if (typeof annotations.title === "string" && annotations.title.length > 0) {
    bounded.title = annotations.title.slice(
      0,
      MAX_TOOL_ANNOTATION_TITLE_LENGTH
    );
  }
  for (const key of [
    "readOnlyHint",
    "destructiveHint",
    "idempotentHint",
    "openWorldHint",
  ] as const) {
    if (typeof annotations[key] === "boolean") {
      bounded[key] = annotations[key];
    }
  }
  if (Object.keys(bounded).length === 0) {
    return {};
  }
  return { annotationsJson: JSON.stringify(bounded) };
}
