import type {
  ApprovalDecision,
  ApprovalProvider,
  McpToolSource,
} from "@anysphere/agent-exec";
import type { Value } from "@bufbuild/protobuf";

export type ApprovalResult = ApprovalDecision;

type WriteOperation = BaseOperation & {
  type: OperationType.Write;
  details: {
    path: string;
    reason: string;
    isNewFile: boolean;
    diffString: string; // for new files, it's just the contents of the file
    before?: string; // undefined for new files
    after?: string; // the content after the edit (same as diffString for new files)
    blockReason?: "outOfWorkspace" | "protectedConfig";
  };
};

export interface BaseOperation {
  type: OperationType;
  toolCallId?: string;
}

export interface ShellOperation extends BaseOperation {
  type: OperationType.Shell;
  details: {
    command: string;
    workingDirectory: string;
    timeout: number;
    reason?: string;
    isSandboxAvailable?: boolean;
    isSandboxEnabled?: boolean;
    canAllowlist?: boolean;
    notAllowedCommands?: string[];
    /** Suggested allowlist entries from the classifier (when smart allowlist is enabled) */
    suggestedAllowlistEntries?: string[];
    smartModeApprovalReason?: string;
    smartModeApprovalRequestId?: string;
  };
}

type DeleteOperation = BaseOperation & {
  type: OperationType.Delete;
  details: {
    path: string;
  };
};

type McpOperation = BaseOperation & {
  type: OperationType.Mcp;
  details: {
    name: string;
    toolName: string;
    providerIdentifier: string;
    source?: McpToolSource;
    args: Record<string, Value>;
    reason?: string;
    canAllowlist?: boolean;
    smartModeApprovalReason?: string;
    smartModeApprovalRequestId?: string;
  };
};

export enum OperationType {
  Write = "write",
  Shell = "shell",
  Delete = "delete",
  Mcp = "mcp",
}

export type Operation =
  | WriteOperation
  | ShellOperation
  | DeleteOperation
  | McpOperation;

export interface PendingDecisionProvider
  extends ApprovalProvider<Operation, ApprovalResult> {
  requestApproval(operation: Operation): Promise<ApprovalResult>;
}
