/**
 * Metrics for detecting silent failures in MCP file system sync.
 * Tracks divergence between lease state (source of truth) and filesystem state.
 *
 * The `mcp_source` label distinguishes which lease/snapshot system detected the divergence:
 * - "workbench_lease": traditional ObservableMcpLease path that writes to disk
 * - "snapshot": McpSnapshotProvider path (used by meta tool system)
 */
type McpSource = "workbench_lease" | "snapshot";

/**
 * Bucket the number of configured MCP servers into a low-cardinality label.
 * This lets us correlate divergence/sync metrics with whether the user
 * even has MCP servers and roughly how many.
 */
function configuredServersBucket(count: number): string {
  if (count === 0) return "0";
  if (count <= 3) return "1-3";
  if (count <= 6) return "4-6";
  if (count <= 10) return "7-10";
  return "11+";
}

