const baseLogger = createLogger("McpFileSystemWriter");

export const MCP_FS_STRUCTURED_LOG_OPT_IN_METADATA_KEY =
  "mcpFsStructuredLogOptIn";

type McpFsLogOptions = {
  includeStructuredLogs?: boolean;
};

function withStructuredLogOptIn(
  metadata: Record<string, unknown> | undefined,
  options: McpFsLogOptions | undefined
): Record<string, unknown> | undefined {
  if (!options?.includeStructuredLogs) {
    return metadata;
  }
  return {
    ...(metadata ?? {}),
    [MCP_FS_STRUCTURED_LOG_OPT_IN_METADATA_KEY]: true,
  };
}

const logger = {
  debug(
    ctx: Context,
    message: string,
    metadata?: Record<string, unknown>,
    options?: McpFsLogOptions
  ): void {
    baseLogger.debug(ctx, message, withStructuredLogOptIn(metadata, options));
  },
  info(
    ctx: Context,
    message: string,
    metadata?: Record<string, unknown>,
    options?: McpFsLogOptions
  ): void {
    baseLogger.info(ctx, message, withStructuredLogOptIn(metadata, options));
  },
  warn(
    ctx: Context,
    message: string,
    metadata?: Record<string, unknown>,
    options?: McpFsLogOptions
  ): void {
    baseLogger.warn(ctx, message, withStructuredLogOptIn(metadata, options));
  },
  error(
    ctx: Context,
    message: string,
    error?: Error | unknown,
    metadata?: Record<string, unknown>,
    options?: McpFsLogOptions
  ): void {
    baseLogger.error(
      ctx,
      message,
      error,
      withStructuredLogOptIn(metadata, options)
    );
  },
};

