/**
 * Sanitizes a name for use as a filename (tools, resources, prompts).
 */
function sanitizeFileName(name: string): string {
  return name.replace(/[^a-zA-Z0-9_-]/g, "_");
}

export interface McpAuthCopyOverrides {
  authToolDescription?: string;
  errorStatusMessage?: string;
  needsAuthStatusMessageWithAuthTool?: string;
  /** Shown for needsAuth when `exposeVirtualMcpAuthTool` is false. */
  needsAuthStatusMessageWithoutVirtualTool?: string;
}

type McpAuthTemplateParams = {
  serverIdentifier: string;
  authToolName: string;
};

function getValidCopyOverride(value: string | undefined): string | undefined {
  if (value === undefined) {
    return undefined;
  }
  const trimmed = value.trim();
  return trimmed.length > 0 ? trimmed : undefined;
}

function interpolateMcpAuthTemplate(
  template: string,
  params: McpAuthTemplateParams
): string {
  return template
    .replace(/\{serverIdentifier\}/g, params.serverIdentifier)
    .replace(/\{authToolName\}/g, params.authToolName);
}

function createVirtualMcpAuthToolDefinition(params: {
  serverIdentifier: string;
  serverName: string;
  plugin?: string;
  marketplace?: string;
  pluginId?: string;
  marketplaceId?: string;
  authToolDescription: string;
}): NamedMcpToolDefinition {
  return {
    clientKey: params.serverIdentifier,
    providerIdentifier: params.serverName,
    plugin: params.plugin,
    marketplace: params.marketplace,
    pluginId: params.pluginId,
    marketplaceId: params.marketplaceId,
    toolName: MCP_AUTH_TOOL_NAME,
    name: MCP_AUTH_TOOL_NAME,
    description: params.authToolDescription,
    inputSchema: {
      type: "object",
      properties: {},
      additionalProperties: false,
    },
  };
}

/**
 * Convert McpClientState to McpServerStatus.
 */
function clientStateToServerStatus(state: McpClientState): McpServerStatus {
  switch (state.kind) {
    case "loading":
      return "initializing";
    case "requires_authentication":
      return "needsAuth";
    case "ready":
      return "connected";
    case "error":
      return "error";
    default: {
      return "disconnected";
    }
  }
}

function canonicalizeJsonValue(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map(item => canonicalizeJsonValue(item));
  }

  if (value !== null && typeof value === "object") {
    const entries = Object.entries(value as Record<string, unknown>)
      .filter(([, entryValue]) => entryValue !== undefined)
      .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
      .map(([key, entryValue]) => [key, canonicalizeJsonValue(entryValue)]);
    return Object.fromEntries(entries);
  }

  return value;
}

function canonicalJsonString(value: unknown): string {
  return JSON.stringify(canonicalizeJsonValue(value));
}

function sortByCanonicalJson<T>(values: T[]): T[] {
  const keyedValues = values.map(value => ({
    value,
    key: canonicalJsonString(value),
  }));
  keyedValues.sort((a, b) => (a.key < b.key ? -1 : a.key > b.key ? 1 : 0));
  return keyedValues.map(entry => entry.value);
}

function serverFingerprint(server: McpServerData): string {
  const tools = sortByCanonicalJson(
    server.tools.map(t => ({
      name: t.toolName,
      description: t.description,
      inputSchema: t.inputSchema,
      outputSchema: t.outputSchema,
    }))
  );
  const resources = sortByCanonicalJson(
    server.resources.map(r => ({
      uri: r.uri,
      name: r.name,
      description: r.description,
      mimeType: r.mimeType,
    }))
  );
  const prompts = sortByCanonicalJson(
    server.prompts.map(p => ({
      name: p.name,
      description: p.description,
      arguments: p.arguments,
    }))
  );

  return canonicalJsonString({
    id: server.serverIdentifier,
    name: server.serverName,
    plugin: server.plugin,
    marketplace: server.marketplace,
    pluginId: server.pluginId,
    marketplaceId: server.marketplaceId,
    tools,
    resources,
    prompts,
    instructions: server.instructions,
    status: server.status,
  });
}

/**
 * McpFileSystemWriter writes MCP server data to disk and provides
 * a unified McpFileSystemOptions built from the same in-memory state.
 *
 * This ensures perfect sync between what's on disk and what's in the request context.
 */
export class McpFileSystemWriter {
  private readonly projectDir: string;
  private readonly mcpLease: ObservableMcpLease;
  private readonly debounceMs: number;
  private readonly mcpAuthCopyOverrides?: McpAuthCopyOverrides;
  private readonly useDirectClientTools: boolean;
  private readonly enabledToolsByServerProvider:
    | ((ctx: Context) => Promise<Record<string, string[]>>)
    | undefined;
  private readonly exposeVirtualMcpAuthTool: boolean;
  private readonly alwaysExposeVirtualMcpAuthTool: boolean;
  private readonly snapshotProvider: McpSnapshotProvider | undefined;
  private readonly mcpVersion: string;
  private readonly onDidWrite?: (
    descriptors: McpFileSystemDescriptor[]
  ) => void;
  private readonly startupCleanupPromise: Promise<void>;
  private leaseChangeDisposable: Disposable | undefined;

  /** Cached in-memory state that mirrors what was written to disk. */
  private cachedServerData: McpServerData[] | undefined;
  private cachedFingerprints = new Map<string, string>();
  private writePromise: Promise<void> | undefined;
  private disposed: boolean = false;

  /** Debounce timer for trailing-edge debouncing */
  private debounceTimer: ReturnType<typeof setTimeout> | undefined;
  private pendingLeaseChangeEvent: McpLeaseChangeEvent | undefined;
  private hasPendingLeaseChangeEvent = false;

  private ctx: Context;

  constructor(
    mcpLease: ObservableMcpLease,
    projectDir: string,
    options?: {
      debounceMs?: number;
      loggerBackend?: LoggerBackend;
      mcpAuthCopyOverrides?: McpAuthCopyOverrides;
      useDirectClientTools?: boolean;
      getEnabledToolsByServer?: (
        ctx: Context
      ) => Promise<Record<string, string[]>>;
      /** When false, no synthetic `mcp_auth` tool is written (e.g. exec-daemon). Default true. */
      exposeVirtualMcpAuthTool?: boolean;
      /** When true, synthetic `mcp_auth` is written for every MCP server, not only needsAuth servers. */
      alwaysExposeVirtualMcpAuthTool?: boolean;
      snapshotProvider?: McpSnapshotProvider;
      mcpVersion?: string;
      onDidWrite?: (descriptors: McpFileSystemDescriptor[]) => void;
    }
  ) {
    this.mcpLease = mcpLease;
    this.projectDir = projectDir;
    this.debounceMs = options?.debounceMs ?? DEFAULT_DEBOUNCE_MS;
    this.mcpAuthCopyOverrides = options?.mcpAuthCopyOverrides;
    this.useDirectClientTools = options?.useDirectClientTools ?? false;
    this.enabledToolsByServerProvider = options?.getEnabledToolsByServer;
    this.exposeVirtualMcpAuthTool = options?.exposeVirtualMcpAuthTool ?? true;
    this.alwaysExposeVirtualMcpAuthTool =
      options?.alwaysExposeVirtualMcpAuthTool ?? false;
    this.snapshotProvider = options?.snapshotProvider;
    this.mcpVersion =
      options?.mcpVersion ?? (this.snapshotProvider ? "snapshots" : "v1");
    this.onDidWrite = options?.onDidWrite;
    this.ctx = this.getContext(options?.loggerBackend);
    this.startupCleanupPromise = this.cleanupStaleStagingDirs(this.ctx);

    this.leaseChangeDisposable = this.mcpLease.onDidChange(event => {
      logger.info(this.ctx, "Lease change event received", {
        serverIdentifiers: event?.serverIdentifiers,
        reason: event?.reason,
      });
      this.onLeaseChanged(this.ctx, event);
    });
    logger.info(this.ctx, "Constructor: scheduling initial write");
    this.scheduleWrite(this.ctx);
    this.ensureCursorDirGitignore();
  }

  /**
   * Fire-and-forget: ensure ~/.cursor/.gitignore exists with allowlist rules.
   * Enables LS tool to list MCP config when user has * in ~/.gitignore.
   */
  private ensureCursorDirGitignore(): void {
    void ensureCursorDirGitignore(join(homedir(), ".cursor")).catch(err => {
      logger.warn(this.ctx, "Failed to ensure ~/.cursor/.gitignore", err);
    });
  }

  private async cleanupStaleStagingDirs(ctx: Context): Promise<void> {
    const logCtx = this.getLogContext(ctx);
    const mcpsPath = join(this.projectDir, MCPS_SUBDIR);
    try {
      const entries = await readdir(mcpsPath);
      await Promise.allSettled(
        entries
          .filter(entry => entry.endsWith(STAGING_SUFFIX))
          .map(entry =>
            rm(join(mcpsPath, entry), {
              recursive: true,
              force: true,
            })
          )
      );
    } catch (err: unknown) {
      if ((err as NodeJS.ErrnoException)?.code !== "ENOENT") {
        logger.error(logCtx, "Error clearing stale mcps staging dirs", err);
      }
    }
  }

  private onLeaseChanged(ctx: Context, event?: McpLeaseChangeEvent): void {
    if (this.disposed) {
      return;
    }

    const normalizedEvent = event ?? { serverIdentifiers: undefined };
    if (this.hasPendingLeaseChangeEvent) {
      this.pendingLeaseChangeEvent = mergeMcpLeaseEvents(
        this.pendingLeaseChangeEvent ?? { serverIdentifiers: undefined },
        normalizedEvent
      );
    } else {
      this.pendingLeaseChangeEvent = normalizedEvent;
      this.hasPendingLeaseChangeEvent = true;
    }

    if (this.debounceTimer !== undefined) {
      clearTimeout(this.debounceTimer);
    }

    this.debounceTimer = setTimeout(() => {
      this.debounceTimer = undefined;
      const pendingEvent = this.takePendingLeaseChangeEvent();
      this.scheduleWrite(ctx, pendingEvent);
    }, this.debounceMs);
  }

  private takePendingLeaseChangeEvent(): McpLeaseChangeEvent | undefined {
    if (!this.hasPendingLeaseChangeEvent) {
      return undefined;
    }
    const pendingEvent = this.pendingLeaseChangeEvent ?? {
      serverIdentifiers: undefined,
    };
    this.pendingLeaseChangeEvent = undefined;
    this.hasPendingLeaseChangeEvent = false;
    return pendingEvent;
  }

  private scheduleWrite(
    ctx: Context,
    leaseChangeEvent?: McpLeaseChangeEvent
  ): void {
    const logCtx = this.getLogContext(ctx);
    if (this.disposed) {
      return;
    }

    const previousPromise = this.writePromise;
    this.writePromise = (async () => {
      if (previousPromise) {
        try {
          await previousPromise;
        } catch (error) {
          logger.error(logCtx, "Error waiting for previous write", error);
        }
      }

      if (this.disposed) {
        return;
      }

      await this.startupCleanupPromise;

      if (this.disposed) {
        return;
      }

      await this.fetchAndWrite(ctx, leaseChangeEvent);
    })();
  }

  private getContext(loggerBackend: LoggerBackend | undefined): Context {
    let ctx = createContext();
    if (loggerBackend) {
      ctx = ctx.with(loggerKey, loggerBackend);
    }
    return ctx;
  }

  private getLogContext(ctx: Context): Context {
    return ctx.with(loggerKey, this.ctx.get(loggerKey));
  }

  private getMetricTags<TLabels extends Record<string, string>>(
    labels: TLabels
  ): TLabels & { mcp_version: string } {
    return {
      ...labels,
      mcp_version: this.mcpVersion,
    };
  }

  private getMcpAuthToolDescription(): string {
    return (
      getValidCopyOverride(this.mcpAuthCopyOverrides?.authToolDescription) ??
      DEFAULT_MCP_AUTH_TOOL_DESCRIPTION
    );
  }

  private shouldExposeVirtualMcpAuthToolForStatus(
    serverIdentifier: string,
    status: McpServerStatus | McpSnapshotStatus | undefined
  ): boolean {
    return (
      this.exposeVirtualMcpAuthTool &&
      supportsInteractiveMcpAuth(serverIdentifier) &&
      (this.alwaysExposeVirtualMcpAuthTool || status === "needsAuth")
    );
  }

  private getErrorStatusMessage(): string {
    return (
      getValidCopyOverride(this.mcpAuthCopyOverrides?.errorStatusMessage) ??
      DEFAULT_MCP_ERROR_STATUS_MESSAGE
    );
  }

  private getNeedsAuthStatusMessage(serverIdentifier: string): string {
    const template =
      getValidCopyOverride(
        this.mcpAuthCopyOverrides?.needsAuthStatusMessageWithAuthTool
      ) ?? DEFAULT_MCP_NEEDS_AUTH_STATUS_MESSAGE;
    return interpolateMcpAuthTemplate(template, {
      serverIdentifier,
      authToolName: MCP_AUTH_TOOL_NAME,
    });
  }

  private getNeedsAuthStatusMessageForWrite(serverIdentifier: string): string {
    if (
      !this.exposeVirtualMcpAuthTool ||
      !supportsInteractiveMcpAuth(serverIdentifier)
    ) {
      return (
        getValidCopyOverride(
          this.mcpAuthCopyOverrides?.needsAuthStatusMessageWithoutVirtualTool
        ) ?? DEFAULT_MCP_NEEDS_AUTH_STATUS_MESSAGE_NO_VIRTUAL_TOOL
      );
    }
    return this.getNeedsAuthStatusMessage(serverIdentifier);
  }

  private async getToolsForServers(
    ctx: Context,
    serverIdentifiers: readonly string[]
  ): Promise<NamedMcpToolDefinition[]> {
    if (serverIdentifiers.length === 0) {
      return [];
    }

    const logCtx = this.getLogContext(ctx);
    try {
      return await this.mcpLease.getToolsForServers(ctx, serverIdentifiers);
    } catch (err) {
      logger.warn(
        logCtx,
        `getToolsForServers() threw, falling back to filtered getTools(): ${err}`
      );
      const allTools = await this.mcpLease.getTools(ctx).catch(e => {
        logger.warn(
          logCtx,
          `getTools() threw during scoped-tool fallback, defaulting to []: ${e}`
        );
        return [];
      });
      const requestedServerIds = new Set(serverIdentifiers);
      return allTools.filter(tool => requestedServerIds.has(tool.clientKey));
    }
  }

  private async getEnabledToolsByServer(
    ctx: Context
  ): Promise<Record<string, string[]> | undefined> {
    if (
      !this.useDirectClientTools ||
      this.enabledToolsByServerProvider === undefined
    ) {
      return undefined;
    }

    try {
      return await this.enabledToolsByServerProvider(ctx);
    } catch (err) {
      logger.warn(
        this.getLogContext(ctx),
        `getEnabledToolsByServer() threw, falling back to raw direct client tool lists: ${err}`
      );
      return undefined;
    }
  }

  private async fetchClientDataForServer(
    ctx: Context,
    clientKey: string,
    client: NonNullable<Awaited<ReturnType<ObservableMcpLease["getClient"]>>>,
    options?: { fetchInstructions?: boolean }
  ): Promise<FetchedClientData> {
    const logCtx = this.getLogContext(ctx);
    const state = await withTimeout(client.getState(ctx), {
      kind: "error" as const,
    }).then(s => {
      if (s.kind === "error" && !("message" in s)) {
        logger.warn(
          ctx,
          `getState() timed out for "${clientKey}", defaulting to error`
        );
      }
      return s;
    });

    const isReachable =
      state.kind === "ready" || state.kind === "requires_authentication";

    const [clientTools, resources, prompts, instructions] = await Promise.all([
      isReachable && this.useDirectClientTools
        ? withTimeout(client.getTools(ctx), []).then(tools => {
            if (tools.length === 0) {
              logger.info(
                logCtx,
                `Direct client getTools() returned 0 tools for "${clientKey}" (state=${state.kind})`
              );
            }
            return tools;
          })
        : Promise.resolve([] as never[]),
      isReachable
        ? withTimeout(client.listResources(ctx), { resources: [] })
        : Promise.resolve({ resources: [] as never[] }),
      isReachable
        ? withTimeout(client.listPrompts(ctx), [])
        : Promise.resolve([] as never[]),
      isReachable && options?.fetchInstructions
        ? withTimeout(client.getInstructions(ctx), undefined)
        : Promise.resolve(undefined),
    ]);

    return {
      clientKey,
      serverName: client.serverName,
      plugin: client.plugin,
      marketplace: client.marketplace,
      pluginId: client.pluginId,
      marketplaceId: client.marketplaceId,
      clientTools: clientTools.map(t => ({
        ...t,
        clientKey,
        providerIdentifier: client.serverName,
        plugin: client.plugin,
        marketplace: client.marketplace,
        pluginId: client.pluginId,
        marketplaceId: client.marketplaceId,
        toolName: t.name,
      })),
      resources: resources.resources.map(r => ({
        ...r,
        serverIdentifier: clientKey,
        serverName: client.serverName,
      })),
      prompts: prompts.map(p => ({
        ...p,
        serverIdentifier: clientKey,
        serverName: client.serverName,
      })),
      instructions,
      status: clientStateToServerStatus(state),
    };
  }

  private buildServerDataMap(
    ctx: Context,
    tools: readonly NamedMcpToolDefinition[],
    clientData: readonly FetchedClientData[],
    enabledToolsByServer: Readonly<Record<string, string[]>> | undefined,
    instructions?: readonly {
      serverIdentifier?: string;
      serverName?: string;
      instructions?: string;
    }[]
  ): Map<string, McpServerData> {
    const clientToolsByKey = new Map(
      clientData.map(data => [data.clientKey, data.clientTools] as const)
    );

    const serverDataMap = new Map<string, McpServerData>();
    for (const data of clientData) {
      const sanitizedId = sanitizeServerName(data.clientKey);
      serverDataMap.set(data.clientKey, {
        serverIdentifier: data.clientKey,
        serverName: data.serverName,
        plugin: data.plugin,
        marketplace: data.marketplace,
        pluginId: data.pluginId,
        marketplaceId: data.marketplaceId,
        sanitizedId,
        folderPath: join(this.projectDir, MCPS_SUBDIR, sanitizedId),
        tools: [],
        resources: data.resources,
        prompts: data.prompts,
        instructions: data.instructions,
        status: data.status,
      });
    }

    for (const tool of tools) {
      let serverData = serverDataMap.get(tool.clientKey);
      if (!serverData) {
        const sanitizedId = sanitizeServerName(tool.clientKey);
        serverData = {
          serverIdentifier: tool.clientKey,
          serverName: tool.providerIdentifier,
          plugin: tool.plugin,
          marketplace: tool.marketplace,
          pluginId: tool.pluginId,
          marketplaceId: tool.marketplaceId,
          sanitizedId,
          folderPath: join(this.projectDir, MCPS_SUBDIR, sanitizedId),
          tools: [],
          resources: [],
          prompts: [],
          instructions: undefined,
          status: undefined,
        };
        serverDataMap.set(tool.clientKey, serverData);
      }
      serverData.tools.push(tool);
    }

    for (const [key, serverData] of serverDataMap) {
      if (serverData.tools.length === 0) {
        const fallbackTools = clientToolsByKey.get(key);
        if (fallbackTools && fallbackTools.length > 0) {
          const enabledToolNames = enabledToolsByServer?.[key];
          const filteredFallbackTools =
            enabledToolNames !== undefined
              ? fallbackTools.filter(tool =>
                  enabledToolNames.includes(tool.toolName)
                )
              : fallbackTools;

          if (
            enabledToolNames !== undefined &&
            filteredFallbackTools.length === 0
          ) {
            logger.info(
              ctx,
              `Skipping direct client tool fallback for "${key}": settings report 0 enabled tools`
            );
            continue;
          }

          logger.info(
            ctx,
            `Using direct client tool fallback for "${key}": lease had 0 tools, client has ${fallbackTools.length}, writing ${filteredFallbackTools.length}`
          );
          serverData.tools = filteredFallbackTools;
        }
      }
    }

    if (instructions !== undefined) {
      for (const instruction of instructions) {
        const instructionIdentifier = instruction.serverIdentifier?.trim();
        let serverData = instructionIdentifier
          ? Array.from(serverDataMap.values()).find(
              s => s.serverIdentifier === instructionIdentifier
            )
          : undefined;
        if (!serverData) {
          const instructionServerName = instruction.serverName?.trim();
          serverData = instructionServerName
            ? Array.from(serverDataMap.values()).find(
                s => s.serverName === instructionServerName
              )
            : undefined;
        }
        if (!serverData) {
          continue;
        }
        if (instruction.instructions) {
          serverData.instructions = instruction.instructions;
        }
      }
    }

    if (this.exposeVirtualMcpAuthTool) {
      for (const server of serverDataMap.values()) {
        if (
          !this.shouldExposeVirtualMcpAuthToolForStatus(
            server.serverIdentifier,
            server.status
          )
        ) {
          continue;
        }
        const hasAuthTool = server.tools.some(
          tool => tool.toolName === MCP_AUTH_TOOL_NAME
        );
        if (!hasAuthTool) {
          server.tools.push(
            createVirtualMcpAuthToolDefinition({
              serverIdentifier: server.serverIdentifier,
              serverName: server.serverName,
              plugin: server.plugin,
              marketplace: server.marketplace,
              pluginId: server.pluginId,
              marketplaceId: server.marketplaceId,
              authToolDescription: this.getMcpAuthToolDescription(),
            })
          );
        }
      }
    }

    return serverDataMap;
  }

  private buildServersToWrite(
    ctx: Context,
    serverDataMap: Map<string, McpServerData>
  ): McpServerData[] {
    const serversToWrite: McpServerData[] = [];
    const seenSanitizedIds = new Set<string>();
    for (const server of serverDataMap.values()) {
      const hasContent =
        server.tools.length > 0 ||
        server.resources.length > 0 ||
        server.prompts.length > 0 ||
        server.instructions;
      const shouldWriteEmptyState =
        server.status === "error" ||
        server.status === "needsAuth" ||
        server.status === "initializing";
      if (!hasContent && !shouldWriteEmptyState) {
        logger.info(
          ctx,
          `Server "${server.serverIdentifier}" excluded from write: tools=${server.tools.length}, resources=${server.resources.length}, prompts=${server.prompts.length}, hasInstructions=${!!server.instructions}, status=${server.status}`
        );
        continue;
      }
      if (seenSanitizedIds.has(server.sanitizedId)) {
        logger.warn(
          ctx,
          `Skipping server "${server.serverIdentifier}" — sanitizedId "${server.sanitizedId}" collides with another server`
        );
        continue;
      }
      seenSanitizedIds.add(server.sanitizedId);
      serversToWrite.push(server);
    }
    return serversToWrite;
  }

  private mergeScopedRefreshWithCachedServerData(
    cachedServerData: McpServerData,
    refreshedServerData: McpServerData
  ): McpServerData {
    const tools = [...refreshedServerData.tools];
    if (
      this.shouldExposeVirtualMcpAuthToolForStatus(
        cachedServerData.serverIdentifier,
        cachedServerData.status
      ) &&
      !tools.some(tool => tool.toolName === MCP_AUTH_TOOL_NAME)
    ) {
      const cachedAuthTool = cachedServerData.tools.find(
        tool => tool.toolName === MCP_AUTH_TOOL_NAME
      );
      if (cachedAuthTool !== undefined) {
        tools.push(cachedAuthTool);
      }
    }

    return {
      ...cachedServerData,
      ...refreshedServerData,
      tools,
      resources: cachedServerData.resources,
      prompts: cachedServerData.prompts,
      instructions: cachedServerData.instructions,
      status: cachedServerData.status,
      plugin: refreshedServerData.plugin ?? cachedServerData.plugin,
      marketplace:
        refreshedServerData.marketplace ?? cachedServerData.marketplace,
      pluginId: refreshedServerData.pluginId ?? cachedServerData.pluginId,
      marketplaceId:
        refreshedServerData.marketplaceId ?? cachedServerData.marketplaceId,
    };
  }

  private async refreshServersFromLease(
    ctx: Context,
    leaseChangeEvent: McpLeaseChangeEvent
  ): Promise<void> {
    const logCtx = this.getLogContext(ctx);
    const uniqueServerIdentifiers = [
      ...new Set(leaseChangeEvent.serverIdentifiers ?? []),
    ];

    logger.info(
      logCtx,
      `fetchAndWrite: refreshing ${uniqueServerIdentifiers.length} targeted servers`,
      {
        serverIdentifiers: uniqueServerIdentifiers,
      }
    );

    const tools = await this.getToolsForServers(ctx, uniqueServerIdentifiers);

    const instructions = await this.mcpLease.getInstructions(ctx).catch(err => {
      logger.warn(
        logCtx,
        `getInstructions() threw during scoped refresh, defaulting to []: ${err}`
      );
      return [];
    });

    const clientLookups = await Promise.all(
      uniqueServerIdentifiers.map(async serverIdentifier => {
        try {
          const client = await this.mcpLease.getClient(ctx, serverIdentifier);
          if (client === undefined) {
            return {
              serverIdentifier,
              kind: "missing",
            } satisfies ScopedRefreshClientLookup;
          }
          return {
            serverIdentifier,
            kind: "client",
            client,
          } satisfies ScopedRefreshClientLookup;
        } catch (error) {
          logger.warn(
            logCtx,
            `getClient("${serverIdentifier}") threw during scoped refresh, preserving cached data: ${error}`
          );
          return {
            serverIdentifier,
            kind: "error",
            error,
          } satisfies ScopedRefreshClientLookup;
        }
      })
    );

    const missingServerIdentifiers = clientLookups
      .filter(
        (
          lookup
        ): lookup is Extract<ScopedRefreshClientLookup, { kind: "missing" }> =>
          lookup.kind === "missing"
      )
      .map(lookup => lookup.serverIdentifier);

    let confirmedMissingServerIdentifiers = new Set<string>();
    if (missingServerIdentifiers.length > 0) {
      const allClients = await this.mcpLease.getClients(ctx).catch(err => {
        logger.warn(
          logCtx,
          `getClients() threw while confirming targeted server removal, preserving cached data: ${err}`
        );
        return undefined;
      });
      if (allClients !== undefined) {
        confirmedMissingServerIdentifiers = new Set(
          missingServerIdentifiers.filter(
            serverIdentifier => allClients[serverIdentifier] === undefined
          )
        );
      }
    }

    const [clientData, enabledToolsByServer] = await Promise.all([
      Promise.all(
        clientLookups
          .filter(
            (
              lookup
            ): lookup is Extract<
              ScopedRefreshClientLookup,
              { kind: "client" }
            > => lookup.kind === "client"
          )
          .map(({ serverIdentifier, client }) =>
            this.fetchClientDataForServer(ctx, serverIdentifier, client, {
              fetchInstructions: true,
            })
          )
      ),
      this.getEnabledToolsByServer(ctx),
    ]);

    const nextServerDataMap = new Map(
      (this.cachedServerData ?? []).map(
        server => [server.serverIdentifier, server] as const
      )
    );
    const refreshedServerDataMap = this.buildServerDataMap(
      ctx,
      tools,
      clientData,
      enabledToolsByServer,
      instructions
    );
    const targetedSet = new Set(uniqueServerIdentifiers);
    const transientlyUnavailableServerIdentifiers = new Set(
      clientLookups
        .filter(lookup => {
          if (lookup.kind === "error") {
            return true;
          }
          return (
            lookup.kind === "missing" &&
            !confirmedMissingServerIdentifiers.has(lookup.serverIdentifier)
          );
        })
        .map(lookup => lookup.serverIdentifier)
    );
    for (const serverIdentifier of uniqueServerIdentifiers) {
      const cachedServerData = nextServerDataMap.get(serverIdentifier);
      const refreshedServerData = refreshedServerDataMap.get(serverIdentifier);
      if (refreshedServerData !== undefined) {
        if (
          transientlyUnavailableServerIdentifiers.has(serverIdentifier) &&
          cachedServerData !== undefined
        ) {
          nextServerDataMap.set(
            serverIdentifier,
            this.mergeScopedRefreshWithCachedServerData(
              cachedServerData,
              refreshedServerData
            )
          );
          logger.warn(
            logCtx,
            `refreshServersFromLease: preserving cached metadata for "${serverIdentifier}" because the client was unavailable during targeted refresh`
          );
          continue;
        }
        nextServerDataMap.set(serverIdentifier, refreshedServerData);
        continue;
      }
      if (confirmedMissingServerIdentifiers.has(serverIdentifier)) {
        nextServerDataMap.delete(serverIdentifier);
        continue;
      }
      logger.warn(
        logCtx,
        `refreshServersFromLease: preserving cached data for "${serverIdentifier}" because targeted refresh returned no replacement`
      );
    }

    const leaseSanitizedIdMap = new Map(
      Array.from(nextServerDataMap.values()).map(
        server => [server.sanitizedId, server.serverIdentifier] as const
      )
    );
    for (const [id, fp] of this.cachedFingerprints) {
      if (!targetedSet.has(id) && !nextServerDataMap.has(id)) {
        const sanitizedId = sanitizeServerName(id);
        leaseSanitizedIdMap.set(sanitizedId, id);
      }
    }
    const serversToWrite = this.buildServersToWrite(ctx, nextServerDataMap);
    await this.writeServerData(ctx, serversToWrite, leaseSanitizedIdMap);
    this.cachedServerData = serversToWrite;
    this.fireOnDidWrite(serversToWrite);
  }

  /**
   * Fetches MCP state from the lease and writes to disk.
   * All data is fetched directly from the ObservableMcpLease.
   */
  private async fetchAndWrite(
    ctx: Context,
    leaseChangeEvent?: McpLeaseChangeEvent
  ): Promise<void> {
    using _span = createSpan(ctx.withName("McpFileSystemWriter.fetchAndWrite"));
    const logCtx = this.getLogContext(ctx);

    try {
      if (
        this.cachedServerData !== undefined &&
        leaseChangeEvent !== undefined &&
        !isFullMcpLeaseInvalidation(leaseChangeEvent)
      ) {
        const targetedServerIdentifiers = [
          ...new Set(leaseChangeEvent.serverIdentifiers ?? []),
        ];
        if (targetedServerIdentifiers.length > 0) {
          await this.refreshServersFromLease(ctx, leaseChangeEvent);
          return;
        }
      }

      const [tools, instructions, clients, enabledToolsByServer] =
        await Promise.all([
          this.mcpLease.getTools(ctx).catch(err => {
            logger.warn(logCtx, `getTools() threw, defaulting to []: ${err}`);
            return [];
          }),
          this.mcpLease.getInstructions(ctx).catch(() => []),
          this.mcpLease.getClients(ctx).catch(err => {
            logger.warn(logCtx, `getClients() threw, defaulting to {}: ${err}`);
            return {};
          }),
          this.getEnabledToolsByServer(ctx),
        ]);

      const clientKeys = Object.keys(clients);
      logger.info(
        logCtx,
        `fetchAndWrite: lease returned ${tools.length} tools across ${clientKeys.length} clients`
      );

      const clientEntries = Object.entries(clients);
      const clientDataPromises = clientEntries.map(([clientKey, client]) =>
        this.fetchClientDataForServer(ctx, clientKey, client)
      );

      const clientData = await Promise.all(clientDataPromises);
      const serverDataMap = this.buildServerDataMap(
        ctx,
        tools,
        clientData,
        enabledToolsByServer,
        instructions
      );
      const serversToWrite = this.buildServersToWrite(ctx, serverDataMap);

      const leaseSanitizedIdMap = new Map(
        Array.from(serverDataMap.values()).map(
          s => [s.sanitizedId, s.serverIdentifier] as const
        )
      );

      await this.writeServerData(ctx, serversToWrite, leaseSanitizedIdMap);
      this.cachedServerData = serversToWrite;
      this.fireOnDidWrite(serversToWrite);
    } catch (error) {
      logger.error(logCtx, "Error fetching/writing MCP state", error);
    }
  }

  private fireOnDidWrite(servers: McpServerData[]): void {
    if (!this.onDidWrite) {
      return;
    }
    try {
      const descriptors: McpFileSystemDescriptor[] = servers.map(server => ({
        serverIdentifier: server.serverIdentifier,
        folderPath: server.folderPath,
        tools: server.tools.map(tool => ({
          toolName: tool.toolName,
          definitionPath: join(
            server.folderPath,
            MCP_TOOLS_SUBDIR,
            `${sanitizeFileName(tool.toolName)}.json`
          ),
        })),
      }));
      this.onDidWrite(descriptors);
    } catch {
      // Fire-and-forget — don't let callback errors break the write loop
    }
  }

  private async writeServerData(
    ctx: Context,
    servers: McpServerData[],
    leaseSanitizedIdMap: Map<string, string>
  ): Promise<void> {
    using _span = createSpan(
      ctx.withName("McpFileSystemWriter.writeServerData")
    );
    const logCtx = this.getLogContext(ctx);
    const mcpsPath = join(this.projectDir, MCPS_SUBDIR);
    await mkdir(mcpsPath, { recursive: true });

    const newFingerprints = new Map<string, string>();
    for (const server of servers) {
      try {
        newFingerprints.set(server.serverIdentifier, serverFingerprint(server));
      } catch (error) {
        logger.error(
          logCtx,
          "Error computing server fingerprint, will force write",
          error,
          {
            serverIdentifier: server.serverIdentifier,
          }
        );
        // Use a unique value so this server is always treated as changed
        newFingerprints.set(
          server.serverIdentifier,
          `__error_${Date.now()}_${Math.random()}`
        );
      }
    }

    const toWrite: McpServerData[] = [];
    for (const server of servers) {
      const oldFp = this.cachedFingerprints.get(server.serverIdentifier);
      const newFp = newFingerprints.get(server.serverIdentifier)!;
      if (oldFp !== newFp) {
        toWrite.push(server);
        if (oldFp !== undefined) {
          logger.info(
            logCtx,
            `Server "${server.serverIdentifier}" fingerprint changed: tools=${server.tools.length}, status=${server.status}`
          );
        }
      }
    }

    for (const server of servers) {
      if (toWrite.includes(server)) {
        continue;
      }
      try {
        await stat(join(mcpsPath, server.sanitizedId));
      } catch {
        logger.info(
          logCtx,
          `Server "${server.serverIdentifier}" directory missing on disk, forcing write`
        );
        toWrite.push(server);
      }
    }

    const toRemove = new Set<string>();
    for (const [id] of this.cachedFingerprints) {
      if (!newFingerprints.has(id)) {
        // Look up from cached data, falling back to sanitizeServerName() in
        // case the entry was already dropped from cachedServerData.
        const old = this.cachedServerData?.find(s => s.serverIdentifier === id);
        const sanitizedId = old?.sanitizedId ?? sanitizeServerName(id);
        if (!leaseSanitizedIdMap.has(sanitizedId)) {
          logger.info(
            logCtx,
            `Server "${id}" (sanitized="${sanitizedId}") left the lease, scheduling directory removal`
          );
          toRemove.add(sanitizedId);
        } else {
          // Server is still in the lease but temporarily has no content.
          // Carry forward its fingerprint so we can properly clean up its
          // directory if it later leaves the lease entirely.
          logger.info(
            logCtx,
            `Server "${id}" (sanitized="${sanitizedId}") still in lease but excluded from write, preserving directory`
          );
          newFingerprints.set(id, this.cachedFingerprints.get(id)!);
        }
      }
    }

    if (this.cachedServerData === undefined) {
      try {
        const existingEntries = await readdir(mcpsPath);
        const liveEntries = new Set(
          existingEntries.filter(
            e => !e.endsWith(STAGING_SUFFIX) && !e.endsWith(PREV_SUFFIX)
          )
        );

        for (const entry of existingEntries) {
          if (entry.endsWith(STAGING_SUFFIX)) {
            await rm(join(mcpsPath, entry), { recursive: true, force: true });
          } else if (entry.endsWith(PREV_SUFFIX)) {
            const liveName = entry.slice(0, -PREV_SUFFIX.length);
            if (!liveEntries.has(liveName)) {
              try {
                await rename(join(mcpsPath, entry), join(mcpsPath, liveName));
                liveEntries.add(liveName);
              } catch {
                await rm(join(mcpsPath, entry), {
                  recursive: true,
                  force: true,
                }).catch(() => {});
              }
            } else {
              await rm(join(mcpsPath, entry), { recursive: true, force: true });
            }
          }
        }

        for (const liveEntry of liveEntries) {
          if (!leaseSanitizedIdMap.has(liveEntry)) {
            toRemove.add(liveEntry);
          } else {
            // Ensure preserved directories are tracked in fingerprints so
            // they can be cleaned up if the server later leaves the lease.
            const serverIdentifier = leaseSanitizedIdMap.get(liveEntry)!;
            if (!newFingerprints.has(serverIdentifier)) {
              newFingerprints.set(serverIdentifier, `__preserved_${liveEntry}`);
            }
          }
        }
      } catch (error) {
        logger.error(logCtx, "Error clearing mcps directory", error);
      }
    }

    const toRemoveIds = Array.from(toRemove);
    if (toWrite.length > 0 || toRemove.size > 0) {
      const changedServers = toWrite.map(server => ({
        serverIdentifier: server.serverIdentifier,
        sanitizedId: server.sanitizedId,
        toolCount: server.tools.length,
      }));
      logger.info(
        logCtx,
        `Incremental write: ${toWrite.length} changed, ${toRemove.size} removed, ${servers.length - toWrite.length} unchanged`,
        {
          changedServerCount: toWrite.length,
          changedServers,
          removedServerCount: toRemove.size,
          removedServerSanitizedIds: toRemoveIds,
          unchangedServerCount: servers.length - toWrite.length,
          totalServerCount: servers.length,
        },
        {
          includeStructuredLogs: true,
        }
      );
    }

    const writeResults = await Promise.allSettled(
      toWrite.map(server => this.writeServerAtomic(ctx, server, mcpsPath))
    );

    for (let i = 0; i < toWrite.length; i++) {
      const result = writeResults[i]!;
      if (result.status === "rejected") {
        const server = toWrite[i]!;
        // Keep the old fingerprint so this server is retried on the next write
        const oldFp = this.cachedFingerprints.get(server.serverIdentifier);
        if (oldFp !== undefined) {
          newFingerprints.set(server.serverIdentifier, oldFp);
        } else {
          newFingerprints.delete(server.serverIdentifier);
        }
        logger.error(
          ctx,
          "Error writing server directory",
          result.reason,
          {
            serverIdentifier: server.serverIdentifier,
            sanitizedId: server.sanitizedId,
          },
          {
            includeStructuredLogs: true,
          }
        );
      }
    }
    const removalResults = await Promise.allSettled(
      toRemoveIds.map(sanitizedId =>
        rm(join(mcpsPath, sanitizedId), { recursive: true, force: true })
      )
    );
    for (let i = 0; i < removalResults.length; i++) {
      const removalResult = removalResults[i]!;
      if (removalResult.status === "rejected") {
        const sanitizedId = toRemoveIds[i]!;
        logger.error(
          ctx,
          "Error removing server directory",
          removalResult.reason,
          {
            sanitizedId,
            removalIndex: i,
            removalAttemptCount: removalResults.length,
            removedServerCount: toRemoveIds.length,
            removedServerSanitizedIds: toRemoveIds,
            changedServerCount: toWrite.length,
            unchangedServerCount: servers.length - toWrite.length,
            totalServerCount: servers.length,
          },
          { includeStructuredLogs: true }
        );
      }
    }

    this.cachedFingerprints = newFingerprints;
  }

  private async writeServerAtomic(
    ctx: Context,
    server: McpServerData,
    mcpsPath: string
  ): Promise<void> {
    using _span = createSpan(
      ctx.withName("McpFileSystemWriter.writeServerAtomic")
    );
    const stagingName = `${server.sanitizedId}${STAGING_SUFFIX}`;
    const prevName = `${server.sanitizedId}${PREV_SUFFIX}`;
    const stagingDir = join(mcpsPath, stagingName);
    const prevDir = join(mcpsPath, prevName);
    const liveDir = join(mcpsPath, server.sanitizedId);

    await rm(stagingDir, { recursive: true, force: true });

    try {
      await rename(prevDir, liveDir);
    } catch {
      await rm(prevDir, { recursive: true, force: true });
    }

    await this.writeServerDirectory(ctx, server, {
      basePath: mcpsPath,
      dirName: stagingName,
    });

    try {
      try {
        await rename(liveDir, prevDir);
      } catch {
        // liveDir may not exist on first write
      }
      await rename(stagingDir, liveDir);
    } catch (error) {
      logger.error(
        ctx,
        "Per-server swap failed",
        error,
        {
          serverIdentifier: server.serverIdentifier,
          sanitizedId: server.sanitizedId,
        },
        {
          includeStructuredLogs: true,
        }
      );
      try {
        await rename(prevDir, liveDir);
      } catch {
        // best effort rollback
      }
      await rm(stagingDir, { recursive: true, force: true });
      throw error;
    }

    await rm(prevDir, { recursive: true, force: true }).catch(() => {});
  }

  private async writeServerDirectory(
    ctx: Context,
    server: McpServerData,
    opts: { basePath: string; dirName?: string }
  ): Promise<void> {
    using _span = createSpan(
      ctx.withName("McpFileSystemWriter.writeServerDirectory")
    );
    const serverDir = join(opts.basePath, opts.dirName ?? server.sanitizedId);
    await mkdir(serverDir, { recursive: true });

    if (server.tools.length > 0) {
      const toolsDir = join(serverDir, MCP_TOOLS_SUBDIR);
      await mkdir(toolsDir, { recursive: true });

      for (const tool of server.tools) {
        const safeToolName = sanitizeFileName(tool.toolName);
        const toolPath = join(toolsDir, `${safeToolName}.json`);
        const content = buildMcpToolFileContent(tool);
        await writeFile(toolPath, JSON.stringify(content, null, 2));
      }
    }

    if (server.resources.length > 0) {
      const resourcesDir = join(serverDir, MCP_RESOURCES_SUBDIR);
      await mkdir(resourcesDir, { recursive: true });

      for (const resource of server.resources) {
        const resourceName =
          resource.name || resource.uri.replace(/[^a-zA-Z0-9_-]/g, "_");
        const safeResourceName = sanitizeFileName(resourceName);
        const resourcePath = join(resourcesDir, `${safeResourceName}.json`);
        const content = {
          uri: resource.uri,
          name: resource.name,
          description: resource.description,
          mimeType: resource.mimeType,
        };
        await writeFile(resourcePath, JSON.stringify(content, null, 2));
      }
    }

    if (server.prompts.length > 0) {
      const promptsDir = join(serverDir, MCP_PROMPTS_SUBDIR);
      await mkdir(promptsDir, { recursive: true });

      for (const prompt of server.prompts) {
        const safePromptName = sanitizeFileName(prompt.name);
        const promptPath = join(promptsDir, `${safePromptName}.json`);
        const content = {
          name: prompt.name,
          description: prompt.description,
          arguments: prompt.arguments,
        };
        await writeFile(promptPath, JSON.stringify(content, null, 2));
      }
    }

    if (server.instructions && server.instructions.trim().length > 0) {
      const instructionsPath = join(serverDir, INSTRUCTIONS_FILENAME);
      await writeFile(instructionsPath, server.instructions.trim());
    }

    if (server.status === "error" || server.status === "needsAuth") {
      const statusPath = join(serverDir, STATUS_FILENAME);
      const statusMessage =
        server.status === "error"
          ? this.getErrorStatusMessage()
          : this.getNeedsAuthStatusMessageForWrite(server.serverIdentifier);
      await writeFile(statusPath, statusMessage);
    }

    const metadataPath = join(serverDir, SERVER_METADATA_FILENAME);
    const metadataContent = {
      serverIdentifier: server.serverIdentifier,
      serverName: server.serverName,
    };
    await writeFile(metadataPath, JSON.stringify(metadataContent, null, 2));
  }

  /**
   * Returns McpFileSystemOptions built from the in-memory cached state.
   * This ensures the options match exactly what was written to disk.
   */
  async getMcpFileSystemOptions(
    ctx: Context,
    options?: { timeoutMs?: number }
  ): Promise<McpFileSystemOptions | undefined> {
    if (this.disposed) {
      return undefined;
    }

    using _span = createSpan(
      ctx.withName("McpFileSystemWriter.getMcpFileSystemOptions")
    );
    const logCtx = this.getLogContext(ctx);

    const writeTimedOut = await this.ensureWritesSettled(
      ctx,
      options?.timeoutMs
    );

    if (this.snapshotProvider && !writeTimedOut) {
      return this.buildOptionsFromSnapshots(ctx);
    }
    if (this.snapshotProvider && writeTimedOut) {
      logger.warn(
        logCtx,
        "Snapshot mode write barrier timed out; falling back to cached descriptors",
        {
          timeoutMs: options?.timeoutMs,
        },
        {
          includeStructuredLogs: true,
        }
      );
    }

    const servers = this.cachedServerData ?? [];

    const mcpDescriptors: McpDescriptor[] = servers.map(server => {
      const tools: McpToolDescriptor[] = server.tools.map(tool => {
        const safeToolName = sanitizeFileName(tool.toolName);
        const toolFilePath = join(
          server.folderPath,
          MCP_TOOLS_SUBDIR,
          `${safeToolName}.json`
        );
        return new McpToolDescriptor({
          toolName: tool.toolName,
          definitionPath: toolFilePath,
          // Annotations are tiny and behavior-relevant (e.g. steer-aware
          // release gates on readOnlyHint), so they ride the descriptor
          // instead of only the definition file.
          ...toolAnnotationsJsonField(tool.annotations),
        });
      });

      return new McpDescriptor({
        serverIdentifier: server.serverIdentifier,
        serverName: server.serverName,
        plugin: server.plugin,
        marketplace: server.marketplace,
        pluginDbId: server.pluginId,
        marketplaceId: server.marketplaceId,
        folderPath: server.folderPath,
        serverUseInstructions: server.instructions,
        tools,
      });
    });

    // Fire-and-forget divergence check (rate-limited to once per 10s)
    // Detects "green UI but no tools" silent failures
    this.checkDescriptorsVsFilesystem(ctx, mcpDescriptors, "workbench_lease");

    return new McpFileSystemOptions({
      enabled: true,
      workspaceProjectDir: this.projectDir,
      mcpDescriptors,
    });
  }

  private async ensureWritesSettled(
    ctx: Context,
    timeoutMs: number | undefined
  ): Promise<boolean> {
    const logCtx = this.getLogContext(ctx);
    const hadPendingDebounce = this.debounceTimer !== undefined;
    if (this.debounceTimer !== undefined) {
      clearTimeout(this.debounceTimer);
      this.debounceTimer = undefined;
      this.scheduleWrite(ctx, this.takePendingLeaseChangeEvent());
    }
    if (hadPendingDebounce) {
      logger.info(
        logCtx,
        "getMcpFileSystemOptions force-fired pending debounce"
      );
    }

    if (!this.writePromise) {
      return false;
    }

    if (timeoutMs !== undefined) {
      let timedOut = false;
      let timer: NodeJS.Timeout | undefined;
      try {
        await Promise.race([
          this.writePromise,
          new Promise<void>(resolve => {
            timer = setTimeout(() => {
              timedOut = true;
              resolve();
            }, timeoutMs);
          }),
        ]);
      } catch (error) {
        logger.error(
          logCtx,
          "Error waiting for pending write to complete",
          error
        );
      } finally {
        clearTimeout(timer);
      }
      if (timedOut) {
        logger.warn(
          logCtx,
          `getMcpFileSystemOptions timed out after ${timeoutMs}ms waiting for write; returning stale cache`
        );
      }
      return timedOut;
    }

    try {
      await this.writePromise;
    } catch (error) {
      logger.error(
        logCtx,
        "Error waiting for pending write to complete",
        error
      );
    }
    return false;
  }

  private async buildOptionsFromSnapshots(
    ctx: Context
  ): Promise<McpFileSystemOptions> {
    using _span = createSpan(
      ctx.withName("McpFileSystemWriter.buildOptionsFromSnapshots")
    );
    const logCtx = this.getLogContext(ctx);
    const startMs = Date.now();
    const snapshots = await this.snapshotProvider!.getAllSnapshots(ctx);
    const mcpDir = join(this.projectDir, MCPS_SUBDIR);

    const mcpDescriptors: McpDescriptor[] = snapshots
      .filter(
        s =>
          s.tools.length > 0 ||
          s.resources.length > 0 ||
          s.prompts.length > 0 ||
          s.instructions !== undefined ||
          this.shouldExposeVirtualMcpAuthToolForStatus(
            s.serverIdentifier,
            s.status
          ) ||
          s.status === "needsAuth" ||
          s.status === "error"
      )
      .map(snapshot => {
        const sanitizedId = sanitizeServerName(snapshot.serverIdentifier);
        const folderPath = join(mcpDir, sanitizedId);
        const tools = snapshot.tools.map(tool => {
          const safeToolName = sanitizeFileName(tool.name);
          return new McpToolDescriptor({
            toolName: tool.name,
            definitionPath: join(
              folderPath,
              MCP_TOOLS_SUBDIR,
              `${safeToolName}.json`
            ),
            // Annotations are tiny and behavior-relevant (e.g. steer-aware
            // release gates on readOnlyHint), so they ride the descriptor
            // instead of only the definition file.
            ...toolAnnotationsJsonField(tool.annotations),
          });
        });

        if (
          this.shouldExposeVirtualMcpAuthToolForStatus(
            snapshot.serverIdentifier,
            snapshot.status
          ) &&
          !snapshot.tools.some(t => t.name === MCP_AUTH_TOOL_NAME)
        ) {
          const safeToolName = sanitizeFileName(MCP_AUTH_TOOL_NAME);
          tools.push(
            new McpToolDescriptor({
              toolName: MCP_AUTH_TOOL_NAME,
              definitionPath: join(
                folderPath,
                MCP_TOOLS_SUBDIR,
                `${safeToolName}.json`
              ),
            })
          );
        }

        return new McpDescriptor({
          serverIdentifier: snapshot.serverIdentifier,
          serverName: snapshot.serverName,
          plugin: snapshot.plugin,
          marketplace: snapshot.marketplace,
          pluginDbId: snapshot.pluginId,
          marketplaceId: snapshot.marketplaceId,
          folderPath,
          serverUseInstructions: snapshot.instructions,
          tools,
        });
      });

    const totalToolCount = mcpDescriptors.reduce(
      (sum, d) => sum + d.tools.length,
      0
    );
    logger.info(
      logCtx,
      `buildOptionsFromSnapshots completed in ${Date.now() - startMs}ms: ${snapshots.length} snapshots, ${mcpDescriptors.length} descriptors, ${totalToolCount} tools`
    );

    // Fire-and-forget divergence check (rate-limited to once per 10s)
    // Detects divergence between snapshot state and filesystem state
    this.checkDescriptorsVsFilesystem(ctx, mcpDescriptors, "snapshot");

    return new McpFileSystemOptions({
      enabled: true,
      workspaceProjectDir: this.projectDir,
      mcpDescriptors,
    });
  }

  /**
   * Wait for any pending write operation to complete.
   * Useful for testing to ensure files are written before assertions.
   */
  async waitForPendingWrites(): Promise<void> {
    if (this.debounceTimer !== undefined) {
      await new Promise<void>(resolve => {
        const checkTimer = (): void => {
          if (this.debounceTimer === undefined) {
            resolve();
          } else {
            setTimeout(checkTimer, 10);
          }
        };
        checkTimer();
      });
    }

    if (this.writePromise) {
      try {
        await this.writePromise;
      } catch {
        // Write errors are non-fatal
      }
    }
  }

  /** For testing. */
  getCachedServerData(): McpServerData[] | undefined {
    return this.cachedServerData;
  }

  /** Cooldown period between divergence checks (10 seconds) */
  private static readonly DIVERGENCE_CHECK_COOLDOWN_MS = 10_000;

  /** Last time we ran a divergence check */
  private lastDivergenceCheckMs: number = 0;

  /**
   * Fire-and-forget divergence check between expected state (from lease/snapshot) and filesystem.
   * Rate-limited to once per DIVERGENCE_CHECK_COOLDOWN_MS to avoid thrash.
   *
   * This detects "silent failures" where the UI shows MCP as connected but
   * tools weren't written to disk (SEV-472, SEV-636 pattern).
   *
   * @param descriptors - The MCP descriptors representing expected state
   * @param source - Which system produced the descriptors (for metrics)
   */
  private checkDescriptorsVsFilesystem(
    ctx: Context,
    descriptors: readonly McpDescriptor[],
    source: McpSource
  ): void {
    const logCtx = this.getLogContext(ctx);
    const now = Date.now();
    if (
      now - this.lastDivergenceCheckMs <
      McpFileSystemWriter.DIVERGENCE_CHECK_COOLDOWN_MS
    ) {
      return;
    }
    this.lastDivergenceCheckMs = now;

    void this._checkDescriptorsVsFilesystemAsync(
      ctx,
      descriptors,
      source
    ).catch(err => {
      logger.warn(logCtx, "Divergence check failed", err);
    });
  }

  private async _checkDescriptorsVsFilesystemAsync(
    ctx: Context,
    descriptors: readonly McpDescriptor[],
    source: McpSource
  ): Promise<void> {
    const logCtx = this.getLogContext(ctx);
    const mcpsPath = join(this.projectDir, MCPS_SUBDIR);

    // Derive expected state from descriptors
    const expectedServerIds = new Set<string>();
    const expectedToolCounts = new Map<string, number>();
    for (const descriptor of descriptors) {
      const sanitizedId = sanitizeServerName(descriptor.serverIdentifier);
      expectedServerIds.add(sanitizedId);
      expectedToolCounts.set(sanitizedId, descriptor.tools.length);
    }

    let actualDirs: string[] = [];
    try {
      actualDirs = await readdir(mcpsPath);
      actualDirs = actualDirs.filter(
        d => !d.endsWith(STAGING_SUFFIX) && !d.endsWith(PREV_SUFFIX)
      );
    } catch (err) {
      if ((err as NodeJS.ErrnoException)?.code !== "ENOENT") {
        throw err;
      }
    }
    const actualServerIds = new Set(actualDirs);

    let synced = true;
    let serversMissing = 0;
    let serversStale = 0;
    let toolMismatches = 0;
    const serversBucket = configuredServersBucket(expectedServerIds.size);

    for (const expected of expectedServerIds) {
      if (!actualServerIds.has(expected)) {
        synced = false;
        serversMissing++;
        mcpFilesystemDivergence.increment(
          ctx,
          1,
          this.getMetricTags({
            divergence_type: "server_missing",
            mcp_source: source,
            configured_servers: serversBucket,
          })
        );
        logger.warn(
          logCtx,
          "Divergence detected: server missing from filesystem",
          {
            mcpFileSystemMeta: {
              divergenceType: "server_missing",
              serverId: expected,
              source,
              configuredServers: expectedServerIds.size,
              configuredServersBucket: serversBucket,
            },
          },
          { includeStructuredLogs: true }
        );
      }
    }

    for (const actual of actualServerIds) {
      if (!expectedServerIds.has(actual)) {
        synced = false;
        serversStale++;
        mcpFilesystemDivergence.increment(
          ctx,
          1,
          this.getMetricTags({
            divergence_type: "server_stale",
            mcp_source: source,
            configured_servers: serversBucket,
          })
        );
      }
    }

    for (const serverId of expectedServerIds) {
      if (!actualServerIds.has(serverId)) {
        continue;
      }

      const expectedCount = expectedToolCounts.get(serverId) ?? 0;
      const toolsPath = join(mcpsPath, serverId, MCP_TOOLS_SUBDIR);
      let actualCount = 0;
      try {
        const files = await readdir(toolsPath);
        actualCount = files.filter(f => f.endsWith(".json")).length;
      } catch {
        /* tools folder doesn't exist */
      }

      if (actualCount !== expectedCount) {
        synced = false;
        toolMismatches++;
        mcpFilesystemDivergence.increment(
          ctx,
          1,
          this.getMetricTags({
            divergence_type: "tool_count_mismatch",
            mcp_source: source,
            configured_servers: serversBucket,
          })
        );
        logger.warn(
          logCtx,
          "Divergence detected: tool count mismatch",
          {
            mcpFileSystemMeta: {
              divergenceType: "tool_count_mismatch",
              serverId,
              expected: expectedCount,
              actual: actualCount,
              source,
              configuredServers: expectedServerIds.size,
              configuredServersBucket: serversBucket,
            },
          },
          { includeStructuredLogs: true }
        );
      }
    }

    mcpFilesystemSyncCheck.increment(
      ctx,
      1,
      this.getMetricTags({
        synced: String(synced),
        mcp_source: source,
        configured_servers: serversBucket,
      })
    );
    mcpFilesystemSyncExpectedServers.gauge(
      ctx,
      expectedServerIds.size,
      this.getMetricTags({
        mcp_source: source,
      })
    );
    mcpFilesystemSyncActualServers.gauge(
      ctx,
      actualServerIds.size,
      this.getMetricTags({
        mcp_source: source,
      })
    );
    mcpFilesystemSyncServersMissing.gauge(
      ctx,
      serversMissing,
      this.getMetricTags({
        mcp_source: source,
      })
    );
    mcpFilesystemSyncToolMismatches.gauge(
      ctx,
      toolMismatches,
      this.getMetricTags({
        mcp_source: source,
      })
    );

    logger.info(
      logCtx,
      "MCP filesystem sync check",
      {
        mcpFileSystemMeta: {
          synced,
          expectedServers: expectedServerIds.size,
          actualServers: actualServerIds.size,
          serversMissing,
          serversStale,
          toolMismatches,
          source,
          configuredServers: expectedServerIds.size,
          configuredServersBucket: serversBucket,
        },
      },
      { includeStructuredLogs: true }
    );

    if (!synced) {
      logger.warn(
        logCtx,
        "MCP filesystem divergence summary",
        {
          mcpFileSystemMeta: {
            synced,
            expectedServers: expectedServerIds.size,
            actualServers: actualServerIds.size,
            serversMissing,
            serversStale,
            toolMismatches,
            source,
            configuredServers: expectedServerIds.size,
            configuredServersBucket: serversBucket,
          },
        },
        { includeStructuredLogs: true }
      );
    }
  }

  dispose(): void {
    if (this.disposed) {
      return;
    }
    this.disposed = true;

    if (this.debounceTimer !== undefined) {
      clearTimeout(this.debounceTimer);
      this.debounceTimer = undefined;
    }

    if (this.leaseChangeDisposable) {
      this.leaseChangeDisposable.dispose();
      this.leaseChangeDisposable = undefined;
    }

    this.cachedServerData = undefined;
    this.cachedFingerprints.clear();
  }
}
