import { SimpleControlledExecHandler } from "./controlled.js";
import { ExecutorResource } from "./remote.js";
import { createResource } from "./resource-provider.js";
import { createClientDeserializer, createClientSerializer, createServerDeserializer, createServerSerializer, } from "./serialization.js";
export const agentStoreConflictExecutorResource = createResource(execManager => new ExecutorResource(execManager, createServerSerializer("agentStoreConflictArgs"), createClientDeserializer("agentStoreConflictResult")), (implementation, controlledExecManager) => {
    controlledExecManager.register(new SimpleControlledExecHandler(implementation, createServerDeserializer("agentStoreConflictArgs"), createClientSerializer("agentStoreConflictResult")));
});
