import * as crypto from "node:crypto";
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";

/**
 * Directory name under ~/.cursor for ephemeral sandbox policy JSON files.
 *
 * Kept out of CURSOR_ALLOWED_WRITE_SUBDIRS so workspace `.cursor` RO mounts
 * continue to deny sandboxed writes here when the workspace is $HOME.
 *
 * The resolved directory is always injected into `additionalReadonlyPaths` so
 * sandboxed peers cannot rewrite policy JSON — including when `$HOME` (and
 * thus this directory) lives under a temp root.
 */
export const SANDBOX_POLICY_DIR_NAME = "sandbox-policies";

/** Env override for tests and unusual layouts. */
export const SANDBOX_POLICY_DIR_ENV = "CURSOR_SANDBOX_POLICY_DIR";

/**
 * Resolve the directory used for cursorsandbox policy JSON files.
 *
 * Preference order:
 * 1. CURSOR_SANDBOX_POLICY_DIR
 * 2. ~/.cursor/sandbox-policies
 *
 * Callers must inject the resolved directory into additionalReadonlyPaths
 * (see withPolicyDirectoryReadonly) so the sandbox cannot rewrite policies.
 * Do not fall back to a world-writable temp dump of loose policy files —
 * that reintroduces the policy-file TOCTOU class of bugs.
 */
export function getSandboxPolicyDirectory(): string {
  const override = process.env[SANDBOX_POLICY_DIR_ENV]?.trim();
  if (override) {
    return path.resolve(override);
  }

  return path.resolve(
    path.join(os.homedir(), ".cursor", SANDBOX_POLICY_DIR_NAME)
  );
}

const STALE_POLICY_MAX_AGE_MS = 60 * 60 * 1000; // 1 hour

/**
 * Remove abandoned sandbox-policy-* files left behind when a helper is killed
 * before cleanup. Keeps the private directory from growing without bound.
 */
function pruneStaleSandboxPolicyFiles(dir: string): void {
  let entries: string[];
  try {
    entries = fs.readdirSync(dir);
  } catch {
    return;
  }
  const now = Date.now();
  for (const name of entries) {
    if (!name.startsWith("sandbox-policy-")) {
      continue;
    }
    const fullPath = path.join(dir, name);
    try {
      const st = fs.statSync(fullPath);
      if (!st.isFile()) {
        continue;
      }
      if (now - st.mtimeMs > STALE_POLICY_MAX_AGE_MS) {
        fs.unlinkSync(fullPath);
      }
    } catch {
      // Best-effort cleanup.
    }
  }
}

/**
 * Ensure the private policy directory exists with restrictive permissions.
 */
export function ensureSandboxPolicyDirectory(): string {
  const dir = getSandboxPolicyDirectory();
  fs.mkdirSync(dir, { recursive: true, mode: 0o700 });
  try {
    fs.chmodSync(dir, 0o700);
  } catch {
    // Best-effort on platforms that ignore chmod.
  }
  pruneStaleSandboxPolicyFiles(dir);
  return dir;
}

/**
 * Write a sandbox policy JSON string to the private policy directory.
 * Returns the absolute path to the created file.
 */
export function writeSandboxPolicyFile(policyJson: string): string {
  const dir = ensureSandboxPolicyDirectory();
  const suffix = crypto.randomBytes(8).toString("hex");
  const filePath = path.join(dir, `sandbox-policy-${suffix}`);
  fs.writeFileSync(filePath, policyJson, { encoding: "utf-8", mode: 0o600 });
  return filePath;
}
