import { snapshotUrlForLog, type UrlSnapshotForLog } from "./log-metadata.js";
import {
  extractResponseFromFetchError,
  getMcpOAuthErrorLogMetadata,
  hashMcpOAuthValueForLog,
  type McpOAuthErrorLogMetadata,
  sanitizeErrorMessageForLog,
  sanitizeStructuredValueForLog,
} from "./oauth-logging.js";

export interface McpHttpExchangeLogger {
  readonly debug?: (
    message: string,
    metadata?: Record<string, unknown>
  ) => void;
  readonly info?: (message: string, metadata?: Record<string, unknown>) => void;
  readonly warn?: (message: string, metadata?: Record<string, unknown>) => void;
  readonly error?: (
    message: string,
    error?: unknown,
    metadata?: Record<string, unknown>
  ) => void;
}

export type McpHttpUrlSnapshot = UrlSnapshotForLog;

export interface McpHttpRequestSnapshotForLog {
  readonly method: string;
  readonly url: McpHttpUrlSnapshot;
  readonly headers: {
    readonly names: readonly string[];
    readonly count: number;
  };
  readonly contentType: string | null;
  readonly body: {
    readonly kind: "none" | "text" | "binary" | "blob" | "stream" | "unknown";
    readonly bytes: number | null;
    readonly contentLength: number | null;
  };
  readonly sessionIdHash: string | null;
  readonly authorizationScheme: string | null;
}

export interface McpHttpResponseSnapshotForLog {
  readonly status: number | null;
  readonly ok: boolean | null;
  readonly headers: {
    readonly names: readonly string[];
    readonly count: number;
  };
  readonly contentType: string | null;
  readonly body: {
    readonly kind: "none" | "stream";
    readonly bytes: number | null;
    readonly contentLength: number | null;
    readonly errorSummary?: string;
  };
  readonly sessionIdHash: string | null;
  readonly wwwAuthenticateHash: string | null;
  readonly mcpProtocolVersion: string | null;
}

export interface McpHttpErrorSnapshotForLog {
  readonly name?: string;
  readonly message?: string;
  readonly type?: string;
  readonly oauthErrorCode?: string;
  readonly responseSummary?: string;
  readonly networkClassification?: McpOAuthErrorLogMetadata["networkClassification"];
  readonly sdkErrorKind?:
    | "oauth_error"
    | "auth_transport_error"
    | "generic_error";
}

type McpOAuthGrantTypeForLog =
  | "authorization_code"
  | "refresh_token"
  | "client_credentials"
  | "urn:ietf:params:oauth:grant-type:jwt-bearer"
  | "urn:ietf:params:oauth:grant-type:token-exchange"
  | "other";

export interface McpHttpExchangeSuccessMetadata {
  readonly event: "mcp_http_exchange";
  readonly outcome: "success" | "http_error";
  readonly durationMs: number;
  readonly cursorMcp: {
    readonly transport: {
      readonly request: McpHttpRequestSnapshotForLog;
      readonly response: McpHttpResponseSnapshotForLog;
    } & Record<string, unknown>;
  };
}

export interface McpHttpExchangeFailureMetadata {
  readonly event: "mcp_http_exchange";
  readonly outcome: "error";
  readonly durationMs: number;
  readonly cursorMcp: {
    readonly transport: {
      readonly request: McpHttpRequestSnapshotForLog;
      readonly response: McpHttpResponseSnapshotForLog;
      readonly error: McpHttpErrorSnapshotForLog;
    } & Record<string, unknown>;
  };
}

interface ResponseForLog {
  readonly status: number;
  readonly ok: boolean;
  readonly headers: Headers;
  readonly body: unknown | null;
}

export type McpHttpFetchLike = (
  input: string | URL,
  init?: RequestInit
) => Promise<Response>;

export interface LoggedMcpHttpFetchOptions {
  readonly fetch: McpHttpFetchLike;
  readonly logger: McpHttpExchangeLogger;
  readonly metadata?: Record<string, unknown>;
  /**
   * When false, omits info-level logs for successful (2xx) exchanges.
   * Non-2xx "MCP HTTP exchange completed" (warn) and failures are still logged.
   * Defaults to true for non-OAuth MCP transport callers.
   */
  readonly logSuccessfulExchanges?: boolean;
}

interface McpHttpRequestLike {
  readonly url: string;
  readonly method?: string;
  readonly headers?: unknown;
}

type McpHttpRequestInput = string | URL | McpHttpRequestLike;

interface McpHttpRequestInitLike {
  readonly method?: string;
  readonly headers?: unknown;
  readonly body?: unknown;
}

const MAX_RESPONSE_ERROR_SUMMARY_LOG_BYTES = 4096;

export function hashMcpHttpLoggingValueForLog(
  value: string | undefined
): string | undefined {
  return hashMcpOAuthValueForLog(value);
}

function isMcpHttpRequestLike(value: unknown): value is McpHttpRequestLike {
  return (
    typeof value === "object" &&
    value !== null &&
    "url" in value &&
    typeof (value as { url?: unknown }).url === "string"
  );
}

function resolveRequestUrl(input: McpHttpRequestInput): string {
  if (typeof input === "string") {
    return input;
  }
  if (input instanceof URL) {
    return input.toString();
  }
  return input.url;
}

function buildMergedHeaders(
  input: McpHttpRequestInput,
  init: McpHttpRequestInitLike | undefined
): Headers {
  const merged = new Headers(
    (isMcpHttpRequestLike(input) ? input.headers : undefined) as
      | Headers
      | undefined
  );
  const extra = new Headers(init?.headers as Headers | undefined);
  extra.forEach((value, key) => {
    merged.set(key, value);
  });
  return merged;
}

function getHeaderNames(headers: Headers): string[] {
  const names: string[] = [];
  headers.forEach((_value, key) => {
    names.push(key);
  });
  return names.sort();
}

function parseContentLength(value: string | null): number | null {
  if (value === null) {
    return null;
  }
  const parsed = Number.parseInt(value, 10);
  return Number.isNaN(parsed) ? null : parsed;
}

function summarizeBody(
  body: unknown,
  headers: Headers
): McpHttpRequestSnapshotForLog["body"] {
  if (body === undefined || body === null) {
    return {
      kind: "none",
      bytes: 0,
      contentLength: parseContentLength(headers.get("content-length")),
    };
  }

  if (typeof body === "string") {
    const bodyBytes = new TextEncoder().encode(body).length;
    return {
      kind: "text",
      bytes: bodyBytes,
      contentLength:
        parseContentLength(headers.get("content-length")) ?? bodyBytes,
    };
  }

  if (body instanceof URLSearchParams) {
    const serialized = body.toString();
    const bodyBytes = new TextEncoder().encode(serialized).length;
    return {
      kind: "text",
      bytes: bodyBytes,
      contentLength:
        parseContentLength(headers.get("content-length")) ?? bodyBytes,
    };
  }

  if (body instanceof Blob) {
    return {
      kind: "blob",
      bytes: body.size,
      contentLength:
        parseContentLength(headers.get("content-length")) ?? body.size,
    };
  }

  if (body instanceof ArrayBuffer) {
    return {
      kind: "binary",
      bytes: body.byteLength,
      contentLength:
        parseContentLength(headers.get("content-length")) ?? body.byteLength,
    };
  }

  if (ArrayBuffer.isView(body)) {
    return {
      kind: "binary",
      bytes: body.byteLength,
      contentLength:
        parseContentLength(headers.get("content-length")) ?? body.byteLength,
    };
  }

  if (typeof body === "object" && body !== null) {
    if ("getReader" in body || Symbol.asyncIterator in body) {
      return {
        kind: "stream",
        bytes: null,
        contentLength: parseContentLength(headers.get("content-length")),
      };
    }
  }

  return {
    kind: "unknown",
    bytes: null,
    contentLength: parseContentLength(headers.get("content-length")),
  };
}

function extractFormValue(body: string, fieldName: string): string | undefined {
  for (const pair of body.split("&")) {
    const separatorIndex = pair.indexOf("=");
    const rawKey = separatorIndex >= 0 ? pair.slice(0, separatorIndex) : pair;
    let key: string;
    try {
      key = decodeURIComponent(rawKey.replaceAll("+", " "));
    } catch {
      return undefined;
    }
    if (key !== fieldName) {
      continue;
    }
    const rawValue = separatorIndex >= 0 ? pair.slice(separatorIndex + 1) : "";
    try {
      return decodeURIComponent(rawValue.replaceAll("+", " "));
    } catch {
      return undefined;
    }
  }
  return undefined;
}

function sanitizeOAuthGrantTypeForLog(
  grantType: string
): McpOAuthGrantTypeForLog {
  switch (grantType) {
    case "authorization_code":
    case "refresh_token":
    case "client_credentials":
    case "urn:ietf:params:oauth:grant-type:jwt-bearer":
    case "urn:ietf:params:oauth:grant-type:token-exchange":
      return grantType;
    default:
      return "other";
  }
}

function extractOAuthGrantTypeForLog(
  contentType: string | null,
  body: unknown
): McpOAuthGrantTypeForLog | undefined {
  if (
    contentType === null ||
    !contentType.toLowerCase().startsWith("application/x-www-form-urlencoded")
  ) {
    return undefined;
  }
  const grantType =
    typeof body === "string"
      ? extractFormValue(body, "grant_type")
      : body instanceof URLSearchParams
        ? (body.get("grant_type") ?? undefined)
        : undefined;
  return grantType ? sanitizeOAuthGrantTypeForLog(grantType) : undefined;
}

export function buildMcpHttpRequestSnapshotForLog(args: {
  input: McpHttpRequestInput;
  init?: McpHttpRequestInitLike;
}): McpHttpRequestSnapshotForLog {
  const { input, init } = args;
  const requestUrl = resolveRequestUrl(input);
  const urlSnapshot = snapshotUrlForLog(requestUrl);
  const headers = buildMergedHeaders(input, init);
  const headerNames = getHeaderNames(headers);
  const contentType = headers.get("content-type");
  const sessionIdHash = hashMcpOAuthValueForLog(
    headers.get("mcp-session-id") ?? undefined
  );
  const authorizationHeader = headers.get("authorization");
  const authorizationScheme = authorizationHeader
    ? (authorizationHeader.split(/\s+/, 1)[0] ?? null)
    : null;

  return {
    method: (
      init?.method ??
      (isMcpHttpRequestLike(input) ? input.method : undefined) ??
      "GET"
    ).toUpperCase(),
    url: urlSnapshot,
    headers: { names: headerNames, count: headerNames.length },
    contentType,
    body: summarizeBody(init?.body, headers),
    sessionIdHash: sessionIdHash ?? null,
    authorizationScheme,
  };
}

export function buildMcpHttpResponseSnapshotForLog(
  response: ResponseForLog,
  errorSummary?: string
): McpHttpResponseSnapshotForLog {
  const headerNames = getHeaderNames(response.headers);
  const contentLength = parseContentLength(
    response.headers.get("content-length")
  );

  return {
    status: response.status,
    ok: response.ok,
    headers: { names: headerNames, count: headerNames.length },
    contentType: response.headers.get("content-type"),
    body: {
      kind: response.body === null ? "none" : "stream",
      bytes: response.body === null ? 0 : contentLength,
      contentLength,
      ...(errorSummary !== undefined ? { errorSummary } : {}),
    },
    sessionIdHash:
      hashMcpOAuthValueForLog(
        response.headers.get("mcp-session-id") ?? undefined
      ) ?? null,
    wwwAuthenticateHash:
      hashMcpOAuthValueForLog(
        response.headers.get("www-authenticate") ?? undefined
      ) ?? null,
    mcpProtocolVersion: response.headers.get("mcp-protocol-version") ?? null,
  };
}

function buildErrorSnapshotForLog(
  errorMeta: McpOAuthErrorLogMetadata
): McpHttpErrorSnapshotForLog {
  const result: Record<string, unknown> = {};
  if (errorMeta.errorName !== undefined) result.name = errorMeta.errorName;
  if (errorMeta.errorMessage !== undefined)
    result.message = errorMeta.errorMessage;
  if (errorMeta.errorType !== undefined) result.type = errorMeta.errorType;
  if (errorMeta.oauthErrorCode !== undefined)
    result.oauthErrorCode = errorMeta.oauthErrorCode;
  if (errorMeta.errorResponseSummary !== undefined)
    result.responseSummary = errorMeta.errorResponseSummary;
  if (errorMeta.networkClassification !== undefined)
    result.networkClassification = errorMeta.networkClassification;
  if (errorMeta.sdkErrorKind !== undefined)
    result.sdkErrorKind = errorMeta.sdkErrorKind;
  return result as McpHttpErrorSnapshotForLog;
}

export function buildMcpHttpExchangeSuccessMetadata(args: {
  input: McpHttpRequestInput;
  init?: McpHttpRequestInitLike;
  response: ResponseForLog;
  durationMs: number;
  metadata?: Record<string, unknown>;
  responseErrorSummary?: string;
  readonly oauthTokenErrorBodySummary?: string;
}): McpHttpExchangeSuccessMetadata & Record<string, unknown> {
  const {
    input,
    init,
    response,
    durationMs,
    metadata,
    responseErrorSummary,
    oauthTokenErrorBodySummary,
  } = args;
  const request = buildMcpHttpRequestSnapshotForLog({ input, init });
  const oauthGrantType = extractOAuthGrantTypeForLog(
    request.contentType,
    init?.body
  );
  return {
    event: "mcp_http_exchange",
    outcome: response.ok ? "success" : "http_error",
    durationMs,
    cursorMcp: {
      transport: {
        ...metadata,
        request,
        response: buildMcpHttpResponseSnapshotForLog(
          response,
          responseErrorSummary
        ),
        ...(oauthGrantType !== undefined
          ? { oauth: { grantType: oauthGrantType } }
          : {}),
        ...(oauthTokenErrorBodySummary !== undefined
          ? { oauthTokenErrorBodySummary }
          : {}),
      },
    },
  };
}

function isOAuthTokenEndpointRequest(
  input: McpHttpRequestInput,
  init?: McpHttpRequestInitLike
): boolean {
  const request = buildMcpHttpRequestSnapshotForLog({ input, init });
  if (
    extractOAuthGrantTypeForLog(request.contentType, init?.body) !== undefined
  ) {
    return true;
  }
  const path = request.url.path?.toLowerCase() ?? "";
  return (
    path.endsWith("/token") ||
    path.includes("/oauth/token") ||
    path.includes("/connect/token")
  );
}

async function readClonedResponseTextUpToMax(
  response: Response,
  maxBytes: number
): Promise<string | undefined> {
  try {
    const text = await response.clone().text();
    return text.length > maxBytes ? text.slice(0, maxBytes) : text;
  } catch {
    return undefined;
  }
}

function summarizeResponseBodyForLog(args: {
  input: McpHttpRequestInput;
  rawText: string;
}): string | undefined {
  const path = snapshotUrlForLog(resolveRequestUrl(args.input)).path;
  if (!isMcpEndpointPath(path)) {
    return sanitizeErrorMessageForLog(args.rawText, {
      maxLength: MAX_RESPONSE_ERROR_SUMMARY_LOG_BYTES,
    });
  }
  try {
    const parsed = JSON.parse(args.rawText) as unknown;
    return typeof parsed === "object" && parsed !== null
      ? summarizeMcpErrorBody(parsed as Record<string, unknown>)
      : undefined;
  } catch {
    return undefined;
  }
}

async function buildOAuthTokenEndpointErrorBodySummaryForLog(args: {
  input: McpHttpRequestInput;
  response: Response;
  init?: McpHttpRequestInitLike;
}): Promise<string | undefined> {
  if (!isOAuthTokenEndpointRequest(args.input, args.init)) {
    return undefined;
  }
  const rawText = await readClonedResponseTextUpToMax(
    args.response,
    MAX_RESPONSE_ERROR_SUMMARY_LOG_BYTES
  );
  if (rawText === undefined) {
    return undefined;
  }
  try {
    return sanitizeStructuredValueForLog(JSON.parse(rawText));
  } catch {
    return sanitizeErrorMessageForLog(rawText, {
      maxLength: MAX_RESPONSE_ERROR_SUMMARY_LOG_BYTES,
    });
  }
}

async function readHttpExchangeErrorSummariesForLog(args: {
  input: McpHttpRequestInput;
  init?: McpHttpRequestInitLike;
  response: Response;
}): Promise<{
  responseErrorSummary?: string;
  oauthTokenErrorBodySummary?: string;
}> {
  const responseErrorSummary = await readErrorResponseSummaryForLog(
    args.input,
    args.response
  );
  const oauthTokenErrorBodySummary =
    responseErrorSummary === undefined
      ? await buildOAuthTokenEndpointErrorBodySummaryForLog({
          input: args.input,
          response: args.response,
          init: args.init,
        })
      : undefined;
  return { responseErrorSummary, oauthTokenErrorBodySummary };
}

export function buildMcpHttpExchangeFailureMetadata(args: {
  input: McpHttpRequestInput;
  init?: McpHttpRequestInitLike;
  error: unknown;
  durationMs: number;
  metadata?: Record<string, unknown>;
  responseFromError?: ResponseForLog;
  responseErrorSummary?: string;
  oauthTokenErrorBodySummary?: string;
}): McpHttpExchangeFailureMetadata & Record<string, unknown> {
  const {
    input,
    init,
    error,
    durationMs,
    metadata,
    responseFromError,
    responseErrorSummary,
    oauthTokenErrorBodySummary,
  } = args;
  const errorMetadata = getMcpOAuthErrorLogMetadata(error);
  const request = buildMcpHttpRequestSnapshotForLog({ input, init });
  const oauthGrantType = extractOAuthGrantTypeForLog(
    request.contentType,
    init?.body
  );
  const response: McpHttpResponseSnapshotForLog =
    responseFromError !== undefined
      ? buildMcpHttpResponseSnapshotForLog(
          responseFromError,
          responseErrorSummary
        )
      : {
          status: errorMetadata.httpStatus ?? null,
          ok: null,
          headers: { names: [], count: 0 },
          contentType: null,
          body: {
            kind: "none" as const,
            bytes: null,
            contentLength: null,
            ...(responseErrorSummary !== undefined
              ? { errorSummary: responseErrorSummary }
              : {}),
          },
          sessionIdHash: null,
          wwwAuthenticateHash: null,
          mcpProtocolVersion: null,
        };
  return {
    event: "mcp_http_exchange",
    outcome: "error",
    durationMs,
    cursorMcp: {
      transport: {
        ...metadata,
        request,
        response,
        ...(oauthGrantType !== undefined
          ? { oauth: { grantType: oauthGrantType } }
          : {}),
        ...(oauthTokenErrorBodySummary !== undefined
          ? { oauthTokenErrorBodySummary }
          : {}),
        error: buildErrorSnapshotForLog(errorMetadata),
      },
    },
  };
}

export function logMcpHttpExchangeSuccess(args: {
  logger: McpHttpExchangeLogger;
  input: McpHttpRequestInput;
  init?: McpHttpRequestInitLike;
  response: ResponseForLog;
  durationMs: number;
  metadata?: Record<string, unknown>;
  responseErrorSummary?: string;
  oauthTokenErrorBodySummary?: string;
}): void {
  const { logger, response } = args;
  const logMetadata = buildMcpHttpExchangeSuccessMetadata(args);
  if (response.ok) {
    logger.info?.("MCP HTTP exchange completed", logMetadata);
  } else {
    logger.warn?.("MCP HTTP exchange completed", logMetadata);
  }
}

export function logMcpHttpExchangeFailure(args: {
  logger: McpHttpExchangeLogger;
  input: McpHttpRequestInput;
  init?: McpHttpRequestInitLike;
  error: unknown;
  durationMs: number;
  metadata?: Record<string, unknown>;
  responseFromError?: ResponseForLog;
  responseErrorSummary?: string;
  oauthTokenErrorBodySummary?: string;
}): void {
  const { logger } = args;
  logger.warn?.(
    "MCP HTTP exchange failed",
    buildMcpHttpExchangeFailureMetadata(args)
  );
}

function isMcpEndpointPath(path: string | null): boolean {
  return path === "/mcp" || path?.endsWith("/mcp") === true;
}

function summarizeMcpErrorBody(
  parsed: Record<string, unknown>
): string | undefined {
  const error = parsed.error;
  if (typeof error === "string") {
    return JSON.stringify({ error });
  }
  if (typeof error !== "object" || error === null) {
    return undefined;
  }
  const errorRecord = error as Record<string, unknown>;
  const code =
    typeof errorRecord.code === "number" || typeof errorRecord.code === "string"
      ? errorRecord.code
      : undefined;
  const message =
    typeof errorRecord.message === "string"
      ? sanitizeErrorMessageForLog(errorRecord.message, {
          maxLength: MAX_RESPONSE_ERROR_SUMMARY_LOG_BYTES,
        })
      : undefined;
  if (code === undefined && message === undefined) {
    return undefined;
  }
  return JSON.stringify({
    ...(code !== undefined ? { code } : {}),
    ...(message !== undefined ? { message } : {}),
  });
}

async function readErrorResponseSummaryForLog(
  input: McpHttpRequestInput,
  response: Response
): Promise<string | undefined> {
  try {
    if (response.ok) {
      return undefined;
    }
    const contentType =
      response.headers.get("content-type")?.toLowerCase() ?? "";
    if (!contentType.includes("json") && !contentType.includes("text")) {
      return undefined;
    }
    const rawText = await readClonedResponseTextUpToMax(
      response,
      MAX_RESPONSE_ERROR_SUMMARY_LOG_BYTES
    );
    if (rawText === undefined) {
      return undefined;
    }
    return summarizeResponseBodyForLog({
      input,
      rawText,
    });
  } catch {
    return undefined;
  }
}

function safelyLogExchange(
  action: () => void,
  logger: McpHttpExchangeLogger,
  phase: "success" | "failure"
): void {
  try {
    action();
  } catch {
    logger.warn?.("MCP HTTP exchange logging failed", {
      event: "mcp_http_exchange_logging_failure",
      phase,
    });
  }
}

export function createLoggedMcpHttpFetch(
  options: LoggedMcpHttpFetchOptions
): McpHttpFetchLike {
  const { fetch, logger, metadata, logSuccessfulExchanges = true } = options;

  return async (input, init) => {
    const startedAtMs = Date.now();

    try {
      const response = await fetch(input, init);
      const { responseErrorSummary, oauthTokenErrorBodySummary } = response.ok
        ? {}
        : await readHttpExchangeErrorSummariesForLog({
            input,
            init,
            response,
          });
      if (logSuccessfulExchanges || !response.ok) {
        safelyLogExchange(
          () => {
            logMcpHttpExchangeSuccess({
              logger,
              input,
              init,
              response,
              durationMs: Date.now() - startedAtMs,
              metadata,
              responseErrorSummary,
              oauthTokenErrorBodySummary,
            });
          },
          logger,
          "success"
        );
      }

      return response;
    } catch (error) {
      const responseFromError = extractResponseFromFetchError(error);
      const { responseErrorSummary, oauthTokenErrorBodySummary } =
        responseFromError
          ? await readHttpExchangeErrorSummariesForLog({
              input,
              init,
              response: responseFromError,
            })
          : {};
      safelyLogExchange(
        () => {
          logMcpHttpExchangeFailure({
            logger,
            input,
            init,
            error,
            durationMs: Date.now() - startedAtMs,
            metadata,
            responseFromError,
            responseErrorSummary,
            oauthTokenErrorBodySummary,
          });
        },
        logger,
        "failure"
      );
      throw error;
    }
  };
}
