import { promises as fs } from "node:fs";
import { dirname, join } from "node:path";

import { z } from "zod";

import {
	LOCAL_EXEC_DAEMON_CONNECTION_FILENAME,
	LOCAL_EXEC_DAEMON_CREDENTIAL_FILENAME,
	LOCAL_EXEC_DAEMON_DISCOVERY_FILENAME,
	LOCAL_EXEC_SUPERVISOR_HEARTBEAT_FILENAME,
	type LocalExecDaemonCredential,
	type LocalExecDaemonDiscovery,
	type LocalExecSupervisorHeartbeat,
} from "../../shared/local-exec-daemon.js";
import { findSystemErrno } from "../../shared/system-errno.js";
import type { SandGatewayConnectionInfo } from "../gateway-protocol.js";
import { getSandRootDir } from "../host-paths.js";

const connectionSchema = z.object({
	baseUrl: z.string().min(1),
	token: z.string().optional(),
	headers: z.record(z.string()).optional(),
});

const discoverySchema = z.object({
	pid: z.number().int().positive(),
	startedAt: z.number(),
	inflightCount: z.number().int().nonnegative().optional(),
});

const supervisorHeartbeatSchema = z.object({
	pid: z.number().int().positive(),
	at: z.number(),
});

export type { LocalExecDaemonDiscovery } from "../../shared/local-exec-daemon.js";

// The daemon's durable, box-bound credential handoff (desktop -> daemon): the
// desktop mints an opaque `slx_*` credential so the daemon can re-resolve a
// recreated box's connection WITHOUT the desktop; `backendUrl` says where to
// exchange it (the daemon inherits no auth). NOT a refresh token: it only
// re-resolves this one box (see sandBoxLocalExecCredentialStore.ts). The
// equality pin below keeps this schema and the shared type from drifting in
// EITHER direction (a return-type annotation checks one-way assignability).
const credentialSchema = z.object({
	credential: z.string().min(1),
	backendUrl: z.string().min(1),
	// Informational expiry; the daemon uses it until the backend rejects it.
	expiresAtMs: z.number().optional(),
});

type InferredCredential = z.infer<typeof credentialSchema>;
type CredentialSchemaMatchesSharedType = [InferredCredential] extends [LocalExecDaemonCredential]
	? [LocalExecDaemonCredential] extends [InferredCredential]
		? Exclude<keyof LocalExecDaemonCredential, keyof InferredCredential> extends never
			? Exclude<keyof InferredCredential, keyof LocalExecDaemonCredential> extends never
				? true
				: false
			: false
		: false
	: false;
const credentialSchemaMatchesSharedType: CredentialSchemaMatchesSharedType = true;
void credentialSchemaMatchesSharedType;

export type { LocalExecDaemonCredential } from "../../shared/local-exec-daemon.js";

export function getLocalExecDaemonConnectionPath(homeDir?: string): string {
	return join(getSandRootDir(homeDir), LOCAL_EXEC_DAEMON_CONNECTION_FILENAME);
}

export function getLocalExecDaemonDiscoveryPath(homeDir?: string): string {
	return join(getSandRootDir(homeDir), LOCAL_EXEC_DAEMON_DISCOVERY_FILENAME);
}

export function getLocalExecDaemonCredentialPath(homeDir?: string): string {
	return join(getSandRootDir(homeDir), LOCAL_EXEC_DAEMON_CREDENTIAL_FILENAME);
}

export function getLocalExecSupervisorHeartbeatPath(homeDir?: string): string {
	return join(getSandRootDir(homeDir), LOCAL_EXEC_SUPERVISOR_HEARTBEAT_FILENAME);
}

async function writeDaemonJsonFile<T>(
	path: string,
	data: T,
	options: { readonly mode?: number; readonly pretty?: boolean } = {},
): Promise<void> {
	await fs.mkdir(dirname(path), { recursive: true });
	const tempPath = `${path}.${process.pid}.tmp`;
	const serialized = JSON.stringify(data, null, options.pretty === true ? 2 : undefined);
	await fs.writeFile(
		tempPath,
		serialized,
		options.mode != null ? { encoding: "utf8", mode: options.mode } : "utf8",
	);
	await fs.rename(tempPath, path);
}

async function readDaemonJsonFile<T>(path: string, schema: z.ZodType<T>): Promise<T | null> {
	let raw: string;
	try {
		raw = await fs.readFile(path, "utf8");
	} catch (error) {
		if (findSystemErrno(error) === "ENOENT") return null;
		throw error;
	}
	try {
		const parsed = schema.safeParse(JSON.parse(raw));
		return parsed.success ? parsed.data : null;
	} catch {
		return null;
	}
}

export function writeLocalExecDaemonConnection(
	connection: SandGatewayConnectionInfo,
	path = getLocalExecDaemonConnectionPath(),
): Promise<void> {
	return writeDaemonJsonFile(path, connection, { mode: 0o600 });
}

export function readLocalExecDaemonConnection(
	path = getLocalExecDaemonConnectionPath(),
): Promise<SandGatewayConnectionInfo | null> {
	return readDaemonJsonFile(path, connectionSchema);
}

export function writeLocalExecDaemonCredential(
	credential: LocalExecDaemonCredential,
	path = getLocalExecDaemonCredentialPath(),
): Promise<void> {
	return writeDaemonJsonFile(path, credential, { mode: 0o600 });
}

export function readLocalExecDaemonCredential(
	path = getLocalExecDaemonCredentialPath(),
): Promise<LocalExecDaemonCredential | null> {
	return readDaemonJsonFile(path, credentialSchema);
}

const NO_SUPERVISOR_HEARTBEAT: LocalExecSupervisorHeartbeat = { pid: 0, at: 0 };

export async function readLocalExecSupervisorHeartbeat(
	path = getLocalExecSupervisorHeartbeatPath(),
): Promise<LocalExecSupervisorHeartbeat> {
	try {
		return (await readDaemonJsonFile(path, supervisorHeartbeatSchema)) ?? NO_SUPERVISOR_HEARTBEAT;
	} catch {
		return NO_SUPERVISOR_HEARTBEAT;
	}
}

export async function clearLocalExecDaemonCredential(
	path = getLocalExecDaemonCredentialPath(),
): Promise<void> {
	await fs.rm(path, { force: true });
}

export function writeLocalExecDaemonDiscovery(
	info: LocalExecDaemonDiscovery,
	path = getLocalExecDaemonDiscoveryPath(),
): Promise<void> {
	return writeDaemonJsonFile(path, info, { pretty: true });
}

export function readLocalExecDaemonDiscovery(
	path = getLocalExecDaemonDiscoveryPath(),
): Promise<LocalExecDaemonDiscovery | null> {
	return readDaemonJsonFile(path, discoverySchema);
}

export async function clearLocalExecDaemonDiscovery(
	path = getLocalExecDaemonDiscoveryPath(),
): Promise<void> {
	await fs.rm(path, { force: true });
}
