import { readFile } from "node:fs/promises";
import { hostname } from "node:os";
import { join } from "node:path";

import type { SimpleControlledExecManager } from "@anysphere/agent-exec";
import { type Context, createContext, loggerKey } from "@anysphere/context";
import {
	ExecServerAbort,
	ExecServerControlMessage,
} from "@anysphere/proto/agent/v1/agent_service_pb.js";
import {
	ExecClientControlMessage,
	ExecClientMessage,
	ExecClientThrow,
	ExecServerMessage,
} from "@anysphere/proto/agent/v1/exec_pb.js";
import type { JsonValue } from "@bufbuild/protobuf";
import {
	createDeadlinePolicy,
	createIdleWatchdogPolicy,
	createPollingPolicy,
	createRetryPolicy,
	type DeadlinePolicy,
} from "@sand/dune/scheduling";

import { errorLogTag, errorMessage } from "../../shared/errors.js";
import { GATEWAY_AUTH_SCHEME } from "../../shared/gateway-wire.js";
import {
	DEFAULT_MAX_LOCAL_EXEC_FILE_BYTES,
	GATEWAY_LOCAL_EXEC_REQUESTS_PATH,
	GATEWAY_LOCAL_EXEC_RESPONSES_PATH,
	localExecFileTooLargeMessage,
	localExecUploadFrameTooLargeMessage,
	maxLocalExecUploadFrameBytes,
	SAND_LOCAL_EXEC_CONTROL_POST_TIMEOUT_MS,
	SAND_LOCAL_EXEC_DATA_POST_TIMEOUT_MS,
	SAND_LOCAL_EXEC_HEARTBEAT_INTERVAL_MS,
	type SandLocalExecRequestFrame,
	type SandLocalExecResponseFrame,
} from "../../shared/local-exec-gateway.js";
import {
	describeLocalExec,
	type SandLocalToolRequest,
} from "../../shared/local-tool-permission-machinery.js";
import { writeFileAtomic } from "../../shared/node/atomic-write.js";
import { type SandGatewayConnectionInfo } from "../gateway-protocol.js";
import { DEFAULT_SAND_COMPUTER_ID } from "../ports/user-computer.js";
import {
	buildLocalExecManager,
	containPath,
	regularFileSizeBytes,
	resolveLocalExecRoot,
} from "./local-exec-machine.js";

export class SandLocalExecStreamError extends Error {}

const SSE_RECONNECT_MIN_MS = 1_000;
const SSE_RECONNECT_MAX_MS = 10_000;
const SSE_STALL_TIMEOUT_MS = 35_000;
const STALE_CONNECTION_FAILURE_THRESHOLD = 3;
const RESPONSE_POST_RETRIES = 3;
const RESPONSE_POST_RETRY_DELAY_MS = 200;

function withAuth(
	headers: Record<string, string>,
	connection: Pick<SandGatewayConnectionInfo, "token" | "headers">,
): Record<string, string> {
	const merged: Record<string, string> = { ...headers, ...connection.headers };
	if (connection.token != null && connection.token.length > 0) {
		merged.authorization = `${GATEWAY_AUTH_SCHEME} ${connection.token}`;
	}
	return merged;
}

function isSameConnection(a: SandGatewayConnectionInfo, b: SandGatewayConnectionInfo): boolean {
	return (
		a.baseUrl === b.baseUrl &&
		a.token === b.token &&
		JSON.stringify(a.headers ?? {}) === JSON.stringify(b.headers ?? {})
	);
}

export interface SandLocalExecProviderOptions {
	readonly resolveConnection: () => Promise<SandGatewayConnectionInfo>;
	readonly root?: string;
	readonly onConnectionStale?: () => Promise<void>;
	readonly computerId?: string;
	readonly computerLabel?: string;
	readonly onInflightChange?: (inflightCount: number) => void;
	readonly maxFileBytes?: number;
	readonly isLocalUseBlocked?: (request: LocalUseRequest) => Promise<string | undefined>;
	readonly onApprovalRetired?: (approvalId: string) => Promise<void>;
	// Bridge routing-preference signals (SAND-1238); `isSupervised` resolves,
	// never rejects, at every hello and heartbeat so the signal can decay.
	readonly isSupervised?: () => Promise<boolean>;
	readonly variant?: string;
}

export interface LocalUseRequest {
	readonly approvalId: string | undefined;
	readonly describes:
		| Pick<SandLocalToolRequest, "action" | "target" | "attachToResourcePath">
		| undefined;
	readonly terminalsFolder: string;
}

export class SandLocalExecProvider {
	private closed = false;
	private abortController: AbortController | undefined;
	private readonly root: string;
	private readonly terminalsFolder: string;
	private readonly computerId: string;
	private readonly computerLabel: string;
	private readonly maxFileBytes: number;
	private readonly maxUploadFrameBytes: number;
	private readonly execManager: SimpleControlledExecManager;
	private readonly dataPostDeadline = createDeadlinePolicy({
		name: "local-exec-data-post",
		timeoutMs: SAND_LOCAL_EXEC_DATA_POST_TIMEOUT_MS,
	});
	private readonly controlPostDeadline = createDeadlinePolicy({
		name: "local-exec-control-post",
		timeoutMs: SAND_LOCAL_EXEC_CONTROL_POST_TIMEOUT_MS,
	});
	private readonly postRetry = createRetryPolicy({
		name: "local-exec-response-post",
		maxAttempts: RESPONSE_POST_RETRIES,
		initialDelayMs: RESPONSE_POST_RETRY_DELAY_MS,
		maxDelayMs: RESPONSE_POST_RETRY_DELAY_MS,
	});
	private readonly reconnectBackoff = createRetryPolicy({
		name: "local-exec-sse-reconnect",
		maxAttempts: Number.MAX_SAFE_INTEGER,
		initialDelayMs: SSE_RECONNECT_MIN_MS,
		maxDelayMs: SSE_RECONNECT_MAX_MS,
	});
	private readonly stallWatchdog = createIdleWatchdogPolicy({
		name: "local-exec-sse-stall",
		idleMs: SSE_STALL_TIMEOUT_MS,
	});
	private readonly heartbeat = createPollingPolicy({
		name: "local-exec-heartbeat",
		intervalMs: SAND_LOCAL_EXEC_HEARTBEAT_INTERVAL_MS,
	});
	private readonly baseCtx: Context = createContext().with(loggerKey, {
		log: () => {},
	});
	private nextExecId = 1;
	private readonly inflight = new Map<
		string,
		{ readonly execId: number; readonly cancel: () => void }
	>();
	private readonly outbox: SandLocalExecResponseFrame[] = [];
	private flushing = false;
	private providerId: string | undefined;

	constructor(private readonly options: SandLocalExecProviderOptions) {
		this.root = options.root ?? resolveLocalExecRoot();
		this.terminalsFolder = join(this.root, "terminals");
		const host = hostname().trim();
		this.computerId =
			options.computerId?.trim() || (host.length > 0 ? host : DEFAULT_SAND_COMPUTER_ID);
		this.computerLabel =
			options.computerLabel?.trim() || (host.length > 0 ? host : "this computer");
		this.maxFileBytes = options.maxFileBytes ?? DEFAULT_MAX_LOCAL_EXEC_FILE_BYTES;
		this.maxUploadFrameBytes = maxLocalExecUploadFrameBytes(this.maxFileBytes);
		this.execManager = buildLocalExecManager(this.root, this.maxFileBytes);
	}

	start(): void {
		void this.runLoop();
	}

	close(): void {
		this.closed = true;
		this.abortController?.abort();
	}

	private enqueue(frame: SandLocalExecResponseFrame): void {
		this.outbox.push(frame);
		void this.flush();
	}

	private async postBatch(
		frames: SandLocalExecResponseFrame[],
		deadline: DeadlinePolicy,
	): Promise<boolean> {
		try {
			return await this.postRetry.runWithRetry(async () => {
				const connection = await this.options.resolveConnection();
				const response = await deadline.run((signal) =>
					fetch(`${connection.baseUrl}${GATEWAY_LOCAL_EXEC_RESPONSES_PATH}`, {
						method: "POST",
						headers: withAuth({ "content-type": "application/json" }, connection),
						body: JSON.stringify({ providerId: this.providerId, frames }),
						signal,
					}),
				);
				if (!response.ok) {
					const failure = new Error("response POST failed") as Error & {
						code?: string;
					};
					failure.code = `http_${response.status}`;
					throw failure;
				}
				return true;
			});
		} catch (error) {
			console.error(
				`[local-exec-provider] dropping ${frames.length}-frame response batch after ${RESPONSE_POST_RETRIES} failed POSTs: ${errorLogTag(error)}`,
			);
			return false;
		}
	}

	private async flush(): Promise<void> {
		if (this.flushing) return;
		this.flushing = true;
		try {
			while (this.outbox.length > 0 && !this.closed) {
				const frames = this.outbox.slice();
				const isPosted = await this.postBatch(frames, this.dataPostDeadline);
				this.outbox.splice(0, frames.length);
				if (!isPosted) break;
			}
		} finally {
			this.flushing = false;
		}
	}

	private async runLoop(): Promise<void> {
		let reconnectAttempt = 1;
		let consecutiveFailures = 0;
		while (!this.closed) {
			try {
				await this.streamRequests(() => {
					reconnectAttempt = 1;
					consecutiveFailures = 0;
				});
			} catch {
				consecutiveFailures += 1;
			}
			if (this.closed) break;
			if (
				consecutiveFailures >= STALE_CONNECTION_FAILURE_THRESHOLD &&
				this.options.onConnectionStale != null
			) {
				consecutiveFailures = 0;
				try {
					await this.options.onConnectionStale();
				} catch (error) {
					console.error(
						`[local-exec-provider] stale-connection re-resolve failed: ${errorLogTag(error)}`,
					);
				}
			}
			const backoff = this.reconnectBackoff.schedule(reconnectAttempt);
			try {
				await backoff.elapsed;
			} finally {
				backoff.dispose();
			}
			reconnectAttempt += 1;
		}
	}

	private async dialedConnectionState(
		dialed: SandGatewayConnectionInfo,
	): Promise<"same" | "moved" | "unreadable"> {
		try {
			const fresh = await this.options.resolveConnection();
			return isSameConnection(fresh, dialed) ? "same" : "moved";
		} catch {
			return "unreadable";
		}
	}

	private async currentSupervised(): Promise<boolean | undefined> {
		return await this.options.isSupervised?.();
	}

	private async streamRequests(resetBackoff: () => void): Promise<void> {
		const connection = await this.options.resolveConnection();
		const controller = new AbortController();
		this.abortController = controller;
		const response = await fetch(`${connection.baseUrl}${GATEWAY_LOCAL_EXEC_REQUESTS_PATH}`, {
			headers: withAuth({ accept: "text/event-stream" }, connection),
			signal: controller.signal,
		});
		if (!response.ok || response.body == null) {
			throw new SandLocalExecStreamError(`local-exec requests stream failed: ${response.status}`);
		}
		resetBackoff();
		void this.currentSupervised().then((supervised) =>
			this.postBatch(
				[
					{
						kind: "hello",
						localRoot: this.root,
						terminalsFolder: this.terminalsFolder,
						computerId: this.computerId,
						label: this.computerLabel,
						...(supervised !== undefined ? { supervised } : {}),
						...(this.options.variant !== undefined ? { variant: this.options.variant } : {}),
					},
				],
				this.controlPostDeadline,
			),
		);

		const reader = response.body.getReader();
		const decoder = new TextDecoder();
		let buffer = "";
		const stall = this.stallWatchdog.arm(() => controller.abort());
		// A live stream to a still-reachable old box never fails on its own, so a
		// box move is observed here: re-dial when the descriptor stops naming
		// this stream's connection.
		const heartbeatTicks = this.heartbeat.start(async () => {
			const supervised = await this.currentSupervised();
			void this.postBatch(
				[{ kind: "ping", ...(supervised !== undefined ? { supervised } : {}) }],
				this.controlPostDeadline,
			);
			if ((await this.dialedConnectionState(connection)) === "moved") {
				controller.abort();
			}
		});

		try {
			let droppingOversizedFrame = false;
			for (;;) {
				const { done, value } = await reader.read();
				if (done) break;
				stall.kick();
				buffer += decoder.decode(value, { stream: true });

				if (droppingOversizedFrame) {
					const boundary = buffer.indexOf("\n\n");
					if (boundary < 0) {
						buffer = buffer.slice(-1);
						continue;
					}
					buffer = buffer.slice(boundary + 2);
					droppingOversizedFrame = false;
				}

				let separator = buffer.indexOf("\n\n");
				while (separator >= 0) {
					if (separator > this.maxUploadFrameBytes) {
						this.rejectOversizedFrame(buffer);
					} else {
						this.dispatchEventBlock(buffer.slice(0, separator));
					}
					buffer = buffer.slice(separator + 2);
					separator = buffer.indexOf("\n\n");
				}

				if (buffer.length > this.maxUploadFrameBytes) {
					this.rejectOversizedFrame(buffer);
					buffer = buffer.slice(-1);
					droppingOversizedFrame = true;
				}
			}
		} finally {
			stall.dispose();
			heartbeatTicks.dispose();
			this.providerId = undefined;
		}
	}

	private rejectOversizedFrame(framePrefix: string): void {
		const head = framePrefix.length > 4096 ? framePrefix.slice(0, 4096) : framePrefix;
		const match = /"requestId"\s*:\s*"([^"\\]+)"/.exec(head);
		if (match === null) return;
		this.enqueue({
			kind: "file-error",
			requestId: match[1],
			error: localExecUploadFrameTooLargeMessage(this.maxFileBytes),
		});
	}

	private dispatchEventBlock(block: string): void {
		const dataLines = block
			.split("\n")
			.filter((line) => line.startsWith("data:"))
			.map((line) => line.slice("data:".length).trim());
		if (dataLines.length === 0) return;
		let frame: SandLocalExecRequestFrame;
		try {
			frame = JSON.parse(dataLines.join("\n")) as SandLocalExecRequestFrame;
		} catch (error) {
			console.error(
				`[local-exec-provider] dropping unparseable request frame: ${errorLogTag(error)}`,
			);
			return;
		}
		void this.handleRequest(frame);
	}

	private async handleRequest(frame: SandLocalExecRequestFrame): Promise<void> {
		if (frame.kind === "retire-approval") {
			await this.options.onApprovalRetired?.(frame.approvalId);
			return;
		}
		if (frame.kind === "exec" || frame.kind === "upload" || frame.kind === "download") {
			const blocked = await this.options.isLocalUseBlocked?.({
				approvalId: frame.approvalId,
				describes: this.describeFrame(frame),
				terminalsFolder: this.terminalsFolder,
			});
			if (blocked !== undefined) {
				this.refuse(frame.requestId, frame.kind, blocked);
				return;
			}
		}
		switch (frame.kind) {
			case "welcome":
				this.providerId = frame.providerId;
				return;
			case "exec":
				return this.handleExec(frame.requestId, frame.serverMessage);
			case "upload":
				return this.handleUpload(frame.requestId, frame.path, frame.bytesBase64);
			case "download":
				return this.handleDownload(frame.requestId, frame.path);
			case "cancel":
				return this.handleCancel(frame.requestId);
		}
	}

	private describeFrame(
		frame: SandLocalExecRequestFrame & {
			readonly kind: "exec" | "upload" | "download";
		},
	): LocalUseRequest["describes"] {
		switch (frame.kind) {
			case "exec":
				try {
					return describeLocalExec(
						ExecServerMessage.fromJson(frame.serverMessage as JsonValue, {
							ignoreUnknownFields: true,
						}),
						this.terminalsFolder,
					);
				} catch {
					return undefined;
				}
			case "upload":
				return { action: "write-file", target: frame.path };
			case "download":
				return {
					action: "read-file",
					target: frame.path,
					attachToResourcePath: frame.path,
				};
		}
	}

	private refuse(requestId: string, kind: "exec" | "upload" | "download", reason: string): void {
		if (kind === "exec") {
			this.enqueue({
				kind: "control",
				requestId,
				message: new ExecClientControlMessage({
					message: {
						case: "throw",
						value: new ExecClientThrow({ id: 0, error: reason }),
					},
				}).toJson(),
			});
			return;
		}
		this.enqueue({ kind: "file-error", requestId, error: reason });
	}

	private async handleExec(requestId: string, serverMessageJson: unknown): Promise<void> {
		let serverMessage: ExecServerMessage;
		try {
			serverMessage = ExecServerMessage.fromJson(serverMessageJson as JsonValue, {
				ignoreUnknownFields: true,
			});
		} catch (error) {
			this.enqueue({
				kind: "control",
				requestId,
				message: new ExecClientControlMessage({
					message: {
						case: "throw",
						value: new ExecClientThrow({ id: 0, error: errorMessage(error) }),
					},
				}).toJson(),
			});
			return;
		}
		const execId = this.nextExecId++;
		serverMessage.id = execId;
		const [ctx, cancel] = this.baseCtx.withCancel();
		this.inflight.set(requestId, { execId, cancel });
		this.options.onInflightChange?.(this.inflight.size);
		try {
			for await (const message of this.execManager.handle(ctx, serverMessage)) {
				if (message instanceof ExecClientMessage) {
					this.enqueue({ kind: "client", requestId, message: message.toJson() });
				} else {
					this.enqueue({ kind: "control", requestId, message: message.toJson() });
				}
			}
		} finally {
			this.inflight.delete(requestId);
			this.options.onInflightChange?.(this.inflight.size);
		}
	}

	private handleCancel(requestId: string): void {
		const entry = this.inflight.get(requestId);
		if (entry === undefined) return;
		this.execManager.handleControlMessage(
			new ExecServerControlMessage({
				message: { case: "abort", value: new ExecServerAbort({ id: entry.execId }) },
			}),
		);
		entry.cancel();
	}

	private async handleUpload(requestId: string, path: string, bytesBase64: string): Promise<void> {
		try {
			const approxBytes = Math.floor((bytesBase64.length * 3) / 4);
			if (approxBytes > this.maxFileBytes) {
				this.enqueue({
					kind: "file-error",
					requestId,
					error: localExecFileTooLargeMessage(approxBytes, this.maxFileBytes),
				});
				return;
			}
			const target = await containPath({ root: this.root, path });
			await writeFileAtomic(target, Buffer.from(bytesBase64, "base64"));
			this.enqueue({ kind: "file", requestId });
		} catch (error) {
			this.enqueue({ kind: "file-error", requestId, error: errorMessage(error) });
		}
	}

	private async handleDownload(requestId: string, path: string): Promise<void> {
		try {
			const target = await containPath({ root: this.root, path });
			const sizeBytes = await regularFileSizeBytes(target);
			if (sizeBytes !== undefined && sizeBytes > this.maxFileBytes) {
				this.enqueue({
					kind: "file-error",
					requestId,
					error: localExecFileTooLargeMessage(sizeBytes, this.maxFileBytes),
				});
				return;
			}
			const data = await readFile(target);
			this.enqueue({
				kind: "file",
				requestId,
				bytesBase64: data.toString("base64"),
			});
		} catch (error) {
			this.enqueue({ kind: "file-error", requestId, error: errorMessage(error) });
		}
	}
}
