import {
  NetworkPolicy_DefaultAction,
  NetworkPolicy as ProtoNetworkPolicy,
  NetworkPolicyLoggingConfig as ProtoNetworkPolicyLoggingConfig,
  SandboxPolicy as ProtoSandboxPolicy,
  SandboxPolicyMergeSources as ProtoSandboxPolicyMergeSources,
  SandboxPolicy_ReadBoundaryMode,
  SandboxPolicy_Type,
} from "@anysphere/proto/agent/v1/sandbox_pb.js";
import type {
  NetworkPolicy as InternalNetworkPolicy,
  NetworkPolicyLoggingConfig as InternalNetworkPolicyLoggingConfig,
  SandboxPolicy as InternalSandboxPolicy,
  SandboxPolicyMergeSources as InternalSandboxPolicyMergeSources,
  SandboxReadBoundary,
} from "@anysphere/shell-exec";
import {
  isNetworkEnabledByPolicy,
  networkAllowAllPolicy,
  networkDisabledPolicy,
} from "@anysphere/shell-exec";

// ============================================================================
// NetworkPolicy Conversion
// ============================================================================

export function convertProtoToNetworkPolicy(
  policy?: ProtoNetworkPolicy
): InternalNetworkPolicy | undefined {
  if (!policy) return undefined;

  const result: InternalNetworkPolicy = {};

  if (policy.version !== undefined) {
    result.version = policy.version as 1;
  }

  if (policy.defaultAction !== undefined) {
    switch (policy.defaultAction) {
      case NetworkPolicy_DefaultAction.ALLOW:
        result.default = "allow";
        break;
      case NetworkPolicy_DefaultAction.DENY:
        result.default = "deny";
        break;
      // UNSPECIFIED falls through to undefined
    }
  }

  if (policy.deny && policy.deny.length > 0) {
    result.deny = policy.deny;
  }

  if (policy.allow && policy.allow.length > 0) {
    result.allow = policy.allow;
  }

  if (policy.logging) {
    result.logging = convertProtoToNetworkPolicyLoggingConfig(policy.logging);
  }

  return result;
}

export function convertNetworkPolicyToProto(
  policy?: InternalNetworkPolicy
): ProtoNetworkPolicy | undefined {
  if (!policy) return undefined;

  let defaultAction: NetworkPolicy_DefaultAction | undefined;
  if (policy.default === "allow") {
    defaultAction = NetworkPolicy_DefaultAction.ALLOW;
  } else if (policy.default === "deny") {
    defaultAction = NetworkPolicy_DefaultAction.DENY;
  }

  return new ProtoNetworkPolicy({
    version: policy.version,
    defaultAction,
    deny: policy.deny ?? [],
    allow: policy.allow ?? [],
    logging: policy.logging
      ? convertNetworkPolicyLoggingConfigToProto(policy.logging)
      : undefined,
  });
}

function convertProtoToNetworkPolicyLoggingConfig(
  config: ProtoNetworkPolicyLoggingConfig
): InternalNetworkPolicyLoggingConfig {
  const result: InternalNetworkPolicyLoggingConfig = {};

  if (config.decisionLogPath) {
    result.decisionLogPath = config.decisionLogPath;
  }

  if (config.logFormat === "jsonl") {
    result.logFormat = "jsonl";
  }

  return result;
}

function convertNetworkPolicyLoggingConfigToProto(
  config: InternalNetworkPolicyLoggingConfig
): ProtoNetworkPolicyLoggingConfig {
  return new ProtoNetworkPolicyLoggingConfig({
    decisionLogPath: config.decisionLogPath,
    logFormat: config.logFormat,
  });
}

// ============================================================================
// SandboxPolicy Conversion
// ============================================================================

/**
 * Resolve the internal NetworkPolicy from a proto SandboxPolicy.
 *
 * Prefers the explicit `networkPolicy` message when present. Otherwise falls
 * back to the legacy `networkAccess` boolean:
 *   - true  → allow-all policy
 *   - false / undefined → disabled (deny-all) policy
 */
function resolveNetworkPolicy(
  policy: ProtoSandboxPolicy
): InternalNetworkPolicy {
  const explicit = convertProtoToNetworkPolicy(policy.networkPolicy);
  if (explicit) return explicit;

  return policy.networkAccess
    ? networkAllowAllPolicy()
    : networkDisabledPolicy();
}

function convertProtoToReadBoundary(
  mode: SandboxPolicy_ReadBoundaryMode
): SandboxReadBoundary | undefined {
  switch (mode) {
    case SandboxPolicy_ReadBoundaryMode.SYSTEM:
      return "system";
    case SandboxPolicy_ReadBoundaryMode.WORKSPACE:
    // Legacy CUSTOM meant workspace + allowlist; collapse to workspace.
    case SandboxPolicy_ReadBoundaryMode.CUSTOM:
      return "workspace";
    case SandboxPolicy_ReadBoundaryMode.UNSPECIFIED:
    default:
      // Unspecified means "no opinion" so merge can take the user's boundary.
      return undefined;
  }
}

function convertReadBoundaryToProto(
  boundary: SandboxReadBoundary | undefined
): SandboxPolicy_ReadBoundaryMode {
  switch (boundary) {
    case "system":
      return SandboxPolicy_ReadBoundaryMode.SYSTEM;
    case "workspace":
      return SandboxPolicy_ReadBoundaryMode.WORKSPACE;
    default:
      return SandboxPolicy_ReadBoundaryMode.UNSPECIFIED;
  }
}

function sandboxedProtoFields(policy: ProtoSandboxPolicy): {
  readBoundary: SandboxReadBoundary | undefined;
  additionalReadPaths: string[] | undefined;
} {
  const readBoundary = convertProtoToReadBoundary(policy.readBoundary);
  // Empty repeated fields are proto's default; treat them as "no opinion" so
  // a bare WORKSPACE boundary does not wipe a user allowlist on merge.
  const paths = policy.additionalReadPaths ?? [];
  return {
    readBoundary,
    additionalReadPaths:
      readBoundary === "workspace" && paths.length > 0 ? paths : undefined,
  };
}

export function convertProtoToInternalPolicy(
  policy?: ProtoSandboxPolicy
): InternalSandboxPolicy {
  if (!policy) {
    return { type: "insecure_none" };
  }
  switch (policy.type) {
    case SandboxPolicy_Type.INSECURE_NONE:
    case SandboxPolicy_Type.UNSPECIFIED:
      return {
        type: "insecure_none",
        allowlistEscalated: policy.allowlistEscalated,
        enableSharedBuildCache: policy.enableSharedBuildCache,
        debugOutputDir: policy.debugOutputDir,
        captureDenies: policy.captureDenies,
      };
    case SandboxPolicy_Type.WORKSPACE_READWRITE:
      return {
        type: "workspace_readwrite",
        networkPolicy: resolveNetworkPolicy(policy),
        skipStatsigDefaults: policy.skipStatsigDefaults,
        additionalReadwritePaths: policy.additionalReadwritePaths,
        additionalReadonlyPaths: policy.additionalReadonlyPaths,
        disableTmpWrite: policy.disableTmpWrite,
        enableSharedBuildCache: policy.enableSharedBuildCache,
        debugOutputDir: policy.debugOutputDir,
        captureDenies: policy.captureDenies,
        networkPolicyStrict: policy.networkPolicyStrict,
        ...sandboxedProtoFields(policy),
      };
    case SandboxPolicy_Type.WORKSPACE_READONLY:
      return {
        type: "workspace_readonly",
        networkPolicy: resolveNetworkPolicy(policy),
        skipStatsigDefaults: policy.skipStatsigDefaults,
        additionalReadonlyPaths: policy.additionalReadonlyPaths,
        disableTmpWrite: policy.disableTmpWrite,
        enableSharedBuildCache: policy.enableSharedBuildCache,
        debugOutputDir: policy.debugOutputDir,
        captureDenies: policy.captureDenies,
        networkPolicyStrict: policy.networkPolicyStrict,
        ...sandboxedProtoFields(policy),
      };
    default:
      return { type: "insecure_none" };
  }
}

export function convertInternalToProtoPolicy(
  policy: InternalSandboxPolicy | undefined
): ProtoSandboxPolicy | undefined {
  if (!policy) return undefined;
  if (policy.type === "insecure_none") {
    return new ProtoSandboxPolicy({
      type: SandboxPolicy_Type.INSECURE_NONE,
      allowlistEscalated: policy.allowlistEscalated,
      enableSharedBuildCache: policy.enableSharedBuildCache,
      debugOutputDir: policy.debugOutputDir,
      captureDenies: policy.captureDenies,
    });
  }
  if (policy.type === "workspace_readwrite") {
    return new ProtoSandboxPolicy({
      type: SandboxPolicy_Type.WORKSPACE_READWRITE,
      networkAccess: isNetworkEnabledByPolicy(policy.networkPolicy),
      skipStatsigDefaults: policy.skipStatsigDefaults,
      additionalReadwritePaths: policy.additionalReadwritePaths ?? [],
      additionalReadonlyPaths: policy.additionalReadonlyPaths ?? [],
      disableTmpWrite: policy.disableTmpWrite,
      enableSharedBuildCache: policy.enableSharedBuildCache,
      debugOutputDir: policy.debugOutputDir,
      captureDenies: policy.captureDenies,
      networkPolicy: convertNetworkPolicyToProto(policy.networkPolicy),
      networkPolicyStrict: policy.networkPolicyStrict,
      readBoundary: convertReadBoundaryToProto(policy.readBoundary),
      additionalReadPaths:
        policy.readBoundary === "workspace"
          ? (policy.additionalReadPaths ?? [])
          : [],
    });
  }
  if (policy.type === "workspace_readonly") {
    return new ProtoSandboxPolicy({
      type: SandboxPolicy_Type.WORKSPACE_READONLY,
      networkAccess: isNetworkEnabledByPolicy(policy.networkPolicy),
      skipStatsigDefaults: policy.skipStatsigDefaults,
      additionalReadonlyPaths: policy.additionalReadonlyPaths ?? [],
      disableTmpWrite: policy.disableTmpWrite,
      enableSharedBuildCache: policy.enableSharedBuildCache,
      debugOutputDir: policy.debugOutputDir,
      captureDenies: policy.captureDenies,
      networkPolicy: convertNetworkPolicyToProto(policy.networkPolicy),
      networkPolicyStrict: policy.networkPolicyStrict,
      readBoundary: convertReadBoundaryToProto(policy.readBoundary),
      additionalReadPaths:
        policy.readBoundary === "workspace"
          ? (policy.additionalReadPaths ?? [])
          : [],
    });
  }
  return new ProtoSandboxPolicy({ type: SandboxPolicy_Type.INSECURE_NONE });
}

// ============================================================================
// SandboxPolicyMergeSources Conversion
// ============================================================================

export function convertProtoToMergeSources(
  sources?: ProtoSandboxPolicyMergeSources
): InternalSandboxPolicyMergeSources {
  if (!sources) {
    return {};
  }

  const result: InternalSandboxPolicyMergeSources = {};

  if (sources.perUser) {
    result.perUser = convertProtoToInternalPolicy(sources.perUser);
  }

  if (sources.perRepo) {
    result.perRepo = convertProtoToInternalPolicy(sources.perRepo);
  }

  if (sources.teamAdmin) {
    result.teamAdmin = convertProtoToInternalPolicy(sources.teamAdmin);
  }

  return result;
}

export function convertMergeSourcesToProto(
  sources?: InternalSandboxPolicyMergeSources
): ProtoSandboxPolicyMergeSources | undefined {
  if (!sources) return undefined;

  return new ProtoSandboxPolicyMergeSources({
    perUser: convertInternalToProtoPolicy(sources.perUser),
    perRepo: convertInternalToProtoPolicy(sources.perRepo),
    teamAdmin: convertInternalToProtoPolicy(sources.teamAdmin),
  });
}
