import { rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { findActualExecutable } from "@anysphere/utils";
import { spawnInSandbox } from "./sandbox/sandbox.js";
import type { IgnoreMapping, SandboxPolicy, TerminalEvent } from "./types.js";

const isWindows = process.platform === "win32";

/**
 * Network policy for controlling network access in sandboxed processes.
 * Used in tests to configure the sandbox's network filtering behavior.
 */
export interface NetworkPolicy {
  /** Policy version. Must be 1. */
  version: 1;
  /** Default action when no rules match. Defaults to "deny". */
  default?: "allow" | "deny";
  /** Enterprise-level policy controls */
  enterprise?: {
    /** Patterns to deny. Highest priority - always blocks. */
    deny?: string[];
    /** Patterns to allow. */
    allow?: string[];
  };
  /** User-level policy controls (can only restrict, not expand enterprise policy) */
  user?: {
    /** Patterns to allow (must be within enterprise allow scope). */
    allow?: string[];
  };
  /** Legacy format: top-level deny list (for backward compatibility) */
  deny?: string[];
  /** Legacy format: top-level allow list (for backward compatibility) */
  allow?: string[];
  /** Logging configuration. */
  logging?: {
    /** Path to write decision logs (JSONL format). */
    decisionLogPath?: string;
    /** Log format. Currently only "jsonl" is supported. */
    logFormat?: "jsonl";
  };
}

/**
 * Result from running a sandboxed command
 */
export interface SandboxedCommandResult {
  success: boolean;
  stdout: string;
  stderr: string;
  exitCode: number | null;
  signal: string | null;
  error?: string;
}

/**
 * Creates a temporary network policy file for testing.
 * @param policy - The network policy to write
 * @param testName - A name for the test (used in filename)
 * @returns Object with paths to the policy file and log file
 */
export function createNetworkPolicyFile(
  policy: NetworkPolicy,
  testName: string
): { policyPath: string; logPath: string } {
  const timestamp = Date.now();
  const policyPath = join(
    tmpdir(),
    `sandbox-test-policy-${testName}-${timestamp}.json`
  );
  const logPath = join(
    tmpdir(),
    `sandbox-network-decisions-${testName}-${timestamp}.log`
  );

  // Set the log path in the policy if logging is configured
  const policyWithLog: NetworkPolicy = {
    ...policy,
    logging: {
      ...policy.logging,
      decisionLogPath: logPath,
      logFormat: "jsonl",
    },
  };

  writeFileSync(policyPath, JSON.stringify(policyWithLog, null, 2), "utf-8");

  return { policyPath, logPath };
}

/**
 * Cleans up temporary policy and log files created by createNetworkPolicyFile.
 * @param policyPath - Path to the policy file
 * @param logPath - Path to the log file
 */
export function cleanupNetworkPolicyFiles(
  policyPath: string,
  logPath: string
): void {
  rmSync(policyPath, { force: true });
  rmSync(logPath, { force: true });
}

/**
 * Runs a command in the sandbox and returns the result.
 * @param command - The command to execute
 * @param args - Command arguments
 * @param sandboxPolicy - The sandbox policy to apply
 * @param options - Additional options
 * @returns Promise resolving to the command result
 */
export async function runSandboxedCommand(
  command: string,
  args: string[],
  sandboxPolicy: SandboxPolicy,
  options: {
    cwd?: string;
    timeout?: number;
    env?: NodeJS.ProcessEnv;
  } = {}
): Promise<SandboxedCommandResult> {
  return new Promise(resolve => {
    const child = spawnInSandbox(
      command,
      args,
      {
        cwd: options.cwd,
        stdio: ["pipe", "pipe", "pipe"],
        env: { ...process.env, ...options.env },
      },
      sandboxPolicy
    );

    let stdout = "";
    let stderr = "";

    child.stdout?.on("data", data => {
      stdout += data.toString();
    });

    child.stderr?.on("data", data => {
      stderr += data.toString();
    });

    child.on("error", error => {
      resolve({
        success: false,
        error: error.message,
        stdout,
        stderr,
        exitCode: null,
        signal: null,
      });
    });

    child.on("exit", (code, signal) => {
      resolve({
        success: code === 0,
        stdout,
        stderr,
        exitCode: code,
        signal: signal,
      });
    });

    // Timeout
    const timeout = setTimeout(() => {
      child.kill("SIGKILL");
      resolve({
        success: false,
        error: "Command timed out",
        stdout,
        stderr,
        exitCode: null,
        signal: "SIGKILL",
      });
    }, options.timeout || 30000);

    child.once("exit", () => {
      clearTimeout(timeout);
    });
  });
}

/**
 * Runs a shell command in the sandbox using the platform's shell.
 * @param shellCmd - The shell command to execute
 * @param sandboxPolicy - The sandbox policy to apply
 * @param options - Additional options
 * @returns Promise resolving to the command result
 */
export async function runSandboxedShellCommand(
  shellCmd: string,
  sandboxPolicy: SandboxPolicy,
  options: {
    cwd?: string;
    timeout?: number;
    env?: NodeJS.ProcessEnv;
  } = {}
): Promise<SandboxedCommandResult> {
  if (isWindows) {
    return runSandboxedCommand(
      "cmd.exe",
      ["/c", shellCmd],
      sandboxPolicy,
      options
    );
  }
  return runSandboxedCommand("sh", ["-c", shellCmd], sandboxPolicy, options);
}

/**
 * Gets the curl command for the current platform.
 * Uses findActualExecutable to locate the actual curl executable.
 * @returns The curl command path or name
 */
export function getCurlCommand(): string {
  const curlName = isWindows ? "curl.exe" : "curl";
  const result = findActualExecutable(curlName, []);
  return result.cmd;
}

// Helper function to collect all events from an async iterable
export async function collectEvents(
  iterable: AsyncIterable<TerminalEvent>
): Promise<TerminalEvent[]> {
  const events: TerminalEvent[] = [];

  for await (const event of iterable) {
    events.push(event);
  }
  return events;
}

// Helper function to check if a shell is available
export function isShellAvailable(shell: string): boolean {
  try {
    // findActualExecutable returns the original command name if not found,
    // or the full path if found
    const result = findActualExecutable(shell, []);
    return result.cmd !== shell;
  } catch {
    return false;
  }
}

// Helper to skip test if shell is not available
export function skipIfShellUnavailable(shell: string): void {
  if (!isShellAvailable(shell)) {
    console.log(`Skipping test - ${shell} not available`);
    return;
  }
}

/**
 * Helper function to create an IgnoreMapping from gitignore-style patterns
 * @param patterns Array of gitignore-style patterns
 * @param baseDir Base directory to apply the patterns to
 * @returns IgnoreMapping with the patterns stored as string arrays
 */
export function createIgnoreMapping(
  patterns: string[],
  baseDir: string
): IgnoreMapping {
  if (!patterns || patterns.length === 0) {
    return {};
  }

  // Filter out empty strings, whitespace-only strings, and comments
  const validPatterns = patterns
    .map(pattern => pattern.trim())
    .filter(pattern => pattern !== "" && !pattern.startsWith("#"));

  if (validPatterns.length === 0) {
    return {};
  }

  // Store patterns as string array (parsed lazily when needed)
  return {
    [baseDir]: validPatterns,
  };
}
