import {
  ShellPermissionDenied,
  ShellRejected,
} from "@anysphere/proto/agent/v1/shell_exec_pb.js";
import { formatAdminCommandDenylistBlockReason } from "../services/admin-command-denylist.js";
import type {
  ApprovalDetails,
  BlockReason,
} from "../services/permissions-service.js";

export type BlockHandlerCallbacks<TResult> = {
  onNeedsApproval: (
    approvalReason: string,
    approvalDetails: ApprovalDetails
  ) => Promise<TResult | null>; // null means continue with operation
  onUserRejected: (reason?: string) => TResult;
  onPermissionDenied: (
    errorMessage: string,
    options?: { isReadonly?: boolean }
  ) => TResult;
};

/**
 * Handles block reasons from the permissions service in a consistent way.
 * Returns a result to be returned from the executor, or null to continue with the operation.
 */
export async function handleBlockReason<TResult>(
  blockReason: BlockReason,
  callbacks: BlockHandlerCallbacks<TResult>
): Promise<TResult | null> {
  switch (blockReason.type) {
    case "needsApproval":
      return callbacks.onNeedsApproval(
        blockReason.approvalReason,
        blockReason.approvalDetails
      );

    case "userRejected":
      return callbacks.onUserRejected(blockReason.reason);

    case "cursorIgnore":
      return callbacks.onPermissionDenied("Blocked by cursor ignore");

    case "permissionsConfig":
      return callbacks.onPermissionDenied(
        "Blocked by permissions configuration",
        { isReadonly: blockReason.isReadonly }
      );

    case "cursorFiles":
      return callbacks.onPermissionDenied("Blocked by cursor files protection");

    case "adminBlock":
      return callbacks.onPermissionDenied("Blocked by admin repository block");

    case "adminCommandDenylist":
      return callbacks.onPermissionDenied(
        formatAdminCommandDenylistBlockReason(blockReason.pattern)
      );

    case "unsafeResolution":
      return callbacks.onPermissionDenied(blockReason.message);

    default: {
      const _exhaustive: never = blockReason;
      throw new Error(
        `Unhandled block reason type: ${JSON.stringify(_exhaustive)}`
      );
    }
  }
}

/**
 * Extract a human-readable rejection message from a BlockReason for shell
 * command rejections. Uses an exhaustive switch so new BlockReason variants
 * cause a compile error rather than silently falling through.
 */
export function shellBlockReasonMessage(
  reason: BlockReason
): string | undefined {
  switch (reason.type) {
    case "userRejected":
      return reason.reason;
    case "unsafeResolution":
      return reason.message;
    case "adminCommandDenylist":
      return formatAdminCommandDenylistBlockReason(reason.pattern);
    case "needsApproval":
    case "cursorIgnore":
    case "adminBlock":
    case "permissionsConfig":
    case "cursorFiles":
      return "Command is not allowed";
    default: {
      const _exhaustive: never = reason;
      return `Command is not allowed (${JSON.stringify(_exhaustive)})`;
    }
  }
}

/** Shared shell rejection shape for sync and background spawn results. */
export type ShellCommandBlockResult =
  | {
      case: "permissionDenied";
      value: ShellPermissionDenied;
    }
  | {
      case: "rejected";
      value: ShellRejected;
    };

/**
 * Map a permissions BlockReason to the shell executor rejection payload used
 * by both the approval path and the skipApproval invariant path.
 */
export function shellCommandBlockResult(
  command: string,
  workingDirectory: string,
  reason: BlockReason
): ShellCommandBlockResult {
  if (reason.type === "permissionsConfig" && (reason.isReadonly ?? false)) {
    return {
      case: "permissionDenied",
      value: new ShellPermissionDenied({
        command,
        workingDirectory,
        error: "Command blocked by permissions configuration",
        isReadonly: true,
      }),
    };
  }
  return {
    case: "rejected",
    value: new ShellRejected({
      command,
      workingDirectory,
      reason: shellBlockReasonMessage(reason),
    }),
  };
}
