import { randomUUID } from "node:crypto";
import { createWriteStream, type WriteStream } from "node:fs";
import { mkdir } from "node:fs/promises";
import path from "node:path";
import type { Writable } from "node:stream";
import {
  AGENT_TOOLS_DIR,
  MAX_OUTPUT_FILE_SIZE,
} from "@anysphere/agent-exec/node";
import { type Context, createLogger, createSpan } from "@anysphere/context";
import { OutputLocation } from "@anysphere/proto/agent/v1/utils_pb.js";
import {
  getSandboxPolicyType,
  INSECURE_NONE_SANDBOX_POLICY,
  type SandboxDenyEvent,
  type SandboxPolicy,
  type SandboxPolicyMergeSources,
  SHELL_OUTPUT_SUPPRESSED_NOTICE,
  type ShellOutputLimiterOptions,
  type TerminalExecutor,
} from "@anysphere/shell-exec";
import { getSafeConversationId, TRANSCRIPTS_SUBDIR } from "@anysphere/utils";
import { resolvePath } from "./common.js";
import { MAX_BUFFER_SIZE } from "./constants.js";
import type { ShellEmitter, ShellManager } from "./shell-manager.js";

const logger = createLogger("local-exec:shell-core");

// Windows uses UAC dialogs for elevation, not SUDO_ASKPASS
const isWindows = process.platform === "win32";

const REQUEST_SCOPED_SHELL_ENV_KEYS = [
  "CURSOR_CONVERSATION_ID",
  "CURSOR_AGENT_STORE_FILES_DIR",
  "CURSOR_AGENT_STORE_SHARED_PATHS",
] as const;

function shellSingleQuote(value: string): string {
  return `'${value.replace(/'/g, "'\\''")}'`;
}

function getEffectiveShellEnvValue(
  env: Record<string, string>,
  key: string
): string | undefined {
  return env[key] ?? process.env[key];
}

function appendRequestScopedEnvRestore(env: Record<string, string>): void {
  const restoreParts = [
    `builtin unset ${REQUEST_SCOPED_SHELL_ENV_KEYS.join(" ")} 2>/dev/null || true`,
  ];
  for (const key of REQUEST_SCOPED_SHELL_ENV_KEYS) {
    const value = getEffectiveShellEnvValue(env, key);
    if (value !== undefined) {
      restoreParts.push(`builtin export ${key}=${shellSingleQuote(value)}`);
    }
  }
  const requestScopedRestore = restoreParts.join("; ");
  const existingRestore = env.__CURSOR_SANDBOX_ENV_RESTORE?.trim();
  const processRestore = process.env.__CURSOR_SANDBOX_ENV_RESTORE?.trim();
  env.__CURSOR_SANDBOX_ENV_RESTORE = [
    processRestore,
    existingRestore,
    requestScopedRestore,
  ]
    .filter((part): part is string => part !== undefined && part !== "")
    .join("; ");
}

/**
 * Event types emitted by the shell core executor
 */
export type ShellCoreEvent =
  | { type: "start"; sandboxed: boolean }
  | { type: "stdin_ready"; stdin?: Writable; pid?: number }
  | { type: "stdout"; data: string }
  | { type: "stderr"; data: string }
  | { type: "stdout_trimmed" }
  | { type: "stderr_trimmed" }
  | {
      type: "exit";
      code: number | null;
      aborted: boolean;
      outputLocation?: OutputLocation;
      localExecutionTimeMs?: number;
    }
  | { type: "sandbox_denies"; events: SandboxDenyEvent[] };

/**
 * Configuration for sudo askpass support.
 */
export interface AskpassConfig {
  /** Path to the Unix socket for IPC with the askpass server */
  socketPath: string;
  /** Path to the cursor-askpass helper executable */
  helperPath: string;
  /** Shared secret for HMAC-SHA256 authentication (hex-encoded) */
  secret: string;
}

/**
 * Terminal output buffering options applied by the underlying shell executor.
 */
export interface ShellOutputBackpressureOptions {
  bufferOutputEvents?: boolean;
  outputLimiterOptions?: ShellOutputLimiterOptions;
}

export type ShellExtraEnvProvider = (
  ctx: Context,
  args: ShellCoreArgs
) => Record<string, string> | undefined;

function appendUnique(
  paths: string[] | undefined,
  pathToAdd: string
): string[] {
  const next = paths === undefined ? [] : [...paths];
  if (!next.includes(pathToAdd)) {
    next.push(pathToAdd);
  }
  return next;
}

function agentStoreSandboxPolicyFromEnv(
  policy: SandboxPolicyMergeSources | undefined,
  env: Record<string, string>
): SandboxPolicyMergeSources | undefined {
  const filesDir = getEffectiveShellEnvValue(
    env,
    "CURSOR_AGENT_STORE_FILES_DIR"
  );
  const sharedPaths = parseAgentStoreSharedPathsEnv(
    getEffectiveShellEnvValue(env, "CURSOR_AGENT_STORE_SHARED_PATHS")
  );
  if (filesDir === undefined && sharedPaths.length === 0) {
    return policy;
  }

  const existingPerUser = policy?.perUser;
  const referencePolicy =
    policy?.perRepo ?? policy?.perUser ?? policy?.teamAdmin;
  if (
    referencePolicy?.type !== "workspace_readwrite" &&
    referencePolicy?.type !== "workspace_readonly"
  ) {
    return policy;
  }
  const perUser: SandboxPolicy =
    existingPerUser?.type === referencePolicy.type
      ? { ...existingPerUser }
      : { type: referencePolicy.type };
  const addSelfStorePath = (pathToAdd: string): void => {
    if (perUser.type === "workspace_readwrite") {
      perUser.additionalReadwritePaths = appendUnique(
        perUser.additionalReadwritePaths,
        pathToAdd
      );
      return;
    }
    perUser.additionalReadonlyPaths = appendUnique(
      perUser.additionalReadonlyPaths,
      pathToAdd
    );
  };
  if (filesDir !== undefined) {
    addSelfStorePath(filesDir);
  }
  for (const entry of sharedPaths) {
    if (!entry.readOnly && perUser.type === "workspace_readwrite") {
      perUser.additionalReadwritePaths = appendUnique(
        perUser.additionalReadwritePaths,
        entry.path
      );
      continue;
    }
    perUser.additionalReadonlyPaths = appendUnique(
      perUser.additionalReadonlyPaths,
      entry.path
    );
  }
  return { ...policy, perUser };
}

function parseAgentStoreSharedPathsEnv(
  value: string | undefined
): Array<{ path: string; readOnly: boolean }> {
  if (value === undefined) {
    return [];
  }
  try {
    const parsed: unknown = JSON.parse(value);
    if (typeof parsed !== "object" || parsed === null) {
      return [];
    }
    const out: Array<{ path: string; readOnly: boolean }> = [];
    for (const entry of Object.values(parsed)) {
      if (
        typeof entry === "object" &&
        entry !== null &&
        "path" in entry &&
        "readOnly" in entry &&
        typeof entry.path === "string" &&
        typeof entry.readOnly === "boolean"
      ) {
        out.push({ path: entry.path, readOnly: entry.readOnly });
      }
    }
    return out;
  } catch {
    return [];
  }
}

/**
 * Arguments for shell core execution
 */
export interface ShellCoreArgs {
  command: string;
  workingDirectory?: string;
  signal?: AbortSignal;
  toolCallId?: string;
  sandboxPolicy?: SandboxPolicyMergeSources;
  /** When true and running under a sandbox policy, emit a sandbox_denies event after exit */
  captureSandboxDenies?: boolean;
  /** If output size exceeds this threshold (in bytes), write to file. If unset or 0, always use inline. */
  fileOutputThresholdBytes?: bigint;
  pipeStdin?: boolean;
  /** When true, include elapsed time in terminal output on exit (feature flag gated) */
  showElapsedTime?: boolean;
  /** Configuration for sudo askpass support. When set, SUDO_ASKPASS env vars are configured. */
  askpassConfig?: AskpassConfig;
  /** Conversation ID for the current turn. Exposed to shell env in filesystem-safe form. */
  conversationId?: string;
}

/**
 * Interface for shell core execution functionality
 */
export interface ShellCoreExecutor {
  /**
   * Execute a shell command and yield events for stdout, stderr, trimming, and exit
   */
  execute(ctx: Context, args: ShellCoreArgs): AsyncIterable<ShellCoreEvent>;

  /**
   * Get the current working directory from the underlying executor
   */
  getCwd(): Promise<string>;

  /**
   * Get the workspace root path
   */
  getWorkspacePath(): string;
}

/**
 * Core shell executor that wraps a terminal executor and provides
 * common functionality for both streaming and non-streaming execution.
 *
 * This class handles:
 * - Working directory resolution
 * - Output buffering with size limits
 * - Event emission for stdout, stderr, trimming, and exit
 */
export class BaseShellCoreExecutor implements ShellCoreExecutor {
  constructor(
    private executor: TerminalExecutor,
    private workspacePath?: string,
    private projectDir?: string,
    private shellOutputBackpressureOptions?:
      | ShellOutputBackpressureOptions
      | undefined,
    private extraEnvProvider?: ShellExtraEnvProvider | undefined
  ) {}

  /**
   * Execute a shell command and yield events for stdout, stderr, trimming, and exit
   */
  async *execute(
    ctx: Context,
    args: ShellCoreArgs
  ): AsyncIterable<ShellCoreEvent> {
    using _span = createSpan(ctx.withName("ShellCoreExecutor.execute"));
    const startMonotonicMs = performance.now();

    // NOTE: sudo -A transformation is now handled by shell-exec runners directly.
    // Bash/zsh runners inject an alias (sudo='sudo -A'), while the naive runner
    // transforms the command string. The SUDO_ASKPASS env var signals this.
    const workingDirectory =
      args.workingDirectory || (await this.executor.getCwd());
    const resolvedWorkingDir = resolvePath(
      workingDirectory,
      this.workspacePath
    );

    let stdoutSize = 0;
    let stderrSize = 0;
    let stdoutTrimmed = false;
    let stderrTrimmed = false;
    let suppressionNoticeSent = false;
    let mergedOutput:
      | {
          file?: WriteStream;
          buffer: string;
          size: number;
          path?: string;
          lineCount: number;
          threshold: number;
        }
      | undefined;
    if (args.fileOutputThresholdBytes && this.projectDir) {
      mergedOutput = {
        buffer: "",
        lineCount: 0,
        size: 0,
        threshold: Number(args.fileOutputThresholdBytes),
      };
    }

    // Use the provided signal or fall back to the context signal
    const signal = args.signal;

    // Build environment variables, including askpass config if provided
    // Skip SUDO_ASKPASS on Windows - sudo.exe uses UAC dialogs
    const env: Record<string, string> = {
      CURSOR_AGENT: "1",
    };
    if (args.conversationId) {
      env.CURSOR_CONVERSATION_ID = getSafeConversationId(args.conversationId);
    }
    if (this.projectDir) {
      env.AGENT_TRANSCRIPTS = path.join(this.projectDir, TRANSCRIPTS_SUBDIR);
    }
    const extraEnv = this.extraEnvProvider?.(ctx, args);
    if (extraEnv !== undefined) {
      Object.assign(env, extraEnv);
    }
    appendRequestScopedEnvRestore(env);
    const sandboxPolicy = agentStoreSandboxPolicyFromEnv(
      args.sandboxPolicy,
      env
    );
    const policyType = getSandboxPolicyType(
      sandboxPolicy ?? INSECURE_NONE_SANDBOX_POLICY
    );
    if (sandboxPolicy) {
      yield {
        type: "start",
        sandboxed:
          policyType === "workspace_readonly" ||
          policyType === "workspace_readwrite",
      };
    }
    if (args.askpassConfig && !isWindows) {
      env.SUDO_ASKPASS = args.askpassConfig.helperPath;
      env.CURSOR_ASKPASS_SOCKET = args.askpassConfig.socketPath;
      env.CURSOR_ASKPASS_SECRET = args.askpassConfig.secret;
    }

    let dataSize = 0;
    let outputData = "";
    for await (const event of this.executor.execute(ctx, args.command, {
      signal,
      workingDirectory: resolvedWorkingDir,
      env,
      sandboxPolicy,
      sandboxWorkspaceRoot: this.workspacePath,
      pipeStdin: args.pipeStdin ?? false,
      bufferOutputEvents:
        this.shellOutputBackpressureOptions?.bufferOutputEvents,
      outputLimiterOptions:
        this.shellOutputBackpressureOptions?.outputLimiterOptions,
    })) {
      dataSize = 0;
      outputData = "";
      if (event.type === "stdout" || event.type === "stderr") {
        outputData = event.data.toString();
        dataSize = event.data.length;
        if (mergedOutput) {
          mergedOutput.size += dataSize;
          mergedOutput.lineCount += outputData.split("\n").length - 1;
          if (mergedOutput.size > MAX_OUTPUT_FILE_SIZE) {
            // We've exceeded allowed file size, so just drop.
          } else if (mergedOutput.file) {
            mergedOutput.file.write(outputData);
          } else {
            // Not met threshold yet, so just buffer.
            mergedOutput.buffer += outputData;
            if (mergedOutput.size > mergedOutput.threshold) {
              const agentToolsDir = path.join(
                this.projectDir!,
                AGENT_TOOLS_DIR
              );
              mergedOutput.path = path.join(
                agentToolsDir,
                `${randomUUID()}.txt`
              );
              await mkdir(path.dirname(mergedOutput.path), { recursive: true });
              mergedOutput.file = createWriteStream(mergedOutput.path);
              mergedOutput.file.write(mergedOutput.buffer);
              mergedOutput.buffer = "";
            }
          }
        }
      }
      switch (event.type) {
        case "stdout": {
          if (!stdoutTrimmed) {
            if (stdoutSize + dataSize > MAX_BUFFER_SIZE) {
              stdoutTrimmed = true;
              yield { type: "stdout_trimmed" };
            } else {
              stdoutSize += dataSize;
              yield { type: "stdout", data: outputData };
            }
          }
          break;
        }
        case "suppressed_output": {
          if (!suppressionNoticeSent) {
            suppressionNoticeSent = true;
            yield {
              type: "stdout",
              data: SHELL_OUTPUT_SUPPRESSED_NOTICE,
            };
          }
          break;
        }
        case "stderr": {
          if (!stderrTrimmed) {
            if (stderrSize + dataSize > MAX_BUFFER_SIZE) {
              stderrTrimmed = true;
              yield { type: "stderr_trimmed" };
            } else {
              stderrSize += dataSize;
              yield { type: "stderr", data: outputData };
            }
          }
          break;
        }
        case "exit": {
          const localExecutionTimeMs = Math.max(
            0,
            Math.round(performance.now() - startMonotonicMs)
          );
          let outputLocation: OutputLocation | undefined;
          if (mergedOutput?.file) {
            await new Promise(resolve => mergedOutput.file!.end(resolve));
            outputLocation = new OutputLocation({
              filePath: mergedOutput.path!,
              sizeBytes: BigInt(mergedOutput.size),
              lineCount: BigInt(mergedOutput.lineCount),
            });
          }
          yield {
            type: "exit",
            code: event.code,
            aborted: event.aborted,
            outputLocation,
            localExecutionTimeMs,
          };
          break;
        }
        case "stdin_ready": {
          yield { type: "stdin_ready", stdin: event.stdin, pid: event.pid };
          break;
        }
        case "sandbox_denies": {
          yield { type: "sandbox_denies", events: event.events };
          break;
        }
      }
    }
  }

  /**
   * Get the current working directory from the underlying executor
   */
  async getCwd(): Promise<string> {
    return this.executor.getCwd();
  }

  /**
   * Get the workspace root path
   */
  getWorkspacePath(): string {
    if (!this.workspacePath) {
      throw new Error("Workspace path is not configured");
    }
    return this.workspacePath;
  }
}

/**
 * Shell core executor that wraps around an inner ShellCoreExecutor and integrates
 * with the ShellManager to emit events for UI updates.
 *
 * This class handles:
 * - Delegating execution to the inner executor
 * - Creating shell emitters for each execution with a toolCallId
 * - Converting ShellCoreEvents to ShellManagerEvents and emitting them
 * - Passing through all events from the inner executor unchanged
 */
export class ManagedShellCoreExecutor implements ShellCoreExecutor {
  constructor(
    private innerExecutor: ShellCoreExecutor,
    private shellManager: ShellManager
  ) {}

  /**
   * Execute a shell command through the inner executor and emit events to the shell manager
   */
  async *execute(
    ctx: Context,
    args: ShellCoreArgs
  ): AsyncIterable<ShellCoreEvent> {
    using _span = createSpan(ctx.withName("ManagedShellCoreExecutor.execute"));

    logger.info(ctx, "Executing shell command", {
      command: args.command,
      workingDirectory: args.workingDirectory,
      toolCallId: args.toolCallId,
    });

    // Create shell emitter if toolCallId is provided
    let shellEmitter: ShellEmitter | null = null;
    if (args.toolCallId) {
      shellEmitter = this.shellManager.getOrCreateShellEmitter(args.toolCallId);
    }

    // Execute through the inner executor and emit events
    for await (const event of this.innerExecutor.execute(ctx, args)) {
      // Emit to shell manager if we have an emitter
      if (shellEmitter) {
        switch (event.type) {
          case "stdin_ready":
            shellEmitter.emit({
              type: "stdin_ready",
              stdin: event.stdin,
              pid: event.pid,
            });
            break;
          case "start":
            shellEmitter.emit({ type: "start", sandboxed: event.sandboxed });
            break;
          case "stdout":
            shellEmitter.emit({ type: "stdout", data: event.data });
            break;
          case "stderr":
            shellEmitter.emit({ type: "stderr", data: event.data });
            break;
          case "exit":
            // When killed by signal, code may be null - use -1 as sentinel
            shellEmitter.emit({
              type: "exit",
              code: event.code ?? -1,
              aborted: event.aborted,
            });
            break;
          // stdout_trimmed and stderr_trimmed events don't need to be emitted to shell manager
          // as they are informational events for the caller
        }
      }

      // Always yield the original event
      yield event;
    }
  }

  /**
   * Get the current working directory from the inner executor
   */
  async getCwd(): Promise<string> {
    return this.innerExecutor.getCwd();
  }

  /**
   * Get the workspace root path from the inner executor
   */
  getWorkspacePath(): string {
    return this.innerExecutor.getWorkspacePath();
  }
}

/**
 * Shell core executor wrapper that injects askpass configuration into every execution.
 *
 * This enables sudo password prompts to be handled through the askpass mechanism,
 * where sudo calls a helper script that communicates with agent-cli to get the
 * password from the user without the model ever seeing it.
 */
export class AskpassShellCoreExecutor implements ShellCoreExecutor {
  constructor(
    private innerExecutor: ShellCoreExecutor,
    private askpassConfig: AskpassConfig
  ) {}

  /**
   * Execute a shell command with askpass environment variables injected.
   */
  async *execute(
    ctx: Context,
    args: ShellCoreArgs
  ): AsyncIterable<ShellCoreEvent> {
    // Inject askpassConfig into args, preserving any existing config
    const argsWithAskpass: ShellCoreArgs = {
      ...args,
      askpassConfig: args.askpassConfig ?? this.askpassConfig,
    };

    yield* this.innerExecutor.execute(ctx, argsWithAskpass);
  }

  /**
   * Get the current working directory from the inner executor
   */
  async getCwd(): Promise<string> {
    return this.innerExecutor.getCwd();
  }

  /**
   * Get the workspace root path from the inner executor
   */
  getWorkspacePath(): string {
    return this.innerExecutor.getWorkspacePath();
  }
}
