/**
 * On-disk MCP catalog layout written by {@link McpFileSystemWriter} in local-exec.
 * Kept in agent-exec so tooling and the IDE share one contract.
 */
export const MCP_DISK_CATALOG_MCPS_DIR = "mcps";
export const MCP_DISK_CATALOG_TOOLS_DIR = "tools";
/**
 * Parse `name` / `toolName` from a `.json` tool definition file on disk.
 */
export function parseMcpToolNameFromDiskDefinitionJson(jsonText) {
    try {
        const parsed = JSON.parse(jsonText);
        if (typeof parsed.name === "string" && parsed.name.length > 0) {
            return parsed.name;
        }
        if (typeof parsed.toolName === "string" && parsed.toolName.length > 0) {
            return parsed.toolName;
        }
        return undefined;
    }
    catch (_a) {
        return undefined;
    }
}
