/**
 * Builds a SandboxPolicy for local MCP server subprocesses when MCP
 * Network Controls are enabled. Merges the MCP network allowlist with
 * the hardcoded agent security invariants (.git write protection, SSL
 * cert readonly paths, SSH key readonly paths).
 *
 * TODO: workspaceDir should ideally be the actual workspace root from
 * workspace folders, not the MCP server's cwd. Currently the caller
 * passes effectiveCwd which may be server-controlled.
 */
import {
  type McpNetworkControlsConfig,
  normalizeMcpNetworkAllowlistPattern,
} from "./mcp-url-utils.js";

const PROXY_MEDIATED_ALLOW_ALL = ["0.0.0.0/0", "::/0"] as const;

interface NormalizedNetworkList {
  readonly hasConfiguredEntries: boolean;
  readonly hasInvalidEntries: boolean;
  readonly entries: string[];
}

function normalizeNetworkList(
  entries: readonly string[] | undefined
): NormalizedNetworkList {
  const configuredEntries = (entries ?? []).filter(entry => entry.trim().length > 0);
  const normalizedEntries = configuredEntries.flatMap(entry => {
    const normalized = normalizeMcpNetworkAllowlistPattern(entry);
    return normalized === undefined ? [] : [normalized];
  });

  return {
    hasConfiguredEntries: configuredEntries.length > 0,
    hasInvalidEntries: normalizedEntries.length !== configuredEntries.length,
    entries: normalizedEntries,
  };
}

function getSandboxAllowlistEntries(allowlist: NormalizedNetworkList): string[] {
  return allowlist.entries.includes("*")
    ? [...PROXY_MEDIATED_ALLOW_ALL]
    : allowlist.entries;
}

function buildMcpNetworkPolicy(
  config: McpNetworkControlsConfig
): import("@anysphere/shell-exec").NetworkPolicy {
  const allowlist = normalizeNetworkList(config.mcpNetworkAllowlist);
  const denylist = normalizeNetworkList(config.mcpNetworkDenylist);
  const mode = config.mcpNetworkMode;

  // `*` in the user-extension denylist means deny all network egress.
  if (
    mode === "deny_all" ||
    denylist.entries.includes("*") ||
    denylist.hasInvalidEntries
  ) {
    return { version: 1, default: "deny" };
  }

  if (mode === "allow_all") {
    return {
      version: 1,
      default: "deny",
      allow: [...PROXY_MEDIATED_ALLOW_ALL],
      ...(denylist.entries.length > 0 ? { deny: denylist.entries } : {}),
    };
  }

  if (mode === "allowlist" || allowlist.hasConfiguredEntries) {
    const sandboxAllowlist = getSandboxAllowlistEntries(allowlist);
    return sandboxAllowlist.length > 0
      ? {
          version: 1,
          default: "deny",
          allow: sandboxAllowlist,
          ...(denylist.entries.length > 0 ? { deny: denylist.entries } : {}),
        }
      : { version: 1, default: "deny" };
  }

  return {
    version: 1,
    default: "deny",
    allow: [...PROXY_MEDIATED_ALLOW_ALL],
    ...(denylist.entries.length > 0 ? { deny: denylist.entries } : {}),
  };
}

export async function buildMcpSandboxPolicy(
  config: McpNetworkControlsConfig,
  workspaceDir: string
): Promise<import("@anysphere/shell-exec").SandboxPolicy> {
  const { resolveSandboxPolicyForWorkspace } = await import(
    "@anysphere/shell-exec"
  );
  const mcpNetworkPolicy: import("@anysphere/shell-exec").WorkspaceReadWriteSandboxPolicy = {
    type: "workspace_readwrite",
    sandboxWorkspaceRoot: workspaceDir,
    // Keep command MCPs sandboxed while allowing default egress through the
    // network proxy unless an admin/user-extension deny pattern closes it.
    networkPolicy: buildMcpNetworkPolicy(config),
    networkPolicyStrict: true,
  };

  const { policy } = await resolveSandboxPolicyForWorkspace(workspaceDir, {
    perUser: mcpNetworkPolicy,
  });
  return policy;
}
