import { realpath } from "node:fs/promises";
import { basename, dirname, isAbsolute, join, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";

import { findSystemErrno } from "../system-errno.js";

export interface PathWithinOptions {
	// The call sites genuinely disagree on whether child===parent is "within"
	// (a protected-root guard denies the root itself; an attachment read-guard
	// wants proper nesting), so the boundary is explicit, never accidental.
	// Defaults to exclusive.
	readonly isInclusive?: boolean;
}

// The one canonical containment check, segment-aware so a sibling sharing a
// string prefix is never inside (`/x/sand-data` does not contain
// `/x/sand-data-evil` — the old raw prefix check's bug).
export function isPathWithin(parent: string, child: string, opts: PathWithinOptions = {}): boolean {
	const rel = relative(resolve(parent), resolve(child));
	if (rel === "") return opts.isInclusive ?? false;
	return !rel.startsWith("..") && !isAbsolute(rel);
}

// The single converter shared by the brain and the desktop transcript manager,
// so a `file://` attachment maps to disk identically on both sides.
export function filePathFromFileUrl(rawUrl: string): string | null {
	try {
		const url = new URL(rawUrl);
		if (url.protocol !== "file:") return null;
		return fileURLToPath(url);
	} catch {
		return null;
	}
}

// For box-bound paths: the box filesystem is POSIX whatever the desktop runs
// on, and on Windows `filePathFromFileUrl` mints `\` separators — and Node
// rejects a drive-letterless win32 file URL outright — so a box-bound caller
// asks for this spelling. Identical to `filePathFromFileUrl` on Linux/macOS.
export function posixPathFromFileUrl(rawUrl: string): string | null {
	try {
		const url = new URL(rawUrl);
		if (url.protocol !== "file:") return null;
		return decodeURIComponent(url.pathname);
	} catch {
		return null;
	}
}

// Symlink-safe containment: lexical check first, then re-checked after
// resolving symlinks on the nearest existing ancestors of target and roots, so
// a symlink inside the sandbox cannot point the read/write outside it. This is
// the gate for every auto-approved MODEL-SUPPLIED host path — those tools get
// no per-path ask card, so an uncontained read is an arbitrary-file-read and
// exfiltration primitive.
export async function containWithin(roots: readonly string[], p: string): Promise<string | null> {
	// A model-supplied relative path would resolve against the host process
	// cwd, outside the agent's sandbox.
	if (typeof p !== "string" || p.length === 0 || !isAbsolute(p)) return null;
	const resolved = resolve(p);
	if (!roots.some((root) => isPathWithin(root, resolved))) return null;
	const [realResolved, realRoots] = await Promise.all([
		realpathNearestExisting(resolved),
		Promise.all(roots.map((root) => realpathNearestExisting(root))),
	]);
	if (!realRoots.some((root) => isPathWithin(root, realResolved))) return null;
	return resolved;
}

// realpath the deepest existing ancestor, then re-append the missing tail, so
// a symlink anywhere on the path resolves even when the leaf does not exist
// yet. The single symlink-safe containment primitive shared by the desktop
// local-exec provider and the protected-path guard.
export async function realpathNearestExisting(p: string): Promise<string> {
	const missing: string[] = [];
	let current = p;
	for (;;) {
		try {
			const real = await realpath(current);
			return missing.length === 0 ? real : join(real, ...missing.reverse());
		} catch (error) {
			if (findSystemErrno(error) !== "ENOENT") throw error;
			const parent = dirname(current);
			if (parent === current) return p;
			missing.push(basename(current));
			current = parent;
		}
	}
}
