import { createValidationResult, validateOptionalString, } from "./base.js";
import { validateBaseHookResponse } from "./baseHookResponse.js";
export const validatePostToolUseResponse = (value) => {
    const errors = [];
    // First validate base response
    const base = validateBaseHookResponse(value);
    if (!base.isValid) {
        return base;
    }
    validateOptionalString(value.additional_context, "additional_context", errors);
    return createValidationResult(errors.length === 0, errors);
};
