import { join } from "node:path";
import type { AgentSkill } from "@anysphere/proto/agent/v1/agent_skills_pb.js";

import {
  getBuiltinExtensibilitySkillRoot,
  getProjectExtensibilitySkillRoots,
  getUserExtensibilitySkillRoots,
} from "./skill-discovery.js";

/** Paths passed to {@link sortAgentSkillsForPromptOrder}. */
export interface AgentSkillsPromptSortContext {
  readonly workspacePaths: readonly string[];
  readonly userHomeDirectory: string;
}

function normalizeFsPath(p: string): string {
  return p.replace(/\\/g, "/");
}

function isUnderAnyDir(pathNorm: string, dirs: readonly string[]): boolean {
  for (const d of dirs) {
    const dir = normalizeFsPath(d);
    if (pathNorm === dir || pathNorm.startsWith(`${dir}/`)) {
      return true;
    }
  }
  return false;
}

function isPluginSkill(skill: AgentSkill): boolean {
  return Boolean(
    skill.plugin?.trim() ||
      skill.pluginId?.trim() ||
      skill.marketplaceId?.trim()
  );
}

enum SkillPromptTier {
  Builtin = 0,
  UserHome = 1,
  Workspace = 2,
  Plugin = 3,
}

function buildPromptSortPrefixes(ctx: AgentSkillsPromptSortContext): {
  builtinDirs: string[];
  userDirs: string[];
  workspaceDirs: string[];
} {
  const builtinDirs = [
    getBuiltinExtensibilitySkillRoot(ctx.userHomeDirectory).dirPath,
  ];

  const userDirs = getUserExtensibilitySkillRoots(
    ctx.userHomeDirectory,
    true
  ).map(r => r.dirPath);

  const workspaceDirs: string[] = [];
  for (const ws of ctx.workspacePaths) {
    workspaceDirs.push(join(ws, ".cursor", "rules"));
    for (const root of getProjectExtensibilitySkillRoots(ws, true)) {
      workspaceDirs.push(root.dirPath);
    }
  }

  return { builtinDirs, userDirs, workspaceDirs };
}

function tierForSkill(
  skill: AgentSkill,
  prefixes: ReturnType<typeof buildPromptSortPrefixes>
): SkillPromptTier {
  if (isPluginSkill(skill)) {
    return SkillPromptTier.Plugin;
  }
  const pathNorm = normalizeFsPath(skill.fullPath);

  if (isUnderAnyDir(pathNorm, prefixes.builtinDirs)) {
    return SkillPromptTier.Builtin;
  }
  if (isUnderAnyDir(pathNorm, prefixes.userDirs)) {
    return SkillPromptTier.UserHome;
  }
  if (isUnderAnyDir(pathNorm, prefixes.workspaceDirs)) {
    return SkillPromptTier.Workspace;
  }
  return SkillPromptTier.Workspace;
}

/**
 * Stable ordering for merged agent skills in the prompt catalog:
 * builtin → user home → workspace → plugins.
 */
export function sortAgentSkillsForPromptOrder(
  skills: AgentSkill[],
  ctx: AgentSkillsPromptSortContext
): AgentSkill[] {
  if (skills.length <= 1) {
    return skills;
  }

  const prefixes = buildPromptSortPrefixes(ctx);
  const decorated = skills.map((skill, index) => ({
    skill,
    index,
    tier: tierForSkill(skill, prefixes),
  }));
  decorated.sort((a, b) => a.tier - b.tier || a.index - b.index);
  return decorated.map(d => d.skill);
}
