const PDF_EXTENSION: string = ".pdf";
const STREAMING_READ_CHUNK_BYTES: number = 64 * 1024;
const MAX_FILE_ENCODINGS = 100;

const logger = createLogger("LocalReadExecutor");

const watchdog = async <R>(
  ctx: Context,
  msg: string,
  ms: number,
  f: () => R | Promise<R>
): Promise<R> => {
  const timeout = setTimeout(() => {
    logger.warn(
      ctx,
      `[watchdog, LocalReadExecutor] ${msg} still not completed after ${ms}ms`
    );
  }, ms);
  try {
    return await f();
  } finally {
    clearTimeout(timeout);
  }
};

function isPdfFilePath(filePath: string): boolean {
  return extname(filePath).toLowerCase() === PDF_EXTENSION;
}

/**
 * Locate the byte offset just past the closing `\n---\n` of a Cursor terminal
 * file's YAML frontmatter. Returns 0 if the buffer doesn't start with `---\n`
 * or no closing delimiter is found, in which case the entire buffer should be
 * treated as body.
 */
function findTerminalFrontmatterEnd(buf: Buffer): number {
  if (
    buf.length < 5 ||
    buf[0] !== 0x2d ||
    buf[1] !== 0x2d ||
    buf[2] !== 0x2d ||
    buf[3] !== 0x0a
  ) {
    return 0;
  }
  // Search for "\n---\n" starting after the opening delimiter.
  const closingDelimiter: Buffer = Buffer.from("\n---\n");
  const idx = buf.indexOf(closingDelimiter, 4);
  if (idx === -1) {
    return 0;
  }
  return idx + closingDelimiter.length;
}

/**
 * Detect the text encoding of a terminal-file body. Cursor's frontmatter is
 * always UTF-8, but the body is whatever the spawned process wrote. Native
 * Windows console binaries (notably `wsl.exe`) emit UTF-16-LE — sometimes
 * without a BOM — when stdout is piped, which would otherwise be silently
 * misdecoded by `Buffer.toString("utf-8")` into U+FFFD soup.
 *
 * Returns "utf-16le" or "utf-16be" only when the evidence is strong, otherwise
 * "utf-8" (which preserves valid UTF-8 and ANSI-escape-rich text losslessly).
 *
 * The heuristic mirrors the printable-ASCII pair logic in
 * `@anysphere/utils`'s `detectUTF16Encoding`: count byte pairs of the form
 * `(printable, 0x00)` for LE and `(0x00, printable)` for BE in the first
 * 4 KB (matching `isBufferText`'s window), require both an absolute floor of
 * paired matches AND a 4× margin over the other side before declaring UTF-16.
 * This is much more robust than counting raw nulls, which misclassifies bodies
 * with a handful of stray null bytes (e.g. `printf` with embedded NULs) and
 * binary blobs that happen to land their nulls one-sided.
 */
const TERMINAL_DETECT_MIN_PAIRED_MATCHES = 8;

function isPrintableAsciiOrCommonWhitespace(byte: number): boolean {
  return (
    (byte >= 0x20 && byte <= 0x7e) ||
    byte === 0x09 ||
    byte === 0x0a ||
    byte === 0x0d
  );
}

function detectTerminalBodyEncoding(
  body: Buffer
): "utf-16le" | "utf-16be" | "utf-8" {
  if (body.length >= 2) {
    if (body[0] === 0xff && body[1] === 0xfe) return "utf-16le";
    if (body[0] === 0xfe && body[1] === 0xff) return "utf-16be";
  }
  const sampleLen: number = Math.min(4096, body.length);
  if (sampleLen < 16) return "utf-8";
  let utf16leMatches = 0;
  let utf16beMatches = 0;
  for (let i = 0; i + 1 < sampleLen; i += 2) {
    const lo: number = body[i];
    const hi: number = body[i + 1];
    if (hi === 0x00 && isPrintableAsciiOrCommonWhitespace(lo)) {
      utf16leMatches++;
    }
    if (lo === 0x00 && isPrintableAsciiOrCommonWhitespace(hi)) {
      utf16beMatches++;
    }
  }
  if (
    utf16leMatches >= TERMINAL_DETECT_MIN_PAIRED_MATCHES &&
    utf16leMatches >= 4 * Math.max(1, utf16beMatches)
  ) {
    return "utf-16le";
  }
  if (
    utf16beMatches >= TERMINAL_DETECT_MIN_PAIRED_MATCHES &&
    utf16beMatches >= 4 * Math.max(1, utf16leMatches)
  ) {
    return "utf-16be";
  }
  return "utf-8";
}

const TERMINAL_BLOCK_DELIMITER: Buffer = Buffer.from("\n---\n");
// Bounds the backwards scan for the opening `\n---\n` of the footer. Needs to
// fit the longest legitimate footer the writer can produce. The writer emits
// `exit_code: <int|unknown>` / `error: <escapedError>` + optional `elapsed_ms`
// + `ended_at: <iso>` (see `packages/local-exec/src/background-shell.ts` lines
// 553-563, 585-595, 712-720). Numeric exit footers top out around 90 bytes,
// but escaped error messages can be quite long, so we give a generous window.
// The strict validator below prevents false positives regardless of the cap.
const TERMINAL_FOOTER_MAX_BYTES: number = 4096;

/**
 * Validate that a candidate slice of bytes between a `\n---\n` opening and a
 * trailing `---\n` closing actually looks like the YAML footer that
 * `FileLoggingShellFactory` writes when a background shell exits. The footer
 * is ASCII with a fixed shape:
 *
 *   exit_code: <int|unknown>\n   OR   error: <escaped message>\n
 *   [elapsed_ms: <int>\n]?
 *   ended_at: <iso8601>\n
 *
 * `exit_code: unknown` is emitted when the child was killed by a signal
 * (`event.code` is null) — this is a real writer output, not a theoretical
 * case. Error messages are escaped via `escapeYamlString()` so embedded
 * newlines become literal `\\n` and the whole message is on one line.
 *
 * If the bytes don't match this shape exactly, we treat them as part of the
 * body so a process that happens to print `\n---\n` mid-output isn't
 * misidentified as a footer.
 */
function isValidTerminalFooterBody(text: string): boolean {
  for (let i = 0; i < text.length; i++) {
    const c: number = text.charCodeAt(i);
    if (c !== 0x0a && (c < 0x20 || c > 0x7e)) return false;
  }
  const lines: string[] = text.split("\n").filter(line => line.length > 0);
  if (lines.length < 2 || lines.length > 3) return false;
  const first: string = lines[0];
  const last: string = lines[lines.length - 1];
  if (!/^(exit_code: (?:-?\d+|unknown)|error: .+)$/.test(first)) return false;
  if (!last.startsWith("ended_at: ")) return false;
  if (lines.length === 3 && !/^elapsed_ms: \d+$/.test(lines[1])) return false;
  return true;
}

/**
 * Locate the byte offset of the opening `\n---\n` of the terminal-file footer.
 * Returns `buf.length` if there is no footer (in-progress shell, or a body
 * that doesn't end in the footer shape).
 *
 * Strategy: the footer always ends with `---\n`, so we first verify the last
 * 5 bytes are `\n---\n`. Then we scan backwards from there for the opening
 * `\n---\n`, bounded by `TERMINAL_FOOTER_MAX_BYTES` so a body containing
 * `\n---\n` literally cannot be misidentified as a footer open. Finally we
 * validate the bytes between the two delimiters via
 * `isValidTerminalFooterBody`.
 */
function findTerminalFooterStart(buf: Buffer, minStart: number): number {
  const len: number = buf.length;
  if (len < TERMINAL_BLOCK_DELIMITER.length * 2) return len;
  if (
    buf[len - 1] !== 0x0a ||
    buf[len - 2] !== 0x2d ||
    buf[len - 3] !== 0x2d ||
    buf[len - 4] !== 0x2d ||
    buf[len - 5] !== 0x0a
  ) {
    return len;
  }
  const scanFloor: number = Math.max(minStart, len - TERMINAL_FOOTER_MAX_BYTES);
  // Search backwards for the opening `\n---\n`, strictly before the closing
  // 5-byte `\n---\n` window at [len-5, len).
  const openingPos: number = buf.lastIndexOf(
    TERMINAL_BLOCK_DELIMITER,
    len - TERMINAL_BLOCK_DELIMITER.length - 1
  );
  if (openingPos === -1 || openingPos < scanFloor) return len;
  const footerBodyText: string = buf
    .subarray(
      openingPos + TERMINAL_BLOCK_DELIMITER.length,
      len - "---\n".length
    )
    .toString("utf-8");
  if (!isValidTerminalFooterBody(footerBodyText)) return len;
  return openingPos;
}

/**
 * Decode a Cursor terminal file buffer to text. The file is split into three
 * regions, each decoded with the appropriate encoding:
 *
 *   1. Frontmatter (always UTF-8 ASCII): `---\n...\n---\n`
 *   2. Body (whatever the child process wrote — may be UTF-16-LE/BE or UTF-8)
 *   3. Footer (always UTF-8 ASCII, only present after shell exit):
 *      `\n---\nexit_code: ...\nended_at: ...\n---\n`
 *
 * Splitting on both ends matters: native Windows binaries like `wsl.exe` pipe
 * UTF-16-LE bodies, but `FileLoggingShellFactory.createLoggingExecutor` always
 * appends the footer as UTF-8. Decoding `body+footer` as UTF-16 corrupts the
 * footer's ASCII bytes into gibberish and hides `exit_code` from the model.
 *
 * Uses only Node built-ins (no iconv-lite): Buffer natively decodes utf16le,
 * and Buffer.swap16() handles utf16be by byte-swapping into utf16le order.
 */
function decodeTerminalFile(rawBuf: Buffer): string {
  const frontmatterEnd: number = findTerminalFrontmatterEnd(rawBuf);
  const frontmatter: string =
    frontmatterEnd > 0
      ? rawBuf.subarray(0, frontmatterEnd).toString("utf-8")
      : "";
  const footerStart: number = findTerminalFooterStart(rawBuf, frontmatterEnd);
  const footer: string =
    footerStart < rawBuf.length
      ? rawBuf.subarray(footerStart).toString("utf-8")
      : "";
  const body: Buffer = rawBuf.subarray(frontmatterEnd, footerStart);
  const bodyEncoding = detectTerminalBodyEncoding(body);
  let bodyText: string;
  if (bodyEncoding === "utf-16le") {
    bodyText = body.toString("utf16le");
  } else if (bodyEncoding === "utf-16be") {
    // swap16() requires an even-length buffer and mutates in place. If the
    // body length is odd (truncated mid-codepoint due to a partial-write race
    // with FileLoggingShellFactory), swap16 the even-length prefix and drop
    // the orphan byte rather than falling back to UTF-8 garbage.
    const evenLen: number = body.length - (body.length % 2);
    const swapped: Buffer = Buffer.from(body.subarray(0, evenLen));
    swapped.swap16();
    bodyText = swapped.toString("utf16le");
  } else {
    bodyText = body.toString("utf-8");
  }
  // Strip a leading UTF-16 BOM character (decoded from FF FE / FE FF) so it
  // doesn't show up mid-content after the frontmatter when the body had a BOM.
  if (bodyText.charCodeAt(0) === 0xfeff) {
    bodyText = bodyText.slice(1);
  }
  return frontmatter + bodyText + footer;
}

/**
 * Magic-byte prefixes for binary file formats that the agent-tools fast-path
 * must reject. The slow path rejects these via `isBufferText`'s heuristic;
 * the fast-path bypasses that heuristic, so we have to identify them here.
 *
 * Each entry is the full disambiguating prefix as a `Buffer`. Short magic
 * numbers (e.g. "PK", "MZ") are listed with their full 3- or 4-byte
 * signatures to avoid false positives on legitimate text that happens to
 * start with the same first byte or two — `MZ` alone is the ASCII bigram
 * "MZ" which appears in plenty of real text, but `MZ\x90` only matches the
 * Microsoft toolchain's DOS stub.
 *
 * Coverage rationale: this list is intentionally conservative — every entry
 * is a stable, well-documented signature whose probability of colliding with
 * legitimate text is negligible. Formats not on the list (RTF, tar without a
 * POSIX `ustar` marker, plain CSV-with-NULs) flow through `decodeTerminalFile`
 * unchanged. The list focuses on the formats observed in production
 * agent-tools failures from WebFetch and MCP `downloadFile` plus the most
 * common binary archive / database / executable formats those tools might
 * legitimately fetch.
 *
 * Terminal files (written by `FileLoggingShellFactory`) always begin with a
 * `---\n` YAML frontmatter delimiter and so cannot match any of these
 * prefixes by construction, but we still gate the check on the path kind for
 * an explicit, self-documenting contract.
 */
const KNOWN_BINARY_MAGIC_PREFIXES: readonly Buffer[] = [
  // ── Documents ──
  Buffer.from("%PDF-", "ascii"), // PDF
  Buffer.from([0xd0, 0xcf, 0x11, 0xe0, 0xa1, 0xb1, 0x1a, 0xe1]), // OLE2 / Compound File Binary (.msi, legacy .doc/.xls/.ppt, .msg)

  // ── ZIP family (DOCX/XLSX/PPTX/JAR/EPUB/APK/IPA all start with these) ──
  Buffer.from([0x50, 0x4b, 0x03, 0x04]), // ZIP local file header
  Buffer.from([0x50, 0x4b, 0x05, 0x06]), // ZIP empty archive end-of-central-dir
  Buffer.from([0x50, 0x4b, 0x07, 0x08]), // ZIP spanned / data descriptor

  // ── Executables ──
  Buffer.from([0x7f, 0x45, 0x4c, 0x46]), // ELF (Linux/BSD .so/.elf executables)
  Buffer.from([0xfe, 0xed, 0xfa, 0xce]), // Mach-O 32-bit BE
  Buffer.from([0xfe, 0xed, 0xfa, 0xcf]), // Mach-O 64-bit BE
  Buffer.from([0xce, 0xfa, 0xed, 0xfe]), // Mach-O 32-bit LE
  Buffer.from([0xcf, 0xfa, 0xed, 0xfe]), // Mach-O 64-bit LE
  Buffer.from([0x4d, 0x5a, 0x90]), // Windows PE / DOS MZ (.exe / .dll). 3-byte
  // prefix avoids text false positives on the ASCII bigram "MZ" — every
  // Microsoft-toolchain PE has e_cblp = 0x0090 in the third byte.
  Buffer.from([0x00, 0x61, 0x73, 0x6d]), // WASM module ("\0asm")

  // ── Images (rejected for agent-tools .txt — real images are read via the
  //    image branch on the slow path; here they only appear if a download
  //    landed an image at a .txt suffix) ──
  Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]), // PNG (8-byte signature)
  Buffer.from([0xff, 0xd8, 0xff]), // JPEG
  Buffer.from("GIF87a", "ascii"), // GIF87a
  Buffer.from("GIF89a", "ascii"), // GIF89a

  // ── Databases ──
  Buffer.from("SQLite format 3\x00", "ascii"), // SQLite 3 database

  // ── Compression / archives ──
  Buffer.from([0x1f, 0x8b]), // gzip
  Buffer.from("BZh", "ascii"), // bzip2 (always followed by '1'-'9' block size)
  Buffer.from([0xfd, 0x37, 0x7a, 0x58, 0x5a, 0x00]), // xz
  Buffer.from([0x28, 0xb5, 0x2f, 0xfd]), // zstd (Zstandard frame magic)
  Buffer.from([0x37, 0x7a, 0xbc, 0xaf, 0x27, 0x1c]), // 7z
  Buffer.from([0x52, 0x61, 0x72, 0x21, 0x1a, 0x07, 0x00]), // RAR (v1.50 - v4.x)
  Buffer.from([0x52, 0x61, 0x72, 0x21, 0x1a, 0x07, 0x01, 0x00]), // RAR5 (v5.0+)
];

/**
 * Returns `true` iff `buf` is at least as long as `prefix` and its first
 * `prefix.length` bytes are byte-for-byte equal to `prefix`. Zero-allocation:
 * `Buffer.subarray` returns a view, not a copy.
 */
function bufferStartsWith(buf: Buffer, prefix: Buffer): boolean {
  return (
    buf.length >= prefix.length && buf.subarray(0, prefix.length).equals(prefix)
  );
}

/**
 * Returns `true` iff `buf` starts with any of the magic-byte prefixes in
 * `KNOWN_BINARY_MAGIC_PREFIXES`. Used by the agent-tools fast-path to
 * preserve the slow path's binary-rejection contract for files that downloaders
 * (WebFetch / MCP `downloadFile` / Windows tools) wrote with a `.txt` suffix.
 */
function looksLikeKnownBinaryFormat(buf: Buffer): boolean {
  return KNOWN_BINARY_MAGIC_PREFIXES.some(prefix =>
    bufferStartsWith(buf, prefix)
  );
}

/**
 * Build the same `invalidFile: Binary files of type ...` ReadResult that the
 * slow path returns when `isBufferText` rejects a file. Extracted so the new
 * fast-path binary guard can return an identical response shape, preserving
 * the existing error contract for genuinely-binary content.
 */
function buildBinaryFileRejection(resolvedPath: string): ReadResult {
  const fileExtension: string = extname(resolvedPath).toLowerCase();
  const reason: string =
    fileExtension === ""
      ? "Binary files without an extension are not supported by the read executor"
      : `Binary files of type ${fileExtension} are not supported by the read executor`;
  return new ReadResult({
    result: {
      case: "invalidFile",
      value: new ReadInvalidFile({
        path: resolvedPath,
        reason,
      }),
    },
  });
}

function tryApplyRequestedReadRange(
  content: string,
  totalLines: number,
  args: ReadArgs
): { content: string; rangeApplied: boolean } {
  if (args.offset === undefined && args.limit === undefined) {
    return { content, rangeApplied: false };
  }

  // Keep existing behavior for empty files and let the tool fallback handle it.
  if (content === "") {
    return { content, rangeApplied: false };
  }

  const effectiveOffset: number = args.offset ?? 1;
  const effectiveLimit: number =
    args.limit ??
    (effectiveOffset < 0 ? Math.abs(effectiveOffset) : totalLines);
  const startIndex: number =
    effectiveOffset < 0
      ? Math.max(0, totalLines + effectiveOffset)
      : Math.max(0, effectiveOffset - 1);
  if (startIndex >= totalLines) {
    // Preserve existing tool-layer error behavior for out-of-bounds offsets.
    return { content, rangeApplied: false };
  }

  const endIndex: number = Math.min(totalLines, startIndex + effectiveLimit);
  const lines = content.split("\n");
  const rangedContent = lines.slice(startIndex, endIndex).join("\n");
  return { content: rangedContent, rangeApplied: true };
}

type BoundedText = {
  text: string;
  truncated: boolean;
};

function appendBounded(
  current: BoundedText,
  addition: string,
  maxChars: number = MAX_TEXT_SIZE
): BoundedText {
  if (addition.length === 0) {
    return current;
  }
  const remaining = maxChars - current.text.length;
  if (remaining <= 0) {
    return { text: current.text, truncated: true };
  }
  if (addition.length > remaining) {
    return {
      text: current.text + addition.slice(0, remaining),
      truncated: true,
    };
  }
  return { text: current.text + addition, truncated: current.truncated };
}

type CappedLine = {
  text: string;
  truncated: boolean;
};

type RetainedLine = {
  line: CappedLine;
  hasNewline: boolean;
};

function appendToCappedLine(line: CappedLine, addition: string): CappedLine {
  const appended = appendBounded(line, addition);
  return { text: appended.text, truncated: appended.truncated };
}

function normalizeRetainedCrlfLine(
  retainedLine: RetainedLine,
  shouldNormalize: boolean
): CappedLine {
  const { line, hasNewline } = retainedLine;
  if (!shouldNormalize || !hasNewline || !line.text.endsWith("\r")) {
    return line;
  }
  return {
    ...line,
    text: line.text.slice(0, -1),
  };
}

function appendRetainedLines(
  current: BoundedText,
  retainedLines: readonly RetainedLine[],
  shouldNormalizeCrlf: boolean
): BoundedText {
  let result = current;
  retainedLines.forEach((retainedLine, index) => {
    const outputLine = normalizeRetainedCrlfLine(
      retainedLine,
      shouldNormalizeCrlf
    );
    if (index > 0) {
      result = appendBounded(result, "\n");
    }
    result = appendBounded(result, outputLine.text);
    if (outputLine.truncated) {
      result = {
        text: result.text,
        truncated: true,
      };
    }
  });
  return result;
}

function setCachedFileEncoding(path: string, encoding: string): void {
  if (_FILE_TO_ENCODING.has(path)) {
    _FILE_TO_ENCODING.delete(path);
  }
  _FILE_TO_ENCODING.set(path, encoding);
  if (_FILE_TO_ENCODING.size <= MAX_FILE_ENCODINGS) {
    return;
  }
  const oldestKey = _FILE_TO_ENCODING.keys().next().value as string | undefined;
  if (oldestKey !== undefined) {
    _FILE_TO_ENCODING.delete(oldestKey);
  }
}

function normalizeReadEncoding(encoding: string): string {
  const normalized = encoding.toLowerCase();
  if (normalized === "utf-8") {
    return "utf8";
  }
  if (normalized === "utf-8-bom" || normalized === "utf-8 bom") {
    return "utf8bom";
  }
  if (normalized === "latin-1") {
    return "latin1";
  }
  return normalized;
}

function toIconvEncoding(encoding: string): string {
  const normalized = normalizeReadEncoding(encoding);
  if (normalized === "utf8bom") {
    return "utf8";
  }
  return normalized;
}

type StreamingDecoderConfig =
  | {
      kind: "strictUtf8";
      cacheEncoding: string;
    }
  | {
      kind: "iconv";
      decoderEncoding: string;
      cacheEncoding: string;
    };

class InvalidUtf8Error extends Error {
  constructor() {
    super("Invalid UTF-8 while streaming read");
    this.name = "InvalidUtf8Error";
  }
}

function getReadEncoding(
  file: string,
  format: ContentFormat,
  encodingHint?: string
): string {
  return normalizeReadEncoding(
    encodingHint ?? _FILE_TO_ENCODING.get(file) ?? format.encoding
  );
}

function getStreamingDecoderConfig(
  file: string,
  format: ContentFormat,
  encodingHint?: string
): StreamingDecoderConfig {
  const requestedEncoding = getReadEncoding(file, format, encodingHint);
  const iconvEncoding = toIconvEncoding(requestedEncoding);
  if (iconvEncoding === "utf8") {
    return {
      kind: "strictUtf8",
      cacheEncoding: "utf8",
    };
  }
  if (iconv.encodingExists(iconvEncoding)) {
    return {
      kind: "iconv",
      decoderEncoding: iconvEncoding,
      cacheEncoding: requestedEncoding,
    };
  }
  return {
    kind: "strictUtf8",
    cacheEncoding: "utf8",
  };
}

async function* decodeFileChunks(
  ctx: Context,
  file: string,
  decoderConfig: StreamingDecoderConfig
): AsyncGenerator<string> {
  if (decoderConfig.kind === "strictUtf8") {
    const decoder = new TextDecoder("utf-8", { fatal: true, ignoreBOM: true });
    const stream = createReadStream(file, {
      highWaterMark: STREAMING_READ_CHUNK_BYTES,
      signal: ctx.signal,
    });
    try {
      for await (const chunk of stream) {
        const text = decoder.decode(chunk, { stream: true });
        if (text.length > 0) {
          yield text;
        }
      }
      const finalText = decoder.decode();
      if (finalText.length > 0) {
        yield finalText;
      }
    } catch (error) {
      if (error instanceof TypeError) {
        throw new InvalidUtf8Error();
      }
      throw error;
    }
    return;
  }

  const decoded = createReadStream(file, {
    highWaterMark: STREAMING_READ_CHUNK_BYTES,
    signal: ctx.signal,
  }).pipe(iconv.decodeStream(decoderConfig.decoderEncoding));
  for await (const chunk of decoded) {
    yield typeof chunk === "string" ? chunk : String(chunk);
  }
}

type StreamingReadTextResult = {
  content: string;
  totalLines: number;
  truncated: boolean;
  rangeApplied: boolean;
};

async function readTextStreaming(
  ctx: Context,
  file: string,
  format: ContentFormat,
  args: ReadArgs
): Promise<StreamingReadTextResult> {
  const decoderConfig = getStreamingDecoderConfig(
    file,
    format,
    args.encodingHint
  );
  try {
    return await readTextStreamingWithDecoder(ctx, file, args, decoderConfig);
  } catch (error) {
    if (error instanceof InvalidUtf8Error) {
      return await readTextStreamingWithDecoder(ctx, file, args, {
        kind: "iconv",
        decoderEncoding: "latin1",
        cacheEncoding: "latin1",
      });
    }
    throw error;
  }
}

async function readTextStreamingWithDecoder(
  ctx: Context,
  file: string,
  args: ReadArgs,
  decoderConfig: StreamingDecoderConfig
): Promise<StreamingReadTextResult> {
  const hasRange = args.offset !== undefined || args.limit !== undefined;
  const isNegativeOffset = (args.offset ?? 1) < 0;
  const effectiveOffset = args.offset ?? 1;
  const positiveStartIndex = Math.max(0, effectiveOffset - 1);
  const positiveEndIndex =
    args.limit === undefined ? undefined : positiveStartIndex + args.limit;
  const tailLineCapacity = isNegativeOffset ? Math.abs(effectiveOffset) : 0;

  const fallbackLines: RetainedLine[] = [];
  let fallbackBytes = 0;
  let fallbackTruncated = false;
  const selectedLines: RetainedLine[] = [];
  let selectedBytes = 0;
  let selectedTruncated = false;
  const tailLines: RetainedLine[] = [];
  let tailBytes = 0;
  // Set when we drop tail lines because they would exceed MAX_TEXT_SIZE,
  // distinct from dropping them because they fell outside the requested
  // tailLineCapacity window.
  let tailTruncated = false;
  let pendingLine: CappedLine = { text: "", truncated: false };
  let totalLines = 0;
  let crlfCount = 0;
  let lfOnlyCount = 0;
  let strippedLeadingBom = false;
  // True when we actually stripped a leading U+FEFF from the first chunk,
  // not just when we checked. Used to upgrade the cached encoding from
  // "utf8" to "utf8bom" so a later getBufferForWrite() preserves the BOM.
  let hadLeadingBom = false;

  const normalizeChunk = (rawChunk: string): string => {
    let chunk = rawChunk;
    if (!strippedLeadingBom && chunk.length > 0) {
      strippedLeadingBom = true;
      if (chunk.charCodeAt(0) === 0xfeff) {
        hadLeadingBom = true;
        chunk = chunk.slice(1);
      }
    }
    return chunk;
  };

  const appendSelectedLine = (line: CappedLine, hasNewline: boolean): void => {
    if (selectedTruncated && selectedBytes >= MAX_TEXT_SIZE) {
      return;
    }
    const separatorBytes = selectedLines.length > 0 ? 1 : 0;
    let remainingBytes = MAX_TEXT_SIZE - selectedBytes;
    if (separatorBytes > 0) {
      if (remainingBytes <= 0) {
        selectedTruncated = true;
        return;
      }
      remainingBytes--;
    }
    const retainedLine: RetainedLine =
      line.text.length > remainingBytes
        ? {
            line: {
              text: line.text.slice(0, remainingBytes),
              truncated: true,
            },
            hasNewline,
          }
        : { line, hasNewline };
    selectedLines.push(retainedLine);
    selectedBytes += separatorBytes + retainedLine.line.text.length;
    if (line.truncated) {
      selectedTruncated = true;
    }
    if (retainedLine.line.truncated) {
      selectedTruncated = true;
    }
  };

  const appendFallbackLine = (line: CappedLine, hasNewline: boolean): void => {
    if (fallbackTruncated && fallbackBytes >= MAX_TEXT_SIZE) {
      return;
    }
    const separatorChars = fallbackLines.length > 0 ? 1 : 0;
    let remainingChars = MAX_TEXT_SIZE - fallbackBytes;
    if (separatorChars > 0) {
      if (remainingChars <= 0) {
        fallbackTruncated = true;
        return;
      }
      remainingChars--;
    }
    const retainedLine: RetainedLine =
      line.text.length > remainingChars
        ? {
            line: {
              text: line.text.slice(0, remainingChars),
              truncated: true,
            },
            hasNewline,
          }
        : { line, hasNewline };
    fallbackLines.push(retainedLine);
    fallbackBytes += separatorChars + retainedLine.line.text.length;
    if (line.truncated || retainedLine.line.truncated) {
      fallbackTruncated = true;
    }
  };

  const finishLine = (line: CappedLine, hasNewline: boolean): void => {
    const lineIndex = totalLines;
    if (hasNewline) {
      if (line.text.endsWith("\r")) {
        crlfCount++;
      } else {
        lfOnlyCount++;
      }
    }
    appendFallbackLine(line, hasNewline);

    if (!isNegativeOffset) {
      const inRequestedRange =
        hasRange &&
        lineIndex >= positiveStartIndex &&
        (positiveEndIndex === undefined || lineIndex < positiveEndIndex);
      if (inRequestedRange) {
        appendSelectedLine(line, hasNewline);
      }
    } else if (tailLineCapacity > 0) {
      tailLines.push({ line, hasNewline });
      tailBytes += line.text.length + 1;
      // Drop oldest lines that fall outside the requested tail window.
      while (tailLines.length > tailLineCapacity) {
        const dropped = tailLines.shift();
        if (dropped !== undefined) {
          tailBytes -= dropped.line.text.length + 1;
        }
      }
      // Drop oldest lines that would push us past the output byte budget.
      while (tailLines.length > 1 && tailBytes > MAX_TEXT_SIZE) {
        const dropped = tailLines.shift();
        if (dropped !== undefined) {
          tailBytes -= dropped.line.text.length + 1;
          tailTruncated = true;
        }
      }
    }

    totalLines++;
  };

  for await (const rawChunk of decodeFileChunks(ctx, file, decoderConfig)) {
    const chunk = normalizeChunk(rawChunk);
    const parts = chunk.split("\n");
    for (let i = 0; i < parts.length; i++) {
      pendingLine = appendToCappedLine(pendingLine, parts[i]);
      if (i < parts.length - 1) {
        finishLine(pendingLine, true);
        pendingLine = { text: "", truncated: false };
      }
    }
  }

  finishLine(pendingLine, false);

  const totalLineEndings = crlfCount + lfOnlyCount;
  const shouldNormalizeCrlf =
    totalLineEndings > 0 && (crlfCount / totalLineEndings) * 100 >= 5;

  // Match readText()'s cache contract: a UTF-8 file with a BOM caches as
  // "utf8bom" so later writes round-trip the BOM. Non-UTF-8 encodings keep
  // their own name even if iconv surfaced a leading U+FEFF (e.g. UTF-16 BOM).
  const cacheEncoding =
    decoderConfig.cacheEncoding === "utf8" && hadLeadingBom
      ? "utf8bom"
      : decoderConfig.cacheEncoding;
  setCachedFileEncoding(file, cacheEncoding);

  let fallback: BoundedText = { text: "", truncated: fallbackTruncated };
  fallback = appendRetainedLines(fallback, fallbackLines, shouldNormalizeCrlf);

  if (!hasRange) {
    return {
      content: fallback.text,
      totalLines,
      truncated: fallback.truncated,
      rangeApplied: false,
    };
  }

  if (fallback.text === "") {
    return {
      content: "",
      totalLines,
      truncated: false,
      rangeApplied: false,
    };
  }

  if (isNegativeOffset) {
    const effectiveLimit = args.limit ?? tailLineCapacity;
    let negativeSelected: BoundedText = { text: "", truncated: tailTruncated };
    negativeSelected = appendRetainedLines(
      negativeSelected,
      tailLines.slice(0, effectiveLimit),
      shouldNormalizeCrlf
    );
    return {
      content: negativeSelected.text,
      totalLines,
      truncated: negativeSelected.truncated,
      rangeApplied: true,
    };
  }

  if (positiveStartIndex >= totalLines) {
    return {
      content: fallback.text,
      totalLines,
      truncated: fallback.truncated,
      rangeApplied: false,
    };
  }

  let selected: BoundedText = { text: "", truncated: selectedTruncated };
  selected = appendRetainedLines(selected, selectedLines, shouldNormalizeCrlf);
  return {
    content: selected.text,
    totalLines,
    truncated: selected.truncated,
    rangeApplied: true,
  };
}

export class LocalReadExecutor implements ReadExecutor {
  private readonly mcpStateAccessor?: McpStateAccessor;
  private readonly useStreamingRead?: () => boolean | Promise<boolean>;

  constructor(
    private permissionsService: PermissionsService,
    private workspacePath?: string,
    _options?: LocalReadExecutorOptions
  ) {
    this.mcpStateAccessor = _options?.mcpStateAccessor;
    this.useStreamingRead = _options?.useStreamingRead;
  }

  async execute(ctx: Context, args: ReadArgs): Promise<ReadResult> {
    using _span = createSpan(ctx.withName("LocalReadExecutor.execute"));
    const filePath = args.path;
    const resolvedPath = resolvePath(filePath, this.workspacePath);

    const shouldBlock = await watchdog(
      ctx,
      "permissionsService.shouldBlockRead",
      3_000,
      () => this.permissionsService.shouldBlockRead(resolvedPath)
    );

    if (shouldBlock) {
      return new ReadResult({
        result: {
          case: "permissionDenied",
          value: new ReadPermissionDenied({
            path: resolvedPath,
          }),
        },
      });
    }

    if (this.mcpStateAccessor !== undefined) {
      scheduleDiskMcpDiscoveryFreshnessOnMcpsPathAccess(
        ctx,
        this.mcpStateAccessor,
        resolvedPath
      );
    }

    try {
      const stats = await watchdog(ctx, "stat", 3_000, () =>
        stat(resolvedPath)
      );

      if (stats.isDirectory()) {
        return new ReadResult({
          result: {
            case: "invalidFile",
            value: new ReadInvalidFile({
              path: resolvedPath,
              reason: "Path is a directory, not a file",
            }),
          },
        });
      }

      if (!stats.isFile()) {
        return new ReadResult({
          result: {
            case: "invalidFile",
            value: new ReadInvalidFile({
              path: resolvedPath,
              reason: "Path is neither a file nor a directory",
            }),
          },
        });
      }

      // Terminal output files written by the Shell tool contain ANSI escape
      // sequences (color codes, cursor movement) whose ESC bytes (0x1B) cause
      // isBufferText to misclassify the file as binary. These files are always
      // text, so we bypass format heuristics entirely. We also fast-path the
      // sibling `agent-tools/<uuid>.txt` files (the Shell tool's large-output
      // capture path), which have the same ANSI-density problem. Unlike
      // terminal files, agent-tools files can hold genuinely-binary content
      // (PDFs from WebFetch, downloads from MCP `downloadFile`, etc.), so the
      // fast-path checks magic bytes and falls back to the same binary
      // rejection the slow path would have returned.
      const isTerminalPath: boolean = isTerminalFilePath(resolvedPath);
      const isAgentToolPath: boolean = isAgentToolOutputFile(resolvedPath);
      if (isTerminalPath || isAgentToolPath) {
        return await this.readTerminalFile(
          ctx,
          resolvedPath,
          stats,
          args,
          isAgentToolPath && !isTerminalPath
        );
      }

      const contentInfo = await watchdog(ctx, "getFormatForFile", 3_000, () =>
        getFormatForFile(resolvedPath)
      );

      // Check if the file is an image
      const isImage = contentInfo.isImageFile;
      const isPdf = isPdfFilePath(resolvedPath);
      const isVideo = isVideoFilePath(resolvedPath);

      if (isImage) {
        // Resize image if needed
        const resizedImage: ResizedImageResult = await watchdog(
          ctx,
          "resizeImageIfNeeded",
          3_000,
          async (): Promise<ResizedImageResult> => {
            const imageData: Buffer = await readFile(resolvedPath);
            return resizeImageBufferIfNeeded(imageData);
          }
        );

        return new ReadResult({
          result: {
            case: "success",
            value: new ReadSuccess({
              path: resolvedPath,
              output: {
                case: "data",
                value: resizedImage.data,
              },
              totalLines: 0,
              fileSize: BigInt(stats.size),
              truncated: false,
            }),
          },
        });
      } else if (isPdf) {
        const pdfData = await watchdog(ctx, "readPdfBinary", 3_000, () =>
          readFile(resolvedPath)
        );

        return new ReadResult({
          result: {
            case: "success",
            value: new ReadSuccess({
              path: resolvedPath,
              output: {
                case: "data",
                value: pdfData,
              },
              totalLines: 0,
              fileSize: BigInt(stats.size),
              truncated: false,
            }),
          },
        });
      } else if (contentInfo.isBinaryFile && isVideo) {
        // Handle supported binary files (currently video formats) - return raw binary data
        // Note: most of these files are not supported by the read file tool; read file will refuse to read files with these extensions.
        // Some are supported for other use cases, like passing input videos to Gemini models
        const binaryData = await watchdog(ctx, "readBinaryFile", 3_000, () =>
          readFile(resolvedPath)
        );

        return new ReadResult({
          result: {
            case: "success",
            value: new ReadSuccess({
              path: resolvedPath,
              output: {
                case: "data",
                value: binaryData,
              },
              totalLines: 0,
              fileSize: BigInt(stats.size),
              truncated: false,
            }),
          },
        });
      } else if (contentInfo.isBinaryFile) {
        return buildBinaryFileRejection(resolvedPath);
      } else {
        const useStreamingRead = this.useStreamingRead;
        const streamingReadEnabled = useStreamingRead
          ? await watchdog(ctx, "useStreamingRead", 3_000, () =>
              useStreamingRead()
            )
          : false;
        if (streamingReadEnabled) {
          const streamedRead = await watchdog(
            ctx,
            "readTextStreaming",
            7_000,
            () => readTextStreaming(ctx, resolvedPath, contentInfo, args)
          );
          return new ReadResult({
            result: {
              case: "success",
              value: new ReadSuccess({
                path: resolvedPath,
                output: {
                  case: "content",
                  value: streamedRead.content,
                },
                totalLines: streamedRead.totalLines,
                fileSize: BigInt(stats.size),
                truncated: streamedRead.truncated,
                rangeApplied: streamedRead.rangeApplied,
              }),
            },
          });
        }

        // Read file as text
        const fullContent = await watchdog(ctx, "readText", 3_000, () =>
          readText(resolvedPath, args.encodingHint)
        );

        const totalLines = await watchdog(ctx, "countLines", 3_000, () =>
          countLines(fullContent)
        );
        const rangedRead = tryApplyRequestedReadRange(
          fullContent,
          totalLines,
          args
        );

        let content = rangedRead.content;
        let truncated = false;

        // Truncate if content exceeds MAX_TEXT_SIZE
        if (content.length > MAX_TEXT_SIZE) {
          content = content.substring(0, MAX_TEXT_SIZE);
          truncated = true;
        }

        return new ReadResult({
          result: {
            case: "success",
            value: new ReadSuccess({
              path: resolvedPath,
              output: {
                case: "content",
                value: content,
              },
              totalLines: totalLines,
              fileSize: BigInt(stats.size),
              truncated: truncated,
              rangeApplied: rangedRead.rangeApplied,
            }),
          },
        });
      }
    } catch (error) {
      const err = error as NodeJS.ErrnoException;
      if (err.code === "ENOENT") {
        return new ReadResult({
          result: {
            case: "fileNotFound",
            value: new ReadFileNotFound({ path: resolvedPath }),
          },
        });
      }
      if (err.code === "EACCES" || err.code === "EPERM") {
        return new ReadResult({
          result: {
            case: "permissionDenied",
            value: new ReadPermissionDenied({ path: resolvedPath }),
          },
        });
      }
      return new ReadResult({
        result: {
          case: "error",
          value: new ReadError({
            path: resolvedPath,
            error:
              err instanceof Error ? err.message : "Unknown error occurred",
          }),
        },
      });
    }
  }

  private async readTerminalFile(
    ctx: Context,
    resolvedPath: string,
    stats: Awaited<ReturnType<typeof stat>>,
    args: ReadArgs,
    checkForBinaryMagicBytes: boolean
  ): Promise<ReadResult> {
    const rawBuf = await watchdog(ctx, "readTerminalFile", 3_000, () =>
      readFile(resolvedPath)
    );

    // Agent-tools files can hold genuinely-binary content (PDF/DOCX/MSI/etc.)
    // because WebFetch and MCP `downloadFile` write whatever bytes the
    // upstream returned. Reject those with the same response shape the slow
    // path would have produced. Terminal files (`isTerminalPath` only) cannot
    // contain raw binary blobs by construction, so we skip the check there
    // for a small perf win on the hot path.
    if (checkForBinaryMagicBytes && looksLikeKnownBinaryFormat(rawBuf)) {
      return buildBinaryFileRejection(resolvedPath);
    }

    // BOM stripping happens inside `decodeTerminalFile` for the body; the
    // frontmatter is plain ASCII so no BOM needs stripping at position 0.
    let content = decodeTerminalFile(rawBuf).replaceAll("\r\n", "\n");

    const totalLines = countLines(content);
    const rangedRead = tryApplyRequestedReadRange(content, totalLines, args);
    content = rangedRead.content;
    let truncated = false;
    if (content.length > MAX_TEXT_SIZE) {
      content = content.substring(0, MAX_TEXT_SIZE);
      truncated = true;
    }

    return new ReadResult({
      result: {
        case: "success",
        value: new ReadSuccess({
          path: resolvedPath,
          output: {
            case: "content",
            value: content,
          },
          totalLines,
          fileSize: BigInt(stats.size),
          truncated,
          rangeApplied: rangedRead.rangeApplied,
        }),
      },
    });
  }
}
