export const SAND_AUTO_REVIEW_INSTRUCTION_MAX_ENTRIES = 20;
export const SAND_AUTO_REVIEW_INSTRUCTION_MAX_CHARS = 1_000;

export interface SandAutoReviewInstructions {
	/**
	 * Whether Sand Auto-review runs at all on this machine (Settings → Agent).
	 * Off means every reviewed surface resolves to mode "off", so no action is
	 * classified and no approval card is raised. On by default, including for a
	 * settings file written before the toggle existed.
	 */
	readonly isEnabled: boolean;
	readonly allowInstructions: readonly string[];
	readonly blockInstructions: readonly string[];
}

export const DEFAULT_SAND_AUTO_REVIEW_INSTRUCTIONS: SandAutoReviewInstructions = {
	isEnabled: true,
	allowInstructions: [],
	blockInstructions: [],
};

function clampInstruction(value: string): string {
	const trimmed = value.trim();
	if (trimmed.length === 0) {
		return "";
	}
	return trimmed.length <= SAND_AUTO_REVIEW_INSTRUCTION_MAX_CHARS
		? trimmed
		: trimmed.slice(0, SAND_AUTO_REVIEW_INSTRUCTION_MAX_CHARS);
}

function normalizeInstructionList(raw: unknown): string[] {
	if (!Array.isArray(raw)) {
		return [];
	}
	const result: string[] = [];
	const seen = new Set<string>();
	for (const item of raw) {
		if (typeof item !== "string") {
			continue;
		}
		const clamped = clampInstruction(item);
		if (clamped.length === 0 || seen.has(clamped)) {
			continue;
		}
		seen.add(clamped);
		result.push(clamped);
		if (result.length >= SAND_AUTO_REVIEW_INSTRUCTION_MAX_ENTRIES) {
			break;
		}
	}
	return result;
}

/** Normalize trusted personal Auto-review rules from settings or the gateway wire. */
export function normalizeSandAutoReviewInstructions(
	partial: Partial<SandAutoReviewInstructions> | undefined,
): SandAutoReviewInstructions {
	return {
		isEnabled: partial?.isEnabled !== false,
		allowInstructions: normalizeInstructionList(partial?.allowInstructions),
		blockInstructions: normalizeInstructionList(partial?.blockInstructions),
	};
}

export function sandAutoReviewInstructionsEqual(
	a: SandAutoReviewInstructions,
	b: SandAutoReviewInstructions,
): boolean {
	return (
		a.isEnabled === b.isEnabled &&
		a.allowInstructions.length === b.allowInstructions.length &&
		a.blockInstructions.length === b.blockInstructions.length &&
		a.allowInstructions.every((value, index) => value === b.allowInstructions[index]) &&
		a.blockInstructions.every((value, index) => value === b.blockInstructions[index])
	);
}

export function appendAutoReviewAllowFromSummary(
	current: SandAutoReviewInstructions,
	summary: string,
): SandAutoReviewInstructions {
	const rule = clampInstruction(summary);
	if (rule.length === 0) return current;
	if (current.allowInstructions.some((entry) => entry === rule)) return current;
	const next = [...current.allowInstructions, rule];
	const allowInstructions =
		next.length <= SAND_AUTO_REVIEW_INSTRUCTION_MAX_ENTRIES
			? next
			: next.slice(-SAND_AUTO_REVIEW_INSTRUCTION_MAX_ENTRIES);
	return normalizeSandAutoReviewInstructions({
		...current,
		allowInstructions,
	});
}
