import { AsyncLocalStorage } from "node:async_hooks";
import type { Context } from "@anysphere/context";
import { createContext } from "@anysphere/context";
import { AgentSkill } from "@anysphere/proto/agent/v1/agent_skills_pb.js";
import {
  CursorRule,
  CursorRuleType,
  CursorRuleTypeAgentFetched,
  CursorRuleTypeGlobal,
  CursorRuleTypeManuallyAttached,
} from "@anysphere/proto/agent/v1/cursor_rules_pb.js";
import { CustomSubagent } from "@anysphere/proto/agent/v1/subagents_pb.js";
import { type GrayMatterFile, grayMatter } from "@anysphere/utils/gray-matter";
import ignore, { type Ignore } from "ignore";
import { Minimatch } from "minimatch";
import type { GitExecutor } from "../git-executor.js";
import type { CloudRulesService } from "../services/cloud-rules-service.js";
import type { AgentSkillsService } from "../services/extensibility/agent-skills-service.js";
import {
  buildAgentSkillFromParsed,
  buildCursorRuleFromParsed,
  type CursorRulesService,
  cursorRuleFromParsedMdc,
  dedupeKey,
  isAlwaysApplySkillParsed,
  parseCursorRulesMdcContent,
} from "../services/extensibility/cursor-rules-service.js";
import { shouldIgnoreExtensibilitySkillPath } from "../services/extensibility/skill-discovery.js";
import {
  deriveNameFromFilename,
  parseSubagentFile,
} from "../services/extensibility/subagents-service.js";

export type BareGitWorkspaceFileKind = "file" | "directory" | "missing";

export type BareGitCommandOutput = {
  exitCode: number;
  stdout: Uint8Array;
  stderr: Uint8Array;
};

export type BareGitWorkspaceRepository<RuntimeContext> = {
  getTreeSha(): string;
  readFile(
    ctx: RuntimeContext,
    repoRelativePath: string
  ): Promise<Uint8Array | undefined>;
  readFiles?(
    ctx: RuntimeContext,
    repoRelativePaths: string[]
  ): Promise<Map<string, Uint8Array | undefined>>;
  stat(
    ctx: RuntimeContext,
    repoRelativePath: string
  ): Promise<BareGitWorkspaceFileKind>;
  listFiles(ctx: RuntimeContext, repoRelativePrefix: string): Promise<string[]>;
  runGit(
    ctx: RuntimeContext,
    args: string[],
    timeoutMs?: number
  ): Promise<BareGitCommandOutput>;
};

export class BareGitWorkspaceRuntimeRef<RuntimeContext> {
  private readonly storage = new AsyncLocalStorage<RuntimeContext>();

  runWith<T>(ctx: RuntimeContext, fn: () => Promise<T>): Promise<T> {
    return this.storage.run(ctx, fn);
  }

  get(): RuntimeContext | undefined {
    return this.storage.getStore();
  }
}

export type ResolveBareGitRuntimeContext<RuntimeContext> = (
  agentCtx: Context,
  runtimeContextFromRef: RuntimeContext | undefined
) => RuntimeContext | undefined;

function normalizeVirtualRoot(root: string): string {
  return root.replace(/\\/g, "/").replace(/\/+$/, "");
}

function toRepoRelative(
  virtualRoot: string,
  absolutePath: string
): string | undefined {
  const root = normalizeVirtualRoot(virtualRoot);
  const norm = absolutePath.replace(/\\/g, "/");
  if (norm === root) {
    return "";
  }
  const prefix = `${root}/`;
  if (!norm.startsWith(prefix)) {
    return undefined;
  }
  return norm.slice(prefix.length);
}

export class BareGitWorkspaceFilesystem<RuntimeContext> {
  private treePathsPromise: Promise<string[]> | undefined;
  private cursorIgnoresPromise:
    | Promise<Array<{ baseDir: string; matcher: Ignore }>>
    | undefined;

  constructor(
    private readonly repository: BareGitWorkspaceRepository<RuntimeContext>,
    private readonly virtualRoot: string,
    private readonly runtimeRef: BareGitWorkspaceRuntimeRef<RuntimeContext>,
    private readonly resolveRuntimeContext: ResolveBareGitRuntimeContext<RuntimeContext>
  ) {}

  private async allTreePaths(ctx: RuntimeContext): Promise<string[]> {
    if (this.treePathsPromise === undefined) {
      this.treePathsPromise = this.repository.listFiles(ctx, "");
    }
    try {
      return await this.treePathsPromise;
    } catch {
      this.treePathsPromise = undefined;
      throw new Error(
        "BareGitWorkspaceFilesystem: failed to list repository files"
      );
    }
  }

  private async getCursorIgnores(
    ctx: RuntimeContext
  ): Promise<Array<{ baseDir: string; matcher: Ignore }>> {
    if (this.cursorIgnoresPromise === undefined) {
      this.cursorIgnoresPromise = this.readCursorIgnores(ctx);
    }
    try {
      return await this.cursorIgnoresPromise;
    } catch {
      this.cursorIgnoresPromise = undefined;
      return [];
    }
  }

  private async readCursorIgnores(
    ctx: RuntimeContext
  ): Promise<Array<{ baseDir: string; matcher: Ignore }>> {
    const paths = await this.allTreePaths(ctx);
    const ignorePaths = Array.from(
      new Set([
        ".cursorignore",
        ...paths.filter(
          path => path === ".cursorignore" || path.endsWith("/.cursorignore")
        ),
      ])
    );
    // Use allSettled so a transient read failure on one nested .cursorignore
    // does not silently discard every other ignore entry. We rethrow if
    // anything failed so getCursorIgnores invalidates its cache and the next
    // caller retries the entries that failed this time.
    const settled = await Promise.allSettled(
      ignorePaths.map(async path => {
        const data = await this.repository.readFile(ctx, path);
        if (data === undefined) {
          return undefined;
        }
        const content = new TextDecoder("utf-8", { fatal: false }).decode(data);
        return {
          baseDir: dirnamePath(path),
          matcher: ignore().add(content),
        };
      })
    );
    const entries: Array<{ baseDir: string; matcher: Ignore }> = [];
    let firstError: unknown;
    for (const result of settled) {
      if (result.status === "fulfilled") {
        if (result.value !== undefined) {
          entries.push(result.value);
        }
      } else if (firstError === undefined) {
        firstError = result.reason;
      }
    }
    if (firstError !== undefined) {
      throw firstError;
    }
    return entries;
  }

  /**
   * Clears the cached tree listing and `.cursorignore` matchers so the next
   * call rereads them from the repository. Service-level reloads must invoke
   * this so that newly added or removed files in the underlying tree show up.
   */
  reset(): void {
    this.treePathsPromise = undefined;
    this.cursorIgnoresPromise = undefined;
  }

  async readTextFile(
    agentCtx: Context,
    absolutePath: string
  ): Promise<string | undefined> {
    const ctx = this.resolveRuntimeContext(agentCtx, this.runtimeRef.get());
    if (ctx === undefined) {
      return undefined;
    }
    const rel = toRepoRelative(this.virtualRoot, absolutePath);
    if (rel === undefined) {
      return undefined;
    }
    const data = await this.repository.readFile(ctx, rel);
    if (data === undefined) {
      return undefined;
    }
    return new TextDecoder("utf-8", { fatal: false }).decode(data);
  }

  async readTextFiles(
    agentCtx: Context,
    absolutePaths: string[]
  ): Promise<Map<string, string | undefined>> {
    const ctx = this.resolveRuntimeContext(agentCtx, this.runtimeRef.get());
    if (ctx === undefined) {
      return new Map(absolutePaths.map(path => [path, undefined]));
    }

    const relByAbsolute = new Map<string, string>();
    for (const absolutePath of absolutePaths) {
      const rel = toRepoRelative(this.virtualRoot, absolutePath);
      if (rel !== undefined) {
        relByAbsolute.set(absolutePath, rel);
      }
    }

    const dataByRel: Map<string, Uint8Array | undefined> =
      this.repository.readFiles !== undefined
        ? await this.repository.readFiles(ctx, [...relByAbsolute.values()])
        : new Map(
            await Promise.all(
              [...relByAbsolute.values()].map(
                async rel =>
                  [rel, await this.repository.readFile(ctx, rel)] as const
              )
            )
          );

    const decoder = new TextDecoder("utf-8", { fatal: false });
    const result = new Map<string, string | undefined>();
    for (const absolutePath of absolutePaths) {
      const rel = relByAbsolute.get(absolutePath);
      const data = rel === undefined ? undefined : dataByRel.get(rel);
      result.set(
        absolutePath,
        data === undefined ? undefined : decoder.decode(data)
      );
    }
    return result;
  }

  async stat(
    agentCtx: Context,
    absolutePath: string
  ): Promise<BareGitWorkspaceFileKind> {
    const ctx = this.resolveRuntimeContext(agentCtx, this.runtimeRef.get());
    if (ctx === undefined) {
      return "missing";
    }
    const rel = toRepoRelative(this.virtualRoot, absolutePath);
    if (rel === undefined) {
      return "missing";
    }
    return this.repository.stat(ctx, rel);
  }

  async *walkFiles(
    agentCtx: Context,
    options: {
      rootDir: string;
      includeGlobs: string[];
      excludeGlobs?: string[];
      followSymlinks?: boolean;
    }
  ): AsyncIterable<string> {
    const ctx = this.resolveRuntimeContext(agentCtx, this.runtimeRef.get());
    if (ctx === undefined) {
      return;
    }
    const walkRoot = normalizeVirtualRoot(options.rootDir);
    const repoRoot = normalizeVirtualRoot(this.virtualRoot);
    const prefix =
      walkRoot === repoRoot
        ? ""
        : (toRepoRelative(repoRoot, walkRoot) ?? undefined);
    if (prefix === undefined) {
      return;
    }
    const paths =
      prefix === ""
        ? await this.allTreePaths(ctx)
        : await this.repository.listFiles(ctx, prefix);

    const matchOptions = { dot: true };
    const includeMatchers = options.includeGlobs.map(
      glob => new Minimatch(glob, matchOptions)
    );
    const excludeMatchers = (options.excludeGlobs ?? []).map(
      glob => new Minimatch(glob, matchOptions)
    );
    for (const path of paths) {
      const candidate = toWalkCandidate(prefix, path);
      if (candidate === undefined) {
        continue;
      }
      const included = includeMatchers.some(matcher =>
        matcher.match(candidate)
      );
      if (!included) {
        continue;
      }
      const excluded = excludeMatchers.some(matcher =>
        matcher.match(candidate)
      );
      if (excluded) {
        continue;
      }
      yield candidate;
    }
  }

  async isIgnoredForRuleDiscovery(
    agentCtx: Context,
    absolutePath: string
  ): Promise<boolean> {
    const ctx = this.resolveRuntimeContext(agentCtx, this.runtimeRef.get());
    if (ctx === undefined) {
      return true;
    }
    const rel = toRepoRelative(this.virtualRoot, absolutePath);
    if (rel === undefined) {
      return true;
    }
    const cursorIgnores = await this.getCursorIgnores(ctx);
    return cursorIgnores.some(({ baseDir, matcher }) => {
      const relativeToIgnoreFile = relativeRepoPath(baseDir, rel);
      return (
        relativeToIgnoreFile !== undefined &&
        matcher.ignores(relativeToIgnoreFile)
      );
    });
  }
}

function dirnamePath(path: string): string {
  const idx = path.lastIndexOf("/");
  return idx === -1 ? "" : path.slice(0, idx);
}

function relativeRepoPath(baseDir: string, path: string): string | undefined {
  if (baseDir === "") {
    return path;
  }
  if (path === baseDir) {
    return "";
  }
  const prefix = `${baseDir}/`;
  if (!path.startsWith(prefix)) {
    return undefined;
  }
  return path.slice(prefix.length);
}

function toWalkCandidate(prefix: string, path: string): string | undefined {
  if (prefix === "") {
    return path;
  }
  if (path === prefix) {
    return "";
  }
  if (path.startsWith(`${prefix}/`)) {
    return path.slice(prefix.length + 1);
  }
  return undefined;
}

// gray-matter throws on YAML it cannot parse (e.g. unquoted glob values like
// `globs: *.ts` look like alias references). A single bad rule file must not
// reject the whole load — we return undefined and let callers emit a parseError
// on a stub rule so discovery still surfaces every other rule/skill/subagent.
function safeParseMatter(content: string):
  | { parsed: GrayMatterFile<string>; error: undefined }
  | {
      parsed: undefined;
      error: string;
    } {
  try {
    return { parsed: grayMatter(content), error: undefined };
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    return {
      parsed: undefined,
      error: `Failed to parse frontmatter: ${message}`,
    };
  }
}

function makeVirtualPath(root: string, repoRelativePath: string): string {
  const normalizedRoot = normalizeVirtualRoot(root);
  return repoRelativePath === ""
    ? normalizedRoot
    : `${normalizedRoot}/${repoRelativePath}`;
}

function isBareGitPathUnderConfigDir({
  repoRelativePath,
  configDir,
  subdir,
}: {
  repoRelativePath: string;
  configDir: string;
  subdir: string;
}): boolean {
  return (
    repoRelativePath.startsWith(`${configDir}/${subdir}/`) ||
    repoRelativePath.includes(`/${configDir}/${subdir}/`)
  );
}

const FIRST_PARTY_SKILL_CONFIG_DIRS = [
  { configDir: ".cursor", subdir: "skills" },
  { configDir: ".agents", subdir: "skills" },
  { configDir: ".cursor", subdir: "skills-cursor" },
];

const THIRD_PARTY_SKILL_CONFIG_DIRS = [
  { configDir: ".claude", subdir: "skills" },
  { configDir: ".codex", subdir: "skills" },
];

function isBareGitSkillPath(
  repoRelativePath: string,
  thirdPartyExtensibilityEnabled: boolean
): boolean {
  if (!repoRelativePath.endsWith("/SKILL.md")) {
    return false;
  }
  if (shouldIgnoreExtensibilitySkillPath(repoRelativePath)) {
    return false;
  }
  const allowedDirs = thirdPartyExtensibilityEnabled
    ? [...FIRST_PARTY_SKILL_CONFIG_DIRS, ...THIRD_PARTY_SKILL_CONFIG_DIRS]
    : FIRST_PARTY_SKILL_CONFIG_DIRS;
  return allowedDirs.some(({ configDir, subdir }) =>
    isBareGitPathUnderConfigDir({ repoRelativePath, configDir, subdir })
  );
}

function isBareGitSubagentPath(
  repoRelativePath: string,
  thirdPartyExtensibilityEnabled: boolean
): boolean {
  const lower = repoRelativePath.toLowerCase();
  const isMarkdown =
    lower.endsWith(".md") ||
    lower.endsWith(".mdc") ||
    lower.endsWith(".markdown");
  if (!isMarkdown) {
    return false;
  }
  if (
    isBareGitPathUnderConfigDir({
      repoRelativePath,
      configDir: ".cursor",
      subdir: "agents",
    })
  ) {
    return true;
  }
  return (
    thirdPartyExtensibilityEnabled &&
    isBareGitPathUnderConfigDir({
      repoRelativePath,
      configDir: ".claude",
      subdir: "agents",
    })
  );
}

function isBareGitRulePath(repoRelativePath: string): boolean {
  return (
    repoRelativePath.endsWith(".mdc") &&
    isBareGitPathUnderConfigDir({
      repoRelativePath,
      configDir: ".cursor",
      subdir: "rules",
    })
  );
}

function buildBareGitRuleFromMdc(
  fullPath: string,
  content: string
): CursorRule {
  const parsed = parseCursorRulesMdcContent(content);
  if (parsed === null) {
    return new CursorRule({
      fullPath,
      content,
      parseError: "Failed to parse .mdc rule file",
      type: new CursorRuleType({
        type: {
          case: "manuallyAttached",
          value: new CursorRuleTypeManuallyAttached(),
        },
      }),
    });
  }
  return cursorRuleFromParsedMdc({
    path: fullPath,
    body: parsed.body,
    frontmatter: parsed.frontmatter,
    rawFrontmatter: parsed.rawFrontmatter,
  });
}

const CLOUD_SPECIFIC_INSTRUCTIONS_HEADER =
  "## Cursor Cloud specific instructions";
const CLOUD_SPECIFIC_INSTRUCTIONS_SEPARATOR = `\n\n${CLOUD_SPECIFIC_INSTRUCTIONS_HEADER}\n`;

type BareGitExtensibilityLoadResult = {
  cursorRules: CursorRule[];
  agentSkills: AgentSkill[];
  cloudRule: string | null;
  subagents: CustomSubagent[];
};

export class BareGitExtensibilityService<RuntimeContext>
  implements CursorRulesService, AgentSkillsService, CloudRulesService
{
  private loaded: Promise<BareGitExtensibilityLoadResult> | undefined;
  private readonly getThirdPartyExtensibilityEnabled: () => boolean;

  constructor(
    private readonly workspacePath: string,
    private readonly fs: BareGitWorkspaceFilesystem<RuntimeContext>,
    getThirdPartyExtensibilityEnabled: () => boolean = () => true
  ) {
    this.getThirdPartyExtensibilityEnabled = getThirdPartyExtensibilityEnabled;
  }

  /**
   * Starts a load and clears `this.loaded` if the load fails so the next
   * `load()` can retry (transient tree listing errors must not wedge the service).
   */
  private beginLoad(ctx: Context): Promise<BareGitExtensibilityLoadResult> {
    let loadPromise: Promise<BareGitExtensibilityLoadResult>;
    loadPromise = this.loadFresh(ctx).catch(err => {
      if (this.loaded === loadPromise) {
        this.loaded = undefined;
      }
      throw err;
    });
    return loadPromise;
  }

  private load(ctx: Context): Promise<BareGitExtensibilityLoadResult> {
    this.loaded ??= this.beginLoad(ctx);
    return this.loaded;
  }

  reload(ctx: Context): void {
    this.fs.reset();
    this.loaded = this.beginLoad(ctx);
  }

  /**
   * Reloads from tree and returns subagents (same contract as
   * `SubagentsService.reload()` in this package).
   */
  async reloadSubagents(): Promise<CustomSubagent[]> {
    this.fs.reset();
    this.loaded = this.beginLoad(createContext());
    return (await this.loaded).subagents;
  }

  dispose(): void {}

  onDidChangeRules(): () => void {
    return () => {};
  }

  onDidChangeSkills(): () => void {
    return () => {};
  }

  onDidChangeRule(): void {}

  async getAllCursorRules(ctx: Context): Promise<CursorRule[]> {
    return (await this.load(ctx)).cursorRules;
  }

  async getAllAgentSkills(ctx: Context): Promise<AgentSkill[]> {
    return (await this.load(ctx)).agentSkills;
  }

  async getCloudRule(ctx: Context): Promise<string | null> {
    return (await this.load(ctx)).cloudRule;
  }

  async getAllSubagents(): Promise<CustomSubagent[]> {
    return (await this.load(createContext())).subagents;
  }

  private async readRepoText(
    ctx: Context,
    path: string
  ): Promise<string | undefined> {
    return await this.fs.readTextFile(
      ctx,
      makeVirtualPath(this.workspacePath, path)
    );
  }

  private async loadFresh(
    ctx: Context
  ): Promise<BareGitExtensibilityLoadResult> {
    const thirdPartyExtensibilityEnabled =
      this.getThirdPartyExtensibilityEnabled();
    const cursorRules: CursorRule[] = [];
    const agentSkills: AgentSkill[] = [];
    const subagents: CustomSubagent[] = [];
    const seenRuleKeys = new Set<string>();
    const seenSkillPaths = new Set<string>();

    const pushRule = (rule: CursorRule): void => {
      const key = dedupeKey(rule.fullPath);
      if (seenRuleKeys.has(key)) {
        return;
      }
      seenRuleKeys.add(key);
      cursorRules.push(rule);
    };

    const includeGlobs = [
      ".cursorrules",
      "AGENTS.md",
      "**/.cursor/rules/**/*.mdc",
      "**/.cursor/skills/**/SKILL.md",
      "**/.cursor/skills-cursor/**/SKILL.md",
      "**/.cursor/agents/**/*.md",
      "**/.cursor/agents/**/*.mdc",
      "**/.cursor/agents/**/*.markdown",
      "**/.agents/skills/**/SKILL.md",
      "**/AGENTS.md",
    ];
    if (thirdPartyExtensibilityEnabled) {
      includeGlobs.push(
        "CLAUDE.md",
        "CLAUDE.local.md",
        "**/CLAUDE.md",
        "**/CLAUDE.local.md",
        "**/.claude/skills/**/SKILL.md",
        "**/.codex/skills/**/SKILL.md",
        "**/.claude/agents/**/*.md",
        "**/.claude/agents/**/*.mdc",
        "**/.claude/agents/**/*.markdown"
      );
    }

    const allPaths: string[] = [];
    for await (const rel of this.fs.walkFiles(ctx, {
      rootDir: this.workspacePath,
      includeGlobs,
      followSymlinks: true,
    })) {
      allPaths.push(rel);
    }

    const ruleAndSkillPaths: string[] = [];
    const subagentPaths: string[] = [];
    for (const path of allPaths) {
      if (isBareGitSubagentPath(path, thirdPartyExtensibilityEnabled)) {
        subagentPaths.push(path);
        continue;
      }
      const fullPath = makeVirtualPath(this.workspacePath, path);
      if (await this.fs.isIgnoredForRuleDiscovery(ctx, fullPath)) {
        continue;
      }
      ruleAndSkillPaths.push(path);
    }

    const ruleAndSkillContent = await this.fs.readTextFiles(
      ctx,
      ruleAndSkillPaths.map(path => makeVirtualPath(this.workspacePath, path))
    );

    for (const path of ruleAndSkillPaths) {
      const fullPath = makeVirtualPath(this.workspacePath, path);
      const content = ruleAndSkillContent.get(fullPath);
      if (content === undefined) {
        continue;
      }
      if (path === ".cursorrules") {
        pushRule(
          new CursorRule({
            fullPath,
            content,
            type: new CursorRuleType({
              type: { case: "global", value: new CursorRuleTypeGlobal() },
            }),
          })
        );
        continue;
      }
      // The include globs pull both the root files (`AGENTS.md`) and nested
      // copies (`**/AGENTS.md`). Match on basename so nested files aren't
      // silently dropped after being read.
      const basename = path.split("/").at(-1) ?? path;
      const isAgentsMd = basename === "AGENTS.md";
      const isClaudeRoot =
        thirdPartyExtensibilityEnabled &&
        (basename === "CLAUDE.md" || basename === "CLAUDE.local.md");
      if (isAgentsMd || isClaudeRoot) {
        pushRule(
          new CursorRule({
            fullPath,
            content,
            type: new CursorRuleType({
              type: { case: "global", value: new CursorRuleTypeGlobal() },
            }),
          })
        );
        continue;
      }
      if (isBareGitRulePath(path)) {
        pushRule(buildBareGitRuleFromMdc(fullPath, content));
        continue;
      }
      if (
        isBareGitSkillPath(path, thirdPartyExtensibilityEnabled) &&
        !seenSkillPaths.has(path)
      ) {
        seenSkillPaths.add(path);
        const { parsed, error: parseError } = safeParseMatter(content);
        if (parsed === undefined) {
          // Match AgentSkillsCursorRulesService: both CursorRule and AgentSkill
          // report the failure so getAllAgentSkills() surfaces the malformed skill.
          const skillErrorMsg = `Failed to read skill file: ${parseError}`;
          pushRule(
            new CursorRule({
              fullPath,
              content,
              parseError: skillErrorMsg,
              type: new CursorRuleType({
                type: {
                  case: "agentFetched",
                  value: new CursorRuleTypeAgentFetched({}),
                },
              }),
            })
          );
          agentSkills.push(
            new AgentSkill({
              fullPath,
              parseError: skillErrorMsg,
            })
          );
          continue;
        }
        const parsedSkill = { skillFilePath: fullPath, content, parsed };
        pushRule(buildCursorRuleFromParsed(parsedSkill));
        if (!isAlwaysApplySkillParsed(parsed)) {
          agentSkills.push(buildAgentSkillFromParsed(parsedSkill));
        }
      }
    }

    const subagentContent = await this.fs.readTextFiles(
      ctx,
      subagentPaths.map(path => makeVirtualPath(this.workspacePath, path))
    );

    for (const path of subagentPaths) {
      const fullPath = makeVirtualPath(this.workspacePath, path);
      const content = subagentContent.get(fullPath);
      if (content === undefined) {
        continue;
      }
      const parsed = parseSubagentFile(content);
      if (parsed === null) {
        continue;
      }
      const filename = path.split("/").at(-1) ?? path;
      const subagent = new CustomSubagent({
        fullPath,
        name: parsed.name || deriveNameFromFilename(filename),
        description: parsed.description ?? "",
        tools: parsed.tools,
        model: parsed.model ?? "inherit",
        forceDefaultModel: parsed.forceDefaultModel,
        prompt: parsed.prompt,
        permissionMode: parsed.permissionMode,
        isBackground: parsed.isBackground,
        source: "workspace",
      });
      subagents.push(subagent);
    }

    const [agentsMdRaw, cloudMdRaw] = await Promise.all([
      this.readRepoText(ctx, "AGENTS.md"),
      this.readRepoText(ctx, ".cursor/CLOUD.md"),
    ]);
    // Align with LocalCloudRulesService.load(): whitespace-only files are ignored.
    const nonEmpty = (s: string | undefined): string | undefined =>
      s !== undefined && s.trim().length > 0 ? s : undefined;
    const agentsMd = nonEmpty(agentsMdRaw);
    const cloudMd = nonEmpty(cloudMdRaw);
    let cloudRule: string | null;
    if (agentsMd === undefined && cloudMd === undefined) {
      cloudRule = null;
    } else if (agentsMd === undefined) {
      cloudRule = `${CLOUD_SPECIFIC_INSTRUCTIONS_HEADER}\n${cloudMd}`;
    } else if (cloudMd === undefined) {
      cloudRule = agentsMd;
    } else {
      cloudRule = `${agentsMd}${CLOUD_SPECIFIC_INSTRUCTIONS_SEPARATOR}${cloudMd}`;
    }

    return { cursorRules, agentSkills, cloudRule, subagents };
  }
}

export class BareGitWorkspaceGitExecutor<RuntimeContext>
  implements GitExecutor
{
  constructor(
    private readonly repository: BareGitWorkspaceRepository<RuntimeContext>,
    private readonly virtualWorkspaceRoot: string,
    private readonly runtimeRef: BareGitWorkspaceRuntimeRef<RuntimeContext>,
    private readonly resolveRuntimeContext: ResolveBareGitRuntimeContext<RuntimeContext>
  ) {}

  async exec(
    agentCtx: Context,
    cwd: string,
    args: string[],
    options?: { timeout?: number; caller?: string }
  ): Promise<{ exitCode: number; stdout: string; stderr: string }> {
    const root = normalizeVirtualRoot(this.virtualWorkspaceRoot);
    const cwdNorm = normalizeVirtualRoot(cwd);

    if (args[0] === "rev-parse" && args[1] === "--show-toplevel") {
      if (cwdNorm === root || cwdNorm.startsWith(`${root}/`)) {
        return { exitCode: 0, stdout: `${root}\n`, stderr: "" };
      }
    }

    if (
      args[0] === "--no-optional-locks" &&
      args[1] === "status" &&
      args[2] === "--short" &&
      args[3] === "--branch" &&
      (cwdNorm === root || cwdNorm.startsWith(`${root}/`))
    ) {
      return {
        exitCode: 0,
        stdout: `## HEAD (detached at ${this.repository.getTreeSha()})\n`,
        stderr: "",
      };
    }

    const ctx = this.resolveRuntimeContext(agentCtx, this.runtimeRef.get());
    if (ctx === undefined) {
      throw new Error("BareGitWorkspaceGitExecutor: missing runtime context");
    }

    const out = await this.repository.runGit(ctx, args, options?.timeout);
    // Return the non-zero exit code instead of throwing: callers like
    // `findGitRoot` treat a non-zero `rev-parse --show-toplevel` as "not a git
    // repo" by branching on `exitCode`. Throwing here would turn an expected
    // negative result into an uncaught exception.
    return {
      exitCode: out.exitCode,
      stdout: decodeUtf8(out.stdout),
      stderr: decodeUtf8(out.stderr),
    };
  }
}

function decodeUtf8(bytes: Uint8Array): string {
  return new TextDecoder("utf-8", { fatal: false }).decode(bytes);
}
