import { availableParallelism } from "node:os";
import type { Context } from "@anysphere/context";
import {
  getRipgrepBinaryPath,
  type SandboxPolicy,
  spawnInSandbox,
} from "@anysphere/shell-exec";
import {
  isRipgrepInvocationRecordingEnabled,
  type RipgrepInvocationSource,
  recordRipgrepInvocation,
} from "./ripgrep-invocation-recorder.js";

/**
 * Upper bound on ripgrep worker threads for `--files` walks.
 *
 * A directory walk is bound by `getdents`/`stat`, not by CPU, so ripgrep's
 * default (`num_cpus`) buys nothing and costs a great deal: kernel time grows
 * roughly with thread count, and several walks running at once — which is the
 * normal case at agent startup, where rules, skills and the ignore mappings all
 * scan the workspace — collapse into lock contention. On a ~250k-file monorepo
 * (overlayfs, 8 cores) three concurrent walks take 21s at the default and 0.8s
 * capped at one thread; a single walk is also faster capped (0.3s vs 0.8s).
 */
const DEFAULT_MAX_RIPWALK_THREADS = 2;

/**
 * Escape hatch for filesystems where a wider walk really is faster
 * (`0` restores ripgrep's default of one thread per core).
 */
const RIPWALK_THREADS_ENV_VAR = "CURSOR_RIPWALK_THREADS";

export function getRipwalkThreadCount(
  env: NodeJS.ProcessEnv = process.env
): number | undefined {
  const raw = env[RIPWALK_THREADS_ENV_VAR]?.trim();
  if (raw !== undefined && raw !== "") {
    const override = Number(raw);
    if (Number.isInteger(override) && override >= 0) {
      return override === 0 ? undefined : override;
    }
  }
  return Math.min(DEFAULT_MAX_RIPWALK_THREADS, availableParallelism());
}

interface RipgrepProcess extends Disposable {
  readonly stdout: NodeJS.ReadableStream;
  readonly processExit: Promise<number>;
  readonly stderr: () => string;
  readonly aborted: Promise<"aborted">;
}

/**
 * Spawn ripgrep with context for abort signal and cleanup.
 * Returns a disposable that kills process on disposal.
 */
function spawnRipgrep(
  ctx: Context,
  args: string[],
  cwd: string,
  sandboxPolicy: SandboxPolicy
): RipgrepProcess {
  const proc = spawnInSandbox(
    getRipgrepBinaryPath(),
    args,
    { cwd },
    sandboxPolicy
  );

  const stderrChunks: Buffer[] = [];
  proc.stderr?.on("data", (chunk: Buffer) => {
    stderrChunks.push(chunk);
  });

  const processExit = new Promise<number>((resolve, reject) => {
    proc.on("error", reject);
    proc.on("close", (code: number | null) => resolve(code ?? 0));
  });

  if (!proc.stdout) {
    throw new Error("No stdout from ripgrep process");
  }

  const aborted = new Promise<"aborted">(resolve => {
    if (ctx.signal.aborted) {
      resolve("aborted");
      return;
    }
    ctx.signal.addEventListener("abort", () => resolve("aborted"), {
      once: true,
    });
  });

  return {
    stdout: proc.stdout,
    processExit,
    stderr: () => Buffer.concat(stderrChunks).toString(),
    aborted,
    [Symbol.dispose]() {
      proc.kill();
    },
  };
}

export interface RipwalkOptions {
  /** Root directory to search */
  root: string;
  /**
   * Paths (relative to `root`) passed to ripgrep as positional arguments.
   * Restricts the walk to these subtrees while keeping `root` as the working
   * directory that relative ignore patterns (e.g. `--cursor-ignore` files)
   * anchor to. When empty, ripgrep walks `root` itself.
   */
  searchPaths?: readonly string[];
  /** Glob patterns to include */
  includeGlobs?: readonly string[];
  /** Glob patterns to exclude */
  excludeGlobs?: readonly string[];
  /** Case-sensitive matching (defaults to false) */
  caseSensitive?: boolean;
  /** Cursor ignore files to respect (custom --cursor-ignore flag) */
  cursorIgnoreFiles?: readonly string[];
  /** Sandbox policy (defaults to no sandbox) */
  sandboxPolicy?: SandboxPolicy;
  /** Disable VCS ignore rules (allows searching inside .git directories) */
  noIgnoreVcs?: boolean;
  /** Follow symbolic links (defaults to false) */
  followSymlinks?: boolean;
  /**
   * Why this walk is happening — used only by the ripgrep-invocation monitor to
   * explain why rg was spawned. Not part of the ripwalk cache key.
   */
  source?: RipgrepInvocationSource;
}

export interface RipwalkResult {
  lines: AsyncIterable<string>;
  didTimeout: Promise<boolean>;
}

/**
 * Walk directory tree via ripgrep with automatic error handling.
 *
 * Streams files/paths as they're discovered with:
 * - Abort signal support (returns partial results on abort)
 * - Exit code validation (only throws if no results and bad exit)
 * - Stderr logging (warns but doesn't throw if got results)
 *
 * @example
 * ```typescript
 * // List all files with timeout
 * const ctx = createContext().withTimeout(5000);
 * const { lines, didTimeout } = ripwalk(ctx, { root: '/workspace' });
 * for await (const path of lines) {
 *   console.log(path);
 * }
 * if (await didTimeout) {
 *   console.warn('Operation was aborted');
 * }
 * ```
 */
export function ripwalk(
  ctx: Context,
  {
    root,
    searchPaths = [],
    includeGlobs = [],
    excludeGlobs = [],
    caseSensitive = false,
    cursorIgnoreFiles = [],
    sandboxPolicy = { type: "insecure_none" } satisfies SandboxPolicy,
    noIgnoreVcs = false,
    followSymlinks = false,
    source = "ripwalk",
  }: RipwalkOptions
): RipwalkResult {
  // Build ripgrep args - always respect .gitignore even outside git repos
  const args: string[] = [
    "--files",
    "--hidden",
    "--no-require-git",
    "--no-config",
    "--color=never",
  ];

  const threads = getRipwalkThreadCount();
  if (threads !== undefined) {
    args.push("--threads", String(threads));
  }

  // Follow symbolic links
  if (followSymlinks) {
    args.push("--follow");
  }

  // Disable VCS ignore rules (allows searching inside .git directories)
  if (noIgnoreVcs) {
    args.push("--no-ignore-vcs");
  }

  if (caseSensitive) {
    args.push("--case-sensitive");
  }

  // Add cursor ignore files (custom flag)
  for (const ignoreFile of cursorIgnoreFiles) {
    args.push("--cursor-ignore", ignoreFile);
  }

  // Add include globs (case-insensitive)
  for (const glob of includeGlobs) {
    args.push("--iglob", glob);
  }

  // Add exclude globs (case-insensitive)
  for (const glob of excludeGlobs) {
    args.push("--iglob", `!${glob}`);
  }

  // Positional paths must come last; output lines stay relative to `root`.
  if (searchPaths.length > 0) {
    args.push("--", ...searchPaths);
  }

  // Shared state for abort tracking
  let abortResolved = false;
  let resolveDidTimeout: (value: boolean) => void;
  const didTimeout = new Promise<boolean>(resolve => {
    resolveDidTimeout = resolve;
  });

  // The async generator that streams lines
  async function* streamLines(): AsyncGenerator<string> {
    // Spawn ripgrep with automatic cleanup via disposable
    using ripgrep = spawnRipgrep(ctx, args, root, sandboxPolicy);

    if (isRipgrepInvocationRecordingEnabled()) {
      recordRipgrepInvocation({
        timestamp: Date.now(),
        source,
        mode: "files",
        patternLength: 0,
        hasPath: true,
        includeGlobCount: includeGlobs.length,
        excludeGlobCount: excludeGlobs.length,
        sandboxPolicyType: sandboxPolicy.type,
      });
    }

    // Stream files with abort check on each iteration
    let filesYielded = 0;
    const fileIterator = lines(ripgrep.stdout)[Symbol.asyncIterator]();

    while (true) {
      const result = await Promise.race([fileIterator.next(), ripgrep.aborted]);

      if (result === "aborted") {
        abortResolved = true;
        resolveDidTimeout(true);
        break;
      }

      if (result.done) break;

      filesYielded++;
      yield result.value;
    }

    // After streaming, check exit code and stderr
    if (filesYielded > 0) {
      // Got results - ignore stderr warnings (permission denied, missing files, etc.)
      // These are not actionable when we have valid results
    } else if (!abortResolved) {
      // No results and didn't abort - check why
      const exitCode = await ripgrep.processExit;
      // Ripgrep exit codes: 0 = matches found, 1 = no matches (success), 2+ = error
      if (exitCode !== 0 && exitCode !== 1) {
        const stderr = ripgrep.stderr();
        throw new Error(
          `Ripgrep failed (exit ${exitCode}) with no results${stderr ? `: ${stderr}` : ""}`
        );
      }
    }

    // Resolve didTimeout to false if we completed without abort
    if (!abortResolved) {
      resolveDidTimeout(false);
    }
  }

  return {
    lines: streamLines(),
    didTimeout,
  };
}

async function* lines(stream: NodeJS.ReadableStream): AsyncGenerator<string> {
  let buffer = "";
  for await (const chunk of stream) {
    buffer += chunk.toString();
    const parts = buffer.split("\n");
    buffer = parts.pop() ?? "";
    yield* parts;
  }
  if (buffer) yield buffer;
}
