import { SimpleControlledExecHandler } from "./controlled.js";
import { ExecutorResource } from "./remote.js";
import { createResource } from "./resource-provider.js";
import { createClientDeserializer, createClientSerializer, createServerDeserializer, createServerSerializer, } from "./serialization.js";
export const recordScreenExecutorResource = createResource(execManager => new ExecutorResource(execManager, createServerSerializer("recordScreenArgs"), createClientDeserializer("recordScreenResult")), (implementation, controlledExecManager) => {
    controlledExecManager.register(new SimpleControlledExecHandler(implementation, createServerDeserializer("recordScreenArgs"), createClientSerializer("recordScreenResult")));
});
