const logger = createLogger("local-exec:mcp");

function isPathWithin(root: string, candidate: string): boolean {
  const relative = path.relative(root, candidate);
  return (
    relative === "" ||
    (!path.isAbsolute(relative) &&
      relative !== ".." &&
      !relative.startsWith(`..${path.sep}`))
  );
}

function getErrorCode(error: unknown): string | undefined {
  return error instanceof Error &&
    "code" in error &&
    typeof error.code === "string"
    ? error.code
    : undefined;
}

async function resolveContainedDownloadPath(
  projectDir: string,
  downloadPath: string
): Promise<string> {
  const unresolvedRoot = path.resolve(projectDir);
  const projectRoot = await realpath(unresolvedRoot);
  const target = path.resolve(unresolvedRoot, downloadPath.replace(/^\/+/, ""));
  if (!isPathWithin(unresolvedRoot, target)) {
    throw new Error("downloadPath must stay within the workspace");
  }

  let existingAncestor = path.dirname(target);
  while (true) {
    try {
      const resolvedAncestor = await realpath(existingAncestor);
      if (!isPathWithin(projectRoot, resolvedAncestor)) {
        throw new Error("downloadPath must stay within the workspace");
      }
      break;
    } catch (error: unknown) {
      if (getErrorCode(error) !== "ENOENT") {
        throw error;
      }
      const parent = path.dirname(existingAncestor);
      if (parent === existingAncestor) {
        throw error;
      }
      existingAncestor = parent;
    }
  }

  await mkdir(path.dirname(target), { recursive: true });
  const resolvedParent = await realpath(path.dirname(target));
  if (!isPathWithin(projectRoot, resolvedParent)) {
    throw new Error("downloadPath must stay within the workspace");
  }
  try {
    if ((await lstat(target)).isSymbolicLink()) {
      throw new Error("downloadPath must stay within the workspace");
    }
  } catch (error: unknown) {
    if (getErrorCode(error) !== "ENOENT") {
      throw error;
    }
  }
  return target;
}

async function writeMcpTextOutputToFile(
  textContent: string,
  projectDir: string
): Promise<OutputLocation> {
  const agentToolsDir = path.join(projectDir, AGENT_TOOLS_DIR);
  const filePath = path.join(agentToolsDir, `${randomUUID()}.txt`);
  await mkdir(path.dirname(filePath), { recursive: true });

  const contentToWrite = textContent.slice(0, MAX_OUTPUT_FILE_SIZE);
  const lineCount = contentToWrite.split("\n").length;
  const actualSize = Buffer.byteLength(contentToWrite, "utf8");

  await writeFile(filePath, contentToWrite, "utf8");

  return new OutputLocation({
    filePath,
    sizeBytes: BigInt(actualSize),
    lineCount: BigInt(lineCount),
  });
}

function createInlineTextContentItem(
  textContent: string
): McpToolResultContentItem {
  return new McpToolResultContentItem({
    content: {
      case: "text",
      value: new McpTextContent({ text: textContent }),
    },
  });
}

/**
 * Sanitize server name for use in file paths.
 * Replaces spaces with underscores, removes special characters, normalizes
 * consecutive dots, and prevents dot-only names that would resolve to parent
 * directories.
 */
export function sanitizeServerName(name: string): string {
  const sanitized: string = name
    .replace(/\s/g, "_")
    .replace(/[^a-zA-Z0-9_.-]/g, "");
  const normalizedDots: string = sanitized.replace(/\.+/g, ".");
  if (normalizedDots === "." || normalizedDots === "..") {
    return normalizedDots.replace(/\./g, "_");
  }
  return normalizedDots.length === 0 ? "_" : normalizedDots;
}

/**
 * Sanitize MCP tool name for use in file paths.
 * Replaces any non-alphanumeric characters (except - and _) with underscores.
 */
export function sanitizeMcpToolName(name: string): string {
  return name.replace(/[^a-zA-Z0-9_-]/g, "_");
}

/**
 * Server descriptor input for computing MCP file system options.
 */
export interface McpServerDescriptorInput {
  /** Unique identifier for the server (e.g., "user-github", "project-0-my-server") */
  serverIdentifier: string;
  /** Display name of the server */
  serverName: string;
  /** Optional usage instructions for the server */
  serverUseInstructions?: string;
  /** List of tools available from this server */
  toolNames: string[];
}

/**
 * Computes MCP file system options from server descriptors.
 * This is a shared utility that can be used by both the CLI/daemon and VSCode extension.
 *
 * @param projectDir - The workspace project directory
 * @param servers - Array of server descriptors with identifier, name, and optional instructions
 * @returns McpFileSystemOptions with enabled=true and descriptors for each server
 */
export function computeMcpFileSystemOptions(
  projectDir: string,
  servers: McpServerDescriptorInput[]
): McpFileSystemOptions {
  if (servers.length === 0) {
    return new McpFileSystemOptions({
      enabled: true,
      workspaceProjectDir: projectDir,
      mcpDescriptors: [],
    });
  }

  const mcpsPath = join(projectDir, MCPS_SUBDIR);

  // Build descriptors for each server, deduplicating by folder path
  const seenFolders = new Set<string>();
  const descriptors: McpDescriptor[] = [];

  for (const server of servers) {
    const sanitizedName = sanitizeServerName(server.serverIdentifier);
    const folderPath = join(mcpsPath, sanitizedName);

    if (seenFolders.has(folderPath)) {
      continue;
    }
    seenFolders.add(folderPath);

    // Compute tool definition paths from folder path
    // TODO(jma): Use these paths when writing the files.
    // Currently the files are written elsewhere, with paths constructed separately so they might not match.
    const toolsDir = join(folderPath, MCP_TOOLS_SUBDIR);
    const tools = (server.toolNames ?? []).map(
      toolName =>
        new McpToolDescriptor({
          toolName,
          definitionPath: join(
            toolsDir,
            `${sanitizeMcpToolName(toolName)}.json`
          ),
        })
    );

    descriptors.push(
      new McpDescriptor({
        serverIdentifier: server.serverIdentifier,
        serverName: server.serverName,
        folderPath,
        serverUseInstructions: server.serverUseInstructions,
        tools,
      })
    );
  }

  return new McpFileSystemOptions({
    enabled: true,
    workspaceProjectDir: projectDir,
    mcpDescriptors: descriptors,
  });
}

export type McpExecutionPolicyToolDef = Pick<NamedMcpToolDefinition, "source">;

export interface McpExecutionPolicyDeps {
  permissionsService: PermissionsService;
  pendingDecisionProvider: PendingDecisionProvider;
  toolDef?: McpExecutionPolicyToolDef;
}

/**
 * Applies the same MCP permission and approval gate as {@link LocalMcpToolExecutor}
 * before running tool logic. Returns a terminal {@link McpResult} when execution
 * must stop; returns `undefined` when the caller may proceed.
 */
export async function runMcpPermissionGate(
  ctx: Context,
  args: McpArgs,
  deps: McpExecutionPolicyDeps
): Promise<McpResult | undefined> {
  const blockReason = args.skipApproval
    ? false
    : await deps.permissionsService.shouldBlockMcp(ctx, args);

  if (!blockReason) {
    return undefined;
  }

  const blockResult = await handleBlockReason(blockReason, {
    onNeedsApproval: async (_approvalReason, approvalDetails) => {
      if (approvalDetails.type !== "mcp") {
        return new McpResult({
          result: {
            case: "error",
            value: new McpError({
              error: `Invalid approval details type for MCP execution`,
            }),
          },
        });
      }

      const result = await deps.pendingDecisionProvider.requestApproval({
        type: OperationType.Mcp,
        details: {
          name: approvalDetails.name,
          toolName: approvalDetails.toolName,
          providerIdentifier: approvalDetails.providerIdentifier,
          source: deps.toolDef?.source,
          args: approvalDetails.args,
          reason: approvalDetails.reason ?? _approvalReason,
          canAllowlist: approvalDetails.canAllowlist,
          smartModeApprovalReason: approvalDetails.smartModeApprovalReason,
          smartModeApprovalRequestId:
            approvalDetails.smartModeApprovalRequestId,
        },
        toolCallId: args.toolCallId,
      });

      if (!result.approved) {
        return new McpResult({
          result: {
            case: "rejected",
            value: new McpRejected({
              reason: `User rejected MCP: ${args.name}${
                result.reason ? ` - ${result.reason}` : ""
              }`,
            }),
          },
        });
      }

      if (args.smartModeApprovalOnly) {
        return new McpResult({
          result: {
            case: "approved",
            value: new McpApproved(),
          },
        });
      }

      return null;
    },
    onUserRejected: reason => {
      return new McpResult({
        result: {
          case: "error",
          value: new McpError({
            error: `User rejected MCP: ${args.name}${
              reason ? ` - ${reason}` : ""
            }`,
          }),
        },
      });
    },
    onPermissionDenied: (errorMessage, metadata) => {
      const formattedError = `MCP tool execution blocked: ${args.name} - ${errorMessage}`;
      return new McpResult({
        result: {
          case: "permissionDenied",
          value: new McpPermissionDenied({
            error: formattedError,
            isReadonly: metadata?.isReadonly ?? false,
          }),
        },
      });
    },
  });

  return blockResult ?? undefined;
}

export class LocalMcpToolExecutor implements McpExecutor {
  constructor(
    private readonly toolSet: McpLease,
    private readonly permissionsService: PermissionsService,
    private readonly pendingDecisionProvider: PendingDecisionProvider,
    private readonly projectDir: string,
    private readonly fileOutputThresholdBytes: number = MCP_TEXT_FILE_THRESHOLD_BYTES,
    private readonly elicitationFactory?:
      | McpElicitationProviderFactory
      | undefined,
    private readonly ensureMcpServersLoaded?: (
      ctx: Context,
      serverIdentifiers: readonly string[]
    ) => Promise<void>
  ) {}

  /**
   * Describes why a known MCP server currently exposes no tools, or undefined
   * when no client matches any of `identifiers`.
   */
  private async describeDisconnectedServer(
    ctx: Context,
    identifiers: readonly string[]
  ): Promise<string | undefined> {
    const wanted = new Set(identifiers.filter(identifier => identifier !== ""));
    if (wanted.size === 0) {
      return undefined;
    }
    let clients: Record<string, McpClient>;
    try {
      clients = await this.toolSet.getClients(ctx);
    } catch {
      return undefined;
    }
    const match = Object.entries(clients).find(
      ([clientKey, client]) =>
        wanted.has(clientKey) || wanted.has(client.serverName)
    );
    if (match === undefined) {
      return undefined;
    }
    const [clientKey, client] = match;
    let state: McpClientState;
    try {
      state = await client.getState(ctx);
    } catch {
      return undefined;
    }
    if (state.kind === "ready") {
      return undefined;
    }
    // Same wording tool discovery uses for the state, so the two surfaces
    // cannot describe one condition two different ways.
    const reason = mcpServerUnavailableReason(
      mcpClientStateToServerStatus(state)
    );
    if (reason === undefined) {
      return undefined;
    }
    const detail =
      state.kind === "error" && state.message ? ` (${state.message})` : "";
    return `MCP server "${clientKey}" has no callable tools right now. ${reason}${detail}`;
  }

  async execute(parentCtx: Context, args: McpArgs): Promise<McpResult> {
    using span = createSpan(parentCtx.withName("LocalMcpToolExecutor.execute"));
    const ctx = span.ctx;

    const serverIdentifier = args.serverIdentifier || args.providerIdentifier;
    await this.ensureMcpServersLoaded?.(ctx, [serverIdentifier]);
    const tools = await this.toolSet.getTools(ctx);
    const availableServers = Array.from(
      new Set(tools.map(tool => tool.clientKey))
    ).sort();
    const toolDef = tools.find(
      t =>
        t.providerIdentifier === args.providerIdentifier &&
        t.toolName === args.toolName
    );

    const gateResult = await runMcpPermissionGate(ctx, args, {
      permissionsService: this.permissionsService,
      pendingDecisionProvider: this.pendingDecisionProvider,
      toolDef,
    });
    if (gateResult !== undefined) {
      return gateResult;
    }

    const toolSet = await this.toolSet.getToolSet(ctx);

    let result: {
      content: McpToolResultContent;
      isError: boolean;
      structuredContent?: Record<string, JsonValue>;
    };
    try {
      result = await toolSet.execute(
        args.name,
        Object.fromEntries(
          Object.entries(args.args).map(([key, value]) => [key, value.toJson()])
        ),
        args.toolCallId,
        this.elicitationFactory
      );
    } catch (error) {
      let mappedError: unknown = error;
      if (
        isMcpToolNotFoundError(mappedError) &&
        args.providerIdentifier.length > 0 &&
        !tools.some(
          tool =>
            tool.clientKey === args.providerIdentifier ||
            tool.providerIdentifier === args.providerIdentifier
        )
      ) {
        mappedError = new McpServerNotFoundError(
          args.providerIdentifier,
          availableServers
        );
      }
      if (mappedError instanceof McpServerNotFoundError) {
        // A configured server whose client left `ready` (401, transport error,
        // still loading) contributes no tools, which is indistinguishable from
        // "never existed" by tool lookup alone. Say what actually happened so
        // the model authenticates or waits instead of guessing server names.
        const disconnected = await this.describeDisconnectedServer(ctx, [
          serverIdentifier,
          args.providerIdentifier,
        ]);
        if (disconnected !== undefined) {
          return new McpResult({
            result: {
              case: "error",
              value: new McpError({ error: disconnected }),
            },
          });
        }
        return new McpResult({
          result: {
            case: "serverNotFound",
            value: new McpServerNotFound({
              name: mappedError.serverName,
              availableServers: mappedError.availableServers,
            }),
          },
        });
      }
      if (isMcpToolNotFoundError(mappedError)) {
        return new McpResult({
          result: {
            case: "toolNotFound",
            value: new McpToolNotFound({
              name: mappedError.toolName,
              availableTools: mappedError.availableTools,
            }),
          },
        });
      }
      throw mappedError;
    }

    const contentItems: McpToolResultContentItem[] = [];

    for (const item of result.content) {
      // Cast to access type as a string for runtime type checks
      // MCP spec includes resource_link and resource types not in our TS types
      const itemType = (item as { type: string }).type;

      if (itemType === "text") {
        const textItem = item as { type: "text"; text: string };
        contentItems.push(createInlineTextContentItem(textItem.text));
      } else if (itemType === "resource") {
        // Handle embedded resource: extract text content
        const resourceItem = item as unknown as {
          type: string;
          resource?: {
            uri: string;
            name?: string;
            mimeType?: string;
            text?: string;
            blob?: string;
          };
        };
        if (resourceItem.resource?.text) {
          contentItems.push(
            createInlineTextContentItem(resourceItem.resource.text)
          );
        }
      } else if (itemType === "image") {
        const imageItem = item as {
          type: string;
          data: string;
          mimeType?: string;
        };
        const dataBytes: Buffer = Buffer.from(imageItem.data, "base64");
        const resizedImage: ResizedImageResult =
          await resizeImageBufferIfNeeded(dataBytes);
        contentItems.push(
          new McpToolResultContentItem({
            content: {
              case: "image",
              value: new McpImageContent({
                data: resizedImage.data,
                mimeType: resizedImage.mimeType,
              }),
            },
          })
        );
      } else if (itemType !== "image") {
        // Handle other content types by extracting text
        const textContent = extractTextFromNonTextContent(item);
        contentItems.push(createInlineTextContentItem(textContent));
      }
    }

    const materializedContentItems = await materializeMcpTextOutput({
      contentItems,
      thresholdBytes: this.fileOutputThresholdBytes,
      write: text => writeMcpTextOutputToFile(text, this.projectDir),
    });
    if (materializedContentItems === undefined) {
      throw new Error("Failed to materialize MCP text output");
    }

    const structuredContentForProto =
      result.structuredContent &&
      typeof result.structuredContent === "object" &&
      !Array.isArray(result.structuredContent)
        ? Struct.fromJson(result.structuredContent as Record<string, JsonValue>)
        : undefined;
    const successValue = new McpSuccess({
      content: materializedContentItems,
      isError: result.isError,
      structuredContent: structuredContentForProto,
    });

    return new McpResult({
      result: {
        case: "success",
        value: successValue,
      },
    });
  }
}

export class LocalListMcpResourcesExecutor implements ListMcpResourcesExecutor {
  constructor(
    private readonly mcpLease: McpLease,
    private readonly ensureMcpServersLoaded?: (
      ctx: Context,
      serverIdentifiers: readonly string[]
    ) => Promise<void>
  ) {}

  async execute(
    parentCtx: Context,
    args: ListMcpResourcesExecArgs
  ): Promise<ListMcpResourcesExecResult> {
    using span = createSpan(
      parentCtx.withName("LocalListMcpResourcesExecutor.execute")
    );
    const ctx = span.ctx;

    try {
      if (args.server) {
        await this.ensureMcpServersLoaded?.(ctx, [args.server]);
        const clients = await this.mcpLease.getClients(ctx);
        const client =
          clients[args.server] ??
          Object.values(clients).find(
            candidate => candidate.serverName === args.server
          );
        if (!client) {
          return new ListMcpResourcesExecResult({
            result: {
              case: "error",
              value: new ListMcpResourcesError({
                error: `Server "${args.server}" not found`,
              }),
            },
          });
        }
        const resources = await this.listResourcesFromClient(
          ctx,
          client,
          args.server,
          true
        );
        return new ListMcpResourcesExecResult({
          result: {
            case: "success",
            value: new ListMcpResourcesSuccess({ resources }),
          },
        });
      }
      const clients = await this.mcpLease.getClients(ctx);
      // Get enabled servers from mcpLease
      const enabledServerNames = new Set<string>();
      const tools = await this.mcpLease.getTools(ctx);
      for (const tool of tools) {
        // Add both with and without 'user-' prefix to handle both naming conventions
        enabledServerNames.add(tool.providerIdentifier);
        enabledServerNames.add(`user-${tool.providerIdentifier}`);
      }

      const allResources: ListMcpResourcesExecResult_McpResource[] = [];

      // List resources from all enabled clients
      for (const [serverName, client] of Object.entries(clients)) {
        // Skip disabled servers
        if (
          enabledServerNames.size > 0 &&
          !enabledServerNames.has(serverName)
        ) {
          continue;
        }

        const resources = await this.listResourcesFromClient(
          ctx,
          client,
          serverName
        );
        allResources.push(...resources);
      }

      return new ListMcpResourcesExecResult({
        result: {
          case: "success",
          value: new ListMcpResourcesSuccess({
            resources: allResources,
          }),
        },
      });
    } catch (error: unknown) {
      const errorMessage =
        error instanceof Error ? error.message : String(error);
      return new ListMcpResourcesExecResult({
        result: {
          case: "error",
          value: new ListMcpResourcesError({
            error: `Failed to list MCP resources: ${errorMessage}`,
          }),
        },
      });
    }
  }

  private async listResourcesFromClient(
    ctx: Context,
    client: McpClient,
    serverName: string,
    initialize: boolean = false
  ): Promise<ListMcpResourcesExecResult_McpResource[]> {
    const state = await client.getState(ctx);
    if (state.kind !== "ready" && !(initialize && state.kind === "loading")) {
      return [];
    }

    const result = await client.listResources(ctx);

    if (!result || !result.resources) {
      return [];
    }

    return result.resources.map(
      resource =>
        new ListMcpResourcesExecResult_McpResource({
          uri: resource.uri,
          name: resource.name,
          description: resource.description,
          mimeType: resource.mimeType,
          server: serverName,
          annotations: resource.annotations as
            | Record<string, string>
            | undefined,
        })
    );
  }
}

export class LocalReadMcpResourceExecutor implements ReadMcpResourceExecutor {
  private readonly workspacePaths: readonly string[];

  constructor(
    private readonly mcpLease: McpLease,
    private readonly projectDir: string = ".",
    private readonly permissionsService?: PermissionsService | undefined,
    workspacePaths: readonly string[] = [],
    private readonly pendingDecisionProvider?:
      | PendingDecisionProvider
      | undefined,
    private readonly ensureMcpServersLoaded?: (
      ctx: Context,
      serverIdentifiers: readonly string[]
    ) => Promise<void>
  ) {
    // Filter empties so callers passing [""] (no folder open) fall through
    // to the projectDir branch instead of writing to "/".
    this.workspacePaths = workspacePaths.filter(p => p.length > 0);
  }

  // Resolves the base directory for relative download paths. Priority:
  //   1. Per-request override from the conversation hook (cloud agent / daemon).
  //   2. The first actual workspace folder. In multi-root windows this avoids
  //      the legacy fallback to the *common parent* (e.g. "/tmp" for two
  //      folders under /tmp), which writes outside any workspace folder.
  //   3. The executor's projectDir (mainly the no-workspace / CLI fallback).
  private resolveProjectDir(ctx: Context): string {
    const ctxRoots = ctx.get(execHookWorkspaceRootsKey);
    const ctxRoot = ctxRoots?.find(p => typeof p === "string" && p.length > 0);
    if (ctxRoot) {
      return ctxRoot;
    }
    if (this.workspacePaths.length > 0) {
      return this.workspacePaths[0];
    }
    return this.projectDir;
  }

  async execute(
    parentCtx: Context,
    args: ReadMcpResourceExecArgs
  ): Promise<ReadMcpResourceExecResult> {
    using span = createSpan(
      parentCtx.withName("LocalReadMcpResourceExecutor.execute")
    );
    const ctx = span.ctx;

    const smartModeApprovalReason = args.smartModeApproval?.reason;
    if (smartModeApprovalReason !== undefined) {
      if (this.pendingDecisionProvider === undefined) {
        return new ReadMcpResourceExecResult({
          result: {
            case: "error",
            value: new ReadMcpResourceError({
              uri: args.uri,
              error: "Auto-review approval provider is not configured",
            }),
          },
        });
      }

      const approval = await this.pendingDecisionProvider.requestApproval({
        type: OperationType.Mcp,
        details: {
          name: "FetchMcpResource",
          toolName: "FetchMcpResource",
          providerIdentifier: args.server,
          args: {
            server: Value.fromJson(args.server),
            uri: Value.fromJson(args.uri),
            ...(args.downloadPath !== undefined
              ? { downloadPath: Value.fromJson(args.downloadPath) }
              : {}),
          },
          reason: "smartMode",
          canAllowlist: false,
          smartModeApprovalReason,
          smartModeApprovalRequestId: args.smartModeApproval?.requestId,
        },
        toolCallId: args.toolCallId,
      });

      if (!approval.approved) {
        return new ReadMcpResourceExecResult({
          result: {
            case: "rejected",
            value: new ReadMcpResourceRejected({
              reason: `User rejected MCP resource fetch${
                approval.reason ? ` - ${approval.reason}` : ""
              }`,
            }),
          },
        });
      }
    }

    await this.ensureMcpServersLoaded?.(ctx, [args.server]);
    const clients = await this.mcpLease.getClients(ctx);
    const client =
      clients[args.server] ??
      Object.values(clients).find(
        candidate => candidate.serverName === args.server
      );

    if (!client) {
      return new ReadMcpResourceExecResult({
        result: {
          case: "error",
          value: new ReadMcpResourceError({
            uri: args.uri,
            error: `Server "${args.server}" not found`,
          }),
        },
      });
    }

    try {
      const state = await client.getState(ctx);
      if (state.kind !== "ready") {
        return new ReadMcpResourceExecResult({
          result: {
            case: "error",
            value: new ReadMcpResourceError({
              uri: args.uri,
              error: `Server "${args.server}" is not ready`,
            }),
          },
        });
      }

      const result = await client.readResource(ctx, {
        uri: args.uri,
      });

      if (!result || !result.contents || result.contents.length === 0) {
        return new ReadMcpResourceExecResult({
          result: {
            case: "notFound",
            value: new ReadMcpResourceNotFound({
              uri: args.uri,
            }),
          },
        });
      }

      const content = result.contents[0];

      // Handle download path if specified
      if (args.downloadPath) {
        const downloadFullPath = await resolveContainedDownloadPath(
          this.resolveProjectDir(ctx),
          args.downloadPath
        );

        if (content.text) {
          await writeFile(downloadFullPath, content.text, "utf8");
        } else if (content.blob) {
          const blobData = Buffer.from(content.blob, "base64");
          await writeFile(downloadFullPath, blobData);
        }

        return new ReadMcpResourceExecResult({
          result: {
            case: "success",
            value: new ReadMcpResourceSuccess({
              uri: args.uri,
              name: content.name,
              description: content.description,
              mimeType: content.mimeType,
            }),
          },
        });
      }

      if (content.text) {
        return new ReadMcpResourceExecResult({
          result: {
            case: "success",
            value: new ReadMcpResourceSuccess({
              uri: args.uri,
              name: content.name,
              description: content.description,
              mimeType: content.mimeType,
              annotations: content.annotations as
                | Record<string, string>
                | undefined,
              content: {
                case: "text",
                value: content.text,
              },
            }),
          },
        });
      }

      if (content.blob) {
        const blobData = Buffer.from(content.blob, "base64");
        return new ReadMcpResourceExecResult({
          result: {
            case: "success",
            value: new ReadMcpResourceSuccess({
              uri: args.uri,
              name: content.name,
              description: content.description,
              mimeType: content.mimeType,
              annotations: content.annotations as
                | Record<string, string>
                | undefined,
              content: {
                case: "blob",
                value: blobData,
              },
            }),
          },
        });
      }

      return new ReadMcpResourceExecResult({
        result: {
          case: "error",
          value: new ReadMcpResourceError({
            uri: args.uri,
            error: "Failed to read resource",
          }),
        },
      });
    } catch (error: unknown) {
      const errorMessage =
        error instanceof Error ? error.message : String(error);
      logger.warn(ctx, "LocalReadMcpResourceExecutor.execute failed", {
        server: args.server,
        hasDownloadPath: Boolean(args.downloadPath),
        errorName: error instanceof Error ? error.name : typeof error,
        errorMessage,
      });
      return new ReadMcpResourceExecResult({
        result: {
          case: "error",
          value: new ReadMcpResourceError({
            uri: args.uri,
            error: `Failed to read MCP resource: ${errorMessage}`,
          }),
        },
      });
    }
  }
}
