import { spawn } from "node:child_process";
import { readFile, stat } from "node:fs/promises";
import { basename, relative } from "node:path";
import { createInterface } from "node:readline";
import type { PiGrepExecutor } from "@anysphere/agent-exec";
import { type Context, createSpan } from "@anysphere/context";
import {
  type PiGrepExecArgs,
  PiGrepExecError,
  PiGrepExecResult,
  PiGrepExecSuccess,
} from "@anysphere/proto/agent/v1/pi_grep_exec_pb.js";
import { getRipgrepBinaryPath } from "@anysphere/shell-exec";
import type { PermissionsService } from "../services/permissions-service.js";
import { blockReasonToString } from "./common.js";
import { resolvePiPath } from "./path.js";
import {
  formatSize,
  PI_DEFAULT_MAX_BYTES,
  truncateHead,
  truncateLine,
} from "./truncate.js";

const DEFAULT_LIMIT = 100;

interface Match {
  filePath: string;
  lineNumber: number;
  lineText?: string;
}

export class LocalPiGrepExecutor implements PiGrepExecutor {
  constructor(
    private readonly permissionsService: PermissionsService,
    private readonly workspacePath?: string
  ) {}

  async execute(
    parentCtx: Context,
    args: PiGrepExecArgs
  ): Promise<PiGrepExecResult> {
    using span = createSpan(parentCtx.withName("LocalPiGrepExecutor.execute"));
    const searchPath = resolvePiPath(args.path || ".", this.workspacePath);
    const shouldBlock =
      await this.permissionsService.shouldBlockRead(searchPath);
    if (shouldBlock) {
      return this.error(`Search blocked: ${blockReasonToString(shouldBlock)}`);
    }

    try {
      const isDirectory = (await stat(searchPath)).isDirectory();
      const rgArgs = ["--json", "--line-number", "--color=never", "--hidden"];
      if (args.ignoreCase) rgArgs.push("--ignore-case");
      if (args.literal) rgArgs.push("--fixed-strings");
      if (args.glob !== undefined) rgArgs.push("--glob", args.glob);
      rgArgs.push("--", args.pattern, searchPath);
      const child = spawn(getRipgrepBinaryPath(), rgArgs, {
        stdio: ["ignore", "pipe", "pipe"],
      });
      const matches: Match[] = [];
      let stderr = "";
      let matchLimitReached = false;
      const limit = Math.max(1, args.limit ?? DEFAULT_LIMIT);
      const rl = createInterface({ input: child.stdout });
      child.stderr?.on("data", chunk => {
        stderr += chunk.toString();
      });
      rl.on("line", line => {
        if (matches.length >= limit || line.trim().length === 0) return;
        const parsed = JSON.parse(line) as {
          type?: string;
          data?: {
            path?: { text?: string };
            line_number?: number;
            lines?: { text?: string };
          };
        };
        if (parsed.type !== "match") return;
        const filePath = parsed.data?.path?.text;
        const lineNumber = parsed.data?.line_number;
        if (filePath === undefined || lineNumber === undefined) return;
        matches.push({
          filePath,
          lineNumber,
          lineText: parsed.data?.lines?.text?.replace(/\n$/, ""),
        });
        if (matches.length >= limit) {
          matchLimitReached = true;
          child.kill();
        }
      });
      const exitCode = await new Promise<number | null>((resolve, reject) => {
        child.on("error", reject);
        child.on("close", resolve);
      });
      rl.close();
      if (!matchLimitReached && exitCode !== 0 && exitCode !== 1) {
        return this.error(
          stderr.trim() || `ripgrep exited with code ${exitCode}`
        );
      }
      if (matches.length === 0) {
        return this.success("No matches found");
      }
      const allowedMatches: Match[] = [];
      for (const match of matches) {
        if (!(await this.permissionsService.shouldBlockRead(match.filePath))) {
          allowedMatches.push(match);
        }
      }
      if (allowedMatches.length === 0) {
        return this.success("No matches found");
      }
      const { output, linesTruncated } = await this.formatMatches(
        allowedMatches,
        searchPath,
        isDirectory,
        Math.max(0, args.context ?? 0)
      );
      const truncated = truncateHead(output, {
        maxLines: Number.MAX_SAFE_INTEGER,
      });
      const notices: string[] = [];
      if (matchLimitReached)
        notices.push(
          `${limit} matches limit reached. Use limit=${limit * 2} for more, or refine pattern`
        );
      if (truncated.truncation.truncated)
        notices.push(`${formatSize(PI_DEFAULT_MAX_BYTES)} limit reached`);
      if (linesTruncated)
        notices.push(
          "Some lines truncated to 500 chars. Use read tool to see full lines"
        );
      return this.success(
        notices.length > 0
          ? `${truncated.content}\n\n[${notices.join(". ")}]`
          : truncated.content,
        {
          matchLimitReached: matchLimitReached ? limit : undefined,
          linesTruncated,
          truncation: truncated.truncation.truncated
            ? truncated.truncation
            : undefined,
        }
      );
    } catch (error) {
      return this.error(
        error instanceof Error ? error.message : "Unknown grep error"
      );
    }
  }

  private async formatMatches(
    matches: Match[],
    searchPath: string,
    isDirectory: boolean,
    context: number
  ): Promise<{ output: string; linesTruncated: boolean }> {
    const outputLines: string[] = [];
    let linesTruncated = false;
    for (const match of matches) {
      const displayPath = isDirectory
        ? relative(searchPath, match.filePath)
        : basename(match.filePath);
      if (context === 0 && match.lineText !== undefined) {
        const line = truncateLine(match.lineText);
        linesTruncated = linesTruncated || line.wasTruncated;
        outputLines.push(`${displayPath}:${match.lineNumber}: ${line.text}`);
        continue;
      }
      const fileLines = (await readFile(match.filePath, "utf8"))
        .replace(/\r\n/g, "\n")
        .replace(/\r/g, "\n")
        .split("\n");
      const start = Math.max(1, match.lineNumber - context);
      const end = Math.min(fileLines.length, match.lineNumber + context);
      for (let lineNumber = start; lineNumber <= end; lineNumber++) {
        const line = truncateLine(fileLines[lineNumber - 1] ?? "");
        linesTruncated = linesTruncated || line.wasTruncated;
        outputLines.push(
          lineNumber === match.lineNumber
            ? `${displayPath}:${lineNumber}: ${line.text}`
            : `${displayPath}-${lineNumber}- ${line.text}`
        );
      }
    }
    return { output: outputLines.join("\n"), linesTruncated };
  }

  private success(
    output: string,
    details?: {
      truncation?: PiGrepExecSuccess["truncation"];
      matchLimitReached?: number;
      linesTruncated?: boolean;
    }
  ): PiGrepExecResult {
    return new PiGrepExecResult({
      result: {
        case: "success",
        value: new PiGrepExecSuccess({
          output,
          truncation: details?.truncation,
          matchLimitReached: details?.matchLimitReached,
          linesTruncated: details?.linesTruncated ?? false,
        }),
      },
    });
  }

  private error(error: string): PiGrepExecResult {
    return new PiGrepExecResult({
      result: { case: "error", value: new PiGrepExecError({ error }) },
    });
  }
}
