export const UTF8_ENCODING: string = "utf8";
export const UTF8_BOM_ENCODING: string = "utf8bom";
export const LATIN1_ENCODING: string = "latin1";

export const ENCODING_MAPPINGS: Readonly<Record<string, string>> = {
  // Windows codepages
  "windows-1250": "cp1250",
  "windows-1251": "cp1251",
  "windows-1252": "cp1252",
  "windows-1253": "cp1253",
  "windows-1254": "cp1254",
  "windows-1255": "cp1255",
  "windows-1256": "cp1256",
  "windows-1257": "cp1257",
  "windows-1258": "cp1258",
  // ISO-8859 family
  "iso-8859-1": "iso88591",
  "iso-8859-2": "iso88592",
  "iso-8859-5": "iso88595",
  "iso-8859-6": "iso88596",
  "iso-8859-7": "iso88597",
  "iso-8859-8": "iso88598",
  "iso-8859-9": "iso88599",
  "iso-8859-15": "iso885915",
  "iso-8859-16": "iso885916",
  // East Asian
  shift_jis: "shiftjis",
  "euc-jp": "eucjp",
  "euc-kr": "euckr",
  "iso-2022-jp": "iso2022jp",
  "iso-2022-kr": "iso2022kr",
  gb2312: "gb2312",
  gbk: "gbk",
  gb18030: "gb18030",
  big5: "big5",
  "big5-hkscs": "big5hkscs",
  // Cyrillic
  "koi8-r": "koi8r",
  "koi8-u": "koi8u",
  ibm855: "cp855",
  ibm866: "cp866",
  maccyrillic: "maccyrillic",
  // UTF encodings
  "utf-16le": "utf16le",
  "utf-16be": "utf16be",
  "utf-32le": "utf32le",
  "utf-32be": "utf32be",
  // Other
  johab: "johab",
  cp949: "cp949",
  cp932: "cp932",
};

/**
 * Maps encoding names from jschardet to iconv-lite compatible names.
 */
export function mapToIconvEncoding(encoding: string): string {
  return ENCODING_MAPPINGS[encoding] || encoding;
}

export function stripUtf8Bom(text: string): string {
  return text.startsWith("\uFEFF") ? text.slice(1) : text;
}

export function normalizeEncodingName(encoding: string): string {
  const normalized = encoding.toLowerCase();
  if (normalized === "latin-1") {
    return LATIN1_ENCODING;
  }
  if (normalized === "utf-8") {
    return UTF8_ENCODING;
  }
  if (normalized === "utf-8-bom" || normalized === "utf-8 bom") {
    return UTF8_BOM_ENCODING;
  }
  return normalized;
}

/**
 * Maps VS Code encoding setting IDs (keys from SUPPORTED_ENCODINGS in
 * vscode/src/vs/workbench/services/textfile/common/encoding.ts) to
 * iconv-lite compatible encoding names.
 *
 * Most VS Code encoding IDs are already iconv-lite compatible. The main
 * exceptions are the `windowsXXXX` → `cpXXXX` pattern.
 */
const VSCODE_ENCODING_MAPPINGS: Readonly<Record<string, string>> = {
  utf8: "utf8",
  utf8bom: "utf8bom",
  utf16le: "utf16le",
  utf16be: "utf16be",
  // Windows codepages
  windows1250: "cp1250",
  windows1251: "cp1251",
  windows1252: "cp1252",
  windows1253: "cp1253",
  windows1254: "cp1254",
  windows1255: "cp1255",
  windows1256: "cp1256",
  windows1257: "cp1257",
  windows1258: "cp1258",
  windows874: "cp874",
  // Cyrillic
  cp1125: "cp1125",
  // These are already iconv-compatible: shiftjis, euckr, eucjp, gbk, gb2312,
  // gb18030, big5, big5hkscs, iso88591..16, cp437, cp850, cp852, cp865,
  // koi8r, koi8u, koi8ru, koi8t, macroman
};

/**
 * Normalizes a VS Code encoding setting ID to an iconv-lite compatible
 * encoding name. Returns the input as-is if no mapping is found (most
 * VS Code encoding IDs are already compatible).
 */
export function normalizeVscodeEncoding(vscodeEncoding: string): string {
  const lower = vscodeEncoding.toLowerCase();
  return VSCODE_ENCODING_MAPPINGS[lower] ?? lower;
}
