import {
  type ShellArgs,
  TimeoutBehavior,
} from "@anysphere/proto/agent/v1/shell_exec_pb.js";

/** Default foreground shell wait before backgrounding (matches legacy `|| 30000`). */
export const DEFAULT_SHELL_FOREGROUND_TIMEOUT_MS = 30_000;

/**
 * Resolve the foreground wait timeout for a shell invocation.
 *
 * `ShellArgs.timeout` is a non-optional proto `int32`, so omitted values decode as
 * `0`. Only treat `0` as intentional when the caller marked a block-until / background
 * execution plan (`timeoutBehavior`, `hardTimeout`, or `isBackground`).
 */
export function resolveShellTimeoutMs(args: ShellArgs): number {
  if (args.timeout !== 0) {
    return args.timeout;
  }
  if (
    args.isBackground ||
    args.timeoutBehavior === TimeoutBehavior.BACKGROUND ||
    (args.hardTimeout !== undefined && args.hardTimeout > 0)
  ) {
    return 0;
  }
  return DEFAULT_SHELL_FOREGROUND_TIMEOUT_MS;
}
