/**
 * McpCoreLogger — injectable logger interface for @anysphere/mcp-core.
 *
 * Each consumer (extension host, utility process, CLI, cloud agent)
 * provides its own implementation that routes to its platform's
 * logging infrastructure.
 */

export interface McpCoreLogOpts {
  /**
   * Suppress forwarding to structured / external log sinks. Used for
   * messages that may contain sensitive data (e.g. tool arguments) so they
   * only land in the local output channel.
   */
  localOnly?: boolean;
}

export interface McpCoreLogger {
  info(
    message: string,
    meta?: Record<string, unknown>,
    opts?: McpCoreLogOpts
  ): void;
  warn(
    message: string,
    meta?: Record<string, unknown>,
    opts?: McpCoreLogOpts
  ): void;
  error(
    message: string,
    error?: Error,
    meta?: Record<string, unknown>,
    opts?: McpCoreLogOpts
  ): void;
  debug(
    message: string,
    meta?: Record<string, unknown>,
    opts?: McpCoreLogOpts
  ): void;
  trace?(
    message: string,
    meta?: Record<string, unknown>,
    opts?: McpCoreLogOpts
  ): void;
}

export interface McpCoreLoggerFactory {
  getLogger(identifier: string): McpCoreLogger;
}

let _loggerFactory: McpCoreLoggerFactory | undefined;

export function setMcpCoreLoggerFactory(factory: McpCoreLoggerFactory): void {
  _loggerFactory = factory;
}

const NULL_LOGGER: McpCoreLogger = {
  info: () => {},
  warn: () => {},
  error: () => {},
  debug: () => {},
};

export function getMcpCoreLogger(identifier: string): McpCoreLogger {
  return _loggerFactory?.getLogger(identifier) ?? NULL_LOGGER;
}

export function getMcpCoreStaticLogger(): McpCoreLogger {
  return _loggerFactory?.getLogger("mcp-core") ?? NULL_LOGGER;
}
