import { SimpleControlledExecHandler } from "./controlled.js";
import { ExecutorResource } from "./remote.js";
import { createResource } from "./resource-provider.js";
import { createClientDeserializer, createClientSerializer, createServerDeserializer, createServerSerializer, } from "./serialization.js";
export const conversationSearchExecutorResource = createResource(execManager => new ExecutorResource(execManager, createServerSerializer("conversationSearchArgs"), createClientDeserializer("conversationSearchResult")), (implementation, controlledExecManager) => {
    controlledExecManager.register(new SimpleControlledExecHandler(implementation, createServerDeserializer("conversationSearchArgs"), createClientSerializer("conversationSearchResult")));
});
