import type { Writable } from "node:stream";
import type { Context } from "@anysphere/context";
import type { ShellOutputLimiterOptions } from "./output-limiter.js";
import type { SandboxPolicyMergeSources } from "./sandbox/policy-merge.js";
import type { SandboxDenyEvent } from "./sandbox/sandbox.js";

/**
 * Network policy for controlling network access in sandboxed processes.
 * Matches the Rust NetworkPolicy schema (v1).
 */
export interface NetworkPolicy {
  /** Policy version. Must be 1. */
  version?: 1;
  /** Default action when no rules match. Defaults to "deny". */
  default?: "allow" | "deny";
  /**
   * Patterns to deny. Highest priority - always blocks.
   * Supports: exact domains, wildcards (*.example.com), CIDR (10.0.0.0/8)
   */
  deny?: string[];
  /**
   * Patterns to allow.
   * Supports: exact domains, wildcards (*.example.com), CIDR (10.0.0.0/8)
   */
  allow?: string[];
  /** Logging configuration. */
  logging?: NetworkPolicyLoggingConfig;
}

export interface NetworkPolicyLoggingConfig {
  /** Path to write decision logs (JSONL format). */
  decisionLogPath?: string;
  /** Log format. Currently only "jsonl" is supported. */
  logFormat?: "jsonl";
}

export type SandboxReadBoundary = "system" | "workspace";

/**
 * Mapping of directory paths to gitignore-style patterns.
 * Patterns are stored as string arrays and parsed lazily when needed.
 */
export interface IgnoreMapping {
  [path: string]: string[];
}

export enum KnownShellExecutor {
  Zsh = "zsh",
  ZshLight = "zsh-light",
  Bash = "bash",
  PowerShell = "powershell",
  Naive = "naive",
}

/**
 * Standard environment overrides for shell execution to ensure consistent behavior:
 * - TERM=dumb: Prevents ANSI color codes and interactive features, also prevents SSH MOTD
 * - NO_COLOR=1: Explicitly disables color output in tools that respect this standard
 * - FORCE_COLOR=0: Disables color for tools that use this convention (like some npm packages)
 */
export const SHELL_ENV_OVERRIDES = {
  TERM: "dumb",
  NO_COLOR: "1",
  FORCE_COLOR: "0",
  _ZO_DOCTOR: "0",
} as const;

export interface ShellExecResult {
  stdout: string;
  stderr: string;
  code: number | null;
}

export type ShellEvent =
  | {
      type: "stdout";
      data: string;
    }
  | {
      type: "stderr";
      data: string;
    }
  | {
      type: "close";
      code: number;
    }
  | {
      type: "error";
      data: Error;
    };

export type TerminalEvent =
  | {
      type: "stdin_ready";
      stdin?: Writable;
      pid?: number;
    }
  | {
      type: "stdout";
      data: Buffer;
    }
  | {
      type: "stderr";
      data: Buffer;
    }
  | {
      /** Trusted executor signal that output forwarding was suppressed. */
      type: "suppressed_output";
    }
  | {
      type: "exit";
      data: string; // NB: this does nothing, it just makes this type less annoying to work with
      code: number | null;
      aborted: boolean;
    }
  | {
      type: "sandbox_denies";
      events: SandboxDenyEvent[];
    };

/**
 * Common options that apply to all sandbox policy types.
 */
interface SandboxPolicyCommon {
  debugOutputDir?: string;
  captureDenies?: boolean;

  /**
   * If true, redirects build tool caches (npm, cargo, pip, etc.) to a shared
   * tmpdir location. This ensures both sandboxed and unsandboxed commands
   * share the same caches.
   */
  enableSharedBuildCache?: boolean;
}

/**
 * Common options for sandbox policies that have network and filesystem controls.
 *
 * For input policies being merged, fields can be undefined meaning "no opinion".
 * The merge function will produce output policies with concrete values for all fields.
 */
interface SandboxedPolicyCommon extends SandboxPolicyCommon {
  /**
   * The original workspace root directory. When set, the sandbox writable root
   * is pinned to this path instead of the process's cwd. This prevents `cd` to
   * a parent directory from expanding the sandbox scope across commands.
   */
  sandboxWorkspaceRoot?: string;
  /**
   * Network policy controlling network access.
   * Undefined means "no opinion" on input; the merge function normalizes to a concrete policy.
   *
   * Use `isNetworkEnabledByPolicy()` to check whether network is enabled:
   *  - `default: "allow"` → allow-all (unrestricted network)
   *  - `default: "deny"` with `allow` entries → allowlist-filtered
   *  - `default: "deny"` with no `allow` entries (or undefined) → network disabled
   */
  networkPolicy?: NetworkPolicy;
  /**
   * When true, Cursor's default network allowlist (from Statsig dynamic config)
   * will NOT be merged into this policy. Only the user's own sandbox.json
   * allowlist and admin controls will apply.
   *
   * Corresponds to the "user_config_only" network mode in user settings.
   * When false or undefined, Statsig defaults are applied as usual
   * ("user_config_with_defaults" mode).
   */
  skipStatsigDefaults?: boolean;
  /**
   * When true (default), any missing or invalid policy causes network access
   * to be disabled (fail closed). When false, network access proceeds without filtering.
   */
  networkPolicyStrict?: boolean;
  /**
   * Filesystem read boundary. Undefined means "system" for backwards compatibility.
   */
  readBoundary?: SandboxReadBoundary;
  /**
   * Extra read-only path/glob roots allowed when readBoundary is "workspace".
   * Ignored when readBoundary is "system".
   */
  additionalReadPaths?: string[];
  additionalReadonlyPaths?: string[];
  ignoreMapping?: IgnoreMapping;
  writeProtectionMapping?: IgnoreMapping;
  /**
   * If true, excludes default tmp paths (/tmp/, /private/tmp/, /var/folders/, /private/var/folders/)
   * from the sandbox policy. Defaults to false. Useful for testing to ensure temp directories
   * are not accessible by default.
   */
  disableTmpWrite?: boolean;
}

/**
 * No sandboxing applied. Command runs with full system access.
 */
export interface InsecureNoneSandboxPolicy extends SandboxPolicyCommon {
  type: "insecure_none";
  /**
   * If true, indicates this policy was applied because the command matched
   * the user's allowlist (auto-escalated from a sandboxed policy).
   */
  allowlistEscalated?: boolean;
}

/**
 * Sandbox with read-write access to the workspace directory.
 */
export interface WorkspaceReadWriteSandboxPolicy extends SandboxedPolicyCommon {
  type: "workspace_readwrite";
  additionalReadwritePaths?: string[];
}

/**
 * Sandbox with read-only access to the workspace directory.
 */
export interface WorkspaceReadOnlySandboxPolicy extends SandboxedPolicyCommon {
  type: "workspace_readonly";
}

export type SandboxPolicy =
  | InsecureNoneSandboxPolicy
  | WorkspaceReadWriteSandboxPolicy
  | WorkspaceReadOnlySandboxPolicy;

export interface TerminalInitializationOptions {
  userTerminalHint?: string;
  signal?: AbortSignal;
  env?: Record<string, string>;
}

export interface NaiveTerminalExecutorOptions {
  shell?: string;
  shellArgs?: readonly string[];
  env?: Record<string, string>;
}

export interface TerminalCommandOptions {
  signal?: AbortSignal;
  workingDirectory?: string;
  pipeStdin?: boolean;
  env?: Record<string, string>;
  sandboxPolicy?: SandboxPolicyMergeSources;

  /**
   * The original workspace root directory. When set, the sandbox writable root
   * is pinned to this path instead of the terminal's current working directory.
   * This prevents `cd` to a parent directory from expanding the sandbox scope.
   * Falls back to workingDirectory/cwd if not provided.
   */
  sandboxWorkspaceRoot?: string;

  /**
   * Maximum time in milliseconds to wait for the 'close' event after 'exit'.
   * If the timeout expires, the command will complete anyway to prevent hanging.
   * Defaults to 5000ms (5 seconds). Set to 0 to wait indefinitely.
   */
  closeTimeout?: number;

  /**
   * When true, consume stdout/stderr with async-iterator backpressure and
   * coalesce chunks before emitting TerminalEvents.
   */
  bufferOutputEvents?: boolean;

  /**
   * Tunables for buffered stdout/stderr event coalescing. Ignored unless
   * bufferOutputEvents is enabled.
   */
  outputLimiterOptions?: ShellOutputLimiterOptions;

  /**
   * Keep any executor-owned terminal mirror active even when mirror suppression
   * is enabled. Used by foreground shells that may be handed off to background
   * ownership after startup.
   */
  preserveTerminalMirror?: boolean;
}

/**
 * Interface for executing terminal commands with streaming output
 */
export interface TerminalExecutor {
  getCwd(): Promise<string>;

  /**
   * Execute a command and return an async iterable of terminal events
   * @param ctx - Context for tracing and logging
   * @param command - The command to execute
   * @param options - Optional command options including signal, working directory, etc.
   * @returns AsyncIterable that yields TerminalEvent objects
   */
  execute(
    ctx: Context,
    command: string,
    options?: TerminalCommandOptions
  ): AsyncIterable<TerminalEvent>;

  /**
   * Clone the executor with its current state
   * @param workingDirectory - Optional working directory to use instead of the current one
   * @returns A new independent executor with the same state
   */
  clone(workingDirectory?: string): TerminalExecutor;
}
