import * as fs from "node:fs/promises";
import path from "node:path";
import type { GitDiffExecutor } from "@anysphere/agent-exec";
import { type Context, createLogger } from "@anysphere/context";
import { checkFilesGenerated, gitSpawn } from "@anysphere/git-core";
import {
  FileDiff,
  FileDiff_Chunk,
  type GetDiffRequest,
  GetDiffRequest_OutputFormat,
  GetDiffResponse,
  GitDiff,
  GitDiff_DiffType,
} from "@anysphere/proto/aiserver/v1/utils_pb.js";
import { type ParseDiffFile, parseDiff } from "./git-diff-parser.js";

const logger = createLogger("local-git-diff");

interface RunGitOptions {
  shouldNotTrimOutput?: boolean;
  ignoreErrors?: boolean;
}

/**
 * Run a git command via spawn (no shell), so special characters in file paths
 * are not interpreted. Mirrors the exec-daemon's `executeGitCommandStable`.
 */
async function runGit(
  cwd: string,
  args: string[],
  options: RunGitOptions = {}
): Promise<string> {
  const result = await new Promise<string>((resolve, reject) => {
    const gitProcess = gitSpawn("git", args, { cwd });
    let stdout = "";
    let stderr = "";
    gitProcess.stdout.on("data", (data: Buffer) => {
      stdout += data.toString();
    });
    gitProcess.stderr.on("data", (data: Buffer) => {
      stderr += data.toString();
    });
    gitProcess.on("close", (code: number | null) => {
      if (code === 0 || options.ignoreErrors === true) {
        // `git diff --no-index` exits 1 when there are differences (expected
        // for untracked files), so callers can opt into ignoring errors.
        resolve(stdout);
      } else {
        reject(new Error(`Git command failed with code ${code}: ${stderr}`));
      }
    });
    gitProcess.on("error", (error: Error) => {
      if (options.ignoreErrors === true) {
        resolve(stdout);
      } else {
        reject(error);
      }
    });
  });
  return options.shouldNotTrimOutput === true ? result : result.trim();
}

function fileDiffToProtoDiff(fileDiff: ParseDiffFile): FileDiff {
  const d = new FileDiff({
    from: fileDiff.from,
    to: fileDiff.to,
    chunks: fileDiff.chunks.map(
      diffChunk =>
        new FileDiff_Chunk({
          content: diffChunk.content,
          lines: diffChunk.changes.map(l => l.content),
          oldStart: diffChunk.oldStart,
          oldLines: diffChunk.oldLines,
          newStart: diffChunk.newStart,
          newLines: diffChunk.newLines,
        })
    ),
  });
  d.added = fileDiff.additions;
  d.removed = fileDiff.deletions;
  return d;
}

function parseGitDiff(input?: string | null): GitDiff {
  const files = parseDiff(input);
  return new GitDiff({
    diffs: files.map(fileDiff => fileDiffToProtoDiff(fileDiff)),
    diffType: GitDiff_DiffType.UNSPECIFIED,
  });
}

function serializeUntrackedFilesForPatchId(
  untrackedFiles: { contents: string; path: string }[]
): string {
  const lines: string[] = [];
  for (const untrackedFile of untrackedFiles) {
    const fileLines = untrackedFile.contents.split("\n");
    const numLines = fileLines.length;
    lines.push(`diff --git a/${untrackedFile.path} b/${untrackedFile.path}`);
    lines.push("--- /dev/null");
    lines.push(`+++ b/${untrackedFile.path}`);
    lines.push(`@@ -0,0 +1${numLines === 1 ? "" : `,${numLines}`} @@`);
    lines.push(...fileLines.map(line => `+${line}`));
  }
  return lines.join("\n");
}

function appendDiffForPatchId(...diffs: string[]): string {
  const nonEmptyDiffs = diffs.filter(diff => diff.length > 0);
  if (nonEmptyDiffs.length === 0) {
    return "";
  }
  return `${nonEmptyDiffs.join("\n")}\n`;
}

/**
 * Compute a stable patch id by piping a diff into `git patch-id --stable`.
 * Returns undefined for an empty diff. This id is stable across commits with
 * the same content, which the local review handlers use for deduplication.
 */
async function computeStablePatchId(
  cwd: string,
  diff: string
): Promise<string | undefined> {
  if (diff.length === 0) {
    return undefined;
  }
  const output = await new Promise<string>((resolve, reject) => {
    const gitProcess = gitSpawn("git", ["patch-id", "--stable"], { cwd });
    let stdout = "";
    let stderr = "";
    gitProcess.stdout.on("data", (data: Buffer) => {
      stdout += data.toString();
    });
    gitProcess.stderr.on("data", (data: Buffer) => {
      stderr += data.toString();
    });
    gitProcess.on("close", (code: number | null) => {
      if (code === 0) {
        resolve(stdout);
      } else {
        reject(new Error(`git patch-id failed with code ${code}: ${stderr}`));
      }
    });
    gitProcess.on("error", reject);
    gitProcess.stdin.end(diff);
  });
  return output.trim().split(/\s+/)[0] || undefined;
}

const COMMON_DEFAULT_BRANCHES = ["main", "master", "develop"];

/**
 * Best-effort resolution of the repository's default branch, mirroring the
 * exec-daemon fallback chain (origin/HEAD symbolic ref, common origin branches,
 * first remote branch, then init.defaultBranch).
 */
async function getDefaultBranch(cwd: string): Promise<string> {
  try {
    const symbolic = await runGit(cwd, [
      "symbolic-ref",
      "--short",
      "refs/remotes/origin/HEAD",
    ]);
    if (symbolic) {
      return symbolic.trim();
    }
  } catch {
    // fall through to the next method
  }

  for (const branch of COMMON_DEFAULT_BRANCHES) {
    const branchName = `origin/${branch}`;
    try {
      await runGit(cwd, ["rev-parse", "--verify", branchName]);
      return branchName;
    } catch {
      // branch doesn't exist, try the next one
    }
  }

  try {
    const branches = await runGit(cwd, ["branch", "-r"]);
    const firstOriginBranch = branches
      .split("\n")
      .map(branch => branch.trim())
      .find(branch => branch.startsWith("origin/"));
    if (firstOriginBranch) {
      return firstOriginBranch;
    }
  } catch {
    // fall through to the next method
  }

  try {
    const configBranch = await runGit(cwd, [
      "config",
      "--get",
      "init.defaultBranch",
    ]);
    if (configBranch) {
      return configBranch.trim();
    }
  } catch {
    // fall through
  }

  throw new Error("Could not determine default branch");
}

async function collectUntrackedFiles(
  cwd: string,
  maxUntrackedFiles: number
): Promise<{ contents: string; path: string }[]> {
  const untrackedFilesOut = await runGit(cwd, [
    "ls-files",
    "--others",
    "--exclude-standard",
  ]);
  let untrackedFiles = untrackedFilesOut
    .split("\n")
    .map(file => file.trim())
    .filter(file => file.length > 0);
  if (untrackedFiles.length > maxUntrackedFiles) {
    untrackedFiles = untrackedFiles.slice(0, maxUntrackedFiles);
  }
  const results = await Promise.all(
    untrackedFiles.map(async filePath => {
      try {
        const content = await fs.readFile(path.join(cwd, filePath), "utf8");
        return { contents: content, path: filePath };
      } catch {
        return undefined;
      }
    })
  );
  return results.filter(
    (file): file is { contents: string; path: string } => file !== undefined
  );
}

function normalizeOutputFormat(
  outputFormat: GetDiffRequest_OutputFormat | undefined
): Exclude<
  GetDiffRequest_OutputFormat,
  GetDiffRequest_OutputFormat.UNSPECIFIED
> {
  switch (outputFormat) {
    case GetDiffRequest_OutputFormat.NAME_STATUS:
      return GetDiffRequest_OutputFormat.NAME_STATUS;
    case GetDiffRequest_OutputFormat.NAME_STATUS_AND_NUMSTAT:
      return GetDiffRequest_OutputFormat.NAME_STATUS_AND_NUMSTAT;
    case GetDiffRequest_OutputFormat.FILE_DIFFS:
      return GetDiffRequest_OutputFormat.FILE_DIFFS;
    case GetDiffRequest_OutputFormat.DIFFS_WITH_BEFORE_AND_AFTER:
      return GetDiffRequest_OutputFormat.DIFFS_WITH_BEFORE_AND_AFTER;
    default:
      return GetDiffRequest_OutputFormat.FILE_DIFFS;
  }
}

/**
 * Compute a git diff locally for the CLI, returning the same shape the backend
 * expects from `gitDiffExecutorResource` (including `patchId`, `headSha`, and
 * `hasUncommittedChanges`, which the local review subagents require).
 *
 * This is a trimmed port of the exec-daemon `GitService.getDiff`: it does not
 * handle submodule recursion (callers that need it set `submoduleRecurseDepth`,
 * which is ignored here).
 */
export async function getLocalGitDiff(
  ctx: Context,
  cwd: string,
  request: GetDiffRequest
): Promise<GetDiffResponse> {
  const format = normalizeOutputFormat(request.outputFormat);

  const resolveBase = async (): Promise<string> => {
    let base =
      request.baseRef.length > 0
        ? request.baseRef
        : await getDefaultBranch(cwd);
    if (request.mergeBase) {
      base = (
        await runGit(cwd, [
          "merge-base",
          base,
          request.ref.length > 0 ? request.ref : "HEAD",
        ])
      ).trim();
    }
    return base;
  };

  const base = await resolveBase();

  const diffArgs = ["diff", "--no-color"];
  if (!request.includeSpaceChanges) {
    diffArgs.push("--ignore-space-change");
  }
  if (request.unifiedContextLines !== undefined) {
    diffArgs.push(`-U${request.unifiedContextLines}`);
  }
  diffArgs.push(base);
  if (request.ref.length > 0) {
    diffArgs.push(request.ref);
  }
  if (request.targetPaths.length > 0) {
    diffArgs.push("--");
    diffArgs.push(...request.targetPaths);
  }

  const diffRaw = await runGit(cwd, diffArgs, { shouldNotTrimOutput: true });
  const diff = parseGitDiff(diffRaw);

  let untrackedFilesForPatchId: { contents: string; path: string }[] = [];
  if (request.maxUntrackedFiles > 0) {
    untrackedFilesForPatchId = await collectUntrackedFiles(
      cwd,
      request.maxUntrackedFiles
    );
    for (const untrackedFile of untrackedFilesForPatchId) {
      const untrackedDiffRaw = await runGit(
        cwd,
        ["diff", "--no-color", "--no-index", "/dev/null", untrackedFile.path],
        { ignoreErrors: true, shouldNotTrimOutput: true }
      );
      diff.diffs.push(...parseGitDiff(untrackedDiffRaw).diffs);
    }
  }

  // Name-status formats do not include hunk content.
  if (format !== GetDiffRequest_OutputFormat.FILE_DIFFS) {
    for (const fileDiff of diff.diffs) {
      fileDiff.chunks = [];
    }
  }

  if (format === GetDiffRequest_OutputFormat.DIFFS_WITH_BEFORE_AND_AFTER) {
    const targetRef = request.ref.length > 0 ? request.ref : "HEAD";
    await Promise.all(
      diff.diffs.map(async fileDiff => {
        try {
          if (fileDiff.from !== "/dev/null") {
            try {
              fileDiff.beforeFileContents = await runGit(
                cwd,
                ["show", `${base}:${fileDiff.from}`],
                { shouldNotTrimOutput: true }
              );
            } catch {
              fileDiff.beforeFileContents = "";
            }
          } else {
            fileDiff.beforeFileContents = "";
          }

          if (fileDiff.to !== "/dev/null") {
            if (request.ref.length > 0) {
              try {
                fileDiff.afterFileContents = await runGit(
                  cwd,
                  ["show", `${targetRef}:${fileDiff.to}`],
                  { shouldNotTrimOutput: true }
                );
              } catch {
                fileDiff.afterFileContents = "";
              }
            } else {
              try {
                fileDiff.afterFileContents = await fs.readFile(
                  path.join(cwd, fileDiff.to),
                  "utf8"
                );
              } catch {
                try {
                  fileDiff.afterFileContents = await runGit(
                    cwd,
                    ["show", `${targetRef}:${fileDiff.to}`],
                    { shouldNotTrimOutput: true }
                  );
                } catch {
                  fileDiff.afterFileContents = "";
                }
              }
            }
          } else {
            fileDiff.afterFileContents = "";
          }
        } catch (error) {
          logger.error(ctx, "Error fetching file contents for diff", error);
        }
      })
    );
  }

  // Generated-file detection (reuses git-core's GitHub-compatible heuristics).
  const fileDiffMap = new Map<string, (typeof diff.diffs)[0]>();
  for (const fileDiff of diff.diffs) {
    const filePath = fileDiff.to !== "/dev/null" ? fileDiff.to : fileDiff.from;
    if (filePath) {
      fileDiffMap.set(filePath, fileDiff);
    }
  }
  const allFilePaths = [...fileDiffMap.keys()];
  const refForContent = request.ref.length > 0 ? request.ref : "HEAD";
  try {
    const generatedResults = await checkFilesGenerated({
      repoRoot: cwd,
      filePaths: allFilePaths,
      getContent: async (filePath: string): Promise<string | undefined> => {
        const fileDiff = fileDiffMap.get(filePath);
        if (!fileDiff) {
          return undefined;
        }
        if (fileDiff.afterFileContents !== undefined) {
          return fileDiff.afterFileContents;
        }
        try {
          if (fileDiff.to && fileDiff.to !== "/dev/null") {
            return await runGit(
              cwd,
              ["show", `${refForContent}:${fileDiff.to}`],
              {
                shouldNotTrimOutput: true,
              }
            );
          }
        } catch {
          // File might not exist in git yet (untracked) or other error
        }
        return undefined;
      },
    });
    for (const [filePath, result] of generatedResults) {
      const fileDiff = fileDiffMap.get(filePath);
      if (fileDiff) {
        fileDiff.isGenerated = result.isGenerated;
      }
    }
  } catch (error) {
    logger.warn(ctx, "Generated-file detection failed; continuing without it", {
      error: error instanceof Error ? error.message : String(error),
    });
  }

  const patchId =
    request.computePatchId === true
      ? await computeStablePatchId(
          cwd,
          appendDiffForPatchId(
            diffRaw,
            serializeUntrackedFilesForPatchId(untrackedFilesForPatchId)
          )
        )
      : undefined;
  const headSha =
    request.returnHeadSha === true
      ? (await runGit(cwd, ["rev-parse", "HEAD"])).trim()
      : undefined;
  const hasUncommittedChanges =
    request.returnHeadSha === true
      ? (
          await runGit(cwd, [
            "status",
            "--porcelain=v1",
            "--untracked-files=all",
          ])
        ).trim().length > 0
      : undefined;

  const response = new GetDiffResponse({
    diff,
    submoduleDiffs: [],
    patchId,
    headSha,
    hasUncommittedChanges,
  });
  // When the caller sets a size cap, reject the diff here before shipping it
  // back. Measured on the fully-assembled response so it covers every part. The
  // marker must match the one the other git providers throw.
  const maxResponseBytes = request.maxResponseBytes ?? 0;
  if (maxResponseBytes > 0) {
    const responseBytes = response.toBinary().byteLength;
    if (responseBytes > maxResponseBytes) {
      throw new Error(
        `GetDiffResponseTooLarge: ${responseBytes} bytes exceeds the ${maxResponseBytes} byte limit`
      );
    }
  }
  return response;
}

/**
 * Local implementation of `gitDiffExecutorResource` for the CLI. The backend
 * (e.g. the Bugbot / Security Review subagents) sends a `GetDiffRequest` over
 * the controlled-exec channel and this runs git in the user's workspace.
 */
export class LocalGitDiffExecutor implements GitDiffExecutor {
  async execute(ctx: Context, args: GetDiffRequest): Promise<GetDiffResponse> {
    return getLocalGitDiff(ctx, args.cwd, args);
  }
}
