export interface MinimalJimpImage {
  mime?: string;
  width: number;
  height: number;
  bitmap: { data: Buffer; width: number; height: number };
  resize(options: { w: number; h: number }): void;
  clone(): MinimalJimpImage;
  getBuffer(mime: string, options?: Record<string, unknown>): Promise<Buffer>;
  scaleToFit(options: { w: number; h: number }): void;
}

export interface MinimalJimp {
  read(source: Buffer): Promise<MinimalJimpImage>;
  fromBitmap(bitmap: {
    data: Buffer;
    width: number;
    height: number;
  }): MinimalJimpImage;
}

async function createJimpInstance(): Promise<MinimalJimp> {
  // Import only the formats and plugins we actually use rather than the full
  // `jimp` barrel, which pulls in every plugin (print, blur, dither, etc.).
  const [
    { createJimp },
    { default: png },
    { default: jpeg },
    { default: bmp, msBmp },
    { default: gif },
    { default: tiff },
    { methods: resizeMethods },
  ] = await Promise.all([
    import("@jimp/core"),
    import("@jimp/js-png"),
    import("@jimp/js-jpeg"),
    import("@jimp/js-bmp"),
    import("@jimp/js-gif"),
    import("@jimp/js-tiff"),
    import("@jimp/plugin-resize"),
  ]);
  return createJimp({
    formats: [png, jpeg, bmp, msBmp, gif, tiff],
    plugins: [resizeMethods],
  }) as unknown as MinimalJimp;
}

let jimpPromise: Promise<MinimalJimp> | undefined;

/** Jimp instance with resize + common raster formats only (no print, blur, etc.). */
export function getMinimalJimp(): Promise<MinimalJimp> {
  if (jimpPromise === undefined) {
    const initPromise = createJimpInstance().catch(error => {
      if (jimpPromise === initPromise) {
        jimpPromise = undefined;
      }
      throw error;
    });
    jimpPromise = initPromise;
  }
  return jimpPromise;
}
