import type { SandAgentDefaultModel, SandComputerUseModel } from "./agents/agent-model.js";
import type { SandLocalToolPermission } from "./local-tool-permission.js";
import type { SandAutoReviewInstructions } from "./sand-auto-review-instructions.js";
import type { SidebarSectionUpdate, StoredSidebarSection } from "./sidebar-sections.js";

export interface SandNotificationConfig {
	readonly isEnabled: boolean;
	readonly allowedApps: readonly string[];
	readonly minIntervalMs: number;
	readonly maxPerWindow: number;
	readonly windowMs: number;
}

export interface SandNotificationConfigInput {
	readonly isEnabled?: boolean;
	readonly allowedApps?: readonly string[];
	readonly minIntervalMs?: number;
	readonly maxPerWindow?: number;
	readonly windowMs?: number;
}

export const SAND_DISABLED_NOTIFICATION_CONFIG: SandNotificationConfig = {
	isEnabled: false,
	allowedApps: [],
	minIntervalMs: 5_000,
	maxPerWindow: 10,
	windowMs: 5 * 60_000,
};

// The host-owned slice of app settings whose source of truth must live with the
// host (not the desktop), so the in-box Driver reads/writes them.
export interface SandHostSettings {
	readonly notifications: SandNotificationConfig;
	readonly mcpCustomInstructions: Readonly<Record<string, string>>;
	readonly mcpCustomInstructionsByServerId?: Readonly<Record<string, string>>;
	readonly mcpCustomInstructionsAccountScope?: string;
	// Per-server disabled MCP tools (server row id → bare tool names). Disables
	// only: an absent server or tool means enabled. Governed by the same
	// account-scope field as the custom instructions.
	readonly mcpDisabledToolsByServerId?: Readonly<Record<string, readonly string[]>>;
	readonly mcpBoxServers: readonly string[];
	// The user's IANA timezone (e.g. "America/Los_Angeles") as AUTO-DETECTED and
	// reported by the desktop. The host runs in the box (UTC), so it relies on
	// this to schedule cron automations and tell the agent "now" on the user's
	// wall clock. Undefined until the desktop first reports it.
	readonly userTimeZone?: string;
	// The user's EXPLICIT timezone choice (Settings → Agent → Timezone), mirrored
	// from the desktop. When present it wins over the
	// detected `userTimeZone` everywhere the host resolves the user's zone; the
	// detection refresh never touches it. Undefined means follow auto-detection.
	readonly userTimeZoneOverride?: string;
	readonly agentDefaultModel?: SandAgentDefaultModel;
	// The user's complete computer-use picker selection (model id + parameters +
	// max mode). Undefined means the dedicated baked-in CUA fallback is used.
	readonly computerUseModel?: SandComputerUseModel;
	readonly autoReviewInstructions: SandAutoReviewInstructions;
	// The user's three-state permission for LOCAL tools (the ones that act on
	// their own computer). The desktop owns the picker and the durable copy; the
	// in-box Host needs its own because it is where the permission is ENFORCED —
	// the local box consults it before every exec and byte transfer aimed at the
	// user's machine. Never absent on the read shape: an un-mirrored Host answers
	// with the safe default ("ask") rather than an unset value.
	readonly localToolPermission: SandLocalToolPermission;
	readonly webauthnProxyEnabled: boolean;
	readonly pinnedAgentIds?: readonly string[];
	readonly sidebarSections?: readonly StoredSidebarSection[];
	readonly hasSeenOnboarding?: boolean;
}

// A partial update to the host-owned settings. Absent fields are left as-is.
export interface SandHostSettingsUpdate {
	readonly notifications?: SandNotificationConfigInput;
	readonly mcpCustomInstructions?: Readonly<Record<string, string>>;
	readonly mcpCustomInstructionsByServerId?: Readonly<Record<string, string>>;
	readonly mcpCustomInstructionsAccountScope?: string | null;
	readonly mcpDisabledToolsByServerId?: Readonly<Record<string, readonly string[]>>;
	readonly mcpBoxServers?: readonly string[];
	readonly userTimeZone?: string;
	// "" clears the override (back to auto-detection); a non-empty value must be
	// a valid IANA zone or the host ignores it.
	readonly userTimeZoneOverride?: string;
	// Null clears the box copy.
	readonly agentDefaultModel?: SandAgentDefaultModel | null;
	readonly computerUseModel?: SandComputerUseModel | null;
	readonly autoReviewInstructions?: SandAutoReviewInstructions;
	// Absent leaves the Host's copy unchanged; any of the three values replaces
	// it. An unrecognized value is normalized to the default by the Host, so a
	// malformed push can never widen access.
	readonly localToolPermission?: SandLocalToolPermission;
	readonly webauthnProxyEnabled?: boolean;
	// A value — INCLUDING `[]` — is written verbatim, so a clear persists.
	readonly pinnedAgentIds?: readonly string[];
	readonly sidebarSections?: readonly SidebarSectionUpdate[];
	readonly hasSeenOnboarding?: boolean;
	readonly featureFlagOverrides?: Readonly<Record<string, boolean>>;
}

export type SandHostSettingsField = keyof SandHostSettingsUpdate;

export interface SandHostSettingsChangedEvent {
	readonly fields: readonly SandHostSettingsField[];
}
