export async function getFirstItem<T>(
  iterable: AsyncIterable<T>
): Promise<{ firstItem: T; rest: AsyncIterable<T> } | undefined> {
  // Take (only) one iterator from the async-iterable
  const iterator = iterable[Symbol.asyncIterator]();

  // Grab the first element
  const first = await iterator.next();
  if (first.done) {
    return undefined;
  }

  // Wrap the *same* iterator so callers can iterate the remaining items exactly once
  const rest: AsyncIterable<T> = {
    async *[Symbol.asyncIterator]() {
      for (;;) {
        const next = await iterator.next();
        if (next.done) return;
        yield next.value;
      }
    },
  };

  return { firstItem: first.value, rest };
}
