import { createValidationResult, isString } from "./base.js";
import { validateBaseHookResponse } from "./baseHookResponse.js";
export const validateSubagentStartResponse = (value) => {
    // First validate base response
    const baseValidation = validateBaseHookResponse(value);
    if (!baseValidation.isValid) {
        return baseValidation;
    }
    const errors = [];
    const response = value;
    // Validate permission field
    if (response.permission !== undefined) {
        const validPermissions = ["allow", "deny", "ask"];
        if (!validPermissions.includes(response.permission)) {
            errors.push(`Invalid permission value. Expected one of: ${validPermissions.join(", ")}, or undefined`);
        }
    }
    // Validate user_message
    if (response.user_message !== undefined && !isString(response.user_message)) {
        errors.push("user_message must be a string if provided");
    }
    return createValidationResult(errors.length === 0, errors);
};
