export const SAND_UPDATE_TRACKS = ["stable", "nightly", "dogfood"] as const;

export type SandUpdateTrack = (typeof SAND_UPDATE_TRACKS)[number];

export type SandUpdateDisabledReason =
	| "disabled-by-env"
	| "lab-build"
	| "not-packaged"
	| "unsupported-platform";

export interface SandUpdateCheckOutcome {
	readonly at: number;
	readonly result: "up-to-date" | "error";
	readonly errorMessage?: string;
}

export type SandUpdateState =
	| { readonly type: "disabled"; readonly reason: SandUpdateDisabledReason }
	| { readonly type: "idle"; readonly lastCheck?: SandUpdateCheckOutcome }
	| { readonly type: "checking" }
	| { readonly type: "available"; readonly version: string }
	| {
			readonly type: "downloading";
			readonly version: string;
			readonly progress: number | null;
	  }
	| { readonly type: "staging"; readonly version: string }
	| {
			readonly type: "ready";
			readonly version: string;
			readonly lastCheck?: SandUpdateCheckOutcome;
	  };

export interface SandUpdateStatus {
	readonly state: SandUpdateState;
	readonly currentVersion: string;
	readonly currentTrack: SandUpdateTrack;
	readonly trackOverride: SandUpdateTrack | null;
	readonly buildDefaultTrack: SandUpdateTrack | null;
	readonly availableTracks: readonly SandUpdateTrack[];
	/**
	 * The current track is forced by `sand_internal_release_track_override`;
	 * the Settings picker renders locked.
	 */
	readonly isTrackManagedByPolicy: boolean;
	/**
	 * The running build sorts below the Statsig minimum
	 * (`sand_min_client_version`). Always false while updates are disabled —
	 * a build that cannot update must never be blocked — and on an
	 * unset/invalid minimum (enforcement fails open).
	 */
	readonly isBelowMinimumVersion: boolean;
	readonly autoUpdateWhenIdleOptIn: boolean;
	readonly autoUpdateWhenIdleGateEnabled: boolean;
}

export function isSandUpdateTrack(value: unknown): value is SandUpdateTrack {
	return value === "stable" || value === "nightly" || value === "dogfood";
}

function isRecord(value: unknown): value is Readonly<Record<string, unknown>> {
	return typeof value === "object" && value != null && !Array.isArray(value);
}

function isSandUpdateCheckOutcome(value: unknown): value is SandUpdateCheckOutcome {
	if (!isRecord(value)) return false;
	return (
		typeof value.at === "number" &&
		(value.result === "up-to-date" || value.result === "error") &&
		(value.errorMessage === undefined || typeof value.errorMessage === "string")
	);
}

function hasOptionalCheckOutcome(value: Readonly<Record<string, unknown>>): boolean {
	return value.lastCheck === undefined || isSandUpdateCheckOutcome(value.lastCheck);
}

export function isSandUpdateState(value: unknown): value is SandUpdateState {
	if (!isRecord(value)) return false;
	switch (value.type) {
		case "disabled":
			return (
				value.reason === "disabled-by-env" ||
				value.reason === "lab-build" ||
				value.reason === "not-packaged" ||
				value.reason === "unsupported-platform"
			);
		case "idle":
			return hasOptionalCheckOutcome(value);
		case "checking":
			return true;
		case "available":
		case "staging":
			return typeof value.version === "string";
		case "downloading":
			return (
				typeof value.version === "string" &&
				(value.progress === null ||
					(typeof value.progress === "number" && value.progress >= 0 && value.progress <= 1))
			);
		case "ready":
			return typeof value.version === "string" && hasOptionalCheckOutcome(value);
		default:
			return false;
	}
}

export function isSandUpdateStatus(value: unknown): value is SandUpdateStatus {
	if (!isRecord(value)) return false;
	return (
		isSandUpdateState(value.state) &&
		typeof value.currentVersion === "string" &&
		isSandUpdateTrack(value.currentTrack) &&
		(value.trackOverride === null || isSandUpdateTrack(value.trackOverride)) &&
		(value.buildDefaultTrack === null || isSandUpdateTrack(value.buildDefaultTrack)) &&
		Array.isArray(value.availableTracks) &&
		value.availableTracks.every(isSandUpdateTrack) &&
		typeof value.isTrackManagedByPolicy === "boolean" &&
		typeof value.isBelowMinimumVersion === "boolean" &&
		typeof value.autoUpdateWhenIdleOptIn === "boolean" &&
		typeof value.autoUpdateWhenIdleGateEnabled === "boolean"
	);
}
