import type { McpFailureClassification } from "./fsm/index.js";
import { classifyMcpFailure } from "./fsm/index.js";

// ── Metric emitter ───────────────────────────────────────────────────

export type McpExtMetricKind = "distribution" | "increment";

export interface McpExtMetricsEmitter {
  emit(
    stat: string,
    value: number,
    kind: McpExtMetricKind,
    tags: readonly string[]
  ): void;
}

let _metricsEmitter: McpExtMetricsEmitter | undefined;
let _leaseConnection = "local";

export function setMcpExtMetricsEmitter(emitter: McpExtMetricsEmitter): void {
  _metricsEmitter = emitter;
}

/**
 * Set the lease-connection identifier used to tag metrics and spans
 * (e.g. `"local"`, `"ssh-remote"`, `"wsl"`).
 */
export function setMcpExtLeaseConnection(name: string): void {
  _leaseConnection = name;
}

export function getMcpExtLeaseConnection(): string {
  return _leaseConnection;
}

export function emitMcpExtMetric(
  stat: string,
  value: number,
  kind: McpExtMetricKind = "distribution",
  extraTags: readonly string[] = []
): void {
  if (!_metricsEmitter) {
    return;
  }
  const tags = [`lease_connection:${_leaseConnection}`, ...extraTags];
  try {
    _metricsEmitter.emit(stat, value, kind, tags);
  } catch {
    // Metric emission must never throw into lifecycle code.
  }
}

// ── Tracing reporter ─────────────────────────────────────────────────

/** Levels accepted by vscode's `Breadcrumb` type. */
export type McpTracingBreadcrumbLevel = "error" | "info" | "debug";

export interface McpTracingBreadcrumb {
  category: string;
  level: McpTracingBreadcrumbLevel;
  message: string;
  data?: Record<string, string | number | boolean | undefined>;
}

export interface McpTracingReporter {
  addBreadcrumb(breadcrumb: McpTracingBreadcrumb): void;
  captureException(error: Error): void;
}

let _tracingReporter: McpTracingReporter | undefined;

export function setMcpTracingReporter(reporter: McpTracingReporter): void {
  _tracingReporter = reporter;
}

// ── Version tag ──────────────────────────────────────────────────────

let _mcpVersionTag = "v1";

export function setMcpVersionTag(version: string): void {
  _mcpVersionTag = version;
}

export function getMcpVersionTag(): string {
  return _mcpVersionTag;
}

// ── Auth meta builder ────────────────────────────────────────────────

export type McpAuthMetaBuilder = (
  fields: Record<string, unknown>
) => Record<string, unknown>;

let _authMetaBuilder: McpAuthMetaBuilder | undefined;

export function setMcpAuthMetaBuilder(builder: McpAuthMetaBuilder): void {
  _authMetaBuilder = builder;
}

/**
 * Wraps OAuth/auth-related fields under a host-defined envelope (for
 * structured logging). When no builder is registered (CLI / tests), falls
 * back to a plain `mcpAuthMeta` key so the data is still queryable.
 */
export function mcpAuthMeta(
  fields: Record<string, unknown>
): Record<string, unknown> {
  if (_authMetaBuilder) {
    return _authMetaBuilder(fields);
  }
  return { mcpAuthMeta: fields };
}

// ── Failure classification + tracing ─────────────────────────────────

export type McpFailurePhase =
  | "connection"
  | "transport"
  | "tool_call"
  | "get_prompt"
  | "read_resource"
  | "get_instructions"
  | "list_offerings";

interface ReportFailureArgs {
  identifier: string;
  phase: McpFailurePhase;
  error: unknown;
  serverType?: string;
  classification?: McpFailureClassification;
  captureException?: boolean;
  extraData?: Record<string, string | number | boolean | undefined>;
}

interface TracedMcpError extends Error {
  mcpFailure?: Record<string, string | number | boolean | undefined>;
}

export function failureMetricTags(
  classification: McpFailureClassification
): string[] {
  const tags = [
    `failure_reason:${classification.reason}`,
    `retryable:${String(classification.retryable)}`,
  ];
  if (classification.httpStatus !== undefined) {
    tags.push(`status_code:${String(classification.httpStatus)}`);
  }
  return tags;
}

/**
 * Emits a breadcrumb for every failure and optionally emits a Sentry exception.
 * This keeps handled MCP errors queryable in tracing without forcing all of
 * them into exception volume.
 */
export function reportMcpFailureToTracing({
  identifier,
  phase,
  error,
  serverType,
  classification: precomputedClassification,
  captureException = true,
  extraData,
}: ReportFailureArgs): McpFailureClassification {
  const classification =
    precomputedClassification ?? classifyMcpFailure(error, serverType);
  const message = error instanceof Error ? error.message : String(error);

  const failureData: Record<string, string | number | boolean | undefined> = {
    identifier,
    phase,
    reason: classification.reason,
    retryable: classification.retryable,
    http_status: classification.httpStatus,
    server_type: serverType,
    ...extraData,
  };

  if (_tracingReporter) {
    _tracingReporter.addBreadcrumb({
      category: "mcp.v2.failure",
      level: "error",
      message,
      data: failureData,
    });

    if (captureException) {
      const wrapper: TracedMcpError = new Error(message);
      wrapper.name = "McpV2Error";
      wrapper.stack = error instanceof Error ? error.stack : undefined;
      wrapper.mcpFailure = failureData;
      _tracingReporter.captureException(wrapper);
    }
  }

  return classification;
}
