import { getMinimalJimp, type MinimalJimpImage } from "./jimp-minimal.js";
import {
  decodeWebp,
  encodeWebp,
  isWebp,
  readWebpDimensions,
} from "./webp-codec.js";

export const MAX_IMAGE_DIMENSION: number = 1024;
export const MAX_WEBP_IMAGE_DIMENSION: number = 1280;
export const MAX_IMAGE_SIZE_BYTES: number = 1024 * 1024; // 1 MiB

export type ValidMimeType =
  | "image/png"
  | "image/bmp"
  | "image/tiff"
  | "image/x-ms-bmp"
  | "image/gif"
  | "image/jpeg"
  | "image/webp";

type JimpEncodableMimeType = Exclude<ValidMimeType, "image/webp">;

export type ResizedImageResult = {
  data: Uint8Array<ArrayBuffer>;
  mimeType: ValidMimeType;
};

const toUint8Array = (buffer: Buffer): Uint8Array<ArrayBuffer> => {
  return new Uint8Array(
    buffer.buffer as ArrayBuffer,
    buffer.byteOffset,
    buffer.byteLength
  );
};

const getMimeType = (image: MinimalJimpImage): JimpEncodableMimeType => {
  switch (image.mime) {
    case "image/png":
      return "image/png";
    case "image/bmp":
      return "image/bmp";
    case "image/tiff":
      return "image/tiff";
    case "image/x-ms-bmp":
      return "image/x-ms-bmp";
    case "image/gif":
      return "image/gif";
    case "image/jpeg":
      return "image/jpeg";
    default:
      return "image/png";
  }
};

const targetDimensions = (
  width: number,
  height: number,
  maxDimension: number = MAX_IMAGE_DIMENSION
): { width: number; height: number; needsResize: boolean } => {
  let newWidth: number = width;
  let newHeight: number = height;

  if (width > height) {
    if (width > maxDimension) {
      newWidth = maxDimension;
      newHeight = Math.max(1, Math.round((height * maxDimension) / width));
    }
  } else {
    if (height > maxDimension) {
      newHeight = maxDimension;
      newWidth = Math.max(1, Math.round((width * maxDimension) / height));
    }
  }

  return {
    width: newWidth,
    height: newHeight,
    needsResize: newWidth !== width || newHeight !== height,
  };
};

const resizeWebp = async (imageData: Buffer): Promise<ResizedImageResult> => {
  const dimensions = readWebpDimensions(imageData);
  const withinDimensionCap =
    dimensions !== undefined &&
    !targetDimensions(
      dimensions.width,
      dimensions.height,
      MAX_WEBP_IMAGE_DIMENSION
    ).needsResize;

  if (withinDimensionCap && imageData.length <= MAX_IMAGE_SIZE_BYTES) {
    return { data: toUint8Array(imageData), mimeType: "image/webp" };
  }

  const decoded = await decodeWebp(imageData);
  const Jimp = await getMinimalJimp();
  const image = Jimp.fromBitmap({
    data: Buffer.from(decoded.data),
    width: decoded.width,
    height: decoded.height,
  });

  let { width, height, needsResize } = targetDimensions(
    image.bitmap.width,
    image.bitmap.height,
    MAX_WEBP_IMAGE_DIMENSION
  );
  if (needsResize) {
    image.resize({ w: width, h: height });
  }

  let resultBuffer: Buffer = await encodeWebp({
    data: image.bitmap.data,
    width: image.bitmap.width,
    height: image.bitmap.height,
  });

  while (
    resultBuffer.length > MAX_IMAGE_SIZE_BYTES &&
    width > 1 &&
    height > 1
  ) {
    width = Math.max(1, Math.round(width * 0.8));
    height = Math.max(1, Math.round(height * 0.8));
    image.resize({ w: width, h: height });
    resultBuffer = await encodeWebp({
      data: image.bitmap.data,
      width: image.bitmap.width,
      height: image.bitmap.height,
    });
  }

  return { data: toUint8Array(resultBuffer), mimeType: "image/webp" };
};

export const resizeImageBufferIfNeeded = async (
  imageData: Buffer
): Promise<ResizedImageResult> => {
  if (isWebp(imageData)) {
    return resizeWebp(imageData);
  }

  const Jimp = await getMinimalJimp();
  const image = await Jimp.read(imageData);
  const sourceMimeType = getMimeType(image);

  const { width, height, needsResize } = targetDimensions(
    image.width,
    image.height
  );

  if (!needsResize && imageData.length <= MAX_IMAGE_SIZE_BYTES) {
    return {
      data: toUint8Array(imageData),
      mimeType: sourceMimeType,
    };
  }

  let newWidth: number = width;
  let newHeight: number = height;
  if (needsResize) {
    image.resize({ w: newWidth, h: newHeight });
  }

  let resultBuffer: Buffer = await image.getBuffer(sourceMimeType);

  while (
    resultBuffer.length > MAX_IMAGE_SIZE_BYTES &&
    newWidth > 1 &&
    newHeight > 1
  ) {
    newWidth = Math.max(1, Math.round(newWidth * 0.8));
    newHeight = Math.max(1, Math.round(newHeight * 0.8));
    image.resize({ w: newWidth, h: newHeight });
    resultBuffer = await image.getBuffer(sourceMimeType);
  }

  return { data: toUint8Array(resultBuffer), mimeType: sourceMimeType };
};
