/** Base directory for project-specific files: .cursor/projects */
export const CURSOR_PROJECTS_DIR = ".cursor/projects";

/** Subdirectory for agent transcripts within project directory */
export const TRANSCRIPTS_SUBDIR = "agent-transcripts";

/** Filename for local experiment override state within a project directory */
export const LOCAL_EXPERIMENT_OVERRIDES_FILE =
  "local-experiment-overrides.json";

/** Maximum length for safe conversation IDs */
const MAX_CONVERSATION_ID_LENGTH = 200;

/** Slugify a path: /Users/wilson/my-project -> Users-wilson-my-project */
export function slugifyPath(path: string): string {
  return path
    .replace(/[^a-zA-Z0-9]/g, "-")
    .replace(/-+/g, "-")
    .replace(/^-+|-+$/g, "");
}

/** Get full project directory path: ~/.cursor/projects/{slug}/ */
export function getProjectPath(homeDir: string, workspacePath: string): string {
  const dirName = slugifyPath(workspacePath);
  return `${homeDir}/${CURSOR_PROJECTS_DIR}/${dirName}`;
}

/** Get the local experiment override state file path for a workspace. */
export function getLocalExperimentOverridesFilePath(
  homeDir: string,
  workspacePath: string
): string {
  return `${getProjectPath(homeDir, workspacePath)}/${LOCAL_EXPERIMENT_OVERRIDES_FILE}`;
}

/**
 * Converts conversation ID to filesystem-safe format:
 * - URL-encodes special characters
 * - Replaces '%' with '_' for filesystem safety
 * - Caps length to avoid filesystem limits
 */
export function getSafeConversationId(conversationId: string): string {
  // URL-encode to handle special characters
  let safe = encodeURIComponent(conversationId);

  // Replace % with _ for cleaner filenames
  safe = safe.replace(/%/g, "_");

  // Cap length to avoid filesystem limits
  if (safe.length > MAX_CONVERSATION_ID_LENGTH) {
    safe = safe.slice(0, MAX_CONVERSATION_ID_LENGTH);
  }

  return safe;
}
