import Parser from "tree-sitter";
import Bash from "tree-sitter-bash";

export interface ShellCommandArg {
  type: string;
  value: string;
}

export interface ExecutableCommand {
  name: string;
  args: ShellCommandArg[];
  fullText: string;
}

export interface ShellRedirect {
  operator: string;
  destinationFds: number[];
  targetNodeType: string;
  targetText?: string;
}

export interface ShellCommandParsingResult {
  parsingFailed: boolean;
  executableCommands: ExecutableCommand[];
  hasRedirects: boolean;
  hasCommandSubstitution: boolean;
  /**
   * Wire-compatible name for the redirect allowlisting safety signal.
   * True means every redirect target was proven safe for allowlist prompts:
   * original stdout/stderr or /dev/null.
   */
  allRedirectsAreDevNull?: boolean;
  redirects: ShellRedirect[];
}

export interface LegacyAnalysis {
  simpleCommands: string[];
  hasInputRedirect: boolean;
  hasOutputRedirect: boolean;
}

export interface FullShellAnalysis {
  legacy: LegacyAnalysis;
  structured: ShellCommandParsingResult;
}

/**
 * Marker `error.code` thrown by artifacts that knowingly ship without the
 * tree-sitter natives (their build substitutes `tree-sitter` with a loader
 * whose Parser constructor throws it when the vendored runtime is absent).
 * Analysis then degrades to `parsingFailed: true`, which every caller treats
 * conservatively. Any other construction failure is a packaging regression
 * and stays a loud rethrow.
 */
export const TREE_SITTER_STUBBED_ERROR_CODE = "CURSOR_TREE_SITTER_STUBBED";

function isStubbedTreeSitterError(error: unknown): boolean {
  return (
    typeof error === "object" &&
    error !== null &&
    (error as { code?: unknown }).code === TREE_SITTER_STUBBED_ERROR_CODE
  );
}

// Constructed lazily so importing this module stays side-effect-free:
// natives-free artifacts must be importable (their loader only throws on
// construction). `undefined` = not yet attempted; `null` = natives
// unavailable on purpose.
let cachedParser: Parser | null | undefined;

function getParser(): Parser | null {
  if (cachedParser !== undefined) {
    return cachedParser;
  }
  try {
    const parser = new Parser();
    parser.setLanguage(Bash);
    cachedParser = parser;
  } catch (error) {
    if (!isStubbedTreeSitterError(error)) {
      // Not cached: a genuine natives failure stays loud on every call.
      throw error;
    }
    cachedParser = null;
    console.warn(
      "shell-parser: tree-sitter natives are unavailable in this artifact; " +
        "shell command analysis degrades to parsingFailed"
    );
  }
  return cachedParser;
}

const redirectNodeTypes = new Set([
  "file_redirect",
  "heredoc_redirect",
  "herestring_redirect",
  "heredoc",
  "here_string",
  "redirect",
  "redirection",
]);

const fileRedirectOperatorTypes = new Set([
  "<",
  ">",
  ">>",
  ">|",
  "<>",
  "<&",
  ">&",
  "&>",
  "&>>",
]);

type RedirectTarget =
  | "original-stdin"
  | "original-stdout"
  | "original-stderr"
  | "dev-null"
  | "unsafe";

interface RedirectClassificationState {
  fdTargets: Map<number, RedirectTarget>;
}

interface FileRedirectParts {
  operator: string;
  target?: Parser.SyntaxNode;
}

/**
 * Parses a shell command and returns both legacy and structured analysis
 */
export function analyzeShellCommand(cmd: string): FullShellAnalysis {
  const parser = getParser();
  if (parser === null) {
    return {
      legacy: {
        simpleCommands: [],
        hasInputRedirect: false,
        hasOutputRedirect: false,
      },
      structured: {
        parsingFailed: true,
        executableCommands: [],
        hasRedirects: false,
        hasCommandSubstitution: false,
        redirects: [],
      },
    };
  }
  const tree = parser.parse(cmd);
  const processedRedirectNodes = new WeakSet<Parser.SyntaxNode>();
  let sawRedirect = false;
  let allRedirectsAreAllowlistSafe = true;

  // Initialize results
  const legacy: LegacyAnalysis = {
    simpleCommands: [],
    hasInputRedirect: false,
    hasOutputRedirect: false,
  };

  const structured: ShellCommandParsingResult = {
    parsingFailed: false,
    executableCommands: [],
    hasRedirects: false,
    hasCommandSubstitution: false,
    redirects: [],
  };

  const recordRedirect = (isAllowlistSafe: boolean): void => {
    sawRedirect = true;
    structured.hasRedirects = true;
    allRedirectsAreAllowlistSafe =
      allRedirectsAreAllowlistSafe && isAllowlistSafe;
  };

  // Helper to detect redirects from text for legacy fields.
  const markRedirectsFromText = (txt: string) => {
    if (/(^|\s)[0-9]*<<?<?/.test(txt)) {
      legacy.hasInputRedirect = true;
    }
    if (
      /(^|\s)[0-9]*>>/.test(txt) ||
      /(^|\s)[0-9]*>(\||&)?/.test(txt) ||
      /(^|\s)&>/.test(txt) ||
      /(^|\s)[0-9]+>&[0-9]+/.test(txt)
    ) {
      legacy.hasOutputRedirect = true;
    }
  };

  const getFileRedirectParts = (
    node: Parser.SyntaxNode
  ): FileRedirectParts | undefined => {
    const children = node.children;
    const operatorIndex = children.findIndex(child =>
      fileRedirectOperatorTypes.has(child.type)
    );
    if (operatorIndex === -1) {
      return undefined;
    }
    return {
      operator: children[operatorIndex]?.type ?? "",
      target: children
        .slice(operatorIndex + 1)
        .find(child => child.type !== "comment"),
    };
  };

  const parseFd = (node: Parser.SyntaxNode | undefined): number | undefined => {
    if (!node || !/^\d+$/.test(node.text)) {
      return undefined;
    }
    return Number.parseInt(node.text, 10);
  };

  const getExplicitRedirectFd = (node: Parser.SyntaxNode): number | undefined =>
    parseFd(node.children.find(child => child.type === "file_descriptor"));

  const createRedirectClassificationState =
    (): RedirectClassificationState => ({
      fdTargets: new Map<number, RedirectTarget>([
        [0, "original-stdin"],
        [1, "original-stdout"],
        [2, "original-stderr"],
      ]),
    });

  const isAllowlistSafeOutputTarget = (
    target: RedirectTarget | undefined
  ): target is "original-stdout" | "original-stderr" | "dev-null" =>
    target === "original-stdout" ||
    target === "original-stderr" ||
    target === "dev-null";

  const getRedirectDestinationFds = (
    node: Parser.SyntaxNode,
    operator: string
  ): number[] => {
    if (operator === "&>" || operator === "&>>") {
      return [1, 2];
    }

    const explicitFd = getExplicitRedirectFd(node);
    if (explicitFd !== undefined) {
      return [explicitFd];
    }

    return operator.startsWith("<") ? [0] : [1];
  };

  const markRedirectLegacyFields = (node: Parser.SyntaxNode): void => {
    markRedirectsFromText(node.text);
    if (
      node.type === "heredoc_redirect" ||
      node.type === "herestring_redirect"
    ) {
      legacy.hasInputRedirect = true;
    }
  };

  const getHeredocReceiverCommandName = (
    node: Parser.SyntaxNode
  ): string | undefined => {
    const redirectedStatement = node.parent;
    if (redirectedStatement?.type !== "redirected_statement") {
      return undefined;
    }

    const commandNode = redirectedStatement.children.find(
      child => child.type === "command"
    );
    const commandName = commandNode?.childForFieldName("name");
    return commandName?.text;
  };

  const isInsideUnquotedCommandSubstitution = (
    node: Parser.SyntaxNode
  ): boolean => {
    let current = node.parent;
    while (current) {
      if (
        current.type === "command_substitution" &&
        current.parent?.type !== "string"
      ) {
        return true;
      }
      current = current.parent;
    }
    return false;
  };

  // A heredoc that feeds stdin to a directly-parsed command is allowlist-safe
  // for any receiver: the heredoc itself cannot create or modify files, and
  // the receiver command still has to match the allowlist on its own. Any
  // command substitution inside an unquoted heredoc body is surfaced by
  // tree-sitter and extracted by `traverse` as its own executable command, so
  // it is allowlist-checked independently. Heredocs whose receiver the parser
  // cannot attribute (e.g. attached to a loop or compound statement), or that
  // sit inside an unquoted command substitution, stay conservatively unsafe.
  const classifyHeredocRedirect = (
    node: Parser.SyntaxNode
  ): { redirect: ShellRedirect; isAllowlistSafe: boolean } => {
    const receiverCommandName = getHeredocReceiverCommandName(node);
    const isAllowlistSafe =
      receiverCommandName !== undefined &&
      !isInsideUnquotedCommandSubstitution(node);

    const redirect: ShellRedirect = {
      operator: isAllowlistSafe ? "<<" : "",
      destinationFds: isAllowlistSafe ? [0] : [],
      targetNodeType: node.type,
    };
    if (isAllowlistSafe) {
      redirect.targetText = receiverCommandName;
    }

    return { redirect, isAllowlistSafe };
  };

  const isExactDevNullTarget = (
    node: Parser.SyntaxNode | undefined
  ): boolean => {
    if (!node) {
      return false;
    }

    if (node.type === "word") {
      return node.text === "/dev/null";
    }

    if (node.type === "raw_string") {
      return node.text === "'/dev/null'";
    }

    if (node.type === "string") {
      const namedChildren = node.namedChildren;
      return (
        namedChildren.length === 1 &&
        namedChildren[0]?.type === "string_content" &&
        namedChildren[0].text === "/dev/null"
      );
    }

    return false;
  };

  const getStaticRedirectTargetText = (
    node: Parser.SyntaxNode | undefined
  ): string | undefined => {
    if (!node) {
      return undefined;
    }

    if (node.type === "word") {
      return node.namedChildren.length === 0 ? node.text : undefined;
    }

    if (node.type === "number") {
      return node.text;
    }

    if (node.type === "raw_string") {
      if (node.text.length < 2) {
        return undefined;
      }
      return node.text.slice(1, -1);
    }

    if (node.type === "string") {
      const namedChildren = node.namedChildren;
      if (
        namedChildren.length === 0 ||
        namedChildren.some(child => child.type !== "string_content")
      ) {
        return undefined;
      }
      return namedChildren.map(child => child.text).join("");
    }

    return undefined;
  };

  const classifyFileRedirect = (
    node: Parser.SyntaxNode,
    state: RedirectClassificationState
  ): boolean => {
    const parts = getFileRedirectParts(node);
    if (!parts) {
      return false;
    }

    const { operator, target } = parts;
    const destinationFds = getRedirectDestinationFds(node, operator);
    const targetText = getStaticRedirectTargetText(target);
    const redirect: ShellRedirect = {
      operator,
      destinationFds,
      targetNodeType: target?.type ?? "",
    };
    if (targetText !== undefined) {
      redirect.targetText = targetText;
    }
    structured.redirects.push(redirect);

    if (operator === ">&") {
      const sourceFd = parseFd(target);
      const sourceTarget =
        sourceFd === undefined ? undefined : state.fdTargets.get(sourceFd);
      if (!isAllowlistSafeOutputTarget(sourceTarget)) {
        for (const fd of destinationFds) {
          state.fdTargets.set(fd, "unsafe");
        }
        return false;
      }
      for (const fd of destinationFds) {
        state.fdTargets.set(fd, sourceTarget);
      }
      return true;
    }

    if (operator === "<&") {
      const sourceFd = parseFd(target);
      const sourceTarget =
        sourceFd === undefined ? undefined : state.fdTargets.get(sourceFd);
      if (sourceTarget !== "dev-null") {
        for (const fd of destinationFds) {
          state.fdTargets.set(fd, "unsafe");
        }
        return false;
      }
      for (const fd of destinationFds) {
        state.fdTargets.set(fd, sourceTarget);
      }
      return true;
    }

    if (!isExactDevNullTarget(target)) {
      for (const fd of destinationFds) {
        state.fdTargets.set(fd, "unsafe");
      }
      return false;
    }

    for (const fd of destinationFds) {
      state.fdTargets.set(fd, "dev-null");
    }
    return true;
  };

  const processRedirectNode = (
    node: Parser.SyntaxNode,
    state: RedirectClassificationState
  ): void => {
    if (processedRedirectNodes.has(node)) {
      return;
    }
    processedRedirectNodes.add(node);
    markRedirectLegacyFields(node);

    if (node.type === "heredoc_redirect") {
      const { redirect, isAllowlistSafe } = classifyHeredocRedirect(node);
      structured.redirects.push(redirect);
      recordRedirect(isAllowlistSafe);
      return;
    }

    if (node.type !== "file_redirect") {
      structured.redirects.push({
        operator: "",
        destinationFds: [],
        targetNodeType: node.type,
      });
      recordRedirect(false);
      return;
    }

    recordRedirect(classifyFileRedirect(node, state));
  };

  const processDirectRedirectChildren = (node: Parser.SyntaxNode): void => {
    const state = createRedirectClassificationState();
    for (const child of node.children) {
      if (redirectNodeTypes.has(child.type)) {
        processRedirectNode(child, state);
      }
    }
  };

  // Traverse the tree
  function traverse(node: Parser.SyntaxNode) {
    const type = node.type;

    processDirectRedirectChildren(node);

    if (redirectNodeTypes.has(type) && !processedRedirectNodes.has(node)) {
      processRedirectNode(node, createRedirectClassificationState());
    }

    // Handle commands
    if (type === "command") {
      const commandName = node.childForFieldName("name");
      if (commandName === null) {
        structured.parsingFailed = true;
      } else {
        // Add to legacy simple commands
        legacy.simpleCommands.push(commandName.text);

        // Build structured command
        let commandFullText = commandName.text;
        const commandArgs: ShellCommandArg[] = [];

        for (const arg of node.childrenForFieldName("argument")) {
          commandArgs.push({
            type: arg.type,
            value: arg.text,
          });
          commandFullText += ` ${arg.text}`;
        }

        structured.executableCommands.push({
          name: commandName.text,
          args: commandArgs,
          fullText: commandFullText,
        });
      }
    }

    // Legacy command detection
    if (type === "command_name" || type === "simple_command") {
      if (
        type === "command_name" &&
        !legacy.simpleCommands.includes(node.text)
      ) {
        legacy.simpleCommands.push(node.text);
      } else if (type === "simple_command") {
        // For simple_command, try to extract just the command name
        const firstChild = node.firstNamedChild;
        if (firstChild && firstChild.type === "command_name") {
          if (!legacy.simpleCommands.includes(firstChild.text)) {
            legacy.simpleCommands.push(firstChild.text);
          }
        } else {
          // Fallback to full text
          legacy.simpleCommands.push(node.text);
        }
      }
    }

    // Handle command substitution
    if (type === "command_substitution" || type === "process_substitution") {
      structured.hasCommandSubstitution = true;
    }

    // Traverse children
    for (const child of node.children) {
      traverse(child);
    }
  }

  traverse(tree.rootNode);

  if (sawRedirect) {
    structured.allRedirectsAreDevNull = allRedirectsAreAllowlistSafe;
  }

  return {
    legacy,
    structured,
  };
}

/**
 * Legacy function for backward compatibility
 */
export function analyzeCommandLegacy(cmd: string): LegacyAnalysis {
  return analyzeShellCommand(cmd).legacy;
}
