import { type Context, createLogger } from "@anysphere/context";
import { createCounter, createHistogram } from "@anysphere/metrics";
import { sanitizeServerName } from "./mcp.js";
import { readMcpDiskCatalogToolNamesForProjectDir } from "./mcp-disk-catalog-read.js";
import type { McpState, McpStateAccessor } from "./request-context.js";

const logger = createLogger("local-exec:mcp-disk-freshness-on-access");

const MCP_PATH_SEGMENT = "/mcps/";
const DISK_MCPS_FRESHNESS_DEBOUNCE_MS = 2_000;

const mcpDiscoveryFreshnessCheck = createCounter(
  "mcp.discovery_freshness.check",
  {
    description:
      "MCP discovery surface freshness comparison outcome against canonical live tools",
    labelNames: ["surface", "outcome"] as const,
  }
);

const mcpDiscoveryFreshnessMissingTools = createHistogram(
  "mcp.discovery_freshness.missing_tools",
  {
    description:
      "Number of tools present in canonical live state but missing from the observed discovery surface",
    labelNames: ["surface"] as const,
  }
);

const mcpDiscoveryFreshnessExtraTools = createHistogram(
  "mcp.discovery_freshness.extra_tools",
  {
    description:
      "Number of tools present on the observed discovery surface but absent from canonical live state",
    labelNames: ["surface"] as const,
  }
);

const mcpDiscoveryFreshnessSymmetricDifference = createHistogram(
  "mcp.discovery_freshness.symmetric_difference",
  {
    description:
      "Total symmetric difference between canonical live tools and the observed discovery surface",
    labelNames: ["surface"] as const,
  }
);

type DiskCatalogReadResult = Awaited<
  ReturnType<typeof readMcpDiskCatalogToolNamesForProjectDir>
>;

type DiskCatalogReader = (
  projectDir: string,
  serverIdentifier: string
) => Promise<DiskCatalogReadResult>;

const diskFreshnessDebounceTimers = new Map<
  string,
  ReturnType<typeof setTimeout>
>();

/** So `.../mcps` (no trailing slash) matches the `/mcps/` layout segment. */
function normalizePathForMcpsLayout(filePath: string): string {
  const norm = filePath.replace(/\\/g, "/");
  if (norm.endsWith("/mcps")) {
    return `${norm}/`;
  }
  return norm;
}

type ParsedMcpsPath =
  | { projectDir: string; kind: "server"; sanitizedServerFolder: string }
  | { projectDir: string; kind: "mcps_root" };

function isMcpDirectoryPath(path: string | undefined): boolean {
  if (path === undefined) {
    return false;
  }
  return normalizePathForMcpsLayout(path).includes(MCP_PATH_SEGMENT);
}

function parseMcpsPath(filePath: string): ParsedMcpsPath | undefined {
  const norm = normalizePathForMcpsLayout(filePath);
  const idx = norm.indexOf(MCP_PATH_SEGMENT);
  if (idx === -1) {
    return undefined;
  }
  const projectDir = norm.slice(0, idx);
  const rest = norm.slice(idx + MCP_PATH_SEGMENT.length);
  const parts = rest.split("/").filter(Boolean);
  if (projectDir.length === 0) {
    return undefined;
  }
  if (parts.length === 0) {
    return { projectDir, kind: "mcps_root" as const };
  }
  return {
    projectDir,
    kind: "server" as const,
    sanitizedServerFolder: parts[0]!,
  };
}

type EmitDiskMcpDiscoveryFreshnessInput = {
  ctx: Context;
  serverIdentifier: string;
  canonicalToolNames: readonly string[];
  observedToolNames: readonly string[];
};

function emitDiskMcpDiscoveryFreshness({
  ctx,
  serverIdentifier,
  canonicalToolNames,
  observedToolNames,
}: EmitDiskMcpDiscoveryFreshnessInput): void {
  const observedToolSet = new Set(observedToolNames);
  const canonicalToolSet = new Set(canonicalToolNames);
  const missingTools = canonicalToolNames.filter(
    toolName => !observedToolSet.has(toolName)
  );
  const extraTools = observedToolNames.filter(
    toolName => !canonicalToolSet.has(toolName)
  );
  const outcome =
    missingTools.length === 0 && extraTools.length === 0 ? "match" : "mismatch";
  const tags = { surface: "disk" as const };

  mcpDiscoveryFreshnessCheck.increment(ctx, 1, {
    ...tags,
    outcome,
  });
  mcpDiscoveryFreshnessMissingTools.histogram(ctx, missingTools.length, tags);
  mcpDiscoveryFreshnessExtraTools.histogram(ctx, extraTools.length, tags);
  mcpDiscoveryFreshnessSymmetricDifference.histogram(
    ctx,
    missingTools.length + extraTools.length,
    tags
  );

  if (outcome === "mismatch") {
    logger.warn(ctx, "mcp_disk_discovery_freshness_mismatch", {
      server_identifier: serverIdentifier,
      missing_tool_count: missingTools.length,
      extra_tool_count: extraTools.length,
    });
  }
}

type RunDiskMcpDiscoveryFreshnessInput = {
  ctx: Context;
  mcpStateAccessor: McpStateAccessor;
  projectDir: string;
  sanitizedServerFolder: string;
  readDiskCatalog: DiskCatalogReader;
  state?: McpState;
};

async function runDiskMcpDiscoveryFreshness({
  ctx,
  mcpStateAccessor,
  projectDir,
  sanitizedServerFolder,
  readDiskCatalog,
  state: providedState,
}: RunDiskMcpDiscoveryFreshnessInput): Promise<void> {
  let state = providedState;
  if (state === undefined) {
    try {
      state = await mcpStateAccessor.getState(ctx);
    } catch (err) {
      logger.warn(ctx, "mcp_disk_state_read_failed", {
        error_type: err instanceof Error ? err.name : typeof err,
      });
      return;
    }
  }

  const server = state.servers.find(
    candidate =>
      sanitizeServerName(candidate.serverIdentifier) === sanitizedServerFolder
  );
  if (server === undefined) {
    return;
  }

  let diskResult: DiskCatalogReadResult;
  try {
    diskResult = await readDiskCatalog(projectDir, server.serverIdentifier);
  } catch (err) {
    logger.warn(ctx, "mcp_disk_catalog_read_failed", {
      error_type: err instanceof Error ? err.name : typeof err,
    });
    return;
  }

  if (!diskResult.toolsDirExists) {
    return;
  }

  const canonicalToolNames = server.tools
    .map(tool => tool.toolName)
    .filter(toolName => toolName.length > 0)
    .sort((a, b) => a.localeCompare(b));

  emitDiskMcpDiscoveryFreshness({
    ctx,
    serverIdentifier: server.serverIdentifier,
    canonicalToolNames,
    observedToolNames: diskResult.toolNames,
  });
}

export function scheduleDiskMcpDiscoveryFreshnessOnMcpsPathAccess(
  ctx: Context,
  mcpStateAccessor: McpStateAccessor,
  filePath: string | undefined,
  readDiskCatalog: DiskCatalogReader = readMcpDiskCatalogToolNamesForProjectDir
): void {
  if (filePath === undefined || !isMcpDirectoryPath(filePath)) {
    return;
  }
  const parsed = parseMcpsPath(filePath);
  if (parsed === undefined) {
    return;
  }

  let key: string;
  let serverFolderForRun: string | undefined;
  const isMcpsRoot = parsed.kind === "mcps_root";
  if (parsed.kind === "mcps_root") {
    key = `${parsed.projectDir}\0__mcps_root__`;
    serverFolderForRun = undefined;
  } else {
    key = `${parsed.projectDir}\0${parsed.sanitizedServerFolder}`;
    serverFolderForRun = parsed.sanitizedServerFolder;
  }

  const existing = diskFreshnessDebounceTimers.get(key);
  if (existing !== undefined) {
    clearTimeout(existing);
  }

  // Capture the calling ctx so the deferred freshness check inherits the
  // ambient metricsKey (and other context values) from the request that
  // triggered the /mcps/ access. Previously this used a bare `createContext()`
  // here, which silently dropped every `mcp.discovery_freshness.*{surface:disk}`
  // metric because @anysphere/metrics is a no-op without a metricsKey on ctx.
  const freshnessCtx = ctx;

  const timer = setTimeout(() => {
    diskFreshnessDebounceTimers.delete(key);
    const runFreshnessCheck = async (): Promise<void> => {
      if (isMcpsRoot) {
        const state = await mcpStateAccessor.getState(freshnessCtx);
        for (const server of state.servers) {
          const folder = sanitizeServerName(server.serverIdentifier);
          await runDiskMcpDiscoveryFreshness({
            ctx: freshnessCtx,
            mcpStateAccessor,
            projectDir: parsed.projectDir,
            sanitizedServerFolder: folder,
            readDiskCatalog,
            state,
          });
        }
        return;
      }

      if (serverFolderForRun !== undefined) {
        await runDiskMcpDiscoveryFreshness({
          ctx: freshnessCtx,
          mcpStateAccessor,
          projectDir: parsed.projectDir,
          sanitizedServerFolder: serverFolderForRun,
          readDiskCatalog,
        });
      }
    };

    void runFreshnessCheck().catch(err => {
      logger.warn(
        freshnessCtx,
        "mcp_disk_discovery_freshness_schedule_failed",
        {
          error_type: err instanceof Error ? err.name : typeof err,
        }
      );
    });
  }, DISK_MCPS_FRESHNESS_DEBOUNCE_MS);
  diskFreshnessDebounceTimers.set(key, timer);
}
