export const SNAPSHOT_TTL_MS = 5 * 60 * 1000;
export function isSnapshotValid(state) {
    return state.status === "valid" && Date.now() < state.expiresAt.getTime();
}
export function validateSnapshotOnSubmit(submittedToken, currentState) {
    if (currentState.status === "expired") {
        return {
            valid: false,
            error: {
                kind: "EXPIRED",
                expiredAt: currentState.expiredAt,
            },
        };
    }
    if (currentState.status === "stale") {
        return {
            valid: false,
            error: {
                kind: "STALE",
                newToken: currentState.newToken,
            },
        };
    }
    if (currentState.status === "valid" &&
        Date.now() >= currentState.expiresAt.getTime()) {
        return {
            valid: false,
            error: {
                kind: "EXPIRED",
                expiredAt: currentState.expiresAt,
            },
        };
    }
    if (submittedToken !== currentState.token) {
        return {
            valid: false,
            error: {
                kind: "TOKEN_MISMATCH",
            },
        };
    }
    return { valid: true };
}
