import type { SandBox } from "./box.js";

export type SandUserComputerBox = Pick<SandBox, "uploadFile" | "downloadFile">;

export const DEFAULT_SAND_COMPUTER_ID = "this-computer";

export interface SandUserComputerDescriptor {
	readonly id: string;
	readonly label: string;
	readonly connected: boolean;
}

export interface SandUserComputerHandle {
	readonly id: string;
	readonly label: string;
	readonly box: SandUserComputerBox;
}

export interface SandUserComputers {
	list(): readonly SandUserComputerDescriptor[];
	resolve(id: string | undefined): SandUserComputerHandle | undefined;
}

export function createSingleUserComputer(args: {
	readonly box: SandUserComputerBox;
	readonly label?: string;
	readonly isConnected?: () => boolean;
}): SandUserComputers {
	const id = DEFAULT_SAND_COMPUTER_ID;
	const label = args.label ?? "this computer";
	const connected = (): boolean => args.isConnected?.() ?? true;
	return {
		list: () => [{ id, label, connected: connected() }],
		resolve: (requestedId) => {
			if (requestedId !== undefined && requestedId !== id) return undefined;
			if (!connected()) return undefined;
			return { id, label, box: args.box };
		},
	};
}
