/**
 * Pure MCP URL policy helpers.
 *
 * This module is the policy layer: normalize configured patterns and answer
 * match/block questions. It deliberately does not fetch team settings, load MCP
 * servers, intercept traffic, or decide which feature gate is enabled. Callers
 * in the enforcement layer own those side effects.
 */

// ── Inlined domain-pattern matching (from @anysphere/agent-core) ────
// Duplicated here to avoid adding agent-core as a dependency of mcp-core,
// which would change package.json and pnpm-lock.yaml.

type ParsedIpAddress =
	| { version: 4; value: bigint }
	| { version: 6; value: bigint };

const BIGINT_ZERO = BigInt(0);
const BIGINT_EIGHT = BigInt(8);
const BIGINT_SIXTEEN = BigInt(16);
const IPV4_LOW_HEXTET_MASK = BigInt(0xffff);

function tryParseIpv4(input: string): ParsedIpAddress | undefined {
	const parts = input.split(".");
	if (parts.length !== 4) {
		return undefined;
	}

	let value = BIGINT_ZERO;
	for (const part of parts) {
		if (!/^\d{1,3}$/.test(part)) {
			return undefined;
		}

		const octet = Number(part);
		if (!Number.isInteger(octet) || octet < 0 || octet > 255) {
			return undefined;
		}

		value = (value << BIGINT_EIGHT) | BigInt(octet);
	}

	return { version: 4, value };
}

function parseIpv6Groups(part: string): number[] | undefined {
	if (part.length === 0) {
		return [];
	}

	const groups: number[] = [];
	const segments = part.split(":");

	for (let i = 0; i < segments.length; i++) {
		const segment = segments[i];
		if (segment.length === 0) {
			return undefined;
		}

		if (segment.includes(".")) {
			if (i !== segments.length - 1) {
				return undefined;
			}

			const ipv4 = tryParseIpv4(segment);
			if (!ipv4) {
				return undefined;
			}

			groups.push(
				Number((ipv4.value >> BIGINT_SIXTEEN) & IPV4_LOW_HEXTET_MASK)
			);
			groups.push(Number(ipv4.value & IPV4_LOW_HEXTET_MASK));
			continue;
		}

		if (!/^[0-9a-f]{1,4}$/i.test(segment)) {
			return undefined;
		}

		groups.push(Number.parseInt(segment, 16));
	}

	return groups;
}

function tryParseIpv6(input: string): ParsedIpAddress | undefined {
	const normalized = normalizePatternValue(input);
	if (normalized.length === 0 || normalized.includes(":::")) {
		return undefined;
	}

	const doubleColonIndex = normalized.indexOf("::");
	if (doubleColonIndex === -1) {
		const groups = parseIpv6Groups(normalized);
		if (!groups || groups.length !== 8) {
			return undefined;
		}

		return {
			version: 6,
			value: groups.reduce(
				(acc, group) => (acc << BIGINT_SIXTEEN) | BigInt(group),
				BIGINT_ZERO
			),
		};
	}

	if (normalized.indexOf("::", doubleColonIndex + 1) !== -1) {
		return undefined;
	}

	const leftPart = normalized.slice(0, doubleColonIndex);
	const rightPart = normalized.slice(doubleColonIndex + 2);
	const leftGroups = parseIpv6Groups(leftPart);
	const rightGroups = parseIpv6Groups(rightPart);
	if (!leftGroups || !rightGroups) {
		return undefined;
	}

	const totalGroups = leftGroups.length + rightGroups.length;
	if (totalGroups > 7) {
		return undefined;
	}

	const groups = [
		...leftGroups,
		...new Array(8 - totalGroups).fill(0),
		...rightGroups,
	];

	return {
		version: 6,
		value: groups.reduce(
			(acc, group) => (acc << BIGINT_SIXTEEN) | BigInt(group),
			BIGINT_ZERO
		),
	};
}

function tryParseIpAddress(input: string): ParsedIpAddress | undefined {
	return tryParseIpv4(input) ?? tryParseIpv6(input);
}

function matchesCidrPattern(host: string, pattern: string): boolean {
	const slashIndex = pattern.lastIndexOf("/");
	if (slashIndex <= 0 || slashIndex === pattern.length - 1) {
		return false;
	}

	const network = tryParseIpAddress(pattern.slice(0, slashIndex));
	const hostIp = tryParseIpAddress(host);
	if (!network || !hostIp || network.version !== hostIp.version) {
		return false;
	}

	const prefixLength = Number(pattern.slice(slashIndex + 1));
	const totalBits = network.version === 4 ? 32 : 128;
	if (
		!Number.isInteger(prefixLength) ||
		prefixLength < 0 ||
		prefixLength > totalBits
	) {
		return false;
	}

	const shift = BigInt(totalBits - prefixLength);
	return hostIp.value >> shift === network.value >> shift;
}

function matchesDomainPattern(domain: string, pattern: string): boolean {
	const normalizedDomain = normalizePatternValue(domain);
	const normalizedPattern = normalizePatternValue(pattern);

	if (normalizedPattern === "*") {
		return true;
	}

	if (normalizedPattern.includes("/")) {
		return matchesCidrPattern(normalizedDomain, normalizedPattern);
	}

	if (normalizedPattern.startsWith("*.")) {
		const suffix = normalizedPattern.slice(2);
		return (
			normalizedDomain === suffix || normalizedDomain.endsWith(`.${suffix}`)
		);
	}

	return normalizedDomain === normalizedPattern;
}

// ── End inlined domain-pattern matching ─────────────────────────────

export function normalizeMcpServerUrl(rawServerUrl: string): string {
	try {
		const parsed = new URL(rawServerUrl);
		const normalized = new URL(parsed.pathname, parsed.origin);
		normalized.search = parsed.search;

		if (normalized.pathname.endsWith("/") && normalized.pathname.length > 1) {
			normalized.pathname = normalized.pathname.slice(0, -1);
		}

		if (normalized.pathname === "/") {
			return normalized.origin + normalized.search;
		}

		return normalized.toString();
	} catch {
		return rawServerUrl.toLowerCase().trim();
	}
}

export function getMcpServerUrlForms(rawServerUrl: string): {
	transportServerUrl: string;
	canonicalServerUrl: string;
} {
	return {
		transportServerUrl: rawServerUrl,
		canonicalServerUrl: normalizeMcpServerUrl(rawServerUrl),
	};
}

export function getMcpServerUrlHostname(rawServerUrl: string): string | undefined {
	try {
		return new URL(normalizeMcpServerUrl(rawServerUrl)).hostname.toLowerCase();
	} catch {
		return undefined;
	}
}

export const MCP_NETWORK_CONTROLS_BLOCK_MESSAGE = "Blocked by MCP Network Admin Server Controls";

export type McpNetworkRequestControlResult =
	| { readonly allowed: true }
	| { readonly allowed: false; readonly message?: string };

export type McpNetworkMode =
	| "allow_all"
	| "allowlist"
	| "deny_all"
	| "no_sandbox";

export interface McpNetworkControlsConfig {
	readonly enabled?: boolean;
	/**
	 * Explicit command MCP network mode. Admin command rows without a stored mode
	 * are normalized to `no_sandbox` before runtime. If sandboxed callers leave
	 * this undefined, empty allowlists remain proxy-mediated allow-all.
	 * `no_sandbox` disables local MCP sandbox/network-control enforcement for the
	 * matched command server.
	 */
	readonly mcpNetworkMode?: McpNetworkMode;
	/**
	 * Resolved MCP network allowlist for the server being checked or sandboxed.
	 * Runtime enforcement callers source this from the matched
	 * `allowedMcpServers[].networkAllowlist` entry when the overhaul model is
	 * enabled.
	 */
	readonly mcpNetworkAllowlist?: readonly string[];
	/**
	 * Resolved user-extension MCP network denylist for the server being sandboxed.
	 * Runtime enforcement callers source this from
	 * `deniedMcpServers[].serverUrl` entries when user MCPs are allowed.
	 */
	readonly mcpNetworkDenylist?: readonly string[];
	readonly localAgentNetworkAllowlist?: readonly string[];
	readonly blockMessage?: string;
}

function stripPortFromHostPattern(pattern: string): string {
	const firstColonIndex = pattern.indexOf(":");
	if (firstColonIndex === -1) {
		return pattern;
	}

	const port = pattern.slice(firstColonIndex + 1);
	if (!/^\d+$/.test(port)) {
		return pattern;
	}

	return pattern.slice(0, firstColonIndex);
}

function hasEmbeddedWhitespace(value: string): boolean {
	return /\s/.test(value);
}

const DNS_LABEL_PATTERN = "[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?";
const HOSTNAME_ALLOWLIST_PATTERN_REGEX = new RegExp(
	`^(?:${DNS_LABEL_PATTERN}\\.)*${DNS_LABEL_PATTERN}$`
);
const WILDCARD_HOST_ALLOWLIST_PATTERN_REGEX = new RegExp(
	`^\\*\\.(?:${DNS_LABEL_PATTERN}\\.)*${DNS_LABEL_PATTERN}$`
);
const IPV4_SEGMENT_PATTERN = "(?:25[0-5]|2[0-4]\\d|1\\d\\d|[1-9]?\\d)";
const IPV4_LITERAL_REGEX = new RegExp(
	`^${IPV4_SEGMENT_PATTERN}(?:\\.${IPV4_SEGMENT_PATTERN}){3}$`
);
const IPV6_LITERAL_REGEX = /^[0-9a-f:]+$/;
const CIDR_ALLOWLIST_PATTERN_REGEX = new RegExp(
	`^(?:${IPV4_SEGMENT_PATTERN}(?:\\.${IPV4_SEGMENT_PATTERN}){3}|[0-9a-f:]+)\\/\\d{1,3}$`
);

function isValidHostnamePattern(pattern: string): boolean {
	const normalizedPattern = normalizePatternValue(pattern);
	return (
		normalizedPattern.length > 0 &&
		normalizedPattern.length <= 253 &&
		HOSTNAME_ALLOWLIST_PATTERN_REGEX.test(normalizedPattern)
	);
}

function isValidIpv6LiteralPattern(pattern: string): boolean {
	const normalizedPattern = normalizePatternValue(pattern);
	if (!IPV6_LITERAL_REGEX.test(normalizedPattern)) {
		return false;
	}

	try {
		new URL(`https://[${normalizedPattern}]`);
		return true;
	} catch {
		return false;
	}
}

function isValidIpLiteralPattern(pattern: string): boolean {
	const normalizedPattern = normalizePatternValue(pattern);
	return (
		IPV4_LITERAL_REGEX.test(normalizedPattern) ||
		isValidIpv6LiteralPattern(normalizedPattern)
	);
}

function isDefaultHttpPort(protocol: string, port: string): boolean {
	return (
		port === "" ||
		(protocol === "http:" && port === "80") ||
		(protocol === "https:" && port === "443")
	);
}

function isValidCidrAllowlistPattern(pattern: string): boolean {
	const normalizedPattern = normalizePatternValue(pattern);
	if (!CIDR_ALLOWLIST_PATTERN_REGEX.test(normalizedPattern)) {
		return false;
	}
	const [network] = normalizedPattern.split("/");
	return network !== undefined && matchesDomainPattern(network, normalizedPattern);
}

function isValidExactUrlAllowlistHostname(hostname: string): boolean {
	const normalizedHostname = hostname.toLowerCase();
	return (
		!normalizedHostname.includes("*") &&
		(isValidHostnamePattern(normalizedHostname) ||
			isValidIpLiteralPattern(normalizedHostname))
	);
}

function isValidUrlShapedAllowlistPattern(pattern: string): boolean {
	try {
		const parsed = new URL(pattern);
		if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
			return false;
		}
		if (
			parsed.hostname.length === 0 ||
			parsed.username.length > 0 ||
			parsed.password.length > 0
		) {
			return false;
		}
		if (parsed.hash !== "") {
			return false;
		}
		return isValidExactUrlAllowlistHostname(parsed.hostname);
	} catch {
		return false;
	}
}

function buildCanonicalEndpointAllowlistPattern(parsed: URL): string {
	const normalized = new URL(parsed.pathname || "/", parsed.origin);
	normalized.search = parsed.search;

	if (normalized.pathname.endsWith("/") && normalized.pathname.length > 1) {
		normalized.pathname = normalized.pathname.slice(0, -1);
	}

	if (normalized.pathname === "/" && normalized.search === "") {
		const protocol = parsed.protocol.toLowerCase();
		const hostname = parsed.hostname.toLowerCase();
		let origin = `${protocol}//${hostname}`;
		if (!isDefaultHttpPort(protocol, parsed.port)) {
			origin += `:${parsed.port}`;
		}
		return origin;
	}

	const protocol = parsed.protocol.toLowerCase();
	const hostname = parsed.hostname.toLowerCase();
	let authority = `${protocol}//${hostname}`;
	if (!isDefaultHttpPort(protocol, parsed.port)) {
		authority += `:${parsed.port}`;
	}
	return `${authority}${normalized.pathname}${normalized.search}`;
}

function isValidNormalizedMcpAllowlistPattern(pattern: string): boolean {
	if (pattern.includes("://")) {
		return isValidUrlShapedAllowlistPattern(pattern);
	}

	const normalizedPattern = normalizePatternValue(pattern);
	if (normalizedPattern === "*") {
		return true;
	}

	if (WILDCARD_HOST_ALLOWLIST_PATTERN_REGEX.test(normalizedPattern)) {
		return true;
	}

	if (normalizedPattern.includes("/")) {
		return isValidCidrAllowlistPattern(normalizedPattern);
	}

	return (
		isValidHostnamePattern(normalizedPattern) ||
		isValidIpLiteralPattern(normalizedPattern)
	);
}

/**
 * Normalize a network allowlist entry. Uses the same stored shapes as
 * `matchesAdminServerUrlPattern`: host/CIDR/*.tokens, or a canonical `http(s)://`
 * endpoint when the input includes a non-default port or explicit path.
 */
export function normalizeMcpNetworkAllowlistPattern(entry: string): string | undefined {
	if (normalizedAllowlistPatternMemo.has(entry)) {
		return normalizedAllowlistPatternMemo.get(entry);
	}
	if (normalizedAllowlistPatternMemo.size >= VALUE_MEMO_LIMIT) {
		normalizedAllowlistPatternMemo.clear();
	}
	const normalized = computeNormalizedMcpNetworkAllowlistPattern(entry);
	normalizedAllowlistPatternMemo.set(entry, normalized);
	return normalized;
}

const VALUE_MEMO_LIMIT = 2048;
const normalizedAllowlistPatternMemo = new Map<string, string | undefined>();
const adminServerUrlParseMemo = new Map<string, URL | undefined>();

function computeNormalizedMcpNetworkAllowlistPattern(entry: string): string | undefined {
	const rawValue = entry.trim();
	if (rawValue.length === 0) {
		return undefined;
	}

	const cidrSlashIndex = rawValue.lastIndexOf("/");
	if (
		!rawValue.includes("://") &&
		cidrSlashIndex > 0 &&
		/^\d+$/.test(rawValue.slice(cidrSlashIndex + 1).trim())
	) {
		const networkPart = normalizePatternValue(rawValue.slice(0, cidrSlashIndex));
		const prefixPart = rawValue.slice(cidrSlashIndex + 1).trim();
		const candidate = `${networkPart}/${prefixPart}`;
		return isValidNormalizedMcpAllowlistPattern(candidate) ? candidate : undefined;
	}

	if (
		hasEmbeddedWhitespace(rawValue) ||
		rawValue.includes("#") ||
		rawValue.includes("@")
	) {
		return undefined;
	}

	const schemeIndex = rawValue.indexOf("://");
	if (schemeIndex !== -1) {
		const protocol = rawValue.slice(0, schemeIndex).toLowerCase();
		if (protocol !== "http" && protocol !== "https") {
			return undefined;
		}

		try {
			const parsed = new URL(rawValue);
			if (
				parsed.hostname.length === 0 ||
				parsed.username.length > 0 ||
				parsed.password.length > 0
			) {
				return undefined;
			}

			const hasExplicitPath =
				parsed.pathname !== "/" && parsed.pathname !== "";
			const hasQuery = parsed.search !== "";

			if (parsed.hostname.includes("*")) {
				return undefined;
			} else if (!hasExplicitPath && !hasQuery) {
				const canonical = buildCanonicalEndpointAllowlistPattern(parsed);
				if (!isValidNormalizedMcpAllowlistPattern(canonical)) {
					return undefined;
				}
				return canonical;
			} else {
				const canonical = buildCanonicalEndpointAllowlistPattern(parsed);
				if (!isValidNormalizedMcpAllowlistPattern(canonical)) {
					return undefined;
				}
				return canonical;
			}
		} catch {
			return undefined;
		}
	} else if (rawValue.includes("/")) {
		return undefined;
	}

	const lowered = rawValue.trim().toLowerCase();
	const normalized = stripPortFromHostPattern(lowered);
	if (
		normalized.length === 0 ||
		!isValidNormalizedMcpAllowlistPattern(normalized)
	) {
		return undefined;
	}

	if (normalized !== lowered && normalized === "*") {
		return undefined;
	}

	return normalized;
}

export function matchesWildcardPattern(pattern: string, stringToMatch: string): boolean {
	if (!pattern.includes("*")) {
		return pattern === stringToMatch;
	}

	const escapedPattern = pattern.replace(/[.+?^${}()|[\]\\]/g, "\\$&");
	const regexPattern = escapedPattern.replace(/\*/g, ".*");
	const regex = new RegExp(`^${regexPattern}$`);
	return regex.test(stringToMatch);
}

/** Endpoint URL patterns require exact hosts. Wildcards belong in host-wide patterns. */
function matchesEndpointHostnamePattern(
	patternHostname: string,
	requestHostname: string
): boolean {
	return (
		!patternHostname.includes("*") &&
		normalizePatternValue(patternHostname) === normalizePatternValue(requestHostname)
	);
}

function normalizeEndpointPathname(pathname: string): string {
	if (pathname.endsWith("/") && pathname.length > 1) {
		return pathname.slice(0, -1);
	}
	return pathname;
}

function matchesEndpointPathnamePattern(
	patternPathname: string,
	requestPathname: string
): boolean {
	return (
		matchesWildcardPattern(patternPathname, requestPathname) ||
		matchesWildcardPattern(
			normalizeEndpointPathname(patternPathname),
			normalizeEndpointPathname(requestPathname)
		)
	);
}

function matchesEndpointSearchPattern(
	patternSearch: string,
	requestSearch: string,
	options: { allowRequestQueryWhenPatternOmitsQuery: boolean }
): boolean {
	if (patternSearch === "") {
		return options.allowRequestQueryWhenPatternOmitsQuery || requestSearch === "";
	}

	return matchesWildcardPattern(patternSearch, requestSearch);
}

function getOriginWideUrlPattern(pattern: string): string | undefined {
	try {
		const parsed = new URL(pattern);
		if (
			parsed.username !== "" ||
			parsed.password !== "" ||
			parsed.pathname !== "/" ||
			parsed.search !== "" ||
			parsed.hash !== ""
		) {
			return undefined;
		}

		return `${parsed.protocol}//${parsed.host}/*`;
	} catch {
		return undefined;
	}
}

function matchesEndpointUrlPattern(
	pattern: string,
	requestUrl: string,
	options: { allowRequestQueryWhenPatternOmitsQuery: boolean }
): boolean {
	const parsedRequestUrl = parseMcpNetworkRequestUrl(requestUrl);
	if (!parsedRequestUrl) {
		return false;
	}

	let parsedPattern: URL;
	try {
		parsedPattern = new URL(pattern);
	} catch {
		return false;
	}

	if (
		parsedPattern.username !== "" ||
		parsedPattern.password !== "" ||
		parsedRequestUrl.username !== "" ||
		parsedRequestUrl.password !== "" ||
		parsedPattern.protocol !== parsedRequestUrl.protocol ||
		parsedPattern.port !== parsedRequestUrl.port
	) {
		return false;
	}

	if (
		!matchesEndpointHostnamePattern(
			parsedPattern.hostname,
			parsedRequestUrl.hostname
		)
	) {
		return false;
	}

	return (
		matchesEndpointPathnamePattern(
			parsedPattern.pathname,
			parsedRequestUrl.pathname
		) &&
		matchesEndpointSearchPattern(
			parsedPattern.search,
			parsedRequestUrl.search,
			options
		)
	);
}

/** Runtime MCP network endpoint matcher. Path-scoped rules allow request query params. */
export function matchesMcpEndpointUrlPattern(
	pattern: string,
	requestUrl: string
): boolean {
	return matchesEndpointUrlPattern(pattern, requestUrl, {
		allowRequestQueryWhenPatternOmitsQuery: true,
	});
}

function hasUnclosedIpv6Bracket(input: string): boolean {
	const openIndex = input.indexOf("[");
	if (openIndex === -1) {
		return false;
	}
	return input.indexOf("]", openIndex) === -1;
}

/**
 * Parse an outbound MCP request URL. Stricter than bare `URL`: http(s) only, no
 * credentials, no whitespace, and IPv6 literals must use balanced `[…]` syntax.
 */
function parseMcpNetworkRequestUrl(url: string): URL | undefined {
	const trimmed = url.trim();
	if (trimmed.length === 0 || hasEmbeddedWhitespace(trimmed)) {
		return undefined;
	}

	if (hasUnclosedIpv6Bracket(trimmed)) {
		return undefined;
	}

	const parsed = tryParseUrl(trimmed);
	if (!parsed) {
		return undefined;
	}

	if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
		return undefined;
	}

	if (parsed.username !== "" || parsed.password !== "") {
		return undefined;
	}

	if (parsed.hostname.length === 0) {
		return undefined;
	}

	// IPv6 hostnames must appear as bracketed literals in the input, not only after normalization.
	if (
		normalizePatternValue(parsed.hostname).includes(":") &&
		!trimmed.includes("[")
	) {
		return undefined;
	}

	if (trimmed.includes("[")) {
		const openIndex = trimmed.indexOf("[");
		const closeIndex = trimmed.indexOf("]", openIndex);
		if (closeIndex === -1) {
			return undefined;
		}
		const literal = trimmed.slice(openIndex + 1, closeIndex);
		if (
			normalizePatternValue(parsed.hostname) !== normalizePatternValue(literal)
		) {
			return undefined;
		}
	}

	return parsed;
}

/**
 * Load-time matcher for concrete `allowedMcpServers[].serverUrl` checks.
 *
 * This intentionally mirrors the existing client allowlist behavior:
 * exact/wildcard string match first, then host/CIDR/domain match against the
 * parsed server URL. It is broader than runtime network controls; client
 * compatibility is the priority for admin-configured MCP server identity.
 */
export function matchesAdminServerUrlPattern(pattern: string, serverUrl: string): boolean {
	if (matchesWildcardPattern(pattern, serverUrl)) {
		return true;
	}

	let parsedServerUrl: URL | undefined;
	if (adminServerUrlParseMemo.has(serverUrl)) {
		parsedServerUrl = adminServerUrlParseMemo.get(serverUrl);
	} else {
		if (adminServerUrlParseMemo.size >= VALUE_MEMO_LIMIT) {
			adminServerUrlParseMemo.clear();
		}
		parsedServerUrl = tryParseUrl(serverUrl);
		adminServerUrlParseMemo.set(serverUrl, parsedServerUrl);
	}
	if (!parsedServerUrl) {
		return false;
	}
	return matchesDomainPattern(parsedServerUrl.hostname, pattern);
}

/**
 * Runtime matcher for outbound MCP fetches. These requests can carry per-request
 * query params (tokens, cursors, filters), so path-scoped rules ignore query
 * unless the pattern explicitly has one.
 */
export function matchesMcpAllowlistPattern(pattern: string, url: string): boolean {
	const parsedUrl = parseMcpNetworkRequestUrl(url);
	if (!parsedUrl) {
		return false;
	}

	if (!pattern.includes("://")) {
		return matchesDomainPattern(normalizePatternValue(parsedUrl.hostname), pattern);
	}

	if (matchesMcpEndpointUrlPattern(pattern, url)) {
		return true;
	}

	const originWidePattern = getOriginWideUrlPattern(pattern);
	return (
		originWidePattern !== undefined &&
		matchesMcpEndpointUrlPattern(originWidePattern, url)
	);
}

function normalizeAllowlist(entries: readonly string[] | undefined): string[] {
	return (entries ?? []).flatMap(entry => {
		const normalized = normalizeMcpNetworkAllowlistPattern(entry);
		return normalized === undefined ? [] : [normalized];
	});
}

function normalizePatternValue(value: string): string {
	const normalized = value.trim().toLowerCase();
	if (normalized.startsWith("[") && normalized.endsWith("]")) {
		return normalized.slice(1, -1);
	}
	return normalized;
}

function tryParseUrl(url: string): URL | undefined {
	const trimmed = url.trim();
	if (trimmed.length === 0) {
		return undefined;
	}

	const urlToParse = trimmed.includes("://") ? trimmed : `https://${trimmed}`;
	try {
		return new URL(urlToParse);
	} catch {
		return undefined;
	}
}

export function getEffectiveMcpNetworkAllowlist(config: McpNetworkControlsConfig): string[] {
	return normalizeAllowlist(config.mcpNetworkAllowlist);
}

export function getEffectiveMcpNetworkDenylist(config: McpNetworkControlsConfig): string[] {
	return normalizeAllowlist(config.mcpNetworkDenylist);
}

export function checkMcpNetworkUrl(
	url: string,
	config: McpNetworkControlsConfig
): McpNetworkRequestControlResult {
	if (config.enabled !== true) {
		return { allowed: true };
	}

	if (config.mcpNetworkMode === "no_sandbox") {
		return { allowed: true };
	}

	if (!parseMcpNetworkRequestUrl(url)) {
		return {
			allowed: false,
			message: config.blockMessage ?? MCP_NETWORK_CONTROLS_BLOCK_MESSAGE,
		};
	}

	const allowlist = getEffectiveMcpNetworkAllowlist(config);
	if (
		allowlist.length > 0 &&
		allowlist.some(pattern => matchesMcpAllowlistPattern(pattern, url))
	) {
		return { allowed: true };
	}

	return {
		allowed: false,
		message: config.blockMessage ?? MCP_NETWORK_CONTROLS_BLOCK_MESSAGE,
	};
}

export function getMcpNetworkControlsBlockMessage(
	url: string,
	config: McpNetworkControlsConfig
): string | undefined {
	const result = checkMcpNetworkUrl(url, config);
	return result.allowed ? undefined : result.message;
}

export interface McpNetworkControlsAllowedServerEntry {
	readonly command?: string;
	readonly serverUrl?: string;
	readonly networkAllowlist?: readonly string[];
	readonly networkMode?: string;
}

export interface McpNetworkControlsAllowedConfiguration {
	readonly allowUserOverrideMcpServers?: boolean;
	readonly allowedMcpServers?: readonly McpNetworkControlsAllowedServerEntry[];
	readonly deniedMcpServers?: readonly McpNetworkControlsAllowedServerEntry[];
}

export interface McpNetworkControlsServer {
	readonly command?: string;
	readonly url?: string;
}

export interface ResolveMcpNetworkControlsConfigFromAdminPolicyOptions {
	readonly allowedMcpConfiguration?: McpNetworkControlsAllowedConfiguration;
	readonly server?: McpNetworkControlsServer;
	readonly localAgentNetworkAllowlist?: readonly string[];
	readonly blockMessage?: string;
	/**
	 * Controls the shape returned for a server-specific lookup with no matching
	 * admin policy row. VS Code desktop historically returned an empty array,
	 * while local-exec and cursor-mcp returned undefined.
	 */
	readonly unmatchedServerAllowlist?: readonly string[];
	/**
	 * Controls no-server aggregate reads. Desktop uses the aggregate allowlist for
	 * policy fingerprints; local-exec and cursor-mcp historically returned no
	 * per-MCP allowlist unless resolving a specific server.
	 */
	readonly aggregateManagedServerNetworkAllowlists?: boolean;
}

export function parseMcpNetworkMode(value: unknown): McpNetworkMode | undefined {
	return value === "allow_all" ||
		value === "allowlist" ||
		value === "deny_all" ||
		value === "no_sandbox"
		? value
		: undefined;
}

export function getConfiguredMcpAllowlistField(value: string | undefined): string | undefined {
	const trimmedValue = value?.trim();
	return trimmedValue && trimmedValue.length > 0 ? trimmedValue : undefined;
}

function hasDenylistPathOrQueryWildcard(rawValue: string): boolean {
	const schemeIndex = rawValue.indexOf("://");
	if (schemeIndex === -1) {
		return false;
	}

	const afterScheme = rawValue.slice(schemeIndex + "://".length);
	const slashIndex = afterScheme.indexOf("/");
	if (slashIndex === -1) {
		return afterScheme.includes("?");
	}

	return afterScheme.slice(slashIndex).includes("*");
}

export function normalizeMcpNetworkDenylistPattern(serverUrl: string): string | undefined {
	const rawValue = serverUrl.trim();
	if (rawValue.length === 0) {
		return undefined;
	}

	if (hasDenylistPathOrQueryWildcard(rawValue)) {
		const schemeIndex = rawValue.indexOf("://");
		if (schemeIndex !== -1) {
			const authority = rawValue
				.slice(schemeIndex + "://".length)
				.split(/[/?#]/, 1)[0];
			if (authority !== undefined && authority.includes("*")) {
				const hostPattern = authority.replace(/:\d+$/, "");
				const normalizedHost = normalizeMcpNetworkAllowlistPattern(hostPattern);
				if (normalizedHost !== undefined) {
					return normalizedHost;
				}
			}
		}
		return undefined;
	}

	if (!rawValue.includes("://") && rawValue.includes("*") && rawValue !== "*" && !rawValue.startsWith("*.")) {
		return undefined;
	}

	const normalized = normalizeMcpNetworkAllowlistPattern(serverUrl);
	if (normalized !== undefined) {
		return normalized;
	}

	const schemeIndex = serverUrl.indexOf("://");
	if (schemeIndex === -1) {
		return undefined;
	}
	const protocol = serverUrl.slice(0, schemeIndex).toLowerCase();
	if (protocol !== "http" && protocol !== "https") {
		return undefined;
	}

	const authority = serverUrl
		.slice(schemeIndex + "://".length)
		.split(/[/?#]/, 1)[0];
	if (authority === undefined || authority.includes("@")) {
		return undefined;
	}
	const hostPattern = authority.replace(/:\d+$/, "");
	const normalizedHost = normalizeMcpNetworkAllowlistPattern(hostPattern);
	if (normalizedHost !== undefined) {
		return normalizedHost;
	}

	try {
		return normalizeMcpNetworkAllowlistPattern(new URL(serverUrl).hostname);
	} catch {
		return undefined;
	}
}

function resolveMcpNetworkDenylistForUserExtensionServers(
	allowedMcpConfiguration: McpNetworkControlsAllowedConfiguration | undefined
): readonly string[] | undefined {
	if (allowedMcpConfiguration?.allowUserOverrideMcpServers !== true) {
		return undefined;
	}
	const denylist = (allowedMcpConfiguration.deniedMcpServers ?? []).flatMap(serverEntry => {
		const serverUrl = getConfiguredMcpAllowlistField(serverEntry.serverUrl);
		const normalized =
			serverUrl === undefined
				? undefined
				: normalizeMcpNetworkDenylistPattern(serverUrl);
		return normalized === undefined ? [] : [normalized];
	});
	return denylist.length > 0 ? denylist : undefined;
}

export function matchesAllowedMcpServerEntry(
	serverEntry: McpNetworkControlsAllowedServerEntry,
	server: McpNetworkControlsServer
): boolean {
	const commandPattern = getConfiguredMcpAllowlistField(serverEntry.command);
	const serverUrlPattern = getConfiguredMcpAllowlistField(serverEntry.serverUrl);
	if (commandPattern === undefined && serverUrlPattern === undefined) {
		return false;
	}

	const passesCommandPolicy =
		commandPattern === undefined ||
		(server.command !== undefined &&
			matchesWildcardPattern(commandPattern, server.command));
	const passesServerUrlPolicy =
		serverUrlPattern === undefined ||
		(server.url !== undefined &&
			matchesAdminServerUrlPattern(serverUrlPattern, server.url));

	return passesCommandPolicy && passesServerUrlPolicy;
}

export function getMatchedAllowedMcpServer(
	allowedMcpServers: readonly McpNetworkControlsAllowedServerEntry[] | undefined,
	server: McpNetworkControlsServer
): McpNetworkControlsAllowedServerEntry | undefined {
	return allowedMcpServers?.find(serverEntry =>
		matchesAllowedMcpServerEntry(serverEntry, server)
	);
}

export function isAllowedUserExtensionCommandServer(
	allowedMcpConfiguration: McpNetworkControlsAllowedConfiguration | undefined,
	matchedServer: McpNetworkControlsAllowedServerEntry | undefined,
	server: McpNetworkControlsServer | undefined
): boolean {
	return (
		server?.command !== undefined &&
		server.url === undefined &&
		matchedServer === undefined &&
		allowedMcpConfiguration?.allowUserOverrideMcpServers === true
	);
}

export function shouldEnableMcpNetworkControlsConfigForServer({
	allowedMcpConfiguration,
	matchedServer,
	server,
}: {
	allowedMcpConfiguration: McpNetworkControlsAllowedConfiguration | undefined;
	matchedServer: McpNetworkControlsAllowedServerEntry | undefined;
	server: McpNetworkControlsServer | undefined;
}): boolean {
	// This decides whether to return an active MCP network-controls config. The
	// stdio sandbox decision is made by `getStdioMcpSandboxConfig`, which also
	// handles explicit `no_sandbox`.
	if (server === undefined) {
		return (allowedMcpConfiguration?.allowedMcpServers?.length ?? 0) > 0;
	}

	if (matchedServer !== undefined) {
		return true;
	}

	return isAllowedUserExtensionCommandServer(
		allowedMcpConfiguration,
		matchedServer,
		server
	);
}

export function resolveMcpNetworkAllowlistForMatchedServer(
	matchedServer: McpNetworkControlsAllowedServerEntry | undefined,
	server: McpNetworkControlsServer,
	unmatchedServerAllowlist?: readonly string[]
): readonly string[] | undefined {
	if (matchedServer === undefined) {
		return unmatchedServerAllowlist;
	}

	return [
		...(matchedServer.networkAllowlist ?? []),
		...(getConfiguredMcpAllowlistField(matchedServer.serverUrl) !== undefined &&
		server.url !== undefined
			? [server.url]
			: []),
	];
}

export function resolveMcpNetworkModeForMatchedCommandServer(
	matchedServer: McpNetworkControlsAllowedServerEntry | undefined,
	server: McpNetworkControlsServer
): McpNetworkMode | undefined {
	if (
		getConfiguredMcpAllowlistField(matchedServer?.command) === undefined ||
		server.command === undefined ||
		server.url !== undefined
	) {
		return undefined;
	}

	return parseMcpNetworkMode(matchedServer?.networkMode) ?? "no_sandbox";
}

export function resolveMcpNetworkControlsConfigFromAdminPolicy({
	allowedMcpConfiguration,
	server,
	localAgentNetworkAllowlist,
	blockMessage,
	unmatchedServerAllowlist,
	aggregateManagedServerNetworkAllowlists = true,
}: ResolveMcpNetworkControlsConfigFromAdminPolicyOptions): McpNetworkControlsConfig {
	const allowedMcpServers = allowedMcpConfiguration?.allowedMcpServers;
	const userExtensionMcpNetworkDenylist =
		resolveMcpNetworkDenylistForUserExtensionServers(allowedMcpConfiguration);
	const matchedServer =
		server === undefined
			? undefined
			: getMatchedAllowedMcpServer(allowedMcpServers, server);
	const allowedUserExtensionCommandServer =
		isAllowedUserExtensionCommandServer(
			allowedMcpConfiguration,
			matchedServer,
			server
		);
	const enabled =
		shouldEnableMcpNetworkControlsConfigForServer({
			allowedMcpConfiguration,
			matchedServer,
			server,
		}) ||
		(server === undefined
			? userExtensionMcpNetworkDenylist !== undefined
			: false);
	const mcpNetworkAllowlist =
		server === undefined
			? aggregateManagedServerNetworkAllowlists
				? allowedMcpServers?.flatMap(
					serverEntry => serverEntry.networkAllowlist ?? []
				)
				: undefined
			: allowedUserExtensionCommandServer
				? []
				: resolveMcpNetworkAllowlistForMatchedServer(
					matchedServer,
					server,
					unmatchedServerAllowlist
				);
	const mcpNetworkMode =
		server === undefined
			? undefined
			: allowedUserExtensionCommandServer
				? "allow_all"
				: resolveMcpNetworkModeForMatchedCommandServer(matchedServer, server);
	const mcpNetworkDenylist =
		server === undefined || allowedUserExtensionCommandServer
			? userExtensionMcpNetworkDenylist
			: undefined;

	return {
		enabled,
		mcpNetworkAllowlist,
		...(mcpNetworkMode !== undefined ? { mcpNetworkMode } : {}),
		...(mcpNetworkDenylist !== undefined ? { mcpNetworkDenylist } : {}),
		...(localAgentNetworkAllowlist !== undefined
			? { localAgentNetworkAllowlist }
			: {}),
		...(blockMessage !== undefined ? { blockMessage } : {}),
	};
}

export function getStdioMcpSandboxConfig(
	networkControlsConfig: McpNetworkControlsConfig | undefined
): McpNetworkControlsConfig | undefined {
	if (networkControlsConfig?.enabled !== true) {
		return undefined;
	}

	if (networkControlsConfig.mcpNetworkMode === "no_sandbox") {
		return undefined;
	}

	return networkControlsConfig;
}
