import { realpath } from "node:fs/promises";
import { homedir } from "node:os";
import {
  dirname,
  isAbsolute,
  normalize,
  parse,
  relative,
  resolve,
  sep,
} from "node:path";
import { fileURLToPath } from "node:url";

// Unix path separator - we normalize all paths to use this
const SEP = "/";

/**
 * Expands ~ to the user's home directory.
 */
export function untildify(path: string): string {
  return path.replace(/^~(?=$|\/|\\)/, homedir());
}

/** Convert a `file://` URL to a filesystem path; leave other inputs unchanged. */
function stripFileUrlIfPresent(path: string): string {
  if (!path.startsWith("file://")) {
    return path;
  }
  try {
    return fileURLToPath(path);
  } catch {
    return path;
  }
}

/**
 * True when `path` is the user's home directory.
 *
 * On Windows, VS Code's `URI#fsPath` uses a lowercase drive letter (via `URI.file` normalization)
 * while `os.homedir()` typically returns the OS-default drive letter casing, so strict `===` can
 * spuriously fail. NTFS paths are case-insensitive for this comparison, so we compare
 * case-insensitively on `win32` only. We also `normalize` on Windows so `\\` vs `/` (and
 * `.` / `..` segments) do not cause a false mismatch.
 */
export function isSameDirectoryPathAsHome(
  path: string | undefined,
  homeDir: string
): boolean {
  if (path === undefined) {
    return false;
  }
  if (process.platform === "win32") {
    return normalize(path).toLowerCase() === normalize(homeDir).toLowerCase();
  }
  return path === homeDir;
}

/**
 * Resolves a path, expanding ~ and optionally resolving relative paths against a base path.
 * - Converts `file://` URLs to filesystem paths
 * - Expands ~ to $HOME
 * - If basePath is provided and path is relative, resolves against basePath
 * - Otherwise resolves to absolute path
 */
export function resolvePath(path: string, basePath?: string): string {
  const untildified = untildify(stripFileUrlIfPresent(path));
  // If a base path is provided and the path is not absolute, resolve relative to base path
  if (basePath && !isAbsolute(untildified)) {
    return resolve(basePath, untildified);
  }
  return resolve(untildified);
}

/**
 * Resolve a path to its canonical real path by following symlinks.
 *
 * - Expands ~ and resolves relative paths against basePath (like resolvePath)
 * - Follows symlinks via realpath
 * - Returns the canonical path on success
 * - Returns the canonical path with any missing suffix re-attached on ENOENT
 * - Returns null if the path can't be verified (EACCES, ELOOP, etc.) --
 *   callers in security-sensitive contexts should treat null as "block"
 */
export async function resolveRealPathStrict(
  path: string,
  basePath?: string
): Promise<string | null> {
  const normalized = resolvePath(path, basePath);
  let current = normalized;

  while (true) {
    try {
      const resolvedCurrent = await realpath(current);
      return resolve(resolvedCurrent, relative(current, normalized));
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code !== "ENOENT") {
        return null;
      }

      const parent = dirname(current);
      if (parent === current) {
        return normalized;
      }
      current = parent;
    }
  }
}

/**
 * Check if a resolved path is within a base directory.
 * This is filesystem-agnostic and works for absolute or relative targets.
 */
export function isPathWithin({
  basePath,
  targetPath,
}: {
  basePath: string;
  targetPath: string;
}): boolean {
  const resolvedBase = resolve(basePath);
  const resolvedTarget = resolve(basePath, targetPath);

  // When base is the filesystem root (e.g. "/" or "C:\"), resolvedBase + sep is "//"
  // and no normal path starts with that, so the usual check fails. Any path under
  // the same root is considered within the base.
  if (resolvedBase === parse(resolvedBase).root) {
    return (
      // 1) The resolved target root is the same as the resolved base root
      parse(resolvedTarget).root === resolvedBase &&
      // 2) target is root OR is a path under the root.
      (resolvedTarget === resolvedBase ||
        resolvedTarget.length > resolvedBase.length)
    );
  }

  return (
    resolvedTarget === resolvedBase ||
    resolvedTarget.startsWith(resolvedBase + sep)
  );
}

/**
 * Check if a path is within any of the provided root directories.
 */
export function isPathWithinAnyRoot(
  targetPath: string,
  roots: string[]
): boolean {
  for (const root of roots) {
    if (isPathWithin({ basePath: root, targetPath })) {
      return true;
    }
  }
  return false;
}

/**
 * Normalizes a path to use Unix separators, converting Windows paths to Unix format.
 * This ensures paths work correctly regardless of the client OS when running on the backend.
 */
export function normalizeToUnixPath(path: string): string {
  // Replace Windows backslashes with forward slashes
  return path.replace(/\\/g, SEP);
}

/**
 * Checks if a path contains `.cursor/worktrees`, indicating it's a Cursor worktree.
 * Normalizes the path to Unix format before checking.
 */
export function isWorktreesPath(path: string): boolean {
  const normalizedPath = normalizeToUnixPath(path);
  return normalizedPath.includes(".cursor/worktrees");
}

export const WORKTREE_GUARD_ERROR: string =
  "You cannot search other worktrees for this repository, stay within your workspace paths.";

export function getWorktreesRepoRoot(worktreePath: string): string | undefined {
  const normalizedPath: string = normalizeToUnixPath(worktreePath);
  const marker: string = "/.cursor/worktrees/";
  const markerIndex: number = normalizedPath.indexOf(marker);
  if (markerIndex === -1) {
    return undefined;
  }

  const afterMarker: string = normalizedPath.slice(markerIndex + marker.length);
  const parts: string[] = afterMarker.split("/");
  if (parts.length < 2) {
    return undefined;
  }

  const repoName: string = parts[0] ?? "";
  if (repoName.length === 0) {
    return undefined;
  }

  return normalizedPath.slice(0, markerIndex + marker.length + repoName.length);
}

export function shouldBlockWorktreePath(params: {
  targetPath: string | undefined;
  workspacePaths: string[];
  mainWorktreePath?: string;
}): boolean {
  const { targetPath, workspacePaths, mainWorktreePath } = params;
  if (targetPath === undefined) {
    return false;
  }
  if (workspacePaths.length === 0) {
    return false;
  }
  if (!workspacePaths.every(path => isWorktreesPath(path))) {
    return false;
  }
  if (isPathWithinAnyRoot(targetPath, workspacePaths)) {
    return false;
  }

  const resolvedTargets: string[] = isAbsolute(targetPath)
    ? [resolve(targetPath)]
    : workspacePaths.map(workspacePath => resolve(workspacePath, targetPath));

  const worktreeRepoRoots: string[] = workspacePaths
    .map(root => getWorktreesRepoRoot(root))
    .filter((root): root is string => root !== undefined);
  if (worktreeRepoRoots.length > 0) {
    if (
      resolvedTargets.some(target =>
        isPathWithinAnyRoot(target, worktreeRepoRoots)
      )
    ) {
      return true;
    }
  }

  if (
    mainWorktreePath !== undefined &&
    resolvedTargets.some(target =>
      isPathWithinAnyRoot(target, [mainWorktreePath])
    )
  ) {
    return true;
  }

  return false;
}
