/**
 * Gets the shell executable path for a known shell executor type.
 * Returns the shell path that can be passed to NaiveTerminalExecutor.
 */
export function getShellExecutablePath(shell: KnownShellExecutor): string {
  switch (shell) {
    case KnownShellExecutor.Zsh:
    case KnownShellExecutor.ZshLight:
      return findActualExecutable("zsh", []).cmd;
    case KnownShellExecutor.Bash:
      return findActualExecutable("bash", []).cmd;
    case KnownShellExecutor.PowerShell:
      return getPowerShellExecutable();
    default:
      return process.env.SHELL || "/bin/sh";
  }
}

/**
 * Checks if a command exists in the PATH.
 */
function commandExists(command: string): boolean {
  try {
    return findActualExecutable(command, []).cmd !== command;
  } catch (_e) {
    return false;
  }
}

function getGitBashPathFromExePath(exepath: string): string {
  const normalizedExePath = exepath.replace(/[\\/]+$/, "");
  const basename = path.win32.basename(normalizedExePath).toLowerCase();

  if (basename === "bash.exe") {
    return normalizedExePath;
  }

  if (basename === "bin") {
    return path.win32.join(normalizedExePath, "bash.exe");
  }

  return path.win32.join(normalizedExePath, "bin", "bash.exe");
}

/**
 * Detects if the current process is running inside a Git Bash (MSYS2/MinGW) environment.
 * This is determined by checking the MSYSTEM environment variable, which is set by Git Bash.
 * Returns a Git Bash executable path hint if detected, undefined otherwise.
 */
function detectGitBashFromEnvironment(): string | undefined {
  if (process.platform !== "win32") {
    return undefined;
  }

  // MSYSTEM is set by Git Bash/MSYS2/MinGW environments
  // Common values: MINGW64, MINGW32, MSYS, CLANG64, UCRT64
  const msystem = process.env.MSYSTEM;
  if (!msystem) {
    return undefined;
  }

  // We're in a Git Bash environment. Try to find the bash executable.
  // EXEPATH can be the Git installation directory or Git's bin directory.
  const exepath = process.env.EXEPATH;
  if (exepath) {
    return getGitBashPathFromExePath(exepath);
  }

  // Fallback: check common Git Bash installation paths
  const commonPaths = [
    "C:\\Program Files\\Git\\bin\\bash.exe",
    "C:\\Program Files (x86)\\Git\\bin\\bash.exe",
  ];

  for (const candidatePath of commonPaths) {
    try {
      const result = findActualExecutable(candidatePath, []);
      if (result.cmd === candidatePath) {
        return candidatePath;
      }
    } catch {
      // Path doesn't exist, try next
    }
  }

  // Last resort: just return a standard path and let the bash.ts handle validation
  return "C:\\Program Files\\Git\\bin\\bash.exe";
}

export function getSuggestedShell(
  userTerminalHint?: string
): KnownShellExecutor {
  if (userTerminalHint === KnownShellExecutor.ZshLight) {
    return KnownShellExecutor.ZshLight;
  }

  const shell = userTerminalHint || process.env.SHELL || "";
  const isWindows = process.platform === "win32";

  // On Windows, detect Git Bash from environment variables if no explicit hint was provided.
  // This allows agent-cli to automatically use Git Bash when launched from a Git Bash terminal.
  const gitBashFromEnv =
    isWindows && !userTerminalHint ? detectGitBashFromEnvironment() : undefined;

  // NB: We normally would not want to support this, but Git Bash is quite popular
  // so we'll try to make it work anyways. We don't support more obscure
  // variants of Bash like Cygwin.
  const isGitBash =
    gitBashFromEnv !== undefined ||
    /git.*bash\.exe$/i.test(shell) ||
    /program.*git.*bin.*bash\.exe$/i.test(shell);
  const bashIsOkay = !isWindows || isGitBash;

  // Check if user's shell is a specific type
  if (shell.includes("zsh")) {
    return KnownShellExecutor.Zsh;
  } else if (shell.includes("bash") && bashIsOkay) {
    return KnownShellExecutor.Bash;
  } else if (shell.includes("pwsh") || shell.includes("powershell")) {
    return KnownShellExecutor.PowerShell;
  } else if (gitBashFromEnv) {
    // If we detected Git Bash from environment, use Bash
    return KnownShellExecutor.Bash;
  } else {
    // On Windows, prefer PowerShell
    if (isWindows) {
      if (commandExists("pwsh") || commandExists("powershell")) {
        return KnownShellExecutor.PowerShell;
      }
    }

    // Check if shells are available in PATH
    if (commandExists("zsh")) {
      return KnownShellExecutor.Zsh;
    } else if (commandExists("bash") && bashIsOkay) {
      return KnownShellExecutor.Bash;
    } else if (commandExists("pwsh") || commandExists("powershell")) {
      return KnownShellExecutor.PowerShell;
    } else {
      // Fall back to naive executor
      return KnownShellExecutor.Naive;
    }
  }
}

/**
 * Creates a default terminal executor based on the user's shell.
 * If the user's shell is zsh, returns a LazyTerminalExecutor with zsh state.
 * If the user's shell is bash, returns a LazyTerminalExecutor with bash state.
 * Otherwise, checks if zsh or bash are available in PATH before falling back to NaiveTerminalExecutor.
 *
 * On Windows, if running inside a Git Bash environment (detected via MSYSTEM env var),
 * the executor will automatically use Git Bash for shell commands.
 *
 * Policies are provided per-execution via options; the default executor is policy-agnostic.
 */
export function createDefaultTerminalExecutor(
  options?: TerminalInitializationOptions
): TerminalExecutor {
  // If no userTerminalHint is provided, check for Git Bash environment on Windows
  let effectiveOptions = options;
  if (!options?.userTerminalHint) {
    const gitBashPath = detectGitBashFromEnvironment();
    if (gitBashPath) {
      effectiveOptions = {
        ...options,
        userTerminalHint: gitBashPath,
      };
    }
  }

  const suggestedShell = getSuggestedShell(
    effectiveOptions?.userTerminalHint ?? ""
  );

  switch (suggestedShell) {
    case KnownShellExecutor.Zsh:
      return new LazyTerminalExecutor(() => initZshState(effectiveOptions));
    case KnownShellExecutor.Bash:
      return new LazyTerminalExecutor(() => initBashState(effectiveOptions));
    case KnownShellExecutor.PowerShell:
      return new LazyTerminalExecutor(() => initPowerShellState());

    case KnownShellExecutor.ZshLight:
      return new LazyTerminalExecutor(() =>
        initZshLightState(effectiveOptions)
      );

    default:
      return createNaiveTerminalExecutor(effectiveOptions);
  }
}

