import type { Context } from "@anysphere/context";
import { TTLCache } from "@anysphere/utils";
import {
  type RipwalkOptions,
  type RipwalkResult,
  ripwalk,
} from "./ripgrep-stream.js";

type RipwalkCacheEntry = {
  linesPromise: Promise<readonly string[]>;
};

/**
 * How long a workspace scan stays reusable.
 *
 * Short by default because an editor's files move under it: rules, skills and
 * ignore files a user just added should show up on the next scan, and 20s is
 * about the longest anyone would tolerate not seeing them.
 *
 * Long-lived hosts serving a checkout that only changes on deploy — the Agent SDK,
 * above all — are the opposite case, and each expiry there costs them a full
 * re-walk of the repo. They can trade that freshness back with
 * {@link setRipwalkCacheTtlMs} or `CURSOR_RIPWALK_CACHE_TTL_MS`.
 */
export const DEFAULT_RIPWALK_CACHE_TTL_MS = 20_000;

const RIPWALK_CACHE_TTL_ENV_VAR = "CURSOR_RIPWALK_CACHE_TTL_MS";

let ripwalkCacheTtlOverrideMs: number | undefined;

/**
 * Set the workspace-scan lifetime for this process. Takes effect for scans
 * cached from here on; anything already cached keeps the lifetime it was
 * given, so shortening the TTL is not a way to force a rescan (use
 * {@link RipwalkTtlCache.clear} for that).
 */
export function setRipwalkCacheTtlMs(ttlMs: number | undefined): void {
  if (ttlMs !== undefined && (!Number.isFinite(ttlMs) || ttlMs <= 0)) {
    throw new Error(
      `Workspace scan cache TTL must be a positive number of milliseconds, got ${ttlMs}`
    );
  }
  ripwalkCacheTtlOverrideMs = ttlMs;
}

export function getRipwalkCacheTtlMs(
  env: NodeJS.ProcessEnv = process.env
): number {
  if (ripwalkCacheTtlOverrideMs !== undefined) {
    return ripwalkCacheTtlOverrideMs;
  }
  const raw = env[RIPWALK_CACHE_TTL_ENV_VAR]?.trim();
  if (raw !== undefined && raw !== "") {
    const parsed = Number(raw);
    if (Number.isFinite(parsed) && parsed > 0) {
      return parsed;
    }
  }
  return DEFAULT_RIPWALK_CACHE_TTL_MS;
}

function getAbortPromise(signal: AbortSignal): Promise<"aborted"> {
  return new Promise(resolve => {
    if (signal.aborted) {
      resolve("aborted");
      return;
    }
    signal.addEventListener("abort", () => resolve("aborted"), {
      once: true,
    });
  });
}

function getRipwalkCacheKey({
  root,
  searchPaths = [],
  includeGlobs = [],
  excludeGlobs = [],
  caseSensitive = false,
  cursorIgnoreFiles = [],
  sandboxPolicy = { type: "insecure_none" },
  noIgnoreVcs = false,
  followSymlinks = false,
}: RipwalkOptions): string {
  return JSON.stringify({
    root,
    searchPaths,
    includeGlobs,
    excludeGlobs,
    caseSensitive,
    cursorIgnoreFiles,
    sandboxPolicy,
    noIgnoreVcs,
    followSymlinks,
  });
}

export class RipwalkTtlCache {
  private readonly cache: TTLCache<string, RipwalkCacheEntry>;

  constructor(ttlMs: number | (() => number) = () => getRipwalkCacheTtlMs()) {
    this.cache = new TTLCache<string, RipwalkCacheEntry>({ ttlMs });
  }

  clear(): void {
    this.cache.clear();
  }

  delete(options: RipwalkOptions): void {
    this.cache.delete(getRipwalkCacheKey(options));
  }

  walk(ctx: Context, options: RipwalkOptions): RipwalkResult {
    const cacheKey = getRipwalkCacheKey(options);

    let abortResolved = false;
    let didTimeoutResolved = false;
    let resolveDidTimeout: (value: boolean) => void;
    const didTimeout = new Promise<boolean>(resolve => {
      resolveDidTimeout = resolve;
    });
    const resolveDidTimeoutOnce = (value: boolean) => {
      if (didTimeoutResolved) {
        return;
      }
      didTimeoutResolved = true;
      resolveDidTimeout(value);
    };
    const abortPromise = getAbortPromise(ctx.signal);

    const streamLines = async function* (
      this: RipwalkTtlCache
    ): AsyncGenerator<string> {
      const cachedEntry = this.cache.get(cacheKey);
      if (cachedEntry !== undefined) {
        const cachedResult = await Promise.race([
          cachedEntry.linesPromise.then(
            lines => ({ type: "lines" as const, lines }),
            error => ({ type: "error" as const, error })
          ),
          abortPromise.then(() => ({ type: "aborted" as const })),
        ]);
        if (cachedResult.type === "aborted") {
          abortResolved = true;
          resolveDidTimeoutOnce(true);
          return;
        }
        if (cachedResult.type === "lines") {
          resolveDidTimeoutOnce(false);
          yield* cachedResult.lines;
          return;
        }
        if (this.cache.get(cacheKey) === cachedEntry) {
          this.cache.delete(cacheKey);
        }
      }

      let resolveCachedLines: ((lines: readonly string[]) => void) | undefined;
      let rejectCachedLines: ((error: unknown) => void) | undefined;
      const newEntry: RipwalkCacheEntry = {
        linesPromise: new Promise<readonly string[]>((resolve, reject) => {
          resolveCachedLines = resolve;
          rejectCachedLines = reject;
        }),
      };
      newEntry.linesPromise.catch(() => {});
      this.cache.set(cacheKey, newEntry);

      const collectedLines: string[] = [];
      let shouldCacheCollectedLines = false;
      let cacheFailureReason: unknown;

      try {
        const innerWalk = ripwalk(ctx, options);

        for await (const line of innerWalk.lines) {
          collectedLines.push(line);
          yield line;
        }

        if (await innerWalk.didTimeout) {
          abortResolved = true;
          cacheFailureReason = new Error(
            "Ripwalk aborted before cacheable result was available"
          );
          resolveDidTimeoutOnce(true);
          return;
        }

        shouldCacheCollectedLines = true;
      } catch (error) {
        cacheFailureReason = error;
        throw error;
      } finally {
        if (shouldCacheCollectedLines) {
          resolveCachedLines?.(collectedLines);
        } else {
          if (this.cache.get(cacheKey) === newEntry) {
            this.cache.delete(cacheKey);
          }
          rejectCachedLines?.(
            cacheFailureReason ??
              new Error(
                "Ripwalk terminated before cacheable result was available"
              )
          );
        }
        if (!abortResolved) {
          resolveDidTimeoutOnce(false);
        }
      }
    }.bind(this);

    return {
      lines: streamLines(),
      didTimeout,
    };
  }
}
