/**
 * Injection point for constructing the per-server OAuth client provider.
 *
 * The shared transport factory in `./transport-factory.ts` calls into a
 * host-registered factory to obtain an SDK-shaped `OAuthClientProvider`
 * (plus optional static client info from the user-supplied auth config).
 *
 * The concrete factory implementation stays in cursor-mcp (and any other
 * host) because the production `MCPOAuthClientProvider` reaches into
 * `vscode.cursor.*` APIs, the OAuth attempt store, and other host
 * surfaces that should not be hard-coupled to mcp-core.
 *
 * The factory type intentionally references {@link TransportAuthEventSink}
 * from `./transport-factory.js` as a TYPE-ONLY import to avoid creating a
 * runtime module cycle (TypeScript erases the import; the factory is just
 * a function value at runtime).
 */

import type { OAuthClientProvider } from "@modelcontextprotocol/sdk/client/auth.js";
import type { MCPServerInfo } from "../fsm/index.js";
import type { McpHostEnvironment } from "../transport/mcp-host-environment.js";
import type { TransportAuthEventSink } from "./transport-factory.js";

type UrlBasedMCPServerInfo = Extract<MCPServerInfo, { serverUrl: string }>;

export interface McpLifecycleOAuthClientProviderFactoryArgs {
  identifier: string;
  serverInfo: UrlBasedMCPServerInfo;
  host: McpHostEnvironment;
  authEventSink: TransportAuthEventSink;
  canonicalServerUrl: string;
  transportServerUrl: string;
}

export interface McpLifecycleOAuthClientProviderResult {
  authProvider: OAuthClientProvider;
  staticClientInfo?: {
    client_id: string;
    client_secret?: string;
  };
}

export type McpLifecycleOAuthClientProviderFactory = (
  args: McpLifecycleOAuthClientProviderFactoryArgs
) => Promise<McpLifecycleOAuthClientProviderResult>;

let _factory: McpLifecycleOAuthClientProviderFactory | undefined;

export function setMcpLifecycleOAuthClientProviderFactory(
  factory: McpLifecycleOAuthClientProviderFactory
): void {
  _factory = factory;
}

export function getMcpLifecycleOAuthClientProviderFactory():
  | McpLifecycleOAuthClientProviderFactory
  | undefined {
  return _factory;
}

/**
 * Returns the registered factory or throws. Used at the lifecycle's
 * authentication call sites where a missing factory indicates the host
 * forgot to run `wireMcpCoreFromVscode()` (or the equivalent) at startup.
 */
export function requireMcpLifecycleOAuthClientProviderFactory(): McpLifecycleOAuthClientProviderFactory {
  if (!_factory) {
    throw new Error(
      "McpLifecycleOAuthClientProviderFactory has not been registered. " +
        "The host (cursor-mcp or mcpProcess) must call " +
        "setMcpLifecycleOAuthClientProviderFactory() at activation."
    );
  }
  return _factory;
}
