import { UnauthorizedError } from '@modelcontextprotocol/sdk/client/auth.js';
import {
	InvalidClientError,
	InvalidGrantError,
	InvalidTokenError,
	OAuthError,
	UnauthorizedClientError,
} from '@modelcontextprotocol/sdk/server/auth/errors.js';
import {
	isExpiredTokenInvalidRequestOAuthError,
	isOAuthRefreshTransientError,
	OAUTH_CREDENTIAL_ERROR_CODES,
	OAUTH_CREDENTIAL_ERROR_NAMES,
	SiblingAlreadyRefreshedError,
} from '../oauth/oauth-errors.js';
import { isTimeoutErrorMessage } from '../transport/error-message-utils.js';
import { extractHttpStatusCode, isRetryableNetworkError } from '../transport/reconnect-manager.js';
import type { ConnectionEvent } from './types.js';

export { extractHttpStatusCode };

export type McpFailureReasonKind =
	| 'auth'
	| 'sibling_refreshed'
	| 'session_invalidated'
	| 'http_4xx'
	| 'http_5xx'
	| 'network'
	| 'timeout'
	| 'unknown';

export type McpFailureClassification = {
	reason: McpFailureReasonKind;
	retryable: boolean;
	httpStatus?: number;
};

export type McpFailureLogAction = 'suppress' | 'debug' | 'warn';

type LoggedConnectionFailureEvent = Extract<
	ConnectionEvent,
	{ kind: 'connect_failure' | 'transport_error' | 'transport_closed' | 'session_invalidated' }
>;

function getErrorCode(error: unknown): unknown {
	if (typeof error === 'object' && error !== null && 'code' in error) {
		return error.code;
	}
	return undefined;
}

function getErrorName(error: unknown): string | undefined {
	if (typeof error === 'object' && error !== null && 'name' in error && typeof error.name === 'string') {
		return error.name;
	}
	return undefined;
}

function getOAuthErrorCode(error: unknown): string | undefined {
	if (typeof error === 'object' && error !== null && 'errorCode' in error && typeof error.errorCode === 'string') {
		return error.errorCode;
	}
	return undefined;
}

function isAuthRelatedOAuthErrorCode(code: unknown): boolean {
	return typeof code === 'string' && OAUTH_CREDENTIAL_ERROR_CODES.has(code.toLowerCase());
}

/**
 * Check if an SDK error is a benign stale response that should not affect
 * the server's displayed status.  This happens when a JSON-RPC response
 * arrives for a request whose handler was already removed (e.g. by _onclose
 * during a transport reconnect).  The server is still healthy.
 */
export function isBenignSdkError(error: Error): boolean {
	return error.message.includes('Received a response for an unknown message ID');
}

/**
 * Check if an error is likely caused by expired or invalid OAuth credentials.
 * Used to classify errors from SDK operations (listTools, callTool, etc.) so
 * the status can be updated to reflect the auth failure instead of staying
 * silently green.
 *
 * Mirrors the MCP SDK's own 401-vs-403 handling: a 401 (or a typed OAuth
 * credential error) means re-auth; a bare 403 / "forbidden" is an authorization
 * or intermediary (gateway, proxy, VPN) rejection and is deliberately excluded.
 * Checks instanceof, then serialized `name` / `errorCode` so errors that crossed
 * the MCP-process IPC boundary and lost their prototype are still recognized.
 */
export function isAuthRelatedError(error: unknown): boolean {
	if (error instanceof UnauthorizedError) {
		return true;
	}
	if (
		error instanceof InvalidGrantError ||
		error instanceof InvalidClientError ||
		error instanceof UnauthorizedClientError ||
		error instanceof InvalidTokenError
	) {
		return true;
	}
	if (error instanceof OAuthError && isAuthRelatedOAuthErrorCode(error.errorCode)) {
		return true;
	}
	if (OAUTH_CREDENTIAL_ERROR_NAMES.has(getErrorName(error) ?? '')) {
		return true;
	}
	if (isAuthRelatedOAuthErrorCode(getOAuthErrorCode(error))) {
		return true;
	}
	// Spacelift-style RFC violation: expired refresh token reported as
	// `invalid_request` instead of `invalid_grant` (see oauth-errors.ts).
	if (isExpiredTokenInvalidRequestOAuthError(error)) {
		return true;
	}
	if (error instanceof Error) {
		const msg = error.message.toLowerCase();
		// Word-boundary match avoids false positives like "expected 4032 bytes".
		if (msg.includes('unauthorized') || /\b401\b/.test(msg)) {
			return true;
		}
		if (getErrorCode(error) === 401) {
			return true;
		}
	}
	return false;
}

export { isTimeoutErrorMessage };

/**
 * The SDK's SSE transport auto-reconnects on live-stream disconnects, so those
 * wrapper errors are benign unless they encode an HTTP status failure.
 */
export function isIgnorableSseError(error: Error): boolean {
	if (error.message.includes('SSE stream disconnected')) {
		return true;
	}
	if (!error.message.startsWith('SSE error:')) {
		return false;
	}
	if (extractHttpStatusCode(error) !== undefined) {
		return false;
	}
	return !error.message.includes('Maximum reconnection attempts');
}

/**
 * Check if an error indicates a terminated/invalid MCP session.
 * Handles both HTTP 404 (per MCP spec) and JSON-RPC session errors (e.g. -32000,
 * and -32001 "Session not found" as returned by some streamable HTTP servers).
 */
export function isSessionTerminatedError(error: unknown, serverType: string): boolean {
	// Only streamableHttp servers use session IDs
	if (serverType !== 'streamableHttp') {
		return false;
	}

	if (!(error instanceof Error)) {
		return false;
	}

	if (extractHttpStatusCode(error) === 404) {
		return true;
	}

	// StreamableHTTPError carries the HTTP status as a numeric .code property.
	// The MCP SDK can also surface plain Error objects with a numeric .code
	// (e.g. from transport internals) — treat those the same way.
	if (getErrorCode(error) === 404) {
		return true;
	}

	// Streamable HTTP transport may surface this when reconnects are exhausted
	// after a server-side session invalidation.
	if (error.message.includes('Maximum reconnection attempts')) {
		return true;
	}

	// After a server-side session invalidation, the SDK can also close the
	// underlying protocol and surface the in-flight operation failure as a
	// generic JSON-RPC connection-closed error instead of preserving the 404.
	if (error.message.includes('MCP error -32000: Connection closed')) {
		return true;
	}

	// Some servers return a JSON-RPC error instead of HTTP 404 for invalid sessions.
	return isJsonRpcSessionError(error.message);
}

/**
 * Check if an error message indicates an invalid session from JSON-RPC errors in the
 * MCP server-reserved range (commonly -32000; some servers use -32001 for "Session not found").
 * The MCP SDK formats these errors as "MCP error -32000: <message>".
 * We also check for raw JSON-RPC responses as a fallback.
 */
export function isJsonRpcSessionError(errorMessage: string): boolean {
	// The MCP SDK formats JSON-RPC errors as "MCP error <code>: <message>"
	// Match -32000 / -32001 with session-related message (see isSessionTerminatedError).
	const mcpErrorMatch = errorMessage.match(/MCP error -3200[01]:\s*(.+)/i);
	if (mcpErrorMatch) {
		const mcpMessage = mcpErrorMatch[1];
		if (/session/i.test(mcpMessage)) {
			return true;
		}
	}

	// Also check for raw JSON-RPC error in case some code paths include it
	const jsonMatch = errorMessage.match(/\{[\s\S]*"jsonrpc"[\s\S]*\}/);
	if (jsonMatch) {
		try {
			const jsonRpc = JSON.parse(jsonMatch[0]);
			const code = jsonRpc?.error?.code;
			if (
				(code === -32000 || code === -32001) &&
				typeof jsonRpc?.error?.message === 'string' &&
				/session/i.test(jsonRpc.error.message)
			) {
				return true;
			}
		} catch {
			// JSON parse failed, continue
		}
	}

	return false;
}

/**
 * Classify an MCP operation failure into a low-cardinality reason taxonomy.
 * This is intentionally conservative so tags remain stable and queryable.
 */
export function classifyMcpFailure(
	error: unknown,
	serverType?: string,
): McpFailureClassification {
	const message = error instanceof Error ? error.message : String(error);
	const retryableFromNetwork =
		error instanceof Error ? isRetryableNetworkError(error) : false;
	const timeout = isTimeoutErrorMessage(message);
	const retryable = retryableFromNetwork || timeout;

	if (error instanceof SiblingAlreadyRefreshedError) {
		return { reason: 'sibling_refreshed', retryable: true };
	}

	if (isOAuthRefreshTransientError(error)) {
		return { reason: 'network', retryable: true };
	}

	if (isAuthRelatedError(error)) {
		return { reason: 'auth', retryable: false };
	}

	if (serverType !== undefined && isSessionTerminatedError(error, serverType)) {
		return { reason: 'session_invalidated', retryable: true, httpStatus: 404 };
	}

	const httpStatus =
		error instanceof Error ? extractHttpStatusCode(error) : undefined;
	if (httpStatus !== undefined) {
		if (httpStatus >= 500) {
			return { reason: 'http_5xx', retryable, httpStatus };
		}
		if (httpStatus >= 400) {
			return { reason: 'http_4xx', retryable, httpStatus };
		}
	}

	if (timeout) {
		return { reason: 'timeout', retryable: true, httpStatus };
	}

	if (retryableFromNetwork) {
		return { reason: 'network', retryable: true, httpStatus };
	}

	return { reason: 'unknown', retryable, httpStatus };
}

/**
 * Decide whether an MCP failure should be visible in normal logs.
 * Retryable transport churn is expected during reconnect storms and should not
 * produce warn/error spam; persistent or auth failures still should.
 */
export function getMcpFailureLogAction(
	error: Error,
	serverType?: string,
	precomputedClassification?: McpFailureClassification,
): McpFailureLogAction {
	if (isIgnorableSseError(error) || isBenignSdkError(error)) {
		return 'suppress';
	}

	const classification = precomputedClassification ?? classifyMcpFailure(error, serverType);
	if (classification.reason === 'session_invalidated') {
		return 'warn';
	}
	return classification.retryable ? 'debug' : 'warn';
}

/**
 * Retryable connection state transitions should not be promoted to warn logs:
 * the higher-level state machine already records the reconnect lifecycle.
 */
export function shouldWarnOnConnectionEventForLogs(
	event: LoggedConnectionFailureEvent,
	exhausted: boolean,
): boolean {
	if (exhausted) {
		return true;
	}

	switch (event.kind) {
		case 'connect_failure':
		case 'transport_error':
			return !event.isRetryable;
		case 'transport_closed':
			return event.isStdio;
		case 'session_invalidated':
			return false;
		default: {
			const _exhaustive: never = event;
			return _exhaustive;
		}
	}
}

// Re-export for convenience
export { isRetryableNetworkError };
