import { type ChildProcess, execFile } from "node:child_process";
import type { SandboxDenyEvent } from "../sandbox.js";

/**
 * Interface for storing sandbox metadata associated with a child process.
 */
interface SandboxMetadata {
  /** The time when the sandboxed process was started */
  startTime: Date;
  /** The process ID of the sandboxed process */
  pid: number;
  /** Set of unrelated PIDs captured before/after execution (when debug output is enabled) */
  unrelatedPids?: Set<number>;
}

/**
 * WeakMap to store sandbox metadata for child processes without affecting the type.
 * Note: This is populated by the sandbox-helper binary wrapper, not by this module.
 */
const sandboxMetadataMap = new WeakMap<ChildProcess, SandboxMetadata>();

/**
 * Registers sandbox metadata for a child process.
 * Called by the sandbox helper to enable deny capture.
 */
export function registerSandboxMetadata(
  child: ChildProcess,
  metadata: SandboxMetadata
): void {
  sandboxMetadataMap.set(child, metadata);
}

/**
 * Captures sandbox denial logs for a sandboxed process.
 * Returns structured deny events.
 */
export async function captureSandboxDenies(
  child: ChildProcess
): Promise<SandboxDenyEvent[]> {
  const metadata = sandboxMetadataMap.get(child);

  if (!metadata) {
    console.log("No sandbox metadata found on child process");
    return [];
  }

  return captureSandboxDeniesInternal(
    metadata.pid,
    metadata.startTime,
    metadata.unrelatedPids
  );
}

/**
 * Determines the relationship of a process to the sandboxed process based on PID.
 */
function determineRelationship(
  eventPid: number,
  rootPid: number,
  unrelatedPids?: Set<number>
): "related" | "maybe_related" | "probably_unrelated" {
  if (eventPid === rootPid) {
    return "related";
  }
  if (unrelatedPids?.has(eventPid)) {
    return "probably_unrelated";
  }
  return "maybe_related";
}

function captureSandboxDeniesInternal(
  pid: number,
  startTime: Date,
  unrelatedPids?: Set<number>
): Promise<SandboxDenyEvent[]> {
  return new Promise(resolve => {
    try {
      // Calculate how long ago the process started (in seconds)
      const now = new Date();
      const secondsAgo = Math.ceil(
        (now.getTime() - startTime.getTime()) / 1000
      );

      // Use execFile instead of exec - split command and arguments
      // Remove PID filter to capture all sandbox events
      const logArgs = [
        "show",
        "--style",
        "ndjson",
        "--predicate",
        `process=="kernel" AND eventMessage CONTAINS "Sandbox:" AND eventMessage contains "deny"`,
        "--last",
        secondsAgo.toString(),
      ];

      execFile("/usr/bin/log", logArgs, (error, stdout, _stderr) => {
        // nosemgrep: detect-child-process
        if (error) {
          resolve([{ raw: error.message }]);
          return;
        }
        const lines = stdout.split(/\r?\n/).filter(l => l.trim().length > 0);
        const out: SandboxDenyEvent[] = [];
        for (const line of lines) {
          try {
            const obj = JSON.parse(line);
            const msg: string = obj?.eventMessage ?? "";
            if (!msg || typeof msg !== "string") continue;
            // Example deny: "Sandbox: zsh(79712) deny(1) mach-lookup com.apple.logd"
            const deny =
              /^Sandbox:\s+([^(]+)\((\d+)\)\s+([a-zA-Z-]+)\((\d+)\)\s+([^\s]+)\s+(.+)$/.exec(
                msg
              );
            if (deny) {
              const [
                ,
                processName,
                pidStr,
                decision,
                decisionCodeStr,
                operation,
                targetRest,
              ] = deny;
              const eventPid = Number(pidStr);
              out.push({
                timestamp: obj.timestamp,
                processName: processName.trim(),
                pid: eventPid,
                decision: decision.toLowerCase(),
                decisionCode: Number(decisionCodeStr),
                operation,
                target: targetRest,
                duplicateCount: 1,
                raw: msg,
                relationship: determineRelationship(
                  eventPid,
                  pid,
                  unrelatedPids
                ),
              });
              continue;
            }
            // Example duplicate: "1 duplicate report for Sandbox: zsh(95877) deny(1) file-read-data /usr/..."
            const dup = /^(\d+) duplicate report for Sandbox: (.+)$/.exec(msg);
            if (dup) {
              const count = Number(dup[1]);
              const inner = dup[2];
              const dm =
                /^([^(]+)\((\d+)\)\s+([a-zA-Z-]+)\((\d+)\)\s+([^\s]+)\s+(.+)$/.exec(
                  inner
                );
              if (dm) {
                const [
                  ,
                  processName,
                  pidStr,
                  decision,
                  decisionCodeStr,
                  operation,
                  targetRest,
                ] = dm;
                const eventPid = Number(pidStr);
                out.push({
                  timestamp: obj.timestamp,
                  processName: processName.trim(),
                  pid: eventPid,
                  decision: decision.toLowerCase(),
                  decisionCode: Number(decisionCodeStr),
                  operation,
                  target: targetRest,
                  duplicateCount: count,
                  raw: msg,
                  relationship: determineRelationship(
                    eventPid,
                    pid,
                    unrelatedPids
                  ),
                });
              } else {
                out.push({
                  timestamp: obj.timestamp,
                  duplicateCount: count,
                  raw: msg,
                });
              }
              continue;
            }
            // Fallback: emit raw
            out.push({ timestamp: obj.timestamp, raw: msg });
          } catch {}
        }
        resolve(out);
      });
    } catch (error) {
      resolve([{ raw: String(error) }]);
    }
  });
}
