/**
 * McpHostEnvironment — abstracts all VS Code host APIs used by the
 * cursor-mcp extension so they can be swapped for test doubles.
 *
 * ZERO vscode coupling: all types are defined here, not imported
 * from the vscode module.  This is construction-level drift protection —
 * the production VscodeHostEnvironment adapts vscode.* to these types,
 * and the TestHostEnvironment provides in-memory implementations with
 * JSON round-trip enforcement.
 */

import type { McpNetworkControlsConfig } from "./mcp-url-utils.js";

// ── Primitive types ─────────────────────────────────────────────────

export type FetchLike = (
	input: Request | URL | string,
	init?: RequestInit,
) => Promise<Response>;

export interface McpHttpFetchOptions {
	readonly identifier: string;
	readonly serverUrl: string;
}

export interface McpDisposable {
	dispose(): void;
}

export interface McpEventEmitter<T> extends McpDisposable {
	readonly event: (listener: (e: T) => void) => McpDisposable;
	fire(value: T): void;
}

export interface McpWorkspaceFolder {
	readonly name: string;
	readonly uri: { readonly fsPath: string; toString(): string };
}

// ── Storage types ───────────────────────────────────────────────────

export interface McpGlobalState {
	get<T>(key: string): T | undefined;
	update(key: string, value: unknown): Promise<void>;
	keys(): readonly string[];
	setIfAbsent?(key: string, value: string): Promise<boolean>;
}

export interface McpSecretStorage {
	get(key: string): Promise<string | undefined>;
	/** Read a legacy fallback key after the host has applied any migration tombstones. */
	getFallback?(key: string): Promise<string | undefined>;
	store(key: string, value: string): Promise<void>;
	delete(key: string): Promise<void>;
	/** Delete only from the host-local fallback store. */
	deleteFallback?(key: string): Promise<void>;
}

/** File-backed or in-memory persistence for `[oauth-attempt:*] mcp_oauth_attempt` records only. */
export interface McpOAuthAttemptStore {
	readAttempt(attemptId: string): Promise<unknown | undefined>;
	writeAttempt(attemptId: string, value: unknown): Promise<void>;
	deleteAttempt(attemptId: string): Promise<void>;
	listAttempts(): Promise<unknown[]>;
	sweepStaleAttempts(maxAgeMs: number): Promise<readonly string[]>;
}

export interface McpOAuthContext {
	readonly globalState: McpGlobalState;
	readonly secrets: McpSecretStorage;
	/** OAuth attempt payloads (PKCE + attempt-scoped client metadata); not used for other MCP OAuth keys. */
	readonly oauthAttempts: McpOAuthAttemptStore;
	/**
	 * When set (production host), used to read MCP OAuth dynamic configs such as
	 * attempt retention and backend Redis refresh lock rollout mode.
	 */
	readonly getDynamicConfigValue?: <T>(key: string) => Promise<T | undefined>;
	/**
	 * Atomic set-if-absent on the persistent disk KV store.
	 * Returns true if the value was set (key was absent), false if the key already existed.
	 * Used for cross-process locking (e.g. OAuth refresh lease).
	 */
	readonly diskKVSetIfAbsent?: (key: string, value: string) => Promise<boolean>;
	/**
	 * Atomically replace disk KV value when the current value still matches `expected`.
	 * Used to renew cross-process OAuth refresh locks without a delete/set gap.
	 */
	readonly diskKVReplaceIfEquals?: (key: string, expected: string, next: string) => Promise<boolean>;
	/**
	 * Delete a key from the persistent disk KV store.
	 * Used to release cross-process locks.
	 */
	readonly diskKVDelete?: (key: string, expectedValue?: string) => Promise<void>;
	/**
	 * Get a value from the persistent disk KV store.
	 */
	readonly diskKVGet?: (key: string) => Promise<string | undefined>;
}

// ── Snapshot types ──────────────────────────────────────────────────

export type McpSnapshotStatusType =
	| 'connected'
	| 'degraded'
	| 'disconnected'
	| 'error'
	| 'initializing'
	| 'needsAuth';

export interface McpSnapshotPush {
	serverIdentifier: string;
	serverName: string;
	status: McpSnapshotStatusType;
	statusDetail?: string;
	statusRetryable?: boolean;
	tools: Array<{ name: string; description?: string; inputSchema?: unknown; outputSchema?: unknown; title?: string; annotations?: Record<string, unknown>; _meta?: Record<string, unknown> }>;
	resources: Array<{ uri: string; name?: string; description?: string; mimeType?: string }>;
	prompts: Array<{ name: string; description?: string; arguments?: Array<{ name: string; description?: string; required?: boolean }> }>;
	instructions: string | undefined;
	snapshotEpoch: number;
	snapshotRevision: number;
}

// ── Dashboard shared OAuth (cursor account) ─────────────────────────

export interface McpSharedOAuthEntry {
	serverUrl: string;
	updatedAtMs: number;
	tokenData: {
		refreshToken?: string;
		accessToken?: string;
		clientId?: string;
		clientSecret?: string;
		redirectUris: string[];
	};
}

export interface McpSharedOAuthStoreArgs {
	serverUrl: string;
	tokenData: {
		refreshToken?: string;
		accessToken?: string;
		clientId?: string;
		clientSecret?: string;
		redirectUris?: string[];
	};
	clientTokenCreatedAtMs?: number;
}

export interface McpSharedOAuthStoreResult {
	updatedAtMs?: number;
	applied: boolean;
	skippedBecauseBackendNewer: boolean;
}

export type McpSharedOAuthStateChangeCause =
	| 'authenticate'
	| 'config_server_modified'
	| 'config_server_removed'
	| 'clear_all_tokens'
	| 'extension_server_unregistered'
	| 'manual_or_external'
	| 'oauth_storage_cleared'
	| 'server_removed'
	| 'team_server_removed_or_changed'
	| 'user_logout';

export type McpSharedOAuthStateChange =
	| 'client_info_saved'
	| 'tokens_saved'
	| 'cleared';

export type McpSharedOAuthTokenSaveKind = 'first' | 'refresh';

export interface McpSharedOAuthStateChangedArgs {
	serverUrl: string;
	identifier: string;
	sourceWorkspaceId?: string;
	change: McpSharedOAuthStateChange;
	cause?: McpSharedOAuthStateChangeCause;
	saveKind?: McpSharedOAuthTokenSaveKind;
}

export type McpSharedOAuthRefreshLockExecutorKind = 'localIde' | 'remoteExtensionHost';

export type McpSharedOAuthRefreshLockBeginOutcome =
	| 'skipped'
	| 'would_acquire'
	| 'would_wait'
	| 'redis_error';

export interface McpSharedOAuthRefreshLockBeginArgs {
	serverUrl: string;
	executorKind: McpSharedOAuthRefreshLockExecutorKind;
	executorId: string;
	observedUpdatedAtMs?: number;
}

export interface McpSharedOAuthRefreshLockBeginResult {
	outcome: McpSharedOAuthRefreshLockBeginOutcome;
	enforce: boolean;
	leaseHandle?: string;
}

export type McpSharedOAuthRefreshLockReleaseReason = 'complete' | 'error' | 'abandoned';

export interface McpSharedOAuthRefreshLockReleaseArgs {
	leaseHandle: string;
	reason: McpSharedOAuthRefreshLockReleaseReason;
}

export interface McpSharedOAuthApi {
	get(serverUrls: string[]): Promise<McpSharedOAuthEntry[]>;
	store(args: McpSharedOAuthStoreArgs): Promise<McpSharedOAuthStoreResult>;
	delete(serverUrl: string): Promise<void>;
	notifyStateChanged(args: McpSharedOAuthStateChangedArgs): Promise<void>;
	refreshLockBegin(args: McpSharedOAuthRefreshLockBeginArgs): Promise<McpSharedOAuthRefreshLockBeginResult>;
	refreshLockRelease(args: McpSharedOAuthRefreshLockReleaseArgs): Promise<void>;
}

// ── Host Environment ────────────────────────────────────────────────

export interface McpHostEnvironment {
	getWorkspaceFolders(): readonly McpWorkspaceFolder[];
	getAppRoot(): string;
	isGlass(): boolean;
	getSpawnEnv(): Record<string, string>;
	/**
	 * Host-provided fetch for shared lifecycle HTTP traffic. Preferred over
	 * `globalThis.fetch` so the MCP utility process can plug in Electron's
	 * `net.fetch` (system keychain) for corporate-CA-signed MCP servers.
	 */
	readonly fetch?: FetchLike;
	/**
	 * Build a fetch for a specific HTTP MCP server. Hosts can use the server
	 * identifier to recover the first subscribing window/workspace and apply the
	 * same proxy/auth/certificate policy that user-facing workbench network
	 * requests use. Returns `undefined` to fall back to {@link fetch}.
	 */
	createHttpFetch?(options: McpHttpFetchOptions): FetchLike | undefined;
	/**
	 * Whether this host process is attached to a remote workspace (e.g.
	 * SSH/WSL/Codespaces). Used by the lifecycle to gate features that
	 * only work locally, such as shared-process MCP transports.
	 */
	isRemote(): boolean;

	executeCommand<T>(command: string, ...args: unknown[]): Promise<T>;

	/** Dashboard shared OAuth; production uses vscode.cursor.mcpSharedOAuth (cursor-mcp only). */
	readonly mcpSharedOAuth: McpSharedOAuthApi;

	checkFeatureGate(gate: string): Promise<boolean>;
	getDynamicConfigValue<T>(key: string): Promise<T | undefined>;

	createEventEmitter<T>(): McpEventEmitter<T>;

	getOAuthContext(): McpOAuthContext;

	pushMcpSnapshots(snapshots: McpSnapshotPush[]): void;

	/**
	 * MCP Network Controls config for sandboxing local MCP subprocesses.
	 * When the returned config has `enabled: true`, stdio MCP servers are
	 * wrapped in cursorsandbox with network egress restricted to the
	 * effective allowlist.
	 */
	getMcpNetworkControlsConfig?(server?: {
		command?: string;
		url?: string;
	}): Promise<McpNetworkControlsConfig>;
}

// ── Reusable EventEmitter implementation ────────────────────────────

export class SimpleMcpEventEmitter<T> implements McpEventEmitter<T> {
	private readonly listeners = new Set<(value: T) => void>();

	readonly event = (listener: (value: T) => void): McpDisposable => {
		this.listeners.add(listener);
		return {
			dispose: () => {
				this.listeners.delete(listener);
			},
		};
	};

	fire(value: T): void {
		for (const listener of Array.from(this.listeners)) {
			listener(value);
		}
	}

	dispose(): void {
		this.listeners.clear();
	}
}
