import { SimpleControlledExecHandler } from "./controlled.js";
import { ExecutorResource } from "./remote.js";
import { createResource } from "./resource-provider.js";
import { createClientDeserializer, createClientSerializer, createServerDeserializer, createServerSerializer, } from "./serialization.js";
export const piLsExecutorResource = createResource(execManager => new ExecutorResource(execManager, createServerSerializer("piLsArgs"), createClientDeserializer("piLsResult")), (implementation, controlledExecManager) => {
    controlledExecManager.register(new SimpleControlledExecHandler(implementation, createServerDeserializer("piLsArgs"), createClientSerializer("piLsResult")));
});
