import { createValidationResult, isObject } from "./base.js";
import { validateBaseHookResponse } from "./baseHookResponse.js";
const isString = (value) => typeof value === "string";
export const validatePreCompactResponse = (value) => {
    // First validate base response
    const baseValidation = validateBaseHookResponse(value);
    if (!baseValidation.isValid) {
        return baseValidation;
    }
    // Empty object is valid
    if (value === undefined ||
        value === null ||
        Object.keys(value).length === 0) {
        return createValidationResult(true, []);
    }
    const errors = [];
    if (!isObject(value)) {
        errors.push("PreCompact response must be an object");
        return createValidationResult(false, errors);
    }
    const response = value;
    // Validate optional user_message field
    if (response.user_message !== undefined && !isString(response.user_message)) {
        errors.push("user_message must be a string");
    }
    return createValidationResult(errors.length === 0, errors);
};
