/**
 * Filters out ELECTRON_RUN_AS_NODE from the environment to prevent issues with dependencies like Cypress.
 * This environment variable is set by Electron/VSCode and can break tools that detect if they're
 * running under Node.js vs Electron (e.g., Cypress tests fail when this is set).
 *
 * @param env - The environment object to filter. If undefined, uses process.env
 * @returns A new environment object without ELECTRON_RUN_AS_NODE
 */
export function filterElectronEnv(env?: NodeJS.ProcessEnv): NodeJS.ProcessEnv {
  const sourceEnv = env || process.env;
  const { ELECTRON_RUN_AS_NODE, ...filteredEnv } = sourceEnv;
  return filteredEnv;
}

/**
 * Environment variables that reference host Unix-domain sockets or runtime
 * directories hidden by the Linux sandbox's mount isolation. Scrubbing these
 * prevents sandboxed tools from trying to connect to sockets that no longer
 * exist inside the mount namespace.
 */
const SOCKET_ENV_VARS_TO_SCRUB = [
  "SSH_AUTH_SOCK",
  "DBUS_SESSION_BUS_ADDRESS",
  "XDG_RUNTIME_DIR",
  "WAYLAND_DISPLAY",
] as const;

/**
 * Removes environment variables that reference host Unix-domain sockets or
 * runtime directories. Called before spawning sandboxed processes on Linux so
 * the child doesn't try to reach sockets hidden by mount isolation.
 */
export function scrubSocketEnvVars(env: NodeJS.ProcessEnv): NodeJS.ProcessEnv {
  const result = { ...env };
  for (const key of SOCKET_ENV_VARS_TO_SCRUB) {
    delete result[key];
  }
  return result;
}
