import { stat } from "node:fs/promises";
import { basename, extname, join, resolve } from "node:path";
import { debuglog } from "node:util";
import { translatePluginAgentsToSubagents } from "@anysphere/cursor-plugins";
import {
  CustomSubagent,
  CustomSubagentPermissionMode,
} from "@anysphere/proto/agent/v1/subagents_pb.js";
import { readText } from "@anysphere/utils";
import type { PluginsService } from "./plugins-service.js";
import { findFilesRecursive } from "./recursive-file-discovery.js";

const log = debuglog("local-subagents");

type SubagentSource = "workspace" | "user" | "plugin" | "claude";

export interface SubagentsService {
  getAllSubagents(): Promise<CustomSubagent[]>;
  /**
   * Reload subagents from disk and return them for convenience.
   * Call this when subagent files have changed.
   */
  reload(): Promise<CustomSubagent[]>;
}

export class NoopSubagentsService implements SubagentsService {
  async getAllSubagents(): Promise<CustomSubagent[]> {
    return [];
  }

  async reload(): Promise<CustomSubagent[]> {
    // No-op
    return [];
  }
}

export type ParsedSubagent = {
  name: string;
  description?: string;
  tools: string[];
  model?: string;
  forceDefaultModel: boolean;
  prompt: string;
  permissionMode: CustomSubagentPermissionMode;
  isBackground: boolean;
};

function parseReadonly(raw: string | undefined): CustomSubagentPermissionMode {
  const normalized = (raw ?? "").trim().toLowerCase();
  return normalized === "true"
    ? CustomSubagentPermissionMode.READONLY
    : CustomSubagentPermissionMode.DEFAULT;
}

function parseBoolean(raw: string | undefined): boolean {
  return (raw ?? "").trim().toLowerCase() === "true";
}

export function parseSubagentFile(content: string): ParsedSubagent | null {
  const frontmatterMatch = content.match(
    /^---\s*\n([\s\S]*?)\n---\s*\n?([\s\S]*)$/m
  );
  if (!frontmatterMatch) return null;

  const frontmatterText = frontmatterMatch[1] ?? "";
  const body = (frontmatterMatch[2] ?? "").trim();
  if (body.length === 0) return null;

  const frontmatter: Record<string, string> = {};
  for (const rawLine of frontmatterText.split("\n")) {
    const line = rawLine.trim();
    if (line.length === 0 || line.startsWith("#")) continue;
    const delimiterIndex = line.indexOf(":");
    if (delimiterIndex === -1) continue;
    const key = line.slice(0, delimiterIndex).trim().toLowerCase();
    const value = line.slice(delimiterIndex + 1).trim();
    if (key.length === 0) continue;
    frontmatter[key] = value;
  }

  const name = frontmatter.name ?? "";
  const description = frontmatter.description;
  const model = frontmatter.model;
  const forceDefaultModel = parseBoolean(frontmatter["force-default-model"]);
  const permissionMode = parseReadonly(frontmatter.readonly);
  const isBackground = parseBoolean(
    frontmatter.background ?? frontmatter.is_background
  );

  const toolsValue = frontmatter.tools;
  const tools =
    toolsValue !== undefined && toolsValue.length > 0
      ? toolsValue
          .split(",")
          .map(tool => tool.trim())
          .filter(tool => tool.length > 0)
      : [];

  return {
    name,
    description,
    tools,
    model,
    forceDefaultModel,
    prompt: body,
    permissionMode,
    isBackground,
  };
}

function isMarkdownFile(filename: string): boolean {
  const extension = extname(filename).toLowerCase();
  return (
    extension === ".md" || extension === ".mdc" || extension === ".markdown"
  );
}

export function deriveNameFromFilename(filename: string): string {
  const name = basename(filename, extname(filename));
  return name.replace(/[\s_]+/g, "-");
}

async function findSubagentFilesRecursive(
  rootDir: string,
  containmentRootDir?: string
): Promise<string[]> {
  return await findFilesRecursive({
    rootDir,
    includeFile: isMarkdownFile,
    containmentRootDir,
  });
}

/**
 * Loads subagents from the `.cursor/agents` directory in the workspace.
 * When thirdPartyExtensibilityEnabled is true, also loads from `.claude/agents` and `.codex/agents`.
 */
export class LocalSubagentsService implements SubagentsService {
  private subagents: Promise<CustomSubagent[]>;
  private readonly getThirdPartyExtensibilityEnabled: () => boolean;

  constructor(
    private readonly workspacePath: string,
    getThirdPartyExtensibilityEnabled?: () => boolean,
    private readonly cursorAgentsSource: "workspace" | "user" = "workspace",
    private readonly allowExternalAgentSymlinks: boolean = false
  ) {
    this.getThirdPartyExtensibilityEnabled =
      getThirdPartyExtensibilityEnabled ?? ((): boolean => true);
    this.subagents = this.load().catch(err => {
      log("Failed to load subagents: %o", err);
      return [];
    });
  }

  async getAllSubagents(): Promise<CustomSubagent[]> {
    return this.subagents;
  }

  async reload(): Promise<CustomSubagent[]> {
    this.subagents = this.load().catch(err => {
      log("Failed to load subagents: %o", err);
      return [];
    });
    return await this.subagents;
  }

  private computeAgentsDirs(): Array<{
    dirPath: string;
    source: SubagentSource;
  }> {
    const workspaceRoot = resolve(this.workspacePath);
    const dirs: Array<{ dirPath: string; source: SubagentSource }> = [
      {
        dirPath: join(workspaceRoot, ".cursor", "agents"),
        source: this.cursorAgentsSource,
      },
    ];

    // Only include .claude/agents when third-party extensibility is enabled
    if (this.getThirdPartyExtensibilityEnabled()) {
      dirs.push({
        dirPath: join(workspaceRoot, ".claude", "agents"),
        source: "claude",
      });
    }

    return dirs;
  }

  private async load(): Promise<CustomSubagent[]> {
    const agentsDirs = this.computeAgentsDirs();
    const subagents: CustomSubagent[] = [];

    for (const { dirPath: agentsDir, source } of agentsDirs) {
      const subagentFiles = await findSubagentFilesRecursive(
        agentsDir,
        this.allowExternalAgentSymlinks ? undefined : this.workspacePath
      );
      for (const fullPath of subagentFiles) {
        const filename = basename(fullPath);
        try {
          const fileStat = await stat(fullPath);
          if (!fileStat.isFile()) continue;
        } catch (error) {
          log(
            "Skipping subagent file %s due to stat error: %o",
            fullPath,
            error
          );
          continue;
        }

        try {
          const content = await readText(fullPath);
          const parsed = parseSubagentFile(content);
          if (!parsed) continue;

          subagents.push(
            new CustomSubagent({
              fullPath,
              name: parsed.name || deriveNameFromFilename(filename),
              description: parsed.description ?? "",
              tools: parsed.tools,
              model: parsed.model ?? "inherit",
              forceDefaultModel: parsed.forceDefaultModel,
              prompt: parsed.prompt,
              permissionMode: parsed.permissionMode,
              isBackground: parsed.isBackground,
              source,
            })
          );
        } catch (error) {
          log("Failed to parse subagent file %s: %o", fullPath, error);
        }
      }
    }

    return subagents;
  }
}

/** Subagent names to exclude when loading from Claude Code directories and plugins. */
const EXCLUDED_SUBAGENT_NAMES = new Set(["claude-code-tutor"]);

export class MergedSubagentsService implements SubagentsService {
  constructor(private readonly subagentsServices: SubagentsService[]) {}

  async getAllSubagents(): Promise<CustomSubagent[]> {
    const allSubagents = await Promise.all(
      this.subagentsServices.map(service =>
        service.getAllSubagents().catch(err => {
          log("Failed to load subagents from merged service: %o", err);
          return [];
        })
      )
    );

    // Dedupe by name - first occurrence wins (Cursor sources are processed first)
    // This ensures that when the same subagent exists in both .cursor and .claude directories,
    // the Cursor version takes precedence
    const deduped = new Map<string, CustomSubagent>();
    for (const subagents of allSubagents) {
      for (const subagent of subagents) {
        if (EXCLUDED_SUBAGENT_NAMES.has(subagent.name)) {
          continue;
        }
        if (!deduped.has(subagent.name)) {
          deduped.set(subagent.name, subagent);
        }
      }
    }

    const result = Array.from(deduped.values());
    return result;
  }

  async reload(): Promise<CustomSubagent[]> {
    await Promise.all(this.subagentsServices.map(service => service.reload()));
    return this.getAllSubagents();
  }
}

// ============================================================================
// Cursor Plugins Subagents Service
// ============================================================================

/**
 * Settings for importing Cursor plugins subagents.
 */
export interface CursorPluginsSubagentsSettings {
  /** Whether to import agents from Claude Code and other third-party plugins */
  importThirdPartyPlugins: boolean;
}

/**
 * Service that loads subagents from installed Cursor plugins.
 * These are agents defined in the "agents" directory of plugins at ~/.cursor/plugins/
 *
 * Plugin loading runs in the background. getAllSubagents returns immediately
 * with the current cache (initially []); when the load completes we update the
 * cache. reload() kicks off a fresh load and awaits it so callers can ensure
 * plugin subagents are ready (e.g. after import).
 */
export class CursorPluginsSubagentsService implements SubagentsService {
  private _subagentsCache: CustomSubagent[] = [];
  private _loadId = 0;
  private _loadPromise: Promise<void> | null = null;
  private _loadedOnce = false;

  constructor(
    private readonly getSettings: () => CursorPluginsSubagentsSettings,
    private readonly pluginsService: PluginsService
  ) {
    this.runLoadInBackground();
  }

  async getAllSubagents(): Promise<CustomSubagent[]> {
    if (this._loadPromise) {
      await this._loadPromise;
    }
    if (!this._loadedOnce) {
      await this.reload();
    }
    return [...this._subagentsCache];
  }

  async reload(): Promise<CustomSubagent[]> {
    this.runLoadInBackground(true);
    if (this._loadPromise) await this._loadPromise;
    return this._subagentsCache;
  }

  /**
   * Run plugin load in background. When complete, update cache.
   * Uses _loadId so stale completions (e.g. after reload) are ignored.
   */
  private runLoadInBackground(reloadPlugins: boolean = false): void {
    const loadId = ++this._loadId;

    this._loadPromise = this.load(reloadPlugins)
      .then(result => {
        if (loadId !== this._loadId) return;
        this._subagentsCache = result;
        this._loadedOnce = true;
      })
      .catch(err => {
        if (loadId !== this._loadId) return;
        log("Failed to load Cursor plugin subagents: %o", err);
        this._subagentsCache = [];
        this._loadedOnce = true;
      })
      .finally(() => {
        if (loadId === this._loadId) {
          this._loadPromise = null;
        }
      });
  }

  dispose(): void {
    // No resources to clean up currently, but method should exist for consistency
  }

  private async load(reloadPlugins: boolean): Promise<CustomSubagent[]> {
    const subagents: CustomSubagent[] = [];

    try {
      let plugins = reloadPlugins
        ? await this.pluginsService.reload()
        : await this.pluginsService.getAllEnabledPlugins();

      // When importThirdPartyPlugins is off, exclude any primitives from Claude Code plugins.
      const settings = this.getSettings();
      if (!settings.importThirdPartyPlugins) {
        plugins = plugins.filter(p => p.identifier.source !== "claude-plugin");
      }

      const translated = translatePluginAgentsToSubagents(plugins, {
        stripModel: true,
        stripTools: true,
      });

      for (const s of translated) {
        const permissionMode =
          s.permissionMode === "readonly"
            ? CustomSubagentPermissionMode.READONLY
            : CustomSubagentPermissionMode.DEFAULT;
        subagents.push(
          new CustomSubagent({
            name: s.name,
            description: s.description,
            tools: [],
            model: "inherit",
            prompt: s.prompt,
            fullPath: s.fullPath,
            permissionMode,
            plugin: s.plugin,
            marketplace: s.marketplace,
            pluginId: s.pluginId,
            marketplaceId: s.marketplaceId,
            source: "plugin",
          })
        );
      }
    } catch {
      // Failed to load plugins
    }

    return subagents;
  }
}
