type PathModule = Pick<
  typeof path,
  "isAbsolute" | "normalize" | "parse" | "relative" | "resolve" | "sep"
>;

type PermissionsPathResolver = typeof resolvePermissionsPath;

type TempPathEnvironment = Record<string, string | undefined>;

interface TempPathOptions {
  platform: NodeJS.Platform;
  env: TempPathEnvironment;
  pathModule: PathModule;
  homeDirectory?: string;
}

type RedirectTarget =
  | "original-stdin"
  | "original-stdout"
  | "original-stderr"
  | "dev-null"
  | "workspace-file"
  | "tmp-file"
  | "unsafe";

interface RedirectClassificationState {
  fdTargets: Map<number, RedirectTarget>;
}

function ignoreResolutionBlockMessage(
  action: "Read" | "Command",
  targetDescription: string,
  path: string
): string {
  return `${action} blocked: cannot verify ${targetDescription} \`${path}\` while resolving symlinks. This can happen when access is denied or the path contains a symlink loop.`;
}

function deduplicateStrings(arr: string[]): string[] {
  return [...new Set(arr)];
}

function createRedirectClassificationState(): RedirectClassificationState {
  return {
    fdTargets: new Map<number, RedirectTarget>([
      [0, "original-stdin"],
      [1, "original-stdout"],
      [2, "original-stderr"],
    ]),
  };
}

function isAllowlistSafeOutputTarget(
  target: RedirectTarget | undefined
): target is
  | "original-stdout"
  | "original-stderr"
  | "dev-null"
  | "workspace-file"
  | "tmp-file" {
  return (
    target === "original-stdout" ||
    target === "original-stderr" ||
    target === "dev-null" ||
    target === "workspace-file" ||
    target === "tmp-file"
  );
}

/**
 * Whether `realAbsolutePath` is the workspace root itself or a descendant of
 * it. Both paths must already be resolved (symlinks resolved, absolute).
 *
 * The descendant check compares against a root prefix that ends in exactly one
 * path separator so that a sibling whose name merely shares a string prefix
 * with the root (e.g. `/ws/project.txt` or `/ws/project_other/file`) is NOT
 * treated as inside `/ws/project`. Omitting the separator here is a
 * path-containment bypass.
 *
 * Filesystem roots already end with the separator (`/` on POSIX, `C:\` on
 * Windows). Appending another would produce `//` or `C:\\` and misclassify
 * every legitimate descendant as out-of-workspace — so we only append when
 * the root does not already end with `sep`.
 *
 * On case-insensitive file systems (Windows, macOS) the comparison is
 * case-insensitive.
 */
export function isPathInsideWorkspaceRoot(
  realAbsolutePath: string,
  realRootDirectory: string
): boolean {
  const isCaseInsensitiveFs =
    process.platform === "win32" || process.platform === "darwin";
  const target = isCaseInsensitiveFs
    ? realAbsolutePath.toLowerCase()
    : realAbsolutePath;
  const root = isCaseInsensitiveFs
    ? realRootDirectory.toLowerCase()
    : realRootDirectory;
  if (target === root) {
    return true;
  }
  const rootPrefix = root.endsWith(sep) ? root : root + sep;
  return target.startsWith(rootPrefix);
}

function isPathWithinRootUsingPathModule({
  basePath,
  targetPath,
  pathModule,
}: {
  basePath: string;
  targetPath: string;
  pathModule: PathModule;
}): boolean {
  const resolvedBase = pathModule.resolve(basePath);
  const resolvedTarget = pathModule.resolve(targetPath);
  const relativePath = pathModule.relative(resolvedBase, resolvedTarget);
  return (
    relativePath === "" ||
    (relativePath !== ".." &&
      !relativePath.startsWith(`..${pathModule.sep}`) &&
      !pathModule.isAbsolute(relativePath))
  );
}

function isOutputFileRedirectOperator(operator: string): boolean {
  return (
    operator === ">" ||
    operator === ">>" ||
    operator === ">|" ||
    operator === "&>" ||
    operator === "&>>"
  );
}

/**
 * Whether a redirect could create or modify a file, i.e. turn an otherwise
 * read-only allowlisted command into an arbitrary-write vector.
 *
 * Only a plain stdin file/fd read (`<`, `<&`) is treated as guaranteed
 * non-writing. Everything else — output redirects (`>`, `>>`, `&>`), the
 * read-write `<>`, fd duplications toward a file (`>&`), and here-docs /
 * here-strings — is treated conservatively as write-capable. That
 * conservatism does not over-block the common safe cases (`cmd 2>&1`, a
 * here-doc feeding a parsed command, `cmd > /dev/null`, or a workspace/temp target),
 * because those are already cleared by the allowlist-safe and workspace-safe
 * checks in `hasUnsafeWriteRedirect` before this predicate is consulted.
 */
function redirectCanWriteFile(redirect: { operator: string }): boolean {
  return redirect.operator !== "<" && redirect.operator !== "<&";
}

/**
 * Whether the command carries a redirect that could write to an unsafe target,
 * making its invocation not an allowlist match. A redirect set is safe when it
 * is empty, when every target is allowlist-safe (original stdout/stderr,
 * /dev/null, or a parser-approved here-doc), when every target
 * resolves inside the workspace/temp dirs, or when every redirect is a plain
 * stdin read (`<`, `<&`, which cannot write). A here-doc/here-string feeding a
 * command the parser did not mark safe, or an empty redirect list on a command
 * that nonetheless reports `hasRedirects` (e.g. a redirect attached to a shell
 * builtin the parser does not surface), is treated conservatively as unsafe.
 */
function hasUnsafeWriteRedirect({
  parsingResult,
  hasRedirects,
  parsingFailed,
  allRedirectsAreAllowlistSafe,
  allRedirectsAreWorkspaceFileSafe,
}: {
  parsingResult: ShellCommandParsingResult;
  hasRedirects: boolean;
  parsingFailed: boolean;
  allRedirectsAreAllowlistSafe: boolean;
  allRedirectsAreWorkspaceFileSafe: boolean;
}): boolean {
  // A parse failure is handled by the existing parser-bypass / smart-allowlist
  // paths; do not additionally treat it as an unsafe redirect here.
  if (
    !hasRedirects ||
    parsingFailed ||
    allRedirectsAreAllowlistSafe ||
    allRedirectsAreWorkspaceFileSafe
  ) {
    return false;
  }
  // Parsed successfully but the redirect could not be attributed to a static
  // target (e.g. a redirect on a shell builtin the parser does not surface).
  // Treat that conservatively as an unsafe write.
  if (parsingResult.redirects.length === 0) {
    return true;
  }
  return parsingResult.redirects.some(redirectCanWriteFile);
}

function parseRedirectFd(targetText: string | undefined): number | undefined {
  if (targetText === undefined || targetText.trim() !== targetText) {
    return undefined;
  }
  const fd = Number(targetText);
  return Number.isInteger(fd) && fd >= 0 ? fd : undefined;
}

function isAllowlistSafeHeredocRedirect(redirect: {
  operator: string;
  destinationFds: readonly unknown[];
  targetNodeType: string;
  targetText?: string;
}): boolean {
  // `targetText` carries the receiver command name and is only populated when
  // the parser attributed the heredoc to a directly-parsed command and marked
  // it allowlist-safe (see `classifyHeredocRedirect` in shell-parser.ts). The
  // receiver command itself still has to match the allowlist to autorun.
  return (
    redirect.operator === "<<" &&
    redirect.targetNodeType === "heredoc_redirect" &&
    redirect.destinationFds.length === 1 &&
    Number(redirect.destinationFds[0]) === 0 &&
    redirect.targetText !== undefined
  );
}

async function classifyRedirectPathTarget({
  targetText,
  workingDirectory,
  rootDirectories,
  allowTmpRedirects,
  resolvePathForPermissions,
  pathModule,
  tempPathOptions,
}: {
  targetText: string;
  workingDirectory: string;
  rootDirectories: string[];
  allowTmpRedirects: boolean;
  resolvePathForPermissions: PermissionsPathResolver;
  pathModule: PathModule;
  tempPathOptions: TempPathOptions;
}): Promise<"workspace-file" | "tmp-file" | undefined> {
  const parsedTarget = pathModule.parse(targetText);
  if (parsedTarget.root !== "" && !pathModule.isAbsolute(targetText)) {
    return undefined;
  }

  const targetPermPath = await resolvePathForPermissions(
    targetText,
    workingDirectory
  );
  if (!isResolutionSafe(targetPermPath.resolution)) {
    return undefined;
  }

  for (const rootDirectory of rootDirectories) {
    const rootPermPath = await resolvePathForPermissions(rootDirectory);
    if (!isResolutionSafe(rootPermPath.resolution)) {
      continue;
    }
    if (
      isPathWithinRootUsingPathModule({
        basePath: rootPermPath.resolvedPath,
        targetPath: targetPermPath.resolvedPath,
        pathModule,
      })
    ) {
      return "workspace-file";
    }
  }

  return allowTmpRedirects &&
    isAllowedTmpPathWithOptions(targetPermPath.resolvedPath, tempPathOptions)
    ? "tmp-file"
    : undefined;
}

export async function areShellRedirectsAllowlistSafeForWorkspace({
  parsingResult,
  workingDirectory,
  rootDirectories,
  allowTmpRedirects = true,
  resolvePathForPermissions = resolvePermissionsPath,
  pathModule = path,
  tempPathOptions = {
    platform: process.platform,
    env: process.env,
    pathModule,
    homeDirectory: homedir(),
  },
}: {
  parsingResult: ShellCommandParsingResult;
  workingDirectory: string;
  rootDirectories: string[];
  /** Host-temp writes can only be safe when the effective sandbox permits them. */
  allowTmpRedirects?: boolean;
  resolvePathForPermissions?: PermissionsPathResolver;
  pathModule?: PathModule;
  tempPathOptions?: TempPathOptions;
}): Promise<boolean> {
  if (!parsingResult.hasRedirects) {
    return true;
  }

  const redirects = parsingResult.redirects;
  if (redirects.length === 0) {
    return false;
  }

  // Redirect metadata is flat and does not expose command boundaries. The
  // parser classifies fd state per command, so multi-command sequences must not
  // let an earlier redirect make a later redirect appear safe.
  const shouldResetRedirectStateForEveryRedirect =
    parsingResult.executableCommands.length > 1;
  const commandRedirectState = createRedirectClassificationState();
  for (const redirect of redirects) {
    if (isAllowlistSafeHeredocRedirect(redirect)) {
      continue;
    }

    const state = shouldResetRedirectStateForEveryRedirect
      ? createRedirectClassificationState()
      : commandRedirectState;
    const { operator, targetText } = redirect;
    const destinationFds = redirect.destinationFds.map(fd => Number(fd));

    if (operator === ">&") {
      const sourceFd = parseRedirectFd(targetText);
      const sourceTarget =
        sourceFd === undefined ? undefined : state.fdTargets.get(sourceFd);
      if (!isAllowlistSafeOutputTarget(sourceTarget)) {
        for (const fd of destinationFds) {
          state.fdTargets.set(fd, "unsafe");
        }
        return false;
      }
      for (const fd of destinationFds) {
        state.fdTargets.set(fd, sourceTarget);
      }
      continue;
    }

    if (operator === "<&") {
      const sourceFd = parseRedirectFd(targetText);
      const sourceTarget =
        sourceFd === undefined ? undefined : state.fdTargets.get(sourceFd);
      if (sourceTarget !== "dev-null") {
        for (const fd of destinationFds) {
          state.fdTargets.set(fd, "unsafe");
        }
        return false;
      }
      for (const fd of destinationFds) {
        state.fdTargets.set(fd, sourceTarget);
      }
      continue;
    }

    if (targetText === "/dev/null") {
      for (const fd of destinationFds) {
        state.fdTargets.set(fd, "dev-null");
      }
      continue;
    }

    if (!isOutputFileRedirectOperator(operator) || targetText === undefined) {
      for (const fd of destinationFds) {
        state.fdTargets.set(fd, "unsafe");
      }
      return false;
    }

    const redirectTarget = await classifyRedirectPathTarget({
      targetText,
      workingDirectory,
      rootDirectories,
      allowTmpRedirects,
      resolvePathForPermissions,
      pathModule,
      tempPathOptions,
    });
    if (!redirectTarget) {
      for (const fd of destinationFds) {
        state.fdTargets.set(fd, "unsafe");
      }
      return false;
    }
    for (const fd of destinationFds) {
      state.fdTargets.set(fd, redirectTarget);
    }
  }

  return true;
}

/**
 * Generate allowlist candidate strings for a command, producing a "ladder" of
 * progressively more specific allowlist entries.
 *
 * This function is classifier-driven: `subcommandTokens` is the authoritative,
 * ordered list of non-flag subcommand keywords (e.g., `["autoscaling",
 * "describe-auto-scaling-groups"]`). The classifier produces it semantically,
 * so it works regardless of flag placement (leading `--region`, trailing
 * `--output`, interleaved, etc.) and correctly returns `[]` for commands
 * without real subcommands (`rg`, `cat`, `ls`, `grep`, `curl`, ...).
 *
 * The ladder is always: `[name, name+t1, name+t1+t2, ..., name+all-args]`.
 * If the full command already equals the deepest ladder rung, it is not
 * duplicated.
 *
 * Call sites currently only reach this function when the smart allowlist is
 * active and the classifier successfully ran, so `subcommandTokens` is a
 * trustworthy input. There is intentionally no heuristic fallback here — if
 * the classifier returns `[]`, we trust it and produce just
 * `[name, fullCommand]`.
 */
export function generateAllowlistCandidatesFromCommandText(command: {
  name: string;
  arguments: string[];
  subcommandTokens: string[];
}): string[] {
  const commandName = command.name.trim();
  if (!commandName) {
    return [];
  }
  if (isTerminalShellInterpreterAllowlistCandidate(commandName)) {
    return [];
  }

  const subcommandTokens = command.subcommandTokens
    .map(token => token.trim())
    .filter(Boolean);
  const argumentsList = command.arguments
    .map(arg => arg.trim())
    .filter(Boolean);

  const candidates: string[] = [commandName];
  const ladder = [commandName];
  for (const token of subcommandTokens) {
    ladder.push(token);
    candidates.push(ladder.join(" "));
  }

  // Bottom rung of the ladder: the full command as the user ran it. For
  // commands without subcommands (e.g., `cat file1.txt file2.txt`) this is
  // the only rung beyond the base name, which is the desired behavior.
  // Appended last so the UI renders it below the subcommand ladder rungs.
  const fullCommand = [commandName, ...argumentsList].join(" ");
  if (!candidates.includes(fullCommand)) {
    candidates.push(fullCommand);
  }

  return normalizeAllowlistCandidates(candidates);
}

/**
 * Trim, drop empties, and dedupe while preserving insertion order. Callers are
 * responsible for building `values` in the order they want to present it to
 * the user: the allowlist ladder must keep the natural `[base, base+t1, ...,
 * full]` order so the full command appears below the subcommand rungs, even
 * when the full command starts with a flag that would otherwise sort above
 * the subcommand entries alphabetically.
 */
function normalizeAllowlistCandidates(values: string[]): string[] {
  return deduplicateStrings(values.map(value => value.trim()).filter(Boolean));
}

/**
 * Build the list of command strings that should be tried against user
 * allowlist / command blocklist entries for a single classifier command.
 *
 * Always includes the RAW form (`name + arguments.join(" ")`) — this is the
 * pre-smart-allowlist-v2 behavior and is what colon-syntax entries like
 * `Shell(npm:install*)` rely on matching when there are no leading flags.
 *
 * When the classifier provided a non-empty `subcommandTokens`, also includes
 * a CANONICAL form (`name + subcommandTokens.join(" ")`). This is the exact
 * string shape the suggestion ladder offers the user, so matching against it
 * makes allowlist entries like `Shell(aws autoscaling describe-auto-scaling-groups)`
 * auto-approve flag-interleaved invocations like
 * `aws --region us-east-1 autoscaling describe-auto-scaling-groups --output json`,
 * where the raw-form prefix check would fail because the command starts with
 * `"aws --region"` instead of `"aws autoscaling"`.
 *
 * This helper is ONLY consumed from the smart-allowlist code path where a
 * classifier result is available. Tree-sitter and other non-classifier paths
 * continue to call `matchesShell(entry, rawCommandText)` directly and are
 * unaffected.
 *
 * Design properties:
 *   - Strictly additive: the raw form is always tried, so no previously
 *     matching command stops matching after this change.
 *   - Classifier-grounded: we only expand the match surface using tokens the
 *     classifier explicitly labeled as subcommands, not any token that happens
 *     to appear in the command. This avoids the over-permissive
 *     `Shell(docker rm)` vs `docker ps rm` trap that a naive set-containment
 *     match would hit — if the classifier says the subcommand is `ps`, the
 *     canonical form is `"docker ps"` and the `docker rm` entry won't match.
 *   - Collapses cleanly: when `subcommandTokens` is empty (`ls`, `cat`, `rg`),
 *     or when the canonical form is identical to the raw form, we emit a
 *     single form and behave identically to the pre-fix code path.
 */
export function classifierCommandMatchForms(command: {
  name: string;
  arguments: string[];
  subcommandTokens: string[];
}): string[] {
  const name = command.name.trim();
  if (!name) return [];

  const args = command.arguments.map(arg => arg.trim()).filter(Boolean);
  const raw = args.length > 0 ? `${name} ${args.join(" ")}` : name;

  const subcommandTokens = command.subcommandTokens
    .map(token => token.trim())
    .filter(Boolean);
  if (subcommandTokens.length === 0) {
    return [raw];
  }

  const canonical = `${name} ${subcommandTokens.join(" ")}`;
  if (canonical === raw) {
    return [raw];
  }
  return [raw, canonical];
}

function commandMatchesBlocklistEntry(
  matchForms: string[],
  blocklistEntry: string
): boolean {
  const normalizedEntry = blocklistEntry.trim();
  if (!normalizedEntry) return false;

  return matchForms.some(
    form => form === normalizedEntry || form.startsWith(`${normalizedEntry} `)
  );
}

function classifierCommandToExecutableCommand(
  command: NonNullable<CommandClassifierResult["commands"]>[number]
): ShellCommandParsingResult_ExecutableCommand {
  const name = command.name.trim();
  const args = command.arguments
    .map(value => value.trim())
    .filter(Boolean)
    .map(
      value =>
        new ShellCommandParsingResult_ExecutableCommandArg({
          type: "word",
          value,
        })
    );

  return new ShellCommandParsingResult_ExecutableCommand({
    name,
    args,
    fullText: [name, ...args.map(arg => arg.value)].join(" ").trim(),
  });
}

/** Type-safe constructor for SandboxedPolicy (avoids `as` casts on object literals). */
function makeSandboxedPolicy(
  type: SandboxedPolicy["type"],
  overrides: Partial<Omit<SandboxedPolicy, "type">> = {}
): SandboxedPolicy {
  return { type, ...overrides } as SandboxedPolicy;
}

/**
 * Workspace allowlist contribution for a single policy source.
 * Missing paths means "no opinion"; an explicit empty array means
 * "nothing beyond the workspace".
 */
function workspaceReadPathsSource(
  readBoundary: SandboxReadBoundary | undefined,
  additionalReadPaths: string[] | undefined
): string[] | undefined {
  if (readBoundary !== "workspace" || additionalReadPaths === undefined) {
    return undefined;
  }
  return additionalReadPaths;
}

/**
 * Apply the user's Agent Read Access as a floor on a model-requested policy.
 *
 * The agent typically requests workspace_readwrite without readBoundary; without
 * this clamp the helper defaults to System and ignores the UI setting.
 * Workspace also carries the user's read allowlist as additionalReadPaths.
 */
function applyUserReadBoundaryFloor({
  requestedPolicy,
  userConfiguredPolicy,
}: {
  requestedPolicy: InternalSandboxPolicy;
  userConfiguredPolicy: InternalSandboxPolicy;
}): InternalSandboxPolicy {
  if (
    requestedPolicy.type === "insecure_none" ||
    userConfiguredPolicy.type === "insecure_none"
  ) {
    return requestedPolicy;
  }

  const readBoundary = mergeReadBoundary(
    requestedPolicy.readBoundary,
    userConfiguredPolicy.readBoundary
  );
  const additionalReadPaths =
    readBoundary === "workspace"
      ? mergeAdditionalReadPaths(
          workspaceReadPathsSource(
            requestedPolicy.readBoundary,
            requestedPolicy.additionalReadPaths
          ),
          workspaceReadPathsSource(
            userConfiguredPolicy.readBoundary,
            userConfiguredPolicy.additionalReadPaths
          )
        )
      : undefined;

  return {
    ...requestedPolicy,
    readBoundary,
    additionalReadPaths,
  };
}

const READ_BOUNDARY_STRICTNESS: Record<SandboxReadBoundary, number> = {
  workspace: 0,
  system: 1,
};

// ============================================================================
// Shell Entry Parsing
// ============================================================================

/**
 * Parsed result of a shell allowlist/denylist entry.
 * Entry format: "Shell(pattern)" or "Bash(pattern)" where pattern can be:
 *   - Simple command: "git", "npm", "echo"
 *   - Command with subcommand: "git status", "npm run"
 *   - Command with args pattern: "curl:*", "echo:hello*" (colon separates command from args glob)
 */
export interface ParsedShellEntry {
  /** The shell type: "Shell" or "Bash" */
  shellType: "Shell" | "Bash";
  /** The full pattern inside parentheses (e.g., "git status", "curl:*") */
  fullPattern: string;
  /** The command/subcommand part (before colon if present, otherwise full pattern) */
  commandPattern: string;
  /** The args glob pattern (after colon), or null if no colon syntax */
  argsPattern: string | null;
}

/**
 * Parse a shell allowlist/denylist entry into its components.
 * Returns null if the entry is not a valid shell entry.
 *
 * @example
 * parseShellEntry("Shell(git)") // { shellType: "Shell", fullPattern: "git", commandPattern: "git", argsPattern: null }
 * parseShellEntry("Shell(git status)") // { shellType: "Shell", fullPattern: "git status", commandPattern: "git status", argsPattern: null }
 * parseShellEntry("Shell(curl:*)") // { shellType: "Shell", fullPattern: "curl:*", commandPattern: "curl", argsPattern: "*" }
 * parseShellEntry("Bash(echo:hello*)") // { shellType: "Bash", fullPattern: "echo:hello*", commandPattern: "echo", argsPattern: "hello*" }
 * parseShellEntry("invalid") // null
 */
export function parseShellEntry(entry: string): ParsedShellEntry | null {
  const match = entry.match(/^\s*(Shell|Bash)\s*\((.*)\)\s*$/);
  if (!match) return null;

  const shellType = match[1] as "Shell" | "Bash";
  const fullPattern = match[2]?.trim() ?? "";

  // Check for colon syntax: "cmd:argsPattern"
  const colonIdx = fullPattern.indexOf(":");
  if (colonIdx !== -1) {
    return {
      shellType,
      fullPattern,
      commandPattern: fullPattern.slice(0, colonIdx).trim(),
      argsPattern: fullPattern.slice(colonIdx + 1).trim(),
    };
  }

  return {
    shellType,
    fullPattern,
    commandPattern: fullPattern,
    argsPattern: null,
  };
}

/**
 * Check if a path is in an allowed tmp directory.
 * These paths match what the sandbox allows (see packages/sandbox-helper).
 *
 * - macOS: /tmp/, /private/tmp/, /var/folders/, /private/var/folders/ (excludes /var/tmp/)
 * - Linux: /tmp/, /private/tmp/, /var/folders/, /private/var/folders/, /var/tmp/
 * - Windows: reads from TEMP/TMP environment variables (normalized to handle forward slashes)
 *
 * On Unix, the user home is excluded even when it is nested under one of these
 * roots. Sandboxed and hermetic environments commonly place HOME under /tmp,
 * but home-relative configuration must retain out-of-workspace protections.
 * Windows uses its explicit TEMP/TMP directory even when that directory is
 * nested under the user profile.
 */
function isAllowedTmpPathWithOptions(
  realAbsolutePath: string,
  { platform, env, pathModule, homeDirectory }: TempPathOptions
): boolean {
  if (platform === "win32") {
    // Windows: check TEMP and TMP env vars (matches win32/allow.rs in sandbox-helper)
    const tempEnv = env.TEMP ?? env.TMP;
    if (tempEnv) {
      // Normalize the path to convert forward slashes to backslashes on Windows
      const normalizedTempEnv = pathModule.normalize(tempEnv);
      // Windows paths are case-insensitive
      const normalizedTemp = normalizedTempEnv.toLowerCase();
      const normalizedPath = pathModule
        .normalize(realAbsolutePath)
        .toLowerCase();
      // Ensure we match the directory prefix properly (add separator if not present)
      const tempPrefix = normalizedTemp.endsWith(pathModule.sep)
        ? normalizedTemp
        : normalizedTemp + pathModule.sep;
      return (
        normalizedPath === normalizedTemp ||
        normalizedPath.startsWith(tempPrefix)
      );
    }
    return false;
  }

  const normalizeUnixPath = (value: string): string => {
    const normalized = pathModule.normalize(value);
    if (platform !== "darwin") {
      return normalized;
    }
    if (
      normalized === "/tmp" ||
      normalized.startsWith("/tmp/") ||
      normalized === "/var" ||
      normalized.startsWith("/var/")
    ) {
      return `/private${normalized}`;
    }
    return normalized;
  };
  const normalizedPath = normalizeUnixPath(realAbsolutePath);
  if (
    homeDirectory !== undefined &&
    isPathWithinRootUsingPathModule({
      basePath: normalizeUnixPath(homeDirectory),
      targetPath: normalizedPath,
      pathModule,
    })
  ) {
    return false;
  }

  // macOS: paths matching MACOS_TMP_READWRITE_PATHS (excludes /var/tmp/)
  if (platform === "darwin") {
    const macosTmpPaths = ["/private/tmp/", "/private/var/folders/"];
    return macosTmpPaths.some(p => normalizedPath.startsWith(p));
  }

  // Linux: includes /var/tmp/ in addition to standard paths
  const linuxTmpPaths = [
    "/tmp/",
    "/private/tmp/",
    "/var/folders/",
    "/private/var/folders/",
    "/var/tmp/",
  ];
  return linuxTmpPaths.some(p => normalizedPath.startsWith(p));
}

function isAllowedTmpPath(realAbsolutePath: string): boolean {
  return isAllowedTmpPathWithOptions(realAbsolutePath, {
    platform: process.platform,
    env: process.env,
    pathModule: path,
    homeDirectory: homedir(),
  });
}

function isDebugLogPath(realAbsolutePath: string): boolean {
  const normalizedPath = realAbsolutePath.replace(/\\/g, "/");
  return /(^|\/)\.cursor\/debug(?:-[a-zA-Z0-9-]+)?\.log$/i.test(normalizedPath);
}

export type Permissions = {
  allow: string[];
  deny: string[];
  approvalMode: "unrestricted" | "allowlist" | "ask-every-time";
  userConfiguredPolicy: InternalSandboxPolicy;
  /**
   * True when an admin permissions file is the effective terminal allowlist.
   * In that mode dashboard team allowlist entries must not grant shell approvals.
   */
  dashboardTerminalAllowlistOverriddenByPermissionsFile?: boolean;
  /** Whether classifier-based shell allowlist matching is enabled */
  smartAllowlistEnabled?: boolean;
  /**
   * Commands that always require approval, even when Auto mode would otherwise
   * run them automatically. These are soft blocks: users can still approve the
   * command for the current run. Unlike the `deny` field (which hard-blocks),
   * commands in this list can still be approved by the user.
   *
   * NOTE: This is intentionally separate from `deny` because:
   * - `deny` entries route through `hasHardDeny()` and block immediately
   * - entries in this list should only prompt, not block
   */
  smartAllowlistDenylist?: string[];
};

export interface PermissionsProvider {
  getPermissions(): Promise<Permissions>;
  updatePermissions(
    transformer: (perms: { allow: string[]; deny: string[] }) => {
      allow: string[];
      deny: string[];
    }
  ): Promise<void>;
}

export type ApprovalDetails = FileEditApprovalDetails | McpApprovalDetails;

export type WriteBlockReason = "outOfWorkspace" | "protectedConfig" | undefined;

type FileEditApprovalDetails = {
  type: "fileEdit";
  isNewFile: boolean;
  diffString: string;
  blockReason?: WriteBlockReason;
};

type McpApprovalDetails = {
  type: "mcp";
  name: string;
  toolName: string;
  providerIdentifier: string;
  args: Record<string, Value>;
  reason?: string;
  canAllowlist?: boolean;
  smartModeApprovalReason?: string;
  smartModeApprovalRequestId?: string;
};

export type BlockReason =
  | { type: "cursorIgnore" }
  | { type: "adminBlock"; source: string }
  | { type: "adminCommandDenylist"; pattern: string }
  | { type: "userRejected"; reason?: string }
  | { type: "permissionsConfig"; isReadonly?: boolean }
  | { type: "cursorFiles" }
  | { type: "unsafeResolution"; message: string }
  | {
      type: "needsApproval";
      approvalReason: string;
      approvalDetails: ApprovalDetails;
    };

/**
 * Checks if policy1 is stricter than or equal to policy2.
 * Returns true if policy1 can be automatically approved given policy2 as the baseline.
 * This means policy1 must not grant any permissions that policy2 doesn't grant.
 */
function isPolicyStricterOrEqual(
  policy1: InternalSandboxPolicy,
  policy2: InternalSandboxPolicy
): boolean {
  // If policy2 is insecure_none (no restrictions), any policy is stricter or equal
  if (policy2.type === "insecure_none") {
    return true;
  }

  // If policy1 is insecure_none but policy2 is not, policy1 is looser
  if (policy1.type === "insecure_none") {
    return false;
  }

  // At this point both policies are either workspace_readonly or workspace_readwrite

  // Check network access: policy1 must not grant more network access than policy2.
  // Strictness ordering: disabled < allowlist < allow-all
  const policy1Network = isNetworkEnabledByPolicy(policy1.networkPolicy);
  const policy2Network = isNetworkEnabledByPolicy(policy2.networkPolicy);
  if (policy1Network && !policy2Network) {
    return false;
  }
  // allow-all is less strict than allowlist-filtered
  const policy1AllowAll = isAllowAllNetworkByPolicy(policy1.networkPolicy);
  const policy2AllowAll = isAllowAllNetworkByPolicy(policy2.networkPolicy);
  if (policy1AllowAll && policy2Network && !policy2AllowAll) {
    return false;
  }

  // Check read/write permissions: readonly is stricter than readwrite
  if (
    policy1.type === "workspace_readonly" &&
    policy2.type === "workspace_readwrite"
  ) {
    return true;
  }

  // If policy1 is readwrite but policy2 is readonly - policy1 is looser
  if (
    policy1.type === "workspace_readwrite" &&
    policy2.type === "workspace_readonly"
  ) {
    return false;
  }

  // Read boundary: workspace < custom < system (lower is stricter).
  // Undefined means System for backwards compatibility.
  const boundary1 = policy1.readBoundary ?? "system";
  const boundary2 = policy2.readBoundary ?? "system";
  if (
    READ_BOUNDARY_STRICTNESS[boundary1] > READ_BOUNDARY_STRICTNESS[boundary2]
  ) {
    return false;
  }

  return true;
}

// Commands that enter the "denied" state cannot leave.
// "preapproved" = command fit within userConfiguredPolicy (auto-approved)
// "allowlisted" = command was explicitly approved via user's allowlist
export type ApprovalState =
  | "preapproved"
  | "allowlisted"
  | "approvable"
  | "denied";

/**
 * Helper to wrap a command and track its approval state.
 */
export class ApprovableCommand {
  public state: ApprovalState;
  /**
   * Command strings that should be tried against user allowlist and hard-deny
   * entries. Populated by the smart-allowlist code path with raw +
   * classifier-canonical forms (see `classifierCommandMatchForms`). Callers
   * outside the smart-allowlist path pass nothing and fall back to a single
   * form derived from `command.fullText`, which matches pre-fix behavior.
   */
  public readonly matchForms: readonly string[];

  constructor(
    public readonly command: ShellCommandParsingResult_ExecutableCommand,
    public readonly requestedPolicy: InternalSandboxPolicy,
    preapprovedPolicy?: InternalSandboxPolicy,
    matchForms?: readonly string[]
  ) {
    // Command is preapproved if preapprovedPolicy is provided and
    // the requested policy is stricter or equal to the preapproved policy
    const preapproved =
      preapprovedPolicy !== undefined &&
      isPolicyStricterOrEqual(requestedPolicy, preapprovedPolicy);
    this.state = preapproved ? "preapproved" : "approvable";

    const fallback = [command.fullText.trim()].filter(Boolean);
    this.matchForms =
      matchForms && matchForms.length > 0 ? [...matchForms] : fallback;
  }

  public approveWithPolicy(policy: InternalSandboxPolicy): void {
    // Allowlist takes precedence: if command is in allowlist, mark as "allowlisted"
    // regardless of whether it was already "preapproved". This ensures allowlisted
    // commands run without sandbox even if requestedPolicy fits userConfiguredPolicy.
    if (
      (this.state === "approvable" || this.state === "preapproved") &&
      isPolicyStricterOrEqual(this.requestedPolicy, policy)
    ) {
      this.state = "allowlisted";
    }
  }

  public deny(): void {
    this.state = "denied";
  }

  public isRunnable(): boolean {
    return this.state === "preapproved" || this.state === "allowlisted";
  }
}

interface ShellApprovalDecisionFacts {
  // Whether any command was denied by non-user allowlist controls after allowlists ran.
  hasSecurityDenies: boolean;
  // Whether a user-configured soft-deny match should force a prompt.
  hasSoftDenies: boolean;
  // Whether team allowlist enforcement is enabled and at least one command missed it.
  hasTeamAllowlistMisses: boolean;
  // Whether every command can run automatically via sandbox preapproval or allowlist.
  allCommandsRunnable: boolean;
  // Whether every command was explicitly user/team allowlisted for unsandboxed autorun.
  allCommandsAllowlisted: boolean;
  // Whether every command can autorun because the requested sandbox policy
  // is within the user's configured auto-run sandbox policy.
  allCommandsPreapproved: boolean;
  // Whether the prompt may offer to add commands to the user's allowlist.
  canAllowlistInPrompt: boolean;
  // Commands that require approval because they are neither preapproved nor allowlisted.
  unapprovedCommands: ApprovableCommand[];
  // Commands denied by team blocklist or delete protection.
  deniedCommands: ApprovableCommand[];
  // Commands missing from the enforced team allowlist.
  notInTeamAllowlist: ApprovableCommand[];
  // Denied commands that specifically matched the team blocklist.
  teamBlocklistedCommands: ApprovableCommand[];
  // Denied rm commands when delete protection is enabled.
  rmDeniedByDeleteProtection: ApprovableCommand[];
}

function sandboxPolicyTypeForLogging(
  policy: InternalSandboxPolicy | undefined
): string {
  return policy?.type ?? "undefined";
}

export interface PermissionsService {
  shouldBlockRead(
    filePath: string,
    facts?: { cursorIgnoreChecked?: boolean }
  ): Promise<false | BlockReason>;

  shouldBlockWrite(
    parentCtx: Context,
    filePath: string,
    newContents: string
  ): Promise<false | BlockReason>;

  shouldBlockShellCommand(
    parentCtx: Context,
    command: string,
    options: {
      workingDirectory: string;
      timeout: number;
      parsingResult: ShellCommandParsingResult;
      toolCallId?: string;
      /** Classifier-derived shell command extraction result, when available */
      classifierResult?: CommandClassifierResult;
      /** Smart Mode classifier reason that forces one-time native approval */
      smartModeApprovalReason?: string;
      /** Redis-backed Smart Mode approval request id */
      smartModeApprovalRequestId?: string;
      hookApprovalRequirement?: ShellHookApprovalRequirement;
    },
    requestedPolicy?: InternalSandboxPolicy
  ): Promise<
    | { kind: "allow"; policy: InternalSandboxPolicy }
    | { kind: "block"; reason: BlockReason }
  >;
  /**
   * Allowlist-only precheck used to skip the Smart Mode risk classifier when
   * the user's existing shell allowlist already covers the command without
   * needing a prompt.
   *
   * Returns true if every extracted command would be auto-approved by the
   * **user or team allowlist** under the *same* matching rules that
   * {@link PermissionsService.shouldBlockShellCommand} applies:
   *   - the smart/semantic allowlist when `smartAllowlistEnabled` is on and a
   *     usable classifier result is available, otherwise the tree-sitter
   *     `fullText` form,
   *   - matched via the existing `matchesShell` allowlist matcher (so
   *     `Shell(npm:install*)`, `Shell(git status)` etc. all keep their
   *     existing semantics).
   *
   * The check is intentionally conservative — it returns false (so the
   * classifier path runs) on any signal that local-exec would normally
   * react to: hard denies, soft denies, team blocklists, delete-protection
   * `rm`s, workspace_readonly mode, ask-every-time mode, parser bypass with
   * no classifier rescue. The classifier (or local-exec's own approval flow)
   * stays the source of truth for those cases.
   *
   * Does NOT mutate state, request user approval, or escalate sandbox policy.
   */
  isShellCommandFullyAllowlisted(
    parentCtx: Context,
    command: string,
    options: {
      workingDirectory: string;
      parsingResult: ShellCommandParsingResult;
      classifierResult?: CommandClassifierResult;
      toolCallId?: string;
    }
  ): Promise<boolean>;
  /**
   * Non-overridable shell gates (repo blocklist, cwd resolution, readonly ceiling).
   * Used when user-facing allowlist approval was already satisfied (e.g. Smart Mode ALLOW).
   *
   * Pass `skipUnsafeWorkingDirectoryBlock: true` for foreground shells where the cwd
   * is just a starting point — the command itself can chdir anywhere, so failing
   * the spawn solely because realpath erroneously errored on the cwd is overzealous.
   * In that mode an unresolvable cwd skips the blocklist lookup (fail-open) instead
   * of hard-blocking; the readonly ceiling still applies.
   */
  shouldEnforceShellInvariantBlocks(
    parentCtx: Context,
    options: {
      workingDirectory: string;
      skipUnsafeWorkingDirectoryBlock?: boolean;
      /**
       * The admin command denylist is enforced against this command, so
       * `skipApproval` paths (Smart Mode ALLOW and other pre-approved flows)
       * cannot bypass the hard block by skipping the approval gate.
       */
      command: string;
      parsingResult?: ShellCommandParsingResult;
      toolCallId?: string;
    },
    requestedPolicy?: InternalSandboxPolicy
  ): Promise<{ kind: "allow" } | { kind: "block"; reason: BlockReason }>;
  shouldBlockMcp(ctx: Context, args: McpArgs): Promise<false | BlockReason>;
  /**
   * Allowlist-only precheck used to skip the Smart Mode risk classifier when
   * the user or team MCP allowlist already covers the call without needing a
   * prompt.
   *
   * Returns true iff every condition that would let
   * {@link PermissionsService.shouldBlockMcp} take its "explicitly allowed"
   * fast-path is satisfied:
   *   - the (`providerIdentifier`, `toolName`) pair is NOT in the user deny
   *     list, and
   *   - it matches either the admin team allowlist (when admin auto-run
   *     controls are enabled) or the user's `Mcp(...)` allowlist (when
   *     they are not).
   *
   * The check is intentionally conservative — anything that would otherwise
   * cause `shouldBlockMcp` to prompt (Smart Mode forced approval, readonly
   * ceiling, team-blocks-MCP under auto-run) returns false so the classifier
   * path remains authoritative. Does NOT mutate state, request user
   * approval, or escalate sandbox policy.
   */
  isMcpFullyAllowlisted(
    parentCtx: Context,
    options: {
      providerIdentifier: string;
      toolName: string;
    }
  ): Promise<boolean>;
  /**
   * Allowlist-only precheck used to skip the Smart Mode risk classifier when
   * the user's existing WebFetch domain allowlist already covers the URL
   * without needing a prompt.
   *
   * The check is intentionally conservative — explicit deny entries win, and
   * anything outside allowlist approval mode or with an invalid URL returns
   * false so the classifier path and downstream approval flow stay
   * authoritative. Does NOT mutate state or request user approval.
   */
  isWebFetchFullyAllowlisted(
    parentCtx: Context,
    options: {
      url: string;
    }
  ): Promise<boolean>;

  addToAllowList(
    ctx: Context,
    kind: "Shell" | "Read" | "Write" | "Mcp" | "WebFetch" | "GenerateImage",
    value: string
  ): Promise<void>;
  addToDenyList(
    ctx: Context,
    kind: "Shell" | "Read" | "Write" | "Mcp" | "WebFetch",
    value: string
  ): Promise<void>;
}

type ShellCommandOptions = Parameters<
  PermissionsService["shouldBlockShellCommand"]
>[2];
type ShellCommandDecision = Awaited<
  ReturnType<PermissionsService["shouldBlockShellCommand"]>
>;

export class InteractivePermissionsService implements PermissionsService {
  private readonly rootDirectories: string[];
  private readonly perUserSandboxConfigPath: string;
  private readonly mcpAllowlistLog?: (msg: string) => void;

  constructor(
    private readonly ignoreService: IgnoreService,
    private readonly pendingDecisionStore: PendingDecisionProvider,
    private readonly permissionsProvider: PermissionsProvider,
    private readonly teamSettingsService: TeamSettingsService,
    rootDirectory?: string | string[],
    private readonly adminNetworkControlsEnabled: boolean = false,
    options?: {
      /**
       * Path to the per-user sandbox config file. Defaults to ~/.cursor/sandbox.json.
       * Injectable for testing — pass a nonexistent path to disable file loading.
       */
      perUserSandboxConfigPath?: string;
      mcpAllowlistLog?: (msg: string) => void;
    }
  ) {
    this.rootDirectories = Array.isArray(rootDirectory)
      ? rootDirectory
      : [rootDirectory ?? process.cwd()];
    this.perUserSandboxConfigPath =
      options?.perUserSandboxConfigPath ??
      join(homedir(), ".cursor", "sandbox.json");
    this.mcpAllowlistLog = options?.mcpAllowlistLog;
  }

  /**
   * Check if a file read should be blocked.
   * Blocks if cursor ignored or explicitly denied by permissions.
   * @returns false if allowed, BlockReason if blocked
   */
  async shouldBlockRead(
    filePath: string,
    { cursorIgnoreChecked = false }: { cursorIgnoreChecked?: boolean } = {}
  ): Promise<false | BlockReason> {
    const absolutePath = resolvePath(filePath);

    // Resolve for ignore checks -- follows symlinks
    const resolvedForIgnore = await resolvePathForIgnoreService(absolutePath);

    // Check repo blocklist first
    if (resolvedForIgnore === null) {
      return {
        type: "unsafeResolution",
        message: ignoreResolutionBlockMessage("Read", "path", absolutePath),
      };
    }
    if (await this.ignoreService.isRepoBlocked(resolvedForIgnore)) {
      return {
        type: "adminBlock",
        source: "Team repo blocklist",
      };
    }

    // Permissions explicit deny for reads
    if (await this.isPathExplicitlyDenied("Read", absolutePath)) {
      return { type: "permissionsConfig" };
    }

    // Allow reads from Cursor internal data roots — these should never be
    // blocked by workspace cursorIgnore patterns.
    if (
      isCursorProjectsPath(resolvedForIgnore) ||
      isCursorWorktreesPath(resolvedForIgnore)
    ) {
      return false;
    }

    // Check if cursor ignored
    if (
      !cursorIgnoreChecked &&
      (await this.ignoreService.isCursorIgnored(resolvedForIgnore))
    ) {
      return { type: "cursorIgnore" };
    }

    // Permissions explicit allow for reads => allow outright
    // this really doesn't matter since we allow reads for out of workspace and dot files
    if (await this.isPathExplicitlyAllowed("Read", absolutePath)) {
      return false;
    }

    // Allow reads for out of workspace and dot files
    return false;
  }

  /**
   * Check if a file write should be blocked.
   * Auto-blocks cursor ignored files.
   * For other cases (out of workspace, dot files), prompts the user unless explicitly allowed by permissions.
   * Explicit deny in permissions blocks immediately.
   * Respects auto-run mode to skip approvals when enabled.
   * @returns false if allowed, BlockReason if blocked
   */
  async shouldBlockWrite(
    parentCtx: Context,
    filePath: string,
    newContents: string
  ): Promise<false | BlockReason> {
    using span = createSpan(
      parentCtx.withName("InteractivePermissionsService.shouldBlockWrite")
    );
    const ctx = span.ctx;

    // Block writes when path resolution is unsafe (dangling symlink,
    // permission denied, symlink loop, etc.). This prevents symlink-based
    // attacks where an unresolvable path could write through to a protected file.
    const permPath = await resolvePermissionsPath(filePath);
    if (!isResolutionSafe(permPath.resolution)) {
      return {
        type: "unsafeResolution",
        message: resolutionBlockMessage(
          permPath.originalPath,
          permPath.resolution
        ),
      };
    }

    // After resolution passes, use the canonical resolved path for all
    // downstream checks. For existing files this is the realpath (symlinks
    // fully resolved); for new files this is parent-resolved + leaf name.
    const realAbsolutePath = permPath.resolvedPath;

    // permPath.resolvedPath is already canonical (symlinks resolved by
    // resolvePermissionsPath), so mint the branded type directly.
    const resolvedForIgnore = unsafeMintResolvedIgnorePath(realAbsolutePath);

    // Check repo blocklist first
    if (await this.ignoreService.isRepoBlocked(resolvedForIgnore)) {
      return {
        type: "adminBlock",
        source: "Team repo blocklist",
      };
    }

    // Permissions explicit deny for writes
    if (await this.isPathExplicitlyDenied("Write", realAbsolutePath)) {
      return { type: "permissionsConfig" };
    }

    // Hard block ANY writes to .cursorignore - cannot be bypassed even in auto-run mode
    // This prevents agents from bypassing CVE-2025-64110 protections by creating, editing, or deleting .cursorignore
    // Check both the original (symlink) name AND the resolved target name
    const originalFileName =
      permPath.originalPath.split(sep).pop()?.toLowerCase() ?? "";
    const resolvedFileName =
      realAbsolutePath.split(sep).pop()?.toLowerCase() ?? "";
    if (
      originalFileName === ".cursorignore" ||
      resolvedFileName === ".cursorignore"
    ) {
      return { type: "permissionsConfig" };
    }

    // Allow writes to Cursor internal data roots — these should never be
    // blocked by workspace cursorIgnore patterns.
    const isCursorProjects = isCursorProjectsPath(resolvedForIgnore);
    const isCursorWorktrees = isCursorWorktreesPath(resolvedForIgnore);
    const isCursorIgnored =
      !isCursorProjects &&
      !isCursorWorktrees &&
      (await this.ignoreService.isCursorIgnored(resolvedForIgnore));
    if (isCursorProjects || isCursorWorktrees) {
      // Still fall through to the remaining checks (out-of-workspace, protected configs, etc.)
    } else if (isCursorIgnored) {
      // Check if cursor ignored - auto block
      return { type: "cursorIgnore" };
    }

    // Explicit allow for writes — skip prompts
    if (await this.isPathExplicitlyAllowed("Write", realAbsolutePath)) {
      return false;
    }

    if (isDebugLogPath(realAbsolutePath)) {
      return false;
    }

    const perms = await this.getPermissions();
    if (perms.userConfiguredPolicy.type === "workspace_readonly") {
      return { type: "permissionsConfig", isReadonly: true };
    }

    // In "Run Everything" mode, bypass all remaining checks (protected configs, dotfiles, out-of-workspace).
    // Admin control is enforced upstream: if admin disables Run Everything, approvalMode is forced to "allowlist".
    // So if we're here with approvalMode === "unrestricted", it's legitimately enabled.
    const isAutoRun = perms.approvalMode === "unrestricted";
    if (isAutoRun) {
      return false;
    }

    // dotCursorProtection: run only for in-workspace paths (prefix match) so we
    // don't block ~/.cursor/worktrees/ when that's the workspace root.
    for (const rootDir of this.rootDirectories) {
      const rootPermPath = await resolvePermissionsPath(rootDir);
      if (!isResolutionSafe(rootPermPath.resolution)) continue;
      const realRootDir = rootPermPath.resolvedPath;
      if (isPathInsideWorkspaceRoot(realAbsolutePath, realRootDir)) {
        const relativePathForCheck = relative(realRootDir, realAbsolutePath);
        const pathComponentsForEarlyCheck = relativePathForCheck
          .split(sep)
          .map(c =>
            process.platform === "win32" && c.includes(":")
              ? c.split(":")[0]
              : c
          );
        const earlyCursorFileBlockReason = await this.checkCursorFileProtection(
          pathComponentsForEarlyCheck
        );
        if (earlyCursorFileBlockReason) {
          return earlyCursorFileBlockReason;
        }
        break;
      }
    }

    const getIsNewFileAndDiffString = async () => {
      let isNewFile = false;
      let originalContents = "";
      try {
        originalContents = await readText(realAbsolutePath);
        isNewFile = false;
      } catch {
        isNewFile = true;
      }

      let diffString = "";
      if (isNewFile) {
        diffString = newContents;
      } else {
        const ensureNL = (s: string) => (s.endsWith("\n") ? s : `${s}\n`);
        const { hunks } = structuredPatch(
          "a",
          "b",
          ensureNL(originalContents),
          ensureNL(newContents),
          "",
          "",
          { context: 2 }
        );
        diffString = hunks
          .map(h =>
            h.lines
              // add a little padding to the lines so that the diff is easier to read
              .map(line =>
                line.length > 0 ? `${line[0]} ${line.slice(1)}` : line
              )
              .join("\n")
          )
          .join("\n...\n");
      }
      return { isNewFile, diffString };
    };

    // Check if out of workspace by checking against all workspace paths
    let isInWorkspace = false;
    let matchedRootDirectory: string | undefined;

    for (const rootDir of this.rootDirectories) {
      const rootPermPath = await resolvePermissionsPath(rootDir);
      if (!isResolutionSafe(rootPermPath.resolution)) continue;
      const realRootDirectory = rootPermPath.resolvedPath;
      if (isPathInsideWorkspaceRoot(realAbsolutePath, realRootDirectory)) {
        isInWorkspace = true;
        matchedRootDirectory = realRootDirectory;
        break;
      }
    }

    // Treat each ~/.cursor/worktrees/<worktree-id>/ as an effective root:
    // these writes bypass out-of-workspace prompts, but still go through
    // protected-path checks below (.git hooks/config, .cursor configs, etc.).
    const cursorWorktreeRoot = !isInWorkspace
      ? getCursorWorktreeRoot(realAbsolutePath)
      : undefined;

    if (!isInWorkspace && cursorWorktreeRoot === undefined) {
      // Allow writing to standard tmp directories without approval
      // These paths are also allowed by the sandbox (see packages/sandbox-helper)
      if (isAllowedTmpPath(realAbsolutePath)) {
        return false;
      }

      // Allow internal agent data paths
      if (
        isCursorProjectsInternalPath(realAbsolutePath, [
          "assets",
          "agent-notes",
          "agent-tools",
          "swarm-agents",
        ])
      ) {
        return false;
      }

      // Allow editing any .md/.mdc/.cursorrules file anywhere in ~/.cursor/
      // These are user-configurable files for rules, commands, skills, agents, etc.
      const userCursorDir = `${homedir()}${sep}.cursor${sep}`;
      if (realAbsolutePath.startsWith(userCursorDir)) {
        const cursorFileName =
          realAbsolutePath.split(sep).pop()?.toLowerCase() ?? "";
        const hasAllowedExtension =
          cursorFileName.endsWith(".md") ||
          cursorFileName.endsWith(".mdc") ||
          cursorFileName === ".cursorrules";
        if (hasAllowedExtension) {
          return false;
        }
      }

      const { isNewFile, diffString } = await getIsNewFileAndDiffString();
      return {
        type: "needsApproval",
        approvalReason: "Out of workspace",
        approvalDetails: {
          type: "fileEdit",
          isNewFile,
          diffString,
          blockReason: "outOfWorkspace",
        },
      };
    }

    // Normalize path for case-insensitive comparison
    // Some FS are case insensitive, do this for safety.
    const pathRootForProtection = matchedRootDirectory ?? cursorWorktreeRoot;
    const pathForProtection = realAbsolutePath;
    const relativePath = relative(pathRootForProtection!, pathForProtection);
    let pathComponents = relativePath.split(sep);
    pathComponents = pathComponents.map(c =>
      process.platform === "win32" && c.includes(":") ? c.split(":")[0] : c
    );

    // Check if any path segment contains ~ (DOS short paths) on Windows
    // DOS short paths look like PROGRA~1 instead of Program Files
    if (
      process.platform === "win32" &&
      pathComponents.some(segment => segment.includes("~"))
    ) {
      const { isNewFile, diffString } = await getIsNewFileAndDiffString();
      return {
        type: "needsApproval",
        approvalReason: `Protected config file: ${pathComponents[pathComponents.length - 1] ?? ""}`,
        approvalDetails: {
          type: "fileEdit",
          isNewFile,
          diffString,
          blockReason: "protectedConfig",
        },
      };
    }

    // Type-aware check against ALL hardcoded write-protection patterns.
    // Resolves each pattern type (workspace, git, worktree, absolute, home)
    // against the correct root directory -- single source of truth shared
    // with the sandbox.
    if (
      await isHardcodedWriteProtected(realAbsolutePath, pathRootForProtection!)
    ) {
      const lastPathSegment =
        pathComponents[pathComponents.length - 1]?.toLowerCase() ?? "";
      const { isNewFile, diffString } = await getIsNewFileAndDiffString();
      return {
        type: "needsApproval",
        approvalReason: `Protected config file: ${lastPathSegment}`,
        approvalDetails: {
          type: "fileEdit",
          isNewFile,
          diffString,
          blockReason: "protectedConfig",
        },
      };
    }

    // Check .cursor file protection (team-admin-controlled, separate from
    // the declarative rules above because it depends on async team settings).
    const cursorFileBlockReason =
      await this.checkCursorFileProtection(pathComponents);
    if (cursorFileBlockReason) {
      return cursorFileBlockReason;
    }

    // Allow all other writes
    return false;
  }

  /**
   * Check if a shell command should be blocked.
   *
   * This is based on a somewhat complicated dance of sandbox policies, allowlists and denylists.
   *
   * We have several allowlists that can be applied.
   * User scoped:
   * - Shell allowlist: Approves commands up to RunLevel.Unsandboxed (effectively unconditionally).
   * - User denylist: Denies a command.
   * - Baseline user sandboxing config: Not really an allowlist but sets the level at which the user is comfortable running commands without approval.
   *
   * Team scoped:
   * - Team allowlist: Approves commands
   * - Team blocklist: Denies commands
   * - Team delete file protection: Denies specifically rm commands.
   *
   * Approval modes:
   * - allowlist: Follow regular sandboxing path with user configured policy
   * - unrestricted: No sandboxing, always run (unless blocked) - applies to all operations
   *
   * Since models can issue composite commands, we need to consider each subcommand separately.
   * Commands start life as potentially preapproved based on whether the requested policy is stricter than the user's config.
   * They are then passed through the above allow and deny lists.
   *
   * If any command is hard denied, we deny the entire batch.
   * If all of them are runnable, we approve the batch without user interaction.
   *
   * If none of the above are true, some commands must be approvable so we prompt the user for approval.
   * The form of approval requested is based on the requested policy and approval mode.
   * Regardless of what commands are already runnable they're going to get run together with the requested policy.
   */
  async shouldEnforceShellInvariantBlocks(
    ctx: Context,
    options: {
      workingDirectory: string;
      skipUnsafeWorkingDirectoryBlock?: boolean;
      command: string;
      parsingResult?: ShellCommandParsingResult;
      toolCallId?: string;
    },
    requestedPolicy?: InternalSandboxPolicy
  ): Promise<{ kind: "allow" } | { kind: "block"; reason: BlockReason }> {
    // Admin command denylist: a deterministic hard block with no approval,
    // bypass, or allowlist path. It lives with the other non-overridable
    // invariants so `skipApproval` paths (Smart Mode ALLOW, pre-approved
    // replays) enforce it exactly like the repo blocklist and readonly
    // ceiling.
    const denylistBlock = await this.getAdminCommandDenylistBlock(ctx, {
      command: options.command,
      parsingResult: options.parsingResult,
      toolCallId: options.toolCallId,
    });
    if (denylistBlock !== undefined) {
      return { kind: "block", reason: denylistBlock };
    }

    const resolvedWorkDir = await resolvePathForIgnoreService(
      options.workingDirectory
    );
    if (resolvedWorkDir === null) {
      if (options.skipUnsafeWorkingDirectoryBlock !== true) {
        return {
          kind: "block",
          reason: {
            type: "unsafeResolution",
            message: ignoreResolutionBlockMessage(
              "Command",
              "working directory",
              options.workingDirectory
            ),
          },
        };
      }
      // Fail-open: shell commands can chdir anywhere, so a cwd we can't realpath
      // is not a meaningful security boundary on its own. We skip the blocklist
      // lookup (it requires a resolved path) but still apply the readonly ceiling
      // below.
    } else if (await this.ignoreService.isRepoBlocked(resolvedWorkDir)) {
      return {
        kind: "block",
        reason: {
          type: "adminBlock",
          source: "Team repo blocklist",
        },
      };
    }

    const perms = await this.getPermissions();
    const userConfiguredPolicy = perms.userConfiguredPolicy;
    const effectiveRequestedPolicy = requestedPolicy ?? userConfiguredPolicy;
    if (
      userConfiguredPolicy.type === "workspace_readonly" &&
      effectiveRequestedPolicy.type !== "workspace_readonly"
    ) {
      return {
        kind: "block",
        reason: { type: "permissionsConfig", isReadonly: true },
      };
    }

    return { kind: "allow" };
  }

  async shouldBlockShellCommand(
    ctx: Context,
    command: string,
    options: {
      workingDirectory: string;
      timeout: number;
      parsingResult: ShellCommandParsingResult;
      toolCallId?: string;
      /** Classifier-derived shell command extraction result, when available */
      classifierResult?: CommandClassifierResult;
      /** Smart Mode classifier reason that forces one-time native approval */
      smartModeApprovalReason?: string;
      /** Redis-backed Smart Mode approval request id */
      smartModeApprovalRequestId?: string;
      hookApprovalRequirement?: ShellHookApprovalRequirement;
    },
    requestedPolicy?: InternalSandboxPolicy
  ): Promise<
    | {
        kind: "allow";
        policy: InternalSandboxPolicy;
      }
    | {
        kind: "block";
        reason: BlockReason;
      }
  > {
    const explicitlyRequestedInsecureNone =
      requestedPolicy?.type === "insecure_none";
    const invariantBlock = await this.shouldEnforceShellInvariantBlocks(
      ctx,
      {
        workingDirectory: options.workingDirectory,
        command,
        parsingResult: options.parsingResult,
        toolCallId: options.toolCallId,
      },
      requestedPolicy
    );
    if (invariantBlock.kind === "block") {
      return invariantBlock;
    }

    const perms = await this.getPermissions();
    const approvalMode = perms.approvalMode;
    const isUnrestricted = approvalMode === "unrestricted";
    const userConfiguredPolicy = perms.userConfiguredPolicy;
    const shouldApplyTeamShellAllowlist =
      !perms.dashboardTerminalAllowlistOverriddenByPermissionsFile;
    logger.info(ctx, "Shell permissions: evaluating shell command", {
      toolCallId: options.toolCallId,
      approvalMode,
      userConfiguredPolicyType:
        sandboxPolicyTypeForLogging(userConfiguredPolicy),
      requestedPolicyType: sandboxPolicyTypeForLogging(requestedPolicy),
      effectiveRequestedPolicyType: sandboxPolicyTypeForLogging(
        requestedPolicy ?? userConfiguredPolicy
      ),
      smartAllowlistEnabled: perms.smartAllowlistEnabled === true,
      hasSmartModeApprovalReason: options.smartModeApprovalReason !== undefined,
      hasSmartModeApprovalRequestId:
        options.smartModeApprovalRequestId !== undefined,
      hookForcesPrompt: isForcePromptHookApprovalRequirement(
        options.hookApprovalRequirement
      ),
      classifierClassificationFailed:
        options.classifierResult?.classificationFailed === true,
      classifierCommandCount: options.classifierResult?.commands.length ?? 0,
      parserCommandCount: options.parsingResult.executableCommands.length,
      parsingFailed: options.parsingResult.parsingFailed,
      hasRedirects: options.parsingResult.hasRedirects,
      commandLength: command.length,
    });

    // Plain Allowlist with no shell controls is intentionally "ask for this
    // command". Keep this before any `options.parsingResult` reads so local-exec
    // does not parse-match against an allowlist that cannot contain a match.
    if (await this.shouldPromptForEmptyPlainShellAllowlist(command, perms)) {
      logger.info(ctx, "Shell permissions: prompting for empty allowlist", {
        toolCallId: options.toolCallId,
        approvalMode,
        userConfiguredPolicyType:
          sandboxPolicyTypeForLogging(userConfiguredPolicy),
        requestedPolicyType: sandboxPolicyTypeForLogging(requestedPolicy),
        hasSmartModeApprovalReason:
          options.smartModeApprovalReason !== undefined,
        hasSmartModeApprovalRequestId:
          options.smartModeApprovalRequestId !== undefined,
      });
      return await this.requestApprovalForEmptyShellAllowlist(
        command,
        options,
        requestedPolicy ?? userConfiguredPolicy
      );
    }

    // Extract command information
    const executableCommands = options.parsingResult.executableCommands;
    const hasRedirects = options.parsingResult.hasRedirects;
    // Field name is wire-compatible with the original /dev/null-only signal,
    // but the parser now sets it for any redirect graph that is safe to offer
    // as an allowlist prompt (original stdout/stderr or /dev/null only).
    const allRedirectsAreAllowlistSafe =
      options.parsingResult.allRedirectsAreDevNull === true;
    const parsingFailed = options.parsingResult.parsingFailed;
    const classifierResult = options.classifierResult;
    const smartModeApprovalReason = options.smartModeApprovalReason;
    const smartModeApprovalRequestId = options.smartModeApprovalRequestId;
    const usableClassifierResult =
      classifierResult !== undefined &&
      !classifierResult.classificationFailed &&
      classifierResult.commands.length > 0
        ? classifierResult
        : undefined;
    const smartAllowlistClassifierCommands =
      approvalMode === "allowlist" && (perms.smartAllowlistEnabled ?? false)
        ? usableClassifierResult?.commands
        : undefined;
    const isSmartAllowlistActive =
      smartAllowlistClassifierCommands !== undefined;
    const commandsForPermissionChecks = smartAllowlistClassifierCommands
      ? smartAllowlistClassifierCommands.map(
          classifierCommandToExecutableCommand
        )
      : executableCommands;
    // Match forms per command, index-aligned with `commandsForPermissionChecks`.
    //   - smart-allowlist path: raw `name args...` plus the canonical
    //     `name + subcommandTokens` form (dedupe-collapses when equal).
    //     This is what lets allowlist / hard-deny entries like
    //     `Shell(aws autoscaling describe-auto-scaling-groups)` correctly
    //     match flag-interleaved invocations.
    //   - tree-sitter path: a single form derived from `fullText`,
    //     byte-identical to pre-fix behavior.
    const commandMatchFormsPerCommand: string[][] =
      smartAllowlistClassifierCommands !== undefined
        ? smartAllowlistClassifierCommands.map(classifierCommandMatchForms)
        : commandsForPermissionChecks.map(cmd =>
            [cmd.fullText.trim()].filter(Boolean)
          );
    const commandBlocklistMatchFormsPerCommand: string[][] =
      usableClassifierResult !== undefined
        ? usableClassifierResult.commands.map(classifierCommandMatchForms)
        : commandMatchFormsPerCommand;

    // If no policy was requested, use the user's configured policy.
    // This ensures commands auto-run in sandbox mode when the model doesn't
    // explicitly request a different policy.
    if (!requestedPolicy) {
      requestedPolicy = perms.userConfiguredPolicy;
    }

    // Backward compatibility: some runtime callers may still omit
    // skipStatsigDefaults on requestedPolicy even when user policy carries it.
    // In that case, inherit from user policy to preserve user_config_only.
    if (
      requestedPolicy.type !== "insecure_none" &&
      requestedPolicy.skipStatsigDefaults === undefined &&
      userConfiguredPolicy.type !== "insecure_none"
    ) {
      requestedPolicy = {
        ...requestedPolicy,
        skipStatsigDefaults: userConfiguredPolicy.skipStatsigDefaults ?? true,
      };
    }

    // If user has network enabled by default, grant it. Use the user's policy
    // as the base (it's the floor) and union any model-requested allow entries
    // so the model's required domains are preserved alongside the user's config.
    // Skip this when the model requested allow-all (full_network) — that's a
    // user-approved escalation that shouldn't be downgraded to an allowlist.
    if (
      userConfiguredPolicy.type !== "insecure_none" &&
      isNetworkEnabledByPolicy(userConfiguredPolicy.networkPolicy) &&
      requestedPolicy.type !== "insecure_none" &&
      !isAllowAllNetworkByPolicy(requestedPolicy.networkPolicy)
    ) {
      const userPolicy = userConfiguredPolicy.networkPolicy;
      const modelAllow = requestedPolicy.networkPolicy?.allow;
      if (modelAllow !== undefined && modelAllow.length > 0 && userPolicy) {
        // Union model's requested domains into user's policy
        const mergedAllow = [
          ...new Set([...(userPolicy.allow ?? []), ...modelAllow]),
        ];
        requestedPolicy = {
          ...requestedPolicy,
          networkPolicy: { ...userPolicy, allow: mergedAllow },
        };
      } else {
        requestedPolicy = {
          ...requestedPolicy,
          networkPolicy: userPolicy,
        };
      }
    }

    // Apply the user's Agent Read Access as a floor. Model-requested policies
    // usually omit readBoundary (proto defaults to unspecified → System); without
    // this, the UI Workspace setting never reaches the helper.
    requestedPolicy = applyUserReadBoundaryFloor({
      requestedPolicy,
      userConfiguredPolicy,
    });

    if (classifierResult) {
      // NOTE: Don't log suggestedAllowlistEntries as they may contain sensitive arguments
      logger.info(ctx, "Smart allowlist: classifier result received", {
        classificationFailed: classifierResult.classificationFailed,
        suggestedSandboxMode: classifierResult.suggestedSandboxMode,
        commandCount: classifierResult.commands.length,
        suggestedAllowlistEntryCount: classifierResult.commands.filter(
          c => c.suggestedAllowlistEntry
        ).length,
      });
    }

    // Classifier-derived command text is only used for user allowlist and
    // command blocklist matching here. Team controls, hard denies, delete protection,
    // readonly policy, and sandbox autorun are evaluated from the shared
    // approval facts below.
    //
    // MATCHING MODEL: For each classifier command we build a set of "match
    // forms" via `classifierCommandMatchForms`: always the raw
    // `name args...` string, and — when the classifier provided non-empty
    // `subcommandTokens` — also a canonical `name sub1 sub2 ...` string that
    // omits flags and non-subcommand args. Each match form is tried against
    // the allowlist/blocklist entries independently, and a match in any form
    // counts.
    //
    // This lets entries like `Shell(aws autoscaling describe-auto-scaling-groups)`
    // — which the suggestion ladder offered the user — correctly auto-approve
    // `aws --region us-east-1 autoscaling describe-auto-scaling-groups ...`,
    // where the raw-form prefix check alone would fail because the command
    // starts with `"aws --region"`. The expansion is strictly additive: when
    // `subcommandTokens` is empty or the classifier is unavailable, match
    // behavior is byte-identical to the pre-fix code path.
    let smartAllowlistWantsAutoApprove = false;
    const commandBlocklistPromptReasons: string[] = [];
    const smartAllowlistPromptReasons: string[] = [];
    let smartAllowlistNotInAllowlist: string[] = [];
    let commandBlocklistedCommands: string[] = [];
    let smartAllowlistSuggestedEntries: string[] = [];

    const userCommandBlocklist = normalizeAllowlistCandidates(
      perms.smartAllowlistDenylist ?? []
    );
    if (userCommandBlocklist.length > 0) {
      commandBlocklistedCommands = [];
      const commandNames = commandBlocklistMatchFormsPerCommand.map(
        forms => forms[0] ?? ""
      );
      for (let i = 0; i < commandBlocklistMatchFormsPerCommand.length; i++) {
        const forms = commandBlocklistMatchFormsPerCommand[i];
        if (!forms || forms.length === 0) continue;
        const isBlocklisted = userCommandBlocklist.some(entry =>
          commandMatchesBlocklistEntry(forms, entry)
        );
        if (isBlocklisted) {
          const commandName = commandNames[i];
          if (commandName) commandBlocklistedCommands.push(commandName);
        }
      }
      if (commandBlocklistedCommands.length > 0) {
        logger.info(ctx, "Command blocklist: commands require approval", {
          count: commandBlocklistedCommands.length,
        });
        commandBlocklistPromptReasons.push(
          `In blocklist: ${commandBlocklistedCommands.join(", ")}`
        );
      }
    }

    if (isSmartAllowlistActive && classifierResult) {
      // `commandMatchFormsPerCommand` was precomputed above and is the same
      // list used when building `ApprovableCommand`s further down, so both
      // allowlist code paths (this user-visible smart-allowlist block and
      // the `isInShellAllowlist` path that drives auto-approval) see the
      // exact same match forms.
      //
      // For logs and user-visible reason text we want a single stable
      // representation per command. The raw form (element 0 of each match
      // forms list) is what the user actually typed, so it's the right
      // choice here.
      const classifiedCommandNames = commandMatchFormsPerCommand.map(
        forms => forms[0] ?? ""
      );

      // Keep the original allowlist entries to use matchesShell for proper
      // args pattern matching. This ensures Shell(npm:install*) only matches
      // "npm install..." not "npm run malicious".
      const userAllowlistEntries = perms.allow.filter(entry =>
        this.isShellEntry(entry)
      );
      logger.info(ctx, "Smart allowlist: checking commands against lists", {
        commandCount: classifiedCommandNames.length,
        allowlistCount: userAllowlistEntries.length,
        commandBlocklistCount: userCommandBlocklist.length,
      });

      // Allowlist: a command is "in the allowlist" if any of its match forms
      // is matched by any allowlist entry via `matchesShell`. This preserves
      // colon-syntax and glob semantics (Shell(npm:install*), Shell(curl:*))
      // because we still delegate to `matchesShell` per form.
      const commandIsAllowlisted = commandMatchFormsPerCommand.map(forms =>
        userAllowlistEntries.some(entry =>
          forms.some(form => this.matchesShell(entry, form))
        )
      );
      const allInAllowlist = commandIsAllowlisted.every(Boolean);

      // Partition classifier commands into allowed vs not-allowed. Done as a
      // single index walk so the raw-name list and classifier-command list
      // stay in sync.
      const notAllowlistedClassifierCommands: NonNullable<
        CommandClassifierResult["commands"]
      > = [];
      for (let i = 0; i < classifierResult.commands.length; i++) {
        if (commandIsAllowlisted[i]) continue;
        const command = classifierResult.commands[i];
        if (!command) continue;
        notAllowlistedClassifierCommands.push(command);
      }

      smartAllowlistNotInAllowlist = normalizeAllowlistCandidates(
        notAllowlistedClassifierCommands.flatMap(command =>
          generateAllowlistCandidatesFromCommandText(command)
        )
      );
      // Collect suggested allowlist entries from the classifier for commands not in allowlist
      smartAllowlistSuggestedEntries = notAllowlistedClassifierCommands
        .map(command => command.suggestedAllowlistEntry)
        .filter((entry): entry is string => typeof entry === "string")
        .filter(entry =>
          // Only include suggestions that are also in the candidate list
          smartAllowlistNotInAllowlist.includes(entry)
        );
      if (smartAllowlistNotInAllowlist.length > 0) {
        const displayCommands = resolveDefaultAllowlistOptionIds(
          smartAllowlistNotInAllowlist,
          smartAllowlistSuggestedEntries
        );
        const notInAllowlistReasonText =
          displayCommands.length > 0
            ? displayCommands.join(", ")
            : smartAllowlistNotInAllowlist.join(", ");
        smartAllowlistPromptReasons.push(
          `Not in allowlist: ${notInAllowlistReasonText}`
        );
      }

      // Track whether classifier-derived commands passed user allowlist and
      // command blocklist checks before shared autorun guards are applied below.
      smartAllowlistWantsAutoApprove =
        allInAllowlist && commandBlocklistedCommands.length === 0;

      if (smartAllowlistWantsAutoApprove) {
        logger.info(
          ctx,
          "Smart allowlist: all commands in allowlist, will check security",
          {
            commandCount: classifiedCommandNames.length,
          }
        );
      }
    }

    // In "Ask Every Time" mode, we should NEVER pre-approve commands,
    // regardless of sandbox policy. This ensures "Ask Every Time" truly asks every time.
    const isAskEveryTimeMode = approvalMode === "ask-every-time";

    // Don't pre-approve if:
    // - We're in "Ask Every Time" mode, OR
    // - The requested policy is insecure_none in allowlist mode
    const preapprovedPolicy =
      isAskEveryTimeMode ||
      (requestedPolicy.type === "insecure_none" && approvalMode === "allowlist")
        ? undefined // Don't pre-approve anything - require explicit approval
        : userConfiguredPolicy;

    // Create a set of commands that are potentially preapproved based on our sandboxing level.
    const commands = commandsForPermissionChecks.map(
      (cmd, i) =>
        new ApprovableCommand(
          cmd,
          requestedPolicy,
          preapprovedPolicy,
          commandMatchFormsPerCommand[i]
        )
    );

    // If we have no trustworthy command extraction, this likely indicates a
    // parser bypass (e.g., ```echo test```). Classifier-derived commands are
    // acceptable when that extraction path is active.
    if (
      (commandsForPermissionChecks.length === 0 ||
        (parsingFailed && !isSmartAllowlistActive)) &&
      !isUnrestricted
    ) {
      logger.info(ctx, "Shell permissions: prompting after parser miss", {
        toolCallId: options.toolCallId,
        approvalMode,
        requestedPolicyType: sandboxPolicyTypeForLogging(requestedPolicy),
        userConfiguredPolicyType:
          sandboxPolicyTypeForLogging(userConfiguredPolicy),
        isSmartAllowlistActive,
        parsingFailed,
        parserCommandCount: commandsForPermissionChecks.length,
        hasSmartModeApprovalReason: smartModeApprovalReason !== undefined,
        hasSmartModeApprovalRequestId: smartModeApprovalRequestId !== undefined,
      });
      // Issue approval request - construct proper approval structure
      const approval: ShellOperation = {
        type: OperationType.Shell,
        toolCallId: options.toolCallId,
        details: {
          command,
          workingDirectory: options.workingDirectory,
          timeout: options.timeout,
          reason:
            smartModeApprovalReason ??
            (parsingFailed
              ? "Parser failed to parse command (possible bypass)"
              : "Parser found no commands (possible bypass)"),
          isSandboxAvailable: false,
          isSandboxEnabled: false,
          canAllowlist: false,
          notAllowedCommands: [],
          smartModeApprovalReason,
          smartModeApprovalRequestId,
        },
      };
      const sandboxResult =
        await this.pendingDecisionStore.requestApproval(approval);
      if (!sandboxResult.approved) {
        return {
          kind: "block",
          reason: { type: "userRejected", reason: sandboxResult.reason },
        };
      } else {
        // User approved - use requested policy
        const mergedPolicy =
          await this.applyServerAndAdminPolicies(requestedPolicy);
        return { kind: "allow", policy: mergedPolicy };
      }
    }

    // Check the hard deny list before any user approval path.
    const hasHardDeny = await this.hasHardDeny(ctx, commands);
    if (hasHardDeny) {
      return { kind: "block", reason: { type: "permissionsConfig" } };
    }

    // --- denies past this point can be manually approved but not allowlisted ---

    // An output redirect is allowlist-safe when it only targets the original
    // stdout/stderr or /dev/null, or when it writes to a static path the
    // effective sandbox permits: workspace paths, plus host temp only under
    // System read access. Workspace has a private per-invocation TMPDIR, so
    // host /tmp must not qualify for unsandboxed allowlist autorun.
    // Computed once here because it gates both the allowlist match below and
    // the "add to allowlist" prompt further down.
    const { allRedirectsAreWorkspaceFileSafe, redirectsAllowlistSafe } =
      await this.computeRedirectAllowlistSafety(
        options.parsingResult,
        options.workingDirectory,
        userConfiguredPolicy.type === "insecure_none" ||
          userConfiguredPolicy.readBoundary !== "workspace"
      );

    // Mark each command allowlisted (→ unsandboxed autorun) only when
    // `cmdIsAllowedByAllowlist` says so. It requires both an allowlist entry
    // match AND a safe redirect set; see its doc for the enumerated exceptions
    // and the H1 rationale. Commands that are not allowed fall through to
    // sandboxed autorun or a prompt via the normal autorun rules below.
    const autoRunControls = await this.teamSettingsService.getAutoRunControls();
    const unsandboxedPolicy: InternalSandboxPolicy = { type: "insecure_none" };
    for (const cmd of commands) {
      const allowed = await this.cmdIsAllowedByAllowlist(cmd, {
        redirectsAllowlistSafe,
        autoRunControls,
        applyTeamAllowlist: shouldApplyTeamShellAllowlist,
      });
      if (allowed) {
        cmd.approveWithPolicy(unsandboxedPolicy);
      }
    }

    // Apply team blocklists and delete file protection after allowlists so
    // security denies take precedence.
    for (const cmd of commands) {
      if (autoRunControls && this.isInTeamBlocklist(autoRunControls, cmd)) {
        cmd.deny();
      }
    }
    const deleteProtectionEnabled =
      await this.teamSettingsService.getDeleteFileProtection();
    if (deleteProtectionEnabled) {
      for (const cmd of commands) {
        if (cmd.command.name === "rm") {
          cmd.deny();
        }
      }
    }

    const approvalDecisionFacts = this.buildShellApprovalDecisionFacts({
      commands,
      autoRunControls,
      shouldApplyTeamShellAllowlist,
      deleteProtectionEnabled,
      softDenylistedCommands: commandBlocklistedCommands,
    });

    // Readonly user configuration is a hard ceiling for shell execution:
    // allowlists can reduce prompts, but they cannot grant write or
    // unsandboxed execution in a readonly session.
    if (
      userConfiguredPolicy.type === "workspace_readonly" &&
      requestedPolicy.type !== "workspace_readonly"
    ) {
      logger.info(ctx, "Shell permissions: blocked by readonly mode");
      return {
        kind: "block",
        reason: { type: "permissionsConfig", isReadonly: true },
      };
    }

    const hookForcesPrompt = isForcePromptHookApprovalRequirement(
      options.hookApprovalRequirement
    );
    const hookPromptReason = options.hookApprovalRequirement?.reason;

    // Handle automatic approval once all allowlist, denylist, readonly, and
    // sandbox facts have been evaluated. Commands with an unsafe redirect were
    // deliberately left unallowlisted above, so they cannot be escalated to
    // unsandboxed autorun here.
    let autoApprovalPolicy = hookForcesPrompt
      ? undefined
      : this.getShellAutoApprovalPolicy({
          approvalMode,
          isUnrestricted,
          requestedPolicy,
          facts: approvalDecisionFacts,
          preserveRequestedPolicyForAllowlistedCommands: isSmartAllowlistActive,
        });
    // Capture allowlist escalation before any admin Workspace clamp rewrites
    // the policy. Smart Mode / Auto-review BLOCK still trusts the allowlist
    // for autorun; the clamp only keeps that autorun sandboxed.
    const allowlistEscalatedToInsecureNone =
      autoApprovalPolicy !== undefined &&
      approvalDecisionFacts.allCommandsAllowlisted &&
      autoApprovalPolicy.type === "insecure_none" &&
      "allowlistEscalated" in autoApprovalPolicy &&
      autoApprovalPolicy.allowlistEscalated === true;
    if (autoApprovalPolicy?.type === "insecure_none") {
      const adminReadBoundary = await this.resolveAdminReadBoundary();
      if (adminReadBoundary === "workspace") {
        if (explicitlyRequestedInsecureNone) {
          // The model deliberately requested a whole-command escape. Do not
          // let an allowlist match bypass the approval required for that
          // escalation.
          autoApprovalPolicy = undefined;
        } else if (requestedPolicy.type !== "insecure_none") {
          // Allowlist and unrestricted-mode auto-approval may normally replace
          // a sandboxed request with insecure_none. An admin Workspace boundary
          // is a ceiling on those implicit escalations, so retain the requested
          // sandbox and let the normal admin merge attach the read boundary.
          autoApprovalPolicy = requestedPolicy;
        }
      }
    }
    const smartModeApprovalBypassedByAllowlist =
      autoApprovalPolicy !== undefined && allowlistEscalatedToInsecureNone;
    if (
      autoApprovalPolicy &&
      (smartModeApprovalReason === undefined ||
        smartModeApprovalBypassedByAllowlist)
    ) {
      if (
        isSmartAllowlistActive &&
        approvalDecisionFacts.allCommandsPreapproved &&
        !approvalDecisionFacts.allCommandsAllowlisted
      ) {
        // Missing shell allowlist entries are not blockers for sandboxed
        // autorun: the user's sandbox policy already preapproved these
        // commands.
        logger.info(
          ctx,
          "Shell permissions: all commands allowed by sandbox policy"
        );
      }
      const mergedPolicy =
        await this.applyServerAndAdminPolicies(autoApprovalPolicy);
      logger.info(ctx, "Shell permissions: auto-approved shell command", {
        toolCallId: options.toolCallId,
        approvalMode,
        requestedPolicyType: sandboxPolicyTypeForLogging(requestedPolicy),
        userConfiguredPolicyType:
          sandboxPolicyTypeForLogging(userConfiguredPolicy),
        autoApprovalPolicyType: sandboxPolicyTypeForLogging(autoApprovalPolicy),
        mergedPolicyType: sandboxPolicyTypeForLogging(mergedPolicy),
        isSmartAllowlistActive,
        smartModeApprovalBypassedByAllowlist,
        allCommandsRunnable: approvalDecisionFacts.allCommandsRunnable,
        allCommandsAllowlisted: approvalDecisionFacts.allCommandsAllowlisted,
        allCommandsPreapproved: approvalDecisionFacts.allCommandsPreapproved,
        hasSmartModeApprovalReason: smartModeApprovalReason !== undefined,
        commandCount: commands.length,
      });
      return { kind: "allow", policy: mergedPolicy };
    }

    // We can allowlist if team settings permit it and we're in allowlist mode OR ask-every-time mode.
    // In ask-every-time mode, users should still be able to add commands to their allowlist.
    let canAllowlist =
      (isSmartAllowlistActive ||
        ((!hasRedirects ||
          allRedirectsAreAllowlistSafe ||
          allRedirectsAreWorkspaceFileSafe) &&
          !parsingFailed)) &&
      (approvalMode === "allowlist" || approvalMode === "ask-every-time") &&
      approvalDecisionFacts.canAllowlistInPrompt;

    const approvalReasons: string[] = [];
    const suppressSecondaryApprovalReasons =
      smartModeApprovalReason !== undefined;
    const shouldAddTeamAllowlistPromptReason =
      approvalDecisionFacts.notInTeamAllowlist.length > 0 &&
      (approvalDecisionFacts.hasSecurityDenies ||
        approvalDecisionFacts.hasSoftDenies ||
        !approvalDecisionFacts.allCommandsRunnable);

    if (smartModeApprovalReason !== undefined) {
      approvalReasons.push(smartModeApprovalReason);
    }
    if (hookForcesPrompt) {
      if (!suppressSecondaryApprovalReasons) {
        approvalReasons.push(
          hookPromptReason
            ? `Hook requested approval: ${hookPromptReason}`
            : "Hook requested approval"
        );
      }
      canAllowlist = false;
    }

    if (commandBlocklistPromptReasons.length > 0) {
      if (!suppressSecondaryApprovalReasons) {
        approvalReasons.push(...commandBlocklistPromptReasons);
      }
      canAllowlist = false;
    }

    if (!suppressSecondaryApprovalReasons) {
      if (isSmartAllowlistActive && smartAllowlistPromptReasons.length > 0) {
        approvalReasons.push(...smartAllowlistPromptReasons);
      } else {
        if (approvalDecisionFacts.unapprovedCommands.length > 0) {
          const allowlistCandidatePatterns = this.generateAllowlistPatterns(
            approvalDecisionFacts.unapprovedCommands.map(cmd => cmd.command)
          );
          const notInAllowlistReasonCommands = resolveDefaultAllowlistOptionIds(
            allowlistCandidatePatterns
          );
          const notInAllowlistReasonText =
            notInAllowlistReasonCommands.length > 0
              ? notInAllowlistReasonCommands.join(", ")
              : approvalDecisionFacts.unapprovedCommands
                  .map(cmd => cmd.command.fullText)
                  .join(", ");
          approvalReasons.push(`Not in allowlist: ${notInAllowlistReasonText}`);
        }
      }
    }

    // Security-deny reasons should not include full command text, since
    // arguments and paths may contain sensitive data.
    if (approvalDecisionFacts.hasSecurityDenies) {
      if (!suppressSecondaryApprovalReasons) {
        if (approvalDecisionFacts.rmDeniedByDeleteProtection.length > 0) {
          approvalReasons.push("Delete protection is enabled");
        }
        if (approvalDecisionFacts.teamBlocklistedCommands.length > 0) {
          approvalReasons.push(
            `In team blocklist: ${approvalDecisionFacts.teamBlocklistedCommands.map(cmd => cmd.command.name).join(", ")}`
          );
        }
      }
      canAllowlist = false;
    }

    // Team allowlist misses make prompts non-allowlistable, but do not veto
    // commands that are already runnable via user allowlist, team allowlist,
    // or sandbox policy.
    if (shouldAddTeamAllowlistPromptReason) {
      const notInTeamAllowlistText = approvalDecisionFacts.notInTeamAllowlist
        .map(cmd => cmd.command.fullText)
        .join(", ");
      logger.info(ctx, "Shell permissions: commands not in team allowlist", {
        commandCount: approvalDecisionFacts.notInTeamAllowlist.length,
      });
      if (!suppressSecondaryApprovalReasons) {
        approvalReasons.push(
          `Not in team allowlist: ${notInTeamAllowlistText}`
        );
      }
      canAllowlist = false;
    }

    const reason = approvalReasons.join(" • ");

    const allowlistCandidates: string[] = [];
    if (canAllowlist) {
      // When Auto-review blocks a sandbox-preapproved command, a user
      // allowlist entry escalates past the smart-mode block on the next run
      // (see smartModeApprovalBypassedByAllowlist).
      const allowlistCandidateCommands =
        smartModeApprovalReason !== undefined
          ? commands.filter(cmd => cmd.state !== "allowlisted")
          : approvalDecisionFacts.unapprovedCommands;
      allowlistCandidates.push(
        ...this.generateAllowlistPatterns(
          allowlistCandidateCommands.map(cmd => cmd.command)
        )
      );
    }
    const useSmartAllowlistPromptContext =
      isSmartAllowlistActive && smartAllowlistPromptReasons.length > 0;
    const notAllowedCommands = useSmartAllowlistPromptContext
      ? smartAllowlistNotInAllowlist
      : allowlistCandidates;
    const suggestedAllowlistEntries =
      useSmartAllowlistPromptContext &&
      smartAllowlistSuggestedEntries.length > 0
        ? smartAllowlistSuggestedEntries
        : undefined;

    const isSandboxAvailable =
      requestedPolicy.type !== "insecure_none" &&
      userConfiguredPolicy.type !== "insecure_none";
    const isSandboxEnabled = requestedPolicy.type !== "insecure_none";
    const approvalReasonTypes = [
      smartModeApprovalReason !== undefined ? "smart_mode_approval" : undefined,
      hookForcesPrompt ? "hook_forces_prompt" : undefined,
      commandBlocklistPromptReasons.length > 0
        ? "command_blocklist"
        : undefined,
      isSmartAllowlistActive && smartAllowlistPromptReasons.length > 0
        ? "smart_allowlist_miss"
        : undefined,
      approvalDecisionFacts.unapprovedCommands.length > 0
        ? "unapproved_commands"
        : undefined,
      approvalDecisionFacts.hasSecurityDenies ? "security_denies" : undefined,
      shouldAddTeamAllowlistPromptReason ? "team_allowlist_miss" : undefined,
    ].filter((reasonType): reasonType is string => reasonType !== undefined);
    logger.info(ctx, "Shell permissions: requesting shell approval", {
      toolCallId: options.toolCallId,
      approvalMode,
      requestedPolicyType: sandboxPolicyTypeForLogging(requestedPolicy),
      userConfiguredPolicyType:
        sandboxPolicyTypeForLogging(userConfiguredPolicy),
      isSandboxAvailable,
      isSandboxEnabled,
      canAllowlist,
      isSmartAllowlistActive,
      hasSmartModeApprovalReason: smartModeApprovalReason !== undefined,
      hasSmartModeApprovalRequestId: smartModeApprovalRequestId !== undefined,
      hookForcesPrompt,
      approvalReasonTypes,
      commandCount: commands.length,
      unapprovedCommandCount: approvalDecisionFacts.unapprovedCommands.length,
      deniedCommandCount: approvalDecisionFacts.deniedCommands.length,
      notInTeamAllowlistCount: approvalDecisionFacts.notInTeamAllowlist.length,
      notAllowedCommandCount: notAllowedCommands.length,
      suggestedAllowlistEntryCount: suggestedAllowlistEntries?.length ?? 0,
      allCommandsRunnable: approvalDecisionFacts.allCommandsRunnable,
      allCommandsAllowlisted: approvalDecisionFacts.allCommandsAllowlisted,
      allCommandsPreapproved: approvalDecisionFacts.allCommandsPreapproved,
      hasSecurityDenies: approvalDecisionFacts.hasSecurityDenies,
      hasSoftDenies: approvalDecisionFacts.hasSoftDenies,
    });

    const approval = {
      type: OperationType.Shell,
      toolCallId: options.toolCallId,
      details: {
        command,
        workingDirectory: options.workingDirectory,
        timeout: options.timeout,
        reason,
        isSandboxAvailable:
          approvalMode === "allowlist" ? isSandboxAvailable : false,
        // In allowlist mode approval uses the requested policy; unrestricted
        // mode approval always runs without sandboxing.
        isSandboxEnabled:
          approvalMode === "allowlist" ? isSandboxEnabled : false,
        canAllowlist,
        notAllowedCommands,
        suggestedAllowlistEntries,
        smartModeApprovalReason,
        smartModeApprovalRequestId,
      },
    } as ShellOperation;

    const sandboxResult =
      await this.pendingDecisionStore.requestApproval(approval);
    if (!sandboxResult.approved) {
      return {
        kind: "block",
        reason: { type: "userRejected", reason: sandboxResult.reason },
      };
    } else {
      // In unrestricted mode, run without sandboxing
      // In allowlist mode, use the requested policy
      const policyToUse =
        approvalMode === "unrestricted"
          ? ({ type: "insecure_none" } as InternalSandboxPolicy)
          : requestedPolicy;
      const mergedPolicy = await this.applyServerAndAdminPolicies(policyToUse);
      return { kind: "allow", policy: mergedPolicy };
    }
  }

  /**
   * @see PermissionsService.isShellCommandFullyAllowlisted
   *
   * Mirrors the matching logic in {@link shouldBlockShellCommand} but only
   * answers the "would this auto-approve without prompting?" question. We
   * deliberately reuse the same helpers — {@link classifierCommandMatchForms},
   * {@link normalizeAllowlistCandidates}, {@link ApprovableCommand},
   * {@link hasHardDeny}, {@link isInShellAllowlist},
   * {@link isInTeamAllowlist}, {@link isInTeamBlocklist} — so that any future
   * tweak to the allowlist matcher stays in sync between this precheck and
   * the canonical block decision.
   */
  async isShellCommandFullyAllowlisted(
    parentCtx: Context,
    _command: string,
    options: {
      workingDirectory: string;
      parsingResult: ShellCommandParsingResult;
      classifierResult?: CommandClassifierResult;
      toolCallId?: string;
    }
  ): Promise<boolean> {
    const ctx = parentCtx.withName(
      "InteractivePermissionsService.isShellCommandFullyAllowlisted"
    );
    const perms = await this.getPermissions();
    const shouldApplyTeamShellAllowlist =
      !perms.dashboardTerminalAllowlistOverriddenByPermissionsFile;

    // Only the allowlist approval mode has a meaningful "fully allowlisted"
    // bypass. In ask-every-time we always prompt; in unrestricted Auto/Smart
    // Mode is not the gate anyway and we want the classifier or normal flow
    // to keep running unchanged.
    if (perms.approvalMode !== "allowlist") {
      return false;
    }

    // Workspace_readonly is a hard ceiling — keep the classifier path so the
    // existing readonly enforcement in shouldBlockShellCommand stays
    // authoritative.
    if (perms.userConfiguredPolicy.type === "workspace_readonly") {
      return false;
    }

    // A file-writing redirect to an unsafe target means the invocation is not an
    // allowlist match even when the command name is allowlisted (same gate as
    // shouldBlockShellCommand, via the shared `cmdIsAllowedByAllowlist` inputs). Fall through
    // so the normal flow sandboxes or prompts instead of treating it as fully
    // allowlisted.
    const { redirectsAllowlistSafe } =
      await this.computeRedirectAllowlistSafety(
        options.parsingResult,
        options.workingDirectory,
        perms.userConfiguredPolicy.type === "insecure_none" ||
          perms.userConfiguredPolicy.readBoundary !== "workspace"
      );
    if (!redirectsAllowlistSafe) {
      return false;
    }

    const classifierResult = options.classifierResult;
    const usableClassifierResult =
      classifierResult !== undefined &&
      !classifierResult.classificationFailed &&
      classifierResult.commands.length > 0
        ? classifierResult
        : undefined;
    const isSmartAllowlistActive =
      (perms.smartAllowlistEnabled ?? false) &&
      usableClassifierResult !== undefined;

    // Without a trustworthy parser AND no smart-allowlist rescue, fall
    // through. This matches the parser-bypass guard in shouldBlockShellCommand.
    if (options.parsingResult.parsingFailed && !isSmartAllowlistActive) {
      return false;
    }

    const executableCommands = options.parsingResult.executableCommands;
    const commandsForPermissionChecks = isSmartAllowlistActive
      ? usableClassifierResult.commands.map(
          classifierCommandToExecutableCommand
        )
      : executableCommands;
    if (commandsForPermissionChecks.length === 0) {
      return false;
    }

    const commandMatchFormsPerCommand: string[][] = isSmartAllowlistActive
      ? usableClassifierResult.commands.map(classifierCommandMatchForms)
      : commandsForPermissionChecks.map(cmd =>
          [cmd.fullText.trim()].filter(Boolean)
        );
    const commandBlocklistMatchFormsPerCommand: string[][] =
      usableClassifierResult !== undefined
        ? usableClassifierResult.commands.map(classifierCommandMatchForms)
        : commandMatchFormsPerCommand;

    // Build ApprovableCommands the same way shouldBlockShellCommand does so
    // hasHardDeny / isInShellAllowlist / isInTeamBlocklist see identical
    // input. Placeholder policies are fine — this precheck never mutates
    // command state nor returns a policy.
    const placeholderPolicy: InternalSandboxPolicy = { type: "insecure_none" };
    const commands = commandsForPermissionChecks.map(
      (cmd, i) =>
        new ApprovableCommand(
          cmd,
          placeholderPolicy,
          undefined,
          commandMatchFormsPerCommand[i]
        )
    );

    // Hard deny → fall through. Local-exec will reject at execution time
    // regardless, but we want the classifier path (with its block-reason
    // surfacing and Smart Mode telemetry) to remain authoritative.
    if (await this.hasHardDeny(ctx, commands)) {
      return false;
    }

    // Soft-deny / user-configured command blocklist.
    const userCommandBlocklist = normalizeAllowlistCandidates(
      perms.smartAllowlistDenylist ?? []
    );
    if (userCommandBlocklist.length > 0) {
      for (const forms of commandBlocklistMatchFormsPerCommand) {
        if (!forms || forms.length === 0) continue;
        if (
          userCommandBlocklist.some(entry =>
            commandMatchesBlocklistEntry(forms, entry)
          )
        ) {
          return false;
        }
      }
    }

    // Delete protection: `rm` must always prompt when the team toggled it on.
    const deleteProtectionEnabled =
      await this.teamSettingsService.getDeleteFileProtection();
    if (
      deleteProtectionEnabled &&
      commands.some(cmd => cmd.command.name === "rm")
    ) {
      return false;
    }

    const autoRunControls = await this.teamSettingsService.getAutoRunControls();
    if (
      autoRunControls !== undefined &&
      commands.some(cmd => this.isInTeamBlocklist(autoRunControls, cmd))
    ) {
      return false;
    }

    // Every command must be allowed by the shared `cmdIsAllowedByAllowlist` gate
    // (user or team allowlist match; redirects already verified safe above).
    for (const cmd of commands) {
      const allowed = await this.cmdIsAllowedByAllowlist(cmd, {
        redirectsAllowlistSafe,
        autoRunControls,
        applyTeamAllowlist: shouldApplyTeamShellAllowlist,
      });
      if (!allowed) {
        return false;
      }
    }

    return true;
  }

  /**
   * Applies file-based policies, Statsig defaults, admin controls, and
   * hardcoded policy to the given policy via mergeSandboxPolicies.
   *
   * Flow:
   * 1. Fold ~/.cursor/sandbox.json into the per-user policy (additive lists)
   * 2. Fold Statsig defaults into the perUser policy (baseline allowlist)
   * 3. Load <workspace>/.cursor/sandbox.json as per-repo policy
   * 4. Build teamAdmin policy from admin dashboard controls
   * 5. Merge perUser + perRepo + teamAdmin via mergeSandboxPolicies
   */
  private async applyServerAndAdminPolicies(
    policy: InternalSandboxPolicy
  ): Promise<InternalSandboxPolicy> {
    if (policy.type === "insecure_none") return policy;

    // Part 1: Fold ~/.cursor/sandbox.json into the UI-derived policy.
    // The file adds list entries (network allow/deny, additional paths) but
    // the UI policy always takes precedence for boolean/enum fields (type,
    // default, etc.) since those are the user's explicit choice.
    const withFileOverlay = await this.foldPerUserFilePolicy(policy);

    // Part 2: Fold Statsig defaults into the perUser policy.
    // Statsig defaults provide the baseline allowlist for all users.
    // Skip this step when the user has explicitly chosen "user_config_only" mode,
    // meaning they only want their own sandbox.json allowlist to apply.
    // No adminNetworkControlsEnabled check needed -- if admin has an allowlist,
    // replace semantics in the merge will override these defaults.
    const perUser = withFileOverlay.skipStatsigDefaults
      ? withFileOverlay
      : await this.applyStatsigDefaults(withFileOverlay);

    // Part 3: Load <workspace>/.cursor/sandbox.json as per-repo policy (full schema).
    const perRepo = await this.loadPerRepoFilePolicy(perUser.type);

    // Part 4: Build admin policy from dashboard controls.
    const teamAdmin = await this.buildTeamAdminPolicy(perUser.type);

    // Part 5: Preserve explicit allow-all requests from the incoming policy.
    // This covers model-requested network access that the user approved.
    // Merge semantics are "deny wins", so we need to restore allow-all after
    // merge to avoid narrowing an explicit user approval.
    const shouldPreserveAllowAllNetwork = isAllowAllNetworkByPolicy(
      policy.networkPolicy
    );

    // Part 6: Merge perUser + perRepo + teamAdmin + hardcoded policy.
    const { policy: merged } = await resolveSandboxPolicyForWorkspace(
      this.rootDirectories[0],
      {
        perUser,
        perRepo,
        teamAdmin,
      }
    );

    // Part 7: Restore explicit allow-all after merge. The user approved
    // full_network, so grant truly unrestricted network access — no deny list,
    // no proxy. This avoids the proxy path (which breaks programs that don't
    // respect HTTP_PROXY) and ensures "full network" means full network.
    if (shouldPreserveAllowAllNetwork) {
      return {
        ...(merged as SandboxedPolicy),
        networkPolicy: networkAllowAllPolicy(),
      };
    }

    return merged;
  }

  /**
   * Loads ~/.cursor/sandbox.json and folds its additive fields (network
   * allow/deny lists, additional paths) into the UI-derived per-user policy.
   *
   * Uses the full policy-loader schema so all sandbox.json fields are parsed,
   * but only list-valued fields are merged additively — boolean/enum fields
   * (type, networkPolicy.default, etc.) come from the UI policy
   * since those represent the user's explicit UI choices.
   */
  private async foldPerUserFilePolicy(
    uiPolicy: SandboxedPolicy
  ): Promise<SandboxedPolicy> {
    // Pass homedir() as baseDir so relative paths like ./foo resolve to $HOME/foo
    const filePolicy = await loadSandboxPolicyFromFileOrUndefined(
      this.perUserSandboxConfigPath,
      homedir()
    );
    if (!filePolicy || filePolicy.type === "insecure_none") return uiPolicy;

    // Merge network allow/deny lists additively (union), but preserve the
    // UI policy's `default` since that's the user's explicit choice (the file
    // is lower priority for enum/boolean fields).
    let mergedNetworkPolicy = mergeNetworkPolicies(
      filePolicy.networkPolicy,
      uiPolicy.networkPolicy
    );
    if (mergedNetworkPolicy && uiPolicy.networkPolicy?.default !== undefined) {
      mergedNetworkPolicy = {
        ...mergedNetworkPolicy,
        default: uiPolicy.networkPolicy.default,
      };
    }

    // Merge readonly paths additively (union).
    const mergedReadonlyPaths = mergePathsUnion(
      filePolicy.additionalReadonlyPaths,
      uiPolicy.additionalReadonlyPaths
    );

    const base = {
      ...uiPolicy,
      networkPolicy: mergedNetworkPolicy,
      additionalReadonlyPaths:
        mergedReadonlyPaths.length > 0 ? mergedReadonlyPaths : undefined,
    };

    // For readwrite policies, also merge additionalReadwritePaths.
    if (
      uiPolicy.type === "workspace_readwrite" &&
      filePolicy.type === "workspace_readwrite"
    ) {
      const mergedReadwritePaths = mergePathsUnion(
        filePolicy.additionalReadwritePaths,
        uiPolicy.additionalReadwritePaths
      );
      return {
        ...base,
        additionalReadwritePaths:
          mergedReadwritePaths.length > 0 ? mergedReadwritePaths : undefined,
      } as SandboxedPolicy;
    }

    return base as SandboxedPolicy;
  }

  /**
   * Applies Statsig default network allowlist to the policy.
   * These provide a baseline set of domains (e.g. npm, pypi) that all users
   * should have access to.
   *
   * Two branches:
   * - allow-all policy → skip (don't introduce restrictions)
   * - otherwise → enable network with deny-default + defaults allowlist
   */
  private async applyStatsigDefaults(
    policy: SandboxedPolicy
  ): Promise<SandboxedPolicy> {
    const defaults =
      await this.teamSettingsService.getDefaultNetworkAllowlist();
    if (!defaults.available || defaults.allowlist.length === 0) return policy;

    // If user already has allow-all network, don't introduce restrictions
    if (isAllowAllNetworkByPolicy(policy.networkPolicy)) {
      return policy;
    }

    // Otherwise, merge Statsig defaults into the policy to enable
    // allowlist-filtered network. Merge with any existing network policy
    // (e.g. deny rules from the user's ~/.cursor/sandbox.json) so user
    // deny rules are preserved.
    const statsigNetworkPolicy = {
      default: "deny" as const,
      allow: deduplicateStrings(defaults.allowlist),
    };
    return {
      ...policy,
      networkPolicy: mergeNetworkPolicies(
        policy.networkPolicy,
        statsigNetworkPolicy
      ),
    };
  }

  /**
   * Loads <workspace>/.cursor/sandbox.json as a full SandboxPolicy.
   * Returns the policy coerced to the given base type, or undefined if
   * no file exists, the file is invalid, or the file's type doesn't match.
   */
  private async loadPerRepoFilePolicy(
    baseType: SandboxedPolicy["type"]
  ): Promise<SandboxedPolicy | undefined> {
    const rootDir = this.rootDirectories[0];
    if (!rootDir) return undefined;

    // Pass rootDir as baseDir so relative paths like ./foo resolve to <workspace>/foo
    const filePolicy = await loadSandboxPolicyFromFileOrUndefined(
      join(rootDir, ".cursor", "sandbox.json"),
      rootDir
    );
    if (!filePolicy || filePolicy.type === "insecure_none") return undefined;

    // If the file specifies a different sandboxed type, coerce to baseType
    // to satisfy the mergeSandboxPolicies same-type requirement.
    if (filePolicy.type !== baseType) {
      return makeSandboxedPolicy(baseType, {
        networkPolicy: filePolicy.networkPolicy,
        additionalReadonlyPaths: filePolicy.additionalReadonlyPaths,
        ...("additionalReadwritePaths" in filePolicy
          ? { additionalReadwritePaths: filePolicy.additionalReadwritePaths }
          : {}),
        disableTmpWrite: filePolicy.disableTmpWrite,
        networkPolicyStrict: filePolicy.networkPolicyStrict,
      });
    }

    return filePolicy as SandboxedPolicy;
  }

  /**
   * Builds a SandboxPolicy from admin dashboard controls only (no Statsig defaults).
   * Returns undefined when the admin has no opinion on any control.
   */
  private async buildTeamAdminPolicy(
    baseType: SandboxedPolicy["type"]
  ): Promise<SandboxedPolicy | undefined> {
    const networkPolicy = await this.buildTeamAdminNetworkPolicy(baseType);
    const readBoundary = await this.resolveAdminReadBoundary();

    if (readBoundary === undefined) {
      return networkPolicy;
    }

    return {
      ...(networkPolicy ?? makeSandboxedPolicy(baseType)),
      readBoundary,
    };
  }

  /**
   * Resolves the admin "Agent Read Access" clamp.
   *
   * Returns undefined unless the admin requires Workspace, so that a System
   * setting stays "no opinion" and leaves the user and repo policies alone.
   * The server already forces System when the feature gate is off, so no
   * separate client-side gate check is needed.
   */
  private async resolveAdminReadBoundary(): Promise<"workspace" | undefined> {
    const { readBoundary } =
      await this.teamSettingsService.getSandboxingControls();
    return readBoundary === "workspace" ? "workspace" : undefined;
  }

  /**
   * Builds the network half of the admin policy from the team allow/deny lists.
   * Returns undefined when admin network controls are off or the admin has no
   * network opinion.
   */
  private async buildTeamAdminNetworkPolicy(
    baseType: SandboxedPolicy["type"]
  ): Promise<SandboxedPolicy | undefined> {
    if (!this.adminNetworkControlsEnabled) return undefined;

    const controls = await this.teamSettingsService.getNetworkAccessControls();

    // Fail-closed: if admin fetch failed, disable network entirely
    if (!controls.available) {
      return makeSandboxedPolicy(baseType, {
        networkPolicy: networkDisabledPolicy(),
      });
    }

    // No admin opinion -- return undefined so user policy passes through
    if (controls.allowlist.length === 0 && controls.denylist.length === 0) {
      return undefined;
    }

    // Build admin policy -- only set fields the admin has an opinion on.
    const adminNetworkPolicy: {
      default?: "deny";
      allow?: string[];
      deny?: string[];
    } = {};

    if (controls.allowlist.length > 0) {
      adminNetworkPolicy.default = "deny";
      adminNetworkPolicy.allow = deduplicateStrings(controls.allowlist);
    }

    if (controls.denylist.length > 0) {
      adminNetworkPolicy.deny = deduplicateStrings(controls.denylist);
    }

    return makeSandboxedPolicy(baseType, {
      networkPolicy: adminNetworkPolicy,
    });
  }

  private async isInShellAllowlist(
    command: ApprovableCommand
  ): Promise<boolean> {
    const perms = await this.getPermissions();
    return perms.allow.some(
      entry =>
        this.isShellEntry(entry) &&
        command.matchForms.some(form => this.matchesShell(entry, form))
    );
  }

  private isInTeamBlocklist(
    autoRunControls: AutoRunControls,
    command: ApprovableCommand
  ): boolean {
    return autoRunControls.blocked.some(blockedCmd =>
      this.matchesAutoRunCommand(command.command.fullText, blockedCmd)
    );
  }

  private isInTeamAllowlist(
    autoRunControls: AutoRunControls,
    command: ApprovableCommand
  ): boolean {
    return autoRunControls.allowed.some(allowedCmd =>
      this.matchesAutoRunCommand(command.command.fullText, allowedCmd)
    );
  }

  /**
   * Compute, once per invocation, whether the command's redirects keep it
   * eligible to match the shell allowlist. Returns the two sub-signals the
   * "add to allowlist" prompt also needs, plus the combined verdict
   * (`redirectsAllowlistSafe`) consumed by {@link cmdIsAllowedByAllowlist}. See
   * `cmdIsAllowedByAllowlist` for the enumerated safe-redirect exceptions and
   * the H1 rationale.
   */
  private async computeRedirectAllowlistSafety(
    parsingResult: ShellCommandParsingResult,
    workingDirectory: string,
    allowTmpRedirects: boolean
  ): Promise<{
    allRedirectsAreAllowlistSafe: boolean;
    allRedirectsAreWorkspaceFileSafe: boolean;
    redirectsAllowlistSafe: boolean;
  }> {
    const hasRedirects = parsingResult.hasRedirects;
    const parsingFailed = parsingResult.parsingFailed;
    const allRedirectsAreAllowlistSafe =
      parsingResult.allRedirectsAreDevNull === true;
    const allRedirectsAreWorkspaceFileSafe =
      hasRedirects && !allRedirectsAreAllowlistSafe && !parsingFailed
        ? await areShellRedirectsAllowlistSafeForWorkspace({
            parsingResult,
            workingDirectory,
            rootDirectories: this.rootDirectories,
            allowTmpRedirects,
          })
        : false;
    const redirectsAllowlistSafe = !hasUnsafeWriteRedirect({
      parsingResult,
      hasRedirects,
      parsingFailed,
      allRedirectsAreAllowlistSafe,
      allRedirectsAreWorkspaceFileSafe,
    });
    return {
      allRedirectsAreAllowlistSafe,
      allRedirectsAreWorkspaceFileSafe,
      redirectsAllowlistSafe,
    };
  }

  /**
   * `cmdIsAllowedByAllowlist` is the single source of truth for whether one parsed shell
   * command matches the user's (or team's) shell allowlist and may therefore
   * autorun **unsandboxed**. Both the live approval path
   * (`shouldBlockShellCommand`) and the Auto/Smart-Mode precheck
   * (`isShellCommandFullyAllowlisted`) go through here so they can never drift.
   *
   * Fixes HackerOne #3694078 / SECX-2400 ("Command injection in Windows Cursor
   * Agent via ls output redirection"). An allowlist entry for a base command
   * (e.g. `ls`) authorises the *command*, not an arbitrary file write. Before
   * this fix, `ls > $env:LOCALAPPDATA\cursor-agent\cursor-agent.ps1` counted as
   * a match purely because `ls` was allowlisted, so it autoran unsandboxed and
   * the `>` overwrote the agent launcher — code execution on next launch, with
   * no sandbox on the Windows CLI to stop the write.
   *
   * A command is allowed iff BOTH hold:
   *   (a) it matches a user or team allowlist entry (`matchesShell` /
   *       `matchesAutoRunCommand`), and
   *   (b) every redirect in the invocation is within the "safe redirect" set
   *       below — passed in as `allowlist.redirectsAllowlistSafe`, computed once
   *       per invocation from the parser signal (`allRedirectsAreDevNull`) and
   *       `areShellRedirectsAllowlistSafeForWorkspace`.
   *
   * Safe redirects that MAY be paired with an allowlist entry — and why none is
   * an arbitrary-write vector:
   *   1. Original stdout/stderr or `/dev/null`, incl. fd duplications like
   *      `2>&1` / `1>&2` — no file is created or modified. (PRs #103973, #107819)
   *   2. A static path inside a workspace root (`>`, `>>`, `&>`) — the write
   *      stays inside the user's own project. (PR #108548)
   *   3. A static path inside an allowed temp dir (`/tmp`, `/var/tmp`,
   *      `/var/folders`, `%TEMP%`) — scratch space, not persistence. (PR #108548)
   *   4. A plain stdin read (`< file`, `<& fd`) — reads only, never writes.
   *   5. A here-doc feeding stdin to a directly-parsed command — feeds stdin
   *      only, so it cannot write a file, and the receiver command must still
   *      match the allowlist itself. Command substitutions inside an unquoted
   *      here-doc body are extracted by the parser as separate executable
   *      commands and allowlist-checked independently. (PRs #109960, this one)
   *
   * Everything else is unsafe and makes the command NOT allowed: a target
   * outside the workspace/temp dirs, a dynamic target (`$env:...`, `$HOME/...`,
   * command substitution), a here-string, a here-doc the parser could not
   * attribute to a command, `<>`
   * (read-write), an fd duplication toward a file, or a redirect the parser
   * could not resolve to a static target. When a command is not allowed the
   * caller does NOT prompt-or-block outright; it falls back to the normal
   * autorun rules: run under the sandbox if one is available (which contains
   * the write), otherwise prompt the user.
   */
  private async cmdIsAllowedByAllowlist(
    command: ApprovableCommand,
    allowlist: {
      redirectsAllowlistSafe: boolean;
      autoRunControls: AutoRunControls | undefined;
      applyTeamAllowlist: boolean;
    }
  ): Promise<boolean> {
    // (b) An unsafe redirect means the allowlist entry does not cover the whole
    // invocation, so it is not a match regardless of the command name.
    if (!allowlist.redirectsAllowlistSafe) {
      return false;
    }
    // (a) The command name/args must match a user or team allowlist entry.
    if (await this.isInShellAllowlist(command)) {
      return true;
    }
    return (
      allowlist.applyTeamAllowlist &&
      allowlist.autoRunControls !== undefined &&
      this.isInTeamAllowlist(allowlist.autoRunControls, command)
    );
  }

  private buildShellApprovalDecisionFacts({
    commands,
    softDenylistedCommands,
    autoRunControls,
    shouldApplyTeamShellAllowlist,
    deleteProtectionEnabled,
  }: {
    commands: ApprovableCommand[];
    softDenylistedCommands: string[];
    autoRunControls: AutoRunControls | undefined;
    shouldApplyTeamShellAllowlist: boolean;
    deleteProtectionEnabled: boolean;
  }): ShellApprovalDecisionFacts {
    const deniedCommands = commands.filter(cmd => cmd.state === "denied");
    const unapprovedCommands = commands.filter(
      cmd => cmd.state === "approvable"
    );
    const notInTeamAllowlist =
      shouldApplyTeamShellAllowlist && autoRunControls?.enabled
        ? commands.filter(cmd => !this.isInTeamAllowlist(autoRunControls, cmd))
        : [];
    const teamBlocklistedCommands = deniedCommands.filter(
      cmd =>
        autoRunControls !== undefined &&
        this.isInTeamBlocklist(autoRunControls, cmd)
    );
    const rmDeniedByDeleteProtection = deleteProtectionEnabled
      ? deniedCommands.filter(cmd => cmd.command.name === "rm")
      : [];

    return {
      hasSecurityDenies: deniedCommands.length > 0,
      hasSoftDenies: softDenylistedCommands.length > 0,
      hasTeamAllowlistMisses: notInTeamAllowlist.length > 0,
      allCommandsRunnable: commands.every(cmd => cmd.isRunnable()),
      allCommandsAllowlisted: commands.every(
        cmd => cmd.state === "allowlisted"
      ),
      allCommandsPreapproved: commands.every(
        cmd => cmd.state === "preapproved"
      ),
      canAllowlistInPrompt:
        deniedCommands.length === 0 && notInTeamAllowlist.length === 0,
      unapprovedCommands,
      deniedCommands,
      notInTeamAllowlist,
      teamBlocklistedCommands,
      rmDeniedByDeleteProtection,
    };
  }

  private getShellAutoApprovalPolicy({
    approvalMode,
    isUnrestricted,
    requestedPolicy,
    facts,
    preserveRequestedPolicyForAllowlistedCommands,
  }: {
    approvalMode: "allowlist" | "unrestricted" | "ask-every-time";
    isUnrestricted: boolean;
    requestedPolicy: InternalSandboxPolicy;
    facts: ShellApprovalDecisionFacts;
    preserveRequestedPolicyForAllowlistedCommands: boolean;
  }): InternalSandboxPolicy | undefined {
    if (
      facts.hasSecurityDenies ||
      facts.hasSoftDenies ||
      !facts.allCommandsRunnable
    ) {
      return undefined;
    }

    // Team allowlist misses constrain prompts, not autorun. If every command
    // is already runnable via user allowlist, team allowlist, or sandbox
    // preapproval, keep the existing autorun policy.
    if (isUnrestricted) {
      // Even in unrestricted mode, preserve an explicitly-requested readonly sandbox.
      // This is used by Ask mode and readonly subagents to force sandboxing even when
      // the user has enabled "Run Everything".
      return requestedPolicy.type === "workspace_readonly"
        ? requestedPolicy
        : { type: "insecure_none" };
    }

    if (approvalMode !== "allowlist") {
      return undefined;
    }

    if (
      facts.allCommandsAllowlisted &&
      !preserveRequestedPolicyForAllowlistedCommands
    ) {
      // An exact allowlist match grants unsandboxed autorun. A command carrying
      // an unsafe redirect is deliberately not marked allowlisted upstream (see
      // the allowlist loop in shouldBlockShellCommand), so it never reaches this
      // branch — it falls through to sandboxed autorun or a prompt instead.
      return { type: "insecure_none", allowlistEscalated: true };
    }

    return requestedPolicy;
  }

  private async getPermissions(): Promise<Permissions> {
    return await this.permissionsProvider.getPermissions();
  }

  private hasLocalShellControls(perms: Permissions): boolean {
    return (
      perms.allow.some(entry => this.isShellEntry(entry)) ||
      perms.deny.some(entry => this.isShellEntry(entry)) ||
      (perms.smartAllowlistDenylist?.length ?? 0) > 0
    );
  }

  private hasTeamShellControls(
    autoRunControls: AutoRunControls | undefined,
    shouldApplyTeamShellAllowlist = true
  ) {
    return (
      autoRunControls !== undefined &&
      ((shouldApplyTeamShellAllowlist &&
        (autoRunControls.enabled || autoRunControls.allowed.length > 0)) ||
        autoRunControls.blocked.length > 0)
    );
  }

  private async shouldPromptForEmptyPlainShellAllowlist(
    command: string,
    perms: Permissions
  ): Promise<boolean> {
    if (
      perms.approvalMode !== "allowlist" ||
      perms.userConfiguredPolicy.type !== "insecure_none" ||
      command.trim().length === 0 ||
      this.hasLocalShellControls(perms)
    ) {
      return false;
    }

    // Team shell controls and delete protection still need the normal parser-
    // aware checks below. Only the truly empty local/team shell policy can skip
    // parser-output matching and go straight to user approval.
    const [autoRunControls, deleteProtectionEnabled] = await Promise.all([
      this.teamSettingsService.getAutoRunControls(),
      this.teamSettingsService.getDeleteFileProtection(),
    ]);
    return (
      !this.hasTeamShellControls(
        autoRunControls,
        !perms.dashboardTerminalAllowlistOverriddenByPermissionsFile
      ) && !deleteProtectionEnabled
    );
  }

  private async requestApprovalForEmptyShellAllowlist(
    command: string,
    options: ShellCommandOptions,
    policyToRequest: InternalSandboxPolicy
  ): Promise<ShellCommandDecision> {
    const allowlistCandidates = this.getEmptyShellAllowlistCandidates(options);
    const approvalResult = await this.pendingDecisionStore.requestApproval({
      type: OperationType.Shell,
      toolCallId: options.toolCallId,
      details: {
        command,
        workingDirectory: options.workingDirectory,
        timeout: options.timeout,
        reason: options.smartModeApprovalReason ?? "Shell allowlist is empty",
        isSandboxAvailable: false,
        isSandboxEnabled: false,
        canAllowlist: allowlistCandidates.length > 0,
        notAllowedCommands: allowlistCandidates,
        smartModeApprovalReason: options.smartModeApprovalReason,
        smartModeApprovalRequestId: options.smartModeApprovalRequestId,
      },
    });

    if (!approvalResult.approved) {
      return {
        kind: "block",
        reason: { type: "userRejected", reason: approvalResult.reason },
      };
    }

    const mergedPolicy =
      await this.applyServerAndAdminPolicies(policyToRequest);
    return { kind: "allow", policy: mergedPolicy };
  }

  private getEmptyShellAllowlistCandidates(
    options: ShellCommandOptions
  ): string[] {
    const parsingResult = options.parsingResult;
    if (
      parsingResult.parsingFailed ||
      parsingResult.executableCommands.length === 0 ||
      (parsingResult.hasRedirects &&
        parsingResult.allRedirectsAreDevNull !== true)
    ) {
      return [];
    }

    return this.generateAllowlistPatterns(parsingResult.executableCommands);
  }

  /**
   * Admin command denylist: a deterministic hard block with no approval,
   * bypass, or allowlist path, enforced in every approval mode (including
   * unrestricted). A stacked model-Shell PR adds a stricter precheck for
   * model-authored commands on top of this execution-time check.
   */
  private async getAdminCommandDenylistBlock(
    ctx: Context,
    args: {
      command: string;
      parsingResult: ShellCommandParsingResult | undefined;
      toolCallId: string | undefined;
    }
  ): Promise<
    Extract<BlockReason, { type: "adminCommandDenylist" }> | undefined
  > {
    const blockedCommands = (
      await this.teamSettingsService.getAdminCommandDenylist()
    ).rules;
    if (blockedCommands.length === 0) {
      return undefined;
    }
    // Matching is best-effort at this layer: the raw command text is always a
    // match form, plus each executable command when the caller supplied a
    // real parse. It deliberately does NOT fail closed on empty or failed
    // parses — `skipApproval` callers include interactive shell mode, where
    // user-typed commands arrive with an intentionally empty parse, and
    // Pi-style executors that fabricate a single-form parse; failing closed
    // here would hard-block every such command for any team with a denylist.
    // Strict fail-closed handling of unanalyzable model-authored commands
    // belongs to the stacked model-Shell PR.
    const matchForms = args.parsingResult
      ? deriveAdminCommandDenylistMatchForms({
          command: args.command,
          parsingResult: args.parsingResult,
        })
      : [args.command];
    const matchedPattern = findMatchingAdminCommandDenylistPattern({
      matchForms,
      blockedCommands,
    });
    if (matchedPattern === undefined) {
      return undefined;
    }
    logger.info(
      ctx,
      "Admin command denylist hard-blocked shell at execution time",
      {
        toolCallId: args.toolCallId,
        parsingFailed: args.parsingResult?.parsingFailed ?? true,
        parserCommandCount: args.parsingResult?.executableCommands.length ?? 0,
      }
    );
    return { type: "adminCommandDenylist", pattern: matchedPattern };
  }

  private async hasHardDeny(
    _ctx: Context,
    commands: ApprovableCommand[]
  ): Promise<boolean> {
    const perms = await this.getPermissions();
    return commands.some(cmd =>
      perms.deny.some(
        entry =>
          this.isShellEntry(entry) &&
          cmd.matchForms.some(form => this.matchesShell(entry, form))
      )
    );
  }

  private isShellEntry(entry: string): boolean {
    return parseShellEntry(entry) !== null;
  }

  private isPathEntry(kind: "Read" | "Write", entry: string): boolean {
    const re = new RegExp(`^\\s*${kind}\\s*\\(`);
    return re.test(entry);
  }

  private matchesShell(entry: string, cmd: string): boolean {
    const parsed = parseShellEntry(entry);
    if (!parsed) return false;

    const command = cmd.trim();
    const base = this.extractBaseCommand(command);

    // Support syntax like "curl:*" or "npm run test:*" => base:args
    if (parsed.argsPattern !== null) {
      const argsText = command.includes(" ")
        ? command.slice(command.indexOf(" ") + 1).trim()
        : "";
      const baseOk =
        this.matchGlob(parsed.commandPattern, base) ||
        this.matchGlob(parsed.commandPattern, command);
      const argsOk = this.matchGlob(parsed.argsPattern, argsText);
      if (baseOk && argsOk) return true;
      // fall through to other matching modes if not matched
    }

    // Glob match against full command first, then prefix, then base command
    if (this.matchGlob(parsed.fullPattern, command)) return true;
    if (command.startsWith(`${parsed.fullPattern} `)) return true;
    if (this.matchGlob(parsed.fullPattern, base)) return true;
    if (base === parsed.fullPattern) return true;
    return false;
  }

  /**
   * Check if a file path is a cursor file and should be protected based on team settings.
   * @param pathComponents The path components relative to root directory
   * @returns BlockReason if blocked, null if not blocked
   */
  private async checkCursorFileProtection(
    pathComponents: string[]
  ): Promise<BlockReason | null> {
    const dotCursorProtection =
      await this.teamSettingsService.getDotCursorProtection();

    const isCursorFile = pathComponents.some(
      component =>
        component.toLowerCase() === ".cursor" ||
        component.toLowerCase() === ".vscode"
    );

    if (isCursorFile && dotCursorProtection) {
      // Allow .md/.mdc/.cursorrules files in .cursor/ without blocking
      const lastPathSegment =
        pathComponents[pathComponents.length - 1]?.toLowerCase() ?? "";
      const hasAllowedExtension =
        lastPathSegment.endsWith(".md") ||
        lastPathSegment.endsWith(".mdc") ||
        lastPathSegment === ".cursorrules";
      if (hasAllowedExtension) {
        return null;
      }
      return { type: "permissionsConfig" };
    }

    return null;
  }

  /**
   * Extract the base command from a command string (the first word)
   */
  private extractBaseCommand(command: string): string {
    const trimmed = command.trim();
    const spaceIndex = trimmed.indexOf(" ");
    return spaceIndex === -1 ? trimmed : trimmed.substring(0, spaceIndex);
  }

  /**
   * Generate allowlist patterns for commands
   * Matches the processCandidatesForAllowlist logic from VSCode
   */
  private generateAllowlistPatterns(
    commands: ShellCommandParsingResult_ExecutableCommand[]
  ): string[] {
    const result: string[] = [];

    // Composite shell commands that should include their first argument
    const compositeShellCommands = [
      "git",
      "npm",
      "yarn",
      "pnpm",
      "docker",
      "pip",
      "systemctl",
      "uv",
      "cargo",
      "bun",
      "npx",
    ];

    for (const cmd of commands) {
      if (isTerminalShellInterpreterAllowlistCandidate(cmd.name)) {
        continue;
      }
      if (
        compositeShellCommands.includes(cmd.name) &&
        cmd.args.length > 0 &&
        cmd.args[0].type === "word"
      ) {
        result.push(`${cmd.name} ${cmd.args[0].value}`);
      } else {
        result.push(cmd.name);
      }
    }

    return [...new Set(result)];
  }

  private matchesPathEntry(
    kind: "Read" | "Write",
    entry: string,
    absPath: string
  ): boolean {
    const re = new RegExp(`^\\s*${kind}\\s*\\((.*)\\)\\s*$`);
    const m = entry.match(re);
    if (!m) return false;
    const rawPattern = (m[1] ?? "").trim();
    const expandedPattern = this.expandTilde(rawPattern);
    return this.matchGlob(expandedPattern, absPath);
  }

  private async isPathExplicitlyDenied(
    kind: "Read" | "Write",
    absPath: string
  ): Promise<boolean> {
    const perms = await this.getPermissions();
    return perms.deny.some(
      e => this.isPathEntry(kind, e) && this.matchesPathEntry(kind, e, absPath)
    );
  }

  private async isPathExplicitlyAllowed(
    kind: "Read" | "Write",
    absPath: string
  ): Promise<boolean> {
    const perms = await this.getPermissions();
    return perms.allow.some(
      e => this.isPathEntry(kind, e) && this.matchesPathEntry(kind, e, absPath)
    );
  }

  private expandTilde(p: string): string {
    if (p === "~") return homedir();
    if (p.startsWith("~/")) return homedir() + p.slice(1);
    return p;
  }

  private matchGlob(pattern: string, value: string): boolean {
    return matchesCommandGlob(pattern, value);
  }

  async addToAllowList(
    _ctx: Context,
    kind: "Shell" | "Read" | "Write" | "Mcp" | "WebFetch" | "GenerateImage",
    value: string
  ): Promise<void> {
    const entry: string = `${kind}(${value})`;
    await this.permissionsProvider.updatePermissions(perms => {
      const allow: string[] = perms.allow.includes(entry)
        ? perms.allow
        : [...perms.allow, entry];
      return { ...perms, allow };
    });
  }

  async addToDenyList(
    _ctx: Context,
    kind: "Shell" | "Read" | "Write" | "Mcp" | "WebFetch",
    value: string
  ): Promise<void> {
    const entry: string = `${kind}(${value})`;
    await this.permissionsProvider.updatePermissions(perms => {
      const deny: string[] = perms.deny.includes(entry)
        ? perms.deny
        : [...perms.deny, entry];
      return { ...perms, deny };
    });
  }

  /**
   * Check if MCP tool execution should be blocked.
   * Always asks for permission unless in auto-run mode (and auto-run is team-allowed).
   * @returns false if allowed, BlockReason if blocked
   */
  async shouldBlockMcp(
    ctx: Context,
    args: McpArgs
  ): Promise<false | BlockReason> {
    using _span = createSpan(
      ctx.withName("InteractivePermissionsService.shouldBlockMcp")
    );
    const { name, toolName, providerIdentifier, args: argsMap } = args;

    const log = (msg: string): void => {
      this.mcpAllowlistLog?.(msg);
    };

    log(
      `[permissions-service] shouldBlockMcp: toolName="${toolName}", providerIdentifier="${providerIdentifier}"`
    );

    const perms = await this.getPermissions();
    const mcpToolControls = await this.teamSettingsService.getMcpToolControls();

    // MCP Tool Controls are independent from terminal auto-run controls. When
    // enabled, the admin MCP allowlist owns approval instead of the user's list.
    const adminMcpAllowlistEnabled = mcpToolControls?.enabled === true;

    // Check explicit deny list first
    const explicitlyDenied = await this.isMcpExplicitlyDenied(
      ctx,
      providerIdentifier,
      toolName
    );
    if (explicitlyDenied) {
      log(
        `[permissions-service] shouldBlockMcp: BLOCKED (explicitly denied) toolName="${toolName}", providerIdentifier="${providerIdentifier}"`
      );
      return { type: "permissionsConfig" };
    }

    const smartModeApprovalReason = args.smartModeApproval?.reason;
    if (smartModeApprovalReason !== undefined) {
      if (
        perms.userConfiguredPolicy.type === "workspace_readonly" &&
        perms.approvalMode !== "unrestricted"
      ) {
        log(
          `[permissions-service] shouldBlockMcp: BLOCKED (readonly mode, Smart Mode forced approval) toolName="${toolName}", providerIdentifier="${providerIdentifier}"`
        );
        return { type: "permissionsConfig", isReadonly: true };
      }

      log(
        `[permissions-service] shouldBlockMcp: needsApproval (Smart Mode) toolName="${toolName}", providerIdentifier="${providerIdentifier}"`
      );
      const smartModeMcpAllowlisted = adminMcpAllowlistEnabled
        ? this.isMcpInTeamAllowlist(mcpToolControls!, {
            providerIdentifier,
            toolName,
          })
        : await this.isMcpExplicitlyAllowed(ctx, providerIdentifier, toolName);
      if (smartModeMcpAllowlisted) {
        return false;
      }
      return {
        type: "needsApproval",
        approvalReason: smartModeApprovalReason,
        approvalDetails: {
          type: "mcp",
          name,
          toolName,
          providerIdentifier,
          args: argsMap,
          reason: "smartMode",
          canAllowlist: false,
          smartModeApprovalReason,
          smartModeApprovalRequestId: args.smartModeApproval?.requestId,
        },
      };
    }

    // Check if explicitly allowed—only use user's allowlist when admin has NOT enabled MCP allowlists
    if (adminMcpAllowlistEnabled) {
      // Admin controls MCP allowlist: only check admin's list, never user's stored allowlist
      const inTeamAllowlist = this.isMcpInTeamAllowlist(mcpToolControls!, {
        providerIdentifier,
        toolName,
      });
      this.recordMcpAllowlistCheckResult(ctx, {
        allowlistScope: "team",
        outcome: inTeamAllowlist ? "pass" : "fail",
      });
      if (inTeamAllowlist) {
        log(
          `[permissions-service] shouldBlockMcp: ALLOWED (in admin MCP allowlist) toolName="${toolName}", providerIdentifier="${providerIdentifier}"`
        );
        return false;
      }
    } else {
      // No admin MCP allowlist: use user's allowlist from permissions
      const explicitlyAllowed = await this.isMcpExplicitlyAllowed(
        ctx,
        providerIdentifier,
        toolName
      );
      this.recordMcpAllowlistCheckResult(ctx, {
        allowlistScope: "user",
        outcome: explicitlyAllowed ? "pass" : "fail",
      });
      if (explicitlyAllowed) {
        log(
          `[permissions-service] shouldBlockMcp: ALLOWED (explicitly in allowlist) toolName="${toolName}", providerIdentifier="${providerIdentifier}"`
        );
        return false;
      }
    }

    // Check readonly mode - only block if not explicitly allowed
    // Readonly mode still respects allowlists, so if explicitly allowed, allow it
    if (
      perms.userConfiguredPolicy.type === "workspace_readonly" &&
      perms.approvalMode !== "unrestricted"
    ) {
      log(
        `[permissions-service] shouldBlockMcp: BLOCKED (readonly mode) toolName="${toolName}", providerIdentifier="${providerIdentifier}"`
      );
      return { type: "permissionsConfig", isReadonly: true };
    }

    const isAutoRun = perms.approvalMode === "unrestricted";
    if (isAutoRun) {
      const teamBlocksMcp = await this.teamSettingsService.getShouldBlockMcp();
      if (teamBlocksMcp) {
        log(
          `[permissions-service] shouldBlockMcp: needsApproval (auto-run but team blocks MCP) toolName="${toolName}", providerIdentifier="${providerIdentifier}"`
        );
        // Fall through to approval
      } else {
        log(
          `[permissions-service] shouldBlockMcp: ALLOWED (auto-run, no team block) toolName="${toolName}", providerIdentifier="${providerIdentifier}"`
        );
        return false;
      }
    }

    log(
      `[permissions-service] shouldBlockMcp: needsApproval (not in allowlist) toolName="${toolName}", providerIdentifier="${providerIdentifier}", approvalMode="${perms.approvalMode}"`
    );
    return {
      type: "needsApproval",
      approvalReason: `MCP tool: ${toolName}`,
      approvalDetails: {
        type: "mcp",
        name,
        toolName,
        providerIdentifier,
        args: argsMap,
        canAllowlist: true,
      },
    };
  }

  /**
   * @see PermissionsService.isMcpFullyAllowlisted
   *
   * Mirrors the two "explicitly allowed" branches of
   * {@link shouldBlockMcp} — admin team allowlist when admin auto-run
   * controls are enabled, otherwise the user's `Mcp(...)` allowlist. Reuses
   * {@link isMcpExplicitlyDenied}, {@link isMcpInTeamAllowlist}, and
   * {@link isMcpExplicitlyAllowed} so any future change to the matchers
   * stays in sync between this precheck and the canonical block decision.
   */
  async isMcpFullyAllowlisted(
    parentCtx: Context,
    options: {
      providerIdentifier: string;
      toolName: string;
    }
  ): Promise<boolean> {
    const ctx = parentCtx.withName(
      "InteractivePermissionsService.isMcpFullyAllowlisted"
    );
    const { providerIdentifier, toolName } = options;

    // Deny list is checked first in `shouldBlockMcp`. If the call would be
    // denied we must NOT short-circuit — let the classifier path run so the
    // existing block-reason surfacing and Smart Mode telemetry stay
    // authoritative.
    if (await this.isMcpExplicitlyDenied(ctx, providerIdentifier, toolName)) {
      return false;
    }

    const mcpToolControls = await this.teamSettingsService.getMcpToolControls();
    if (mcpToolControls?.enabled === true) {
      // Admin controls MCP allowlist: check admin's list first
      if (
        this.isMcpInTeamAllowlist(mcpToolControls, {
          providerIdentifier,
          toolName,
        })
      ) {
        return true;
      }
      return false;
    }

    return await this.isMcpExplicitlyAllowed(ctx, providerIdentifier, toolName);
  }

  /**
   * @see PermissionsService.isWebFetchFullyAllowlisted
   *
   * Mirrors the explicit WebFetch domain allowlist auto-approval path: only
   * user `WebFetch(domain)` entries count, deny entries win, and all
   * non-allowlist approval modes fall through.
   */
  async isWebFetchFullyAllowlisted(
    _parentCtx: Context,
    options: {
      url: string;
    }
  ): Promise<boolean> {
    const perms = await this.getPermissions();
    if (perms.approvalMode !== "allowlist") {
      return false;
    }

    let parsed: URL;
    try {
      parsed = new URL(options.url);
    } catch {
      return false;
    }

    const hostname = parsed.hostname;
    if (perms.deny.some(entry => this.matchesWebFetchEntry(entry, hostname))) {
      return false;
    }

    return perms.allow.some(entry =>
      this.matchesWebFetchEntry(entry, hostname)
    );
  }

  /**
   * Matches a command against an autorun pattern using the same logic as VSCode.
   * The pattern matches if it appears at the beginning of the command followed by space or end of string.
   * This is intentionally simpler than matchesShellEntry to provide predictable behavior for team admins.
   */
  private matchesAutoRunCommand(
    command: string,
    patternToMatch: string
  ): boolean {
    // Sanitize the command pattern by escaping regex special characters
    const escapedPattern = patternToMatch.replace(
      /[.*+?^${}()|[\]\\]/g,
      "\\$&"
    );

    // Create a regex that matches the pattern only at the beginning of the string (^)
    // and only if followed by whitespace (\s) or end of string ($)
    return new RegExp(`^${escapedPattern}(\\s|$)`).test(command.trim());
  }

  /**
   * Check if an MCP entry matches a pattern.
   * Pattern format: [server]:[tool]
   * Supports wildcards: *:[tool], [server]:*, *:*
   * providerIdentifier is the display name from mcp.json (source of truth, set by the agent).
   */
  private matchesMcpPattern({
    pattern,
    providerIdentifier,
    toolName,
    logLabel,
  }: {
    pattern: string;
    providerIdentifier: string;
    toolName: string;
    logLabel: string;
  }): boolean {
    const colonIdx = pattern.indexOf(":");
    if (colonIdx === -1) return false;

    const serverPattern = pattern.slice(0, colonIdx).trim().toLowerCase();
    const toolPattern = pattern
      .slice(colonIdx + 1)
      .trim()
      .toLowerCase();
    // Runtime ids arrive scoped as `<name>::mcpScope:<profile>:cfg:<hash>`; the allowlist is
    // keyed on the bare display name, so strip the scope (marker mirrors vscode's mcpProcessServerIdentifier.ts).
    const scopeMarker = "::mcpScope:";
    const scopeMarkerIndex = providerIdentifier.lastIndexOf(scopeMarker);
    const unscopedProviderIdentifier =
      scopeMarkerIndex === -1
        ? providerIdentifier
        : providerIdentifier.slice(0, scopeMarkerIndex);
    const normalizedProviderIdentifier = unscopedProviderIdentifier
      .toLowerCase()
      .trim();
    const normalizedToolName = toolName.toLowerCase().trim();

    const serverMatches =
      serverPattern === "*" ||
      this.matchGlob(serverPattern, normalizedProviderIdentifier);
    const toolMatches =
      toolPattern === "*" || this.matchGlob(toolPattern, normalizedToolName);

    const result = serverMatches && toolMatches;
    const msg = `[permissions-service] ${logLabel}: serverPattern="${serverPattern}", toolPattern="${toolPattern}", normalizedProviderIdentifier="${normalizedProviderIdentifier}", normalizedToolName="${normalizedToolName}", serverMatches=${serverMatches}, toolMatches=${toolMatches}, result=${result}`;
    this.mcpAllowlistLog?.(msg);
    return result;
  }

  private recordMcpAllowlistCheckResult(
    ctx: Context,
    {
      allowlistScope,
      outcome,
    }: {
      allowlistScope: "user" | "team";
      outcome: "pass" | "fail";
    }
  ): void {
    mcpAllowlistCheckResult.increment(ctx, 1, {
      allowlist_scope: allowlistScope,
      outcome,
    });
  }

  private matchesMcpEntry(
    entry: string,
    providerIdentifier: string,
    toolName: string
  ): boolean {
    const m = entry.match(/^\s*Mcp\s*\((.*)\)\s*$/);
    if (!m) return false;

    const pattern = m[1]?.trim() ?? "";
    return this.matchesMcpPattern({
      pattern,
      providerIdentifier,
      toolName,
      logLabel: "matchesMcpEntry",
    });
  }

  private matchesWebFetchEntry(entry: string, hostname: string): boolean {
    const match = entry.match(/^\s*WebFetch\s*\((.*)\)\s*$/);
    if (!match) {
      return false;
    }

    const pattern = match[1]?.trim() ?? "";
    return matchesDomainPattern(hostname, pattern);
  }

  /**
   * Matches a bare server:tool pattern (no Mcp(...) wrapper).
   * Used for admin MCP allowlist entries which come in server:tool format.
   */
  private matchesMcpEntryBare({
    pattern,
    providerIdentifier,
    toolName,
  }: {
    pattern: string;
    providerIdentifier: string;
    toolName: string;
  }): boolean {
    return this.matchesMcpPattern({
      pattern,
      providerIdentifier,
      toolName,
      logLabel: "matchesMcpEntryBare",
    });
  }

  private isMcpInTeamAllowlist(
    mcpToolControls: McpToolControls,
    {
      providerIdentifier,
      toolName,
    }: {
      providerIdentifier: string;
      toolName: string;
    }
  ): boolean {
    return mcpToolControls.mcpToolAllowlist.some(entry =>
      this.matchesMcpEntryBare({ pattern: entry, providerIdentifier, toolName })
    );
  }

  private async isMcpExplicitlyDenied(
    _ctx: Context,
    providerIdentifier: string,
    toolName: string
  ): Promise<boolean> {
    const perms = await this.getPermissions();
    return perms.deny.some(e =>
      this.matchesMcpEntry(e, providerIdentifier, toolName)
    );
  }

  private async isMcpExplicitlyAllowed(
    _ctx: Context,
    providerIdentifier: string,
    toolName: string
  ): Promise<boolean> {
    const perms = await this.getPermissions();
    return perms.allow.some(e =>
      this.matchesMcpEntry(e, providerIdentifier, toolName)
    );
  }
}
