import { lstat, readdir, rm, rmdir, stat } from "node:fs/promises";
import { join } from "node:path";

export const DEFAULT_AGENT_DATA_TTL_MS: number = 30 * 24 * 60 * 60 * 1000; // 30 days
export const DEFAULT_AGENT_DATA_CLEANUP_INTERVAL_MS: number =
  24 * 60 * 60 * 1000; // 24 hours
export const DEFAULT_AGENT_DATA_ALLOWED_EXTENSIONS = [
  ".txt",
  ".json",
  ".jsonl",
] as const;
export const DEFAULT_AGENT_DATA_SUBDIRS = [
  "agent-transcripts",
  "agent-tools",
] as const;

export type AgentDataCleanupOptions = {
  /**
   * Absolute path to the Cursor projects directory (usually `~/.cursor/projects`).
   * This directory contains per-workspace subdirectories.
   */
  projectsDir: string;
  nowMs?: number;
  ttlMs?: number;
  allowedExtensions?: readonly string[];
  subdirs?: readonly string[];
};

export type AgentDataCleanupResult = {
  scannedProjects: number;
  scannedFiles: number;
  deletedFiles: number;
};

const AGENT_DATA_CLEANUP_ENTRIES_PER_YIELD = 100;

type CleanupSubdirResult = {
  scannedFiles: number;
  deletedFiles: number;
  isEmpty: boolean;
};

/** Deletes expired files and optionally recurses, reporting whether the directory is empty. */
async function cleanupSubdir(
  dir: string,
  nowMs: number,
  ttlMs: number,
  allowedExtensions: readonly string[],
  recursive: boolean,
  traversalState: { entriesSinceYield: number }
): Promise<CleanupSubdirResult> {
  let scannedFiles = 0;
  let deletedFiles = 0;
  let isEmpty = true;

  try {
    const entries = await readdir(dir, { withFileTypes: true });
    for (const entry of entries) {
      traversalState.entriesSinceYield++;
      if (
        traversalState.entriesSinceYield >= AGENT_DATA_CLEANUP_ENTRIES_PER_YIELD
      ) {
        traversalState.entriesSinceYield = 0;
        // Unsupported entries do no I/O, so explicitly yield between batches.
        await new Promise<void>(resolve => setImmediate(resolve));
      }

      const entryPath = join(dir, entry.name);
      if (entry.isDirectory()) {
        if (!recursive) {
          isEmpty = false;
          continue;
        }

        const result = await cleanupSubdir(
          entryPath,
          nowMs,
          ttlMs,
          allowedExtensions,
          recursive,
          traversalState
        );
        scannedFiles += result.scannedFiles;
        deletedFiles += result.deletedFiles;

        if (!result.isEmpty) {
          isEmpty = false;
          continue;
        }

        try {
          await rmdir(entryPath);
        } catch {
          // A concurrent write made the directory nonempty; preserve it.
          isEmpty = false;
        }
        continue;
      }

      if (
        !entry.isFile() ||
        !allowedExtensions.some(ext => entry.name.endsWith(ext))
      ) {
        isEmpty = false;
        continue;
      }

      scannedFiles++;
      try {
        const s = await stat(entryPath);
        if (Number.isFinite(s.mtimeMs) && nowMs - s.mtimeMs > ttlMs) {
          await rm(entryPath, { force: true });
          deletedFiles++;
        } else {
          isEmpty = false;
        }
      } catch {
        // Best-effort: ignore races, perms, missing files, etc.
        isEmpty = false;
      }
    }
  } catch {
    // Directory doesn't exist or isn't readable.
    isEmpty = false;
  }

  return { scannedFiles, deletedFiles, isEmpty };
}

/**
 * Deletes old agent transcript + tool output files in all Cursor project directories.
 *
 * Intended to be called by the exec layer (local exec / cursor-agent-exec),
 * not by client/UI code.
 */
export async function cleanupOldAgentData(
  options: AgentDataCleanupOptions
): Promise<AgentDataCleanupResult> {
  const nowMs = options.nowMs ?? Date.now();
  const ttlMs = options.ttlMs ?? DEFAULT_AGENT_DATA_TTL_MS;
  const allowedExtensions =
    options.allowedExtensions ?? DEFAULT_AGENT_DATA_ALLOWED_EXTENSIONS;
  const subdirs = options.subdirs ?? DEFAULT_AGENT_DATA_SUBDIRS;

  let scannedProjects = 0;
  let scannedFiles = 0;
  let deletedFiles = 0;
  const traversalState = { entriesSinceYield: 0 };

  try {
    const projectEntries = await readdir(options.projectsDir, {
      withFileTypes: true,
    });
    for (const projectEntry of projectEntries) {
      if (!projectEntry.isDirectory()) continue;
      scannedProjects++;

      for (const subdir of subdirs) {
        const dir = join(options.projectsDir, projectEntry.name, subdir);
        try {
          if (!(await lstat(dir)).isDirectory()) continue;
        } catch {
          continue;
        }

        const result = await cleanupSubdir(
          dir,
          nowMs,
          ttlMs,
          allowedExtensions,
          subdir === "agent-tools",
          traversalState
        );
        scannedFiles += result.scannedFiles;
        deletedFiles += result.deletedFiles;
      }
    }
  } catch {
    // Projects directory doesn't exist or isn't readable.
  }

  return { scannedProjects, scannedFiles, deletedFiles };
}
