import type { SpawnOptionsWithoutStdio } from "node:child_process";
import { randomUUID } from "node:crypto";
import { existsSync } from "node:fs";
import * as fs from "node:fs/promises";
import { rm } from "node:fs/promises";
import * as os from "node:os";
import * as path from "node:path";
import type { Context } from "@anysphere/context";
import { createSpan, reportEvent } from "@anysphere/context";
import { createWritableIterable, findActualExecutable } from "@anysphere/utils";
import { spawnWithSignal, splitPwdAndState } from "./core.js";
import powershellWrapperScript from "./dump_powershell_state.js";
import {
  attachShellOutputStreams,
  type BufferReadable,
} from "./output-limiter.js";
import { resolveSandboxPolicyForWorkspace } from "./sandbox/policy-merge.js";
import { shouldEnableSudoAskpass, transformSudoCommand } from "./sudo.js";
import {
  SHELL_ENV_OVERRIDES,
  type TerminalCommandOptions,
  type TerminalEvent,
  type TerminalExecutor,
} from "./types.js";

/**
 * Detects which PowerShell executable to use.
 * Returns 'pwsh' for PowerShell Core (cross-platform) or 'powershell' for Windows PowerShell.
 */
export function getPowerShellExecutable(): string {
  if (process.platform !== "win32") {
    const shell = process.env.SHELL;
    if (shell?.includes("pwsh") || shell?.includes("powershell")) {
      return shell;
    }
  }

  let pwsh = findActualExecutable("pwsh", []).cmd;
  if (pwsh !== "pwsh") {
    return pwsh;
  }

  pwsh = findActualExecutable("powershell", []).cmd;
  if (pwsh !== "powershell") {
    return pwsh;
  }

  if (process.platform === "win32") {
    // Fall back to hard-coded guaranteed PowerShell path
    pwsh = path.join(
      process.env.SYSTEMROOT!,
      "System32",
      "WindowsPowerShell",
      "v1.0",
      "powershell.exe"
    );
    if (existsSync(pwsh)) {
      return pwsh;
    }
  }

  throw new Error(
    "Neither 'pwsh' (PowerShell Core) nor 'powershell' (Windows PowerShell) found in PATH"
  );
}

export class PowerShellState implements TerminalExecutor {
  constructor(
    private cwd: string,
    private state: string
  ) {}

  async getCwd(): Promise<string> {
    return this.cwd;
  }

  clone(workingDirectory?: string): TerminalExecutor {
    return new PowerShellState(workingDirectory ?? this.cwd, this.state);
  }

  async *execute(
    ctx: Context,
    command: string,
    options?: TerminalCommandOptions
  ): AsyncIterable<TerminalEvent> {
    using span = createSpan(ctx.withName("PowerShellState.execute"));
    const pipeStdin = options?.pipeStdin ?? false;
    const cwd = options?.workingDirectory ?? this.cwd;
    const iterable = createWritableIterable<TerminalEvent>();

    const env = {
      ...process.env,
      ...SHELL_ENV_OVERRIDES,
      ...options?.env,
    } as NodeJS.ProcessEnv;

    // Transform sudo commands to use -A flag when askpass is configured.
    // PowerShell can't use shell aliases, so we transform the command string
    // like the naive runner. shouldEnableSudoAskpass returns false on Windows,
    // so this only takes effect on non-Windows platforms where pwsh is used.
    const transformedCommand = shouldEnableSudoAskpass(env)
      ? transformSudoCommand(command)
      : command;

    // Create temporary files for state transfer
    const tempDir = os.tmpdir();
    const stateOutFile = path.join(tempDir, `ps-state-out-${randomUUID()}.txt`);

    const commandScript = powershellWrapperScript(
      this.state,
      cwd,
      transformedCommand,
      stateOutFile
    );

    // Write the command script to a temporary file and execute with -File
    const scriptFile = path.join(tempDir, `ps-script-${randomUUID()}.ps1`);
    await writeFileWithBom(scriptFile, commandScript);

    // Build args with -NonInteractive BEFORE -File (arguments after -File are passed to the script, not pwsh)
    const args = ["-ExecutionPolicy", "Bypass"];

    if (!pipeStdin) {
      args.push("-NonInteractive");
    }

    // -File must come last - any args after it are passed to the script
    args.push("-File", scriptFile);

    const pwsh = getPowerShellExecutable();

    // On Windows, detached: true creates a new console which breaks stdio piping.
    // On non-Windows, detached creates a new process group for clean kill.
    const isWindows = process.platform === "win32";

    const sandboxWorkspaceRoot = options?.sandboxWorkspaceRoot ?? cwd;
    const resolvedPolicy = (
      await resolveSandboxPolicyForWorkspace(
        sandboxWorkspaceRoot,
        options?.sandboxPolicy
      )
    ).policy;
    const sandboxPolicy =
      resolvedPolicy.type !== "insecure_none"
        ? { ...resolvedPolicy, sandboxWorkspaceRoot }
        : resolvedPolicy;

    const child = spawnWithSignal(
      pwsh,
      args,
      {
        env,
        // Use 'ignore' for stdin (unless interactive) to prevent background processes
        // from inheriting an open stdin pipe, which would prevent the 'close' event from firing
        stdio: [pipeStdin ? "pipe" : "ignore", "pipe", "pipe"],
        cwd,
        // Use detached to create a new process group. This allows killing all
        // child processes (e.g., python servers) when aborting, not just the shell.
        // On Windows, avoid detached as it creates a new console and breaks stdio.
        detached: !isWindows,
      } as SpawnOptionsWithoutStdio,
      sandboxPolicy,
      options?.signal
    );

    // Pass the stdin stream to the background terminal state if available, for the writeShellStdin tool to use
    child.on("spawn", async () => {
      try {
        await iterable.write({
          type: "stdin_ready",
          stdin: child.stdin ?? undefined,
          pid: child.pid,
        });
      } catch (_error) {
        // Iterable might be closed, ignore write errors
      }
    });

    const outputPump = attachShellOutputStreams({
      stdout: child.stdout as BufferReadable | null,
      stderr: child.stderr as BufferReadable | null,
      writable: iterable,
      bufferOutputEvents: options?.bufferOutputEvents,
      outputLimiterOptions: options?.outputLimiterOptions,
    });

    const cleanup = async () => {
      try {
        const newState = await fs.readFile(stateOutFile, "utf8");
        const { cwd: newCwd, rest } = splitPwdAndState(newState);
        this.state = rest;
        // PowerShell paths may have extra whitespace, trim it
        this.cwd = newCwd.trim();

        await rm(stateOutFile).catch(() => {
          /* ignore */
        });
      } catch (_error) {
        // If we can't read the state file, the command likely failed
        // Keep the current state
      }

      // Cleanup temporary script file
      await rm(scriptFile).catch(() => {
        /* ignore */
      });
    };

    // NB: This is extremely Tricky. Data from stdio can come in after 'exit',
    // so instead of emitting 'exit' immediately, we store off the exit code
    // and emit it once 'close' is called.
    let exitCode: number | null = null;
    let closeTimeoutId: NodeJS.Timeout | null = null;
    let hasEmittedExit = false;

    const emitExitAndClose = async (waitForOutputPumps: boolean) => {
      if (hasEmittedExit) return;
      hasEmittedExit = true;

      if (closeTimeoutId) {
        clearTimeout(closeTimeoutId);
        closeTimeoutId = null;
      }

      reportEvent(span.ctx, "exit");

      if (waitForOutputPumps) {
        try {
          await outputPump.waitForOutput();
        } catch (error) {
          await cleanup();
          iterable.throw(
            error instanceof Error ? error : new Error(String(error))
          );
          return;
        }
      }
      await outputPump.flush();

      try {
        await iterable.write({
          type: "exit",
          code: exitCode,
          data: "",
          aborted: options?.signal?.aborted ?? false,
        });

        await cleanup();
        iterable.close();
      } catch (_error) {
        // Iterable might be closed, ignore write errors
        iterable.close();
      }
    };

    child.on("exit", (code, _signal) => {
      exitCode = code;

      // Start timeout to prevent hanging if 'close' never fires
      const timeout = options?.closeTimeout ?? 5000;
      if (timeout > 0) {
        closeTimeoutId = setTimeout(() => {
          console.warn(
            `[shell-exec] Close event did not fire within ${timeout}ms after exit. ` +
              `This may indicate a background process is holding file descriptors open. ` +
              `Proceeding anyway to prevent hang.`
          );
          emitExitAndClose(false);
        }, timeout);
      }
    });

    child.on("close", async () => {
      await emitExitAndClose(true);
    });

    // Handle process exit and errors
    child.on("error", error => {
      cleanup().catch(() => {
        /* ignore */
      });
      iterable.throw(error);
    });

    yield* iterable;
  }
}

const UTF8_BOM = "\uFEFF";
async function writeFileWithBom(
  filePath: string,
  content: string
): Promise<void> {
  await fs.writeFile(filePath, UTF8_BOM + content, { encoding: "utf8" });
}

export async function initPowerShellState(): Promise<PowerShellState> {
  return new PowerShellState(process.cwd(), "");
}
