import type {
  ChildProcess,
  SpawnOptionsWithoutStdio,
} from "node:child_process";
import type Stream from "node:stream";
import { withConfiguredRipgrepEnv } from "./ripgrep.js";
import { spawnInSandbox } from "./sandbox/sandbox.js";
import {
  type SandboxPolicy,
  SHELL_ENV_OVERRIDES,
  type ShellExecResult,
} from "./types.js";

export function spawnWithSignal(
  command: string,
  args: string[] = [],
  options: SpawnOptionsWithoutStdio | undefined = {},
  sandboxPolicy: SandboxPolicy,
  signal?: AbortSignal
): ChildProcess {
  // Check if signal is already aborted
  if (signal?.aborted) {
    const error = new Error("Operation was aborted");
    error.name = "AbortError";
    // Create a mock child process that immediately emits an error
    const mockChild =
      new (require("node:events").EventEmitter)() as ChildProcess;
    process.nextTick(() => {
      mockChild.emit("error", error);
    });
    return mockChild;
  }

  const child = spawnInSandbox(
    command,
    args,
    {
      ...options,
      env: withConfiguredRipgrepEnv(options.env ?? process.env),
    },
    sandboxPolicy
  );

  if (signal) {
    const abortHandler = () => {
      if (child.pid) {
        try {
          // Send SIGTERM to the process group to gracefully terminate
          if (options.detached) {
            try {
              process.kill(-child.pid, "SIGTERM");
            } catch {
              // Process group kill might fail (e.g., on Windows or if already dead)
              // Fall back to killing just the child process
              child.kill("SIGTERM");
            }
          } else {
            child.kill("SIGTERM");
          }

          // Set up force kill after 1 second
          const forceKillTimeout = setTimeout(() => {
            if (!child.killed && child.pid) {
              try {
                if (options.detached) {
                  try {
                    process.kill(-child.pid, "SIGKILL");
                  } catch {
                    // Process group kill might fail (e.g., on Windows or if already dead)
                    // Fall back to killing just the child process
                    child.kill("SIGKILL");
                  }
                } else {
                  child.kill("SIGKILL");
                }
              } catch (_killError) {
                // Process might already be dead
              }
            }
          }, 1000);

          // Clean up timeout if process exits gracefully
          child.once("exit", () => {
            clearTimeout(forceKillTimeout);
          });
        } catch (_error) {
          // Process might already be dead, ignore errors
        }
      }
    };

    signal.addEventListener("abort", abortHandler, { once: true });

    // Clean up event listener when child process exits
    child.once("exit", () => {
      signal.removeEventListener("abort", abortHandler);
    });
  }

  return child;
}

/** Best-effort kill of a detached spawn's process group (negative pid). */
export function killDetachedProcessGroup(
  pid: number | undefined,
  signal: NodeJS.Signals,
  forceKillAfterMs?: number
): void {
  if (!pid) {
    return;
  }
  try {
    process.kill(-pid, signal);
  } catch {
    return;
  }
  if (
    signal === "SIGTERM" &&
    forceKillAfterMs !== undefined &&
    forceKillAfterMs > 0
  ) {
    setTimeout(() => {
      try {
        process.kill(-pid, "SIGKILL");
      } catch {}
    }, forceKillAfterMs);
  }
}

export function shellExec(
  command: string,
  args: string[] = [],
  options:
    | (SpawnOptionsWithoutStdio & {
        signal?: AbortSignal;
      })
    | undefined = {},
  sandboxPolicy: SandboxPolicy
): Promise<ShellExecResult> {
  return new Promise((resolve, reject) => {
    const { signal, ...spawnOptions } = options;

    // Set environment variables to disable color output
    const env = {
      ...process.env,
      ...SHELL_ENV_OVERRIDES,
      ...spawnOptions.env,
    };

    const child = spawnWithSignal(
      command,
      args,
      {
        ...spawnOptions,
        env,
        stdio: ["pipe", "pipe", "pipe"],
      },
      sandboxPolicy,
      signal
    );
    let stdout = "";
    let stderr = "";

    child.stdout?.on("data", data => {
      stdout += data.toString();
    });

    child.stderr?.on("data", data => {
      stderr += data.toString();
    });

    child.stdin?.end();

    child.on("error", error => {
      reject(error);
    });

    child.on("exit", code => {
      if (code === 0) {
        resolve({ stdout, stderr, code });
      } else {
        const error: Error & Partial<ShellExecResult> = new Error(
          `Process exited with code ${code}`
        );
        error.code = code;
        error.stdout = stdout;
        error.stderr = stderr;
        reject(error);
      }
    });
  });
}

export function readPipe(
  child: ChildProcess,
  pipe: Stream.Readable
): Promise<string> {
  return new Promise<string>((resolve, reject) => {
    const chunks: Uint8Array[] = [];

    pipe.on("data", chunk => {
      chunks.push(chunk);
    });
    pipe.on("end", () => {
      resolve(Buffer.concat(chunks).toString());
    });
    pipe.on("error", reject);

    child.on("error", reject);
    child.on("exit", () => {
      resolve(Buffer.concat(chunks).toString());
    });
  });
}

/**
 * Attach a no-op error listener so premature close / EPIPE does not become an
 * unhandled Socket 'error' and kill the host process.
 *
 * Shell state restore is already best-effort: missing dump markers keep the
 * previous valid state. A closed state pipe is the same class of failure.
 */
export function ignoreStreamErrors(
  stream: NodeJS.ReadableStream | NodeJS.WritableStream | null | undefined
): void {
  stream?.on("error", () => {
    // Intentionally empty: EPIPE / premature close on best-effort pipes.
  });
}

/**
 * Write the shell state snapshot to stdio[3]. Ignores EPIPE when the child has
 * already closed the pipe.
 */
export function writeShellStatePipe(
  inFd: Stream.Writable | null | undefined,
  state: string
): void {
  if (!inFd) {
    return;
  }
  ignoreStreamErrors(inFd);
  inFd.write(state);
  inFd.end();
}

/**
 * Listen for the dumped shell state on stdio[4]. Ignores premature close.
 */
export function attachShellStateOutput(
  outFd: Stream.Readable | null | undefined,
  onChunk: (text: string) => void
): void {
  if (!outFd) {
    return;
  }
  ignoreStreamErrors(outFd);
  outFd.on("data", data => {
    onChunk(data.toString());
  });
}

/**
 * Splits shell state output into working directory and state snapshot.
 * The first line is expected to be the current working directory (PWD),
 * and the rest is the shell state (environment vars, functions, etc.).
 */
export function splitPwdAndState(state: string): { cwd: string; rest: string } {
  const firstLineIndex = state.indexOf("\n");
  const cwd = state.substring(0, firstLineIndex);
  const rest = state.substring(firstLineIndex);

  return { cwd, rest };
}

/**
 * Extracts shell state after a marker to filter out MOTD and other
 * shell initialization output. If the marker is not found, returns
 * the full output as a fallback.
 */
export function parseShellStateOutput(
  fullOutput: string,
  marker: string
): string {
  const markerWithNewline = `${marker}\n`;
  const markerIndex = fullOutput.indexOf(markerWithNewline);

  return markerIndex >= 0
    ? fullOutput.slice(markerIndex + markerWithNewline.length)
    : fullOutput;
}
