import {
	getDegradedProbeDelayMs,
	getKeepaliveJitterMs,
	getKeepaliveProbeDelayMs,
	getStabilityThresholdMs,
} from '../config/mcp-fsm-timing-config.js';
import type { ConnectionState } from './types.js';

// ── Activity Types ──────────────────────────────────────────────────
// Activities are ongoing effects bound to a state's lifetime (Harel
// statechart concept).  Instead of the FSM emitting explicit
// start_*/cancel_* timer commands, the interpreter derives which
// activities should be active from the current state and reconciles
// the difference on every transition.  This makes it structurally
// impossible to forget a cancel (I3).

export type ActivityType = 'backoff_timer' | 'stability_timer' | 'periodic_retry_timer' | 'health_probe_timer';

export interface ActivitySpec {
	readonly delayMs: number;
}

export interface ActivityTimingConfig {
	readonly getStabilityThresholdMs?: () => number;
	readonly getDegradedProbeDelayMs?: () => number;
	readonly getKeepaliveProbeDelayMs?: () => number;
	readonly getKeepaliveJitterMs?: () => number;
	readonly getKeepaliveProbesEnabled?: () => boolean;
	readonly getRetryNonRetryableAutomatically?: () => boolean;
}

// ── Service Types ───────────────────────────────────────────────────
// Services are one-shot async operations bound to a state's lifetime.
// Like activities, they are derived from state and managed by the
// reconciler: started on state entry, cancelled on state exit.
//
// This unifies ALL managed effects (timers AND connection attempts)
// under the same model, eliminating fire-and-forget async operations.

export type ServiceType = 'connection_attempt' | 'health_probe';

/**
 * Pure function: given a ConnectionState, return the set of activities
 * (timers) that should be active.  The exhaustive switch ensures that
 * adding a new state forces you to declare its activities.
 */
export function activeActivities(
	state: ConnectionState,
	timingConfig?: ActivityTimingConfig,
): ReadonlyMap<ActivityType, ActivitySpec> {
	switch (state.type) {
		case 'idle':
			return EMPTY_ACTIVITIES;

		case 'connecting':
			return EMPTY_ACTIVITIES;

		case 'connected':
			if (!state.stabilized) {
				return stabilityTimerActivities(timingConfig);
			}
			if (state.probing) {
				return EMPTY_ACTIVITIES;
			}
			if (timingConfig?.getKeepaliveProbesEnabled?.() === false) {
				return EMPTY_ACTIVITIES;
			}
			return createKeepaliveProbeTimer(timingConfig);

		case 'dormant':
			return EMPTY_ACTIVITIES;

		case 'degraded':
			return state.probing ? EMPTY_ACTIVITIES : degradedProbeTimerActivities(timingConfig);

		case 'transient_failure':
			return new Map<ActivityType, ActivitySpec>([
				['backoff_timer', { delayMs: state.nextDelayMs }],
			]);

		case 'failed':
			if (state.automaticRetry === false) {
				if (timingConfig?.getRetryNonRetryableAutomatically?.() !== true) {
					return EMPTY_ACTIVITIES;
				}
			}
			if (state.exhausted) {
				return EMPTY_ACTIVITIES;
			}
			return new Map<ActivityType, ActivitySpec>([
				['periodic_retry_timer', { delayMs: state.periodicRetryDelayMs }],
			]);

		case 'closed':
			if (state.automaticRetry === false) {
				if (timingConfig?.getRetryNonRetryableAutomatically?.() !== true) {
					return EMPTY_ACTIVITIES;
				}
			}
			if (state.exhausted) {
				return EMPTY_ACTIVITIES;
			}
			return new Map<ActivityType, ActivitySpec>([
				['periodic_retry_timer', { delayMs: state.periodicRetryDelayMs }],
			]);

		default: {
			const _exhaustive: never = state;
			return _exhaustive;
		}
	}
}

/**
 * Pure function: given a ConnectionState, return the set of services
 * (one-shot async operations) that should be running.
 *
 * The `connecting` state requires a connection attempt service.
 * The reconciler starts the service on entry and cancels it on exit.
 */
export function activeServices(
	state: ConnectionState,
): ReadonlySet<ServiceType> {
	switch (state.type) {
		case 'idle':
			return EMPTY_SERVICES;

		case 'connecting':
			return CONNECTION_SERVICE;

		case 'connected':
			return state.probing ? HEALTH_PROBE_SERVICE : EMPTY_SERVICES;

		case 'dormant':
			return EMPTY_SERVICES;

		case 'degraded':
			return state.probing ? HEALTH_PROBE_SERVICE : EMPTY_SERVICES;

		case 'transient_failure':
			return EMPTY_SERVICES;

		case 'failed':
			return EMPTY_SERVICES;

		case 'closed':
			return EMPTY_SERVICES;

		default: {
			const _exhaustive: never = state;
			return _exhaustive;
		}
	}
}

// ── Pre-allocated constants (avoid allocation on hot path) ──────────

const EMPTY_ACTIVITIES: ReadonlyMap<ActivityType, ActivitySpec> = new Map();

function resolveStabilityThresholdMs(timingConfig?: ActivityTimingConfig): number {
	return timingConfig?.getStabilityThresholdMs?.() ?? getStabilityThresholdMs();
}

function resolveKeepaliveProbeDelayMs(timingConfig?: ActivityTimingConfig): number {
	return timingConfig?.getKeepaliveProbeDelayMs?.() ?? getKeepaliveProbeDelayMs();
}

function resolveKeepaliveJitterMs(timingConfig?: ActivityTimingConfig): number {
	return timingConfig?.getKeepaliveJitterMs?.() ?? getKeepaliveJitterMs();
}

function resolveDegradedProbeDelayMs(timingConfig?: ActivityTimingConfig): number {
	return timingConfig?.getDegradedProbeDelayMs?.() ?? getDegradedProbeDelayMs();
}

function stabilityTimerActivities(timingConfig?: ActivityTimingConfig): ReadonlyMap<ActivityType, ActivitySpec> {
	return new Map<ActivityType, ActivitySpec>([
		['stability_timer', { delayMs: resolveStabilityThresholdMs(timingConfig) }],
	]);
}

function createKeepaliveProbeTimer(timingConfig?: ActivityTimingConfig): ReadonlyMap<ActivityType, ActivitySpec> {
	return new Map<ActivityType, ActivitySpec>([
		['health_probe_timer', {
			delayMs: resolveKeepaliveProbeDelayMs(timingConfig) + Math.floor(Math.random() * resolveKeepaliveJitterMs(timingConfig)),
		}],
	]);
}

function degradedProbeTimerActivities(timingConfig?: ActivityTimingConfig): ReadonlyMap<ActivityType, ActivitySpec> {
	return new Map<ActivityType, ActivitySpec>([
		['health_probe_timer', { delayMs: resolveDegradedProbeDelayMs(timingConfig) }],
	]);
}

const EMPTY_SERVICES: ReadonlySet<ServiceType> = new Set();

const CONNECTION_SERVICE: ReadonlySet<ServiceType> = new Set<ServiceType>([
	'connection_attempt',
]);

const HEALTH_PROBE_SERVICE: ReadonlySet<ServiceType> = new Set<ServiceType>([
	'health_probe',
]);
