import {
  matchesAdminServerUrlPattern,
  matchesWildcardPattern,
} from "./transport/mcp-url-utils.js";

/**
 * Pure load-time MCP admin policy.
 *
 * This evaluates configured MCP server definitions before load. The URL checks
 * compare declared server URLs from config; they are not runtime traffic
 * interception. Enforcement call sites decide when to block loading.
 */

export type AdminAllowedMcpServer = {
  name?: string;
  command?: string;
  serverUrl?: string;
};

export type AdminMcpConfigurationForPolicy = {
  disableAll?: boolean;
  allowUserOverrideMcpServers?: boolean;
  allowedMcpServers?: AdminAllowedMcpServer[];
  deniedMcpServers?: AdminAllowedMcpServer[];
};

export type AdminMcpServerPolicyServer = {
  command?: string;
  url?: string;
};

export type AdminMcpPolicyOptions = {
  matchesServerUrlPattern?: (pattern: string, serverUrl: string) => boolean;
};

export { matchesAdminServerUrlPattern };

/**
 * Cursor-owned in-process MCP providers (cursor-app-control,
 * cursor-backend-control, etc.) are exposed over this synthetic URL scheme.
 * They back first-party product features (automations, re-rooting, project
 * creation, ...), so the admin allow/deny lists — which govern third-party MCP
 * servers — never apply to them. This is not a bypass vector: nothing can
 * connect to an `mcp-provider://` URL, so a user-configured server spoofing
 * the scheme cannot reach an external server.
 */
const CURSOR_MCP_PROVIDER_URL_PREFIX = "mcp-provider://";

export function isCursorInProcessMcpProviderServer(
  server: AdminMcpServerPolicyServer
): boolean {
  return server.url?.startsWith(CURSOR_MCP_PROVIDER_URL_PREFIX) === true;
}

function normalizeCommandPattern(
  pattern: string | undefined
): string | undefined {
  const normalized = pattern?.trim();
  return normalized === undefined || normalized.length === 0
    ? undefined
    : normalized;
}

function normalizeServerUrlPattern(
  pattern: string | undefined
): string | undefined {
  const normalized = pattern?.trim();
  return normalized === undefined || normalized.length === 0
    ? undefined
    : normalized;
}

function matchesDeniedMcpServerEntry(
  server: AdminMcpServerPolicyServer,
  deniedMcpServers: AdminAllowedMcpServer[] | undefined,
  options?: AdminMcpPolicyOptions
): boolean {
  const matchesServerUrl =
    options?.matchesServerUrlPattern ?? matchesAdminServerUrlPattern;
  return (deniedMcpServers ?? []).some(serverEntry => {
    const commandPattern = normalizeCommandPattern(serverEntry.command);
    const serverUrlPattern = normalizeServerUrlPattern(serverEntry.serverUrl);
    const hasCommandPattern = commandPattern !== undefined;
    const hasServerUrlPattern = serverUrlPattern !== undefined;

    if (!hasCommandPattern && !hasServerUrlPattern) {
      return false;
    }

    const passesCommandPolicy =
      commandPattern === undefined ||
      (server.command !== undefined &&
        matchesWildcardPattern(commandPattern, server.command));
    const passesServerUrlPolicy =
      serverUrlPattern === undefined ||
      (server.url !== undefined &&
        matchesServerUrl(serverUrlPattern, server.url));

    return passesCommandPolicy && passesServerUrlPolicy;
  });
}

function matchesExplicitAdminAllowlistEntry(
  server: AdminMcpServerPolicyServer,
  allowedMcpServers: AdminAllowedMcpServer[],
  options?: AdminMcpPolicyOptions
): boolean {
  // Empty allowlists are not explicit approvals. They mean there is no admin
  // allowlist boundary unless user-extension deny rules apply later.
  return (
    allowedMcpServers.length > 0 &&
    matchesConfiguredAllowedMcpServerEntry(server, allowedMcpServers, options)
  );
}

function matchesConfiguredAllowedMcpServerEntry(
  server: AdminMcpServerPolicyServer,
  allowedMcpServers: AdminAllowedMcpServer[],
  options?: AdminMcpPolicyOptions
): boolean {
  const matchesServerUrl =
    options?.matchesServerUrlPattern ?? matchesAdminServerUrlPattern;
  return allowedMcpServers.some(serverEntry => {
    const commandPattern = normalizeCommandPattern(serverEntry.command);
    const serverUrlPattern = normalizeServerUrlPattern(serverEntry.serverUrl);
    const hasCommandPattern = commandPattern !== undefined;
    const hasServerUrlPattern = serverUrlPattern !== undefined;
    if (!hasCommandPattern && !hasServerUrlPattern) {
      return false;
    }

    const passesCommandPolicy =
      commandPattern === undefined ||
      (server.command !== undefined &&
        matchesWildcardPattern(commandPattern, server.command));
    const passesServerUrlPolicy =
      serverUrlPattern === undefined ||
      (server.url !== undefined &&
        matchesServerUrl(serverUrlPattern, server.url));

    return passesCommandPolicy && passesServerUrlPolicy;
  });
}

export function isMcpServerAllowedByAdminPolicy(
  server: AdminMcpServerPolicyServer,
  config: AdminMcpConfigurationForPolicy | undefined,
  options?: AdminMcpPolicyOptions
): boolean {
  // Admin MCP load policy precedence:
  // 1. `disableAll` is a hard block.
  // 2. Cursor in-process providers are exempt from the allow/deny lists.
  // 3. Empty allowlists mean there is no admin allowlist boundary.
  // 4. Explicit admin allowlist matches are always allowed.
  // 5. User-extension mode applies the denylist only to non-admin-approved MCPs.
  // 6. A configured allowlist is a hard boundary when user extension is off.
  if (config === undefined) {
    return true;
  }
  if (config.disableAll === true) {
    return false;
  }
  if (isCursorInProcessMcpProviderServer(server)) {
    return true;
  }
  const allowedMcpServers = config.allowedMcpServers ?? [];
  if (
    allowedMcpServers.length === 0 &&
    config.allowUserOverrideMcpServers !== true
  ) {
    return true;
  }

  if (matchesExplicitAdminAllowlistEntry(server, allowedMcpServers, options)) {
    return true;
  }

  if (config.allowUserOverrideMcpServers === true) {
    return !matchesDeniedMcpServerEntry(
      server,
      config.deniedMcpServers,
      options
    );
  }

  return false;
}
