export type WebpBitmap = {
  data: Uint8Array;
  width: number;
  height: number;
};

export type WebpCodec = {
  decode: (data: Buffer) => Promise<WebpBitmap>;
  encode: (bitmap: WebpBitmap) => Promise<Buffer>;
};

let registeredCodec: WebpCodec | undefined;

export const registerWebpCodec = (codec: WebpCodec): void => {
  registeredCodec = codec;
};

const requireCodec = (): WebpCodec => {
  if (registeredCodec === undefined) {
    throw new Error(
      "webp codec not registered: registerWebpCodec() must be called by a Node server before decoding/encoding webp"
    );
  }
  return registeredCodec;
};

export const isWebp = (buffer: Buffer): boolean =>
  buffer.length >= 12 &&
  buffer.toString("ascii", 0, 4) === "RIFF" &&
  buffer.toString("ascii", 8, 12) === "WEBP";

export const readWebpDimensions = (
  buffer: Buffer
): { width: number; height: number } | undefined => {
  if (!isWebp(buffer) || buffer.length < 16) {
    return undefined;
  }
  const fourCC = buffer.toString("ascii", 12, 16);

  if (fourCC === "VP8 ") {
    if (
      buffer.length < 30 ||
      buffer[23] !== 0x9d ||
      buffer[24] !== 0x01 ||
      buffer[25] !== 0x2a
    ) {
      return undefined;
    }
    return {
      width: (buffer[26] | (buffer[27] << 8)) & 0x3fff,
      height: (buffer[28] | (buffer[29] << 8)) & 0x3fff,
    };
  }

  if (fourCC === "VP8L") {
    if (buffer.length < 25 || buffer[20] !== 0x2f) {
      return undefined;
    }
    const bits =
      (buffer[21] |
        (buffer[22] << 8) |
        (buffer[23] << 16) |
        (buffer[24] << 24)) >>>
      0;
    return {
      width: (bits & 0x3fff) + 1,
      height: ((bits >> 14) & 0x3fff) + 1,
    };
  }

  if (fourCC === "VP8X") {
    if (buffer.length < 30) {
      return undefined;
    }
    return {
      width: 1 + (buffer[24] | (buffer[25] << 8) | (buffer[26] << 16)),
      height: 1 + (buffer[27] | (buffer[28] << 8) | (buffer[29] << 16)),
    };
  }

  return undefined;
};

export const decodeWebp = (data: Buffer): Promise<WebpBitmap> =>
  requireCodec().decode(data);

export const encodeWebp = (bitmap: WebpBitmap): Promise<Buffer> =>
  requireCodec().encode(bitmap);
