import type { ShellCommandParsingResult } from "@anysphere/proto/agent/v1/shell_exec_pb.js";
import {
  getAdminCommandDenylistRuleError,
  matchesCommandGlob,
  normalizeAdminCommandDenylistText,
  parseAdminCommandDenylistColonRule,
} from "@anysphere/utils";

const ADMIN_COMMAND_DENYLIST_UNANALYZABLE_REASON =
  `Denied: this command could not be conclusively analyzed against your team's administrator command denylist, so it was blocked (fail-closed) and was not executed. ` +
  `It cannot be approved from this conversation; only a user can run it manually outside the agent. ` +
  `You may continue working on the task.`;

type AdminCommandParsingResult = Pick<
  ShellCommandParsingResult,
  "parsingFailed"
> & {
  readonly executableCommands: readonly Pick<
    ShellCommandParsingResult["executableCommands"][number],
    "fullText"
  >[];
};

/**
 * Admin team command denylist matching.
 * String matching only; no intent inference.
 * Before literal matching we apply two widen-only normalizations so common
 * shell *syntax* cannot evade a rule for the same executable/args:
 * 1. separator collapse (ordinary whitespace, NBSP, ZWSP/ZWNJ/ZWJ/BOM → one space)
 * 2. bash-like quote removal / backslash unescaping within words, including
 *    ANSI-C quotes (`r""m`, `"rm"`, `\rm`, `$'rm'` → `rm`)
 * Semantically different wrappers (`bash -c`, `env`, `/bin/rm`, …) stay
 * unmatched by design — admins author rules against the command text.
 * Fail closed: an invalid rule still blocks.
 */

/**
 * Builds denylist candidates. The submitted text supports whole-command
 * rules; parsed `fullText` entries expose nested commands but retain source
 * quotes and escapes, which the matcher normalizes later.
 */
export function deriveAdminCommandDenylistMatchForms({
  command,
  parsingResult,
}: {
  command: string;
  parsingResult: Pick<AdminCommandParsingResult, "executableCommands">;
}): string[] {
  return [
    ...new Set([
      command,
      ...parsingResult.executableCommands.map(c => c.fullText),
    ]),
  ];
}

const ANSI_C_ESCAPES: Readonly<Record<string, string>> = {
  a: "\u0007",
  b: "\b",
  e: "\u001b",
  E: "\u001b",
  f: "\f",
  n: "\n",
  r: "\r",
  t: "\t",
  v: "\v",
  "\\": "\\",
  "'": "'",
  '"': '"',
  "?": "?",
};

function canonicalizeCommandForDenylistMatching(command: string): string {
  type QuoteMode = "plain" | "single" | "double" | "ansi";

  let result = "";
  let mode: QuoteMode = "plain";
  let i = 0;

  while (i < command.length) {
    const character = command[i]!;

    if (mode === "plain") {
      if (character === "$" && command[i + 1] === "'") {
        mode = "ansi";
        i += 2;
      } else if (character === "$" && command[i + 1] === '"') {
        mode = "double";
        i += 2;
      } else if (character === "'") {
        mode = "single";
        i++;
      } else if (character === '"') {
        mode = "double";
        i++;
      } else if (character === "\\" && i + 1 < command.length) {
        if (command[i + 1] !== "\n") {
          result += command[i + 1]!;
        }
        i += 2;
      } else {
        result += character;
        i++;
      }
      continue;
    }

    if (mode === "single") {
      if (character === "'") {
        mode = "plain";
      } else {
        result += character;
      }
      i++;
      continue;
    }

    if (mode === "double") {
      if (character === '"') {
        mode = "plain";
        i++;
        continue;
      }
      if (character === "\\" && i + 1 < command.length) {
        const escaped = command[i + 1]!;
        if (
          escaped === "$" ||
          escaped === "`" ||
          escaped === '"' ||
          escaped === "\\" ||
          escaped === "\n"
        ) {
          if (escaped !== "\n") {
            result += escaped;
          }
          i += 2;
          continue;
        }
      }
      result += character;
      i++;
      continue;
    }

    if (character === "'") {
      mode = "plain";
      i++;
      continue;
    }
    if (character !== "\\" || i + 1 >= command.length) {
      result += character;
      i++;
      continue;
    }

    const escaped = command[i + 1]!;
    const namedEscape = ANSI_C_ESCAPES[escaped];
    if (namedEscape !== undefined) {
      result += namedEscape;
      i += 2;
      continue;
    }

    const encoded =
      escaped === "x"
        ? command.slice(i + 2).match(/^[0-9a-fA-F]{1,2}/)?.[0]
        : escaped === "u"
          ? command.slice(i + 2).match(/^[0-9a-fA-F]{1,4}/)?.[0]
          : escaped === "U"
            ? command.slice(i + 2).match(/^[0-9a-fA-F]{1,8}/)?.[0]
            : command.slice(i + 1).match(/^[0-7]{1,3}/)?.[0];
    const isUnicodeEscape = escaped === "u" || escaped === "U";
    const radix = escaped === "x" || isUnicodeEscape ? 16 : 8;
    if (encoded !== undefined) {
      const value = Number.parseInt(encoded, radix);
      if (!isUnicodeEscape || value <= 0x10ffff) {
        result += isUnicodeEscape
          ? String.fromCodePoint(value)
          : String.fromCharCode(value);
        i += encoded.length + (radix === 16 ? 2 : 1);
        continue;
      }
    }

    result += escaped;
    i += 2;
  }

  return normalizeAdminCommandDenylistText(result);
}

export function matchAdminCommandDenylistRule({
  rule,
  command,
}: {
  rule: string;
  command: string;
}): boolean {
  const trimmedRule = normalizeAdminCommandDenylistText(rule).trim();
  if (trimmedRule.length === 0) {
    return false;
  }
  if (getAdminCommandDenylistRuleError(trimmedRule) !== null) {
    // Stored malformed rules must fail closed even if they predate current
    // author-time and backend validation.
    return true;
  }
  // Match the command raw, whitespace-normalized, and shell-dequoted.
  // Whitespace normalization catches separator evasion (`rm\t-rf`); the raw
  // form keeps glob rules like `kubectl * delete *` matching commands whose
  // extra spacing is itself the text between literal-space-delimited
  // wildcards (`kubectl  delete pod`); dequoting catches quote/escape
  // evasion of the same executable (`r""m`, `"rm"`, `\rm`). The union only
  // ever widens matching.
  return [
    command.trim(),
    normalizeAdminCommandDenylistText(command).trim(),
    canonicalizeCommandForDenylistMatching(command).trim(),
  ].some(commandForm => matchRuleAgainstCommand(trimmedRule, commandForm));
}

function matchRuleAgainstCommand(
  trimmedRule: string,
  trimmedCommand: string
): boolean {
  // Colon syntax: `executable:argsPattern`, split at the first `:`. Mirrors
  // the allowlist matcher: when the colon interpretation does not match, fall
  // through to the glob/prefix modes on the full rule text.
  const colonRule = parseAdminCommandDenylistColonRule(trimmedRule);
  if (colonRule !== undefined) {
    const { executablePattern, argsPattern } = colonRule;
    const spaceIdx = trimmedCommand.indexOf(" ");
    const executable =
      spaceIdx === -1 ? trimmedCommand : trimmedCommand.slice(0, spaceIdx);
    const argsText =
      spaceIdx === -1 ? "" : trimmedCommand.slice(spaceIdx + 1).trim();
    if (
      matchesCommandGlob(executablePattern, executable) &&
      matchesCommandGlob(argsPattern, argsText)
    ) {
      return true;
    }
  }

  // Glob: the full rule must match the entire command string.
  if (trimmedRule.includes("*")) {
    return matchesCommandGlob(trimmedRule, trimmedCommand);
  }

  // Prefix: equal, or command starts with the rule followed by a space.
  return (
    trimmedCommand === trimmedRule ||
    trimmedCommand.startsWith(`${trimmedRule} `)
  );
}

/**
 * Returns the first matching denylist rule, or undefined if none match.
 */
export function findMatchingAdminCommandDenylistPattern({
  matchForms,
  blockedCommands,
}: {
  matchForms: readonly string[];
  blockedCommands: readonly string[];
}): string | undefined {
  const rules = blockedCommands
    .map(entry => entry.trim())
    .filter(entry => entry.length > 0);
  if (rules.length === 0) {
    return undefined;
  }

  const forms = matchForms
    .map(form => form.trim())
    .filter(form => form.length > 0);
  // Whitespace-only commands leave no forms after trim. Still evaluate rules
  // against "" so malformed fail-closed paths cannot be skipped.
  const effectiveForms = forms.length > 0 ? forms : [""];

  for (const rule of rules) {
    if (
      effectiveForms.some(command =>
        matchAdminCommandDenylistRule({ rule, command })
      )
    ) {
      return rule;
    }
  }
  return undefined;
}

/**
 * Model-visible block message. Per the denylist RFC, the agent is informed
 * that the command was blocked and was not executed, and that it can continue
 * working so long-running workflows are not stalled. The message deliberately
 * does NOT instruct the agent to find an alternative mechanism — whether to
 * try a different approach or report the block is left to the agent's own
 * judgment. It must never stall the turn waiting for an approval that cannot
 * be granted.
 */
export function formatAdminCommandDenylistBlockReason(pattern: string): string {
  return (
    `Denied: this command was blocked by administrator policy (denylist rule: ${pattern}) and was not executed. ` +
    `It cannot be approved from this conversation; only a user can run it manually outside the agent. ` +
    `You may continue working on the task.`
  );
}

/**
 * Fail-closed model-Shell gate over the turn snapshot from ShellArgs.
 * Does not re-read `admin_command_denylist_enforcement_killswitch`.
 * That lever empties rules in TeamSettingsService.getAdminCommandDenylist()
 * and must omit them when assembling RequestContext. An in-flight snapshot
 * stays in force until the Shell tool is recreated.
 */
export function getModelShellAdminCommandDenylistBlockReason({
  command,
  parsingResult,
  blockedCommands,
}: {
  command: string;
  parsingResult: AdminCommandParsingResult;
  blockedCommands: readonly string[];
}): string | undefined {
  if (blockedCommands.length === 0) {
    return undefined;
  }

  if (
    parsingResult.parsingFailed ||
    parsingResult.executableCommands.length === 0
  ) {
    return ADMIN_COMMAND_DENYLIST_UNANALYZABLE_REASON;
  }

  const matchedPattern = findMatchingAdminCommandDenylistPattern({
    matchForms: deriveAdminCommandDenylistMatchForms({
      command,
      parsingResult,
    }),
    blockedCommands,
  });
  return matchedPattern === undefined
    ? undefined
    : formatAdminCommandDenylistBlockReason(matchedPattern);
}
