import { homedir } from "node:os";
import { join, relative, sep } from "node:path";
import { isDescendant } from "@anysphere/git-core";

const CURSOR_PROJECTS_ROOT = join(homedir(), ".cursor", "projects");
const CURSOR_WORKTREES_ROOT = join(homedir(), ".cursor", "worktrees");

/**
 * Returns internal directory name for a given path, e.g. /home/user/.cursor/projects/agent-tools/file.txt -> "agent-tools"
 */
export function getCursorProjectsInternalDir(
  absolutePath: string
): string | undefined {
  if (!isDescendant(CURSOR_PROJECTS_ROOT, absolutePath)) {
    return undefined;
  }
  if (absolutePath === CURSOR_PROJECTS_ROOT) {
    return undefined;
  }

  const rest = relative(CURSOR_PROJECTS_ROOT, absolutePath);
  const parts = rest.split(sep).filter(Boolean);
  return parts.length >= 2 ? parts[1] : undefined;
}

/**
 * Checks if path is anywhere under ~/.cursor/projects/.
 * Used to bypass cursorIgnore for Cursor's own internal data
 * (agent transcripts, tool results, etc.).
 */
export function isCursorProjectsPath(absolutePath: string): boolean {
  return (
    isDescendant(CURSOR_PROJECTS_ROOT, absolutePath) &&
    absolutePath !== CURSOR_PROJECTS_ROOT
  );
}

/**
 * Checks if path is anywhere under ~/.cursor/worktrees/.
 * Used to allow internal Cursor worktree operations without out-of-workspace prompts.
 */
export function isCursorWorktreesPath(absolutePath: string): boolean {
  return (
    isDescendant(CURSOR_WORKTREES_ROOT, absolutePath) &&
    absolutePath !== CURSOR_WORKTREES_ROOT
  );
}

/**
 * Returns worktree root for a path under ~/.cursor/worktrees/, e.g.
 * /home/user/.cursor/worktrees/repo-id/app/layout.tsx -> /home/user/.cursor/worktrees/repo-id
 */
export function getCursorWorktreeRoot(
  absolutePath: string
): string | undefined {
  if (!isCursorWorktreesPath(absolutePath)) {
    return undefined;
  }

  const rest = relative(CURSOR_WORKTREES_ROOT, absolutePath);
  const parts = rest.split(sep).filter(Boolean);
  if (parts.length === 0) {
    return undefined;
  }
  return join(CURSOR_WORKTREES_ROOT, parts[0]!);
}

/**
 * Checks if path is inside a .cursor/projects/ internal directory
 */
export function isCursorProjectsInternalPath(
  absolutePath: string,
  internalDirs: readonly string[]
): boolean {
  const internalDir = getCursorProjectsInternalDir(absolutePath);
  return internalDir !== undefined && internalDirs.includes(internalDir);
}
