import { SimpleControlledExecHandler } from "./controlled.js";
import { ExecutorResource } from "./remote.js";
import { createResource } from "./resource-provider.js";
import { createClientDeserializer, createClientSerializer, createServerDeserializer, createServerSerializer, } from "./serialization.js";
export const piFindExecutorResource = createResource(execManager => new ExecutorResource(execManager, createServerSerializer("piFindArgs"), createClientDeserializer("piFindResult")), (implementation, controlledExecManager) => {
    controlledExecManager.register(new SimpleControlledExecHandler(implementation, createServerDeserializer("piFindArgs"), createClientSerializer("piFindResult")));
});
