/**
 * Convert an AbortSignal/Context cancellation reason into structured log fields.
 *
 * This is intentionally conservative about including messages: it only includes
 * a message for `Error` and `string` reasons to avoid accidentally stringifying
 * arbitrary objects into logs.
 */
export function getAbortReasonInfo(reason) {
    if (reason instanceof Error) {
        return {
            abortReasonType: "error",
            abortReasonName: reason.name,
            abortReasonMessage: reason.message,
        };
    }
    if (typeof reason === "string") {
        return { abortReasonType: "string", abortReasonMessage: reason };
    }
    if (reason === undefined) {
        return { abortReasonType: "undefined" };
    }
    // Note: `typeof null` is "object". That's fine; we avoid stringifying.
    return { abortReasonType: typeof reason };
}
