export function trimRemotePath(pathname: string): string {
  const normalizedPath = pathname.replace(/\/+$/, "").replace(/\.git$/i, "");
  if (!normalizedPath || normalizedPath === "/") {
    return "";
  }
  return normalizedPath.startsWith("/") ? normalizedPath : `/${normalizedPath}`;
}

export type RepoUrlWithoutAuth = string;
export type RepoUrlWithAuth = string;

function toSanitizationCandidate(rawUrl: string): string {
  const hasScheme = /^[a-z][a-z0-9+.-]*:\/\//i.test(rawUrl);
  if (hasScheme) {
    return rawUrl;
  }

  // First try treating the value as an HTTPS URL. This handles schemeless userinfo
  // forms like "user:token@github.com/org/repo" without leaking credentials.
  const httpsCandidate = `https://${rawUrl}`;
  try {
    void new URL(httpsCandidate);
    return httpsCandidate;
  } catch {
    // Convert SCP-style remotes (git@host:path) into a URL the parser understands.
    const scpLikeMatch = rawUrl.match(/^([^@/\s]+@)?([^:/\s]+):(.+)$/);
    if (scpLikeMatch) {
      const userInfo = scpLikeMatch[1] ?? "";
      const host = scpLikeMatch[2];
      const path = scpLikeMatch[3];
      return `ssh://${userInfo}${host}/${path}`;
    }
    return httpsCandidate;
  }
}

function toRepoAuthUrl(raw: string | URL): URL {
  return raw instanceof URL
    ? new URL(raw.toString())
    : new URL(toSanitizationCandidate(raw));
}

function stripRepoAuthUrlParts(url: URL): void {
  url.username = "";
  url.password = "";
  url.search = "";
  url.hash = "";
}

function buildSanitizedRepoIdentity(host: string, pathname: string): string {
  const normalizedPath = trimRemotePath(pathname);
  if (!normalizedPath) {
    return "";
  }
  return `${host}${normalizedPath}`.toLowerCase();
}

export function getBoundedRepoAuthPathname(pathname: string): string {
  return `${trimRemotePath(pathname)}.git/`;
}

export function normalizeRepoUrlForAuthLookup(
  repoUrl: string | URL
): RepoUrlWithoutAuth {
  const normalized = toRepoAuthUrl(repoUrl);
  stripRepoAuthUrlParts(normalized);
  normalized.pathname = trimRemotePath(normalized.pathname);
  return normalized.toString();
}

export function buildRepoUrlForAuthRefresh(
  repoUrl: string | URL,
  host: string
): RepoUrlWithoutAuth {
  const refreshUrl = toRepoAuthUrl(repoUrl);
  stripRepoAuthUrlParts(refreshUrl);
  // `host` intentionally includes the port. Self-hosted GitLab can expose a
  // different external host:port for pods than the user-facing repo URL.
  refreshUrl.host = host;
  return refreshUrl.toString();
}

const sanitizedRemoteUrlCache = new Map<string, string>();
const SANITIZED_REMOTE_URL_CACHE_MAX_SIZE = 2048;

/**
 * Strip protocol, auth credentials, and `.git` suffix from a remote URL.
 * Produces a normalized form like `github.com/org/repo` safe for storage and comparison.
 */
export function sanitizeRemoteUrl(raw: string): string {
  const cached = sanitizedRemoteUrlCache.get(raw);
  if (cached !== undefined) {
    return cached;
  }
  const sanitized = computeSanitizedRemoteUrl(raw);
  if (sanitizedRemoteUrlCache.size >= SANITIZED_REMOTE_URL_CACHE_MAX_SIZE) {
    sanitizedRemoteUrlCache.clear();
  }
  sanitizedRemoteUrlCache.set(raw, sanitized);
  return sanitized;
}

function computeSanitizedRemoteUrl(raw: string): string {
  const rawUrl = raw.trim();
  if (!rawUrl) {
    return "";
  }

  try {
    const candidate = toSanitizationCandidate(rawUrl);
    const parsed = new URL(candidate);
    return buildSanitizedRepoIdentity(parsed.hostname, parsed.pathname);
  } catch {
    // Keep a defensive fallback for malformed values so we still strip common
    // credential-bearing prefixes before storage/comparison.
    const fallback = rawUrl.replace(/^(?:https?|ssh|git):\/\//i, "");
    const firstSlash = fallback.indexOf("/");
    const authority =
      firstSlash === -1 ? fallback : fallback.slice(0, firstSlash);
    const path = firstSlash === -1 ? "" : fallback.slice(firstSlash);
    const sanitizedAuthority = authority.includes("@")
      ? authority.slice(authority.lastIndexOf("@") + 1)
      : authority;
    return buildSanitizedRepoIdentity(sanitizedAuthority, path);
  }
}

/**
 * Strip credentials from a remote URL while preserving scheme and port for cloud use.
 * For schemeless inputs, defaults to `https://`.
 * Example:
 *   https://user:token@ghe.example.com:8443/org/repo.git -> https://ghe.example.com:8443/org/repo
 */
export function sanitizeRemoteUrlForHttpUrl(raw: string): string {
  const rawUrl = raw.trim();
  if (!rawUrl) {
    return "";
  }

  try {
    const parsed = new URL(toSanitizationCandidate(rawUrl));
    const protocol =
      parsed.protocol === "http:" || parsed.protocol === "https:"
        ? parsed.protocol
        : "https:";
    const host = parsed.host.toLowerCase();
    const normalizedPath = trimRemotePath(parsed.pathname);
    if (!normalizedPath) {
      return "";
    }
    return `${protocol}//${host}${normalizedPath}`;
  } catch {
    const normalized = sanitizeRemoteUrl(rawUrl);
    return normalized ? `https://${normalized}` : "";
  }
}

export type CloudRepoAvailability =
  | { readonly status: "available" }
  | { readonly status: "needs_github_connect"; readonly repoUrl: string }
  | { readonly status: "repo_not_accessible"; readonly repoUrl: string }
  | { readonly status: "no_repo" };

export const ORIGIN_REPO_CLONE_HOST = "origin.cursor.com";

/**
 * True when the host is an Origin git host (origin.cursor.com, or an env host
 * like origin-staging / origin-test). Re-exported by cursor-plugins.
 */
export function isOriginGitHost(host: string): boolean {
  return /^origin(-[a-z0-9]+)?\.cursor\.com$/i.test(host);
}

function parseRemoteUrlForOriginCheck(rawUrl: string): URL | undefined {
  let url = rawUrl.trim();
  if (url === "") {
    return undefined;
  }

  if (url.startsWith("git@")) {
    url = `https://${url.slice("git@".length).replace(":", "/")}`;
  } else if (
    /^[a-z][a-z0-9+.-]*:\/\//i.test(url) &&
    !/^https?:\/\//i.test(url)
  ) {
    url = url.replace(/^[a-z][a-z0-9+.-]*:\/\//i, "https://");
  } else if (!/^https?:\/\//i.test(url)) {
    url = `https://${url}`;
  }

  try {
    return new URL(url);
  } catch {
    return undefined;
  }
}

export interface OriginRepoIdentity {
  readonly owner: string;
  readonly name: string;
}

type OriginRepoCloneUrlParts = {
  hostname: string;
  owner: string;
  name: string;
};

const originRepoClonePartsCache = new Map<
  string,
  OriginRepoCloneUrlParts | undefined
>();
const ORIGIN_REPO_CLONE_PARTS_CACHE_MAX_SIZE = 2048;

/** Host-bearing parse of a recognized Origin clone URL (legacy or GitHub
 * shape, Origin hosts only; URL, schemeless, and SCP-style remotes). Callers
 * with extra acceptance (e.g. localhost dev) layer their carve-out on top. */
export function parseOriginRepoCloneUrlParts(
  remoteUrl: string | undefined
): { hostname: string; owner: string; name: string } | undefined {
  if (remoteUrl === undefined) {
    return undefined;
  }
  if (originRepoClonePartsCache.has(remoteUrl)) {
    return originRepoClonePartsCache.get(remoteUrl);
  }
  const parts = computeOriginRepoCloneUrlParts(remoteUrl);
  if (
    originRepoClonePartsCache.size >= ORIGIN_REPO_CLONE_PARTS_CACHE_MAX_SIZE
  ) {
    originRepoClonePartsCache.clear();
  }
  originRepoClonePartsCache.set(remoteUrl, parts);
  return parts;
}

function computeOriginRepoCloneUrlParts(
  remoteUrl: string
): OriginRepoCloneUrlParts | undefined {
  const parsed = remoteUrl
    ? parseRemoteUrlForOriginCheck(remoteUrl)
    : undefined;
  if (parsed === undefined || !isOriginGitHost(parsed.hostname)) {
    return undefined;
  }
  const segments = trimRemotePath(parsed.pathname).split("/").filter(Boolean);
  const isLegacyShape =
    segments.length === 3 && segments[0]?.toLowerCase() === "git";
  const isRootShape =
    segments.length === 2 && segments[0]?.toLowerCase() !== "git";
  if (!isLegacyShape && !isRootShape) {
    return undefined;
  }
  const owner = isLegacyShape ? segments[1] : segments[0];
  const name = isLegacyShape ? segments[2] : segments[1];
  if (!owner || !name) {
    return undefined;
  }
  return Object.freeze({ hostname: parsed.hostname, owner, name });
}

/** Parse an Origin clone URL (legacy `/git/<owner>/<repo>` or GitHub-shaped
 * `<owner>/<repo>`, on any Origin env host) into its owner and repo name. URL,
 * schemeless, and SCP-style remotes are supported. */
export function parseOriginRepoCloneUrl(
  remoteUrl: string | undefined
): OriginRepoIdentity | undefined {
  const parts = parseOriginRepoCloneUrlParts(remoteUrl);
  return parts === undefined
    ? undefined
    : { owner: parts.owner, name: parts.name };
}

/** Legacy-shape identity (`<hostname>/git/<owner>/<repo>`, lowercased) for any
 * recognized Origin remote — matches `sanitizeRemoteUrl` on legacy clone URLs
 * so mixed-shape remotes of the same repo compare equal; undefined otherwise. */
export function originRepoCloneIdentity(
  remoteUrl: string | undefined
): string | undefined {
  const parts = parseOriginRepoCloneUrlParts(remoteUrl);
  if (parts === undefined) {
    return undefined;
  }
  return `${parts.hostname}/git/${parts.owner}/${parts.name}`.toLowerCase();
}

/** Comparison key for a repo URL. Any Origin clone shape folds onto the one
 * legacy identity so mixed-shape remotes of a repo compare equal; a non-Origin
 * URL keeps `sanitizeRemoteUrl`'s output byte for byte. */
export function repoComparisonKey(repoUrl: string): string {
  return originRepoCloneIdentity(repoUrl) ?? sanitizeRemoteUrl(repoUrl);
}

/** Returns true when `remoteUrl` is a recognized Origin clone URL (legacy,
 * GitHub-shaped, or SSH). */
export function isOriginBackedRemoteUrl(
  remoteUrl: string | undefined
): boolean {
  return parseOriginRepoCloneUrl(remoteUrl) !== undefined;
}

/** Primary URL plus optional verified GitHub mirror from GetRepoWithMirrorInfo. */
export function getVerifiedMirrorEnvironmentCandidateRepoUrls({
  primaryRepoUrl,
  githubMirrorRepoUrl,
}: {
  primaryRepoUrl: string;
  githubMirrorRepoUrl?: string;
}): string[] {
  const candidates: string[] = [];
  const seen = new Set<string>();
  const pushUnique = (repoUrl: string | undefined): void => {
    const trimmed = repoUrl?.trim();
    if (!trimmed) {
      return;
    }
    const key = repoComparisonKey(trimmed);
    if (key.length === 0 || seen.has(key)) {
      return;
    }
    seen.add(key);
    candidates.push(trimmed);
  };

  pushUnique(primaryRepoUrl);
  pushUnique(githubMirrorRepoUrl);
  return candidates;
}

export function repoUrlMatchesAnyCandidate(
  repoUrl: string,
  candidateRepoUrls: readonly string[]
): boolean {
  const key = repoComparisonKey(repoUrl);
  if (key.length === 0) {
    return false;
  }
  return candidateRepoUrls.some(
    candidate => repoComparisonKey(candidate) === key
  );
}

export interface GetCloudRepoAvailabilityOptions {
  readonly selectedTargetRepoUrls: Iterable<string>;
  readonly cloudProjectRepoUrls: Iterable<string>;
  /** When true, Origin selected URLs are cloud-eligible without GitHub App match. */
  readonly allowOriginRepos?: boolean;
}

function isGithubDotcomRepoUrl(repoUrl: string): boolean {
  return repoUrl.startsWith("github.com/");
}

function isOriginRepoUrl(repoUrl: string): boolean {
  return isOriginBackedRemoteUrl(repoUrl);
}

export function getCloudRepoAvailability({
  allowOriginRepos,
  cloudProjectRepoUrls,
  selectedTargetRepoUrls,
}: GetCloudRepoAvailabilityOptions): CloudRepoAvailability {
  const selectedUrls = new Set<string>();
  for (const repoUrl of selectedTargetRepoUrls) {
    const sanitized = repoComparisonKey(repoUrl);
    if (sanitized.length > 0) {
      selectedUrls.add(sanitized);
    }
  }

  const cloudUrls = new Set<string>();
  for (const repoUrl of cloudProjectRepoUrls) {
    const sanitized = repoComparisonKey(repoUrl);
    if (sanitized.length > 0) {
      cloudUrls.add(sanitized);
    }
  }

  if (allowOriginRepos) {
    const firstOriginRepoUrl = [...selectedUrls].find(isOriginRepoUrl);
    if (firstOriginRepoUrl) {
      return { status: "available" };
    }
  }

  // A selected repo that matches one of the user's cloud projects is
  // cloud-eligible regardless of host: personal/team environments can point at
  // GitLab/Bitbucket/self-hosted remotes the backend already knows how to run.
  // This must run before the github.com gate below so non-GitHub repos with a
  // matching cloud project don't get misreported as `no_repo` (which reads as
  // "connect GitHub" in the UI even when no GitHub flow is wanted).
  for (const selectedUrl of selectedUrls) {
    if (cloudUrls.has(selectedUrl)) {
      return { status: "available" };
    }
  }

  const firstGithubRepoUrl = [...selectedUrls].find(isGithubDotcomRepoUrl);
  if (!firstGithubRepoUrl) {
    return { status: "no_repo" };
  }

  if (cloudUrls.size === 0) {
    return {
      status: "needs_github_connect",
      repoUrl: firstGithubRepoUrl,
    };
  }

  return {
    status: "repo_not_accessible",
    repoUrl: firstGithubRepoUrl,
  };
}
