import { ExecClientMessage, ExecServerMessage, } from "@anysphere/proto/agent/v1/exec_pb.js";
// Remote Ser-de
/**
 * Create a serializer that accepts plain args and returns plain ExecServerMessage.
 */
export function createServerSerializer(argsKey) {
    function serialize(id, args) {
        return new ExecServerMessage({
            id,
            message: { case: argsKey, value: args },
        });
    }
    return serialize;
}
/**
 * Create a deserializer that extracts from plain ExecClientMessage.
 */
export function createClientDeserializer(resultKey) {
    return (result) => {
        if (result.message.case !== resultKey) {
            return undefined;
        }
        return result.message.value;
    };
}
// Controlled Ser-de
export function createClientSerializer(resultKey) {
    function serialize(id, result) {
        const message = {
            case: resultKey,
            value: result,
        };
        return new ExecClientMessage({
            id,
            message,
        });
    }
    return serialize;
}
export function createServerDeserializer(argsKey) {
    function deserialize(result) {
        if (result.message.case !== argsKey) {
            return undefined;
        }
        return { id: result.id, args: result.message.value };
    }
    return deserialize;
}
