export type McpOAuthCredentialInvalidationScope =
  | "tokens"
  | "client"
  | "verifier"
  | "all";

export type McpOAuthPermanentGrantFailureReason =
  | "client_id_mismatch"
  | "issued_to_different_client"
  | "grant_not_found"
  | "refresh_token_revoked"
  | "refresh_token_does_not_exist"
  | "refresh_token_expired"
  | "invalid_grant_generic";

export interface McpOAuthPermanentGrantFailure {
  readonly reason: McpOAuthPermanentGrantFailureReason;
  readonly matchedMessage: string;
}

export interface ClassifyMcpOAuthPermanentGrantFailureOptions {
  readonly allowInvalidGrantGeneric?: boolean;
}

const PERMANENT_GRANT_ERROR_NAMES: ReadonlySet<string> = new Set([
  "InvalidGrantError",
  "InvalidRequestError",
]);

const RETRYABLE_REFRESH_ERROR_NAMES: ReadonlySet<string> = new Set([
  "SiblingAlreadyRefreshedError",
  "OAuthRefreshTransientError",
  "AbortError",
  "TimeoutError",
  "ServerError",
  "TemporarilyUnavailableError",
]);

const PERMANENT_GRANT_MESSAGE_PATTERNS: ReadonlyArray<{
  readonly reason: McpOAuthPermanentGrantFailureReason;
  readonly needle: string;
}> = [
  { reason: "client_id_mismatch", needle: "client id mismatch" },
  { reason: "client_id_mismatch", needle: "client_id mismatch" },
  {
    reason: "issued_to_different_client",
    needle: "issued to different client",
  },
  {
    reason: "issued_to_different_client",
    needle: "issued to another client",
  },
  { reason: "grant_not_found", needle: "grant not found" },
  { reason: "refresh_token_revoked", needle: "has been revoked" },
  { reason: "refresh_token_revoked", needle: "token revoked" },
  {
    reason: "refresh_token_does_not_exist",
    needle: "refresh token does not exist",
  },
  // Spacelift reports an expired refresh token as `invalid_request` with
  // "token has expired" (RFC 6749 §5.2 says this should be `invalid_grant`).
  // The name gate above already restricts matching to InvalidGrantError /
  // InvalidRequestError, so this cannot fire for non-OAuth errors.
  { reason: "refresh_token_expired", needle: "token has expired" },
  { reason: "refresh_token_expired", needle: "token is expired" },
  { reason: "refresh_token_expired", needle: "token expired" },
];

const INVALID_GRANT_GENERIC_PATTERNS: readonly string[] = [
  "invalid refresh token",
  "refresh token is invalid",
  "invalid or expired refresh token",
  "failed to refresh token",
  "invalid_grant",
];

interface ErrorLike {
  readonly name?: unknown;
  readonly message?: unknown;
}

function asErrorLike(error: unknown): ErrorLike | undefined {
  if (error instanceof Error) {
    return error;
  }
  if (error !== null && typeof error === "object") {
    return error as ErrorLike;
  }
  return undefined;
}

function normalizeMessage(value: unknown): string {
  return typeof value === "string" ? value.toLowerCase().trim() : "";
}

export function classifyMcpOAuthPermanentGrantFailure(
  error: unknown,
  options?: ClassifyMcpOAuthPermanentGrantFailureOptions
): McpOAuthPermanentGrantFailure | undefined {
  const errLike = asErrorLike(error);
  if (errLike === undefined) {
    return undefined;
  }

  const name = typeof errLike.name === "string" ? errLike.name : "";
  if (RETRYABLE_REFRESH_ERROR_NAMES.has(name)) {
    return undefined;
  }
  if (!PERMANENT_GRANT_ERROR_NAMES.has(name)) {
    return undefined;
  }

  const message = normalizeMessage(errLike.message);
  for (const { reason, needle } of PERMANENT_GRANT_MESSAGE_PATTERNS) {
    if (message.includes(needle)) {
      return { reason, matchedMessage: message };
    }
  }

  if (options?.allowInvalidGrantGeneric) {
    for (const needle of INVALID_GRANT_GENERIC_PATTERNS) {
      if (message.includes(needle)) {
        return { reason: "invalid_grant_generic", matchedMessage: message };
      }
    }
  }

  return undefined;
}
