/**
 * AsyncCache — single-flight TTL cache with optional stale-while-revalidate.
 *
 * Used by lifecycle code that needs to cache infrequently-changing values
 * (tool lists, prompts, resources, instructions) and tolerate concurrent
 * callers. The `invalidateKeepingStale` mode lets the next read return the
 * previous value immediately while a background refresh runs.
 */

export class AsyncCache<T> {
  private state:
    | {
        expiresAt: number;
        value: T;
      }
    | undefined;

  /** When true, `get` returns the last value immediately and refreshes in the background (single-flight). */
  private staleDirty = false;
  private refreshInFlight: Promise<void> | undefined;
  /** Bumps when `invalidate()` runs so in-flight refreshes do not write after a hard clear. */
  private refreshGeneration = 0;

  constructor(private readonly ttl: number = 1000 * 60 * 60 * 24) {}

  async get(fetcher: () => Promise<T>): Promise<T> {
    const now = performance.now();
    if (this.state && this.state.expiresAt > now && !this.staleDirty) {
      return this.state.value;
    }

    if (this.staleDirty && this.state) {
      const staleValue = this.state.value;
      if (!this.refreshInFlight) {
        const gen = this.refreshGeneration;
        let refreshPromise: Promise<void> | undefined;
        refreshPromise = (async () => {
          try {
            const value = await fetcher();
            if (gen !== this.refreshGeneration) {
              return;
            }
            this.state = { expiresAt: performance.now() + this.ttl, value };
            this.staleDirty = false;
          } catch {
            // Keep serving stale until the next successful refresh.
          } finally {
            if (refreshPromise && this.refreshInFlight === refreshPromise) {
              this.refreshInFlight = undefined;
            }
          }
        })();
        this.refreshInFlight = refreshPromise;
      }
      return staleValue;
    }

    const value = await fetcher();
    this.state = { expiresAt: performance.now() + this.ttl, value };
    this.staleDirty = false;
    return value;
  }

  invalidate(): void {
    this.refreshGeneration++;
    this.state = undefined;
    this.staleDirty = false;
    this.refreshInFlight = undefined;
  }

  /**
   * Mark the cache stale but keep the last resolved value visible.
   * The next `get` returns that value immediately and kicks off a single in-flight refresh.
   * No-op if there is no cached value.
   */
  invalidateKeepingStale(): void {
    if (!this.state) {
      return;
    }
    this.staleDirty = true;
  }
}
