/**
 * Event-sourced input logger for polished recording preprocessing.
 *
 * Instead of polling cursor position, we log events precisely when
 * xdotool commands complete, capturing the ground truth of what happened.
 */

import type { ComputerUseAction } from "@anysphere/proto/agent/v1/computer_use_tool_pb.js";
import { CursorType } from "@anysphere/proto/agent/v1/recording_data_pb.js";
import { CoordinateScaler } from "./scaling.js";
import { exec } from "./shell.js";
import type { ResolutionConfig } from "./types.js";

/**
 * A single input event captured at execution time.
 */
export interface InputEvent {
  /** Timestamp when xdotool command COMPLETED (ms since recording start) */
  executionTimestampMs: number;

  /** The action that was executed */
  action: ComputerUseAction;

  /** How long the xdotool command took to execute (ms) */
  commandDurationMs: number;

  /** Cursor position BEFORE this action (in API coordinates) */
  positionBefore: { x: number; y: number };

  /** Cursor position AFTER this action (in API coordinates) */
  positionAfter: { x: number; y: number };

  /** Cursor type AFTER this action */
  cursorTypeAfter: CursorType;
}

/**
 * Configuration for the InputEventLogger.
 */
export interface InputEventLoggerConfig {
  displayNum?: number;
  resolution: ResolutionConfig;
}

/**
 * X11 cursor name to CursorType mapping.
 * Based on common X11 cursor names from xdotool and X11 cursor themes.
 */
const X11_CURSOR_MAP: Record<string, CursorType> = {
  // Arrow cursors
  left_ptr: CursorType.ARROW,
  arrow: CursorType.ARROW,
  default: CursorType.ARROW,
  top_left_arrow: CursorType.ARROW,

  // Pointer/hand cursors
  hand: CursorType.POINTER,
  hand1: CursorType.POINTER,
  hand2: CursorType.POINTER,
  pointer: CursorType.POINTER,
  pointing_hand: CursorType.POINTER,

  // Text cursors
  xterm: CursorType.TEXT,
  ibeam: CursorType.TEXT,
  text: CursorType.TEXT,

  // Wait/loading cursors
  watch: CursorType.WAIT,
  wait: CursorType.WAIT,
  progress: CursorType.WAIT,
  left_ptr_watch: CursorType.WAIT,

  // Crosshair cursors
  crosshair: CursorType.CROSSHAIR,
  cross: CursorType.CROSSHAIR,
  tcross: CursorType.CROSSHAIR,

  // Move cursors
  move: CursorType.MOVE,
  fleur: CursorType.MOVE,
  size_all: CursorType.MOVE,

  // Resize cursors
  sb_v_double_arrow: CursorType.RESIZE_NS,
  v_double_arrow: CursorType.RESIZE_NS,
  ns_resize: CursorType.RESIZE_NS,
  row_resize: CursorType.RESIZE_NS,
  top_side: CursorType.RESIZE_NS,
  bottom_side: CursorType.RESIZE_NS,

  sb_h_double_arrow: CursorType.RESIZE_EW,
  h_double_arrow: CursorType.RESIZE_EW,
  ew_resize: CursorType.RESIZE_EW,
  col_resize: CursorType.RESIZE_EW,
  left_side: CursorType.RESIZE_EW,
  right_side: CursorType.RESIZE_EW,

  top_left_corner: CursorType.RESIZE_NWSE,
  bottom_right_corner: CursorType.RESIZE_NWSE,
  nwse_resize: CursorType.RESIZE_NWSE,
  size_fdiag: CursorType.RESIZE_NWSE,

  top_right_corner: CursorType.RESIZE_NESW,
  bottom_left_corner: CursorType.RESIZE_NESW,
  nesw_resize: CursorType.RESIZE_NESW,
  size_bdiag: CursorType.RESIZE_NESW,

  // Not allowed cursors
  not_allowed: CursorType.NOT_ALLOWED,
  no_drop: CursorType.NOT_ALLOWED,
  forbidden: CursorType.NOT_ALLOWED,
  circle: CursorType.NOT_ALLOWED,

  // Grab cursors
  grab: CursorType.GRAB,
  openhand: CursorType.GRAB,
  grabbing: CursorType.GRABBING,
  closedhand: CursorType.GRABBING,
};

/**
 * InputEventLogger captures precise input events during recording.
 *
 * Key insight: Since the CUA controls all input via xdotool, we know
 * exactly what actions were performed. Instead of polling cursor position,
 * we log events at the moment each xdotool command completes.
 *
 * This gives us:
 * - Precise timing (when the command finished, not when it was requested)
 * - Clean waypoints for cursor path generation
 * - Accurate cursor type detection after each action
 */
export class InputEventLogger {
  private events: InputEvent[] = [];
  private recordingStartTime: number = 0;
  private lastKnownPosition: { x: number; y: number } = { x: 0, y: 0 };
  private isRunning: boolean = false;
  private pending: Promise<void> = Promise.resolve();

  private readonly env: Record<string, string>;
  private readonly scaler: CoordinateScaler;

  constructor(config: InputEventLoggerConfig) {
    const displayNum = config.displayNum ?? 1;
    this.env = { DISPLAY: `:${displayNum}` };
    this.scaler = new CoordinateScaler(config.resolution);
  }

  /**
   * Start logging events. Call this when recording begins.
   */
  async start(): Promise<void> {
    this.events = [];
    this.recordingStartTime = Date.now();
    this.isRunning = true;
    this.pending = Promise.resolve();

    try {
      this.lastKnownPosition = await this.captureCurrentPosition();
    } catch {
      this.lastKnownPosition = {
        x: Math.floor(this.scaler.apiWidth / 2),
        y: Math.floor(this.scaler.apiHeight / 2),
      };
    }
  }

  /**
   * Log an input event after an xdotool command completes.
   *
   * @param action - The action that was executed
   * @param commandStartTime - When the command started (Date.now())
   * @param commandEndTime - When the command completed (Date.now())
   */
  logEvent(
    action: ComputerUseAction,
    commandStartTime: number,
    commandEndTime: number
  ): void {
    if (!this.isRunning) {
      return;
    }

    const positionBefore = { ...this.lastKnownPosition };

    // Update lastKnownPosition optimistically to handle rapid sequential events
    // This prevents stale positionBefore values when events are queued faster than processed
    const expectedPosition = this.getExpectedPositionAfterAction(
      action,
      positionBefore
    );
    this.lastKnownPosition = expectedPosition;

    const task = async (): Promise<void> => {
      // Capture current position and cursor type after the action
      let positionAfter: { x: number; y: number };
      let cursorTypeAfter: CursorType;

      try {
        [positionAfter, cursorTypeAfter] = await Promise.all([
          this.captureCurrentPosition(),
          this.detectCursorType(),
        ]);
        // Update with actual captured position (corrects any drift)
        this.lastKnownPosition = positionAfter;
      } catch {
        // Fallback if capture fails - use the expected position
        positionAfter = expectedPosition;
        cursorTypeAfter = CursorType.ARROW;
      }

      const event: InputEvent = {
        executionTimestampMs: commandEndTime - this.recordingStartTime,
        action,
        commandDurationMs: commandEndTime - commandStartTime,
        positionBefore,
        positionAfter,
        cursorTypeAfter,
      };

      this.events.push(event);
    };

    this.pending = this.pending.then(() => task()).catch(() => {});
  }

  /**
   * Stop logging and return all captured events.
   */
  async stop(): Promise<InputEvent[]> {
    this.isRunning = false;
    await this.pending;
    return [...this.events];
  }

  /**
   * Get all events captured so far (without stopping).
   */
  getEvents(): InputEvent[] {
    return [...this.events];
  }

  /**
   * Get the recording start time (for timestamp calculations).
   */
  getRecordingStartTime(): number {
    return this.recordingStartTime;
  }

  /**
   * Check if the logger is currently running.
   */
  getIsRunning(): boolean {
    return this.isRunning;
  }

  /**
   * Capture current cursor position via xdotool.
   */
  private async captureCurrentPosition(): Promise<{ x: number; y: number }> {
    const output = await exec("xdotool", ["getmouselocation", "--shell"], {
      env: this.env,
    });

    const xMatch = output.match(/X=(\d+)/);
    const yMatch = output.match(/Y=(\d+)/);

    if (!xMatch || !yMatch) {
      throw new Error(`Failed to parse cursor position: ${output}`);
    }

    const displayX = parseInt(xMatch[1], 10);
    const displayY = parseInt(yMatch[1], 10);

    return this.scaler.displayToApi(displayX, displayY);
  }

  /**
   * Detect current cursor type via X11.
   *
   * We use xdotool's getmouselocation which can optionally include cursor info,
   * or fall back to inferring from the action type.
   */
  private async detectCursorType(): Promise<CursorType> {
    try {
      // Try to get cursor name from xdotool (not all versions support this)
      const output = await exec("xdotool", ["getmouselocation", "--shell"], {
        env: this.env,
      });

      // Look for CURSOR= in output (some xdotool versions include this)
      const cursorMatch = output.match(/CURSOR=(\S+)/i);
      if (cursorMatch) {
        const cursorName = cursorMatch[1].toLowerCase();
        return X11_CURSOR_MAP[cursorName] ?? CursorType.ARROW;
      }

      // Try using xprop to query the cursor (more reliable but slower)
      try {
        const xpropOutput = await exec("xprop", ["-root", "_XSERVER_CURSOR"], {
          env: this.env,
          timeoutMs: 500,
        });

        // Parse cursor name from xprop output
        for (const [name, type] of Object.entries(X11_CURSOR_MAP)) {
          if (xpropOutput.toLowerCase().includes(name)) {
            return type;
          }
        }
      } catch {
        // xprop not available or failed, continue with default
      }

      return CursorType.ARROW;
    } catch {
      return CursorType.ARROW;
    }
  }

  /**
   * Get expected position after an action based on the action type.
   * Used as fallback if actual position capture fails.
   */
  private getExpectedPositionAfterAction(
    action: ComputerUseAction,
    positionBefore: { x: number; y: number }
  ): { x: number; y: number } {
    const actionOneof = action.action;
    if (!actionOneof) {
      return positionBefore;
    }

    switch (actionOneof.case) {
      case "mouseMove": {
        const coord = actionOneof.value.coordinate;
        if (coord) {
          return { x: coord.x, y: coord.y };
        }
        break;
      }

      case "click": {
        const coord = actionOneof.value.coordinate;
        if (coord) {
          return { x: coord.x, y: coord.y };
        }
        break;
      }

      case "drag": {
        const path = actionOneof.value.path;
        if (path.length > 0) {
          const lastPoint = path[path.length - 1];
          return { x: lastPoint.x, y: lastPoint.y };
        }
        break;
      }

      case "scroll": {
        const coord = actionOneof.value.coordinate;
        if (coord) {
          return { x: coord.x, y: coord.y };
        }
        break;
      }

      default:
        // For keyboard actions, position doesn't change
        break;
    }

    return positionBefore;
  }
}
