import { createKey, type ContextKey } from "@anysphere/context";
import type { ExecServerMessage } from "@anysphere/proto/agent/v1/exec_pb.js";

import {
	SAND_DEFAULT_LOCAL_TOOL_PERMISSION,
	sandLocalToolActionLabel,
	type SandLocalToolAction,
	type SandLocalToolPermission,
	type SandLocalToolPermissionResolution,
	type SandLocalToolPermissionStatus,
} from "./local-tool-permission.js";

/**
 * The user's standing permission for LOCAL tools — the ones that act on the
 * user's own computer. This module is the process-neutral vocabulary (the gate
 * and scope types, the refusal messages, the description and coverage rules
 * every side applies identically); the host-held coordinator that enforces it
 * lives with its plugin in
 * host/extensions/local-tool-permission/local-tool-permission-controller.ts.
 *
 * The unit of consent is ONE ACTION, not a turn: the card names the concrete
 * command or path, and answering it authorizes exactly that. Each new top-level
 * `ExternalShell`, `ExternalRead`, `CopyToBox`, or `CopyFromBox` asks again.
 *
 * A single approved action is still allowed to be several trips to the machine —
 * one `ExternalShell` invocation opens a stream and reads its own terminal file
 * back, and `AwaitExternalShell` polls that same file afterwards. Those ride the
 * approval rather than re-asking, and they can only do so through two narrow
 * bindings:
 *
 *  - SCOPE: the top-level tool call carries an opaque approval id on its
 *    {@link sandLocalToolScopeKey} context, so every exec that call makes is the
 *    approved action continuing. The scope retires when the tool call returns.
 *  - RESOURCE: an approved `run-command` owns exactly one terminal file, so a
 *    later read of that exact path is honored without a new card. Nothing else
 *    attaches — a read of any other path is its own action.
 *
 * The boundary is the local box port (`SandBox` wired to the user's machine):
 * `ExternalShell`, `ExternalRead`, and `AwaitExternalShell` execute through its
 * resource accessor and `CopyToBox` / `CopyFromBox` through its verbatim
 * upload/download, so the gate lives there
 * (host/extensions/local-exec/gateway-local-exec-sand-box.ts) rather than at the tool
 * registry — a tool the model can still see is refused at execution, and a
 * future caller that reaches for the local box inherits the gate for free.
 *
 * The agent's OWN computer — the box, reached by the unprefixed `Shell`, `Read`,
 * `AwaitShell` plus `Computer` and `Screenshot` — runs against a different box
 * (`remoteBox`) and is deliberately untouched. Only the `External*` prefix
 * crosses onto a machine the user has to consent to.
 */

/** How long an unanswered ask card stays answerable before it fails closed. */
export const SAND_LOCAL_TOOL_ASK_TTL_MS = 10 * 60 * 1000;

/**
 * One top-level local tool call, as the gate sees it. Carried on the Context so
 * every exec the call makes is recognizable as the same action, and so the
 * PRINCIPAL is the runner's canonical conversation id rather than whatever id a
 * particular `ensureReady` call site happened to pass (a computerUse subagent's
 * monitor box id is not the agent whose transcript shows the card).
 */
export interface SandLocalToolScope {
	/** The agent whose transcript renders the card. One canonical id per runner. */
	readonly agentId: string;
	/**
	 * The top-level tool call this work belongs to, when there is one. Absent for
	 * host-side upkeep (the background terminal poller), which is why that path
	 * can only ever ride an already-approved RESOURCE.
	 */
	readonly toolCallId?: string;
	/**
	 * The user-direction epoch this work started under (see {@link
	 * SandLocalToolPermissionTurns.beginTurn}), captured once when its turn began.
	 *
	 * Work can outlive the direction that started it: a `Task` subagent is
	 * dispatched in the background and keeps running after the user's next
	 * message interrupts its parent. That subagent still carries the OLD epoch,
	 * which is what lets the gate tell an action the user is currently waiting on
	 * from one belonging to a job they have already moved past.
	 *
	 * Absent for call sites with no turn behind them (host upkeep, tests); those
	 * read as the agent's current epoch, so nothing is stale by default.
	 */
	readonly directionEpoch?: number;
	/**
	 * What this tool call is FOR, declared by the tool rather than inferred from
	 * whichever trip to the machine happens to come first.
	 *
	 * It exists because a tool can touch the machine before it does the thing it
	 * was called for: the Shell tool's Auto-review enrichment reads the script or
	 * package.json a command names before running it. Without a declared action
	 * that read would raise the scope's card — the user would be asked to approve
	 * reading a file, and the command would then run under that answer without
	 * ever being named. So a declared scope may only raise a card for its OWN
	 * action; anything else it tries first is refused until the real action is
	 * approved (enrichment treats an unreadable target as unread and continues).
	 */
	readonly action?: SandLocalToolAction;
}

export const sandLocalToolScopeKey: ContextKey<SandLocalToolScope | undefined> = createKey<
	SandLocalToolScope | undefined
>(Symbol("sand.local-tool.scope"), undefined);

/**
 * The direction ONE RUN belongs to, stamped on that run's context when it began
 * and read back at the moment a tool reaches the machine.
 *
 * On the context rather than on the runner, because a runner can have two runs
 * in flight: the queue watchdog releases a wedged run's slot and lets it keep
 * streaming while a successor turn starts on the same runner (see
 * host/extensions/transcript/run-scheduler.ts). A shared field would hand the
 * escaped run the successor's direction at execution time — which is exactly
 * the standing it must not inherit. The same reason `sandQuietWorkOriginKey`
 * carries provenance here instead of on the runner.
 */
export const sandTurnDirectionEpochKey: ContextKey<number | undefined> = createKey<
	number | undefined
>(Symbol("sand.local-tool.direction-epoch"), undefined);

// Actionable for the MODEL, not just the user: each names the disabled surface
// and points at the box tools that still work, so a turn pivots instead of
// retrying the same refusal.
export const SAND_LOCAL_TOOLS_DISABLED_MESSAGE =
	'Local tools are turned off. The user has set local tool access to "Never", so ExternalShell, ExternalRead, AwaitExternalShell, CopyToBox, and CopyFromBox cannot run on their computer. Do not retry them while this setting remains "Never". Use your own computer instead (Shell, Read, AwaitShell), or ask the user to change the setting in Settings → Agent → Execution on Local Computer. If they change it away from "Never", you may try again.';

export const SAND_LOCAL_TOOLS_DENIED_MESSAGE =
	"The user declined this action on their computer. Do not retry it. Do something else, use your own computer instead (Shell, Read, AwaitShell), or ask them what they would prefer.";

export const SAND_LOCAL_TOOLS_ASK_EXPIRED_MESSAGE =
	"The request to run this on the user's computer went unanswered, so nothing ran. Use your own computer instead (Shell, Read, AwaitShell), or tell the user you are waiting on their approval.";

export const SAND_LOCAL_TOOLS_ASK_UNAVAILABLE_MESSAGE =
	"Using the user's computer needs their permission, and this conversation has nowhere to ask for it. Use your own computer instead (Shell, Read, AwaitShell), or do this from a direct chat with the user.";

// Raised by the machine-side backstop, not the ask flow: work arrived at the
// user's computer without an approval that machine had recorded.
// Raised when the gate cannot describe what an exec would do. Consent has to
// name the action, so an unnameable one is refused wherever consent is needed.
export const SAND_LOCAL_TOOLS_UNDESCRIBABLE_MESSAGE =
	"Grok Bot could not describe that request to the user's computer, so it could not ask permission for it and did not run it. Use your own computer instead (Shell, Read, AwaitShell).";

export const SAND_LOCAL_TOOLS_UNAPPROVED_MESSAGE =
	'That action was not approved on the user\'s computer, so nothing ran. Ask the user to approve it (or to set Settings → Agent → Execution on Local Computer to "Always allow"), and use your own computer (Shell, Read, AwaitShell) in the meantime.';

// The user was shown this exact action and did not approve it. Widening the
// standing setting afterwards is consent for what happens NEXT, not a
// retroactive answer to a card they walked away from, so the refusal outlives
// the setting change for the work that raised it.
export const SAND_LOCAL_TOOLS_ABANDONED_MESSAGE =
	"The user was already asked about this exact action on their computer and did not approve it, so it will not run and will not be asked again for this task — a later permission change does not authorize it. Do not retry it. If it still needs to happen, say so in chat and let the user ask for it, and use your own computer in the meantime (Shell, Read, AwaitShell).";

// The whole task is closed to the machine, not one action: either the agent was
// torn down, or its direction is one whose individual refusals can no longer be
// held exactly and so is refused wholesale. Forgetting a denial must never widen
// access, which is what makes bounding that memory safe.
export const SAND_LOCAL_TOOLS_STALE_TASK_MESSAGE =
	"This task's earlier requests to use the user's computer were not approved and the user has since moved on, so nothing from this task will run there. Do not retry. If it still needs to happen, say so in chat and let the user ask for it, and use your own computer in the meantime (Shell, Read, AwaitShell).";

// Refused rather than asked: consent for this tool call has to name the thing
// the call is actually for, so preparatory work cannot become the card.
export const SAND_LOCAL_TOOLS_PREPARATORY_MESSAGE =
	"That preparatory access to the user's computer was skipped: the user is asked about the action itself, not the work leading up to it. Continue without it.";

/**
 * What the caller is about to do on the user's machine, in the words the card
 * shows. `target` is the concrete command or path — the thing the user is
 * actually approving.
 */
export interface SandLocalToolRequest {
	readonly action: SandLocalToolAction;
	readonly target: string;
	/**
	 * Plain-English what the agent is about to do. Display-only on the ask
	 * card; never part of the consent binding (that is {@link target}).
	 */
	readonly description?: string;
	/**
	 * The one resource this action owns, if any. A `run-command` owns its
	 * terminal file; a later read of that exact path is the same action
	 * continuing (AwaitShell, or the host's background poll) rather than a new
	 * one. Nothing else may attach to an approval.
	 */
	readonly resourcePath?: string;
	/**
	 * A resource this action WANTS to attach to. When it names a live approval's
	 * resource the action rides that approval; otherwise it is its own action and
	 * asks on its own.
	 */
	readonly attachToResourcePath?: string;
	/**
	 * Whether the action keeps running after the tool call that started it
	 * returns. A backgrounded command does, and reading its output afterwards is
	 * the point of backgrounding it, so its approval lives until the user's next
	 * message instead of retiring with the call.
	 */
	readonly outlivesScope?: boolean;
	readonly signal?: AbortSignal;
}

export type SandLocalToolAuthorization =
	| {
			readonly allowed: true;
			/**
			 * The opaque id the user's machine will check this work against, or
			 * undefined when the standing setting is "always" (nothing to check).
			 */
			readonly approvalId?: string;
	  }
	| { readonly allowed: false; readonly reason: string };

/**
 * The execution-layer gate the local box consults before every trip to the
 * user's machine. `authorize` may suspend (the "ask" state) but never rejects;
 * every non-approval path is a deny carrying model-readable text.
 */
export interface SandLocalToolGate {
	authorize(
		scope: SandLocalToolScope | undefined,
		request: SandLocalToolRequest,
	): Promise<SandLocalToolAuthorization>;
	/** The top-level tool call finished; its approval must not outlive it. */
	completeScope(scope: SandLocalToolScope | undefined): void;
	/**
	 * The synchronous, total "is the whole surface off" check for transport-level
	 * backstops that have no action to name. Returns the refusal text when the
	 * standing permission is `never`, otherwise undefined.
	 */
	blockedReason(): string | undefined;
	/**
	 * Whether an action has to be named and approved before it may run. False for
	 * the two absolute states, where there is nothing to ask — which is what lets
	 * a caller that cannot describe its work still run under "always".
	 */
	requiresApproval(): boolean;
}

export interface SandLocalToolPermissionRequest {
	readonly id: string;
	readonly agentId: string;
	readonly action: SandLocalToolAction;
	readonly target: string;
	readonly status: SandLocalToolPermissionStatus;
	readonly createdAtMs: number;
	readonly expiresAtMs: number;
	/** Plain-English what the agent is about to do (display only). */
	readonly description?: string;
}

export type SandLocalToolPermissionEvent =
	| { readonly type: "created"; readonly request: SandLocalToolPermissionRequest }
	| { readonly type: "settled"; readonly request: SandLocalToolPermissionRequest };

/**
 * The turn-boundary half of the coordinator, as the runner sees it: the runner
 * announces new user direction and knows nothing else about the permission.
 */
export interface SandLocalToolPermissionTurns {
	beginTurn(agentId: string): void;
	/**
	 * The top-level tool call that owns this scope has returned, so its approval
	 * must not outlive it. Called for every local tool call, approved or not.
	 */
	completeScope(scope: SandLocalToolScope | undefined): void;
	/**
	 * The agent's current user-direction epoch, for a turn to stamp onto the
	 * scopes it opens (see {@link SandLocalToolScope.directionEpoch}). Read once
	 * at the top of a turn; reading it per tool call would give work that
	 * outlived the user's next message the CURRENT epoch and hide exactly the
	 * staleness this exists to expose.
	 */
	directionEpoch(agentId: string): number;
	/**
	 * First-run desktop Yes/No before Auto-review may present a host-shell card.
	 * When the standing permission is still "ask", suspends for that decision;
	 * otherwise returns immediately from the standing value.
	 */
	awaitDesktopStandingDecision(args: {
		readonly agentId: string;
		readonly toolCallId: string;
		readonly signal?: AbortSignal;
		/** Concrete host command about to run (display + consent target). */
		readonly command?: string;
		/** Model-authored English description of what that command does. */
		readonly description?: string;
	}): Promise<SandLocalToolAuthorization>;
}

// The card carries the command or path VERBATIM — no collapsing, no eliding —
// because the user's answer authorizes what they read. Anything too large to
// show honestly is refused instead.
export const SAND_LOCAL_TOOLS_TARGET_TOO_LARGE_MESSAGE =
	"That action is too long to show the user for approval, so it was not run. Split it into smaller steps, or use your own computer instead (Shell, Read, AwaitShell).";

// Resource paths are compared exactly, so every side must agree on the
// separator: the desktop advertises a Windows terminals folder with `\`, while
// the paths built from it are joined with `/`. Exported for the controller,
// which binds approvals to the same normalized form.
export function normalizeResourcePath(path: string | undefined): string | undefined {
	if (path === undefined || path.length === 0) return undefined;
	return path.replace(/\\/g, "/");
}

/**
 * The terminal file one shell owns: one file per shell under the folder the
 * desktop advertises. The id is assigned by the executor when the shell starts,
 * not by the tool call, which is why an approval binds to the FOLDER (see
 * {@link describeLocalExec}) rather than to a path it could predict up front.
 */
export function sandTerminalFilePath(terminalsFolder: string, shellId: string): string | undefined {
	if (shellId.length === 0) return undefined;
	return `${normalizeSeparators(terminalsFolder)}/${shellId}.txt`;
}

function normalizeSeparators(path: string): string {
	return path.replace(/\\/g, "/").replace(/\/+$/, "");
}

/**
 * Whether a path is a shell's own output file: directly inside the folder the
 * desktop advertises for terminals, and nothing deeper. That folder holds only
 * the output of commands, which is what makes it the resource an approved
 * command owns.
 */
function isTerminalFile(path: string, terminalsFolder: string): boolean {
	const folder = normalizeSeparators(terminalsFolder);
	if (folder.length === 0) return false;
	const normalized = normalizeSeparators(path);
	if (!normalized.startsWith(`${folder}/`)) return false;
	const rest = normalized.slice(folder.length + 1);
	return rest.length > 0 && !rest.includes("/") && rest.endsWith(".txt");
}

/**
 * Thrown at the execution layer when the user's standing permission (or their
 * answer to an ask card) refuses this action. The message is written for the
 * model: it says what is off and names the box tools to use instead.
 */
export class SandLocalToolPermissionDeniedError extends Error {
	constructor(reason: string) {
		super(reason);
		this.name = "SandLocalToolPermissionDeniedError";
	}
}

/** Consults the gate and throws the model-readable refusal when it says no. */
export async function authorizeLocalToolAction(
	gate: SandLocalToolGate,
	scope: SandLocalToolScope | undefined,
	request: SandLocalToolRequest,
): Promise<string | undefined> {
	const decision = await gate.authorize(scope, request);
	if (!decision.allowed) {
		throw new SandLocalToolPermissionDeniedError(decision.reason);
	}
	return decision.approvalId;
}

/**
 * What one exec is about to do on the user's machine, in the terms the ask card
 * names. Derived from the CONCRETE serialized arguments, never from the tool
 * that produced them — which is what lets the user's machine re-derive the same
 * description independently and check it against what the user actually saw.
 *
 * Covers every case the local box's executors can produce: shell (foreground,
 * background spawn, promote-to-background, stdin), read (plain and redacted),
 * and ls. A kind it does not know is left undescribed, because consent cannot
 * be asked for — or checked against — something that cannot be named.
 */
export function describeLocalExec(
	serverMessage: ExecServerMessage,
	terminalsFolder: string,
): Omit<SandLocalToolRequest, "signal"> | undefined {
	const message = serverMessage.message;
	switch (message.case) {
		case "shellStreamArgs":
		case "backgroundShellSpawnArgs":
			return {
				action: "run-command",
				target: message.value.command,
				// A command owns its output. Which file that is only becomes known when
				// the shell starts (the executor numbers it), so the approval binds to
				// the terminals folder itself — the place where nothing lives but the
				// output of commands.
				resourcePath: terminalsFolder,
				// A backgrounded command outlives the call that started it, and reading
				// its output afterwards is the whole point of backgrounding it. It
				// arrives either as a dedicated spawn or as a stream flagged
				// background, depending on how the Shell tool started it.
				...(message.case === "backgroundShellSpawnArgs" || message.value.isBackground
					? { outlivesScope: true }
					: {}),
			};
		case "forceBackgroundShellArgs":
			// The command already running under this tool call, moving to the
			// background: it names no new work, it just means the command — and so
			// its approval — now outlives the call that started it.
			return {
				action: "run-command",
				target: "a command already running",
				attachToResourcePath: terminalsFolder,
				outlivesScope: true,
			};
		case "writeShellStdinArgs":
			// Typing into a live command is its own effect on the machine, and the
			// input is the concrete thing to approve — the numeric shell id it
			// targets is not a path, so it binds to no resource.
			return { action: "send-input", target: message.value.chars };
		case "readArgs":
		case "redactedReadArgs": {
			const path = message.value.path;
			return {
				action: "read-file",
				target: path,
				// Reading a command's own output is that command continuing —
				// AwaitShell, or the host's background poll — so it rides that
				// command's approval. Only output files qualify; every other path is
				// its own action.
				...(isTerminalFile(path, terminalsFolder) ? { attachToResourcePath: terminalsFolder } : {}),
			};
		}
		case "lsArgs":
			return { action: "list-directory", target: message.value.path };
		default:
			return undefined;
	}
}

/** The two facts an approval is bound to: what the card named, and what it owns. */
export interface SandLocalToolApprovalBinding {
	readonly action: SandLocalToolAction;
	readonly target: string;
	/** The terminal file an approved command owns, once it is known. */
	readonly resourcePath?: string;
}

/**
 * Whether one trip to the user's machine is covered by an approval, applied
 * IDENTICALLY by the host and by the user's own machine.
 *
 * An approval covers exactly two things: the action the card named, and reads
 * of the one resource that action owns (a command's terminal file, which is how
 * AwaitShell and the background poll follow it). Everything else is a different
 * action and needs its own answer — so a live id cannot be attached to some
 * other command or path than the one the user saw.
 */
export function localToolApprovalCovers(
	approval: SandLocalToolApprovalBinding,
	request: Pick<SandLocalToolRequest, "action" | "target" | "attachToResourcePath">,
): boolean {
	if (approval.action === request.action && approval.target === request.target) {
		return true;
	}
	const owned = normalizeResourcePath(approval.resourcePath);
	const wanted = normalizeResourcePath(request.attachToResourcePath);
	return owned !== undefined && owned === wanted;
}

/** A gate that always allows, for call sites with no permission wiring (tests). */
export const allowAllLocalTools: SandLocalToolGate = {
	authorize: async () => ({ allowed: true }),
	completeScope: () => {},
	blockedReason: () => undefined,
	requiresApproval: () => false,
};

export { SAND_DEFAULT_LOCAL_TOOL_PERMISSION, sandLocalToolActionLabel };
export type {
	SandLocalToolAction,
	SandLocalToolPermission,
	SandLocalToolPermissionResolution,
	SandLocalToolPermissionStatus,
};
