import type { AuthState, ConnectionState } from '../fsm/types.js';
import {
	FOCUS_RETRY_MINIMUM_COOLDOWN_MS,
	getFocusRetryCooldownMs,
} from './mcp-focus-retry-cooldown.js';
import {
	getMcpReconnectConfigValue,
	type McpReconnectConfigContext,
} from './mcp-reconnect-config.js';

/** Matches cursor-mcp `probeAllConnected`: health probes only when fully connected. */
export function shouldProbeOnConnectivityRecovery(state: ConnectionState | undefined): boolean {
	return state?.type === 'connected';
}

export function isNonRetryablePeriodicFailureState(connectionState: ConnectionState): boolean {
	return (
		(connectionState.type === 'failed' || connectionState.type === 'closed')
		&& connectionState.automaticRetry === false
	);
}

/**
 * Matches cursor-mcp `retryPeriodicLifecycleIfUnblocked` eligibility for wake/network recovery.
 */
export function shouldFastTrackReconnectOnConnectivityRecovery(
	connectionState: ConnectionState,
	authState: AuthState,
	context?: McpReconnectConfigContext,
): boolean {
	if (connectionState.type !== 'failed' && connectionState.type !== 'closed') {
		return false;
	}

	if (connectionState.automaticRetry === false) {
		if (getMcpReconnectConfigValue('retryNonRetryableOnWake', context) !== true) {
			return false;
		}
	}

	if (authState.type === 'needsUserAuth' || authState.type === 'expired') {
		return false;
	}

	return true;
}

export function getConnectivityRecoveryRetryCooldownMs(
	connectionState: ConnectionState,
	context?: McpReconnectConfigContext,
): number {
	if (isNonRetryablePeriodicFailureState(connectionState)) {
		return getMcpReconnectConfigValue('nonRetryableWakeRetryCooldownMs', context) ?? FOCUS_RETRY_MINIMUM_COOLDOWN_MS;
	}
	return getFocusRetryCooldownMs(context);
}
