export interface TTLCacheOptions {
  /**
   * Entry lifetime. A function is read on every write, so a process-level
   * setting can be changed after the cache exists; entries already written
   * keep the lifetime they were given.
   */
  ttlMs: number | (() => number);
  now?: () => number;
}

type TTLCacheEntry<V> = {
  value: V;
  expiresAtMs: number;
};

/**
 * Small TTL cache with lazy expiration on read/check.
 */
export class TTLCache<K, V> {
  private readonly ttlMs: () => number;
  private readonly now: () => number;
  private readonly entries = new Map<K, TTLCacheEntry<V>>();

  constructor({ ttlMs, now = Date.now }: TTLCacheOptions) {
    this.ttlMs =
      typeof ttlMs === "function" ? ttlMs : TTLCache.validated(ttlMs);
    this.now = now;
  }

  private static validated(ttlMs: number): () => number {
    if (!Number.isFinite(ttlMs) || ttlMs <= 0) {
      throw new Error(`TTL cache requires a positive ttlMs, got ${ttlMs}`);
    }
    return () => ttlMs;
  }

  get(key: K): V | undefined {
    const entry = this.entries.get(key);
    if (entry === undefined) {
      return undefined;
    }

    if (entry.expiresAtMs <= this.now()) {
      this.entries.delete(key);
      return undefined;
    }

    return entry.value;
  }

  has(key: K): boolean {
    const entry = this.entries.get(key);
    if (entry === undefined) {
      return false;
    }

    if (entry.expiresAtMs <= this.now()) {
      this.entries.delete(key);
      return false;
    }

    return true;
  }

  set(key: K, value: V): void {
    this.entries.set(key, {
      value,
      expiresAtMs: this.now() + this.ttlMs(),
    });
  }

  delete(key: K): boolean {
    return this.entries.delete(key);
  }

  clear(): void {
    this.entries.clear();
  }
}
