import type { MCPServerInfo } from '../fsm/types.js';
import { getMcpServerUrlHostname } from '../transport/mcp-url-utils.js';

export type McpReconnectConfigFields = {
	fastRetryBaseDelayMs?: number;
	fastRetryMaxDelayMs?: number;
	fastRetryMaxAttempts?: number;
	periodicRetryBaseDelayMs?: number;
	periodicRetryMaxDelayMs?: number;
	maxPeriodicCycles?: number;
	focusRetryCooldownMs?: number;
	inlineReconnectCooldownMs?: number;
	streamableHttpSession404TombstoneThreshold?: number;
	healthProbeTimeoutMs?: number;
	/**
	 * Kill switch for AQ-1514 progress-aware tool-call timeouts.
	 * When false, desktop tool calls use the legacy hard 1-hour timeout.
	 */
	toolCallBoundedTimeoutEnabled?: boolean;
	/** Idle silence before a tool call times out (progress resets this). */
	toolCallIdleTimeoutMs?: number;
	/** Absolute wall-clock cap for one tool call, even with progress. */
	toolCallMaxTotalTimeoutMs?: number;
	degradedProbeDelayMs?: number;
	maxDegradedProbeFailures?: number;
	keepaliveProbeDelayMs?: number;
	keepaliveJitterMs?: number;
	stabilityThresholdMs?: number;
	stdioConnectFailuresAreNonRetryable?: boolean;
	retryNonRetryableOnWake?: boolean;
	retryNonRetryableAutomatically?: boolean;
	networkResumeReconnectEnabled?: boolean;
	networkResumeReconnectDebounceMs?: number;
	nonRetryableWakeRetryCooldownMs?: number;
};

export type McpReconnectConfigOverride = McpReconnectConfigFields & {
	identifier?: string;
	hostname?: string;
};

type McpReconnectConfig = McpReconnectConfigFields & {
	overrides?: McpReconnectConfigOverride[];
};

export type McpReconnectConfigContext = {
	identifier: string;
	serverInfo?: MCPServerInfo;
};

const NUMERIC_FIELDS = [
	'fastRetryBaseDelayMs',
	'fastRetryMaxDelayMs',
	'fastRetryMaxAttempts',
	'periodicRetryBaseDelayMs',
	'periodicRetryMaxDelayMs',
	'maxPeriodicCycles',
	'focusRetryCooldownMs',
	'inlineReconnectCooldownMs',
	'streamableHttpSession404TombstoneThreshold',
	'healthProbeTimeoutMs',
	'toolCallIdleTimeoutMs',
	'toolCallMaxTotalTimeoutMs',
	'degradedProbeDelayMs',
	'maxDegradedProbeFailures',
	'keepaliveProbeDelayMs',
	'keepaliveJitterMs',
	'stabilityThresholdMs',
	'nonRetryableWakeRetryCooldownMs',
	'networkResumeReconnectDebounceMs',
] as const satisfies ReadonlyArray<keyof McpReconnectConfigFields>;

const BOOLEAN_FIELDS = [
	'stdioConnectFailuresAreNonRetryable',
	'retryNonRetryableOnWake',
	'retryNonRetryableAutomatically',
	'networkResumeReconnectEnabled',
	'toolCallBoundedTimeoutEnabled',
] as const satisfies ReadonlyArray<keyof McpReconnectConfigFields>;

let cachedReconnectConfig: McpReconnectConfig = {};

function parseOptionalNumber(
	config: Record<string, unknown>,
	key: keyof McpReconnectConfigFields,
): number | undefined {
	const value = config[key];
	return typeof value === 'number' && Number.isFinite(value) ? value : undefined;
}

function parseOptionalBoolean(config: Record<string, unknown>, key: keyof McpReconnectConfigFields): boolean | undefined {
	const value = config[key as string];
	return typeof value === 'boolean' ? value : undefined;
}

function copyNumericFields(config: Record<string, unknown>): McpReconnectConfigFields {
	const next: McpReconnectConfigFields = {};
	for (const key of NUMERIC_FIELDS) {
		const value = parseOptionalNumber(config, key);
		if (value !== undefined) {
			next[key] = value;
		}
	}
	for (const key of BOOLEAN_FIELDS) {
		const value = parseOptionalBoolean(config, key);
		if (value !== undefined) {
			next[key] = value;
		}
	}
	return next;
}

function parseOverride(value: unknown): McpReconnectConfigOverride | undefined {
	if (!value || typeof value !== 'object') {
		return undefined;
	}

	const record = value as Record<string, unknown>;
	const identifier = typeof record.identifier === 'string' && record.identifier.length > 0
		? record.identifier
		: undefined;
	const hostname = typeof record.hostname === 'string' && record.hostname.length > 0
		? record.hostname.toLowerCase()
		: undefined;
	if (identifier === undefined && hostname === undefined) {
		return undefined;
	}

	return {
		...copyNumericFields(record),
		...(identifier !== undefined ? { identifier } : {}),
		...(hostname !== undefined ? { hostname } : {}),
	};
}

function getServerHostname(serverInfo: MCPServerInfo | undefined): string | undefined {
	if (!serverInfo || serverInfo.type === 'stdio') {
		return undefined;
	}
	return getMcpServerUrlHostname(serverInfo.serverUrl);
}

function matchesOverride(
	override: McpReconnectConfigOverride,
	context: McpReconnectConfigContext | undefined,
): boolean {
	if (!context) {
		return false;
	}
	if (override.identifier !== undefined && override.identifier !== context.identifier) {
		return false;
	}
	if (override.hostname !== undefined) {
		const serverHostname = getServerHostname(context.serverInfo);
		if (!serverHostname || serverHostname !== override.hostname) {
			return false;
		}
	}
	return true;
}

export function setMcpReconnectConfigFromStatsig(config: unknown): void {
	if (!config || typeof config !== 'object') {
		cachedReconnectConfig = {};
		return;
	}

	const record = config as Record<string, unknown>;
	const overrides = Array.isArray(record.overrides)
		? record.overrides
			.map(parseOverride)
			.filter((override): override is McpReconnectConfigOverride => override !== undefined)
		: undefined;

	cachedReconnectConfig = {
		...copyNumericFields(record),
		...(overrides !== undefined ? { overrides } : {}),
	};
}

export function getMcpReconnectConfigValue<K extends keyof McpReconnectConfigFields>(
	key: K,
	context?: McpReconnectConfigContext,
): McpReconnectConfigFields[K] | undefined {
	let resolved = cachedReconnectConfig[key];
	for (const override of cachedReconnectConfig.overrides ?? []) {
		if (!matchesOverride(override, context)) {
			continue;
		}
		const overrideValue = override[key];
		if (overrideValue !== undefined) {
			resolved = overrideValue;
		}
	}
	return resolved;
}
