export class McpAbortError extends Error {
	readonly isMcpAbortError = true;

	constructor() {
		super('MCP operation aborted');
		this.name = 'McpAbortError';
	}
}

function createAbortError(signal: AbortSignal): Error {
	if (
		signal.reason instanceof Error
		&& !(typeof DOMException !== 'undefined' && signal.reason instanceof DOMException)
	) {
		return signal.reason;
	}
	return new McpAbortError();
}

/**
 * Races `promise` against `signal` so abort rejects promptly even if the underlying
 * MCP/SDK work cannot be cancelled yet.
 */
export function raceWithAbortSignal<T>(promise: Promise<T>, signal: AbortSignal | undefined): Promise<T> {
	if (!signal) {
		return promise;
	}
	if (signal.aborted) {
		// The caller abandoned `promise` due to prior cancellation. Attach a no-op
		// rejection handler so late failures do not surface as unhandled rejections.
		void promise.catch(() => { });
		return Promise.reject(createAbortError(signal));
	}
	return new Promise<T>((resolve, reject) => {
		const onAbort = () => reject(createAbortError(signal));
		signal.addEventListener('abort', onAbort, { once: true });
		promise.then(resolve, reject).finally(() => signal.removeEventListener('abort', onAbort));
	});
}

/**
 * Metadata refresh cancellation means the caller abandoned the read.  It is not
 * evidence that the MCP server changed status or offerings.
 */
export function isAbortError(error: unknown, signal?: AbortSignal): boolean {
	return error instanceof McpAbortError || signal?.aborted === true;
}
