/**
 * Browser-safe helpers for structured log metadata (URL snapshots, core logger emit).
 * Keep free of `node:*` imports so Electron renderer unit tests can load mcp-core OAuth code.
 */
import { getMcpCoreLogger } from "./logger.js";

export type StructuredCoreLogLevel = "debug" | "info" | "warn" | "error";

export interface EmitStructuredCoreLogArgs {
  readonly identifier: string;
  readonly level: StructuredCoreLogLevel;
  readonly message: string;
  readonly metadata: Record<string, unknown>;
  readonly error?: unknown;
}

export function emitStructuredCoreLog(args: EmitStructuredCoreLogArgs): void {
  const logger = getMcpCoreLogger(args.identifier);
  if (args.level === "error") {
    const error =
      args.error instanceof Error
        ? args.error
        : args.error !== undefined
          ? new Error(String(args.error))
          : undefined;
    logger.error(args.message, error, args.metadata);
    return;
  }
  if (args.level === "warn") {
    logger.warn(args.message, args.metadata);
    return;
  }
  if (args.level === "debug") {
    logger.debug?.(args.message, args.metadata);
    return;
  }
  logger.info(args.message, args.metadata);
}

export function compactLogMetadata<T extends Record<string, unknown>>(
  value: T
): T {
  return Object.fromEntries(
    Object.entries(value).filter(([, entry]) => entry !== undefined)
  ) as T;
}

export interface SnapshotUrlForLogOptions {
  /** When false, set `path` to null (remote / privacy-sensitive uploads). Default true. */
  readonly includePath?: boolean;
}

export interface UrlSnapshotForLog {
  readonly host: string | null;
  readonly origin: string | null;
  readonly path: string | null;
}

/** @deprecated Prefer {@link UrlSnapshotForLog}. */
export type McpUrlSnapshotForLog = UrlSnapshotForLog;

function snapshotUrlPartsForLog(url: string): {
  host: string | null;
  origin: string | null;
  pathname: string | null;
} {
  try {
    const parsed = new URL(url);
    return {
      host: parsed.host,
      origin: parsed.origin,
      pathname: parsed.pathname,
    };
  } catch {
    return {
      host: null,
      origin: null,
      pathname: null,
    };
  }
}

export function snapshotUrlForLog(
  url: string,
  options?: SnapshotUrlForLogOptions
): UrlSnapshotForLog {
  const parts = snapshotUrlPartsForLog(url);
  const includePath = options?.includePath !== false;
  return {
    host: parts.host,
    origin: parts.origin,
    path: includePath ? parts.pathname : null,
  };
}

export function snapshotNestedUrlForLog(
  nestedKey: string,
  url: string,
  options?: SnapshotUrlForLogOptions
): Record<string, UrlSnapshotForLog> {
  return { [nestedKey]: snapshotUrlForLog(url, options) };
}

export interface BuildUrlHostMetadataFieldsOptions
  extends SnapshotUrlForLogOptions {
  /** Duplicate `host` under additional Datadog pivot field names. */
  readonly duplicateHostAs?: readonly string[];
}

/** Flat host/origin fields for `mcpMeta.*` pivots without logging full URLs. */
export function buildUrlHostMetadataFields(
  url: string,
  options?: BuildUrlHostMetadataFieldsOptions
): Record<string, string | null> {
  const snapshot = snapshotUrlForLog(url, options);
  const fields: Record<string, string | null> = {
    host: snapshot.host,
    origin: snapshot.origin,
  };
  for (const alias of options?.duplicateHostAs ?? []) {
    fields[alias] = snapshot.host;
  }
  return fields;
}

export function snapshotServerUrlForLog(
  url: string,
  options?: SnapshotUrlForLogOptions
): UrlSnapshotForLog {
  return snapshotUrlForLog(url, options);
}

export function snapshotAuthorizationUrlForLog(
  url: string,
  options?: SnapshotUrlForLogOptions
): UrlSnapshotForLog {
  return snapshotUrlForLog(url, options);
}

/** Nest fields under `mcpAuthMeta` for structured client logs (`@client_log_key:mcp`). */
export function authMetaLogEnvelope(
  fields: Record<string, unknown>
): Record<string, unknown> {
  return { mcpAuthMeta: fields };
}
