import { getMaxDegradedProbeFailures, getStabilityThresholdMs } from '../config/mcp-fsm-timing-config.js';
import { getFastRetryMaxAttempts, getMaxPeriodicCycles } from '../config/mcp-reconnect-runtime-policy.js';
import type { BackoffConfig, ConnectionEvent, ConnectionState, ConnectionTransitionResult } from './types.js';

function resolveMaxAttempts(config: BackoffConfig): number {
	return config.maxAttempts ?? config.getMaxAttempts?.() ?? getFastRetryMaxAttempts();
}

function resolveMaxPeriodicCycles(config: BackoffConfig): number | undefined {
	return config.maxPeriodicCycles !== undefined
		? config.maxPeriodicCycles
		: config.getMaxPeriodicCycles?.() ?? getMaxPeriodicCycles();
}

function resolveStabilityThresholdMs(config: BackoffConfig): number {
	return config.getStabilityThresholdMs?.() ?? getStabilityThresholdMs();
}

function resolveMaxDegradedProbeFailures(config: BackoffConfig): number {
	return config.getMaxDegradedProbeFailures?.() ?? getMaxDegradedProbeFailures();
}

const NO_CHANGE: ConnectionTransitionResult = { state: null, commands: [] };

/**
 * Extract the current generation from a ConnectionState.
 * Only `connecting` carries a generation; other states return 0.
 */
function currentGeneration(state: ConnectionState): number {
	return state.type === 'connecting' ? state.generation : 0;
}

/**
 * Derive the next generation for a new `connecting` state.
 * Monotonically increasing — ensures the ActivityReconciler can
 * detect self-transitions without relying on reference identity.
 */
function nextGeneration(state: ConnectionState): number {
	return currentGeneration(state) + 1;
}

function toIdle(): ConnectionTransitionResult {
	return { state: { type: 'idle' }, commands: [{ type: 'cancel_backoff_timer' }] };
}

function toConnecting(state: ConnectionState, attempt: number, periodicCycle = 0): ConnectionTransitionResult {
	return { state: { type: 'connecting', attempt, generation: nextGeneration(state), periodicCycle }, commands: [] };
}

function toConnectingWithCommands(state: ConnectionState, attempt: number, commands: ConnectionTransitionResult['commands'], periodicCycle = 0): ConnectionTransitionResult {
	return { state: { type: 'connecting', attempt, generation: nextGeneration(state), periodicCycle }, commands };
}

function toFailed(
	error: string,
	config: BackoffConfig,
	periodicCycle = 0,
	automaticRetry = true,
): ConnectionTransitionResult {
	return {
		state: {
			type: 'failed',
			error,
			periodicRetryDelayMs: config.getPeriodicRetryDelay(periodicCycle),
			periodicCycle,
			...(automaticRetry === false ? { automaticRetry: false } : {}),
		},
		commands: [],
	};
}

function toFailedWithCommands(
	error: string,
	config: BackoffConfig,
	commands: ConnectionTransitionResult['commands'],
	periodicCycle = 0,
	automaticRetry = true,
): ConnectionTransitionResult {
	return {
		state: {
			type: 'failed',
			error,
			periodicRetryDelayMs: config.getPeriodicRetryDelay(periodicCycle),
			periodicCycle,
			...(automaticRetry === false ? { automaticRetry: false } : {}),
		},
		commands,
	};
}

function toClosed(
	error: string,
	config: BackoffConfig,
	commands: ConnectionTransitionResult['commands'] = [],
	periodicCycle = 0,
	automaticRetry = true,
): ConnectionTransitionResult {
	return {
		state: {
			type: 'closed',
			error,
			periodicRetryDelayMs: config.getPeriodicRetryDelay(periodicCycle),
			periodicCycle,
			...(automaticRetry === false ? { automaticRetry: false } : {}),
		},
		commands,
	};
}

function toTransientFailure(attempt: number, config: BackoffConfig, periodicCycle = 0): ConnectionTransitionResult {
	const nextDelayMs = config.getBackoffDelay(attempt);
	return {
		state: { type: 'transient_failure', attempt, nextDelayMs, periodicCycle },
		commands: [{ type: 'start_backoff_timer', delayMs: nextDelayMs }],
	};
}

function handleConnectFailure(
	currentAttempt: number,
	error: string,
	isRetryable: boolean,
	config: BackoffConfig,
	periodicCycle = 0,
): ConnectionTransitionResult {
	if (!isRetryable) {
		return toFailed(error, config, periodicCycle, false);
	}
	const nextAttempt = currentAttempt + 1;
	if (nextAttempt >= resolveMaxAttempts(config)) {
		return toFailed(error, config, periodicCycle);
	}
	return toTransientFailure(nextAttempt, config, periodicCycle);
}

function fromIdle(state: ConnectionState, event: ConnectionEvent, config: BackoffConfig): ConnectionTransitionResult {
	switch (event.kind) {
		case 'connect_start':
			return toConnecting(state, 0);
		case 'connect_failure':
			return toFailed(event.error, config, 0, event.isRetryable);
		case 'server_removed':
			// Already idle — no-op
			return NO_CHANGE;
		case 'connect_success':
		case 'transport_error':
		case 'transport_closed':
		case 'session_invalidated':
		case 'idle_suspend':
		case 'backoff_timer_expired':
		case 'connection_stabilized':
		case 'periodic_retry_expired':
		case 'request_degraded':
		case 'health_probe_due':
		case 'health_probe_succeeded':
		case 'health_probe_failed':
			return NO_CHANGE;
		default: {
			const _exhaustive: never = event;
			return _exhaustive;
		}
	}
}

function fromConnecting(state: ConnectionState & { type: 'connecting'; generation: number; periodicCycle: number }, event: ConnectionEvent, config: BackoffConfig): ConnectionTransitionResult {
	switch (event.kind) {
		case 'connect_success':
			return {
				state: { type: 'connected', attempt: state.attempt, stabilized: false, probing: false },
				commands: [{ type: 'cancel_backoff_timer' }, { type: 'start_stability_timer', delayMs: resolveStabilityThresholdMs(config) }],
			};
		case 'connect_failure':
			return handleConnectFailure(state.attempt, event.error, event.isRetryable, config, state.periodicCycle);
		case 'server_removed':
			return toIdle();
		case 'connect_start':
		case 'transport_error':
		case 'transport_closed':
		case 'idle_suspend':
		case 'backoff_timer_expired':
		case 'connection_stabilized':
		case 'periodic_retry_expired':
		case 'request_degraded':
		case 'health_probe_due':
		case 'health_probe_succeeded':
		case 'health_probe_failed':
			return NO_CHANGE;
		case 'session_invalidated':
			// While already connecting, a nested session-invalid signal must bump
			// generation and restart `connection_attempt` (ActivityReconciler case 3).
			// Dropping it as NO_CHANGE can leave a stale in-flight attempt bound to a
			// dead streamable HTTP session.
			return toConnectingWithCommands(state, 0, [{ type: 'initiate_connection' }]);
		default: {
			const _exhaustive: never = event;
			return _exhaustive;
		}
	}
}

function fromConnected(state: ConnectionState & { type: 'connected' }, event: ConnectionEvent, config: BackoffConfig): ConnectionTransitionResult {
	switch (event.kind) {
		case 'connect_start':
			// No-op to avoid spinner flash on reload
			return NO_CHANGE;
		case 'connection_stabilized':
			return { state: { type: 'connected', attempt: 0, stabilized: true, probing: false }, commands: [] };
		case 'transport_error':
			if (event.isRetryable) {
				const nextAttempt = state.stabilized ? 0 : state.attempt + 1;
				if (nextAttempt >= resolveMaxAttempts(config)) {
					return toFailedWithCommands(event.error, config, [{ type: 'cancel_stability_timer' }]);
				}
				return {
					state: { type: 'transient_failure', attempt: nextAttempt, nextDelayMs: config.getBackoffDelay(nextAttempt), periodicCycle: 0 },
					commands: [{ type: 'cancel_stability_timer' }, { type: 'start_backoff_timer', delayMs: config.getBackoffDelay(nextAttempt) }],
				};
			}
			return toFailedWithCommands(event.error, config, [{ type: 'cancel_stability_timer' }], 0, false);
		case 'transport_closed':
			if (event.isStdio) {
				return toClosed('Client closed', config, [{ type: 'cancel_stability_timer' }]);
			}
			{
				const nextAttempt = state.stabilized ? 0 : state.attempt + 1;
				if (nextAttempt >= resolveMaxAttempts(config)) {
					return toFailedWithCommands('Transport closed', config, [{ type: 'cancel_stability_timer' }]);
				}
				return {
					state: { type: 'transient_failure', attempt: nextAttempt, nextDelayMs: config.getBackoffDelay(nextAttempt), periodicCycle: 0 },
					commands: [{ type: 'cancel_stability_timer' }, { type: 'start_backoff_timer', delayMs: config.getBackoffDelay(nextAttempt) }],
				};
			}
		case 'session_invalidated':
			return toConnectingWithCommands(state, 0, [{ type: 'cancel_backoff_timer' }, { type: 'cancel_stability_timer' }, { type: 'initiate_connection' }]);
		case 'idle_suspend':
			// Release the transport but stay logically connected (reconciler cancels the timers).
			return { state: { type: 'dormant' }, commands: [{ type: 'cancel_stability_timer' }] };
		case 'server_removed':
			return { state: { type: 'idle' }, commands: [{ type: 'cancel_backoff_timer' }, { type: 'cancel_stability_timer' }] };
		case 'request_degraded':
			return {
				state: { type: 'degraded', consecutiveFailures: 0, reason: event.reason, probing: false },
				commands: [{ type: 'cancel_stability_timer' }],
			};
		case 'health_probe_due':
			if (state.probing) {
				return NO_CHANGE;
			}
			return { state: { ...state, probing: true }, commands: [] };
		case 'health_probe_succeeded':
			if (!state.probing) {
				return NO_CHANGE;
			}
			return { state: { ...state, probing: false }, commands: [] };
		case 'health_probe_failed':
			return {
				state: { type: 'degraded', consecutiveFailures: 1, reason: event.error, probing: false },
				commands: [{ type: 'cancel_stability_timer' }],
			};
		case 'connect_success':
		case 'connect_failure':
		case 'backoff_timer_expired':
		case 'periodic_retry_expired':
			return NO_CHANGE;
		default: {
			const _exhaustive: never = event;
			return _exhaustive;
		}
	}
}

function fromDegraded(state: ConnectionState & { type: 'degraded' }, event: ConnectionEvent, config: BackoffConfig): ConnectionTransitionResult {
	switch (event.kind) {
		case 'health_probe_due':
			if (state.probing) {
				return NO_CHANGE;
			}
			return { state: { ...state, probing: true }, commands: [] };
		case 'health_probe_succeeded':
			return { state: { type: 'connected', attempt: 0, stabilized: true, probing: false }, commands: [] };
		case 'health_probe_failed': {
			const next = state.consecutiveFailures + 1;
			if (next >= resolveMaxDegradedProbeFailures(config)) {
				return toTransientFailure(0, config);
			}
			return { state: { type: 'degraded', consecutiveFailures: next, reason: event.error, probing: false }, commands: [] };
		}
		case 'request_degraded':
			return { state: { type: 'degraded', consecutiveFailures: 0, reason: event.reason, probing: state.probing }, commands: [] };
		case 'transport_error':
			if (event.isRetryable) {
				return toTransientFailure(0, config);
			}
			return toFailed(event.error, config, 0, false);
		case 'transport_closed':
			if (event.isStdio) {
				return toClosed('Client closed', config);
			}
			return toTransientFailure(0, config);
		case 'session_invalidated':
			return toConnectingWithCommands(state, 0, [{ type: 'cancel_backoff_timer' }, { type: 'initiate_connection' }]);
		case 'server_removed':
			return { state: { type: 'idle' }, commands: [] };
		case 'connect_start':
		case 'connect_success':
		case 'connect_failure':
		case 'idle_suspend':
		case 'backoff_timer_expired':
		case 'connection_stabilized':
		case 'periodic_retry_expired':
			return NO_CHANGE;
		default: {
			const _exhaustive: never = event;
			return _exhaustive;
		}
	}
}

function fromTransientFailure(state: ConnectionState & { type: 'transient_failure' }, event: ConnectionEvent): ConnectionTransitionResult {
	switch (event.kind) {
		case 'backoff_timer_expired':
			return {
				state: { type: 'connecting', attempt: state.attempt, generation: nextGeneration(state), periodicCycle: state.periodicCycle },
				commands: [{ type: 'initiate_connection' }],
			};
		case 'connect_start':
			// Manual reconnect resets attempts
			return toConnectingWithCommands(state, 0, [{ type: 'cancel_backoff_timer' }]);
		case 'server_removed':
			return toIdle();
		case 'connect_success':
		case 'connect_failure':
		case 'transport_error':
		case 'transport_closed':
		case 'session_invalidated':
		case 'idle_suspend':
		case 'connection_stabilized':
		case 'periodic_retry_expired':
		case 'request_degraded':
		case 'health_probe_due':
		case 'health_probe_succeeded':
		case 'health_probe_failed':
			return NO_CHANGE;
		default: {
			const _exhaustive: never = event;
			return _exhaustive;
		}
	}
}

function fromFailed(state: ConnectionState & { type: 'failed' }, event: ConnectionEvent, config: BackoffConfig): ConnectionTransitionResult {
	switch (event.kind) {
		case 'connect_start':
			// Manual reconnect resets cycle counter
			return toConnecting(state, 0);
		case 'periodic_retry_expired': {
			const maxCycles = resolveMaxPeriodicCycles(config);
			if (maxCycles !== undefined && state.periodicCycle >= maxCycles) {
				if (state.exhausted) {
					return NO_CHANGE;
				}
				return {
					state: { ...state, exhausted: true },
					commands: [],
				};
			}
			return toConnecting(state, 0, state.periodicCycle + 1);
		}
		case 'server_removed':
			return { state: { type: 'idle' }, commands: [] };
		case 'connect_success':
		case 'connect_failure':
		case 'transport_error':
		case 'transport_closed':
		case 'session_invalidated':
		case 'idle_suspend':
		case 'backoff_timer_expired':
		case 'connection_stabilized':
		case 'request_degraded':
		case 'health_probe_due':
		case 'health_probe_succeeded':
		case 'health_probe_failed':
			return NO_CHANGE;
		default: {
			const _exhaustive: never = event;
			return _exhaustive;
		}
	}
}

function fromClosed(state: ConnectionState & { type: 'closed' }, event: ConnectionEvent, config: BackoffConfig): ConnectionTransitionResult {
	switch (event.kind) {
		case 'connect_start':
			// Manual reconnect/restart
			return toConnecting(state, 0);
		case 'periodic_retry_expired': {
			const maxCycles = resolveMaxPeriodicCycles(config);
			if (maxCycles !== undefined && state.periodicCycle >= maxCycles) {
				if (state.exhausted) {
					return NO_CHANGE;
				}
				return {
					state: { ...state, exhausted: true },
					commands: [],
				};
			}
			return toConnecting(state, 0, state.periodicCycle + 1);
		}
		case 'server_removed':
			return { state: { type: 'idle' }, commands: [] };
		case 'connect_success':
		case 'connect_failure':
		case 'transport_error':
		case 'transport_closed':
		case 'session_invalidated':
		case 'idle_suspend':
		case 'backoff_timer_expired':
		case 'connection_stabilized':
		case 'request_degraded':
		case 'health_probe_due':
		case 'health_probe_succeeded':
		case 'health_probe_failed':
			return NO_CHANGE;
		default: {
			const _exhaustive: never = event;
			return _exhaustive;
		}
	}
}

function fromDormant(state: ConnectionState & { type: 'dormant' }, event: ConnectionEvent): ConnectionTransitionResult {
	switch (event.kind) {
		case 'connect_start':
		case 'session_invalidated':
			// Demand resumes: a fresh `connecting` makes the reconciler start a new attempt.
			return toConnecting(state, 0);
		case 'server_removed':
			return toIdle();
		case 'idle_suspend':
		case 'connect_success':
		case 'connect_failure':
		case 'transport_error':
		case 'transport_closed':
		case 'backoff_timer_expired':
		case 'connection_stabilized':
		case 'periodic_retry_expired':
		case 'request_degraded':
		case 'health_probe_due':
		case 'health_probe_succeeded':
		case 'health_probe_failed':
			return NO_CHANGE;
		default: {
			const _exhaustive: never = event;
			return _exhaustive;
		}
	}
}

export function connectionTransition(
	state: ConnectionState,
	event: ConnectionEvent,
	config: BackoffConfig,
): ConnectionTransitionResult {
	switch (state.type) {
		case 'idle':
			return fromIdle(state, event, config);
		case 'connecting':
			return fromConnecting(state, event, config);
		case 'connected':
			return fromConnected(state as ConnectionState & { type: 'connected' }, event, config);
		case 'dormant':
			return fromDormant(state as ConnectionState & { type: 'dormant' }, event);
		case 'degraded':
			return fromDegraded(state as ConnectionState & { type: 'degraded' }, event, config);
		case 'transient_failure':
			return fromTransientFailure(state as ConnectionState & { type: 'transient_failure' }, event);
		case 'failed':
			return fromFailed(state as ConnectionState & { type: 'failed' }, event, config);
		case 'closed':
			return fromClosed(state as ConnectionState & { type: 'closed' }, event, config);
		default: {
			const _exhaustive: never = state;
			return _exhaustive;
		}
	}
}
