export function accountMcpServerIdentifier(
  name: string,
  teamId?: number
): string {
  return teamId === undefined
    ? `user-${name}`
    : `dashboard-team-${teamId}-${name}`;
}

export function dashboardAccountMcpServerIdentifier(
  name: string,
  teamId?: number
): string {
  return teamId === undefined
    ? `dashboard-${name}`
    : `dashboard-team-${teamId}-${name}`;
}
