/**
 * Loader for sandbox policy JSON files.
 *
 * Used to load user configuration from:
 * - ~/.cursor/sandbox.json (perUser config)
 * - <workspace>/.cursor/sandbox.json (perRepo config)
 *
 * These files allow users to configure partial sandbox policies.
 * Missing fields use defaults, and the final policy is merged with
 * other sources (perUser, perRepo, teamAdmin, hardcoded).
 */

import { readFile } from "node:fs/promises";
import { resolvePath } from "@anysphere/utils";
import type {
  InsecureNoneSandboxPolicy,
  NetworkPolicy,
  NetworkPolicyLoggingConfig,
  SandboxPolicy,
  WorkspaceReadOnlySandboxPolicy,
  WorkspaceReadWriteSandboxPolicy,
} from "../types.js";

/**
 * JSON schema for partial sandbox policy configuration files.
 * All fields are optional - users only specify what they want to override.
 */
export interface PartialSandboxPolicyJson {
  /**
   * Policy type. Defaults to "workspace_readwrite" if not specified.
   */
  type?: "insecure_none" | "workspace_readwrite" | "workspace_readonly";

  /**
   * Whether network access is allowed. Defaults to false (deny-by-default).
   */
  networkAccess?: boolean;

  /**
   * Fine-grained network access control.
   */
  networkPolicy?: {
    /** Default action when no rules match. */
    default?: "allow" | "deny";
    /** Patterns to allow. */
    allow?: string[];
    /** Patterns to deny (highest priority). */
    deny?: string[];
    /** Logging configuration. */
    logging?: {
      decisionLogPath?: string;
      logFormat?: "jsonl";
    };
  };

  /**
   * When true, any missing or invalid network policy causes network access
   * to be disabled (fail closed).
   */
  networkPolicyStrict?: boolean;

  /**
   * Additional paths with read-write access (only for workspace_readwrite type).
   */
  additionalReadwritePaths?: string[];

  /**
   * Additional paths with read-only access.
   */
  additionalReadonlyPaths?: string[];

  /**
   * Filesystem read boundary. Defaults to "system" for backwards compatibility.
   * Legacy `"custom"` is accepted and normalized to `"workspace"`.
   */
  readBoundary?: "system" | "workspace" | "custom";

  /**
   * Extra read paths allowed when readBoundary is "workspace".
   */
  additionalReadPaths?: string[];

  /**
   * If true, excludes default tmp paths from the sandbox writable paths.
   */
  disableTmpWrite?: boolean;

  /**
   * If true, redirects build tool caches to a shared tmpdir location.
   */
  enableSharedBuildCache?: boolean;

  /**
   * Directory for sandbox debug output.
   */
  debugOutputDir?: string;

  /**
   * If true, captures sandbox deny events for debugging.
   */
  captureDenies?: boolean;
}

/**
 * Result of loading a sandbox policy file.
 */
export type LoadSandboxPolicyResult =
  | { success: true; policy: SandboxPolicy }
  | { success: false; error: string };

/**
 * Parses a NetworkPolicy from JSON.
 */
function parseNetworkPolicy(
  json: PartialSandboxPolicyJson["networkPolicy"]
): NetworkPolicy | undefined {
  if (!json) return undefined;

  const result: NetworkPolicy = {
    version: 1,
  };

  if (json.default === "allow" || json.default === "deny") {
    result.default = json.default;
  }

  if (Array.isArray(json.allow) && json.allow.length > 0) {
    result.allow = json.allow.filter(
      (item): item is string => typeof item === "string"
    );
  }

  if (Array.isArray(json.deny) && json.deny.length > 0) {
    result.deny = json.deny.filter(
      (item): item is string => typeof item === "string"
    );
  }

  if (json.logging) {
    const logging: NetworkPolicyLoggingConfig = {};
    if (typeof json.logging.decisionLogPath === "string") {
      logging.decisionLogPath = json.logging.decisionLogPath;
    }
    if (json.logging.logFormat === "jsonl") {
      logging.logFormat = "jsonl";
    }
    if (Object.keys(logging).length > 0) {
      result.logging = logging;
    }
  }

  return result;
}

/**
 * Parses a partial sandbox policy JSON into a SandboxPolicy.
 * Uses sensible defaults for missing fields.
 *
 * @param json - The parsed JSON object
 * @returns A valid SandboxPolicy
 */
export function parseSandboxPolicyJson(
  json: PartialSandboxPolicyJson
): SandboxPolicy {
  const type = json.type ?? "workspace_readwrite";

  // Common fields for all policy types
  const commonFields = {
    debugOutputDir: json.debugOutputDir,
    captureDenies: json.captureDenies,
    enableSharedBuildCache: json.enableSharedBuildCache,
  };

  if (type === "insecure_none") {
    const policy: InsecureNoneSandboxPolicy = {
      type: "insecure_none",
      ...commonFields,
    };
    return policy;
  }

  let additionalReadonlyPaths: string[] | undefined;
  if (Array.isArray(json.additionalReadonlyPaths)) {
    const paths = json.additionalReadonlyPaths as string[];
    additionalReadonlyPaths = paths.length > 0 ? paths : undefined;
  }

  // Legacy "custom" meant workspace + allowlist; collapse to workspace.
  const readBoundary =
    json.readBoundary === "custom" ? "workspace" : json.readBoundary;

  // Common fields for sandboxed policies
  const sandboxedCommon = {
    ...commonFields,
    networkAccess: json.networkAccess,
    networkPolicy: parseNetworkPolicy(json.networkPolicy),
    networkPolicyStrict: json.networkPolicyStrict,
    additionalReadonlyPaths,
    readBoundary,
    additionalReadPaths: Array.isArray(json.additionalReadPaths)
      ? json.additionalReadPaths
      : undefined,
    disableTmpWrite: json.disableTmpWrite,
  };

  if (type === "workspace_readonly") {
    const policy: WorkspaceReadOnlySandboxPolicy = {
      type: "workspace_readonly",
      ...sandboxedCommon,
    };
    return policy;
  }

  // workspace_readwrite (default)
  const policy: WorkspaceReadWriteSandboxPolicy = {
    type: "workspace_readwrite",
    ...sandboxedCommon,
    additionalReadwritePaths: json.additionalReadwritePaths,
  };
  return policy;
}

/**
 * Validates that a value is a valid PartialSandboxPolicyJson object.
 *
 * @param value - The value to validate
 * @returns An error message if invalid, undefined if valid
 */
function validateSandboxPolicyJson(value: unknown): string | undefined {
  if (typeof value !== "object" || value === null) {
    return "Expected an object";
  }

  const json = value as Record<string, unknown>;

  // Validate type field
  if (json.type !== undefined) {
    const validTypes = [
      "insecure_none",
      "workspace_readwrite",
      "workspace_readonly",
    ];
    if (typeof json.type !== "string" || !validTypes.includes(json.type)) {
      return `Invalid type: expected one of ${validTypes.join(", ")}`;
    }
  }

  // Validate boolean fields
  const booleanFields = [
    "networkAccess",
    "networkPolicyStrict",
    "disableTmpWrite",
    "enableSharedBuildCache",
    "captureDenies",
  ];
  for (const field of booleanFields) {
    if (json[field] !== undefined && typeof json[field] !== "boolean") {
      return `Invalid ${field}: expected boolean`;
    }
  }

  // Validate string fields
  const stringFields = ["debugOutputDir"];
  for (const field of stringFields) {
    if (json[field] !== undefined && typeof json[field] !== "string") {
      return `Invalid ${field}: expected string`;
    }
  }

  // Validate string array fields
  const stringArrayFields = [
    "additionalReadwritePaths",
    "additionalReadonlyPaths",
    "additionalReadPaths",
  ];
  for (const field of stringArrayFields) {
    if (json[field] !== undefined) {
      if (!Array.isArray(json[field])) {
        return `Invalid ${field}: expected array`;
      }
      const arr = json[field] as unknown[];
      if (!arr.every(item => typeof item === "string")) {
        return `Invalid ${field}: expected array of strings`;
      }
    }
  }

  if (
    json.readBoundary !== undefined &&
    json.readBoundary !== "system" &&
    json.readBoundary !== "workspace" &&
    json.readBoundary !== "custom"
  ) {
    return 'Invalid readBoundary: expected "system", "workspace", or "custom"';
  }

  // Validate networkPolicy
  if (json.networkPolicy !== undefined) {
    if (typeof json.networkPolicy !== "object" || json.networkPolicy === null) {
      return "Invalid networkPolicy: expected object";
    }
    const np = json.networkPolicy as Record<string, unknown>;
    if (
      np.default !== undefined &&
      np.default !== "allow" &&
      np.default !== "deny"
    ) {
      return 'Invalid networkPolicy.default: expected "allow" or "deny"';
    }
    if (np.allow !== undefined && !Array.isArray(np.allow)) {
      return "Invalid networkPolicy.allow: expected array";
    }
    if (np.deny !== undefined && !Array.isArray(np.deny)) {
      return "Invalid networkPolicy.deny: expected array";
    }
  }

  return undefined;
}

/**
 * Loads and parses a sandbox policy from a JSON file.
 *
 * @param filePath - Absolute path to the JSON file
 * @param baseDir - Optional base directory to resolve relative paths against.
 *                  If provided, paths in additionalReadwritePaths and
 *                  additionalReadonlyPaths will be resolved against this directory.
 * @returns LoadSandboxPolicyResult with the parsed policy or an error
 */
export async function loadSandboxPolicyFromFile(
  filePath: string,
  baseDir?: string
): Promise<LoadSandboxPolicyResult> {
  try {
    const content = await readFile(filePath, "utf-8");
    const json: unknown = JSON.parse(content);

    const validationError = validateSandboxPolicyJson(json);
    if (validationError) {
      return {
        success: false,
        error: `Invalid sandbox policy: ${validationError}`,
      };
    }

    let policy = parseSandboxPolicyJson(json as PartialSandboxPolicyJson);

    // Resolve paths if a base directory is provided
    if (baseDir) {
      policy = resolvePolicyPaths(policy, baseDir);
    }

    return { success: true, policy };
  } catch (error: unknown) {
    if (error instanceof Error) {
      // File not found is not an error - just means no config
      if ("code" in error && error.code === "ENOENT") {
        return { success: false, error: "File not found" };
      }
      if (error instanceof SyntaxError) {
        return { success: false, error: `Invalid JSON: ${error.message}` };
      }
      return { success: false, error: error.message };
    }
    return { success: false, error: "Unknown error" };
  }
}

/**
 * Loads a sandbox policy from a JSON file, returning undefined if the file
 * doesn't exist or is invalid.
 *
 * This is a convenience wrapper that silently handles missing files,
 * which is the common case for optional user configuration.
 *
 * @param filePath - Absolute path to the JSON file
 * @returns The parsed policy, or undefined if file doesn't exist or is invalid
 */
export async function loadSandboxPolicyFromFileOrUndefined(
  filePath: string,
  baseDir?: string
): Promise<SandboxPolicy | undefined> {
  const result = await loadSandboxPolicyFromFile(filePath, baseDir);
  if (result.success) {
    return result.policy;
  }
  return undefined;
}

/**
 * Resolves all paths in a sandbox policy against a base directory.
 *
 * This should be called after loading a policy from a file, with the
 * appropriate base directory for that config location:
 * - For ~/.cursor/sandbox.json: use homedir() (so ./foo means $HOME/foo)
 * - For <workspace>/.cursor/sandbox.json: use the workspace root
 *
 * @param policy - The parsed sandbox policy
 * @param baseDir - The base directory to resolve relative paths against
 * @returns A new policy with all paths resolved to absolute paths
 */
export function resolvePolicyPaths(
  policy: SandboxPolicy,
  baseDir: string
): SandboxPolicy {
  // insecure_none policies don't have path arrays
  if (policy.type === "insecure_none") {
    return policy;
  }

  const resolvedReadonlyPaths = policy.additionalReadonlyPaths?.map(p =>
    resolvePath(p, baseDir)
  );
  const resolvedReadPaths = policy.additionalReadPaths?.map(p =>
    resolvePath(p, baseDir)
  );

  if (policy.type === "workspace_readonly") {
    return {
      ...policy,
      additionalReadonlyPaths: resolvedReadonlyPaths,
      additionalReadPaths: resolvedReadPaths,
    };
  }

  const resolvedReadwritePaths = policy.additionalReadwritePaths?.map(p =>
    resolvePath(p, baseDir)
  );

  return {
    ...policy,
    additionalReadonlyPaths: resolvedReadonlyPaths,
    additionalReadPaths: resolvedReadPaths,
    additionalReadwritePaths: resolvedReadwritePaths,
  };
}
