import { readFile, rm } from "node:fs/promises";
import { join } from "node:path";

import type { SandLocalToolApprovalBinding } from "../../shared/local-tool-permission-machinery.js";
import {
	isSandLocalToolAction,
	type SandLocalToolAction,
} from "../../shared/local-tool-permission.js";
import { writeFileAtomic } from "../../shared/node/atomic-write.js";
import { getSandRootDir } from "../host-paths.js";

// The user's machine's own record of which local-tool actions it has
// approved. The in-box Host owns the ask flow, but its copy of the
// permission lives on box storage the agent's own Shell can reach — so the
// box's word alone cannot be what lets an agent touch this machine. The
// desktop writes an entry here when the user answers a card, and the
// local-exec daemon refuses any request that entry does not cover while the
// standing setting is "ask".
//
// An entry records WHAT THE CARD SAID, not just an id, because an id alone
// is a bearer token the box could attach to different work than the user
// saw; the daemon re-derives the action and target from the wire arguments
// and checks them against this record. One entry is ONE ACTION: retired the
// moment its action ends, and every entry is dropped on the user's next
// message, so there is no standing window to ride.
//
// Each of the two files here has exactly ONE writing process (main owns the
// approvals ledger, the daemon owns the retirements), so no read-modify-write
// crosses processes. Both are written atomically, and every unreadable state
// reads as "nothing", which fails CLOSED for the ask path.

export const LOCAL_TOOL_APPROVALS_FILENAME = "local-tool-approvals.json";
export const LOCAL_TOOL_RETIREMENTS_FILENAME = "local-tool-retirements.json";

/** One answered card, as this machine remembers it. */
export interface LocalToolApproval extends SandLocalToolApprovalBinding {
	readonly id: string;
}

interface ApprovalsFile {
	readonly approvals: readonly LocalToolApproval[];
}

const writeQueues = new Map<string, Promise<unknown>>();

async function serializeWrite<T>(path: string, mutate: () => Promise<T>): Promise<T> {
	const prior = writeQueues.get(path) ?? Promise.resolve();
	const next = prior.then(mutate, mutate);
	const settled = next.then(
		() => undefined,
		() => undefined,
	);
	writeQueues.set(path, settled);
	void settled.then(() => {
		if (writeQueues.get(path) === settled) writeQueues.delete(path);
	});
	return await next;
}

export function getLocalToolApprovalsPath(): string {
	return join(getSandRootDir(), LOCAL_TOOL_APPROVALS_FILENAME);
}

/** The daemon's own ledger: ids whose action has ended. Only the daemon writes it. */
export function getLocalToolRetirementsPath(): string {
	return join(getSandRootDir(), LOCAL_TOOL_RETIREMENTS_FILENAME);
}

function parseApproval(value: unknown): LocalToolApproval | undefined {
	if (typeof value !== "object" || value === null) return undefined;
	const record = value as Record<string, unknown>;
	const id = record.id;
	const action = record.action;
	const target = record.target;
	if (
		typeof id !== "string" ||
		id.length === 0 ||
		!isSandLocalToolAction(action) ||
		typeof target !== "string"
	) {
		return undefined;
	}
	return {
		id,
		action: action as SandLocalToolAction,
		target,
		...(typeof record.resourcePath === "string" ? { resourcePath: record.resourcePath } : {}),
	};
}

/** What this machine currently honors, by id. Any unreadable state reads as none. */
export async function readLocalToolApprovals(
	path = getLocalToolApprovalsPath(),
): Promise<ReadonlyMap<string, LocalToolApproval>> {
	try {
		const parsed = JSON.parse(await readFile(path, "utf-8")) as ApprovalsFile;
		const entries = parsed?.approvals;
		if (!Array.isArray(entries)) return new Map();
		const approvals = new Map<string, LocalToolApproval>();
		for (const entry of entries) {
			const approval = parseApproval(entry);
			if (approval !== undefined) approvals.set(approval.id, approval);
		}
		return approvals;
	} catch {
		return new Map();
	}
}

async function persist(
	path: string,
	approvals: ReadonlyMap<string, LocalToolApproval>,
): Promise<void> {
	if (approvals.size === 0) {
		await rm(path, { force: true });
		return;
	}
	const contents: ApprovalsFile = { approvals: [...approvals.values()] };
	await writeFileAtomic(path, new Uint8Array(Buffer.from(JSON.stringify(contents))));
}

/**
 * Records the user's answer to one card, with the action and target the card
 * showed them. Throws on a write failure so the caller can refuse to settle the
 * ask rather than telling the user an action is allowed over a machine that
 * will keep refusing it.
 */
export async function recordLocalToolApproval(
	approval: LocalToolApproval,
	path = getLocalToolApprovalsPath(),
): Promise<void> {
	await serializeWrite(path, async () => {
		const approvals = new Map(await readLocalToolApprovals(path));
		approvals.set(approval.id, approval);
		await persist(path, approvals);
	});
}

async function readRetirements(path: string): Promise<ReadonlySet<string>> {
	try {
		const parsed = JSON.parse(await readFile(path, "utf-8")) as {
			readonly retiredIds?: readonly unknown[];
		};
		const ids = parsed?.retiredIds;
		if (!Array.isArray(ids)) return new Set();
		return new Set(ids.filter((id): id is string => typeof id === "string"));
	} catch {
		return new Set();
	}
}

/**
 * Stops honoring one approval — its action has ended.
 *
 * Recorded in the DAEMON's own file rather than by editing the approvals ledger
 * main owns, so the two processes never race to rewrite the same file. Retiring
 * only ever narrows what is honored, so a failed write cannot widen access.
 */
export async function retireLocalToolApproval(
	approvalId: string,
	approvalsPath = getLocalToolApprovalsPath(),
	retirementsPath = getLocalToolRetirementsPath(),
): Promise<void> {
	await serializeWrite(retirementsPath, async () => {
		const approvals = await readLocalToolApprovals(approvalsPath);
		const retired = new Set(await readRetirements(retirementsPath));
		if (retired.has(approvalId)) return;
		retired.add(approvalId);
		for (const id of [...retired]) {
			if (!approvals.has(id)) retired.delete(id);
		}
		if (retired.size === 0) {
			await rm(retirementsPath, { force: true });
			return;
		}
		await writeFileAtomic(
			retirementsPath,
			new Uint8Array(Buffer.from(JSON.stringify({ retiredIds: [...retired] }))),
		);
	});
}

/**
 * What this machine will actually honor right now: approved, and not since
 * retired. The one function the local-exec daemon should consult.
 */
export async function readLiveLocalToolApprovals(
	approvalsPath = getLocalToolApprovalsPath(),
	retirementsPath = getLocalToolRetirementsPath(),
): Promise<ReadonlyMap<string, LocalToolApproval>> {
	const approvals = await readLocalToolApprovals(approvalsPath);
	const retired = await readRetirements(retirementsPath);
	if (retired.size === 0) return approvals;
	const live = new Map(approvals);
	for (const id of retired) live.delete(id);
	return live;
}

/**
 * Drops everything: the user has moved on, so nothing they approved still
 * applies. Only the approvals ledger is touched — the daemon's retirements are
 * its own file, and with the ledger gone they honor nothing either way.
 */
export async function clearLocalToolApprovals(path = getLocalToolApprovalsPath()): Promise<void> {
	await serializeWrite(path, async () => {
		await rm(path, { force: true });
	});
}
