import { PiTruncation } from "@anysphere/proto/agent/v1/pi_common_pb.js";

export const PI_DEFAULT_MAX_LINES = 2000;
export const PI_DEFAULT_MAX_BYTES: number = 50 * 1024;
export const PI_GREP_MAX_LINE_LENGTH = 500;

type TruncatedBy = "lines" | "bytes";

export interface PiTruncationResult {
  content: string;
  truncation: PiTruncation;
}

function byteLength(value: string): number {
  return Buffer.byteLength(value, "utf8");
}

export function formatSize(bytes: number): string {
  if (bytes < 1024) return `${bytes}B`;
  return `${Math.round(bytes / 1024)}KB`;
}

function makeTruncation(args: {
  truncated: boolean;
  truncatedBy?: TruncatedBy;
  totalLines: number;
  outputLines: number;
  outputBytes: number;
  maxLines?: number;
  maxBytes?: number;
  firstLineExceedsLimit?: boolean;
  lastLinePartial?: boolean;
}): PiTruncation {
  return new PiTruncation({
    truncated: args.truncated,
    truncatedBy: args.truncatedBy ?? "",
    totalLines: args.totalLines,
    outputLines: args.outputLines,
    outputBytes: args.outputBytes,
    maxLines: args.maxLines,
    maxBytes: args.maxBytes,
    firstLineExceedsLimit: args.firstLineExceedsLimit ?? false,
    lastLinePartial: args.lastLinePartial ?? false,
  });
}

export function truncateHead(
  text: string,
  options?: { maxLines?: number; maxBytes?: number }
): PiTruncationResult {
  const maxLines = options?.maxLines ?? PI_DEFAULT_MAX_LINES;
  const maxBytes = options?.maxBytes ?? PI_DEFAULT_MAX_BYTES;
  const lines = text.split("\n");
  const totalLines = lines.length;
  const firstLine = lines[0] ?? "";
  if (byteLength(firstLine) > maxBytes) {
    return {
      content: "",
      truncation: makeTruncation({
        truncated: true,
        truncatedBy: "bytes",
        totalLines,
        outputLines: 0,
        outputBytes: 0,
        maxLines,
        maxBytes,
        firstLineExceedsLimit: true,
      }),
    };
  }

  const outputLines: string[] = [];
  let outputBytes = 0;
  let truncatedBy: TruncatedBy | undefined;
  for (let i = 0; i < lines.length; i++) {
    if (outputLines.length >= maxLines) {
      truncatedBy = "lines";
      break;
    }
    const next = lines[i];
    const separatorBytes = outputLines.length > 0 ? 1 : 0;
    const nextBytes = byteLength(next) + separatorBytes;
    if (outputBytes + nextBytes > maxBytes) {
      truncatedBy = "bytes";
      break;
    }
    outputLines.push(next);
    outputBytes += nextBytes;
  }

  return {
    content: outputLines.join("\n"),
    truncation: makeTruncation({
      truncated: truncatedBy !== undefined,
      truncatedBy,
      totalLines,
      outputLines: outputLines.length,
      outputBytes,
      maxLines,
      maxBytes,
    }),
  };
}

export function truncateTail(
  text: string,
  options?: { maxLines?: number; maxBytes?: number }
): PiTruncationResult {
  const maxLines = options?.maxLines ?? PI_DEFAULT_MAX_LINES;
  const maxBytes = options?.maxBytes ?? PI_DEFAULT_MAX_BYTES;
  const lines = text.split("\n");
  const totalLines = lines.length;
  const outputLines: string[] = [];
  let outputBytes = 0;
  let truncatedBy: TruncatedBy | undefined;
  let lastLinePartial = false;

  for (let i = lines.length - 1; i >= 0; i--) {
    if (outputLines.length >= maxLines) {
      truncatedBy = "lines";
      break;
    }
    const next = lines[i];
    const separatorBytes = outputLines.length > 0 ? 1 : 0;
    const nextBytes = byteLength(next) + separatorBytes;
    if (outputBytes + nextBytes > maxBytes) {
      truncatedBy = "bytes";
      if (outputLines.length === 0) {
        const bytes = Buffer.from(next, "utf8");
        outputLines.unshift(
          bytes.subarray(Math.max(0, bytes.length - maxBytes)).toString("utf8")
        );
        outputBytes = byteLength(outputLines[0]);
        lastLinePartial = true;
      }
      break;
    }
    outputLines.unshift(next);
    outputBytes += nextBytes;
  }

  return {
    content: outputLines.join("\n"),
    truncation: makeTruncation({
      truncated: truncatedBy !== undefined,
      truncatedBy,
      totalLines,
      outputLines: outputLines.length,
      outputBytes,
      maxLines,
      maxBytes,
      lastLinePartial,
    }),
  };
}

export function truncateLine(line: string): {
  text: string;
  wasTruncated: boolean;
} {
  if (line.length <= PI_GREP_MAX_LINE_LENGTH) {
    return { text: line, wasTruncated: false };
  }
  return {
    text: `${line.slice(0, PI_GREP_MAX_LINE_LENGTH)}... [truncated]`,
    wasTruncated: true,
  };
}
