/**
 * Consecutive streamable-HTTP session HTTP 404 threshold before quarantining
 * (non-retryable failure). Set from Statsig dynamic config
 * `mcp_reconnect_config` (see the `mcpCommandsV2` loader).
 */

import {
	getMcpReconnectConfigValue,
	type McpReconnectConfigContext,
} from './mcp-reconnect-config.js';

export const DEFAULT_STREAMABLE_HTTP_SESSION_404_TOMBSTONE_THRESHOLD = 5;

export function advanceStreamableHttpSession404Counter(args: {
	currentCount: number;
	sawSession404: boolean;
	threshold: number;
}): { nextCount: number; shouldTombstone: boolean } {
	if (!args.sawSession404) {
		return { nextCount: 0, shouldTombstone: false };
	}

	const nextCount = args.currentCount + 1;
	if (nextCount >= args.threshold) {
		return { nextCount: 0, shouldTombstone: true };
	}

	return { nextCount, shouldTombstone: false };
}

/**
 * Threshold for tombstoning after repeated session HTTP 404s.
 * Clamped to [1, 50] to avoid misconfiguration.
 */
export function getStreamableHttpSession404TombstoneThreshold(context?: McpReconnectConfigContext): number {
	const raw = getMcpReconnectConfigValue('streamableHttpSession404TombstoneThreshold', context)
		?? DEFAULT_STREAMABLE_HTTP_SESSION_404_TOMBSTONE_THRESHOLD;
	const n = Math.trunc(raw);
	return Math.max(1, Math.min(n, 50));
}
