/**
 * Utilities for handling sudo with SUDO_ASKPASS support in shell execution.
 *
 * When SUDO_ASKPASS is configured, sudo should use the -A flag to invoke the
 * askpass helper for password prompts instead of reading from the terminal.
 */

// Windows uses UAC dialogs for elevation, not SUDO_ASKPASS
const isWindows = process.platform === "win32";

/**
 * Check if sudo askpass support should be enabled based on environment variables.
 * Returns true if SUDO_ASKPASS is set in the environment (and not on Windows).
 */
export function shouldEnableSudoAskpass(
  env?: Record<string, string | undefined>
): boolean {
  if (isWindows) {
    return false;
  }
  return !!env?.SUDO_ASKPASS;
}

/**
 * Get the shell alias command to make sudo use -A flag.
 * This alias is injected into bash/zsh runners so any sudo invocation
 * automatically uses the askpass helper.
 *
 * For bash: `alias sudo='sudo -A'`
 * For zsh: Same, but must be set after `setopt aliases` is enabled
 */
export const SUDO_ALIAS = "alias sudo='sudo -A'";

/**
 * Get the sudo alias injection string for shell commands.
 * Returns the alias command with trailing semicolon and space if SUDO_ASKPASS
 * is configured, otherwise returns an empty string.
 *
 * This is used by bash/zsh runners to inject the sudo alias into the command.
 */
export function getSudoAliasInjection(
  env?: Record<string, string | undefined>
): string {
  return shouldEnableSudoAskpass(env) ? `${SUDO_ALIAS}; ` : "";
}

/**
 * Transform a shell command to add -A flag to sudo invocations.
 * This enables sudo to use the SUDO_ASKPASS helper for password prompts.
 *
 * This is used by the naive runner which can't use shell aliases since
 * each command runs in a fresh shell without state preservation.
 *
 * Handles various sudo patterns:
 * - `sudo cmd` -> `sudo -A cmd`
 * - `sudo -u user cmd` -> `sudo -A -u user cmd`
 * - `cmd1 && sudo cmd2` -> `cmd1 && sudo -A cmd2`
 * - `cmd1 || sudo cmd2` -> `cmd1 || sudo -A cmd2`
 * - `cmd1 | sudo cmd2` -> `cmd1 | sudo -A cmd2`
 * - `cmd1; sudo cmd2` -> `cmd1; sudo -A cmd2`
 *
 * Does NOT transform if -A is already present.
 * @internal Exported for testing
 */
export function transformSudoCommand(command: string): string {
  const result: string[] = [];
  let i = 0;

  while (i < command.length) {
    // Check if we're at a position where a command could start
    const isCommandStart =
      i === 0 ||
      command.slice(Math.max(0, i - 2), i) === "&&" ||
      command.slice(Math.max(0, i - 2), i) === "||" ||
      command[i - 1] === "|" ||
      command[i - 1] === ";";

    // Also handle whitespace after operators
    const lookbackStart = Math.max(0, i - 10);
    const lookback = command.slice(lookbackStart, i);
    const isAfterOperator =
      /(?:&&|\|\||[|;])\s*$/.test(lookback) ||
      (i === 0 && /^\s*$/.test(lookback));

    if (
      (isCommandStart || isAfterOperator) &&
      command.slice(i, i + 4) === "sudo"
    ) {
      // Check what follows "sudo"
      const afterSudo = i + 4;
      if (afterSudo >= command.length || /\s/.test(command[afterSudo])) {
        // It's "sudo" followed by whitespace or end - this is a sudo command
        // Find the next non-whitespace to check for existing -A flag
        let j = afterSudo;
        while (j < command.length && /\s/.test(command[j])) {
          j++;
        }

        // Check if the next argument already contains -A
        let hasAFlag = false;
        if (j < command.length && command[j] === "-") {
          // Read the flag argument
          let flagEnd = j + 1;
          while (flagEnd < command.length && /[^\s]/.test(command[flagEnd])) {
            flagEnd++;
          }
          const flag = command.slice(j, flagEnd);
          // Check if -A is present as standalone or combined (e.g., -A, -nA, -An)
          hasAFlag = /^-[a-zA-Z]*A[a-zA-Z]*$/.test(flag);
        }

        if (hasAFlag) {
          // Already has -A, just copy sudo as-is
          result.push("sudo");
          i = afterSudo;
        } else {
          // Insert -A after sudo
          result.push("sudo -A");
          i = afterSudo;
        }
        continue;
      }
    }

    // Not a sudo command position, just copy the character
    result.push(command[i]);
    i++;
  }

  return result.join("");
}
