import { type Context, createLogger } from "@anysphere/context";
import type { CursorManagedSkill } from "./builtin-skills-sync-service.js";
import { syncBuiltinSkills } from "./builtin-skills-sync-service.js";

const logger = createLogger("managed-skills-sync");

export interface FetchAndSyncManagedSkillsOptions {
  /**
   * Host-supplied managed-skills loader.
   * This keeps the sync path reusable across CLI, ACP, and future runtime code.
   */
  getManagedSkills: () => Promise<readonly CursorManagedSkill[] | undefined>;
}

export type FetchAndSyncManagedSkillsResult =
  | {
      status: "synced";
      managedSkillsCount: number;
      syncResult: Awaited<ReturnType<typeof syncBuiltinSkills>>;
    }
  | {
      status: "fetch_failed";
      error: unknown;
    };

/**
 * Fetch managed skills from a host-provided source and sync them to disk.
 * On fetch failure, logs a warning and preserves whatever is already cached.
 */
export async function fetchAndSyncManagedSkills(
  ctx: Context,
  options: FetchAndSyncManagedSkillsOptions
): Promise<FetchAndSyncManagedSkillsResult> {
  try {
    const managedSkills = (await options.getManagedSkills()) ?? [];
    const syncResult = await syncBuiltinSkills(ctx, {
      managedSkills: [...managedSkills],
    });
    return {
      status: "synced",
      managedSkillsCount: managedSkills.length,
      syncResult,
    };
  } catch (error: unknown) {
    logger.warn(ctx, "Failed to sync managed skills from source", { error });
    return {
      status: "fetch_failed",
      error,
    };
  }
}
