export function hashMcpOAuthValueForLog(
  value: string | undefined
): string | undefined {
  if (!value) {
    return undefined;
  }
  return createHash("sha256").update(value).digest("hex").slice(0, 12);
}

export function hashMcpOAuthStringArrayForLog(
  values: readonly string[] | undefined
): string | undefined {
  if (!values || values.length === 0) {
    return undefined;
  }
  return hashMcpOAuthValueForLog(JSON.stringify([...values].sort()));
}

export interface McpOAuthClientInformationSnapshotForLog {
  readonly clientIdHash?: string;
  readonly clientSecretHash?: string;
  readonly redirectUrisHash?: string;
  readonly redirectUriCount: number;
}

export function buildOAuthClientInformationSnapshotForLog(
  clientInformation:
    | {
        readonly client_id?: string;
        readonly client_secret?: string;
        readonly redirect_uris?: readonly string[];
      }
    | undefined
): McpOAuthClientInformationSnapshotForLog {
  return {
    clientIdHash: hashMcpOAuthValueForLog(clientInformation?.client_id),
    clientSecretHash: hashMcpOAuthValueForLog(clientInformation?.client_secret),
    redirectUrisHash: hashMcpOAuthStringArrayForLog(
      clientInformation?.redirect_uris
    ),
    redirectUriCount: clientInformation?.redirect_uris?.length ?? 0,
  };
}

type NetworkClassification =
  | "timeout"
  | "dns"
  | "tls"
  | "connection_reset"
  | "connection_refused";

function classifyNetworkError(args: {
  message: string | undefined;
  code?: string;
}): NetworkClassification | undefined {
  const normalized = args.message?.toLowerCase();
  const normalizedCode = args.code?.toLowerCase();
  if (
    normalized?.includes("timed out") ||
    normalized?.includes("timeout") ||
    normalized?.includes("etimedout") ||
    normalizedCode === "etimedout"
  ) {
    return "timeout";
  }
  if (
    normalized?.includes("enotfound") ||
    normalized?.includes("eai_again") ||
    normalized?.includes("dns") ||
    normalizedCode === "enotfound" ||
    normalizedCode === "eai_again"
  ) {
    return "dns";
  }
  if (
    normalized?.includes("certificate") ||
    normalized?.includes("tls") ||
    normalized?.includes("ssl")
  ) {
    return "tls";
  }
  if (
    normalized?.includes("econnreset") ||
    normalized?.includes("connection reset") ||
    normalizedCode === "econnreset"
  ) {
    return "connection_reset";
  }
  if (
    normalized?.includes("econnrefused") ||
    normalized?.includes("connection refused") ||
    normalizedCode === "econnrefused"
  ) {
    return "connection_refused";
  }
  return undefined;
}

function readNestedRecordValue(
  value: unknown,
  path: readonly string[]
): unknown {
  let current = value;
  for (const key of path) {
    if (typeof current !== "object" || current === null || !(key in current)) {
      return undefined;
    }
    current = (current as Record<string, unknown>)[key];
  }
  return current;
}

function firstString(
  value: unknown,
  keys: readonly string[]
): string | undefined {
  for (const key of keys) {
    if (typeof readNestedRecordValue(value, key.split(".")) === "string") {
      return readNestedRecordValue(value, key.split(".")) as string;
    }
  }
  return undefined;
}

/** SDK `OAuthError` subclasses expose `errorCode` via getter (not enumerable). */
function readSdkOAuthErrorCode(error: unknown): string | undefined {
  if (!error || typeof error !== "object") {
    return undefined;
  }
  const errorCode = (error as { errorCode?: unknown }).errorCode;
  return typeof errorCode === "string" ? errorCode : undefined;
}

function firstNumber(
  value: unknown,
  keys: readonly string[]
): number | undefined {
  for (const key of keys) {
    const candidate = readNestedRecordValue(value, key.split("."));
    if (typeof candidate === "number" && Number.isFinite(candidate)) {
      return candidate;
    }
  }
  return undefined;
}

function parseHttpStatusFromErrorMessage(
  message: string | undefined
): number | undefined {
  if (!message) {
    return undefined;
  }
  const match = message.match(/\(HTTP (\d+)\)|Non-200 status code \((\d+)\)/);
  const matchedStatus = match?.[1] ?? match?.[2];
  if (!matchedStatus) {
    return undefined;
  }
  const parsed = Number.parseInt(matchedStatus, 10);
  return Number.isNaN(parsed) ? undefined : parsed;
}

const REDACTED_LOG_VALUE = "[REDACTED]";
const SENSITIVE_ERROR_SUMMARY_KEY_PATTERN =
  /(^|_|-)(token|secret|password|assertion|authorization|verifier|challenge|code)(_|-|$)/i;

function isSensitiveErrorSummaryKey(key: string): boolean {
  const normalized = key.toLowerCase();
  return (
    normalized === "code" ||
    normalized === "authorization" ||
    normalized.includes("token") ||
    normalized.includes("secret") ||
    normalized.includes("password") ||
    normalized.includes("assertion") ||
    normalized.includes("verifier") ||
    normalized.includes("challenge") ||
    SENSITIVE_ERROR_SUMMARY_KEY_PATTERN.test(normalized)
  );
}

function redactSensitiveText(value: string): string {
  return value
    .replace(
      /((?:access_token|refresh_token|id_token|client_secret|authorization|code|password|assertion|token|secret)[^:=\r\n]{0,32}[:=]\s*["']?)([^"',\s&}]+)/gi,
      `$1${REDACTED_LOG_VALUE}`
    )
    .replace(
      /(\bBearer\s+)([A-Za-z0-9\-._~+/]+=*)/gi,
      `$1${REDACTED_LOG_VALUE}`
    );
}

function truncateLogValue(value: string, maxLength = 256): string {
  return value.length > maxLength
    ? `${value.slice(0, Math.max(0, maxLength - 3))}...`
    : value;
}

export function sanitizeErrorMessageForLog(
  value: string,
  options?: { readonly maxLength?: number }
): string {
  return truncateLogValue(redactSensitiveText(value), options?.maxLength);
}

export function sanitizeStructuredValueForLog(
  value: unknown
): string | undefined {
  return sanitizeStructuredValue(value);
}

function sanitizeStructuredValue(value: unknown): string | undefined {
  if (typeof value === "string") {
    return truncateLogValue(redactSensitiveText(value));
  }
  if (value === undefined) {
    return undefined;
  }
  try {
    const serialized = JSON.stringify(value, (key, nestedValue: unknown) => {
      if (key && isSensitiveErrorSummaryKey(key)) {
        return REDACTED_LOG_VALUE;
      }
      if (typeof nestedValue === "string") {
        return redactSensitiveText(nestedValue);
      }
      return nestedValue;
    });
    if (!serialized) {
      return undefined;
    }
    return truncateLogValue(serialized);
  } catch {
    return undefined;
  }
}

export interface McpOAuthErrorLogMetadata {
  readonly errorName?: string;
  readonly errorMessage?: string;
  readonly errorType?: string;
  readonly httpStatus?: number;
  readonly oauthErrorCode?: string;
  readonly errorResponseSummary?: string;
  readonly networkClassification?: NetworkClassification;
  readonly sdkErrorKind?:
    | "oauth_error"
    | "auth_transport_error"
    | "generic_error";
}

export function extractResponseFromFetchError(
  error: unknown
): Response | undefined {
  if (!error || typeof error !== "object") {
    return undefined;
  }
  const candidates: unknown[] = [
    (error as { response?: unknown }).response,
    (error as { cause?: { response?: unknown } }).cause?.response,
  ];
  for (const candidate of candidates) {
    if (
      candidate &&
      typeof candidate === "object" &&
      "status" in candidate &&
      typeof (candidate as Response).status === "number" &&
      "headers" in candidate &&
      typeof (candidate as Response).headers?.get === "function"
    ) {
      return candidate as Response;
    }
  }
  return undefined;
}

export function getMcpOAuthErrorLogMetadata(
  error: unknown
): McpOAuthErrorLogMetadata {
  const errorName =
    error instanceof Error
      ? error.name
      : error != null
        ? typeof error
        : undefined;
  const rawErrorMessage =
    error instanceof Error
      ? error.message
      : error != null
        ? String(error)
        : undefined;
  const errorMessage =
    rawErrorMessage !== undefined
      ? sanitizeErrorMessageForLog(rawErrorMessage)
      : undefined;
  const systemErrorCode = firstString(error, ["code", "cause.code"]);
  const oauthErrorCode =
    readSdkOAuthErrorCode(error) ??
    firstString(error, [
      "errorCode",
      "error",
      "cause.errorCode",
      "cause.error",
      "body.error",
      "response.body.error",
    ]);
  const httpStatus =
    firstNumber(error, [
      "status",
      "statusCode",
      "response.status",
      "response.statusCode",
      "cause.status",
      "cause.statusCode",
      "cause.response.status",
      "cause.response.statusCode",
    ]) ?? parseHttpStatusFromErrorMessage(errorMessage);
  const errorResponseSummary = sanitizeStructuredValue(
    readNestedRecordValue(error, ["response", "body"]) ??
      readNestedRecordValue(error, ["body"]) ??
      readNestedRecordValue(error, ["data"]) ??
      readNestedRecordValue(error, ["cause", "body"])
  );
  const networkClassification = classifyNetworkError({
    message: errorMessage,
    code: systemErrorCode,
  });
  const sdkErrorKind: McpOAuthErrorLogMetadata["sdkErrorKind"] = oauthErrorCode
    ? "oauth_error"
    : networkClassification
      ? "auth_transport_error"
      : errorMessage
        ? "generic_error"
        : undefined;

  return compactLogMetadata({
    errorName,
    errorMessage,
    errorType: error != null ? typeof error : undefined,
    httpStatus,
    oauthErrorCode,
    errorResponseSummary,
    networkClassification,
    sdkErrorKind,
  });
}

export type McpOAuthLifecycleEvent =
  | "mcp_oauth_provider_initialized"
  | "mcp_oauth_tokens_loaded"
  | "mcp_oauth_tokens_saved"
  | "mcp_oauth_callback_completion"
  | "mcp_oauth_client_info_loaded"
  | "mcp_oauth_client_info_saved"
  | "mcp_oauth_refresh_prepare"
  | "mcp_oauth_refresh_error_release"
  | "mcp_oauth_state_transition"
  | "mcp_oauth_credentials_invalidated";

export type McpOAuthLifecycleLogLevel = "debug" | "info" | "warn" | "error";

export interface McpOAuthLifecycleLogger {
  readonly debug?: (
    message: string,
    metadata?: Record<string, unknown>
  ) => void;
  readonly info?: (message: string, metadata?: Record<string, unknown>) => void;
  readonly warn?: (message: string, metadata?: Record<string, unknown>) => void;
  readonly error?: (
    message: string,
    error?: unknown,
    metadata?: Record<string, unknown>
  ) => void;
}

export interface EmitMcpOAuthLifecycleLogArgs {
  readonly logger: McpOAuthLifecycleLogger;
  readonly event: McpOAuthLifecycleEvent;
  readonly level?: McpOAuthLifecycleLogLevel;
  readonly metadata?: Record<string, unknown>;
  readonly error?: unknown;
  readonly message?: string;
}

const EVENT_MESSAGES: Record<McpOAuthLifecycleEvent, string> = {
  mcp_oauth_provider_initialized: "MCP OAuth provider initialized",
  mcp_oauth_tokens_loaded: "MCP OAuth tokens loaded",
  mcp_oauth_tokens_saved: "MCP OAuth tokens saved",
  mcp_oauth_callback_completion: "MCP OAuth callback exchange completed",
  mcp_oauth_client_info_loaded: "MCP OAuth client information loaded",
  mcp_oauth_client_info_saved: "MCP OAuth client information saved",
  mcp_oauth_refresh_prepare: "MCP OAuth refresh prepared",
  mcp_oauth_refresh_error_release: "MCP OAuth refresh error released",
  mcp_oauth_state_transition: "MCP OAuth state transition",
  mcp_oauth_credentials_invalidated: "MCP OAuth credentials invalidated",
};

export function emitMcpOAuthLifecycleLog(
  args: EmitMcpOAuthLifecycleLogArgs
): void {
  const message = args.message ?? EVENT_MESSAGES[args.event];
  const metadata: Record<string, unknown> = {
    event: args.event,
    cursorMcp: {
      oauth: compactLogMetadata({ ...args.metadata }),
    },
  };
  const level = args.level ?? "info";

  if (level === "error") {
    args.logger.error?.(message, args.error, metadata);
    return;
  }
  if (level === "warn") {
    args.logger.warn?.(message, metadata);
    return;
  }
  if (level === "debug") {
    args.logger.debug?.(message, metadata);
    return;
  }
  args.logger.info?.(message, metadata);
}
